-- Sources: data/i18n/deDE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["quest:175"] = {n="Der Blick zu den Sternen",s="Nach den Bauplänen des Tüftlers Cog sucht Viktori Prism'Antras nach einer reflektierenden Oberfläche, um sein Observatoriumsfernrohr in Dunkelhain zusammenzubauen. Er schickt Reisende in den südlichen Dämmerwald, um Mary ausfindig zu machen, eine einheimische Frau, die dafür in Erinnerung geblieben ist, stets einen Taschenspiegel bei sich getragen zu haben.",h="Nach den Bauplänen des Tüftlers Cog sucht Viktori Prism'Antras nach einer reflektierenden Oberfläche, um sein...",kw={"die blinde mary","dunkelhain","dämmerwald","der blick zu den sternen","taschenspiegel","mary","teleskop","friedhof stille gärten","viktori prism'antras"},ang={["faction:Alliance"]="Viktori beim Bau seines Teleskops zu helfen, bietet einen seltenen Schimmer von Neugier und Fortschritt in einer Stadt, die ansonsten von Terror und Verfall zerfressen wird.",["profession:Engineering"]="Der Zusammenbau des Teleskops basiert auf präzisen optischen Vorgaben und nutzt gnomische Baupläne, um das schwache Sternenlicht zu reflektieren und zu vergrößern."},sec={{t="Eine reflektierende Oberfläche",b="Nachdem er sich eine Bronzeröhre für sein Teleskop gesichert hat, widmet sich Viktori Prism'Antras der nächsten Anforderung aus Cogs Bauplänen: einem verlässlichen Spiegel, der das Licht durch das Gerät leitet und reflektiert. Anstatt angesichts der herrschenden Knappheit in Dunkelhain feines verspiegeltes Glas von Grund auf neu anzufertigen, erinnert sich Viktori an Mary – eine Bewohnerin, die in der ganzen Region dafür bekannt war, stets einen Taschenspiegel bei sich zu tragen."},{t="Die Suche im Süden",b="Marys früherer Wohnsitz liegt tief im Süden von Dämmerwald, knapp nördlich des heimgesuchten Friedhofs \"Stille Gärten\". Die Suche nach ihr führt Abenteurer über die sicheren Patrouillengrenzen der Nachtwache hinaus in verheerte Haine voller ausgehungerter Wölfe, wilder Spinnen und umherstreifender Untoter."},{t="Eine tragische Bewohnerin",b="Das Erreichen von Marys bescheidener Hütte im Süden offenbart die düstere Realität des Niedergangs von Dämmerwald. Die Frau, an die sich Viktori erinnerte, ist keine lebende Bewohnerin mehr, sondern die blinde Mary – ein umherirrender Geist, der in der Nähe ihrer alten Behausung und des nahegelegenen Friedhofs verweilt, gebunden an die Erinnerungen und Besitztümer ihres einstigen Lebens."}},faq={{q="Was baut Viktori Prism'Antras?",a="Viktori baut in seiner Hütte auf dem Hügel in Dunkelhain ein astronomisches Teleskop und arbeitet dabei nach Entwürfen eines Tüftlers namens Cog.",al={"viktori teleskop","der blick zu den sternen projekt","was baut viktori"}},{q="Warum braucht Viktori einen Taschenspiegel?",a="Cogs optische Baupläne erfordern einen Spiegel, um das Licht durch das Gehäuse des Teleskops zu reflektieren und zu bündeln. Viktori erinnert sich daran, dass Mary einen Taschenspiegel bei sich trug, und hofft, ihn für den Zusammenbau beschaffen zu können.",al={"warum spiegel benötigt","reflektierende oberfläche teleskop"}},{q="Wo ist Mary zu finden?",a="Mary hält sich in einer verfallenen Behausung im südöstlichen Dämmerwald auf, die direkt nördlich des Friedhofs \"Stille Gärten\" liegt.",al={"wo ist mary","mary aufenthaltsort dämmerwald","die blinde mary finden"}},{q="Wer ist Mary?",a="Mary war eine Bewohnerin des südlichen Dämmerwalds, bevor das Land in verfluchte Finsternis stürzte, und in ganz Dunkelhain dafür bekannt, stets einen Taschenspiegel bei sich zu tragen. Was aus ihr geworden ist, müsst Ihr an ihrem alten Heim nahe dem Friedhof \"Stille Gärten\" selbst herausfinden.",al={"wer ist die blinde mary","hintergrundgeschichte der blinden mary"}},{q="Hat Mary ihren Taschenspiegel noch?",a="Spricht man Mary an, bestätigt sie, einst einen Taschenspiegel besessen zu haben; allerdings besitzt sie ihn nicht mehr und kann Euch nur darauf hinweisen, wo er geblieben ist.",al={"hat mary einen spiegel","die blinde mary taschenspiegel"}},{q="Welche Gefahren umgeben Marys Hütte?",a="In den südöstlichen Wäldern und auf dem angrenzenden Friedhof \"Stille Gärten\" wimmelt es von feindseligen Untoten, wilden Dämmerfledermäusen, Giftnetzspinnen und tollwütigen Wölfen, die Reisenden südlich von Dunkelhain nachstellen.",al={"gefahren nahe mary","friedhof stille gärten bedrohungen"}}},fx={["966ba84d"]={q="Warum ist Viktori Prism'Antras so darauf fixiert, sein Teleskop fertigzustellen?",a="Viktori Prism'Antras ist von seinem Ehrgeiz verzehrt, ein astronomisches Teleskop auf seinem Turm in Dunkelhain fertigzustellen. Den Bauplänen des Gnoms Cog folgend, benötigt er spezialisierte Komponenten, um Licht zu reflektieren und zu fokussieren. Er hofft, über das ewige Düster, das den Dämmerwald einhüllt, hinauszublicken, und das Sammeln jedes obskuren Teils ist wesentlich, um seine großartige Konstruktion zum Leben zu erwecken.",al={"warum will viktori das erledigt haben","viktori prism'antras motiv","warum das teleskop bauen"}}},fp="17,265,20.388.0,19.282.0,17.298.1,38.138.0,38.189.0,24.109.0,12.246.1,39.144.1,37.199.0"}
P.entries["quest:1758"] = {n="Foliant der Kabale",s="Foliant der Kabale schickt einen aufstrebenden Hexenmeister der Allianz von den Anhöhen über Ratschet zurück in die Bibliothek von Eisenschmiede. Um einen unersättlichen Teufelsjäger zu beschwören und zu beherrschen, muss der Beschwörer ein legendäres Lehrwerk aufspüren, das von den ersten Hexenmeistern verfasst wurde, die die Bestie jemals bezwungen haben.",h="Foliant der Kabale schickt einen aufstrebenden Hexenmeister der Allianz von den Anhöhen über Ratschet zurück...",kw={"teufelsjäger","hall of explorers","eisenschmiede","krom starkarm","ratschet","strahad farsan","foliant der kabale","hexenmeister"},ang={["class:Warlock"]="Die Beschaffung des Folianten der Kabale ist der entscheidende Initiationsritus für einen Ausübenden der dunklen Künste, der die Beherrschung von Teufelsjägern anstrebt und über niedere Diener hinaus zur wahren Anti-Magie-Dämonologie übergeht.",["faction:Alliance"]="Praktizierende der Allianz müssen von der Grenze Kalimdors zur Hall of Explorers in Eisenschmiede zurückkehren, um die Gelehrsamkeit der Zwerge für verbotene finstere Schriften zu nutzen.",["race:Dwarf"]="Krom Starkarm beweist, dass nicht jeder in der Hall of Explorers vergrabene Zwerg Titanenartefakte ausgräbt – manche tragen im Verborgenen das Wissen des Brennenden Schattens zusammen."},sec={{t="Eine Bestie, die sich von Magie nährt",b="Die Unterwerfung eines Wichtels, eines Leerwandlers oder einer Sukkubus erfordert Rituale, doch ein Teufelsjäger birgt eine völlig andere Gefahr. Teufelsjäger dienen der Brennenden Legion nicht bloß; sie jagen und verschlingen aktiv arkane Energie. Ein gewöhnlicher Beschwörungskreis zerfällt vor ihnen und entzieht dem Beschwörer die Magie, noch bevor eine Bindung überhaupt greifen kann. Strahad Farsan, der von seiner Schanze im Brachland aus über Ratschet wacht, weiß es besser, als einen Laien unvorbereitet eine solche Bindung versuchen zu lassen."},{t="Die erste Bindung",b="Um einen Teufelsjäger sicher hervorzuholen und zu binden, benötigt ein Akolyth die arkanen Formeln, die im Foliant der Kabale zusammengetragen wurden. Verfasst von der frühesten sterblichen Kabale von Hexenmeistern, die einen Teufelsjäger ohne fremde Hilfe erfolgreich unterjochte, beschreibt das Manuskript die spezifische Geomantie, Materialien und Bindungsrunen, die notwendig sind, um dem Hunger der Kreatur zu widerstehen. Zum Unglück von Strahad und seinem Zirkel ging ihr Exemplar dieses Meisterwerks vor langer Zeit verloren."},{t="Der Horter von Dun Morogh",b="Da er den Text selbst nicht bereitstellen kann, entsendet Strahad Hexenmeister der Allianz über das große Meer zur Hall of Explorers in Eisenschmiede. Dort lauert Krom Starkarm, ein umherziehender Zwergenhexenmeister, der seinen Lebensabend damit verbringt, uralte Manuskripte und Bibliotheksaufzeichnungen zu durchforsten. Wenn in den Östlichen Königreichen noch eine Spur des verlorenen Grimoires verzeichnet ist, liegt sie begraben in Kroms akribischen Katalogen."}},faq={{q="Warum muss ich den Folianten der Kabale finden?",a="Der Foliant der Kabale enthält die genauen Anweisungen der ersten sterblichen Hexenmeister, die jemals ohne fremde Hilfe einen Teufelsjäger beschworen und unterworfen haben. Gewöhnliche Beschwörungsrituale reichen nicht aus, um einen Dämon einzufangen, der sich aktiv von magischer Energie ernährt.",al={"was ist foliant der kabale","warum buch finden","zweck foliant der kabale"}},{q="Wer ist Krom Starkarm?",a="Krom Starkarm ist ein wandernder Zwergenhexenmeister, der in der Bibliothek der Hall of Explorers in Eisenschmiede weilt. Er verbringt seine Tage zurückgezogen zwischen staubigen Wälzern und katalogisiert uralte historische Aufzeichnungen.",al={"wo ist krom","wer ist krom starkarm","krom eisenschmiede"}},{q="Warum befindet sich Strahad Farsan im Brachland?",a="Strahad Farsan ist ein versierter menschlicher Hexenmeister, der auf den Klippen über Ratschet eine ruhige, neutrale Schanze unterhält. Fernab der wachsamen Blicke der Kirin Tor und der Behörden von Sturmwind bildet er Ausübende sowohl der Allianz als auch der Horde in mächtiger Dämonologie aus.",al={"strahad aufenthaltsort","warum ratschet","wer ist strahad"}},{q="Was geschieht, nachdem ich mit Krom Starkarm gesprochen habe?",a="Krom Starkarm erinnert sich an Erwähnungen des Folianten aus alten Katalogen. Er wird Euch damit beauftragen, seine verschollenen Teile aufzuspüren und die seltenen Reagenzien zu beschaffen, die für die Wiederherstellung des Grimoires benötigt werden.",al={"folgequest","nach krom","foliant der kabale nächster schritt"}},{q="Können Hexenmeister der Horde diese Quest annehmen?",a="Diese spezifische Reise nach Eisenschmiede ist ausschließlich Hexenmeistern der Allianz vorbehalten. Hexenmeister der Horde erhalten von Strahad eine gleichwertige Aufgabe, die sie stattdessen zu sachkundigen Kontakten innerhalb des Hordegebiets führt.",al={"horde version","nur allianz"}},{q="Welchen Dämon schaltet diese Questreihe frei?",a="Der Abschluss der gesamten Questreihe um den Folianten der Kabale gipfelt in einem Ritualkampf gegen einen beschworenen Teufelsjäger und lehrt den Hexenmeister, wie man einen solchen als dauerhaften Diener beschwört und bindet.",al={"welcher dämon","teufelsjäger quest","welchen begleiter bekomme ich"}}},fx={["8ce24f0c"]={q="Warum möchte Strahad Farsan, dass Ihr das Tome of the Cabal findet?",a="Strahad Farsan leitet Eure Entwicklung als Hexenmeister und bereitet Euch darauf vor, einen der grausamsten Raubtiere des Wirbelnden Nether zu befehligen: einen Teufelsjäger. Das Beschwören eines solchen Tieres erfordert komplizierte, gefährliche Rituale, die weit über Standard-Magiekreise hinausgehen. Das verlorene Tome of the Cabal enthält die ursprünglichen Riten, die von den ersten Hexenmeistern verfasst wurden, die erfolgreich einen Teufelsjäger ohne Hilfe banden. Strahad und seine Akolythen stehen bereit, um die Beschwörungskreise über Ratschet zu weben, aber ohne das spezifische Wissen, das im Tome of the Cabal bewahrt ist, kann das Ritual nicht sicher beginnen.",al={"warum will strahad das tome","strahad farsan motiv","strahad cabal tome grund"}},["327d5815"]={q="Warum schickt Strahad mich, anstatt das Tome of the Cabal selbst zu bergen?",a="Die Unterwerfung eines dämonischen Dieners ist eine zutiefst persönliche Prüfung, die Euren Einfallsreichtum und Eure Entschlossenheit testet. Strahad stellt die Expertise, das Ritualheiligtum und die Akolythen bereit, um die Magie zu verankern, aber die Last, das notwendige Wissen zu sichern, liegt ganz bei Euch. Außerdem bleibt Strahad in Ratschet verschanzt, um gefährliche arkanische Kräfte zu verwalten, während Ihr frei zur Hall of Explorers in Eisenschmiede reisen könnt, um Gelehrte wie Krom Starkarm zu konsultieren und die verstreuten Relikte selbst zu bergen.",al={"warum schickt strahad mich","warum kann strahad das tome nicht holen","warum spieler nach eisenschmiede schicken"}}},fp="17,266,27.470.0,17.439.0,25.399.0,44.244.0,21.197.0,37.269.0,44.198.1,33.203.0,38.180.0"}
P.entries["quest:176"] = {n="GESUCHT: \"Hogger\"",s="GESUCHT: \"Hogger\" ist ein Kopfgelderlass der Allianz, der außerhalb von Goldhain für den Kopf eines riesigen, wilden Gnollhäuptlings ausgehängt wurde. Hogger durchstreift die südwestlichen Wälder im Wald von Elwynn und hat jeden Versuch der örtlichen Behörden, ihn zur Strecke zu bringen, gewaltsam vereitelt.",h="GESUCHT: \"Hogger\" ist ein Kopfgelderlass der Allianz, der außerhalb von Goldhain für den Kopf eines riesigen...",kw={"kopfgeld","dughan","elwynn","der waldrand","gnoll","goldhain","hogger","gesucht"},ang={["faction:Alliance"]="Das Bezwingen von Hogger gilt als Reifeprüfung für junge Helden der Allianz, die ihren Mut bei der Verteidigung des Kernlandes von Sturmwind unter Beweis stellen.",["race:Human"]="Für die Menschen von Elwynn sichert das Erschlagen von Hogger die Gehöfte und den Straßenhandel, die monatelang von Gnoll-Hinterhalten terrorisiert wurden."},sec={{t="Eine Bedrohung in den Wäldern",b="Während der Wald von Elwynn mit Banditentum und Koboldplagen zu kämpfen hat, sind die Gnollstämme im Süden unter der brutalen Führung von Hogger kühner und organisierter geworden. Hogger, der typische Gnolle der Flusspfoten weit überragt, hat in der Nähe vom Waldrand ein Lager aufgeschlagen, lauert Reisenden auf und überwältigt die örtlichen Milizpatrouillen, die zu seiner Unterwerfung ausgesandt wurden."},{t="Goldhains Verzweiflung",b="Da die Streitkräfte von Sturmwind stark überdehnt sind und keine regulären Truppen erübrigen können, um die Außenbezirke der Hauptstadt zu sichern, ergriff Marschall Dughan den ungewöhnlichen Schritt, ein offenes Kopfgeld auf die Bestie auszusetzen. Das Bezwingen von Hogger erfordert den Vorstoß in zutiefst feindseliges Gnollgebiet, und seine Wildheit hat ihm den Ruf der tödlichsten Bedrohung eingebracht, der sich unerfahrene Abenteurer in Elwynn stellen müssen."}},faq={{q="Wer ist Hogger?",a="Hogger ist ein ungewöhnlich großer und wilder Gnollanführer, der den südwestlichen Wald von Elwynn terrorisiert. Er befehligt die örtlichen Rudel rund um den Waldrand und hat alle bisherigen Versuche der Wachen von Sturmwind, ihn gefangen zu nehmen oder zu töten, gewaltsam vereitelt.",al={"wer ist hogger","hogger hintergrund","was ist hogger"}},{q="Wo ist Hogger zu finden?",a="Hogger streift durch die Gnoll-Lager im südwestlichen Wald von Elwynn, nahe der südlichen Grenze, die als Der Waldrand bekannt ist, knapp nördlich der Flussgrenze zu Westfall und dem Dämmerwald.",al={"hogger standort","wo ist hogger","hogger finden"}},{q="Warum ist ein Kopfgeld auf Hogger ausgesetzt?",a="Die Armee von Sturmwind setzte ein Kopfgeld auf Hogger aus, weil er örtliche Patrouillen überwältigt hat und eine tödliche Gefahr für Reisende darstellt. Da die offiziellen Truppen im ganzen Königreich überlastet sind, wandte sich Marschall Dughan an unabhängige Abenteurer und Kopfgeldjäger, um die Bedrohung zu beseitigen.",al={"warum hogger töten","gesucht poster hogger","wer hat kopfgeld auf hogger ausgesetzt"}},{q="Wer nimmt den Beweis für Hoggers Tod entgegen?",a="Der Beweis für das Ableben der Bestie – seine Gewaltige Gnollklaue – muss direkt zu Marschall Dughan gebracht werden, der die in Goldhain stationierte Garnison befehligt.",al={"hogger abgeben","wo hogger abgeben","wer will hoggers klaue"}},{q="Warum ist Hogger im Vergleich zu anderen Gnollen so gefährlich?",a="Im Gegensatz zu den gewöhnlichen Gnollen, die Elwynn unsicher machen, besitzt Hogger eine immense physische Statur und Brutalität. Er schlägt erheblich härter zu und hält weitaus mehr Schaden aus, wodurch er Einzelkämpfer, die ihn unterschätzen, oft überwältigt.",al={"ist hogger stark","warum ist hogger elite"}},{q="Warum können die Wachen von Sturmwind Hogger nicht selbst beseitigen?",a="Die militärischen Ressourcen des Königreichs sind stark erschöpft und durch die Verteidigung wichtiger Grenzen oder das Verschwinden von König Varian Wrynn gebunden. Marschall Dughans kleiner Einheit in Goldhain fehlt die nötige Mannstärke, um eine derart widerstandsfähige Bestie gefahrlos zur Strecke zu bringen.",al={"warum tötet dughan hogger nicht","wo ist die armee von sturmwind"}}},fx={fccb34f1={q="Wozu dient die Gewaltige Gnollklaue?",a="Die Gewaltige Gnollklaue dient als unbestreitbarer Beweis für den Tod von Hogger. Da das Biest jeden Versuch seiner Gefangennahme vereitelt hat, benötigen Marschall Dughan und die Armee von Sturmwind einen unmissverständlichen physischen Beweis, bevor sie die ausgeschriebene Kopfgeldprämie aushändigen.",al={"gewaltige gnollklaue","warum brauche ich hoggers klaue","hogger klaue verwendung"}}},fp="16,253,21.347.0,23.369.0,14.234.0,26.184.0,32.274.0,41.151.0,52.226.0,56.251.0"}
P.entries["quest:177"] = {n="Der Blick zu den Sternen",s="Diese Quest schickt Abenteurer los, um den weggeworfenen Handspiegel von der blinden Mary für den Astronomen Viktori Prism'Antras zu beschaffen. Der zerbrechliche Spiegel fiel in die Hände eines Insane Ghoul, der auf dem Friedhof \"Stille Gärten\" im südlichen Dämmerwald umherstreift.",h="Diese Quest schickt Abenteurer los, um den weggeworfenen Handspiegel von der blinden Mary für den Astronomen...",kw={"die blinde mary","cog","dunkelhain","insane ghoul","der blick zu den sternen","marys handspiegel","teleskop","der friedhof \"stille gärten\"","viktori prism'antras"},ang={["class:Priest"]="Priester, die den verdorbenen Boden des Friedhofs \"Stille Gärten\" betreten, werden Zeuge der schrecklichen Schmach, die den Toten des Dämmerwalds widerfährt, da gefallene Dorfbewohner zu wahnsinnigen Plünderern degradiert wurden.",["faction:Alliance"]="Die Bergung verlorener Stadtreliquien aus den Händen unersättlicher Untoter verdeutlicht das bittere Schicksal des Volkes im Dämmerwald, das an den gefährlichen Rändern des Königreichs Sturmwind im Stich gelassen wurde.",["profession:Engineering"]="Ingenieure wissen Viktoris improvisierte optische Mechanismen zu schätzen, mit denen er gewöhnliche polierte Handspiegel in reflektierende Bauteile für ein astronomisches Instrument verwandelt."},sec={{t="Ein Relikt besserer Tage",b="Bevor die schleichende Düsternis Grand Hamlet überrannte und sie in einen weinenden Geist verwandelte, schätzte die blinde Mary einen verzierten Handspiegel sehr. Nach dem schrecklichen Vorfall, der ihr das Augenlicht und den Verstand raubte, warf sie das Andenken hinter die Scheune ihrer Familie in den Schmutz. Der reflektierende Spiegel ist genau das, was Viktori Prism'Antras für den Bau seines großen Teleskops in Dunkelhain benötigt, doch er wurde schon lange vor den Träumen des Astronomen, den Himmel zu erforschen, in die Schatten geraubt."},{t="Der Friedhofsplünderer",b="Der Spiegel wurde von einem Insane Ghoul geraubt, der hinter den verfallenen Gehöften herumlungerte. Getrieben von rastlosem Hunger trug die erbärmliche untote Kreatur den Handspiegel zum Friedhof \"Stille Gärten\" und spukt nun in einer verlassenen Kapelle inmitten der überwucherten Grabsteine. Die Bergung der empfindlichen Linse erfordert es, den fleischfressenden Schrecken zu trotzen, die die südlichen Wälder heimsuchen, um Marys verlorenen Schatz aus verrottenden Klauen zu reißen."}},faq={{q="Warum braucht Viktori Marys Handspiegel?",a="Viktori Prism'Antras baut in seiner Hütte auf dem Hügel in Dunkelhain ein mächtiges Teleskop zusammen. Er benötigt hochwertige reflektierende Linsen und Spiegel, um das schwache Sternenlicht zu bündeln, und Marys geschätztes Erbstück erfüllt die genauen optischen Anforderungen für seine Erfindung.",al={"viktori spiegel","warum handspiegel","wofür ist der spiegel"}},{q="Wer ist der Insane Ghoul, der den Spiegel gestohlen hat?",a="Der Insane Ghoul ist ein plünderndes untotes Ungetüm, das Schmuckstücke von den verlassenen Gehöften nahe Marys Haus zusammengetragen hat. Er floh nach Süden und suchte Zuflucht in der zerstörten Kapelle auf dem Friedhof \"Stille Gärten\".",al={"wo ist der insane ghoul","wer hat den handspiegel","ghul in kapelle"}},{q="Warum hat die blinde Mary ihren Handspiegel weggeworfen?",a="Mary schätzte ihren Handspiegel sehr, bis zu \"dem Vorfall\", der ihr das Augenlicht raubte, ihren Verstand zerrüttete und sie als rastlosen Schemen band. Nach diesem Unglück konnte sie es nicht mehr ertragen, hineinzusehen oder ihn zu halten, und warf ihn voller Verzweiflung hinter ihrer Scheune weg.",al={"warum warf mary ihn weg","die blinde mary spiegel","mary handspiegel vorfall"}},{q="Wo liegt der Friedhof \"Stille Gärten\"?",a="Der Friedhof \"Stille Gärten\" liegt in den südöstlichen Ausläufern des Dämmerwalds, südlich der Hauptstraße. Einst eine friedliche Ruhestätte für Grand Hamlet, wird er nun von aggressiven Ghulen, Skeletten und Aasbestien heimgesucht.",al={"stille gärten standort","wo ist der friedhof"}},{q="Wer ist Cog?",a="Cog ist ein Gnomentüftler, der in Dunkelhain ansässig ist. Viktori verlässt sich auf Cogs Ingenieurskunst, um die empfindlichen Mechanismen seines Sternenbeobachtungsgeräts zu begutachten und bei deren Konstruktion zu helfen.",al={"wer ist cog","viktori cog"}},{q="Was geschieht, nachdem man Viktori den Spiegel zurückgebracht hat?",a="Mit dem reflektierenden Gegenstand in Händen ist Viktori begeistert vom Fortschritt des Apparats. Anschließend beginnt er die letzte Phase des Zusammenbaus seines Teleskops und bittet um eine allerletzte entscheidende Komponente zur Vollendung des Linsensystems.",al={"der blick zu den sternen folgequest","was kommt danach"}}},fx={["9a9407cc"]={q="Warum hilft Die blinde Mary Euch, das Fernrohr zu finden?",a="Mary hegt keinen Wunsch, ihr Fernrohr zu behalten. Einst unter ihren wertvollsten Schätzen, wurde es für sie unerträglich, nachdem ein tragischer Vorfall sie erblindete und ins Verderben stürzte. Nachdem sie es in ihrer Verzweiflung bereits hinter ihre Scheune geworfen hat, hat sie keinen Grund, dessen Schicksal geheim zu halten, und weist Euch bereitwillig den Weg zu dem Plünderer, der es genommen hat.",al={"warum hilft die blinde mary","die blinde mary motiv fernrohr","warum sagt mary, wo der spiegel ist"}},["161ca8d7"]={q="Warum benötigt Die blinde Mary Euch, um den Spiegel zu bergen, anstatt ihn selbst zu holen?",a="Die blinde Mary ist ein hilfloser, blinder Geist, der isoliert außerhalb von Dunkelhain verweilt. Selbst zu Lebzeiten wäre es für sie unmöglich gewesen, sich einer wilden Monstrosität der Geißel entgegenzustellen, und im Tod ist sie an ihre heimgesuchte Hütte gebunden. Ein bewaffneter Abenteurer ist der einzige, der fähig ist, dem Der Friedhof \"Stille Gärten\" zu trotzen, um ihn zurückzuholen.",al={"warum kann mary den spiegel nicht holen","warum braucht mary mich","warum holt mary das fernrohr nicht selbst"}}},fp="17,249,22.467.0,23.420.0,43.261.0,46.205.0,48.237.0,39.221.0,11.184.0,51.228.1"}
P.entries["quest:178"] = {n="Wiederbeschaffung für Theocritus",s="Theocritus' Retrieval beginnt, wenn ein Abenteurer im Rotkammgebirge ein magisches Schmuckstück findet, das von den örtlichen Gnollen getragen wird, und eine ferne Stimme daraus vernehmen kann. Der Sprecher ist Theocritus, ein Hochmagier vom Turm von Azora, der das mystische Netzwerk der Gnolle erfolgreich angezapft hat und dringend darum bittet, den Anhänger zu ihm zu bringen, damit er ihn untersuchen kann.",h="Theocritus' Retrieval beginnt, wenn ein Abenteurer im Rotkammgebirge ein magisches Schmuckstück findet, das...",kw={"wald von elwynn","gnolle","morganth","anhänger","rotkammgebirge","schattenfell","theocritus","turm von azora"},ang={["class:Mage"]="Theocritus' Arbeit demonstriert eine geniale Anwendung von Bannzaubern und Divination, indem er das Netzwerk eines anderen Zauberers hackt, um Gegen-Zauber über große Distanzen zu übermitteln.",["faction:Alliance"]="Die Koordination zwischen dem Turm von Azora im Wald von Elwynn und den bedrängten Verteidigern von Seenhain zeigt, wie örtliche Magier dort eingreifen, wo die königliche Armee von Sturmwind ihre Garnisonen unterbesetzt gelassen hat."},sec={{t="Eine Stimme im Stein",b="Während sie gegen die wilden Schattenfellgnolle im ganzen Rotkammgebirge kämpfen, stolpern Reisende manchmal über ein verzaubertes Schmuckstück, bekannt als Schattenfellanhänger. Anstatt gutturalem Bellen oder Flüchen löst eine Berührung des Objekts eine ruhige, körperlose Stimme aus, die Theocritus gehört, einem menschlichen Magier, der im Turm von Azora jenseits der Grenze im Wald von Elwynn lebt. Die Übertragung ist das Ergebnis langer, mühsamer Forschung mit dem Ziel, in die dunklen Zaubereien einzudringen, die die Gnollrudel lenken."},{t="Morganths Netzwerk unterwandern",b="Die Schattenfellgnolle handeln nicht rein aus triebhaftem Instinkt; sie gehorchen Morganth, einem abtrünnigen dunklen Zauberer, der in den Bergen verborgen ist. Morganth fertigt diese verzauberten Anhänger an und verteilt sie, um Befehle direkt an seine tierischen Schergen zu übermitteln. Theocritus verbrachte Monate damit, die Frequenz von Morganths Sendezaubern zu entschlüsseln. Wenn ein Abenteurer den verblichenen Anhänger zum Turm von Azora zurückbringt, bestätigt der Zauberer, dass sein Spähen das Talisman erreichte, was die Tür öffnete, um einen Angriff zu entwickeln, der die Gnolle vollständig ausschaltet."}},faq={{q="Wer ist Theocritus?",a="Theocritus ist ein Hochmagier der Allianz, der im Turm von Azora im östlichen Wald von Elwynn stationiert ist. Er behält regionale Störungen im Auge und widmet einen Großteil seiner magischen Studien der Bekämpfung dunkler Magie, die vom Rotkammgebirge herüberdringt.",al={"theocritus hintergrundgeschichte","wer spricht durch den anhänger","magier vom turm von azora"}},{q="Warum trugen die Schattenfellgnolle magische Anhänger?",a="Die Anhänger sind magische Leitungen, die von dem abtrünnigen Zauberer Morganth erschaffen wurden. Durch sie sendet er mentale Befehle und koordiniert die Bewegungen des Schattenfellklans aus der Ferne.",al={"warum haben gnolle anhänger","zweck des schattenfellanhängers","magischer gnollgegenstand"}},{q="Warum war die Stimme verzögert, als Theocritus sie sendete?",a="Theocritus sprach seine Nachricht Wochen bevor ein Abenteurer den Stein fand, da er anfangs glaubte, sein Zauber hätte sich aufgelöst und sei fehlgeschlagen. Das Durchdringen von Morganths dunklen Schutzzaubern und der Aufbau einer Verbindung über eine so große Distanz verursachte eine beträchtliche magische Verzögerung.",al={"verzögerte nachricht","warum brauchte theocritus wochen","verzögerung beim verblichenen anhänger"}},{q="Was erhofft sich Theocritus von dem zurückgebrachten Anhänger?",a="Durch die Entschlüsselung der spezifischen magischen Frequenz, die den Anhänger mit Morganth verbindet, hofft Theocritus, den Magiefluss umzukehren. Sein ultimatives Ziel ist es, einen Angriffszauber durch das Netzwerk zu senden, der jeden Gnoll, der einen solchen trägt, augenblicklich bewegungsunfähig machen könnte.",al={"plan von theocritus","was wird theocritus tun","warum den anhänger untersuchen"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Die Abgabe des Anhängers schließt diesen Auftrag für sich genommen ab. Theocritus' eigenständiger Kampf gegen Morganth geht in 'A Watchful Eye' weiter, das Abenteurer aussendet, um Morganths Festung im Der Turm von Ilgalar auszuspionieren.",al={"nächste quest nach theocritus' retrieval","morganth-reihe","was passiert als nächstes"}}},fx={["24fcac1f"]={q="Warum benötigt Theocritus einen Abenteurer, um das Amulett zu überbringen?",a="Theocritus sandte seine Nachricht blind über die magischen Frequenzen aus, die Morganth benutzt, um mit den Gnollen zu kommunizieren, ohne eine Ahnung zu haben, wo oder wann ein Amulett sie empfangen könnte. An sein Heiligtum im Turm von Azora im Wald von Elwynn gebunden, konnte er die feindselige Wildnis des Rotkammgebirges nicht selbst durchkämmen. Er verlässt sich auf jeden fähigen Reisenden, der das Artefakt entdeckt, um es sicher zurück in zivilisierte Lande zu tragen.",al={"warum einen abenteurer schicken","warum braucht theocritus mich","warum kann theocritus das amulett nicht holen"}}},fp="21,342,20.490.0,29.538.1,18.244.0,57.178.0,50.252.0,64.257.0,38.216.1"}
P.entries["quest:1782"] = {n="Furens Rüstung",s="Furens Rüstung markiert den Höhepunkt der Quest eines aufstrebenden Kriegers, dem Meisterschmied Furen Langbart in Sturmwind beizustehen. Durch das Sammeln von Spinnenzähnen, Schimärenhörnern und einer Phiole mit Phlogiston hilft Der Abenteurer Longbeard dabei, einen widerstandsfähigen feuergehärteten Panzer zu schmieden. Als Gegenleistung für diese Hilfe belohnt Longbeard den Krieger mit dem fertigen Kettenpanzer und gelobt, seine neu entdeckten metallurgischen Techniken in der gesamten Allianz zu teilen.",h="Furens Rüstung markiert den Höhepunkt der Quest eines aufstrebenden Kriegers, dem Meisterschmied Furen...",kw={"allianzkrieger","schmiedekunst","feuergehärteter panzer","furen langbart","furens rüstung","schwere rüstung","sturmwind"},ang={["class:Warrior"]="Für heranwachsende Krieger der Allianz stellt das Verdienen von Furens maßgehärteter Rüstung einen Initiationsritus dar und bietet unverzichtbaren Schutz für frühe Kampagnen an vorderster Front.",["faction:Alliance"]="Starke Rüstungen sind unerlässlich, um die Streitkräfte der Allianz gegen anhaltende Bedrohungen durch die Defias, Gnolle und feindliche Elementarkräfte am Leben zu erhalten.",["profession:Blacksmithing"]="Furens erfolgreiches Experiment unterstreicht die kooperative Tradition der Allianzschmiede, die spezialisierte metallurgische Entdeckungen teilen, um die Handwerksstandards in ganz Sturmwind und Eisenschmiede anzuheben."},sec={{t="Der Durchbruch eines Meisters",b="Furen Langbart, ein geschätzter Zwergenrüstschmied in Sturmwind, hat sein Handwerk dem Ziel gewidmet, die Grenzen der defensiven Metallurgie der Allianz zu erweitern. Indem er einen unerschütterlichen Abenteurer damit beauftragte, seltene Zähne, Hörner und Phlogiston aufzuspüren, wollte Longbeard fortschrittliche Techniken testen, um Kettenglieder gegen sengende Hitze und vernichtende Schläge zu härten. Die daraus resultierende Handwerkskunst erweist sich als enormer Erfolg und festigt Longbeards Ruf als einer der führenden Rüstungsschmiede der Allianz."},{t="Das Handwerk teilen",b="Bei der Übergabe des frisch fertiggestellten feuergehärteten Panzers an den Abenteurer, der die Materialien gesammelt hat, drückt Furen seine tiefe Dankbarkeit für die Partnerschaft aus. Die Experimente brachten mehr hervor als nur eine einzige strapazierfähige Rüstung; sie erweiterten sein Verständnis des schützenden Schmiedens. Im gemeinschaftlichen Geist der Handwerker von Eisenschmiede und Sturmwind beschließt Longbeard, seine Notizen und Entdeckungen an Schmiedekollegen der Allianz zu senden, um sicherzustellen, dass sein Durchbruch die Frontkämpfer der gesamten Fraktion stärkt."}},faq={{q="Wer ist Furen Langbart?",a="Furen Langbart ist ein zwergischer Meisterschmied, der in der Stadt Sturmwind tätig ist. Er arbeitet eng mit den Kriegerorden der Allianz zusammen, insbesondere mit Kriegern, die spezialisierte, hochwertige Rüstungen suchen.",al={"wer ist furen","furen langbart","sturmwind schmied furen"}},{q="Welche Art von Rüstung hat Furen hergestellt?",a="Durch ausführliche Experimente mit seltenen Zähnen, Hörnern und Phlogiston schmiedete Furen eine Feuergehärtete Halsberge, ein Kettenbrustteil. Er entwarf sie so, dass sie wilden Angriffen und extremer Hitze auf dem Schlachtfeld standhält.",al={"welche rüstung stellt furen her","feuergehärteter panzer","furens belohnung"}},{q="Wohin sendet Furen Langbart seine schmiedetechnischen Entdeckungen?",a="Furen verspricht, seine technischen Erkenntnisse und Notizen an Schmiedekollegen in der gesamten Allianz zu senden, um die Vorteile der neu erprobten Härtemethoden in Rüstkammern und Schmieden im ganzen Reich zu verbreiten.",al={"furens notizen","wer bekommt furens pläne","allianzschmiede"}},{q="Warum wurde der Krieger gebeten, Reagenzien für Furen zu sammeln?",a="Furen benötigte seltene und flüchtige Komponenten, um ungetestete Schmiedetechniken auszuprobieren. Da er seine Schmiede nicht verlassen konnte, um die Spinnen des Sumpflands und die Schimären des Steinkrallengebirges zu jagen, verließ er sich darauf, dass ein ehrgeiziger Krieger sie beschafft.",al={"warum reagenzien für furen sammeln","feuergehärteter panzer questmaterialien"}},{q="Wo wird diese Rüstung geschmiedet und übergeben?",a="Der Austausch findet direkt an Furen Langbarts Schmiede in der Stadt Sturmwind statt, wo er das abschließende Hämmern und Abkühlen der Kettenrüstung vollendet.",al={"wo ist furen langbart","abgabeort","furen standort"}},{q="Kommt diese Arbeit anderen Kämpfern der Allianz zugute?",a="Ja. Furen merkt an, dass die aus der Arbeit mit diesen Materialien gezogenen Lehren mit anderen Rüstschmieden der Allianz geteilt werden, was seiner Hoffnung nach weitere Schmiede dazu ermutigen wird, Eliteausrüstung für die Soldaten der Allianz herzustellen und bereitzustellen.",al={"vorteil für die allianz","furens durchbruch"}}},fp="13,426,23.485.0,17.494.0,23.201.0,36.214.0,57.204.0,55.237.0,41.155.0,47.223.0"}
P.entries["quest:179"] = {n="Zwergenausstatter",s="Zwergenausstatter ist eine einführende Überlebensaufgabe im Coldridgetal, die von Sten Starkarm angeboten wird. Im Austausch für das Ausdünnen der einheimischen Wölfe und das Sammeln ihres zähen Fleisches für Winterrationen werden frische Rekruten mit robusten Handschuhen belohnt, um Erfrierungen in der eisigen Kälte von Dun Morogh abzuwehren.",h="Zwergenausstatter ist eine einführende Überlebensaufgabe im Coldridgetal, die von Sten Starkarm angeboten...",kw={"ambossar","das coldridgetal","dun morogh","zwergenausstatter","erfrierungen","handschuhe","sten starkarm","zähes wolfsfleisch"},ang={["race:Dwarf"]="Für junge Bronzebartzwerge, die ihre ersten Schritte ins Coldridgetal wagen, ist diese Aufgabe eine frühe Lektion in Sachen Selbstständigkeit im Grenzland: Verdient Euren Lebensunterhalt, versorgt das Lager und respektiert die Kälte der Berge.",["race:Gnome"]="Nachdem sie bei ihren zwergischen Vettern in Dun Morogh Zuflucht gesucht haben, stellen Gnome schnell fest, dass das Überleben in Ambossar praktische Gebirgskleidung genauso erfordert wie einen scharfen Verstand."},sec={{t="Ein fairer Handel in Coldridge",b="Der Hochgebirgspass des Coldridgetals ist bitterkalt, und unvorbereitete Reisende lernen schnell, dass eine Standardausrüstung den Elementen nicht gewachsen ist. Vor Ambossar bietet Sten Starkarm neuen Rekruten einen unkomplizierten Handel im Grenzland an: Wagt Euch in die Schneewehen, jagt die umherstreifenden Wölfe und bringt Stücke von zähem Fleisch zurück, um den Außenposten zu versorgen. Im Gegenzug stellt er ordentliche Kälteschutzhandschuhe zur Verfügung, damit junge Abenteurer alle zehn Finger behalten."},{t="Leben vom Tal",b="Während Wölfe eine ständige Gefahr für Zwergenspäher und die im Tal trainierenden Gnomenneulinge darstellen, sind sie zugleich eine lebenswichtige Ressource. Ihr Fleisch ernährt die in Ambossar stationierte Garnison, und das Ausdünnen ihrer Bestände macht die Pfade zwischen den örtlichen Lagern etwas sicherer. Stoutarms Abmachung dient einem doppelten Zweck – sie prüft die Fähigkeit eines Rekruten, mit der heimischen Tierwelt umzugehen, während Vorräte für die bitterkalten Nächte angelegt werden."}},faq={{q="Wer ist Sten Starkarm?",a="Sten Starkarm ist ein Zwerg, der vor Ambossar im Coldridgetal stationiert ist. Er hält Ausschau nach neu eingetroffenen Rekruten und stellt sicher, dass sie für das Überleben im frostigen Wetter von Dun Morogh gerüstet sind, indem er praktische Ausrüstung gegen die Jagd auf lokales Wild anbietet.",al={"sten starkarm","wer vergibt zwergenausstatter","ausstatter von ambossar"}},{q="Warum braucht Sten Wolfsfleisch?",a="Der Außenposten von Ambossar ist auf die Jagd vor Ort angewiesen, um seine Vorräte aufzustocken. Wolfsfleisch liefert den Truppen und Ausbildern, die im abgelegenen, eingeschneiten Tal leben, eine deftige, verlässliche Nahrung.",al={"warum wolfsfleisch","zähes wolfsfleisch","wofür ist das fleisch"}},{q="Wo findet man die Wölfe für diese Aufgabe?",a="Wölfe streifen durch die verschneiten Lichtungen im gesamten Coldridgetal, besonders direkt hinter dem Haupthof von Ambossar und entlang der Pfade, die zu den entlegeneren Lagern führen.",al={"wo sind wölfe","wölfe fundorte coldridge","woher bekommt man fleisch"}},{q="Welche Belohnung bietet Sten?",a="Sten belohnt Rekruten mit einem verlässlichen Paar warmer Handschuhe, die speziell entwickelt wurden, um Erfrierungen abzuwehren und die Hände eines Kämpfers vor den schneidenden Winden von Dun Morogh zu schützen.",al={"zwergenausstatter belohnung","welche handschuhe bekommt man","questbelohnung"}},{q="Gilt Wolfsfleisch bei Zwergen als gutes Essen?",a="Zähes Wolfsfleisch ist grobfaserig und schwer zu kauen, doch im rauen Gebirgsklima von Dun Morogh schätzen Zwerge eine herzhafte, sättigende Mahlzeit weit mehr als feine Gourmetküche. Als Eintopf oder über dem Lagerfeuer geröstet leistet es der Garnison gute Dienste.",al={"schmeckt wolfsfleisch","zwerge wolfsfleisch","wolf essen"}},{q="Können Gnome diese Quest ebenfalls annehmen?",a="Ja. Gnome, die an der Seite ihrer zwergischen Verbündeten im Coldridgetal trainieren, trotzen denselben beißenden Winden und benötigen warme Kleidung genauso dringend.",al={"gnom zwergenausstatter","können gnome handschuhe bekommen","gnom kaltes wetter"}}},fx={cf6e8786={q="Was machen die Wölfe im Coldridgetal?",a="Zerlumpte junge Wölfe und zerlumpte Holzwölfe streifen als einheimische Raubtiere durch die gefrorenen Klippen des Coldridgetals. Obwohl sie ein natürlicher Teil der rauen Gebirgsökologie von Dun Morogh sind, macht sie ihr aggressives Herumstreunen direkt vor Ambossar zu einer ständigen Plage für junge Rekruten und zu einer praktischen Quelle für frische Vorräte für den Außenposten.",al={"warum sind hier wölfe","coldridgetal wölfe","wolfbedrohung dun morogh"}}},fp="18,283,25.471.0,21.438.0,21.262.0,29.195.0,43.175.0,30.166.0,48.221.0,29.145.0"}
P.entries["quest:1791"] = {n="Der Windbehüter",s="Der Windbehüter ist eine belehrende Aufforderung, die erfahrene Krieger dazu anweist, einen zurückgezogen lebenden Trollschamanen weit im Norden aufzusuchen. Nachdem sie ihren Mut in der Prüfung des Ringkampfs bewiesen und die Berserkerhaltung gemeistert haben, werden die Krieger angewiesen, eine Waffe zu suchen, die ihrem wachsenden Zorn ebenbürtig ist.",h="Der Windbehüter ist eine belehrende Aufforderung, die erfahrene Krieger dazu anweist, einen zurückgezogen...",kw={"alteracgebirge","bath'rah","berserkerhaltung","cyclonian","prügel-eiland","klannoc macleod","tarrens mühle","der ringkampf","der windbehüter"},ang={["class:Warrior"]="Dieser Übergangsritus schlägt eine Brücke zwischen Eurer Beherrschung der Berserkerhaltung auf Prügel-Eiland und dem Streben nach einer legendären Bewaffnung, die durch elementare Macht geschmiedet wurde.",["race:Troll"]="Die Suche nach Bath'rah beweist, dass selbst tief in den zerstörten Ruinen von Lordaeron Trollschamanen und Waffenschmiede über mystisches Wissen gebieten, das Krieger jeglicher Herkunft verehren."},sec={{t="Eine Waffe für einen Berserker",b="Nachdem sie die brutale Ausdauerprüfung des Ringkampfs auf Prügel-Eiland überstanden haben, erlangen Krieger die wilde Disziplin der Berserkerhaltung von Klannoc Macleod. Doch eine derart rohe kriegerische Disziplin verlangt nach einer Waffe von gleichem Ruhm. In dieser Erkenntnis schickt Klannoc vielversprechende Kämpfer von der Küste des Brachlands fort und weist ihnen den Weg über Kontinente, um einen einsamen Handwerker aufzusuchen, der fähig ist, eine außergewöhnliche Bewaffnung zu schmieden."},{t="Der Einsiedler am Flussufer",b="Die Quest führt Reisende tief in die umkämpften Täler des nördlichen Lordaerons, insbesondere in das nebelverhangene Grenzland zwischen dem Alteracgebirge und den verheerten Westlichen Pestländern. Am Fluss, der nördlich an Tarrens Mühle vorbeifließt, lebt der Trolleinsiedler Bath'rah der Windbehüter isoliert inmitten steinerner Ruinen. Bath'rah ist kein gewöhnlicher Einsiedler: Er ist sowohl ein begabter Waffenschmied als auch ein Meister mächtiger Elementarschamanismus-Kräfte, der auf Krieger wartet, die entschlossen genug sind, etwas wahrhaft Monumentales zu schmieden."}},faq={{q="Wer schickt Euch aus, um den Windbehüter zu finden?",a="Klannoc Macleod, der Meister der Kampfprüfungen auf Prügel-Eiland vor der Ostküste des Brachlands, schickt Euch auf diese Reise, sobald Ihr den Ringkampf bezwungen und die Berserkerhaltung erlernt habt.",al={"questgeber","wer vergibt der windbehüter","klannoc macleod quest"}},{q="Wer ist Bath'rah der Windbehüter?",a="Bath'rah ist ein rätselhafter Trolleinsiedler, meisterhafter Waffenschmied und mächtiger Schamane, der isoliert in der Wildnis zwischen dem Alteracgebirge und den Westlichen Pestländern lebt.",al={"wer ist bathrah","bathrah der windbehüter lore","bath'rah identität"}},{q="Wo genau befindet sich Bath'rah?",a="Bath'rah schlägt sein Lager am östlichen Ufer des Flusses auf, der nördlich an Tarrens Mühle vorbeifließt, gelegen nahe uralten Ruinen an der Grenze zwischen Alterac und den Westlichen Pestländern.",al={"wo ist bath'rah","bathrah standort","bathrah finden"}},{q="Warum schickt Klannoc Krieger zu Bath'rah?",a="Klannoc erkennt, dass ein Krieger, der die wilde Berserkerhaltung gemeistert hat, eine außergewöhnliche Waffe benötigt, um diesen Zorn zu kanalisieren, und Bath'rah besitzt das seltene Wissen über die Elemente und das Schmieden, um eine solche herzustellen.",al={"warum zu bathrah gehen","was ist das ziel dieser quest","windbehüter zweck"}},{q="Was geschieht nach dem Gespräch mit Bath'rah?",a="Das Gespräch mit Bath'rah führt unmittelbar zur Quest, sich dem stürmischen Elementar Cyclonian zu stellen und seltene Materialien zu sammeln, um eine mächtige Kriegswaffe herzustellen.",al={"wie geht es nach dem windbehüter weiter","cyclonian folgequest","windbehüter fortsetzung"}},{q="Ist diese Reise für einen Reisenden aus dem Brachland sicher?",a="Sie ist ziemlich gefährlich. Die Reise führt Reisende durch das Vorgebirge von Hillsbrad in umkämpfte nördliche Gebiete nahe Unterschlüpfen des Syndikats, angriffslustigen Raubtieren des Gebirges und der tödlichen Seuche der Westlichen Pestländer.",al={"ist es gefährlich","gefahr fluss tarrens mühle"}}},fx={ff43a27e={q="Warum schickt Klannoc Euch zu Bath'rah, anstatt selbst zu gehen?",a="Klannoc Macleod sucht nicht für sich selbst nach einer legendären Waffe; er dient als erfahrener Mentor auf den Übungsplätzen auf dem Prügel-Eiland. Da er gesehen hat, wie Ihr The Affray überlebt und die Berserkerhaltung gemeistert habt, glaubt er, dass Ihr bereit für eine Waffe seid, die Eurem neu entfesselten Zorn würdig ist. Die lange Pilgerreise zu dem weit entfernten Einsiedler Bath'rah ist eine Prüfung für die eigene Entschlossenheit und das Wachstum eines Kriegers.",al={"warum ich the windwatcher","warum krieger senden","warum klannoc spieler sendet"}}},fp="15,283,24.410.0,27.517.0,38.202.0,32.171.0,34.175.0,43.210.0,40.163.1,60.223.0"}
P.entries["quest:1793"] = {n="Der Foliant der Tapferkeit",s="Der Foliant der Tapferkeit ist eine grundlegende Prüfung für heranreifende Paladine der Allianz. Unter der Anleitung von Paladin-Mentoren in Sturmwind und Eisenschmiede werden Initianden dazu herausgefordert zu beweisen, dass ihr Mut und ihre Hingabe zum Schutz der Unschuldigen ihrem kriegerischen Können in nichts nachstehen.",h="Der Foliant der Tapferkeit ist eine grundlegende Prüfung für heranreifende Paladine der Allianz.",kw={"kathedrale des lichts","duthorian rall","das heilige licht","eisenschmiede","paladinprüfung","silver hand","tiza kriegshammer","foliant der ehre"},ang={["class:Paladin"]="Dieser Ritus markiert den Übergang von einem einfachen Akolythen zu einem vertrauenswürdigen Verteidiger des Heiligen Lichts und fordert Euch heraus, selbstlose Pflichterfüllung über Eure persönliche Sicherheit zu stellen.",["faction:Alliance"]="Die im Folianten beschriebenen Prüfungen bereiten Streiter darauf vor, Siedlungen der Allianz gegen wachsende Bedrohungen zu verteidigen – von örtlichen Banditen bis hin zu monströsen Eindringlingen.",["race:Dwarf"]="Die Paladine von Eisenschmiede unter der Führung von Mentoren wie Tiza Kriegshammer betrachten den Foliant der Ehre als Beweis dafür, dass die zwergische Standhaftigkeit durch eine heilige Bestimmung gestärkt wird.",["race:Human"]="Unter dem wachsamen Auge von Duthorian Rall in der Kathedrale des Lichts organisiert, spiegelt diese Prüfung Sturmwinds beständige Hingabe an die Gründungsideale der Silver Hand wider."},sec={{t="Der Maßstab eines Paladins",b="Um das Heilige Licht im Kampf zu führen, bedarf es mehr als schwerer Rüstung und kriegerischer Disziplin. Wenn junge Paladine in ihrer Ausbildung weiter voranschreiten, verlangen die Ausbilder in der Kathedrale des Lichts und der Hall of Mysteries Beweise für ihre innere Entschlossenheit. Die Lehren aus dem Foliant der Ehre prüfen die Bereitschaft eines Initianden, sich furchterregenden Übeln – von Drachen bis hin zu Dämonen – zu stellen, ohne zu wanken oder jene im Stich zu lassen, die sich nicht selbst verteidigen können."},{t="Tugenden des Ordens",b="Tapferkeit angesichts tödlicher Bedrohungen gilt für einen heiligen Krieger als ebenso unverzichtbar wie seine Waffe und sein Schild. Durch die im Foliant der Ehre dargelegten Prüfungen lernen Paladine, dass rohe Stärke wertlos ist ohne den unerschütterlichen Eid, den Hilflosen Schutz zu gewähren. Echtem Unheil entgegenzutreten stellt sicher, dass die Verteidiger der Allianz standhaft bleiben und nicht zerbrechen, wenn Dunkelheit über sie hereinbricht."}},faq={{q="Was ist der Zweck des Folianten der Ehre?",a="Der Foliant der Tapferkeit stellt einen Übergangsritus für aufstrebende Paladine der Allianz dar. Er wurde von den Mentoren des Heiligen Lichts geschaffen, um sicherzustellen, dass ein Initiand wahrhaften Mut und den uneigennützigen Wunsch besitzt, die Schwachen zu beschützen, bevor er im Orden aufsteigt.",al={"was ist der foliant der ehre","zweck des folianten der ehre","warum foliant der ehre machen"}},{q="Wer leitet Paladine bei dieser Prüfung an?",a="Initianden werden üblicherweise von ranghohen Paladinen in den Hauptstädten der Allianz zu dieser Prüfung berufen, wie etwa von Duthorian Rall in der Kathedrale des Lichts in Sturmwind oder von Tiza Kriegshammer in Eisenschmiedes Hall of Mysteries.",al={"wer vergibt foliant der ehre","foliant der ehre questgeber","wer startet foliant der ehre"}},{q="Wohin führt diese Prüfung?",a="Der anfängliche Ruf dient als Tor zu einer Reihe spezifischer Aufgaben, die die Entschlossenheit des Paladins auf die Probe stellen und ihn hinaus ins Feld führen, um sich im Schutz des Reiches und der Unschuldigen echten Gefahren zu stellen.",al={"was kommt nach foliant der ehre","foliant der ehre folgequest","foliant der ehre questreihe"}},{q="Warum wird Tapferkeit bei Paladinen so stark betont?",a="Das Heilige Licht antwortet auf Glauben und Willen. Bei der Konfrontation mit überwältigenden Schrecken wie Dämonen oder Drachen kann Furcht den Geist eines Kriegers brechen; Mut gewährleistet, dass ein Paladin selbst unter den finstersten Umständen ein unerschütterlicher Schild für andere bleibt.",al={"warum ehre","warum mut paladinen wichtig ist"}},{q="Unterziehen sich Zwergen- und Menschenpaladine derselben Prüfung?",a="Während Zwergenpaladine von Eisenschmiede aus ausgebildet werden und Menschen in Sturmwinds Kathedrale des Lichts, folgen beide Traditionen denselben Kernwugenden aus Mut, Pflichtbewusstsein und dem Schutz der Hilflosen unter dem Licht.",al={"ist es bei zwergen anders","eisenschmiede foliant der ehre","sturmwind foliant der ehre"}},{q="Welche grundlegenden Lehren werden in der Prüfung vermittelt?",a="Die Prüfung dreht sich um drei grundlegende Pflichten: ungebeugten Mut ungeachtet der Chancen zu beweisen, die Schwachen aktiv vor Unheil zu bewahren und den Glauben angesichts des Terrors aufrechtzuerhalten.",al={"foliant der ehre lehren","was lehrt der foliant"}}},fx={["81822402"]={q="Warum wollen die Paladinmeister, dass Ihr diese Prüfung ablegt?",a="Die Zeiten in Azeroth werden immer gefährlicher, bedroht durch drohende Übel wie Dämonen und Drachen. Obwohl Ihr bereits bewiesen habt, dass das Heilige Licht auf Euren Ruf antwortet, wissen Duthorian Rall und Tiza Kriegshammer, dass reiner Glaube allein nicht ausreicht. Sie müssen die Härte unter Eurer Haut prüfen, um sicherzustellen, dass Ihr über den unerschütterlichen Mut verfügt, der von einem wahren Paladin verlangt wird, bevor größere Gefahren Eure Heimat treffen.",al={"warum prüfung ablegen","duthorian rall motiv","tiza kriegshammer prüfung warum"}},f91e68e3={q="Warum müsst Ihr diese Prüfung ablegen und nicht hochrangige Paladine oder Wachen?",a="Diese Reise ist kein Verteidigungsauftrag, den Stadtwachen oder erfahrene Ritter für Euch erledigen können. Es ist ein persönliches Initiationsritus. Die Meister müssen sehen, wie Euer eigener Geist sich in Notzeiten behauptet, und Eure persönliche Fähigkeit testen, die Schwachen zu beschützen, an Eurem Glauben festzuhalten und angesichts des Terrors standhaft zu bleiben.",al={"warum ich foliant der ehre","warum spieler ehre senden","warum können wachen das nicht"}}},fp="17,264,24.434.0,20.366.0,41.255.0,35.201.0,27.195.0,50.234.0,52.205.0,44.197.0"}
P.entries["quest:1795"] = {n="Die Bindung",s="Die Bindung ist der krönende Ritus für Hexenmeister, die einen Teufelsjäger befehligen wollen. Unter der Aufsicht des rätselhaften Beschwörers Strahad Farsan oberhalb von Ratschet nutzt das Ritual den wiederhergestellten Foliant der Kabale, um ein aggressives dämonisches Raubtier aus dem Nether zu reißen und es durch eine Kampfprüfung zur Unterwerfung zu zwingen.",h="Die Bindung ist der krönende Ritus für Hexenmeister, die einen Teufelsjäger befehligen wollen.",kw={"brachland","teufelsjäger","ratschet","strahad farsan","beschwörung","die bindung","foliant der kabale","hexenmeister"},ang={["class:Warlock"]="Die Unterwerfung eines Teufelsjägers ist ein entscheidender Meilenstein für jeden Hexenmeister, da sie ihm ein spezialisiertes Anti-Magie-Raubtier an die Seite stellt, das imstande ist, Zauber zu verschlingen und feindliche Zauberer unschädlich zu machen.",["faction:Alliance"]="Hexenmeister der Allianz werden aus der Sicherheit von Sturmwind über das Meer in den rauen, neutralen Zufluchtsort Ratschet entsandt, um ihr gefährliches Beschwörungsritual unter Strahads wachsamen Augen zu vollenden.",["faction:Horde"]="Praktizierende der Horde reisen in das Herz des Brachlands, um ihre Herrschaft über den Nether zu beweisen, und treten auf neutralem Boden vor Strahad, um den Hund zu binden."},sec={{t="Der Kreis der Kabale",b="Auf den Klippen über dem Goblinhafen Ratschet führt Strahad Farsan einige der gefährlichsten dämonologischen Prüfungen auf Kalimdor durch. Nachdem ein Hexenmeister die verstreuten Fragmente und Reagenzien gesammelt hat, die zum Zusammensetzen des uralten Foliant der Kabale nötig sind, bereitet Strahad die Bindungsstätte vor. Er zeichnet eine innere Glyphe der Eindämmung, während seine loyalen Akolythen ihre Macht durch verzauberte Stäbe kanalisieren, um den äußeren Kreis zu vollenden. So wird sichergestellt, dass jegliche Schrecken, die hervortreten, von der darunterliegenden Siedlung isoliert bleiben."},{t="Unterwerfung des Jägers",b="Indem der Initiand die im Foliant der Kabale niedergeschriebenen Beschwörungsformeln anruft, öffnet er eine Brücke in den Wirbelnden Nether. Teufelsjäger sind unersättliche Dämonenhunde, die von Natur aus nach arkaner Macht hungern und sich an magischer Energie laben. Die beschworene Bestie lässt sich nicht einfach beschwichtigen oder sanft bezaubern; sie muss im Kampf gewaltsam bezwungen und gebrochen werden, bevor sie den Hexenmeister als ihren rechtmäßigen Meister anerkennt. Das Überleben dieses Aufeinandertreffens beweist die Bereitschaft eines Beschwörers, den Hund gegen feindliche Zauberwirker ins Feld zu führen."}},faq={{q="Was ist der Zweck dieses Rituals?",a="Das Ritual ermöglicht es einem Hexenmeister, einen Teufelsjäger zu beschwören und an seinen Willen zu binden. Indem der Hexenmeister aus dem vollendeten Foliant der Kabale innerhalb von Strahad Farsans Beschwörungskreis liest, lockt er das dämonische Raubtier aus dem Nether und besiegt es im Kampf, wodurch er sich die dauerhafte Knechtschaft des Dämons verdient.",al={"warum diese quest machen","ziel der teufelsjäger-quest","zweck der bindung"}},{q="Wer ist Strahad Farsan?",a="Strahad Farsan ist ein vollendeter menschlicher Hexenmeister, der von einem Turm oberhalb von Ratschet im Brachland aus agiert. Wegen seines immensen Wissens über finstere Beschwörungskünste schicken Lehrmeister sowohl der Allianz als auch der Horde insgeheim ihre vielversprechendsten Schüler zu ihm, um unter seiner Anleitung fortgeschrittene Bindungsriten zu erlernen.",al={"wer ist strahad","strahad farsan hintergrund","questgeber strahad"}},{q="Warum muss ein Hexenmeister den Dämon töten, anstatt ihn zu versklaven?",a="Ein Teufelsjäger ist ein aggressives, Magie verschlingendes Raubtier, das einzig absolute Dominanz respektiert. Das Ritual verlangt vom Anwender, den Dämon im physischen und magischen Kampf zu bezwingen, um seine Wildheit zu brechen und seinem Geist seine Autorität aufzuprägen, was sicherstellt, dass er künftigen Beschwörungen gehorcht.",al={"warum teufelsjäger töten","kann man teufelsjäger versklaven","kampf gegen teufelsjäger"}},{q="Können sowohl Hexenmeister der Horde als auch der Allianz dieses Ritual hier durchführen?",a="Ja. Obwohl sich die vorangegangenen Aufgaben zur Rekonstruktion des Foliant der Kabale je nach Fraktionszugehörigkeit unterscheiden, werden letztlich sowohl Hexenmeister der Allianz als auch der Horde zu Strahad Farsan oberhalb von Ratschet geschickt, um die abschließende Beschwörung durchzuführen.",al={"nur für die horde","nur für die allianz","wer bekommt diese quest"}},{q="Was geschieht, wenn der Teufelsjäger den Beschwörer besiegt?",a="Fällt der Beschwörer, wird der Dämon zurück in den Nether verbannt und das Ritual schlägt fehl. Strahad gestattet Hexenmeistern, die ihre Niederlage überleben, jedoch, ein neues Exemplar des Foliant der Kabale einzufordern und die Beschwörung erneut zu versuchen, sobald sie angemessen vorbereitet sind.",al={"was passiert beim tod","bindung fehlgeschlagen","ritual wiederholen möglich"}},{q="Was unterscheidet Teufelsjäger von anderen Dämonen?",a="Teufelsjäger sind dämonische Hunde, die jagen, indem sie magische Ausstrahlungen aufspüren. Anstatt sich rein auf rohe Gewalt oder Schattenzauber zu verlassen, glänzen sie darin, Zauberei zu wittern, aktive Verzauberungen zu verschlingen und feindliche Zauberwirker zu stören, was sie zu unschätzbaren Gefährten gegen rivalisierende Magiewirker macht.",al={"was macht ein teufelsjäger","teufelsjäger hintergrund","warum teufelsjäger"}}},fx={b1095368={q="Warum will Strahad Farsan, dass Ihr den Felhunter beschwört?",a="Strahad Farsan benutzt Euch nicht, um Besorgungen zu machen – er bildet Euch aus, um größere dämonische Magie zu beherrschen. Er glaubt, dass jeder Hexenmeister einen Felhunter unter seinem Befehl haben sollte, da die zerstörerischen Kräfte der Kreatur die Gefahr, eine zu binden, bei weitem überwiegen. Nachdem er Eure Sammlung der Materialien und das Tome of the Cabal geleitet hat, geht es ihm darum, Euer Potenzial zu testen und zu sehen, ob Ihr die Prüfung überleben könnt, um unter den furchterregendsten Praktizierenden der Ära zu stehen.",al={"warum will strahad das","strahad farsan motiv","warum felhunter für strahad beschwören"}},["44d888c5"]={q="Warum müsst Ihr dem Felhunter selbst gegenübertreten, anstatt dass Strahad das tut?",a="Ein beschworener Dämon kann nicht einfach in Eurem Namen besiegt werden. Die Unterwerfung eines Schergen aus dem Wirbelnden Nether erfordert den Beweis Eures persönlichen Willens und Eurer Dominanz über die Kreatur; wenn Strahad oder seine Akolythen ihn besiegen würden, würde kein Band der Knechtschaft zu Euch entstehen. Strahad und seine Assistenten kanalisieren die größeren Beschwörungskreise, um den Bruch einzudämmen, aber die wilde Kraft der Bestie im Kampf zu brechen, ist eine Prüfung, die nur der zukünftige Meister bestehen kann.",al={"warum kann strahad nicht kämpfen","warum muss ich den felhunter töten","warum muss ich alleine gegen den dämon kämpfen"}},["6bf7b15d"]={q="Was ist der beschworene Felhunter und woher kommt er?",a="Ihr steht einem bösartigen, räuberischen Dämon gegenüber, der mithilfe der Beschwörungen innerhalb des Tome of the Cabal direkt aus dem Wirbelnden Nether gezogen wurde. Felhunter sind monströse Bestien, die vom Geschmack arkaner und magischer Energien angezogen werden, die sie eifrig verfolgen, absaugen und stören. Da sie von Natur aus gefräßige Unholde sind, wird die Kreatur, die in den Beschwörungskreis gezogen wird, Euch sofort nach ihrer Materialisierung angreifen und verlangen, dass Ihr sie im Kampf überwältigt, bevor ihr Geist an Euren Dienst gebunden werden kann.",al={"was ist der beschworene felhunter","gegen was kämpfe ich","felhunter lore"}}},fp="11,301,18.506.0,22.507.0,35.285.0,22.302.0,66.283.0,62.227.0,51.257.0,54.293.0"}
P.entries["quest:1796"] = {n="Komponenten für die verzauberte Goldblutrobe",s="Menara Leerbringer beauftragt aufstrebende Hexenmeister im Brachland damit, ein Paar Roben von Arcana als Grundgewand für ein mächtiges magisches Kleidungsstück zu beschaffen. Dies markiert den ersten Schritt bei der Erschaffung der Verzauberten Goldblutrobe und schafft das grundlegende Gefäß, das notwendig ist, um dunklen Verzauberungen standzuhalten.",h="Menara Leerbringer beauftragt aufstrebende Hexenmeister im Brachland damit, ein Paar Roben von Arcana als...",kw={"brachland","goldblutrobe","verzauberte goldblutrobe","menara leerbringer","roben von arcana","schneiderei","hexenmeister quest"},ang={["class:Warlock"]="Das Erschaffen der Verzauberten Goldblutrobe ist ein wichtiges Initiationsritual für Hexenmeister und lehrt, dass mächtige Artefakte auf widerstandsfähigen, sorgfältig vorbereiteten Fundamenten geschmiedet werden müssen.",["profession:Tailoring"]="Die Quest stützt sich auf das seltene Fachwissen eines geschickten Schneiders, der das Muster für Roben von Arcana gemeistert hat und dabei Spinnenseide sowie Ballen um Ballen feiner Seide verwendet.",["race:Orc"]="Für Orc-Hexenmeister, die im Schatten der dämonischen Vergangenheit ihres Volkes wirken, stellt das Beschaffen von Materialien für unauffällige Roben eine leisere Beherrschung der Teufelsenergie abseits neugieriger Blicke dar.",["race:Undead"]="Verlassene Praktizierende reisen oft weit in das sonnengebleichte Brachland, um Menaras Techniken zu erlernen, in dem Bestreben, ihre gebrechlichen sterblichen Hüllen gegen ihre eigenen unberechenbaren Künste zu wappnen."},sec={{t="Ein Gefäß von Arcana",b="Bevor dunkle Magie an Stoff gebunden werden kann, muss das Gewand selbst würdig sein, eine solche Macht zu tragen. Menara Leerbringer weist Hexenmeister, die nach größerer Macht streben, an, ein Paar Roben von Arcana zu beschaffen. Wie Menara erklärt, hängt das Fassungsvermögen jedes magischen Relikts von der Kunstfertigkeit, Seltenheit und Mühe ab, die in seine Grundmaterialien eingewoben wurden. Gewöhnliche Lumpen würden unter der Belastung tiefer Verzauberungen zerfallen, was ein fein genähtes, empfängliches Gewand unverzichtbar macht."},{t="Handwerk und Ehrgeiz",b="Obwohl Menara besondere Bewunderung für jene Praktizierenden hegt, die fähig sind, das Gewand mit ihren eigenen Händen zu weben, schätzt sie rücksichtslosen Ehrgeiz höher als Stolz. Ob ein Hexenmeister die Seide selbst näht, einen begabten Handwerker beauftragt oder auf dem Markt feilscht, das Ergebnis bleibt dasselbe: eine vollendete Robe, bereit, in ein spezialisiertes Werkzeug der Teufelsmeisterschaft verwandelt zu werden."}},faq={{q="Warum benötigt Menara Leerbringer ausgerechnet Roben von Arcana?",a="Hochgradige Verzauberungen erfordern ein Gewand, das mit außergewöhnlichem Geschick und seltenen Materialien gewoben wurde. Menara nutzt die Roben von Arcana als reine, empfängliche Grundlage, die in der Lage ist, die flüchtigen magischen Kräfte zu halten, die bald an sie gebunden werden.",al={"warum roben von arcana","warum diese robe","zweck der robe"}},{q="Wo befindet sich Menara Leerbringer?",a="Menara Leerbringer hält sich in der Goblin-Hafenstadt Ratschet im Brachland auf, wo sie Hexenmeister unterweist, die ihr Handwerk verfeinern und spezialisierte Ausrüstung schmieden wollen.",al={"menara leerbringer standort","wo ist menara","menara leerbringer wo"}},{q="Muss ich die Roben von Arcana selbst schneidern?",a="Nein. Obwohl Menara die Hingabe respektiert, das Gewand persönlich herzustellen, akzeptiert sie auch Roben, die durch Handel erworben oder von anderen Handwerkern gekauft wurden. Für einen Hexenmeister ist die Beschaffung des Gefäßes auf jedem praktischen Weg annehmbar.",al={"brauche ich schneiderei","kann ich die roben kaufen","schneiderei erforderlich"}},{q="Woher stammt das Muster für Roben von Arcana?",a="Das Muster ist eine seltene Beute, die hauptsächlich von Kultisten und dunklen Zauberwirkern erbeutet werden kann, wie etwa von den Leerrufern des Dunklen Strangs am Turm von Althalaxx an der Dunkelküste oder von Verzauberern der Defias im Dämmerwald.",al={"muster roben von arcana","wie muster bekommen","schneiderrezept fundort"}},{q="Was geschieht mit den Roben von Arcana nach der Abgabe?",a="Menara nimmt die Roben in ihren Besitz, damit sie als Rohmaterial für das nachfolgende Erfüllungsritual dienen. Tragt Ihr sie beim Abschluss der Aufgabe am Leib, streift sie diese sofort ab, sodass Ihr ohne Brustteil dasteht, bis spätere Schritte abgeschlossen sind.",al={"verliere ich die roben","robe weg","was passiert mit robe"}},{q="Was ist die Verzauberte Goldblutrobe?",a="Sie ist ein spezialisiertes Gewand, maßgeschneidert für Hexenmeister mittleren Ranges. Gebunden an dunkle Komponenten und schützende Verzauberungen, stärkt sie die Widerstandskraft sowie die Reserven dunkler Energie eines Zauberwirkers.",al={"was ist goldblutrobe","goldblutrobe lore","verzauberte goldblutrobe"}}},fx={["44990969"]={q="Warum will Menara Leerbringer, dass dies getan wird?",a="Menara Leerbringer dient als Mentorin, die ehrgeizige Hexenmeister zu größerer Meisterschaft der dunklen Künste führt. Sie sucht keine Roben für ihre eigene Garderobe; stattdessen testet sie Eure Hingabe und Euren Einfallsreichtum, während sie Euch beibringt, mächtige Hexenmeistergewänder zu schmieden. Vielversprechende Praktizierende dazu anzuleiten, fel-Kräfte durch maßgeschneiderte Fokussierungen zu kanalisieren, stärkt die Reihen ihres schattenhaften Handwerks.",al={"warum hilft mir menara","menara leerbringer motiv","warum die roben machen"}}},fp="43,292,18.443.0,18.366.0,61.234.0,35.159.0,47.225.0,53.191.0,58.255.0,37.182.0"}
P.entries["quest:1798"] = {n="Die Suche nach Strahad",s="Die Suche nach Strahad ist eine Hexenmeisterquest der Allianz, die Ausüber der dunklen Künste aus Sturmwind über das große Meer in das Brachland schickt. Dort, unter den wachsamen Blicken des Goblinhafens Ratschet, ersuchen sie das Fachwissen von Strahad Farsan, um die Beschwörung von Teufelsjägern zu erlernen. Dies markiert den Übergang eines Hexenmeisters in die höheren, gefährlicheren Ränge dämonischer Unterjochung.",h="Die Suche nach Strahad ist eine Hexenmeisterquest der Allianz, die Ausüber der dunklen Künste aus Sturmwind...",kw={"teufelsjäger","gakin der dunkelbinder","ratschet","die suche nach strahad","sturmwind","strahad farsan","brachland","hexenmeister"},ang={["class:Warlock"]="Diese Quest markiert einen wichtigen Meilenstein im Werdegang eines Hexenmeisters: den Aufstieg von einfachen Dämonen und Sukkuben zum gerissenen, magiezehrenden Teufelsjäger.",["faction:Alliance"]="Für Allianz-Beschwörer erfordert die Reise das Bestehen der langen Überfahrt über das große Meer direkt in das zerklüftete, von der Horde beherrschte Kernland von Kalimdor."},sec={{t="Ein Ruf über das Meer",b="In der unterirdischen Enklave des Gasthauses Zum Geschlachteten Lamm in Sturmwind überwacht Gakin der Dunkelbinder die Entwicklung aufstrebender Hexenmeister. Doch die Beherrschung des räuberischen Teufelsjägers erfordert Materialien, Relikte und Riten, die über das hinausgehen, was der bescheidene Keller im Magierviertel bieten kann. Da Gakin erkennt, dass sein Schüler an Macht gewonnen hat, leitet er ihn fort von der Sicherheit des Königreichs in Richtung Kalimdor und leitet damit eine Reise ein, welche die geheimen Zirkel menschlicher Dämonologie über Kontinente hinweg verbindet."},{t="Der Einsiedler von Ratschet",b="Das Ziel sind die trockenen Hügel mit Blick auf den Goblinhafen Ratschet. Dort weilt Strahad Farsan, ein menschlicher Hexenmeister und ein Gefährte Gakins innerhalb ihrer geheimen Kabale. Das Agieren aus neutralem Territorium gewährt Strahad relative Freiheit vor den neugierigen Blicken von Allianzmagistraten, Kircheninquisitoren und Hordeposten gleichermaßen. Seine Präsenz im Brachland dient als Ankerpunkt für ehrgeizige Beschwörer, die bereit sind, die Kontrolle über manaze Coupon Dämonen an sich zu reißen."}},faq={{q="Wer schickt Euch aus, um Strahad zu finden?",a="Gakin der Dunkelbinder, der Hexenmeisterlehrer, der sich in der Krypta unter dem Geschlachteten Lamm im Magierviertel von Sturmwind aufhält, schickt Euch auf diese Reise, sobald Ihr bereit seid zu lernen, wie man einen Teufelsjäger beschwört.",al={"wer gibt die suche nach strahad","questgeber","gakin"}},{q="Wo befindet sich Strahad Farsan?",a="Strahad Farsan hat sich im Brachland niedergelassen und weilt auf den Anhöhen mit Blick auf die Goblin-Hafenstadt Ratschet.",al={"strahad aufenthaltsort","wo ist strahad","strahad finden"}},{q="Warum muss ein Hexenmeister der Allianz den ganzen Weg bis ins Brachland reisen?",a="Gakin fehlt es in Sturmwind an den spezialisierten Reagenzien und dem Wissen, die zur Durchführung der Beschwörungsriten des Teufelsjägers erforderlich sind. Strahad Farsan besitzt das notwendige Wissen und die Materialien, nachdem er sich im neutralen Territorium von Ratschet fernab lokaler Beobachtung niedergelassen hat.",al={"warum ins brachland","warum kalimdor","warum ratschet"}},{q="Zur Freischaltung welcher Fähigkeit führt diese Quest?",a="Diese Quest ist der einleitende Schritt einer Reihe, die zum Folianten der Kabale und dem Bindungsritual führt, das erforderlich ist, um einen Teufelsjäger als Gefährten zu beschwören.",al={"für welchen begleiter ist das","was erhalte ich","teufelsjäger quest"}},{q="Ist Strahad Farsan der Horde gegenüber feindlich gesinnt?",a="Nein. Strahad residiert in neutralem Goblin-Gebiet und dient sowohl Hexenmeistern der Allianz als auch der Horde als Lehrmeister, die die Geheimnisse der Teufelsjägerbeschwörung ergründen wollen, wobei er Verbindungen zu verschiedenen Kabalen pflegt.",al={"ist strahad nur für die allianz","horde strahad"}},{q="Was geschieht, nachdem Ihr mit Strahad gesprochen habt?",a="Nach Eurer Begrüßung beauftragt Strahad Euch damit, die notwendigen Komponenten für das Bindungsritual zu sammeln, womit die mehrteilige Questreihe um den Folianten der Kabale beginnt.",al={"folgequest","was nach der suche nach strahad kommt","foliant der kabale"}}},fx={["034d02a4"]={q="Warum möchte Gakin der Dunkelbinder, dass Ihr Strahad aufsucht?",a="Gakin urteilt, dass Eure Macht weit genug gewachsen ist, um einen Teufelsjäger zu befehligen, doch ihm fehlen die arkanen Reagenzien und rituellen Komponenten, die erforderlich sind, um Euch unter Sturmwind auszubilden. Anstatt Eure Ausbildung ins Stocken geraten zu lassen, schickt er Euch zu Strahad Farsan, einem vertrauenswürdigen Kollegen aus ihrem inneren Zirkel, der über das nötige Wissen und die Materialien auf der anderen Seite des Meeres verfügt.",al={"warum zu strahad schicken","gakin dunkelbinder motiv","warum gakin euch wegschickt"}}},fp="15,369,24.480.0,21.455.0,30.202.0,32.115.0,71.262.0,47.147.0,39.195.0,40.170.0"}
P.entries["quest:18"] = {n="Bruderschaft der Diebe",s="Bruderschaft der Diebe ist eine frühe Aufgabe, die von Deputy Willem vor der Abtei von Nordhain vergeben wird. Sie schickt junge Rekruten der Allianz über den östlichen Fluss, um eine vordringende Räuberbande zurückzuschlagen, die als Bruderschaft der Defias bekannt ist. Das Sammeln der charakteristischen roten Rupfenbandanas dieser Diebe liefert den Behörden von Sturmwind den ersten handfesten Beweis für die organisierte Präsenz dieser Gruppe im Tal.",h="Bruderschaft der Diebe ist eine frühe Aufgabe, die von Deputy Willem vor der Abtei von Nordhain vergeben wird.",kw={"bandanas","bruderschaft der diebe","defias","deputy willem","elwynn","nordhain","armee von sturmwind"},ang={["class:Rogue"]="Die Begegnung mit den Defias gewährt angehenden Schurken einen ersten Einblick darin, wie organisierte kriminelle Netzwerke in den Schatten des menschlichen Kernlandes operieren.",["faction:Alliance"]="Die Behörden von Sturmwind verlassen sich auf neu eingetroffene Rekruten der Allianz, um in Nordhain für Ordnung zu sorgen, während das reguläre Militär des Königreichs überlastet ist.",["race:Human"]="Für Menschen, die ihre Ausbildung in Nordhain beginnen, ist die Konfrontation mit den Defias die erste ernüchternde Mahnung, dass die Sicherheit des Königreichs Sturmwind von innen heraus ins Wanken gerät."},sec={{t="Banditen im Tal",b="Das Nordhaintal gilt seit langem als sichere Zuflucht im Wald von Elwynn, geschützt von den Wachen aus Sturmwind und der Ausbildung neuer Rekruten sowie Kleriker des Heiligen Lichts gewidmet. In jüngster Zeit hat die Disziplin an den Außengrenzen jedoch gelitten. Vagabunden und Diebe haben den östlichen Fluss überquert, lauern nahe den Wäldern und errichten kleine Lager direkt vor der Nase der Abtei. Deputy Willem, der mit der Aufrechterhaltung der örtlichen Ordnung beauftragt ist, erkennt, dass die örtliche Wache ohne die Hilfe von Freiwilligen nicht genügend Kräfte aufbringen kann, um jeden Winkel des Tals zu sichern."},{t="Das purpurne Siegel",b="Was diese Gesetzlosen von gewöhnlichen Wegelagerern unterscheidet, sind ihre Koordination und ihre einheitliche Kleidung. Sie nennen sich die Bruderschaft der Defias und kennzeichnen ihre Zugehörigkeit mit markanten roten Rupfenbandanas, die sie vor das Gesicht gebunden tragen. Indem Deputy Willem den Rekruten aufträgt, diese Banditen zu jagen und ihre Masken zu beschaffen, will er ihren kühnen Vorstoß eindämmen und gleichzeitig erfassen, wie tief die Defias bereits in das Herzland des Königreichs eingedrungen sind."}},faq={{q="Wer ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist eine organisierte Vereinigung von Banditen und Gesetzlosen, die derzeit im gesamten Wald von Elwynn und in Westfall operiert. Während die Behörden in Nordhain sie anfangs nur für dreiste Diebe halten, tragen sie einheitliche rote Rupfenmasken und folgen einer koordinierten Führung.",al={"wer sind die defias","was ist bruderschaft der defias","defias lore"}},{q="Warum bittet Deputy Willem Rekruten um Hilfe, statt die Armee von Sturmwind einzusetzen?",a="Die Armee von Sturmwind und die örtlichen Stadtwachen sind im gesamten Königreich überdehnt. Da in den Nachbarregionen Unruhen schwelen und die Führung in Sturmwind angespannt ist, müssen sich die örtlichen Deputies auf eifrige Freiwillige und unerfahrene Rekruten verlassen, um die vordringenden Banditen zu vertreiben.",al={"warum willem hilfe braucht","wo sind die wachen von sturmwind","warum keine armee"}},{q="Woher kommen diese Diebe?",a="In Nordhain haben sich die Diebe jenseits des Flusses östlich der Abtei gesammelt, wo sie an den Rändern der örtlichen Gehöfte und in Lagern nahe dem Weinberg herumlungern.",al={"wo sind die banditen","defias aufenthaltsort nordhain"}},{q="Warum tragen die Diebe rote Rupfenbandanas?",a="Das rote Rupfenbandana dient als einheitliches Erkennungszeichen der Bruderschaft der Defias; es verhüllt ihre Identität und signalisiert zugleich ihre Treue gegenüber anderen Gesetzlosen, die in den Gebieten der Menschen operieren.",al={"warum rote bandanas","bedeutung roter masken","roter rupfen"}},{q="Was geschieht nach dem Abschluss dieser Quest?",a="Deputy Willem und die Einheimischen erkennen schnell, dass die Bedrohung durch die Banditen noch tiefer nach Nordhain hineinreicht. Dies veranlasst die Rekruten dazu, Milly Geltmark bei ihrer ruinierten Ernte zu helfen und einen bestimmten Rädelsführer namens Garrick Padfoot aufzuspüren.",al={"wie geht es weiter","nach bruderschaft der diebe"}},{q="Weiß Deputy Willem, wer die Defias anführt?",a="Zu diesem Zeitpunkt ist Willem das volle Ausmaß der Organisation noch nicht bewusst. Er weiß nur, dass sie sich Bruderschaft der Defias nennen, und ahnt, dass ihre Anwesenheit nahe der Abtei nichts Gutes für Sturmwind verheißt.",al={"kennt willem vancleef","wer führt defias in nordhain an"}}},fx={e491bbee={q="Warum will Deputy Willem, dass Ihr gegen die Diebe kämpft?",a="Deputy Willem ist damit beauftragt, die Abtei von Nordhain und das umliegende Tal zu schützen. Eine dreiste Verbrecherbande namens The Defias Brotherhood hat sich in die östlichen Wälder jenseits des Flusses geschlichen und bedroht die Sicherheit der Abtei und der örtlichen Arbeiter. Willem will, dass sie sofort unterdrückt werden, bevor sie einen stärkeren Stützpunkt gewinnen oder einen direkten Angriff auf das Tal starten.",al={"warum will willem das","willem motiv","warum hier die defias stoppen"}},["4db9a478"]={q="Wer sind die Diebe jenseits des Flusses?",a="Ihr werdet gegen die Defias-Schläger ausgesandt, Gesetzlose der The Defias Brotherhood, die ihr Lager in den Wäldern jenseits des Baches östlich der Abtei von Nordhain aufgeschlagen haben. Sie haben sich in der Nähe der Weinberge und der umliegenden Felder versammelt, spähen das Tal aus und belästigen die Einheimischen, während sie eine bewaffnete Präsenz direkt unter der Nase von Sturmwind aufbauen.",al={"wer sind die diebe","gegen wen kämpfe ich","defias in nordhain"}}},fp="22,393,21.543.0,17.440.0,31.267.0,82.264.0,36.162.0,44.197.0,41.217.0,45.203.0"}
P.entries["quest:180"] = {n="GESUCHT: Leutnant Fangor",s="GESUCHT: Leutnant Fangor ist ein lokales Kopfgeld, das in Seenhain von Magistrat Solomon ausgesetzt wurde. Es ruft Abenteurer dazu auf, Leutnant Fangor zur Strecke zu bringen, den bösartigen Häuptling der Schattenfellgnolle, die das Rotkammgebirge bedrängen. Seine Beseitigung versetzt dem abtrünnigen Hexenmeister Morganth, dem die Gnolle dienen, einen direkten Schlag.",h="GESUCHT: Leutnant Fangor ist ein lokales Kopfgeld, das in Seenhain von Magistrat Solomon ausgesetzt wurde.",kw={"fangor","gnoll","seenhain","leutnant fangor","magistrat solomon","morganth","rotkammgebirge","schattenfell"},ang={["faction:Alliance"]="Seenhain dient als entscheidendes Bollwerk für die Allianz im Rotkammgebirge; Fangor auszuschalten verhindert, dass die Siedlung in völlige Isolation gerät.",["race:Human"]="Menschliche Verteidiger spüren Sturmwinds Vernachlässigung im Rotkammgebirge am eigenen Leib, was ein persönliches Eingreifen gegen Gnollhäuptlinge zu einer Frage des reinen Überlebens ihrer Heimat macht."},sec={{t="Eine Stadt unter Belagerung",b="Seenhain befindet sich in einer verzweifelten Lage. Da Sturmwinds Armee überdehnt ist und König Varian Wrynn auf mysteriöse Weise verschwunden bleibt, hat Hochlord Bolvar Fordragon Grenzsiedlungen wie das Rotkammgebirge sich selbst überlassen. Der Schattenfellklan ist zusehends dreister geworden, überfällt Handelsrouten, brennt Gehöfte nieder und rückt direkt an die Grenzen der Stadt vor. Magistrat Solomon verlässt sich auf angeschlagene Kopfgelder, um Söldnerklingen anzulocken, wo königliche Soldaten nicht marschieren."},{t="Morganths Leutnant",b="Leutnant Fangor ist nicht bloß eine marodierende Bestie; er fungiert als Vollstrecker für Morganth, einen abtrünnigen dunklen Zauberer, der in den Hügeln des Rotkammgebirges lauert. Unter Fangors Kommando koordinieren die Schattenfellgnolle ihre Angriffe, anstatt als unorganisierte Aasfresser zu kämpfen, und drohen damit, Seenhain vollständig vom Wald von Elwynn abzuschneiden. Fangors Tatze abzutrennen liefert Magistrat Solomon den Beweis dafür, dass Morganths brutale Vorhut gebrochen wurde."}},faq={{q="Wer ist Leutnant Fangor?",a="Leutnant Fangor ist ein mächtiger Anführer innerhalb des Schattenfellgnollklans, der im Rotkammgebirge haust. Er koordiniert die Raubzüge der Gnolle und setzt den Willen von Morganth durch, einem dunklen Zauberer, der Seenhain bedroht.",al={"leutnant fangor","wer ist fangor","fangor geschichte"}},{q="Wer hat das Kopfgeld auf Leutnant Fangor ausgesetzt?",a="Das Kopfgeld wurde von Magistrat Solomon ausgestellt, dem Stadtoberhaupt von Seenhain, der versucht, die Grenzen des Rotkammgebirges gegen feindselige Gnolle und dunkle Zauberwirker zu sichern.",al={"wer hat das kopfgeld ausgesetzt","wer will fangor tot sehen","magistrat solomon fangor"}},{q="Warum schickt Sturmwind keine Soldaten, um sich um die Gnolle zu kümmern?",a="Sturmwind ist durch das plötzliche Verschwinden von König Varian Wrynn und interne Unruhen gelähmt. Hochlord Bolvar Fordragon und das Haus der Adligen haben sich geweigert, reguläre Armeeabteilungen in entlegene Städte wie Seenhain zu entsenden, was Magistrat Solomon dazu zwingt, abenteuerlustige Söldner anzuheuern.",al={"warum keine wache aus sturmwind","wo sind die soldaten aus sturmwind","warum hilft die armee nicht"}},{q="Welcher Beweis wird benötigt, um das Kopfgeld einzufordern?",a="Magistrat Solomon verlangt die abgetrennte Tatze von Leutnant Fangor als physischen Beweis dafür, dass der Kriegsherr der Schattenfelle erschlagen wurde.",al={"fangor beweis","fangors tatze","welcher gegenstand zum abgeben"}},{q="Wer ist Morganth und warum folgt Fangor ihm?",a="Morganth ist ein abtrünniger menschlicher Zauberwirker, der von einem Turm im Rotkammgebirge aus dunkle Magie praktiziert. Er hat die Schattenfellgnolle seinem Willen unterworfen und nutzt Leutnant Fangor als Vollstrecker, um das Umland zu terrorisieren.",al={"wer ist morganth","warum folgen die gnolle morganth","fangor morganth"}},{q="Was sind die Schattenfellgnolle?",a="Der Schattenfellklan ist ein wilder Stamm von Gnollen, der die schroffen Felsen und Wälder des Rotkammgebirges bewohnt. Bekannt für ihre Aggressivität und brutale Hinterhaltstaktiken, plagen sie die Siedler von Seenhain seit Jahren.",al={"schattenfellklan","rotkamm gnolle","schattenfell hintergrund"}}},fp="26,333,18.465.0,21.441.0,26.209.0,45.174.0,57.282.0,43.127.0,48.222.0,31.219.0"}
P.entries["quest:1801"] = {n="Foliant der Kabale",s="Diese Quest schickt Hexenmeister der Horde auf eine Reise von Strahad Farsans Lager im Brachland nach Unterstadt, um nach uraltem dämonologischem Wissen zu suchen. Um einen Teufelsjäger zu beschwören und zu binden, muss ein Initiant den verlorenen Folianten der Kabale aufspüren, beginnend bei einem Kartographen namens Jorah Annison. Dies stellt einen entscheidenden Schritt bei der Beherrschung höherer dämonischer Beschwörungen dar.",h="Diese Quest schickt Hexenmeister der Horde auf eine Reise von Strahad Farsans Lager im Brachland nach...",kw={"brachland","teufelsjäger","jorah annison","ratschet","strahad farsan","foliant der kabale","unterstadt","hexenmeisterquest"},ang={["class:Warlock"]="Dieser Übergangsritus ist für Hexenmeister der Horde obligatorisch, die einen Teufelsjäger zähmen wollen, und erfordert Reisen zwischen Kalimdor und den Östlichen Königreichen, um vergessene Ritualkomponenten zusammenzutragen.",["faction:Horde"]="Die Quest veranschaulicht die Zusammenarbeit zwischen den dunklen Zauberwirkern Kalimdors und den okkulten Gelehrten der Verlassenen, die unter den Ruinen von Lordaeron hausen."},sec={{t="Eine Jagd nach uraltem Wissen",b="Die Beschwörung eines Teufelsjägers ist kein unbedeutender Trick der Teufelsmagie; die raubtierhaften Bestien verschlingen magische Energien und widerstehen gewöhnlichen Beschwörungskreisen. Strahad Farsan erklärt, dass ein Initiant die Hilfe spezieller Kreise und eines uralten Zauberbuchs namens Foliant der Kabale benötigt, um einen herbeizurufen. Verfasst vom ersten Orden von Hexenmeistern, dem es je gelang, einen Teufelsjäger ohne fremde Hilfe zu binden, enthält das Buch die genauen Riten und Siegel, die erforderlich sind, um einen derart gefährlichen Dämon zu versklaven."},{t="Der Kartograph von Unterstadt",b="Da Exemplare des Folianten der Kabale den Hexenmeistern in Kalimdor schon lange verloren gegangen sind, schickt Strahad seinen Schüler über das Meer zu Jorah Annison in Unterstadt. Obwohl er nominell als königlicher Kartograph angestellt ist, um Lordaeron zu kartieren, besitzt Annison ein außergewöhnlich tiefes Wissen über uralte und obskure Texte. Wie Annison selbst gesteht, verabscheut er das einfache Handwerk des Kartenzeichnens und giert weitaus mehr nach seltenen Geschichtswerken, okkulten Erzählungen und Abhandlungen über dunkle Magie."}},faq={{q="Was ist der Foliant der Kabale?",a="Der Foliant der Kabale ist ein seltenes okkultes Zauberbuch, verfasst von den ersten Hexenmeistern, die erfolgreich einen Teufelsjäger ohne fremde Hilfe beschworen und gebunden haben. Er enthält die präzisen Anweisungen, Schutzbannzauber und Riten, die nötig sind, um eine dieser magiezehrenden Bestien sicher nach Azeroth zu bringen.",al={"foliant der kabale lore","was ist dieses buch","foliant der kabale"}},{q="Warum schickt Strahad Farsan Euch nach Unterstadt?",a="Strahad und seinen Akolythen im Brachland fehlt ein Exemplar des Folianten der Kabale. Er weiß, dass Jorah Annison, ein Kartograph in Unterstadt, ein erfahrener Gelehrter für seltene und uralte Bücher ist, der wissen könnte, wo man die verlorenen Seiten oder Bände wiederbeschaffen kann.",al={"warum nach unterstadt","strahad farsan unterstadt","warum jorah aufsuchen"}},{q="Wer ist Jorah Annison?",a="Jorah Annison ist ein Gelehrter der Verlassenen, der in Unterstadt arbeitet. Obwohl sein offizielles Handwerk die Kartographie und das Zeichnen von Karten ist, liegt seine wahre Leidenschaft in obskuren Texten, nekromantischen Abhandlungen und alter Literatur.",al={"wer ist jorah","jorah annison lore"}},{q="Warum wird ein spezielles Buch benötigt, um einen Teufelsjäger zu beschwören?",a="Teufelsjäger ernähren sich natürlicherweise von arkanen und magischen Energien, was es schwierig und gefährlich macht, sie durch gewöhnliche Dämonenkreise zu leiten. Der Foliant der Kabale beschreibt die speziellen Schutzmaßnahmen, die erforderlich sind, um sie zu binden, bevor sie den Beschwörer verschlingen.",al={"warum teufelsjäger buch braucht","warum teufelsjäger schwer zu beschwören ist"}}},fx={["9f4798be"]={q="Warum will Strahad Farsan, dass dies getan wird?",a="Strahad Farsan überwacht Euren Fortschritt als ehrgeiziger Hexenmeister, der würdig ist, größere dämonische Macht auszuüben. Das Beschwören und Unterwerfen eines Felhunters ist ein gefährlicher Initiationsritus, der testet, ob ein Praktizierender eine Kreatur meistern kann, die darauf ausgelegt ist, sich von roher magischer Essenz zu ernähren. Strahad ist bereit, seine Akolythen und Magiekreise für das Bindungsritual zur Verfügung zu stellen, aber Ihr müsst zuerst das alte Wissen beschaffen, das erforderlich ist, um die Beschwörung überhaupt möglich zu machen.",al={"strahad farsan motiv","warum hilft strahad","strahad grund"}},["5aabed1a"]={q="Warum schickt Strahad Farsan Euch, anstatt selbst zu gehen?",a="Die Prüfung ist ganz allein an Euch zu beweisen. Ein Hexenmeister muss Einfallsreichtum, Widerstandsfähigkeit und persönliche Herrschaft über die dunklen Künste demonstrieren, um eine Bestie zu binden, die so gefährlich ist wie ein Felhunter. Strahad und seine Akolythen müssen außerdem am Beschwörungskreis über Ratschet bleiben, um die komplexen Schutzzauber und Rituale vorzubereiten, die benötigt werden, wenn Ihr mit dem geborgenen Text zurückkehrt.",al={"warum mich senden","warum geht strahad nicht","warum muss ich in die unterstadt"}}},fp="17,352,28.467.0,29.487.0,30.273.0,50.237.0,21.209.0,51.254.0"}
P.entries["quest:1802"] = {n="Foliant der Kabale",s="Diese Quest beauftragt einen Hexenmeister der Allianz damit, die verstreuten, beschädigten Hälften eines einzigartigen Grimoires namens Foliant der Kabale aufzuspüren. Die fehlenden Seiten aus fernen Ländern zu bergen, ist unerlässlich, um die dunklen Riten zu entschlüsseln, die für die Bindung eines Teufelsjägers erforderlich sind.",h="Diese Quest beauftragt einen Hexenmeister der Allianz damit, die verstreuten, beschädigten Hälften eines...",kw={"der azurschacht","teufelsjäger","eisenschmiede","krom starkarm","schimmliger foliant","spalthufhöhle","strahad farsan","zerlumptes manuskript","foliant der kabale"},ang={["class:Warlock"]="Das Bergen der zerrissenen Hälften dieses Grimoires stellt einen Übergangsritus dar, der die grundlegenden Beschwörungsrituale freischaltet, um einen Teufelsjäger aus dem Nether zu ziehen und ihn zu versklaven.",["faction:Alliance"]="Praktizierende der Allianz verlassen sich auf Kontakte in Eisenschmiede wie Krom Starkarm, um seltene dämonische Relikte über Kontinente hinweg aufzuspüren, ohne den offenen Verdacht von Kirche oder Krone zu erwecken."},sec={{t="Ein geteiltes Grimoire",b="Es wurde nur ein einziges Exemplar des Folianten der Kabale jemals niedergeschrieben, und seine gewaltsame Geschichte sorgte dafür, dass er nicht unversehrt blieb. Zerrissen und geschändet wurden seine Überreste in völlig verschiedene Ecken der Welt verstreut. Ein Teil, ein zerlumptes Manuskript, das direkt aus dem Einband gerissen wurde, fand irgendwie seinen Weg über das Meer in die schroffen Schluchten von Kalimdor und fiel in die Hände der Zentaurenclans. Der verbleibende Teil war für den Seetransport von den Küsten Lordaerons hinab nach Khaz Modan bestimmt, doch das Schiff sank, bevor es seinen Hafen erreichte."},{t="Über Meer und Schluchten",b="Das Zusammensetzen des Grimoires erfordert das Überleben zweier tückischer Gefahren. Die im Meer verlorenen Seiten wurden vor der Küste von Hillsbrad westlich von Süderstade an Land gespült, wo geborgenes Treibgut und durchnässte Relikte in die Hände von Küstenmurlocs nahe dem Azurschacht fielen. Derweil erfordert die Bergung der dürren Hälfte das Eindringen in die Spalthufhöhle in Tausend Nadeln, um tief in den Höhlen der Zentauren das Manuskript aus einer uralten Truhe zurückzuholen. Erst wenn diese ungleichen Hälften vereint sind, kann Krom Starkarm den verschollenen Text untersuchen, bevor er zu Strahad Farsan zurückkehrt."}},faq={{q="Was ist der Foliant der Kabale?",a="Es ist ein seltenes, einzigartiges dämonisches Grimoire, das esoterisches Wissen enthält, welches für Hexenmeister unerlässlich ist. Sein Inhalt birgt die komplexen Beschwörungen und Bindungsrituale, die erforderlich sind, um einen Teufelsjäger aus dem Wirbelnden Nether zu rufen und zu unterwerfen.",al={"foliant der kabale lore","was ist dieses buch","foliant der kabale"}},{q="Wer ist Krom Starkarm und warum will er den Folianten?",a="Krom Starkarm ist ein Zwerg aus Eisenschmiede, der sich dem Studium seltener und vergessener Texte widmet. Im Austausch dafür, dass er Hexenmeistern der Allianz verrät, wo die zerrissenen Teile des Folianten gelandet sind, bittet er lediglich um die Gelegenheit, den Inhalt selbst aus erster Hand zu studieren, sobald sie geborgen wurden.",al={"wer ist krom starkarm","warum will krom das buch","krom starkarm eisenschmiede"}},{q="Wo sind die beiden Teile des Buches gelandet?",a="Der Schimmlige Foliant wurde an der Küste von Hillsbrad westlich von Süderstade nahe dem Azurschacht an Land gespült und von Küstenmurlocs geplündert. Das Zerlumpte Manuskript landete in Kalimdor in der Spalthufhöhle, verstaut in einer ramponierten Truhe tief in einer Zentaurenhöhle in Tausend Nadeln.",al={"wo sind die foliantenteile","buch fundorte","zerlumptes manuskript fundort"}},{q="Warum wurde der Foliant überhaupt zerrissen?",a="Nur ein einziges Exemplar des Folianten der Kabale wurde jemals niedergeschrieben. Zu irgendeinem Zeitpunkt in seiner finsteren Vergangenheit wurde er absichtlich geschändet; ein großer Teil wurde sauber aus dem Einband gerissen und nach Kalimdor geschafft, während der Rest während einer verhängnisvollen Überfahrt nach Hafen von Menethil auf See verloren ging.",al={"warum wurde das buch zerrissen","wer hat den folianten geschändet"}},{q="Wer ist Strahad Farsan und was hat er mit dieser Quest zu tun?",a="Strahad Farsan ist ein erfahrener Hexenmeister, der nahe Ratschet im Brachland weilt. Er weist angehende Beschwörer an, den Folianten zu bergen, damit sie unter seiner Anleitung die Riten erlernen können, die für das Beschwören und Binden eines Teufelsjägers nötig sind.",al={"wer ist strahad","strahad farsan","strahad verbindung"}},{q="Warum ist der Schimmlige Foliant mit Meeresschmutz bedeckt?",a="Das Buch befand sich an Bord eines Schiffes von der Küste Lordaerons mit dem Ziel Hafen von Menethil, das sein Ziel nie erreichte. Das Schiffswrack trieb nahe der Küste von Hillsbrad, wo die feuchten, modernden Seiten von Küstenmurlocs nahe dem Azurschacht aufgelesen wurden.",al={"warum ist der schimmlige foliant nass","hillsbrad foliant murlocs"}}},fx={["7c4e226c"]={q="Was ist der Schimmlige Foliant?",a="Der Schimmlige Foliant repräsentiert die wasserdurchtränkten Überreste der primären Bindung des Tome of the Cabal. Er ging auf See vor der Küste des Vorgebirges des Hügellands verloren, als ein Transportschiff auf dem Weg zum Hafen von Menethil sank. Ihn zurückzuholen bedeutet, den Kern der finsteren Lehren des Grimoires wiederherzustellen.",al={"schimmliger foliant","was ist der schimmlige foliant","warum schimmligen folianten finden"}},aa350fa4={q="Was ist das Zerlumpte Manuskript?",a="Das Zerlumpte Manuskript ist der Abschnitt, der aus dem ursprünglichen Tome of the Cabal herausgerissen wurde, bevor das Buch verloren ging. Weit über das Meer getragen, landete es in den Händen der Galak-Zentauren in Tausend Nadeln und enthält die fehlenden Riten, die benötigt werden, um den vollständigen Text zusammenzusetzen.",al={"zerlumptes manuskript","was ist das zerlumpte manuskript","zentauren manuskript"}}},fp="17,262,18.560.0,21.545.0,30.227.0,51.262.0,44.274.0,47.281.0,66.214.0,43.247.0"}
P.entries["quest:1803"] = {n="Foliant der Kabale",s="Diese Quest beauftragt Hexenmeister der Horde damit, die getrennten Hälften des uralten Folianten der Kabale für Jorah Annison in Unterstadt wieder zu vereinen. Einst im Königreich Lordaeron aufbewahrt, wurde das Grimoire zerrissen und über die ganze Welt verstreut, bevor es völlig verloren ging. Das Aufspüren seiner feuchten und zerlumpten Überreste erfordert es, feindseligen Gewässern in den Östlichen Königreichen und tiefem Zentaurengebiet in Kalimdor zu trotzen.",h="Diese Quest beauftragt Hexenmeister der Horde damit, die getrennten Hälften des uralten Folianten der Kabale...",kw={"galak","jorah annison","lordaeron","schimmliger foliant","süderstade","spalthufhöhle","zerlumptes manuskript","tausend nadeln","foliant der kabale","hexenmeisterquest"},ang={["class:Warlock"]="Die Wiederbeschaffung des Folianten der Kabale ist eine Reifeprüfung für fortgeschrittene Anwender, bei der verlorene Arkana aus Lordaeron gesammelt werden, um Euer Beschwörungsrepertoire zu erweitern.",["faction:Horde"]="Die Suche nach dem Manuskript führt Euch durch die Schluchten von Tausend Nadeln, wo die auf dem Freiwindposten stationierten Streitkräfte der Horde einen ständigen Krieg gegen die einheimischen Zentauren führen.",["race:Undead"]="Der Foliant wurde vor dem Fall des Königreichs in Lordaeron aufbewahrt, weshalb seine Wiederbeschaffung die Rückforderung okkulten Erbes aus dem früheren menschlichen Leben der Verlassenen darstellt."},sec={{t="Ein geteiltes Erbe",b="Der Foliant der Kabale wurde einst innerhalb der Bibliotheksmauern des alten Königreichs Lordaeron verwahrt. Irgendwann vor dem Untergang des Königreichs wurde das finstere Grimoire vorsätzlich geschändet, fast um die Hälfte seiner Seiten beraubt und in zwei Teile gespalten. Der verbleibende formelle Text war für den Transport nach Süden in die Zwergenhallen von Eisenschmiede vorgesehen, doch das Schicksal griff ein: Das Transportschiff erlitt an der felsigen Küste westlich von Süderstade Schiffbruch, wodurch die Seiten in den Untiefen unter den wachsamen Augen plündernder Murlocs verrotteten."},{t="Über Kontinente verstreut",b="Die geschändete Hälfte des Folianten wanderte noch weiter in die Ferne. Aus Lordaeron entwendet, gelangte sie bis in das südliche Kalimdor und fiel tief in der Spalthufhöhle in Tausend Nadeln in den rauen Besitz der Galakzentauren. Um den vollständigen Text wiederzuerlangen, muss ein Hexenmeister die feuchte Küste von Hillsbrad nach dem Schimmligen Folianten absuchen und die staubigen, wilden Schluchten der Zentauren nach dem Zerlumpten Manuskript infiltrieren. Sobald beide Überreste zu Jorah Annison gebracht werden, wird das legendäre dunkle Werk wieder zu einem einzigen, lesbaren Band zusammengefügt."}},faq={{q="Was ist der Foliant der Kabale?",a="Es ist ein arkanes und dämonisches Grimoire, das einst in der Hauptstadt von Lordaeron aufbewahrt wurde. Es enthält fortgeschrittene Rituale für Hexenmeister, wurde jedoch verstümmelt und in zwei Teile geteilt, bevor es über zwei verschiedene Kontinente hinweg verloren ging.",al={"foliant der kabale lore","was ist dieses buch","foliant der kabale"}},{q="Warum befindet sich ein Teil des Buches in der Nähe von Süderstade?",a="Nachdem das Buch geschändet worden war, sollte der verbliebene gebundene Teil zu den Gelehrten von Eisenschmiede überführt werden. Das Schiff, das ihn transportierte, erlitt jedoch an der Küste westlich von Süderstade Schiffbruch, sodass das Grimoire inmitten der dortigen Murlocs strandete.",al={"warum süderstade","schimmliger foliant herkunft","küste westlich von süderstade"}},{q="Wie gelangten die Seiten zu den Zentauren in Tausend Nadeln?",a="Ungefähr die Hälfte der Seiten wurde aus dem ursprünglichen Folianten in Lordaeron herausgerissen und weggeschmuggelt. Durch Handel, Plünderung oder wandernde Hände landete dieses zerlumpte Manuskript schließlich tief in der Spalthufhöhle, aufbewahrt in einer Kiste der Galakzentauren.",al={"warum zentauren es haben","tausend nadeln seiten","spalthufhöhle buch"}},{q="Wer ist Jorah Annison?",a="Jorah Annison ist ein Hexenmeister der Verlassenen, der im Magieviertel von Unterstadt ansässig ist. Er leitet aufstrebende Hexenmeister der Horde dabei an, vergessenes, verbotenes Wissen wiederzuerlangen, um ihre Beherrschung dämonischer Mächte zu vertiefen.",al={"jorah annison lore","wer ist jorah"}},{q="Wer hat den Folianten überhaupt geschändet?",a="Die genaue Identität des Täters bleibt unbekannt. Jorah Annison selbst beklagt die Tat und fragt sich, wer ein solch abscheuliches Verbrechen an einem Text von so tiefer okkulter Macht begehen konnte.",al={"wer zerriss das buch","wer stahl die seiten","foliant vandale"}},{q="Was macht Jorah mit dem Buch, sobald Ihr beide Teile zurückbringt?",a="Nachdem er sowohl den Schimmligen Folianten als auch das Zerlumpte Manuskript erhalten hat, fügt Jorah Annison die Teile zu einem einzigen Band zusammen und liest die Seiten durch, um Euch auf die nächsten Schritte Eurer dämonischen Riten vorzubereiten.",al={"was passiert nach abgabe","wiederhergestellter foliant"}}},fx={a3cceb5d={q="Warum will Jorah Annison das Tome of the Cabal?",a="Jorah Annison ist ein Hexenmeister-Gelehrter der Verlassenen, der sich dem Aufspüren verlorener fel-Überlieferungen widmet, die einst in Lordaeron beherbergt waren. Die Wiederherstellung des zerbrochenen Tome of the Cabal ermöglicht es ihm, seine okkulten Geheimnisse aus erster Hand zu studieren, während er vielversprechende Hexenmeister bei der Beherrschung gefährlicher, fortgeschrittener Beschwörungen anleitet.",al={"warum will jorah das","jorah annison motiv","warum tome of the cabal sammeln"}},["53b5e7e7"]={q="Was ist der Schimmlige Foliant?",a="Der Schimmlige Foliant enthält die geborgenen Überreste des Originaltextes, der nach dem Fall von Lordaeron für den Transfer nach Eisenschmiede bestimmt war. Bei einem Schiffbruch entlang der Küste nahe Süderstade verloren gegangen und von Murlocs geplündert, enthält er eine wichtige Hälfte der Rituale der Kabale.",al={"was ist schimmliger foliant","schimmliger foliant lore","nutzen von schimmligem folianten"}},["2b99c3ce"]={q="Was ist das Zerlumpte Manuskript?",a="Das Zerlumpte Manuskript ist die fehlende Hälfte des Tome of the Cabal, die herausgerissen wurde, als das Buch in Lordaeron geschändet wurde. Durch unbekannte Hände überquerten diese gestohlenen Seiten das Meer nach Kalimdor und landeten schließlich verschlossen in einer Truhe bei den Galak-Zentauren von Tausend Nadeln.",al={"was ist zerlumpte manuskript","zerlumpte manuskript lore","nutzen von zerlumptem manuskript"}}},fp="17,405,16.528.0,27.563.1,30.206.0,44.241.0,62.248.0,21.210.0,43.189.0,64.204.0"}
P.entries["quest:1804"] = {n="Foliant der Kabale",s="Diese Quest markiert die letzte Vorbereitung für Hexenmeister der Allianz, die einen Teufelsjäger befehligen wollen. Nachdem der Hexenmeister den fragmentierten Tome of the Cabal zusammengesetzt hat, muss er Ruten der Kanalisierung von Orcs des Drachenmals im Sumpfland beschaffen und zu Strahad Farsan mit Blick auf Ratschet zurückkehren.",h="Diese Quest markiert die letzte Vorbereitung für Hexenmeister der Allianz, die einen Teufelsjäger befehligen...",kw={"brachland","drachenmal","teufelsjäger","krom starkarm","ratschet","ruten der kanalisierung","strahad farsan","tome of the cabal","sumpfland"},ang={["class:Warlock"]="Das Unterwerfen eines Teufelsjägers ist ein prägender Übergangsritus, der einen Hexenmeister von einfachen Pakten mit Wichteln und Leerwandlern zur Beherrschung räuberischer Dämonen erhebt, die erschaffen wurden, um arkane Magie zu verschlingen.",["faction:Alliance"]="Diese Quest führt Beschwörer der Allianz auf Reisen zwischen Eisenschmiede, den nebligen Mooren des Sumpflands und dem neutralen Goblinhafen Ratschet in Kalimdor.",["race:Dwarf"]="Selbst die dunklen Künste verlassen sich auf die akribischen Konservierungsfertigkeiten in Eisenschmiedes Hall of Explorers, wo Krom Starkarm zerstörte Relikte wieder zusammenfügt."},sec={{t="Eine widerwillige Übergabe",b="In Eisenschmiedes Hall of Explorers band Krom Starkarm die verkohlten und modrigen Überreste des Tome of the Cabal akribisch wieder zusammen. Widerstrebend, ein so seltenes Werk dunkler Gelehrsamkeit herauszugeben, ringt der Zwergengelehrte dem Hexenmeister das Versprechen einer künftigen Kopie ab, ehe er ein neues Schreiben von Strahad Farsan weiterreicht. Der Foliant enthält die Riten, die erforderlich sind, um in den Nether vorzudringen, doch rohes Pergament allein kann das notwendige Ritual nicht leiten."},{t="Gestohlene Relikte des Drachenmals",b="Bevor Strahads Akolythen dabei helfen können, einen Dämon zu binden, der so unersättlich ist wie ein Teufelsjäger, benötigen sie Fokusfokusse, um die beschworenen Energien zu stabilisieren. Krom schickt den Hexenmeister ins Sumpfland, wo Zauberwirker des Drachenmalklans Ruten der Kanalisierung führen. Diese Foki aus den Händen feindseliger Orcs zu entreißen, liefert den Kanal, den Strahads Zirkel benötigt, um den Riss zu kontrollieren."},{t="Zurück ins Brachland",b="Die Übergabe sowohl des rekonstruierten Grimoires als auch der Ruten der Kanalisierer an Strahads Turm hoch über Ratschet schließt den mühsamen Zusammenbau ab. Da die Instrumente gesichert und der Text übersetzt ist, bereitet sich Strahad darauf vor, den gefährlichen Ritus der Bindung einzuleiten, um zu prüfen, ob der Beschwörer die Willenskraft besitzt, einen Hund der Brennenden Legion zu zähmen."}},faq={{q="Warum benötigt Strahad Ruten der Kanalisierung?",a="Die Beschwörung und Bindung eines Teufelsjägers ist für einen einzelnen Hexenmeister ohne Verankerung zu unruhig. Strahads Akolythen müssen während des Rituals den Beschwörungskreis aufrechterhalten und fokussieren, und diese Ruten kanalisieren und stabilisieren die nötigen Energien, um zu verhindern, dass das Portal zusammenbricht oder außer Kontrolle gerät.",al={"warum ruten der kanalisierung","zweck der ruten der kanalisierung","wofür sind die ruten"}},{q="Wo sind die Ruten der Kanalisierung zu finden?",a="Die Ruten befinden sich im Besitz der Orc-Zauberwirker des Drachenmalklans, die im Sumpfland verweilen, insbesondere in den Sümpfen und Ruinen, die sie besetzen.",al={"wo man ruten der kanalisierung bekommt","wer ruten der kanalisierung fallen lässt","ort der ruten der kanalisierung"}},{q="Warum war Krom Starkarm an einem Hexenmeister-Ritual beteiligt?",a="Krom Starkarm ist ein Meisterforscher in Eisenschmiede, der über die spezialisierten Fähigkeiten verfügt, die erforderlich sind, um uralte, beschädigte Manuskripte zu übersetzen, zu konservieren und physisch zu rekonstruieren. Seine Faszination für seltene Antiquitäten veranlasste ihn dazu, die verdorbenen Seiten des Tome of the Cabal wiederherzustellen.",al={"warum krom","warum hilft ein zwerg aus eisenschmiede einem hexenmeister","krom starkarm hexenmeister"}},{q="Was geschieht, nachdem man Strahad den Folianten und die Ruten übergeben hat?",a="Strahad setzt die gesammelten Werkzeuge unverzüglich ein und beginnt das Ritual der Bindung auf der Spitze seines Turms, wo Ihr Euch dem beschworenen Teufelsjäger persönlich stellen und ihn unterwerfen müsst.",al={"was als nächstes geschieht","nächste quest nach tome of the cabal 3","was macht strahad"}},{q="Wer ist Strahad Farsan?",a="Strahad Farsan ist ein mächtiger Hexenmeister, der von einem einsamen Turm auf den Klippen über der Hafenstadt Ratschet im Brachland aus agiert. Erfahrene Praktizierende in ganz Kalimdor und den Östlichen Königreichen beugen sich seiner Meisterschaft der Dämonologie.",al={"strahad farsan lore","wer ist strahad","mann über ratschet"}},{q="Wird der Tome of the Cabal auch von der Horde verwendet?",a="Hexenmeister der Horde verfolgen ihre eigene Version der Riten des Tome of the Cabal, wenngleich ihre Hinweise sie zu anderen Kontaktpersonen in Kalimdor und der Unterstadt führen, anstatt mit Krom Starkarm in Eisenschmiede zusammenzuarbeiten.",al={"horde tome of the cabal","machen orcs diese quest"}}},fx={["7a279078"]={q="Warum müsst Ihr den Dragonmaw-Clan im Sumpfland jagen?",a="Der Überrest des Dragonmaw-Clans, der sich im Sumpfland verschanzt hat, führt immer noch mächtige dunkle Magie, die von ihrer früheren Herrschaft übrig geblieben ist. Krom weiß, dass ihre Zauberwirker die spezialisierten Stäbe der Kanalisierung tragen, die benötigt werden, um Strahads Beschwörungskreis zu verankern. Um die Fokussierungen zu beanspruchen, müsst Ihr sie diesen feindseligen Orc-Zauberern direkt entreißen.",al={"warum dragonmaw orcs","sumpfland dragonmaw hexenmeister","wer hat stäbe der kanalisierung"}}},fp="17,278,19.436.0,30.375.0,19.338.1,41.284.0,39.144.0,51.268.0,55.165.1,22.242.0,51.209.0"}
P.entries["quest:1805"] = {n="Foliant der Kabale",s="Diese Quest markiert den letzten vorbereitenden Abschnitt auf dem Weg eines Hexenmeisters der Horde, einen Teufelsjäger zu beschwören und zu befehligen. Nachdem er Jorah Annison geholfen hat, den uralten Folianten der Kabale wiederherzustellen, muss der Praktizierende in feindliches Gebiet reisen, um drei Rods of Channeling an sich zu bringen, bevor er die Komponenten zu Strahad Farsan in Ratschet bringt.",h="Diese Quest markiert den letzten vorbereitenden Abschnitt auf dem Weg eines Hexenmeisters der Horde, einen...",kw={"lager der grollhauer","dragonmaw","teufelsjäger","jorah annison","ratschet","rute des kanalisierens","strahad farsan","foliant der kabale","sumpfland"},ang={["class:Warlock"]="Diese Prüfung stellt Eure Entschlossenheit auf die Probe, gefährliche Ritualreagenzien aus feindlichen Landen zu beschaffen, und beweist, dass Ihr das Wissen und den Mut besitzt, einen raubtierhaften Teufelsjäger an Euren Dienst zu binden.",["faction:Horde"]="Dragonmaw-Abtrünnige im Sumpfland bleiben erbitterte Feinde von Thralls Horde, was die gewaltsame Rückforderung ihrer Kanalisierungsstäbe zu einem doppelten Sieg für die Interessen der Horde macht.",["race:Orc"]="Das Niederschlagen der abtrünnigen Mitglieder des Dragonmaw-Klans im Sumpfland dient als harte Erinnerung an den finsteren, unbußfertigen Pfad, den die Horde hinter sich zu lassen versuchte.",["race:Undead"]="Jorah Annisons Gelehrtenarbeit in Unterstadt spiegelt die Tradition der Hexenmeister der Verlassenen wider, verbotene arkane Texte zur praktischen Erlangung arkaner Vorherrschaft zu sezieren."},sec={{t="Geheimnisse des Rekonstruierten Folianten",b="In Unterstadt untersucht der Gelehrte der Verlassenen, Jorah Annison, die Fragmente des geborgenen Folianten der Kabale und setzt dessen unheimliche Passagen zusammen. Obwohl er über den seltenen intellektuellen Schatz erfreut ist, überbringt Jorah eine dringende Anweisung von Strahad Farsan. Um ein dämonisches Raubtier wie einen Teufelsjäger zu binden, reicht reines Wissen nicht aus: Ein Hexenmeister muss präzise Machtinstrumente besitzen, die fähig sind, gewaltsame dämonische Energien in einen Bindungskreis zu fokussieren."},{t="Vorstoß in das Sumpfland",b="Strahad benötigt drei Rods of Channeling, spezialisierte Fokussierstäbe, die von den abtrünnigen Orcs des Dragonmaw-Klans getragen werden. Weit entfernt von den Kernlanden der Horde hausen diese Dragonmaw inmitten der Ruinen des Lagers der Grollhauer in den durchnässten Marschen des Sumpflands. Sie aufzuspüren erfordert das Betreten umkämpfter Lande, die von feindseligen Klanüberresten beherrscht werden, welche die moderne Horde ebenso verachten, wie sie Forscher der Allianz abschlachten."},{t="Rückkehr nach Ratschet",b="Mit den geborgenen Stäben in der Hand und dem gesicherten Rekonstruierten Folianten kehrt der Hexenmeister über das Meer zu Strahad Farsans Turm zurück, der Ratschet überragt. Strahad begrüßt den zurückkehrenden Zauberwirker mit grimmiger Genugtuung. Die Komponenten für das Beschwörungsritual sind versammelt, was die Bühne für eine gefährliche Willensprüfung gegen eine ungezähmte Bestie des Wirbelnden Nethers bereitet."}},faq={{q="Was ist der Zweck dieser Quest?",a="Sie ist der dritte Schritt in der Questreihe der Horde-Hexenmeister, um das Beschwören eines Teufelsjägers zu erlernen. Sie erfordert das Überbringen des wiederhergestellten Folianten der Kabale und von drei Rods of Channeling an Strahad Farsan oberhalb von Ratschet.",al={"warum diese quest machen","questzweck","wozu foliant der kabale"}},{q="Wer ist Jorah Annison?",a="Jorah Annison ist ein Hexenmeister und Gelehrter der Verlassenen im Magieviertel von Unterstadt. Er studiert esoterische und dunkle Schriften und unterstützt andere Praktizierende, indem er zerschlagene Zauberbücher wie den Folianten der Kabale wieder zusammensetzt.",al={"wer ist jorah","jorah annison geschichte"}},{q="Warum werden Rods of Channeling benötigt?",a="Das Beschwören und Beherrschen eines Teufelsjägers erfordert präzise metaphysische Kontrolle. Die Stäbe dienen als fokussierende Kanäle, um den Beschwörungskreis zu stabilisieren und zu formen, damit der Hexenmeister den Dämon unterwerfen kann, anstatt von ihm verschlungen zu werden.",al={"warum rods of channeling","stäbe zweck"}},{q="Wo befinden sich die Orcs des Dragonmaw-Klans für diese Quest?",a="Der Dragonmaw-Klan hält das Lager der Grollhauer im Sumpfland, einem von der Allianz dominierten Gebiet jenseits des Meeres in Khaz Modan. Konkret tragen ihre Knochenwächter die begehrten Kanalisierungsstäbe bei sich.",al={"wo dragonmaw finden","dragonmaw aufenthaltsort sumpfland","lager der grollhauer"}},{q="Wer ist Strahad Farsan?",a="Strahad Farsan ist ein einflussreicher menschlicher Hexenmeister, der mit den dunklen Zauberwirkern der Horde verbündet ist und von einem einsamen Turm auf den Klippen oberhalb des Goblin-Hafens Ratschet im Brachland aus operiert.",al={"wer ist strahad","strahad farsan ratschet"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Der Abschluss dieser Übergabe führt direkt zu 'Die Bindung', wo Strahad den Hexenmeister anweist, einen Beschwörungskreis zu zeichnen und sich einem beschworenen Teufelsjäger im magischen Kampf zu stellen, um die Bestie zu meistern.",al={"was kommt danach","folgequest nach foliant"}}},fx={["9475dbd0"]={q="Warum hilft Euch Jorah Annison?",a="Jorah Annison ist ein Kartograph der Verlassenen im Magieviertel der Unterstadt, der nach langem Erschöpfen der spärlichen Auswahl an Geographie-Texten vor Ort hungrig nach arkanem und esoterischem Lesematerial ist. Im Austausch für die Gelegenheit, das rekonstruierte Tome of the Cabal zu studieren, gibt er Anweisungen von Strahad Farsan weiter und verrät Euch, wo Ihr die seltenen Kanalisierungsstäbe erwerben könnt, die Ihr für Eure Ausbildung benötigt.",al={"warum hilft jorah","jorah annison motiv","was will jorah"}},cff1ec65={q="Warum haben die Dragonmaw-Orcs die Stäbe der Kanalisierung?",a="Der abtrünnige Dragonmaw-Clan unterhält Festungen im gesamten Sumpfland und beherbergt dunkle Zauberwirker und Knochenwächter, die finstere Magien praktizieren, die sich von der modernen Horde unterscheiden. Sie benutzen mächtige Kanalisierungsstäbe, um rohe magische Energien zu fokussieren und zu binden, was ihre Lager zu den besten Orten macht, um die arkanen Foki zu bergen, die Strahad für Beschwörungsrituale benötigt.",al={"dragonmaw orcs sumpfland","wer hat die stäbe der kanalisierung","warum dragonmaw orcs"}}},fp="17,320,33.453.0,25.411.0,17.365.1,34.199.0,21.231.0,34.222.0,52.199.0,22.192.0,41.191.1"}
P.entries["quest:1806"] = {n="Die Prüfung der Rechtschaffenheit",s="Die Prüfung der Rechtschaffenheit gipfelt an Jordan Stillbrunns Schmiede vor Eisenschmiede in Dun Morogh. Nach dem Sammeln gefährlicher Komponenten aus den Östlichen Königreichen und Kalimdor wartet ein Paladin, während der Schmied einen mächtigen Kriegshammer herstellt. Es markiert den Übergang von einem Lehrling zu einem anerkannten Streiter des Lichts.",h="Die Prüfung der Rechtschaffenheit gipfelt an Jordan Stillbrunns Schmiede vor Eisenschmiede in Dun Morogh.",kw={"bosch verigan","dun morogh","schmiede","hammer","eisenschmiede","jordan stillbrunn","paladin","prüfung der rechtschaffenheit","verigan"},ang={["class:Paladin"]="Dieser Übergangsritus belohnt Eure gefährlichen Reisen durch ferne Länder mit Verigans Faust, einer ikonischen Waffe, die dem Schutz der Rechtschaffenheit gewidmet ist.",["profession:Blacksmithing"]="Jordan Stillbrunn bei der Arbeit am Amboss zuzusehen, zeigt, wie meisterhafte Handwerkskunst heilige Bestimmung in rohen Stahl und geborgene Materialien leiten kann.",["race:Dwarf"]="Der hier geschmiedete Hammer verewigt das Andenken an Bosch Verigan, einen geehrten Zwergenpaladin, der die Widerstandskraft von Khaz Modan verkörperte."},sec={{t="Der Tribut eines Schmieds",b="Meisterschmied Jordan Stillbrunn übt sein Handwerk vor den Toren von Eisenschmiede aus. Obwohl er zugibt, wandernde Paladine um ein Weniges zu beneiden, erfüllt es ihn mit tiefem Stolz, ihre Sache mit Hammer und Amboss zu unterstützen. Sobald ihm seltene Materialien überreicht werden, die aus finsteren Krypten, versunkenen Ruinen und gefährlichen Minen geborgen wurden, erfüllt Stilwell sein Versprechen, eine Waffe zu schmieden, die eines wahren Verteidigers würdig ist."},{t="Das Vermächtnis von Bosch Verigan",b="Der fertige Kriegshammer wird zu Ehren von Bosch Verigan, einem hochgeschätzten Zwergenpaladin und engen persönlichen Freund von Jordan Stillbrunn, auf den Namen Verigans Faust getauft. Indem Stilwell diese heilige Waffe im Namen seiner selbst und seiner Frau in die Hände eines jungen Streiters übergibt, sorgt er dafür, dass das Andenken und der Mut seines gefallenen Freundes gegen die Finsternis weiterleben, die Azeroth bedroht."}},faq={{q="Was geschieht während dieses Questschritts?",a="Jordan Stillbrunn tritt an seinen Amboss und bearbeitet heißes Metall, um die Komponenten zusammenzusetzen, die Ihr auf Euren mühseligen Prüfungen gesammelt habt. Nachdem er an der Schmiede gearbeitet hat, kehrt er zurück, um Euch die fertige Waffe zu überreichen.",al={"prüfung der rechtschaffenheit ende","jordan schmiedet waffe","verigan zwischensequenz"}},{q="Wer ist Bosch Verigan?",a="Bosch Verigan war ein angesehener Zwergenpaladin und ein enger Freund von Jordan Stillbrunn. Jordan benannte den neu geschmiedeten Zweihandhammer zu seinem Gedenken und ehrte damit seine Hingabe an das Heilige Licht.",al={"wer ist verigan","verigans faust namensgeber","bosch verigan"}},{q="Wo findet dieser Schmiedevorgang statt?",a="Das Schmieden findet direkt vor den großen Toren von Eisenschmiede in den verschneiten Gipfeln von Dun Morogh statt, wo Jordan Stillbrunn seine Esse und seinen Amboss betreibt.",al={"jordan stillbrunn standort","wo ist die schmiede","dun morogh amboss"}},{q="Warum benötigte Jordan seltene Materialien aus aller Welt?",a="Jordan entwarf eine Waffe von außergewöhnlicher Ausgewogenheit und heiliger Resonanz. Um etwas zu schmieden, das dem heiligen Zorn eines Paladins standhalten kann, benötigte er seltene Erze, Holz und Edelsteine, die nur an gefährlichen Orten auf der ganzen Welt geborgen werden konnten.",al={"warum materialsammlung","questkomponenten prüfung der rechtschaffenheit"}},{q="Kämpft Jordan Stillbrunn jemals selbst in der Schlacht?",a="Jordan Stillbrunn ist ein Hufschmied und kein umherziehender Krieger. Obwohl er zugibt, gelegentlich Abenteurer zu beneiden, die durch die Lande ziehen, findet er seine wahre Bestimmung und seinen Stolz darin, Waffen zu schmieden, um Verteidiger des Lichts auszurüsten.",al={"ist jordan ein krieger","jordan stillbrunn kämpfer"}},{q="Was bedeutet der Erhalt dieses Hammers für einen Paladin?",a="Der Erhalt des Hammers markiert den erfolgreichen Abschluss der langen Prüfungen eines Paladins. Er beweist, dass der Träger den Mut, die Beharrlichkeit und die heilige Überzeugung besitzt, die nötig sind, um das Licht in den gefährlichsten Ecken von Azeroth zu verteidigen.",al={"bedeutung von verigans faust","paladin übergangsritus"}}},fx={["49955bc3"]={q="Warum will Jordan Stillbrunn diesen Hammer schmieden?",a="Jordan Stillbrunn gibt zu, einen Anflug von Neid zu verspüren, wenn er die gewagten Heldentaten von Champions in ganz Azeroth sieht, da er eher Schmied als Abenteurer ist. Indem er Verigans Faust aus den seltenen Komponenten schmiedet, die Ihr gesammelt habt, kann er einem Verteidiger das Licht direkt unterstützen und auf seine eigene, lebenswichtige Weise dazu beitragen, das Reich sicher zu halten.",al={"jordan stillbrunn motiv","warum die waffe schmieden","warum schmiedet jordan den hammer"}}},fp="25,320,17.391.0,27.358.0,43.211.0,21.190.0,35.152.0,59.243.0,50.225.0,54.228.0"}
P.entries["quest:181"] = {n="Der Blick zu den Sternen",s="Diese Quest markiert das letzte Kapitel in Viktori Prism'Antras' Bestreben, ein Gerät zur Sternenbeobachtung in Dunkelhain zusammenzubauen. Da das Teleskopgerüst ansonsten fertiggestellt ist, schickt Viktori Reisende zum gefährlichen Ogerhort Vul'Gol, um eine Linse zu beschaffen, die groß genug für seine Apparatur ist: ein Monokel, das von dem Oger Zzarc'Vul getragen wird.",h="Diese Quest markiert das letzte Kapitel in Viktori Prism'Antras' Bestreben, ein Gerät zur Sternenbeobachtung...",kw={"cog","dunkelhain","der blick zu den sternen","monokel","teleskop","viktori prism'antras","ogerhort vul'gol","zzarc'vul"},ang={["faction:Alliance"]="Dunkelhain klammert sich an ein zerbrechliches Überleben gegen Schrecken und Bestien, was Viktoris Streben nach himmlischem Wissen zu einem dauerhaften, wenn auch exzentrischen Leuchtfeuer zivilen Durchhaltevermögens macht.",["profession:Engineering"]="Magier und Tüftler schätzen gleichermaßen die Kühnheit, ein gewaltiges Ogermonokel einzusetzen, um die Brennpunktanforderungen einer astronomischen Linse zu erfüllen.",["race:Gnome"]="Die Vorrichtung basiert auf Bauplänen gnomischer Handwerkskunst und verlangt nach genialen Improvisationen im Feld, wie der Umwandlung von Rohlings-Sehhilfen in Präzisionsoptik."},sec={{t="Das letzte Teil",b="Während des gesamten Baus seines Teleskops zur Sternenbeobachtung hat sich Viktori Prism'Antras auf Pläne gestützt, die von dem Gnomen-Ingenieur Cog Glitzspinner entworfen wurden. Während Messingrohre und stabile Halterungen aus lokalen Vorräten geborgen oder zusammengebaut werden konnten, erforderte der Apparat eine außergewöhnlich gewaltige Fokussierlinse. Handelsüblichen Vergrößerungsgläsern und optischen Komponenten von Händlern aus Sturmwind fehlte schlichtweg der Durchmesser, den Cogs ehrgeiziger Entwurf verlangte, was Viktori dazu veranlasste, nach einer unwahrscheinlichen und gefährlichen Alternative zu suchen."},{t="Das Okular des Ogers",b="Im Schatten der südlichen Hügel liegt der Ogerhort Vul'Gol, ein Lager, in dem es von feindseligen Rohlingen nur so wimmelt. Unter ihnen weilt Zzarc'Vul, ein sonderbarer Oger, der dafür bekannt ist, ein Glasmonokel zu tragen, das groß genug ist, um als Linse für das Observatorium zu dienen. Tief in den Hort vorzudringen und Zzarc'Vul das Okular abzunehmen, erfüllt Cogs Baupläne und ermöglicht es Viktori, sein Teleskop fertigzustellen und über das schattige Blätterdach des Dämmerwalds hinweg in die Gestirne zu blicken."}},faq={{q="Wer ist Viktori Prism'Antras?",a="Viktori Prism'Antras ist ein Astronom und Gelehrter, der in einer Hütte auf dem Hügel in Dunkelhain lebt. Trotz der Düsternis, die den Dämmerwald einhüllt, widmet er sich weiterhin unermüdlich der Fertigstellung seines Observatoriumsteleskops, um die Sterne zu studieren.",al={"wer ist viktori","viktori prism'antras"}},{q="Wo kann ich Zzarc'Vul finden?",a="Zzarc'Vul hält sich in den südlichen Ausläufern des Dämmerwalds im Ogerhort Vul'Gol auf. Er streift durch das Lager und das Höhlensystem des Horts, sodass Suchende durch schwer bewachtes Ogergebiet vordringen müssen, um ihn zu finden.",al={"zzarc'vul aufenthaltsort","wo ist der oger","oger-monokel fundort"}},{q="Warum besitzt ein Oger ein Monokel?",a="Obwohl Oger nicht gerade für ihre akademischen Bestrebungen oder feine Optik bekannt sind, trägt Zzarc'Vul ein übergroßes Monokel bei sich. Seine ungewöhnlichen Proportionen machen es zur einzigen Linse in der Region, die massiv genug ist, um in Cogs Teleskoppläne zu passen.",al={"warum ogermonokel","ogermonokel lore"}},{q="Was geschieht, sobald die Vorrichtung vollendet ist?",a="Die Sicherung des Monokels ermöglicht es Viktori, das letzte optische Element einzusetzen. Sobald das Teleskop vollständig zusammengebaut ist, kann Viktori seine astronomischen Studien ungestört vom tristen Waldboden darunter wieder aufnehmen.",al={"teleskop fertiggestellt","quest-abschluss"}},{q="Wer hat das Teleskop entworfen?",a="Die Baupläne für das Gerät stammten von einem Ingenieur namens Cog, dessen komplexer Entwurf Spezialteile, Metallfassungen und eine Linse vorsah, die weitaus größer war als normale Zwergen- oder Gnomenbrillen.",al={"cogs baupläne","wer baute das teleskop"}},{q="Kann man den Ogerhort Vul'Gol gefahrlos allein betreten?",a="Nein. Der Ogerhort Vul'Gol ist dicht von feindseligen Ogern bevölkert, die oft in Rudeln patrouillieren oder enge Pfade bewachen. Tief in den Hort vorzudringen, um Zzarc'Vul ausfindig zu machen, stellt für Einzelreisende eine erhebliche Gefahr dar.",al={"vul'gol schwierigkeit","ogerhort sicher"}}},fx={ac1c4dd0={q="Warum will Viktori Prism'Antras, dass dies erledigt wird?",a="Viktori ist ein exzentrischer Gelehrter, der sich dem Bau eines speziellen Apparats zur Sternenbeobachtung nach den Bauplänen von Cog widmet. Er hat beträchtliche Anstrengungen unternommen, um empfindliche Teile zu sammeln, aber seinem Entwurf fehlt noch ein Objektiv von ausreichender Größe, um in den Himmel zu spähen. Sobald das Teleskop vollständig zusammengebaut ist, wird er endlich in der Lage sein, seine astronomische Forschung aus dem Düsteren von Dunkelhain wieder aufzunehmen.",al={"warum viktori ein monokel braucht","viktori prism'antras ziel","look to the stars motiv"}},f331a2d2={q="Wozu dient das Ogermonokel?",a="Die Baupläne für Viktoris Gerät zur Sternenbeobachtung erfordern ein ungewöhnlich großes optisches Objektiv. Anstatt in der schattigen Isolation von Dämmerwald eines von Grund auf neu zu schleifen, erkannte Viktori, dass das übergroße Monokel, das der Oger Zzarc'Vul trägt, genau die Abmessungen und das fokussierende Glas bietet, die zur Vervollständigung des Apparats benötigt werden.",al={"zweck des ogermonokels","warum das monokel des ogers","wofür wird das monokel verwendet"}},bbeac028={q="Wer ist Zzarc'Vul?",a="Zzarc'Vul ist ein bekannter Oger, der unter seinesgleichen im Ogerhort Vul'Gol in den südlichen Hügeln von Dämmerwald lebt. Im Gegensatz zu seinen brutalen Gefährten trägt er ein riesiges Monokel, das die Aufmerksamkeit von Viktori Prism'Antras auf sich gezogen hat, was ihn zum letzten Hindernis zwischen dem Gelehrten und seinem fertiggestellten Teleskop macht.",al={"wer ist zzarcvul","wer ist der oger","ziel zzarc'vul"}}},fp="17,312,15.508.0,19.438.1,28.210.0,27.220.0,35.226.0,42.197.0,27.202.0,42.212.0"}
P.entries["quest:1818"] = {n="Gespräch mit Dillinger",s="Gespräch mit Dillinger ist eine militärische Weisung der Horde, die in Unterstadt erteilt wird. Austil de Mon schickt kampffähige Streiter zu Todeswache Dillinger nach Brill, um eine gefährliche Kampfmission im Dienste von Fürstin Sylvanas anzunehmen.",h="Gespräch mit Dillinger ist eine militärische Weisung der Horde, die in Unterstadt erteilt wird.",kw={"austil de mon","brill","todeswache dillinger","gespräch mit dillinger","tirisfal","ulag der spalter","unterstadt"},ang={["class:Warrior"]="Die Kommandanten der Todeswache schätzen vor allem pure Entschlossenheit im Kampf, was diese Entsendung zu einer direkten Prüfung Eurer Kampffähigkeiten an vorderster Front macht.",["faction:Horde"]="Dem Ruf zur Verteidigung von Unterstadt zu folgen, festigt die fraktionsübergreifende Solidarität zwischen den Verbündeten Kalimdors und den neu integrierten Verlassenen.",["race:Undead"]="Für frisch befreite Verlassene ist das Folgen von Dillingers Ruf ein entscheidender Schritt, um Eure Hingabe an die Dunkle Fürstin und die Verteidigung von Tirisfal zu beweisen."},sec={{t="Ein Ruf an die Front",b="In den unterirdischen Hallen von Unterstadt hält Austil de Mon ein wachsames Auge nach vielversprechenden Kämpfern offen, die bereit sind, der Dunklen Fürstin zu dienen. Wenn die an der Oberfläche stationierten Todeswachen fähige Hände benötigen, schickt de Mon unerprobte Abenteurer aus der königlichen Hauptstadt hinaus ins Feld. Todeswache Dillinger, der die Sicherheit an den westlichen Grenzen von Brill überwacht, hat für eine dringende Aufgabe jemanden mit kriegerischem Geschick angefordert."},{t="Prüfung der Getreuen",b="Brill liegt direkt an der Frontlinie von Tirisfal, wo die Verlassenen ihre kriegerische Vorherrschaft ständig gegen feindliche Bedrohungen unter Beweis stellen müssen. Dillingers Posten in der Nähe des Dorffriedhofs bringt ihn in die beste Position, um lokale Übergriffe abzuwehren. Für den jungen Krieger ist die Meldung bei Dillinger mehr als ein einfacher Botengang: Es ist eine formelle Prüfung des Kampfgeschicks und der politischen Loyalität gegenüber dem neu geschmiedeten Volk der Verlassenen."}},faq={{q="Wer schickt mich auf diese Mission?",a="Austil de Mon, der sich in Unterstadt befindet, wählt potenzielle Soldaten aus und schickt sie zur Unterstützung von Todeswache Dillinger.",al={"questgeber","austil de mon","wer startet gespräch mit dillinger"}},{q="Wo ist Todeswache Dillinger zu finden?",a="Todeswache Dillinger ist am westlichen Rand von Brill in Tirisfal stationiert, nahe dem Friedhofseingang.",al={"dillinger standort","wo ist dillinger","dillinger finden"}},{q="Was ist der Zweck der Meldung bei Dillinger?",a="Dillinger benötigt einen fähigen Recken für eine Kampfmission, um Brill zu verteidigen und seine Loyalität zur Sache der Verlassenen zu beweisen.",al={"warum gespräch mit dillinger","dillinger zweck"}},{q="Welchen Auftrag hält Dillinger bereit?",a="Sobald Ihr Euch bei Todeswache Dillinger meldet, beauftragt er Euch damit, eine gefährliche Bedrohung namens Ulag der Spalter zur Strecke zu bringen.",al={"was will dillinger","folgequest dillinger"}},{q="Erhalten auch andere Völker der Horde diesen Befehl?",a="Jeder Krieger der Horde, der das Vertrauen der Beamten von Unterstadt gewonnen hat, kann den Auftrag annehmen, auch wenn er in erster Linie dazu dient, Rekruten zur Verteidigung von Tirisfal zu prüfen.",al={"nur für untote","können orcs das machen"}},{q="Warum wird diese Weisung in Unterstadt statt in Brill erteilt?",a="Austil de Mon dient als Rekrutierungsspäher in der Hauptstadt und leitet neu erstarkte Abenteurer an die Frontkommandanten weiter, die sofortige Verstärkung brauchen.",al={"warum start in unterstadt","austil de mon rolle"}}},fx={a192b457={q="Warum schickt Austil de Mon Euch zu Dillinger?",a="Austil de Mon fungiert als Vermittler und weist aufstrebende Verlassene, die nach höherem Ansehen streben, dorthin, wo ihre kriegerischen Talente dem Reich dienen können. Indem er fähige Hände aus der Unterstadt und unter das Kommando von Todeswache Dillinger schickt, stellt er sicher, dass die Siedlungen an der Front Verstärkung erhalten, während er gleichzeitig prüft, ob Ihr über wahren Wert und Hingabe für Lady Sylvanas' Sache verfügt.",al={"austil de mon motiv","warum zu dillinger schicken","grund für austil de mon"}}},fp="20,221,22.434.0,20.419.0,29.117.0,40.111.0,46.129.0,45.117.1,40.168.0,62.153.0"}
P.entries["quest:1819"] = {n="Ulag der Spalter",s="Ulag der Spalter ist ein Übergangsritus für junge Krieger der Verlassenen in Tirisfal. Todeswache Dillinger beauftragt Euch damit, einen versklavten Krieger der Geißel zu befreien und hinzurichten, der in einem nördlichen Mausoleum gefangen gehalten wird, um Eure kriegerische Entschlossenheit auf die Probe zu stellen und den Respekt der Todeswache zu erlangen.",h="Ulag der Spalter ist ein Übergangsritus für junge Krieger der Verlassenen in Tirisfal.",kw={"brill","todeswache dillinger","dillinger","mausoleum","geißel","totenkopfstein","ulag","ulag der spalter"},ang={["class:Warrior"]="Diese Prüfung dient Kriegern der Verlassenen als frühes Bewährungsfeld und stellt Euren Mut gegen einen mächtigen, gedankenkontrollierten Champion der Geißel auf die Probe.",["race:Undead"]="Ulags Schicksal veranschaulicht die grausame Realität der Kontrolle durch die Geißel und zeigt den tragischen Unterschied zwischen jenen Verlassenen, die sich befreien konnten, und jenen, deren Geist dem Lichkönig versklavt bleibt."},sec={{t="Ein gebundener Knecht der Geißel",b="Als die Geißel über Lordaeron fegte, gelang es den Verlassenen, einen eigenartigen untoten Krieger gefangen zu nehmen, der sich selbst Ulag der Spalter nannte. Obwohl Ulag einen bewussten, klaren Geist besaß, blieb seine Seele untrennbar von der mentalen Knechtschaft des Lichkönigs beherrscht. Um zu verstehen, wie die Geißel den freien Willen bindet, hielten die Verlassenen ihn unter einem magischen Siegel unterhalb eines Mausoleums nördlich von Brill gefangen, in der Hoffnung, die spirituellen Ketten des Wesens zu sprengen."},{t="Die Prüfung des Henkers",b="Alle Bemühungen, Ulag aus dem mentalen Griff des Lichkönigs zu befreien, scheiterten. In der Erkenntnis, dass wahre Freiheit nur durch Vernichtung erlangt werden konnte, funktionierte Todeswache Dillinger den Gefangenen zu einer Kampfprüfung für aufstrebende Krieger der Verlassenen um. Durch das Auslösen des Totenkopfsteins vor der Krypta durchbricht ein Krieger die Schutzglyphen, befreit Ulag aus seiner Gefangenschaft und gewährt ihm Erlösung durch die Schneide einer Axt."}},faq={{q="Wer ist Ulag der Spalter?",a="Ulag der Spalter war ein untoter Krieger, der während des Einfalls der Geißel in Tirisfal von den Verlassenen gefangen genommen wurde. Einzigartigerweise behielt er seinen freien Verstand und seine Identität, blieb jedoch völlig dem mentalen Befehl des Lichkönigs unterworfen.",al={"ulag lore","wer ist ulag","ulag der spalter identität"}},{q="Warum war Ulag unter dem Mausoleum eingesperrt?",a="Gelehrte und Soldaten der Verlassenen sperrten ihn unter einem magischen Siegel ein, um zu erforschen, wie die Gedankenkontrolle des Lichkönigs funktionierte. Sie hatten gehofft, eine Methode zu entdecken, um das mentale Band zu durchtrennen, das ihn festhielt, doch ihre Experimente blieben erfolglos.",al={"warum ist ulag eingesperrt","mausoleum gefangener tirisfal"}},{q="Warum wollen die Todeswachen Ulag nun töten?",a="Nachdem sie eingesehen hatten, dass der Griff des Lichkönigs über Ulag nicht gebrochen werden konnte, beschlossen die Verlassenen, dass der Tod die einzig verbliebene Gnade war. Todeswache Dillinger entschied, die Hinrichtung als Prüfung kriegerischen Mutes und Disziplin für angehende Krieger zu nutzen.",al={"warum ulag töten","grund ulag zu töten"}},{q="Wie wird Ulag beschworen?",a="Er ist unter einem Mausoleum direkt nördlich von Brill eingesperrt. Die Interaktion mit dem Totenkopfstein nahe der Gruft löst das magische Siegel, das ihn bindet, woraufhin er sich erhebt und angreift.",al={"wie ulag beschwören","wo ist ulag","ulag totenkopfstein"}},{q="Wer gibt die Quest, Ulag zu töten?",a="Todeswache Dillinger, der die westliche Straße aus Brill in Tirisfal bewacht, vergibt diesen Auftrag speziell an Krieger der Verlassenen, die nach weiterer Ausbildung suchen.",al={"questgeber ulag","wer schickt mich zu ulag"}},{q="Was geschieht, nachdem Ulag besiegt wurde?",a="Nach der Bestätigung von Ulags Ableben erkennt Todeswache Dillinger Euren Mut an und schickt Euch für das Gespräch mit Coleman Heller nach Brill, um Eure Ausbildung fortzusetzen.",al={"nach ulag","ulag quest folgequest"}}},fx={["6de55395"]={q="Warum lässt Todeswache Dillinger Euch gegen Ulag antreten, anstatt sich selbst darum zu kümmern?",a="Todeswache Dillinger stellt Euer Können auf die Probe. Ulag war kein unbedeutender Diener der Geißel, und sich ihm allein zu stellen, beweist, ob Ihr über das Geschick, den Mut und die Entschlossenheit verfügt, die von einem wahren Krieger im Dienste von Lady Sylvanas verlangt werden. Dillinger bewacht Brill und überwacht Eure Ausbildung; der Gang in die Gruft dient als Eure Prüfung durch Kampf, um zu zeigen, dass Ihr einer fortgeschrittenen Ausbildung würdig seid.",al={"warum ich dillinger","warum ulag selbst töten","warum spieler zu ulag schicken"}}},fp="16,280,22.455.0,23.417.0,24.233.0,44.246.0,44.236.0,21.178.0,33.174.0,36.156.0"}
P.entries["quest:182"] = {n="Die Trollhöhle",s="Diese Mission, vergeben vom Gebirgsjäger Grelin Weißbart, entsendet Abenteurer, um junge Frostmanetrolle zu dezimieren, die sich in den südlichen Höhlen des Coldridgetals sammeln. Da der Senat von Eisenschmiede durch eine eskalierende Trogg-Krise gebunden ist, müssen einsame Späher und bereitwillige Rekruten Grenzgefechte austragen, bevor die Trolle dauerhaft Fuß fassen.",h="Diese Mission, vergeben vom Gebirgsjäger Grelin Weißbart, entsendet Abenteurer, um junge Frostmanetrolle zu...",kw={"das coldridgetal","dun morogh","frostmane","grelin weißbart","troggs","trolle","welpe"},ang={["class:Hunter"]="Die Klippen um die südliche Höhle sind ein hartes Übungsgelände für junge Fährtenleser, die lernen, feindselige Beute aus den Höhen der Berge aufzuschrecken.",["race:Dwarf"]="Für junge Bronzebeard-Zwerge, die ihre ersten Schritte in den Schnee setzen, ist das Niederschlagen von Frostmane-Kriegstrupps sowohl eine Frage der Grenzsicherheit als auch eine uralte Bergfehde.",["race:Gnome"]="Nachdem sie nach dem Fall von Gnomeregan in Dun Morogh Zuflucht gefunden haben, stellen die Gnome ihren Scharfsinn und ihre Waffen gerne zur Verfügung, um ihren zwergischen Gastgebern bei der Abwehr umliegender Bedrohungen zu helfen."},sec={{t="Augen in der Kälte",b="Während die regulären Streitkräfte von Eisenschmiede vollauf damit beschäftigt sind, die Übergriffe der Felsbackentroggs in den Schneefeldern abzuwehren, dürfen die südlichen Zugänge nicht unbewacht bleiben. Grelin Weißbart und sein Bruder Senir wurden von den Gebirgsbehörden entsandt, um zu prüfen, ob die einheimischen Eistrolle eine unmittelbare Gefahr für das Kernland darstellen. Auf einer Klippe über dem gefrorenen Tal behält Grelin ihre Bewegungen einsam im Auge."},{t="Ein Präventivschlag",b="Grelins Erkundungen ergaben, dass sich der örtliche Frostmane-Klan in einer tiefen Höhle entlang des südlichen Gebirgskamms des Coldridgetals niedergelassen hat. In der Überzeugung, eine vollständige militärische Mobilisierung wäre eine unnötige Verschwendung zwergischer Streitkräfte, zog der Späher es vor, fähige Freiwillige vor Ort anzuheuern, um die aggressiven Welpen zu dezimieren. Das Ausdünnen ihrer jungen Krieger dient dazu, ihr Lager zu zerschlagen, bevor die Frostmane koordinierte Angriffe auf nahegelegene zwergische Gehöfte starten können."}},faq={{q="Warum schickt Eisenschmiede keine regulären Soldaten gegen diese Trolle?",a="Der Senat von Eisenschmiede und das zwergische Militär sind durch eine plötzliche, verheerende Trogg-Invasion in ganz Dun Morogh stark überlastet. Kleinere Bedrohungen wie kleine Trollkriegstrupps werden Spähern wie Grelin Weißbart überlassen, die unabhängige Abenteurer anheuern, um sich darum zu kümmern.",al={"warum keine zwergenarmee","wo sind die wachen","warum abenteurer anheuern"}},{q="Wer sind die Frostmanetrolle?",a="Die Frostmane sind ein einheimischer Stamm von Eistrollen aus den frostigen Klippen von Dun Morogh. Sie stehen den Bronzebeard-Zwergen seit Langem feindselig gegenüber und geraten mit den Gebirgsjägern immer wieder wegen Jagdgründen, Territorien und uralten Bergpässen aneinander.",al={"frostmane klan","dun morogh trolle","wer sind die frostmane"}},{q="Wo befindet sich die Trollhöhle?",a="Die Höhle liegt versteckt am südlichen Gebirgskamm des Coldridgetals, südlich von Grelin Weißbarts Beobachtungslager.",al={"standort der trollhöhle","wo ist die höhle","wo sind die welpen"}},{q="Wer ist Grelin Weißbart?",a="Grelin Weißbart ist ein Späher aus Eisenschmiede, der im Coldridgetal stationiert ist. Zusammen mit seinem Bruder Senir, der andere Ecken von Dun Morogh überwacht, verfolgt Grelin feindselige Trollpopulationen, um den zwergischen Anführern Bericht zu erstatten.",al={"grelin","questgeber","whitebeard"}},{q="Warum zielt Grelin gezielt auf Frostmanewelpen ab?",a="Das Lager im südlichen Coldridgetal ist eine aufkeimende Siedlung voller heranwachsender Krieger. Die Beseitigung ihrer heranwachsenden Kämpfer verhindert, dass die Gruppe stark genug wird, um zwergische Nachschublinien zu bedrohen.",al={"warum welpen","warum junge trolle ins visier nehmen"}},{q="Was geschieht nach dem Säubern der Höhle?",a="Nach Eurer Rückkehr stellt Ihr fest, dass die Trolle in der Nacht Vergeltung geübt, Grelins Lager überfallen und sein persönliches Felttagebuch gestohlen haben, was einen sofortigen Bergungseinsatz tiefer in ihren Höhlen erfordert.",al={"was als nächstes","folgequest trollhöhle"}}},fx={["9e422164"]={q="Warum will Grelin Weißbart, dass man sich um die Trolle kümmert?",a="Grelin und sein Bruder Senir wurden durch Das Coldridgetal entsandt, um zu beurteilen, ob die einheimischen Frostmähneneistrolle eine ernsthafte Bedrohung für das Reich darstellen. Da der Senat von Eisenschmiede bereits durch den Aufstand der Troggs andernorts überlastet ist, hofft Grelin, diese Ansammlung im Keim zu ersticken, bevor sie zu einer Krise eskaliert, die reguläre Truppen erfordert.",al={"warum die trolle töten","grelin weißbart motiv","warum die trollhöhle säubern"}}},fp="14,348,16.431.0,19.464.0,70.270.0,29.237.0,32.120.0,25.216.0,53.218.0,36.197.1"}
P.entries["quest:1820"] = {n="Gespräch mit Coleman",s="Gespräch mit Coleman ist eine Übergangsaufgabe in Tirisfal, die Recken angeboten wird, die ihren Wert gegen die Geißel unter Beweis gestellt haben. Todeswache Dillinger schickt fähige Krieger vom Dorfplatz zur örtlichen Taverne, um Coleman Heller bei persönlichen und fraktionellen Rachefeldzügen beizustehen.",h="Gespräch mit Coleman ist eine Übergangsaufgabe in Tirisfal, die Recken angeboten wird, die ihren Wert gegen...",kw={"agamand","brill","coleman heller","todeswache dillinger","verlassene","taverne zur galgenfrist","horde","tirisfal"},ang={["faction:Horde"]="Für Reisende, die bei der Sicherung von Lordaeron helfen, bietet die Kontaktaufnahme mit den örtlichen Dorfbewohnern in Brill einen wichtigen Ausgangspunkt für Einsätze in ganz Tirisfal.",["race:Undead"]="Viele Verlassene hegen neben ihrer Treue zur Dunklen Fürstin auch persönliche Rachegelüste; die Bitten von Coleman Heller spiegeln wider, wie persönlicher Verlust und die Verteidigung des Reiches in Tirisfal ineinandergreifen."},sec={{t="Ein Wort der Wache",b="Nachdem sie bei der Eindämmung ernster örtlicher Bedrohungen geholfen haben – wie etwa der Beseitigung gefährlicher Überreste der Geißel wie Ulag der Spalter –, erlangen Abenteurer das persönliche Vertrauen von Todeswache Dillinger. Als einer der Wächter über die Straßen nach Brill beurteilt Dillinger, wer mehr als routinemäßige Patrouillen an den Außengrenzen bewältigen kann, und verweist fähige Kämpfer an Bürger, die spezialisierte Dienste benötigen."},{t="Eine private Fehde",b="Nicht jeder Konflikt in Tirisfal wird auf Befehl der obersten Führung aus Unterstadt ausgetragen. Im gesamten zerstörten Königreich Lordaeron hegen überlebende Untote tiefen Groll, der mit dem Land, ihren Familien und dem Vermögen verbunden ist, das sie zurückgelassen haben. Coleman Heller wartet in der Taverne 'Zur Galgenfrist' auf seine Gelegenheit und sucht nach einem Werkzeug der Rache, um gegen die Bedrohungen zurückzuschlagen, die in der Nähe ehemaliger Siedlungen wie Agamands Mühlen verweilen."}},faq={{q="Wo finde Ich Coleman Heller?",a="Coleman Heller wartet in der Taverne 'Zur Galgenfrist' auf der Ostseite des Dorfes Brill in Tirisfal.",al={"coleman heller aufenthaltsort","wo ist coleman heller","farthing brill finden"}},{q="Wer schickt Euch, um mit Coleman zu sprechen?",a="Todeswache Dillinger, der den Zugangsweg nach Brill bewacht, schickt Euch zu Coleman, sobald Ihr Euer kriegerisches Können unter Beweis gestellt habt.",al={"wer gibt gespräch mit coleman","dillinger quest"}},{q="Welche Art von Arbeit hat Coleman Heller?",a="Coleman sucht einen fähigen Kämpfer, der den Feinden der Verlassenen als Werkzeug der Rache dient, insbesondere im Hinblick auf Angelegenheiten rund um die alten Agamand-Besitztümer.",al={"was coleman will","coleman heller aufgabe"}},{q="Welche Voraussetzungen müssen vor Erhalt dieser Aufgabe erfüllt sein?",a="Todeswache Dillinger verweist Euch erst an Coleman, wenn Ihr Eure Loyalität und Euer Kampfgeschick gegenüber den Verlassenen durch den Sieg über Ulag der Spalter bewiesen habt.",al={"voraussetzungen für gespräch mit coleman","ulag voraussetzung"}},{q="Gewährt diese Mission direkt nennenswerte Belohnungen?",a="Dieser Auftrag bringt Euch lediglich mit Heller in der Taverne zusammen und eröffnet seine persönliche Questreihe, anstatt selbst nennenswerte Ausrüstung oder Münzen zu gewähren.",al={"gespräch mit coleman belohnungen","lohnt es sich"}},{q="Was ist die Taverne 'Zur Galgenfrist'?",a="Die Taverne 'Zur Galgenfrist' ist das zentrale Gasthaus von Brill und dient als Treffpunkt, Raststätte und informelles Zentrum für private Aufträge unter den örtlichen Untoten.",al={"brill taverne","taverne zur galgenfrist"}}},fx={["75bd5c35"]={q="Warum will Todeswache Dillinger, dass ich mit Coleman spreche?",a="Todeswache Dillinger erkennt an, dass Ihr Eure Stärke und Loyalität gegenüber der Dunklen Fürstin unter Beweis gestellt habt, indem Ihr die Bedrohungen in Brill bewältigt habt. Coleman Heller hat persönliche Beschwerden und benötigt einen fähigen Kämpfer, um an den Feinden der Verlassenen Rache zu üben. Indem er Euch an ihn verweist, stellt Dillinger sicher, dass fähige Champions ihre Mitbürger unterstützen und gleichzeitig die Sicherheit des Reiches insgesamt fördern.",al={"warum zu coleman schicken","dillinger motiv sprich mit coleman","warum coleman heller treffen"}},["5d6ae549"]={q="Warum schickt mich Todeswache Dillinger, anstatt Colemans Bitte selbst zu bearbeiten?",a="Dillinger ist eine Todeswache, die stationiert ist, um den Stadtperimeter von Brill gegen unmittelbare Bedrohungen wie die Geißel zu bewachen. Er kann seinen Posten nicht verlassen, um die persönlichen Vendetten oder privaten Anliegen der örtlichen Stadtbewohner zu lösen. Ihr habt Euer kämpferisches Können und Eure Unabhängigkeit unter Beweis gestellt, was Euch zum idealen Agenten macht, um Coleman Heller direkt zu unterstützen.",al={"warum ich coleman","warum nicht dillinger","warum dillinger euch schickt"}}},fp="18,283,21.406.0,18.413.0,34.123.0,33.132.0,45.174.0,57.145.0,53.164.0,32.162.0"}
P.entries["quest:1821"] = {n="Agamand-Erbstücke",s="Coleman Heller beauftragt Abenteurer damit, die Gruft der Familie Agamand am nördlichen Ende von Agamands Mühlen zu plündern. Getrieben von bitterem Groll über sein sterbliches Ableben versucht er, seinen ehemaligen Herren ihre Erbwaffen zu entreißen und die letzten Reste ihrer Würde auszulöschen.",h="Coleman Heller beauftragt Abenteurer damit, die Gruft der Familie Agamand am nördlichen Ende von Agamands...",kw={"gruft der familie agamand","agamand-erbstücke","agamands mühlen","coleman heller","erbwaffe","geißel","tirisfal"},ang={["class:Rogue"]="Sich an lauernden Ghulen vorbeizuschleichen, um uralte Waffen aus bewachten Grabkammern zu entwenden, ist für heimliche Kundschafter eine Selbstverständlichkeit.",["faction:Horde"]="Die Säuberung der Gruft schwächt den festen Griff der Geißel über das nördliche Tirisfal und macht das Land sicherer für Reisende der Horde.",["race:Undead"]="Coleman Hellers verbitterte Quest verkörpert den anhaltenden Groll und die unverheilten Wunden, die viele Verlassene aus ihrem sterblichen Leben in den Untod hinübertragen."},sec={{t="Der bittere Groll eines Dieners",b="Bevor der Dritte Krieg Lordaeron verwüstete, diente Coleman Heller der wohlhabenden und einflussreichen Familie Agamand auf ihren weitläufigen Mühlen in Tirisfal. Was auch immer während des Untergangs ihres Anwesens geschah, Heller gibt seinen einstigen Dienstherren die alleinige Schuld an seinem Tod. Nun unter den Verlassenen zum Untod erweckt, betrachtet er den Niedergang der Agamands mit boshafter Genugtuung und frohlockt darüber, dass die einst stolze Dynastie zu geistlosen Dienern herabgewürdigt wurde, die dem Lichkönig versklavt sind."},{t="Entweihung der Gruft",b="Um das verbliebene Ansehen der Familie endgültig zu tilgen, schickt Heller Abenteurer in die Gruft der Familie Agamand, die unter den nördlichen Klippen der Mühlen liegt. In ihren heimgesuchten steinernen Hallen wandeln die rastlosen Toten an der Seite verbliebener Geißeltruppen. Heller verlangt die Bergung von vier geschichtsträchtigen Relikten – das Schwert, die Axt, der Dolch und der Streitkolben der Familie Agamand –, um sicherzustellen, dass das Vermächtnis ihrer Blutlinie auch des letzten Funzens Ehre beraubt wird."}},faq={{q="Wer war Coleman Heller zu Lebzeiten?",a="Coleman Heller war vor der Invasion der Geißel in Lordaeron ein Gefolgsmann im Dienst der wohlhabenden Familie Agamand auf Agamands Mühlen. Er starb während der Katastrophe und gibt seinen Herren die Schuld an seinem Ableben, wobei er eine tiefe Bitterkeit hegt, die bis in seinen Untod fortdauert.",al={"wer ist coleman heller","coleman hintergrundgeschichte","farthing geschichte"}},{q="Warum will Coleman Heller die Erbstücke?",a="Heller trachtet nach vollständiger Rache an seinen früheren Herren. Indem er ihr ererbtes Schwert, ihre Axt, ihren Dolch und ihren Streitkolben aus der Familiengruft plündert, will er dem gefallenen Geschlecht auch die letzten Spuren von Ehre und Andenken nehmen.",al={"warum erbstücke stehlen","coleman motiv","warum waffen nehmen"}},{q="Was geschah mit der Familie Agamand?",a="Die Familie Agamand kam um, als die Geißel über Tirisfal hinwegfegte. Statt im Tod Frieden zu finden, wurden sie als geistlose untote Knechte erweckt, die an den Willen des Lichkönigs gebunden sind und durch ihre zerstörten Mühlen und die Gruft streifen.",al={"schicksal der agamands","leben die agamands","was sind die agamands jetzt"}},{q="Wo befindet sich die Gruft der Familie Agamand?",a="Die Gruft liegt am nördlichen Rand von Agamands Mühlen, eingebettet in die felsigen Klippen über den verheerten Gehöften im nördlichen Tirisfal.",al={"gruft standort","wo ist die gruft","agamand gruft karte"}},{q="Welche Waffen werden in der Gruft aufbewahrt?",a="Die Gruft birgt vier verschiedene Erbwaffen der Blutlinie: das Schwert der Familie Agamand, die Axt der Familie Agamand, den Dolch der Familie Agamand und den Streitkolben der Familie Agamand.",al={"welche erbstücke","vier erbstücke","agamand waffen"}},{q="Warum greifen die Verlassenen die Agamands an, wenn beide untot sind?",a="Die Verlassenen besitzen einen freien Willen und kämpfen um ihr eigenes Überleben, wohingegen die untoten Agamands geistlose Sklaven der Geißel bleiben und dem Lichkönig dienen, den die Verlassenen verabscheuen.",al={"untote gegen untote","warum agamands bekämpfen","konflikt verlassene geißel"}}},fx={c3afbf3e={q="Was wird Coleman Heller mit den Agamand Heirlooms tun?",a="Für Coleman Heller repräsentieren die vier Waffen – das Schwert der Familie Agamand, die Axt, der Dolch und der Streitkolben – die letzten Überreste des Stolzes und der Abstammung seiner ehemaligen Meister. Indem er ihr Grab schändet und sie an sich nimmt, raubt er den verfluchten Ländereien von Agamand die letzten Überreste von Ehre und Erinnerung und erklärt, dass die Familie tatsächlich nicht mehr existiert.",al={"nutzen der agamand heirlooms","wofür sind die heirlooms","zweck der waffen der familie agamand"}},c1f9d064={q="Wer bewacht die Gruft der Familie Agamand?",a="Die Gruft und die umliegenden Mühlen sind von gedankenlosen Schergen der Geißel befallen, einschließlich der wiederbelebten Überreste der Familie Agamand selbst. An den Willen des Lichkönigs gebunden, statt freiwillige Verlassene zu sein, lauern diese Untoten in den dunklen Gräbern ihrer Vorfahren und bewachen die Familienreliquien erbittert gegen jeden Eindringling.",al={"feinde in der agamandgruft","wer beschützt die heirlooms","monster in der agamandgruft"}}},fp="17,272,25.468.0,21.443.0,33.266.0,45.219.0,36.230.0,42.144.0,39.181.0,63.180.0"}
P.entries["quest:1824"] = {n="Prüfung auf dem Feld der Riesen",s="Prüfung auf dem Feld der Riesen ist eine Kriegerriten-Quest, die von Ruga Rachtotem in Camp Taurajo vergeben wird. Als Teil ihrer Ausbildung werden Kriegeraspiranten nach Süden in die wimmelnden Hügel auf dem Feld der Riesen entsandt, um fremdartige insektoide Invasoren zu erschlagen. Die Kandidaten müssen mehrere noch zuckende Fühler erbeuten und sie eilig zurückbringen, ehe der biologische Beweis erstarrt.",h="Prüfung auf dem Feld der Riesen ist eine Kriegerriten-Quest, die von Ruga Rachtotem in Camp Taurajo vergeben...",kw={"brachland","camp taurajo","feld der riesen","ruga rachtotem","silithiden","zuckender fühler","kriegerprüfung"},ang={["class:Warrior"]="Diese Prüfung bildet einen wesentlichen Übergangsritus um Stufe zwanzig herum und stellt die Fähigkeit eines Kriegers auf die Probe, wimmelnde Widersacher zügig zu beseitigen und unter strengem Zeitdruck körperliche Ausdauer zu beweisen.",["faction:Horde"]="Die Horde behält die wachsende Präsenz der Silithiden im südlichen Brachland wachsam im Auge und nutzt einzelne Trainingsprüfungen als Vorpostenaufklärung gegen eine schleichende Bedrohung.",["race:Tauren"]="Für die Verteidiger der Tauren trägt die Säuberung des geschändeten Felds der Riesen dazu bei, ihre Jagdgründe rund um Camp Taurajo vor einem unnatürlichen, invasiven Schwarm zu schützen."},sec={{t="Eine Prüfung von Schnelligkeit und Stahl",b="Kriegerausbilder der Horde begnügen sich selten mit bloßem kriegerischem Geschick, ohne auch Entschlossenheit und Schnelligkeit auf die Probe zu stellen. Ruga Rachtotem fordert heranwachsende Krieger in Camp Taurajo dazu heraus, sich gegen einen ungewohnten Widersacher zu beweisen. Die Aspiranten sollen die vordringenden Kreaturen nicht bloß erschlagen; sie müssen frische Fühler abtrennen und innerhalb einer halben Stunde nach Taurajo zurückkehren, ehe das erbeutete Gewebe aufhört zu zucken, was eine rasche Durchquerung des südlichen Brachlands erfordert."},{t="Unerwünschte Eindringlinge",b="Das Ziel der Prüfung sind die Silithidenschwärme, die sich auf dem Feld der Riesen unter gewaltigen, versteinerten Rippenbögen ausbreiten. Diese kriechenden, chitinharten Insekten sind erst kürzlich im Brachland aufgetaucht und beunruhigen die Jäger und Schamanen der Tauren, die über die Savannen wachen. Ruga bemerkt mit Grauen, dass ihre Anwesenheit nichts Gutes für Kalimdor verheißt, wodurch der Ausrottungstest einem doppelten Zweck dient: Er stellt die Kampfinstinkte eines jungen Kriegers auf die Probe und liefert zugleich Erkenntnisse über eine heraufziehende ökologische Bedrohung."}},faq={{q="Warum gibt es ein Zeitlimit für die Fühler?",a="Ruga Rachtotem verlangt, dass die Fühler noch zucken, wenn sie nach Camp Taurajo gebracht werden, was den Kriegern nur dreißig Minuten Zeit lässt, um die Jagd abzuschließen und den Rückweg anzutreten. Die biologische Frische stellt sicher, dass der Aspirant den Silithiden rasch im direkten Kampf bezwungen hat, anstatt tote Panzer abzusuchen.",al={"warum mit zeitlimit","zuckende fühler zeitbegrenzung","wie viel zeit"}},{q="Welche Kreaturen leben auf dem Feld der Riesen?",a="Das Feld der Riesen wird von Silithiden heimgesucht, einer bizarren und aggressiven Brut insektoider Gräber. Sie haben gewaltige Erdhügel und Schwärme unter uralten Fossilien ausgehoben, wodurch sie die örtliche Ökologie stören und die Horde alarmieren.",al={"was sind das für käfer","feld der riesen gegner","was sind silithiden"}},{q="Wer ist Ruga Rachtotem?",a="Ruga Rachtotem ist ein Kriegerausbilder der Tauren, der in Camp Taurajo im südlichen Brachland stationiert ist. Er überwacht Prüfungen, die das Geschick, die Zähigkeit und das Tempo von Hordekriegern testen, die ihr Ansehen mehren wollen.",al={"ruga","wer gibt die quest","ruga rachtotem lore"}},{q="Wo befindet sich das Feld der Riesen?",a="Das Feld der Riesen liegt direkt südlich von Camp Taurajo und flankiert den Weg vor dem südlichen Pass, der nach Tausend Nadeln führt. Man erkennt es an den emporragenden skelettartigen Rippenbögen und den Hügeln der Silithiden.",al={"wo ist das feld der riesen","feld der riesen aufenthaltsort","wo finde ich die insekten"}},{q="Wohin führt diese Ausbildungsreihe als Nächstes?",a="Sobald die zuckenden Fühler rechtzeitig abgeliefert wurden, trägt Ruga dem Krieger auf, mit Thun'grim Feuerblick zu sprechen – einem alten Orkschmied auf einem Hügel östlich vom Wegekreuz, der für bewährte Krieger eine Rüstung schmiedet.",al={"folgequest","was kommt danach","fortsetzung kriegerquestreihe"}},{q="Warum sind die Tauren wegen der Insekten besorgt?",a="Die Silithiden sind unnatürliche Neuankömmlinge im Brachland. Ruga erklärt, dass ihr Erscheinen Unheil über das Land bringt, und vermutet, dass ihr aggressives Graben und ihre Ausbreitung eine weitaus größere Gefahr ankündigen, die sich unter dem Sand regt.",al={"warum sorgt das die tauren","insektenboten","silithidengefahr"}}},fx={["5312a899"]={q="Warum will Ruga Rachtotem, dass dies erledigt wird?",a="Ruga Rachtotem testet Eure kriegerische Entschlossenheit als Teil Eurer Kriegerausbildung, während er ein Auge auf eine aufkommende Bedrohung hat. Seltsame insektoide Kreaturen sind kürzlich im Feld der Riesen aufgetaucht und haben die örtlichen Tauren beunruhigt. Indem er Euch schickt, um sie schnell auszudünnen und frische Trophäen zurückzubringen, bevor sie aufhören zu zucken, testet Ruga Euer kämpferisches Können, Eure Geschwindigkeit und Eure Ausdauer im Feld.",al={"ruga rachtotem motiv","warum prüfung am feld der riesen","warum schickt ruga euch"}},["2d3c0cc0"]={q="Warum braucht Ruga Rachtotem Euch anstelle der Lagerwachen?",a="Diese Mission ist ein persönlicher Initiationsritus, der speziell für einen aufstrebenden Krieger unter Rugas Obhut entwickelt wurde. Die Lagerwachen sind damit beschäftigt, Camp Taurajo zu verteidigen und die nahegelegenen Grenzen zu beobachten, wohingegen das Überleben harter, einsamer Prüfungen gegen gefährliche Raubtiere die Art und Weise ist, wie Ihr beweist, dass Ihr bereit seid, den größeren Pfad des Kriegers zu beschreiten.",al={"warum ich prüfung der riesen","warum einen abenteurer zu ruga schicken"}}},fp="28,361,25.458.0,19.485.0,42.297.0,43.221.0,22.208.0,37.205.0,41.226.0,47.220.0"}
P.entries["quest:1825"] = {n="Gespräch mit Thun'grim",s="Diese Aufgabe führt aufstrebende Krieger der Horde zu Thun'grim Brandblick, einem angesehenen Orkschmied, der sein Lager im Brachland aufgeschlagen hat. Nachdem sie sich in anspruchsvollen körperlichen Prüfungen bewährt haben, werden die Krieger eingeladen, sich in Anerkennung ihrer Tapferkeit eine maßgefertigte Rüstung schmieden zu lassen. Die Quest dient als entscheidende Brücke zwischen den allgemeinen Kriegerprüfungen und der Herstellung der Brutalen Rüstung.",h="Diese Aufgabe führt aufstrebende Krieger der Horde zu Thun'grim Brandblick, einem angesehenen Orkschmied, der...",kw={"brachland","brutale rüstung","das wegekreuz","firegaze","ragetotem","ruga","thun'grim","krieger"},ang={["class:Warrior"]="Diese Quest markiert einen wichtigen Übergangsritus, der Euch vom einfachen Kämpfer zu einem anerkannten Champion erhebt, der eine maßgeschmiedete Rüstung verdient.",["faction:Horde"]="Die Rüstungsschmiede der Horde sind stolz darauf, ihre wildesten Verteidiger auszurüsten und sicherzustellen, dass jene, die an vorderster Front kämpfen, Ausrüstung tragen, die ihren Taten auf dem Schlachtfeld gerecht wird.",["profession:Blacksmithing"]="Thun'grim Brandblick verkörpert die traditionelle orkische Schmiedephilosophie, nach der meisterhafte Rüstungen durch kriegerische Prüfungen und nicht durch bloßes Gold verdient werden müssen."},sec={{t="Der Ruf des Schmieds",b="Nachdem sie ihren Mut während der Prüfung auf dem Feld der Riesen gegen die Silithidenschwärme bewiesen haben, verdienen sich die Krieger der Horde mehr als nur schlichtes Lob von Ruga Rachtotem. Die Kunde von ihrer Ausdauer und ihrem kriegerischen Können erreicht rasch Thun'grim Brandblick, einen namhaften Orkschmied, der auf einem Bergrücken östlich des Wegekreuzes lagert. In der Erkenntnis, dass dieser Krieger seines Handwerks würdig ist, lässt Thun'grim ausrichten, dass er ihm eine außergewöhnliche Schlachtrüstung schmieden möchte."},{t="Der Maßstab eines Meisters",b="Thun'grim Brandblick schmiedet nicht für gewöhnliche Soldaten. Für einen Rüstungsschmied seines Rufs muss der Stahl dem Geist dessen entsprechen, der ihn in die Schlacht führt. Das Erreichen seines Lagers bedeutet, dass ein Krieger den einfachen Milizübungen entwachsen und bereit ist, die zermürbenden, spezialisierten Aufgaben auf sich zu nehmen, die für das Beschaffen seltener Handwerksreagenzien in ganz Kalimdor erforderlich sind."}},faq={{q="Wer ist Thun'grim Brandblick?",a="Thun'grim Brandblick ist ein angesehener Orkschmied, der auf einem felsigen Bergrücken östlich des Wegekreuzes im Brachland sein Lager hat. Er schmiedet maßgefertigte, gewaltige Rüstungen für Krieger der Horde, die ihren Mut in gefährlichen Prüfungen unter Beweis gestellt haben.",al={"wer ist thungrim","thungrim lore","thungrim firegaze"}},{q="Warum schickt Ruga Rachtotem mich zu ihm?",a="Ruga Rachtotem erkennt, dass Ihr den einfachen Prüfungen entwachsen seid, nachdem Ihr die Silithiden im südlichen Brachland überlebt habt. Er schickt Euch zu Thun'grim, damit der Meisterschmied Eure Dienste für die Horde mit dem Schmieden einer spezialisierten Rüstung belohnen kann.",al={"warum mit thungrim sprechen","ruga schickt mich"}},{q="Wo kann ich Thun'grims Lager finden?",a="Thun'grim schlägt sein Lager auf den hohen Klippen östlich des Wegekreuzes im Brachland auf, von wo aus er die trockene Savanne überblickt.",al={"wo ist thungrim","thungrim aufenthaltsort","thun'grim brandblick finden"}},{q="Was geschieht nach dem Gespräch mit Thun'grim?",a="Das Treffen mit Thun'grim leitet die Questreihe um die Brutale Rüstung ein und führt Krieger in ferne Länder, um zähe Materialien wie rauchige Eisenbarren und normale Eisenbarren zu sammeln, aus denen ein maßgeschneidertes Kettenharnisch gefertigt wird.",al={"folgequest nach thungrim","was will thungrim"}},{q="Ist diese Quest für alle Klassen verfügbar?",a="Nein. Diese Quest und die dazugehörige Rüstungsreihe sind strikt Teil der kriegerischen Ausbildung, die Kriegern der Horde vorbehalten ist.",al={"können nicht-krieger das machen","nur für krieger"}},{q="Welche Prüfung war vor diesem Treffen erforderlich?",a="Vor diesem Botengang mussten die Krieger in das südliche Brachland reisen, um die Prüfung auf dem Feld der Riesen abzuschließen, bei der sie zuckende Silithidenfühler sammelten, um ihr Durchhaltevermögen im Kampf zu beweisen.",al={"vorquest","was habe ich davor gemacht"}}},fx={["2df90612"]={q="Warum schickt Ruga Rachtotem Euch, anstatt selbst zu gehen?",a="Ruga Rachtotem überwacht die Ausbildung und Prüfung aufstrebender Krieger der Horde von seinem Posten in Camp Taurajo aus. Thun'grim Firegaze hat sich speziell an Euch gewandt, nachdem er von Eurer Tapferkeit und Euren Prüfungen im Brachland gehört hat. Ruga gibt die Aufforderung lediglich weiter, damit Ihr Rüstung beanspruchen könnt, die nach Eurem persönlichen Maß geschmiedet wurde.",al={"warum schickt ruga mich","warum ich ruga rachtotem","warum braucht ruga mich"}}},fp="20,365,21.456.0,19.360.0,26.226.0,39.239.0,34.116.0,43.192.0,39.124.0,44.189.0"}
P.entries["quest:183"] = {n="Der Eberjäger",s="Der Eberjäger ist ein früher Auftrag des Zwergenjägers Talin Keeneye im Coldridgetal. Ein starker Anstieg der örtlichen Felseneberpopulation hat die Wälder überaus gefährlich gemacht, und junge Rekruten werden damit betraut, die aggressiven Bestien auszudünnen, damit erfahrene Jäger ungestört auf Fährtensuche gehen können.",h="Der Eberjäger ist ein früher Auftrag des Zwergenjägers Talin Keeneye im Coldridgetal.",kw={"ambossar","der eberjäger","das coldridgetal","felseneber","dun morogh","jagd","talin keeneye"},ang={["class:Hunter"]="Talin Keeneye verkörpert die geradlinige Haltung der Zwerge gegenüber der Fährtensuche: Zielt stets genau, achtet die Bestien und lichtet das Unterholz, wenn das Wild zu feindselig wird.",["race:Dwarf"]="In den Bergen zu leben bedeutet, das Land mit unerbittlichen Wildtieren zu teilen. Das Ausdünnen der angriffslustigen Felseneber rund um Ambossar ist ein Initiationsritus für jeden jungen Zwerg, der seine ersten Schritte abseits der Schmiede wagt.",["race:Gnome"]="Für frisch aus Gnomeregan eingetroffene Gnomflüchtlinge ist die Konfrontation mit den wilden Ebern von Dun Morogh eine raue, praktische Einführung in das Leben im schroffen Reich der Zwerge."},sec={{t="Ein überfülltes Tal",b="Das Coldridgetal ist für gewöhnlich ein ruhiges, geschütztes Übungsgelände für junge Gebirgsjäger und Gelehrte aus Eisenschmiede. Im rauen Winterklima wird die Tierwelt jedoch oft unruhig und vermehrt sich übermäßig. Talin Keeneye, ein erfahrener Jäger vor Ambossar, stellt fest, dass sich die aggressiven kleinen Felseneber so rasch vermehrt haben, dass sie zu einer echten Bedrohung für jeden geworden sind, der die schneebedeckten Pfade beschreitet."},{t="Ordnung im Schnee",b="Die Jagd ist ein Grundpfeiler des zwergischen Lebens und liefert Fleisch, Leder sowie unverzichtbare Übung im Feldhandwerk. Doch wenn Wildtiere zur Plage werden und sofort angreifen, ist eine Bestandsminderung erforderlich, um das Gleichgewicht wiederherzustellen. Indem sie die Zahl der Felseneber an den Hängen des Tals verringern, beweisen junge Abenteurer ihre Kampfbereitschaft und verschaffen den Jägern vor Ort Raum, ihrem Handwerk nachzugehen, ohne überwältigt zu werden."}},faq={{q="Wer ist Talin Keeneye?",a="Talin Keeneye ist ein Zwergenjäger, der im Coldridgetal in der Nähe von Ambossar stationiert ist. Er verbringt seine Tage damit, Wildspuren im Schnee zu folgen, und hilft dabei, unerfahrene Abenteurer in den praktischen Grundlagen des Beseitigens feindseliger Bestien zu unterweisen.",al={"talin keeneye","wer gibt die quest der eberjäger","eberjäger nsc"}},{q="Warum stellen die Felseneber ein solches Problem dar?",a="Die kleinen Felseneber im Coldridgetal treten in ungewöhnlich großer Zahl auf und greifen jeden in Sichtweite grundlos an. Ihre Masse macht das gewöhnliche Reisen und Jagen für die Einheimischen gefährlich.",al={"warum eber töten","eberproblem coldridgetal","warum eber gefährlich sind"}},{q="Wo sind die Felseneber zu finden?",a="Kleine Felseneber streifen im gesamten Coldridgetal über die offenen Schneeflächen und durch die lichten Waldstücke rund um Ambossar.",al={"wo sind die eber","felseneber aufenthaltsort","kleiner felseneber karte"}},{q="Steht diese Quest mit einer größeren Bedrohung im Tal in Verbindung?",a="Nein. Im Gegensatz zu den Trogg-Plagen, die den Zwergenaußenposten zu schaffen machen, handelt es sich hierbei schlicht um eine örtliche Wildtierregulierung, um die Pfade sicher zu halten und Talin in Ruhe jagen zu lassen.",al={"gibt es eine folgequest","eberjäger questreihe","hintergrund der eber"}},{q="Was macht die Felseneber so gut geeignet für Dun Morogh?",a="Felseneber sind zähe Schweine mit dicker Haut, die den eisigen Temperaturen von Dun Morogh trotzen. Dank ihres aggressiven Gemüts und ihrer scharfen Hauer können sie gefrorene Erde aufwühlen und Raubtiere des Gebirges abwehren.",al={"felseneber geschichte","zwergen eber","tierwelt von dun morogh"}},{q="Warum erlegt Talin Keeneye die Eber nicht selbst?",a="Talin merkt an, dass es so viele aggressive Eber gibt, dass seine gemütlichen Jagdausflüge unangenehm gefährlich geworden sind. Er spannt eifrige neue Abenteurer ein, die durch Ambossar reisen, um die Rotten auszudünnen, damit er wieder wie gewohnt auf Fährtensuche gehen kann.",al={"warum talin hilfe braucht","talin faul","warum talin sie nicht jagen kann"}}},fx={aa61ef91={q="Warum will Talin Keeneye, dass die kleinen Krag Eber ausgedünnt werden?",a="Talin Keeneye betrachtet die Eberjagd als einen schönen Zeitvertreib, aber die schiere Anzahl der kleinen Krag Eber, die Das Coldridgetal befallen, hat seinen Sport ruiniert. Ihre aggressive Natur und ihre explosionsartige Anzahl haben seine tägliche Routine eher gefährlich als entspannt gemacht. Indem Ihr ein Dutzend der Biester ausdünnt, stellt Ihr etwas Sicherheit im Tal wieder her, sodass er seine Jagd genießen kann, ohne ständig umschwärmt zu werden.",al={"warum eber töten","talin keeneye motiv","warum muss talin eber tot sehen"}},cf0c4f7e={q="Was sind kleine Krag Eber und warum sind sie im Das Coldridgetal?",a="Kleine Krag Eber sind die robusten, einheimischen Schweine von Dun Morogh, die von Natur aus mit dickem Fell und hitzigem Temperament ausgestattet sind, um im frostigen Bergland zu überleben. Das Coldridgetal bietet reichlich Nahrung entlang der verschneiten Ausläufer, aber in letzter Zeit ist ihre Population so dramatisch angestiegen, dass sie überall umherstreifen und jeden aggressiv angreifen, der sich nähert.",al={"was sind krag eber","warum sind hier eber","lore der kleinen krag eber"}}},fp="15,279,16.412.0,17.384.0,21.214.0,38.203.0,34.120.0,57.168.0,43.215.0,49.224.0"}
P.entries["quest:1838"] = {n="Brutale Rüstung",s="Brutale Rüstung ist ein Übergangsritus für Krieger der Horde, der vom nahezu erblindeten Schmied Thun'grim Brandblick im nördlichen Brachland überwacht wird. Mit dem Ziel, eine Rüstung zu schmieden, die eines aufstrebenden Champions würdig ist, schickt Thun'grim erfahrene Krieger durch ferne Länder, um seltene Reagenzien und exotische Schmelzmittel zu beschaffen. Das Erfüllen seiner Schriftrolle leitet das Schmieden einer vollständigen Ausrüstung brutaler Kriegsrüstung ein.",h="Brutale Rüstung ist ein Übergangsritus für Krieger der Horde, der vom nahezu erblindeten Schmied Thun'grim...",kw={"brachland","brutale rüstung","brutale halsberge","phlogiston","pulverisierter azurit","rauchiger eisenbarren","thun'grim brandblick","kriegerquest"},ang={["class:Warrior"]="Diese Quest stellt einen prägenden Meilenstein für Krieger der Horde dar und beweist ihre Tapferkeit sowie Ausdauer über mehrere Kontinente hinweg, um sich eine maßgeschmiedete Kampfrüstung zu verdienen.",["faction:Horde"]="Die Rüstungen der Brutalen Rüstung sind ein Zeugnis der Solidarität der Horde und vereinen die unverwechselbaren Handwerkstraditionen der Orc-, Tauren-, Troll- und Verlassenen-Schmiede in einem einzigen Kampfset.",["profession:Blacksmithing"]="Thun'grims Schriftrolle zeugt von fortgeschrittener metallurgischer Alchemie, indem sie rauchiges Eisen, pulverisierten Azurit und Phlogiston miteinander verbindet, um das herkömmliche Eisenschmelzen zu veredeln."},sec={{t="Die Berufung eines Meisters",b="Inmitten der zerklüfteten Hügel des nördlichen Brachlands lauscht der erfahrene Orcschmied Thun'grim Brandblick aufmerksam den Winden des Krieges. Obwohl seine Sehkraft nachlässt und getrübt ist, bleibt sein Ruf an der Esse unübertroffen. Nachdem er Gerüchte über einen Krieger vernommen hat, dessen Stärke und Tapferkeit die gewöhnlicher Soldaten übertreffen, beschließt Thun'grim, ein beständiges Kettenpanzerset zu schmieden, das selbst den härtesten Zusammenstößen in Kalimdor und den Östlichen Königreichen standhalten kann."},{t="Eine kontinentübergreifende Suche",b="Das Schmieden einer Rüstung dieses Kalibers erfordert weit mehr als gewöhnliches Erz. Bei schwachem Feuerschein und mit getrübten Augen verfasst Thun'grim eine anspruchsvolle Schriftrolle, in der die für das Kernstück – das Brustteil – benötigten Komponenten detailliert aufgeführt sind. Die Aufgabe verlangt nach gewöhnlichem veredeltem Eisen neben seltenen rauchigen Eisenbarren, die von grabenden Kobolden getragen werden, pulverisiertem Azurit, das von Bergleuten jenseits des Meeres abgebaut wird, und einer flüchtigen Phlogistonphiole. Nur ein Krieger, der bereit ist, weite Prüfungen auf sich zu nehmen, kann hoffen, die Rüstung zum Leben erweckt zu sehen."},{t="Der erste Hammerschlag",b="Die Lieferung dieser seltenen Vorräte ist erst der Anfang von Thun'grims Vision. Nachdem er die Materialien entgegengenommen und seinen Ofen angeheizt hat, um die Brutale Halsberge zu schmieden, erkennt der alte Schmied, dass ein Handwerker allein eine solch ehrgeizige Rüstkammer nicht vollenden kann. Die Erschaffung des vollständigen Sets erfordert die Hilfe von Meisterschmieden der anderen Hordevölker – eines Tauren-Helmformers, eines Troll-Handschuhmachers und eines untoten Beinschienenschmieds auf den verschiedenen Kontinenten."}},faq={{q="Wer ist Thun'grim Brandblick?",a="Thun'grim Brandblick ist ein geschätzter erfahrener Orcschmied, der auf einem Hügel über dem nördlichen Brachland lebt. Trotz seiner schwindenden Sehkraft sind seine Instinkte am Amboss scharf, und er fertigt mächtige, maßgeschneiderte Kriegsrüstungen für Hordekrieger, die sich durch Taten der Tapferkeit Ruhm erworben haben.",al={"wer ist thungrim","thun'grim brandblick lore","thungrim hintergrundgeschichte"}},{q="Was ist die Brutale Rüstung?",a="Die Brutale Rüstung ist ein berühmtes Set kampfgeschmiedeter Kettenrüstung, das speziell für erfahrene Krieger der Horde entworfen wurde. Geschmiedet durch das gesammelte Wissen von Hordeschmieden, erfordert jedes Teil gefährliche Reisen zur Beschaffung seltener alchemistischer Reagenzien, gereinigter Erze und uralter Techniken.",al={"was ist brutale rüstung","brutale rüstung set lore","krieger rüstungskette"}},{q="Warum benötigt Thun'grim so ungewöhnliche Zutaten?",a="Gewöhnliches Eisen ist zu spröde, um den schweren Schlägen standzuhalten, die ein Frontkämpfer einstecken muss. Exotische Reagenzien wie pulverisierter Azurit, rauchige Eisenbarren und flüchtiges Phlogiston dienen als Fluss- und Härtungsmittel, die es Thun'grim ermöglichen, das Metall mit enormer Widerstandskraft und Stärke zu versehen.",al={"warum pulverisierter azurit","warum phlogiston","wofür sind die reagenzien"}},{q="Schmiedet Thun'grim das gesamte Set selbst?",a="Nein. Thun'grim stellt die zentrale Halsberge selbst her, weist den Krieger jedoch an andere Kunsthandwerker in der gesamten Horde – darunter Orm Stonehoof, Ula'elek und Velora Nachtens –, um den passenden Helm, die Handschuhe und die Beinschützer zu fertigen.",al={"stellt thungrim alles her","wer stellt teile der brutalen rüstung her"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Der Abschluss dieser Prüfung führt direkt zum Schmieden der Brutalen Halsberge und eröffnet Wege, Schmiede in Donnerfels, Sen'jin und Unterstadt aufzusuchen, um den Rest der brutalen Kriegsrüstung zusammenzustellen.",al={"was kommt nach brutaler rüstung","brutale rüstung folgequest"}},{q="Warum muss ein Krieger für diese Materialien so weit reisen?",a="Die Prüfung ist sowohl ein Test kriegerischer Zähigkeit als auch eine Lektion in Einfallsreichtum. Um sich einer meisterhaft geschmiedeten Rüstung würdig zu erweisen, muss ein Krieger feindliches Gebiet durchqueren, in gefährliche Minen vordringen und Komponenten beschaffen, die für gewöhnliche Sterbliche unerreichbar sind.",al={"warum in die östlichen königreiche reisen","warum so viele materialien"}}},fx={["31952f55"]={q="Warum will Thun'grim Firegaze diese Rüstung herstellen?",a="Thun'grim hat von Eurem wachsenden Ruhm in der gesamten Horde gehört und möchte eine Rüstung anfertigen, die Eurer Stärke würdig ist. Für den alternden, fast blinden Schmied ist es eine Ehre und ein Beweis für sein eigenes Handwerk, legendäre Rüstungen zu schmieden, um einen aufstrebenden Krieger auf seiner Reise zu begleiten.",al={"warum hilft mir thungrim","thun'grim firegaze motiv","warum brutal armor herstellen"}},["8131a754"]={q="Warum muss Thun'grim Euch die Materialien sammeln lassen?",a="Thun'grim ist ein betagter Orc, dessen Sehkraft fast erloschen ist; er hat sich mehrere Nächte lang abgemüht, nur um Eure Anweisungen zu schreiben. Das Sammeln gefährlicher Reagenzien aus entfernten Minen und von wilden Tieren übersteigt seine physischen Fähigkeiten bei weitem und erfordert einen bewährten Krieger, um die Reise zu unternehmen.",al={"warum muss ich die materialien holen","warum ich brutal armor","warum braucht thungrim meine hilfe"}}},fp="12,365,18.438.0,26.474.0,30.423.1,26.284.0,21.277.0,49.286.0,44.234.1,38.221.1,61.236.0"}
P.entries["quest:1839"] = {n="Ula'elek und die brutalen Stulpen",s="Diese Quest führt aufstrebende Krieger der Horde von den Höhen des Brachlands zurück an die Küste von Durotar. Ausgesandt vom Schmied Thun'grim Brandblick müsst Ihr den Dunkelspeer-Handwerker Ula'elek in Sen'jin aufsuchen, um Eure brutalen Stulpen schmieden zu lassen.",h="Diese Quest führt aufstrebende Krieger der Horde von den Höhen des Brachlands zurück an die Küste von Durotar.",kw={"brutale stulpen","dunkelspeer","durotar","sen'jin","brachland","thun'grim brandblick","ula'elek","krieger"},ang={["class:Warrior"]="Die Questreihe um die brutale Rüstung stellt einen entscheidenden Übergangsritus für Krieger der Horde dar und markiert ihren Wandel zu kampferprobten Champions an vorderster Front.",["faction:Horde"]="Die Zusammenarbeit zwischen orcischen Meisterschmieden im Brachland und Trollschmieden in Durotar veranschaulicht den Zusammenhalt, der Thralls junge Koalition verbindet.",["race:Troll"]="Der Besuch bei Ula'elek unterstreicht den Beitrag des Dunkelspeer-Stammes zu den Kriegsanstrengungen der Horde durch geschickte Schmiedekunst und spirituelle Einstimmung."},sec={{t="Eine Reise an die Küste",b="Nachdem sie ihren Mut im gesamten Brachland unter Beweis gestellt und die Aufgabe übernommen haben, das Set der brutalen Rüstung zusammenzutragen, werden Krieger von Thun'grim Brandblick nach Osten geschickt. Anstatt jedes Teil auf seinem eigenen Bergposten zu schmieden, verlässt sich der erfahrene Orcschmied auf ein Netzwerk geschickter Handwerker in den Ländern der Horde. Um schwere Plattenstulpen herzustellen, die für einen aufstrebenden Champion geeignet sind, schickt er die Kämpfer hinab an Durotars felsige Südküste."},{t="Die Augen der Loa",b="In Sen'jin arbeitet der Troll-Rüstungsschmied Ula'elek inmitten seiner Dunkelspeer-Verwandten. Weit davon entfernt, unvorbereitet überrascht zu werden, offenbart Ula'elek, dass Thun'grim bereits Kunde von Euren Taten überbracht hatte – und was noch wichtiger ist: Die Geister selbst hatten Eure Triumphe im Kampf beobachtet. Für einen Krieger, der sich einen Platz unter der Elite der Horde verdient, gehen Handwerkskunst und spirituelle Anerkennung Hand in Hand."}},faq={{q="Wer vergibt die Quest „Ula'elek und die brutalen Stulpen“?",a="Die Quest wird von Thun'grim Brandblick vergeben, einem hochgeschätzten Orc-Rüstungsschmied, der sich auf den Bergen im Brachland befindet.",al={"questgeber","wer startet ula'elek und die brutalen stulpen","thun'grim brandblick quest"}},{q="Wo kann ich Ula'elek finden?",a="Ula'elek ist in Sen'jin an der Südküste von Durotar stationiert.",al={"ula'elek aufenthaltsort","wo ist ula'elek","ula'elek sen'jin"}},{q="Was ist das Set der brutalen Rüstung?",a="Die brutale Rüstung ist ein maßgefertigtes Set aus Ketten- und Plattenrüstung, das speziell für erfahrene Krieger der Horde um ihre dreißigste Jahreszeit entworfen und von verbündeten Schmieden in ganz Kalimdor gefertigt wurde.",al={"brutale rüstung","was sind brutale stulpen","krieger klassenrüstung 30"}},{q="Was geschieht, nachdem man Ula'elek erreicht hat?",a="Nachdem er Euch begrüßt und Eure Taten im Kampf gewürdigt hat, beauftragt Ula'elek Euch damit, die exotischen Materialien zu beschaffen, die für die Herstellung der brutalen Stulpen benötigt werden – beginnend mit Satyrhufen.",al={"folgequest","nach dem gespräch mit ula'elek","satyrhufe quest"}},{q="Warum schickt Thun'grim einen zu einem Troll-Rüstungsschmied?",a="Thun'grim verteilt das Schmieden des Sets der brutalen Rüstung auf die besten spezialisierten Schmiede der Horde und vertraut für die Stulpen auf Dunkelspeer-Handwerker wie Ula'elek.",al={"warum ula'elek","warum nach sen'jin","trollschmied brutale rüstung"}},{q="Haben Allianz-Spieler ein Gegenstück zu dieser Quest?",a="Allianz-Krieger absolvieren eine ähnliche kriegerische Prüfung, um ihre eigene klassenspezifische Rüstung herzustellen, aber die Questreihe um die brutale Rüstung und Ula'eleks Handwerkskunst sind exklusiv für die Horde.",al={"allianz brutale stulpen","allianz gegenstück"}}},fx={a664db53={q="Warum muss Thun'grim Firegaze Euch nach Sen'jin schicken?",a="Thun'grim Firegaze leitet Euer Wachstum als aufstrebender Krieger der Horde. Während er Eure Ausbildung überwacht, erfordert die alte Kunst des Schmiedens von Brutal Armor die speziellen Talente anderer Handwerker in den Ländern der Horde. Ula'elek in Sen'jin ist ein geschickter Rüstungsschmied der Dunkelspeer, der auf die Geister eingestimmt ist und dafür geeignet ist, die Handschuhe zu schmieden. Thun'grim schickt Euch persönlich, nicht nur, um das Stück in Auftrag zu geben, sondern um Eure Hingabe zu beweisen und das Vertrauen des Rüstungsschmieds direkt zu verdienen.",al={"warum ich ula'elek","warum kann thungrim keine handschuhe herstellen","warum krieger nach durotar schicken"}}},fp="33,247,22.423.0,19.383.0,54.108.0,26.87.0,29.179.0,37.185.0,50.160.0,53.176.0"}
P.entries["quest:184"] = {n="Brauenwirbels Urkunde",s="Brauenwirbels Urkunde ist eine gestohlene Landurkunde, die von Dieben der Defias im Wald von Elwynn mitgeführt wird. Die Rückgabe des Dokuments an den vertriebenen Bauer Brauenwirbel nahe der Grenze nach Westfall bietet dem fliehenden Paar die einzige Hoffnung, seinen geraubten Hof eines Tages zurückzufordern.",h="Brauenwirbels Urkunde ist eine gestohlene Landurkunde, die von Dieben der Defias im Wald von Elwynn...",kw={"defias","elwynn","furlbrow","theodore furlbrow","verna brauenwirbel","westfall","westfall urkunde"},ang={["class:Paladin"]="Die Rückgabe gestohlener Urkunden an mittellose Flüchtlinge verkörpert die heiligen Gelübde, die Wehrlosen zu verteidigen und Gerechtigkeit in gesetzlose Grenzlande zu bringen.",["faction:Alliance"]="Die Not der Furlbrows verdeutlicht das Versagen der Krone von Sturmwind, ihre steuerzahlenden Bürger jenseits der befestigten Mauern der Hauptstadt zu schützen."},sec={{t="Ein Hinweis auf gestohlenem Papier",b="Bei Zusammenstößen mit Banditen der Defias im gesamten Wald von Elwynn finden Reisende oft eine zerknitterte Landurkunde, unterzeichnet von Theodore und Verna Brauenwirbel. Auf der Rückseite des Pergaments enthüllt eine krakelige Handschrift den Plan der Banditen: Nachdem sie den betagten Bauern von seinem Land verjagt hatten, schmuggelten sie das Dokument über den Fluss nach Elwynn, um es als Vorlage für gefälschte Besitzurkunden für andere beschlagnahmte Ländereien zu nutzen. Die Notiz besagt auch, dass die Furlbrows kurz hinter der Grenze mit einem kaputten Wagen an der Straße gestrandet gesichtet wurden."},{t="Die Not der Bauern von Westfall",b="Der Verlust der Furlbrows steht sinnbildlich für die Tragödie, die Westfall heimsucht. Da die Armee von Sturmwind abwesend ist und die Ressourcen des Reiches schwinden, hat die Bruderschaft der Defias Dutzende Familien von ihrer angestammten Scholle vertrieben und sich mit Gewalt und juristischen Winkelzügen die Kontrolle über die Kornkammer des Königreichs gesichert. Obwohl Theodore und Verna ihren Hof zu ihrer eigenen Sicherheit aufgeben, bewahrt der rechtmäßige Besitz der Urkunde ihren einzigen Rechtsanspruch gegen den Aufstand der Gesetzlosen, sollte die Ordnung in der Provinz jemals wiederhergestellt werden."}},faq={{q="Wo finde ich diese Urkunde?",a="Die Urkunde wird von verschiedenen Mitgliedern der Bruderschaft der Defias fallen gelassen, die im südlichen und westlichen Wald von Elwynn lauern, beispielsweise in der Nähe von Jerods Anlegestelle oder in hiesigen Lagern.",al={"urkunde beute","furlbrows urkunde bekommen","wo droppt die urkunde"}},{q="Wo befindet sich Bauer Brauenwirbel?",a="Bauer Brauenwirbel und seine Frau Verna sind neben einem zerbrochenen Wagen an der Hauptstraße kurz hinter der Grenze zu Westfall gestrandet, gleich nach dem Überqueren der Brücke gen Westen vom Wald von Elwynn aus.",al={"furlbrow standort","furlbrows urkunde abgeben","wo ist der bauer"}},{q="Warum wollten die Defias die Urkunde überhaupt haben?",a="Eine Notiz auf der Rückseite verrät, dass die Banditen beabsichtigten, Furlbrows rechtmäßige Urkunde als Vorlage zu nutzen, um Ansprüche auf andere Besitztümer in der Region zu fälschen und ihre Kontrolle über geraubte Höfe mit gefälschten Dokumenten zu untermauern.",al={"warum stahlen banditen die urkunde","warum wollen defias urkunden"}},{q="Kehren die Furlbrows zu ihrem Hof zurück?",a="Nicht in absehbarer Zeit. Das Paar befindet sich aufgrund der Gesetzlosigkeit und der Banditenangriffe auf der Flucht aus der Region. Ihre Urkunde in Händen zu halten sichert ihnen jedoch das Recht zu, ihr Land legal zurückzufordern, falls Westfall jemals befriedet werden sollte.",al={"kehren furlbrows heim","was passiert mit furlbrows hof"}},{q="Warum beschützt Sturmwind diese Höfe nicht?",a="Sturmwind ist durch das plötzliche Verschwinden von König Varian Wrynn und innenpolitische Spannungen gelähmt. Da sich die königlichen Ressourcen auf die Hauptstadt konzentrieren, wurden Randgebiete wie Westfall sich selbst überlassen, um sich gegen das Erstarken der Bruderschaft der Defias zur Wehr zu setzen.",al={"warum keine wachen in westfall","warum ignoriert sturmwind westfall"}},{q="Was ist die Verbindung zwischen Elwynn und Westfall bei dieser Quest?",a="Die Quest dient als Wegweiser, der Abenteurer aus dem Wald von Elwynn über den Fluss nach Westfall führt, und zeigt auf, wie weit das Netzwerk der Defias in die Kernlande des Königreichs hineinreicht.",al={"warum war die urkunde in elwynn","verbindung zwischen zonen"}}},fx={["9b306b68"]={q="Warum sollte ich Brauenwirbels Urkunde zurückgeben?",a="Die Urkunde selbst ist nur ein lebloses Stück Papier, aber die Nachricht, die auf ihrer Rückseite gekritzelt ist, enthüllt, dass Defias-Raufbolde Theodore und Verna Brauenwirbel dazu eingeschüchtert haben, ihr Land aufzugeben. Die Diebe wollten sie als Vorlage verwenden, um Ansprüche auf andere Grundstücke zu fälschen. Sie an die flüchtenden Brauenwirbels zurückzubringen, gibt einer ehrlichen Bauernfamilie den einzigen Eigentumsnachweis, den sie noch haben, und bietet ihnen Hoffnung, ihr gestohlenes Erbe eines Tages zurückzufordern, falls jemals wieder Frieden in Westfall einkehren sollte.",al={"warum die urkunde zurückgeben","motiv für westfall-urkunde","zweck der brauenwirbel-urkunde"}}},fp="15,251,22.516.0,32.511.0,26.182.0,25.170.0,52.223.0,42.207.0,43.256.0,65.189.0"}
P.entries["quest:1840"] = {n="Orm Steinhuf und der brutale Helm",s="Dieser Auftrag schickt aufstrebende Krieger der Horde nach Donnerfels, um Orm Stonehoof aufzusuchen, einen meisterhaften Schmied. Von Thun'grim Brandblick empfohlen, besitzt Orm das nötige Fachwissen, um den Brutalen Helm zu schmieden.",h="Dieser Auftrag schickt aufstrebende Krieger der Horde nach Donnerfels, um Orm Stonehoof aufzusuchen, einen...",kw={"rüstungsquest","brutaler helm","orm stonehoof","thun'grim brandblick","donnerfels","krieger"},ang={["class:Warrior"]="Diese Quest markiert den Übergang zu schwerem Kopfschutz und schickt die Krieger zu einem der besten Meisterschmiede der Horde.",["faction:Horde"]="Die Quest veranschaulicht die Zusammenarbeit zwischen den orkischen Waffenmeistern im Brachland und den Handwerkern der Tauren hoch oben auf Donnerfels."},sec={{t="Eine Empfehlung in Eisen",b="Nachdem sie ihren Mut bewiesen und Teile der Brutalen Rüstung im Brachland gesammelt haben, werden die Krieger weiter hinauf in die Hochebenenstadt Donnerfels geschickt. Thun'grim Brandblick, selbst ein vollendeter Rüstungsschmied, erkennt seine Grenzen und verweist seine Recken an Orm Stonehoof. Orms Handwerkskunst ist in ganz Kalimdor berühmt, insbesondere seine Fähigkeit, aus seltenen, wilden Trophäen widerstandsfähige Schlachthelme zu formen."},{t="Der Kunstschmied am Teich",b="Orm lebt und arbeitet auf den hohen Klippen von Mulgore nahe den ruhigen Gewässern unter dem gewaltigen zentralen Totem der Stadt. Wenn ein Krieger mit einer Nachricht von Thun'grim eintrifft, unterbricht Orm seine alltägliche Arbeit, um die anspruchsvollen Komponenten zu besprechen, die erforderlich sind, um einen Kopfschutz zu schmieden, der den Frontlinien der Horde wahrhaft würdig ist."}},faq={{q="Wer ist Orm Stonehoof?",a="Orm Stonehoof ist ein erfahrener Rüstungsschmied der Tauren, der in Donnerfels lebt. Er ist für seine Handwerkskunst bekannt und hilft Kriegern, die von Thun'grim Brandblick geschickt wurden, bei der Herstellung spezieller Schlachthelme.",al={"orm stonehoof","wer ist orm"}},{q="Wo ist Orm Stonehoof zu finden?",a="Er befindet sich im Herzen von Donnerfels und steht in der Nähe des Wasserbeckens unweit des gewaltigen zentralen Totems der Stadt.",al={"wo ist orm","orm stonehoof standort","orm finden"}},{q="Warum schickt Thun'grim Brandblick Euch nach Donnerfels?",a="Während Thun'grim das Brustteil und andere Bestandteile des Brutalen Sets herstellen kann, räumt er ein, dass Orm Stonehoof über das genaue Fachwissen verfügt, das zur Anfertigung des Brutalen Helms nötig ist.",al={"warum donnerfels","warum zu orm"}},{q="Was ist der Brutale Helm?",a="Der Brutale Helm ist ein ikonischer Kopfschutz, der für erfahrene Krieger der Horde geschmiedet wird. Er erfordert gefährliche Materialien, die von Bestien aus ganz Kalimdor beschafft werden müssen.",al={"brutaler helm quest","was ist der brutale helm"}},{q="Worum bittet Orm als Nächstes?",a="Sobald Ihr mit Orm sprecht, weist er Euch an, die nötigen Bestientrophäen für den Helm zu beschaffen, beginnend mit der Jagd auf Schimären in der Wildnis, um ein Schimärenhorn zu erbeuten.",al={"nächste quest","nach orm stonehoof","schimärenhorn quest"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Diese Questreihe ist Kriegern vorbehalten, die in ihrer kriegerischen Ausbildung weit genug vorangeschritten sind und Thun'grims anfängliche Rüstungsaufgaben abgeschlossen haben.",al={"nur für krieger","wer kann diese quest machen"}}},fx={["528c5ae8"]={q="Warum möchte Thun'grim Firegaze, dass Ihr Orm Stonehoof aufsucht?",a="Thun'grim Firegaze hat Euer Training als Krieger angeleitet, doch die Anfertigung eines Brutal Helm erfordert einen Meisterhandwerker, dessen Talent gewöhnliche Schmiedekunst übertrifft. Da Thun'grim Orm Stonehoofs unübertroffenes Geschick bei der Verarbeitung von Metall und Knochen erkennt, schickt er Euch zu dem Tauren-Handwerker nach Donnerfels, damit Ihr Euch ein Rüstungsteil verdienen könnt, das Eurer wachsenden Stärke und Eurem Dienst für die Horde würdig ist.",al={"motiv von thungrim firegaze","warum zu orm stonehoof","grund für thungrims brutal helm"}}},fp="33,213,24.405.0,23.328.0,21.185.0,33.119.0,54.180.0,24.168.0,27.164.1,30.146.0"}
P.entries["quest:1841"] = {n="Velora Nachtens und die brutalen Beinschützer",s="Diese Quest führt erfahrene Krieger der Horde aus dem Brachland über das Meer nach Unterstadt in Lordaeron. Dort nutzt die Rüstungsschmiedin der Verlassenen, Velora Nachtens, ihre erhaltene sterbliche Handwerkskunst, um spezialisierte Brutale Beinschützer zu schmieden. Sie stellt einen entscheidenden Schritt bei der Zusammenstellung einer widerstandsfähigen Rüstung für die Frontkämpfer der Horde dar.",h="Diese Quest führt erfahrene Krieger der Horde aus dem Brachland über das Meer nach Unterstadt in Lordaeron.",kw={"brutal armor","brutale beinschützer","lordaeron","thun'grim firegaze","handwerksviertel","unterstadt","velora nachtens","kriegerquest"},ang={["class:Warrior"]="Diese Quest stellt einen bedeutenden Meilenstein für Krieger der Horde um Stufe 30 dar und erweitert ihre Reise über Kalimdor hinaus, um spezialisierte Klassenrüstung zu erlangen.",["faction:Horde"]="Die Questreihe um die Brutal Armor schweißt die junge Horde zusammen, indem sie auf Kalimdor beheimatete Orcs, Trolle und Tauren dazu bringt, sich direkt mit Handwerkern der Verlassenen in den Östlichen Königreichen abzustimmen.",["race:Undead"]="Velora Nachtens zeigt, dass die Verlassenen die verfeinerten kulturellen Fertigkeiten und künstlerischen Vermächtnisse des gefallenen Königreichs Lordaeron bewahrt haben."},sec={{t="Eine Reise über das Meer",b="Nachdem sie dem Veteranenschmied Thun'grim Firegaze auf seiner Wacht im Brachland ihren Mut bewiesen haben, werden Krieger damit beauftragt, die sagenumwobene Brutal Armor zusammenzutragen. Thun'grim kann die vollständige Rüstung nicht allein herstellen und weist aufstrebende Recken an geschickte Verbündete in der gesamten Horde. Für die Beinschützer schickt er sie ostwärts über das große Meer in das unterirdische Reich der Verlassenen, um eine Handwerkerin aufzusuchen, deren Werk schon lange vor dem Fall der nördlichen Menschheit verehrt wurde."},{t="Die Kunstfertigkeit von Velora Nachtens",b="Vor ihrem Ableben während der Geißelung des Nordens war Velora Nachtens als eine der herausragendsten Rüstungsschmiedinnen im Königreich Lordaeron berühmt. Trotz des Verlusts ihres sterblichen Lebens und der Verderbnis ihrer Heimat vermochte der Tod ihre metallurgische Meisterschaft nicht zu schmälern. Nun geht sie ihrem Gewerbe im Handwerksviertel von Unterstadt nach, setzt ihr uraltes Handwerk der Menschen zum Wohle der Krieger der Horde ein und bewahrt sich einen trockenen, makabren Witz über ihren untoten Zustand."}},faq={{q="Wer ist Velora Nachtens?",a="Velora Nachtens wurde einst als eine der feinsten Rüstungsschmiedinnen im Königreich Lordaeron gerühmt. Nach dem Dritten Krieg und ihrer Wiedererweckung als eine der Verlassenen zog sie in das Handwerksviertel von Unterstadt, wo sie ihr Schmiedehandwerk für die Horde fortführt.",al={"velora nachtens lore","wer ist velora","verlassene schmiedin velora"}},{q="Warum schickt Thun'grim mich nach Unterstadt?",a="Während Thun'grim Firegaze Eure Ausbildung im Brachland überwacht, erfordert die Herstellung der vollständigen Brutal Armor spezialisierte Handwerker in der gesamten Horde. Er erkennt Veloras unübertroffenen Ruf für Rüstungen an und entsendet Euch nach Lordaeron, um die Beinschützer direkt in Auftrag zu geben.",al={"warum nach unterstadt","thun'grim unterstadt quest","brachland nach unterstadt krieger"}},{q="Wo kann ich Velora Nachtens in Unterstadt finden?",a="Velora Nachtens kann bei der Arbeit an den Schmieden im Handwerksviertel von Unterstadt angetroffen werden, umgeben von anderen meisterhaften Handwerkern und Schmieden im Dienste von Fürstin Sylvanas Windläufer.",al={"velora nachtens aufenthaltsort","wo ist velora nachtens","velora nachtens finden"}},{q="Was folgt nach dem Gespräch mit Velora Nachtens?",a="Velora bittet Euch, Schienbeinknochen von Dragonmaw-Orcs im Sumpfland zu beschaffen, damit sie diese zur Herstellung Eurer Brutalen Beinschützer verwenden kann.",al={"nächste quest nach velora","dragonmaw shinbones quest","was will velora"}},{q="Gibt es von Velora Dialoge darüber, dass sie untot ist?",a="Ja. Nach Abschluss der Reise, um mit ihr zu sprechen, scherzt sie trocken darüber, ob sie die Rüstung für Euch herstellt oder umgekehrt, und bemerkt, dass sie ihren Sinn für Humor ungefähr zu der Zeit verlor, als sie ihren Geruchssinn einbüßte und aufhörte zu atmen.",al={"velora witze","untoter schmied dialog","velora humor"}},{q="Ist Brutal Armor nur für Krieger gedacht?",a="Ja, die Prüfungen der Brutal Armor – einschließlich des Aufsuchens von Velora Nachtens für die Beinschützer – sind ein exklusiver Ritus des kriegerischen Aufstiegs, der eigens für Krieger der Horde bestimmt ist, die erfahrene Ränge erreichen.",al={"können andere klassen brutal armor erhalten","nur für krieger quest brutal armor"}}},fx={["7eb107f7"]={q="Warum möchte Thun'grim Firegaze, dass Ihr dies tut?",a="Thun'grim Firegaze hilft Euch dabei, Eure vollständige Rüstung der Brutal Armor zu schmieden, ein Ritus des kriegerischen Fortschritts für vielversprechende Krieger der Horde. Während Thun'grim selbst einige Komponenten herstellen kann, übersteigt die spezialisierte Handwerkskunst, die für die Beinschützer erforderlich ist, seine persönlichen Schmiedetechniken, was ihn dazu veranlasst, Euch an Velora Nachtens zu verweisen, die als eine der besten Rüstungsschmiede von Lordaeron bekannt ist.",al={"thungrim firegaze beweggrund","warum brutale beinschützer herstellen","warum zu velora nachtens schicken"}}},fp="38,330,24.463.0,29.458.0,21.266.0,40.270.0,48.168.0,43.124.1,49.242.0,34.197.0"}
P.entries["quest:1842"] = {n="Satyrhufe",s="Satyrhufe ist eine Quest, die vom Trollhandwerker Ula'elek in Sen'jin vergeben wird. Um ein Paar ermächtigter brutaler Stulpen zu schmieden, müssen Krieger nach Norden nach Eschental reisen, um Satyrn zu jagen und ihre magisch aufgeblähten, ungespaltenen Hufe zu erbeuten.",h="Satyrhufe ist eine Quest, die vom Trollhandwerker Ula'elek in Sen'jin vergeben wird.",kw={"eschental","brutale stulpen","durotar","hufe","satyr","sen'jin","ula'elek","ungespalten"},ang={["class:Warrior"]="Diese Aufgabe ist Teil eines Prüfungsrituals für Krieger und stellt ihre kämpferische Widerstandskraft gegen hinterlistige dämonische Angreifer auf die Probe, um maßgeschneiderte Rüstung zu erlangen.",["faction:Horde"]="Die Aufnahme dieser Jagd führt Krieger der Horde aus den trockenen Ebenen von Durotar weit hinein in das umkämpfte Gebiet der Nachtelfen in Eschental.",["race:Troll"]="Ula'eleks Methoden zeigen die pragmatische Natur der Handwerkskunst der Dunkelspeere, die rohe Essenz gefallener magischer Feinde abzapft, anstatt sich rein auf herkömmliche Schmiedekunst zu verlassen."},sec={{t="Die Nutzung verderbter Essenz",b="Um eine Rüstung zu schmieden, die es mit den brutalsten Kräften auf Kalimdor aufnehmen kann, blickt der Handwerker der Dunkelspeere, Ula'elek, über gewöhnliches Eisen und Leder hinaus. Er schickt aufstrebende Krieger nach Norden in die uralten Wälder von Eschental, wo die verbliebene dämonische Verderbnis in den örtlichen Zirkeln der Satyrn schwelt."},{t="Die Schwellung durch Eschentals Magie",b="Laut Ula'elek ernähren sich die Satyrn im nordöstlichen Eschental, indem sie die schlummernde Reinheit des Waldes absaugen und in unheilvolle Macht verdrehen. Jene Dämonen, die sich am tiefsten an diesem geborgten Leben gelabt haben, weisen abnorme, geschwollene Hufe auf, die ihre natürliche Spaltung verloren haben. Ula'elek beabsichtigt, diese konzentrierte magische Energie zu entziehen und direkt in die von ihm gefertigten Stulpen einzuweben."}},faq={{q="Warum braucht Ula'elek Satyrhufe?",a="Ula'elek benötigt die Hufe, um die brutalen Stulpen zu ermächtigen, die er herstellt. Er will die konzentrierte Waldmagie abzapfen, die die Satyrn entzogen und in ihren geschwollenen Füßen verdorben haben.",al={"warum satyrhufe","huf zweck","wofür sind die hufe"}},{q="Wo sind die Satyrn zu finden?",a="Sie bewohnen das nordöstliche Eschental, wo sie in verderbten alten Ruinen hausen und von der verbliebenen magischen Energie des tiefen Waldes zehren.",al={"wo sind satyrn","satyr aufenthaltsort","satyrhufe finden"}},{q="Was macht einen ungespaltenen Huf so besonders?",a="Das Fehlen einer Spaltung deutet darauf hin, dass sich ein Satyr an übermäßigen Mengen von Eschentals reiner Magie überfressen hat, wodurch seine Gliedmaßen mit gestohlener Macht anschwellen.",al={"ungespaltene hufe lore","warum ungespalten","geschwollene hufe"}},{q="Wer ist Ula'elek?",a="Ula'elek ist ein geschickter Rüstungshandwerker der Dunkelspeertrolle, der in Sen'jin im südlichen Durotar lebt und dafür bekannt ist, Kriegern bei der Herstellung von Prüfungsrüstung zu helfen.",al={"wer ist ulaelek","questgeber","troll in senjin"}},{q="Welche Rüstung schmiedet Ula'elek?",a="Er bereitet die Herstellung eines Paares Brutale Stulpen vor, schwere schützende Handschuhe, die für aufstrebende Krieger der Horde mit gestohlener magischer Kraft erfüllt sind.",al={"was sind brutale stulpen","stulpen quest","belohnungsrüstung"}},{q="Dienen die Satyrn hier der Brennenden Legion?",a="Ja. Satyrn sind uralte Nachtelfen, die durch dämonische Pakte verwandelt wurden, und die verbliebenen Zirkel in den Wäldern Kalimdors praktizieren weiterhin Teufelsverderbnis im Dienste dämonischer Mächte.",al={"satyr loyalität","gehören satyrn zur legion"}}},fx={["749a1d7b"]={q="Warum befinden sich die Satyrn im nordöstlichen Eschental?",a="Satyrn suchen das nordöstliche Eschental heim, um sich an der Reinheit des uralten Waldes zu laben. Indem sie seine verborgenen Zauber aussaugen und korrumpieren, stärken sie ihre bösartigen Rituale und verzerren ihre eigenen Körper. Diejenigen, die sich am meisten an der natürlichen Magie des Eschentals gütlich tun, entwickeln groteske, geschwollene, nicht gespaltene Hufe und werden zu lebendigen Gefäßen konzentrierter arkaner Stärke.",al={"warum satyrn im eschental","hintergrund zu satyrhufen","wen für hufen jagen"}}},fp="12,253,28.286.0,30.413.0,36.195.0,27.145.0,36.161.0,16.157.0,31.140.0,44.180.0"}
P.entries["quest:1843"] = {n="Brutale Stulpen",s="Brutale Stulpen ist der Höhepunkt der Handwerkskunst eines Meisters für erfahrene Krieger der Horde. Nach dem Sammeln seltener Bestandteile in fernen Ländern fertigt der Handwerker Ula'elek ein gewaltiges Paar Handschützer, die sowohl dem Schöpfer als auch dem Träger Ehre bringen sollen.",h="Brutale Stulpen ist der Höhepunkt der Handwerkskunst eines Meisters für erfahrene Krieger der Horde.",kw={"rüstungsschmieden","brutale stulpen","durotar","horde","satyrhufe","ula'elek","kriegerrüstung"},ang={["class:Warrior"]="Diese Stulpen stehen für den Übergang eines Kriegers zu disziplinierter militärischer Führung und dienen als verlässlicher Rüstungsteil, der speziell für schwere Nahkampfgefechte geschmiedet wurde.",["faction:Horde"]="Die Handwerkskunst der Horde beruht auf beständiger Tradition und kriegerischem Stolz und stellt sicher, dass die Champions das spirituelle Gewicht und die Ehre ihrer Handwerker mit in die Schlacht tragen."},sec={{t="Das Meisterwerk eines Handwerkers",b="Das Schmieden einer Rüstung für einen erfahrenen Frontkrieger ist mehr als bloße Metallbearbeitung – für die Kunsthandwerker der Horde ist es ein spirituelles Unterfangen. Ula'elek, ein in Durotar ansässiger Handwerker, lässt seine Abstammung und sein Können in die Formung dieser brutalen Stulpen einfließen. Durch die Verwendung gehärteter Trophäen, die von gefährlichen Widersachern erbeutet wurden, fertigt er eine Rüstung, die darauf ausgelegt ist, heftigen Hieben standzuhalten und gleichzeitig die Offensivkraft des Trägers zu steigern."},{t="Ehre der Ahnen",b="In den Traditionen der Orcs und Trolle tragen erlesene Waffen und Rüstungen das Ansehen der Schmiede und den Geist des Schöpfers in die Schlacht. Wenn Ula'elek einem Krieger die fertigen Stulpen überreicht, vertraut er ihm das Erbe seiner Ahnen an. Von einem Champion, der sie im Kampf trägt, wird erwartet, dass er Mut, kriegerische Disziplin und Stärke beweist, die dieser Handwerkskunst würdig sind."}},faq={{q="Wer ist Ula'elek?",a="Ula'elek ist ein in Durotar ansässiger Handwerker, der Kriegern der Horde dabei hilft, maßgeschneiderte, hochwertige Rüstungen zu erhalten. Er verlangt exotische Materialien, um sicherzustellen, dass seine Schmiedekunst sowohl seinem Handwerk als auch den Traditionen seiner Ahnen Ehre macht.",al={"ulaelek","wer gibt brutale stulpen","questgeber"}},{q="Warum wurden Satyrhufe für diese Stulpen benötigt?",a="Die geschwollenen, ungespaltenen Hufe der Satyrn tragen die Kraft in sich, die sie der Magie von Eschental entzogen haben. Ula'elek entzieht den Hufen diese Macht und macht sie sich für sein Handwerk zunutze, sodass den Stulpen große Magie innewohnt.",al={"warum satyrhufe","satyrkörperteile","verwendete materialien"}},{q="Was bedeutet das Tragen der Stulpen für Ula'elek?",a="Für Ula'elek stellt die Herstellung dieser Stulpen den Höhepunkt seines Schaffens dar. Sie einem würdigen Krieger anzuvertrauen, gereicht seinem Handwerk und seinen Ahnen zu tiefer Ehre und verbindet seine Arbeit unmittelbar mit den kriegerischen Siegen der Horde.",al={"ahnen ehren","ula'elek ehre"}},{q="Wo findet diese Prüfung statt?",a="Das Schmieden endet in Durotar, dem kargen Kernland der Orcs und Dunkelspeere, wo Ula'elek die beschafften Materialien prüft und die vollendete Rüstung überreicht.",al={"ort","wo brutale stulpen abgegeben wird"}},{q="Ist diese Prüfung für alle Abenteurer gedacht?",a="Dieser Pfad ist eigens für Frontkrieger bestimmt, die ihre Ausdauer und kriegerische Hingabe bewiesen haben, und markiert ihren Aufstieg in erfahrenere Kampfrollen innerhalb der Horde.",al={"nur für krieger","klassenvoraussetzung"}},{q="Was geschieht nach dem Erhalt der Stulpen?",a="Die Übergabe der Stulpen markiert den Abschluss dieser spezifischen handwerklichen Prüfung, sodass der Krieger bestens gerüstet ist, um sich größeren Bedrohungen auf den vom Krieg zerrütteten Schlachtfeldern Azeroths zu stellen.",al={"folgequest","brutale stulpen fortsetzung"}}},fp="16,262,25.416.0,15.367.0,16.212.0,49.203.0,52.214.0,32.168.0,43.180.0,41.182.0"}
P.entries["quest:1844"] = {n="Schimärenhorn",s="Als Teil des Krieger-Ritus zur Herstellung des Brutal Helm beauftragt Orm Stonehoof einen aufstrebenden Champion damit, in das ruinierte Das verbrannte Tal zu reisen. Dort muss der Krieger eine wahnsinnig gewordene Schimärenmatriarchin jagen, um ihr Galvanisiertes Horn sowohl als Akt der Gnade als auch als Beweis der Stärke zu erlangen.",h="Als Teil des Krieger-Ritus zur Herstellung des Brutal Helm beauftragt Orm Stonehoof einen aufstrebenden...",kw={"brutal helm","das verbrannte tal","schimärenmatriarchin","chimaeric horn","galvanisiertes horn","orm stonehoof","steinkrallengebirge","donnerfels","krieger quest"},ang={["class:Warrior"]="Diese Prüfung testet die Fähigkeit eines Kriegers, einsame Alpha-Bestien in brutalen Umgebungen zu jagen, und sich damit das Recht zu verdienen, den Brutal Helm zu tragen.",["faction:Horde"]="Krieger der Horde, die von Sonnenfels aus operieren, stoßen tief in die umkämpften Wildnisse vom Steinkrallengebirge vor, um die Waffen zu schmieden, die für die Verteidigung von Kalimdor benötigt werden.",["race:Tauren"]="Orm Stonehoof begegnet der Kriegführung mit taurenhafter Ehrfurcht und erinnert Krieger daran, dass selbst bei Gewalt das Erlösen einer gequälten Bestie aus ihrem Leiden die Erdenmutter ehrt."},sec={{t="Eine Prüfung der Entschlossenheit",b="Orm Stonehoof ist bereit, den legendären Brutal Helm für Krieger der Horde zu schmieden, doch die kriegerische Tradition verlangt, dass der Träger zuerst seinen Mut beweist. Orm verlangt nicht einfach nach rohem Metall oder Gold; er verlangt Beweise für kriegerisches Können und die Bereitschaft, sich den grimmigen Narben zu stellen, die ein verheerender Konflikt hinterlassen hat."},{t="Die Narben von Das verbrannte Tal",b="Die Quest führt Krieger in die südwestlichen Ausläufer vom Steinkrallengebirge, in die aschene Einöde, die als Das verbrannte Tal bekannt ist. Einst üppig und grün, wurde das Tal zu einer rauchenden Einöde niedergebrannt. Die überlebenden Bestien, die durch die rußbedeckten Krater wandern, sind von Qual und Wut gezeichnet, besonders die mächtigen Schimären, die ihre Nester inmitten der toten Bäume und sengenden Dampfschlote bauen."},{t="Gnade im Kampf",b="Das Erlegen einer Schimärenmatriarchin erfüllt in den Augen des Tauren-Schmieds zwei Zwecke. Es sichert das gehärtete Galvanisiertes Horn, das für die Herstellung des Kopfschmucks erforderlich ist, beendet aber auch die Qualen der Kreatur. Durch das Erlegen der Matriarchin handelt der Krieger sowohl als Henker als auch als Instrument der Gnade für einen wilden Geist, der durch die Zerstörung seiner Heimat in den Wahnsinn getrieben wurde."}},faq={{q="Wer ist Orm Stonehoof?",a="Orm Stonehoof ist ein geschickter Tauren-Schmied, der in Donnerfels ansässig ist und Veteranen der Horde bei der Herstellung ikonischer Stücke ihrer Klassenrüstung unterstützt, darunter der Brutal Helm.",al={"orm stonehoof lore","wer ist orm stonehoof","schmied orm in donnerfels"}},{q="Warum will Orm das Galvanisiertes Horn?",a="Das Galvanisiertes Horn dient sowohl als langlebige physische Komponente für den Brutal Helm als auch als greifbarer Beweis dafür, dass der Krieger den Mut besitzt, ein gefährliches Alpha-Raubtier in gefährlichem Gelände aufzuspüren und zu besiegen.",al={"nutzen vom galvanisierten horn","warum das galvanisierte horn","brutal helm horn"}},{q="Was sind Schimären im Steinkrallengebirge?",a="Schimären sind große, zweiköpfige, geflügelte Bestien, die in den Wildnissen von Kalimdor heimisch sind. Diejenigen, die in Das verbrannte Tal überlebt haben, wurden durch das Feuer und die Zerstörung ihrer Nistplätze gewaltsam in den Wahnsinn getrieben.",al={"schimären im steinkrallengebirge","schimären lore","was sind schimären"}},{q="Wie passt diese Quest in das Training eines Kriegers?",a="Um ihre dreißigste Saison herum werden Krieger der Horde an Spezialisten wie Orm Stonehoof verwiesen, um gefährliche Prüfungen zu bestehen. Das Abschließen dieser Herausforderungen ermöglicht es ihnen, das schwere, stachelige Brutal Armor Set zu tragen, das für Schlachtfeldchampions entworfen wurde.",al={"brutal helm kette für krieger","krieger quest donnerfels stufe 30","brutal armor questreihe"}},{q="Warum stellt Orm die Jagd als einen Akt der Gnade dar?",a="Die Kultur der Tauren betont die Harmonie mit der Erde und ihren Geschöpfen. Da die Bewohner von Das verbrannte Tal aufgrund der Verwüstung ihres Landes in unaufhörlichen Qualen leben, wird das Erlegen der Matriarchin eher als das Erlösen einer leidenden Bestie aus ihrem endlosen Elend und nicht als gedankenloses Schlachten angesehen.",al={"warum gnade für die matriarchin","von ihrem elend befreien"}}},fx={["3a1b9e89"]={q="Wozu dient das Galvanisierte Horn?",a="Das Galvanisierte Horn erfüllt für Orm Stonehoof einen doppelten Zweck. Materiell liefert es das gewaltige, gehärtete Horn, das zum Schmieden Eures Brutal Helm benötigt wird. Ritualistisch dient es als physischer Beweis dafür, dass Ihr den aschfahlen Einöden des Das verbrannte Tal getrotzt, einer wahnsinnigen Chimärenmatriarchin gegenübergetreten seid und sowohl kriegerische Stärke als auch die Gnade bewiesen habt, ihr die Erlösung zu gewähren.",al={"verwendung des galvanisierten horns","warum brauche ich das galvanisierte horn","galvanisiertes horn für brutal helm"}},["241e9666"]={q="Wen sollt Ihr im Das verbrannte Tal jagen?",a="Ihr seid ausgesandt, um eine Chimärenmatriarchin zu jagen, die inmitten der Ruinen des Das verbrannte Tal haust. Einst ein üppiges Hochlandtal, wurde das Tal durch feurige Zerstörung völlig entweiht, was die überlebenden Bestien vor Qual und Verzweiflung in den Wahnsinn trieb. Die Matriarchin ist eine dieser majestätischen Raubtiere, die nun endlos in der verpesteten Asche leidet, bis Ihr ihr ein ehrenvolles Ende bereitet.",al={"ziel chimärenmatriarchin","wen im verbrannten tal töten","ziel chimaeric horn"}},c3120874={q="Warum schickt Orm Euch, anstatt selbst zu gehen?",a="Orm Stonehoof stellt Euren Geist auf die Probe und bittet nicht um einen routinemäßigen Botengang. Der Brutal Helm ist ein traditionelles, mächtiges Rüstungsteil, das nur Kriegern vorbehalten ist, die ihre Entschlossenheit, ihr kriegerisches Können und ihre Fähigkeit zu ehrenvoller Gnade bewiesen haben. Indem Ihr das Biest selbst in den feindseligen Einöden des Das verbrannte Tal jagt, beweist Ihr Orm, dass Ihr würdig seid, sein Werk zu tragen.",al={"warum schickt orm mich","warum kann orm die matriarchin nicht jagen","warum braucht orm einen abenteurer"}}},fp="14,275,17.316.0,29.393.0,15.348.0,21.180.0,38.210.0,33.205.0,46.244.0,47.285.0"}
P.entries["quest:1845"] = {n="Brutaler Helm",s="Der Brutale Helm markiert den Höhepunkt einer beschwerlichen Kriegerprüfung, die von Orm Stonehoof auf den Anhöhen von Donnerfels beaufsichtigt wird. Nachdem sie seltene Bestientrophäen in ganz Kalimdor gesammelt haben, wird ein aufstrebender Krieger mit einem furchteinflößenden Hörnerhelm als Zeugnis seiner Stärke belohnt.",h="Der Brutale Helm markiert den Höhepunkt einer beschwerlichen Kriegerprüfung, die von Orm Stonehoof auf den...",kw={"brutaler helm","schimärenhorn","erdenmutter","die anhöhe der jäger","orm stonehoof","donnerfels","krieger"},ang={["class:Warrior"]="Dieser Ritus dient als wichtiger Meilenstein für Krieger der Horde und führt sie an schwere Rüstung heran, die aus wilden Bestien geschmiedet und von erfahrenen Veteranenausbildern gesegnet wurde.",["faction:Horde"]="Die Prüfung der Brutalen Rüstung stellt sicher, dass Champions, die unter dem Banner der Horde kämpfen, die von ihren Anführern geforderte rohe körperliche Ausdauer und Jagdkunst besitzen.",["race:Tauren"]="In Donnerfels verliehen, spiegelt der Helm die Taurentradition wider, Jagdtrophäen unter der Gnade der Erdenmutter zu schützendem Kriegsgerät zu verarbeiten."},sec={{t="Der Ritus eines Kriegers",b="Orm Stonehoof dient als strenger Schmied in Donnerfels und leitet Krieger der Horde durch zermürbende Übergangsriten. Diese Prüfungen verlangen den Beweis kriegerischen Könnens und führen die Initianden in tückisches Terrain, um wilde Kreaturen zu jagen und seltene Trophäen zu erbeuten. Nur jene, die Orms anspruchsvollen Maßstäben gerecht werden, erhalten eine Audienz zur Vollendung ihrer Rüstung."},{t="Die Gabe der Erdenmutter",b="Indem der Krieger Orm Stonehoof das seltene Schimärenhorn bringt, beweist er seine Entschlossenheit gegenüber der Wildnis. Als Anerkennung überreicht Orm den Brutalen Helm – ein schweres, bedrohliches Plattenrüstungsstück, geschmiedet, um die Bestie zu ehren und den Träger an vorderster Front zu stärken. Bei der Übergabe ruft Orm den Segen der Erdenmutter an und blickt den größeren Taten entgegen, die der Krieger in ganz Azeroth vollbringen soll."}},faq={{q="Wer bietet den Brutalen Helm an?",a="Orm Stonehoof, ein ehrwürdiger Taurenschmied in Donnerfels, überreicht den Brutalen Helm an Krieger der Horde, die seine Prüfungen bestehen.",al={"wer gibt brutalen helm","brutaler helm nsc","orm stonehoof quest"}},{q="Welche Aufgabe muss vor dem Erhalt des Helms abgeschlossen werden?",a="Ihr müsst die Prüfung 'Schimärenhorn' abschließen, die erfordert, wilde Bestien in der Wildnis zu jagen und deren Horn zu Orm Stonehoof in Donnerfels zu bringen.",al={"voraussetzung für brutalen helm","schimärenhorn quest"}},{q="Wo befindet sich Orm Stonehoof?",a="Orm Stonehoof befindet sich nahe dem Teich beim großen zentralen Totem auf den Hochebenen der Stadt Donnerfels.",al={"orm stonehoof standort","wo ist orm stonehoof"}},{q="Warum ruft Orm Stonehoof die Erdenmutter an?",a="Als Taure ehrt Orm die Erdenmutter als Schöpferin und spirituelle Hüterin der Welt. Ihren Segen über den vollendeten Helm eines Kriegers auszusprechen, spiegelt den traditionellen Glauben der Tauren wider, dass Stärke im Kampf im Einklang mit spiritueller Ehrfurcht stehen muss.",al={"warum erdenmutter erwähnt","erdenmutter lore"}},{q="Steht diese Prüfung jedem Abenteurer offen?",a="Nein. Die Prüfung und ihre Belohnungen der Brutalen Rüstung sind exklusiv Kriegern der Horde vorbehalten, die ihren Mut in speziellen Klassenquests unter Beweis stellen.",al={"kann jeder den brutalen helm bekommen","brutaler helm klasse"}},{q="Welche Bedeutung hat das Rüstungsset der Brutalen Rüstung?",a="Die Teile der Brutalen Rüstung repräsentieren den Aufstieg eines Kriegers vom unerfahrenen Soldaten zum Elite-Champion der Horde, geschmiedet aus Materialien, die von den wildesten Raubtieren in Kalimdor erbeutet wurden.",al={"brutale rüstung lore","warum heißt es brutaler helm"}}},fx={["3a1185bd"]={q="Warum belohnt Orm Stonehoof Euch mit dem Brutal Helm?",a="Orm Stonehoof verleiht den Helm nicht aus einer verzweifelten Notlage oder einer plötzlichen Krise heraus, sondern als zeremonielle Anerkennung Eurer kriegerischen Entwicklung. Indem Ihr seltene Materialien aus ganz Kalimdor gesammelt und Eure Stärke in den Kriegerprüfungen unter Beweis gestellt habt, habt Ihr gezeigt, dass Ihr bereit seid, den Mantel erfahrener Champions zu tragen. Orm ehrt diese Ausdauer und ruft den Segen der Erdenmutter an, damit Eure Rüstung Euch in den noch größeren Schlachten, die auf Euch warten, schützen möge.",al={"warum gibt orm euch den helm","motiv von orm stonehoof für brutal helm","warum brutal helm"}}},fp="11,259,16.365.0,27.412.0,27.130.0,53.168.0,31.105.0,46.254.0,37.127.0,49.188.0"}
P.entries["quest:1846"] = {n="Schienbeinknochen der Drachenmalorcs",s="Dragonmaw Shinbones ist eine Krieger-Quest der Horde, die von der Rüstungsbauerin Velora Nachtens in Unterstadt vergeben wird. Um die widerstandsfähigen Brutale Beinschützer herzustellen, werden Krieger in das südliche Sumpfland entsandt, um außergewöhnlich dicke Schienbeine von den feindseligen Dragonmaw-Orcs zu erbeuten.",h="Dragonmaw Shinbones ist eine Krieger-Quest der Horde, die von der Rüstungsbauerin Velora Nachtens in...",kw={"lager der grollhauer","brutale beinschützer","dragonmaw","schienbeine","thandol-übergang","unterstadt","velora nachtens","sumpfland"},ang={["class:Warrior"]="Diese Prüfung stellt sowohl die körperliche Zähigkeit eines Kriegers im Feld auf die Probe als auch seine Bereitschaft, morbide Materialien zu sammeln, um überlegene Rüstung herzustellen.",["faction:Horde"]="Das Niederschlagen des abtrünnigen Dragonmaw-Clans in Khaz Modan schwächt ein gefährliches Überbleibsel der Alten Horde und stärkt zugleich die Champions von Thralls neuer Koalition.",["race:Orc"]="Für Orgrimmar-treue Orcs ist das Ausdünnen der unbelehrbaren Dragonmaw eine eindringliche Erinnerung an die dämonische Vergangenheit ihres Volkes und den blutigen Preis der Erlösung.",["race:Undead"]="Velora Nachtens' pragmatischer Umgang mit humanoiden Überresten veranschaulicht die Mentalität der Verlassenen, jede verfügbare Ressource zur Waffe zu machen, ganz gleich wie makaber sie sein mag."},sec={{t="Eine grausige Rüstung",b="Das Schmieden einer Rüstung, die für einen erfahrenen Frontkämpfer geeignet ist, erfordert unkonventionelle Materialien. Bei der Aufgabe, Brutale Beinschützer herzustellen, verlangt die Rüstungsbauerin der Verlassenen, Velora Nachtens, nach einer Stützverstrebung aus dickem, widerstandsfähigem Knochen. Anstatt gewöhnliche Bestien zu nutzen, schickt sie angehende Krieger zu den Dragonmaw-Orcs des Sumpflands, deren dichter Skelettbau die nötige Widerstandskraft bietet, um schweren Schlägen im Kampf standzuhalten."},{t="Die Prüfung des Marks",b="Das Erbeuten von Knochen der Dragonmaw ist nur die halbe Bewährungsprobe. Velora weist die Krieger an, jeden im Feld erbeuteten Knochen von Hand zu testen; jedes Exemplar, das so spröde ist, dass es in den bloßen Händen zerbricht, ist für die Schmiede völlig unbrauchbar. Krieger müssen die Lager der Abtrünnigen entlang der Felsen des Sumpflands durchkämmen und schwache Knochen zerbrechen, bis acht wahrhaft stabile Exemplare den Test of Strength überstehen."}},faq={{q="Warum benötigt Velora Nachtens speziell Orc-Schienbeine?",a="Velora benötigt dichtes, dickes Material als Stützgerüst für die Brutale Beinschützer. Sie hält die Dragonmaw-Orcs des Sumpflands für einzigartig geeignet, da ihr schwerer, kräftiger Skelettbau weitaus mehr strukturelle Steifigkeit bietet als gewöhnliches Wild oder zusammengesuchte Überreste.",al={"warum orc-schienbeine","warum dragonmaw-knochen","velora knochenrüstung"}},{q="Warum sind die Dragonmaw-Orcs Freiwild für Krieger der Horde?",a="Die im Sumpfland verschanzten Überreste des Dragonmaw-Clans sind feindselige Abtrünnige, die an dem finsteren Erbe des Zweiten Krieges festhalten. Sie haben keine Loyalität gegenüber Thralls moderner Horde, was sie zu Staatsfeinden und legitimer Beute für Abenteurer der Horde macht.",al={"gehören dragonmaw zur horde","warum dragonmaw bekämpfen","ruf der dragonmaw bei der horde"}},{q="Wo sind die Dragonmaw für diese Aufgabe zu finden?",a="Sie halten sich im Sumpfland auf, südlich über The Thandol Span vom Arathihochland aus. Krieger jagen sie gewöhnlich an den bergigen Klippen rund um das Lager der Grollhauer, das südwestlich der nördlichen Hauptstraße liegt.",al={"standort der dragonmaw","wo man dragonmaw shinbones findet","standort von lager der grollhauer"}},{q="Warum brechen während der Quest so viele der Knochen?",a="Velora verlangt nur das dichteste Markgerüst für das Schmieden der Rüstung. Gemäß ihren Anweisungen testen Krieger jeden Knochen von Hand; jeder Knochen, der unter roher körperlicher Kraft zerbricht, wird als zu zerbrechlich verworfen, um die Beine eines Kriegers im Kampf zu schützen.",al={"gebrochene schienbeine","warum schienbeine brechen","test stabiler knochen"}},{q="Wer ist Velora Nachtens?",a="Velora Nachtens ist eine Rüstungsbauerin der Verlassenen, die in Unterstadt tätig ist. Schroff, morbid-trocken und zu grimmigen Versuchen von Humor neigend, unterstützt sie Krieger der Horde bei der Anfertigung spezialisierter Kriegsausrüstung für kampferprobte Veteranen.",al={"velora nachtens lore","wer ist velora","rüstungsbauerin von unterstadt"}},{q="Welches Rüstungsteil wird aus diesen Knochen geschmiedet?",a="Die gesammelten Knochen bilden das innere Gerüst für die Brutale Beinschützer, ein Paar langlebiger Kettenbeinschützer, das für Krieger der Horde mittlerer Stufe gefertigt wird.",al={"belohnung für shinbones","wofür die schienbeine sind","brutale beinschützer herstellen"}}},fx={["0579d748"]={q="Warum möchte Velora Nachtens, dass dies erledigt wird?",a="Velora Nachtens benötigt Schienbeinknochen von Dragonmaw-Orcs im Sumpfland, um Eure Brutale Beinschützer anzufertigen. Ihre stabilen Knochen liefern das Material für die Rüstung, die sie zu fertigen zugestimmt hat.",al={"motiv von velora nachtens","warum will velora schienbeinknochen","velora nachtens warum"}}},fp="19,266,19.437.0,18.377.0,55.285.0,56.245.0,44.222.0,51.239.0,21.229.0,44.141.0"}
P.entries["quest:1848"] = {n="Brutale Halsberge",s="Die Brutale Halsberge markiert den Höhepunkt eines mühsamen Übergangsritus für Krieger der Horde im Brachland. Nachdem sie seltene Materialien gesammelt und ihren Mut gegen gefährliche Widersacher in fernen Ländern bewiesen haben, überreichen die Krieger ihre Ausbeute dem zurückgezogen lebenden Schmied Thun'grim Brandblick. Als Gegenleistung schmiedet er eine robuste Kettenrüstung, die selbst den härtesten Schlachten standhalten soll.",h="Die Brutale Halsberge markiert den Höhepunkt eines mühsamen Übergangsritus für Krieger der Horde im Brachland.",kw={"brutale rüstung","brutale halsberge","das wegekreuz","orcische schmiedekunst","brachland","thun'grim brandblick","krieger kettenrüstung"},ang={["class:Warrior"]="Die Brutale Halsberge ist ein bedeutender Meilenstein für junge Krieger der Horde und symbolisiert den Wandel vom einfachen Rekruten zum abgehärteten Kämpfer in maßgefertigtem Kettenpanzer.",["faction:Horde"]="Geschmiedet aus blutig erstrittenen Trophäen der Wildnis von Kalimdor, verkörpert die Halsberge die grundlegenden Tugenden der Horde: kriegerische Eigenständigkeit und Stärke.",["profession:Blacksmithing"]="Thun'grim bei der Arbeit zuzusehen, gewährt einen Einblick in die traditionelle orcische Schmiedekunst, bei der Kampfgeist und Widerstandskraft direkt in den Stahl gehämmert werden."},sec={{t="Das Meisterwerk eines Schmieds",b="Thun'grim Brandblick haust hoch in den zerklüfteten Hügeln des nördlichen Brachlands und schmiedet Rüstungen nicht für jedermann. Der einsiedlerische Orc verlangt von aufstrebenden Kriegern, weit und breit zu reisen, um zähe Bestienteile, seltenes Metall und alchemistische Reagenzien zu sammeln, noch bevor er überhaupt seinen Blasebalg entfacht. Die fertige Halsberge ist nicht bloß schützende Ausrüstung; sie ist ein dauerhaftes Abzeichen für Ausdauer und Härte, das von erfahrenen Kämpfern in der gesamten Horde geschätzt wird."},{t="In Entbehrung geschmiedet",b="Thun'grims Aufgabe ist bewusst unerbittlich gestaltet. Echte Waffen und Rüstungen der Horde müssen von Beginn an den Schweiß und das Blut ihres Trägers tragen. Bei der Übergabe der fertigen Brutalen Halsberge spart sich der Schmied blumige Worte – er erwartet lediglich, dass sich die Rüstung in brutalen Kämpfen bewährt und ruhmreiche Geschichten von Blut und Ehre heimkehren lässt."}},faq={{q="Was ist die Brutale Halsberge?",a="Die Brutale Halsberge ist ein stabiles Brustteil, das vom Orc-Schmied Thun'grim Brandblick maßgefertigt wird. Sie dient als krönende Belohnung für Hordekrieger, die ihr kriegerisches Können unter Beweis stellen, indem sie seltene Materialien in verschiedenen gefährlichen Ländern zusammentragen.",al={"was ist brutale halsberge","brutale halsberge quest","wer fertigt brutale halsberge"}},{q="Wer ist Thun'grim Brandblick?",a="Thun'grim Brandblick ist ein zurückgezogen lebender Schmiedeveteran, der auf einem Bergausläufer im nördlichen Brachland weilt, östlich des Weges zwischen dem Wegekreuz und Orgrimmar. Er prüft aufstrebende Krieger und schmiedet ihnen maßgeschneiderte Rüstung, sobald sie ihren Wert unter Beweis gestellt haben.",al={"wer ist thun grim","thungrim firegaze","wo ist thungrim"}},{q="Warum verlangt Thun'grim so viel Aufwand, bevor er die Rüstung schmiedet?",a="Die kriegerische Tradition der Horde schätzt Entbehrungen ebenso sehr wie Kampfgeschick. Thun'grim ist der Ansicht, dass hochwertige Kettenrüstung an jeden verschwendet wäre, der nicht sein eigenes Blut vergossen und geschuftet hat, um die seltenen Bestandteile für ihre Herstellung zu beschaffen.",al={"warum so viele materialien sammeln","brutale rüstung anforderungen","thungrim prüfungen"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Diese Quest stellt den letzten Schritt der Prüfungen um die Brutale Rüstung dar. Sobald Thun'grim Euch die fertige Halsberge überreicht, ist seine Arbeit für Euch getan und Ihr könnt die Rüstung in Schlachten in ganz Kalimdor und den Östlichen Königreichen tragen.",al={"was kommt nach brutale halsberge","nächste quest nach brutale halsberge","gibt es eine folgequest"}},{q="Ist die Quest für die Brutale Halsberge für die Allianz verfügbar?",a="Nein. Die Brutale Halsberge ist ausschließlich eine Prüfung der Horde. Krieger der Allianz durchlaufen ein eigenes Kampf-Ritual bei den Schmieden von Eisenschmiede und den umliegenden Zwergenterritorien, um ihre eigene unverwechselbare Rüstung zu schmieden.",al={"kann allianz brutale halsberge bekommen","allianz äquivalent","nur für horde"}},{q="Wo im Brachland kann man Thun'grim finden?",a="Thun'grim lebt auf einem hohen Gebirgskamm im nördlichen Brachland, südlich des Südstroms und etwas östlich des Hauptgebirgswegs, der nach Norden in Richtung Durotar führt.",al={"thungrim standort","wo ist thungrim im brachland","thun grim finden"}}},fx={a5674fab={q="Warum schmiedet Thun'grim Firegaze diesen Brutal Hauberk für Euch?",a="Thun'grim Firegaze schmiedet seine Brutal Armor nicht für irgendwen. Als geehrter Meisterrüstmeister, der vielversprechende Krieger der Horde prüft, verlangt er den Beweis von Ausdauer, Stärke und roher Zähigkeit, bevor er seinen Hammer schwingt. Indem Ihr die notwendigen Materialien gesammelt und in seinem Namen Gefahren getrotzt habt, habt Ihr Euch als würdig erwiesen, seine feinste Handwerkskunst in die Schlacht zu tragen.",al={"warum ich brutal hauberk","warum fertigt thungrim die rüstung","warum brutal hauberk geben"}}},fp="14,363,21.433.0,18.356.0,27.241.0,26.255.0,68.223.0,38.233.0,54.212.0,44.169.0"}
P.entries["quest:1858"] = {n="Die Zerschmetterte Hand",s="Diese Schurkenprüfung dient als abschließende Initiation in die Reihen der Shattered-Hand in Orgrimmar. Therzok beauftragt angehende Schurken damit, eine sichergestellte Tasche zu öffnen, indem sie den Schlüssel einem ahnungslosen Komplizen entwenden.",h="Diese Schurkenprüfung dient als abschließende Initiation in die Reihen der Shattered-Hand in Orgrimmar.",kw={"die kluft der schatten","gamon","orgrimmar","taschendiebstahl","schurke","die shattered-hand","tazan","therzok"},ang={["class:Rogue"]="Dieser Übergangsritus lehrt die Grundsätze des Schurkenhandwerks: das Verfolgen eines ahnungslosen Ziels in belebten Räumen, das unbemerkte Entwenden eines Schlüssels und das Beschaffen wichtiger Informationen.",["faction:Horde"]="Hinter der kriegerischen Ehre von Thralls neuer Horde liegt die Notwendigkeit verdeckter Aufklärung, die tief im Inneren von Orgrimmar unauffällig von der Shattered-Hand gelenkt wird."},sec={{t="Eine Prüfung der Täuschung",b="Nachdem Tazans verschlossene Tasche geborgen wurde, ist die Beute für angehende Schurken ohne ihren Schlüssel nutzlos. Anstatt das komplexe Schloss mit roher Gewalt aufzubrechen, besteht die Shattered-Hand auf echtem Handwerk. Therzok weist seine Initianden auf Gamon hin, einen leicht abzulenkenden, betrunkenen Tauren, der Orgrimmars Taverne frequentiert und zuvor Tazan half – was ihn zu einem idealen Ziel für einen lautlosen Diebstahl macht."},{t="Willkommen in den Schatten",b="Gamon den Schlüssel zu entwenden, ohne die gesamte Taverne zu alarmieren, ermöglicht es einem Initianden, die Tasche zu öffnen und Tazans Logbuch an sich zu bringen. Diese gestohlenen Inhalte zu Therzok in die Kluft der Schatten zurückzubringen, erfüllt die strengen Maßstäbe der Gilde. Ist der Auftrag sauber erledigt, wird der Kandidat feierlich als anerkannter Agent der Shattered-Hand aufgenommen."}},faq={{q="Wer ist Gamon und warum hat er den Schlüssel?",a="Gamon war ein Gehilfe von Tazan, dem Agenten, dessen Tasche von Therzok untersucht wird. Während Tazan die Tasche trug, überließ er den Schlüssel Gamon, einem ahnungslosen Trunkenbold, der seine Tage trinkend in Orgrimmars zentraler Taverne verbringt.",al={"warum gamon","wer hat den schlüssel","gamon schlüssel"}},{q="Was befindet sich in Tazans Tasche?",a="In der verschlossenen Tasche liegt Tazans Logbuch. Sein Inhalt umfasst Geheimdienstberichte von Interesse für Therzok und die Shattered-Hand, was die Fähigkeit des Initianden beweist, wichtige Informationen unter verdeckten Bedingungen zu beschaffen.",al={"tazans logbuch","tascheninhalt","was ist in der tasche"}},{q="Was ist die Shattered-Hand in Orgrimmar?",a="Ursprünglich ein berüchtigter Orc-Clan aus Draenor, der für Selbstverstümmelung und Skrupellosigkeit bekannt war, hat sich die Shattered-Hand in Orgrimmar zur führenden Gilde der Horde für Attentäter, Spione und Schurken gewandelt, die aus der unterirdischen Kluft der Schatten heraus agiert.",al={"was ist die shattered-hand","shattered-hand schurken","orgrimmar schurken"}},{q="Wo agiert Therzok?",a="Therzok agiert aus der Kluft der Schatten, dem düsteren Höhlennetzwerk, das unter den felsigen Kämmen von Orgrimmar verborgen liegt und in dem Hexenmeister, Schurken und Schattenkunst fernab des Tageslichts gedeihen.",al={"wo ist therzok","therzok standort","die kluft der schatten schurkenlehrer"}},{q="Warum bricht Therzok die Tasche nicht einfach auf?",a="Die Tasche ist mit einem komplexen Schließmechanismus versehen, aber noch wichtiger ist, dass dies eine Prüfung der Disziplin eines Schurken darstellt. Die Shattered-Hand schätzt chirurgischen Diebstahl und Finesse höher ein als lautstarke Zerstörung.",al={"warum taschendiebstahl","warum schlüssel nötig"}},{q="Was passiert nach dieser Quest?",a="Dieser Auftrag markiert den Abschluss der Initiationsreihe. Durch die Übergabe von Tazans Logbuch werdet Ihr feierlich zum anerkannten Mitglied der Shattered-Hand ernannt und mit Werkzeugen belohnt, die Eure künftigen verdeckten Unternehmungen unterstützen.",al={"belohnung shattered-hand","ende der reihe"}}},fx={["74a53139"]={q="Warum möchte Therzok, dass Tazans Ranzen geöffnet wird?",a="Therzok und The Shattered Hand operieren aus den Schatten von Orgrimmar und handeln mit Geheimnissen und verdeckter Sicherheit für die Horde. Tazan besaß Informationen, die für ihre Operationen entscheidend waren, aber der heikle Inhalt blieb in einem komplizierten Ranzen verschlossen. Therzok will die darin enthaltenen Informationen, ohne sie zu zerstören, und nutzt die Bergung als praktische Prüfung, um zu sehen, ob Ihr über die List, Heimlichkeit und das Geschick verfügt, die einer formellen Aufnahme in ihre Gilde würdig sind.",al={"motiv von therzok","warum den ranzen öffnen","was will therzok"}},a30dee79={q="Was ist Tazans Logbuch?",a="Tazans Logbuch enthält die schriftlichen Aufzeichnungen und geheimen Geschäfte von Tazan, einem Agenten, dessen Aktivitäten die Aufmerksamkeit von The Shattered Hand erregten. Sicher in seinem verschlossenen Ranzen verwahrt, enthält das Logbuch die entscheidenden Informationen, die Therzok benötigt. Es unversehrt zu übergeben beweist nicht nur Eure Fähigkeit, Taschen zu stehlen und knifflige Schlösser zu knacken, sondern liefert auch wertvolle Informationen direkt an die Spionagemeister von Orgrimmar.",al={"tazans logbuch","was steht im logbuch","hintergrund zu tazans logbuch"}},["1b7f194d"]={q="Warum schickt Therzok nicht die Wachen von Orgrimmar hinter Gamon her?",a="The Shattered Hand lebt von Diskretion und Geheimhaltung, weit entfernt von den offensichtlichen, ehrenhaften Methoden der Stadtwache. Die Grunts von Orgrimmar einzubeziehen, um einen betrunkenen Tavernengast wie Gamon festzunehmen, würde ein unerwünschtes öffentliches Spektakel verursachen und mögliche Verbündete von Tazan warnen. Den Diebstahl einem aufstrebenden Schurken anzuvertrauen hält die Operation unauffällig und dient gleichzeitig als stille Bewertung Eurer Finesse.",al={"warum ich","warum schurke schicken","warum keine stadtwachen"}}},fp="18,216,18.387.0,22.353.0,42.243.0,31.216.0,40.250.0,27.179.0,48.194.0,30.223.1"}
P.entries["quest:1859"] = {n="Therzok",s="Therzok ist eine Vorladung, die an vielversprechende Schurken der Horde überbracht wird, die in der Nähe vom Tal der Prüfungen und Sen'jin operieren. Der Schurkenlehrer Kaplak bemerkt Euer Geschick für Gewalt und Heimlichkeit und schickt Euch leise in die höhlenartige Kluft der Schatten, um einen Agenten von der Shattered-Hand zu treffen.",h="Therzok ist eine Vorladung, die an vielversprechende Schurken der Horde überbracht wird, die in der Nähe vom...",kw={"meuchelmörder","die kluft der schatten","durotar","kaplak","orgrimmar","schurke","shattered-hand","therzok"},ang={["class:Rogue"]="Diese Vorladung markiert Euren offiziellen Eintritt in die Shattered-Hand und verbindet Euer einsames Wirken in Durotar mit dem organisierten Spionagenetzwerk, das die gesamte Horde durchzieht.",["faction:Horde"]="Während Thrall Ehre und Kriegergeist predigt, beweist die Existenz von Therzok und seinem Netzwerk, dass die Horde die praktische Notwendigkeit verborgener Klingen und geheimer Informationsbeschaffer sehr wohl versteht."},sec={{t="Eine geflüsterte Vorladung",b="Nicht alle Diener von der neuen Horde kämpfen am helllichten Tag unter dem Banner von Thralls Ehre. Wenn junge Schurken beginnen, sich in Durotar einen Namen zu machen, nimmt Kaplak sie mit leisen Worten beiseite. Die Kunde von einem Agenten, der körperliche Tödlichkeit mit der Bereitschaft verbindet, die Regeln der offenen Kriegsführung zu umgehen, dringt schnell an die Ohren der Untergrundgilde in Orgrimmar."},{t="In die Kluft der Schatten",b="Kaplak schickt den Initianden tief unter die roten Felsklippen von Orgrimmar in die Kluft der Schatten. Fernab der wachsamen Augen der Grunts der Stadt wartet Therzok im Zwielicht. Das Treffen dient als Einführungsritual und führt einsame Beutelschneider und Hinterhalt-Spezialisten in das geordnete Gefüge von der Shattered-Hand ein, jenes verdeckte Netzwerk, das als Dolche der Horde im Dunkeln fungiert."}},faq={{q="Wer ist Therzok?",a="Therzok ist ein Agent von der Shattered-Hand, der sich in der unterirdischen Kluft der Schatten in Orgrimmar aufhält. Er überprüft vielversprechende junge Schurken, die von den Übungsplätzen in Durotar eintreffen, und weiht sie in den Dienst der Gilde ein.",al={"wer ist therzok","therzok lore","nsc therzok"}},{q="Warum schickt Kaplak mich zu ihm?",a="Kaplak erkennt, dass Ihr neben Kampfgeschick auch ein Talent für Heimlichkeit und List besitzt. Da er weiß, dass Die Shattered-Hand ständig nach fähigen Schurken sucht, um ihre Reihen zu verstärken, leitet er Therzoks Ersuchen, Euch zu rekrutieren, an Euch weiter.",al={"warum zu therzok geschickt","kaplak quest","warum nach orgrimmar"}},{q="Was ist Die Shattered-Hand in Orgrimmar?",a="Während der Name auf einen uralten Clan auf Draenor zurückgeht, fungiert Die Shattered-Hand im modernen Orgrimmar als Geheimbund von Meuchelmördern, Spionen und Dieben im Dienste der Horde. Sie führen die notwendigen, moralisch zwiespältigen Aufgaben aus, die Thralls ehrenhafte Krieger nicht offen erledigen können.",al={"was ist shattered-hand","shattered-hand orgrimmar","horde schurkengilde"}},{q="Wo befindet sich die Kluft der Schatten?",a="Die Kluft der Schatten ist eine riesige Höhle unter dem Zentrum von Orgrimmar, erreichbar über dunkle Gänge, die vom Tal der Stärke und Tal der Ehre hinabführen. Sie beherbergt die Hexenmeister und Schurken der Stadt, abseits der öffentlichen Aufmerksamkeit.",al={"wo ist die kluft der schatten","therzok finden","die kluft der schatten standort"}},{q="Was geschieht nach dem Treffen mit Therzok?",a="Nachdem Ihr Therzok begrüßt habt, führt er Euch sogleich an die Pflichten der Arbeit für die Shattered-Hand heran und überträgt Euch Aufgaben, um Eure Fähigkeiten, Heimlichkeit und Loyalität gegenüber dem Netzwerk unter Beweis zu stellen.",al={"folgequest","was will therzok","nach therzok"}},{q="Erhalten Nicht-Schurken diese Quest?",a="Nein. Diese Quest wird ausschließlich Schurken angeboten, sobald sie eine bestimmte Erfahrungsstufe erreicht haben, was ihren Übergang von lokalen Plänklern zu offiziellen Agenten des Geheimdienstnetzwerks der Horde markiert.",al={"können andere klassen das tun","nur für schurken","schurkenquest"}}},fx={["89f659b0"]={q="Warum wählt Kaplak Euch für dieses Treffen aus?",a="Kaplak wurde ausdrücklich angewiesen, nach Personen Ausschau zu halten, die Eurer Beschreibung entsprechen. Es hat sich bis zur Gilde herumgesprochen, dass Ihr Euch im Kampf behaupten könnt und nicht davor zurückschreckt, bei Bedarf Heimlichkeit, Täuschung oder weniger ehrenhafte Mittel einzusetzen. Therzok hat Geschäfte im Sinn, die jemanden mit Euren spezifischen, flexiblen Talenten erfordern.",al={"warum ich kaplak","warum zu therzok schicken","warum hat kaplak mich gewählt"}}},fp="7,282,19.368.0,24.369.0,15.228.0,31.243.0,40.284.0,37.237.0,33.190.0,33.200.0"}
P.entries["quest:1860"] = {n="Gespräch mit Jennea",s="Gespräch mit Jennea ist ein einführender Vorladungsruf, der sich an angehende Magier der Allianz richtet, die ihre Grundausbildung im Wald von Elwynn hinter sich gelassen haben. Entsandt vom Ausbilder Zaldimar Wefhellt in Goldhain, werden Initianden angewiesen, sich direkt bei Jennea Haubitz im Magiersanktum in Sturmwind zu melden.",h="Gespräch mit Jennea ist ein einführender Vorladungsruf, der sich an angehende Magier der Allianz richtet, die...",kw={"wald von elwynn","goldhain","jennea haubitz","das magierviertel","gespräch mit jennea","sturmwind","sanktum der magier","zaldimar wefhellt"},ang={["class:Mage"]="Dieser Auftrag markiert Euren Übergang vom ländlichen Zauberwirken in Goldhain zur formellen Einbindung bei den Hochmagiern, die aus Sturmwinds Sanktum der Magier heraus operieren.",["faction:Alliance"]="Die Sicherheit des Walds von Elwynn und Sturmwinds beruht nicht allein auf einfachen Soldaten, sondern auf arkaner Wachsamkeit, die direkt aus der magischen Akademie der Hauptstadt überwacht wird."},sec={{t="Ein Ruf zum Magiersanktum",b="Sobald ein Magierlehrling in Goldhain ausreichende Beherrschung elementarer Zauber zeigt, erkennt Zaldimar Wefhellt, dass die Ausbildung vor Ort bei den örtlichen Lehrern an ihre Grenzen stößt. Anstatt endlos in den Dörfern von Elwynn zu verweilen, werden vielversprechende Zauberkundige direkt nach Sturmwind geschickt. Im Herzen des Magierviertels ragt das Magiersanktum empor, eine weitläufige Zuflucht arkaner Forschung und Lehre, in der die ranghohen Praktizierenden des Reichs weitreichendere magische Angelegenheiten des Königreichs koordinieren."},{t="Angelegenheiten der königlichen Sicherheit",b="Zaldimar betont, dass die Meldung in Sturmwind weit mehr als eine routinemäßige akademische Beförderung ist; es hat sich eine konkrete Aufgabe ergeben, die sich unmittelbar auf die Sicherheit des Walds von Elwynn und von Sturmwind auswirkt. Nach der Ankunft meldet sich der Lehrling bei Jennea Haubitz, einer etablierten Magierin, die wichtige lokale Aufgaben überwacht. Auch wenn Jennea besonnen und vorsichtig bleibt, wenn es darum geht, einem frisch eingetroffenen Lehrling große Geheimnisse zu offenbaren, markiert die Meldung bei ihr den Beginn des direkten Dienstes für den Zauberorden."}},faq={{q="Wer schickt mich auf diese Quest?",a="Zaldimar Wefhellt, der menschliche Magierlehrer im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, leitet die Quest ein, sobald Ihr über ausreichende arkane Fertigkeiten verfügt.",al={"questgeber","wer gibt die quest","zaldimar"}},{q="Wo finde ich Jennea Haubitz?",a="Jennea Haubitz befindet sich im Magiersanktum, gelegen im Zentrum des Magierviertels in Sturmwind. Man findet sie studierend in den mystischen Hallen des Magiersanktums vor.",al={"jennea haubitz standort","wo ist jennea","jennea finden"}},{q="Was ist das Magiersanktum?",a="Das Magiersanktum ist die markante magische Spitze im Magierviertel von Sturmwind. Es dient als primäre Akademie, Bibliothek und Operationsbasis für die Magier und Arkanforscher des Königreichs.",al={"was ist das sanktum der magier","magierturm sturmwind"}},{q="Warum schickt Zaldimar mich zu Jennea, anstatt die Sache selbst zu regeln?",a="Zaldimar unterrichtet junge Magier in Goldhain in den Grundlagen, doch größere regionale Bedrohungen und spezialisierte Aufgaben, die das Reich betreffen, werden von höherrangigen Gelehrten wie Jennea Haubitz aus der Hauptstadt überwacht.",al={"warum nach sturmwind","warum jennea"}},{q="Was geschieht nach der Meldung bei Jennea Haubitz?",a="Sobald Ihr Euch bei Jennea meldet, beauftragt sie Euch damit, rätselhafte magische Anomalien rund um den Spiegelsee im Wald von Elwynn zu untersuchen.",al={"wie geht es weiter","folgequest","nächster schritt"}},{q="Ist diese Quest für jede Klasse verfügbar?",a="Nein. Diese Quest ist Magiern vorbehalten und dient als klassenspezifischer Initiationsritus, der einen Lehrling aus der ländlichen Dorfausbildung in die formellen Ränge der arkanen Gesellschaft von Sturmwind überführt.",al={"können nicht-magier dies tun","nur für magier","klassenvoraussetzung"}}},fx={["8f9ffa7f"]={q="Warum möchte Zaldimar Wefhellt, dass Ihr mit Jennea sprecht?",a="Zaldimar Wefhellt handelt aus Sorge um die Sicherheit sowohl von Sturmwind als auch vom Wald von Elwynn. Es ist eine dringende Angelegenheit aufgekommen, die die Aufmerksamkeit fähiger Magier erfordert. Anstatt sich direkt darum zu kümmern, verweist er vielversprechende Lehrlinge an Jennea Haubitz im Magiersanktum, die die Einzelheiten dieser heiklen Mission beaufsichtigt.",al={"zaldimar beweggrund","warum jennea aufsuchen","warum zu jennea schicken"}}},fp="17,310,30.503.0,27.490.0,27.159.0,31.170.0,29.189.0,67.208.0,46.135.1,37.190.0"}
P.entries["quest:1861"] = {n="Spiegelsee",s="Der Spiegelsee ist eine einführende Untersuchungsquest für angehende Magier der Allianz, die im Magier-Viertel von Sturmwind studieren. Im Auftrag von Jennea Haubitz begeben sich Lehrlinge südwestlich der Stadttore, um das Wasser des Wasserfalls im Spiegelsee auf restliche magische Verunreinigungen zu untersuchen.",h="Der Spiegelsee ist eine einführende Untersuchungsquest für angehende Magier der Allianz, die im...",kw={"arkane verunreinigung","wald von elwynn","jennea haubitz","leylinien","spiegelsee","wasserprobe","sanktum der magier"},ang={["class:Mage"]="Diese Aufgabe markiert den Übergang eines Lehrlings vom Lesen staubiger Folianten im Magiersanktum hin zur Untersuchung realer arkaner Phänomene und belohnt ihn mit seinem ersten dedizierten Magierstab oder einem Nebenhand-Orb.",["faction:Alliance"]="Die Sicherheit der natürlichen Ressourcen im Wald von Elwynn zu gewährleisten, ist eine der stillen Arten, wie die Magier des Magiersanktums das Herz des Königreichs schützen.",["race:Human"]="Der Spiegelsee speist das umliegende Ackerland und die Wasserwege im Wald von Elwynn, was seine Reinheit für die tägliche Gesundheit der Bürger von Sturmwind entscheidend macht."},sec={{t="Leylinien und verschobene Strömungen",b="Azeroth hat in den letzten Jahrzehnten katastrophale mystische Konflikte erlitten, von der Öffnung des Dunklen Portals bis zum Dritten Krieg und der Schlacht am Hyjal. Diese gewaltsamen Erschütterungen rissen uralte arkan-Strömungen aus ihren einst stabilen Kanälen. Im Sanktum der Magier von Sturmwind beobachten Magier wie Jennea Haubitz diese Verschiebungen genau, da sie befürchten, dass freigesetzte arkan-Energieflüsse in die umliegende Wildnis sickern und die lokalen Ökosysteme verderben könnten."},{t="Das Wasser testen",b="Der Spiegelsee liegt eingebettet unter den Klippen südwestlich der Tore von Sturmwind und dient als primäres natürliches Reservoir, das von Gebirgswasserfällen gespeist wird. Da die umliegende Landschaft von diesem Wasser abhängt, schickt Jennea Novizen mit einem Glasfläschchen direkt an den Fuß des Wasserfalls. Durch das Sammeln frischer Gischt kann das Sanktum empfindliche Scrying- und Reagenzientests durchführen, um zu bestätigen, ob wilde Magie in die öffentliche Wasserversorgung eingedrungen ist."}},faq={{q="Warum möchte Jennea Haubitz eine Wasserprobe aus dem Spiegelsee?",a="Massive mystische Kriege in ganz Azeroth haben die natürlichen Ley-Strömungen zerstört. Jennea Haubitz befürchtet, dass instabile arkan-Energien in den Grundwasserspiegel um Sturmwind sickern, was sich nachteilig auf jeden auswirken könnte, der aus dem See trinkt.",al={"warum wasser aus dem spiegelsee","wasserprobe jennea","wofür ist diese quest"}},{q="Wo genau ist der Spiegelsee?",a="Der Spiegelsee liegt im nordwestlichen Wald von Elwynn, versteckt an den hohen Felsen südwestlich der Haupttore von Sturmwind. Die benötigte Probe wird aus dem Becken am Fuß des kaskadierenden Wasserfalls entnommen.",al={"wo liegt der spiegelsee","standort spiegelsee","spiegelsee finden"}},{q="Was passiert, wenn das Wasser verunreinigt ist?",a="Jennea befürchtet, dass das langfristige Trinken von magisch verunreinigtem Wasser denjenigen schaden könnte, die auf den See angewiesen sind. Die genauen Auswirkungen sind noch nicht bekannt.",al={"ist das wasser vergiftet","was wenn wasser magie enthält","auswirkungen von arkaner verunreinigung"}},{q="Wer kann diese Mission übernehmen?",a="Dieser Auftrag ist speziell für Novizen der Magier reserviert, die in der Allianz ausgebildet werden, und dient als eine ihrer ersten praktischen Feldaufgaben im Namen des Magiersanktums.",al={"wer bekommt die spiegelsee quest","ist der spiegelsee nur für magier"}},{q="Führt diese Quest zu weiteren Untersuchungen?",a="Sie schließt die direkte anfängliche Aufgabe ab, die mit der Vorladung von Jennea Haubitz begann, belohnt den Lehrling mit seinem ersten formellen Magier-Utensil und etabliert seine Pflicht, magische Störungen im gesamten Reich zu überwachen.",al={"was kommt nach dem spiegelsee","spiegelsee questreihe"}},{q="Was hat die magischen Strömungen überhaupt destabilisiert?",a="Jennea schreibt die veränderten Strömungen den massiven mystischen Kämpfen der Welt zu, ohne eine bestimmte Schlacht oder ein Ereignis zu identifizieren.",al={"warum sind leylinien beschädigt","bedeutung mystischer kämpfe","was hat die magie zerstört"}}},fx={["66ca747e"]={q="Wofür ist die Probe des Spiegelseewassers gut?",a="Jennea Haubitz benötigt die Probe, um das Wasser des Mirror Lake auf magische Verunreinigung zu testen. Massive mystische Umwälzungen in ganz Azeroth haben arkane Ströme von ihren normalen Bahnen abgelenkt, und die Magier des Magierviertels befürchten, dass diese instabilen Energien direkt in die örtliche Wasserversorgung sickern. Die Untersuchung des Seewassers wird zeigen, ob diejenigen, die daraus trinken, Gefahr laufen, magisch korrumpiert zu werden.",al={"verwendung der probe des spiegelseewassers","warum wasserprobe holen","was bewirkt die probe"}}},fp="11,279,31.453.0,18.464.0,60.237.0,29.215.0,37.141.0,31.177.0,47.214.0,67.127.0"}
P.entries["quest:1879"] = {n="Gespräch mit Bink",s="„Gespräch mit Bink“ ist eine Aufforderung der Allianz, die Magieranfänger aus Dun Morogh in die Hauptstadt Eisenschmiede schickt. Entsandt von Magis Funkelmantel, führt der Ruf vielversprechende Zauberwirker dorthin, um Bink beizustehen, einer arkanen Forscherin, die in der Hall of Mysteries arbeitet.",h="„Gespräch mit Bink“ ist eine Aufforderung der Allianz, die Magieranfänger aus Dun Morogh in die Hauptstadt...",kw={"bink","dun morogh","hall of mysteries","eisenschmiede","magier","magis funkelmantel","mystic ward"},ang={["class:Mage"]="Diese Vorladung markiert Euren Abschied von der Einführungsausbildung im Tal hin zu den umfassenderen Aufgaben der akademischen Arkanisten von Eisenschmiede.",["faction:Alliance"]="Die gemeinsamen Studien in der Hall of Mysteries zeigen das enge Zusammenspiel aus gnomischem Intellekt und zwergischer Gastfreundschaft unter dem Banner der Allianz.",["race:Gnome"]="Bink und Magis Funkelmantel verkörpern den Fortbestand der gnomischen Arkantradition in den gastlichen Hallen von Eisenschmiede nach dem Verlust von Gnomeregan."},sec={{t="Der Ruf eines Kollegen",b="Novizen der Magie, die in den kalten Felsen von Dun Morogh trainieren, fallen früher oder später Magis Funkelmantel ins Auge. Sobald er erkennt, dass ein Lehrling den einfachen Übungen rund um Kharanos entwachsen ist, überbringt Sparkmantle eine Botschaft seiner Kollegin Bink. Das Gesuch ist präzise und kompromisslos: Bink benötigt einen Arkan-Spezialisten und weigert sich, die Angelegenheit jemandem anzuvertrauen, der keine Magie wirken kann."},{t="Die Hall of Mysteries",b="Der Auftrag führt junge Magier in Eisenschmiedes Mystic Ward, wo Gelehrte, Priester und Arkanisten unter den hohen Steingewölben der Hall of Mysteries zusammenkommen. Hier geht Bink ihren Studien nach und mustert eintreffende Lehrlinge mit scharfem Blick. Aus ihrer Sicht ist rohes Potenzial lediglich ein Anfang; ein undisziplinierter Zauberwirker wird in arkanen Belangen rasch eher zu einer Gefahr als zu einer Hilfe."}},faq={{q="Wer vergibt diese Quest?",a="Magis Funkelmantel bietet die Quest Novizen der Magie der Allianz an, die ihre anfängliche Ausbildung in Dun Morogh vorangebracht haben.",al={"questgeber","wo beginnen","wer startet gespräch mit bink"}},{q="Wo finde ich Bink?",a="Bink hält sich in der Hall of Mysteries auf, die sich im Mystic Ward im nördlichen Viertel von Eisenschmiede befindet.",al={"bink aufenthaltsort","wo ist bink","bink finden"}},{q="Warum möchte Bink nur einen Magier?",a="Bink widmet sich Forschungen, die sich direkt mit arkanen Energien und empfindlicher Überwachungsausrüstung befassen. Sie hält Nicht-Magier für ungeeignet, mit den magischen Feinheiten und den damit verbundenen Gefahren umzugehen.",al={"warum nur magier","magier-voraussetzung","bink will nur magier"}},{q="Was geschieht nach dem Treffen mit Bink?",a="Nachdem sie Euch begrüßt und Eure Fähigkeiten eingeschätzt hat, nimmt Bink Eure Hilfe bei ihren Forschungen in Anspruch und leitet zur Quest 'Mage-tastic Gizmonitor' über.",al={"folgequest","bink fortsetzung","was folgt nach gespräch mit bink"}},{q="Ist diese Quest für andere Klassen als Magier verfügbar?",a="Nein. Diese Quest ist ausschließlich auf Magier zugeschnitten und dient als Übergang von der örtlichen Anfängerausbildung zu spezialisierten Aufgaben in der Hauptstadt.",al={"können andere klassen dies tun","nur für magier","magierspezifisch"}},{q="Was ist die Hall of Mysteries?",a="Die Hall of Mysteries ist Eisenschmiedes Zentrum für arkane und heilige Studien und beherbergt Lehrer, Gelehrte sowie Forscher, welche die magischen Künste der Zwerge und Gnom gleichermaßen vertreten.",al={"eisenschmiede hall of mysteries","was ist die hall of mysteries"}}},fx={["96ce9827"]={q="Warum schickt Magis Funkelmantel Euch zu Bink?",a="Magis Funkelmantel ist ein Gnom-Magierlehrer, der in Kharanos stationiert ist und als Mentor für aufstrebende Zauberwirker dient. Seine Kollegin in Eisenschmiede, Bink, schickte ausdrücklich eine Nachricht, in der sie einen fähigen Magier für ein wichtiges Unterfangen anforderte. Da Magis Eure wachsende Beherrschung der arkanen Künste erkennt, schickt er Euch in die Zwergenhauptstadt, damit Ihr ihrem Ruf folgen und Eure magische Ausbildung fortsetzen könnt.",al={"warum schickt magis euch","motiv von magis funkelmantel","warum mit bink sprechen"}}},fp="15,259,21.388.0,21.404.0,21.113.0,22.108.0,31.192.0,32.141.0,52.134.0,30.172.0"}
P.entries["quest:1881"] = {n="Gespräch mit Anastasia",s="Gespräch mit Anastasia ist eine einleitende Vorladung, die vielversprechende Magier der Verlassenen zu Anastasia Hirschbrunn in Unterstadt führt. Ausgesandt vom Magierlehrer Cain Feuerlied, wird der junge Zauberwirker ins Magieviertel gerufen, um entscheidende Aufgaben für die Magier der Verlassenen zu übernehmen. Diese kurze Vorladung bereitet den Boden für Nachforschungen in den verheerten Landen von Tirisfal.",h="Gespräch mit Anastasia ist eine einleitende Vorladung, die vielversprechende Magier der Verlassenen zu...",kw={"anastasia hirschbrunn","balnirs bauernhof","cain feuerlied","magierquest","magieviertel","unterstadt"},ang={["class:Mage"]="Diese Quest markiert Euren Übergang von der grundlegenden arkanen Ausbildung in den aktiven Dienst für die Magier von Unterstadt.",["race:Undead"]="Für die Arkanisten der Verlassenen bietet Hartwells Ruf die Gelegenheit, Lordaerons intellektuelle Vergangenheit gegen seine gegenwärtigen Gefahren einzusetzen."},sec={{t="Ein Ruf ins Magieviertel",b="Während angehende Zauberwirker ihre ersten Talente unter der Anleitung von Cain Feuerlied schärfen, werden sie bald tiefer in die Hauptstadt geschickt. Die Magier der Verlassenen unterhalten eine eigene Enklave im Magieviertel von Unterstadt, wo sie sowohl arkanes Wissen als auch strategische Verteidigungsbemühungen in ganz Lordaeron organisieren. Cain Feuerlied fungiert als Prüfer, der bloße Novizen aussiebt und jene mit echtem Talent direkt zu erfahrenen Meistern schickt, die fähige Helfer im Feld benötigen."},{t="Anastasia Hirschbrunns Ambitionen",b="Anastasia Hirschbrunn gehört zu den herausragenden Magierausbildern in Unterstadt. Anstatt vielversprechende Schüler in aller Sicherheit belanglose Beschwörungen studieren zu lassen, verliert sie keine Zeit und spannt sie für die territorialen und praktischen Interessen der Verlassenen ein. Ihrem Ruf zu folgen, ist sowohl ein Initiationsritus für Arkananwender als auch eine Einführung in die finsteren, pragmatischen magischen Bestrebungen, die die Untoten nach der Geißel prägen."}},faq={{q="Wer schickt Euch zu Anastasia Hirschbrunn?",a="Cain Feuerlied, ein Magierlehrer der Verlassenen, schickt Euch zu ihr, nachdem er erkannt hat, dass Eure arkanen Talente weit genug entwickelt sind, um bei anspruchsvolleren Angelegenheiten in der Hauptstadt zu helfen.",al={"wer vergibt gespräch mit anastasia","questgeber gespräch mit anastasia","cain feuerlied vorladung"}},{q="Wo ist Anastasia Hirschbrunn zu finden?",a="Anastasia Hirschbrunn hält sich im Magieviertel von Unterstadt auf, wo sie die Ausübenden der arkanen Künste für die Verlassenen koordiniert und unterweist.",al={"wo ist anastasia hirschbrunn","anastasia hirschbrunn standort","anastasia finden"}},{q="Was ist der Zweck dieser Vorladung?",a="Anastasia sucht nach einem fähigen Zauberwirker für praktische Aufgaben außerhalb der Stadtmauern, beginnend mit Feldeinsätzen in Tirisfal wie der Untersuchung von Balnirs Bauernhof.",al={"warum will sie mich","gespräch mit anastasia zweck","was braucht anastasia"}},{q="Welche Quest folgt auf Gespräch mit Anastasia?",a="Sich bei Anastasia zu melden, führt direkt zu 'Balnirs Bauernhof' und schickt Euch in das östliche Tirisfal, um Löwenmäulchen aus dem Garten des Gehöfts zu sammeln.",al={"welche quest kommt danach","folgequest nach gespräch mit anastasia","gespräch mit anastasia folgequest"}},{q="Ist diese Quest auf bestimmte Klassen beschränkt?",a="Ja, diese Quest ist speziell für Magier der Verlassenen gedacht und dient als Meilenstein ihres Klassenfortschritts, sobald sie um die zehnte Stufe herum erste Fertigkeiten erlangen.",al={"ist das eine reine magierquest","wer kann gespräch mit anastasia annehmen","klassenvoraussetzung"}},{q="Warum unterhalten die Magier der Verlassenen ein eigenes Viertel in Unterstadt?",a="Das Magieviertel bietet Arkanisten, Hexenmeistern und Forschern der Verlassenen ein eigenes Refugium, um abseits der physischen Viertel zu studieren und zu zaubern und so ihre Traditionen aus der Zeit vor dem Dritten Krieg in den Tiefen von Lordaeron fortzuführen.",al={"warum magieviertel","magier der verlassenen unterstadt"}}},fx={["34129032"]={q="Warum schickt Cain Feuerlied Euch zu Anastasia Hirschbrunn?",a="Cain Feuerlied dient als Ausbilder für angehende Verlassene-Magier in Brill. Sobald Ihr ausreichende Fertigkeiten in den arkanen Künsten unter Beweis gestellt habt, ist es seine Aufgabe, vielversprechende Zauberwirker an Anastasia Hirschbrunn im Magieviertel der Unterstadt zu verweisen. Hirschbrunn koordiniert größere Unternehmungen für den magischen Orden der Verlassenen, und Cain stellt sicher, dass ihre Reihen mit fähigen Praktizierenden aufgefüllt werden, die bereit für den Dienst sind.",al={"warum schickt cain euch","motiv von cain feuerlied","warum anastasia hirschbrunn besuchen"}}},fp="20,370,27.494.0,29.442.0,47.178.0,38.152.0,36.183.0,40.160.0,41.163.0,67.227.0"}
P.entries["quest:1882"] = {n="Balnirs Bauernhof",s="„Balnirs Bauernhof“ ist eine frühe Reifeprüfung für junge Magier der Verlassenen, die von Anastasia Hirschbrunn im Magieviertel von Unterstadt angeleitet wird. Die Initiierten werden in den Osten von Tirisfal geschickt, um Löwenmäulchen von einem verlassenen Bauernhof zu sammeln, der gefährlich nahe an der Grenze zu den Pestländern liegt. Die botanischen Proben dienen als Barometer für die übergreifende magische Verderbnis, die sich aus dem von der Geißel heimgesuchten Osten ausbreitet.",h="„Balnirs Bauernhof“ ist eine frühe Reifeprüfung für junge Magier der Verlassenen, die von Anastasia...",kw={"anastasia","balnir","bauernhof","hartwell","magier","pestländer","löwenmäulchen","tirisfal","unterstadt"},ang={["class:Mage"]="Diese frühe Prüfung lehrt unerfahrene Magier, dass ihr Studium des Arkane unverzichtbar ist, um fremde magische Verderbnis zu überwachen und abzuwehren.",["profession:Herbalism"]="Das Balnir-Löwenmäulchen dient als Beispiel dafür, wie botanische Exemplare als direkte Speicher und Indikatoren magischer Verschmutzung fungieren können.",["race:Undead"]="Für die Verlassenen ist die Sicherung der Grenzen von Tirisfal gegen die heranrückende Geißel eine Frage des unmittelbaren Überlebens und der eigenen Souveränität."},sec={{t="Ein magisches Barometer",b="Während die Königliche Apothekervereinigung regelmäßig die Auswirkungen von Nekromantie und Verfall erforscht, wachen auch die Magier der Verlassenen über die Grenzgebiete. Anastasia Hirschbrunn beauftragt unerfahrene Zauberwirker damit, zu Balnirs Bauernhof im Osten von Tirisfal zu reisen. Die in den Gärten des Hofes heimischen Löwenmäulchen reagieren von Natur aus empfindlich auf wechselnde magische Strömungen und nehmen Energien aus dem Boden und der Atmosphäre auf. Durch die Untersuchung dieser Blüten können die Arkanforscher in Unterstadt feststellen, ob die verderbliche Seuche aus der Domäne des Lichkönigs das Bollwerk überwunden und Tirisfal selbst erreicht hat."},{t="Die östliche Grenze",b="Balnirs Bauernhof liegt an den Ausläufern der Lichtungen, bedenklich nah an der von der Seuche gezeichneten Wildnis der Westlichen Pestländer. Die Verlassenen erkennen, dass die Seuche des Lichkönigs eine ungebändigte und zerstörerische Macht ist, die das Land selbst verfaulen lässt. Obwohl die Verlassenen eigene dunkle Künste wirken, bedroht die unkontrollierte Verderbnis der Geißel ihre Grenzen und ihre Sicherheit. Anastasia beabsichtigt, die gesammelten Löwenmäulchen an die Apotheker weiterzuleiten, um arkanes Wissen mit alchemistischer Forschung zu verbinden und das zurückgewonnene Herzland von Lordaeron zu verteidigen."}},faq={{q="Warum verlangt Anastasia Hirschbrunn ausgerechnet Löwenmäulchen?",a="Balnir-Löwenmäulchen besitzen eine ausgeprägte natürliche Empfindlichkeit gegenüber magischen Strömungen in ihrer Umgebung. Da sie Energien direkt aus der Erde und der Luft aufnehmen, ermöglicht ihre Erforschung den Magiern der Verlassenen festzustellen, ob die arkane und nekromantische Verderbnis der nahen Pestländer bereits auf Tirisfal übergreift.",al={"warum löwenmäulchen","balnir löwenmäulchen zweck","wozu löwenmäulchen"}},{q="Wo befindet sich Balnirs Bauernhof?",a="Der Bauernhof liegt im Osten von Tirisfal, nahe der Grenze, an der die Lichtungen an die verseuchte Grenzregion der Westlichen Pestländer stoßen. Die Löwenmäulchen wachsen auf den überwucherten Beeten und Gärten rund um die verfallenen Gebäude des Hofes.",al={"balnirs bauernhof standort","wo ist balnirs bauernhof","balnirs bauernhof finden"}},{q="Wer ist Anastasia Hirschbrunn?",a="Anastasia Hirschbrunn ist eine bedeutende Magierin und Ausbilderin der Verlassenen im Magieviertel von Unterstadt. Sie leitet neu erwachte untote Zauberwirker an und unterweist sie in Disziplin, arkanem Gleichgewicht und der praktischen Grenzsicherung gegen feindliche Mächte.",al={"anastasia hirschbrunn lore","wer ist anastasia"}},{q="Warum wollen die Magier der Verlassenen die Seuche eindämmen?",a="Obwohl die Verlassenen mit eigenen Seuchen und Fäulnis experimentieren, gilt die ansteckende Geißelmagie des Lichkönigs als unkontrollierbare Anomalie. Bliebe sie ungehindert, würde die Verderbnis der Geißel ganz Tirisfal verschlingen und die Unabhängigkeit der Verlassenen vernichten.",al={"warum die seuche aufhalten","hassen verlassene die seuche"}},{q="Was geschieht mit den Blumen, nachdem man sie gesammelt hat?",a="Nach Erhalt der Löwenmäulchen übergibt Anastasia sie den Apothekern von Unterstadt. Die Alchemisten und Magier analysieren die Proben gemeinsam, um festzustellen, wie tief Boden und Flora bereits von der Geißel verdorben wurden.",al={"was macht anastasia mit den blumen","wer bekommt die löwenmäulchen"}},{q="Ist diese Quest nur für Magier verfügbar?",a="Ja. Bei dieser Aufgabe handelt es sich um eine reine Klassenquest, die ausschließlich jungen Magiern der Verlassenen offensteht, die ihre ersten Lektionen in Todesend abgeschlossen haben und in der Hauptstadt ihr Verständnis der Arkantheorie unter Beweis stellen wollen.",al={"ist balnirs bauernhof nur für magier","magier klassenquest"}}},fp="20,416,19.614.0,18.566.0,58.297.0,38.248.0,26.261.0,53.269.0,51.231.0,34.219.0"}
P.entries["quest:1885"] = {n="Mennet Carkad",s="Mennet Carkad ist eine einführende Schurkenquest in Unterstadt, die vielversprechende Agenten in die Reihen von The Deathstalkers bringt. Unter der Leitung von Marion Call werden angehende Assassinen herbeigerufen, um sich tief im Schurkenviertel direkt bei Mennet Carkad zu melden.",h="Mennet Carkad ist eine einführende Schurkenquest in Unterstadt, die vielversprechende Agenten in die Reihen...",kw={"assassine","the deathstalkers","schurke der verlassenen","marion call","mennet carkad","schurkenviertel","unterstadt"},ang={["class:Rogue"]="Diese Vorladung markiert Euren Übergang von einem unbewiesenen Beutelschneider zu einer anerkannten Kraft von The Deathstalkers, dem elitären Schattennetzwerk der Verlassenen.",["race:Undead"]="The Deathstalkers sind für das Überleben der Verlassenen von entscheidender Bedeutung: Sie jagen Scharlachrote Eiferer sowie Überreste der Geißel und beschützen Königin Sylvanas vor verborgenen Bedrohungen."},sec={{t="Eine Vorladung aus den Schatten",b="In den finsteren Gängen von Unterstadt verbreitet sich die Kunde unter den verdeckten Agenten der Verlassenen im Stillen. Fällt ein Späher oder Assassine der höheren Führung ins Auge, wird eine Einladung ausgesprochen. Marion Call überbringt die Nachricht, dass Mennet Carkad, eine prominente Gestalt unter den Ausbildern der Schurken, persönlich aufmerksam geworden ist. Angesichts des tödlichen Rufs des Geheimdienstapparats der Verlassenen gilt es nicht als gangbare Option, eine solche Weisung zu ignorieren."},{t="Beitritt zu The Deathstalkers",b="Mennet Carkad wartet in den schattigen Nischen des Schurkenviertels, beobachtet die Rekruten und beurteilt ihre Einsatzbereitschaft. Wer seinem Ruf folgt, tritt nicht bloß einer gewöhnlichen Diebesgilde bei; man wird auf die Aufnahme in The Deathstalkers geprüft, dem gefürchteten Spionage- und Attentatszweig der Verlassenen. Rascher Gehorsam ist lediglich die erste Grundvoraussetzung für jeden, der der Dunklen Fürstin aus den Schatten heraus dienen möchte."}},faq={{q="Wer ist Mennet Carkad?",a="Mennet Carkad ist ein Schurkenlehrer und Koordinator von The Deathstalkers, der im Schurkenviertel von Unterstadt agiert. Er beaufsichtigt vielversprechende verdeckte Agenten und vergibt entscheidende Missionen im Auftrag der Führung der Verlassenen.",al={"mennet carkad lore","wer ist carkad"}},{q="Was geschieht, wenn jemand die Vorladung von Mennet Carkad ignoriert?",a="Marion Call warnt davor, dass Ihr nicht wissen wolltet, was mit jenen geschah, die Carkads Ruf missachteten. Ihr genaues Schicksal lässt sie unerklärt.",al={"carkad ignorieren","was passiert wenn vorladung ignoriert wird"}},{q="Wer sind The Deathstalkers?",a="The Deathstalkers sind der Eliteorden aus Schurken, Spionen und Assassinen im Dienste der Verlassenen. Aus den Schatten von Unterstadt heraus eliminieren sie hochrangige Ziele, sammeln Informationen und sichern Lordaeron vor Feinden wie die Scharlachroter Kreuzzug und der Geißel.",al={"todespirscher lore","was sind the deathstalkers"}},{q="Wo kann ich Mennet Carkad finden?",a="Mennet Carkad befindet sich im Schurkenviertel von Unterstadt, gewöhnlich umgeben von anderen verdeckten Ermittlern, Ausbildern und Zubehör für Schattengewirke.",al={"carkad aufenthaltsort","wo ist mennet carkad"}},{q="Wer vergibt die Quest, Mennet Carkad aufzusuchen?",a="Die Aufgabe wird von Marion Call in Brills Taverne Zur Galgenschlinge vergeben, die Euer aufkeimendes Talent bemerkt und Euch warnt, dass Carkad unverzüglichen Gehorsam erwartet.",al={"wer startet diese quest","marion call quest"}},{q="Was geschieht, nachdem man sich bei Mennet Carkad gemeldet hat?",a="Die Meldung bei Mennet Carkad führt unmittelbar in den direkten Dienst für The Deathstalkers, beginnend mit Aufgaben, die Eure List und Eure Loyalität zur Sache der Verlassenen auf die Probe stellen sollen.",al={"folgequest nach carkad","was will carkad"}}},fx={f971228d={q="Warum schickt Euch Marion Call zu Mennet Carkad?",a="Marion Call sagt, dass Mennet Carkad auf Euch aufmerksam geworden ist und ein Treffen erwartet. Sie drängt Euch, seiner Vorladung Folge zu leisten, und gibt eine ominöse Warnung bezüglich derer ab, die sie ignoriert haben, ohne jedoch ihr Schicksal zu erklären.",al={"warum will marion call das erledigt haben","warum zu mennet carkad gehen","marion call beweggrund"}}},fp="13,256,26.446.0,25.425.0,21.216.0,56.140.0,26.268.0,31.150.0,46.154.0,44.173.0"}
P.entries["quest:1886"] = {n="Die Todespirscher",s="Diese Aufgabe stellt die Prüfung für Initianden dar, die Aufnahme bei den Todespirschern suchen, dem verdeckten und tödlichen Arm, der Lord Varimathras in Unterstadt untersteht. Die von Mennet Carkad im Schurkenviertel erteilte Mission verlangt rücksichtslose Eigeninitiative, um einen reisenden Boten abzufangen. Ihr Abschluss öffnet die Tür zu tiefergehenden klandestinen Plänen im Reich der Verlassenen.",h="Diese Aufgabe stellt die Prüfung für Initianden dar, die Aufnahme bei den Todespirschern suchen, dem...",kw={"astor hadren","die todespirscher","mennet carkad","schurkenviertel","silberwald","unterstadt","varimathras"},ang={["class:Rogue"]="Für Schurken der Verlassenen stellt der Beitritt zu den Todespirschern die höchste Stufe des Staatsdienstes dar, wodurch gerissene Halunken zu eingeschworenen Werkzeugen von Varimathras und der Dunklen Fürstin werden.",["faction:Horde"]="Die Todespirscher agieren in tiefster Geheimhaltung und stellen sicher, dass die Verlassenen lebenswichtige Spionagenetzwerke aufrechterhalten, während die südlichen Verbündeten der Horde über ihre zwielichtigeren internen Angelegenheiten weitgehend im Unklaren bleiben.",["race:Undead"]="Die Todespirscher verkörpern den eisernen Griff der inneren Sicherheit in Lordaeron und haben ein wachsames, paranoides Auge auf äußere Feinde wie auch auf potenzielle Verräter unter den Verlassenen."},sec={{t="Eine Prüfung in den Schatten",b="Die Todespirscher nehmen nicht jeden in ihre Reihen auf. Dieser geheimnisvolle Orden, der direkt unter Schreckenslord Varimathras operiert, fungiert sowohl als Geheimpolizei als auch als Elite-Attentatskorps der Verlassenen. Um ihre Aufmerksamkeit zu erregen, muss ein hoffnungsvoller Agent List, Diskretion und die unerschütterliche Bereitschaft beweisen, Ziele zu eliminieren. In den schattigen Ecken des Schurkenviertel stellt Verbindungsmann Mennet Carkad eine Initiationsprüfung, die darauf ausgelegt ist, die Schwachen oder allzu Gewissenhaften auszusortieren."},{t="Das Abfangen",b="Das Ziel des Initianden ist Astor Hadren, ein Kurier, der auf der Straße zwischen Unterstadt und dem Silberwald unterwegs ist. Carkad bietet keinerlei taktische Ratschläge und überlässt die Methode, an Hadrens persönliches Empfehlungsschreiben zu gelangen, gänzlich dem Agenten. Die Aufgabe hängt davon ab, Astor abzufangen, seine Papiere an sich zu bringen und sicherzustellen, dass die Todespirscher ihren Rekruten als den erwarteten Gesandten bei einem Agenten namens Andron ausgeben können."}},faq={{q="Wer sind die Todespirscher?",a="Die Todespirscher sind der Elitezweig der Verlassenen für Heimlichkeit und Attentate. Mit Hauptsitz im Schurkenviertel von Unterstadt kümmern sie sich um Spionage, verdeckte Exekutionen und Informationsbeschaffung und unterstehen direkt Lord Varimathras.",al={"die todespirscher lore","was sind die todespirscher","untote schurken"}},{q="Wer ist Mennet Carkad?",a="Mennet Carkad ist ein Verbindungsmann der Todespirscher, der vom Schurkenviertel in Unterstadt aus operiert. Er überwacht erste Prüfungen und testet Rekruten, die ihren verdeckten Reihen beitreten möchten.",al={"mennet carkad rolle","wer vergibt quest"}},{q="Warum braucht Mennet Astor Hadrens Brief?",a="Astor Hadren ist ein Kurier, der zwischen dem Silberwald und Unterstadt reist. Die Beschaffung seines Empfehlungsschreibens erlaubt es den Todespirschern, ihren neuen Agenten an Hadrens Stelle einzusetzen, um einen Verbündeten namens Andron zu täuschen.",al={"astor hadrens brief","warum boten abfangen","astors empfehlungsschreiben"}},{q="Wo reist Astor Hadren?",a="Astor Hadren reist entlang des Pfades, der Unterstadt und den Silberwald verbindet, und transportiert Korrespondenz im Auftrag seiner Kontakte zwischen den Regionen.",al={"astor hadren route","astor hadren aufenthaltsort","wo ist astor"}},{q="Wer ist Lord Varimathras?",a="Varimathras ist ein Nathrezim-Schreckenslord, der sich mit Königin Sylvanas Windläufer verbündete, um seine eigene Existenz zu sichern. Er beaufsichtigt Unterstadts Sicherheit, Verteidigung und Schurkenoperationen vom Königsviertel aus.",al={"varimathras rolle","schreckenslord in unterstadt"}},{q="Was geschieht nach dieser Prüfung?",a="Das Bestehen der Prüfung beweist die Kompetenz eines Agenten und führt zu einem verdeckten Täuschungsauftrag, um Astors Papiere zu überbringen und Androns Geschäfte zu infiltrieren.",al={"was kommt als nächstes","fortsetzung der todespirscher-questreihe"}}},fx={["1398690a"]={q="Warum will Mennet Carkad, dass dies erledigt wird?",a="Mennet Carkad leitet eine Infiltrationsoperation, bei der es darauf ankommt, Nachrichten abzufangen, die für einen Kontaktmann namens Andron bestimmt sind. Durch den Diebstahl von Astor Hadrens Brief sichert Mennet sich die Beglaubigungsschreiben, die benötigt werden, um einen Agenten unbemerkt in das Vertrauen von Andron einzuschleusen.",al={"warum benötigt mennet das","mennet carkads beweggrund","warum den brief stehlen"}},["763d70d5"]={q="Wer ist Astor Hadren?",a="Astor Hadren ist ein Kurier, der zwischen dem Silberwald und der Unterstadt unterwegs ist. Er trägt ein Empfehlungsschreiben bei sich, das für einen Kontaktmann namens Andron bestimmt ist, ohne zu ahnen, dass The Deathstalkers es für ihre eigenen verdeckten Machenschaften auf seine Korrespondenz abgesehen haben.",al={"wer ist hadren","astor hadren","astor hadren als ziel"}},f8c6b26b={q="Warum schickt Mennet Carkad Euch anstelle eines etablierten Agenten?",a="Ihr versucht, Euch als würdig zu erweisen, den The Deathstalkers beizutreten, den Elite-Schurken im Dienste von Lord Varimathras. Mennet setzt gezielt aufstrebende Rekruten für gefährliche, entbehrliche Feldprüfungen ein, um zu sehen, ob sie über die Gerissenheit und Tödlichkeit verfügen, die für den Orden erforderlich sind.",al={"warum ich deathstalkers","warum schickt mich mennet","warum keinen existierenden deathstalker verwenden"}}},fp="17,363,21.480.0,16.414.1,26.240.0,21.173.0,43.231.0,31.151.0,24.201.0,30.158.1"}
P.entries["quest:1898"] = {n="Die Todespirscher",s="Dieser verdeckte Auftrag schickt einen Geheimagenten in die schattenhafte Schattenwelt von Unterstadt, um einen ahnungslosen Verschwörer zu verhören. Im Auftrag von Lord Varimathras gebt Ihr Euch als der erwartete Bote aus, um Hochverrat in der Hauptstadt der Verlassenen aufzudecken.",h="Dieser verdeckte Auftrag schickt einen Geheimagenten in die schattenhafte Schattenwelt von Unterstadt, um...",kw={"andron gant","das apothekarium","astor hadren","die todespirscher","spionage","verlassene","mennet carkad","unterstadt","varimathras"},ang={["class:Rogue"]="Einen Spionagering unter der Identität eines toten Mannes zu infiltrieren, um einen unvorsichtigen Verschwörer zu ködern, ist Spionagehandwerk wie aus dem Lehrbuch der Todespirscher.",["faction:Horde"]="Unter der Oberfläche von Unterstadt verbirgt sich ein Nest politischer Intrigen – ein Beweis dafür, dass selbst innerhalb der Grenzen der Horde Vertrauen ein seltenes Gut ist.",["race:Undead"]="Für die Verlassenen bedeutet Wachsamkeit das Überleben. Jeder Bürger, der dabei erwischt wird, wie er externen Gruppierungen hilft, riskiert die sofortige Säuberung durch die Geheimpolizei der Dunklen Fürstin."},sec={{t="Ein Netz aus Täuschung",b="Die Todespirscher eliminieren nicht nur äußere Bedrohungen für die Verlassenen; sie wachen auch unerbittlich über ihre eigenen Bürger. Aufgrund des von Lord Varimathras gehegten Verdachts setzt Todespirscher Mennet Carkad einen Infiltrationsplan in Gang. Ausgerüstet mit einem gefälschten oder erbeuteten Letter of Introduction von Astor Hadren habt Ihr die Aufgabe, das Misstrauen eines örtlichen Händlers namens Andron Gant zu umgehen."},{t="Der Laden nahe dem Apothekarium",b="Andron Gant betreibt ein Geschäft in der Nähe der giftigen Dämpfe und brodelnden Kessel des Apothekariums. Mennet hält den Ladenbesitzer für dumm und unaufmerksam – es fehle ihm der Scharfsinn, einen Hochstapler zu durchschauen. Das Vorzeigen des Briefes etabliert Eure Tarnung als Bote und veranlasst Gant dazu, bereitwillig seine Wachsamkeit aufzugeben und Einzelheiten über seine Geschäfte mit einer unbekannten dritten Partei preiszugeben."}},faq={{q="Wer ist Andron Gant?",a="Andron Gant ist ein Ladenbesitzer in Unterstadt, dessen Geschäft sich nahe dem Apothekarium befindet. Er ist ins Visier der Todespirscher und von Lord Varimathras geraten, weil er angeblich einer unbekannten externen Fraktion Informationen und Unterstützung zukommen lässt.",al={"andron gant","wer ist gant","wo ist andron gant"}},{q="Warum interessiert sich Lord Varimathras für diesen Händler?",a="Varimathras verdächtigt Gant, mit einer Organisation außerhalb der Verlassenen zu kollaborieren. Um die Stadt zu schützen und potenzielle Subversion im Keim zu ersticken, verlangt der Schreckenslord konkrete Beweise für Gants Kontakte und Absichten.",al={"warum varimathras sich sorgt","varimathras andron gant","warum andron ausspionieren"}},{q="Wie täuscht der Spieler Andron Gant?",a="Mennet Carkad stattet Euch mit Astors Vorstellungsschreiben aus. Da Gant ohnehin einen Boten erwartet und von den Todespirschern als wenig scharfsinnig eingeschätzt wird, genügt das Vorzeigen der Beglaubigung, um sein Vertrauen zu gewinnen.",al={"astors brief","wie man andron gant austrickst","botentarnung"}},{q="Was für eine Gruppierung sind die Todespirscher?",a="Die Todespirscher sind der elitäre Schurkenorden und der Geheimdienst der Verlassenen. Unter Königin Sylvanas und Lord Varimathras agieren sie aus den Schatten heraus, um Aufruhr zu ersticken, Feinde zu sabotieren und interne Bedrohungen auszuschalten.",al={"die todespirscher lore","wer sind die todespirscher","unterstadt schurken"}},{q="Wo ist Andron Gant zu finden?",a="Er hält sich in seinem Laden nahe dem Eingang zum Viertel des Apothekariums in Unterstadt auf, wo er seine Geschäfte unter den wachsamen Augen der Königlichen Apothekervereinigung und der Todespirscher führt.",al={"andron gant aufenthaltsort","wo ist gants laden"}},{q="Was geschieht, nachdem Gant den Brief angenommen hat?",a="Gant nimmt den Brief arglos entgegen und nimmt an, Ihr wärt lediglich ein unbedarfter Bote. Er deutet sofort eine fortlaufende Zusammenarbeit mit gemeinsamen Bekannten an, was die Grundlage dafür legt, weitere Beweise für seinen Verrat zu sammeln.",al={"was tut gant","gants reaktion"}}},fx={["6d39edb7"]={q="Warum möchte Mennet Carkad, dass Andron Gant untersucht wird?",a="Mennet Carkad handelt direkt auf Befehl von Lord Varimathras. Der Schreckenslord vermutet, dass Andron Gant heimlich Unterstützung und Informationen an eine unbekannte rivalisierende Fraktion aus der Unterstadt schleust. Um die Führung der Verlassenen vor interner Subversion zu schützen, benötigt Mennet definitive Beweise für Gants Verrat und die Identität der zwielichtigen Organisation, der er dient.",al={"warum andron gant untersuchen","motiv von mennet carkad","warum schickt mennet mich zu gant"}},["3bf738ba"]={q="Warum schickt Mennet Carkad Euch, anstatt selbst zu gehen?",a="Mennet Carkad hat Andron Gant bereits persönlich getroffen, weshalb seine eigene Anwesenheit das Scheitern der Mission bedeuten würde. Gant würde sofort einen bekannten Deathstalker-Agenten erkennen. Da Ihr Astor Hadrens Empfehlungsschreiben besitzt, hat Gant keinen Grund zu vermuten, dass Ihr etwas anderes seid als der Kurier, den er treffen sollte.",al={"warum braucht mennet mich","warum kann mennet nicht mit gant sprechen","warum einen abenteurer nutzen"}}},fp="17,276,15.416.0,30.377.1,19.228.0,52.214.0,40.225.0,33.235.0,31.189.0,43.228.1"}
P.entries["quest:1899"] = {n="Die Todespirscher",s="Diese Besorgung dient als entscheidender Schritt zur Formalisierung einer Vereinbarung zwischen dem Informanten Andron Gant und den Todespirschern von Unterstadt. Nachdem seine Kooperation gesichert ist, überbringt ein Agent Gants umfangreiches Buch direkt in die Hände von Mennet Carkad im Schurkenviertel. Der Austausch markiert den Übergang von einfachen Nachforschungen zu tieferen, verdeckteren Operationen im Auftrag des Staates der Verlassenen.",h="Diese Besorgung dient als entscheidender Schritt zur Formalisierung einer Vereinbarung zwischen dem...",kw={"andron gant","attentäter","die todespirscher","spionage","geschäftsbuch","mennet carkad","schurkenviertel","unterstadt"},ang={["class:Rogue"]="Für einen aufstrebenden Schurken in Unterstadt ist die Durchführung heikler Botengänge für Mennet Carkad ein grundlegender Diskretionstest, der beweist, dass ein Agent geheime Güter beschaffen kann, ohne unnötige Aufmerksamkeit zu erregen.",["race:Undead"]="Innere Sicherheit bedeutet in Unterstadt das nackte Überleben; den Todespirschern beizustehen stärkt direkt die Kontrolle der Dunklen Fürstin über die Hauptstadt – sowohl gegen lebende Infiltratoren als auch gegen rivalisierende Untote."},sec={{t="Ein Bote in den Schatten",b="Die Todespirscher verlassen sich nicht allein auf rohe Gewalt oder Schattenmagie; ihre Operationen hängen stark von gewöhnlichen Geschäftsbüchern, erfassten Namen und akribischer Überwachung ab. Andron Gant, der von Unterstadt aus operiert, erklärt sich bereit, ein persönliches Buch voller brisanter Informationen zu übergeben, nach denen die Attentäter verlangen. Anstatt direkt mit dem tödlichen Kern der Organisation zu verhandeln, setzt Gant sein Vertrauen in einen zwischengeschalteten Boten – ein Beweis für die Vorsicht, die typisch für jeden ist, der unter den Toten mit Informationen handelt."},{t="Geheimdienst im Schurkenviertel",b="Als das Buch an Mennet Carkad im Schurkenviertel übergeben wird, erweist es sich als weitaus aufschlussreicher, als Die Todespirscher erwartet hatten. Statt flüchtiger Notizen liefern Gants Aufzeichnungen verwertbare Hinweise, die es Carkad ermöglichen, den Umfang ihrer Untersuchungen zu erweitern. In einem so paranoiden und zersplitterten Umfeld wie dem Reich der Verlassenen sind verifizierte Schriftspuren unerlässlich, um interne Subversion aufzuspüren und externe Bedrohungen zu überwachen, bevor sie die Hauptstadt treffen."}},faq={{q="Was steht in Androns Geschäftsbuch?",a="Das Buch enthält vertrauliche Informationen und Aufzeichnungen, die von Andron Gant gesammelt wurden. Obwohl der genaue Inhalt nicht laut vorgelesen wird, stellt Mennet Carkad fest, dass es deutlich mehr Details und wertvollere Informationen enthält, als Die Todespirscher ursprünglich von ihm erwartet hatten.",al={"inhalt von androns buch","was steht im buch","buch der todespirscher"}},{q="Wer sind Die Todespirscher?",a="Die Todespirscher sind die führende Geheimorganisation und Attentätergilde der Verlassenen. Mit ihrem Hauptquartier im Schurkenviertel von Unterstadt agieren sie als Augen, Ohren und verborgene Dolche von Fürstin Sylvanas Windläufer und kümmern sich um Spionage, Aufklärung und gezielte Attentate in ganz Lordaeron.",al={"lore der todespirscher","wer sind die todespirscher","schurken von unterstadt"}},{q="Warum möchte Gant, dass in Zukunft derselbe Bote eingesetzt wird?",a="In der trüben, misstrauischen Atmosphäre von Unterstadt ist es selten, einen Agenten zu finden, der vertrauliche Dokumente überbringen kann, ohne sie zu stehlen oder zu manipulieren. Gant bittet ausdrücklich darum, zukünftige Geschäfte über denselben Läufer abzuwickeln, um Risiken zu minimieren und seine bewährte Arbeitsbeziehung zu wahren.",al={"warum gant euch mag","andron gant vertrauen","gants bote"}},{q="Wer ist Mennet Carkad?",a="Mennet Carkad ist ein erfahrener Agent der Todespirscher, der im Schurkenviertel stationiert ist. Er koordiniert lokale Agenten, sammelt Feldberichte von Informanten wie Andron Gant und leitet verdeckte Einsätze in der gesamten Hauptstadt und den umliegenden Gebieten.",al={"mennet carkad lore","wer ist carkad"}},{q="Wo befindet sich das Schurkenviertel?",a="Das Schurkenviertel ist das südliche Viertel von Unterstadt. Es dient als primäre Basis für getarnte Agenten, Diebe und Attentäter der Verlassenen und bietet Übungsplätze und finstere Nischen weitab der öffentlichen Plätze der oberen Ruinen.",al={"standort des schurkenviertel","wo ist das schurkenviertel","unterstadt schurkenviertel"}},{q="Warum benötigen die Verlassenen einen internen Geheimdienst?",a="Von allen Seiten von der Geißel, dem Scharlachroten Kreuzzug und misstrauischen Überresten der Allianz umgeben, sieht sich die junge Nation der Verlassenen ständigen Gefahren durch Infiltration und Rebellion ausgesetzt. Die Todespirscher merzen Subversion innerhalb der Grenzen Lordaerons aus, um das Überleben des jungen Regimes zu sichern.",al={"warum es todespirscher gibt","spione der verlassenen","geheimdienst von unterstadt"}}},fx={ca9bbdfd={q="Warum möchte Andron Gant, dass das Hauptbuch überbracht wird?",a="Andron Gant operiert innerhalb der Unterstadt unter dem wachsamen Auge der The Deathstalkers, dem Geheimdienstnetzwerk der Verlassenen. Die Auslieferung des angeforderten Hauptbuchs erfüllt deren Forderungen und beweist seinen fortwährenden Wert für sie, wodurch ihre Abmachung intakt bleibt und ihm unerwünschte Überprüfungen erspart bleiben.",al={"warum das hauptbuch überbringen","andron gant beweggrund","warum kooperiert andron"}}},fp="17,408,24.503.0,35.465.1,27.270.0,26.299.0,55.305.0,21.265.0,37.248.0,57.274.0"}
P.entries["quest:19"] = {n="Tharil'zun",s="Marschall Marris setzt ein Kopfgeld auf Tharil'zun aus, den gerissenen Anführer der Vorläufer des Schwarzfelsclans, die die Straßen nahe Burg Steinwacht unsicher machen. Ihn zur Strecke zu bringen, ist ein entscheidender Schritt, um den Griff des Schwarzfelsclans über das nördliche Rotkammgebirge zu brechen. Seinen abgetrennten Kopf nach Seenhain zurückzubringen, bedeutet einen hart erkämpften Sieg für die bedrängte Stadtwache.",h="Marschall Marris setzt ein Kopfgeld auf Tharil'zun aus, den gerissenen Anführer der Vorläufer des...",kw={"schwarzfels","seenhain","marschall marris","vorlaeufer","rotkammgebirge","steinwacht","burg steinwacht","tharil'zun","tharilzun"},ang={["faction:Alliance"]="Seenhain steht ohne direkte Verstärkung aus Sturmwind weitgehend isoliert da, was das Kopfgeld auf Tharil'zun zu einer überlebenswichtigen lokalen Maßnahme macht, um eine Belagerung der Stadt zu verhindern.",["race:Human"]="Die Präsenz des Schwarzfelsclans im Rotkammgebirge ist eine schmerzhafte Erinnerung an den Ersten und Zweiten Krieg, und das Töten von Tharil'zun erobert dem Königreich geraubtes Land zurück.",["race:Orc"]="Tharil'zun gehört zu den finsteren Überresten der Alten Horde unter dem Banner des Schwarzfelsclans und dient Herren, die Thralls neue Ordnung jenseits des Meeres ablehnen."},sec={{t="Der Weg nach Steinwacht",b="Der gewundene Pass zwischen Seenhain und Burg Steinwacht ist zu einem Spießrutenlauf plötzlicher Hinterhalte geworden. Vorläufer und Abtrünnige des Schwarzfelsclans streifen durch die felsigen Kämme, schneiden Kundschafter ab und bedrohen jedwede Verstärkung, die versucht, zur Festung vorzustoßen. Marschall Marris identifiziert Tharil'zun als den Kommandanten, der diese koordinierten Angriffe leitet, und erklärt seine Beseitigung für notwendig, um zu verhindern, dass Seenhain vollständig eingekesselt wird."},{t="Den Vorläufern den Kopf abschlagen",b="Tharil'zun verkörpert einen gefährlichen Schlag von Schlachtfeldanführern: bösartig, schlau und in der Lage, die zersplitterten Orcräuber zu einer schlagkräftigen Angriffstruppe zusammenzuschweißen. Seinen Kopf im Schatten von Steinwacht zu fordern, verlangt das Durchbrechen verschanzter Außenposten des Schwarzfelsclans. Sein Tod bricht den Zusammenhalt der Vorläuferpatrouillen und ebnet der Allianz den Weg, um die Garnison anzugreifen, die sich in der Burg selbst verschanzt hat."}},faq={{q="Wer ist Tharil'zun?",a="Tharil'zun ist ein gefürchteter Orckommandant des Schwarzfelsclans, der dafür verantwortlich ist, die Vorläufer und Abtrünnigen anzuführen, die Hinterhalte entlang der Pfade zwischen Seenhain und Burg Steinwacht legen.",al={"wer ist tharilzun","tharil'zun geschichte","tharilzun boss"}},{q="Wo ist Tharil'zun zu finden?",a="Tharil'zun ist nahe Burg Steinwacht im nordöstlichen Rotkammgebirge stationiert und befehligt die Vorläufer, die die umliegenden Pässe und Außenposten patrouillieren.",al={"wo ist tharil'zun","tharilzun standort","tharil'zun finden"}},{q="Warum will Marschall Marris seinen Kopf?",a="Marris erkennt in Tharil'zun den gerissenen Taktiker, der die das Rotkammgebirge bedrängenden Hinterhalte lenkt. Die Forderung nach seinem Kopf stellt sicher, dass die Führung der Vorläufer zerschlagen wird, und liefert den unbestreitbaren Beweis für die Beseitigung der Bedrohung.",al={"warum tharilzun toeten","tharilzun kopfgeld grund"}},{q="Was geschieht, nachdem Tharil'zun besiegt wurde?",a="Die Beseitigung von Tharil'zun schwächt die Koordination der Vorläufer empfindlich und ermöglicht es Seenhains Verteidigern und Abenteurern, tiefer nach Burg Steinwacht vorzustoßen, um sich der Hauptgarnison des Schwarzfelsclans zu stellen.",al={"quest nach tharilzun","was folgt nach tharil'zun"}},{q="Warum sind Schwarzfelsorcs im Rotkammgebirge?",a="Überreste des Schwarzfelsclans stießen von der Brennenden Steppe nach Süden ins Rotkammgebirge vor und befestigten alte menschliche Außenposten wie Burg Steinwacht, um die Östlichen Königreiche zu bedrohen, während Sturmwinds Streitkräfte überstrapaziert bleiben.",al={"warum sind schwarzfelsorcs im rotkammgebirge","steinwacht orcs hintergrund"}},{q="Welche Voraussetzung muss vor der Jagd auf Tharil'zun erfüllt werden?",a="Marschall Marris verlangt von Abenteurern, zunächst ihren Mut zu beweisen, indem sie die Invasionsstreitkräfte in der Quest 'Die Bedrohung durch die Schwarzfelsorcs' dezimieren, bevor er sie auf Tharil'zun selbst ansetzt.",al={"tharilzun voraussetzung","wie tharilzun quest freischalten"}}},fx={["3b83e264"]={q="Warum benötigt Marschall Marris Tharil'zuns Kopf?",a="Marschall Marris fordert Tharil'zuns Kopf als definitiven Beweis für den Tod des Kriegsherrn. Tharil'zun ist ein gerissener und bösartiger Anführer, der Hinterhalte gegen die Verteidiger von Seenhain leitet, und Marris kann es sich nicht leisten, sich auf Gerüchte oder falsche Berichte zu verlassen, wenn die Sicherheit der gesamten Region am seidenen Faden hängt.",al={"wozu dient tharilzuns kopf","zweck von tharilzuns kopf","warum tharilzuns kopf mitnehmen"}},["66abe4be"]={q="Warum schickt Marschall Marris Euch anstatt der Stadtwache?",a="Die örtliche Garnison von Seenhain ist bis an ihre absolute Belastungsgrenze beansprucht. Da Sturmwind Verstärkungen zurückhält und Orc-Hinterhalte bis dicht an die Stadt heranreichen, kann Marschall Marris keine Männer entbehren, um tief in das Gebiet von Steinwacht vorzustoßen. Er muss sich auf erfahrene, unabhängige Abenteurer verlassen, um hochrangige gegnerische Kommandanten auszuschalten.",al={"warum einen abenteurer schicken","warum nicht die wachen vom rotkammgebirge","warum braucht marris mich"}}},fp="10,342,22.432.0,27.419.0,18.176.0,30.144.0,38.216.0,42.185.0,45.218.0,62.173.0"}
P.entries["quest:1918"] = {n="Das beschmutzte Element",s="Nachdem sie die aufgewühlten Wasserelementare rund um den Mystralsee erschlagen haben, entdecken Abenteurer eine faulige, leuchtende Kugel aus verdorbenem Wasser. Um zu verstehen, was den See und seine Elementargeister vergiftet hat, bringen sie die Probe zu Mastok Wutfauch am Splitterholzposten.",h="Nachdem sie die aufgewühlten Wasserelementare rund um den Mystralsee erschlagen haben, entdecken Abenteurer...",kw={"eschental","beschmutzte wasserkugel","verderbte elementare","der irdene ring","mastok wutfauch","mystralsee","splintertreeposten"},ang={["class:Shaman"]="Der verzerrte Zustand der Geister des Mystralsees bereitet den Schamanen große Sorge, da sie den Schmerz der Elemente vernehmen und die Notwendigkeit des Eingreifens des Irdenen Rings erkennen.",["faction:Horde"]="Der Splitterholzposten kann es sich nicht leisten, dass direkt vor seiner Haustür eine chaotische elementare Bedrohung schwelt, während Schildwachen der Allianz und Furbolgs die Versorgungswege der Horde gefährden.",["race:Tauren"]="Reisende der Tauren empfinden eine tiefe kulturelle Verpflichtung, das verdorbene Wasser des Landes zu heilen, was die Rettung des Mystralsees zu einer dringlichen spirituellen Aufgabe macht."},sec={{t="Verdorbene Wasser des Mystralsees",b="Der Mystralsee, gelegen im südöstlichen Eschental, ist in schwere Bedrängnis geraten. Die Wasserelementare, die seine Untiefen bewohnen, sind gewalttätig aggressiv und sichtlich korrumpiert geworden. Werden sie niedergestreckt, hinterlassen ihre Überreste seltsame, intensiv leuchtende Sphären fauliger Flüssigkeit anstelle reiner elementarer Essenz. Welche Verderbnis auch immer sich über den See gelegt hat, sie ist in diesen Kugeln konzentriert und signalisiert, dass die Unruhe weit über eine natürliche territoriale Aggression hinausgeht."},{t="Rat am Splintertreeposten suchen",b="Ohne klares Verständnis der am Werk befindlichen fauligen Magie wenden sich Späher der Horde an die Garnison am Splitterholzposten, um Rat einzuholen. Mastok Wutfauch, einer der Aufseher des Außenpostens, ist zunächst angewidert von der abscheulichen Probe, die ihm gebracht wird. Als Soldat und nicht als Gelehrter erkennt Mastok schnell, dass gewöhnlicher Stahl erkranktes Wasser nicht heilen kann, weshalb er den Abenteurer an die Elementarspezialisten des Irdenen Rings verweist."}},faq={{q="Was befindet sich in der Beschmutzten Wasserkugel?",a="Die Kugel enthält eine widerwärtige, konzentrierte Probe der Verderbnis, die derzeit den Mystralsee vergiftet. Sie entsteht aus den Überresten erschlagener Elementare und beweist, dass ihre spirituelle Verderbnis physisch und mächtig ist.",al={"inhalt der beschmutzten kugel","was ist in der wasserkugel","mystralsee wasserkugel"}},{q="Wo beginnt diese Quest?",a="Die Quest beginnt als Beutegegenstand beim Kampf gegen die wütenden oder beschmutzten Wasserelementare, die den Mystralsee im südlichen Zentrum von Eschental bewohnen.",al={"wo finde ich die wasserkugel","wie beginnt das beschmutzte element","questbeginn"}},{q="Warum will Mastok Wutfauch nichts damit zu tun haben?",a="Mastok Wutfauch ist ein Offizier der Horde, dessen Hauptaugenmerk auf dem militärischen Überleben und der Logistik am Splitterholzposten liegt. Er hat keinerlei Gespür dafür, wie man krankes magisches Wasser untersucht, weshalb er vorschlägt, stattdessen den Irdenen Ring aufzusuchen.",al={"wer ist mastok","warum mit mastok sprechen","rolle von mastok wutfauch"}},{q="Welches Interesse hat Der Irdene Ring daran?",a="Der Irdene Ring ist ein Schamanenorden, der sich dem Studium, der Beruhigung und der Wiederherstellung der Harmonie der Elemente widmet. Verderbte Elementare wie jene am Mystralsee fallen direkt unter seine spirituelle Zuständigkeit.",al={"warum der irdene ring","verbindung zum irdenen ring","wer ist der irdene ring"}},{q="Wohin führt die Untersuchung als Nächstes?",a="Mastok verweist Euch an Je'neu Sancrea, einen Schamanen des Irdenen Rings, der an der Westküste von Eschental am Zoram'gar Strand stationiert ist und das verdorbene Relikt fachgerecht untersuchen kann.",al={"was kommt als nächstes","folgequest nach das beschmutzte element","wohin als nächstes"}}},fp="20,271,30.469.0,30.429.1,40.219.0,28.140.0,53.222.0,44.208.0,39.175.1"}
P.entries["quest:1938"] = {n="Urs Abhandlung über Schattenmagie",s="Urs Abhandlung über Schattenmagie ist eine Quest, die von Zaubermeister Andromath im Magierviertel von Sturmwind vergeben wird. Er beauftragt Abenteurer damit, einen verbotenen, magisch versiegelten Folianten von dem abtrünnigen Magier Morganth wiederzubeschaffen, der damit in den Turm von Ilgalar im Rotkammgebirge floh.",h="Urs Abhandlung über Schattenmagie ist eine Quest, die von Zaubermeister Andromath im Magierviertel von...",kw={"andromath","ilgalar","morganth","schattenmagie","sturmwind","abhandlung","ur","magiersanktum"},ang={["class:Mage"]="Sturmwinds Magier nehmen interne Disziplinarangelegenheiten ernst und beauftragen vertrauenswürdige Zauberwirker damit, die gefährlichen Folgen eines Gefährten zu beseitigen, der sich verbotener Schattenmagie zugewandt hat.",["class:Warlock"]="Während die Kirin Tor und Sturmwinds Magier Urs Abhandlungen über die Schatten fürchten, begehren Hexenmeister häufig genau jene Mächte der Beschwörung außerweltlicher Wesen und dunkler Zauberei, die darin versiegelt liegen.",["faction:Alliance"]="Die Wiederbeschaffung des gestohlenen Folianten sichert die Grenzen des Rotkammgebirges vor Morganths wachsender magischer Bedrohung und schützt das Königreich Sturmwind vor abtrünniger Arkankunst."},sec={{t="Ein Schisma im Turm",b="Vor langer Zeit studierten drei vielversprechende Magier gemeinsam im Magiersanktum von Sturmwind. Mit der Zeit erlag einer von ihnen, Morganth, den Versuchungen der dunklen Künste und der Schattenmagie. Trotz verzweifelter Warnungen seiner Gefährten, die ihn drängten, sich von einer derart verderblichen Macht abzuwenden, weigerte er sich, seine Obsession aufzugeben. Er wurde förmlich aus dem magischen Orden der Stadt verbannt, doch er ging nicht mit leeren Händen – er stahl ein gefährliches Werk aus der Feder von Ur, einem berüchtigten Erzmagier, dessen Studien weit über die orthodoxe Arkankunst hinausgingen."},{t="Die Zuflucht des gefallenen Magiers",b="Morganth errichtete fernab der Aufsicht Sturmwinds einen neuen Stützpunkt und besetzte den Turm von Ilgalar in den Höhen des Rotkammgebirges. Zaubermeister Andromath kann nicht zulassen, dass solch gefährliches Wissen in den Händen eines Verstoßenen verbleibt, der verbotene Zauberei praktiziert. Indem er Abenteurer der Allianz damit beauftragt, die Verteidigung des Turms zu durchbrechen, will Andromath den Folianten sichern, bevor seine Bannsiegel fallen."},{t="Unversehrte Bannsiegel",b="Nachdem die Abhandlung aus Ilgalars Bibliothek geborgen und zum Magiersanktum zurückgebracht wurde, ist Andromath sichtlich erleichtert. Er hatte befürchtet, Morganth hätte die Schutzzauber bereits aufgelöst oder das Werk unerreichbar versteckt. Glücklicherweise hielten die magischen Siegel auf Urs Abhandlung stand und hinderten den abtrünnigen Zauberer daran, die verheerenden Geheimnisse zwischen ihren Seiten zu entfesseln."}},faq={{q="Wer hat die Abhandlung verfasst?",a="Die Abhandlung wurde von Ur verfasst, einem legendären Magier aus Dalaran, der für seine esoterischen Forschungen über außerweltliche Wesenheiten und Schattenmagie berühmt war.",al={"wer ist ur","autor der abhandlung","urs abhandlung autor"}},{q="Wer hat Urs Abhandlung über Schattenmagie gestohlen?",a="Morganth, ein ehemaliger Magier aus Sturmwind, stahl das Buch, als er der dunklen Magie verfiel und aus dem Magiersanktum verbannt wurde.",al={"wer stahl das buch","wer nahm die abhandlung","morganth buch"}},{q="Wo wird das Buch aufbewahrt?",a="Das Buch wird in der Bibliothek im Turm von Ilgalar aufbewahrt, hoch oben im Rotkammgebirge, wo Morganth seine neue Zuflucht errichtet hat.",al={"wo ist die abhandlung","turm von ilgalar buch standort","wo findet man urs abhandlung"}},{q="Hat Morganth es geschafft, das Buch zu lesen?",a="Nein. Als die Abhandlung zu Zaubermeister Andromath zurückgebracht wird, bestätigt er, dass die Schutzsiegel auf dem Buch gehalten haben, was bedeutet, dass Morganth es nie öffnen konnte.",al={"hat morganth das buch geöffnet","wurde die abhandlung geöffnet","sind die siegel gebrochen"}},{q="Warum wollen die Magier von Sturmwind das Buch zurück?",a="Der Foliant birgt tiefgründige Geheimnisse der Schattenmagie, die für Ungeübte den Ruin bedeuten können. Sturmwinds Magier halten es für viel zu gefährlich, ihn in den Händen eines Abtrünnigen wie Morganth zu lassen.",al={"warum das buch bergen","warum ist die abhandlung gefährlich","andromath ziel"}},{q="Wer vergibt diese Quest?",a="Die Quest wird von Zaubermeister Andromath angeboten, der sich im Magiersanktum im Magierviertel von Sturmwind aufhält.",al={"questgeber","wo quest urs abhandlung annehmen","andromath quest"}}},fx={["705e1c6d"]={q="Was ist Urs Abhandlung über Schattenmagie?",a="Es ist ein mächtiger und gefährlicher Wälzer, der die dunklen Geheimnisse der Schattenmagie erforscht. Er wurde von dem Magier des Kirin Tor, Ur, verfasst und seine Tiefen sind nicht für Ungeschulte gedacht, da das Eindringen in sein verbotenes Wissen direkt ins Verderben und in den Ruin führen kann. Um seinen Missbrauch zu verhindern, haben die Magier von Sturmwind den Band mit magischen Siegeln belegt.",al={"urs abhandlung über schattenmagie","was ist die abhandlung","was bewirkt urs abhandlung"}}},fp="29,282,21.515.0,22.395.0,12.383.1,23.135.0,40.123.0,23.145.0,37.174.1,49.186.0,21.118.0"}
P.entries["quest:1939"] = {n="Zaubermeister Andromath",s="High Sorcerer Andromath ist eine kurze Vorladung, die Magier der Allianz dazu auffordert, sich auf dem Gipfel des Magiersanktums in Sturmwind zu melden. High Sorcerer Andromath gilt als einer der herausragenden Erzmagier des Königreichs außerhalb der zerstörten Stadt Dalaran.",h="High Sorcerer Andromath ist eine kurze Vorladung, die Magier der Allianz dazu auffordert, sich auf dem Gipfel...",kw={"andromath","arkan","dalaran","jennea haubitz","das magierviertel","sturmwind","magiersanktum"},ang={["class:Mage"]="Diese Vorladung markiert den Übergang von routinemäßigen Zauberübungen unter Jennea Haubitz zur direkten Forschung an gefährlicher, spezialisierter Überlieferung an der Seite eines der führenden Erzmagier Sturmwinds.",["faction:Alliance"]="Da die überlebenden Magier von Dalaran mit dem Wiederaufbau ihrer zerstörten Stadt beschäftigt sind, ist die Allianz stark auf das eigene Sanktum von Sturmwind angewiesen, um Magier auszubilden und übernatürlichen Bedrohungen entgegenzuwirken."},sec={{t="Vorladung zum Turm",b="Im Magierviertel von Sturmwind weist die Ausbilderkoordinatorin Jennea Haubitz vielversprechende Zauberwirker zum Gipfel des Magiersanktums hinauf. High Sorcerer Andromath, einer der erfahrensten Praktizierenden der arkanen Künste, die aktiv in den südlichen Königreichen tätig sind, verlangt ausdrücklich eine Audienz bei aufstrebenden Magiern, die für gewichtigere Verantwortungen bereit sind."},{t="Ein Meister außerhalb von Dalaran",b="Da die nördliche Magokratie Dalaran im Dritten Krieg zerstört wurde und ihre überlebenden Zauberer mit dem Wiederaufbau beschäftigt sind, kommt Praktizierenden wie Andromath eine entscheidende strategische Bedeutung zu. Ohne leichten Zugang zu den Bibliotheken der Violetten Zitadelle verlässt sich die Allianz direkt auf erfahrene Erzmagier, die in Sturmwind stationiert sind, um uralte Bedrohungen zu studieren und Forschungen über schattenhafte, verbotene Künste zu leiten."}},faq={{q="Wer ist High Sorcerer Andromath?",a="High Sorcerer Andromath ist ein geschätzter erfahrener Magier, der ganz oben im Magiersanktum in Sturmwind residiert. Er ist bei seinen Kollegen als einer der mächtigsten und kenntnisreichsten Zauberwirker bekannt, die außerhalb von Dalaran aktiv sind.",al={"wer ist andromath","andromath hintergrundwissen","sturmwind hochmagier"}},{q="Wo finde ich High Sorcerer Andromath?",a="Er ist an der Spitze des Magiersanktums zu finden, dem spiralförmigen Turm im Magierviertel von Sturmwind.",al={"andromath fundort","wo ist andromath","high sorcerer andromath finden"}},{q="Warum schickt mich Jennea Haubitz zu ihm?",a="Jennea Haubitz identifiziert vielversprechende Zauberwirker, die der grundlegenden Ausbildung entwachsen sind, und schickt sie zu Andromath für höheren Rat und spezialisierte, gefährliche Forschungsaufträge.",al={"warum mit andromath sprechen","jennea haubitz empfehlung"}},{q="Wobei benötigt Andromath Hilfe?",a="Andromath rekrutiert fähige Magier, um dunkle arkane Geheimnisse zu untersuchen, und schickt sie speziell aus, um einen gefährlichen historischen Band zu bergen: Urs Abhandlung über Schattenmagie.",al={"andromath questreihe","was will andromath"}},{q="Warum wird Dalaran als 'abgeriegelt' beschrieben?",a="Jenneas Formulierung spiegelt wider, wie zurückgezogen die Kirin Tor seit dem Dritten Krieg sind. Nachdem die Geißel und die Brennende Legion ihre Stadt verwüstet hatten, wandten sich die überlebenden Zauberer von Dalaran nach innen, um sie wiederaufzubauen, und ließen nur wenige von ihnen an äußeren Angelegenheiten teilhaben.",al={"warum ist dalaran abgeriegelt","status von dalaran","was ist mit dalaran passiert"}},{q="Ist diese Quest exklusiv für Magier?",a="Ja. Diese Vorladung ist Teil des dedizierten Trainings- und Questpfads für Magier der Allianz, die ihre Handwerkskunst vorantreiben.",al={"können nicht-magier das machen","nur für magier quest"}}},fx={["56d3f2e8"]={q="Warum schickt mich Jennea Haubitz, anstatt sich selbst darum zu kümmern?",a="Jennea Haubitz dient als Ausbilderin im Magiersanktum und führt angehende Anwender der arkanen Künste. High Sorcerer Andromath hat ausdrücklich darum gebeten, mit Euch zu sprechen, einem versierten und aufstrebenden Magier, der für fortgeschrittenere Angelegenheiten bereit ist, anstatt die Mentoren der Akademie von ihren Lehrverpflichtungen abzuhalten.",al={"warum schickt sie mich","warum geht jennea nicht selbst","warum will andromath mich"}}},fp="23,241,20.356.0,24.400.0,31.239.0,41.114.0,42.168.0,35.167.1,42.253.0,33.108.0"}
P.entries["quest:1940"] = {n="Makellose Spinnenseide",s="Makellose Spinnenseide ist eine Initiationsaufgabe für aufstrebende Magier der Allianz, die von Zaubermeister Andromath in Sturmwind vergeben wird. Um sich ein Gewand zu verdienen, das dem Rang eines Adepten gebührt, wird der Zauberwirker in die finsteren Wälder des Dämmerwalds entsandt, um erstklassige Seide von Aas-Einsiedlerspinnen zu erbeuten. Die gesammelten Spulen werden Schneiderin Wynne Larson im Magierviertel überbracht, um verzauberte Roben anzufertigen.",h="Makellose Spinnenseide ist eine Initiationsaufgabe für aufstrebende Magier der Allianz, die von Zaubermeister...",kw={"andromath","aas-einsiedler","dämmerwald","larsons gewänder","magierroben","makellose spinnenseide","sanktum der magier","wynne larson"},ang={["class:Mage"]="Dieser Übergangsritus schlägt die Brücke zwischen der Lehrzeit und wahren Adepten und stellt sicher, dass jeder Magier aus Sturmwind Roben trägt, die aus von ihm selbst bezwungenen Gefahren gewoben wurden.",["faction:Alliance"]="Der Dämmerwald bleibt ein gefährliches Grenzland für die Untertanen von Sturmwind und erfordert von Magiern, das sichere Refugium der Hauptstadt zu verlassen, um seltene regionale Ressourcen zu beschaffen.",["profession:Tailoring"]="Die Methoden von Wynne Larson zeigen, wie hochwertige Fasern wilder Monster in magisch empfängliche Stoffe verwandelt werden können, die gewöhnlicher Schafwolle oder Leinen weit überlegen sind."},sec={{t="Gewänder des Adepten",b="Im Magiersanktum misst sich Anerkennung nicht nur an der Beherrschung des Arkanen, sondern auch an den Insignien ihrer Anwender. Zaubermeister Andromath erkennt, wann ein Schüler den einfachen Lehrlingsarbeiten entwachsen ist, und weist ihn an, für einen Adepten angemessene Gewänder in Auftrag zu geben. Statt fertige Waren einfach zu kaufen, muss der Magier sowohl Feldtauglichkeit als auch Urteilskraft beweisen, indem er makellose, unversehrte Seide direkt von gefährlichen Bestien beschafft."},{t="Der Webstuhl des Dämmerwalds",b="Das benötigte Material lässt sich nicht an herkömmlichen Händlerständen finden. Es muss behutsam den giftigen Aas-Einsiedlerspinnen entnommen werden, die durch das heimgesuchte Dunkel des Dämmerwalds streifen. Sobald acht erstklassige Exemplare gesammelt sind, werden sie quer durch die Stadt zu Larsons Gewänder im Magierviertel gebracht, wo Schneiderin Wynne Larson bereitsteht, um die feinen Fäden zu einer Robe von arkaner Bedeutung zu spinnen."}},faq={{q="Wer schickt Magier auf diesen Auftrag?",a="Zaubermeister Andromath, der dem Magiersanktum in Sturmwind vorsteht, überträgt diese Aufgabe Zauberwirkern, die ihre Hingabe unter Beweis gestellt haben.",al={"wer gibt makellose spinnenseide","questgeber makellose spinnenseide","andromath quest"}},{q="Wo wird die Seide gesammelt?",a="Die Seide wird von Aas-Einsiedlerspinnen gewonnen, die durch die heimgesuchten Wälder und spinnwebenverhangenen Lichtungen des Dämmerwalds streifen.",al={"woher bekommt man makellose seide","spinnen aufenthaltsort","fundort aas-einsiedler"}},{q="Wer fertigt die Robe aus der Seide?",a="Wynne Larson, eine professionelle Schneiderin in Larsons Gewänder im Magierviertel von Sturmwind, übernimmt das Weben und Schneidern.",al={"wer webt die seide","wynne larson","larsons gewänder"}},{q="Warum verwenden Magier Spinnenseide für Kleidung?",a="Makellose Spinnenseide bietet natürliche Widerstandskraft sowie eine außergewöhnlich feine Webstruktur und ergibt einen leichten Stoff, der subtile Verzauberungen aufnehmen kann, ohne den Zauberwirker zu beschweren.",al={"warum spinnenseide","spinnenseide magierroben"}},{q="Was folgt nach der Abgabe der Seide?",a="Nachdem Wynne die Seide geprüft und an ihrem Webstuhl gearbeitet hat, überreicht sie dem Magier das fertige Astralknotengewand.",al={"folgequest nach makellose spinnenseide","wie geht es weiter"}},{q="Ist jede Spinnenseide aus dem Dämmerwald annehmbar?",a="Nein. Die feinen Verzauberungen, die bei Larsons Gewänder eingewoben werden, verlangen ausdrücklich makellose Exemplare, die sorgsam von Aas-Einsiedlern gewonnen wurden, während gröbere Gespinste abgelehnt werden.",al={"kann man normale spinnenseide benutzen","makellose vs normale seide"}}},fx={a495a13a={q="Warum schickt Euch High Sorcerer Andromath los, um Seide zu sammeln?",a="High Sorcerer Andromath sieht Eure unerschütterliche Hingabe an die arkanen Künste und glaubt, dass es an der Zeit ist, dass Eure Kleidung Eure wachsende Meisterschaft widerspiegelt. Anstatt Euch ein fertiges Gewand auszuhändigen, erwartet das Wizard's Sanctum von Euch, dass Ihr es Euch verdient, indem Ihr den Gefahren des Dämmerwalds trotzt, um die seltenen Materialien zu sammeln, die für ein Gewand eines Adepten benötigt werden.",al={"warum andromath seide will","andromaths motiv","warum gibt andromath diese quest"}},["8d44c073"]={q="Welche Kreaturen müsst Ihr für die Seide jagen?",a="Ihr werdet ausgesandt, um die Aas-Einsiedlerspinnen zu jagen, die in den dunklen Wäldern des Dämmerwalds lauern. Diese giftigen Spinnentiere spinnen einen außergewöhnlich haltbaren und resonanten Faden, doch nur ihre feinsten, makellosen Stränge eignen sich zum Weben eines verzauberten Gewandes.",al={"wen muss ich für makellose seide jagen","welche spinnen lassen die seide fallen","aas-einsiedlerspinne dämmerwald"}}},fp="20,381,22.460.0,20.400.0,35.146.0,28.117.0,34.131.0,42.185.0,37.113.0,44.163.0"}
P.entries["quest:1941"] = {n="Managewirkte Robe",s="Managewirkte Robe markiert den Abschluss des ehrgeizigen Handwerksauftrags einer Schneiderin im Herzen von Sturmwind. Wynne Larson präsentiert ein fertiges, verzaubertes Gewand, gewoben aus feinen Materialien – ein stolzes Aushängeschild für das Geschäft ihrer Familie. Für aufstrebende Zauberwirker stellt es ein frühes Abzeichen arkaner Hingabe und hochwertiger menschlicher Handwerkskunst dar.",h="Managewirkte Robe markiert den Abschluss des ehrgeizigen Handwerksauftrags einer Schneiderin im Herzen von...",kw={"lehrlingsrobe","tuchhändler","larson clothiers","das magierviertel","managewirkte robe","sturmwind","schneider","wynne larson"},ang={["class:Mage"]="Für einen Magierlehrling, der in den Türmen von Sturmwind studiert, signalisiert das Anlegen einer maßgeschneiderten managewirkten Robe den Übergang zu ernsthafter Feldforschung und eigenständigem Zauberwirken.",["faction:Alliance"]="Vielversprechende Recken in den hiesigen Geschäften der Hauptstadt auszustatten, trägt dazu bei, Sturmwinds Ansehen und Eigenständigkeit in unruhige Gebiete hinauszutragen.",["profession:Tailoring"]="Wynne Larsons Arbeit veranschaulicht den hohen Standard menschlicher Schneiderei und zeigt, wie weltliche Materialien gewoben werden können, um flüchtige arkane Macht zu bändigen und zu nutzen."},sec={{t="Larson Clothiers",b="Im geschäftigen Magierviertel von Sturmwind versorgt Larson Clothiers Anwender der arkanen Künste, die Kleidung benötigen, die für das Kanalisieren flüchtiger Energien geeignet ist. Die Herstellung feiner magischer Gewänder erfordert seltene Materialien, sorgfältige Nadelarbeit und ein scharfes Auge für Fäden, die sich unter mystischer Resonanz nicht auflösen. Wynne Larson ist persönlich stolz auf die Kleidungsstücke, die ihren Laden verlassen, und betrachtet jede im Feld getragene Robe als lebendiges Zeugnis für den Namen Larson."},{t="Gewobene Zauberei",b="Die managewirkte Robe soll Magierlehrlingen helfen und bietet Komfort, Beweglichkeit sowie die praktische Widerstandsfähigkeit, die beim Durchstreifen umkämpfter Gebiete erforderlich ist. Nach der Lieferung der notwendigen Komponenten setzt Wynne den letzten Stich selbst und überreicht das fertige Gewand nicht bloß als Warengeschäft, sondern als Meisterwerk, das Blicke auf sich ziehen und die Qualität der Larson-Schneiderei im ganzen Königreich bekannt machen soll."}},faq={{q="Wer fertigt die Managewirkte Robe?",a="Wynne Larson fertigt das Kleidungsstück bei Larson Clothiers im Magierviertel von Sturmwind an.",al={"wer stellt managewirkte robe her","wynne larson robe","larson clothiers"}},{q="Warum möchte Wynne Larson, dass Ihr die Robe mit Stolz tragt?",a="Wynne betrachtet die Robe als eine ihrer bisher feinsten Kreationen. Sie bittet Abenteurer darum, Larson Clothiers weiterzuempfehlen, wann immer andere die Handwerkskunst bewundern, und sieht darin lebendige Werbung für ihr Geschäft.",al={"warum larson weiterempfehlen","larson werbung","wynne dialog"}},{q="Wo befindet sich Larson Clothiers?",a="Das Geschäft befindet sich im Magierviertel von Sturmwind, ganz in der Nähe der Akademien und Sankten, an denen sich die Zauberwirker der Allianz versammeln.",al={"larson laden standort","wo ist wynne larson","das magierviertel schneiderei"}},{q="Was für ein Kleidungsstück ist eine Managewirkte Robe?",a="Es ist eine verzauberte Stoffrobe für Anwender der Magie, maßgeschneidert, um mystische Energien zu kanalisieren und gleichzeitig praktischen Schutz auf gefährlichen Reisen zu bieten.",al={"managewirkte robe lore","was ist managewirkte robe","was bewirkt die robe"}},{q="Ist dies Teil einer längeren Questreihe?",a="Ja, der Abschluss dieses Auftrags dient als letzter Schritt einer Schneider-Questreihe, bei der Wynne Larson mit Materialien für ihre Arbeit unterstützt wird.",al={"managewirkt reihe","roben questreihe","questreihe ende"}},{q="Welche Fraktion kann diese Quest annehmen?",a="Diese Quest ist ausschließlich Mitgliedern der Allianz vorbehalten, da Wynne Larson vollständig innerhalb der Hauptstadt Sturmwind tätig ist.",al={"allianz oder horde robe","kann horde managewirkte robe bekommen","fraktionsvoraussetzung"}}},fp="14,347,16.468.0,13.412.0,30.95.0,59.208.0,34.134.0,41.159.0,35.135.0,38.123.0"}
P.entries["quest:1942"] = {n="Astralknotengewand",s="Das Astralknotengewand ist der Höhepunkt eines engagierten Handwerksunterfangens in Sturmwind. Nachdem ein Abenteurer den Gefahren der Wildnis getrotzt hat, um seltene Spinnenseide zu sammeln, überreicht er die Materialien der geschickten Schneiderin Wynne Larson. Das Ergebnis ist ein feines, magisches Gewebe, das sich sowohl für tückische Reisen als auch für Empfänge der feinen Gesellschaft eignet.",h="Das Astralknotengewand ist der Höhepunkt eines engagierten Handwerksunterfangens in Sturmwind.",kw={"astralknotengewand","stoffrüstung","das magierviertel","makellose spinnenseide","seidenrobe","sturmwind","schneiderei","wynne larson"},ang={["class:Mage"]="Das Astralknotengewand verbindet die arkane Würde von Sturmwinds Magierviertel mit praktischen Verzauberungen, die auf Reisen jenseits der befestigten Mauern des Königreichs vonnöten sind.",["faction:Alliance"]="Die Handwerker von Sturmwind sind stolz darauf, Streiter der Allianz mit einer Ausrüstung zu versorgen, die königlichen Hallen und gefährlichen Frontlinien gleichermaßen gerecht wird.",["profession:Tailoring"]="Wynne Larsons Arbeit verkörpert den Gipfel der Verarbeitung makelloser Spinnenseide und zeigt, wie rohe, monströse Materialien zu großartiger Mode veredelt werden können."},sec={{t="Der Witz einer Weberin",b="Im geschäftigen Magierviertel von Sturmwind versorgen Schneider und Schneiderinnen die arkane Elite ebenso wie den reisenden Adel. Wynne Larson ist eine dieser Handwerkerinnen, berühmt für ihre Fähigkeit, makellose Spinnenseide zu strapazierfähigen, verzauberten Gewändern zu verweben. Bekannt für ihren verspielten Sinn für Humor, scherzt sie darüber, zusätzliche Reste der kostbaren Seide für ihre eigene Garderobe zu behalten, bevor sie ihre fachmännisch geschneiderten Schöpfungen übergibt."},{t="Vielseitige Eleganz",b="Das Astralknotengewand wird von stofftragenden Zauberwirkern geschätzt, die sowohl Widerstandskraft als auch Raffinesse verlangen. Gewebt aus zarter, doch robuster Seide, die von gefährlichen Spinnentieren gesammelt wurde, ist das Gewand darauf ausgelegt, den Härten des Kampfes standzuhalten, während es zugleich das gepflegte Erscheinungsbild bewahrt, das bei formellen Banketten in Burg Sturmwind erwartet wird."}},faq={{q="Was ist das Astralknotengewand?",a="Es ist ein fein geschneidertes Gewand, das von Wynne Larson in Sturmwind hergestellt wird. Gefertigt aus makelloser Spinnenseide, ist es eigens dafür geschaffen, stofftragenden Anwendern sowohl im abenteuerlichen Kampf als auch bei formellen Anlässen der gehobenen Gesellschaft zu dienen.",al={"was ist das astralknotengewand","astralknotenrobe","astralknotengewänder"}},{q="Wer stellt das Astralknotengewand her?",a="Wynne Larson, eine im Magierviertel von Sturmwind ansässige Schneiderin, fertigt das Stück an, sobald sie mit den notwendigen exotischen Materialien versorgt wird.",al={"wer stellt astralknoten her","wynne larson quest","astralknoten schneider"}},{q="Welche Materialien werden zur Fertigstellung dieses Gewands benötigt?",a="Das Gewand erfordert makellose Spinnenseide, die von tödlichen Spinnen in den wilden Regionen der Welt erbeutet wird, verwoben mit Schneidertechniken, die die natürliche Stärke und Verzauberbarkeit der Seide bewahren.",al={"materialien für astralknoten","benötigte spinnenseide","wie wird es hergestellt"}},{q="Warum scherzt Wynne Larson darüber, übrig gebliebene Seide zu behalten?",a="Makellose Spinnenseide ist unter Schneidern außergewöhnlich selten und begehrt. Wynne scherzt darüber, das Gewand kurz zu schneidern, um ein paar Reste für sich selbst zu behalten, übergibt die vollendete Arbeit jedoch vollständig.",al={"hat sie meine seide gestohlen","wynne larson witz","kurze robe"}},{q="Wo in Sturmwind findet diese Schneiderarbeit statt?",a="Wynne Larson befindet sich im Magierviertel von Sturmwind, einem Viertel, das Gelehrten, Arkanisten und spezialisierten Schneidern ein Zuhause bietet, die sich auf verzauberte Textilien verstehen.",al={"wo ist wynne larson","astralknoten ort","wo astralknoten abgeben"}},{q="Wer trägt üblicherweise das Astralknotengewand?",a="Magier der Allianz verdienen und schätzen das Gewand wegen seines leichten, schützenden Gewebes und seines würdevollen Aussehens.",al={"wer nutzt astralknoten","für welche klasse ist das","wer trägt es"}}},fx={["96918ee1"]={q="Warum fertigt Wynne Larson das Astral Knot Garment an?",a="Wynne Larson ist eine geschickte Schneiderin in Sturmwind, die sich bereit erklärt, das Gewand als Krönung Eurer Bemühungen zu weben. Nachdem sie Euch durch gefährliche Länder geschickt hat, um seltene Komponenten wie Makellose Spinnenseide zu sammeln, ist sie stolz darauf, außergewöhnliche Kleidung für Magieanwender zu fertigen, die praktischen Schutz mit exquisiter, formeller Eleganz verbindet.",al={"warum fertigt wynne larson das gewand an","wynne larson motiv astral knot garment","warum fertigt wynne das gewand"}}},fp="19,317,14.408.0,18.327.0,32.228.0,35.136.0,53.212.0,56.207.0,50.158.0,44.99.0"}
P.entries["quest:1943"] = {n="Gespräch mit Deino",s="\"Speak with Deino\" ist eine Aufforderung, die vielversprechende Magier der Horde dazu anleitet, eine erfahrene Praktizierende in Orgrimmar aufzusuchen. Deino, eine Trollmagierin, die aus dem Tal der Geister heraus operiert, benötigt eine Fachkraft, um entscheidende Arbeiten im Namen ihrer Kunst durchzuführen. Ihr Ruf zu folgen, ebnet den Weg zu tieferem magischen Studium und lebenswichtigen Aufgaben in ganz Kalimdor.",h="\"Speak with Deino\" ist eine Aufforderung, die vielversprechende Magier der Horde dazu anleitet, eine...",kw={"anastasia hirschbrunn","darkbriar lodge","deino","magierquest","orgrimmar","quithas","tal der geister","waters of xavian"},ang={["class:Mage"]="Diese Quest ist ein entscheidender Schritt in Eurer formalen arkanen Ausbildung, der Euch mit ranghohen Zauberwirkern in Orgrimmar verbindet.",["faction:Horde"]="Die Vorladung verbindet regionale Ausbilder aus Lordaeron und Durotar mit der zentralen arkanen Führung, die sich in Orgrimmar versammelt.",["race:Troll"]="Deino repräsentiert die fokussierte arkane Disziplin, die von einigen wenigen unter den Darkspear tribe praktiziert wird."},sec={{t="Eine Vorladung nach Orgrimmar",b="Wenn Praktizierende der arkanen Künste innerhalb der Horde ihre Fähigkeiten verfeinern, erkennen Ausbilder, wann ein Schüler für anspruchsvollere Unternehmungen bereit ist. Mentoren wie Anastasia Hirschbrunn in der Unterstadt verweisen sich entwickelnde Magier nach Orgrimmar. Dort, versteckt im von Trollen dominierten Viertel, warten spezialisierteres Wissen und gefährliche Besorgungen auf Euch."},{t="Das Tal der Geister und Darkbriar Lodge",b="Deino hat ihr Zuhause in der Darkbriar Lodge im Tal der Geister von Orgrimmar. Unter den Dunkelspeer sind engagierte Praktizierende der arkanen Künste im Vergleich zu Hexendoktoren und Priestern relativ selten, was Deino zu einer bemerkenswerten Autorität in der Hauptstadt macht. Sie arbeitet nicht nur für lokale Belange, sondern für die umfassenderen Interessen der arkanen Praktizierenden der Horde und sucht nach ehrgeizigen Magiern, die bereit sind, fernen Gefahren zu trotzen."}},faq={{q="Wer schickt Euch, um mit Deino zu sprechen?",a="Magierlehrer wie Anastasia Hirschbrunn im Magieviertel der Unterstadt schicken angehende Magier nach Orgrimmar, sobald diese ausreichende Fähigkeiten erlangt haben.",al={"questgeber","wer startet dies","wo erhalte ich speak with deino"}},{q="Wo kann ich Deino finden?",a="Deino befindet sich in der Darkbriar Lodge, die im Tal der Geister auf der westlichen Seite von Orgrimmar liegt.",al={"deino standort","wo ist deino","darkbriar lodge standort"}},{q="Warum benötigt Deino Unterstützung?",a="Deino beaufsichtigt wichtige Forschungen und Aufgaben, die für die Gesellschaft der Magier der Horde als unerlässlich erachtet werden. Sie rekrutiert fähige Zauberwirker, damit diese sich in gefährliche Gebiete begeben und seltene magische Ressourcen sichern.",al={"warum benötigt deino hilfe","was möchte deino"}},{q="Was geschieht, nachdem Ihr Euch bei Deino gemeldet habt?",a="Sobald Ihr Euch bei Deino meldet, weist sie Euch in ihre Mission ein und schickt Euch zu Eurer nächsten Aufgabe, die mit der Beschaffung der Waters of Xavian beginnt.",al={"nächste quest","was kommt danach","folgequest"}},{q="Ist diese Quest für alle Klassen verfügbar?",a="Nein. Diese Quest wird ausschließlich Magiern der Horde als Teil ihres klassenspezifischen Fortschritts und Trainings angeboten.",al={"ist dies nur für magier","können hexenmeister dies tun","klassenbeschränkung"}},{q="Sind Trollmagier in der Horde verbreitet?",a="Arkane Magie ist unter den Darkspear-Trollen weniger verbreitet als spiritueller Schamanismus, Voodoo oder das Priestertum der Loa. Dennoch zeigen Persönlichkeiten wie Deino, dass einige Trolle das formale Studium der arkanen Kräfte vollständig gemeistert haben.",al={"trolle nutzen arkane magie","darkspear magier lore"}}},fx={["2e9f17ef"]={q="Warum schicken die Magierlehrer Euch zu Deino?",a="Während Eure Beherrschung der arkanen Künste wächst, erkennen Eure Mentoren in den Hauptstädten, dass tiefere Geheimnisse jenseits der Standardausbildung auf Euch warten. Die Troll-Magierin Deino in Orgrimmar beaufsichtigt fortgeschrittene Unternehmungen, die für die kollektive Gesellschaft der Magier in der Horde von entscheidender Bedeutung sind. Lehrer wie Anastasia Hirschbrunn in der Unterstadt verweisen vielversprechende Praktizierende an sie, damit Ihr zu Angelegenheiten beitragen könnt, die für Euer gemeinsames Handwerk lebenswichtig sind.",al={"warum zu deino schicken","motiv von anastasia hirschbrunn","warum schickt mich anastasia hirschbrunn"}}},fp="16,334,22.343.0,41.411.0,34.141.0,23.111.0,31.186.0,38.141.0,39.118.0,36.217.0"}
P.entries["quest:1944"] = {n="Wasser von Xavian",s="Wasser von Xavian ist eine Magierquest der Horde, die von Deino in Orgrimmar angeboten wird. Um uralten elfischen Geheimnissen auf den Grund zu gehen, beauftragt sie ihren Lehrling damit, zu den Ruinen von Xavian in Eschental zu reisen und eine Probe von dessen höchstem Wasserfall zu schöpfen.",h="Wasser von Xavian ist eine Magierquest der Horde, die von Deino in Orgrimmar angeboten wird.",kw={"eschental","deino","fläschchen","magierquest","orgrimmar","satyr","splintertree","wasser von xavian","xavian"},ang={["class:Mage"]="Diese Quest ist ein exklusives Studienritual für Magier der Horde, das ihre Fähigkeit prüft, in feindselige Wildnis vorzudringen, um ungezähmte arkane Reagenzien zu gewinnen.",["faction:Horde"]="Der Splitterholzposten dient der Horde im östlichen Eschental als nächstgelegener Stützpunkt, um die von Satyren heimgesuchte Wildnis rund um Xavian zu durchqueren."},sec={{t="Die Neugier einer Magierin",b="In den dunklen Winkeln des Tal der Geister sucht die Trollmagierin Deino nach verbliebenen Vorkommen ursprünglicher arkaner Energie in ganz Kalimdor. Ihr Blick richtet sich auf Xavian, eine uralte Stadt der Nachtelfen, die tief unter dem östlichen Blätterdach von Eschental verborgen liegt. Unter Gelehrten besagen Legenden, dass die Stadt vor der Zerschlagung voller magischem Wissen war, und ihren Gewässern wird nachgesagt, dass sie wirkmächtige arkane Eigenschaften bewahrt haben, die moderne Zauberwirker nur zu gern analysieren möchten."},{t="Die Ruinen von Xavian",b="Die Quelle dieser Gewässer zu erreichen, ist kein einfacher Botengang. Xavian gehört nicht länger friedlichen elfischen Weisen; es ist zerfallen und wird nun von wilden, verderbten Satyren überrannt, die ihr Territorium erbittert gegen Außenstehende verteidigen. Neugierige Magier müssen Satyrnaar hinter sich lassen und durch gefährliche Wasserläufe waten, wobei sie sowohl lauernden Bestien als auch dämonischen Wächtern ausweichen müssen, um Deinos Fläschchen am Fuße des gewaltigen Wasserfalls der Stadt zu füllen."}},faq={{q="Wer ist Deino?",a="Deino ist eine Magierlehrerin und Gelehrte der Trolle im Tal der Geister in Orgrimmar. Sie unterweist Magier der Horde und erforscht Relikte uralter Magie Kalimdors.",al={"wer gibt wasser von xavian","deino orgrimmar"}},{q="Wo befindet sich Xavian?",a="Xavian ist eine uralte Ruinenstadt im nordöstlichen Eschental, nördlich des Splitterholzpostens und unmittelbar nordwestlich der Satyrfestung Satyrnaar.",al={"xavian ort","wo ist xavian","xavian finden"}},{q="Warum möchte Deino dieses Wasser haben?",a="Gelehrtenberichte besagen, dass Xavian einst gewaltiges magisches Wissen barg, und seinen Gewässern wird nachgesagt, noch immer arkane Macht in sich zu tragen. Deino verlangt nach einer frischen Probe aus der Quelle des Wasserfalls, um ihre Eigenschaften zu analysieren.",al={"warum xavian-wasser holen","zweck von xavian-wasser"}},{q="Welche Gefahren bewachen die Ruinen von Xavian?",a="Die Ruinen werden von Satyren heimgesucht – dämonischen, verderbten Wesen, die Eindringlinge verabscheuen und ihr Territorium aggressiv gegen neugierige Magier verteidigen.",al={"xavian feinde","wer kontrolliert xavian"}},{q="Wo genau wird die Wasserprobe gesammelt?",a="Die Probe muss aus dem Becken direkt am Fuße des höchsten Wasserfalls in den Ruinen von Xavian in Deinos Fläschchen geschöpft werden.",al={"wasserfall ort","wo fläschchen füllen","xavian wasserfall"}},{q="Was folgt, nachdem man die Probe zu Deino zurückgebracht hat?",a="Zufrieden mit der Wasserprobe schickt Deino den Magier mit der Quest Lachende Schwestern in die nächste Phase der Studien, die sich um die Dryaden in Eschental dreht.",al={"wasser von xavian folgequest","nächste quest nach wasser von xavian"}}},fx={["6a4223ea"]={q="Wozu dient die Wasserprobe von Xavian?",a="Die uralte Stadt Xavian ist unter Gelehrten für ihr vergessenes Wissen legendär, und ihr Wasser soll über gewaltige magische Kräfte verfügen. Deino möchte eine unverfälschte Probe, die direkt vom Fuß des höchsten Wasserfalls der Stadt geschöpft wurde, damit sie ihre verborgenen arkanen Eigenschaften zurück in Orgrimmar untersuchen kann.",al={"was bewirkt xavian-wasser","warum xavian-wasser sammeln","verwendung der xavian-wasserprobe"}}},fp="16,230,18.440.0,19.426.0,13.165.0,24.152.0,31.207.0,39.147.0,44.129.0,52.147.1"}
P.entries["quest:1945"] = {n="Lachende Schwestern",s="Lachende Schwestern ist eine Horde-Quest, die Magier in das Herz von Eschental führt, um verzauberte Haarlocken von wilden Dryaden zu sammeln. Das Material ist für Kil'hala bestimmt, einen erfahrenen Trollschneider im Wegekreuz, der daraus eine ermächtigte Magierrobe weben soll. Die Jagd auf die Töchter des Cenarius unterstreicht die unerbittlichen Reibungen zwischen den Zauberkundigen der Horde und den einheimischen Verteidigern des uralten Waldes.",h="Lachende Schwestern ist eine Horde-Quest, die Magier in das Herz von Eschental führt, um verzauberte...",kw={"eschental","das wegekreuz","deino","dryade","haar","kil'hala","lachende schwestern","raynewood","hexenmeisterrobe"},ang={["class:Mage"]="Dieser Initiationsritus lehrt aufstrebende Magier, dass selbst die heiligen Waldgeister von Eschental für die Materialien des arkanen Handwerks geerntet werden können.",["faction:Horde"]="Das Erschlagen der Dryaden von Eschental verschärft den Konflikt zwischen der expansionistischen Präsenz der Horde und den heiligen Waldwächtern im Dienste der Nachtelfen.",["profession:Tailoring"]="Die Quest beleuchtet die seltene Kunst, lebendige magische Fasern in Stoffrüstungen einzuweben, und stellt das meisterhafte Können zur Schau, das Kil'hala im Wegekreuz anwendet."},sec={{t="Das Weben des Arkanen",b="Nach ihren Bemühungen, verdorbenes Wasser aus Xavian zu beschaffen, werden aufstrebende Magier von Deino in Orgrimmar angewiesen, bei der Herstellung ihrer eigenen verzauberten Gewänder zu helfen. Arkane Schneiderei dieser Art erfordert Materialien, die von roher magischer Essenz durchdrungen sind. Dryadenlocken, die von Natur aus von der urzeitlichen Lebenskraft des Waldes erfüllt sind, besitzen die nötigen Eigenschaften, um kunstvolle magische Gewänder zu weben, die die Kräfte eines Zauberwirkers schützen und verstärken können."},{t="Auf der Pirsch bei Raynewood",b="Um diese Locken zu erbeuten, müssen Magier nach Süden in Richtung Rajenbaum in Eschental vordringen. Die lachenden Schwestern – flinke Walddryaden, die mit den Nachtelfen verbündet sind – bewachen diese Haine erbittert gegen vordringende Holzfäller und Fremde gleichermaßen. Da diese Waldfeen ihr Haar niemals freiwillig an Zauberkundige der Horde abtreten würden, wird die Ernte unter dem Blätterdach uralter Bäume unweigerlich mit Blut bezahlt."},{t="Das Vorrecht des Wirkers",b="Einmal gesammelt, werden die Locken südwärts über die Grenze in die staubige Siedlung Das Wegekreuz im Brachland gebracht. Dort nimmt der Trollschneider Kil'hala den Tribut ohne Reue entgegen. Obwohl er den Verlust der Waldkreaturen mit einer Spur von Ironie zur Kenntnis nimmt, verliert Kil'hala keine Zeit, die verzauberten Strähnen praktisch zu nutzen, wohl wissend, dass Macht in der Horde oft unnachgiebige Entschlossenheit erfordert."}},faq={{q="Wer vergibt die Quest, die lachenden Schwestern zu jagen?",a="Deino, eine Trollmagierin in der Darkbriar Lodge in Orgrimmar, schickt Magier auf diese Botenfahrt als Belohnung und Vorbereitung für die Herstellung ihrer Klassenroben.",al={"wer gibt quest lachende schwestern","lachende schwestern questgeber","deino quest"}},{q="Was sind die lachenden Schwestern?",a="Lachende Schwestern sind Dryaden, Töchter des Halbgottes Cenarius. Mit dem Oberkörper von Nachtelfinnen und dem Unterkörper von Rehen beschützen sie die Wälder und heiligen Lichtungen von Eschental.",al={"was ist eine lachende schwester","lachende schwester dryade","sind lachende schwestern dryaden"}},{q="Wo sind die lachenden Schwestern zu finden?",a="Sie durchstreifen die Waldgebiete nahe Rajenbaum und die Lichtung der lachenden Schwestern im zentralen Eschental, unweit des Handelswegs.",al={"lachende schwestern ort","wo sind lachende schwestern","lachende schwestern finden"}},{q="Warum braucht Kil'hala Dryadenhaar?",a="Dryadenhaar ist von natürlicher Verzauberung durchdrungen, was es zu einem idealen Faden für Kil'hala macht, um daraus spezielle, magisch resonante Roben für die arkanen Künste zu weben.",al={"warum dryadenhaar","warum haar der lachenden schwester","wofür ist das haar"}},{q="Wo gebe ich das Haar ab, sobald es gesammelt ist?",a="Überbringt das Haar Kil'hala, einem Meisterschneider im geschäftigen Außenposten Das Wegekreuz im Brachland.",al={"wo ist kilhala","lachende schwestern abgeben","das wegekreuz schneider hexenmeister"}},{q="Was geschieht, nachdem Kil'hala das Haar entgegengenommen hat?",a="Nachdem Kil'hala das Haar erhalten hat, nimmt er sich einen kurzen Moment Zeit, um das Material zu bearbeiten, bevor er die Folgeaufgabe Netherspitzengewand anbietet, um die Robe fertigzustellen.",al={"folgequest nach lachende schwestern","nach lachende schwestern","netherspitzengewand folgequest"}}},fx={["6db1d5c5"]={q="Warum schickt Euch Deino los, um die Laughing Sisters zu jagen?",a="Deino belohnt Eure fortwährenden Dienste für die Magier der Horde, indem sie die Anfertigung spezieller Roben in die Wege leitet. Anstatt sie Euch einfach zu schenken, verlangt sie, dass Ihr die exotischen magischen Reagenzien selbst sammelt, und schickt Euch tief in das Eschental, um den Verteidigern des Waldes Dryadenhaar abzuringen.",al={"warum will deino haare der laughing sisters","deino motiv laughing sisters","warum laughing sisters haare sammeln"}}},fp="16,400,18.441.0,18.412.0,24.410.0,51.141.0,30.199.0,40.135.0,34.164.0,49.117.0,43.160.0"}
P.entries["quest:1946"] = {n="Netherspitzengewand",s="Das Netherspitzengewand markiert den Abschluss der spezialisierten Handwerksarbeit des Schneiders Kil'hala im Brachland. Indem er das gesammelte Haar von Dryaden zu veredeltem Stoff verwebt, fertigt der Schneider ein verzaubertes Gewand an, das für Zauberwirker geeignet ist.",h="Das Netherspitzengewand markiert den Abschluss der spezialisierten Handwerksarbeit des Schneiders Kil'hala im...",kw={"eschental","brachland","das wegekreuz","deino","kil'hala","lachende schwestern","magier","netherspitze"},ang={["class:Mage"]="Das Netherspitzengewand dient als wichtiger Meilenstein für aufstrebende Magier und verbindet Prüfungen in der Wildnis von Eschental mit Kil'halas Handwerkskunst unter Deinos Anleitung.",["faction:Horde"]="Die Beschaffung von Komponenten aus Kalimdors heiligen Wäldern zur Ausrüstung von Zauberwirkern der Horde veranschaulicht den anhaltenden Konflikt zwischen der Horde und den waldbewohnenden Verteidigern von Eschental.",["profession:Tailoring"]="Kil'halas Handwerk zeigt, wie exotische Reagenzien wie Dryadenhaar zu Stoffen versponnen werden können, die von Natur aus magischen Schutz bieten."},sec={{t="Das Weben der Netherspitze",b="Kil'hala, der vom Wegekreuz im Brachland aus arbeitet, übernimmt den heiklen Prozess der Herstellung von Netherspitze. Da er seltene und magisch resonante Komponenten benötigt – insbesondere die Locken der als Lachende Schwestern bekannten Dryaden aus Eschental –, bindet der Schneider die natürliche Verzauberung des Waldes direkt in bequemen, strapazierfähigen Stoff ein."},{t="Gefallen für Orgrimmar",b="Über das bloße Ausüben seines Handwerks hinaus hat Kil'hala persönliche Beweggründe, die Qualität des Gewands sicherzustellen. Er ist besonders darauf bedacht, sich die Gunst von Deino zu sichern, einer angesehenen Trollmagierin, die im Tal der Geister in Orgrimmar weilt. Indem er außergewöhnliche Kleidung für aufstrebende Praktizierende fertigt, hofft Kil'hala, Deinos Wohlwollen zu erlangen und zu erhalten."}},faq={{q="Was ist Netherspitze?",a="Netherspitze ist ein verzauberter Stoff, der von Kil'hala geschneidert wird. Er wird aus magischen Materialien gewebt, insbesondere den Haaren von Lachenden Schwestern, was ihn sowohl widerstandsfähig als auch von Natur aus mit arkaner Resonanz erfüllt macht.",al={"netherspitzenstoff","was ist netherspitzengewand"}},{q="Wer fertigt das Netherspitzengewand an?",a="Kil'hala, ein geschickter Schneidermeister der Horde, der beim Wegekreuz im Brachland stationiert ist, fertigt das Gewand an, sobald er mit dem erforderlichen Dryadenhaar aus Eschental versorgt wird.",al={"wer stellt netherspitze her","kil hala netherspitze"}},{q="Warum erwähnt Kil'hala Deino?",a="Deino ist eine einflussreiche Magierlehrerin der Trolle, die im Tal der Geister in Orgrimmar weilt. Kil'hala ist bestrebt, sich mit ihr gutzustellen, und hofft, dass Eure Zufriedenheit mit seiner Schneiderkunst ein gutes Licht auf ihn wirft.",al={"wer ist deino","warum wird deino erwähnt"}},{q="Woher stammten die Materialien für das Gewand?",a="Das Kernmaterial ist Haar, das von den Lachenden Schwestern gesammelt wurde, einer Gruppe schwer fassbarer Dryaden, die in den Wäldern von Eschental zu finden sind.",al={"materialien für netherspitze","dryadenhaarstoff"}},{q="Für wen wird dieses Gewand hergestellt?",a="Es wird in erster Linie für Zauberwirker angefertigt, insbesondere für Magier in der Ausbildung, die Roben benötigen, die arkane Energien kanalisieren können, ohne die Bewegung einzuschränken.",al={"wer nutzt netherspitzengewand","netherspitze klasse"}},{q="Wo befindet sich Kil'hala?",a="Kil'hala befindet sich beim Wegekreuz, der zentralen Wegkreuzungssiedlung im Herzen des Brachlands.",al={"kil hala aufenthaltsort","wo ist kil hala"}}},fp="19,223,23.343.0,20.351.0,20.207.0,35.155.0,32.208.0,50.126.0,29.151.0,26.107.0"}
P.entries["quest:1950"] = {n="Der Knüller schlechthin",s="Magus Tirth hat ein entscheidendes Zauberbuch in seiner magisch versiegelten Geldkassette eingeschlossen, erinnert sich jedoch nicht mehr an den Aktivierungssatz, um sie zu öffnen. Um den Band zu bergen, müsst Ihr seinen verschwundenen Lehrling irgendwo an der Rennstrecke auf der schimmernden Ebene aufspüren und ihm die vergessenen Worte entlocken.",h="Magus Tirth hat ein entscheidendes Zauberbuch in seiner magisch versiegelten Geldkassette eingeschlossen...",kw={"der knüller schlechthin","johnson","magus tirth","illusionenrennbahn","die schimmernde ebene","geldkassette","tausend nadeln","zauberstab quest"},ang={["class:Mage"]="Der Umgang mit Tirth bietet einen humorvollen, aber auch mahnenden Einblick in die Gefahren von Verwandlungsflüchen und die Zerstreutheit, die mächtige Gelehrte befallen kann."},sec={{t="Ein Magus und sein Gedächtnis",b="Magus Tirth ist ein exzentrischer Zauberwirker, der auf der rissigen Salzwüste der schimmernden Ebene in Tausend Nadeln haust. Zwar verfügt er über das esoterische Wissen und die Wälzer, die aufstrebende Magier händeringend suchen, doch der Umgang mit ihm erfordert Geduld. Tirth verlässt sich stark auf einen Assistenten, der alltägliche Belange regelt – einschließlich der gesprochenen Passwörter, die seine arkanen Aufbewahrungsorte schützen. Wenn sie den Auftrag erhalten, ein Buch der Macht zu beschaffen, stellen anreisende Praktizierende schnell fest, dass Tirth das Werk hinter magischen Worten weggeschlossen hat, die ihm vollkommen entfallen sind."},{t="Geflügelter Schabernack",b="Tirths Lehrling Johnson aufzuspüren bedeutet nicht, einfach durch das Fahrerlager der Illusionenrennbahn zu spazieren. Nachdem man sich bei den Goblins und Gnomen umgehört hat, die die Strecke betreiben, erfährt man, dass Johnson das typische Berufsrisiko im Dienste eines sprunghaften Zauberers ereilt hat: Verwandlung. Von seinem Meister in die Gestalt eines gewöhnlichen Huhns verflucht, irrt Johnson über die Salzebene – unfähig zu sprechen, bis ein vorbeikommender Reisender herantritt und den magischen Dunst lange genug lüftet, damit er das fehlende Passwort gackern kann."}},faq={{q="Wer ist Magus Tirth?",a="Magus Tirth ist ein zurückgezogen lebender menschlicher Zauberer, der nahe der Illusionenrennbahn auf der schimmernden Ebene in Tausend Nadeln stationiert ist. Er besitzt fortgeschrittenes arkanes Wissen, das von Magiern gesucht wird, die ihr Können verfeinern möchten.",al={"tirth lore","wer ist magus tirth","tirth schimmernde ebene"}},{q="Warum benötigt Tirth das Passwort für seine eigene Kassette?",a="Tirth verschloss seine Geldkassette magisch mit einem gesprochenen Satz und verließ sich darauf, dass sein Assistent profane Details wie Passwörter behält. Getreu seiner zerstreuten Art vergaß er die Worte, sobald sein Lehrling verschwunden war.",al={"warum tirth vergaß","passwort für tirths geldkassette"}},{q="Wohin ist der Lehrling gegangen?",a="Johnson ist nicht weit geflohen. Er wandert nahe der Rennbahn östlich von Tirths Lager umher, wenngleich sein Auffinden dadurch erschwert wird, dass Tirth ihn in ein Huhn verwandelt hat.",al={"tirths assistenten finden","wo ist lehrling johnson","johnsons aufenthaltsort"}},{q="Warum wurde der Lehrling in ein Huhn verwandelt?",a="Tirth belegte Johnson mit einem Fluch, bevor er vergaß, dies getan zu haben. Als er vom Schicksal seines Assistenten erfährt, nimmt Tirth vage an, dass der Lehrling es als undankbarer Schüler wohl verdient habe.",al={"warum ist johnson ein huhn","tirth verwandelt lehrling"}},{q="Was befindet sich in Tirths Geldkassette?",a="Die magisch versiegelte Truhe enthält ein Buch mit Ritualen und Anleitungen, die für die Weiterbildung eines Magiers und magische Werkzeuge unerlässlich sind.",al={"inhalt von tirths geldkassette","welches buch ist in der kiste"}},{q="Wer kann diese Aufgabe übernehmen?",a="Dieser Botengang ist Teil einer speziellen Prüfung, die ausschließlich für Magier bestimmt ist, die nach spezialisierter Unterweisung und Materialien zur Herstellung eines mächtigen Zauberstabs streben.",al={"können nicht-magier der knüller schlechthin annehmen","ist diese quest nur für magier"}}},fx={["25c94f6f"]={q="Warum schickt Euch Magus Tirth, anstatt den Lehrling selbst zu finden?",a="Magus Tirth hat nicht die Absicht, selbst die Die schimmernde Ebene zu durchkämmen, wenn Ihr diejenige Person seid, die um sein Wissen bettelt. Ihr kamt auf der Suche nach seinem seltenen magischen Folianten, und da er ohne seinen vermissten Assistenten die verbale Inkantation zum Öffnen seiner eigenen magisch versiegelten Geldkassette nicht mehr weiß, macht er die Hilfe für ihn zum Preis für seine Unterstützung.",al={"warum schickt sie mich","warum findet tirth johnson nicht","warum muss ich den lehrling finden"}}},fp="13,283,22.549.0,9.526.1,19.201.0,48.218.0,28.167.1,45.186.1,33.143.0,28.138.0"}
P.entries["quest:1959"] = {n="Meldung bei Anastasia",s="Meldung bei Anastasia ist eine Aufforderung an aufstrebende Magier der Horde in ganz Kalimdor und den Östlichen Königreichen. Anastasia Hirschbrunn, eine bedeutende Arkanistin im Magieviertel von Unterstadt, hat eine unbekannte magische Störung innerhalb der Stadt wahrgenommen und benötigt fähige Zauberwirker für die Untersuchung.",h="Meldung bei Anastasia ist eine Aufforderung an aufstrebende Magier der Horde in ganz Kalimdor und den...",kw={"anastasia hirschbrunn","cain feuerlied","untersuchungen im alchemistenladen","magier","magieviertel","meldung bei anastasia","thurston xane","un'thuwa","unterstadt","uthel'nay"},ang={["class:Mage"]="Diese Aufgabe markiert einen wichtigen Meilenstein für Magier der Horde, da sie die Anwender aus regionalen Ausbildungsposten herausführt und sie mit den tieferen arkanen Geheimnissen – und Gefahren – vertraut macht, die sich unter den Ruinen von Lordaeron zusammenbrauen.",["faction:Horde"]="Der Ruf zeugt vom gemeinsamen Austausch zwischen den Verlassenen und der übrigen Horde, bei dem magische Talente aller Mitgliedsvölker genutzt werden, um ihre gemeinsamen Interessen zu schützen.",["race:Undead"]="Magier der Verlassenen werden ins Magieviertel von Unterstadt zurückbeordert, um ihr junges Königreich gegen ungesehene arkane Bedrohungen innerhalb der eigenen Mauern zu sichern."},sec={{t="Ein Ruf an das Arkane",b="Unter den Zauberwirkern der Horde spricht sich die Kunde schnell herum. Ob beim Studium auf den Klippen von Donnerfels, in der staubigen Hitze von Durotar oder inmitten der Ruinen von Lordaeron: Magier von ausreichendem Talent erhalten eine eindeutige Weisung. Die Arkananwender von Unterstadt haben eine unerklärliche Störung gespürt, die durch ihr Herrschaftsgebiet wogt, und benötigen Unterstützung vor Ort."},{t="Die Magierin von Unterstadt",b="Anastasia Hirschbrunn überwacht arkane Angelegenheiten aus dem Magieviertel von Unterstadt. Nach Eurer Ankunft bestätigt sie die beunruhigenden Neuigkeiten: In der unterirdischen Metropole wurden anomale Energien registriert. Da die Natur dieser Magie noch völlig unbekannt ist – weder nachweislich harmlos noch offenkundig feindselig –, benötigt sie einen Adepten, der ihrer Quelle im Stillen nachgeht, beginnend im Apothekarium der Stadt."}},faq={{q="Wer ist Anastasia Hirschbrunn?",a="Anastasia Hirschbrunn ist eine Magierin der Verlassenen und eine arkane Lehrmeisterin, die im Magieviertel von Unterstadt stationiert ist. Sie leitet unerfahrene Anwender an und hält ein wachsames Auge auf arkane Abweichungen in der Hauptstadt der Verlassenen.",al={"anastasia hirschbrunn lore","wer ist anastasia","hartwell unterstadt"}},{q="Wo befindet sich Anastasia Hirschbrunn?",a="Sie hält sich im Magieviertel von Unterstadt auf, das im nördlichen Bogen der unterirdischen Stadt liegt. Man findet sie dort inmitten der anderen Ausbilder für Zauberwirker und arkanen Forscher.",al={"wo ist anastasia","hartwell aufenthaltsort","anastasia unterstadt karte"}},{q="Warum werden Magier aus Donnerfels oder dem Brachland nach Unterstadt gerufen?",a="Wenngleich die Verlassenen ihre eigenen Arkan-Spezialisten heranbilden, bedrohen ungewöhnliche magische Anomalien die gesamte Hordenpräsenz in Lordaeron. Lehrmeister in Kalimdor schicken ihre vielversprechenden Schüler nach Unterstadt, um Hilfe zu leisten und praktische Erfahrungen mit komplexen magischen Phänomenen zu sammeln.",al={"warum nach unterstadt reisen","warum meldung bei anastasia","donnerfels magierquest"}},{q="Welche Art von Störung untersucht Anastasia?",a="Die Magier nahmen unerklärliche magische Fluktuationen innerhalb der Stadt wahr. Zum Zeitpunkt dieses Rufs hat Anastasia Hirschbrunn noch nicht feststellen können, ob die Energie feindselig, versehentlich entstanden oder harmlos ist, weshalb sie eine vorsichtige Nachforschung einleitet.",al={"welche störung","magische störung unterstadt","was stimmt nicht in unterstadt"}},{q="Wer vergibt diese Quest?",a="Verschiedene Magierlehrer der Horde können diesen Ruf erteilen, sobald ein Zauberwirker genug Erfahrung gesammelt hat, darunter Uthel'nay in Orgrimmar, Thurston Xane in Donnerfels, Cain Feuerlied in Brill und Un'Thuwa in Sen'jin.",al={"wer startet meldung bei anastasia","questgeber meldung bei anastasia"}},{q="Was geschieht nach der Meldung bei Anastasia?",a="Sobald Ihr mit Anastasia sprecht und Eure Einweisung erhaltet, weist sie Euch sogleich an, der Störung genauer auf den Grund zu gehen, beginnend mit Nachforschungen im Apothekarium der Stadt bei der Quest Untersuchungen im Alchemistenladen.",al={"folgequest nach meldung bei anastasia","meldung bei anastasia fortsetzung"}}},fx={["22ef3f4a"]={q="Warum schicken Euch die Magierlehrer zu Anastasia Hirschbrunn, anstatt sich selbst darum zu kümmern?",a="Eure Lehrer werden benötigt, um angehende Zauberwirker zu unterrichten und die mystische Aufsicht über die Siedlungen in Kalimdor aufrechtzuerhalten. Als die Nachricht eintraf, dass die Magier der Verlassenen Unterstützung bei der Untersuchung einer arkanen Anomalie in der Unterstadt benötigten, suchten die Lehrer nach fähigen, aufstrebenden Praktizierenden, die für Außeneinsätze bereit waren, anstatt ihre Lehrposten aufzugeben.",al={"warum schickt man mich zu anastasia","warum können die lehrer nicht in die unterstadt","warum soll ich mich bei anastasia melden"}}},fp="19,292,20.385.0,25.418.0,26.229.0,36.183.0,80.273.0,52.238.0,21.220.0,42.221.0"}
P.entries["quest:1960"] = {n="Untersuchungen im Alchemistenladen",s="Untersuchungen im Alchemistenladen ist eine Quest in Unterstadt für Magier der Horde, die damit beauftragt sind, eine arkane Anomalie im Apothekarium zu beseitigen. Unter der Anleitung von Anastasia Hirschbrunn spüren die Zauberwirker unsichtbare Wesen aus reiner magischer Energie auf und fangen sie ein, die in Algernons Laden frei herumlaufen.",h="Untersuchungen im Alchemistenladen ist eine Quest in Unterstadt für Magier der Horde, die damit beauftragt...",kw={"algernon","anastasia hirschbrunn","das apothekarium","inkantation der manifestation","eindämmungskassette","magieviertel","rissbrut","unterstadt"},ang={["class:Mage"]="Diese Aufgabe prüft die Beherrschung reiner arkaner Kräfte durch einen Lehrling und erfordert den Einsatz spezialisierter Manifestations-Inkantationen sowie Eindämmungsgefäße anstelle reiner Zerstörungskraft.",["race:Undead"]="Während sich die Apotheker der Verlassenen vor allem auf Alchimie und Seuchenkunde konzentrieren, unterstreicht dieser Auftrag die Wachsamkeit der arkanen Gelehrten von Unterstadt beim Schutz ihrer Stadt vor magischer Infiltration."},sec={{t="Eine Störung im Apothekarium",b="Unterstadt ist an unnatürliche Phänomene gewöhnt, doch im Apothekarium trat kürzlich ein Problem rein arkaner Natur auf. Unsichtbare magische Wesenheiten wurden dabei beobachtet, wie sie durch Algernons Alchimieladen streiften und geräuschlos zwischen brodelnden Kesseln und giftigen Reagenzien umherzogen. Da sie einen unnatürlichen Riss im Fluss der Magie erkannte, weist die Magierlehrerin von Unterstadt, Anastasia Hirschbrunn, vielversprechende arkane Initianden an, die Wesenheiten zu untersuchen und einzudämmen, bevor katastrophaler Schaden entsteht."},{t="Manifestation und Eindämmung",b="Da die Wesenheiten unsichtbar sind und gänzlich aus roher arkaner Kraft bestehen, sind gewöhnliche Aufspürmethoden nutzlos. Anastasia stattet ihre Schüler mit einer speziellen Inkantation der Manifestation aus, um den Wesenheiten ihre Unsichtbarkeit zu nehmen, sowie mit robusten Eindämmungskassetten. Sobald sie enthüllt sind, müssen die unbeständigen Rissbruten niedergekämpft und sicher in den Kassetten versiegelt werden, bevor sie sich weiter auflösen oder den arbeitenden Alchimisten schaden können."},{t="Unfall oder arkaner Angriff?",b="Nachdem die Exemplare gesichert sind, gilt Anastasias Sorge deren Herkunft. Ein spontaner Riss im umgebenden Magiefluss ist beunruhigend genug, doch ein absichtlicher Bruch würde einen aktiven, koordinierten magischen Angriff auf die Hauptstadt der Verlassenen bedeuten. Die gefangenen Kreaturen werden zu Forschungszwecken übergeben, um festzustellen, ob das Apothekarium lediglich einen arkanen Unfall erlitten hat oder an vorderster Front einer gezielten Bedrohung steht."}},faq={{q="Wer vergibt diese Quest und wo ist diese Person zu finden?",a="Die Quest wird von Anastasia Hirschbrunn angeboten, der Magierlehrerin im Magieviertel von Unterstadt.",al={"questgeber","startpunkt","anastasia aufenthaltsort"}},{q="Wo befindet sich die Störung?",a="Die Störung konzentriert sich um Algernons Alchimieladen, der unten im Viertel des Apothekariums in Unterstadt liegt.",al={"wohin gehen","standort alchimistenladen","wo ist algernon"}},{q="Was sind das für Kreaturen, die im Laden umherstreifen?",a="Es handelt sich um Rissbruten – unsichtbare Wesen, die gänzlich aus konzentrierter magischer Energie bestehen und durch eine Anomalie im örtlichen Magiefluss aufgetaucht sind.",al={"was sind die monster","unsichtbare kreaturen","rissbruten"}},{q="Wie fängt man die Kreaturen ein?",a="Ihr müsst die Inkantation der Manifestation im Laden rezitieren, um die Rissbruten zu enthüllen, sie mit Zaubern schwächen und anschließend eine Eindämmungskassette einsetzen, um sie darin einzusperren.",al={"wie fangen","kassette benutzen","wie abschließen"}},{q="Warum möchte Anastasia diese Kreaturen lebend fangen?",a="Anastasia und die Gelehrten von Unterstadt benötigen lebende Exemplare, um festzustellen, ob der Riss in der Magie ein natürliches, zufälliges Phänomen war oder ein vorsätzlicher Angriff einer externen magischen Macht auf die Stadt.",al={"warum einfangen","zweck der eindämmungskassette","warum erforschen"}},{q="Können andere Klassen außer Magiern diese Quest annehmen?",a="Nein, diese Quest ist ausdrücklich Teil der frühen Ausbildungsreihe und ausschließlich Magiern der Horde vorbehalten.",al={"nur für magier","wer kann diese quest annehmen"}}},fx={["20993eae"]={q="Wozu dient die Inkantation der Manifestation?",a="Die Inkantation der Manifestation ist ein Zauberspruch, der auf eine Schriftrolle geschrieben und von Anastasia Hirschbrunn bereitgestellt wurde, um das Unsichtbare zu offenbaren. Die Wesen, die in Algernons Laden spuken, bestehen aus reiner magischer Energie und sind für das bloße Auge von Natur aus unsichtbar. Das Lesen der Inkantation innerhalb des Ladens reißt ihren Schleier der Verborgenheit weg und zwingt sie zur physischen Manifestation, sodass Ihr sie bekämpfen und unterwerfen könnt.",al={"zweck der inkantation der manifestation","warum inkantation der manifestation benutzen","was bewirkt die inkantation"}},["355e23e2"]={q="Wozu dient die Truhe mit Verwahrungskästen?",a="Die Truhe mit Verwahrungskästen enthält speziell geschützte Gefäße, die dazu gefertigt wurden, rohe magische Wesen zu binden. Da die Rissbruten im Das Apothekarium nicht einfach mit der Hand getragen werden können, müsst Ihr diese arkanen Kästen einsetzen, sobald die Kreaturen im Kampf geschwächt sind, um sie sicher darin einzuschließen, damit sie transportiert werden können, ohne sich aufzulösen.",al={"truhe mit verwahrungskästen","was sind verwahrungskästen","zweck von verwahrungskästen"}},["01d568c5"]={q="Wozu dient der Gefüllte Verwahrungskasten?",a="Jeder Gefüllte Verwahrungskasten enthält eine lebende Rissbrut, die aus Algernons Laden gefangen wurde. Anastasia Hirschbrunn benötigt drei dieser gefangenen Wesen, die unversehrt zurückgebracht werden müssen, damit die größten arkanen Gelehrten der Unterstadt sie untersuchen können, um herauszufinden, ob ihre plötzliche Manifestation ein versehentlicher Riss im Gefüge der Magie oder ein gezielter Angriff war.",al={"verwendung gefüllter verwahrungskasten","warum gefüllte kästen bringen","zweck gefüllter verwahrungskasten"}}},fp="30,277,33.479.0,29.435.0,27.417.1,46.109.0,33.123.0,42.144.0,33.168.0,55.195.0,43.101.0"}
P.entries["quest:1961"] = {n="Materialsammlung",s="Materialsammlung ist ein Initiationsritus für angehende Magier der Horde, die in Unterstadt ausgebildet werden. Die von Anastasia Hirschbrunn vergebene Aufgabe schickt Lehrlinge in den Silberwald, um arkanische Edelsteine von den Zauberern Dalarans zu erbeuten und die Komponenten zu beschaffen, die für das Weben ihrer ersten echten Magierroben benötigt werden.",h="Materialsammlung ist ein Initiationsritus für angehende Magier der Horde, die in Unterstadt ausgebildet...",kw={"mühlenbern","anastasia hirschbrunn","dalaran manastein","materialsammlung","josef gregorian","leinenstoff","magieviertel","roben des zauberfeuers","unterstadt"},ang={["class:Mage"]="Diese Quest stellt einen entscheidenden Meilenstein für Hordemagier dar und markiert ihren Aufstieg von einfacher Lehrlingskleidung zu maßgeschneiderten Roben, die mit eingefangener arkaner Macht gewoben sind.",["profession:Tailoring"]="Der Prozess verdeutlicht, wie gewöhnlicher Leinenstoff mit mächtigen Manasteinen verbunden werden kann, um dauerhaft verzauberte Gewänder zu erschaffen.",["race:Undead"]="Die Mission veranschaulicht die erbarmungslose Weltanschauung der Verlassenen: Eine frühere Verbundenheit mit den Zauberern Dalarans bringt keine Gnade, sollten sich jene lebenden Zauberer als zu schwach erweisen, um den Silberwald zu halten."},sec={{t="Ein Ritus arkaner Anerkennung",b="In den arkanen Klöstern des Magieviertels müssen angehende Magier beweisen, dass sie mehr als nur bloße Beschwörungsformeln beherrschen. Um sich ihre ersten echten Roben zu verdienen – ein formelles Gewand, das ihren Rang und persönlichen Wert verdeutlicht –, werden die Initianden von Anastasia Hirschbrunn angewiesen, die für das verzauberte Gewebe nötigen Grundkomponenten zu beschaffen: einen Ballen einfachen Leinenstoffs und eine Reihe mächtiger Dalaranmanasteine."},{t="Der Pragmatismus der Verlassenen",b="Die Manasteine können nicht einfach gekauft oder herbeigezaubert werden; man muss sie den Magiern von Dalaran entreißen, die im gesamten Silberwald, insbesondere nahe Mühlenbern, stationiert sind. Anastasia Hirschbrunn bemerkt mit kühler Distanz, dass die arkanen Philosophien Dalarans zwar ihren eigenen ähneln, sentimentale Zögerlichkeit in Unterstadt jedoch keinen Platz hat. In den Augen der Verlassenen haben jene lebenden Zauberer sowohl ihre Schätze als auch ihr Leben verwirkt, wenn es ihnen an der Stärke fehlt, ihre Relikte zu verteidigen."},{t="Der Schneider des Magieviertels",b="Sobald der Stoff und die Edelsteine gesammelt sind, werden sie zu Josef Gregorian gebracht, einem Schneider, der im Magieviertel ansässig ist. Während Gregorian offen zugibt, dass ihm das magische Talent fehlt, um die makellose Qualität der verzauberten Steine Dalarans zu beurteilen, besitzt er das seltene handwerkliche Geschick, das erforderlich ist, um deren rohe Macht direkt in den Stoff der Roben einzuweben."}},faq={{q="Was ist der Zweck von Materialsammlung?",a="Die Quest dient als Einweihung für Magier der Horde. Ihr Abschluss versorgt den Schneider Josef Gregorian mit den nötigen Komponenten – Leinen und Manasteine –, um die ersten formellen, verzauberten Roben des Initianden herzustellen.",al={"warum materialsammlung machen","materialsammlung quest zweck","magierrobe quest unterstadt"}},{q="Warum schickt Anastasia Hirschbrunn Euch gegen Dalaranmagier aus?",a="Die im Silberwald stationierten Zauberer von Dalaran tragen veredelte Manasteine bei sich, die in der Lage sind, starke magische Ströme zu leiten. Hartwell betrachtet diese lebenden Magier pragmatisch: Trotz gemeinsamer intellektueller Wurzeln bedeutet Schwäche auf dem Schlachtfeld, dass ihr Leben und ihre Ressourcen an die Verlassenen verfallen sind.",al={"warum dalaranmagier töten","dalaran manasteine lore","warum silberwald magier"}},{q="Wo befinden sich die Zauberer von Dalaran?",a="Sie sind im Silberwald anzutreffen, wo sie Außenposten und Ländereien südöstlich vom Grabmal besetzen, konzentriert um die Siedlung Mühlenbern.",al={"wo dalaran manasteine finden","silberwald magier standort","mühlenbern magier"}},{q="Wer ist Josef Gregorian?",a="Josef Gregorian ist ein untoter Schneider, der im Magieviertel von Unterstadt arbeitet. Obwohl er eher ein Handwerker als ein arkaner Zauberwirker ist, ist er darauf spezialisiert, verzauberte Gewänder wie Roben des Zauberfeuers zu nähen.",al={"josef gregorian unterstadt","wer ist der schneider im magieviertel","gregorian schneider"}},{q="Welche Roben werden aus diesen Materialien gefertigt?",a="Josef Gregorian nutzt das Leinen und die Dalaranmanasteine, um Roben des Zauberfeuers zu nähen, ein klassisches Gewand, das den Übergang eines Lehrlings zu einem vollwertigen Magier markiert.",al={"welche robe bekommt man","roben des zauberfeuers belohnung","materialsammlung belohnungsrobe"}},{q="Warum findet Anastasia das Töten von Dalaranmagiern etwas unangenehm?",a="Viele Zauberwirker der Verlassenen, einschließlich Hartwell selbst, wurden zu Lebzeiten in den Traditionen Dalarans ausgebildet und teilen ähnliche intellektuelle und magische Philosophien. Trotz dieser Verbundenheit wiegen Überleben und Notwendigkeit schwerer als Sentimentalität.",al={"hartwell gefühle dalaran","magier der verlassenen gegen dalaran","anastasia hirschbrunn lore"}}},fx={e61c0dee={q="Wozu dient der Leinenstoff?",a="Der Leinenstoff dient als profane Grundlage für Eure Spellfire Robes. Josef Gregorian, der Schneider im Magieviertel der Unterstadt, verwebt den Stoff zu feinen Kleidungsstücken, bevor er magische Reagenzien in die Fäden einwebt, um sie zu stärken.",al={"verwendung von leinenstoff","warum leinenstoff","wofür ist leinen"}},["8f9ef647"]={q="Wozu dient der Manaedelstein aus Dalaran?",a="Manaedelsteine aus Dalaran enthalten rohe arkane Energie, die von den Magiern der Kirin Tor kanalisiert wurde. Josef Gregorian näht sie direkt in Eure Roben ein, um den Stoff mit der magischen Kraft zu durchdringen, die erforderlich ist, um wahre Spellfire-Kleidung zu schmieden.",al={"verwendung manaedelstein aus dalaran","warum manaedelsteine aus dalaran","wofür sind die manaedelsteine"}},["608132d5"]={q="Wer sind die Magier aus Dalaran im Silberwald?",a="Es handelt sich um menschliche Zauberer, die Dalaran treu ergeben sind und um Mühlenbern im östlichen Silberwald stationiert sind. Obwohl ihre arkanes Disziplin die der Magier der Verlassenen widerspiegelt, bedroht ihre Anwesenheit direkt die Herrschaft der Unterstadt über die Region, was sie zu erstklassigen Zielen für ambitionierte Lehrlinge macht.",al={"dalaran-magier im silberwald","wer sind die magier aus dalaran","dalaran-menschen im silberwald"}},["1cfe23fe"]={q="Warum schickt Anastasia Hirschbrunn einen Lehrling, anstatt sich selbst darum zu kümmern?",a="Der Erhalt Eurer ersten Magierroben ist ein Initiationsritus. Anastasia Hirschbrunn erwartet, dass Ihr Euren Wert und Euren arkanen Status beweist, indem Ihr Rivalen die Reagenzien durch Willenskraft und persönliche Stärke abnehmt.",al={"warum ich materialien sammeln","warum lehrling schicken","warum holt anastasia die edelsteine nicht selbst"}}},fp="19,297,25.384.0,26.464.0,31.334.0,43.208.0,57.284.0,38.149.0,23.214.0,44.158.0,67.222.0"}
P.entries["quest:1962"] = {n="Roben des Zauberfeuers",s="Roben des Zauberfeuers ist der krönende Ritus in der Ausbildung junger Magier der Horde in Unterstadt, vollendet durch den Schneider Josef Gregorian. Nach dem Sammeln seltener Komponenten aus dem gesamten Reich wird der Lehrling mit maßgefertigten, verzauberten Gewändern belohnt, die seine wachsende Beherrschung des Arkanen symbolisieren.",h="Roben des Zauberfeuers ist der krönende Ritus in der Ausbildung junger Magier der Horde in Unterstadt...",kw={"arkane roben","materialsammlung","josef gregorian","magierquest","magieviertel","roben des zauberfeuers","unterstadt"},ang={["class:Mage"]="Der Erhalt dieser Roben ist eine frühe Reifeprüfung für Zauberwirker der Horde und verleiht ihnen maßgeschneiderte Kleidung, die flüchtige Feuer- und Arkankräfte bändigen kann.",["profession:Tailoring"]="Die Quest veranschaulicht, wie gewöhnlicher Stoff durch exotische Reagenzien verstärkt wird, um mächtigen magischen Strömen standzuhalten und sie zu verstärken.",["race:Undead"]="Zauberwirker der Verlassenen in Unterstadt bewahren die arkane Disziplin im Stile Dalarans und verbinden alte magische Traditionen mit ihrer neuen Existenz in den Ruinen von Lordaeron."},sec={{t="Das Gewand eines Magiers",b="Für Lehrlinge, die in Lordaeron die arkanen Künste erlernen, taugen gewöhnliche Umhänge und herkömmliche Kleidung kaum dazu, rohe unheimliche Kräfte zu kanalisieren oder gegen sie abzuschirmen. Josef Gregorian, ein Schneider im Magieviertel von Unterstadt, webt echte magische Gewänder aus den speziellen Materialien, die vielversprechende Zauberwirker der Horde zusammentragen. Das vollendete Nähen der Roben des Zauberfeuers markiert den Übergang eines Lehrlings von einfachen Beschwörungsformeln zu einem vollwertigen Anwender der arkanen und feurigen Künste."},{t="Geflochtene Macht",b="Gewänder zu fertigen, die hochintensive Magie sicher bündeln können, ist eine anspruchsvolle Aufgabe. Weit über bloßes Schneidern hinaus erfordert die Herstellung solcher Roben spezifische alchemistische und arkane Komponenten, die durch gefährliche Prüfungen beschafft werden müssen. Sobald diese Vorräte beschafft und in Gregorians Refugium dargeboten werden, webt der Schneider sie an Ort und Stelle zusammen und verleiht dem angehenden Magier ein spürbares Zeichen von Status und Schutz."}},faq={{q="Was ist der Zweck der Quest 'Roben des Zauberfeuers'?",a="Sie dient als letzter Schritt in einem frühen Klassenritus für Magier der Horde und belohnt sie mit eigens verzauberten Roben, nachdem sie Schneidereikomponenten für den Schneider Josef Gregorian beschafft haben.",al={"roben des zauberfeuers zweck","was bewirken roben des zauberfeuers","warum diese quest machen"}},{q="Wer ist Josef Gregorian?",a="Josef Gregorian ist ein Schneider der Verlassenen, der in der Schneiderei im Magieviertel von Unterstadt arbeitet. Er näht die ersten vollwertigen Klassengewänder für frisch gebackene Magier, die von Anastasia Hirschbrunn zu ihm geschickt werden.",al={"wer ist josef","wer fertigt die robe","josef gregorian unterstadt"}},{q="Wo findet diese Quest statt?",a="Die gesamte Interaktion findet im Magieviertel von Unterstadt statt, direkt in der Schneiderei von Josef Gregorian.",al={"roben des zauberfeuers standort","wo roben des zauberfeuers abgeben"}},{q="Warum müsst Ihr für diese Quest nicht aufbrechen, um eine weitere Aufgabe zu erledigen?",a="Die gesamte Vorarbeit wurde in der vorangegangenen Aufgabe 'Materialsammlung' geleistet. Sobald Ihr Josef diese Reagenzien überreicht, nimmt er sich einfach einen Moment Zeit, um das Kleidungsstück zu weben, und übergibt Euch sogleich die fertigen Roben.",al={"warum ist es sofort fertig","wie man roben des zauberfeuers abschließt","robe sofort abschließen"}},{q="Können andere Klassen als Magier diese Roben erhalten?",a="Nein. Die gesamte Questreihe und die daraus resultierenden verzauberten Gewänder sind exklusiv Magiern vorbehalten, die mit der Horde verbündet sind.",al={"nur für magier","kann hexenmeister das bekommen","wer kann roben des zauberfeuers machen"}},{q="Welche Materialien waren nötig, um diese Roben herzustellen?",a="Die Robe wird aus den seltenen Vorräten hergestellt, die während der vorangegangenen Aufgabe gesammelt wurden, darunter Leinenstoff und Dalaranmanasteine, die von den Magiern der Kirin Tor im Silberwald erbeutet wurden.",al={"was gehört in die robe","materialien für die robe","materialsammlung abgabe"}}},fx={c778cc7d={q="Warum schnei-dert Euch Josef Gregorian die Spellfire Robes?",a="Josef Gregorian dient als Mentor für aufstrebende Magier der Verlassenen und der Horde im Magieviertel. Indem er die gesammelten Reagenzien in geeignete verzauberte Gewänder einwebt, stellt er sicher, dass Ihr angemessen ausgerüstet seid, um die arkanen Kräfte zu kanalisieren und zu ertragen, die Euer wachsendes Handwerk erfordert.",al={"warum macht josef die roben","motiv von josef gregorian","warum hilft josef dir"}}},fp="15,301,17.487.0,11.426.0,49.191.0,23.199.0,33.120.0,62.209.0,48.110.0,49.183.0"}
P.entries["quest:1963"] = {n="Die Zerschmetterte Hand",s="Diese Schurkenprüfung, erteilt von Therzok in der Kluft der Schatten, testet Initianden, die Aufnahme in die geheimnisvolle Gilde der Shattered-Hand suchen. Um ihre tödliche Effizienz zu beweisen, erhalten angehende Schurken die Aufgabe, den Trollschmuggler Tazan zur Strecke zu bringen und seine verschlossene Tasche an sich zu bringen.",h="Diese Schurkenprüfung, erteilt von Therzok in der Kluft der Schatten, testet Initianden, die Aufnahme in die...",kw={"die kluft der schatten","orgrimmar","ratschet","schurke","tasche","die shattered-hand","tazan","therzok"},ang={["class:Rogue"]="Dieser Übergangsritus führt junge Schurken der Horde in die Reihen der Shattered-Hand ein und legt den Schwerpunkt auf rücksichtslose Effizienz, Attentate und Nützlichkeit statt auf den offenen Kampf.",["faction:Horde"]="Die Zerschmetterte Hand verkörpert die internen ideologischen Spannungen in Orgrimmar, wo geheime Gruppierungen Thralls vorsichtige Vision für die junge Horde im Stillen anfechten."},sec={{t="Schatten in der Kluft",b="Unter den geschäftigen Straßen von Orgrimmar liegt die unterirdische Düsternis der Kluft der Schatten. Hier operiert die Shattered-Hand, ein klandestiner Orden von Attentätern und Dieben, der in alten orkischen Traditionen verwurzelt ist. Während Kriegshäuptling Thrall Ehre, Diplomatie und Umsicht bei der Führung der jungen Horde predigt, glaubt die Führung der Shattered-Hand, dass ein solches Zögern ihr Volk schwächt. Sie trachten danach, die kriegerische Vorherrschaft durch verdeckte Gewalt zurückzugewinnen, indem sie Dolche und Gift dort einsetzen, wo Vorstöße auf dem Schlachtfeld scheitern könnten."},{t="Das Schicksal eines Schmugglers",b="Um die Ungeschickten und Schwachen auszusortieren, stellt der Ausbilder Therzok einen unmissverständlichen Auftrag: Tazan zu eliminieren, einen abtrünnigen Troll, der sein Unwesen im Brachland nahe Ratschet treibt. Tazan hat Handel mit Küstenpiraten getrieben und besitzt brisante Informationen, die die Gilde begehrt. Die Beschaffung seiner verschlossenen Tasche beweist die Fähigkeit des Schurken, Beute jenseits der Stadtmauern zu erjagen, obgleich die Bergung des Inhalts noch weiteres Fingerspitzengefühl erfordert."}},faq={{q="Was ist die Shattered-Hand in Orgrimmar?",a="Die Zerschmetterte Hand ist die verdeckte Horde-Gilde aus Schurken, Spähern und Attentätern, die aus der Kluft der Schatten in Orgrimmar heraus operiert. Während sie historisch ein alter orkischer Clan war, der für brutale Selbstverstümmelung bekannt war, dient sie in der modernen Horde als schattenhaftes Netzwerk für Aufklärung und Auftragsmorde, das rücksichtslosen Pragmatismus Thralls vorsichtiger Diplomatie vorzieht.",al={"wer ist die shattered-hand","schurken der shattered-hand","ziel der shattered-hand"}},{q="Wer ist Therzok?",a="Therzok ist ein Verbindungsmann der Shattered-Hand, der in der Kluft der Schatten stationiert ist. Er prüft angehende Schurken, um sicherzustellen, dass sie die nötige Schläue und Tödlichkeit besitzen, die für den Dienst in der Gilde erforderlich sind, und äußert offene Skepsis gegenüber Thralls Zurückhaltung.",al={"therzok rolle","wer ist questgeber","therzok orgrimmar"}},{q="Warum will Therzok Tazans Tod?",a="Tazan ist ein Trollschmuggler, der unerlaubten Handel mit den Piraten der Südmeerfreibeuter nahe dem Hafen von Ratschet treibt. Neben welcher Schmuggelware auch immer er verschiebt, trägt Tazan entscheidende Informationen in einer Tasche bei sich, die die Shattered-Hand für ihre eigenen verdeckten Operationen haben will.",al={"warum tazan toeten","tazan lore","was tat tazan"}},{q="Wo befindet sich Tazan?",a="Tazan treibt sich im Brachland herum und lauert nahe der Küste und den Piratenoperationen südlich von Ratschet.",al={"tazan aufenthaltsort","wo ist tazan","tazan finden"}},{q="Was geschieht nach der Bergung von Tazans Tasche?",a="Bei der Rückkehr zu Therzok stellt sich heraus, dass die Tasche verschlossen ist. Erfreut über Tazans Ableben, aber angewiesen auf die Informationen im Inneren, nutzt Therzok die Situation als Folgeprüfung für das Schlossknacken des Schurken.",al={"folgequest","verschlossene tasche","was tun mit tasche"}},{q="Weiß Thrall von den Methoden der Shattered-Hand?",a="Obwohl die Shattered-Hand nominell der Horde dient, agieren ihre Mitglieder weitgehend aus dem Verborgenen und hegen Verachtung für Thralls vorsichtige Führung. Sie verfolgen im Stillen ihre eigenen Informationsnetzwerke, um vermeintliche Bedrohungen zu beseitigen, bevor die Diplomatie des Kriegshäuptlings entschlossenes Handeln verzögern kann.",al={"thrall und shattered-hand","billigt kriegshaeuptling das","thrall schurken"}}},fx={["6c6760e5"]={q="Was befindet sich in Tazans Ranzen?",a="Therzok sucht nach dem Ranzen, weil er wertvolle Informationen enthält. Tazan handelt direkt mit den Southsea Freebooters, die in der Nähe von Ratschet operieren, und jegliche Korrespondenz oder Aufzeichnungen, die er bei sich trägt, könnten der The Shattered Hand einen Vorteil gegenüber den Bewegungen der Piraten entlang der Küste verschaffen. Leider ist der Beutel sicher verschlossen, was ihn nutzlos macht, bis Ihr einen Weg findet, ihn zu öffnen.",al={"tazans ranzen","was ist tazans ranzen","zweck von tazans ranzen"}},fc6df596={q="Wer ist Tazan?",a="Tazan ist ein Troll-Schurke, der illegale Geschäfte mit den Piraten südlich von Ratschet betreibt. Da er im Brachland außerhalb der Reichweite der Gesetze von Orgrimmar operiert, handelt er mit Geheimnissen und Schmuggelware, was die Aufmerksamkeit der The Shattered Hand auf sich zog. Seine Geschäfte mit Gesetzlosen machen ihn zu einem erstklassigen Ziel für die Eliminierung.",al={"wer ist tazan","tazan als ziel","warum tazan töten"}},beb36990={q="Warum schickt Therzok Euch, anstatt sich selbst um Tazan zu kümmern?",a="The Shattered Hand operiert streng geheim aus den Tiefen der Die Kluft und verbirgt ihre rücksichtslosen Methoden vor den wachsamen Augen von Kriegshäuptling Thrall. Therzok kann keine offiziellen Wachen der Horde aussenden oder hochrangige Gildenmitglieder bei belanglosen Außeneinsätzen entlarven. Stattdessen nutzt er den Auftrag als Initiationsprüfung, um zu testen, ob Ihr über die tödliche Gerissenheit verfügt, die erforderlich ist, um ihrer Untergrundbruderschaft zu dienen.",al={"warum schickt man mich","warum will therzok dich","warum tötet er tazan nicht selbst"}}},fp="18,266,20.505.0,17.421.1,40.345.0,15.226.0,33.250.0,23.97.0,46.211.1,52.286.0"}
P.entries["quest:1978"] = {n="Die Todespirscher",s="Dieser Auftrag markiert die formelle Aufnahme eines fähigen Agenten in die Reihen der Todespirscher, dem Orden der Meuchelmörder und Spione der Verlassenen. Mit der Aufgabe betraut, Androns Geschäftsbuch direkt an den Schreckenslord Varimathras zu überbringen, liefert der Bote der obersten Führungsebene von Unterstadt den Beweis für die verdeckten Aktivitäten des Syndikats.",h="Dieser Auftrag markiert die formelle Aufnahme eines fähigen Agenten in die Reihen der Todespirscher, dem...",kw={"alterac","androns geschäftsbuch","todespirscher","hall of the dark lady","mennet carkad","syndikat","unterstadt","varimathras"},ang={["class:Rogue"]="Diese Aufnahme stellt den offiziellen Eintritt in den spezialisierten Schurkenkader der Verlassenen dar und erhebt einfache Beutelschneider zu staatlichen Geheimdienstagenten.",["faction:Horde"]="Obwohl es sich um eine interne Sicherheitsangelegenheit der Verlassenen handelt, schützt die Überwachung der menschlichen Überreste Alteracs die nördlichen Territorien der Horde vor zersetzender Sabotage.",["race:Undead"]="Für die Verlassenen ist die Aufnahme in die Todespirscher ein direktes Gelöbnis, die fragile Souveränität von Lordaeron vor menschlichen Überlebenden und lauernden Verrätern zu schützen."},sec={{t="Aufnahme in die Schatten",b="Nachdem belastende Aufzeichnungen von Andron Gant ans Licht gebracht wurden, heißt Mennet Carkad den Agenten offiziell bei den Todespirschern willkommen. Die Organisation dient Fürstin Sylvanas in ganz Lordaeron als Augen, Ohren und Dolche und verlässt sich auf Spionagenetzwerke, rücksichtslose Effizienz und Heimlichkeit, um Bedrohungen zu beseitigen, bevor sie an die Oberfläche treten. Die formelle Anerkennung innerhalb des Ordens zu erlangen, ist ein wichtiger Meilenstein für jeden aufstrebenden Schurken oder Kundschafter in Unterstadt."},{t="Die Verbindung zum Syndikat",b="Die Ausbeute dieser verdeckten Untersuchung ist Androns Geschäftsbuch, das illegale Verbindungen zwischen lokalen Agenten und dem Syndikat offenlegt. Einst die adelige Aristokratie des gefallenen Menschenkönigreichs Alterac, wandte sich das Syndikat Banditentum und Subversion zu, nachdem ihr Reich im Zweiten Krieg zusammengebrochen war. Carkad äußert Überraschung und Verachtung darüber, wie tief die gefallenen Lords von Alterac gesunken sind, indem sie sich zu kleinen Verschwörungen herablassen, um wieder an Macht zu gelangen."},{t="Audienz beim Schreckenslord",b="Aufgrund der heiklen Natur der Informationen wird das Geschäftsbuch direkt zu Varimathras im Königsviertel von Unterstadt gebracht. Der Kommandant der Nathrezim beaufsichtigt unter Sylvanas Windläufer die taktische Aufklärung der Verlassenen. Erfreut über die Initiative der Todespirscher begrüßt Varimathras die bewiesene Leistungsfähigkeit des Agenten und bemerkt, dass seine Geheimdienstabteilung jemanden, der Resultate liefert, immer gebrauchen kann."}},faq={{q="Was sind die Todespirscher?",a="Die Todespirscher sind der führende Spionage-, Kundschafter- und Attentatsorden der Verlassenen. Mit ihrem Hauptquartier im Schurkenviertel von Unterstadt agieren sie in ganz Lordaeron, um politische Rivalen auszuschalten, feindliche Fraktionen zu infiltrieren und das Reich der Verlassenen vor äußerer und innerer Subversion zu schützen.",al={"wer sind die todespirscher","todespirscher lore","attentäter der verlassenen"}},{q="Warum ist das Syndikat verwickelt?",a="Das sichergestellte Geschäftsbuch enthüllt geheime Verbindungen zum Syndikat, der vertriebenen Aristokratie von Alterac, die sich dem organisierten Banditentum zugewandt hat. Die Verlassenen beobachten die in ihrem Gebiet agierenden Überreste Alteracs genau, da die Agenten des Syndikats fortwährend nach Gelegenheiten suchen, verlorenes Land zurückzufordern und Ressourcen im nördlichen Lordaeron zu plündern.",al={"warum syndikat","alterac verbindung","syndikat geschäftsbuch"}},{q="Warum direkt an Varimathras Bericht erstatten?",a="Varimathras fungiert als taktischer Berater von Königin Sylvanas und beaufsichtigt die Sicherheits- und Geheimdienstoperationen von Unterstadt. Bedeutende Entdeckungen bezüglich ausländischer Verschwörungen – wie etwa die verdeckten Operationen des Syndikats – erfordern eine Begutachtung auf höchster Führungsebene, um umfassendere militärische und diplomatische Gegenmaßnahmen zu koordinieren.",al={"warum varimathras","wer ist varimathras","rolle des schreckenslords"}},{q="Wer war Mennet Carkad?",a="Mennet Carkad ist ein leitender Kontaktmann und Verbindungsoffizier der Todespirscher in Unterstadt. Er betreut Außendienstagenten, beurteilt neue Rekruten und sichtet gesammelte Informationen, bevor er entscheidende Erkenntnisse in der Befehlskette nach oben weiterleitet.",al={"rolle von mennet carkad","questgeber carkad"}},{q="Wo findet diese Audienz statt?",a="Die Audienz findet in der Hall of the Dark Lady statt, die sich im Königsviertel tief in Unterstadt befindet. Varimathras steht an der Seite von Königin Sylvanas Windläufer im Herzen des Machtzentrums der Verlassenen.",al={"wo ist varimathras","hall of the dark lady standort"}},{q="Was geschieht nach dem Beitritt zu den Todespirschern?",a="Nachdem Eure Qualifikationen feststehen und Ihr Eure Zuverlässigkeit sowohl gegenüber Mennet Carkad als auch Varimathras bewiesen habt, werdet Ihr als vertrauenswürdiger Außendienstagent der Verlassenen anerkannt. Dies bereitet den Weg für künftige Aufklärungs- und Eliminierungsaufträge in den umkämpften Ländern von Lordaeron.",al={"fortsetzung der todespirscher questreihe","wie geht es weiter"}}},fx={["123798f3"]={q="Warum möchte Mennet Carkad, dass Androns Geschäftsbuch an Varimathras ausgeliefert wird?",a="Das Geschäftsbuch enthüllt, dass das Syndikat – die gefallenen Adligen von Alterac – sich gegen die Verlassenen verschworen hat. Die Aufdeckung ihres Verrats ist ein Sieg im Bereich Vital Intelligence für The Deathstalkers, und Mennet weiß, dass solch dringende Nachrichten, die die Sicherheit von Lordaeron betreffen, direkt in die Hände von Lord Varimathras gelegt werden müssen, der die Operationen des Ordens beaufsichtigt.",al={"warum geschäftsbuch ausliefern","mennet carkad motiv","warum syndikat an varimathras melden"}},b0e675df={q="Warum schickt Mennet Euch, anstatt selbst Bericht bei Varimathras zu erstatten?",a="Ihr wart derjenige, der die Verschwörer aufgespürt und Androns Geschäftsbuch vor Ort sichergestellt hat. Mennet glaubt, es sei nur angemessen, dass Ihr die Informationen persönlich überbringt, was es Euch ermöglicht, den Ruhm vor Lord Varimathras zu ernten und Eure formelle Aufnahme in die Reihen von The Deathstalkers zu markieren.",al={"warum ich deathstalkers","warum schickt mich mennet","warum geschäftsbuch selbst ausliefern"}}},fp="17,326,26.441.0,24.431.1,27.427.0,27.311.0,30.341.0,35.327.0,22.243.0,36.206.0,45.277.0"}
P.entries["quest:199"] = {n="Eine dunkle Bedrohung",s="Diese Quest markiert den Moment, in dem eine Untersuchung von Sabotage am Steinwerkdamm handfeste Beweise für ein Verbrechen zutage fördert. Nach der Entdeckung eines verdächtigen Fasses, das nahe dem gewaltigen Zwergenbauwerk versteckt liegt, beschaffen Abenteurer eine Probe eines seltsam riechenden Pulvers, um sie zu Chefingenieur Hinderweir VII. zu bringen.",h="Diese Quest markiert den Moment, in dem eine Untersuchung von Sabotage am Steinwerkdamm handfeste Beweise für...",kw={"eine dunkle bedrohung","hinderweir","loch modan","sabotage","der steinwerkdamm","seltsam riechendes pulver","verdächtiges fass"},ang={["profession:Engineering"]="Ein Ingenieur spürt sofort Gefahr, wenn er flüchtige Pulver begutachtet, die gezielt an den statischen Schwachstellen eines großen Damms deponiert wurden.",["race:Dwarf"]="Der Steinwerkdamm ist eine der glanzvollsten architektonischen Meisterleistungen der Zwerge von Eisenschmiede. Jede Bedrohung seiner Unversehrtheit trifft die Sicherheit und den Stolz von Khaz Modan ins Mark.",["race:Gnome"]="Gnomische Köpfe schätzen die Präzision hinter den zwergischen Bauwerken, weshalb die chemische Natur dieser primitiven Sabotage besonders beunruhigend wirkt."},sec={{t="Eine verdächtige Entdeckung",b="Der Steinwerkdamm steht als monumentaler Triumph zwergischer Ingenieurskunst da und staut die gewaltigen Wassermassen des Lochs auf. Doch Gerüchte über Sabotage haben den Blick auf das umliegende Ufer gelenkt. Abgelegen am Wasserrand verbirgt ein deplatziertes Fass eine unheilvolle Substanz – ein seltsames, stechend riechendes Pulver, das ganz eindeutig nicht zu den üblichen Vorräten für die Instandhaltung des Damms gehört."},{t="Alarm am Damm",b="Eine Probe des unbekannten Pulvers zu nehmen und sie Chefingenieur Hinderweir VII. vorzulegen, bestätigt die schlimmsten Befürchtungen der Behörden von Loch Modan. Der Ingenieur erkennt sofort, dass eine fremde Macht ein Komplott gegen den Damm schmiedet, was die Untersuchung von einem bloßen Verdacht zu einer dringenden Angelegenheit der regionalen Verteidigung macht."}},faq={{q="Was ist das seltsam riechende Pulver?",a="Das im Fass gefundene, seltsam riechende Pulver ist ein explosiver oder alchemistischer Stoff, der nahe dem Fundament des Steinwerkdamms deponiert wurde. Es dient als direkter Beweis dafür, dass ein Feind plant, das gewaltige Bauwerk zu zerstören oder zu schwächen.",al={"seltsames pulver","was ist im fass","verdächtiges fass pulver"}},{q="Wer ist Chefingenieur Hinderweir VII.?",a="Chefingenieur Hinderweir VII. ist der zwergische Meisteringenieur, der die Instandhaltung, Stabilität und Sicherheit des Steinwerkdamms in Loch Modan überwacht.",al={"wer ist hinderweir","chefingenieur hinderweir","dammingenieur"}},{q="Wo ist das verdächtige Fass zu finden?",a="Das verdächtige Fass liegt versteckt am Ufer nahe dem Fundament des Steinwerkdamms im nördlichen Loch Modan.",al={"fass fundort","wo ist das fass","fass loch modan"}},{q="Warum gerät der Steinwerkdamm ins Visier?",a="Der Steinwerkdamm staut das riesige Reservoir von Loch Modan auf. Sollte er brechen, würde eine verheerende Flut durch das darunterliegende Sumpfland fegen, Handelswege der Allianz lahmlegen und zwergische Besitztümer in ganz Khaz Modan verwüsten.",al={"warum damm zerstören","dammsabotage","bedrohung für loch modan"}},{q="Wer hat das verdächtige Fass dort zurückgelassen?",a="Das Fass wurde von Agenten platziert, die darauf aus sind, die Zwergenländer zu destabilisieren, was Chefingenieur Hinderweir veranlasst, eine umfassendere Untersuchung darüber einzuleiten, wer hinter dem Komplott steckt.",al={"wer hat das fass platziert","saboteure","wer hat das pulver platziert"}},{q="Was sollte ich nach dem Einsammeln des Pulvers tun?",a="Bringt die Probe direkt zu Chefingenieur Hinderweir VII. oben auf dem Steinwerkdamm, damit er die Substanz untersuchen und Gegenmaßnahmen einleiten kann.",al={"was als nächstes","pulver abgeben","mit wem sprechen"}}},fp="19,308,22.377.0,16.319.1,36.233.0,37.149.0,37.124.0,43.226.0,36.168.0,45.139.0"}
P.entries["quest:1998"] = {n="Fenwick Thatros",s="Mennet Carkad beauftragt vielversprechende Schurken in Unterstadt direkt auf Befehl von Lord Varimathras damit, Fenwick Thatros zur Strecke zu bringen. Thatros steht im Verdacht, an den Ufern von Silberwald unabhängige untote Streitkräfte zu organisieren. Ihn zu eliminieren beweist den Todespirschern den Mut eines Agenten und ebnet den Weg für eine anspruchsvollere Ausbildung im Handwerk.",h="Mennet Carkad beauftragt vielversprechende Schurken in Unterstadt direkt auf Befehl von Lord Varimathras...",kw={"die todespirscher","fenwick thatros","der lordameresee","mennet carkad","schurkenviertel","silberwald","unterstadt","varimathras"},ang={["class:Rogue"]="Dieser Auftrag dient als Bewährungsprobe für Schurken der Verlassenen, um ihre Heimlichkeit und Tödlichkeit zu bestätigen, bevor ihnen die fortgeschritteneren Werkzeuge des Todespirscher-Handwerks anvertraut werden.",["race:Undead"]="Die Verlassenen können rivalisierende untote Fraktionen nicht dulden, die so nahe an der Ruine der Hauptstadt Souveränität beanspruchen, was Thatros' Kopf zu einer politischen Notwendigkeit macht."},sec={{t="Ein Befehl des Schreckenslords",b="In den finsteren Korridoren des Schurkenviertel kümmert sich Mennet Carkad um interne Aufträge und das Training für die Todespirscher – den verschwiegenen Geheimdienstflügel der Verlassenen. Wenn Lord Varimathras ein vorrangiges Ziel vorgibt, ist dies kein Auftrag, der leichtfertig an unerfahrene Rekruten vergeben wird. Fenwick Thatros hat die Aufmerksamkeit des Schreckenslords erregt, indem er unter den abtrünnigen Untoten im Silberwald Fuß gefasst hat. Sich selbst überlassen, könnte eine unabhängige Führung der Untoten die Festigung der Macht der Verlassenen über die alten Besitztümer Lordaerons gefährden."},{t="Der verfallene Steg am Lordamere",b="Laut Aufklärungsberichten der Todespirscher versteckt sich Thatros nicht in tiefen Festungen oder Krypten. Stattdessen verorteten Späher ihn nahe einem verfallenen Steg an den Gewässern des Lordameresees im Silberwald. Ihn dort niederzustrecken erfordert das Durchqueren umkämpfter Wildnis, die von wilden Tieren, den Gnollen der Rot Hide und Überresten der Geißel beherrscht wird. Seinen abgetrennten Kopf zurückzubringen liefert den handfesten Beweis, den Varimathras verlangt, bevor ein Agent in tiefere verdeckte Operationen eingeweiht wird."}},faq={{q="Wer ist Fenwick Thatros?",a="Fenwick Thatros ist ein untoter Anführer, der an den Ufern des Lordameresees im Silberwald agiert. Anders als die Verlassenen, die Fürstin Sylvanas dienen, befehligt Thatros Gruppen von Untoten, die ungebunden oder feindselig gegenüber Unterstadt eingestellt sind, was Lord Varimathras dazu veranlasste, ihn zur Exekution auszuwählen.",al={"fenwick lore","wer ist thatros","fenwick thatros hintergrund"}},{q="Warum will Varimathras den Tod von Fenwick Thatros?",a="Varimathras sieht in Thatros eine wachsende Bedrohung, die streunende Untote im Silberwald gegen die Verlassenen sammeln könnte. Um die Grenzen rund um Unterstadt zu sichern, müssen alle rivalisierenden Anführer, die Sylvanas' absolute Kontrolle über die Region gefährden, rasch beseitigt werden.",al={"varimathras thatros","warum fenwick toeten"}},{q="Wer sind Die Todespirscher?",a="Die Todespirscher sind die führende Organisation der Verlassenen für Spionage, Attentate und Aufklärung. Mit ihrer Basis im Schurkenviertel in Unterstadt operieren sie in ganz Lordaeron, um interne Bedrohungen auszuschalten, rivalisierende Fraktionen auszuspionieren und Territorien für die Dunkle Fürstin zu sichern.",al={"todespirscher lore","was sind todespirscher","fraktion der untotenschurken"}},{q="Wo befindet sich Fenwick Thatros?",a="Berichte der Todespirscher verorten Thatros nahe einem verfallenen, baufälligen Steg am Ufer des Lordameresees im nordöstlichen Silberwald.",al={"wo ist fenwick","fenwick steg standort","thatros der lordameresee"}},{q="Was bringt der Abschluss dieser Mission bei den Todespirschern ein?",a="Die Exekution von Thatros beweist Mennet Carkad und den Todespirschern die Fähigkeiten und Loyalität eines Agenten. Nachdem Eure Zuverlässigkeit unter Beweis gestellt wurde, bietet Carkad an, Eure Ausbildung in den Schattenkünsten durch spezialisierte handwerkliche Unterweisungen voranzutreiben.",al={"fenwick belohnung lore","was kommt nach fenwick"}},{q="Wer ist Mennet Carkad?",a="Mennet Carkad ist ein Schurkenlehrer und Verbindungsmann der Todespirscher im Schurkenviertel von Unterstadt. Er beaufsichtigt Außendienstagenten und vergibt Missionen, die direkt mit der Sicherheit des Reiches der Verlassenen verknüpft sind.",al={"mennet carkad","wer gibt die fenwick-quest"}}},fx={eac48585={q="Warum benötigt Mennet Carkad Fenwicks Kopf?",a="Fenwick Thatros stellt eine organisierte Bedrohung dar, die direkt an den Grenzen des Silberwalds lauert. Mennet Carkad verlangt seinen abgetrennten Kopf als unumstößlichen Beweis dafür, dass der untote Schurkenkommandant eliminiert wurde. Bei den verdeckten Operationen der The Deathstalkers und Lord Varimathras reicht das Wort eines Assassinen niemals ohne eine physische Trophäe aus, um den Erfolg zu bestätigen.",al={"wofür ist fenwicks kopf","warum fenwicks kopf nehmen","zweck von fenwicks kopf"}},bc8ca6fa={q="Warum wählt Mennet Carkad Euch für diese Mission aus?",a="Mennet Carkad fungiert als Ausbilder und Kontaktperson für die Deathstalkers im Schurkenviertel. Wenn Lord Varimathras eine chirurgische Tötung anordnet, sind gewöhnliche Stadtwachen für die heimliche Aufklärung außerhalb der Stadt ungeeignet. Mennet wählt Euch gezielt aus, weil Ihr Talent in den Schattenkünsten gezeigt habt, und nutzt diesen kritischen Auftrag, um zu beurteilen, ob Ihr bereit für eine fortgeschrittene Ausbildung unter den Eliteagenten der Verlassenen seid.",al={"warum werde ich geschickt","warum wählt mich mennet aus","warum keine wachen der deathstalkers schicken"}}},fp="15,348,28.525.0,30.480.0,23.290.0,47.256.0,26.279.0,33.129.0,62.236.0,21.206.0"}
P.entries["quest:1999"] = {n="Werkzeuge des Handwerks",s="Tools of the Trade ist eine Einführungsmission für Schurken der Horde, die von Mennet Carkad in der Unterstadt vergeben wird. Auf Befehl von Lord Varimathras müssen Agenten Schlösserknackerwerkzeug beschaffen und Mühlenbern infiltrieren, um sensible Berichte der Kirin Tor zu bergen, die den aktuellen Zustand von Dalaran detailliert beschreiben.",h="Tools of the Trade ist eine Einführungsmission für Schurken der Horde, die von Mennet Carkad in der...",kw={"mühlenbern","dalaran","deathstalkers","estelle gendry","kirin tor","schlösserknacken","mennet carkad","schurkenviertel","unterstadt","varimathras"},ang={["class:Rogue"]="Diese Mission markiert einen Initiationsritus für Schurken der Horde, bei dem Ihr formelles Schlösserknackerwerkzeug beschaffen und statt roher Gewalt Heimlichkeit und Finesse anwenden müsst.",["faction:Horde"]="Die Sicherung menschlicher Informationen im Silberwald festigt den Stützpunkt der Horde im nördlichen Lordaeron gegen die Überreste der Allianz.",["race:Undead"]="Die Infiltration von Mühlenbern ermöglicht es den Verlassenen, genau jene Magier der Kirin Tor zu überlisten, die versuchen, Lordaeron aus dem Grab zurückzuerobern."},sec={{t="Augen auf Mühlenbern",b="Nach dem Verhör eines Gefangenen der Kirin Tor erfuhren die Deathstalkers, dass wichtige Informationen über die Ruinen von Dalaran in Mühlenbern verborgen liegen. Der Silberwald bleibt eine prekäre Frontlinie und die menschlichen Magier, die das Dorf bewachen, schützen ihre Kommunikation erbittert. Auf Befehl von Lord Varimathras weist der Deathstalker-Ausbilder Mennet Carkad vielversprechende Agenten an, die Wachen der Kirin Tor zu umgehen und den Statusbericht von Dalaran zu sichern."},{t="Die Kunst des Einbruchs",b="Anders als direkte Attentate dient diese Mission als praktischer Test für Infiltration und Schlösserknacken. Agenten werden mit spezialisiertem Diebeswerkzeug von Estelle Gendry ausgerüstet, bevor sie in das feindliche Gebiet der Kirin Tor marschieren. Das Knacken der gesicherten Truhe in Mühlenbern beweist, dass ein Agent seine rohe Gewalt auf der Straße hinter sich gelassen hat und zu einer unverzichtbaren Spionagekraft für die Verlassenen geworden ist."}},faq={{q="Wer erteilt diesen Auftrag?",a="Mennet Carkad, ein Meister-Schurke der Deathstalkers, der im Schurkenviertel der Unterstadt stationiert ist, weist diese Aufgabe zu. Der übergeordnete Auftrag kommt direkt von Lord Varimathras, der die Informationsbeschaffung für die Verlassenen beaufsichtigt.",al={"wer vergibt tools of the trade","questgeber","mennet carkad quest"}},{q="Was ist der Statusbericht von Dalaran?",a="Es ist eine versiegelte Depesche der Kirin Tor, die die Bedingungen innerhalb von Dalaran detailliert beschreibt. Die Verhörspezialisten der Deathstalkers entlockten einem gefangenen menschlichen Magier den Aufenthaltsort und alarmierten die Unterstadt, dass wichtige Informationen über ihre südlichen Nachbarn verwundbar waren.",al={"was sind die dokumente","kirin tor unterlagen","statusbericht"}},{q="Wo wird der Bericht aufbewahrt?",a="Der Bericht ist in einer verschlossenen Truhe innerhalb des Außenpostens der Kirin Tor in Mühlenbern gesichert, das sich im südlichen Silberwald befindet.",al={"wo finde ich die dokumente","fundort der truhe in mühlenbern","wo ist der statusbericht"}},{q="Wer stellt das Schlösserknackerwerkzeug bereit?",a="Estelle Gendry, eine Ausrüsterin im Schurkenviertel der Unterstadt, stellt das notwendige Diebeswerkzeug zur Verfügung, um die verschlossene Truhe der Kirin Tor zu öffnen.",al={"wo bekomme ich werkzeug","estelle gendry rolle","ausrüster werkzeug"}},{q="Warum ist Dalaran für die Verlassenen derzeit wichtig?",a="Die überlebenden Zauberer von Dalaran bauen ihre Stadt auf der anderen Seite des Lordameresee vom Silberwald aus wieder auf. Die Verlassenen beobachten die Kirin Tor, um ihre eigenen Besitzungen in Lordaeron zu schützen.",al={"warum dalaran wichtig","verlassene gegen dalaran","kirin tor bedrohung"}},{q="Welche Voraussetzung muss erfüllt sein, bevor Ihr diese Mission annehmen könnt?",a="Agenten müssen zuerst den Attentatsauftrag für Fenwick Thatros abschließen und ein Ziel im Silberwald zur Strecke bringen, bevor Mennet Carkad ihnen delikate Infiltrationsarbeit anvertraut.",al={"voraussetzung","welche quest kommt davor","fenwick thatros quest"}}},fx={["77cf7ea8"]={q="Warum will Mennet Carkad, dass dies erledigt wird?",a="Lord Varimathras beauftragte die Deathstalkers damit, den Bericht zu beschaffen, nachdem er dessen Verbleib aus einem Gefangenen herausgepresst hatte. Als Agent im Schurkenviertel führt Mennet Carkad die Anweisungen des Schreckenslords aus und stellt gleichzeitig Eure aufkeimenden Fähigkeiten in Infiltration und Spionage auf die Probe.",al={"warum will mennet carkad das","mennet carkad beweggrund","warum statusbericht von dalaran bergen"}},["9b719de0"]={q="Gegen wen werdet Ihr in Mühlenbern ausgesandt?",a="Euer Ziel ist die in Mühlenbern im Silberwald stationierte Kirin Tor. Diese menschlichen Magier unterhalten eine Enklave in der Nähe der wiederaufgebauten Stadt Dalaran und bewahren vertrauliche Informationen über den aktuellen Zustand der zerstörten Stadt vor den Verlassenen.",al={"wer besitzt den bericht","ziel von tools of the trade","wen greift ihr an"}},["6507a470"]={q="Warum benötigt Mennet Carkad Euch für diese Mission?",a="Die Mission dient als Initiationsritus. Nachdem Ihr durch die Ausschaltung von Fenwick Thatros grundlegende Eignung bewiesen habt, hat Mennet Euch ausgewählt, um zu beweisen, dass Ihr das heiklere Handwerk der Deathstalkers beherrscht – das sich auf Verstohlenheit, Schlossknacken und Infiltration statt auf rohe Gewalt stützt.",al={"warum werde ich ausgesandt","warum ich mennet carkad","warum können the deathstalkers den bericht nicht holen"}}},fp="18,265,17.457.0,21.418.0,24.235.0,34.246.0,25.125.0,35.145.0,51.178.0,63.183.0"}
P.entries["quest:2"] = {n="Klaue von Scharfkralle",s="Klaue von Scharfkralle ist eine Trophäenquest, die den Sieg über den wilden Hippogryphen Scharfkralle in Eschental besiegelt. Wenn Ihr die abgetrennte Kralle der Kreatur zu Senani Donnerherz am Splitterholzposten zurückbringt, beweist dies Euer Können und sichert die Nachschubwege der Horde durch den uralten Wald.",h="Klaue von Scharfkralle ist eine Trophäenquest, die den Sieg über den wilden Hippogryphen Scharfkralle in...",kw={"eschental","die jagd in eschental","hippogryph","peons","senani donnerherz","scharfkralle","splintertreeposten","kriegshymnenklan"},ang={["class:Hunter"]="Einen legendären geflügelten Räuber wie Scharfkralle zu bezwingen, gilt als ultimative Prüfung der Fährtenlesekunst und Treffsicherheit unter dem dichten Blätterdach von Eschental.",["faction:Horde"]="Der Sieg über Scharfkralle sichert lebenswichtige Pfade für die Holzgewinnung des Kriegshymnenklans und schützt verwundbare Peons, die zwischen den Vorposten und dem Splitterholzposten unterwegs sind.",["race:Orc"]="Die Beseitigung der geflügelten Schrecken des Waldes erleichtert dem Kriegshymnenklan seine zermürbende Holzbeschaffungskampagne.",["race:Tauren"]="Das Befolgen der Riten der Jagd durch Senani Donnerherz demonstriert die traditionelle Ehrfurcht der Tauren davor, sich im Wettstreit mit den wildesten Bestien der Natur zu beweisen."},sec={{t="Eine Geißel der Waldpfade",b="Während die Horde versucht, in Eschental Ressourcen zu gewinnen, erweist sich die einheimische Tierwelt als ebenso gefährlich wie die Schildwachen der Nachtelfen. Scharfkralle, ein berüchtigt aggressiver Hippogryph, lauerte in den Baumkronen und entlang der Wege, die sich zum Splitterholzposten schlängeln. Die Bestie machte Jagd auf wehrlose Peons und Kuriere, die zwischen den vorderen Holzfällerlagern und dem Außenposten unterwegs waren, und behinderte die Operationen der Horde in der Region empfindlich."},{t="Beweis der Jagd",b="Unter der Anleitung der Taurenjägerin Senani Donnerherz erhalten Fährtenleser der Horde den Auftrag, die tödlicheren Raubtiere auszuschalten, die unter dem Blätterdach von Eschental lauern. Das Abtrennen der gewaltigen Kralle von Scharfkralle dient als unbestreitbarer Beweis dafür, dass der Schrecken der Lüfte gefallen ist. Die Übergabe der Trophäe am Splitterholzposten bringt Ehre unter den Verteidigern des Außenpostens und verschafft den verängstigten Arbeitern Erleichterung, die diese Wälder durchqueren müssen."}},faq={{q="Was ist Scharfkralle?",a="Scharfkralle ist ein namentlich bekannter, räuberischer Hippogryph, der in Eschental heimisch ist. Bekannt für seine Wildheit überfiel er unerbittlich Reisende, die sich durch die uralten Wälder bewegten.",al={"wer ist scharfkralle","scharfkralle mob","welche art bestie ist scharfkralle"}},{q="Warum verlangt Senani Donnerherz nach der Kralle?",a="Senani Donnerherz koordiniert Die Jagd in Eschental vom Splitterholzposten aus. Die Kralle dient als handfester Beweis dafür, dass ein großes Raubtier beseitigt wurde, welches die Arbeiter und Nachschubwege der Horde bedrohte.",al={"warum kralle abgeben","senani donnerherz trophäe","zweck von klaue von scharfkralle"}},{q="Wo gebe ich die Klaue von Scharfkralle ab?",a="Ihr gebt die Kralle bei Senani Donnerherz ab, einer Tauren am Splitterholzposten im östlichen Eschental.",al={"wo abgeben","wer nimmt die kralle","kralle abgabeort"}},{q="Wie hilft das Töten von Scharfkralle der Horde?",a="Scharfkralle griff regelmäßig Peons an, die zwischen den abgelegenen Sägewerken und dem Splitterholzposten unterwegs waren. Die Vernichtung der Bestie gewährleistet einen sichereren Transport von Nachschub, Holz und Boten.",al={"warum scharfkralle töten lore","horde interesse an scharfkralle"}},{q="Ist diese Quest Teil einer längeren Reihe?",a="Ja. Sie ist Teil von „Die Jagd in Eschental“, einer Reihe von Prüfungen der Bestienjagd von Senani Donnerherz, die in „Die Jagd ist abgeschlossen“ gipfelt.",al={"die jagd in eschental reihe","questreihe scharfkralle"}},{q="Wer ist Senani Donnerherz?",a="Senani Donnerherz ist eine Taurenjägerin, die am Splitterholzposten stationiert ist. Sie wacht über das Gleichgewicht des Waldes und stellt den Mut der Jäger der Horde gegen die gefährlichsten Kreaturen von Eschental auf die Probe.",al={"senani lore","wer ist senani"}}},fp="17,275,30.407.0,17.424.0,19.162.0,43.195.0,37.104.0,43.178.0,37.146.0,27.194.0"}
P.entries["quest:20"] = {n="Bedrohung durch den Schwarzfelsklan",s="Marschall Marris von Seenhain beauftragt Abenteurer damit, die aggressiven Blackrockorcs zu dezimieren, die das Rotkammgebirge bedrängen. Durch das Erbeuten ihrer kampferprobten Äxte hoffen die Verteidiger des Ortes, die Belagerung zu durchbrechen, die sich immer enger um die Siedlung zieht.",h="Marschall Marris von Seenhain beauftragt Abenteurer damit, die aggressiven Blackrockorcs zu dezimieren, die...",kw={"aexte","blackrock","brennende steppe","seenhain","marris","orcs","rotkammgebirge","steinwacht","tharil'zun"},ang={["class:Warrior"]="Schild an Schild mit gestählten Blackrockmarodeuren zusammenzustoßen, bietet eine brutale Prüfung der soldatischen Disziplin und der Standhaftigkeit an vorderster Front.",["faction:Alliance"]="Die Verteidigung von Seenhain ist entscheidend, um die südliche Grenze des Königreichs Sturmwind gegen Widersacher der alten Welt zu halten.",["race:Human"]="Der Blackrockklan zerstörte das ursprüngliche Königreich Sturmwind im Ersten Krieg; ihnen im Rotkammgebirge erneut gegenüberzustehen, weckt bitteren historischen Schmerz."},sec={{t="Eine belagerte Stadt",b="Seenhain sieht sich an mehreren Fronten eingekesselt, doch keine stellt eine so ernste Bedrohung dar wie die Blackrockorcs, die aus der feurigen Brennenden Steppe herüberdrängen. Nachdem sie nach Süden in das Rotkammgebirge vorgestoßen sind, haben diese erfahrenen Plünderer Festungen besetzt und durchstreifen die schroffen Pässe. Ihre Anwesenheit hält die Stadtbewohner praktisch in der Siedlung gefangen und schneidet den Handel, das Sammeln von Vorräten und das Reisen auf den nördlichen Straßen ab."},{t="Schlag gegen die Vorhut",b="Marschall Marris, der Kommandant der bedrängten Wache von Seenhain, kann keine Abteilung entbehren, um ihre Stellungen direkt anzugreifen. Stattdessen heuert er umherziehende Abenteurer an, um die vorgeschobenen Späher und Fußsoldaten der Invasoren ausbluten zu lassen. Indem er ihre groben, kampferprobten Äxte als Beweis für ihren Tod verlangt, versucht Marris, die Reihen der Invasoren sowohl um Steinwacht im Norden als auch in den zerklüfteten Winkeln des südöstlichen Rotkammgebirges zu lichten."}},faq={{q="Woher stammen diese Blackrockorcs?",a="Sie marschierten nach Süden über die gezackten Gebirgspässe, die aus der Brennenden Steppe herausführen, ihrer angestammten Hochburg rund um den Schwarzfels.",al={"woher kommen die orcs","blackrock invasion rotkammgebirge","warum sind orcs im rotkammgebirge"}},{q="Wer erteilt diese Aufgabe?",a="Marschall Marris, der leitende Offizier, der mit der Verteidigung von Seenhain und der Aufrechterhaltung der Ordnung angesichts der wachsenden Einkesselung der Stadt betraut ist.",al={"wer vergibt bedrohung durch die blackrock","bedrohung durch die blackrock questgeber","marschall marris quest"}},{q="Wo sind die Blackrock-Invasoren zu finden?",a="Sie halten das nördliche Hochland rund um Burg Steinwacht besetzt und haben auch im südöstlichen Winkel des Rotkammgebirges Fuß gefasst.",al={"wo sind blackrockorcs","fundorte kampferprobte axt","rotkamm orclager"}},{q="Warum verlangt Marschall Marris kampferprobte Äxte?",a="Die kampferprobten Äxte dienen als unumstößlicher physischer Beweis dafür, dass ein Abenteurer die das Tal bedrohenden Blackrockmarodeure aktiv bekämpft und erschlagen hat.",al={"warum aexte","todesbeweis","zweck kampferprobte axt"}},{q="Was geschieht, nachdem diese Späher besiegt wurden?",a="Das Lichten der Vorhut veranlasst Marschall Marris dazu, einen Schlag gegen den örtlichen Anführer der Blackrock in den Bergen, Tharil'zun, anzuordnen.",al={"was folgt auf bedrohung durch die blackrock","folgequest nach bedrohung durch die blackrock","wer fuehrt die orcs an"}},{q="Gehören die Orcs zu Thralls Horde?",a="Nein. Der hier operierende Blackrockklan besteht aus Überresten der Alten Horde, die der Allianz weiterhin feindselig gegenüberstehen und unabhängig von Thralls neuer Horde in Kalimdor agieren.",al={"sind das horde orcs","gehoert der blackrockklan zu thralls horde","friedliche orcs im rotkammgebirge"}}},fx={ded9bd4b={q="Warum will Marschall Marris, dass die Blackrock-Orcs getötet werden?",a="Der Blackrock-Clan ist aus der Brennende Steppe herabgestiegen, hat Burg Steinwacht eingenommen und marodiert durch das Land nördlich von Seenhain. Ihre ständigen Überfälle haben die Bürger der Stadt effektiv innerhalb ihrer Grenzen gefangen gehalten, wie Vieh eingepfercht. Marschall Marris will diese erstickende Belagerung brechen, die nördlichen Grenzen der Region sichern und auskundschaftende Kriegstrupps eliminieren, bevor Seenhain vollständig überrannt wird.",al={"motiv von marris","warum blackrock-orcs töten","warum blackrock menace"}},["29f2a399"]={q="Wer sind die Blackrock-Invasoren, die Seenhain bedrohen?",a="Ihr werdet gegen die Blackrock-Orcs entsandt, Überreste der Alten Horde, die aus der Brennende Steppe herabgestiegen sind. Nachdem sie Burg Steinwacht im Norden beansprucht haben, marodieren sie aktiv durch die Wildnis und haben begonnen, Außenposten in den südöstlichen Ausläufern des Rotkammgebirge zu errichten, um Seenhain zu erdrosseln und ihren territorialen Griff über die Berge auszuweiten.",al={"wer sind die blackrock-orcs","wer ist das ziel","orcs in burg steinwacht"}},e27bf976={q="Warum benötigt Marschall Marris Abenteurer anstatt der Wache von Seenhain?",a="Die örtliche Garnison von Seenhain ist bis zum Äußersten angespannt. Da die Armee von Sturmwind abwesend ist und keine Verstärkung schickt, können es sich Marris und seine wenigen verbliebenen Wachen nicht leisten, in die Wildnis auszurücken, ohne die Stadt völlig wehrlos zurückzulassen. Um die vorrückenden Invasoren zurückzuschlagen, ist er auf fähige unabhängige Söldner und Abenteurer angewiesen.",al={"warum kämpft die wache nicht","warum ich marris","warum braucht man abenteurer"}}},fp="16,228,18.405.0,21.413.0,41.142.0,21.135.0,42.147.0,48.154.0,45.136.1,44.183.0"}
P.entries["quest:2038"] = {n="Bingles' verschwundene Werkzeuge",s="Nach einer Bruchlandung mit seinem Gyrokopter in den Gewässern des Lochs wurde der exzentrische Gnomen-Ingenieur Bingles Blastenheimer von einheimischen Troggs überfallen, die sich mit seiner unverzichtbaren Ausrüstung aus dem Staub machten. Gestrandet am südöstlichen Ufer des Sees benötigt er seinen gestohlenen Schraubenschlüssel, Schraubenzieher, Hammer und seine maßgefertigten Blastencapper-Sprengsätze zurück, um seine Flugmaschine zu reparieren und sich wieder dem Kampf um Gnomeregan anzuschließen.",h="Nach einer Bruchlandung mit seinem Gyrokopter in den Gewässern des Lochs wurde der exzentrische...",kw={"bingles","blastencapper","blastenheimer","gnomeregan","gyrokopter","hammer","loch modan","schraubenzieher","der loch","trogg","schraubenschlüssel"},ang={["faction:Alliance"]="Einem Piloten der Allianz im Herzen von Loch Modan zu helfen, sichert die Wasserwege und unterstützt die weiteren strategischen Kriegsanstrengungen zur Rückeroberung der verlorenen Gebiete von Khaz Modan.",["profession:Engineering"]="Spezialwerkzeuge und flüchtige Munition wie den Blastenheimer Blastencapper in den plumpen Händen von Troggs zu belassen, ist ein Affront gegen die Handwerkskunst und ein vorprogrammierter verheerender Unfall.",["race:Dwarf"]="Die Troggplage auf den Inseln des Lochs bedroht den lokalen Handel und das Reisen, weshalb jeder Schlag gegen ihre Lager ein willkommener Dienst für die Gebirgsjäger ist.",["race:Gnome"]="Jedes wiederbeschaffte Werkzeug bringt das Gnomenvolk der Einleitung einer Gegenoffensive aus der Luft gegen die Troggs und Lepragnome näher, die Gnomeregan ersticken."},sec={{t="Ein feuchter Absturz",b="Bingles Blastenheimer steuerte seinen Gyrokopter über Loch Modan, als ihn ein unerwarteter Absturz direkt in die kalten Gewässer des Lochs stürzen ließ. Den Aufprall zu überleben war schon Glück genug, doch sich an Land zu schleppen, erwies sich als nur die halbe Mühsal. Die Troggs, die die zentralen Inseln des Sees heimsuchen, nutzten seine missliche Lage sofort aus, fielen über den benommenen Piloten her und plünderten seine wertvollsten Habseligkeiten."},{t="Gnomischer Einfallsreichtum unter Beschuss",b="Die marodierenden Troggs verstreuten Bingles' unverzichtbare Ausrüstung über ihre Insellager. Zu den fehlenden Vorräten gehören seine Standard-Feldwerkzeuge – ein Schraubenschlüssel, ein Schraubenzieher und ein Hammer – sowie seine geschätzte Erfindung, der Blastenheimer Blastencapper. Zwar ist der Verlust gewöhnlicher Bergungsgüter ärgerlich genug, doch das Zurücklassen flüchtiger Sprengstoffe mit hoher Sprengkraft in einem ohnehin von Troggs wimmelnden Gebiet stellt eine unmittelbare Gefahr für jeden dar, der Loch Modan bereist."},{t="Für Gnomeregan",b="Bingles unternimmt keineswegs nur eine Vergnügungsfahrt durch den Himmel von Khaz Modan; er betrachtet sich selbst als fliegende Vorhut für die Befreiung seiner gefallenen Heimat. Da Gnomeregan derzeit von unterirdischen Troggs und verstrahlten Lepragnomen überrannt ist, stellt sich Bingles einen entscheidenden Luftangriff vor, um den Griff des Feindes zu brechen. Ohne seine Werkzeuge und Blastencapper zum Wiederaufbau seiner Flugmaschine bleibt sein groß angelegter Luftfeldzug jedoch vollkommen im Schilf stecken."}},faq={{q="Warum ist Bingles Blastenheimer in Loch Modan gestrandet?",a="Bingles stürzte mit seinem Gyrokopter direkt in den Loch. Während er versuchte, sich am südöstlichen Ufer von dem Wrack zu erholen, wurde er von nahegelegenen Insel-Troggs überfallen, die seine Werkzeuge und experimentelle Munition plünderten.",al={"warum bingles hier ist","wie bingles abstürzte","bingles absturz"}},{q="Welche Vorräte wurden von den Troggs gestohlen?",a="Die Troggs machten sich mit vier wichtigen Gegenständen davon: Bingles Schraubenschlüssel, einem Schraubenzieher, einem Hammer und einer speziellen Sprengladung namens Blastenheimer Blastencapper.",al={"was troggs stahlen","bingles vorräte","welche gegenstände bingles"}},{q="Wohin brachten die Troggs Bingles' Ausrüstung?",a="Die Troggs brachten die gestohlene Ausrüstung zurück zu ihren Lagern auf den Inseln im nördlichen Teil des Lochs und verstreuten die Werkzeugeimer und Sprengstoffe entlang der felsigen Ufer.",al={"wo sind bingles werkzeuge","trogginsel standort","wo ist blastencapper"}},{q="Was ist der Blastencapper?",a="Der Blastencapper ist ein urheberrechtlich geschützter Sprengsatz, der von Bingles Blastenheimer entwickelt wurde und für den Kampfeinsatz bei Luftangriffen gegen die Gnomeregan besetzenden Feinde gedacht ist.",al={"was ist blastencapper","blastenheimer blastencapper","bingles sprengsatz"}},{q="Auf welche Bewegung bezieht sich Bingles?",a="Bingles widmet sich der Rückeroberung von Gnomeregan. Sein Ziel ist es, eine Luftbombardement-Kampagne zu mobilisieren, um die unterirdischen Troggs und Lepragnome zu vertreiben, die die Gnomenhauptstadt als Geisel halten.",al={"welche bewegung","für gnomeregan","bingles beweggrund"}},{q="Warum kann Bingles die Vorräte nicht selbst zurückholen?",a="Bingles ist isoliert, durchnässt und nach dem Überleben eines katastrophalen Absturzes völlig unbewaffnet. Sich einem befestigten Lager aggressiver Troggs über offenes Wasser ohne Waffen oder Fluggerät zu stellen, wäre für einen einsamen Ingenieur reiner Selbstmord.",al={"warum bingles sie nicht holt","warum bingles wartet"}}},fx={["008fc445"]={q="Warum möchte Bingles Blastenheimer, dass seine Vorräte geborgen werden?",a="Bingles ist mit seiner Flugmaschine in Der Loch abgestürzt, während er sie testete, aber der Verlust seiner Ausrüstung gefährdet mehr als nur seine Bergung. Er hat spezialisierte Werkzeuge und firmeneigene Blastenheimer Blastencapper-Sprengstoffe speziell für die gnomische Luftoffensive zur Rückeroberung von Gnomeregan angefertigt. Ohne seine Werkzeuge zum Wiederaufbau und seine Munition zum Abwerfen kann der Versuch, die Troggs und die Lepragnome, die seine Heimat besetzen, zu bombardieren, nicht fortgesetzt werden.",al={"motiv von bingles","warum braucht bingles seine werkzeuge","warum bingles helfen"}},["0d3e655b"]={q="Wer hat Bingles' Vorräte genommen und warum sind sie hier?",a="Troggs, die die Inseln von Loch Modan befallen haben, haben Bingles kurz nach seinem Absturz überfallen und seine Ausrüstung geplündert. Diese primitiven unterirdischen Bestien wurden während der Ausgrabungen der Zwerge in ganz Khaz Modan freigelegt. Angetrieben von einem gewalttätigen territorialen Instinkt und einem Hang dazu, sich glänzende mechanische Kuriositäten zu schnappen, schleppten sie Bingles' Werkzeugkasten und die flüchtigen Sprengstoffe zurück in ihre Lager am See.",al={"wer hat bingles werkzeuge gestohlen","troggs in loch modan bingles","warum sind troggs auf den inseln"}}},fp="25,387,14.419.0,29.443.0,14.446.0,52.210.0,40.155.0,40.188.0,26.169.0,38.192.0,48.227.0"}
P.entries["quest:2039"] = {n="Sucht Bingles",s="Sucht Bingles ist eine Vorquest der Allianz, die in Eisenschmiede von dem Gnom Gnoarn vergeben wird. Aus Sorge um einen Flieger, der vor über einer Woche während eines Aufklärungsflugs in Richtung des gefallenen Gnomeregan verschwand, schickt Gnoarn Abenteurer los, um die Ufer von Loch Modan abzusuchen. Die Suche nach dem vermissten Piloten führt direkt zu Bingles Blastenheimer, der quicklebendig ist, jedoch dringend Hilfe bei der Bergung seiner Ausrüstung benötigt.",h="Sucht Bingles ist eine Vorquest der Allianz, die in Eisenschmiede von dem Gnom Gnoarn vergeben wird.",kw={"bingles","blastenheimer","flugmaschine","gnoarn","gnomeregan","eisenschmiede","loch modan","aufklärung","tüftlerstadt"},ang={["faction:Alliance"]="Kundschafter der Allianz überbrücken häufig die Kommunikationslücke zwischen den Hallen von Eisenschmiede und den Feldeinsätzen in ganz Loch Modan.",["profession:Engineering"]="Ingenieure können die Berufsrisiken der Gnomenluftfahrt gut nachvollziehen, wo eine verlorene Flügelmutter oder eine Triebwerksexplosion einfach zum Alltag im Feld gehören.",["race:Gnome"]="Für die Gnome geht es bei der Rettung von Bingles darum, die Hoffnung auf die Rückeroberung von Gnomeregan aufrechtzuerhalten, wo jeder Kundschafter und jede Flugmaschine zählt."},sec={{t="Ein vermisster Pilot",b="In der geschäftigen Gnomenenklave Tüftlerstadt in Eisenschmiede ist die Sorge um vermisste Artgenossen und verlorene Maschinen groß. Der Gnomenflieger Bingles Blastenheimer wurde auf eine Luftaufklärungsmission über den verstrahlten Ruinen von Gnomeregan entsandt. Als nach mehr als einer Woche noch immer jede Nachricht fehlte, befürchtete Gnoarn das Schlimmste – er vermutete, Bingles sei dem Berufsrisiko der Gnomeningenieure zum Opfer gefallen und habe sich selbst vom Himmel geholt. Die letzte gemeldete Sichtung verortete den exzentrischen Flieger irgendwo über den Gewässern des Lochs."},{t="Unten am Loch",b="Statt eines tragischen Haufens rauchender Trümmer finden die Suchenden Bingles quicklebendig am Ufer von Loch Modan. Völlig unbeeindruckt von seiner langen Abwesenheit und leicht gekränkt darüber, dass man an seinen Flugkünsten zweifelte, konzentriert sich der gestrandete Erfinder ganz auf seine größere Mission. Anstatt unverzüglich zurückzukehren und Gnoarn Bericht zu erstatten, bittet Bingles seine Retter sogleich um Hilfe, um die Werkzeuge und Blastencapper-Sprengstoffe zurückzuholen, die ihm von Troggs gestohlen wurden, damit er seine Pflichten für die Gnomenbewegung wieder aufnehmen kann."}},faq={{q="Wer ist Bingles Blastenheimer?",a="Bingles Blastenheimer ist ein exzentrischer Gnomenflieger und Mechaniker. Er stieg in die Lüfte auf, um die Luftaufklärung über der gefallenen Stadt Gnomeregan durchzuführen, bevor er mit seiner Flugmaschine in der Nähe von Loch Modan abstürzte.",al={"wer ist bingles","bingles blastenheimer lore","wer ist der pilot"}},{q="Warum flog Bingles über Gnomeregan?",a="Die Führung und die Tüftler der Gnome überwachen Gnomeregan nach dessen tragischem Fall an Troggs und Strahlung ununterbrochen. Bingles stieg in die Lüfte, um feindliche Stellungen und die Umweltbedingungen von oben auszukundschaften – ein Teil der größeren Bemühungen, ihre Heimat zurückzuerobern.",al={"bingles mission","warum flog bingles","gnomeregan aufklärung"}},{q="Wo befindet sich Bingles?",a="Bingles sitzt an den Ufern des Lochs in Loch Modan fest, an dessen südöstlichem Ufer, wo er versucht, seine abgestürzte Flugmaschine wieder in Gang zu bringen.",al={"wo ist bingles","sucht bingles standort","wo man bingles findet"}},{q="Wer ist Gnoarn?",a="Gnoarn ist ein Gnomenkoordinator in Tüftlerstadt in Eisenschmiede. Er behält das Gnomenpersonal und die Missionen im Auge und leitet die Suche ein, als Bingles nicht wie geplant zurückkehrt.",al={"wer ist gnoarn","questgeber gnoarn"}},{q="Was geschieht, nachdem man Bingles gefunden hat?",a="Das Finden von Bingles schaltet die Folgequest Bingles' verschwundene Werkzeuge frei, bei der Abenteurer seinen Schraubenschlüssel, Schraubenzieher, Hammer und die Blastencapper-Sprengstoffe von den Troggs auf den Inseln des Lochs zurückholen.",al={"was nach sucht bingles tun","flügelmutter quest","bingles folgequest"}},{q="Wurde Bingles beim Absturz verletzt?",a="Bingles ist völlig unverletzt, auch wenn sein Stolz einen kleinen Knacks bekommen hat, weil Gnoarn an seinen Flugkünsten zweifelte. Seine eigentliche Sorge gilt der Wiederbeschaffung der Werkzeuge und Sprengstoffe, die Troggs ihm gestohlen haben.",al={"ist bingles verletzt","ist bingles gestorben"}}},fx={b67b7bf8={q="Warum will Gnoarn, dass Bingles gefunden wird?",a="Bingles wurde auf einen kritischen Aufklärungsflug über das gefallene Gnomeregan geschickt und hat sich seit mehr als einer Woche nicht zurückgemeldet. Angesichts der unberechenbaren Natur gnomischer Maschinen und Bingles' Hang zur Katastrophe befürchtet Gnoarn, dass der Pilot sich irgendwo in der Wildnis in die Luft gesprengt hat. Er braucht jemanden, der die Region in der Nähe von Loch Modan, wo Bingles zuletzt gesehen wurde, durchsucht, um sein Schicksal zu bestimmen.",al={"warum bingles finden","motiv von gnoarn","warum suchen nach bingles schicken"}}},fp="12,409,15.522.0,16.513.0,29.203.0,39.253.0,25.145.0,14.187.0,35.197.0,31.191.0"}
P.entries["quest:2040"] = {n="Unterirdischer Angriff",s="Unterirdischer Angriff ist eine Allianz-Quest, die von Shoni die Schtille im Zwergendistrikt von Sturmwind angeboten wird. Mit der Aufgabe betraut, den vertriebenen Gnomen beizustehen, wagen sich Abenteurer in die Todesminen, um den intakten Energiekern eines Goblin-Schredders zu bergen. Diese erbeutete Komponente soll Bohrmaschinen antreiben, die als Speerspitze für die Befreiung von Gnomeregan dienen sollen.",h="Unterirdischer Angriff ist eine Allianz-Quest, die von Shoni die Schtille im Zwergendistrikt von Sturmwind...",kw={"die todesminen","gnoamsprenkelspross","gnomeregan","goblin-schredder","gyrobohrmatisch","shoni die schtille","troggs","unterirdischer angriff"},ang={["faction:Alliance"]="Die Unterstützung der vertriebenen Gnome des Zwergendistrikts stärkt das Bündnis zwischen Sturmwind und seinen exilierten Verbündeten und versetzt gleichzeitig den Nachschublinien der Defias einen Schlag.",["profession:Engineering"]="Tüftler werden die wagemutige Ingenieurskunst zu schätzen wissen, den Energiekern eines brutalen Goblin-Schredders auszuschlachten, um gnomische Präzisionsbohrmaschinen anzutreiben.",["race:Gnome"]="Für exilierte gnomische Abenteurer ist die Bergung dieses Energiekerns ein persönlicher Schritt, um die felsigen Wände ihrer gefallenen Heimat zu durchstoßen und die Troggs aus Gnomeregan zu vertreiben."},sec={{t="Verzweifelter Erfindergeist",b="Nach dem katastrophalen Fall von Gnomeregan an die primitiven Troggs wurden die überlebenden gnomischen Tüftler ins Exil nach Khaz Modan und Sturmwind gezwungen. Anstatt in ihrer Niederlage zu verharren, entwickeln Ingenieure wie Shoni die Schtille bereits mechanische Operationen, um in ihre verlorene Heimat einzudringen. Das Haupthindernis ist das dichte, unterirdische Gestein rund um die technokratische Stadt, das gewaltige Tunnelbohrmaschinen erfordert, die als Gyrobohrmatische Exkavation bekannt sind. Da es in den Ländern der Menschen an den notwendigen lokalen Stromnetzen mangelt, haben die Gnome ihren Blick auf eine ungewöhnliche und unberechenbare Alternative gerichtet: schwere Goblin-Maschinerie, die in der kriminellen Unterwelt betrieben wird."},{t="Plünderung der Defias-Gießereien",b="Tief in den verwinkelten Schächten der Todesminen in Westfall beschäftigt Edwin van Cleefs Bruderschaft der Defias Goblin-Ingenieure, um Kriegsmaschinen herzustellen, darunter einen voll einsatzfähigen Goblin-Schredder. Shoni weist Agenten der Allianz an, diese Gießerei zu infiltrieren, den schwerfälligen Automaten zu zerstören oder zu zerlegen und sein spezialisiertes Herzstück zu bergen – das Gnoamsprenkelspross. Indem sie sich die wirkungsvolle Goblin-Energieversorgung aneignen, gewinnen die exilierten Gnom die nötige rohe mechanische Kraft, um die unterirdischen Grenzen zu durchbrechen und eine Gegenoffensive zur Rückeroberung von Gnomeregan zu starten."}},faq={{q="Wer vergibt die Quest „Unterirdischer Angriff“?",a="Die Quest wird von Shoni die Schtille vergeben, einer gnomischen Ingenieurin im Zwergendistrikt von Sturmwind. Abenteurer werden oft an sie verwiesen, nachdem sie mit anderen Gnomen gesprochen haben, die von ihren ehrgeizigen Plänen berichten.",al={"questgeber unterirdischer angriff","wer gibt unterirdischer angriff","shoni quest"}},{q="Wo finde ich den Gnoamsprenkelspross?",a="Der Gnoamsprenkelspross wird aus einem funktionsfähigen Goblin-Schredder tief in den Gießereitunneln der Todesminen in Westfall geborgen.",al={"fundort sprecklesprocket","wo ist sprecklesprocket","schredderteil todesminen"}},{q="Warum benötigt Shoni Teile von einem Goblin-Schredder?",a="Gnomische Gyrobohrmatische Exkavation erfordert eine gewaltige, tragbare Energieversorgung, um die verstärkten unterirdischen Grenzen um Gnomeregan zu durchbrechen. Der Hochleistungs-Energiekern, der den Goblin-Schredder der Bruderschaft der Defias antreibt, liefert genau die für die Bohrer erforderliche mechanische Leistung.",al={"warum goblinteile","warum schredder energieversorgung","zweck von sprecklesprocket"}},{q="Was ist das übergeordnete Ziel dieser Mission?",a="Die Mission dient der künftigen Befreiung von Gnomeregan. Durch den Antrieb schwerer Ausgrabungsbohrer wollen die vertriebenen Gnome direkt durch das Felsmassiv ihrer besetzten Stadt graben und einen Überraschungsangriff gegen die besetzenden Troggs führen.",al={"warum unterirdischer angriff machen","gnomeregan rückeroberung quest","gnomen angriffsplan"}},{q="Was geschah mit Gnomeregan, dass dieser Angriff geplant werden musste?",a="Gnomeregan wurde von einer unterirdischen Trogg-Invasion überwältigt, die tief unter der Stadt hervorbrach. Bei der chaotischen Verteidigung wurde die Stadt durch giftige Strahlung verseucht, was die überlebende gnomische Bevölkerung dazu zwang, als Flüchtlinge nach Eisenschmiede und Sturmwind zu fliehen.",al={"warum fiel gnomeregan","was geschah mit gnomeregan","trogg invasion"}},{q="Sind die Bruderschaft der Defias und die Troggs verbündet?",a="Nein, es gibt keine Verbindung zwischen ihnen. Die Bruderschaft der Defias hat lediglich Goblin-Tüftler angeheuert, um Kriegsmaschinen in Westfall zu bauen. Shoni nutzt die Präsenz der Defias in den Todesminen einfach als bequeme Quelle für ergiebige Goblin-Technologie.",al={"defias und troggs","gehören troggs zu den defias"}}},fx={["41842bc5"]={q="Was ist der Gnoamsprenkelspross?",a="Der Gnoamsprenkelspross ist eine intakte, hocheffiziente Energiezelle der Goblins, die in dem Schredder untergebracht ist, der tief in den Todesminen operiert. Shoni die Schtille beabsichtigt, diesen Energiekern direkt in die Gyrodrillmatic Excavationators der Gnome zu integrieren. Diese schweren Bohrmaschinen benötigen enorme Energie, um sich durch die dichte, felsige unterirdische Umrandung zu bohren, die Gnomeregan abschirmt, und so einen Eingang für die Angriffstruppen der Gnome zu schaffen, die darauf warten, ihre Heimat zurückzuerobern.",al={"was ist gnoamsprenkelspross","zweck von sprenkelspross","was macht die schredder-energiezelle"}},["37ad24fa"]={q="Warum schickt Shoni Euch hinter dem Goblin-Schredder in den Todesminen her?",a="The Defias Brotherhood setzt fortschrittliche Goblin-Technik ein, einschließlich eines voll funktionsfähigen Holz- und Bergbauschredders, um ihre geheimen Operationen unter Mondbruch auszugraben und zu konstruieren. Da diese Kriegsmaschinen bemerkenswert starke Energiekerne verwenden, identifizierte Shoni diese Maschine als erstklassiges Ziel zur Bergung. Ihr werdet ausgesandt, um den Schredder tief im Inneren des Geländes zu demontieren oder zu zerstören und seine intakte Energieeinheit zu extrahieren, bevor die Bruderschaft sie weiter nutzen kann.",al={"wer ist das ziel in den todesminen","warum schredder töten","warum gibt es einen schredder in den todesminen"}}},fp="19,356,21.658.0,28.571.0,40.214.0,43.135.0,49.279.0,41.251.0,67.253.0,49.230.0"}
P.entries["quest:2041"] = {n="Sprecht mit Shoni",s="Diese Überleitung ruft Allianz-Abenteurer aus den Hallen von Eisenschmiede dazu auf, Shoni die Schtille in Sturmwind zu finden. Shoni leitet eine Einheit für unterirdische Angriffe, die dazu bestimmt ist, die laufende Rückeroberung von Gnomeregan zu unterstützen.",h="Diese Überleitung ruft Allianz-Abenteurer aus den Hallen von Eisenschmiede dazu auf, Shoni die Schtille in...",kw={"die tiefenbahn","der zwergendistrikt","gnomeregan","gyrodrillmatic excavationator","eisenschmiede","shoni die schtille","sturmwind","tüftlerstadt","underground assault"},ang={["faction:Alliance"]="Diese Mission demonstriert die enge Logistik zwischen den Hauptstädten der Allianz und nutzt die Tiefenbahn, um Personal zwischen Eisenschmiede und Sturmwind zu transportieren.",["profession:Engineering"]="Shonis Projekt umfasst Gyrodrillmatic Excavationators, eine komplexe Meisterleistung gnomischer Ingenieurskunst, die für Tunnelarbeiten tief unter der Erde entwickelt wurde.",["race:Gnome"]="Jeder Gnom in Eisenschmiede träumt davon, seine verstrahlte Heimat zurückzuerobern; Shonis Befehle anzunehmen bedeutet, aktiv zu den technologischen Bemühungen beizutragen, Gnomeregan zurückzuerobern."},sec={{t="Ein Ruf aus der Tüftlerstadt",b="Nach dem radioaktiven Untergang von Gnomeregan errichteten die überlebenden Gnome ein Exilviertel in Eisenschmiede. Ihre Ingenieure, Tüftler und Strategen schmieden ständig Pläne, um ihre verlorene Heimat zurückzuerobern. Während die zentrale Planung in der Tüftlerstadt verwurzelt bleibt, erstrecken sich die Vorbereitungen an der Front weit über Khaz Modan hinaus. Unternehmungslustige Abenteurer in der Bergstadt werden nach Süden nach Sturmwind umgeleitet, wo spezialisierte militärische Ausrüstung für die unterirdische Kriegsführung vorbereitet wird."},{t="Unterirdische Ambitionen",b="Shoni die Schtille befehligt eine Eliteeinheit für unterirdische Angriffe, die inmitten der Ambosse und Schmieden im Zwergendistrikt von Sturmwind stationiert ist. Um tief in die von Troggs verseuchten Sektoren vorzudringen, benötigen ihre Mineure spezialisierte Maschinen, die als Gyrodrillmatic Excavationators bekannt sind. Shoni zu erreichen ist dank der neu in Betrieb genommenen Tiefenbahn, die Eisenschmiede direkt unter den Bergen mit Sturmwind verbindet, ein Leichtes."}},faq={{q="Wer ist Shoni die Schtille?",a="Shoni die Schtille ist eine gnomische Offizierin, die in Sturmwind stationiert ist. Trotz ihres leisen Beinamens befehligt sie eine Einheit für unterirdische Angriffe, die damit beauftragt ist, schwere Ausgrabungsgeräte zu bauen und einzusetzen, um die Bemühungen zur Rückeroberung von Gnomeregan zu unterstützen.",al={"wer ist shoni","shoni die schtille","wer ist der npc"}},{q="Wo finde ich Shoni die Schtille?",a="Shoni befindet sich im Zwergendistrikt von Sturmwind, in der Nähe der Schmiedelehrer und Schmieden, nur wenige Schritte vom Terminal der Tiefenbahn entfernt.",al={"wo ist shoni","standort von shoni","koordinaten von shoni"}},{q="Wie komme ich von Eisenschmiede nach Sturmwind?",a="Der schnellste Weg ist die Tiefenbahn, ein technisches Wunderwerk, das sich auf der nordöstlichen Seite der Tüftlerstadt in Eisenschmiede befindet. Sie bringt Reisende direkt in den Zwergendistrikt von Sturmwind, ohne dass Ihr durch die Wildnis reisen müsst.",al={"reisen nach sturmwind","von eisenschmiede nach sturmwind","wie erreicht man sturmwind"}},{q="Wobei benötigt Shoni Hilfe?",a="Shoni rüstet eine Einheit für unterirdische Angriffe aus und benötigt wichtige Komponenten für ihre Gyrodrillmatic Excavationators – eine Aufgabe, die Abenteurer schließlich nach Westfall und in die Todesminen führt.",al={"questziel von shoni","was will shoni"}},{q="Wird diese Quest benötigt, um Underground Assault zu erhalten?",a="Nein, es handelt sich um eine optionale Überleitungsquest. Ihr könnt direkt zum Zwergendistrikt in Sturmwind reisen und selbst mit Shoni sprechen, um Underground Assault anzunehmen.",al={"ist speak with shoni erforderlich","kann ich direkt zu shoni"}},{q="Wie hängt das mit Gnomeregan zusammen?",a="Die gnomische Führung versammelt Truppen und Ausgrabungstechnologie, um die Verteidigungsanlagen von Gnomeregan zu durchbrechen. Shonis Team entwickelt die unterirdischen Bohrvorrichtungen, die notwendig sind, um in die verseuchte Stadt einzudringen.",al={"warum gnomeregan","gnomenverbindung"}}},fx={["3fdd7df6"]={q="Warum schickt Euch der Questgeber zu Shoni die Schtille?",a="Die Gnome kämpfen einen schweren Kampf, um ihre gefallene Heimat Gnomeregan zurückzuerobern. Shoni die Schtille befehligt eine unterirdische Angriffstruppe, die spezialisierte Gyrodrillmatic Excavationators für die Kriegsanstrengungen vorbereitet, aber ihren Operationen in Sturmwind fehlen Arbeitskräfte. Das Hauptkommando in Eisenschmiede benötigt fähige Abenteurer, die bereit sind, nach Süden zu reisen und ihr kritisches Ingenieursprojekt zu unterstützen, bevor ihre Offensive voranschreiten kann.",al={"warum mit shoni sprechen","warum zu shoni schicken","warum shoni besuchen"}}},fp="16,216,22.474.0,22.407.0,25.235.0,35.148.0,41.216.0,31.196.0,50.165.0,36.210.0"}
P.entries["quest:2078"] = {n="Gyromasts Rache",s="Gelkak Gyromast sucht Vergeltung an den örtlichen Murlocs, die sein havariertes Schiff an der Küste der Dunkelküste geplündert haben. Um seine Vendetta auszuführen, schickt der exzentrische Kapitän Abenteurer aus, um seinen mechanischen Ersten Offizier, den Threshwackonator 4100, zu reaktivieren.",h="Gelkak Gyromast sucht Vergeltung an den örtlichen Murlocs, die sein havariertes Schiff an der Küste der...",kw={"dunkelküste","gelkak","golem","gyromast","schlüssel","murloc","threshwackonator","threshwackonator 4100"},ang={["faction:Alliance"]="Das Beseitigen fehlerhafter Maschinen und aggressiver Murlocs trägt dazu bei, die Küste für die Reise der Allianz zwischen Auberdine und den Gebieten im Süden zu sichern.",["profession:Engineering"]="Gelkaks mechanischer Erster Offizier zeigt, wie sehr sich ein gestrandeter Kapitän auf seine technische Ausrüstung verlässt.",["race:Gnome"]="Gnome könnten den Aufziehschlüssel als vertrautes Mittel zur Aktivierung eines mechanischen Automatons erkennen."},sec={{t="Die Vendetta eines Kapitäns",b="Gelkak Gyromast ist an den nebligen Stränden der Dunkelküste gestrandet und weigert sich, die Niederlage durch die küstenbewohnenden Murlocs zu akzeptieren. Nachdem er die notwendigen Teile geborgen hat, um seine Pläne zu verwirklichen, hat es der exzentrische Kapitän auf eine vollständige Vergeltung gegen den Stamm und seinen Häuptling abgesehen. Anstatt mit einem Entermesser in der Hand in die Brandung zu waten, verlässt sich Gelkak auf schwere Ingenieurskunst, um seine Rache zu vollstrecken, und vertraut jedem Landratten, der mutig genug ist, mit seinem mechanischen Untergebenen umzugehen, einen Aufziehschlüssel an."},{t="Die Meuterei des Ersten Offiziers",b="Gelkaks vertrauter Erster Offizier ist kein salziger Zwerg oder Seemann, sondern der Threshwackonator 4100 – ein klappernder mechanischer Golem, der in den Untiefen südlich des Wracks zurückgelassen wurde. Während die Aufzieh-Automatisierung ein leichtes Schlachten der Murlocs verspricht, erweist sich diese spezielle Maschine als gefährlich unzuverlässig. Nachdem er aufgezogen und zum Kapitän zurückgeführt wurde, erleidet das Konstrukt eine katastrophale Fehlfunktion, verwechselt seinen Retter und Schöpfer mit feindlichen Zielen und erzwingt einen Kampf am Strand."}},faq={{q="Wer ist Gelkaks Erster Offizier?",a="Gelkaks Erster Offizier ist der Threshwackonator 4100, ein automatisierter mechanischer Golem, der an der Küste südlich des Lagers des gestrandeten Kapitäns ruht.",al={"erster offizier","gelkak erster offizier","wer ist der erste offizier"}},{q="Warum will Gelkak Rache?",a="Gelkaks Schiff ist an der Dunkelküste gestrandet, und die einheimischen Greymist-Murlocs haben sein Hab und Gut geplündert und seine überlebende Mannschaft schikaniert. Gelkak beabsichtigt, seinen Golem einzusetzen, um den Stamm und seinen Häuptling zu zermalmen.",al={"warum rache","murloc rache","gelkak motivation"}},{q="Was passiert, wenn man den Threshwackonator zurückbringt?",a="Führt den Ersten Offizier nach der Aktivierung mit seinem Schlüssel zu Gelkak zurück. Sein Verhalten beim Erreichen des Kapitäns wird während der Eskorte aufgedeckt.",al={"threshwackonator angriff","roboter fehlfunktion","warum greift der golem an"}},{q="Was mache ich mit Gyromasts Schlüssel nach Abschluss der Quest?",a="Der Schlüssel aktiviert den Threshwackonator. Nach Abschluss der Mission hat er keinen weiteren Zweck mehr.",al={"gyromasts schlüssel verwendung","gyromasts schlüssel behalten","kann ich schlüssel löschen"}},{q="Woher hat Gelkak den Threshwackonator?",a="Der Golem ist Teil der Fracht und Ausrüstung, die von Gelkaks verhängnisvoller Reise entlang des nördlichen Kalimdor geborgen wurde, und wurde als schweres mechanisches Muskelpaket für seine Crew konzipiert.",al={"wer baute threshwackonator","threshwackonator herkunft"}},{q="Gibt Gelkak auf, nachdem der Golem zerstört ist?",a="Gelkaks Pläne und seine Reaktion auf Eure Arbeit werden offenbart, wenn Ihr seinen Ersten Offizier zurückbringt.",al={"was passiert mit gelkak","nach gyromasts rache"}}},fx={a39a7119={q="Warum muss Gelkak Euch holen lassen, um seinen ersten Maat zu holen, anstatt selbst zu gehen?",a="Gelkak ist nach einem katastrophalen Schiffbruch am Strand der Dunkelküste gestrandet und vollkommen besessen davon, die Ladung seines gesunkenen Schiffes zu bergen und Rache an den örtlichen Greymist-Murlocs zu nehmen. Da er sich bereits darauf verlassen hat, dass Ihr nach den lebenswichtigen Komponenten seines mechanischen ersten Maats taucht, lagert er weiterhin bei seiner geborgenen Ausrüstung und befiehlt Euch als angeheuertes Besatzungsmitglied – oder in seinen Worten, Landratte –, das Gerät zu starten und sicher zu ihm zurückzubringen.",al={"warum ich gyromast","warum braucht gelkak hilfe","warum kann gelkak den golem nicht selbst holen"}}},fp="18,252,20.490.0,23.473.1,27.138.0,29.206.0,54.140.1,59.97.1,42.159.0,49.93.1"}
P.entries["quest:2098"] = {n="Gyromasts Rettung",s="Nach einem Schiffbruch an der nebligen Küste der Dunkelküste sucht der exzentrische Gnomenpirat Gelkak Gyromast nach Hilfe, um seinen mechanischen Ersten Maat wieder instand zu setzen. Sein lebenswichtiger Aufziehschlüssel zerbrach an den Felsen und wurde von der einheimischen Tierwelt und den Murlocs geplündert. Das Wiederbeschaffen der drei Teile ist der erste Schritt, um seine Mannschaft wieder funktionstüchtig zu machen.",h="Nach einem Schiffbruch an der nebligen Küste der Dunkelküste sucht der exzentrische Gnomenpirat Gelkak...",kw={"dunkelküste","erster maat","waldschreiter","gelkak gyromast","greymist","gyromasts rettung","pirat","riffkriecher","threshadon"},ang={["profession:Engineering"]="Ingenieure können die Herausforderung nachempfinden, mechanische Apparate nach einem verheerenden Schiffbruch in Salzwasser funktionstüchtig zu halten.",["race:Gnome"]="Gnome werden sofort Gelkaks Vorliebe für Uhrwerk-Geräte gegenüber leibhaftigen Kameraden wiedererkennen, auch wenn sein Piratendasein für ihr Volk recht ungewöhnlich ist."},sec={{t="Schiffbrüchiger an der Dunkelküste",b="Gelkak Gyromast ist ein seltsamer Anblick an den düsteren Stränden von Dunkelküste: ein Gnomenpirat, gestrandet fernab der typischen Seerouten der Südlichen Meere. Laut Gelkak fand sein Schiff direkt vor der Küste ein unglückliches Ende, nachdem es von aggressiven Threshadons angegriffen und versenkt worden war. Als er inmitten des Treibguts an Land gespült wurde, fand er sich völlig gestrandet und von seiner treuen Mannschaft getrennt wieder."},{t="Der geplünderte Schlüssel",b="Gelkaks dringlichste Sorge gilt weder Proviant noch Gold, sondern seinem Ersten Maat. Um diesen Gefährten zu aktivieren und zu bedienen, wird ein spezieller Schlüssel benötigt, der in drei verschiedene Bruchstücke zerbrach, als Gelkak an den felsigen Untiefen zerschellte. Bevor er die Fragmente aufsammeln konnte, schnappte sich die einheimische Tierwelt – umherhuschende Riffkriecher am Strand, hoch aufragende Waldschreiter nahe den Wäldern und Aasfresser des hiesigen Greymist-Murlocstammes – die glänzenden Metallteile."},{t="Ein sonderbarer Gefährte",b="Gelkak spricht mit der grimmigen Loyalität eines Seekapitäns von seinem Ersten Maat, obgleich Erwähnungen, den Gefährten „wieder in Schuss bringen“ zu müssen, auf ein ungewöhnliches Besatzungsmitglied hindeuten. Ein auf fremden Gestaden gestrandeter Gnomen-Seefahrer verlässt sich naturgemäß auf mechanischen Erfindungsgeist, und das Zusammensetzen des zerbrochenen Schlüssels erweist sich als unverzichtbar, um welches Uhrwerk-Wunder auch immer wieder in Betrieb zu nehmen, das Gelkak aus den Tiefen geborgen hat."}},faq={{q="Wer ist Gelkak Gyromast?",a="Gelkak Gyromast ist ein exzentrischer Gnomenpirat, der vor der Küste von Dunkelküste Schiffbruch erlitt, als räuberische Threshadons sein Schiff angriffen und versenkten.",al={"gelkak gyromast","wer ist der gnomenpirat","dunkelküste gnomenpirat"}},{q="Wofür wird der Schlüssel verwendet?",a="Der Schlüssel wird benötigt, um Gelkaks Ersten Maat wieder zu aktivieren und aufzuziehen – eine mechanische Schöpfung, die während ihres verhängnisvollen Schiffbruchs abgeschaltet wurde.",al={"warum braucht gelkak den schlüssel","gelkak schlüssel zweck","schlüssel erster maat"}},{q="Wo sind die drei Teile des Schlüssels gelandet?",a="Als der Schlüssel am Ufer zerbrach, wurden die Teile von hiesigen Kreaturen weggeschleppt: Das obere Teil wurde von Waldschreitern mitgenommen, das mittlere von Greymist-Murlocs und das untere von Riffkriechern an der Küste.",al={"wo sind die schlüsselteile","wer stahl den schlüssel","zerbrochener schlüssel dunkelküste"}},{q="Warum segelte ein Gnomenpirat nahe Dunkelküste?",a="Gelkak befuhr die Gewässer vor dem nördlichen Kalimdor auf der Suche nach Beute, doch feindselige Threshadons setzten seiner Reise ein abruptes Ende.",al={"warum ist gelkak in dunkelküste","piraten in dunkelküste"}},{q="Was geschieht, nachdem der Schlüssel wieder zusammengesetzt wurde?",a="Sobald Gelkak alle drei Teile seines Schlüssels besitzt, kann er damit fortfahren, seinen Gefährten aufzuziehen, was direkt in die Quest 'Gyromasts Rache' mündet.",al={"was kommt nach schlüssel","gyromasts bergung folgequest"}},{q="Wer sind die Murlocs, die das Schlüsselteil besitzen?",a="Das mittlere Teil wurde vom Murlocstamm der Greymist geplündert, der sich in den Wracks gesunkener Schiffe entlang der Untiefen von Dunkelküste niedergelassen hat.",al={"dunkelküste murlocs","greymist murloc schlüssel","schiffswrack murlocs"}}},fx={["460afe34"]={q="Warum möchte Gelkak Gyromast, dass sein Schlüssel repariert wird?",a="Gelkak Gyromast erlitt vor der Küste der Dunkelküste Schiffbruch, als Dreschadons sein Schiff versenkten. Gestrandet und umgeben von feindseliger Tierwelt, braucht er seinen mechanischen ersten Maat dringend wieder in funktionstüchtigem Zustand, um sich zu verteidigen und seine Rache an den Kreaturen zu üben, die seine Reise ruinierten. Ohne die drei zerbrochenen Teile des Aufziehschlüssels bleibt sein mechanischer Gefährte völlig regungslos.",al={"warum will gelkak den schlüssel","gelkak gyromast beweggrund","warum gelkak helfen"}},c4a26b9a={q="Warum braucht Gelkak Gyromast Eure Hilfe?",a="Gelkak ist ein gestrandeter Pirat ohne Besatzung und ohne Freunde unter den örtlichen Nachtelfen. Nachdem er den Untergang seines Schiffes kaum überlebt hat und zerschunden an den Strand gespült wurde, ist er nicht in der Lage, gegen die bösartigen Riffler, Schreiter und Murlocs zu kämpfen, die mit seinen zerbrochenen Schlüsselfragmenten davongekommen sind.",al={"warum braucht gelkak mich","warum kann gelkak den schlüssel nicht holen","warum ich gyromast"}}},fp="20,328,21.381.0,17.468.0,20.376.1,23.148.0,25.145.0,41.194.0,46.137.0,42.144.1,42.150.0"}
P.entries["quest:21"] = {n="Scharmützel in der Echokammmine",s="Scharmützel in der Echokammmine ist eine direkte militärische Operation, die von Marschall McBride befohlen wurde, um die Echokammmine von Koboldarbeitern zu säubern. Nach ersten Erkundungen zielt dieser Schlag darauf ab, zu verhindern, dass die unterirdische Plage im Nordhaintal dauerhaft Fuß fasst.",h="Scharmützel in der Echokammmine ist eine direkte militärische Operation, die von Marschall McBride befohlen...",kw={"echokamm","echokammmine","elwynn","kobold","arbeiter","marschall mcbride","mcbride","nordhain","scharmützel","armee von sturmwind"},ang={["class:Warrior"]="Unterirdische Gefechte gegen ausschwärmende Arbeiter bieten jungen Kriegern ihren ersten Vorgeschmack auf Nahkämpfe auf engstem Raum gegen mehrere verschanzte Feinde.",["faction:Alliance"]="Jede Mine, die den vordringenden Monstern wieder entrissen wird, sichert lebenswichtige Steine und Erze, die für den Wiederaufbau und die Befestigung menschlicher Siedlungen nach dem Krieg erforderlich sind.",["profession:Mining"]="Die Beseitigung der Plage weckt neue Hoffnung, dass wertvolle Mineraladern im gesamten Nordhaintal wieder sicher abgebaut und verhüttet werden können.",["race:Human"]="Die Säuberung des Echokamms stellt die erste echte Bewährungsprobe eines Rekruten bei der Verteidigung seines angestammten Königreichs dar und beweist seinen Mut direkt vor den Führungsspitzen des Militärs von Sturmwind."},sec={{t="Säuberung der Mine",b="Nachdem frühe Späher bestätigt hatten, dass Kobolde die Echokammmine überrannt hatten, verlor Marschall McBride keine Zeit, einen aktiven Gegenangriff zu organisieren. Bleibt es ungestört, befestigt das unterirdische Ungeziefer rasch seine Tunnel, hortet gestohlene Ressourcen und vermehrt sich unkontrolliert. Um den lebenswichtigen landwirtschaftlichen und spirituellen Zufluchtsort des Nordhaintals zu schützen, verlässt sich die örtliche Garnison auf Rekruten, die die Koboldarbeiter direkt angreifen und ihre Reihen lichten, bevor sie sich noch weiter verschanzen."},{t="Eine dünne Verteidigung",b="Die Notwendigkeit, frisch angeworbene Rekruten für einen direkten Frontalangriff einzusetzen, spiegelt die angespannte Lage der Armee von Sturmwind wider. Da die Garnisonen an vorderster Front entlang der südlichen Grenzen dünn gesät sind und Gerüchte über wachsende Unruhen in ganz Elwynn die Runde machen, müssen örtliche Offiziere wie McBride alle willigen Hände mustern, die sie finden können. Das erfolgreiche Scharmützel in der Echokammmine beweist die Zuverlässigkeit des Rekruten, bringt ihm formellen Respekt ein und bereitet ihn auf wichtigere Einsätze an anderen Orten des Königreichs vor."}},faq={{q="Warum wird die Echokammmine von Kobolden heimgesucht?",a="Kobolde fühlen sich naturgemäß von mineralreichen unterirdischen Stollen und verlassenen Steinbrüchen angezogen. Da das Militär von Sturmwind überlastet ist, wurden unbewachte Orte wie der Echokamm zu leichten Zielen für Ungeziefer, das Höhlen graben, Gold horten und unterirdisch Fuß fassen will.",al={"warum kobolde in der mine","kobolde im echokamm","was machen kobolde"}},{q="Wer befiehlt das Scharmützel?",a="Marschall McBride, der ranghöchste Offizier der Armee von Sturmwind, der in der Abtei von Nordhain stationiert ist, befehligt die Operation. Er überwacht die Verteidigung des Tals und ist damit beauftragt, trotz begrenzter militärischer Truppenstärke die Ordnung aufrechtzuerhalten.",al={"wer vergibt scharmützel-quest","befehle von marschall mcbride"}},{q="Welche strategische Bedeutung hat die Echokammmine?",a="Der Echokamm liefert Rohsteine und Erze, die für die Instandhaltung von Nordhain und die umfassenderen Wiederaufbaubemühungen von Sturmwind unerlässlich sind. Zuzulassen, dass sich direkt an der Nordgrenze von Nordhain eine Plage ausbreitet, stellt eine unmittelbare physische Bedrohung für die Abtei und die nahe gelegenen Weinberge dar.",al={"warum der echokamm wichtig ist","bedeutung der echokammmine"}},{q="Wohin führt diese Mission als Nächstes?",a="Sobald die Mine vom anfänglichen Widerstand der Arbeiter befreit ist, erkennt Marschall McBride die bewiesene Kampfkraft des Abenteurers an und schickt ihn weiter nach Goldhain, um die regionale Verteidigung zu unterstützen.",al={"welche quest nach scharmützel","nächster schritt nach echokamm"}},{q="Warum säubert die Armee von Sturmwind die Mine nicht selbst?",a="Der Armee von Sturmwind mangelt es akut an Personal, da sie damit zu kämpfen hat, ferne Grenzen zu verteidigen und auf Banditentum in ganz Elwynn zu reagieren. Offiziere wie McBride müssen sich auf neu vereidigte Rekruten verlassen, um örtliche Bedrohungen zu bewältigen, während erfahrene Wachen die Verteidigungslinien sichern.",al={"warum rekruten","wo sind die soldaten von sturmwind"}},{q="Sind Kobolde intelligent genug, um eine organisierte militärische Bedrohung darzustellen?",a="Einzelne Koboldarbeiter sind zwar feige und einfältig, in großer Zahl jedoch gefährlich territorial und aggressiv. Wenn man sie gewähren lässt, graben sie rasch labyrinthartige Tunnel, versehen Höhlen mit Fallen und locken größeres, besser bewaffnetes Ungeziefer an.",al={"sind kobolde klug","gefahrenstufe kobolde"}}},fx={a391cdc3={q="Warum möchte Marschall McBride, dass die Kobolde in der Echokammmine dezimiert werden?",a="Marschall McBride weiß, dass die Kobolde in der Echokammmine umso tiefer in Nordhain Fuß fassen, je länger sie ungehindert bleiben. Sie in Ruhe zu lassen lädt sie dazu ein, sich weiter zu verschanzen und das Tal zu bedrohen, was ihre spätere Vertreibung weitaus blutiger machen würde und die Sicherheit der Abtei von Nordhain selbst gefährdet.",al={"warum kobolde in der echokammmine töten","mcbride beweggrund echokammmine","warum echokammmine räumen"}}},fp="22,283,16.486.0,14.500.0,46.266.0,24.223.0,52.263.0,34.203.0,57.260.0,66.252.0"}
P.entries["quest:2118"] = {n="Verseuchtes Land",s="Verseuchtes Land ist eine Quest der Allianz, die von Tharnariun Baumwahrer an der Dunkelküste angeboten wird. Getrieben von dem Wunsch, der sich ausbreitenden Verderbnis der einheimischen Tierwelt Einhalt zu gebieten, beauftragt Tharnariun Abenteurer damit, einen wütenden Distelbären mithilfe eines verzauberten Relikts lebend zu fangen, um ein Heilmittel zu erproben.",h="Verseuchtes Land ist eine Quest der Allianz, die von Tharnariun Baumwahrer an der Dunkelküste angeboten wird.",kw={"ausrottung der infizierten","dunkelküste","verseuchtes land","wütender distelbär","tharnariun baumwahrer","tharnariuns hoffnung","distelbär"},ang={["class:Druid"]="Druiden teilen Tharnariuns Kummer über den Anblick der verdorbenen Natur, und der tragische Verlust des Bären unterstreicht die heimtückische Tiefe der sich ausbreitenden Krankheit des Landes.",["faction:Alliance"]="Reisende der Allianz, die durch das nördliche Kalimdor ziehen, müssen sich mit der ungebändigten Verderbnis auseinandersetzen, die direkt an die Grenzen besiedelter Gebiete heranreicht.",["race:NightElf"]="Für die Kaldorei ist es ein Frevel an Cenarius und dem Gleichgewicht der Natur, das sie zu schützen geschworen haben, mitzuerleben, wie die heimische Flora und Fauna der Dunkelküste in tollwütigen Wahn verfällt."},sec={{t="Eine Plage in der Wildnis",b="Ein unheilvolles Leiden kriecht durch die Wälder der Dunkelküste und verwandelt deren Bestien in rasende, aggressive Schatten ihres früheren Wesens. Die einheimischen Distelbären haben unter diesem Wahn am schwersten gelitten und sind einer tollwütigen Raserei verfallen, die sowohl vorbeireisende Wanderer als auch das empfindliche ökologische Gleichgewicht der Küste bedroht. Wo Schildwachen der Nachtelfen oft mit Stahl antworten, versuchen die Druiden, die Ursache zu ergründen und zu heilen."},{t="Tharnariuns Hoffnung",b="Da Tharnariun Baumwahrer sich weigert, die verdorbenen Bestien abzuschlachten, ohne versucht zu haben, sie zu retten, fertigte er eine spezielle Falle namens Tharnariuns Hoffnung an. Abenteurer platzieren das Gerät auf dem Waldboden und nutzen sein beruhigendes Licht, um den Geist eines wütenden Distelbären vorübergehend zu besänftigen. Sobald die Kreatur beruhigt ist, folgt sie dem Reisenden folgsam zurück zu Tharnariuns Außenposten, wo sie untersucht werden soll."},{t="Tragische Heilkunst",b="Führt ein Abenteurer einen infizierten Bären erfolgreich ins Lager, versucht Tharnariun unverzüglich, die Krankheit mit wiederherstellender Magie zu läutern. Leider erweisen sich seine ersten Versuche als verheerend: Die wirbelnden reinigenden Energien überwältigen die geschwächte Konstitution des Tieres, sodass die Bestie auf der Stelle zusammenbricht und stirbt. Dieser Fehlschlag verdeutlicht, wie tief die finstere Seuche bereits Fuß gefasst hat."}},faq={{q="Wer vergibt die Quest Verseuchtes Land?",a="Die Quest wird von Tharnariun Baumwahrer vergeben, einem Nachtelfen-Druiden in Auberdine an der Dunkelküste, der versucht, die befallene Tierwelt zu heilen.",al={"questgeber verseuchtes land","tharnariun dunkelküste quest","wer startet verseuchtes land"}},{q="Was ist das Ziel von Verseuchtes Land?",a="Ihr müsst den bereitgestellten Gegenstand Tharnariuns Hoffnung einsetzen, um einen wütenden Distelbären an der Dunkelküste einzufangen und zu besänftigen, und die gebändigte Kreatur anschließend lebend zu Tharnariun zurückführen.",al={"ziel verseuchtes land","was tun in verseuchtes land","wie bären fangen dunkelküste"}},{q="Was geschieht mit dem Bären, wenn man ihn zurückbringt?",a="Tharnariun versucht, das Tier mit Heilmagie zu reinigen, doch die Krankheit ist bereits zu weit fortgeschritten. Die Anstrengung überwältigt die Kreatur, und sie stirbt unmittelbar nach der Behandlung.",al={"stirbt der bär","tharnariun bär heilung ergebnis","tod des bären verseuchtes land"}},{q="Welchen Gegenstand verwendet man, um den Bären einzufangen?",a="Tharnariun stellt ein verzaubertes Fanggerät namens Tharnariuns Hoffnung zur Verfügung, das ein beruhigendes Licht ausstrahlt; dieses besänftigt den wütenden Bären, sodass er Euch folgt.",al={"falle verseuchtes land","tharnariuns hoffnung gegenstand","bärenkäfig dunkelküste"}},{q="Welche Quest folgt auf Verseuchtes Land?",a="Verseuchtes Land ist das erste Kapitel einer dreiteiligen Reihe. Ihr Abschluss schaltet die Folgequest Ausrottung der Infizierten frei, die schließlich zur finalen Quest Tharnariuns Hoffnung führt.",al={"nächste quest nach verseuchtes land","questreihe verseuchtes land","tharnariun folgequest"}},{q="Warum sind die Distelbären wütend?",a="Eine schleichende, verderbende Seuche breitet sich über die Dunkelküste aus, vergiftet Geist und Körper der heimischen Wildtiere und treibt edle Distelbären in sinnlose Aggression.",al={"warum sind bären krank an der dunkelküste","dunkelküste seuchenbären","dunkelküste verderbnis"}}},fx={bbb593c2={q="Warum möchte Tharnariun Baumwahrer, dass Ihr einen tollwütigen Distelbären fangt?",a="Eine dunkle Krankheit breitet sich über die Dunkelküste aus und ergreift Geist und Körper der örtlichen Tierwelt. Die Distelbären hat es am schlimmsten getroffen; sie verwandelten sich von edlen Waldtieren in rasende Zerstörungsmaschinen. Tharnariun Baumwahrer glaubt, er könnte ein Heilmittel für das Leiden entwickelt haben, aber er braucht ein lebendes, tollwütiges Subjekt, das direkt zu ihm gebracht wird, damit er sein Heilmittel testen und die Verderbnis aufhalten kann, bevor sie alle Kreaturen des Waldes befallen hat.",al={"warum distelbären fangen","tharnariun beweggrund plagued lands","warum will tharnariun einen bären"}},["1b7f183c"]={q="Was sind tollwütige Distelbären und warum jagt Ihr sie?",a="Distelbären sind heimische Raubtiere der Dunkelküste, die normalerweise als standhafte und edle Bestien verehrt werden. Jedoch hat eine unnatürliche Ansteckung kürzlich ihre Reihen infiziert, sie in einen wahnsinnigen Rausch getrieben und ihren Verstand verzerrt. Ihr werdet nicht ausgesandt, um sie einfach abzuschlachten, sondern um ein krankes Exemplar mit Tharnariuns Falle anzulocken und zu beruhigen, damit es sicher untersucht werden kann, in der Hoffnung, ein Gegenmittel zu entwickeln.",al={"was sind tollwütige distelbären","warum tollwütige distelbären jagen","tollwütiger distelbär dunkelküste"}}},fp="13,269,26.422.0,17.371.0,15.390.1,34.139.0,39.161.0,48.186.1,41.155.0,33.189.0,32.171.0"}
P.entries["quest:2138"] = {n="Ausrottung der Infizierten",s="Ausrottung der Infizierten ist eine Allianzaufgabe an der Dunkelküste, die von Tharnariun Baumwahrer in Auberdine vergeben wird. Nachdem sein Heilungsversuch die Waldkrankheit nicht stoppen konnte, befiehlt der Pfleger schweren Herzens die Tötung der tollwütigen Distelbären, die durch die neblige Wildnis streifen. Es stellt einen bitteren Wendepunkt dar, an dem der Erhalt der Eindämmung weicht.",h="Ausrottung der Infizierten ist eine Allianzaufgabe an der Dunkelküste, die von Tharnariun Baumwahrer in...",kw={"auberdine","ausrottung","dunkelkueste","infizierte","tollwütiger distelbär","tharnariun","treetender"},ang={["class:Druid"]="Druiden, die die Geister der wilden Bären verehren, empfinden Tharnariuns Befehl als besonders schmerzhaft: Es ist ein Akt der Gnade und forstlichen Schadensbegrenzung statt einer gewöhnlichen Jagd.",["class:Hunter"]="Jäger verstehen, dass das Ausdünnen erkrankter Raubtiere manchmal zwingend erforderlich ist, um die weitere Ökologie zu schützen, selbst wenn die eigentliche Ursache ungelöst bleibt.",["race:NightElf"]="Für die Kaldorei ist der Befehl zur Schlachtung verdorbener Bestien eine schwere Last, die verdeutlicht, wie tief die Verderbnis der Nachkriegszeit in ihre uralte Heimat eingedrungen ist."},sec={{t="Eine bittere Notwendigkeit",b="Tharnariun Baumwahrer hat viele Stunden damit verbracht, nach einem Heilmittel zu suchen, um das schleichende Leiden einzudämmen, das die Tierwelt der Dunkelküste verdirbt. Trotz seines Versuchs, einen gefangenen Bären zu reinigen, bleiben die Distelbären schwer krank und gewalttätig. Nachdem er seine sanfteren Optionen erschöpft hat, kommt der Nachtelfenpfleger zu dem Schluss, dass das Töten der Bestien der einzige unmittelbare Weg ist, um zu verhindern, dass sie andere Kreaturen zerfleischen und ihre Krankheit weiter in die uralten Wälder tragen."},{t="Eindämmung der Wildnis",b="Das Erlegen von zwanzig tollwütigen Bären ist eine qualvolle Pflicht für jeden Diener der Natur. Tharnariun räumt offen ein, dass das Töten der Bestien die zugrundeliegende Seuche nicht heilen wird, aber es verschafft den Verteidigern von Auberdine wertvolle Zeit. Bis die Hauptquelle der Verderbnis des Waldes identifiziert und abgetrennt werden kann, bleibt das Ausdünnen der aggressiven Herden der einzige Puffer der Siedlung gegen eine Katastrophe."}},faq={{q="Warum möchte Tharnariun, dass die Distelbären getötet statt geheilt werden?",a="Tharnariun versuchte zuvor, einen gefangenen Bären zu reinigen, doch das Heilmittel schlug fehl und das Tier starb. Da die erkrankten Bären gewalttätig werden und andere Kreaturen bedrohen, ist ihre Tötung ein letzter Ausweg, um die Ausbreitung der Krankheit zu verlangsamen.",al={"warum bären töten","warum bären nicht heilen","tharnariun bären quest"}},{q="Wer ist Tharnariun Baumwahrer?",a="Tharnariun ist ein Nachtelfenpfleger, der in Auberdine stationiert ist. Er erforscht die Leiden, die Flora und Fauna der Dunkelküste befallen haben, und bemüht sich, das natürliche Gleichgewicht gegen die sich ausbreitende Verderbnis zu bewahren.",al={"tharnariun rolle","wer gibt ausrottung der infizierten"}},{q="Beendet das Töten der tollwütigen Bären die Seuche tatsächlich?",a="Nein. Tharnariun warnt ausdrücklich davor, dass das Töten der tollwütigen Bären die Seuche nicht stoppen wird. Es verschafft dem Wald und den Bewohnern von Auberdine lediglich kostbare Zeit, indem es das Tempo von Infektion und Gewalt drosselt.",al={"rettet das die dunkelkueste","ist die seuche geheilt"}},{q="Was folgt auf Ausrottung der Infizierten?",a="Sobald Ihr Tharnariun Bericht erstattet habt, bittet er Euch, Euren Geist auf weiteres Blutvergießen vorzubereiten, und bietet die Folgequest Tharnariuns Hoffnung an, um sich weiter um die verdorbene Tierwelt zu kümmern.",al={"folgequest nach ausrottung","was folgt auf ausrottung der infizierten"}},{q="Wo sind die tollwütigen Distelbären zu finden?",a="Tollwütige Distelbären durchstreifen die Küsten- und Binnenwaldgebiete der zentralen Dunkelküste und sind oft zwischen den nebligen Kiefern südlich und östlich von Auberdine anzutreffen.",al={"tollwütiger distelbär fundort","wo sind bären dunkelkueste"}},{q="Was hat die Distelbären tollwütig gemacht?",a="Die Bären sind Opfer eines mysteriösen Verderbs, der die Wälder des nördlichen Kalimdor heimsucht und friedliche Wildtiere in rasende, aggressive Bestien verwandelt, die Tharnariuns Heilungsversuch trotzen.",al={"warum sind bären krank","bärenkrankheit dunkelkueste"}}},fx={acd0862d={q="Was sind tollwütige Distelbären und warum müssen sie getötet werden?",a="Distelbären sind heimische Waldraubtiere, die normalerweise in Harmonie mit der Wildnis der Dunkelküste leben. Eine schleichende, unnatürliche Seuche jedoch, die sich durch die Wälder ausbreitet, hat viele von ihnen tollwütig und gewalttätig-wahnsinnig gemacht. In ihrem verpesteten Wahnsinn greifen diese kranken Bestien andere Tiere an, bedrohen Reisende in der Nähe von Auberdine und verwüsten die Ökologie des Waldes. Da Versuche, ihr Leiden zu heilen, fehlgeschlagen sind, ist das Töten der einzige Weg, die Verwüstung einzudämmen.",al={"tollwütige distelbären","wer sind tollwütige distelbären","warum tollwütige distelbären töten"}}},fp="25,344,18.466.0,20.402.1,67.232.0,29.192.0,53.202.0,43.189.0,40.159.0,42.192.0"}
P.entries["quest:2139"] = {n="Tharnariuns Hoffnung",s="Tharnariuns Hoffnung ist der düstere Abschluss von Tharnariun Baumwahrers Bemühungen, die Wildtierkrankheit der Dunkelküste einzudämmen. Nachdem unzählige infizierte Bestien in den Wäldern erlöst wurden, erhält ein Champion der Allianz den Auftrag, die tollwütige Den Mother nordöstlich von Auberdine zu erlegen.",h="Tharnariuns Hoffnung ist der düstere Abschluss von Tharnariun Baumwahrers Bemühungen, die Wildtierkrankheit...",kw={"auberdine","bashal'aran","ausrottung der infizierten","dunkelküste","den mother","tollwütiger thistle bear","tharnariun baumwahrer","tharnariuns hoffnung"},ang={["class:Druid"]="Druiden bringen Bären durch die Lehren von Ursoc hohe spirituelle Wertschätzung entgegen. Die Hinrichtung einer verdorbenen Den Mother dient als ernüchternde Mahnung an das empfindliche Gleichgewicht der Natur und die Tragödien des Verderbens.",["class:Hunter"]="Jäger verstehen die Tragödie eines Spitzenprädators, der durch eine Krankheit in den Wahnsinn getrieben wurde, und erkennen, wann die Tötung eines infizierten Tieres der wahrhaftigste Akt der Gnade ist.",["faction:Alliance"]="Der Schutz von Auberdine stärkt die Stellung der Allianz an der Küste des nördlichen Kalimdor und beweist ihre Entschlossenheit, die Länder der Nachtelfen gegen eskalierende Bedrohungen aus der Wildnis zu verteidigen.",["race:NightElf"]="Für Nachtelfen widerspricht das Töten von Waldtieren – insbesondere einer Bärenmatriarchin – ihrer grundlegenden Ehrfurcht vor der Natur, was diese Pflicht zu einer bitteren und schmerzhaften Notwendigkeit macht."},sec={{t="Eine tragische Notwendigkeit",b="Nach dem Dritten Krieg erlagen die wilden Kreaturen von Dunkelküste einer unnatürlichen, tollwutartigen Krankheit. Tharnariun Baumwahrer, der in Auberdine stationiert war, beauftragte tagelang Reisende damit, infizierte Tiere zu erlösen, um die Qualen des Waldes zu lindern. Das Keulen tollwütiger Thistle Bears behandelte jedoch nur das Symptom. Um die Ausbreitung aufzuhalten, stellte er fest, dass der Ursprung unter den einheimischen Bären beseitigt werden musste: die als Den Mother bekannte Matriarchin."},{t="Die Den Mother",b="Die Den Mother lauerte in einer Höhle nordöstlich von Auberdine nahe den uralten Ruinen von Bashal'Aran und war einst eine wichtige Beschützerin der Waldtiere. Von dem wahnsinnigen Leiden verzehrt, das sich über das nördliche Kalimdor ausbreitete, brachte sie fortwährend Würfe tollwütiger Jungen zur Welt und zog sie auf. Indem Helden der Allianz die Matriarchin in ihrem Bau zur Strecke brachten, setzten sie ihren Qualen ein Ende und hielten die Flut rasender Bären auf, die die Küstenstraße unsicher machten."},{t="Die düstere Realität von Kalimdor",b="Nach dem Ableben der Den Mother drückt Tharnariun tiefe Dankbarkeit aus, wenngleich von Melancholie überschattet. Für die Kaldorei ist es eine qualvolle Pflicht, Waffen gegen Waldkreaturen zu erheben. Doch während finstere Mächte gegen ihre neue Heimat drängen und viele verzweifeln oder Zuflucht suchen, beweisen Taten wie diese, dass die Verteidiger von Auberdine bereit sind, die schwere moralische Last zu tragen, die der Schutz ihrer Wildnis erfordert."}},faq={{q="Wer ist Tharnariun Baumwahrer?",a="Tharnariun Baumwahrer ist ein Pfleger der Nachtelfen, der in Auberdine stationiert ist. Bestürzt über die Seuche und den Wahnsinn, die die Tierwelt von Dunkelküste verzerren, leitet er die Bemühungen, leidende Tiere zu erforschen, aufzuspüren und schließlich von ihren Qualen zu erlösen.",al={"tharnariun","wer vergibt tharnariuns hoffnung","treetender auberdine"}},{q="Wo befindet sich die Den Mother?",a="Sie haust in einer Höhle in den Hügeln nordöstlich von Auberdine, direkt östlich der Ruinen von Bashal'Aran.",al={"wo ist den mother","höhle von den mother standort","den mother finden"}},{q="Warum muss die Den Mother getötet anstatt geheilt werden?",a="Das Leiden, das die Tierwelt von Dunkelküste heimsucht, sitzt tief und treibt die Tiere in heftige Raserei. Da es kein unmittelbares Heilmittel gab und die Den Mother unentwegt tollwütigen Nachwuchs aufzog, gelangte Tharnariun zu dem Schluss, dass ihre Tötung der einzige Weg war, um eine weitere Ausbreitung der Krankheit zu verhindern.",al={"kann den mother gerettet werden","warum den mother töten","den mother heilen"}},{q="Welche Quests führen zu Tharnariuns Hoffnung?",a="Diese Quest ist der letzte Schritt einer dreiteiligen Reihe. Sie beginnt mit 'Plagued Lands', setzt sich über 'Ausrottung der Infizierten' fort und schließt mit 'Tharnariuns Hoffnung' ab.",al={"voraussetzungen für tharnariuns hoffnung","questreihe tharnariun"}},{q="Was macht die Tiere von Dunkelküste krank?",a="Tharnariun nennt keine Ursache. Er weiß nur, dass sich eine Krankheit in Dunkelküste ausbreitet, die Geist und Körper aller Befallenen ergreift, und dass die Thistle Bears am härtesten betroffen sind.",al={"warum bären in dunkelküste tollwütig sind","dunkelküste tierplage ursache","was hat die bären verdorben"}},{q="Warum erwähnt Tharnariun Leute, die in befestigte Länder fliehen?",a="Auberdine ist ein exponierter Küstenaußenposten, der von Geistern, verdorbener Tierwelt und feindseligen Kreaturen bedrängt wird. Während die Zivilisation der Nachtelfen nach der Invasion der Brennenden Legion um den Wiederaufbau kämpft, fühlen sich einige Bewohner überfordert und entscheiden sich dafür, sich zu verstecken oder in sicherere Bastionen der Allianz zurückzuziehen.",al={"flucht aus auberdine","befestigte allianzländer"}}},fx={f873ab28={q="Wer ist die Höhlenmutter?",a="Die Höhlenmutter ist ein massiver, verderbter Bär, der in einer Höhle nordöstlich in der Nähe der Ruinen von Bashal'Aran haust. Sie ist die Quelle, die die tollwütigen Distelbären gebärt oder beherbergt, die die Region plagen. Sie zu erschlagen stoppt den Zustrom kranker Bestien, die Auberdine bedrohen.",al={"was ist die höhlenmutter","wer ist die höhlenmutter","höhlenmutter dunkelküste"}}},fp="17,272,18.445.0,14.431.1,28.400.0,29.234.0,32.110.0,51.305.0,41.170.0,45.198.0,63.294.0"}
P.entries["quest:214"] = {n="Rote Seidenkopftücher",s="Rote Seidenkopftücher ist ein Auftrag, der von Späherin Riell im Namen der Volksmiliz erteilt wird. Er schickt Abenteurer der Allianz in die Todesminen, um hochrangige Defias-Aktivisten zur Strecke zu bringen und ihre markanten roten Seidenmasken als Beweis zurückzubringen.",h="Rote Seidenkopftücher ist ein Auftrag, der von Späherin Riell im Namen der Volksmiliz erteilt wird.",kw={"die todesminen","bruderschaft der defias","mondbruch","volksmiliz","rote seidenkopftücher","späherin riell","vancleef","westfall"},ang={["class:Rogue"]="Die roten Seidenmasken der Defias stehen für eine berüchtigte Tradition der Unterweltkriminalität und zeichnen erfahrene Halsabschneider sowie verdeckte Verschwörer aus.",["faction:Alliance"]="Jeder in den Todesminen gefallene Offizier lockert den eisernen Griff der Bruderschaft auf die Kornkammer des Königreichs Sturmwind.",["profession:Tailoring"]="Feine rote Seide ist ein kostspieliger Luxus für gewöhnliche Banditen, was verdeutlicht, wie üppig ausgerüstet und finanziert die Führung der Bruderschaft in Wahrheit ist."},sec={{t="Eine Hierarchie im Tuch",b="Während gewöhnliche Beutelschneider und Wegelagerer in ganz Westfall groben roten Stoff um ihre Gesichter binden, pflegt Die Bruderschaft der Defias eine strenge interne Hierarchie, die sich im Gewebe zeigt. Späherin Riell und Die Volksmiliz haben herausgefunden, dass einfache Banditen grobes Gewebe tragen, während leitende Verschwörer und Agenten des inneren Zirkels sich durch feine rote Seide auszeichnen. Ihnen diese Kopftücher abzunehmen, trifft gezielt die erfahrenen Offiziere, die den Aufstand von Edwin van Cleef koordinieren."},{t="Ein Schlag ins Zentrum",b="Da Seide ein Zeichen von Dienstalter und Rang ist, versammelt sich die größte Dichte dieser hochrangigen Gesetzlosen tief in den Todesminen unter Mondbruch. Schildwachen und Späher, die außerhalb der Späherkuppe stationiert sind, verlassen sich auf freischaffende Helden, um in die umkämpften unterirdischen Tunnel vorzustoßen. Jedes sichergestellte Seidenkopftuch bedeutet einen Leutnant weniger, der Hinterhalte organisiert, Waffenlager verteidigt oder Van Cleefs Herrschaft über Westfall durchsetzt."}},faq={{q="Warum tragen die Defias rote Kopftücher?",a="Das rote Kopftuch dient als einheitliches Emblem und Erkennungszeichen der Bruderschaft der Defias in den gesamten Gebieten von Sturmwind. Es verbirgt ihre Identität und signalisiert zugleich ihre Treue zu Edwin van Cleefs rebellischer Bewegung.",al={"bedeutung defias maske","warum rote masken","defias uniform"}},{q="Was macht die roten Seidenkopftücher im Vergleich zu gewöhnlichen Kopftüchern so besonders?",a="Laut Späherin Riell zeigt der Stoff den Status innerhalb der Bruderschaft an. Gewöhnliche Straßendiebe tragen grobes, billiges Material, während Veteranen, Offiziere und vertraute Leutnants mit roter Seide belohnt werden.",al={"warum rote seide","seide gegen stoff defias","unterschied seidenkopftuch"}},{q="Wer ist Späherin Riell?",a="Späherin Riell ist eine Agentin im Dienst der Volksmiliz in Westfall, deren Aufgabe es ist, die Bewegungen der Defias zu überwachen und Abenteurer anzuleiten, ihre Hochburgen rund um die Todesminen anzugreifen.",al={"späherin riell westfall","wer gibt quest rote seidenkopftücher"}},{q="Wo halten sich die Defias mit den Seidenkopftüchern auf?",a="Sie konzentrieren sich in und um die Todesminen unter der Ortschaft Mondbruch, wo Edwin van Cleefs ranghöchste Truppen die unterirdischen Operationen leiten.",al={"wo findet man seidenkopftücher","todesminen seidenkopftuch fundort"}},{q="Was ist die Volksmiliz?",a="Die Volksmiliz ist eine freiwillige Verteidigungstruppe, die von Gryan Starkmantel und den bedrängten Bauern von Westfall gegründet wurde, um ihr Land zu schützen, nachdem die Armee von Sturmwind keine ausreichenden Garnisonen stellen konnte.",al={"wer ist die volksmiliz","volksmiliz westfall"}},{q="Haben diese Kopftücher einen Zweck abseits des Nachweises eines Tötens?",a="Für die Volksmiliz dienen sie rein als unumstößlicher Beweis dafür, dass hochrangige Gesetzlose ausgeschaltet wurden, was die Befehlskette der Bruderschaft schwächt.",al={"kann man rotes seidenkopftuch tragen","wofür sind die kopftücher"}}},fx={["09c03d28"]={q="Warum möchte Späherin Riell, dass Rote Seidenbandanas gesammelt werden?",a="Späherin Riell versucht, im Namen der Volksmiliz einen entscheidenden Schlag gegen die Führung von The Defias Brotherhood zu führen. Die Miliz weiß, dass Seidenbandanas eher ranghohe Offiziere als bloße Schläger kennzeichnen. Indem sie diese Schlüsselfiguren eliminiert und ihre Bandanas als Beweis fordert, hofft Riell, die Kommandostruktur der Bruderschaft zu zerschlagen und Westfall endlich für seine Bewohner zurückzugewinnen.",al={"warum scout riell bandanas","scout riell beweggrund","warum rote seidenbandanas sammeln"}},["762e9a74"]={q="Gegen wen werdet Ihr ausgesandt?",a="Ihr jagt die Eliteoffiziere und Veteranen von The Defias Brotherhood, die in und um Edwin van Cleefs Festung innerhalb der Todesminen stationiert sind. Anders als die groben Halsabschneider, die durch Westfalls Farmen streifen, bewachen diese ranghohen Mitglieder die Operationsbasis der Bruderschaft, beaufsichtigen die versteckten Arbeiten tief unter Mondbruch und leiten die Operationen des Syndikats in der gesamten Region.",al={"wen jagen wir","rotes seidenbandana ziel","wer lässt seidenbandanas fallen"}},["966e78fe"]={q="Warum fragt Späherin Riell Euch anstelle der Wachen von Sturmwind?",a="Sturmwind hat Westfall praktisch aufgegeben und bietet wenig bis gar keine militärische Unterstützung, während das Haus der Adligen die wachsende Krise ignoriert. Die örtliche Volksmiliz ist überlastet und verfügt nicht über die Zahlen, die Ausbildung und die Ressourcen, um einen Frontalangriff auf befestigte kriminelle Bastionen zu starten. Riell und ihre Mitstreiter müssen sich auf fähige Abenteurer verlassen, um die tückischen Todesminen zu infiltrieren und sich der Führung der Bruderschaft direkt zu stellen.",al={"warum nicht die armee von sturmwind","warum einen abenteurer schicken","warum brauche ich"}}},fp="17,240,20.475.0,17.421.0,36.216.0,70.196.0,19.186.0,51.149.0,29.201.0,57.165.0"}
P.entries["quest:2159"] = {n="Lieferung für Dolanaar",s="Lieferung für Dolanaar ist ein Botengang, der jungen Nachtelfen anvertraut wird, die das schützende Geäst von Laubschattental verlassen, um die weiteren Gefilde von Teldrassil zu erkunden. Porthannius, der durch Angelegenheiten mit den örtlichen Druiden aufgehalten wird, beauftragt Reisende damit, ein Päckchen Kräuter nach Süden zu Gastwirt Keldamyr zu bringen. Die einfache Reise markiert für einen Initianden den Übergang in das geschäftige Zentrum von Dolanaar.",h="Lieferung für Dolanaar ist ein Botengang, der jungen Nachtelfen anvertraut wird, die das schützende Geäst von...",kw={"lieferung","dolanaar","lieferung für dolanaar","kräuter","gastwirt keldamyr","nachtelf","porthannius","laubschattental","teldrassil"},ang={["class:Druid"]="Porthannius' Beschäftigung mit den Druiden von Laubschattental deutet auf die tieferen spirituellen Pflichten und das natürliche Ungleichgewicht hin, die den Zirkel des Cenarius im Geäst des Baumes in Anspruch nehmen.",["profession:Herbalism"]="Die Lieferung verdeutlicht, wie wichtig frische Kräuter aus den fruchtbaren Böden von Laubschattental für die Heiler, Köche und Pfleger von Dolanaar sind.",["race:NightElf"]="Die Annahme dieser Aufgabe markiert für einen Nachtelfen den Aufbruch aus der geschützten Wiege von Aldrassil hinaus in die weitreichenderen Pflichten zum Schutz von Teldrassil."},sec={{t="Ein Bote für Laubschattental",b="Bevor neue Abenteurer das Trainingsgelände von Laubschattental verlassen, sucht Porthannius nach jemandem, der dem Weg in das restliche Teldrassil folgt. In dringliche Geschäfte mit den Druiden verwickelt, die die Lichtung hüten, kann er sich nicht selbst entfernen, um alltägliche Erledigungen zu machen. Stattdessen legt er ein Bündel frisch geernteter Kräuter in die Hände eines angehenden Helden, um sicherzustellen, dass lebenswichtige Vorräte über den Waldpfad nach Süden gelangen."},{t="Der Weg nach Dolanaar",b="Folgt man der südlichen Straße aus dem abgelegenen Tal hinaus, erreicht man Dolanaar, eine der bedeutendsten Nachtelfensiedlungen auf den gewaltigen Ästen von Teldrassil. Dort sorgt Gastwirt Keldamyr für Gastfreundschaft, Rast und Vorräte für Wanderer, Schildwachen und Druiden gleichermaßen. Bei der Entgegennahme der Kräuter im Namen von Porthannius nutzt Keldamyr die Gelegenheit, junge Abenteurer dazu anzuhalten, Geist und Seele ruhen zu lassen, bevor sie sich der wachsenden Verderbnis auf dem Weltenbaum stellen."}},faq={{q="Wer ist Porthannius?",a="Porthannius ist ein Nachtelf, der in Laubschattental lebt, der Startlichtung von Teldrassil. Während er eng mit den örtlichen Druiden zusammenarbeitet, bittet er Reisende, die die Lichtung verlassen, in seinem Namen Vorräte nach Süden zu bringen.",al={"porthannius","wer vergibt dolanaar-lieferung","questgeber porthannius"}},{q="Warum kann Porthannius die Kräuter nicht selbst abliefern?",a="Porthannius hat dringliche, unvollendete Angelegenheiten mit den Druiden von Laubschattental. Da seine Pflichten ihn in dem geschützten Tal binden, muss er sich auf vorbeikommende Abenteurer verlassen, um die Reise nach Süden anzutreten.",al={"warum braucht porthannius hilfe","warum kann porthannius nicht gehen"}},{q="Was befindet sich in dem Paket?",a="Das Paket enthält eine Sammlung von Kräutern, die in Laubschattental gesammelt wurden und für den Gebrauch im Gasthaus in Dolanaar bestimmt sind.",al={"dolanaar-lieferung paketinhalt","was sind die kräuter"}},{q="Wer ist Gastwirt Keldamyr?",a="Gastwirt Keldamyr leitet das Gasthaus in Dolanaar. Neben der Bereitstellung von Gastfreundschaft, Unterkünften und Ruhesteinen für Reisende koordiniert er regelmäßig den Handel und den Austausch von Vorräten mit anderen Siedlungen in Teldrassil.",al={"keldamyr","dolanaar gastwirt","wer erhält die kräuter"}},{q="Wo liegt Dolanaar?",a="Dolanaar liegt südlich von Laubschattental. Folgt man der Hauptstraße, die aus dem Ausgang der Lichtung herausführt, gelangt man direkt ins Zentrum des Ortes.",al={"wo liegt dolanaar","dolanaar standort","wegbeschreibung nach dolanaar"}},{q="Warum ist diese Lieferung wichtig für junge Abenteurer?",a="Sie dient als Einführung in die Welt jenseits von Laubschattental und ermutigt Novizen, ihr Trainingsgelände hinter sich zu lassen und Dolanaars Gasthaus, Lehrer sowie Dienstleister zu entdecken.",al={"bedeutung der lieferung","warum kräuter liefern"}}},fx={e1815add={q="Warum muss Porthannius dieses Paket nach Dolanaar liefern lassen?",a="Porthannius hat ein lebenswichtiges Bündel frischer Kräuter vorbereitet, die im Laubschattental gesammelt wurden und auf die Gastwirt Keldamyr unten in Dolanaar wartet. Dringende Pflichten halten Porthannius jedoch mit den örtlichen Druiden beschäftigt, was ihn daran hindert, die Reise selbst zu machen. Um sicherzustellen, dass der Gastwirt diese notwendigen Vorräte ohne Verzögerung erhält, verlässt er sich auf einen vorbeiziehenden Reisenden, der sich nach Teldrassil begibt.",al={"porthannius lieferbeweggrund","warum kräuter nach dolanaar schicken","zweck der lieferung für dolanaar"}}},fp="17,359,26.414.0,20.466.0,19.211.0,48.201.0,27.111.0,26.216.0,26.140.0,53.187.0"}
P.entries["quest:2160"] = {n="Vorräte für Tannok",s="Vorräte für Tannok ist eine Besorgung, die angehenden Abenteurern anvertraut wird, welche das Coldridgetal durch den gefährlichen Bergpass ins weitere Dun Morogh verlassen. Der Gnomen-Tüftler Hands Federspross schickt eine Kiste mit benötigtem Proviant zu Tannok Frosthammer im Gasthaus der Brauerei Donnerbräu in Kharanos, um die von Troggs heimgesuchten Pfade zu umgehen, die den regelmäßigen Handel unterbrochen haben.",h="Vorräte für Tannok ist eine Besorgung, die angehenden Abenteurern anvertraut wird, welche das Coldridgetal...",kw={"ambossar","coldridgepass","hands federspross","kharanos","vorräte für tannok","tannok frosthammer","donnerbräu","troggs"},ang={["faction:Alliance"]="Die Wiederherstellung des Handels zwischen abgelegenen Außenposten hält Eisenschmiedes inländische Nachschublinien trotz wilder Trogg-Überfälle aufrecht.",["race:Dwarf"]="Das Transportieren von Vorräten von Ambossar nach Kharanos markiert Euren Übergangsritus aus dem geschützten Tal hinaus in den Dienst für das gesamte Königreich von Eisenschmiede.",["race:Gnome"]="Hands Federspross zu helfen beweist die verlässliche Zusammenarbeit zwischen den Gnomeregangnomen und ihren zwergischen Gastgebern in Dun Morogh."},sec={{t="Ein blockiertes Tal",b="Das Coldridgetal ist traditionell das Übungsgelände und die Zuflucht für junge Zwerge aus Eisenschmiede und verbannte Überlebende aus Gnomeregan, doch die jüngsten Ereignisse haben seine Verbindung zum Rest von Dun Morogh schwer belastet. Überfälle der Troggs haben die Eisklamm überrannt, sodass der Engpass im Gebirge nur noch unter Lebensgefahr durchquert werden kann. Die Bergsteiger sind durch die Bewachung von Siedlungen und Verteidigungslinien völlig überlastet, was geplante Versorgungseskorten tagelang verzögert."},{t="Hands und der Gehilfe des Gastwirts",b="Hands Federspross, ein in Ambossar verweilender Gnom, fand sich im Besitz einer Kiste lebenswichtiger Gasthausvorräte für Kharanos wieder, ohne die Möglichkeit zu haben, sie gefahrlos selbst zu überbringen. Da er bemerkt, dass sich bereits beherzte Abenteurer darauf vorbereiten, den tückischen Pass zu durchqueren, bittet er aufbrechende Reisende darum, die Fracht zu Tannok Frosthammer zu bringen, dem Gehilfen im geschäftigen Gasthaus Donnerbräu."},{t="Eine einladende Feuerstelle in Kharanos",b="Das Erreichen von Kharanos markiert den Eintritt eines Abenteurers in die weitere Welt von Dun Morogh. Tannok Frosthammer nimmt die Lieferung eifrig entgegen und bemerkt, dass Nachrichten aus Ambossar selten geworden sind, seit die Troggs das Reisen durch den Pass behindern. Die Zustellung der Waren stellt eine zerbrechliche Verbindung des Handels und der Kommunikation zwischen den beiden isolierten Zwergengemeinschaften wieder her."}},faq={{q="Wer ist Hands Federspross?",a="Hands Federspross ist ein geschäftiger Gnom, der in Ambossar im Coldridgetal stationiert ist. Da er den gefährlichen Bergpass nicht allein überqueren kann, verlässt er sich auf fähige Reisende, um Waren nach Kharanos zu transportieren.",al={"hands federspross","questgeber","wer gibt vorräte für tannok"}},{q="Wer ist Tannok Frosthammer?",a="Tannok Frosthammer ist der Gehilfe des Gastwirts in der Brauerei Donnerbräu in Kharanos. Er hilft bei der Organisation der örtlichen Taverne und nimmt eintreffenden Proviant aus Außenposten wie Ambossar entgegen.",al={"tannok","tannok frosthammer","kharanos gastwirt gehilfe"}},{q="Warum kann Hands die Vorräte nicht selbst liefern?",a="Der Pass, der das Coldridgetal mit Kharanos verbindet, wurde von feindseligen Troggs überrannt. Hands ist nicht dafür ausgerüstet, sich allein einen Weg freizukämpfen, und offizielle Eskorten der Bergsteiger verspäten sich massiv.",al={"warum kann hands nicht selbst liefern","warum abenteurer gebraucht","warum ist der pass gefährlich"}},{q="Wo befindet sich das Gasthaus in Kharanos?",a="Tannok Frosthammer befindet sich in der Brauerei Donnerbräu, dem großen Gasthaus mitten im Zentrum von Kharanos an der Hauptstraße, die ostwärts nach Eisenschmiede führt.",al={"wo ist tannok","brauerei donnerbräu standort","kharanos gasthaus standort"}},{q="Was befindet sich in der Kiste mit Gasthausvorräten?",a="Die Kiste enthält unverzichtbaren Tavernenbedarf und Vorräte, die in Ambossar gesammelt wurden, um die Bestände des Gasthauses Donnerbräu in Kharanos aufzufüllen.",al={"was ist in der kiste","kiste mit gasthausvorräten"}},{q="Warum ist die Verbindung zwischen Ambossar und Kharanos unterbrochen?",a="Troggs, die aus unterirdischen Tunneln strömen, haben die Eisklamm überschwemmt. Ihre aggressive Präsenz hat den einfachen Reiseverkehr zu Fuß und regelmäßige Meldungen zwischen dem Coldridgetal und dem Rest von Dun Morogh lahmgelegt.",al={"warum kaum nachrichten aus ambossar","trogg problem pass"}}},fx={["6d15a4f4"]={q="Warum möchte Hands Federspross, dass die Vorräte nach Kharanos geliefert werden?",a="Hands Federspross versprach Tannok Frosthammer, dem Assistenten im Gasthaus von Kharanos, lebenswichtige Versorgungsgüter, aber Trogangriffe haben den Reiseverkehr durch den Pass aus dem Coldridgetal zum Erliegen gebracht. Da reguläre Lieferungen festsitzen und Bergsteiger-Eskorten Tage entfernt sind, bleibt Tannok wartend und besorgt mit schwindenden Vorräten zurück. Hands möchte seine Lieferung einhalten und sicherstellen, dass die geschäftige Brauerei Donnerbräu und das Gasthaus für straßenmüde Reisende bestückt bleiben.",al={"warum vorräte an tannok senden","hands federspross beweggrund","warum kiste mit gasthausvorräten liefern"}}},fp="18,367,18.421.0,35.383.0,30.353.0,28.205.0,26.196.0,45.192.0,37.174.0,41.140.0,59.201.0"}
P.entries["quest:2161"] = {n="Die Bürde eines Peons",s="Die Bürde eines Peons ist ein einführender Lieferauftrag von Ukor, einem ängstlichen Orc-Arbeiter, der am Pfad außerhalb des Tals der Prüfungen gestrandet ist. Nachdem er versucht hatte, Vorräte an neue Rekruten zu liefern, die diese gar nicht benötigten, vertraut Ukor Reisenden die schwere Last an, damit sie diese sicher nach Klingenhügel zurückbringen.",h="Die Bürde eines Peons ist ein einführender Lieferauftrag von Ukor, einem ängstlichen Orc-Arbeiter, der am...",kw={"durotar","essen","gastwirt grosk","peon","klingenhügel","vorräte","ukor","das tal der prüfungen"},ang={["faction:Horde"]="Diese Wanderung dient als Übergang aus dem Übungsgelände und führt Reisende nach Klingenhügel, dem zentralen Knotenpunkt für die Verteidigung und Logistik der Horde im südlichen Durotar.",["race:Orc"]="Die Kultur der Orcs schätzt körperliche Macht und Mut, wodurch Peons wie Ukor ganz unten in der sozialen Hierarchie stehen; die Übernahme seines Botengangs zeigt, wie selbst bescheidene Arbeit die junge Nation von Durotar am Laufen hält."},sec={{t="Eine verfehlte Lieferung",b="Ukor ist ein aufrichtiger Peon, der mit guten Absichten von Klingenhügel aus aufbrach und ein schweres Paket mit Vorräten in Richtung des Tals der Prüfungen schleppte. Im Glauben, die im roten Canyon trainierenden neuen Rekruten bräuchten dringend Rationen, trotzte er der Straße, nur um abgewiesen zu werden. Die Zuchtmeister, welche die Prüfungen beaufsichtigen, halten die Vorräte bewusst knapp – wie Gastwirt Grosk später anmerkt, gilt das Überleben mit magerer Kost als ein Weg, um Disziplin und Ausdauer bei jungen Kriegern der Horde zu schmieden."},{t="Gefahren der roten Einöde",b="Obwohl er es bis zum Pass geschafft hat, fürchtet sich Ukor davor, seine Schritte über den sonnenverbrannten Boden von Durotar zurückzugehen. Die Felsen entlang des Pfades wimmeln von aggressiven Skorpiden, giftigen Spinnen und umherstreifenden Ebern. Da ihm Waffen, Rüstung und der von Orc-Grunzern erwartete Kampfgeist fehlen, wartet der verängstigte Arbeiter am Wegesrand und fleht jeden vorbeikommenden Abenteurer an, der das Übungsgelände verlässt, seine Bürde zu schultern und sie zum Gasthaus zurückzubringen."}},faq={{q="Wer ist Ukor?",a="Ukor ist ein Orc-Peon, der an der Straße steht, die aus dem Tal der Prüfungen herausführt. Er meint es gut, ist jedoch ängstlich und wagte sich hinaus, um Vorräte aus Klingenhügel zu liefern, bevor er merkte, dass er zu viel Angst vor den heimischen Wildtieren hatte, um den Rückweg allein anzutreten.",al={"ukor","wer ist der peon an der straße","peon nahe tal der prüfungen"}},{q="Warum wollten die Ausbilder im Tal der Prüfungen das Essen nicht?",a="Die Aufseher im Tal der Prüfungen glauben an rigorose Disziplin für angehende Rekruten. Wie Gastwirt Grosk humorvoll bemerkt, ziehen es die Ausbilder vor, die Auszubildenden hungrig zu halten, um ihren Mut zu testen und ihren Geist zu stärken, weshalb Ukors wohltätige Lieferung unerwünscht war.",al={"warum essen ablehnen","warum trug ukor essen","gastwirt grosk aushungern"}},{q="Wohin muss diese Lieferung gebracht werden?",a="Die Bürde muss nach Norden entlang der Hauptverkehrsstraße von Durotar nach Klingenhügel getragen werden, wo sie Gastwirt Grosk in der Taverne der Siedlung übergeben wird.",al={"wo ist klingenhügel","wem gebe ich das essen","wohin ukors bürde liefern"}},{q="Was macht die Reise für einen Peon so gefährlich?",a="Durotars felsige Ödnisse sind voll von territorialen Skorpiden, giftigen Kriecher-Spinnen und wilden Ebern. Während erfahrene Rekruten mit solchem Ungeziefer fertigwerden, hat ein ungerüsteter und untrainierter Arbeiter wie Ukor kaum eine Chance, wenn er angegriffen wird.",al={"warum hat ukor angst","durotar straßengefahren"}},{q="Welche Rolle spielen Peons in der Horde?",a="Peons stehen auf der untersten Stufe der Orc-Gesellschaft und verrichten einfache Arbeiten wie das Schleppen von Vorräten, das Holzfällen und das Errichten von Befestigungen. Während Grunzer und Champions Lob und Ruhm ernten, werden Peons oft übersehen, obwohl sie dafür sorgen, dass Siedlungen ernährt und instand gehalten werden.",al={"orc peons lore","peon status","was sind peons"}},{q="Wer ist Gastwirt Grosk?",a="Gastwirt Grosk leitet das Gasthaus in Klingenhügel. Er verwaltet die Unterkünfte und Vorräte des Ortes, bietet reisenden Kriegern Speis, Trank sowie eine Herberge und erinnert Rekruten daran, dass Rast lebenswichtig ist, bevor man die weite Welt erkundet.",al={"gastwirt grosk","grosk klingenhügel","klingenhügel gastwirt"}}},fx={["777a74e1"]={q="Warum möchte Ukor, dass das Essen zurück nach Klingenhügel geliefert wird?",a="Ukor meinte es aufrichtig gut, als er Vorräte aus Klingenhügel heranschaffte, in der Hoffnung, den jungen Rekruten zu helfen, die unter der harten Sonne des Tals der Prüfungen trainieren. Da er feststellen musste, dass die Ausbilder die Rationen ablehnten, kann er die Vorräte nicht einfach zurücklassen oder auf der Straße verderben lassen. Das Essen gehört zurück in die Regale der Speisekammer von Gastwirt Grosk, aber nachdem er den Treck vorbei an den Skorpionen und Spinnen der Region kaum überlebt hat, hat Ukor schreckliche Angst davor, den gefährlichen Rückweg allein anzutreten.",al={"warum das essen zurückbringen","ukor beweggrund","warum essen an grosk geben"}},["044c44d7"]={q="Warum bittet Ukor Euch, die Last zu tragen, anstatt es selbst zu tun?",a="Ukor ist ein gewöhnlicher Peon, der an Gewalt nicht gewöhnt und unbewaffnet gegenüber der Wildnis ist. Während er es schaffte, den Skorpionen und Spinnen auf der Straße von Klingenhügel aus zu trotzen, hat ihn das reine Entsetzen, diesen wilden Raubtieren erneut gegenüberzustehen, erstarren lassen. Als er Euch siegreich aus dem Tal der Prüfungen kommen sah, erblickte er einen fähigen Helden, der nichts fürchtet, und hofft, dass Ihr die Last gerne auf Eurem Weg zum Wegekreuz tragen werdet.",al={"warum kann ukor es nicht tragen","warum ich peons bürde","warum mich ukor fragen"}}},fp="15,305,20.477.0,23.460.0,12.254.0,62.278.0,36.156.0,44.229.0,39.269.0,23.222.0"}
P.entries["quest:217"] = {n="Verteidigung der Länder des Königs",s="Verteidigung der Länder des Königs gipfelt in einem direkten Schlag gegen die Führung des Trogg-Einfalls in Loch Modan. Zwergenspäher führen die gewaltsame Plage auf Häuptling Grawmug und seine grobschlächtigen Leibwächter tief im Splittersteintal zurück. Hauptmann Rugelfuß beauftragt kühne Abenteurer der Allianz damit, den Häuptling zu töten, um die Moral der Troggs zu brechen und die südlichen Grenzen des Reiches zurückzuerobern.",h="Verteidigung der Länder des Königs gipfelt in einem direkten Schlag gegen die Führung des Trogg-Einfalls in...",kw={"brawler","gnasher","grawmug","länder des königs","loch modan","rugelfuss","splitterstein","trogg"},ang={["faction:Alliance"]="Die Verteidigung von Loch Modan sichert die lebenswichtige Überlandverbindung zwischen Eisenschmiede und den östlichen Grenzgebieten und hält die Nachschublinien für alle Streitkräfte der Allianz offen.",["race:Dwarf"]="Für Zwerge ist die Vertreibung der Troggs von Khaz Modans uraltem Boden eine Frage der Heimatverteidigung und der Ehre, damit die Bergfestungen von den unterirdischen Plagen unberührt bleiben."},sec={{t="Enthauptung des Schwarmes",b="Die anhaltende Troggbedrohung im Süden von Loch Modan hat sich als mehr als nur ein zufälliges Untergrundkriechen erwiesen. Die Späher von Hauptmann Rugelfuß fanden heraus, dass die Splittersteintroggs unter der primitiven Führung eines Häuptlings namens Grawmug agieren. Anders als gewöhnliche, verstreute Marodeure bewegt sich dieses Rudel mit gezielter Aggression und droht, die Länder des Königs zu überrennen, wenn es nicht aufgehalten wird. Indem sie den Kampf in ihre Höhle tragen und Grawmug zusammen mit seinen persönlichen Schlägern hinrichten, hoffen die Zwergenverteidiger, den Zusammenhalt des Rudels zu brechen und die Flut einzudämmen."},{t="In die Splittersteinhöhle",b="Grawmug verschanzt sich in einer schattigen Höhle in den südöstlichen Klippen des Splittersteintals. Umgeben von seinen treuesten Raufbolden, Gnasher und Brawler, stellt der Häuptling für einsame Soldaten eine gefährliche Herausforderung dar. Das Niederschlagen dieses inneren Zirkels stürzt die verbliebenen Troggs ins Chaos und verschafft den bedrängten Gebirgsjägern die dringend benötigte Gelegenheit, die Straßen zu befestigen und die Bestien zurück in die dunklen Tiefen zu treiben."}},faq={{q="Wer ist Grawmug?",a="Grawmug ist der bösartige Trogghäuptling, der die Splittersteintroggs im Süden von Loch Modan um sich schart. Zwergenspäher machten ihn als den Drahtzieher hinter den organisierten Angriffen aus, die das Tal heimsuchen, stets begleitet von zwei gewaltigen Leibwächtern, Gnasher und Brawler.",al={"grawmug lore","wer ist der trogganführer","häuptling grawmug"}},{q="Wo befinden sich Grawmug und seine Wachen?",a="Grawmug, Gnasher und Brawler haben sich in einer Höhle am südöstlichen Rand des Splittersteintals in Loch Modan verschanzt. Sie hausen gemeinsam tief in den Winkeln der Höhle.",al={"grawmug aufenthaltsort","wo ist grawmug","wo man grawmug findet"}},{q="Wer ist Hauptmann Rugelfuß?",a="Hauptmann Rugelfuß ist der zwergische Offizier, der am südlichen Wachturm in Loch Modan stationiert ist. Er beaufsichtigt die Verteidigungskampagnen gegen die vorrückenden Trogg-Einfälle und erteilt Befehle zum Schutz der territorialen Unversehrtheit der Länder des Königs.",al={"rugelfuss","rolle von hauptmann rugelfuß","wer gibt verteidigung der länder des königs"}},{q="Warum müssen auch Grawmugs Wachen getötet werden?",a="Gnasher und Brawler sind Grawmugs persönliche Schläger, die niemals von seiner Seite weichen. Um den Häuptling auszuschalten und die Führung der Trogg-Offensive endgültig zu zerschlagen, müssen beide schweren Beschützer an der Seite ihres Anführers besiegt werden.",al={"warum gnasher und brawler töten","gnasher und brawler","grawmug leibwächter"}},{q="Was geschieht, nachdem Grawmug eliminiert wurde?",a="Die Tötung von Grawmug bringt Loch Modan entscheidende Erleichterung. Ohne ihren Häuptling, der ihre Überfälle koordiniert, verlieren die Splittersteintroggs jegliche Organisation, was der örtlichen Zwergenmiliz eine echte Chance gibt, die Grenzen zu halten und die Bestien wieder unter die Erde zu drängen.",al={"folge der tötung von grawmug","troggs nach grawmugs tod","haben wir loch modan gerettet"}},{q="Warum fallen Troggs in Loch Modan ein?",a="Troggs hausen schon lange tief in unterirdischen Kammern unter Khaz Modan. Ausgrabungen und unversiegelte Höhlen haben es ihnen ermöglicht, an die Oberfläche zu dringen, wo sie aggressiv Siedlungen verdrängen und Reisende auf den Königsstraßen überfallen.",al={"warum sind troggs hier","trogg invasion loch modan","ursprung der splittersteintroggs"}}},fx={["440a3b53"]={q="Warum möchte Hauptmann Rugelfuß, dass Grawmug getötet wird?",a="Hauptmann Rugelfuß sieht in Grawmug den Drahtzieher, der die Trogg-Einfälle vorantreibt, die Loch Modan bedrohen. Die Zwergengarnisonen kämpfen damit, die unterirdischen Schwärme zurückzuhalten, und Rugelfuß glaubt, dass die Enthauptung ihrer Führung – insbesondere die Eliminierung von Grawmug zusammen mit seinen Elite-Leibwächtern – ihren Schwung brechen und den Zwergen eine echte Chance geben wird, sie zurück unter die Erde zu treiben.",al={"rugelfuß beweggrund","warum grawmug töten","zweck von in defense of the kings lands"}}},fp="30,391,22.553.0,23.450.0,15.278.0,41.171.0,25.246.0,43.231.0,41.266.1,35.241.0"}
P.entries["quest:2178"] = {n="Schreitereintopf",s="Schreitereintopf ist eine lokale kulinarische Aufgabe, die von Alanndarian Nachtweise in Auberdine angeboten wird. Sie brennt darauf, ihr geschätztes Rezept für Schreitereintopf zu teilen – vorausgesetzt, ein Abenteurer ist bereit, die wilden Foreststriders zu jagen, die die Dunkelküste durchstreifen, und ihr Fleisch zu beschaffen.",h="Schreitereintopf ist eine lokale kulinarische Aufgabe, die von Alanndarian Nachtweise in Auberdine angeboten...",kw={"alanndarian nachtweise","auberdine","kochen","dunkelküste","schreitereintopf","foreststrider","schreiterfleisch"},ang={["class:Hunter"]="Foreststriders sind zugleich flinkes Wild und potenzielle tierische Begleiter; sie bieten auf den nebelverhangenen Pfaden der Dunkelküste eine gute Gelegenheit, das Spurenlesen und Jagen zu üben.",["profession:Cooking"]="Diese Aufgabe ist für reisende Köche an der Dunkelküste unverzichtbar, da sie das Rezept belohnt, um nahrhaften Schreitereintopf aus der einheimischen Fauna zuzubereiten.",["race:NightElf"]="In Kalimdor in Harmonie zu leben bedeutet oft, vom Land zu leben, und herzhafte Schreitereintöpfe sind für die Nachtelfen in Auberdine zu einem festen Bestandteil an der Küste geworden."},sec={{t="Ein Geschmack der Wildnis",b="Auberdine mag ein ruhiges Hafendorf sein, doch das Überleben an der Küste erfordert eine gute Nutzung der einheimischen Tierwelt. Alanndarian Nachtweise hat ein Geheimrezept für herzhaften Schreitereintopf entwickelt, ein schmackhaftes Gericht aus den großen, leichtfüßigen Foreststriders, die durch die schattenhaften Wälder der Dunkelküste pirschen. Anstatt ihre kulinarischen Geheimnisse einfach so preiszugeben, bittet sie angehende Köche und Jäger, hinauszuziehen und die Vögel selbst zu erlegen."},{t="Die Jagd auf die Foreststriders",b="Foreststriders sind flinke, scharfgeschnäbelte gefiederte Raubtiere, die die nebelverhangenen Wälder und Strände nördlich und südlich von Auberdine durchstreifen. Zwar können sie launisch und aggressiv werden, wenn sie provoziert werden, doch ihr saftiges Fleisch bietet eine hervorragende Grundlage für einen gehaltvollen Eintopf. Frisches Fleisch zurückzubringen, füllt Alanndarians hungrigen Topf und bringt dem Jäger ihr hochgeschätztes Rezept ein."}},faq={{q="Wer ist Alanndarian Nachtweise?",a="Alanndarian Nachtweise ist eine Nachtelfe, die in Auberdine an der Dunkelküste lebt. Sie ist bekannt für ihren brodelnden Topf mit Schreitereintopf und bietet an, Reisenden, die ihr jagdliches Geschick unter Beweis stellen, ihre Kochkunst beizubringen.",al={"alanndarian","wer ist alanndarian nachtweise","eintopf koch auberdine"}},{q="Wo finde ich das Schreiterfleisch?",a="Schreiterfleisch erhält man durch die Jagd auf Foreststriders überall an der Dunkelküste. Diese großen, flugunfähigen Vögel streifen sowohl an den Sandstränden als auch durch die bewaldeten Haine außerhalb von Auberdine.",al={"schreiterfleisch fundort","wo sind foreststriders","wie man schreiterfleisch bekommt"}},{q="Was ist der Zweck dieser Quest?",a="Die Quest beauftragt Euch damit, Foreststriders zu jagen, um Alanndarian Nachtweise fünf Fleischstücke zu bringen – im Gegenzug dafür, dass sie Euch beibringt, wie man Schreitereintopf zubereitet.",al={"warum schreitereintopf machen","questzweck","schreitereintopf questziel"}},{q="Sind die Foreststriders gefährlich zu jagen?",a="Foreststriders sind revierbezogene Vögel, die mit scharfen Schnäbeln und flinken Beinen ausgestattet sind, was sie aggressiv macht, wenn man sich ihnen nähert. Ein vernünftig ausgerüsteter Abenteurer kann sie jedoch ohne große Gefahr zur Strecke bringen.",al={"sind schreiter schwer zu töten","foreststrider gefahr"}},{q="Schaltet diese Quest ein Kochrezept frei?",a="Ja. Sobald Ihr Alanndarian das verlangte Fleisch bringt, teilt sie ihre Kochgeheimnisse und lehrt Abenteurer das Rezept für Schreitereintopf.",al={"bekomme ich ein rezept","schreitereintopf rezept","kochbelohnung"}},{q="Wo findet diese Quest statt?",a="Die Quest beginnt und endet in der Siedlung Auberdine, während die Jagd in der Wildnis der Dunkelküste stattfindet.",al={"questzone","wo ist schreitereintopf"}}},fx={["624f04e5"]={q="Wofür wird Schreiterfleisch verwendet?",a="Das saftige Fleisch ist die Hauptzutat für Alanndarians schmackhaften Schreitereintopf. Wenn Ihr ihr fünf Stücke bringt, füllt das ihren leeren Kessel und beweist ihr, dass Ihr Euch das Recht verdient habt, ihr geheimes Wildnisrezept zu erlernen.",al={"was ist schreiterfleisch für","warum schreiterfleisch","nutzen schreiterfleisch"}},["64984ff6"]={q="Warum möchte Alanndarian Nachtweise, dass dies getan wird?",a="Alanndarian Nachtweise hat einen leeren Kochtopf und Appetit auf frischen Schreitereintopf. Bevor sie bereit ist, sich von ihrem Geheimrezept zu trennen, besteht sie darauf zu sehen, ob Ihr das Zeug dazu habt, die Stelzvögel selbst zu jagen und frische Stücke für ihr Kochfeuer zurückzubringen.",al={"alanndarian beweggrund","warum will alanndarian schreiterfleisch","warum schreitereintopf"}}},fp="19,267,19.430.0,26.361.0,29.202.0,33.176.0,34.165.0,41.196.0,40.133.0,33.119.0"}
P.entries["quest:218"] = {n="Das gestohlene Tagebuch",s="Das gestohlene Tagebuch ist eine frühe Allianz-Quest in Dun Morogh, bei der Grelin Weißbart Abenteurer damit beauftragt, die Trollhöhle im Coldridgetal zu betreten, um sein gestohlenes Notizbuch zurückzuholen. Um es wiederzuerlangen, müsst Ihr den gewaltigen Trollanführer Grik'nir the Cold besiegen. Die Rückbeschaffung des Tagebuchs ermöglicht es Grelin, seine Einschätzung der Trollbedrohung im Coldridgetal abzuschließen.",h="Das gestohlene Tagebuch ist eine frühe Allianz-Quest in Dun Morogh, bei der Grelin Weißbart Abenteurer damit...",kw={"das coldridgetal","dun morogh","höhle der frostmähnen","frostmane-troll","grelin weißbart","grik'nir the cold","senir weißbart","das gestohlene tagebuch"},ang={["faction:Alliance"]="Die Unterdrückung des aggressiven Frostmane-Stammes stellt sicher, dass die Anfangstäler von Dun Morogh vor inneren Störungen geschützt bleiben.",["race:Dwarf"]="Die Beseitigung der Frostmane-Führung im Coldridgetal schützt junge Zwergenrekruten, die ihre ersten Schritte außerhalb von Ambossar wagen.",["race:Gnome"]="Gnomische Flüchtlinge, die in Ambossar Zuflucht suchen, verlassen sich auf die Sicherheit der Pässe des Coldridgetals, während sie sich auf zwergischem Territorium neu formieren."},sec={{t="Die verlorenen Notizen eines Gelehrten",b="Grelin Weißbart hat die Frostmane-Trolle beobachtet, die in das Coldridgetal vordringen, und detaillierte Notizen über ihre Bräuche und ihre plötzliche Aggression geführt. Während der Unruhen machte sich ein ungewöhnlich imposanter Troll mit seinem persönlichen Tagebuch davon und zog sich in die Tiefen ihrer Höhle zurück. Für Grelin ist der Verlust keineswegs nur sentimental; das Notizbuch enthält den Großteil seiner Aufklärung, sodass sein offizieller Bericht stockt, bis es aus der Höhle geborgen wird."},{t="Gegenüberstellung mit Grik'nir the Cold",b="Der Unhold, der für den Raub des Tagebuchs verantwortlich ist, ist Grik'nir the Cold, ein mächtiger Frostmane-Troll mit auffälligen Körper- und Gesichtsbemalungen, der im Herzen der Trollhöhle des Tals Hof hält. Das Töten von Grik'nir bricht die unmittelbare lokale Führung der Trolle in der Höhle und sichert Grelins Tagebuch. Nachdem der Anführer ausgeschaltet ist, fühlt sich Grelin zuversichtlich genug, zu berichten, dass die Trollsituation im Tal unter Kontrolle ist, und sendet seine fertigen Ergebnisse an seinen Bruder Senir weiter."}},faq={{q="Wer hat Grelin Weißbarts Tagebuch gestohlen?",a="Das Tagebuch wurde von Grik'nir the Cold entwendet, einem großen Frostmane-Troll mit seltsamen Zeichnungen auf Haut und Gesicht, der tief in der Trollhöhle lauert.",al={"wer hat das tagebuch gestohlen","wer hat grelins tagebuch","tagebuchdieb"}},{q="Wo ist Grik'nir the Cold zu finden?",a="Grik'nir the Cold befindet sich in der Trollhöhle in den südlichen Gefilden des Coldridgetals.",al={"wo ist griknir","grik'nir aufenthaltsort","wie man grik'nir findet"}},{q="Warum ist das Tagebuch für Grelin von Bedeutung?",a="Das Tagebuch enthält Grelin Weißbarts Notizen und Erkenntnisse über die Trollaktivitäten im Coldridgetal. Er benötigt es zurück, um einen vollständigen Bericht für seinen Bruder Senir zusammenzustellen.",al={"warum will grelin sein tagebuch","was steht in grelins tagebuch"}},{q="Was geschieht, nachdem Ihr das Tagebuch zurückgebracht habt?",a="Sobald das Tagebuch wiederbeschafft ist, stellt Grelin seinen Bericht zur Lage der Trolle im Coldridgetal fertig und bittet Euch, seine Beobachtungen als Bote zu seinem Bruder Senir Weißbart nach Kharanos zu bringen.",al={"wie geht es nach das gestohlene tagebuch weiter","folgequest das gestohlene tagebuch"}},{q="Sind die Frostmane-Trolle danach aus dem Coldridgetal vertrieben?",a="Grelin glaubt, dass die Trollsituation im Coldridgetal nach Grik'nirs Niederlage unter Kontrolle ist, wenngleich die Frostmane eine dauerhafte Bedrohung in den weiteren Gebirgspässen von Dun Morogh bleiben.",al={"sind die trolle im coldridgetal besiegt","ist das coldridgetal sicher vor trollen"}},{q="Wer ist Senir Weißbart?",a="Senir Weißbart ist Grelins Bruder, ein Späher der Allianz, der außerhalb des Coldridgetals nahe Kharanos stationiert ist und Informationen über Bedrohungen für das Königreich sammelt.",al={"wer ist senir","grelins bruder senir"}}},fx={["78f0c4e3"]={q="Warum will Grelin Weißbart, dass dies erledigt wird?",a="Grelin stellt für seinen Bruder Senir einen offiziellen Bericht über die Bedrohung durch die Frostmähne im Das Coldridgetal zusammen. Ohne sein Tagebuch kann er seine Notizen nicht vervollständigen oder die Sicherheit des Tals beurteilen, was die örtlichen Anführer ohne wichtige Informationen über die Trollaktivitäten zurücklässt.",al={"warum will grelin sein tagebuch","grelin weißbart motiv","warum grelins tagebuch bergen"}},beb6a987={q="Warum muss Grelin, dass Ihr sein Tagebuch wiederbeschafft?",a="Grelin ist eher Beobachter als Frontkämpfer und das Tagebuch wurde von einem furchterregenden Trollbrut tief in die Trollhöhle im Das Coldridgetal verschleppt. Da er bereits Euren Erfolg im Kampf gegen die Trolle im Tal miterlebt hat, bittet er Euch, in die Höhle einzudringen und die Gefahr zu beseitigen.",al={"warum braucht grelin mich","warum einen abenteurer für das tagebuch schicken","warum kann grelin sein tagebuch nicht selbst holen"}}},fp="18,368,22.459.0,29.474.0,37.160.0,37.95.0,39.176.0,42.193.1,67.198.0,24.160.0"}
P.entries["quest:219"] = {n="Vermisst",s="Vermisst ist eine Geleitmission der Allianz im Rotkammgebirge, um Corporal Keeshan aus der Gefangenschaft der Schwarzfelsorks zu befreien. Nachdem sein Regiment in den Hügeln aufgerieben worden war, wurde Keeshan bewusstlos geschlagen und in eine Höhlenfestung geschleift. Den verwundeten Soldaten sicher nach Seenhain zurückzuleiten hilft der örtlichen Garnison, das finstere Schicksal ihrer vermissten Männer zu bestätigen.",h="Vermisst ist eine Geleitmission der Allianz im Rotkammgebirge, um Corporal Keeshan aus der Gefangenschaft der...",kw={"schwarzfelsorks","corporal keeshan","eskorte","keeshan","seenhain","marschall marris","vermisst","rotkammgebirge"},ang={["class:Warrior"]="Keeshan aus einem befestigten Orklager zu befreien erfordert es, die Frontlinie gegen Wellen unerbittlicher Schwarzfels-Angreifer zu halten, während man einen Gefährten mit Gehirnerschütterung beschützt.",["faction:Alliance"]="Die Garnison von Seenhain steht kurz vor dem Zusammenbruch, was jeden geretteten Soldaten für die Verteidigung des Königreichs gegen den Schwarzfelsclan unverzichtbar macht."},sec={{t="Ein überranntes Regiment",b="Das Rotkammgebirge ist immer gefährlicher geworden, während Schwarzfelsorks von den nördlichen Gipfeln herabsteigen. Von der Stadtwache ausgesandte Patrouillen geraten häufig in Hinterhalte, und Corporal Keeshans Einheit traf es am schlimmsten. In der Unterzahl und überwältigt wurden die meisten Soldaten seines Regiments an Ort und Stelle niedergemacht. Keeshan überlebte nur, weil ihn ein vernichtender Schlag bewusstlos streckte, ehe er hingerichtet werden konnte, sodass die Orks ihn als Gefangenen in ihre Höhle verschleppen konnten."},{t="Flucht aus den Höhlen",b="Zerschlagen, mit einer Gehirnerschütterung und tief im feindlichen Gebiet festgehalten, konnte Keeshan den mühsamen Weg den Berg hinab nicht allein bewältigen. Ihn hinab in die Sicherheit von Seenhain zu eskortieren führt an schwärmenden Ork-Kriegstrupps vorbei, die die Bergrücken besetzen. Das Rathaus lebend zu erreichen bringt Marschall Marris dringend benötigte Erleichterung, der versucht hat herauszufinden, was mit dem vermissten Regiment geschehen ist, während er Seenhain gegen weitere Angriffe wappnet."}},faq={{q="Wer ist Corporal Keeshan?",a="Corporal Keeshan ist ein Infanterist der Allianz, der im Rotkammgebirge stationiert ist. Während einer Patrouille in den felsigen Hügeln wurde sein Regiment von Schwarzfelsorks überwältigt, was ihn zum einzigen bekannten Überlebenden machte, ehe er in die Gefangenschaft verschleppt wurde.",al={"corporal keeshan","wer ist keeshan","keeshan lore"}},{q="Wo wurde Corporal Keeshan gefangen genommen?",a="Er wird tief im Inneren einer von Orks wimmelnden Höhle in den nördlichen Hügeln des Rotkammgebirges gefangen gehalten, umringt von feindseligen Schwarzfels-Kriegern.",al={"wo ist keeshan","keeshan aufenthaltsort","keeshan höhle"}},{q="Was geschah mit dem Rest von Keeshans Einheit?",a="Laut Keeshan lauerten die Schwarzfelsorks seinem Regiment auf und überwältigten es, wobei fast alle Männer während des ersten Gefechts getötet wurden.",al={"keeshan trupp","was geschah mit dem regiment","keeshans männer"}},{q="Wer schickt Spieler aus, um Keeshan zu retten?",a="Die Quest beginnt direkt bei Corporal Keeshan selbst in seiner Gefängnishöhle, wenn Abenteurer der Allianz ihn entdecken und befreien.",al={"wer startet vermisst","questgeber","wo nimmt man vermisst an"}},{q="Wohin geht Keeshan nach seiner Befreiung?",a="Er muss den Berghang hinab in die Stadt Seenhain eskortiert werden, wo er sich bei Marschall Marris im Rathaus meldet.",al={"vermisst abgeben","wohin läuft keeshan","keeshans ziel"}},{q="Warum sind die Schwarzfelsorks im Rotkammgebirge?",a="Der Schwarzfelsclan dringt von seinen Festungen in der Brennenden Steppe nach Süden in das Rotkammgebirge vor, bedroht die kaum verstärkte Siedlung Seenhain und überfällt Patrouillen des Königreichs.",al={"schwarzfelsorks rotkammgebirge","warum orks in seenhain","schwarzfels invasion"}}},fx={["64cb6fe2"]={q="Warum benötigt Corporal Keeshan Eure Hilfe bei der Flucht?",a="Corporal Keeshan sitzt tief im feindlichen Gebiet fest, nachdem sein gesamtes Regiment vom Clan der Schwarzfelsorcs überfallen und abgeschlachtet wurde. Nachdem er bei dem Gefecht einen schweren Schlag auf den Kopf erlitten hat, ist er schwer verletzt, orientierungslos und benötigt eine Eskorte. Ohne jemanden, der ihn durch die umgebenden Orcs führt, droht ihm in der Höhle die sichere Hinrichtung oder der Hungertod.",al={"warum keeshan helfen","keeshan motiv","warum braucht keeshan rettung"}},["1d637b84"]={q="Warum kann Keeshan nicht alleine entkommen oder auf die Wache von Seenhain warten?",a="Keeshan ist schwer verletzt und braucht Hilfe, um sich den Weg an den Plünderern der Schwarzfelsorcs vorbeizukämpfen. Währenddessen sind die Verteidiger von Seenhain bereits bis an ihre Grenzen belastet, nur um die Stadt gegen Gnolle und Orcs zu halten, sodass keine Truppen für eine tiefgehende Such- und Rettungsmission übrig sind. Als Ihr über seine Zelle stolpert, seid Ihr buchstäblich seine einzige Hoffnung, lebend zurückzukehren.",al={"warum kann keeshan nicht alleine entkommen","warum braucht mich keeshan","warum keine stadtwachen"}}},fp="17,365,18.474.0,21.424.0,24.243.0,36.128.0,44.138.0,36.131.0,40.123.0,39.181.0"}
P.entries["quest:22"] = {n="Pastete aus Geiferzahnleber",s="Pastete aus Geiferzahnleber ist eine kulinarische Besorgung für Salma Saldean auf dem Saldean Farm in Westfall. Da die Kornkammer des Königreichs von Dürre und Banditen heimgesucht wird, sind die ansässigen Siedler auf die Jagd nach den aggressiven Wildschweinen der Gegend angewiesen, um eine herzhafte Mahlzeit auf den Tisch zu bringen. Salma zu helfen, gewährt einen seltenen Vorgeschmack auf Behaglichkeit und hausgemachte Gastfreundschaft in einem ansonsten trostlosen Grenzland.",h="Pastete aus Geiferzahnleber ist eine kulinarische Besorgung für Salma Saldean auf dem Saldean Farm in...",kw={"eber","kochen","geiferzahn","leberpastete","saldean farm","salma saldean","westfall"},ang={["faction:Alliance"]="Die Hilfe für ländliche Siedler wie die Saldeans unterstützt die treuen Menschenfamilien direkt, die in Abwesenheit von Sturmwinds Armee darum ringen, das Grenzland des Königreichs zu halten.",["profession:Cooking"]="Salmas Gericht veranschaulicht die traditionelle ländliche Küche der Menschen, die Gartenkräuter wie Knoblauch, Rosmarin und Dillkraut verwendet, um Wildinnereien zu einem Grundnahrungsmittel aufzuwerten."},sec={{t="Gastfreundschaft im Grenzland",b="Westfall war einst die fruchtbare Kornkammer von Sturmwind, doch die letzten Jahre brachten schwere Zeiten mit sich. Durch vernachlässigte Infrastruktur, umherziehende Gesetzlose und überwucherte Felder ist der Alltag für die wenigen verbliebenen Siedler zu einer mühsamen Plackerei geworden. Auf dem Saldean Farm arbeitet Salma Saldean unermüdlich daran, trotz der herannahenden Gefahren ein Gefühl von Herd und Heim zu bewahren. Die Zubereitung einer traditionellen Fleischpastete stellt einen der wenigen bescheidenen Luxusgüter dar, die Siedlern zur Verfügung stehen, welche ihre Lebensweise bewahren wollen."},{t="Westfalls wilde Bestien",b="Die Ebenen von Westfall wimmeln von Geiferzähnen, aggressiven Wildschweinen, die für ihre zähe Haut und ihre bösartigen Stoßzähne bekannt sind. Für einsame Knechte sind sie gefährlich, doch für Familien, die vom regelmäßigen Handel abgeschnitten sind, stellen sie auch eine lebenswichtige Fleischquelle dar. Salmas Rezept erfordert eine sorgfältige Zubereitung – zerstoßener Rosmarin, gehackter Knoblauch, fein geschnittener Dill und köchelnde Bratensoße –, um die markanten Innereien dieser widerstandsfähigen Bestien in ein reichhaltiges, herzhaftes Mahl zu verwandeln."}},faq={{q="Wer ist Salma Saldean?",a="Salma Saldean ist eine widerstandsfähige Siedlerin, die mit ihrem Mann, Bauer Saldean, auf ihrem Hof im Herzen von Westfall lebt. Sie ist für ihre Hausmannskost bekannt und tut ihr Bestes, um die Moral trotz der Gefahren durch Banditen und wilde Bestien aufrechtzuerhalten.",al={"salma saldean","wer ist salma","saldeans frau"}},{q="Warum möchte Salma Geiferzahnlebern?",a="Salma bereitet ihre berühmte herzhafte Fleischpastete zu, um sie mit ihrem Mann zu teilen. Die Pastetenkruste ist bereits gebacken und die Gewürze sind vorbereitet; es fehlen nur noch die Lebern der einheimischen Geiferzähne, um die Füllung fertig einzukochen.",al={"warum geiferzahnleber","woraus besteht die pastete","zweck der leberpastete"}},{q="Wo sind Geiferzähne typischerweise in Westfall zu finden?",a="Geiferzähne streifen ausgiebig über die goldenen Ebenen und brachliegende Ackerflächen in ganz Westfall, wühlen auf verlassenen Feldern und wandern an den Feldwegen entlang.",al={"aufenthaltsorte von geiferzähnen","wo schweine finden","geiferzahnleber jagd"}},{q="Sind Geiferzähne für die Bauern der Gegend gefährlich?",a="Ja. Geiferzähne sind aggressive, revierbezogene Wildschweine, die mit scharfen Stoßzähnen ausgestattet sind. Sie stellen eine erhebliche Bedrohung für das Vieh und ungeschützte Reisende in den Ebenen dar.",al={"sind geiferzähne feindselig","schweinegefahr westfall"}},{q="Warum ist die Nahrung in Westfall derzeit so knapp?",a="Ein Zusammenspiel aus verheerenden Dürren, fehlender Unterstützung durch das Königshaus in Sturmwind und Überfällen durch organisierte Banditen hat viele Bauern von ihrem Land vertrieben und die einstige Kornkammer des Königreichs in ein notleidendes, verarmtes Grenzland verwandelt.",al={"hungersnot in westfall","warum kein essen westfall","schwere zeiten in westfall"}},{q="Hilft der Abschluss dieser Aufgabe dem Saldean Farm beim Überleben?",a="Zwar löst dies nicht die umfassenderen Krisen, denen Westfall gegenübersteht, doch das Beschaffen von frischem Fleisch sichert der Familie Saldean direkt den Lebensunterhalt und versorgt Reisende mit nahrhaften Rationen für den weiteren Weg.",al={"ist die pastete wichtig","nahrungsvorrat der saldeans"}}},fx={["3baa4b09"]={q="Wofür werden Geiferzahnlebern verwendet?",a="Salma Saldean benötigt frische Geiferzahnlebern als letzte, entscheidende Zutat für ihren charakteristischen Fleischpastete aus Westfall. Sie hat bereits die gewürzte Kruste, gehackten Dill, Knoblauch, Rosmarin und köchelnde Bratensoße vorbereitet, aber es fehlt ihr das Fleisch, um das Familienessen zu vervollständigen.",al={"was ist geiferzahnleber für","warum geiferzahnleber","rezept geiferzahnleberpastete"}},ad043644={q="Warum bittet Salma einen Abenteurer, anstatt die Geiferzähne selbst zu jagen?",a="Salma ist damit beschäftigt, die Gehöfte zu führen und sich um die Küche zu kümmern, während die Saldeans um ihr Überleben kämpfen, angesichts der Härten, die Westfall heimsuchen. Da Wildschweine aggressiv außerhalb des Schutzes des Zauns streifen und die örtliche Miliz nur spärlich vorhanden ist, ist sie auf fähige Reisende angewiesen, um frisches Fleisch zu sammeln.",al={"warum ich geiferzahnleber","warum braucht mich salma","warum jagt salma nicht selbst"}}},fp="18,375,20.494.0,23.417.0,21.245.0,36.213.0,48.163.0,45.169.0,44.233.0,56.180.0"}
P.entries["quest:220"] = {n="Ruf des Wassers",s="Dieser Abschnitt der Schamanenprüfung verlangt von einem Novizen, gereinigtes Wasser quer durch das Brachland zu Islen Wasserdeuter zurückzubringen. Diese von der Einsiedlerin Brine zubereitete und gesegnete Phiole enthält den Katalysator, der benötigt wird, um einen spirituellen Sapta zu destillieren. Einmal gebraut, enthüllt der Trank die Elementargeister, die in den fernen Gewässern des Silberwalds verweilen.",h="Dieser Abschnitt der Schamanenprüfung verlangt von einem Novizen, gereinigtes Wasser quer durch das Brachland...",kw={"brine","ruf des wassers","islen wasserdeuter","sapta","silberwald","brachland","phiole mit reinstem wasser","wassersapta","wassertotem"},ang={["class:Shaman"]="Jeder Schamane der Horde muss die Rituale vom Ruf des Wassers abschließen, um Zwiesprache mit den Geistern zu halten und das Recht zu erlangen, sein Wassertotem zu tragen, das Heilung und Erneuerung regiert.",["faction:Horde"]="Die Prüfung erstreckt sich über Kalimdor und Lordaeron und verdeutlicht die geografische Weite der Horde, während junge Novizen vom Brachland in den von den Verlassenen kontrollierten Silberwald reisen."},sec={{t="Rückkehr an die Küste",b="Nachdem ein Schamanennovize das südliche Brachland durchquert und die von Brine gestellten Prüfungen bestanden hat, erhält er eine Phiole mit reinstem Wasser. Gefüllt aus unberührten Quellen und geweiht durch Brines abgeschiedene Riten, verkörpert dieses Gefäß das reine Potenzial des Elements. Es sicher zurück an die Ostküste zu bringen, wo Islen Wasserdeuter Wache hält, ist das entscheidende Bindeglied zwischen Brines einfacher Weisheit und den formellen Riten des Totems."},{t="Der Zweck des Saptas",b="Bei Erhalt des reinen Wassers erklärt Islen, dass sterbliche Augen die schwer fassbaren Geister des Wassers nicht ohne Weiteres erblicken können. Um mit ihnen Zwiesprache zu halten, muss ein Novize ein spezielles Gebräu zu sich nehmen, das als Sapta bekannt ist. Die von Brine gebrachte Flüssigkeit dient als wirkungsvolle Grundlage für diesen Trank und öffnet die Sinne des Schamanen für Mächte, die dem gewöhnlichen Blick verborgen bleiben. Doch wie Islen mahnt, ist die Zwiesprache nur die halbe Reise; die Geister selbst verlangen nach einer Prüfung."},{t="Eine Überfahrt nach Lordaeron",b="Islen offenbart, dass der Höhepunkt der Prüfung nicht in den trockenen Weiten Kalimdors stattfinden wird. Stattdessen muss der Schamane weit über das Meer zu den uralten, nebelverhangenen Küsten des Silberwalds reisen, südlich von Unterstadt. Dort, neben einem abgelegenen Schrein, muss der Sapta getrunken werden, damit der Novize den Elementaren direkt entgegentreten und sich das Recht verdienen kann, das Wassertotem zu manifestieren."}},faq={{q="Was befindet sich in der Phiole mit reinstem Wasser?",a="Die Phiole enthält Wasser, das der Novize aus reinen Quellen gesammelt hat und das durch die Riten der Einsiedlerin Brine geweiht wurde. Sie repräsentiert unberührtes Elementarwasser, das für das Brauen des alchemistischen Saptas unerlässlich ist, um mit Wassergeistern zu kommunizieren.",al={"phiole mit reinstem wasser","brines wasser","was gab brine mir"}},{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine ältere Schamanin, die an der abgelegenen Südostküste des Brachlands südlich von Ratschet lebt. Sie fungiert als wichtigste Mentorin für Schamanen der Horde, die Zwiesprache mit dem Element des Wassers halten und ihr Wassertotem erlangen möchten.",al={"islen","wer ist islen wasserdeuter","islen wasserdeuter lore"}},{q="Was ist ein Sapta?",a="Ein Sapta ist ein zeremonielles Stärkungsmittel, das von schamanischen Mentoren hergestellt wird. Nach dem Verzehr verändert es die Wahrnehmung des Trinkers und ermöglicht es einem Schamanen, Elementargeister klar zu sehen und mit ihnen zu interagieren, die für sterbliche Augen sonst unsichtbar sind.",al={"bedeutung sapta","wassersapta","was bewirkt sapta"}},{q="Warum muss ich als Nächstes in den Silberwald?",a="Der mit dieser Zwiesprache verbundene Elementarschrein liegt in den Küstengewässern des Silberwalds, südlich von Unterstadt in den Östlichen Königreichen. Die dort verweilenden Geister verlangen nach Zwiesprache und einer letzten Prüfung, bevor sie die Meisterschaft über ihr Element gewähren.",al={"warum silberwald","silberwald wassertotem","schrein im silberwald"}},{q="Wo lebt Brine?",a="Brine lebt in einer abgelegenen Hütte hoch in den Hügeln des südlichen Brachlands, westlich der Straße, die hinab zum großen Aufzug und zu den Tausend Nadeln führt.",al={"brine standort","wo ist brine","brine finden"}},{q="Kann ein Schamane das Herstellen des Saptas umgehen?",a="Nein. Die Rituale der Zwiesprache erfordern, dass der Geist eines Schamanen auf die unsichtbare Welt eingestimmt wird. Ohne die durch den Sapta geschaffene Brücke der Wahrnehmung können die Wassergeister am Schrein weder angesprochen noch herausgefordert werden.",al={"sapta überspringen","ist sapta erforderlich","visionssuche schamane"}}},fx={["5a67c999"]={q="Warum schickt Euch Brine zurück zu Islen Wasserdeuter?",a="Brine hat ihren Teil getan, indem sie die Gewässer, die Ihr in ganz Kalimdor gesammelt habt, gereinigt und in ein gesegnetes Fläschchen versiegelt hat. Sie weiß, dass sie nur eine Wegweiserin auf Eurem Pfad ist, nicht die Seherin, die Euch in die tieferen Mysterien einweiht. Islen Wasserdeuter schickte Euch zu Brine, um Eure Ausdauer zu beweisen, und nun, da das reinste Wasser vorbereitet ist, besitzt allein Islen die Weisheit, Eure Sapta zu brauen und die letzte Prüfung Eurer Verbindung zu leiten.",al={"warum schickt euch brine","brine motiv ruf des wassers","warum zurück zu islen"}},["51ede7cd"]={q="Warum muss Brine, dass Ihr das Fläschchen tragt, anstatt es selbst zu überbringen?",a="Diese Pilgerreise ist Eure Prüfung als Schamane, keine lästige Besorgung. Das Fläschchen enthält Wasser, das Ihr persönlich aus dem Wasserloch unterhalb von Brines Hütte im Brachland, dem Brunnen bei Tarrens Mühle und den The Ruins of Stardust im Eschental geschöpft habt, gesegnet durch Eure eigene Arbeit. Es über die Ebenen zurück zu Islen zu tragen, vollendet Eure persönliche Verbindung zum Element, bevor Ihr versucht, mit den Geistern zu kommunizieren.",al={"warum muss ich das fläschchen liefern","warum ich brine ruf des wassers","warum kann brine es nicht nehmen"}}},fp="13,347,19.429.0,24.445.0,23.397.1,40.257.0,23.238.0,16.225.0,46.247.0,22.146.0,39.206.0"}
P.entries["quest:2205"] = {n="Aufsuchen des SI:7",s="Aufsuchen des SI: 7 ist eine Einführungsaufgabe, die angehenden Schurken im Wald von Elwynn von Keryn Sylvius übertragen wird. Mit einem kleinen Paket von Goldhain nach Sturmwind werden Neulinge Meister Mathias Shaw vorgestellt, dem Anführer des verdeckten Geheimdienstnetzwerks der Krone.",h="Aufsuchen des SI: 7 ist eine Einführungsaufgabe, die angehenden Schurken im Wald von Elwynn von Keryn Sylvius...",kw={"goldhain","keryn sylvius","mathias shaw","die altstadt","schurke","aufsuchen des si: 7","der si:7","sturmwind"},ang={["class:Rogue"]="Diese Mission markiert den formellen Eintritt eines Schurken in die Dienste von Sturmwinds führender Spionagebehörde – der Übergang von einfachen Gassenkniffen zur königlichen Aufklärung.",["faction:Alliance"]="Der SI:7 dient als Augen und Ohren der Krone gegen interne und externe Bedrohungen und schützt das Reich im Stillen, während König Varian Wrynn weiterhin vermisst wird."},sec={{t="Die Prüfung eines Boten",b="Im Gasthaus \"Zur Höhle des Löwen\" in Goldhain verschwendet Schurkenlehrerin Keryn Sylvius wenig Zeit damit, Neuankömmlingen zu schmeicheln. In dem Glauben, dass frische Initianden eher wie Käselieferanten als fähige Geheimagenten aussehen, übergibt Sylvius dennoch einen Auftrag: eine versiegelte Lieferung in die Hauptstadt zu bringen. Die Aufgabe dient sowohl als verlässlicher Botengang als auch als unauffällige Eignungsprüfung für Späher, die in den weiteren Dienst des Reiches treten."},{t="Hinter verschlossenen Türen in der Altstadt",b="Das Ziel liegt tief in der Altstadt, dem belebten und abgewetzten Viertel von Sturmwind. In der südöstlichen Ecke des Bezirks befindet sich das Command Center des SI:7 – Stormwind Intelligence, Section 7. Hier überwacht Meister Mathias Shaw die verdeckten Operationen des Königreichs. Er nimmt das Paket mit seiner charakteristischen trockenen Skepsis entgegen und prüft, ob der Reisende die Härte besitzt, die für echte Spionage erforderlich ist."}},faq={{q="Was ist der SI:7?",a="Der SI:7 steht für Stormwind Intelligence, Section 7. Es ist die geheime Aufklärungs- und Spezialeinheit des Königreichs Sturmwind, die von Meister Mathias Shaw aus ihrem Hauptquartier in der Altstadt geleitet wird.",al={"was bedeutet si 7","was ist der si7","der si:7 lore"}},{q="Wer ist Keryn Sylvius?",a="Keryn Sylvius ist eine Schurkenlehrerin, die in Goldhain im Gasthaus \"Zur Höhle des Löwen\" stationiert ist. In Zusammenarbeit mit dem SI:7 beurteilt sie lokale Rekruten und schickt vielversprechende Späher zu Meister Mathias Shaw nach Sturmwind.",al={"keryn sylvius","schurkenlehrer goldhain"}},{q="Wo befindet sich Mathias Shaw in Sturmwind?",a="Meister Mathias Shaw ist im oberen Stockwerk des SI:7-Hauptquartiers zu finden, das in der südöstlichen Ecke von der Altstadt in Sturmwind liegt, vorbei an den Schurkenlehrern der Stadt.",al={"wo ist shaw","mathias shaw finden","mathias shaw aufenthaltsort"}},{q="Was geschieht nach der Übergabe des Pakets an Shaw?",a="Sobald Ihr Euch bei Mathias Shaw meldet, stellt er Eure praktischen Schurkenfähigkeiten sofort auf die Probe, indem er Euch auf eine verdeckte Mission nach Jerods Anlegestelle schickt, um den Frachtplan eines Hafenmeisters der Defias zu entwenden.",al={"folgequest nach aufsuchen des si 7","was will shaw"}},{q="Warum spottet Keryn über den Spieler, bevor sie die Lieferung übergibt?",a="Agenten des SI:7 sind stolz auf hohe Kompetenz und scharfe Instinkte. Sylvius behandelt unerfahrene Rekruten hart, um deren Wesen zu prüfen und sicherzustellen, dass nur Personen mit dickem Fell und wahrer Entschlossenheit Meister Shaw behelligen.",al={"warum beleidigt keryn mich","beleidigung käselieferant"}}},fx={["5aa3ad9f"]={q="Warum möchte Keryn Sylvius, dass dieses Paket an Mathias Shaw geliefert wird?",a="Keryn hat sich formell dazu verpflichtet, das Paket an Meister Mathias Shaw als Teil eines offiziellen Auftrags auszuliefern. Während sie es sichtlich verschmäht, selbst einfache Botengänge zu erledigen, dient es Euch zu schicken einem doppelten Zweck: Es ehrt ihre Verpflichtung gegenüber der Agentur und stellt gleichzeitig Eure angehenden Fähigkeiten als Schurke vor ihren Vorgesetzten in Sturmwind auf die Probe.",al={"warum an mathias liefern","keryn sylvius motiv","warum paket an si:7 schicken"}},["6bd14f9c"]={q="Warum schickt Keryn einen unerprobten Schurken, anstatt das Paket selbst auszuliefern?",a="Keryn ist in Goldhain stationiert, um neue Talente auszukundschaften und zu betreuen, weshalb sie wenig Interesse daran hat, kleine Lieferungen zurück zur Die Altstadt zu bringen. Die Aufgabe an einen eifrigen Neuling wie Euch abzugeben, erspart ihr die Laufarbeit und dient gleichzeitig als praktisches Vorsprechen, um zu sehen, ob Ihr scharf genug seid, das Hauptquartier des Geheimdienstes von Sturmwind zu finden.",al={"warum schickt mich keryn","warum ich si:7 aufsuchen","warum liefert sie es nicht selbst"}}},fp="14,267,16.414.0,31.426.0,13.207.0,21.216.0,43.175.0,50.191.1,64.212.0"}
P.entries["quest:2206"] = {n="Schneller Eingriff",s="Schneller Eingriff ist ein verdeckter Auftrag, der vielversprechenden Schurken von Meister Mathias Shaw, dem Anführer des SI:7, erteilt wird. Er beauftragt Agenten damit, Jerods Anlegestelle zu infiltrieren, um Informationen über Verschiffungen der Bruderschaft der Defias zu entwenden.",h="Schneller Eingriff ist ein verdeckter Auftrag, der vielversprechenden Schurken von Meister Mathias Shaw, dem...",kw={"kristallsee","defias","dockmaster","goldhain","jerods anlegestelle","mathias shaw","shipping schedule","der si:7","schneller eingriff"},ang={["class:Rogue"]="Diese Mission markiert die formelle Einführung eines Schurken in Den Der SI:7 und stellt Heimlichkeit und Beutelschneiderinstinkte auf die Probe, um Anerkennung und eine charakteristische Klinge von Mathias Shaw zu erlangen.",["faction:Alliance"]="Das Abfangen der Nachschubketten der Defias an Jerods Anlegestelle schützt den Wald von Elwynn und schwächt das kriminelle Syndikat, das die umliegenden Gebiete von Sturmwind bedroht."},sec={{t="Eine Prüfung des Handwerks",b="Für einen angehenden Agenten in Sturmwind ist das Erscheinen vor Meister Mathias Shaw die wahre Eintrittsprüfung in den verdeckten Geheimdienstflügel des Königreichs. Anstatt sich auf rohe Gewalt zu verlassen, verlangt Shaw den Beweis von Finesse und Heimlichkeit. Wichtige Zielpersonen lautlos auszuschalten und lebenswichtige Dokumente zu beschaffen, ohne das Reich in einen offenen Skandal zu verwickeln, ist der Kernauftrag des SI:7, und diese Mission dient als Bewährungsprobe für Eingeweihte."},{t="Schmuggler auf dem Fluss",b="Jerods Anlegestelle liegt am Fluss im südlichen Elwynn, südlich von Goldhain und knapp östlich der Weinberge der Maclures. Obwohl einst ein ruhiger örtlicher Kai, riss die Bruderschaft der Defias die Kontrolle über den Ort an sich, um einen illegalen Transitkorridor einzurichten. Indem die Diebe geschmuggelte Waffen, Vorräte und Schmuggelware über die Gewässer des Rotkammgebirges hinab nach Westfall befördern, umgehen sie die königlichen Straßenpatrouillen vollständig."},{t="Glaubhafte Abstreitbarkeit",b="Shaw macht die ständige Doktrin des SI:7 überdeutlich, bevor er Agenten ins Feld schickt: Sollte der Agent gefangen genommen, kompromittiert oder getötet werden, leugnen die Krone und ihre Spionagemeister jedes Wissen über seine Existenz. Die Beschaffung des Zeitplans des Hafenmeisters der Defias sichert entscheidende Beweise für die Nachschublinien der Bruderschaft, während die offizielle Verstrickung von Sturmwind im Schatten bleibt."}},faq={{q="Wer vergibt die Quest Schneller Eingriff?",a="Meister Mathias Shaw, Anführer von Sturmwinds Geheimdienst Der SI:7, vergibt die Quest aus dem Inneren des SI:7-Hauptquartiers in der Altstadt.",al={"wer vergibt schneller eingriff","questgeber schneller eingriff"}},{q="Wo liegt Jerods Anlegestelle?",a="Jerods Anlegestelle ist ein Kai am Fluss im südlichen Wald von Elwynn, südlich von Goldhain und knapp östlich der Weinberge der Maclures. Die Bruderschaft der Defias hat die Docks und das dortige Dockhaus beschlagnahmt.",al={"jerods anlegestelle standort","wo ist jerods anlegestelle","standort hafenmeister"}},{q="Was schmuggeln die Defias über Jerods Anlegestelle?",a="Die Defias nutzen Jerods Anlegestelle, um große Lieferungen von Schmuggelware und Nachschub über das Wasser zwischen dem Rotkammgebirge und Westfall zu transportieren, wodurch königliche Wachposten und Straßenkontrollpunkte umgangen werden.",al={"was schmuggeln sie","defias schmuggelware"}},{q="Wer trägt den Lieferzeitplan der Defias bei sich?",a="Der Lieferzeitplan wird vom Defias Dockmaster getragen, der bei der Bewachung des Dockhauses an Jerods Anlegestelle angetroffen werden kann.",al={"wo ist lieferzeitplan","wer droppt zeitplan","defias dockmaster"}},{q="Was passiert, wenn ein Agent während dieser Mission gefangen genommen wird?",a="Wie Meister Mathias Shaw warnt, agiert Der SI:7 nach dem Prinzip strenger glaubhafter Abstreitbarkeit. Wird ein Agent enttarnt oder gefangen genommen, streitet Der SI:7 jede Verbindung zu ihm ab.",al={"was passiert bei scheitern","vom si7 verleugnet"}},{q="Warum interessiert sich Der SI:7 für diesen Lieferzeitplan?",a="Das Dokument legt detailliert dar, wie die Bruderschaft der Defias Schmuggelgut zwischen dem Rotkammgebirge und Westfall transportiert. Es in Besitz zu bringen, erlaubt es dem Geheimdienstnetzwerk von Sturmwind, die feindliche Logistik zu kartieren, ohne das Syndikat zu warnen.",al={"warum zeitplan gebraucht","si7 lieferzeitplan"}}},fx={["170a7301"]={q="Was ist der Lieferzeitplan der Defias?",a="Der Zeitplan beschreibt den Transport illegaler Waren über die Wasserwege im Wald von Elwynn. The Defias Brotherhood hat Jerods Anlegestelle beschlagnahmt, um große Mengen an Schmuggelware zwischen Rotkammgebirge und Westfall direkt unter der Nase des Reiches zu befördern. Die Wiederbeschaffung dieser Fahrpläne liefert SI:7 konkrete Informationen über die Bewegungskorridore und logistischen Routen der Defias.",al={"lieferzeitplan der defias","was ist lieferzeitplan","nutzen lieferzeitplan"}},["5dd0ffd3"]={q="Wer ist der Defias Dockmaster?",a="Der Dockmaster überwacht die verdeckten Operationen der Brotherhood an Jerods Anlegestelle, einem Hafenhaus am Fluss südlich von Goldhain. Von diesem Aussichtspunkt aus koordiniert er den Fluss geschmuggelter Vorräte, Waffen und gestohlener Fracht, die zwischen Rotkammgebirge und Westfall bewegt werden, und führt die Frachtmanifeste der Defias-Flussläufer bei sich.",al={"defias dockmaster","wer ist der dockmaster","dockmaster jerods anlegestelle"}},a07026c6={q="Warum schickt Mathias Shaw Euch anstelle von erfahrenen SI:7-Agenten?",a="Ihr wurdet als vielversprechender neuer Schurkenrekrut, der von Keryn Sylvius entdeckt wurde, zu Mathias Shaw geschickt. Das Infiltrieren von Jerods Anlegestelle dient sowohl als echter operativer Test Eurer Heimlichkeit und Diebeskunst als auch als eine abstreitbare Feldmission. Da SI:7 plant, jegliche Kenntnis von Euch abzustreiten, falls Ihr erwischt werdet, schützt die Verwendung eines grünen Agenten das führende Geheimdienstnetzwerk Sturmwinds vor öffentlicher Enthüllung.",al={"warum schickt mich das","warum rekrutieren für si:7","warum braucht euch mathias shaw"}}},fp="15,223,20.422.0,22.390.0,21.390.0,38.132.0,25.200.0,54.184.0,41.119.0,61.160.0,48.206.0"}
P.entries["quest:221"] = {n="Worgen in den Wäldern",s="Während das Nightbane-Rudel weiter auf Dunkelhain vorrückt, beauftragt Calor Abenteurer damit, die primären einfachen Stalker des Rudels niederzustrecken. Diese wilden Dark Runners haben den nahegelegenen Der verlassene Obstgarten überrannt und drohen, die belagerte Stadt komplett einzukesseln.",h="Während das Nightbane-Rudel weiter auf Dunkelhain vorrückt, beauftragt Calor Abenteurer damit, die primären...",kw={"calor","treuwein","dark runner","dunkelhain","dämmerwald","the night watch","nightbane","der verlassene obstgarten","worgen"},ang={["class:Hunter"]="Das rasche Vordringen unnatürlicher zweibeiniger Wölfe im Der verlassene Obstgarten bietet Jägern eine düstere Lektion im Umgang mit außerweltlichen Bestien, deren Instinkte der natürlichen Ökologie von Azeroth trotzen.",["faction:Alliance"]="Der Dämmerwald hat praktisch keine Verstärkung von der Krone von Sturmwind erhalten, was lokale freiwillige Milizen wie The Night Watch dazu zwingt, sich vollständig auf reisende Helden der Allianz zu verlassen, um die eindringenden Raubtierrudel auszudünnen."},sec={{t="Ein sich verengender Belagerungsring",b="Während Kundschafter zuerst vereinzelte Worgen antrafen, die schattenhafte Magie am Rande des Waldes wirkten, enthüllten Calors Erkundungen eine weitaus dringendere taktische Bedrohung. Größere, schnellere Bestien, bekannt als Nightbane Dark Runners, haben sich im Der verlassene Obstgarten südwestlich von Dunkelhain versammelt. Anstatt nur unter dem Blätterdach zu lauern, bilden diese Raubtiere den Großteil des Rudels und haben einen Bereitstellungsraum in Schlagdistanz zu den Dorftoren errichtet."},{t="Eine unerschöpfliche Flut",b="Das Dezimieren der Dark Runners schwächt die Offensive des Rudels vorübergehend, aber für The Night Watch bietet dies kaum Beruhigung. Calor stellt mit wachsender Angst fest, dass jede erlegte Bestie augenblicklich durch eine andere ersetzt wird, die durch den Nebel streift. Die übernatürliche Widerstandsfähigkeit und die schiere Nachschubrate der Nightbane lassen die Verteidiger der Stadt ratlos zurück und zwingen sie dazu, sich an erfahrene Monsterjäger wie Meister Jonathan Treuwein zu wenden, um herauszufinden, welcher üble Katalysator diese außerweltlichen Schrecken in den Dämmerwald beschworen hat."}},faq={{q="Was sind Nightbane Dark Runners?",a="Nightbane Dark Runners sind größere, körperlich imposante Worgen, die die primären Fronttruppen des Rudels bilden, das den Dämmerwald heimsucht. Im Gegensatz zu den mystischen Shadow Weavers verlassen sich Dark Runners auf rohe Geschwindigkeit, Klauen und reine räuberische Wildheit.",al={"dark runners","was sind dark runners","nightbane dark runner"}},{q="Wo befindet sich Der verlassene Obstgarten?",a="Der verlassene Obstgarten liegt südwestlich von Dunkelhain. Einst produktives Ackerland, hat er sich zu einer verdorbenen, verfallenen Lichtung entwickelt, die das Nightbane-Rudel als vorgeschobenen Stützpunkt in der Nähe der Stadt eingenommen hat.",al={"lage von der verlassene obstgarten","wo ist der verlassene obstgarten"}},{q="Wer ist Calor?",a="Calor ist ein Waldläufer in Dunkelhain, der The Night Watch verlassen hat, um Meister Jonathan Treuwein zu dienen. Er erkundet die Außenbezirke der Siedlung und verfolgt die aggressiven Bewegungen der Worgen-Rudel, die das Überleben der Stadt bedrohen.",al={"wer ist calor","calor dämmerwald","calor questgeber"}},{q="Warum erscheinen die Worgen-Zahlen für die Verteidiger endlos?",a="Die Verteidiger verstehen noch nicht die übernatürliche Natur der Worgen-Präsenz. Sie glauben, dass eine böse Macht die Bestien aktiv in den Dämmerwald beschwört oder dorthin zieht, was dazu führt, dass neue Wellen so schnell erscheinen, wie die bestehenden getötet werden.",al={"warum so viele worgen","unerschöpfliche worgen","woher kommen die worgen"}},{q="Wer ist Meister Treuwein?",a="Meister Jonathan Treuwein ist ein erfahrener Jäger und Schütze, der in Dunkelhain stationiert ist. The Night Watch vertraut immens auf seine Expertise, um die Ursache für die monströsen Heimsuchungen zu finden, die die Region quälen.",al={"meister treuwein","jonathan treuwein","wer ist treuwein"}},{q="Wie passt diese Aufgabe in die Verteidigung von Dunkelhain?",a="Dunkelhain ist eine isolierte Siedlung mit schwindenden Vorräten und ohne Hilfe aus Sturmwind. Die Säuberung von Der verlassene Obstgarten verhindert, dass das Nightbane-Rudel direkte, überwältigende Hinterhalte an der südwestlichen Peripherie der Stadt inszeniert.",al={"warum dark runners töten","verteidigung von dunkelhain"}}},fx={e2dcc78b={q="Warum will Calor, dass die Nightbane-Finsterläufer erlegt werden?",a="Calor verfolgt die tierischen Übergriffe um Dunkelhain und weiß, dass die Finsterläufer den Großteil der Worgen-Streitkräfte ausmachen, die im Wald umherstreifen. Schlimmer noch, sie haben den Der verlassene Obstgarten südwestlich der Stadt komplett überrannt. Ein solch großes und wildes Rudel so nahe an Dunkelhain ungehindert zu lassen, führt zum Desaster, also muss er ihre Anzahl verringern, bevor die Siedlung überwältigt wird.",al={"calor motiv","warum finsterläufer töten","warum will calor dass dies erledigt wird"}},["99fe833d"]={q="Warum verlässt sich Calor auf Euch, anstatt den Obstgarten selbst zu säubern?",a="Calor ist ein Kundschafter und Waldläufer, dessen Hauptaufgabe darin besteht, den Wald im Auge zu behalten, Tierbewegungen zu verfolgen und Bedrohungen an Dunkelhain zu melden. Die Nightbane-Worgen sind aggressiv, zäh und scheinbar unerschöpflich, was die Verteidiger der Stadt bis an ihre Grenzen belastet. Da Dunkelhain von allen Seiten von Schrecken belagert wird, sind Waldläufer wie Calor auf fähige Abenteurer angewiesen, um den Kampf direkt in die befallenen Haine wie den Der verlassene Obstgarten zu tragen.",al={"warum ich","warum macht calor es nicht","warum braucht calor hilfe"}}},fp="19,266,22.451.0,21.497.1,32.243.0,37.199.0,13.221.0,56.242.0,22.219.0,53.221.0"}
P.entries["quest:222"] = {n="Worgen in den Wäldern",s="Während das Rudel der Nachtheuler den Dämmerwald immer fester im Griff hat, schickt Calor Abenteurer aus, um deren tödlichste Ränge anzugreifen. Indem sie den Kampf direkt zu ihren südlichen Höhlen und Minen tragen, drängen die Verteidiger die wilde Bedrohung zurück, die auf Dunkelhain übergreift.",h="Während das Rudel der Nachtheuler den Dämmerwald immer fester im Griff hat, schickt Calor Abenteurer aus, um...",kw={"calor","carevin","dunkelhain","dämmerwald","nachtheuler","besudelter","übelfang","worgen"},ang={["class:Hunter"]="Die von dem Rudel der Nachtheuler gezeigte Gerissenheit macht sie zu unnatürlicher Beute und verlangt Fährtenlesern, die sich in die Nähe ihrer finsteren Höhlen wagen, höchste Wachsamkeit ab.",["faction:Alliance"]="Dunkelhain liegt isoliert im düsteren Süden des Königreichs; die Säuberung der südlichen Höhlen trägt dazu bei, die empfindlichen Versorgungswege und verbliebenen Gehöfte des Dämmerwalds zu schützen."},sec={{t="Ein wilder Stützpunkt",b="Die Worgenplage, die den Dämmerwald heimsucht, ist keineswegs sinnloses Chaos. Die als Nachtheuler bekannten Bestien haben sich im dunklen Areal südlich von Dunkelhain ein Revier abgesteckt und damit begonnen, befestigte Lager zu errichten. Calor beobachtet ihre Lagerfeuer in der Ferne mit wachsendem Grauen und stellt fest, dass die Kreaturen tiefe Höhlen und verlassene Minenschächte besetzt haben. Unter ihnen stellen die Übelfänge und die Besudelten die bösartigsten Züchtungen dar; sie legen eine grimmige Wildheit und Zähigkeit an den Tag, die den Schutzgürtel der Stadt zu überwältigen droht."},{t="Calors Empfehlung",b="Calor dient als aufmerksamer Rekrutierer an vorderster Front für Dunkelhains Verteidigung, auch wenn er sich kaum Illusionen über die furchterregende Natur der wölfischen Invasoren macht. Das Brechen der Macht der Übelfänge und Besudelten stellt den Mut eines jeden Helden auf die Probe. Wer diese abgebrühten Rudel erfolgreich ausdünnt, erlangt mehr als nur ein paar Münzen: Man verdient sich Calors Respekt und eine persönliche Empfehlung an Meister Carevin, die zurückgezogen lebende Gestalt, die die umfassendere Offensive gegen die Worgenplage koordiniert."}},faq={{q="Wo befinden sich die Übelfänge und Besudelten?",a="Diese gefährlichen Züchtungen des Nachtheulerrudels rotten sich um Höhlen und die Mine in den südlichen Gefilden des Dämmerwalds zusammen, oft versammelt um sichtbare Lagerfeuer.",al={"wo sind besudelte","wo sind übelfänge","worgen orte dämmerwald"}},{q="Wer ist Calor?",a="Calor ist ein pflichtbewusster Bewohner von Dunkelhain, der die Worgenbedrohung in den Wäldern überwacht und fähige Abenteurer anwirbt, um das Vorrücken der Kreaturen einzudämmen.",al={"calor dunkelhain","wer vergibt worgs in den wäldern 3"}},{q="Wer ist Meister Carevin?",a="Meister Carevin ist Jonathan Treuwein aus Dunkelhain, dessen Familie den Kampf gegen das Böse in der Region aufnimmt und der die Bemühungen leitet, die Worgenbedrohung aus dem Umland auszumerzen.",al={"meister carevin","carevin dämmerwald"}},{q="Warum machen die Worgen Lagerfeuer?",a="Trotz ihrer monströsen, wolfsähnlichen Erscheinung zeigen die Worgen der Nachtheuler eine beunruhigende Intelligenz; sie rotten sich in organisierten Lagern zusammen, nutzen Feuer und halten befestigte Stellungen wie Minen.",al={"warum machen worgen feuer","nachtheuler lagerfeuer"}},{q="Was geschieht nach Abschluss dieser Jagd?",a="Wer Calor beeindruckt, erhält ein Empfehlungsschreiben, das Euch direkt zu Meister Carevin schickt, um ihm bei der nächsten Phase der Jagd beizustehen.",al={"folgequest worgs in den wäldern 3","worgs in den wäldern folgequest"}},{q="Warum ist Dunkelhain wegen genau dieser Worgen so besorgt?",a="Die Übelfänge und Besudelten gehören zu den tödlichsten und aggressivsten Mitgliedern des Rudels. Lässt man sie nahe den südlichen Minen gewähren, besteht die Gefahr, dass die Bestien die umliegenden Straßen vollständig überrennen.",al={"warum nachtheuler übelfang","übelfang gefahr"}}},fx={["0c2f2969"]={q="Warum will Calor, dass diese Worgen getötet werden?",a="Calor arbeitet daran, Dunkelhain zu beschützen und Meister Treuweins laufenden Kreuzzug gegen die lupine Bedrohung zu unterstützen. Das Nightbane-Rudel hat sich im Süden verschanzt, Lagerfeuer entzündet und Stützpunkte in Höhlen und Minen errichtet. Indem er Euch schickt, um ihre tödlichsten Kämpfer auszumerzen, hofft Calor, die Stärke des Rudels zu schwächen, bevor sie die wenigen verbliebenen Verteidigungskräfte im Dämmerwald überwältigen.",al={"warum die worgen töten","calor motiv","warum will calor das"}},["5cfb2401"]={q="Was sind die Vile Fangs und Tainted Ones, die Ihr jagt?",a="Sie gehören zu den tödlichsten und grausamsten Mitgliedern des Nightbane-Rudels. Im Gegensatz zu den niedereren Bestien, die durch die Wildnis streifen, haben diese Worgen Lager in der Nähe von Rolands Verdammnis und anderen südlichen Höhlen errichtet, brennende Feuer entfacht und eine gerissene, koordinierte Präsenz gezeigt, die ganz Dunkelhain bedroht.",al={"wer sind die vile fangs","tainted ones dämmerwald","ziel worgen"}},["5e6f00dd"]={q="Warum rekrutiert Calor Euch, anstatt die Bestien selbst zu erledigen?",a="Die Verteidiger von Dunkelhain, The Night Watch, sind bei der Bewachung des Stadtperimeters gegen Untote, Spinnen und bösartige Bestien bis an ihre Grenzen belastet. Den Kampf tief in das Worgen-Gebiet zu tragen erfordert erfahrene Recken, die dunkler Magie und roher Wildheit standhalten können, und Eure vergangenen Erfolge haben Calor bewiesen, dass Ihr die Fähigkeiten zum Überleben habt.",al={"warum braucht mich calor","warum schickt man mich","warum kümmert sich die night watch nicht darum"}}},fp="19,242,16.538.0,19.475.1,50.158.0,13.150.0,22.188.0,32.189.0,40.135.0,58.205.0"}
P.entries["quest:223"] = {n="Worgen in den Wäldern",s="Dieser Botengang überbringt Calors Empfehlungsschreiben an Jonathan Treuwein in Dunkelhain und schließt Eure Jagd nach den wilden Worgen ab, die den Dämmerwald heimsuchen. Beeindruckt von Eurem Können gegen die bestialischen Invasoren schickt Calor Euch direkt zu einem Mann, der noch tiefere Bedrohungen in den Schatten bekämpft.",h="Dieser Botengang überbringt Calors Empfehlungsschreiben an Jonathan Treuwein in Dunkelhain und schließt Eure...",kw={"calor","calors notiz","dunkelhain","dämmerwald","jonathan treuwein","die nachtwache","worgen in den wäldern"},ang={["class:Paladin"]="Carevin begrüßt bewährte Verbündete mit Anrufungen des Heiligen Lichts und sucht nach heiligen Streitern, die bereit sind, den unbändigen unheiligen Mächten des Dämmerwalds die Stirn zu bieten.",["class:Priest"]="Carevins Abschiedssegen „Ruhm unter dem Licht“ spiegelt den verzweifelten Glauben der verbliebenen Verteidiger von Dunkelhain angesichts der endlosen dunklen Verderbnis wider.",["faction:Alliance"]="Da das Königreich Sturmwind keine Soldaten für die Grenzlande des Dämmerwalds entbehren kann, bilden unabhängige Abenteurer der Allianz und Selbstjustizler wie Carevin die einzige Verteidigungslinie der Stadt."},sec={{t="Eine seltene Empfehlung",b="Nachdem Ihr das Rudel der Nachtheuler dezimiert habt, das Rolands Verdammnis und die schattigen Lichtungen heimsuchte, habt Ihr Euch den mühsam erworbenen Respekt von Calor verdient. An den finsteren Grenzen des Waldes stationiert, verteilt Calor nur selten Komplimente, geschweige denn formelle Empfehlungen. Er händigt Euch ein verblichenes Stück Pergament aus und weist Euch an, sein Wort direkt an Jonathan Treuwein in Dunkelhain zu überbringen. Dabei bemerkt er, dass ihre kleine Truppe mit mehr Kämpfern Eures Schlags die bedrängte Nachtwache der Stadt endlich in den Schatten stellen könnte."},{t="Carevins Wacht",b="Jonathan Treuwein agiert in Dunkelhain unter enormem Druck, misstrauisch gegenüber Fremden und ständig in Eile. Die Stadt sieht sich nicht nur den Angriffen geifernder Worgen ausgesetzt, sondern auch rastlosen Untoten, finsteren dämonischen Mächten und verräterischen Kultisten, welche die Verderbnis von innen heraus unterstützen. Calors glühende Empfehlung bricht Carevins kühles Auftreten und bestätigt Euch als vertrauenswürdige Klinge, die sich dem Schutz des Lichts gegen die erdrückenden Schrecken des Dämmerwalds verschrieben hat."}},faq={{q="Wer schickt mich auf diese Mission?",a="Calor schickt Euch auf diesen Botengang. Nachdem er Eure Erfolge gegen die gefräßigen Worgenrudel im gesamten Dämmerwald beobachtet hat, händigt er Euch eine verblichene Empfehlungsnotiz aus, die Ihr zu seinem Gefährten Jonathan Treuwein bringen sollt.",al={"questgeber","wer startet das","calor"}},{q="Wer ist Jonathan Treuwein?",a="Jonathan Treuwein ist ein düsterer, hochkonzentrierter Bewohner von Dunkelhain, der die Maßnahmen gegen die übernatürlichen Übel koordiniert, welche die Stadt bedrohen. Obwohl er Fremden gegenüber misstrauisch ist, arbeitet er mit verlässlichen Verbündeten wie Calor zusammen, um Untote, Dämonen und deren Helfershelfer auszumerzen.",al={"carevin","wer ist carevin","meister carevin"}},{q="Warum steht Calor der Nachtwache so geringschätzig gegenüber?",a="Calor deutet an, dass die offizielle Nachtwache der Stadt überfordert und zu dünn aufgestellt ist, um der Vielzahl von Schrecken im Dämmerwald Herr zu werden. Er glaubt, dass ein paar fähige, entschlossene Kämpfer außerhalb der formellen Bürokratie gegen die vordringenden Schatten weit mehr ausrichten können.",al={"calor nachtwache","die nachtwache übertreffen","warum konkurrenz zur nachtwache"}},{q="Vor welchen Gefahren warnt Carevin bei der Übergabe?",a="Nachdem er die Empfehlung gelesen hat, warnt Carevin, dass Dunkelhain an allen Fronten bedroht wird: durch gefräßige Worgen, umherwandernde Untote, einfallende Dämonen und heimtückische Kultisten oder Sympathisanten, die ihnen beistehen. Er mahnt Euch, stets wachsam zu bleiben und nur bewährten Verbündeten zu vertrauen.",al={"carevins feinde","was sagt carevin","was bekämpfen wir"}},{q="Erfordert diese Quest irgendwelche Kämpfe?",a="Nein. Dieser letzte Schritt ist ein reiner Botengang. Nachdem Ihr in den früheren Teilen der Reihe die gefährlichen Jagden auf die Nachtheuler-Worgen im gesamten Dämmerwald überstanden habt, müsst Ihr bei dieser Aufgabe Calors Notiz lediglich sicher zu Carevin in Dunkelhain bringen.",al={"irgendein kampf","muss ich etwas töten","nur lieferung"}},{q="Wo finde ich Jonathan Treuwein?",a="Jonathan Treuwein hält sich in der Stadt Dunkelhain im Dämmerwald auf, wo er sich um dringende Angelegenheiten rund um die heikle Verteidigung der Stadt kümmert.",al={"carevin standort","wo ist carevin","wo abgeben"}}},fx={f56a577c={q="Warum schickt Euch Calor zu Jonathan Carevin?",a="Calor glaubt, dass Ihr Euren Mut in den Wäldern bewiesen habt, und möchte Euch formell seinem Vorgesetzten, Meister Jonathan Carevin, vorstellen. Sein kleiner Orden operiert im Schatten von Dämmerwald abseits der schwer bedrängten The Night Watch, und er hofft, dass es ihre geheimen Bemühungen gegen die dunkleren Bedrohungen, die die Region plagen, stärkt, kompetente Kämpfer wie Euch in ihren Kreis aufzunehmen.",al={"warum zu carevin schicken","calor motiv","warum notiz zu carevin bringen"}},["47a08b52"]={q="Warum verlässt sich Calor auf Euch und nicht auf die The Night Watch?",a="Calor hat wenig Vertrauen in die herkömmliche Stadtwache und hält die The Night Watch für unzureichend für die düstere, spezialisierte Arbeit, die sein Orden verrichtet. Da Ihr Eure Fähigkeiten unter Beweis gestellt habt, indem Ihr Euch direkt mit der Worgenbedrohung auseinandergesetzt habt, wo andere versagten, sieht er Euch als jemanden, der wirklich in der Lage ist, ihren geheimen Kreuzzug gegen die dunkleren Schrecken des Dämmerwalds zu unterstützen.",al={"warum nicht night watch","warum vertrauen mir die wachen nicht","warum braucht calor mich"}}},fp="19,285,21.503.0,15.479.0,29.213.0,24.271.0,46.276.0,51.271.0,35.246.0,34.140.0"}
P.entries["quest:224"] = {n="Verteidigung der Länder des Königs",s="Gebirgsjäger Cobbleflint bewacht den südlichen Turm im Tal der Könige und sucht verzweifelt nach Hilfe gegen die vordringenden Splittersteintroggs. Da Eisenschmiedes Streitkräfte an fernen Fronten gebunden sind, fällt die Verteidigung der südlichen Pässe von Loch Modan durchreisenden Freiwilligen der Allianz zu.",h="Gebirgsjäger Cobbleflint bewacht den südlichen Turm im Tal der Könige und sucht verzweifelt nach Hilfe gegen...",kw={"cobbleflint","gravelgaw","eisenschmiede","loch modan","gebirgsjäger","splitterstein","trogg","tal der könige"},ang={["class:Hunter"]="Die Klippen und Felsvorsprünge des Splittersteintals bieten ideales Terrain, um aggressive Troggwachen und Spähtrupps aus erhöhter Position auszuschalten.",["faction:Alliance"]="Die Sicherung des Tals der Könige beweist die Stärke des Bündnisses der Allianz und erhört Eisenschmiedes Hilferuf, während die Zwergentruppen an fernen Fronten der Verbündeten kämpfen.",["race:Dwarf"]="Für Zwergenabenteurer ist Cobbleflints Ruf eine entscheidende Angelegenheit der Heimatverteidigung, damit König Magnis angestammte Täler nicht an unterirdisches Ungeziefer fallen, während die Armee andernorts kämpft."},sec={{t="Eine dünne Linie im Tal der Könige",b="Die gewaltigen Zwergenmonumente, die in die Berge des Tals der Könige gehauen wurden, überragen eine Garnison unter schwerer Belastung. Gebirgsjäger Cobbleflint und seine Kameraden am südlichen Wachturm sehen sich einer stetig wachsenden Invasion von Troggs gegenüber, die aus dem Fels hervorbrechen. Da ein Großteil des regulären Heeres von König Magni Bronzebart im Ausland eingesetzt wird, um die Verpflichtungen gegenüber der Allianz zu erfüllen, ist die Heimatfront stark auf örtliche Patrouillen und angeheuerte Klingen angewiesen, damit die Provinz nicht überrannt wird."},{t="Der Überfall der Splittersteine",b="Die unterirdische Bedrohung geht vom Splittersteintal aus, einer zerklüfteten Schlucht, die sich in die südlichen Gipfel von Loch Modan schneidet. Troggs und ihre Späher haben sich in Scharen an die Oberfläche gegraben und befestigte Lager auf dem Talboden errichtet. Bleiben sie ungestört, gefährden ihre Spähtrupps die entscheidenden Straßen, die Loch Modan mit den südlichen Pässen verbinden, was die Gebirgsjäger zu einem fortwährenden Abnutzungskampf zwingt."}},faq={{q="Warum ist die Garnison in Loch Modan so unterbesetzt?",a="König Magni Bronzebart hat große Teile der Streitkräfte von Eisenschmiede auf fernen Schlachtfeldern und Außenposten der Allianz in ganz Azeroth stationiert. Durch diesen Auslandseinsatz werden Heimatgebiete wie Loch Modan vor allem von leichten Gebirgsjägerpatrouillen geschützt, die auf durchreisende Abenteurer angewiesen sind, um regionale Invasionen einzudämmen.",al={"warum so wenige wachen","wo sind die soldaten von eisenschmiede","warum unterbesetzt"}},{q="Wer ist Gebirgsjäger Cobbleflint?",a="Gebirgsjäger Cobbleflint ist ein Zwergenposten am südlichen Wachturm im Tal der Könige. Er koordiniert die Grenzsicherung entlang der südlichen Ausläufer von Loch Modan und leitet Gegenangriffe gegen die nistenden Troggstämme.",al={"cobbleflint","wer gibt quest","questgeber"}},{q="Wo liegt das Splittersteintal?",a="Das Splittersteintal liegt südlich von Thelsamar und ist über einen Zugang nahe der Hauptstraße erreichbar, bevor man die gewaltigen Zwergenstatuen im Tal der Könige erreicht. Die Troggs unterhalten mehrere Lager auf dem felsigen Grund.",al={"splitterstein standort","wo sind troggs","splittersteintal finden"}},{q="Was macht Troggs zu einer derart ernsten Bedrohung für die Zwerge?",a="Troggs sind aggressive, unterirdische Rohlinge, die sich durch massiven Fels graben und so herkömmliche Mauern und Befestigungen an der Oberfläche umgehen. Da sie unvorhergesehen unter Straßen, Siedlungen und Minen hervorbrechen können, betrachtet die Zwergenführung ihre ungebremste Ausbreitung als existenzielle Gefahr für die Sicherheit von Eisenschmiede.",al={"trogg bedrohung","warum troggs bekämpfen","sind troggs gefährlich"}},{q="Mit wem spreche ich nach der Hilfe für Cobbleflint?",a="Nachdem Ihr die Reihen der Troggs und Späher der Splittersteine gelichtet habt, schickt Euch Cobbleflint zu Gebirgsjäger Gravelgaw, der direkt im angrenzenden Wachturm postiert ist und die nächste Phase der Patrouille an der Talfront leitet.",al={"folgequest","wohin danach","gravelgaw"}},{q="Sind die Splittersteintroggs organisiert?",a="Obwohl primitiv, zeigt der Splitterstein-Klan eine rudimentäre Organisation, indem er spezialisierte Späher zur Erkundung der Straßen aussendet, während brutale Fußsoldaten Verteidigungslager in der gesamten Schlucht unterhalten.",al={"troggspäher","sind troggs klug","splittersteinstruktur"}}},fx={abec66b9={q="Warum will Gebirgsjäger Cobbleflint, dass die Troggs dezimiert werden?",a="Gebirgsjäger Cobbleflint betrachtet den Troggbefall als die größte Bedrohung für Loch Modan und Eisenschmiede selbst. Die Kreaturen haben sich aus jeder Spalte nach oben gegraben und bedrohen das Tal der Könige und die umliegenden Ländereien. Da die reguläre Zwergenarmee an entfernten Fronten eingesetzt ist, muss sich Cobbleflint auf mutige Freiwillige verlassen, um ihre schwärmenden Zahlen zu verringern, bevor die örtlichen Türme und Siedlungen völlig überrannt werden.",al={"warum troggs töten","cobbleflint motiv","warum muss cobbleflint troggs töten lassen"}},["515fdd78"]={q="Was machen die Splittersteintroggs in Loch Modan?",a="Die Splittersteintroggs sind wilde unterirdische Mutanten, die sich in den südlichen Teil des Lochs gegraben und Lager im gesamten Splittersteintal errichtet haben. Ihre Späher erkunden ständig das Zwergengebiet und suchen nach Schwachstellen entlang der Talstraßen und in der Nähe des südlichen Wachturms. Wenn man sie nicht aufhält, droht ihr rasches Auftauchen die Reiserouten zu unterbrechen und die Region zu überrennen.",al={"wer sind die troggs","warum sind splittersteintroggs hier","splittersteintroggs ziel"}}},fp="30,289,34.477.0,27.426.0,49.323.0,31.239.0,38.219.0,54.314.0,44.226.0,39.218.0"}
P.entries["quest:2242"] = {n="Das Schicksal ruft",s="Das Schicksal ruft ist eine diskrete Untersuchung im Auftrag von Syurna, um die Quelle des Verderbens aufzudecken, das durch Teldrassils Äste sickert. Die Mission beauftragt einen Agenten damit, an einem feindseligen Satyr namens Sethir the Ancient nahe der Lichtung des Orakels vorbeizuschlüpfen oder ihn zu stellen, um sein Tagebuch zu beschaffen.",h="Das Schicksal ruft ist eine diskrete Untersuchung im Auftrag von Syurna, um die Quelle des Verderbens...",kw={"dunkelküste","darnassus","das schicksal ruft","tagebuch","die lichtung des orakels","satyr","sethir the ancient","syurna","teldrassil"},ang={["class:Rogue"]="Vergeben von Darnassus' eigenen Schleichmeistern, prüft diese Mission die Fähigkeit eines Infiltrators, heikle Informationen direkt vor der Nase eines gefährlichen Satyrs zu entwenden.",["faction:Alliance"]="Die Entdeckung verknüpft die örtlichen Waldunruhen auf Teldrassil mit einer umfassenderen kontinentalen Korruption und bereitet die Bühne für Streitkräfte der Allianz, die ins nördliche Kalimdor reisen.",["race:NightElf"]="Für Verteidiger der Kaldorei signalisiert die Erkenntnis, dass der uralte Fluch der Dunkelküste das Meer nach Teldrassil überquert hat, eine alarmierende Bedrohung für ihre heilige Zuflucht."},sec={{t="Eine lautlose Erkundung",b="Die Führung der Nachtelfen in Darnassus hat Teldrassils wachsende Krankheit mit stiller Sorge beobachtet. Anstatt bewaffnete Patrouillen auszusenden, die den Tod finden, sucht die Schurkenlehrerin Syurna nach jemandem, der zu unauffälligem Vorgehen fähig ist. Sethir the Ancient, ein Satyr, der auf einem abgelegenen Ast nahe der Lichtung des Orakels haust, hat jeden Versuch mit Gewalt ebenso abgewehrt wie diplomatische Annäherungen. Um herauszufinden, was er weiß, muss man sich in seinen Unterschlupf schleichen und seine persönlichen Besitztümer an sich bringen."},{t="Ein drohender Schatten von der Dunkelküste",b="Die geborgenen Seiten aus Sethirs Tagebuch bringen düstere Enthüllungen zutage. Das heimtückische Verderben, das den neugeborenen Weltenbaum bedroht, steht in direktem Zusammenhang mit der uralten Fäulnis und Korruption, die die Wälder und Wasserwege jenseits des nebligen Meeres an der Dunkelküste verzehrt. Anstelle einer isolierten Krankheit des Bodens deutet das Gebrechen auf eine größere, gezielte Bosheit hin, die das Kernland der Kaldorei bedroht."}},faq={{q="Wer ist Sethir the Ancient?",a="Sethir the Ancient ist ein schwer fassbarer Satyr, der sich auf einem Ast an den nördlichen Ausläufern von Teldrassils Lichtung des Orakels verbirgt. Feindselig und gerissen hat er sowohl militärische Angriffe als auch friedliche Nachforschungen vereitelt, die herausfinden sollten, was er über das Verderben der Insel weiß.",al={"sethir","wer ist sethir","satyr auf der lichtung des orakels"}},{q="Warum will Syurna Sethirs Tagebuch?",a="Syurna glaubt, dass Sethir entscheidende Einblicke in die unnatürliche Krankheit besitzt, die sich auf Teldrassil ausbreitet. Sein persönliches Tagebuch enthält Aufzeichnungen über die Aktivitäten des Satyrs und die Natur des dunklen Verderbens.",al={"warum sethirs tagebuch","syurnas ziel","was steht im tagebuch"}},{q="Was enthüllt das Tagebuch nach Abschluss?",a="Das Tagebuch bestätigt, dass die Krankheit, die Teldrassils Äste befällt, mit der tieferen, dämonischen Plage verbunden ist, die die uralten Wälder und Küsten der Dunkelküste jenseits der Meerenge heimsucht.",al={"tagebuch-lore","was sethir herausfand","dunkelküste verbindung"}},{q="Wo wird diese Quest angenommen?",a="Die Aufgabe wird von Syurna vergeben, der Schurkenlehrerin in den Schatten von Darnassus, nachdem Ihr eine erste Prüfung Eurer Fähigkeiten bestanden habt.",al={"wo bekomme ich das schicksal ruft","das schicksal ruft questgeber","wer vergibt das schicksal ruft"}},{q="Wohin sollten Abenteurer nach Abschluss dieser Mission gehen?",a="Syurna bemerkt, dass Ihr in dieser Angelegenheit alles getan habt, was Ihr für Teldrassil tun konntet, und weist junge Verteidiger nach Dunkelküste, wo die wahre Wurzel des Verderbens des Festlands wartet.",al={"was kommt danach","nächster schritt nach das schicksal ruft","nach sethir"}},{q="Warum kümmert sich ein Schurkenlehrer um Waldverderbnis statt der Druiden?",a="Herkömmliche Methoden – sowohl militärische Streitkräfte als auch druidische Diplomatie – scheiterten an Sethir mit tödlichen Folgen. Syurna greift auf verdeckte Aufklärung und Infiltration zurück, wenn offenkundige Bemühungen in blutigen Sackgassen enden.",al={"warum schurkenquest","warum syurna","warum nicht zirkel des cenarius"}}},fp="13,276,23.456.0,31.375.1,26.260.0,38.206.0,45.186.1,29.148.0,58.174.1,68.211.0"}
P.entries["quest:2259"] = {n="Erion Schattenflüsterer",s="Erion Schattenflüsterer ist eine geradlinige Vorquest, die aufstrebende Schurken der Allianz nach Darnassus entsendet. Die von Jannok Windsang überbrachte Nachricht leitet Reisende in die Enklave des Cenarius, wo Erion darauf wartet, ihre Bemühungen über die lokalen Grenzen hinaus auszuweiten.",h="Erion Schattenflüsterer ist eine geradlinige Vorquest, die aufstrebende Schurken der Allianz nach Darnassus...",kw={"die enklave des cenarius","darnassus","erion schattenflüsterer","erions befehl","jannok windsang","schurken vorquest","syurna"},ang={["class:Rogue"]="Diese Vorquest markiert Euren Übergang von der Anfängerarbeit auf Teldrassil und führt Euch direkt zu Erion Schattenflüsterer für Missionen, die jenseits der Startwälder Fingerspitzengefühl verlangen.",["faction:Alliance"]="Die Quest weist Agenten der Allianz im nördlichen Kalimdor an, sich mit Kontaktpersonen in Darnassus abzustimmen, bevor sie sich in umkämpftes Gebiet vorwagen.",["race:NightElf"]="Für Schattengänger der Nachtelfen ist die Meldung bei Erion in Darnassus ein wesentlicher Übergangsritus – der Schritt von der lokalen Schutzarbeit hin zu umfassenderen Pflichten auf dem Kontinent."},sec={{t="Eine Vorladung in die Enklave",b="Wenn ein Schurke sich in den umliegenden Landen von Teldrassil einen Namen macht, schreitet Jannok Windsang ein, um sicherzustellen, dass dessen Talente nicht vergeudet werden. Jannok zerstreut jegliche ängstlichen Gedanken daran, zur anspruchsvollen Ausbilderin Syurna geschickt zu werden, und weist den Agenten stattdessen direkt in das Herz von Darnassus. Dort, tief unter den grünen Ästen der Enklave des Cenarius, wacht Erion Schattenflüsterer über Angelegenheiten, die ein leiseres, subtileres Vorgehen erfordern."},{t="Den Horizont im Blick",b="Erion zu erreichen markiert einen wichtigen Wendepunkt für jeden Schurken, der im Territorium der Nachtelfen agiert. Seine Begrüßung stellt unmissverständlich klar, dass die schützenden Wälder von Teldrassil die Pflichten eines Agenten nicht länger eingrenzen können. Erions Aufgabe ist es, fähige Hände hinaus in eine weitere, gefährlichere Welt zu lenken, und fungiert als Sprungbrett für Einsätze jenseits des Meeres."}},faq={{q="Wer schickt Euch aus, um Erion Schattenflüsterer zu finden?",a="Jannok Windsang spricht die Aufforderung aus und weist Euch an, Euch unverzüglich nach Darnassus zu begeben, um mit Erion Schattenflüsterer in der Enklave des Cenarius zu sprechen.",al={"questgeber","wer startet erion schattenflüsterer","jannok windsang quest"}},{q="Wo befindet sich Erion Schattenflüsterer?",a="Erion Schattenflüsterer befindet sich in der Enklave des Cenarius in Darnassus, eingebettet zwischen den Bäumen auf den oberen Ebenen der Enklave.",al={"erion standort","wo ist erion","erion schattenflüsterer finden"}},{q="Warum erwähnt Jannok Syurna?",a="Syurna ist eine prominente Schurkenausbilderin in Darnassus, die für ihre Strenge und fordernde Ausbildung bekannt ist. Jannok macht eine heitere Bemerkung, um Euch zu beruhigen, dass Ihr nicht in Schwierigkeiten steckt oder zu ihren harten Lektionen herbeizitiert werdet.",al={"wer ist syurna","warum nicht syurna","jannok syurna spruch"}},{q="Was geschieht, nachdem Ihr bei Erion Meldung gemacht habt?",a="Nachdem Ihr Euren Bericht abgeschlossen habt, erteilt Erion Euch seine nächste Aufgabe in der Quest Erions Befehl, die Euch aus Teldrassil entsendet, um Eure operative Reichweite in Kalimdor zu erweitern.",al={"was als nächstes","erion folgequest","quest nach erion schattenflüsterer"}},{q="Welche Art von Arbeit beaufsichtigt Erion?",a="Erion koordiniert Operationen und leitet angehende Schurken in Darnassus an; dabei agiert er als Kontaktmann, der lokale Agenten mit umfassenderen Missionen im gesamten Netzwerk der Allianz verbindet.",al={"ist erion ein schurkenlehrer","erion schattenflüsterer rolle","was macht erion"}},{q="Warum ist ein Kontaktmann der Schurken in der Enklave des Cenarius stationiert?",a="Obwohl die Enklave des Cenarius vor allem für Druiden und Naturverehrung bekannt ist, bieten ihre weitläufigen, schattigen Bäume reichlich Abgeschiedenheit für verstohlenere Akteure, um sich abseits des Tempels des Mondes zu treffen und Geschäfte abzuwickeln.",al={"enklave des cenarius schurke","warum druidengebiet für schurken"}}},fx={["8fe8a3c2"]={q="Warum schickt Euch Jannok Windsang zu Erion?",a="Jannok Windsang überträgt Euch keine eigene Aufgabe, sondern fungiert als Bote. Erion Shadewhisper hat ausdrücklich um Eure Anwesenheit in der Die Enklave des Cenarius gebeten, um Eure Fähigkeiten zu testen und Euch mit fortschreitender Ausbildung über Teldrassil hinaus zu entsenden.",al={"warum schickt jannok mich","jannok windsang motiv","warum zu erion shadewhisper"}}},fp="18,245,24.444.0,19.359.0,41.142.0,36.127.0,31.217.0,38.164.0,37.170.0,57.221.0"}
P.entries["quest:226"] = {n="Wölfe sind uns auf den Fersen",s="Wölfe sind uns auf den Fersen ist eine Allianz-Quest, die von Lars in Svens Lager im westlichen Dämmerwald angeboten wird. Reisende, die mit der Jagd auf die tollwütigen und verhungernden Schreckenswölfe betraut werden, welche die umliegenden Wälder durchstreifen, helfen dabei, unmittelbare Bedrohungen aus der Wildnis zu beseitigen, damit Sven und Lars sich auf ihre Blutrache gegen den Nekromanten Morbent Teufel konzentrieren können.",h="Wölfe sind uns auf den Fersen ist eine Allianz-Quest, die von Lars in Svens Lager im westlichen Dämmerwald...",kw={"schreckenswolf","dämmerwald","blitzbündel","lars","morbent teufel","tollwütiger schreckenswolf","verhungernder schreckenswolf","sven","svens lager"},ang={["class:Hunter"]="Die verzerrte Tierwelt des Dämmerwalds zu zähmen oder zu dezimieren erfordert geschärfte Sinne; diese Schreckenswölfe sind weit verzweifelter und bösartiger als gewöhnliche Waldbestien.",["faction:Alliance"]="Lars zu helfen stabilisiert Svens abgelegenes Lager und sichert einen verbündeten Stützpunkt gegen die untoten Streitkräfte, die den westlichen Dämmerwald heimsuchen."},sec={{t="Ein prekäres Lager",b="Versteckt in den westlichen Hügeln des Dämmerwalds nahe der Grenze zu Westfall unterhalten Sven Yorgen und sein Gefährte Lars einen abgelegenen Außenposten. Da sie abseits von Dunkelhain leben, sind sie zum Überleben vollkommen auf ihre eigene Nahrungssuche und Jagd angewiesen. Doch das Tragen von frischem Wildbret durch diese dunklen Wälder macht Lars zu einem unwiderstehlichen Ziel für die ausgehungerten Raubtiere, die an den schattigen Flussufern und im Unterholz lauern."},{t="Den Wald säubern",b="Die örtlichen Rudel verhungernder und tollwütiger Schreckenswölfe streifen vor allem nördlich und östlich des Lagers in Richtung des Flusses umher. Indem Reisende diese rasenden Bestien dezimieren, beenden sie eine unmittelbare Belagerung von Lars' Jagdbemühungen. Das Ausdünnen der Wölfe befreit beide Männer davon, ständig um ihr tägliches Brot kämpfen zu müssen, sodass sie ihre volle Aufmerksamkeit auf den Nekromanten Morbent Teufel richten können, der weiter östlich lauert."}},faq={{q="Wer ist Lars?",a="Lars ist ein wettergegerbter Überlebenskünstler, der Sven Yorgen in einem kleinen Lager in den Hügeln des westlichen Dämmerwalds unterstützt. Er kümmert sich um die tägliche Jagd und Nahrungssuche des Lagers, während Sven von Rache gegen die finsteren Mächte besessen ist, die die Region bedrohen.",al={"lars","wer vergibt wölfe auf den fersen","questgeber lars"}},{q="Wo streunen die Wölfe herum?",a="Die Schreckenswölfe durchstreifen die Wälder direkt nördlich und östlich von Svens Lager, besonders entlang der Ufer des Flusses, der den Dämmerwald von den Gebieten im Norden trennt.",al={"wolf standort","wo sind tollwütige schreckenswölfe","wo sind verhungernde schreckenswölfe"}},{q="Warum sind die Schreckenswölfe so aggressiv?",a="Die Wildnis des Dämmerwalds hat sich unter einem heraufziehenden Schatten verschlechtert. Wild ist rar, was die Schreckenswölfe an den Rand des Verhungerns treibt, und Seuchen oder finstere Verderbnis haben viele von ihnen tollwütig und rücksichtslos gewalttätig gegenüber jedem gemacht, der frisches Fleisch bei sich trägt.",al={"warum greifen wölfe an","tollwütige wölfe dämmerwald"}},{q="Wer ist Morbent Teufel?",a="Morbent Teufel ist ein mächtiger Nekromant, der vom Friedhof und den Hügeln im Osten aus finstere Künste ausübt. Sven und Lars hegen einen erbitterten Groll gegen ihn und bereiten sich darauf vor, ihn zur Strecke zu bringen, sobald ihre grundlegenden Überlebensbedürfnisse gesichert sind.",al={"morbent teufel","der nekromant","wer ist der nekromant im osten"}},{q="Was sind die Blitzbündel, die Lars als Belohnung vergibt?",a="Blitzbündel sind blendende Lichtvorrichtungen, die von den Bewohnern von Dunkelhain hergestellt wurden. Wohlgesinnte Bewohner spendeten sie an Svens Lager, um seinen Kampf gegen die Untoten und Bestien zu unterstützen, die die Wälder heimsuchen.",al={"blitzbündel","lars belohnung","was ist ein blitzbündel"}},{q="Warum leben Sven und Lars nicht in Dunkelhain?",a="Svens Familie erlitt eine Tragödie, die ihn zu einem verbitterten, getriebenen Selbstjustizler machte. Anstatt Schutz hinter der Nachtwache in Dunkelhain zu suchen, bezogen Sven und Lars Stellung in der Wildnis, um den Schrecken, die die Wälder plagen, persönlich nachzustellen.",al={"warum in einem lager leben","svens lager standort","warum nicht in der stadt"}}},fx={e2641657={q="Warum will Lars, dass die Schattenwölfe getötet werden?",a="Sven und Lars leben isoliert im westlichen Dämmerwald und müssen ihr eigenes Wild jagen, um zu überleben. Jedes Mal, wenn Lars versucht, Fleisch zurück ins Lager zu schaffen, überfallen ihn Rudel ausgehungerter Schattenwölfe. Das Beseitigen der Raubtiere sichert die Lebensmittelversorgung ihres Lagers und gibt ihnen die Freiheit, sich auf die drohende Bedrohung durch den Nekromanten Morbent Fel zu konzentrieren.",al={"warum wölfe töten","lars wölfe motiv","warum braucht lars wolfskills"}},["8ad2a450"]={q="Welche Schattenwölfe streifen durch den westlichen Dämmerwald?",a="Diese bösartigen Bestien streifen durch die Wälder und Flussufer nördlich und östlich von Sven's Camp. Angetrieben von extremer Hungersnot und sich ausbreitender Krankheit sind die hungernden und tollwütigen Schattenwölfe zu rücksichtslosen Aasfressern geworden, die sofort von frischem Fleisch angelockt werden und eine tödliche Gefahr für jeden darstellen, der die westliche Wildnis durchquert.",al={"was sind das für wölfe","hungernde schattenwölfe dämmerwald","tollwütige schattenwölfe"}},["6ca73ecd"]={q="Warum kann Lars sich nicht selbst um die Wölfe kümmern?",a="Lars und Sven sind am äußersten Rand des Gebiets auf sich allein gestellt, weit abseits der Reichweite der The Night Watch oder der Wachen von Sturmwind. Da sie bereits damit beschäftigt sind, sich auf ihren Kampf gegen Morbent Fel vorzubereiten, und kaum die tägliche Jagd bewältigen können, kann es sich Lars einfach nicht leisten, ohne die Hilfe eines Abenteurers gegen ganze Rudel bösartiger Wölfe zu kämpfen.",al={"warum tötet lars die wölfe nicht","warum fragst du mich wegen der wölfe","warum nicht lars"}}},fp="19,311,17.404.0,18.401.0,12.237.0,30.163.0,38.246.0,19.223.0,50.197.0,42.242.0"}
P.entries["quest:2260"] = {n="Erions Befehl",s="Erions Befehl ist eine Vorladung, die an vielversprechende Nachtelfenschurken in Darnassus gerichtet wird. In Anerkennung ihrer aufkeimenden Tarnkünste schickt der Schurkenlehrer Erion Schattenflüsterer sie über das Meer nach Sturmwind, um sich direkt beim Geheimdienst von Sturmwind zu melden.",h="Erions Befehl ist eine Vorladung, die an vielversprechende Nachtelfenschurken in Darnassus gerichtet wird.",kw={"darnassus","erion schattenflüsterer","erions befehl","die altstadt","renzik das messer","schurke","der si:7","sturmwind"},ang={["class:Rogue"]="Diese Vorladung markiert Euren Aufstieg von lokalen Scharmützeln in Kalimdor zur kontinentalen Spionage und tödlichen Ausbildung beim SI:7.",["faction:Alliance"]="Der SI:7 bündelt verdeckte Operationen für die Allianz und stellt sicher, dass talentierte Späher jedes Mitgliedsvolkes dort eingesetzt werden können, wo die Krone sie am dringendsten benötigt.",["race:NightElf"]="Den Schutz von Darnassus und Teldrassil zu verlassen, um den menschlichen Geheimdienstnetzwerken in den steinernen Gassen von Sturmwind zu dienen, bedeutet für Pirscher der Kaldorei oft einen spürbaren Kulturschock."},sec={{t="Eine Vorladung über das Meer",b="Nachtelfenschurken, die im Schatten von Teldrassil agieren, feilen für gewöhnlich unter den wachsamen Augen von Lehrern wie Erion Schattenflüsterer an ihren Fähigkeiten. Wenn ein Agent jedoch außergewöhnliches Talent beweist, spricht sich dies weit über das Geäst des Weltenbaums hinaus herum. Durch Erion spricht der Geheimdienst von Sturmwind – besser bekannt als der SI:7 – eine direkte Einladung aus, über das große Meer in die Hauptstadt der Menschen zu reisen."},{t="Eintritt in den Dienst des SI:7",b="Die Reise ist beschwerlich und führt den Agenten von den nördlichen Ausläufern Kalimdors über die Docks der Dunkelküste oder des Sumpflands bis in die geschäftigen Straßen von Sturmwind. Einmal in der Hauptstadt angekommen, muss der Agent in die Altstadt schlüpfen und sich im Hauptquartier des SI:7 melden. Dort wartet Renzik \"Das Messer\", um den Neuankömmling zu mustern, was die Tür zu fortgeschrittener Spionage, Giftkunde und verdeckten Operationen im Auftrag der Allianz öffnet."}},faq={{q="Wer schickt mich auf diese Mission?",a="Erion Schattenflüsterer, der Schurkentrainer in Darnassus, erteilt Euch diesen Auftrag, nachdem Eure frühen Taten die Aufmerksamkeit von Geheimdienstnetzwerken jenseits des Meeres erregt haben.",al={"questgeber","erion schattenflüsterer","wer gab mir das"}},{q="Warum kontaktiert der Geheimdienst von Sturmwind einen Nachtelfen?",a="Obwohl die Nachtelfen ihre eigenen Schleichtraditionen pflegen, verlässt sich die Allianz bei der Koordination von Spionage und Sabotage stark auf den SI:7. Der Geheimdienst von Sturmwind hält regelmäßig Ausschau nach fähigen Schurken aller Allianz-Völker, um seine operativen Reihen zu verstärken.",al={"warum der si:7","warum sturmwind","warum interessiert das menschen"}},{q="Wo finde ich Renzik 'Das Messer'?",a="Renzik \"Das Messer\" ist im Hauptquartier des SI:7 stationiert, das versteckt im Viertel Die Altstadt von Sturmwind liegt.",al={"standort von renzik","wo ist das messer","renzik finden"}},{q="Ist diese Quest nur für Schurken?",a="Ja. Dies ist eine Klassenquest für Allianzen-Schurken, die dazu dient, in Kalimdor ansässige Agenten zum zentralen Knotenpunkt der Geheimdienstausbildung der Allianz in Sturmwind zu führen.",al={"nur schurke","können andere klassen das machen","ist das eine schurkenquest"}},{q="Was passiert nach dem Treffen mit Renzik?",a="Die Meldung bei Renzik gliedert Euch in die Ausbildungsoperationen des SI:7 in den Östlichen Königreichen ein und bereitet Euch auf spezialisiertes Training sowie verdeckte Einsätze in den Ländern der Menschen vor.",al={"folgequest","was erhalte ich","nach renzik"}},{q="Wie gelangt ein Nachtelf zu diesem Zeitpunkt nach Sturmwind?",a="Ein Reisender muss ein Schiff von Auberdine an der Dunkelküste über das Meer zum Hafen von Menethil im Sumpfland nehmen, die gefährliche Reise durch Loch Modan und Dun Morogh nach Eisenschmiede antreten und mit der Tiefenbahn nach Sturmwind fahren.",al={"wie komme ich nach sturmwind","reise nach sturmwind","weg nach sturmwind"}}},fx={["4c3449b0"]={q="Warum schickt Euch Erion Shadewhisper nach Sturmwind?",a="Erion Shadewhisper handelt auf eine formelle Vorladung des Geheimdienstes von Sturmwind. Euer wachsender Ruf als Schurke hat menschliche Ohren jenseits Das große Meer erreicht und der SI:7 hat ausdrücklich nach Euch gefragt. Erion erkennt, dass die geheime Gilde in Die Altstadt spezialisierte Ausbildung und Ressourcen bietet, die weit über das hinausgehen, was die stillen Schatten von Teldrassil bieten, und drängt Euch, die Gelegenheit zu ergreifen, anstatt isoliert in Darnassus zu bleiben.",al={"warum nach sturmwind schicken","erion shadewhisper motiv","warum erions behest"}}},fp="14,262,24.399.0,28.426.0,29.161.0,53.256.0,34.128.0,30.153.0,34.182.0,57.225.0"}
P.entries["quest:2281"] = {n="Rendezvous im Rotkammgebirge",s="Rendezvous im Rotkammgebirge ist ein Schurkenauftrag der Allianz, der aus dem Geheimdienst-Hauptquartier von Sturmwind entsandt wird. Da der SI:7 weiß, dass es unerfahrenen Rekruten an der nötigen Finesse für gefährliche Feldeinsätze mangelt, schickt er vielversprechende Agenten nach Seenhain, um ihr Handwerk unter erfahrenen Einsatzkräften zu verfeinern.",h="Rendezvous im Rotkammgebirge ist ein Schurkenauftrag der Allianz, der aus dem Geheimdienst-Hauptquartier von...",kw={"seenhain","lucius","rendezvous im rotkammgebirge","renzik das messer","schurkenquest","der si:7","sturmwind"},ang={["class:Rogue"]="Diese Mission markiert den Eintritt eines Schurken in die formelle Feldarbeit des SI:7 und verlagert sein Training von einfachen Diebereien in dunklen Gassen hin zu kalkulierter Staatsspionage.",["faction:Alliance"]="Der Auftrag verdeutlicht die Reichweite des Geheimdienstes von Sturmwind, der unauffällige Agenten in abgelegenen Siedlungen wie Seenhain unterhält."},sec={{t="Eine Frage des Überlebens",b="In den geheimen Hallen des SI:7 in Sturmwind spricht der stellvertretende Befehlshaber Renzik „das Messer“ unverblümt über die Lebenserwartung von Neulingen. Ungeschliffene Einsatzkräfte direkt in feindliche Operationen zu schicken, fordert eher Opfer als brauchbare Aufklärung. Um unnötige Verluste zu verhindern, werden vielversprechende Rekruten nach Osten ins Rotkammgebirge geschickt, um unter Lucius zu trainieren, einem Agenten, der an den Docks am Seeufer stationiert ist."},{t="Augen in Seenhain",b="Seenhain dient als idealer Ausgangspunkt für geheime Ausbildungen. Von Gnollen und Blackrock-Orcs bedrängt, bietet die Grenzstadt reichlich reale Gefahren, während die belebten Stege einem Agenten wie Lucius reichlich Deckung bieten, um die Heimlichkeit, Reflexe und Schlösserknacken-Fähigkeiten eines Schurken zu beurteilen, ohne das Aufsehen der örtlichen Bewohner oder Stadtwachen zu erregen."}},faq={{q="Wer vergibt die Quest Rendezvous im Rotkammgebirge?",a="Renzik „das Messer“, der Goblin-Meisterspion, der im Hauptquartier des SI:7 in Sturmwinds Altstadt operiert, vergibt den Auftrag an Schurken, die sich beim Geheimdienstkommando gemeldet haben.",al={"wer startet rendezvous im rotkammgebirge","questgeber rendezvous im rotkammgebirge","wer gibt quest"}},{q="Wo befindet sich Lucius?",a="Lucius befindet sich an den Holzstegen von Seenhain im Rotkammgebirge und fügt sich unauffällig unter die örtlichen Herumtreiber und Fischer am Wasser ein.",al={"wo ist lucius","lucius standort","lucius finden"}},{q="Warum schickt der SI:7 Schurken ins Rotkammgebirge?",a="Renzik hält unerfahrene Schurken für ungeeignet für heikle Aufklärungsmissionen im Feld. Lucius hat die Aufgabe, ihren rohen Fähigkeiten den letzten Schliff zu verpassen und ihre praktischen Fertigkeiten wie Taschendiebstahl und Schlösserknacken unter Grenzlandbedingungen zu testen.",al={"warum seenhain","zweck von rendezvous im rotkammgebirge","warum rotkammgebirge"}},{q="Was folgt nach dem Abschluss von Rendezvous im Rotkammgebirge?",a="Sich bei Lucius zu melden, führt direkt zu Trainingsübungen, beginnend mit Althers Mühle, wo der Agent angewiesen wird, seine Heimlichkeit und Fingerfertigkeit auf die Probe zu stellen.",al={"folgequest","nachfolgequest rendezvous im rotkammgebirge","nach rendezvous im rotkammgebirge"}},{q="Ist diese Quest für andere Klassen als Schurken verfügbar?",a="Nein. Rendezvous im Rotkammgebirge ist ausschließlich eine Klassenquest für Allianzschurken, die auf die Feldausbildung des SI:7 zugeschnitten ist.",al={"können krieger rendezvous im rotkammgebirge machen","nur für schurken","klassenvoraussetzung"}},{q="Warum arbeitet Renzik für den Geheimdienst von Sturmwind?",a="Obwohl er ein Goblin ist, ist Renzik „das Messer“ ein hochgeschätzter Vertrauter von Meisterspion Mathias Shaw und leitet die Rekrutierung sowie das Training von Agenten tief aus dem Inneren der Festung des SI:7 heraus.",al={"warum ist ein goblin im si7","renzik geschichte","goblin in sturmwind"}}},fx={da1ebf68={q="Warum braucht Renzik mich für diesen Auftrag?",a="Der SI:7 braucht frische Agenten, die in der Lage sind, gefährliche verdeckte Arbeit zu leisten, aber Renzik weiß, dass es im Grunde ein Todesurteil ist, einen ungeschliffenen Schurken direkt in aktive Feldeinsätze zu schicken. Anstatt vielversprechendes Talent zu verschwenden, entsendet er speziell Euch, damit Ihr Euer Handwerk unter Lucius schärfen könnt, bevor Ihr Missionen angeht, die Euer Leben kosten könnten.",al={"warum ich renzik","warum wählt man mich rotkammgebirge","warum zu lucius schicken"}}},fp="19,288,21.416.0,17.368.0,40.178.0,24.146.0,38.227.0,48.172.0,53.101.0,48.175.0"}
P.entries["quest:2282"] = {n="Althers Mühle",s="Althers Mühle ist ein entscheidender Ausbildungsauftrag, der Allianz-Schurken von Lucius in Seenhain erteilt wird. Ausgestattet mit einem Diebeswerkzeug werden die Initianden zu der nahegelegenen Mühle entsandt, um ein von den Schwarzfelsorks überwachtes Gebiet zu infiltrieren, eine verschlossene Kiste zu knacken und ein Zeichen der Diebeskunst zu bergen.",h="Althers Mühle ist ein entscheidender Ausbildungsauftrag, der Allianz-Schurken von Lucius in Seenhain erteilt...",kw={"althers mühle","schwarzfelsorks","seenhain","schlossknacken","lucius","rotkammgebirge","der si:7","diebeswerkzeug","zeichen der diebeskunst"},ang={["class:Rogue"]="Diese Feuertaufe verschafft Euch Euer unverzichtbares Schlossknack-Werkzeug sowie Feldakkreditierungen und stellt Eure Geduld und Heimlichkeit inmitten patrouillierender Schwarzfelsorks auf die Probe.",["faction:Alliance"]="Die Ausbildung spezialisierter Diebe und Infiltratoren am Rande von Seenhain stärkt die Aufklärung der Allianz und behält gleichzeitig die Bewegungen der Schwarzfelsorks genau im Auge."},sec={{t="Eine Prüfung von Anmut und Finesse",b="In Seenhain halten sich Schurkenlehrer nicht mit theoretischen Vorträgen auf, wenn eine verschlossene Kiste die Lektion schneller vermitteln kann. Lucius schickt vielversprechende Agenten die Straße nach Nordosten zu Althers Mühle hinauf und rüstet sie mit ihrem ersten Diebeswerkzeug aus. Um sich ihr offizielles Zertifikat der Diebeskunst zu verdienen, müssen Novizen in die verlassene Mühle schleichen, Lucius' persönliche Schatulle knacken und das darin verborgene Zeichen zurückbringen."},{t="Schatten um die Sägen",b="Obwohl Althers Mühle einst ein gewöhnlicher Holzfäller-Außenposten war, hat sie in jüngster Zeit die gefährliche Aufmerksamkeit der Schwarzfelsorks auf sich gezogen, die ins Rotkammgebirge vordringen. Lucius betrachtet die herannahenden Kriegstreiber voller Freude als zusätzliche Ebene der praktischen Prüfung. Durch feindlich besetztes Gebiet zu schleichen, um unbemerkt Schlösser zu knacken, ist genau die Art von Bewährungsprobe, die der SI:7 von seinen Agenten erwartet."}},faq={{q="Was ist das Ziel des Auftrags bei Althers Mühle?",a="Er dient als praktische Feldprüfung für Allianz-Schurken, die die Kunst des Schlossknackens erlernen. Lucius stellt Euch ein Diebeswerkzeug zur Verfügung und verlangt von Euch, ein bestimmtes Zeichen aus einer verschlossenen Fußkiste zu bergen, um Eure Finesse unter Beweis zu stellen.",al={"warum nach althers mühle","questziel","was bringt diese quest"}},{q="Wer ist Lucius?",a="Lucius ist ein erfahrener Schurkenlehrer, der in Seenhain im Rotkammgebirge tätig ist. Er hat Jahre damit verbracht, schurkische Rekruten auszubilden, die ihm von Kontakten aus der gesamten Allianz geschickt werden, und ihre Heimlichkeit sowie Fingerfertigkeit auf die Probe zu stellen.",al={"wer ist lucius","lucius seenhain","wer vergibt diese quest"}},{q="Wo befindet sich Althers Mühle?",a="Althers Mühle liegt direkt an der Straße etwas nordöstlich und östlich von Seenhain, eingebettet in die Ausläufer vor den höheren Gebirgspässen.",al={"wo ist die mühle","althers mühle standort","wie finde ich althers mühle"}},{q="Warum befinden sich Orks um Althers Mühle?",a="Orks des Schwarzfelsclans sind von den Höhen der Steinwacht und den brennenden Kämmen herabgestiegen, überfallen menschliche Siedlungen und errichten Vorposten im gesamten Rotkammgebirge, einschließlich des Gebiets um die verlassene Mühle.",al={"warum sind orks hier","schwarzfelsorks rotkammgebirge","wer kontrolliert althers mühle"}},{q="Welche Belohnung gewährt Lucius für den Abschluss der Aufgabe?",a="Lucius verleiht Euch das Zertifikat der Diebeskunst und erkennt damit an, dass Ihr die Grundlagen von Zylindern und Dietrichen meistert und nun als voll zertifizierter Feldschurke agieren könnt.",al={"was ist die belohnung","zertifikat der diebeskunst","belohnung für questabschluss"}},{q="Wie fügt sich diese Quest in die Schurkenausbildung der Allianz ein?",a="Schurken in den Gebieten der Allianz werden von Kontaktpersonen wie Mathias Shaws SI:7-Verbindungsmännern in Sturmwind angewiesen, sich mit Lucius in Seenhain zu treffen. Der Auftrag bei Althers Mühle bildet den praktischen Höhepunkt ihrer grundlegenden Feldausbildung.",al={"schurkenquestreihe","si:7-verbindung","folgequest rendezvous im rotkammgebirge"}}},fx={bca91f0e={q="Warum schickt Euch Lucius zu Althers Mühle?",a="Lucius bildet angehende Schurken für die Allianz aus und möchte Eure praktische Finesse unter Druck testen. Indem er eine verschlossene Truhe direkt in der Nähe von Althers Mühle platziert – einem Gebiet, das von Schwarzfelsorks bedrängt wird –, zwingt er Euch, echtes Schlösserknacken in einer feindseligen Umgebung zu demonstrieren, anstatt in einem gemütlichen Klassenzimmer.",al={"lucius motiv","warum will lucius das erledigt haben","warum nach althers mühle schicken"}},["7e02fd2a"]={q="Wofür ist die Marke der Diebeskunst?",a="Die Marke der Diebeskunst ist ein Beweis Eurer Handwerkskunst. Sicher in Lucius' Truhe verschlossen, dient sie als physischer Beweis dafür, dass es Euch gelungen ist, in Althers Mühle einzudringen, das Schloss zu knacken und unentdeckt zu entkommen. Wenn Ihr sie zurückbringt, erhaltet Ihr Lucius' offizielles Zertifikat der Diebeskunst.",al={"nutzen marke der diebeskunst","was ist die marke der diebeskunst","zweck der marke der diebeskunst"}}},fp="13,289,27.415.0,23.376.0,52.231.0,14.228.0,31.143.0,40.223.0,55.174.0,64.236.0"}
P.entries["quest:23"] = {n="Ursangus' Tatze",s="Diese Quest dient als Beweis für die Erlegung von Ursangus, einem der wildesten und legendärsten Raubtiere, die Eschental durchstreifen. Wenn Ihr die abgetrennte Tatze der Bestie zu Senani Donnerherz am Splitterholzposten bringt, erntet Ihr Ehre unter den Spähern der Horde und deckt eine subtile Verbindung zwischen dem großen Bären und den hiesigen Nachtelfen auf.",h="Diese Quest dient als Beweis für die Erlegung von Ursangus, einem der wildesten und legendärsten Raubtiere...",kw={"eschental","jagd in eschental","bär","halbmondemblem","tatze","senani donnerherz","splintertreeposten","ursangus"},ang={["class:Hunter"]="Das Aufspüren und Besiegen eines der ältesten und tödlichsten Raubtiere von Eschental ist eine erstklassige Prüfung für Feldkunde, Überlebensinstinkt und Kampfgeschick.",["faction:Horde"]="Die Jäger der Horde betrachten Ursangus als gefährliche Beute, deren Niederlage am Splitterholzposten Ehre einbringt.",["race:Tauren"]="Für Taurenjäger ist das Nehmen von Ursangus' Tatze eine heilige Angelegenheit, um das Tier zu ehren und gleichzeitig kriegerische Entschlossenheit und Respekt für die Geister der Jagd zu zeigen."},sec={{t="Eine Trophäe der Großen Jagd",b="Im Rahmen der Jagd in Eschental haben die vom Splitterholzposten aus operierenden Späher den Auftrag, die uralten Bestien zu jagen, die das dichte Blätterdach des Waldes beherrschen. Ursangus zählt zu den furchterregendsten dieser Spitzenprädatoren, bekannt dafür, zahlreiche Reisende und Krieger getötet zu haben, die seinen Weg kreuzten. Eine solche Bestie zur Strecke zu bringen ist keine geringe Leistung, und die Tatze zu beanspruchen dient als unbestreitbarer physischer Beweis dafür, dass das mächtige Geschöpf endlich seinen Meister gefunden hat."},{t="Die Verbindung zu den Nachtelfen",b="Bei genauerer Betrachtung von Ursangus' Tatze ist ein kleines viertelmondförmiges Emblem zu erkennen, das in das Fleisch geschnitzt oder gebrannt wurde. Wenn Ihr es Senani Donnerherz präsentiert, identifiziert sie dieses Zeichen eindeutig als kaldoreiischen Einfluss. Die Nachtelfen trainieren und verbinden sich oft mit den furchterregenden Bestien des Waldes, um ihre heiligen Grenzen zu verteidigen. Das bedeutet, dass Ursangus wahrscheinlich mehr als nur ein wildes Raubtier war – er diente als unwissender Wächter oder Waffe der Allianz."}},faq={{q="Was ist Ursangus?",a="Ursangus ist ein außerordentlich massiver und tödlicher Bär, der die Wälder von Eschental durchstreift. Er wird von Jägern und Wanderern gleichermaßen gefürchtet und hat unzählige Leben gefordert, bevor er der Jagd der Horde zum Opfer fiel.",al={"wer ist ursangus","ursangus bär","ursangus hintergrundgeschichte"}},{q="Was bedeutet das Mondsichelemblem auf der Tatze?",a="Das viertelmondförmige Emblem ist ein Rätsel, wenn Ihr die Trophäe untersucht. Senani Donnerherz kann es begutachten, wenn Ihr die Tatze abliefert.",al={"halbmondzeichen auf tatze","tatzensymbol","warum gibt es einen halbmond"}},{q="Wem bringe ich Ursangus' Tatze?",a="Die Tatze muss zu Senani Donnerherz gebracht werden, der Taurenjägerin, die am Splitterholzposten im östlichen Eschental stationiert ist.",al={"wo gebe ich die tatze ab","wer will ursangus tatze","senani donnerherz standort"}},{q="Wie passt dies in die Jagd im Eschental?",a="Ursangus ist eines von drei großen Tieren, die im Rahmen der Jagd in Eschental ins Visier genommen werden, neben Shadumbra und Sharptalon. Alle drei zu besiegen und ihre Trophäen zu präsentieren ist erforderlich, um das gesamte Ritual abzuschließen.",al={"jagd in eschental questreihe","was ist die jagd","jagdquestreihe"}},{q="Warum jagt die Horde die großen Bestien von Eschental?",a="Die Jäger der Horde, insbesondere die Tauren und Orcs am Splitterholzposten, jagen diese Spitzenprädatoren sowohl, um ihre kriegerischen Fähigkeiten zu testen, als auch um die tödlichsten Bedrohungen in der Nähe ihrer verwundbaren Versorgungslinien und Lager zu dezimieren.",al={"warum bären jagen","splintertreeposten jagdhintergrund"}},{q="Was passiert nach der Abgabe der Tatze?",a="Sobald Ihr die Trophäen von Ursangus und den anderen bestimmten Zielen gesammelt habt, wird Senani Donnerherz Euren Triumph in der abschließenden Prüfung, Die Jagd ist abgeschlossen, anerkennen.",al={"nächste quest nach tatze","was folgt auf ursangus"}}},fp="15,321,26.441.0,24.456.1,18.193.0,46.130.0,34.122.0,42.198.0,55.224.0,38.177.0"}
P.entries["quest:230"] = {n="Svens Lager",s="Svens Lager ist eine Allianzquest im Dämmerwald, die einen entscheidenden Hinweis auf die Tragödie auf dem Hof der Yorgens aufdeckt. Indem Abenteurer ein vergrabenes, unbetiteltes Tagebuch aus einem Erdhaufen auf dem verlassenen Hof ausgraben, setzen sie zusammen, wer Zeuge des Massakers an Sven Yorgens Familie war.",h="Svens Lager ist eine Allianzquest im Dämmerwald, die einen entscheidenden Hinweis auf die Tragödie auf dem...",kw={"dunkle reiter","dämmerwald","erdhaufen","schattengestalt","sven yorgen","hof der yorgens"},ang={["faction:Alliance"]="Die Untersuchung des Yorgen-Massakers ist Teil des umfassenderen Kampfes der Allianz, die dunklen Mächte zu verstehen, die den Dämmerwald bedrohen."},sec={{t="Ein Hinweis in der Erde",b="Sven Yorgen wurde von dunklen Reitern von seinem Hof vertrieben und kehrte nur zurück, um seine Familie ermordet und seinen Hof in Trümmern vorzufinden. Von Trauer und Rache verzehrt, schickte er Verbündete los, um die Trümmer des Gehöfts zu durchsuchen. Verborgen unter einem Haufen frisch aufgeworfener Erde lag ein kleines, schmutzbeflecktes Buch begraben, das im Chaos zurückgelassen worden war."},{t="Ein stiller Zeuge",b="Als das Buch zu Sven in sein Lager in den westlichen Hügeln gebracht wird, enthüllt es ein erschreckendes Detail. Es beweist, dass eine Schattengestalt beobachtet hatte, wie sich das grausame Massaker an seiner Familie abspielte. Anstatt Sven Frieden zu bringen, lenkt das Tagebuch seine Trauer darauf, diesen unbekannten Beobachter zu finden und Antworten zu verlangen."}},faq={{q="Was ist das im Erdhaufen gefundene Buch?",a="Es ist ein unbetiteltes, schmutzbeflecktes Tagebuch, das auf dem Hof der Yorgens vergraben war. Seine Einträge beweisen, dass ein unbekannter Beobachter das Massaker an Sven Yorgens Familie mitangesehen hat.",al={"welches buch ist das","buch von svens hof","was habe ich ausgegraben"}},{q="Wohin führt diese Quest als Nächstes?",a="Die Übergabe des Buches an Sven Yorgen führt direkt zur Quest 'Die Schattengestalt', womit die Suche nach dem geheimnisvollen Zeugen beginnt.",al={"wie geht es weiter","folgequest nach svens lager","wer ist die schattengestalt"}},{q="Wo befindet sich Sven Yorgen?",a="Sven hat in einem Lager in den nordwestlichen Hügeln des Dämmerwalds Zuflucht gesucht, wo er über das Schicksal seiner Familie nachgrübelt und seine Vergeltung plant.",al={"wo ist sven","sven yorgen aufenthaltsort","wo gebe ich das ab"}},{q="Warum war das Buch auf dem Hof vergraben?",a="Das Buch wurde in einem Erdhaufen inmitten des zerstörten Gehöfts versteckt, entweder hastig weggeworfen oder von dem Beobachter verborgen, der am Ort des Angriffs verweilt hatte.",al={"warum vergraben","wer versteckte das buch","erdhaufen"}},{q="Wer hat Svens Familie getötet?",a="Geheimnisvolle, dunkle Reiter wüteten auf dem Hof, schlachteten Svens Angehörige ab und verwandelten das einst friedliche Gehöft in eine von Untoten heimgesuchte Ruine.",al={"wer griff den hof an","wer tötete svens familie","mörder von svens familie"}},{q="Welche Fraktion kann diese Quest abschließen?",a="Diese Quest ist exklusiv für Allianzspieler, da Sven Yorgen nur bei den Verteidigern des Dämmerwalds und der Allianz um Hilfe bittet.",al={"nur für allianz","kann horde svens lager annehmen"}}},fp="11,291,18.318.0,16.303.1,44.160.0,32.135.0,29.144.0,36.168.0,25.144.0,37.123.0"}
P.entries["quest:2300"] = {n="Der SI:7",s="Diese Direktive beordert vielversprechende junge Schurken aus dem Wald von Elwynn direkt in das Herz von Sturmwinds verdecktem Geheimdienstnetzwerk. Von Keryn Sylvius in Goldhain angewiesen, erhalten Agenten den Befehl, sich unverzüglich bei Renzik \"Das Messer\" in der Altstadt zu melden. Dieser Vorladung Folge zu leisten, führt einen Agenten direkt in den Dienst unter Meister Mathias Shaw.",h="Diese Direktive beordert vielversprechende junge Schurken aus dem Wald von Elwynn direkt in das Herz von...",kw={"keryn sylvius","mathias shaw","die altstadt","renzik das messer","schurke","späherkuppe","der si:7","sturmwind"},ang={["class:Rogue"]="Diese Vorladung markiert Euren Übergang von einem Schurken, der Gelegenheitsjobs erledigt, zu einem anerkannten Agenten für Sturmwinds offiziellen Geheimdienst.",["faction:Alliance"]="Der SI:7 dient als der verdeckte Schild der Allianz und wickelt gefährliche Spionageoperationen ab, die reguläre Marschälle und Infanterie nicht öffentlich durchführen können."},sec={{t="Eine Vorladung in die Altstadt",b="Aus dem Gasthaus \"Zur Höhle des Löwen\" in Goldhain heraus behält der Schurkenlehrer Keryn Sylvius lokale Rekruten im Auge. Sobald ein Schurke ausreichend Schläue und Kompetenz gegen die aufkeimende Bedrohung durch die Defias beweist, überbringt Sylvius eine Botschaft aus dem Hauptquartier. Die Vorladung ist kurz und formlos: Meldet Euch unverzüglich bei Renzik \"Das Messer\". Die Felder von Elwynn hinter sich lassend, wird der Agent direkt in das verdeckte Herz der Hauptstadt geschickt."},{t="Sturmwinds verborgene Augen",b="Verborgen hinter der Fassade einer unscheinbaren Kaserne in der Altstadt liegt das Hauptquartier des SI:7, Sturmwinds führender Geheimdienst. Unter dem Befehl von Meister Mathias Shaw leitet der SI:7 verdeckte Operationen, Aufklärung und Attentate im gesamten Königreich und darüber hinaus. Renzik \"Das Messer\", Shaws scharfzüngiger Stellvertreter, überprüft vielversprechende Feldagenten persönlich, bevor er sie auf riskante Operationen ansetzt, an die sich das reguläre Militär des Königreichs nicht heranwagen darf."}},faq={{q="Wer schickt mich zur Meldung beim SI:7?",a="Keryn Sylvius, der Schurkenlehrer im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, erteilt Euch die Direktive. Sobald Ihr Eure Kompetenz im Einsatz bewiesen habt, leitet Sylvius Befehle weiter, die Euch anweisen, Euch im Hauptquartier in Sturmwind zu melden.",al={"wer vergibt quest","questgeber","keryn sylvius"}},{q="Wer ist Renzik \"Das Messer\"?",a="Renzik \"Das Messer\" ist ein Goblin-Agent, der als Stellvertreter des SI:7 fungiert und direkt unter Meister Mathias Shaw arbeitet. Er beurteilt Feldagenten und koordiniert verdeckte Geheimdienstaufträge vom Hauptquartier des SI:7 in der Altstadt aus.",al={"renzik das messer","wer ist renzik","renzik"}},{q="Was ist der SI:7?",a="Der SI:7 – kurz für Stormwind Intelligence, Section 7 – ist der verdeckte Zweig für Spionage, Aufklärung und Attentate des Königreichs Sturmwind. Unter der Führung von Mathias Shaw sammeln seine Agenten Informationen über Bedrohungen der Krone, denen herkömmliche Wachen und Soldaten nicht begegnen können.",al={"was ist der si7","was macht der si7","sturmwind geheimdienst"}},{q="Wo befindet sich das Hauptquartier des SI:7?",a="Das Hauptquartier des SI:7 liegt im östlichen Teil von der Altstadt in Sturmwind. Es operiert aus einem befestigten Gildenhaus samt Ausbildungskaserne, abseits der Hauptstraßen gelegen.",al={"wo ist der si7","si7 standort","wo ist renzik"}},{q="Was passiert nach der Meldung bei Renzik?",a="Sobald Ihr Euch bei Renzik meldet, prüft er Eure Einsatzbereitschaft, bevor er Euch eine Feldmission jenseits der Stadtmauern zuweist und Euch losschickt, um einen im Rotkammgebirge stationierten Agenten zu treffen.",al={"folgequest","was kommt danach","rendezvous im rotkammgebirge"}},{q="Warum nennt mich Keryn Sylvius 'Fisch'?",a="Es ist ein Slangausdruck für einen unerprobten Neuling oder Rekruten. Agenten innerhalb der Organisation nutzen bildhafte, raue Spitznamen, um Neulinge auf dem Boden der Tatsachen zu halten, bis sie sich bei echten Aufträgen bewiesen haben.",al={"warum fisch genannt","bedeutung fisch"}}},fx={d2c94cb8={q="Warum schickt mich Keryn Sylvius zum SI:7?",a="Keryn Sylvius handelt auf Befehle von ganz oben. Renzik \"Das Messer\" hat ausdrücklich Nachricht geschickt, dass er nach Euch sucht, und Keryn weiß, dass es besser ist, eine Vorladung von Mathias Shaws Stellvertreter nicht zu ignorieren. In der verdeckten Hierarchie des Geheimdienstes von Sturmwind geben Vermittler wie Keryn den Befehl sofort weiter, wenn Renzik nach einem Agenten verlangt, ohne das Hauptquartier warten zu lassen.",al={"warum schickt keryn mich","keryn sylvius motiv","warum an si7 melden"}},fe886311={q="Warum braucht der SI:7 mich anstelle ihrer eigenen Agenten?",a="Renzik \"Das Messer\" hat ausdrücklich namentlich nach Euch gefragt. Als aufstrebender Schurke, der innerhalb des Netzwerks der Allianz arbeitet, stellt Ihr frisches Talent dar, das außerhalb des unmittelbaren Blickfelds lokaler Gegner agiert. Meister Shaw und Renzik verlassen sich häufig auf fähige, neu bewährte Feldagenten, um diskrete Aufträge im ganzen Königreich zu übernehmen, bei denen erfahrene, bekannte Gesichter unerwünschte Aufmerksamkeit erregen könnten.",al={"warum ich si7","warum will renzik mich","warum nach mir rufen"}}},fp="4,339,21.429.0,23.473.0,31.223.0,25.240.0,13.281.0,39.184.0,39.170.1,38.192.0"}
P.entries["quest:233"] = {n="Postbeförderung im Eisklammtal",s="Postbeförderung im Eisklammtal ist eine einfache Kurieraufgabe, die Rekruten von Sten Starkarm bei Ambossar anvertraut wird. Da die Gebirgspässe oft von Schnee verweht sind und Troggs in der Nähe drängen, hält die Überbringung frischer Korrespondenz zu den Lagern am gefrorenen See die abgelegenen Verteidiger des Tals miteinander in Verbindung.",h="Postbeförderung im Eisklammtal ist eine einfache Kurieraufgabe, die Rekruten von Sten Starkarm bei Ambossar...",kw={"ambossar","das coldridgetal","dun morogh","grelin weißbart","postbeförderung","sten starkarm","talin keeneye"},ang={["faction:Alliance"]="Jeder Außenposten im Coldridgetal trägt dazu bei, Dun Morogh zu sichern, was eine zuverlässige Korrespondenz für eine frühzeitige militärische Koordination unerlässlich macht.",["race:Dwarf"]="Das Überbringen von Nachrichten zwischen den Außenposten unterstreicht die gemeinschaftliche Entschlossenheit der Zwerge von Eisenschmiede und sorgt dafür, dass selbst weit entfernte Späher im Tal mit ihren Clans verbunden bleiben.",["race:Gnome"]="Als Gäste und Verbündete in Dun Morogh nach dem Fall von Gnomeregan stärkt die Unterstützung bei der Aufrechterhaltung der Kommunikationslinien das Vertrauen zu den örtlichen zwergischen Verteidigern."},sec={{t="Ein Kurier im Schnee",b="Das Leben im Coldridgetal ist selbst in den ruhigsten Jahreszeiten abgeschieden. Wenn Winterkuriere den Gebirgspass mit Post aus dem restlichen Dun Morogh erfolgreich überwinden, stapeln sich die Schriftstücke in Ambossar schnell. Sten Starkarm, der mit der örtlichen Versorgung und Sicherheit beschäftigt ist, verlässt sich auf umherziehende Rekruten, um diese Bündel die westliche Straße hinabzutragen, anstatt wichtige Neuigkeiten in der Halle liegenzulassen."},{t="Grenzaußenposten",b="Der vorgesehene Empfänger, Talin Keeneye, hält am gefrorenen See im Westen Wache und beobachtet Trogg-Bewegungen sowie gefährliche Wildtiere. Selbst draußen in der Kälte bleiben Nachrichten aus Eisenschmiede und den umliegenden Außenposten kostbar. Allerdings ist das Sortieren der Post unter den rauen Gebirgsbedingungen selten fehlerfrei, und Briefe für verschiedene Späher reisen oft gemeinsam in einem einzigen Bündel."}},faq={{q="Wer startet die Postbeförderung?",a="Sten Starkarm gibt Euch die Zustellungsaufgabe vor Ambossar. Er hat einen Stapel Briefe erhalten, der frisch durch den Gebirgspass gebracht wurde, kann es sich jedoch zeitlich nicht leisten, seine Pflichten persönlich zu verlassen, um sie auszutragen.",al={"questgeber","wer gibt postbeförderung im coldridgetal","sten starkarm quest"}},{q="Wo befindet sich Talin Keeneye?",a="Talin Keeneye hat sein Lager westlich von Ambossar aufgeschlagen, direkt an der Straße neben dem gefrorenen See im Coldridgetal.",al={"wo ist talin keeneye","talin keeneye aufenthaltsort","talin keeneye finden"}},{q="Sind alle Briefe auf dem Stapel tatsächlich für Talin bestimmt?",a="Nein. Als Talin das Bündel durchsieht, entdeckt er, dass einer der Briefe an Grelin Weißbart adressiert ist, der in der Nähe im Tal stationiert ist.",al={"ist die ganze post für talin","grelin weißbart brief","fehlgeleitete post"}},{q="Warum braucht Sten einen Abenteurer, um die Post zu überbringen?",a="Da Ambossar aktiv mit Trogg-Übergriffen und lokalen Bedrohungen zu kämpfen hat, sind zwergische Verteidiger wie Sten durch dringende logistische und verteidigungstechnische Pflichten gebunden. Vorbeireisende und junge Rekruten bieten den schnellsten Weg, um Briefe zu den entlegenen Posten zu bringen.",al={"warum post ausliefern","warum liefert sten sie nicht aus","postbeförderungspflicht"}},{q="Führt diese Quest zu weiteren Aufgaben?",a="Ja. Nach Abschluss der Zustellung bittet Talin Euch im zweiten Teil der Postbeförderungsreihe, den fehlgeleiteten Brief zu Grelin Weißbart zu bringen.",al={"folgequest","post-questreihe","fortsetzung der postbeförderung"}},{q="Woher stammten die Briefe ursprünglich?",a="Die Briefe kamen durch den Pass, der in das Coldridgetal führt, und wurden aus den weiteren Landen von Dun Morogh und Eisenschmiede in das geschützte Becken geschickt.",al={"woher kam die post","ursprung der briefe"}}},fx={bf556c8e={q="Warum will Sten Starkarm, dass die Briefe zugestellt werden?",a="Ein frisches Bündel Korrespondenz ist gerade über den Gebirgspass eingetroffen, aber Sten ist in Ambossar an seine eigenen Pflichten gebunden und kann nicht weggehen, um sie selbst auszutragen. Anstatt wichtige Nachrichten und Depeschen verstauben zu lassen, während Gebirgsjäger draußen im Feld auf Nachricht warten, verlässt er sich darauf, dass ein hilfreicher Reisender sie sicher die Straße hinunterbringt.",al={"warum briefe zustellen","sten starkarm motiv","warum post schicken"}}},fp="30,297,21.405.0,17.372.0,29.210.0,31.118.0,52.151.1,49.265.0,36.148.1,43.146.0"}
P.entries["quest:234"] = {n="Postbeförderung im Eisklammtal",s="Diese Besorgung schließt einen Kurierlauf durch die schneebedeckten Weiten des Coldridgetals ab. Die Weiterleitung der Depesche von Gebirgsjäger Talin Keeneye über die südöstliche Straße stellt sicher, dass Grelin Weißbart mit der Zwergenhauptstadt in Verbindung bleibt.",h="Diese Besorgung schließt einen Kurierlauf durch die schneebedeckten Weiten des Coldridgetals ab.",kw={"das coldridgetal","kurier","dun morogh","grelin weißbart","eisenschmiede","postzustellung","talin keeneye"},ang={["faction:Alliance"]="Zuverlässige Kurierrouten durch tückische Schneepässe versorgen abgelegene Späher der Allianz mit Befehlen und lebenswichtigen Informationen.",["race:Dwarf"]="Jeder Außenposten in Dun Morogh verlässt sich auf Depeschen von König Magnis Thron in Eisenschmiede, um die Verteidigung des Reiches zu koordinieren."},sec={{t="Eine Verbindung zum Berg",b="Selbst in einem abgelegenen Kessel wie dem Coldridgetal müssen Neuigkeiten und formelle Korrespondenz ihren Weg finden. Während Ambossar als administratives Herz des Tals dient, sind die entlang der Pfade stationierten Kundschafter und Wachtposten auf Fußkuriere angewiesen, um Depeschen zwischen den Hochpässen und Eisenschmiede weiterzuleiten."},{t="Nachricht für Whitebeard",b="Grelin Weißbart unterhält ein kleines Lager an der Straße südöstlich von Talin Keeneyes Posten. Die an diesen abgelegenen Wachposten stationierten, erfahrenen Gebirgsjäger trotzen eisigen Schneewehen sowie ständigen Übergriffen der Troggs und sind auf regelmäßige Schreiben angewiesen, um über die allgemeinen Ereignisse in Dun Morogh und dem restlichen Königreich informiert zu bleiben."}},faq={{q="Wer ist Grelin Weißbart?",a="Grelin Weißbart ist ein zwergischer Veteran, der an einem Außenposten an der südöstlichen Straße des Coldridgetals stationiert ist. Er überwacht die Straßen des Tals und hält Ausschau nach lokalen Bedrohungen wie vordringenden Troggs und Bestien.",al={"grelin","grelin weißbart info","wer ist grelin"}},{q="Woher stammt dieser Brief?",a="Der Brief wurde aus der Zwergenhauptstadt Eisenschmiede abgesandt. Er gelangte in das Coldridgetal und wurde von lokalen Läufern und Wachposten über die Bergpässe getragen, bevor er seinen endgültigen Empfänger erreichte.",al={"woher stammt der brief","eisenschmiede brief","briefabsender"}},{q="Warum wird die Post hier zu Fuß zugestellt?",a="Das Coldridgetal ist von steilen, frostigen Gipfeln umgeben und von den Hauptstraßen von Dun Morogh abgeschnitten. Da keine Greifenrouten die abgelegenen Feldlager direkt anfliegen, überbringen vertrauenswürdige Reisende und Gebirgsjäger die Depeschen zwischen den Außenposten von Hand.",al={"warum fusskurier","warum postbote","keine briefkästen im coldridgetal"}},{q="Wo befindet sich das Lager von Grelin Weißbart?",a="Sein Lager liegt weiter unten an der südöstlichen Straße, die durch das Coldridgetal führt, hinter den Jagd- und Spähgründen des oberen Passes.",al={"wo ist grelins lager","grelin weißbart aufenthaltsort","grelin finden"}},{q="Wer hat den Brief zur Übergabe an Grelin überreicht?",a="Talin Keeneye, ein erfahrener Jäger und Kundschafter am Pass, übergab das Schreiben, nachdem es vom primären Sammelpunkt nahe Ambossar hergebracht worden war.",al={"wer gab den brief","talin keeneye rolle","wer startet quest"}},{q="Was geschieht, nachdem Grelin seine Post erhalten hat?",a="Sobald Grelin die Neuigkeiten aus Eisenschmiede erhalten hat, widmet er seine Aufmerksamkeit den dringenden Gefahren, die das Tal bedrohen, und weist Rekruten oft an, bei der Abwehr der lokalen Übergriffe von Frostmähnentrollen und Troggs zu helfen.",al={"was folgt nach der post","grelin nächste quest","nach der postzustellung"}}},fx={c573251b={q="Warum will Talin Keeneye, dass dies erledigt wird?",a="Talin Keeneye ist draußen in der Kälte entlang der Straße stationiert und weiß, dass Grelin Weißbart ohne Nachrichten in seinem Lager gewartet hat. Nachdem er die Depesche aus Ambossar entgegengenommen hat, möchte Talin sicherstellen, dass sein Zwergenkamerad endlich seine Korrespondenz aus Eisenschmiede erhält, anstatt ihn gestrandet und uninformiert im Tal zurückzulassen.",al={"warum muss talin das zugestellt haben","talin keeneye motiv","warum brief an grelin schicken"}},d47c3713={q="Warum bittet Euch Talin Keeneye, den Brief zuzustellen, anstatt ihn selbst mitzunehmen?",a="Talin Keeneye ist auf der Wache entlang der Straße von Das Coldridgetal stationiert und behält die Pfade und die lokale Tierwelt im Auge. Wenn er seinen Posten verlassen würde, um den ganzen Weg hinunter zu Grelin Weißbarts Lager zu wandern, bliebe der Pass unbewacht, was einen vorbeireisenden Reisenden wie Euch zur natürlichen Wahl macht, um den Brief den Rest des Weges zu tragen.",al={"warum braucht talin mich","warum kann talin den brief nicht zustellen","warum ich talin"}}},fp="30,230,22.291.0,19.316.0,25.214.0,32.205.0,35.246.0,42.146.0,47.173.0,44.197.0"}
P.entries["quest:235"] = {n="Die Jagd im Eschental",s="Diese von Kriegsrufer Gorlach in Orgrimmar erlassene Weisung ruft angehende Abenteurer der Horde nach Norden über das Brachland hinaus in die uralten Wälder von Eschental. Die Spieler werden angewiesen, sich bei Senani Donnerherz am Splitterholzposten zu melden, um an der fortlaufenden Jagd teilzunehmen und die expandierende Grenze der Horde zu verstärken.",h="Diese von Kriegsrufer Gorlach in Orgrimmar erlassene Weisung ruft angehende Abenteurer der Horde nach Norden...",kw={"eschental","brachland","gorlach","jagd","orgrimmar","senani","splintertree","thunderheart"},ang={["class:Hunter"]="Eschentals dichte Baumkronen und gefährliche Bestien bieten das ultimative Wildnis-Prüffeld für aufstrebende Fährtenleser, die dem Ruf von Senani Donnerherz folgen.",["faction:Horde"]="Der Marsch nach Eschental stellt auf die Probe, ob die neu vereinte Horde über die trockenen Felsen von Durotar hinaus in ressourcenreichen, doch feindseligen fremden Boden expandieren kann.",["race:Tauren"]="Der Dienst unter Senani Donnerherz erlaubt es Taurenabenteurern, ihre tiefe Ehrfurcht vor der großen Jagd in den ungezähmten nördlichen Wald einzubringen."},sec={{t="Ruf der Wildnis",b="Orgrimmar summt vor kriegerischem Eifer, doch die junge Stadt benötigt riesige Mengen an Holz, Fleisch und gesicherten Handelsrouten, um ihr Wachstum aufrechtzuerhalten. Kriegsrufer Gorlach dient als Stimme des Oberkommandos der Horde und lenkt erfahrene Wanderer wie auch frisches Blut zu aktiven Feldzügen. Für Krieger, die in Durotar und dem Brachland erwachsen werden, stellen die uralten Wälder von Eschental das nächste Prüffeld für Ruhm und Überleben dar."},{t="Eine tückische Grenze",b="Das Überqueren der nördlichen Grenze des Brachlands führt Reisende direkt nach Eschental, wo die Horde zwei primäre Bastionen unterhält: den Splitterholzposten, eingebettet in die östlichen Wälder, und den Außenposten von Zoram'gar entlang der Westküste. Senani Donnerherz koordiniert die Operationen am Splitterholzposten und organisiert Fährtenleser sowie Jäger, um das von Bestien wimmelnde Blätterdach zu zähmen und die feindseligen Nachtelfenschildwachen zurückzudrängen, die die Ansprüche der Horde anfechten."}},faq={{q="Wer startet diese Quest und wo kann man ihn finden?",a="Kriegsrufer Gorlach bietet diese Quest in Orgrimmar, der Hauptstadt der Horde, an. Er dient als Offizier, der fähige Abenteurer dazu aufruft, Feldzüge jenseits der Grenzen von Durotar aufzunehmen.",al={"questgeber","wo ist gorlach","wer gibt die jagd in eschental"}},{q="Wo befindet sich der Splitterholzposten?",a="Der Splitterholzposten liegt direkt nördlich des Brachlands im östlichen Eschental an der Hauptwaldstraße, die ostwärts in Richtung Azshara verläuft.",al={"splintertree standort","wo ist der splintertreeposten","weg zum splintertreeposten"}},{q="Wer ist Senani Donnerherz?",a="Senani Donnerherz ist eine erfahrene Taurenfährtenleserin, die am Splitterholzposten stationiert ist. Sie leitet die Jagdbemühungen in ganz Eschental und beurteilt Abenteurer, die an den lokalen Prüfungen teilnehmen möchten.",al={"wer ist senani","senani donnerherz aufenthaltsort","abgabe-npc"}},{q="Was ist der Zweck der Jagd in Eschental?",a="Die Jagd ermöglicht es der Horde, Wildbret zu sichern, wertvolle Felle zu erbeuten und Spitzenprädatoren zu beseitigen, die Patrouillen rund um den Splitterholzposten und nahegelegene Holzfällerbetriebe gefährden.",al={"warum in eschental jagen","geschichte die jagd in eschental","ziel der horde in eschental"}},{q="Welche weiteren Außenposten hält die Horde in Eschental?",a="Zusätzlich zum Splitterholzposten unterhält die Horde ein Lager am äußersten westlichen Rand des Waldes am Zoramstrand.",al={"stützpunkte der horde in eschental","posten am zoramstrand","außenposten in eschental"}},{q="Beinhaltet diese Quest irgendwelche Kämpfe?",a="Nein. Diese Quest dient rein als Wegweiserauftrag, der Euch anweist, sicher von Orgrimmar durch das Brachland zu reisen, um Euch bei Senani Donnerherz zu melden.",al={"gibt es kämpfe in dieser quest","muss man kämpfen","einfache abgabe"}}},fx={["70907bc1"]={q="Warum will Kriegsrufer Gorlach, dass Abenteurer ins Eschental geschickt werden?",a="Kriegsrufer Gorlach fungiert als Herold und Rekrutierer in Orgrimmar und ruft eifrige Krieger dazu auf, die Grenzkampagnen der Horde zu unterstützen. Die Horde hat sich mit dem Splitterholzposten und dem Außenposten am Zoramstrand einen Stützpunkt im Eschental geschaffen, aber die Aufrechterhaltung und Verteidigung dieser Präsenz erfordert einen stetigen Strom fähiger Kämpfer. Indem er Euch zur Jagd von Senani Donnerherz schickt, stärkt Gorlach die Nordgrenze und gibt gleichzeitig erprobten Rekruten ein Übungsgelände, um Ehre und Ruhm für die Horde zu gewinnen.",al={"kriegsrufer gorlach motiv","warum ins eschental schicken","warum gorlachs jagd"}}},fp="18,314,17.436.0,22.438.0,48.176.0,27.143.0,27.198.0,42.177.0,53.129.0,35.156.0"}
P.entries["quest:2359"] = {n="Klavens Turm",s="Klavens Turm ist eine verdeckte Infiltrationsmission des SI:7 für Schurken der Allianz in Westfall. Auf der Grundlage von Informationen von Agentin Kearnen müssen Agenten einen Schlüssel stehlen, in einen schwer bewachten Außenposten der Defias einbrechen und unheilvolle Dokumente bergen, die mit unnatürlichen Experimenten in Verbindung stehen.",h="Klavens Turm ist eine verdeckte Infiltrationsmission des SI:7 für Schurken der Allianz in Westfall.",kw={"agentin kearnen","bruderschaft der defias","dämmerwaldtruhe","klaven mortwake","klavens turm","mathias shaw","gifte","der si:7","westfall","zanzil"},ang={["class:Rogue"]="Diese verdeckte Infiltration ist ein prägender Übergangsritus für Schurken der Allianz, der die Beherrschung von Heimlichkeit, Taschendiebstahl, Schlossknacken und das Ausnutzen physischer Schwachstellen des Gegners erfordert.",["faction:Alliance"]="Die Aufdeckung des Defias-Komplotts am Turm zeigt, dass die Rebellen keine bloßen gekränkten Steinmetze sind, sondern gefährliche Verschwörer, die bereit sind, mit Dschungeltrollen und dunkler Alchemie zu paktieren, um das Königreich zu bedrohen.",["race:Human"]="Menschliche Verteidiger von Sturmwind sind entsetzt darüber, dass ihre ehemaligen Landsleute in Westfall zu willenlosen untoten Drohnen verzerrt werden."},sec={{t="Ein Einsatz in Westfall",b="Am südöstlichen Rand von Westfall, nahe dem Fluss und nördlich der Dolchhügel, steht eine einsame Felsnadel aus Stein, die von der Bruderschaft der Defias beansprucht wird. Während die menschlichen Diebe und Banditen der Bruderschaft auf den Ebenen weit verbreitet sind, bemerkte Agentin Kearnen nach wochenlanger heimlicher Überwachung seltsame Entwicklungen. Kürzlich traf eine bizarre Lieferung direkt aus den schattenhaften Wäldern des Dämmerwalds ein, eskortiert von monströsen, verformten Wachen, die gewöhnlichen Wegelagerern in keiner Weise ähneln."},{t="Die Felsnadel und die gespickte Wache",b="Der Turm wird von Klaven Mortwake befehligt und von bizarr veränderten Wachen bewacht, deren Atem schwer und mühsam geht. Unter diesen schlurfenden Wachen befindet sich ein massiver, mit Eisenspitzen gespickter Zombie, der den Turmschlüssel der Defias bei sich trägt. Den Schlüssel zu stehlen erfordert Lautlosigkeit und Finesse, damit ein Agent die Bodenverteidigung umgehen, in die oberen Ebenen der Festung schlüpfen und die mit einem Vorhängeschloss gesicherte Dämmerwaldtruhe aufbrechen kann."},{t="Zanzils Gebräu",b="Das aus der Truhe geborgene persönliche Tagebuch von Klaven Mortwake beschreibt eine düstere Partnerschaft zwischen den Defias, der Venture Company und den Dschungeltrollen des Schlingendorntals. Die Schriften enthüllen, dass der Hexendoktor Zanzil ein alchemistisches Gift entdeckt hat, das mächtig genug ist, um willenlose, gehorsame untote Drohnen zu erwecken. Für Meister Mathias Shaw und den SI:7 offenbart diese Entdeckung die wachsenden Ambitionen der Defias und macht ein fundiertes Verständnis von Giften für seine Agenten unerlässlich."}},faq={{q="Wo befindet sich Klavens Turm?",a="Klavens Turm liegt am südöstlichen Rand von Westfall, nahe dem Fluss und nördlich der Dolchhügel. Er dient der Bruderschaft der Defias als sichere, befestigte Redoute.",al={"klavens turm standort","wo ist klavens turm","defias turm standort westfall"}},{q="Wer ist Agentin Kearnen?",a="Agentin Kearnen ist eine Agentin des Geheimdienstes von Sturmwind, des SI:7. Sie hat wochenlang von einem nahegelegenen Lager aus heimlich Klavens Turm beobachtet, seltsame Lieferungen verfolgt und eine Infiltration geplant.",al={"agentin kearnen","wer gibt klavens turm quest","wer ist der schurke in westfall"}},{q="Was macht die Wachen an Klavens Turm so ungewöhnlich?",a="Anders als die gewöhnlichen menschlichen Banditen der Defias sind die Wachen, die den Turm beschützen, mutierte untote Drohnen. Sie sind geistlose Arbeiter, die durch ein exotisches alchemistisches Gebräu erschaffen wurden, das nach Westfall verschifft wurde.",al={"warum sind wachen zombies","klaven turm wachen","was sind die turmwachen"}},{q="Wie kommen die Defias an untote Diener?",a="Die Defias beschafften sich ein spezielles toxisches Gebräu, das vom Dschungeltroll-Hexendoktor Zanzil im Schlingendorntal zusammengebraut wurde. Durch Vereinbarungen unter Beteiligung der Venture Company wurde dieses Gift importiert, um lebende Versuchspersonen in gehorsame Drohnen zu verwandeln.",al={"wie bekamen defias zombies","warum defias untote haben","zanzil defias verbindung"}},{q="Wer ist Klaven Mortwake?",a="Klaven Mortwake ist ein hochrangiger Aufseher der Defias, der am Turm stationiert ist. Er überwachte den Empfang finsterer Lieferungen aus dem Dämmerwald und führte ein privates Tagebuch, in dem die unheilvolle Alchemie detailliert beschrieben wird.",al={"klaven mortwake geschichte","wer ist klaven mortwake","klaven"}},{q="Warum interessiert sich Mathias Shaw für das geborgene Tagebuch?",a="Meister Mathias Shaw benötigt verwertbare Informationen über die Allianzen der Defias und gefährliche ausländische Agenten. Die Erkenntnis, dass Zanzils Trolle Untot durch Gift hervorrufen können, alarmiert den SI:7 hinsichtlich einer ernsten neuen Bedrohung für Sturmwind und zwingt die Behörde dazu, ihre Agenten gründlich im Umgang mit Giften auszubilden.",al={"warum mathias shaw tagebuch will","si7 zanzil gift","mathias shaw klaven"}}},fx={af44437f={q="Warum will Agentin Kearnen, dass dies erledigt wird?",a="Agentin Kearnen beobachtet Klaven's Tower seit Wochen, um die Defias-Aktivitäten zu verfolgen. Als eine unheimliche Lieferung aus dem Dämmerwald unter der Bewachung unmenschlicher Kreaturen eintraf, wusste sie, dass die Bruderschaft etwas Gefährliches verbarg. Ihre Pflicht gegenüber dem SI:7 ist die Überwachung und Informationsbeschaffung; herauszufinden, was in dieser Truhe verschlossen ist, wird offenlegen, welches finstere Vorhaben die Defias direkt unter der Nase von Sturmwind aushecken.",al={"kearnen motiv","warum braucht agentin kearnen das","kearnen grund"}},["043ff283"]={q="Wofür ist der Turmschlüssel der Defias?",a="Der Turmschlüssel der Defias gewährt Zugang zur schwer befestigten Festung und der darin bewachten Dämmerwaldtruhe. Der Schlüssel, der von einer der grotesken, stacheligen Monstrositäten getragen wird, die den Umkreis patrouillieren, ist Eure einzige Möglichkeit, die Schlösser der Defias zu umgehen und zu untersuchen, was ihre seltsamen Verbündeten nach Westfall geschmuggelt haben.",al={"turmschlüssel der defias","was öffnet klaven's tower","nutzen turmschlüssel"}},d5d17d25={q="Was ist Klaven Jagdrufs Tagebuch?",a="Dieses Tagebuch, das in der Dämmerwaldtruhe oben im Turm verschlossen ist, enthält die Aufzeichnungen und Geheimnisse von Klaven Jagdruf. Es beschreibt, wie die The Defias Brotherhood mit externen Kräften zusammenarbeitete, um abscheuliche Gebräue zu brauen, und enthüllt, dass seltsame Tränke von Zanzils Trollen einen Zustand des lebendigen Todes hervorrufen können, um willenslose Drohnen zu erschaffen.",al={"klaven jagdrufs tagebuch","klavens tagebuch","was steht im tagebuch"}},["738a266c"]={q="Warum schickt Agentin Kearnen Euch an ihrer statt?",a="Agentin Kearnen ist eine Späherin des SI:7, deren Hauptaufgabe langfristige Aufklärung ist. Ihre Tarnung aufzugeben, um einen befestigten Außenposten voller unnatürlicher Wachen zu stürmen, würde ihre Stellung gefährden und die Defias warnen, bevor das SI:7 von deren Plänen erfährt. Sie braucht einen fähigen Agenten, der an den Wachen vorbeischlüpft, die Informationen sichert und sie direkt an Mathias Shaw liefert.",al={"warum ich klaven turm","warum infiltriert kearnen nicht","warum schickt ihr mich"}}},fp="14,279,22.463.0,30.420.1,19.466.2,32.172.0,21.203.0,48.205.1,41.233.1,23.189.0,55.291.1"}
P.entries["quest:237"] = {n="Verteidigung der Länder des Königs",s="Dieser militärische Auftrag verpflichtet Abenteurer der Allianz dazu, im Namen von Gebirgsjäger Gravelgaw eine Troggoffensive im südlichen Loch Modan abzuwehren. Da die regulären Streitkräfte der Zwerge in fernen Feldzügen der Allianz gebunden sind, müssen sich die örtlichen Außenposten auf Freiwillige verlassen, um gefährliche Schädelbrecher und Seher der Splittersteintrogge auszudünnen, bevor das Tal der Könige überrannt wird.",h="Dieser militärische Auftrag verpflichtet Abenteurer der Allianz dazu, im Namen von Gebirgsjäger Gravelgaw...",kw={"gravelgaw","eisenschmiede","loch modan","gebirgsjäger","seher","schädelbrecher","splittersteintrogge","trogge","tal der könige"},ang={["faction:Alliance"]="Diese Mission verdeutlicht den hohen Preis der Kriegsanstrengungen der Allianz: Das Sichern ferner Gebiete hat die Heimatländer ihrer Kernvölker schutzlos gegenüber einheimischen Bedrohungen zurückgelassen.",["race:Dwarf"]="Für einen Zwerg ist die Sicherung des Tals der Könige eine persönliche Angelegenheit: Dieser Boden ehrt die größten Herrscher von Eisenschmiede, und mitanzusehen, wie Trogge ihn entweihen, während das eigene Volk auf fernen Schlachtfeldern verblutet, ist eine bittere Pille."},sec={{t="Eine dünne Verteidigung",b="Die entlang des südlichen Passes nach Dun Morogh stationierten Gebirgsjäger sind gefährlich dünn gesät. Da König Magni Bronzebart beträchtliche zwergische Militärkräfte an die weitläufigere Allianzfront entsandt hat, fehlt es Außenposten wie den Wachtürmen im Tal der Könige an regulärer Infanterie. Gebirgsjäger Gravelgaw ist auf freiwillige Helfer von außerhalb angewiesen, um aggressive Störangriffe im Splittersteintal durchzuführen, die unterirdischen Invasoren in Schach zu halten und Zeit zu gewinnen, während die örtlichen Garnisonen auf Verstärkung warten, die vielleicht niemals eintrifft."},{t="Schamanen und Schläger der Splittersteintrogge",b="Die Splittersteintrogge sind keine geistlosen Bestien, die ziellos umherstreifen; ihre Kriegstrupps koordinieren sich durch rohe Gewalt und primitive Elementarmagie. Gravelgaw nimmt die erfahrenen Kämpfer des Stammes – die Schädelbrecher – sowie ihre mystische Führung, die Seher, ins Visier. Das Ausschalten dieser Frontkommandanten bricht den Schwung des Stammes, stürzt ihre südlichen Lager ins Chaos und verhindert einen massiven Vorstoß auf die Straße nach Eisenschmiede."},{t="Düstere Kunde von der Front",b="Sobald Ihr Euren Erfolg meldet, teilt Gravelgaw ernüchternde Neuigkeiten mit: Die versprochene zwergische Verstärkung wird nicht eintreffen. Schwere Verluste an der fernen Allianzfront haben die Reserven von Eisenschmiede erschöpft, sodass Loch Modan völlig auf die örtlichen Gebirgsjäger und durchreisende Mietsoldaten angewiesen ist, um das Kernland des Königreichs zu schützen."}},faq={{q="Wo befindet sich Gebirgsjäger Gravelgaw?",a="Gebirgsjäger Gravelgaw ist am südlichen Wachturm an der Straße durch das Tal der Könige stationiert und bewacht den Pass, der Loch Modan mit Dun Morogh verbindet.",al={"standort gravelgaw","wo ist gravelgaw","abgabe gravelgaw"}},{q="Warum sind die zwergischen Gebirgsjäger so unterbesetzt?",a="König Magni Bronzebart hat den Großteil des stehenden Heeres von Eisenschmiede an die weiter entfernten Fronten der Allianz im Ausland entsandt. Da andernorts die Verluste steigen, verbleiben an Grenzposten wie jenen in Loch Modan nur noch Rumpfbesatzungen, die auf die Hilfe reisender Freiwilliger angewiesen sind.",al={"warum keine zwergenwachen","wo bleibt die verstärkung","eisenschmiede armee loch modan"}},{q="Wo sind die Schädelbrecher und Seher der Splittersteintrogge zu finden?",a="Sie versammeln sich hauptsächlich in den südlichen Lagern des Splittersteintals östlich des Tals der Könige. Eine kleinere Gruppe von ihnen treibt sich zudem auf der nördlichsten Insel im Loch herum.",al={"standort splittersteinschädelbrecher","standort splittersteinseher","wo sind die trogge"}},{q="Warum geraten gezielt Schädelbrecher und Seher ins Visier?",a="Schädelbrecher fungieren als vorderste Stoßtruppen der Splittersteintrogge, während Seher primitive Magie wirken und die niederen Trogge befehligen. Werden beide Gruppen ausgeschaltet, verliert die Invasionsstreitmacht sowohl ihre Schlagkraft als auch ihre mystische Führung.",al={"warum seher töten","warum schädelbrecher","trogg ziele"}},{q="Wohin schickt Gravelgaw Euch als Nächstes?",a="Gravelgaw schickt Euch zu Gebirgsjäger Wallbang, der im südlichen Wachturm im Tal der Könige stationiert ist, um bei der nächsten Phase der Verteidigung des Tals zu helfen.",al={"folgequest gravelgaw","wer ist wallbang","nach in defense of the king's lands"}}},fx={c78d8208={q="Warum will Gebirgsjäger Gravelgaw, dass dies erledigt wird?",a="Gebirgsjäger Gravelgaw versucht, den Verteidigern von Loch Modan kostbare Zeit zu verschaffen. Die Troggs der Steinbeißer dringen unaufhörlich in das südliche Tal vor, während Zwergentruppen auf fernen Schlachtfeldern der Allianz dringend benötigt werden. Indem er die Invasionsstreitkräfte dezimiert, hofft er, die südlichen Pässe zu sichern, bis Verstärkung aus Eisenschmiede eintreffen kann.",al={"warum troggs töten","gravelgaw beweggrund","in defense of the kings lands beweggrund"}}},fp="30,343,14.495.0,34.424.0,27.317.1,39.164.0,48.259.0,61.203.0,48.228.0,35.163.1"}
P.entries["quest:2378"] = {n="Suche nach der Zerschmetterten Hand",s="Suche nach der Shattered-Hand ist eine Reisequest, die vielversprechende Schurken der Verlassenen aus Tirisfal über das Meer nach Durotar schickt. Auf Anweisung der Todespirscher reist der Initiand in Orgrimmars schattenhafte Schattenseiten, um spezialisierte Künste vom Clan der Shattered-Hand zu erlernen.",h="Suche nach der Shattered-Hand ist eine Reisequest, die vielversprechende Schurken der Verlassenen aus...",kw={"die kluft der schatten","die todespirscher","mennet carkad","orgrimmar","schurkenquest","die shattered-hand","shenthul"},ang={["class:Rogue"]="Diese Quest schlägt eine Brücke zwischen der lokalen Ausbildung und dem breiteren kriminellen sowie verdeckten Netzwerk der Horde und führt Schurken an die primären Unterweltausbilder in Kalimdor heran.",["faction:Horde"]="Die Mission verdeutlicht, dass die Zusammenarbeit der Horde über Frontsoldaten und Schamanen hinausgeht, und zeigt eine tiefe Abstimmung zwischen den Geheimdiensten von Orgrimmar und Unterstadt.",["race:Undead"]="Für junge Schurken der Verlassenen markiert dies den offiziellen Übergang vom Kampf gegen lokale Reste der Geißel in Lordaeron zur Integration in das Kernland der Horde in Durotar."},sec={{t="Ein Bund der Schatten",b="Während die Verlassenen in den Todespirschern ihren eigenen Geheimorden pflegen, eröffnet ihr Bündnis mit der Horde Wege zur Zusammenarbeit in dunkleren Künsten. Nachdem Mennet Carkad miterlebt hat, wie ein Schurke in Tirisfal seinen Wert bewiesen hat, erkennt er die Notwendigkeit einer umfassenderen Ausbildung. Er weist vielversprechende Schatten an, die Shattered-Hand in Orgrimmar aufzusuchen, und stützt sich dabei auf die stille Partnerschaft zwischen Lordaerons untoten Agenten und Kalimdors orkischer Meuchelmördergilde."},{t="In die Kluft der Schatten",b="Die Reise endet tief in der Kluft der Schatten, der unterirdischen Höhle unter Orgrimmar, in der Hexenmeister, Schurken und Dämonenbinder Geschäften nachgehen, die die Bewohner der Oberfläche lieber nicht sehen wollen. Dort wartet Shenthul, ein Ausbilder der Shattered-Hand. Unbeeindruckt von bloßem Ruf mustert der schroffe Troll den neu eingetroffenen untoten Agenten mit harter Skepsis, begierig darauf zu prüfen, ob dieser Gesandte echte Schläue besitzt oder lediglich die Reise über das große Meer verschwendet hat."}},faq={{q="Wer vergibt die Quest Suche nach der Zerschmetterten Hand?",a="Mennet Carkad, ein Ausbilder der Todespirscher im Schurkenviertel von Unterstadt, vergibt die Quest, sobald ein Schurke seine grundlegenden Fähigkeiten in Tirisfal bewiesen hat.",al={"wer startet suche nach der shattered-hand","mennet carkad quest","wer schickt mich nach orgrimmar"}},{q="Wo befindet sich Shenthul?",a="Shenthul befindet sich in der Kluft der Schatten, der finsteren Schlucht unter den zentralen Pfaden von Orgrimmar.",al={"findet shenthul","shenthul standort","wo ist shenthul in orgrimmar"}},{q="In welcher Beziehung stehen die Todespirscher und die Shattered-Hand?",a="Die Todespirscher fungieren als Geheimdienst und Meuchelmördergilde der Verlassenen, während die Shattered-Hand eine ähnliche geheime Rolle für die Horde in Orgrimmar einnimmt. Sie kooperieren als formelle Verbündete und teilen fortgeschrittene Ausbildung sowie geheime Aufträge über die Fraktionen der Horde hinweg.",al={"die todespirscher und die shattered-hand","verlassene schurken ork schurken","warum nach orgrimmar geschickt"}},{q="Warum nennt Shenthul mich uninspirierend?",a="Die Zerschmetterte Hand schätzt körperliche Zähigkeit und rücksichtslose Schläue über alles. Shenthul beleidigt und schmälert Neulinge regelmäßig, um ihren Stolz zu brechen und zu prüfen, ob sie die Entschlossenheit besitzen, eine rigorose Ausbildung zum Meuchelmörder zu überstehen.",al={"shenthul dialog","warum ist shenthul gemein","shenthul abschlusstext"}},{q="Was geschieht, nachdem man Shenthul erreicht hat?",a="Shenthul spannt den Agenten direkt ein, bietet die Quest Zando'zan an und schickt ihn schließlich nach Süden in Richtung Ratschet, um praktische Feldeinsätze im Brachland zu unternehmen.",al={"was kommt nach suche nach der shattered-hand","folgequest nach shenthul","shattered-hand questreihe"}},{q="Können Nicht-Verlassene-Schurken diese Quest annehmen?",a="Nein. Suche nach der Zerschmetterten Hand ist die Variante der Verlassenen, die von den Todespirschern vergeben wird. Ork- und Trollschurken, die in Durotar operieren, erhalten eine gleichwertige Übergangsquest namens 'Auf nach Orgrimmar!'.",al={"ork schurke suche nach der shattered-hand","troll version","alternative auf nach orgrimmar"}}},fx={aa6bb2de={q="Warum möchte Mennet Carkad, dass ich nach Orgrimmar gehe?",a="Mennet Carkad erkennt an, dass Ihr den Deathstalkers zwar gut gedient und Talent in Heimlichkeit und Täuschung bewiesen habt, Eure Entwicklung innerhalb der Unterstadt jedoch vorerst ihre Grenzen erreicht hat. Um Euer tödliches Handwerk weiter zu verfeinern, möchte er, dass Ihr Euch hinaus in die weite Horde wagt. Indem er Euch zum Shattered Hand in Orgrimmar schickt, nutzt Mennet ein Bündnis zwischen den beiden Fraktionen von Assassinen, um sicherzustellen, dass Ihr fortgeschrittene Unterweisung von erfahrenen orkischen Schurken erhaltet, die Euch Techniken lehren können, die in den Schatten von Lordaeron nicht zu finden sind.",al={"warum nach orgrimmar schicken","mennet carkads beweggrund","warum das shattered hand finden"}}},fp="23,266,19.462.0,24.474.0,44.169.0,26.105.0,74.297.0,38.228.0,37.178.0,39.189.0"}
P.entries["quest:2379"] = {n="Zando'zan",s="Dieser Auftrag weist vielversprechende Schurken der Horde an, sich bei Zando'zan tief in Orgrimmars Kluft der Schatten vorzustellen. Entsandt von Ausbilder Shenthul, unternimmt der Initiant die ersten Schritte in die geheimen Ränge und verbotenen Techniken der Shattered-Hand.",h="Dieser Auftrag weist vielversprechende Schurken der Horde an, sich bei Zando'zan tief in Orgrimmars Kluft der...",kw={"die kluft der schatten","schlossknacken","orgrimmar","schurke","shattered-hand","shenthul","verstohlenheit","wrenix","zando'zan"},ang={["class:Rogue"]="Diese Aufgabe markiert Eure formelle Aufnahme in den Geheimapparat der Shattered-Hand und wandelt Euch von einem ungeschulten Messerkämpfer zu einem anerkannten Agenten der Horde.",["faction:Horde"]="Während der Kriegshäuptling oft von Ehre und Frontalangriffen spricht, übernimmt die Shattered-Hand die unverzichtbare Spionage und verdeckte Drecksarbeit, die die junge Horde vor unsichtbaren Bedrohungen schützt."},sec={{t="Ein Schritt in die Schatten",b="Orgrimmar mag wie eine Festung roher Gewalt und kriegerischer Disziplin wirken, doch ihre Herrscher wissen, dass bloße Muskelkraft allein nicht jeden Krieg gewinnen kann. Unten im unterirdischen Dunkel der Kluft der Schatten operiert die Shattered-Hand, die geheime Gilde, die Spionage, Sabotage und Diebstahl für die Horde abwickelt. Wenn der Schurkenlehrer Shenthul entscheidet, dass ein Initiant genügend Potenzial bewiesen hat, schickt er ihn direkt zu Zando'zan, um dort die Ausbildung zum echten Agenten zu beginnen."},{t="Seinen Wert beweisen",b="Zando'zan zollt nicht jedem Grünschnabel unter den Schurken, der in die Höhle hinabsteigt, automatisch Respekt. Ihn aufzusuchen ist eine formelle Initiation in die feineren heimlichen Künste, beginnend mit den heiklen Fertigkeiten der Heimlichkeit, List und Dieberei. Die Begegnung mit Zando'zan schließt die Lücke zwischen einfachen Straßentaschendieben und organisierten Geheimdienstagenten und bereitet den Schurken auf die heikle Feldarbeit jenseits des Schutzes der roten Schluchtwände der Hauptstadt vor."}},faq={{q="Wer ist Zando'zan?",a="Zando'zan ist ein Schurkenlehrer und Verbindungsmann der Shattered-Hand in Orgrimmars unterirdischer Kluft der Schatten. Er beurteilt neue Rekruten und unterweist sie in praktischer Heimlichkeit, Einbruchskunst und dem Handwerk eines Agenten.",al={"zandozan","wer ist zando'zan","zando'zan die kluft der schatten"}},{q="Warum schickt Shenthul Schurken zu Zando'zan?",a="Shenthul erkennt, wann ein angehender Schurke den einfachen Schlägereien entwachsen ist und eine spezialisierte Ausbildung als Agent der Shattered-Hand benötigt. Zando'zan leitet die Lektionen im Einbrechen und Schlossknacken, die für geheime Feldeinsätze unerlässlich sind.",al={"warum mit zando'zan sprechen","shenthul zando'zan","zweck der quest"}},{q="Was ist die Shattered-Hand in Orgrimmar?",a="Ursprünglich ein brutaler Orc-Clan aus Draenor, der für rituelle Selbstverstümmelung bekannt war, hat sich die Shattered-Hand in Durotar zum Arm für Geheimoperationen und Attentate der Horde entwickelt. Sie operiert aus den Schatten Orgrimmars und befasst sich mit Spionage, Giften und Aufklärung.",al={"was ist shattered-hand","shattered-hand orgrimmar","hordeschurken shattered-hand"}},{q="Wohin führt diese Ausbildungsreihe als Nächstes?",a="Nachdem Ihr Euch bei Zando'zan vorgestellt habt, schickt er Euch hinaus nach Ratschet an der Küste des Brachlands, um einen Goblinkontakt namens Wrenix zu konsultieren und die praktische Feldarbeit im Schlossknacken zu beginnen.",al={"folgequest","was kommt nach zando'zan","wrenix aus ratschet"}},{q="Wo kann ich Zando'zan finden?",a="Er lauert in der Kluft der Schatten, dem tiefen Höhlennetzwerk unter dem Zentrum von Orgrimmar, wo sich Hexenmeister, Schattenpriester und Schurkenagenten abseits des Tageslichts versammeln.",al={"zando'zan aufenthaltsort","wo ist zando'zan","zando'zan finden"}},{q="Warum entschuldigt sich Zando'zan, als er mir begegnet?",a="Zando'zan hatte vor Eurer Ankunft wahrscheinlich Bedenken oder zweifelte an Eurem Mut. Zu sehen, dass Ihr bereit zur Ausbildung vor ihm steht, zwingt ihn dazu, Eure Entschlossenheit anzuerkennen und seine anfängliche Skepsis zurückzunehmen.",al={"warum entschuldigt sich zandozan","abschlussdialog zando'zan"}}},fx={["1d4b3aab"]={q="Warum vertraut Shenthul dieses Training Euch anstatt einem anderen Schurken?",a="Shenthul erkennt Eure rohe Entschlossenheit an, weiß aber, dass bloßer Eifer nicht ausreicht, um die verdeckten Schlachten zu überleben, denen die Horde gegenübersteht. Ihr habt Euch als würdig erwiesen, über grundlegende Straßentricks hinauszugehen, aber um The Shattered Hand wirklich zu dienen, müsst Ihr formell zu einem engagierten Agenten geformt werden. Shenthul schickt Euch gezielt, weil Euer Pfad und Euer Potenzial die wachsamen Augen der Gilde auf Euch gezogen haben.",al={"warum ich shenthul","warum schickt mich zandozan","warum bin ich auserwählt"}}},fp="9,249,23.461.0,19.441.0,17.220.0,47.240.0,40.273.0,41.190.1,27.182.0,45.195.0"}
P.entries["quest:2380"] = {n="Nach Orgrimmar!",s="Nach Orgrimmar! ist eine einleitende Vorladung, die einen aufstrebenden Schurken der Horde von Klingenhügel in die Hauptstadt entsendet. Auf Befehl von Kaplak wird der Initiant unter die Oberfläche in die Kluft der Schatten geschickt, um sich vor Shenthul und tiefer im Netzwerk der Shattered-Hand vorzustellen.",h="Nach Orgrimmar!",kw={"die kluft der schatten","kaplak","klingenhügel","schurke","shattered-hand","shenthul","nach orgrimmar"},ang={["class:Rogue"]="Diese Mission markiert Eure offizielle Aufnahme in das verdeckte Netzwerk der Hauptstadt und führt Euch über die primitiven Grenzland-Raufereien hinaus in das Handwerk von Giften, Diebstahl und Täuschung unter Shenthuls Aufsicht.",["faction:Horde"]="Die leise Unzufriedenheit, die Shenthul äußert, verdeutlicht die Reibung zwischen Thralls ehrenhaftem neuem Weg und den finsteren Überresten älterer Clanorganisationen, die unter Orgrimmar überdauern."},sec={{t="Eine Vorladung in die Schatten",b="Nachdem sie sich in ganz Durotar die ersten Sporen verdient haben, erregen unerfahrene Schurken schließlich die Aufmerksamkeit prominenterer Kontaktpersonen. In Klingenhügel stellt Kaplak unverblümt fest, dass die aufkeimenden Talente eines Agenten – wenn auch noch ungeschliffen – Beachtung gefunden haben. Anstatt weiter draußen zwischen den roten Felsen zu verweilen, wird der Agent nach Norden in die höhlenartigen Gassen von Orgrimmar geschickt."},{t="Unter Thralls wachsamen Augen",b="Das Treffen mit Shenthul in der unterirdischen Kluft der Schatten offenbart tiefere Spannungen unter den Gründungsidealen der Horde. Shenthul macht keinen Hehl aus seiner Wachsamkeit gegenüber den politischen Reformen von Kriegshäuptling Thrall. Für die Shattered-Hand reichen rohe Gewalt und offener Trotz niemals aus, um ihre Interessen zu wahren; Überleben und Einfluss verlangen Geduld, Täuschung und ausgefeilte Heimtücke."}},faq={{q="Wer schickt mich auf diese Quest?",a="Kaplak, ein in Klingenhügel stationierter Schurkenlehrer, überbringt die Vorladung, nachdem er festgestellt hat, dass Eure Fähigkeiten die Aufmerksamkeit von Vorgesetzten in Orgrimmar erregt haben.",al={"questgeber","wer vergibt nach orgrimmar","kaplak quest"}},{q="Wo finde ich Shenthul?",a="Shenthul befindet sich in der Kluft der Schatten, dem finsteren unterirdischen Bezirk tief unter Orgrimmar, wo sich Schurken, Hexenmeister und andere Ausgestoßene versammeln.",al={"shenthul aufenthaltsort","wo ist shenthul","die kluft der schatten shenthul"}},{q="Welche Absichten verfolgt die Shattered-Hand in Orgrimmar?",a="Die Zerschmetterte Hand operiert als Spionage- und Attentätergilde innerhalb der Horde. Obwohl sie nominell Teil der neuen Hauptstadt sind, stehen Anführer wie Shenthul den ehrenhaften Reformen Thralls misstrauisch gegenüber und setzen auf Heimlichkeit, um Einfluss und Überleben zu sichern.",al={"motive der shattered-hand","warum shattered-hand in orgrimmar","shattered-hand thrall"}},{q="Warum werde ich genau zu diesem Zeitpunkt entsandt?",a="Unerfahrene Agenten, die sich bei einfachen Erkundungen und Scharmützeln bewähren, werden für formellere Gildenaufgaben herangezogen – beginnend mit dem Knacken von Schlössern und verdeckten Feldeinsätzen, die in der Hauptstadt vergeben werden.",al={"stufe 16 schurkenquest","warum jetzt nach orgrimmar","schurkenausbildung vorladung"}},{q="Unterscheidet sich diese Quest von 'Suche nach der Zerschmetterten Hand'?",a="Beide dienen als einleitende Wegweiser, die Schurken zu Shenthul in Orgrimmar führen; je nachdem, wo Ihr trainiert oder Befehle entgegennehmt, erhaltet Ihr die eine oder die andere Quest, um dieselbe Ausbildungsreihe voranzutreiben.",al={"suche nach der shattered-hand oder nach orgrimmar","alternative hinführungsquest"}},{q="Was passiert nach der Meldung bei Shenthul?",a="Shenthul prüft Eure Fähigkeiten und leitet Euch in der Befehlskette weiter, indem er Euch mit Kontaktpersonen wie Zando'zan und schließlich mit verdeckten Einsätzen rund um Goblin-Kontakte in Ratschet vertraut macht.",al={"folgequest nach orgrimmar","was vergibt shenthul"}}},fx={a9995c5c={q="Warum will Kaplak, dass ich nach Orgrimmar gehe?",a="Kaplak handelt unter direktem Befehl von oben. Während er anerkennt, dass Ihr weit davon entfernt seid, ein wahrer Meister der Heimlichkeit zu sein, haben Eure aufkeimenden Talente die Aufmerksamkeit von Shenthul selbst erregt. The Shattered Hand benötigt gerissene Agenten, die für ihre verdeckte Agenda ausgebildet sind, und Kaplaks Pflicht ist es, vielversprechende Schurken wie Euch in die tieferen Schatten der Hauptstadt zu leiten, wo Eure wahre Ausbildung beginnen kann.",al={"warum schickt mich kaplak","kaplak beweggrund","warum nach orgrimmar"}}},fp="13,301,24.353.0,27.382.1,27.157.0,25.157.0,49.250.0,47.188.0,54.189.0,41.174.0"}
P.entries["quest:2381"] = {n="Das Ausplündern der Plünderer",s="Diese von dem Goblin Wrenix der Jämmerliche in Ratschet vergebene Reifeprüfung stellt einen aufstrebenden Schurken der Horde gegen die Südmeerfreibeuter auf die Probe. Bei der Infiltration des Piratenschiffs Tide Razor müssen Agenten an den Halsabschneidern vorbeischleichen, die Schlösser im Frachtraum knacken und einen monströsen gefiederten Wächter mithilfe von Goblin-Technologie ausschalten, um den Schatz der Südmeerfreibeuter an sich zu bringen.",h="Diese von dem Goblin Wrenix der Jämmerliche in Ratschet vergebene Reifeprüfung stellt einen aufstrebenden...",kw={"r.c.v.k.","schlossknacken","das ausplündern der plünderer","polly","ratschet","südmeerfreibeuter","schatz der südmeerfreibeuter","disteltee","tide razor","wrenix der jämmerliche"},ang={["class:Rogue"]="Diese Reifeprüfung lehrt die grundlegende Kunst, Schlösser unter Druck zu knacken, und belohnt mit dem begehrten Rezept für Disteltee, was sie zu einem unverzichtbaren Meilenstein für jeden Agenten im Dienste der Horde macht.",["faction:Horde"]="Die Zerschmetterte Hand nutzt neutrale Goblin-Verbindungen in Ratschet, um angehende Außendienstagenten gegen die Südmeerfreibeuter auf die Probe zu stellen, die die Küste des Brachlands bedrohen.",["profession:Cooking"]="Die Mission bringt das Kochrezept für Disteltee ein, wodurch kochkundige Schurken ihre eigenen speziellen Energietränke aus einfachen Kräutern und Wasser brauen können."},sec={{t="Eine Prüfung von Heimlichkeit und Stahl",b="Für einen aufstrebenden Agenten der Shattered-Hand bedeutet rohe Muskelkraft ohne Finesse nichts. Wrenix der Jämmerliche, ein in Ratschet ansässiger Goblinkontakt, sorgt für die praktische Prüfung. Er schickt Schurken entlang der sonnenverbrannten Küste des Brachlands nach Süden zu einer Bucht, in der die Tide Razor ankert, ein von Südmeerfreibeutern bemanntes Schiff. Der Auftrag ist trügerisch einfach: Geht unbemerkt an Bord des Schiffes, dringt in den Unterschlupf der Piraten ein, wo sie ihre eigenen Beutelschneider ausbilden, knackt die Schatullen im tiefen Frachtraum und bringt deren wertvolle Beute zurück."},{t="Polly und das Dingsbums",b="Die Beute zu erreichen erfordert mehr als flinke Finger. Wrenix warnt davor, dass frühere Diebe in Stücken zu ihm zurückgebracht wurden, vor allem wegen des Wächters im untersten Frachtraum des Schiffes: ein erschreckend wilder Papagei namens Polly. Um diesem geflügelten Schrecken zu begegnen, stellt Wrenix ein experimentelles Gerät namens R.C.V.K. zur Verfügung. Wird das Dingsbums nach dem Knacken der Piratenschatulle auf den bösartigen Vogel geschleudert, desorientiert und schwächt es die Bestie, wodurch ein aussichtsloses Todesurteil in ein gewinnbares Duell verwandelt wird."}},faq={{q="Wer ist Wrenix der Jämmerliche?",a="Wrenix der Jämmerliche ist ein Goblin-Schurkenkontakt im neutralen Hafen von Ratschet. In Zusammenarbeit mit Agenten, die mit der Shattered-Hand in Orgrimmar in Verbindung stehen, testet er angehende Diebe, indem er sie in Piratengebiet schickt, um das Knacken von Schlössern zu üben und gestohlene Beute zu beschaffen.",al={"wrenix","wer ist wrenix","ratschet goblin schurkenquest"}},{q="Wo befindet sich die Tide Razor?",a="Die Tide Razor liegt südlich von Ratschet an der Ostküste des Brachlands vor Anker, eingebettet in der Enklave der Südmeerfreibeuter. Das Schiff dient Piratenschurken als Stützpunkt und Ausbildungsstätte.",al={"standort der tide razor","wo ist das piratenschiff","wo sind die südmeerpiraten"}},{q="Was ist ein R.C.V.K. und wie benutze ich es?",a="Das R.C.V.K. ist ein experimentelles Goblin-Dingsbums, das von Wrenix' Gizmotronic Apparatus ausgegeben wird. Es wird gegen Polly eingesetzt, den tödlichen Riesenpapagei, der den Schatz der Südmeerfreibeuter im Bauch der Tide Razor bewacht, und schwächt die Bestie drastisch, sodass sie besiegt werden kann.",al={"rcvk","was ist das rcvk","wie man polly besiegt"}},{q="Warum ist der Bereich zum Schlossknacken auf dem Schiff von Bedeutung?",a="Das zweite Deck der Tide Razor dient den Südmeerpiraten als Übungsraum. Es beherbergt eine Ansammlung wiederkehrender Schließkassetten, an denen Schurken ihre Techniken zum Schlossknacken unter Feldbedingungen üben können, bevor sie sich an die Hauptschatulle weiter unten wagen.",al={"schlossknacken üben","ausbildungsschiff der beutelschneider","kisten knacken brachland"}},{q="Warum ist diese Mission für Schurken so wichtig?",a="Der erfolgreiche Beutezug beweist den Wert eines Schurken für das Netzwerk der Shattered-Hand. Als Teil Eures Anteils belohnt Euch Wrenix mit der Geheimformel für Disteltee, ein unschätzbares Kräutergebräu, das die Kampfenergie eines Schurken rasch wiederherstellt.",al={"schurkenquest disteltee","warum das ausplündern der plünderer machen","schurkenquest belohnung"}},{q="Wer ist Polly?",a="Polly ist der bösartige Wachpapagei der Südmeerfreibeuter, der im unteren Frachtraum der Tide Razor stationiert ist. Wenn man ihn gewähren lässt, ist der Vogel für unerfahrene Eindringlinge tödlich – es sei denn, er wird mit Goblin-Technologie geschwächt.",al={"polly","riesenpapagei","tide razor boss"}}},fx={d00111f9={q="Warum will Wrenix der Jämmerliche den Schatz der Südmeerfreibeuter?",a="Wrenix ist ein gerissener Goblin-Dieb und Problemlöser, der von Ratschet aus operiert und es auf den illegalen Hort der Southsea Freebooters als große Auszahlung abgesehen hat. Frühere Versuche, das Schiff der Piraten zu plündern, endeten katastrophal und hinterließen fünf andere tote und zerstückelte Schurken. Indem er Euch schickt, um das Schiff zu stürmen und die Beute zu bergen, sichert Wrenix einen lukrativen Preis, während er Euren Mut gegen Halsabschneider testet, die sie zuerst gestohlen haben.",al={"wrenix beweggrund","warum schatz der südmeerfreibeuter stehlen","warum will wrenix das erledigt haben"}},abe44597={q="Warum braucht Wrenix Euch, anstatt Wachen anzuheuern oder selbst zu gehen?",a="Der Diebstahl bei den Southsea Freebooters ist heikle, illegale Arbeit, die nicht mit roher Gewalt oder den neutralen Wachen von Ratschet erledigt werden kann. Die Piraten bilden ihre eigenen Diebe an Bord der Tide Razor aus, was jemanden erfordert, der in Heimlichkeit und Schlossknacken geschult ist, um unentdeckt in den Laderaum zu schlüpfen. Als ein Goblin, der außerhalb der üblichen Handelsabkommen operiert, zieht Wrenix es vor, einen entbehrlichen, fähigen Agenten anzuheuern, anstatt seine eigene Haut zu riskieren.",al={"warum ich wrenix","warum einen schurken schicken","warum holt wrenix den schatz nicht"}}},fp="25,348,27.537.0,19.489.1,27.264.0,32.195.0,40.257.0,52.248.0,40.228.0,13.214.0"}
P.entries["quest:2382"] = {n="Wrenix aus Ratschet",s="Wrenix aus Ratschet ist ein Schurkenauftrag der Horde, der angehende Agenten aus Orgrimmar hinaus und hinab zur Goblinstadt Ratschet führt. Der manische Troll Zando'zan schickt Agenten nach Süden, um einem zwielichtigen Goblin namens Wrenix der Jämmerliche beizustehen.",h="Wrenix aus Ratschet ist ein Schurkenauftrag der Horde, der angehende Agenten aus Orgrimmar hinaus und hinab...",kw={"ratschet","schurke","die shattered-hand","brachland","thrall","wrenix","zando'zan"},ang={["class:Rogue"]="Diese Reise ist ein wesentlicher Schritt in der Ausbildung eines Schurken der Horde, da sie junge Agenten aus der Sicherheit Orgrimmars hinaus in neutrales Piratengebiet führt.",["faction:Horde"]="Die Zerschmetterte Hand unterhält Augen und Ohren jenseits der Grenzen von Durotar und greift für heikle Aufträge häufig auf neutrale Häfen wie Ratschet zurück."},sec={{t="Ein Prophet in den Schatten",b="In den gewundenen Spalten der Kluft der Schatten in Orgrimmar geht die Schurkengilde ihren Geschäften größtenteils im Verborgenen nach. Agenten, die Zando'zan aufsuchen, empfängt er mit wirrem Gefasel und unheilvollen Vorzeichen, darunter düstere Visionen über die Ermordung von Kriegshäuptling Thrall durch Gift und Klinge. Statt seine Prophezeiung zu erklären, schickt der exzentrische Troll die Agenten rasch in die Hafenstadt Ratschet im Brachland."},{t="Ratschets Problemlöser",b="An der Küste östlich von dem Wegekreuz gelegen, beherbergt der neutrale Hafen von Ratschet allerlei Schurken, Söldner und Bastler. Wrenix der Jämmerliche agiert von dieser geschäftigen Zuflucht aus, bringt jedoch wenig Geduld für Zando'zans Schrullen auf. Laut Wrenix fanden die früheren Rekruten des Trolls ihr unglückliches Ende in den von Raubfischen wimmelnden Gewässern der Bucht."}},faq={{q="Wer schickt Euch nach Ratschet?",a="Zando'zan, ein Troll der Shattered-Hand in Orgrimmars Kluft der Schatten, schickt Euch auf diesen Botengang, nachdem er seltsame Visionen herausgeplatzt hat.",al={"wer vergibt quest","questgeber","zandozan"}},{q="Wer ist Wrenix der Jämmerliche?",a="Wrenix der Jämmerliche ist eine Goblin-Kontaktperson, die in der Hafenstadt Ratschet tätig ist. Er kümmert sich um verdeckte Aufträge und mechanische Vorräte für Schurken, die im gesamten Brachland im Einsatz sind.",al={"wer ist wrenix","wrenix ratschet","identität von wrenix"}},{q="Was geschah mit den vor mir entsandten Agenten?",a="Laut Wrenix scheiterten die letzten fünf von Zando'zan entsandten Agenten an ihren Aufgaben und endeten als Haifischfutter vor der Küste von Ratschet.",al={"vorherige schurken","haifischfutter","andere rekruten"}},{q="Was meinte Zando'zan in Bezug auf Thrall?",a="Zando'zan behauptet, eine Vision gehabt zu haben, in der Thrall durch einen vergifteten Dolch in den Rücken niedergestreckt wird, unterbricht sich jedoch rasch selbst und wechselt das Thema.",al={"thrall-prophezeiung","thrall vergiftet","zandozan thrall-vision"}},{q="Wo liegt Ratschet?",a="Ratschet liegt an der Ostküste des Brachlands, direkt östlich von dem Wegekreuz. Es ist über Straßen mit Durotar verbunden, die vom Südstrom aus nach Süden führen.",al={"wo liegt ratschet","ratschet finden","standort von ratschet"}},{q="Was geschieht nach dem Treffen mit Wrenix?",a="Nachdem Ihr Wrenix begrüßt habt, beauftragt er Euch mit 'Das Ausplündern der Plünderer', was die Infiltration der Südmeerfreibeuter entlang der Küste südlich von Ratschet erfordert.",al={"nächste quest","nach wrenix","ratschet folgequest"}}},fx={["17a3bd65"]={q="Warum schickt Zando'zan Euch zu Wrenix?",a="Zando'zan ist aufgeschreckt durch hektische Visionen des Untergangs und sieht Gift sowie einen verräterischen Dolch, der auf den Rücken von Kriegshäuptling Thrall gerichtet ist. In seiner Verzweiflung, diesen ungesehenen Bedrohungen in den Schatten entgegenzuwirken, verlässt sich der exzentrische Troll auf externe Kontakte wie Wrenix der Jämmerliche in Ratschet, um verdeckte Operationen durchzuführen und spezialisierte Ausrüstung zu beschaffen.",al={"warum zu wrenix schicken","zandozan beweggrund","warum wrenix besuchen"}},["2311cb82"]={q="Warum schickt Zando'zan Euch, anstatt es selbst zu erledigen?",a="Zando'zan bleibt in den Schatten der Kluft der Schatten von Orgrimmar gefangen, wo er dunkle Vorzeichen beobachtet und über seine Verschwörungsvisionen murmelt. Sein erratisches Auftreten und seine Angst davor, 'zu viel gesagt' zu haben, halten ihn davon ab, offen im Feld zu operieren, also verlässt er sich auf fähige Schurken, die als seine diskreten Hände außerhalb der Stadtmauern dienen.",al={"warum schickt ihr mich","warum braucht mich zandozan","warum geht er nicht selbst"}}},fp="17,236,24.403.0,24.363.0,25.146.0,27.167.0,47.147.0,50.159.0,25.164.0,37.155.1"}
P.entries["quest:239"] = {n="Hilfe für die Weststromgarnison",s="Marschall Dughan schickt verfügbare Abenteurer nach Westen zur Weststromgarnison, dem Vorposten, der die Grenze des Walds von Elwynn zu Westfall bewacht. Da die Armee von Sturmwind über das gesamte Königreich hinweg überdehnt ist, sehen sich Stellvertreter Rainer und seine Wachen ohne reguläre Verstärkung dem wachsenden Druck durch aggressive Flusssetzergnolle und umherziehende Diebe ausgesetzt.",h="Marschall Dughan schickt verfügbare Abenteurer nach Westen zur Weststromgarnison, dem Vorposten, der die...",kw={"stellvertreter rainer","wald von elwynn","gnolle","goldhain","marschall dughan","flusssetzer","weststromgarnison"},ang={["faction:Alliance"]="Freiwillige der Allianz schlüpfen hier in die Rolle regulärer Soldaten und leisten die nötige Basisarbeit, um zu verhindern, dass die Kernlande im völligen Chaos versinken.",["race:Human"]="Für die Menschen von Sturmwind ist dieser Auftrag ein beunruhigendes Zeichen der Vernachlässigung des Königreichs und zeigt aus erster Hand, wie sehr die Verteidigung der Krone in der Folge des Verschwindens des Königs gelitten hat."},sec={{t="Eine überdehnte Grenze",b="Die Weststromgarnison markiert den westlichen Rand des Walds von Elwynn und liegt genau dort, wo die besiedelten Waldgebiete in die unruhigen Ebenen von Westfall übergehen. Da Gnollkriegstrupps und Banditen entlang der Wasserwege und westlichen Straßen immer dreister werden, hat die kleine Besatzung des Vorpostens um mehr Männer gefleht. Allerdings haben Marschall Dughan und die Verwaltung von Goldhain keine regulären Soldaten aus Sturmwind erübrigen können, sodass den örtlichen Befehlshabern keine andere Wahl bleibt, als reisende Söldner und umherziehende Abenteurer anzuheuern."},{t="Die Bedrohung jenseits des Baches",b="Die größte Bedrohung für Stellvertreter Rainer und seine Männer stellt das Gnollrudel der Flusssetzer dar, dessen Raubzüge Reisende und nahe gelegene Höfe heimsuchen. Diese Gnolle, die in den Grenzlanden zwischen Elwynn und Westfall operieren, haben Sturmwinds politische und militärische Ablenkung ausgenutzt, um tiefer in bewohntes Gebiet vorzudringen. Die Weststromgarnison steht als letzte Verteidigungslinie da, die sie daran hindert, unkontrolliert in das Herz des Waldes zu streifen."}},faq={{q="Warum kann Sturmwind keine regulären Soldaten zur Weststromgarnison schicken?",a="Sturmwinds stehendes Heer ist an mehreren Fronten stark überdehnt. Da König Varian Wrynn vermisst wird und das Reich mit inneren Konflikten zu kämpfen hat, hat sich das Oberkommando geweigert oder war außerstande, reguläre Soldaten zu ländlichen Außenposten zu entsenden. Dies zwingt Ortsmarschälle wie Dughan dazu, sich auf freiberufliche Freiwillige zu verlassen.",al={"warum keine truppen aus sturmwind","warum abenteurer schicken","wo ist die armee von sturmwind"}},{q="Wo befindet sich die Weststromgarnison?",a="Die Garnison liegt am westlichen Rand des Walds von Elwynn. Folgt der Hauptstraße von Goldhain aus nach Westen über den kleinen Bach; der befestigte Turm befindet sich zu Eurer Rechten kurz vor der Grenze nach Westfall.",al={"weststromgarnison standort","weg zur weststromgarnison","wo ist stellvertreter rainer"}},{q="Welche Bedrohungen machen der Garnison zu schaffen?",a="Stellvertreter Rainer hat mit anhaltenden Überfällen der Flusssetzergnolle sowie einer Zunahme von Diebes- und Banditenaktivitäten zu kämpfen, die im Grenzland zwischen Westfall und dem Wald von Elwynn ihr Unwesen treiben.",al={"wer greift weststrom an","warum braucht rainer hilfe","wer greift die weststromgarnison an"}},{q="Wer ist Stellvertreter Rainer?",a="Stellvertreter Rainer ist der Offizier aus Sturmwind, der das Kommando über die Weststromgarnison führt. Mit der Aufgabe betraut, die westliche Grenze zu halten, ist er aufgrund eines gravierenden Mangels an offizieller militärischer Verstärkung gezwungen, sich an zivile Freiwillige und Söldner zu wenden.",al={"rainer lore","stellvertreter rainer","wer ist rainer"}},{q="Was geschieht nach der Meldung bei Stellvertreter Rainer?",a="Stellvertreter Rainer nimmt sogleich Eure Hilfe gegen die örtlichen Flusssetzergnolle in Anspruch und setzt ein Kopfgeld auf deren Halsbänder aus, um ihre Reihen zu lichten und die Grenzstraße zu schützen.",al={"was kommt danach","weststrom questreihe","rainer quest"}},{q="Warum dringen die Gnolle in den Wald von Elwynn vor?",a="Die Flusssetzergnolle haben Lager entlang der Flüsse errichtet, die Elwynn und Westfall voneinander trennen. Sie nutzen die verringerte militärische Präsenz an der Grenze aus und sind dreist genug geworden, Handelsrouten zu überfallen und in Richtung der Farmen im Landesinneren von Elwynn vorzustoßen.",al={"flusssetzergnolle elwynn","warum sind die gnolle hier","gnollproblem"}}},fx={["76645dec"]={q="Warum will Marschall Dughan, dass Ihr zur Weststromgarnison geht?",a="Marschall Dughan ist dafür verantwortlich, im Wald von Elwynn von Goldhain aus für Ordnung und Sicherheit zu sorgen, aber seine Ressourcen sind bis zum Äußersten erschöpft. Die Weststromgarnison bewacht die westliche Grenze des Königreichs, und Stellvertreter Rainer hat dringende Nachrichten über zunehmendes Banditentum und eindringende Gnolle gesendet. Ohne reguläre Truppen, die er als Verstärkung entsenden könnte, muss Dughan sich auf unabhängige Abenteurer verlassen, die auf den Hilferuf des Außenpostens antworten, bevor die westliche Grenze vollständig zusammenbricht.",al={"warum zur weststromgarnison schicken","marschall dughan beweggrund","warum braucht weststromgarnison hilfe"}}},fp="30,345,25.500.0,27.446.0,64.313.0,36.200.0,40.188.0,21.244.0,46.162.0,46.249.0"}
P.entries["quest:2399"] = {n="Die sprießenden Wedel",s="Nach Denalans botanischen Experimenten am Al'Amethsee schlagen die gepflanzten Wedelsamen Wurzeln und blühen auf. Dieser ruhige Moment markiert eine erfolgreiche Ernte beim Verständnis der seltsamen und lebenswichtigen Flora von Teldrassil. Reisende, die die Gartenbeete untersuchen, können das schnelle Wachstum aus erster Hand miterleben.",h="Nach Denalans botanischen Experimenten am Al'Amethsee schlagen die gepflanzten Wedelsamen Wurzeln und blühen...",kw={"denalan","kräuterkunde","pflanzbeet","samen","schimmernder wedel","sprießende wedel","teldrassil","wellspringsee"},ang={["class:Druid"]="Druiden, die Denalans Pflanzbeet beobachten, können das stille Gleichgewicht der Natur schätzen und sehen, wie das Leben unter aufmerksamer Pflege selbst inmitten der wachsenden Gefahren von Teldrassil gedeiht.",["profession:Herbalism"]="Denalans Forschung spiegelt die praktischen Künste des Sammelns und Studierens der einzigartigen Vegetation von Teldrassil wider und zeigt, wie schnell sich lokale Samen an gepflegten Boden anpassen.",["race:NightElf"]="Die Pflege der neu gesprossenen Flora spiegelt die Verantwortung der Kaldorei wider, das Leben, das auf ihrem jungen Weltenbaum Wurzeln schlägt, zu überwachen und zu pflegen."},sec={{t="Ein Garten am Al'Amethsee",b="Versteckt in der Nähe des Al'Amethsees widmet sich der Botaniker Denalan der Katalogisierung des eigentümlichen Pflanzenlebens von Teldrassil. Nachdem die Samen eines mysteriösen Schimmernden Wedels gesät wurden, zeigt der Boden schnell Ergebnisse. In seinem gepflegten Pflanzbeet schießen seltsame, zitternde Wedel aus der fruchtbaren Erde, bereit, gepflückt und untersucht zu werden."},{t="Die seltsame Flora des Weltenbaums",b="Teldrassil ist jung, riesig und wimmelt von einer schnellen natürlichen Entwicklung, die Nachtelfen-Kräuterkundige gleichermaßen fasziniert und beunruhigt. Die Schimmernden Wedel und ihre sprießenden Ableger sind sinnbildlich dafür, wie schnell das Leben auf den Ästen des großen Baums Fuß fasst, was auf die mächtige, aber unvorhersehbare Vitalität hindeutet, die in den Boden der Insel eingewebt ist."}},faq={{q="Was sind die sprießenden Wedel?",a="Es handelt sich um die ausgereiften Pflanzen, die aus den Samen sprossen, die Denalan in seinem Lager am See ausgesät hat. Diese eigentümlichen Pflanzen wurden aus den Schimmernden Wedeln kultiviert, die anderswo in Teldrassil gefunden wurden, und beben vor Energie, wenn sie zur Ernte bereit sind.",al={"sprießende wedel","was sind diese pflanzen","denalans wedel"}},{q="Wo befindet sich Denalans Garten?",a="Denalan hält seinen Garten und sein Forschungslager am östlichen Rand des Al'Amethsees, südöstlich von Dolanaar in Teldrassil.",al={"denalans standort","wo ist denalan","garten am wellspringsee"}},{q="Warum pflanzt Denalan diese Wedel?",a="Denalan untersucht die merkwürdigen und schnellen Wachstumsmuster der Pflanzenwelt von Teldrassil. Indem er Samen in kontrollierten Boden pflanzt, erforscht er deren Natur und testet, ob sie nützliche heilende oder kräuterkundliche Eigenschaften besitzen.",al={"warum wedel pflanzen","denalans experiment","zweck der wedel"}},{q="Sind die sprießenden Wedel gefährlich?",a="Nein. Im Gegensatz zu einigen der korrumpierten oder feindseligen Pflanzen anderswo auf den Ästen von Teldrassil sind diese sprießenden Wedel harmlose botanische Exemplare, die nur darauf warten, gepflückt zu werden.",al={"sind wedel gefährlich","greifen wedel an","ist die pflanze schädlich"}},{q="Was kommt vor dieser Aufgabe?",a="Abenteurer entdecken zuerst einen Schimmernden Wedel in der Wildnis von Teldrassil und bringen ihn zu Denalan, der die Samen in sein Gartenbeet pflanzt, um auf ihr Sprießen zu warten.",al={"voraussetzung für sprießende wedel","welche aufgabe kommt zuerst"}},{q="Warum beben die Wedel?",a="Die Wedel beben, während sie darauf warten, gepflückt zu werden. Die Quelle erklärt nicht, was diese Bewegung verursacht.",al={"zitternde wedel","warum beben sie"}}},fp="19,281,25.337.0,35.336.0,29.224.0,34.120.0,36.220.0,34.166.0,29.166.0,26.96.0"}
P.entries["quest:24"] = {n="Schattumbras Kopf",s="Diese Quest stellt den Beweis für den Sieg über Shadumbra dar, einen berüchtigt wilden Nachtsäbler, der die westlichen Pfade von Eschental heimsucht. Den abgetrennten Kopf der Bestie zu Senani Donnerherz am Splitterholzposten zurückzubringen, erfüllt eine zentrale Prüfung der Jagd im Eschental und sichert die Reiserouten in Richtung des Zoramstrands.",h="Diese Quest stellt den Beweis für den Sieg über Shadumbra dar, einen berüchtigt wilden Nachtsäbler, der die...",kw={"die jagd in eschental","nachtsäbler","senani donnerherz","shadumbra","splintertreeposten","trophäe","der zoramstrand"},ang={["class:Hunter"]="Das Aufspüren und Bezwingen eines so schwer fassbaren Nachtsäblers wie Shadumbra ist eine fundamentale Prüfung für Treffsicherheit, Geduld und das Überleben in dichtem Waldgelände.",["faction:Horde"]="Der Splitterholzposten bleibt eine isolierte Hochburg der Horde; die Beseitigung lokaler Bedrohungen wie Shadumbra hält lebenswichtige Versorgungslinien zum Zoramstrand offen.",["race:Tauren"]="Für die Tauren ehrt die Jagd auf eine Bestie von Shadumbras Kaliber die natürliche Ordnung der Erdenmutter, indem das eigene Können an einem Spitzenprädator gemessen und gleichzeitig Stammesbrüder auf der Straße beschützt werden."},sec={{t="Eine Bedrohung der Weststraße",b="Shadumbra ist kein gewöhnliches Raubtier unter den hoch aufragenden Bäumen von Eschental. Der große Nachtsäbler durchstreifte die Wildnis westlich des Splitterholzpostens und lauerte Spähern und Boten der Horde auf, die versuchten, zum Zoramstrand zu reisen. Ihre Schnelligkeit, Tarnung und schiere Wildheit machten das Reisen zu Fuß lebensgefährlich, was die Verteidiger des Splitterholzpostens jedes Mal in Alarmbereitschaft versetzte, wenn Patrouillen nach Westen zogen."},{t="Beweis der Jagd",b="Als Teil der Jagd in Eschental fordert die Taurenjägerin Senani Donnerherz die Champions der Horde heraus, die Spitzenprädatoren des Waldes aufzuspüren und zu erlegen. Schattumbras Kopf zu überreichen, ist nicht bloß eine düstere Demonstration von Tapferkeit; es dient als unbestreitbarer Beweis dafür, dass die Straßen sicherer gemacht wurden und der Jäger einen der tödlichsten einheimischen Jäger Kalimdors bezwungen hat."}},faq={{q="Wer war Shadumbra?",a="Shadumbra war ein außergewöhnlich wilder Nachtsäbler, der die Wälder westlich des Splitterholzpostens durchstreifte. Sie war dafür bekannt, Reisenden auf dem langen Weg zur Küste aufzulauern, und galt als eine der gefährlichsten einheimischen Bestien Eschentals.",al={"was ist shadumbra","shadumbra lore","wer ist die katze"}},{q="Warum will Senani Donnerherz den Kopf?",a="Senani Donnerherz leitet Die Jagd in Eschental am Splitterholzposten. Den Kopf einzufordern dient sowohl als traditionelle Trophäe einer eindrucksvollen Jagd als auch als Bestätigung dafür, dass die Bedrohung für westwärts Reisende beseitigt wurde.",al={"warum kopf bringen","senani donnerherz trophäe","die jagd in eschental beweis"}},{q="Wie fügt sich dies in die Jagd in Eschental ein?",a="Es ist eine der Hauptprüfungen, die nach Annahme der Jagd in Eschental begonnen werden. Das Erlegen von Shadumbra, zusammen mit den anderen großen Bestien des Waldes wie Ursangous und Sharptalon, führt zur endgültigen Anerkennung und der Quest „Die Jagd ist abgeschlossen“.",al={"was ist die jagd in eschental","jagd questreihe","nächste jagdquest"}},{q="Warum ist die Beseitigung dieser Bestie wichtig für die Horde?",a="Der Splitterholzposten ist auf Späher und Läufer angewiesen, die nach Westen zum Lager der Horde am Außenposten von Zoram'gar am Zoramstrand reisen. Shadumbras räuberische Natur stellte eine ständige Gefahr für den Fußverkehr der Horde durch die ungezähmten Wälder dar.",al={"warum ist das der horde wichtig","gefahr zoramstrand straße","splintertreeposten sicherheit"}},{q="Wo ist Shadumbra zu finden?",a="Shadumbra durchstreift die Wälder westlich des Splitterholzpostens und lauert zwischen den Bäumen zwischen der Straße und den alten Ruinen der Nachtelfen, die über das zentrale und westliche Eschental verstreut sind.",al={"shadumbra aufenthaltsort","wo ist shadumbra","shadumbra finden"}},{q="Ist Shadumbra mit den Nachtelfen verbündet?",a="Nein. Während Nachtsäbler von den Nachtelfen oft gezähmt und verehrt werden, ist Shadumbra ein wilder Schrecken des Waldes, der rein nach rohem Raubtierinstinkt handelt und jeden bedroht, der ihr Territorium durchquert.",al={"ist shadumbra ein haustier","schildwachen begleiter","shadumbra nachtelf"}}},fp="16,309,28.368.0,17.354.0,18.236.0,43.224.0,44.236.0,50.233.0,29.180.0,41.202.0"}
P.entries["quest:240"] = {n="Rückkehr zu Bibbers",s="Rückkehr zu Bibbers schließt Küchenchef Gruals kulinarische Besorgung im Dämmerwald ab. Nachdem er seine berüchtigten „Krebsküchlein“ mithilfe der klebrigen Beine der hiesigen Giftnetzspinnen zubereitet hat, schickt Grual Euch zurück zu dem verhungernden, verängstigten Einsiedler auf Rabenflucht. Die Lieferung der Mahlzeit stillt endlich Bibbers' verzweifelten Hunger.",h="Rückkehr zu Bibbers schließt Küchenchef Gruals kulinarische Besorgung im Dämmerwald ab.",kw={"küchenchef grual","dunkelhain","dämmerwald","schwärzliche krebsküchlein","knurrender magen","jitters","scarlet raven tavern"},ang={["faction:Alliance"]="Die karge, unkonventionelle Ernährung in Dunkelhain spiegelt wider, wie abgeschnitten die Stadt von Sturmwinds größeren Nachschublinien ist, sodass die Einheimischen auf alles angewiesen sind, was in den Schatten kriecht.",["profession:Cooking"]="Küchenchef Gruals Fähigkeit, klebrige Giftnetzspinnenbeine in schmackhafte Küchlein zu verwandeln, zeugt von dem unerbittlichen Einfallsreichtum, der Köchen an den Grenzlanden abverlangt wird."},sec={{t="Eine zweifelhafte Delikatesse",b="Im Dämmerwald mangelt es an herkömmlichem Vieh und Meeresfrüchten, sodass Küchenchef Grual in der Scarlet Raven Tavern mit allem improvisieren muss, was der verheerte Wald hergibt. Seine berühmten „Schwärzliche Krebsküchlein“ enthalten keinerlei echtes Krebsfleisch, sondern basieren stattdessen auf klebrigen Beinen, die von den durch den Wald kriechenden Giftnetzspinnen erbeutet wurden. Grual betrachtet dies als einfallsreiche Kochkunst; jeder mit einem empfindlichen Magen dürfte es jedoch mit Entsetzen betrachten."},{t="Bibbers' Nerven beruhigen",b="Bibbers verbringt seine Tage zusammengekauert auf Rabenflucht, völlig von Angst zerfressen und gelähmt von den Schrecken, die ihn aus dem Wald getrieben haben. Geschwächt vor Entsetzen und unfähig, den Mut aufzubringen, selbst zu jagen oder nach Nahrung zu suchen, verstärkt sein leerer Magen seine Not nur noch weiter. Der Erhalt der warmen Küchlein bringt dem zitternden Vagabunden einen seltenen Moment der Erleichterung – er ist viel zu hungrig, um zu hinterfragen, welche Art von „Krebs“ Küchenchef Grual verwendet hat."}},faq={{q="Was steckt in den Schwärzlichen Krebsküchlein?",a="Im Dämmerwald gibt es keine Krebse. Küchenchef Grual bereitet seine Spezialküchlein aus den klebrigen Beinen der hiesigen Giftnetzspinnen zu und würzt sie so, dass sie traditionelle Meeresfrüchteküchlein nachahmen.",al={"krebsküchlein zutaten","woraus bestehen schwärzliche krebsküchlein","sind es echte krebse"}},{q="Weiß Bibbers, dass die Küchlein aus Spinnenglibber bestehen?",a="Küchenchef Grual behält sein kulinarisches Geheimnis für sich, und Bibbers ist viel zu ausgehungert und verängstigt, um nach dem Rezept zu fragen. Er isst sie eifrig auf, ohne ihren wahren Ursprung zu ahnen.",al={"weiß jitters bescheid","weiß jitters von den spinnen"}},{q="Warum konnte Bibbers sich sein Essen nicht selbst besorgen?",a="Bibbers ist nach seinen Begegnungen in den wilden Wäldern des Dämmerwalds völlig von Angst überwältigt. Von Panik gelähmt weigert er sich, sich weit von seinem Versteck auf Rabenflucht zu entfernen, und ist darauf angewiesen, dass mitfühlende Reisende ihm Nahrung bringen.",al={"warum verhungert jitters","warum jagt jitters nicht"}},{q="Wer ist Küchenchef Grual?",a="Küchenchef Grual ist der Koch in der Scarlet Raven Tavern in Dunkelhain. Angesichts einer Stadt, die von Schatten und Bestien isoliert ist, nutzt er jede noch so unkonventionelle Zutat, die ihm Plünderer bringen, um die Gäste der Taverne zu versorgen.",al={"küchenchef grual rolle","koch in dunkelhain"}},{q="Wo beginnt diese Questreihe?",a="Die Besorgung beginnt bei Bibbers auf Rabenflucht, der in „Bibbers' knurrender Magen“ um Hilfe für seinen rumorenden Bauch bittet, was zur Jagd auf Giftnetzspinnen für Küchenchef Grual führt, bevor man mit der fertigen Mahlzeit hierher zurückkehrt.",al={"jitters essensquest starten","jitters questreihe start"}},{q="Erholt sich Bibbers nach dem Essen?",a="Die Mahlzeit stillt seinen körperlichen Hunger und bringt Euch seine herzliche Dankbarkeit ein, aber Nahrung heilt nicht seinen tief sitzenden psychischen Schrecken. Er bleibt ängstlich und wird weiterhin von den dunklen Geheimnissen des Waldes heimgesucht.",al={"ist jitters geheilt","hilft essen jitters"}}},fx={deba9bdd={q="Warum will Küchenchef Grual, dass die Krabbenküchlein an Bibbers geliefert werden?",a="Küchenchef Grual leitet die Küche in der Scarlet Raven Tavern in Dunkelhain und ist stolz darauf, Bestellungen auszuführen, selbst bizarre, die aus örtlichen Spinneneingeweiden gekocht werden. Bibbers hungert in der gefährlichen Düsternis von Raven Hill und ist zu verängstigt, um die Reise in die Stadt selbst zu machen. Nachdem er seine speziellen 'Krabben'-Küchlein à la Grual zubereitet hat, vertraut der Koch sie Euch an, um die Bestellung von Bibbers zu erfüllen und sicherzustellen, dass der arme Kerl etwas zu essen bekommt.",al={"warum krabbenküchlein liefern","grual beweggrund bibbers","warum essen an bibbers schicken"}}},fp="17,299,18.423.0,24.416.0,32.168.0,51.177.0,38.240.0,18.209.0,34.216.0,34.204.0"}
P.entries["quest:2438"] = {n="Der smaragdgrüne Traumfänger",s="Tallonkai Flinkwurzel in Dolanaar bittet Abenteurer darum, ein geschätztes Erbstück aus seinem verlassenen Heim in Sternenhauch zu bergen. Der smaragdgrüne Traumfänger, den ihm der Hüter der Druiden, Gaerolas Talvethren, schenkte, blieb zurück, als verdorbene Gnarlpine-Furbolgs die friedliche Siedlung überrannten. Die Rückbeschaffung dieses Amuletts verhindert, dass seine sanfte Naturmagie in finstere Hände fällt.",h="Tallonkai Flinkwurzel in Dolanaar bittet Abenteurer darum, ein geschätztes Erbstück aus seinem verlassenen...",kw={"grabhügel von ban'ethil","dolanaar","smaragdgrüner traum","smaragdgrüner traumfänger","furbolg","gaerolas talvethren","gnarlpine","starbreeze","tallonkai flinkwurzel","teldrassil"},ang={["class:Druid"]="Das Amulett ist ein direktes Werk von Gaerolas Talvethren, jenem Hüter, der Eure schlafende Verwandtschaft im Grabhügel von Ban'ethil betreut; seine Wiederbeschaffung ist daher eine Frage der druidischen Ehre.",["faction:Alliance"]="Den vertriebenen Kaldorei von Dolanaar beizustehen, sichert die örtliche Stabilität, während Teldrassil mit der um sich greifenden Verderbnis unter den Furbolgstämmen ringt.",["race:NightElf"]="Starbreeze war einst eine friedliche Zuflucht für Euer Volk. Tallonkai dabei zu helfen, sein Erbe zurückzuerlangen, versetzt dem Wahnsinn, der Teldrassils Tierwelt ergreift, einen kleinen Schlag."},sec={{t="Ein druidischer Talisman",b="Der smaragdgrüne Traumfänger ist weit mehr als nur ein dekorativer Ziergegenstand. Gefertigt von Gaerolas Talvethren, dem geehrten Hüter der schlafenden Druiden im Grabhügel von Ban'ethil, wurde das Amulett erschaffen, um die ruhigen Ströme des Smaragdgrünen Traums zu kanalisieren. Indem er diese reine geistige Energie abschöpft, schenkt der Traumfänger seinem Träger Frieden und Glück. Solche Zeichen sind überaus selten und werden nur wenigen Auserwählten anvertraut, deren Leben eng mit der Obhut des Waldes verflochten sind."},{t="Die Flucht aus Sternenhauch",b="Bis vor Kurzem war Sternenhauch eine friedliche Siedlung inmitten der Äste von Teldrassil. Dieses ruhige Leben endete, als die einheimischen Gnarlpine-Furbolgs einem gewaltsamen Wahnsinn verfielen und die Nachtelfen aus ihren angestammten Behausungen vertrieben. Im Schrecken und der Verwirrung der Evakuierung sah sich Tallonkai gezwungen, seinen wertvollsten Besitz versteckt in seiner Kommode im südöstlichen Viertel des Dorfes zurückzulassen, unfähig, ihn aus eigener Kraft wiederzuerlangen."},{t="Die Bedrohung durch das Verderben",b="Einen Fokus der Magie des Smaragdgrünen Traums im Herzen eines überrannten Dorfes zurückzulassen, birgt ernste Gefahren. Die Gnarlpine haben sich als anfällig für dunkle Einflüsse erwiesen, und ein Artefakt, das von den Energien des Traums pulsiert, könnte leicht verderbt oder als Waffe missbraucht werden. Die sichere Bergung des Traumfängers bringt Tallonkai ein Stück des Erbes von Starbreeze zurück, bevor die Furbolgs oder andere finstere Bewohner seine verbleibende Magie entweihen können."}},faq={{q="Was ist der smaragdgrüne Traumfänger?",a="Es ist ein seltenes Amulett, gefertigt von Gaerolas Talvethren, dem Hüter der Druiden im Grabhügel von Ban'ethil. Der Traumfänger schöpft Energie aus dem Smaragdgrünen Traum, um jedem, der ihn bei sich trägt, Glück und geistige Harmonie zu schenken.",al={"was ist der traumfaenger","traumfaenger geschichte","smaragdgrüner traumfänger"}},{q="Warum wurde der Traumfänger in Sternenhauch zurückgelassen?",a="Sternenhauch wurde rasch überrannt, als die einheimischen Gnarlpine-Furbolgs in einen gewalttätigen, verdorbenen Blutrausch verfielen. Tallonkai Flinkwurzel musste um sein Leben nach Dolanaar fliehen und ließ das kostbare Erbstück wohlverwahrt in der Schlafzimmerkommode zurück.",al={"warum zurueckgelassen","starbreeze kommode","tallonkai kommode"}},{q="Wer ist Tallonkai Flinkwurzel?",a="Tallonkai ist ein Nachtelfenflüchtling, der sich derzeit in Dolanaar aufhält. Nachdem er dem Fall von Sternenhauch entkommen ist, sucht er nach mutigen Reisenden, die sich zurück in die besetzten Ruinen wagen, um seine Familienerbstücke zu retten und druidische Relikte zu sichern.",al={"wer ist tallonkai","tallonkai flinkwurzel"}},{q="Wer hat den Traumfänger hergestellt?",a="Er wurde von Gaerolas Talvethren gefertigt und verschenkt, jenem Hüter, der über die schlummernden Druiden im Grabhügel von Ban'ethil wacht.",al={"wer hat ihn erschaffen","gaerolas talvethren traumfaenger","gaerolas"}},{q="Wo in Sternenhauch befindet sich der Traumfänger?",a="Er liegt in Tallonkais persönlicher Kommode im südöstlichsten Haus von Sternenhauch, in dem nun feindselige Gnarlpine-Furbolgs lauern.",al={"wo ist die kommode","starbreeze kommode ort","traumfaenger finden"}},{q="Was geschieht, nachdem der Traumfänger zurückgebracht wurde?",a="Sobald Tallonkai das geborgene Amulett untersucht, stellt er fest, dass sein Smaragd fehlt – gestohlen vom Anführer der Gnarlpine, Ferocitas der Traumfresser –, was direkt zur Jagd auf diesen führt.",al={"questfortsetzung","folgequest nach traumfaenger"}}},fx={["1ded4259"]={q="Warum will Tallonkai Flinkwurzel den Smaragdgrüner Traumfänger zurückhaben?",a="Der Smaragdgrüner Traumfänger ist ein seltener und zutiefst persönlicher Schatz. Er wurde Tallonkai von Gaerolas Talvethren, dem Wächter der Druiden im Grabhügel von Ban'ethil, geschenkt und trägt mächtige Magie aus dem Der Smaragdgrüne Traum in sich, um Glück zu bringen. Als Sternenhauch an die verderbten Gnarlpine-Furbolgs fiel, war Tallonkai gezwungen, ihn zurückzulassen. Er befürchtet, dass das heilige Relikt geschändet oder zerstört wird, wenn es in seinem verlassenen Zuhause bleibt.",al={"warum will tallonkai den traumfänger","tallonkai beweggrund","warum smaragdgrüner traumfänger bergen"}}},fp="24,377,18.471.0,26.451.0,24.410.1,33.219.0,59.242.0,27.237.0,26.128.0,56.172.0,48.185.1"}
P.entries["quest:244"] = {n="Eindringende Gnolle",s="Eindringende Gnolle ist eine Allianz-Aufgabe, die die Stadtwache von Seenhain davor warnt, dass Gnolle gefährlich nahe an der Grenze zu Elwynn herumschleichen. Wache Parker entdeckt Lager, die sich entlang des Grenzpasses ansammeln, und schickt Reisende voraus, um Stellvertreter Feldon zu warnen. Die Nachricht bestätigt die wachsende Furcht in Seenhain, dass die Tiermenschen drohen, das Rotkammgebirge vollständig abzuschneiden.",h="Eindringende Gnolle ist eine Allianz-Aufgabe, die die Stadtwache von Seenhain davor warnt, dass Gnolle...",kw={"einschätzung der gefahr","stellvertreter feldon","elwynn-grenze","eindringende gnolle","wache parker","seenhain","rotkammgebirge"},ang={["faction:Alliance"]="Die Isolation Seenhains bedroht die Ostfront der Allianz, was Aufklärung an den Grenzen für Reisende und Versorgungskonvois unerlässlich macht.",["race:Human"]="Das Vordringen von Tiermenschen in Sichtweite des Walds von Elwynn verdeutlicht, wie verwundbar die Kerngebiete des Königreichs in der Abwesenheit des Königs geworden sind."},sec={{t="Wachsame Augen an der Grenze",b="Die Straße, die den Wald von Elwynn mit dem Rotkammgebirge verbindet, sollte eine der sichersten Reiserouten im Königreich sein, doch die ausgedünnten Streitkräfte von Sturmwind lassen sie nur minimal verteidigt zurück. Wache Parker ist entlang des westlichen Grenzpfads stationiert, um Bewegungen zu überwachen. Während es ihm gelingt, die Schotterstraße für Versorgungswagen passierbar zu halten, enthüllen seine Erkundungsausflüge nach Norden und Osten, dass Kriegstrupps der Gnolle aus den Felsen vorgerückt sind und beunruhigend nahe an der Straße Lager aufgeschlagen haben."},{t="Eine Stadt unter Belagerung",b="Als Stellvertreter Feldon die Warnung nahe der Brücke von Seenhain erhält, erkennt er, dass die Lage schlimmer ist als befürchtet. Die Rotkammgnolle überfallen nicht bloß die Außengrenzen der Stadt; ihre vorgelagerte Präsenz nahe der Grenze zu Elwynn lässt darauf schließen, dass sie Seenhain einkesseln und in das Kernland des Königreichs vorstoßen könnten. Da Sturmwind die Bitten um Verstärkung ignoriert, ist die Wache von Seenhain schlecht darauf vorbereitet, eine Bedrohung an zwei Fronten zu bewältigen."}},faq={{q="Wer startet diese Quest?",a="Wache Parker bietet diese Quest entlang der Straße im westlichen Rotkammgebirge an, nahe dem Grenzübergang in den Wald von Elwynn.",al={"questgeber","wo beginnen","wache parker aufenthaltsort"}},{q="Wo finde ich Stellvertreter Feldon?",a="Stellvertreter Feldon ist in Seenhain stationiert und patrouilliert auf dem Gelände direkt südlich der großen Steinbrücke der Stadt.",al={"feldon aufenthaltsort","wer ist stellvertreter feldon","abgabeort"}},{q="Warum sind die Gnolle auf der Straße ein Problem?",a="Die Straße zum Wald von Elwynn ist Seenhains einzige sichere Überlandverbindung zum Rest des Königreichs. Wenn Gnolle die westlichen Hänge einnehmen, ist die Stadt praktisch von Nachschub und Fluchtwegen abgeschnitten.",al={"warum gnolle wichtig sind","rotkamm gnollproblem","straßengefahr"}},{q="Warum schickt Sturmwind Seenhain keine Hilfe?",a="Da König Varian Wrynn verschollen ist und das Reich durch Unruhen belastet wird, weigern sich Hochlord Bolvar und der Hof, königliche Truppen ins Rotkammgebirge zu entsenden, wodurch die Verteidigung Seenhains gänzlich den örtlichen Deputies und Freiwilligen überlassen bleibt.",al={"wo sind stormwind-wachen","keine verstärkung","seenhain verteidigung"}},{q="Was geschieht, nachdem man die Gnolle gemeldet hat?",a="Stellvertreter Feldon bittet Euch, der Sache nachzugehen, indem Ihr in der Quest Einschätzung der Gefahr die Gnoll-Lager genauer auskundschaftet, um die wahre Stärke ihrer Streitkräfte zu ermitteln.",al={"folgequest","questreihenfortsetzung"}},{q="Welche Gnollrudel dringen hier ein?",a="Die Rotkammgnolle, die sich in den Hügeln als Rotkammgnollrudel sammeln, sind zunehmend dreister und koordinierter geworden, während die Kontrolle der Menschen über die Region nachlässt.",al={"welche gnolle","rotkamm gnollclans"}}},fx={e50462f9={q="Warum will Wache Parker, dass dies erledigt wird?",a="Wache Parker ist damit beauftragt, diesen Straßenabschnitt, der in das Rotkammgebirge führt, zu sichern, aber er hat feindliche Gnoll-Lager gesichtet, die sich direkt im Norden und Osten sammeln. Da er einen unmittelbar bevorstehenden Vorstoß befürchtet, der seine Patrouille überwältigen und den Pass abschneiden könnte, muss er dringend die Behörden in Seenhain informieren, bevor die Gnolle die Straße angreifen oder Richtung Wald von Elwynn vorstoßen.",al={"wache parker beweggrund","warum warnung an seenhain","warum schickt euch parker"}},be5d12a2={q="Warum schickt Wache Parker Euch, anstatt selbst zu gehen?",a="Parker hat strenge Befehle, Wache zu halten und die Straße zwischen dem Wald von Elwynn und Rotkammgebirge zu verteidigen. Wenn er seinen Posten verlässt, um zurück in die Stadt zu laufen, bleibt die Grenze völlig unbewacht gegenüber den lauernden Rudeln. Ein rüstiger Reisender, der in Richtung Seenhain unterwegs ist, ist seine beste Chance, die Warnung schnell zu überbringen, ohne seine Pflicht zu vernachlässigen.",al={"warum schickt ihr mich","warum geht parker nicht","warum kann wache parker nicht melden"}}},fp="18,361,18.460.0,18.417.0,22.121.0,31.108.0,40.190.0,45.214.0,40.159.0,39.159.0"}
P.entries["quest:245"] = {n="Gefahr auf acht Beinen",s="Gefahr auf acht Beinen ist ein Milizvertrag, der von Behüter Dodds im Dämmerwald ausgestellt wird. Da die westliche Grenze von aggressiven Giftnetzspinnen überrannt wird, ist die unterbesetzte Nachtwache darauf angewiesen, dass wandernde Abenteurer die Brut dezimieren, bevor noch mehr Wachen in ihren Netzen gefangen werden.",h="Gefahr auf acht Beinen ist ein Milizvertrag, der von Behüter Dodds im Dämmerwald ausgestellt wird.",kw={"dunkelhain","dämmerwald","gefahr auf acht beinen","nachtwache","zwergenhafte giftnetzspinne","spinnen","behüter dodds"},ang={["class:Hunter"]="Die Giftnetzspinnen des Dämmerwaldes sind bösartige Bestien, die sorgfältige Fußarbeit und die Vorbereitung von Gegengiften erfordern, um sie effektiv zu jagen.",["faction:Alliance"]="Die Nachtwache steht ohne die Hilfe des Hauses der Adligen völlig allein da, weshalb jede Unterstützung, die Abenteurer der Allianz leisten, entscheidend dafür ist, die Straßen offen zu halten."},sec={{t="Eine Grenze unter Belagerung",b="Entlang der westlichen Straße, die Westfall mit dem Dämmerwald verbindet, weicht das dichte Blätterdach verfilztem Dickicht, das von Spinnweben erstickt wird. Als die Dunkelheit ihre Fänge um Grand Hamlet schloss und es in den verwunschenen Hain verwandelte, der heute als solcher bekannt ist, mutierten die heimischen Spinnentiere zu monströsen Raubtieren. Zwergenhafte Giftnetzspinnen verseuchen nun das Gestrüpp in Schwärmen, bedrohen Reisende und rücken den schwachen Verteidigungslinien der Nachtwache immer näher."},{t="Die Last der Nachtwache",b="Weit entfernt von der Sicherheit von Dunkelhain stationiert, leidet Behüter Dodds unter einem verzweifelten Mangel an Truppen. Kommandantin Althea Schwarzhaupt kann keine Verstärkung für die Sicherung entlegener Außenposten entbehren, während Untote und Worgen die Siedlung selbst bedrängen. Isolierter denn je, musste Dodds bereits mitansehen, wie Kameraden den Spinnen zum Opfer fielen, und fand Männer kopfüber im Blätterdach hängend, während lähmendes Gift sie langsam für die Fütterung verflüssigte."}},faq={{q="Wer bietet diese Quest an?",a="Behüter Dodds, ein Mitglied der Nachtwache, das in einem kleinen Lager im Dämmerwald stationiert ist, bietet Reisenden, die in der Lage sind, die Spinnen zu beseitigen, diese Aufgabe an.",al={"questgeber","wer gibt gefahr auf acht beinen","behüter dodds"}},{q="Warum kann die Nachtwache die Spinnen nicht selbst bekämpfen?",a="Kommandantin Althea Schwarzhaupt muss ihre knappe Garnison in der Nähe von Dunkelhain konzentrieren, um unaufhörliche Angriffe der Untoten abzuwehren. Dodds fehlen die Arbeitskräfte, um die verseuchten Nester an der Grenze anzugreifen, ohne seinen Posten aufzugeben.",al={"warum wird hilfe benötigt","warum abenteurer rufen","dunkelhain milizmangel"}},{q="Wo befinden sich diese Spinnen?",a="Die zwergenhaften Giftnetzspinnen nisten zahlreich in den westlichen Wäldern des Dämmerwaldes und lauern im Gebüsch direkt neben der Hauptstraße, die von Westfall herführt.",al={"spinnenfundort","wo sind zwergenhafte giftnetzspinnen","spinnenwälder"}},{q="Was macht diese Spinnen so gefährlich für die Wache?",a="Abgesehen von ihrer schieren Anzahl besitzen sie ein starkes Gift, das Fleisch lähmt und zersetzt, wodurch gefangene Nachtwächter hilflos in den Ästen hängen und leichte Beute sind.",al={"spinnengift","spinnengiftwirkung","spinnenopfer"}},{q="Sind dies die einzigen Spinnen im Dämmerwald?",a="Nein. Die zwergenhaften Giftnetzspinnen sind lediglich die kleineren Jungtiere. Tiefer in den Wäldern hausen weitaus größere, tödlichere Exemplare, die eine noch größere Gefahr für Reisende darstellen.",al={"andere dämmerwaldspinnen","spinnenarten","giftnetzspinnen"}},{q="Warum ist die Insekten- und Spinnenpopulation so aggressiv gewachsen?",a="Die allgegenwärtige magische Verderbnis, die den Dämmerwald bedeckt, hat die einheimische Tierwelt verzerrt und ihre Aggressivität, Größe und Tödlichkeit im gesamten verseuchten Wald beschleunigt.",al={"warum so viele spinnen","dämmerwald verderbnis natur","spinnenursprung"}}},fx={["19037cd1"]={q="Warum will Behüter Dodds, dass die Spinnen dezimiert werden?",a="Pygmäengiftnetzspinnen haben die westliche Grenze von Dämmerwald übernommen, und The Night Watch hat zu wenig Männer, um mit ihnen fertig zu werden. Behüter Dodds hat bereits mehrere seiner Männer an ihr Gift und ihre Netze verloren, und Kommandant Schwarzhaupt kann keine Soldaten so weit von Dunkelhain entbehren.",al={"warum pygmäengiftnetzspinnen töten","dodds spinnen beweggrund","warum will dodds das erledigt haben"}},["3807547d"]={q="Was sind die Pygmäengiftnetzspinnen?",a="Pygmäengiftnetzspinnen sind aggressiv territoriale Spinnentiere, die die westlichen Grenzgebiete von Dämmerwald befallen. Obwohl sie kleiner sind als die ausgewachsenen monströsen Spinnen tiefer im Wald, jagen sie in Schwärmen, verstricken unvorsichtige Reisende in Netznestern und produzieren ein starkes Gift, das in der Lage ist, das Fleisch ihrer Beute von innen heraus zu schmelzen.",al={"pygmäengiftnetzspinnen","wen jagen wir","spinnen westlicher dämmerwald"}}},fp="20,268,20.429.0,29.421.0,22.145.0,56.206.0,32.143.0,51.178.0,39.165.0,63.171.0"}
P.entries["quest:2458"] = {n="Undercover",s="Undercover ist ein verdeckter Auftrag, der vielversprechenden Schurken der Horde von Shenthul in Orgrimmar erteilt wird. Der Einsatz entsendet den Agenten zu den Bohrplätzen der Venture Company im Schlickermoor, um heimlich Kontakt mit einem eingeschleusten Agenten der Shattered-Hand aufzunehmen.",h="Undercover ist ein verdeckter Auftrag, der vielversprechenden Schurken der Horde von Shenthul in Orgrimmar...",kw={"brachland schurke","undercover","signalpistole","shattered-hand","shenthul","das schlickermoor","zuchtmeister fizzule","venture company"},ang={["class:Rogue"]="Dieser Auftrag markiert einen entscheidenden Meilenstein für aufstrebende Schurken der Horde und verwandelt sie von einfachen Straßenspähern in vertrauenswürdige Agenten, die zu verdeckter Koordination im Feld fähig sind.",["faction:Horde"]="Die unablässigen Rodungen und Bohrungen der Venture Company im Brachland gefährden die territoriale Kontrolle und die natürlichen Ressourcen der Horde, was aggressive Spionage erforderlich macht."},sec={{t="Ein Spion unter Geschäftemachern",b="Die Zerschmetterte Hand agiert als geheimer Aufklärungsdienst und Meuchelmördergilde der Horde, die Orgrimmars Interessen im Verborgenen mit skrupellos pragmatischen Mitteln schützt. Ein ganzes Jahr lang mühte sich die Gilde ab, einen Agenten in die Hierarchie der unersättlichen Venture Company einzuschleusen. Diesem Kontakt, Zuchtmeister Fizzule, gelang es, sich in deren industriellem Bohraußenteil nördlich des Schlickermoors beliebt zu machen."},{t="Zeichen und Signale",b="Tief hinter den feindlichen Söldnerlinien zu operieren, lässt keinen Raum für Fehler. Da Fizzule eine rücksichtslose Fassade aufrechterhält, um seine Vorgesetzten zufriedenzustellen, riskiert jeder unangekündigte Besucher einen sofortigen Angriff. Um ihre Identität zu belegen, müssen eintreffende Schurken in Sichtweite seines Turms zwei Leuchtraketen aus einer dafür vorgesehenen Signalpistole abfeuern, sich leise nähern und den geheimen Gruß der Shattered-Hand entbieten, bevor sie seinen Bericht über die eskalierenden Vorhaben der Venture Company erhalten."}},faq={{q="Wer ist Zuchtmeister Fizzule?",a="Zuchtmeister Fizzule ist ein Undercover-Agent der Shattered-Hand, der in der Hierarchie der Venture Company nördlich des Schlickermoors platziert wurde. Er verbrachte ein ganzes Jahr damit, unter den Söldnern in eine Autoritätsposition aufzusteigen, ihre Machenschaften zu beobachten und Berichte nach Orgrimmar weiterzuleiten.",al={"fizzule","wer ist fizzule","zuchtmeister fizzule identität"}},{q="Warum greift Fizzule an, wenn man ihm kein ordentliches Signal gibt?",a="Fizzule wahrt seine Tarnung als grobschlächtiger, hartherziger Zuchtmeister der Venture Company. Nähert sich jemand seinem Posten, ohne das exakte Signal mit zwei Leuchtraketen und den Gruß der Shattered-Hand vorzulegen, muss er annehmen, dass es sich um feindliche Eindringlinge oder gegnerische Firmenagenten handelt, und greift sie auf der Stelle an, um seine Deckung zu bewahren.",al={"warum fizzule angreift","fizzule feindlich","fizzule tötet mich"}},{q="Wo befindet sich der Turm der Venture Company?",a="Der Turm überblickt die industriellen Anlagen unmittelbar nördlich des Schlickermoors, im zentralen nördlichen Teil des Brachlands.",al={"fizzule standort","turm standort","wo ist der schlickermoor turm"}},{q="Warum spioniert die Horde die Venture Company aus?",a="Die Venture Company ist berüchtigt für rücksichtslosen Raubbau, Ausbeutung und brutale Gewalt in ganz Kalimdor. Jüngste von der Shattered-Hand gesammelte Informationen offenbarten, dass das Kartell ein großes Vorhaben im Brachland plant, was Shenthul dazu veranlasste, seinen Kontakt zu aktivieren.",al={"warum venture co ausspionieren","venture co bedrohung"}},{q="Was geschieht nach der Kontaktaufnahme mit Fizzule?",a="Sobald der Kontakt sicher hergestellt ist, weist Fizzule den Schurken an, den nahegelegenen Turm der Venture Company zu infiltrieren, dessen Bewohner einschließlich Grand Foreman Puzik Gallywix zu töten und den Behälter mit Zanzils veränderter Mixtur zu stehlen, um seinen Wert für die Gilde zu beweisen.",al={"wie geht es nach undercover weiter","nach fizzule"}},{q="Was ist die Shattered-Hand?",a="Die Zerschmetterte Hand ist das finstere Netzwerk aus Schurken, Spionen und Meuchelmördern, das von der Kluft der Schatten in Orgrimmar aus operiert. Einst ein berüchtigter Clan auf Draenor, dient sie in der neuen Horde als verdeckter Nachrichtendienst der Horde.",al={"die shattered-hand","wer ist die shattered-hand"}}},fx={aa88dce8={q="Warum schickt Shenthul Euch, um Kontakt aufzunehmen, anstatt selbst zu gehen?",a="Shenthul ist ein Ausbilder, der Schurkenoperationen aus den Schatten von Orgrimmar koordiniert, während Zuchtmeister Fizzule tief im feindlichen Territorium im Das Schlickermoor eingebettet ist. Das Eindringen in eine aktive Basis von The Venture Co. erfordert einen wendigen Feldagenten, der an Wachen vorbeischlüpfen und einen Undercover-Agenten unbemerkt signalisieren kann, ohne die Aufmerksamkeit von Unternehmens-Söldnern zu erregen oder den gesamten Ring von The Shattered Hand zu gefährden.",al={"warum schickt ihr mich","warum braucht mich shenthul","warum geht er nicht selbst"}}},fp="10,261,22.401.0,17.460.0,26.284.0,58.308.0,43.136.0,47.276.0,47.264.1,27.233.0"}
P.entries["quest:2459"] = {n="Ferocitas der Traumfresser",s="Ferocitas der Traumfresser ist eine Quest der Allianz, die von Tallonkai Flinkwurzel in Dolanaar vergeben wird. Nachdem er seinen beschädigten Erbstück-Traumfänger zurückerhalten hat, stellt Tallonkai fest, dass dessen mächtiger Smaragdkern von Gnarlpinefurbolgs nördlich von Sternenhauch herausgebrochen wurde. Abenteurer werden ausgesandt, um die verdorbenen Mystiker zu erschlagen und das gestohlene Juwel von ihrem Anführer, Ferocitas, zurückzuholen.",h="Ferocitas der Traumfresser ist eine Quest der Allianz, die von Tallonkai Flinkwurzel in Dolanaar vergeben...",kw={"dolanaar","traumfresser","smaragdgrüner traumfänger","ferocitas","gnarlpinemystiker","starbreeze","tallonkai flinkwurzel","tallonkais juwel","teldrassil"},ang={["class:Druid"]="Traumfänger sind mächtige Werkzeuge, die mit dem Smaragdgrünen Traum verbunden sind; mitansehen zu müssen, wie ein solcher von einem verdorbenen Furbolg geschändet wird, verlangt nach rascher Vergeltung der Natur.",["race:NightElf"]="Die Gnarlpine waren einst Verbündete der Kaldorei, was die Verderbnis ihrer Mystiker und den Diebstahl heiliger Talismane zu einer schmerzhaften Tragödie für jeden Nachtelfen macht, der Teldrassil verteidigt."},sec={{t="Ein geschändetes Erbstück",b="Als Tallonkai Flinkwurzel den aus der verdorbenen Wildnis geborgenen Traumfänger untersuchte, schlug Erleichterung schnell in Bestürzung um. Das heilige Artefakt war geschändet worden; sein leuchtend grünes Smaragd-Mittelstück war aus dem geflochtenen Rahmen herausgebrochen. Unter den Nachtelfen hieß es, dass eine Gruppe von Gnarlpinemystikern nördlich von Sternenhauch unter den Einfluss eines Furbolganführers namens Ferocitas der Traumfresser geraten war, der schamlos einen strahlend grünen Stein um den Hals trug. In dem Wissen, dass das heilige Juwel in den Klauen dieser Kreatur nutzlos und entweiht war, sandte Tallonkai Verteidiger aus, um es zurückzuholen."},{t="Die Läuterung der Mystiker",b="Die Gnarlpinefurbolgs, die Teldrassils nördliche Gefilde bewohnen, waren einst friedliche Nachbarn, doch die wachsende Verderbnis, die in den Weltenbaum sickerte, trieb sie in Raserei und Wahnsinn. Ihre Mystiker, die einst harmonische Naturrituale vollführten, begannen verzerrte magische Energien anzuzapfen. Indem sie Ferocitas aufspüren und sein mystisches Gefolge niederkämpfen, das seine Wald-Enklave bewacht, stellen Reisende das Gleichgewicht der Wälder wieder her und bringen Tallonkais Juwel zurück, damit der Traumfänger endlich wieder vervollständigt werden kann."}},faq={{q="Wo finde ich Ferocitas den Traumfresser?",a="Ferocitas der Traumfresser befindet sich im Wald nördlich von Sternenhauch auf Teldrassil, umgeben von verdorbenen Gnarlpinemystikern und anderen Gefahren des Waldes.",al={"ferocitas aufenthaltsort","wo ist ferocitas","traumfresser finden"}},{q="Wer ist Ferocitas?",a="Ferocitas ist ein Gnarlpinefurbolg-Anführer, der eine Schar verdorbener Gnarlpinemystiker nördlich von Sternenhauch befehligt. Er nahm den Smaragd aus Tallonkai Flinkwurzels Traumfänger und machte daraus eine grobe Halskette.",al={"wer ist ferocitas","ferocitas hintergrundgeschichte","was ist der traumfresser"}},{q="Warum will Tallonkai Flinkwurzel das Juwel zurück?",a="Der fehlende Smaragd ist die zentrale Kraftquelle von Tallonkais Traumfänger. Ohne ihn kann der Talisman weder repariert werden, noch die schützenden Energien des Smaragdgrünen Traums kanalisieren.",al={"warum tallonkai juwel will","zweck tallonkais juwel"}},{q="Können die Gnarlpine die Magie des Smaragds überhaupt nutzen?",a="Nein. Laut Tallonkai Flinkwurzel sind die magischen Eigenschaften des Smaragds für Kreaturen wie Ferocitas und die Gnarlpinemystiker völlig nutzlos, die ihn lediglich als glänzenden Ziergegenstand begehrten.",al={"können gnarlpine traumfänger nutzen","nutzt ferocitas smaragd"}},{q="Was geschieht nach dieser Quest?",a="Diese Quest ist das letzte Kapitel der zweiteiligen Reihe, die mit dem smaragdgrünen Traumfänger begann. Sobald Ihr das Juwel zu Tallonkai in Dolanaar bringt, kann er sein Erbstück endlich reparieren.",al={"quest nach ferocitas","nächste quest traumfänger"}},{q="Warum sind die Gnarlpinemystiker feindselig?",a="Wie viele der Wildtiere und Furbolgstämme auf Teldrassil sind auch die Gnarlpine einer seltsamen Verderbnis erlegen, die das Geäst des neu gepflanzten Weltenbaums verformt, ihren Geist verwirrt und sie aggressiv macht.",al={"warum furbolgs verrückt","die verderbnis der knarzklauen"}}},fx={["80c83c66"]={q="Wofür ist Tallonkais Juwel?",a="Der fehlende Smaragd ist der lebenswichtige Fokus des beschädigten Traumfängers von Tallonkai Flinkwurzel. Ohne ihn kann der Talisman nicht funktionieren, und er braucht den Stein intakt zurück, damit er den heiligen Schutz endlich reparieren kann.",al={"was ist tallonkais juwel","zweck tallonkais juwel","nutzen fehlender smaragd"}}},fp="25,360,18.578.0,19.503.0,42.163.0,17.219.0,49.174.0,51.191.0,30.184.0,38.218.0"}
P.entries["quest:246"] = {n="Einschätzung der Gefahr",s="Einschätzung der Gefahr ist eine defensive Aufklärungsoperation, die von Stellvertreter Feldon in Seenhain in Auftrag gegeben wurde. Da die örtliche Garnison überlastet ist und Verstärkung aus Sturmwind verwehrt bleibt, werden Abenteurer angeheuert, um vordringende Gnollrudel entlang der südlichen Straße auszudünnen und die Stärke der wachsenden Bedrohung zu ermitteln.",h="Einschätzung der Gefahr ist eine defensive Aufklärungsoperation, die von Stellvertreter Feldon in Seenhain in...",kw={"einschätzung","feldon","gnolle","seenhain","mongrel","poacher","aufklärung","rotkammgebirge","gefahr"},ang={["class:Warrior"]="Stellvertreter Feldon bittet um aggressive Kampfaufklärung und stellt die Fähigkeit eines bewaffneten Streiters auf die Probe, in befestigte feindliche Lager vorzudringen und deren Vorhut zu brechen.",["faction:Alliance"]="Das Rotkammgebirge zeigt die Risse im Kernland der Allianz, wo vernachlässigte Grenzsiedlungen freischaffende Recken anheuern müssen, um zu überleben, während die Hauptstadt wegsieht.",["race:Human"]="Für menschliche Verteidiger ist der Schutz von Seenhain eine persönliche Angelegenheit; diese Grenzfamilien ertragen die Konsequenzen der politischen Lähmung in Burg Sturmwind."},sec={{t="Eine angespannte Grenze",b="Der Ort Seenhain kämpft an mehreren Fronten ums Überleben. Während Kriegstrupps der Blackrockorcs von den Höhen herabsteigen und aggressive Gnollrudel die Täler heimsuchen, können die örtlichen Verteidiger keine Truppen für gewöhnliche Aufklärungspatrouillen entbehren. Als erste Berichte bestätigten, dass Gnolle über die Grenze vordringen, wandte sich Stellvertreter Feldon an Hilfe von außen. Anstatt reguläre Wachen in die Wildnis zu entsenden, bezahlt der Ort reisende Helden dafür, die Stärke des Feindes aus erster Hand auf die Probe zu stellen."},{t="Gewaltsame Aufklärung",b="Die Mission entsendet Späher entlang der südlichen Straße des Rotkammgebirges, um in die Lager der Bastarde der Rotkammgnolle und Wilderer der Rotkammgnolle vorzudringen. Hierbei handelt es sich um Informationsbeschaffung durch Zermürbung: Vorhutspäher ausschalten, Nachschublinien stören und abschätzen, ob die Rudel lediglich umherstreifende Aasfresser sind oder Teil einer organisierten militärischen Präsenz, die die Siedlung bedroht. Die blutigen Scharmützel verschaffen Feldon die konkreten Zahlen, die er zur Planung der angespannten Verteidigung von Seenhain benötigt."}},faq={{q="Warum sendet Stellvertreter Feldon Abenteurer anstelle von Stadtwachen?",a="Seenhains Garnison ist kritisch unterbesetzt. Da keine Verstärkung aus Sturmwind eintrifft und feindliche Truppen aus allen Richtungen vordringen, kann die Stadtwache die für ausgedehnte Patrouillen entlang der südlichen Straße erforderlichen Soldaten nicht entbehren.",al={"warum abenteurer anheuern","wo sind die wachen","seenhain wachenmangel"}},{q="Wo befinden sich die Gnolle für diese Mission?",a="Die Bastarde der Rotkammgnolle und Wilderer der Rotkammgnolle errichten lose Kriegslager entlang der südlichen Straße und den niedrigen Ausläufern des Rotkammgebirges, südlich von Seenhain und nahe den Grenzspässen.",al={"wo sind bastarde der rotkammgnolle","gnoll standorte rotkammgebirge","südliche straße gnolle"}},{q="Was ist der strategische Zweck der Dezimierung dieser Gnolle?",a="Die Operation erfüllt zwei Zwecke: Sie drängt vorgeschobene Späher zurück, die auf die Straße vordringen, und liefert militärische Aufklärung aus erster Hand über die Größe, Bewaffnung und Disziplin der Gnolle des Rotkammgebirges.",al={"warum gnolle töten","ziel der gefahreneinschätzung","seenhain verteidigung"}},{q="Hilft Sturmwind bei der Bedrohung durch die Gnolle?",a="Nein. Das Haus der Adligen von Sturmwind und der Regentschaftsrat verweigern abgelegenen Regionen wie dem Rotkammgebirge reguläre militärische Unterstützung, was örtliche Autoritäten wie Magistrat Solomon und Stellvertreter Feldon dazu zwingt, auf bezahlte Söldner zurückzugreifen.",al={"sturmwind verstärkung","warum hilft sturmwind nicht","sturmwind armee seenhain"}},{q="Was macht Stellvertreter Feldon mit Eurem Bericht?",a="Stellvertreter Feldon bewertet die Stärke und Zähigkeit der Rudel, bestätigt, dass die südlichen Gnolle eine ernsthafte militärische Bedrohung statt isolierter Bestien darstellen, und weist Euch an, anderen Anführern des Ortes bei der Stärkung der Verteidigung beizustehen.",al={"feldons reaktion","was geschieht nach gefahreneinschätzung","bericht abgeben"}},{q="Wie hängt diese Aufgabe mit der vorherigen Quest zusammen?",a="Sie ist die direkte Fortsetzung von Eindringende Gnolle. Nachdem Ihr die Garnison erstmals auf die Bewegungen der Gnolle aufmerksam gemacht hattet, gab Feldon diese Kampfpatrouille in Auftrag, um festzustellen, wie gravierend der Übergriff tatsächlich ist.",al={"questreihenverbindung","eindringende gnolle folgequest","vorquest"}}},fx={["6de7b21c"]={q="Wer sind die Gnolle aus dem Rotkammgebirge, die Ihr ausdünnen sollt?",a="Ihr werdet gegen die Bastarde der Rotkammgnolle und die Wilderer der Rotkammgnolle ausgesandt, die entlang der südlichen Straße ihr Lager aufgeschlagen haben. Diese wilden Gnolle sammeln sich direkt an der Lebensader der Stadt, belästigen Reisende, unterbinden Versorgungswege und rücken gefährlich nahe an Seenhain heran, während die Verteidigung der Stadt bereits bis an ihre Grenzen strapaziert ist.",al={"bastarde der rotkammgnolle wilderer","wer sind die gnolle im rotkammgebirge","bedrohung durch rotkammgnolle"}}},fp="20,305,19.493.0,23.461.0,63.247.0,46.170.0,54.208.0,47.229.0,44.231.0,46.193.0"}
P.entries["quest:2460"] = {n="Der Gruß der Zerschmetterten Hand",s="Der Shattered-Gruß ist ein Initiationsritual unter der Aufsicht von Shenthul in der Kluft der Schatten in Orgrimmar. Durch das Erlernen dieses eindeutigen Erkennungszeichens erfahren angehende Schurken, wie sie Verbündete der Shattered-Hand im Feld sicher identifizieren.",h="Der Shattered-Gruß ist ein Initiationsritual unter der Aufsicht von Shenthul in der Kluft der Schatten in...",kw={"kluft der schatten","verdeckt","undercover","orgrimmar","schurke","die shattered-hand","der shattered-gruß","shenthul"},ang={["class:Rogue"]="Für einen Schurken der Horde markiert das Beherrschen der geheimen Signale der Shattered-Hand den Übergang vom gewöhnlichen Beutelschneider zum vertrauenswürdigen Agenten des Aufklärungsnetzwerks von Orgrimmar.",["faction:Horde"]="Obwohl Kriegshäuptling Thrall mit Ehre führt, verlässt sich die Horde stark auf die heimlichen Methoden der Shattered-Hand, um Bedrohungen zu neutralisieren, bevor sie an die Oberfläche gelangen."},sec={{t="Zeichen und Schatten",b="In den dunklen Tunneln der Kluft der Schatten agiert die Shattered-Hand als geheimer Aufklärungs- und Attentatszweig von Thralls Horde. Angesichts der gefährlichen und geheimen Natur ihrer Aufträge können sich Agenten nicht auf offenkundige Banner oder standardmäßige militärische Heraldik verlassen. Shenthul unterweist neu aufgenommene Schurken im Shattered-Gruß, einer bestimmten Geste, die Verbündeten als unmissverständliches, lautloses Signal dienen soll."},{t="Vorbereitung auf den Einsatz",b="Die Beherrschung des Grußes ist keine bloße zeremonielle Übung; sie ist lebenswichtiges Handwerk. Schurkenagenten, die in gefährliches Terrain entsandt werden oder mit der Infiltration rivalisierender Fraktionen betraut sind, müssen Kontakte verifizieren, ohne Umstehende oder Zielpersonen zu alarmieren. Shenthul besteht darauf, dass ein Agent die Geste mühelos erkennen und erwidern kann, bevor er ihm verdeckte Feldeinsätze anvertraut."}},faq={{q="Was ist der Zweck des Shattered-Grußes?",a="Der Shattered-Gruß dient als geheimes Erkennungssignal unter Mitgliedern der Shattered-Hand. Er ermöglicht es Agenten, einander im verdeckten Einsatz oder in feindlichem Gebiet zu erkennen, ohne ihre wahre Zugehörigkeit gegenüber Außenstehenden preiszugeben.",al={"warum brauche ich den gruß","zweck shattered-gruß","was bewirkt der gruß"}},{q="Wer lehrt den Shattered-Gruß?",a="Der Gruß wird von Shenthul gelehrt, einem Schurkenlehrer tief in der Kluft der Schatten unterhalb von Orgrimmar.",al={"wer gibt die quest","wer ist shenthul","wo lerne ich den gruß"}},{q="Welche Organisation verwendet diese Geste?",a="Er wird von der Shattered-Hand genutzt, einem Orden orkischer Schurken, Spione und Attentäter, der der modernen Horde aus den Schatten von Orgrimmar heraus dient.",al={"clan der shattered-hand","wer ist die shattered-hand","welche gilde nutzt das"}},{q="Warum ist das Erlernen des Grußes vor dem Einsatz im Feld notwendig?",a="Agenten, die auf Infiltrationsmissionen entsandt werden – etwa zur Kontaktaufnahme mit Undercover-Agenten –, sind auf den Gruß angewiesen, um ihre Tarnung nicht auffliegen zu lassen oder einen Feind nicht fälschlich für einen Verbündeten zu halten.",al={"warum gruß üben","ist der gruß erforderlich"}},{q="Wo findet dieses Training statt?",a="Das Training findet in der Kluft der Schatten statt, dem unterirdischen Bezirk unterhalb von Orgrimmar, in dem Schurken, Hexenmeister und andere Ausübende verbotener Künste abseits öffentlicher Blicke zusammenkommen.",al={"standort des grußes","wo befindet sich shenthul"}},{q="Welcher Auftrag folgt nach dem Meistern des Grußes?",a="Sobald Shenthul mit der Beherrschung des Grußes durch einen Agenten zufrieden ist, teilt er ihn Operationen zu, bei denen er Undercover agieren muss, und prüft seine Fähigkeit, das Signal zur Kontaktaufnahme mit Agenten im Feld einzusetzen.",al={"was kommt danach","nächste quest nach gruß","quest undercover"}}},fp="20,257,17.431.0,25.365.0,44.230.0,33.111.0,36.141.0,65.174.0,36.193.0,51.183.0"}
P.entries["quest:247"] = {n="Die Jagd ist abgeschlossen",s="„Die Jagd ist abgeschlossen“ ist der krönende Abschluss von Senani Donnerherz' Prüfungen der großen Bestien in Eschental. Durch das Erlegen von Ursangous, Shadumbra und Sharptalon beweist ein Champion der Horde seine Stärke, Hartnäckigkeit und urwüchsige Meisterschaft in einem umkämpften Wald.",h="„Die Jagd ist abgeschlossen“ ist der krönende Abschluss von Senani Donnerherz' Prüfungen der großen Bestien...",kw={"eschental","bestien","jagd","raubtier","senani","shadumbra","sharptalon","thunderheart","trophäe","ursangous"},ang={["class:Hunter"]="Das Bezwingen von drei Spitzenprädatoren des Eschentals ist der ultimative Ritus des Fährtenlesens und der Treffsicherheit, der beweist, dass Eure Instinkte denen der wilden Bestien selbst ebenbürtig sind.",["faction:Horde"]="Das Bezwingen der Bestien von Eschental hilft dabei, den Stützpunkt der Horde in einem gefährlichen, feindseligen Waldgebiet zu sichern, das gleichermaßen von Raubtieren und Schildwachen der Allianz bevölkert ist.",["race:Tauren"]="Für die Shu'halo ist das Jagen von Ursangous, Shadumbra und Sharptalon eine traditionsreiche Prüfung von Respekt, Gleichgewicht und Stolz der Ahnen."},sec={{t="Der Beweis eines Jägers",b="Senani Donnerherz, die bei den Streitkräften der Horde in Eschental stationiert ist, prüft Reisende nicht bloß nach ihrer Loyalität zum Kriegshäuptling, sondern nach ihrem Verständnis für das Überleben in der Wildnis. Die Jagd in Eschental zielt auf drei legendäre Raubtiere ab, die unter dem uralten Blätterdach lauern: der Bär Ursangous, die Katze Shadumbra und der wilde Hippogryph Sharptalon. Das Erlegen aller drei und das Sichern ihrer Trophäen beweist, dass wahres Jägerblut in den Adern des Herausforderers fließt."},{t="Die Ahnen ehren",b="Für die Tauren ist die Jagd ein heiliger Akt des Gleichgewichts und des Respekts, selbst inmitten einer aktiven Kriegsfront. Indem ein Jäger die gefürchtetsten Spitzenprädatoren des Eschentals bezwingt, ehrt er die Geister des Landes und verdient sich die Segnungen der Ahnen von Thunderheart. Die Jagd endet mit einer formellen Anerkennung und einem Zeichen des Wohlwollens, was den Ruf des Champions im gesamten Wald festigt."}},faq={{q="Wer bietet diese Quest an und wo befindet sich die Person?",a="Die Quest wird bei Senani Donnerherz abgeschlossen, einer Taurenjägerin, die bei der Horde in den uralten Wäldern von Eschental stationiert ist.",al={"questgeber","wo abgeben","senani donnerherz aufenthaltsort"}},{q="Was sind die Voraussetzungen, um die Jagd abzuschließen?",a="Ihr müsst drei Spitzenprädatoren erschlagen, die Eschental durchstreifen, und den Beweis ihres Ablebens erbringen: die Tatze des Bären Ursangous, den Kopf des Nachtsäblers Shadumbra und die Kralle des Hippogryphen Sharptalon.",al={"welche bestien töten","voraussetzungen","welche tiere"}},{q="Warum möchte Senani Donnerherz, dass diese Bestien erlegt werden?",a="Die Jagd dient als Prüfung von Stärke und Ausdauer. Das Erlegen solch furchterregender Bestien beweist, dass ein Reisender das wahre Herz und den Instinkt eines Jägers besitzt, der in Eschentals tückischer Wildnis überleben kann.",al={"warum jagen","senanis motiv","zweck der jagd"}},{q="Welche kulturelle Bedeutung hat die Jagd für die Horde?",a="Für Tauren wie Senani Donnerherz ist das Kräftemessen mit mächtigen Bestien eine ehrenvolle Tradition, die die Geister und Ahnen anspricht. Sie beweist die Beherrschung der Wildnis ohne leichtfertige Ehrlosigkeit.",al={"lore der taurenjagd","kulturelle bedeutung","warum tauren bestien jagen"}},{q="Wird diese Prüfung von der gesamten Horde anerkannt?",a="Ja. Der Abschluss der Jagd zeichnet Euch in den Augen der in Eschental stationierten Horde als bewährten Jäger aus und bringt Euch den Segen der Ahnen sowie den Respekt Eurer Kameraden ein.",al={"anerkennung der horde","ist es offiziell","belobigung der horde"}},{q="Welche drei Bestien sind das Ziel der Jagd im Eschental?",a="Die Ziele sind Ursangous der große Bär, Shadumbra der lautlose Nachtsäbler und Sharptalon der tödliche Hippogryph.",al={"die drei bestien","jagdziele","benannte tiere"}}},fx={ded238b8={q="Welche Bestien musstet Ihr für die The Ashenvale Hunt erlegen?",a="Die Prüfung verlangte von Euch, drei der grausamsten Raubtiere vom Eschental aufzuspüren und zu erlegen: den uralten Bären Ursangous, den schwer fassbaren Nachtsäbler Shadumbra und den wilden Hippogryphen Scharfklaue. Diese wilden Bestien beherrschten das Blätterdach und das Dickicht des Waldes, stellten eine ernste Bedrohung für Reisende dar und dienten als ultimativer Test für Stärke, Geduld und Jagdgeschick in der ungezähmten Wildnis.",al={"welche bestien habe ich getötet","ziele ashenvale hunt","welche bestien jagd abgeschlossen"}}},fp="18,243,16.447.0,22.354.0,49.128.0,47.201.0,53.215.0,59.217.0,45.164.0,54.114.0"}
P.entries["quest:2478"] = {n="Mission: möglich, aber nicht sehr wahrscheinlich",s="Dieser entscheidende Auftrag stellt die Tarnung, das Diebeshandwerk und die Kampffertigkeiten eines Schurken der Horde gegen einen abtrünnigen Außenposten der Venture Company im nördlichen Brachland auf die Probe. Agenten infiltrieren einen Ölturm, ermorden Grand Foreman Puzik Gallywix und beschlagnahmen ein wirksames chemisches Gebräu für The Shattered Hand.",h="Dieser entscheidende Auftrag stellt die Tarnung, das Diebeshandwerk und die Kampffertigkeiten eines Schurken...",kw={"brachland","fizzule","schlossknacken","gifte","puzik gallywix","the shattered hand","shenthul","silixiz","das schlickermoor","zanzil"},ang={["class:Rogue"]="Diese Reifeprüfung vermittelt praktische Feldarbeit im Schlossknacken, Taschendiebstahl und dem Ausnutzen von Schwachstellen und dient als Einstieg in das tödliche Handwerk und die Gifte von The Shattered Hand.",["faction:Horde"]="The Shattered Hand agiert aus den Schatten von Orgrimmar und behält gefährliche korporative Eindringlinge wie die Venture Company im Auge, die das Brachland ausbeuten."},sec={{t="Infiltration der Venture Co.",b="Nördlich der Bohrinseln im Schlickermoor unterhält die Venture Company einen isolierten Bohrturm. Auf Befehl von Zuchtmeister Fizzule, einem eingeschleusten Agenten von The Shattered Hand, der sich als Aufseher der Venture Company ausgibt, werden Schurken angewiesen, klassische Unterweltmethoden statt eines direkten Angriffs anzuwenden. Fizzule fordert Schurken auf, Foreman Silixiz direkt per Taschendiebstahl einen Schlüssel zu stehlen und ihn für ihn aufzubewahren, bevor sie den Aufstieg durch schwer veränderte Arbeiter und Wachen antreten."},{t="Eine chemische Katastrophe",b="Die Bewohner des Turms wurden durch eine experimentelle Substanz zutiefst gezeichnet: Zanzils veränderte Mischung. Während das Gift die Wachen geschwächt hat – was sie ungewöhnlich anfällig für schnelle Schläge, Blutungseffekte und plötzliche Hinterhalte macht –, hat es die Einrichtung zudem höchst instabil zurückgelassen. An der Spitze lauert Grand Foreman Puzik Gallywix, der eine Schließkassette bewacht, die das volatile Gebräu selbst enthält."},{t="Der Preis der Pflicht",b="Das Knacken von Gallywixs Schließkassette setzt den Schurken unweigerlich den heimtückischen Dämpfen der veränderten Mischung aus, was ein schwächendes, lang anhaltendes Leiden verursacht, das die Tarnung bricht und die Lebenskraft raubt. Die Mission endet wieder in Orgrimmar beim Mentor von The Shattered Hand, Shenthul, der Gallywixs Kopf und die chemische Probe entgegennimmt, während er im Stillen Fizzules kompromittierte Lage betrauert und den sterbenden Agenten ausschickt, um ein Heilmittel zu finden."}},faq={{q="Wo befindet sich der Turm der Venture Co.?",a="Der Turm steht in den nördlichen Ausläufern des Brachlands, unmittelbar nördlich der Bohroperation im Schlickermoor. Er ist von feindseligen Arbeitern der Venture Company umgeben, während sich Zuchtmeister Fizzule nahe einem Baum direkt östlich davon versteckt hält.",al={"standort des venture co. turms","wo ist gallywix turm","turm im schlickermoor"}},{q="Wie erhält man den Schlüssel zum Turm?",a="Der Turmschlüssel gehört Foreman Silixiz, der auf dem Gelände außerhalb des Turmfußes umherwandert. Ihr müsst Euch tarnen und seine Taschen leeren, um den Schlüssel zu erlangen; ihn zu töten, wird den Gegenstand nicht einbringen.",al={"turmschlüssel von silixiz","wie man den turmschlüssel bekommt","wo ist der schlüssel"}},{q="Was ist Zanzils veränderte Mischung?",a="Es ist ein alchemistisches Gebräu, das auf den Rezepturen des berüchtigten Troll-Hexendoktors Zanzil basiert. Die Venture Company gelangte in den Besitz der Substanz, doch ihre instabilen Dämpfe vergifteten die Arbeiter im Turm, wodurch sie kränklich und mutiert wurden und anfällig für die Kampftechniken der Schurken sind.",al={"zanzil-mischung","was ist das gift","veränderte mischung"}},{q="Warum kann ich mich nach dem Öffnen der Schließkassette nicht mehr tarnen?",a="Das Öffnen von Gallywixs Schließkassette setzt konzentrierte Dämpfe der veränderten Mischung frei. Der daraus resultierende giftige Schwächungseffekt hält tagelang an, schwächt Eure Attribute und nimmt Euch die Fähigkeit, verborgen zu bleiben, bis Ihr von einem erfahrenen Apotheker geheilt werdet.",al={"berührung von zanzil","vergiftet nach truhe","kann mich nicht tarnen schurkenquest","7-tage-gift"}},{q="Wer ist Zuchtmeister Fizzule?",a="Fizzule ist ein verdeckter Ermittler für The Shattered Hand, die Schurkengilde der Horde. Als Zwerg der Dunkeleisenzwerge, der sich im Brachland als unbarmherziger Zuchtmeister der Venture Company ausgibt, leitet er Rekruten an, Besitztümer der Venture Company zu sabotieren, ohne seine eigene Tarnung auffliegen zu lassen.",al={"fizzule","wer gab diese quest","fizzule lore"}},{q="Wer ist Grand Foreman Puzik Gallywix?",a="Grand Foreman Puzik Gallywix ist der Goblin-Aufseher, der den Turm der Venture Company nahe dem Schlickermoor befehligt. Er bewacht das gestohlene Versteck von Zanzils Gebräu, bis er von Agenten von The Shattered Hand getötet wird.",al={"puzik gallywix","ist gallywix im brachland","vorarbeiter gallywix"}}},fx={["2a5cd36a"]={q="Warum will Zuchtmeister Fizzule, dass der Turm von The Venture Co. zerstört wird?",a="Während er tief undercover für The Shattered Hand arbeitet, hat Zuchtmeister Fizzule beobachtet, wie The Venture Company mit einem flüchtigen, mutierenden Gift experimentiert. Jetzt, da die vergiftete Mischung jeden im Turm korrumpiert und geschwächt hat, sieht Fizzule eine Gelegenheit, die gesamte Operation zu eliminieren, die Führung von Obervorarbeiter Gallywix zu zerschlagen und die tödliche Verbindung für Orgrimmar zu sichern, bevor sie sich unkontrolliert ausbreitet.",al={"fizzule beweggrund","warum gallywix fizzule töten","warum venture co turm angreifen"}},bde16d60={q="Warum will Shenthul Gallywixs Kopf?",a="Den Kopf von Obervorarbeiter Puzik Gallywix abzutrennen, dient als unbestreitbarer Beweis für seinen Untergang und die Zerschlagung der Turmhierarchie von The Venture Company. Ihn Shenthul in der Shadowswift Den zu präsentieren, bestätigt, dass der primäre Aufseher hinter der regionalen Operation dauerhaft eliminiert wurde.",al={"zweck gallywixs kopf","warum gallywixs kopf nehmen","was ist der zweck von gallywixs kopf"}},["53be2ad7"]={q="Wozu wird Silixiz' Turmschlüssel verwendet?",a="Vorarbeiter Silixiz trägt den Schlüssel außerhalb des Turms. Fizzule bittet Euch, ihn zu stehlen und aufzubewahren, da er ihn möglicherweise später benötigt; ihn zu bergen ist eines der Missionsziele.",al={"silixiz turmschlüssel","zweck des turmschlüssels","warum turmschlüssel stehlen"}},["78e0c22c"]={q="Wozu dient der Behälter mit Zanzils veränderter Mixtur?",a="Eingeschlossen auf der Spitze des Turms in Gallywix' persönlicher Truhe enthält dieser verbleibende Vorrat das seltsame, schwächende Gebräu, das aus Zanzils Formeln stammt. The Shattered Hand verlangt, dass Ihr die Mixtur bergt, damit ihre toxischen und mutierenden Eigenschaften von den Schurkenmeistern in Orgrimmar untersucht – und sicher eingedämmt – werden können.",al={"behälter mit zanzils veränderter mixtur","zanzil mixtur behälter","warum mixtur nehmen"}},["07291131"]={q="Warum werdet Ihr gegen Großvorarbeiter Puzik Gallywix und die Turmarbeiter ausgesandt?",a="Ihr wurdet ausgesandt, um das korrumpierte Personal der Venture Company zu säubern, das den Turm im nördlichen Brachland bewohnt. Unter Großvorarbeiter Puzik Gallywix hat diese Mannschaft Zanzils toxische Verbindung falsch gehandhabt, wodurch die Drohnen in mutierte Monstrositäten verwandelt wurden und die Region gefährdeten. Durch die Eliminierung der Wachposten, Patrouillen, Drohnen und Gallywix selbst beseitigt Ihr ihren vordringenden industriellen Stützpunkt.",al={"gegen wen kämpft ihr im turm","venture co turm ziele","warum gallywix töten"}},fa60081f={q="Warum braucht Fizzule Euch, anstatt sich selbst um den Turm zu kümmern?",a="Fizzule wahrt eine heikle Identität als tief eingeschleuster Aufseher der Venture Company. Würde er dabei erwischt, wie er offen in den Turm eindringt, Aufseher erschlägt oder Gallywix' Schließfach plündert, würde seine Tarnung sofort auffliegen. Als externer Agent von The Shattered Hand besitzt Ihr die tödliche Heimlichkeit, die erforderlich ist, um die Anlage zu säubern, ohne seine Rolle preiszugeben.",al={"warum ich fizzule","warum braucht fizzule hilfe","warum säubert fizzule den turm nicht selbst"}}},fp="34,289,31.453.0,22.399.1,17.431.2,39.228.0,39.188.0,33.268.0,53.233.1,26.255.0,36.201.0"}
P.entries["quest:2479"] = {n="Hinotts Hilfe",s="Hinotts Hilfe ist eine dringende Reise von Hordeschurken, die an einem schwächenden tropischen Toxin leiden. Die Beschwerde, die man sich bei einer Infiltrationsmission im Brachland zugezogen hat, erfordert die spezialisierte Expertise von Serge Hinott in Tarrens Mühle. Seine Hilfe in Anspruch zu nehmen, verspricht sowohl eine lebensrettende Heilung als auch Unterweisung in der Kunst, tödliche Gifte herzustellen.",h="Hinotts Hilfe ist eine dringende Reise von Hordeschurken, die an einem schwächenden tropischen Toxin leiden.",kw={"vorgebirge des hügellands","hinotts hilfe","schurken gift quest","serge hinott","shenthul","tarrens mühle","unterstadt zeppelin","zanzil","zanzils mischung"},ang={["class:Rogue"]="Dieser Initiationsritus schlägt die Brücke zwischen einfacher Heimlichkeit und den alchemistischen Künsten; er stellt die Ausdauer eines Schurken auf die Probe und öffnet zugleich die Tür zu selbst hergestellten Giften.",["faction:Horde"]="Die Mission veranschaulicht die praktische Zusammenarbeit, die die Orc- und Trollschurken von Kalimdor mit dem finsteren alchemistischen Wissen der Verlassenen in Lordaeron verbindet."},sec={{t="Eine giftige Zwangslage",b="Nach der gewagten Infiltration des Turms der Venture Company nördlich vom Schlickermoor sehen sich Schurken von Zanzils veränderter Mischung befallen. Das Gift richtet verheerenden Schaden im Körper an, trübt die Reflexe und bedroht das Leben selbst. Schurkenlehrer Shenthul in Orgrimmar erkennt die Schwere des Leidens, räumt ein, dass hiesige Heilmittel unzureichend sind, und schickt den vergifteten Agenten über das Meer in die Östlichen Königreiche."},{t="Reise nach Tarrens Mühle",b="Die Suche nach einem Heilmittel führt nach Süden durch den Kontinent Lordaeron zum Dorf Tarrens Mühle im Vorgebirge des Hügellands. Dort residiert Serge Hinott, ein Apotheker, dessen Faszination für virulente Gebräue ihn ideal dafür qualifiziert, die exotische Probe zu analysieren. Während gewöhnliche Heiler vor Zanzils Gift zurückschreckten, begegnet Hinott der tödlichen Verbindung mit fachlicher Freude, begierig darauf, das üble Gemisch zu sezieren und würdige Schurken darin zu unterweisen, ihre eigenen Gifte zu brauen."}},faq={{q="Warum muss ich Serge Hinott aufsuchen?",a="Serge Hinott ist ein erfahrener Apotheker in Tarrens Mühle, der sich auf seltene Toxine und deren Gegenmittel spezialisiert hat. Gewöhnliche Heiler können Zanzils veränderte Mischung nicht beseitigen, was Hinott zur einzigen Anlaufstelle macht, die in der Lage ist, die Verbindung zu analysieren, Euer Leben zu retten und die Kunst der Giftherstellung zu lehren.",al={"warum hinott","wer heilt das gift","serge hinott rolle"}},{q="Wo befindet sich Tarrens Mühle?",a="Tarrens Mühle ist eine Siedlung der Verlassenen im nördlichen Vorgebirge des Hügellands. Nehmt von Orgrimmar aus den Zeppelin nach Unterstadt in Tirisfal, reist dann südwärts durch den Silberwald und biegt entlang der Straße nach Osten nach Hillsbrad ab.",al={"tarrens mühle standort","weg nach tarrens mühle","wo ist hinott"}},{q="Wie wurde ich überhaupt vergiftet?",a="Ihr wurdet während des verdeckten Auftrags „Mission: möglich, aber nicht sehr wahrscheinlich“ am Turm der Venture Company nördlich vom Schlickermoor im Brachland infiziert. Das Öffnen der Hochsicherheitskiste setzte Euch Zanzils veränderter Mischung aus, was ein anhaltendes, schwächendes Leiden hinterließ.",al={"wie zanzils gift bekommen","mission möglich gift","warum bin ich vergiftet"}},{q="Was geschieht, nachdem Serge Hinott die Probe erhalten hat?",a="Sobald Hinott die Probe erhält, untersucht er ihre Eigenschaften und bereitet ein Gegenmittel zu, um Euren Körper zu reinigen. Nachdem er das Toxin geheilt hat, teilt er sein Wissen, wodurch Schurken das Brauen und Auftragen eigener Gifte meistern können.",al={"hinott quest folgequest","werde ich geheilt","nach hinotts hilfe"}},{q="Wer ist Shenthul und warum hat er mich weggeschickt?",a="Shenthul ist der Schurkenlehrer der Shattered-Hand in der Kluft der Schatten in Orgrimmar. Er beaufsichtigte Eure Fertigkeitsprüfung im Brachland und erkannte, dass Zanzils Gemisch die medizinischen Kenntnisse Orgrimmars weit überstieg und einen Spezialisten in Hillsbrad erforderte.",al={"wer ist shenthul","shenthul orgrimmar","warum schickte mich lehrer weg"}},{q="Kann eine andere Klasse diese Quest abschließen?",a="Nein. Diese Mission ist Teil der speziellen Schurken-Ausbildungsreihe, die die grundlegende Disziplin des Brauens von Giften und Gegenmitteln freischaltet.",al={"nur schurken quest","können krieger hinotts hilfe machen"}}},fp="19,359,19.431.0,22.461.0,34.289.0,29.229.0,42.263.0,52.233.1,44.265.0,40.137.0"}
P.entries["quest:248"] = {n="Weitere Beobachtungen",s="Looking Further ist eine Spionagemission der Allianz, die vom Magier Theocritus über eine verzauberte Verbindung geleitet wird. Um die Spannungen zwischen dem abtrünnigen Magier Morganth und den Schwarzfelsorks zu untersuchen, müsst Ihr den Wachturm neben der Burg Steinwacht infiltrieren und eine verzauberte Glyphe in einem unauffälligen Behälter platzieren.",h="Looking Further ist eine Spionagemission der Allianz, die vom Magier Theocritus über eine verzauberte...",kw={"leerer krug","glyphe von azora","looking further","morganth","statue des alten löwen","steinwacht","burg steinwacht","theocritus","der turm von ilgalar"},ang={["class:Mage"]="Theocritus verlässt sich auf hochentwickelte Fernspähmagie durch die Glyphe von Azora, was zeigt, wie der Magier von Azora magische Überwachung in feindlichen Gebieten einrichtet.",["faction:Alliance"]="Die Burg Steinwacht bleibt die wichtigste Festung des Schwarzfelsklans im Rotkammgebirge. Informationen über deren interne Konflikte mit Morganth zu sammeln, ist entscheidend für die Verteidigung von Seenhain."},sec={{t="Ein Riss im Rotkammgebirge",b="Von seinem Zufluchtsort im Wald von Elwynn aus hält der Magier Theocritus durch Spähmagie ein wachsames Auge auf das östliche Rotkammgebirge. Während er den Der Turm von Ilgalar überwacht, entdeckt er plötzlich Zwistigkeiten zwischen dem abtrünnigen menschlichen Hexenmeister Morganth und den Schwarzfelsorks, die sich in der Burg Steinwacht verschanzt haben. Anstatt gegen das Königreich Sturmwind zusammenzuarbeiten, sind diese feindseligen Fraktionen in einen Konflikt um eine unbekannte Beute verstrickt, was Theocritus dazu veranlasst, einzugreifen, bevor sich das Gleichgewicht verschiebt."},{t="Das Auge auf Steinwacht",b="Um die Verteidigung der Burg Steinwacht zu durchdringen, benötigt Theocritus einen zweiten magischen Ankerpunkt. Er befiehlt Abenteurern, den intakten Wachturm zu erklimmen, der neben der zerstörten Festung steht. Dort, zwischen dem Gerümpel der Garnison, bietet ein leerer Krug, der von orkischen Wachen zurückgelassen wurde, das perfekte, alltägliche Versteck. Sobald die Glyphe von Azora im Gefäß befestigt ist, kann Theocritus telepathisch die Gedanken innerhalb von Steinwacht durchsuchen, um aufzudecken, was Morganth und die Schwarzfelsorks entzweit hat."}},faq={{q="Wer schickt mich auf diese Mission?",a="Die Quest wird von Theocritus, dem Magier von Azora, erteilt, der durch die Statue des Alten Löwen im Rotkammgebirge zu Euch spricht, nachdem Ihr seine vorherige Aufgabe abgeschlossen habt.",al={"wer vergibt quest","questgeber","statue des alten löwen"}},{q="Warum spioniert Theocritus die Burg Steinwacht aus?",a="Theocritus entdeckte, dass sich zwischen Morganth, dem abtrünnigen dunklen Magier im Der Turm von Ilgalar, und den Schwarzfelsorks, die die Burg Steinwacht besetzt halten, Feindseligkeiten entwickelten. Er möchte herausfinden, was ihren Konflikt ausgelöst hat.",al={"warum orks ausspionieren","ziel von theocritus","warum steinwacht"}},{q="Wo befindet sich der Behälter?",a="Der Behälter ist ein leerer Krug, der auf Fässern ganz oben auf dem intakten Wachturm steht, der sich direkt neben dem Haupteingang der Burg Steinwacht befindet.",al={"fundort leerer krug","wo glyphe platzieren","wo ist der wachturm"}},{q="Was bewirkt die Glyphe von Azora?",a="Sie dient als Fokus für magische Spionage und Weissagung und ermöglicht es Theocritus, die Umgebung aus der Ferne zu überwachen und in die Gedanken der Schwarzfelsorks innerhalb der Burg einzudringen.",al={"zweck der glyphe von azora","was macht die glyphe"}},{q="Was passiert, nachdem die Glyphe platziert wurde?",a="Sobald Theocritus den Ursprung des Konflikts ergründet hat, weist er Euch an, Morganth selbst im Der Turm von Ilgalar aufzuspüren und seinen Schattenanhänger zurückzubringen.",al={"nächste quest","was passiert als nächstes","folgequest looking further"}},{q="Warum wird ein leerer Krug verwendet?",a="Eine magische Spionagerune benötigt ein unauffälliges Gefäß, damit Wachen sie nicht entdecken oder zerstören. Der zurückgelassene, übel riechende Schnapskrug, der auf Fässern vergessen wurde, ist ein ideales Versteck.",al={"warum der krug","hintergrund zum leeren krug"}}},fx={["3912e7be"]={q="Wen bespioniere ich in Burg Steinwacht?",a="Ihr spioniert die Schwarzfelsorks aus, die Burg Steinwacht besetzt haben. Von seinem Aussichtspunkt aus hat der Magier Theocritus Zwietracht zwischen diesen feindseligen Orks und dem dunklen Zauberer Morganth im Der Turm von Ilgalar ausgemacht. Das Platzieren der Glyphe erlaubt es dem Magier, die Gedanken innerhalb von Burg Steinwacht zu erforschen, um die wahre Ursache dieser Reibereien aufzudecken.",al={"wer ist in burg steinwacht","burg steinwacht ziel","looking further ziel"}},["6347ef38"]={q="Warum benötigt Theocritus einen Abenteurer, um die Glyphe zu platzieren?",a="Theocritus ist an den Turm von Azora gebunden und kanalisiert seine Magie durch verzauberte Relikte wie die Statue des alten Löwen, um Bedrohungen im gesamten Rotkammgebirge zu überwachen. Burg Steinwacht wimmelt von gefährlichen Schwarzfelsorks, und das Eindringen in die Festung erfordert jemanden, der sich unsichtbar zum Turm durchkämpfen kann, anstatt einen einsamen, verletzlichen Magier, der seinen Posten verlässt.",al={"warum werde ich geschickt looking further","warum tut theocritus es nicht","warum ich burg steinwacht"}}},fp="15,307,18.487.0,21.494.1,29.154.0,44.210.0,31.155.0,32.177.0,38.158.1,21.179.0"}
P.entries["quest:2480"] = {n="Hinotts Hilfe",s="Hinotts Hilfe ist der Höhepunkt der Reise eines Horde-Schurken, um Zanzils tödliches, schleichendes Gift zu überwinden. Während der betroffene Agent in Tarrens Mühle auf den Apotheker Serge Hinott wartet, erhält er ein Gegengift für das Toxin sowie eine grundlegende Ausbildung in alchemistischer Giftherstellung.",h="Hinotts Hilfe ist der Höhepunkt der Reise eines Horde-Schurken, um Zanzils tödliches, schleichendes Gift zu...",kw={"gegengift","heilmittel","hillsbrad","hinott","gifte","schurkenquest","serge hinott","tarrens mühle","zanzil"},ang={["class:Rogue"]="Dieser Übergangsritus heilt das schwächende Leiden, das Ihr während Eurer Initiation erlitten habt, und schaltet das Wissen frei, das zur Herstellung taktischer Gifte erforderlich ist.",["faction:Horde"]="Die Alchemie der Verlassenen erweist sich als unverzichtbar für die heimlichen Agenten der Horde und verwandelt exotische Toxine der Dschungeltrolle in standardisiertes Feldwissen.",["race:Undead"]="Apotheker Hinott veranschaulicht die distanzierte, wissenschaftliche Bewunderung der Königlichen Apothekervereinigung für jedes Gift, das echte Handwerkskunst beweist – unabhängig von seiner Herkunft."},sec={{t="Ein toxisches Meisterwerk",b="Nachdem sich Horde-Schurken bei einem Auftrag im Brachland ein ansteckendes, geistig zersetzendes Toxin zugezogen haben, werden sie nach Norden nach Tarrens Mühle geschickt, um Serge Hinott aufzusuchen. Als Verlassener Chemiker mit unvergleichlichem Fokus zeigt Hinott professionelle Bewunderung für das Gift, das vom verbannten Dschungeltroll Zanzil gebraut wurde. Hinott schert sich nicht um die Identität oder Abstammung des Trolls, lobt jedoch offen die bösartige Wirksamkeit des Gebräus und brennt darauf, dessen Wirkungsweise zu untersuchen, bevor er ein Gegenmittel formuliert."},{t="Das Gegengift und das Handwerk",b="Die Entwicklung des Heilmittels erfordert lediglich Geduld, während Hinott die Wirkstoffe isoliert. Das fertige Gebräu stoppt den schleichenden Wahnsinn, auch wenn der Chemiker zugibt, den verweilenden Gestank nicht beseitigen zu können. Einmal von dem schwächenden Gift befreit, wandeln sich die Schurken von Opfern zu Anwendern und nutzen Hinotts Einblicke in Zanzils Machwerk, um die Zubereitung ihrer eigenen taktischen Gifte zu meistern."}},faq={{q="Was geschieht während Hinotts Hilfe?",a="Ihr müsst lediglich einige Augenblicke in Tarrens Mühle warten, während Serge Hinott das Gegengift zubereitet. Sobald er das Gebräu fertiggestellt hat, sprecht mit ihm, um das Heilmittel einzunehmen und Zanzils Gift zu neutralisieren.",al={"was muss ich hier tun","hinotts hilfe ablauf","wie beende ich die quest"}},{q="Wer ist Serge Hinott?",a="Serge Hinott ist ein Alchemist und Giftexperte der Verlassenen, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Er stellt sein spezialisiertes Handwerk Schurken der Horde zur Verfügung, die exotische Leiden heilen und die Feinheiten der Giftzubereitung erlernen möchten.",al={"serge hinott geschichte","wer ist hinott","tarrens mühle apotheker"}},{q="Warum ist Serge Hinott von dem Gift beeindruckt?",a="Hinott hält Zanzils Rezeptur aufgrund ihrer wirkungsvollen Mischung aus schleichendem Wahnsinn und körperlicher Schwächung für ein Meisterwerk alchemistischer Kunst. Selbst während er an dessen Neutralisierung arbeitet, lobt er offen die Handwerkskunst hinter einem derart zerstörerischen Gebräu.",al={"zanzil gift reaktion","warum gefällt es hinott"}},{q="Was ist der anhaltende Gestank, den Hinott erwähnt?",a="Zanzils Mischung verströmt einen stechenden, kränklichen Geruch, der die Poren des Opfers durchdringt. Obwohl Hinotts Gegengift das Fortschreiten des Giftes erfolgreich stoppt und den Geist klärt, neutralisiert es den zurückbleibenden üblen Gestank nicht sofort.",al={"warum stinke ich","wahnsinn geruch","quest gestank"}},{q="Was ist die Belohnung für den Abschluss dieser Quest?",a="Der Abschluss dieser Aufgabe entfernt den anhaltenden Schwächungseffekt, den man sich während der Schurken-Klassenquestreihe zugezogen hat, und ebnet den Weg zum Erlernen der Schurken-Giftfertigkeit, wodurch Spieler ihre eigenen schwächenden Waffenbeschichtungen brauen können.",al={"was bekommen schurken","hinotts hilfe belohnung"}},{q="Wo wird diese Quest abgegeben?",a="Die Quest beginnt und endet direkt bei Serge Hinott in Tarrens Mühle, gelegen im nördlichen Vorgebirge des Hügellands.",al={"wo ist hinott","abgabeort"}}},fp="19,279,19.460.0,26.398.1,40.200.0,20.237.0,44.239.0,44.244.0,45.206.0,30.118.0"}
P.entries["quest:249"] = {n="Morganth",s="Morganth ist die entscheidende Quest, die eine lange Untersuchung des Magiers Theocritus über einen finsteren Rivalen im Rotkammgebirge abschließt. Betraut damit, einen dunklen Hexenmeister aufzuhalten, der nach einem uralten Relikt von schrecklicher Macht sucht, müssen Abenteurer den Der Turm von Ilgalar stürmen und seinen Machenschaften ein Ende setzen.",h="Morganth ist die entscheidende Quest, die eine lange Untersuchung des Magiers Theocritus über einen finsteren...",kw={"elwynn","morganth","schattenanhänger","rotkammgebirge","the scythe of elune","theocritus","turm von azora","der turm von ilgalar"},ang={["class:Mage"]="Theocritus repräsentiert die fleißige, gelehrte Tradition menschlicher Magier, die von hohen Türmen aus wachen, um das Reich vor abtrünnigen Zauberwirkern zu schützen.",["class:Warlock"]="Morganth steht für die Gefahr ungezügelter Teufels- und Schattenambitionen und beweist, dass das Gieren nach Relikten wie der The Scythe of Elune rasche Zerstörung heraufbeschwört.",["faction:Alliance"]="Das Besiegen von Morganth schützt die ungeschützten östlichen Grenzen von Sturmwinds und stellt sicher, dass das Gebiet des Rotkammgebirges nicht in dunkle Zauberei versinkt.",["race:NightElf"]="Das Flüstern über die The Scythe of Elune in Menschenhand sollte die Kaldorei zutiefst beunruhigen, da der Name des Relikts heilige und unbeständige Geheimnisse berührt."},sec={{t="Ein Wächter jenseits der Grenze",b="Von seinem Sanktum im Turm von Azora im östlichen Wald von Elwynn aus hielt der Magier Theocritus ein wachsames, spähendes Auge auf die Felsen des Rotkammgebirges gerichtet. Was er beobachtete, bestätigte seine tiefsten Befürchtungen: Der Hexenmeister Morganth, der sich im Der Turm von Ilgalar verschanzt hatte, suchte aktiv nach der legendären The Scythe of Elune. Als Theocritus erkannte, dass der Hexenmeister kurz davor stand, diese dunkle Macht zu erlangen, rief er mutige Champions der Allianz dazu auf, einzugreifen, bevor Morganths Schatten auf das gesamte Königreich Sturmwind fallen konnte."},{t="Sturm auf den Turm",b="Der Turm von Ilgalar ragt hoch über dem Becken des Rotkammgebirges auf, verseucht von Gnollen und verdrehten arkanen Energien. Morganth wartete auf dem Gipfel, schwang Shadow Magic und bewachte seine Forschungen. Um den Hexenmeister zu konfrontieren, mussten Abenteurer durch feindliches Gebiet aufsteigen, um den Zauberer direkt zur Strecke zu bringen und seinen Schattenanhänger als unbestreitbaren Beweis dafür zu erlangen, dass der Turm gefallen und die Bedrohung gebannt war."},{t="Der bleibende Schatten der Sense",b="Obwohl Morganths Niederlage eine unmittelbare und katastrophale Bedrohung für Sturmwind beseitigt, zeigt sein Streben nach der The Scythe of Elune, wie weit die dunkle Legende des Artefakts reicht. Während Theocritus aufatmet, als er den Schattenanhänger erhält, bleibt der wahre Verbleib der uralten Sense und das Unheil, das sie anrichten könnte, ein beunruhigendes Rätsel in den umliegenden Provinzen."}},faq={{q="Wer ist Morganth?",a="Morganth ist ein mächtiger abtrünniger Hexenmeister, der auf dem Gipfel des Der Turm von Ilgalar im Rotkammgebirge haust. Er hat seine Zeit damit verbracht, dunkle Künste zu studieren und die The Scythe of Elune zu verfolgen, ein Artefakt, das imstande ist, katastrophale Magie zu entfesseln.",al={"morganth identität","wer ist morganth","morganth hintergrundgeschichte"}},{q="Wo befindet sich der Der Turm von Ilgalar?",a="Der Der Turm von Ilgalar befindet sich im östlichen Rotkammgebirge, hinter Burg Steinwacht, wo Shadowhide-Gnolle ihr Lager um seinen Fuß aufgeschlagen haben.",al={"der turm von ilgalar standort","wo ist morganths turm","rotkammgebirge turm"}},{q="Warum will Theocritus, dass Morganth stirbt?",a="Durch seine Spähzauber erfuhr Theocritus, dass Morganth nach der The Scythe of Elune jagte, und er fürchtete, dass der Hexenmeister kurz davor stünde, sie zu erlangen. Eine solche dunkle Macht würde eine katastrophale Bedrohung für das Rotkammgebirge und das benachbarte Königreich Sturmwind darstellen.",al={"theocritus motiv","warum morganth töten","theocritus quest grund"}},{q="Was ist die The Scythe of Elune?",a="Die The Scythe of Elune ist ein uraltes, geheimnisumwobenes Artefakt, das für seine immense, chaotische Macht bekannt ist, die Bestien verformen, albtraumhafte Schrecken herbeirufen und Magie verderben kann. Hexenmeister und dunkle Zauberwirker begehren es wegen der gewaltigen Schattenenergien, die es freisetzt.",al={"the scythe of elune lore","was ist die sense","warum ist die sense gefährlich"}},{q="Was ist der Schattenanhänger?",a="Der Schattenanhänger ist Morganths magischer Talisman, der sowohl als Fokus für seine dunklen Künste dient als auch als definitiver Beweis für seine Niederlage, wenn Ihr ihn zu Theocritus in den Turm von Azora zurückbringt.",al={"schattenanhänger","morganth anhänger","beweis von morganths tod"}},{q="Welche Questreihe führt dazu?",a="Diese Quest ist das Finale einer vierteiligen Kette, die mit 'Theocritus' Retrieval' im Wald von Elwynn beginnt, gefolgt von 'A Watchful Eye' und 'Looking Further', bei denen es darum geht, Werkzeuge zu bergen und Spähposten zu errichten, um Morganths Turm zu beobachten.",al={"morganth questreihe","morganth voraussetzungen","wie man morganth freischaltet"}}},fx={["23819dbd"]={q="Warum schickt Theocritus Euch, um Morganth gegenüberzutreten, anstatt selbst zu gehen?",a="Theocritus gibt ganz offen zu, dass er nicht bereit ist, seine eigene magische Macht direkt gegen Morganth einzusetzen. Während er von Turm von Azora aus über die Grenzen wacht und die Verteidigung gegen Shadow Magic koordiniert, erfordert ein Angriff auf den Der Turm von Ilgalar selbst einen mutigen, fähigen Abenteurer, der bereit ist, die Festung des Hexenmeisters zu stürmen, bevor Morganths dunkle Ambitionen ganz Sturmwind bedrohen können.",al={"warum werdet ihr geschickt","warum kämpft theocritus nicht gegen morganth","warum nicht theocritus"}}},fp="8,293,27.510.0,18.392.0,29.391.1,16.235.0,30.136.0,39.245.0,28.250.0,30.192.0,34.236.0"}
P.entries["quest:2498"] = {n="Rückkehr zu Denalan",s="Return to Denalan ist eine Quest der Allianz, die jene Botaniker verbindet, welche die Verderbnis innerhalb von Teldrassil untersuchen. Nachdem er die moosigen Tumors erforscht hat, die die einheimischen Timberlinge befallen, schickt Rellian Greenspyre Euch zurück nach Süden zum Al'Amethsee, um Denalan bei einer besorgniserregenden neuen Entdeckung beizustehen.",h="Return to Denalan ist eine Quest der Allianz, die jene Botaniker verbindet, welche die Verderbnis innerhalb...",kw={"denalan","dolanaar","al'amethsee","oakenscowl","rellian greenspyre","teldrassil","timberlinge","tumors"},ang={["class:Druid"]="Die Untersuchung unnatürlicher Tumors an Waldgeistern berührt den Kern des cenarischen Auftrags, das natürliche Gleichgewicht zu wahren und schleichende Verderbnis zu reinigen.",["race:NightElf"]="Die Timberlinge sind lebendige Manifestationen von Teldrassils Lebenskraft; Denalan beizustehen ist Teil der heiligen Pflicht, die wachsende Verderbnis zu heilen, die die neue Heimat Eures Volkes bedroht."},sec={{t="Eine Nachricht über die Äste hinweg",b="Während er die seltsamen moosigen Tumors untersucht, die Teldrassils Timberlinge plagen, erhält Rellian Greenspyre dringende Nachricht von seinem Kollegen Denalan. Denalan, der an den ruhigen Gewässern des Al'Amethsees weilt, glaubt, endlich herausgefunden zu haben, was diese unnatürlichen Wucherungen auf den Naturgeistern des Waldes verursacht. Rellian erkennt den Ernst der Lage und schickt Euch sogleich zurück nach Süden, um zur Hand zu gehen."},{t="Die Bedrohung am See",b="Denalans Forschungen am Al'Amethsee sind entscheidend, um die Leiden zu verstehen, die über den jungen Weltenbaum kriechen. Was als Untersuchung von verdorbener Pflanzenwelt und erkrankten Timberlingen begann, entwickelt sich rasch zu einer direkten Konfrontation mit den verdorbenen Wesenheiten, die das Geäst vergiften – beginnend mit dem verdorbenen Timberling Oakenscowl."}},faq={{q="Wer ist Denalan?",a="Denalan ist ein Forscher und Naturkundler der Nachtelfen, der am Al'Amethsee im Süden von Teldrassil stationiert ist. Er widmet seine Zeit dem Studium der Flora der Insel, seltsamer Keimlingsmutationen und der unnatürlichen Leiden, die sich unter den hiesigen Timberlingen ausbreiten.",al={"denalan lore","wer ist denalan","denalan al'amethsee"}},{q="Warum schickt Euch Rellian Greenspyre zurück zum Al'Amethsee?",a="Rellian erfährt, dass Denalan die mutmaßliche Ursache für die Tumors entdeckt hat, die die Timberlinge verderben. Da sich die Situation rasch zuspitzt und eine wachsende Gefahr für den Wald darstellt, schickt Rellian Euch aus, um sofortige Hilfe vor Ort zu leisten.",al={"warum zu denalan reisen","rellian greenspyre mission"}},{q="Was sind die Tumors, die die Timberlinge befallen?",a="Timberlinge sind friedliche Naturgeister, die aus der Pflanzenwelt der Insel hervorgegangen sind, doch eine um sich greifende Verderbnis, die in Teldrassil Wurzeln schlägt, lässt ihnen bizarre moosige Wucherungen wachsen. Diese Tumors treiben die Kreaturen in Feindseligkeit und Wahnsinn.",al={"tumors der timberlinge","warum timberlinge tumors haben","moosige tumors"}},{q="Wo kann ich Denalan finden?",a="Denalan schlägt sein Lager an den Ufern des Al'Amethsees auf, direkt südlich von Dolanaar in den südlichen Wäldern von Teldrassil.",al={"denalan standort","wo ist denalan"}},{q="Was geschieht, nachdem Ihr Denalan erreicht habt?",a="Denalan begrüßt Eure Hilfe und berichtet, dass er etwas Beunruhigendes entdeckt hat. Er erklärt die nächste Aufgabe, sobald Ihr sein Lager erreicht.",al={"was kommt danach","oakenscowl folgequest"}},{q="Wie verbindet dieser Botengang Rellian und Denalan?",a="Der Botengang verbindet Rellian Greenspyres Timberling-Forschung in Darnassus mit Denalans Lager am Al'Amethsee und führt Rellians Studien über die Tumors mit Denalans neuer Entdeckung über deren Ursache zusammen.",al={"warum schickt rellian mich zu denalan","return to denalan zweck"}}},fp="17,276,27.417.0,22.343.1,15.250.0,59.260.0,47.227.0,25.121.0,37.126.1,49.191.0"}
P.entries["quest:2499"] = {n="Grimmeiche",s="Denalan bittet Abenteurer darum, Oakenscowl, einen mächtigen Holzling, der von einem riesengroßen Tumor befallen ist, zur Strecke zu bringen. Das in einer Höhle am südlichen Ufer des Al'Amethsees hausende, wahnsinnig gewordene Geschöpf verbreitet nun die Fäulnis unter der lokalen Tierwelt.",h="Denalan bittet Abenteurer darum, Oakenscowl, einen mächtigen Holzling, der von einem riesengroßen Tumor...",kw={"verderbnis","denalan","riesengroßer tumor","al'amethsee","moosige tumors","oakenscowl","teldrassil","holzling"},ang={["class:Druid"]="Einen Wächter-Holzling zu sehen, der von seltsamen Tumors befallen ist, ist für Druiden eine erschütternde Erinnerung daran, dass es um das aufblühende Ökosystem von Teldrassil schlecht bestellt ist.",["profession:Herbalism"]="Kräuterkundige, die Denalan unterstützen, beobachten aus erster Hand, wie sich botanisches Leben unter dem Einfluss unsichtbarer Fäulnis in bösartige, moosige Plagen verwandeln kann.",["race:NightElf"]="Der tragische Untergang von Oakenscowl trifft die Nachtelf-Gesellschaft ins Mark und bedroht den Al'Amethsee südlich von Dolanaar."},sec={{t="Ein gefallener Wächter",b="Oakenscowl war einst ein bedeutender Anführer unter den Holzlingen, den Waldgeistern, die sich um die üppigen Zweige von Teldrassil kümmern. Tragischerweise unterscheidet die Verderbnis, die sich durch den Weltenbaum frisst, nicht zwischen dem einfachen Wild und den uralten Beschützern. Durch einen riesengroßen Tumor, der auf seiner Rinde anschwillt, wurde Oakenscowl in den Wahnsinn getrieben und ist nun eher ein Gefäß der Fäulnis als ein Hüter des Wachstums."},{t="Die Reinigung des Al'Amethsees",b="Die toxische Präsenz von Oakenscowl, der in einer Höhle am südlichen Ufer des Al'Amethsees lauert, vergiftet aktiv das umliegende Wasser und die Waldtiere. Denalan, der sich der Bestie nicht allein entgegenstellen kann, sucht nicht aus Bosheit nach der Vernichtung des Geschöpfs, sondern um die Quelle der Verderbnis barmherzig zu trennen und den bizarren, überwucherten Tumor zu untersuchen, der die Geister des Sees heimsucht."}},faq={{q="Was ist Oakenscowl?",a="Oakenscowl ist ein massiver Holzling – ein Waldgeist, der mit der Pflanzenwelt von Teldrassil verbunden ist. Er wurde einst als edler Anführer seinesgleichen angesehen, bevor er einem bösartigen Gewächs zum Opfer fiel.",al={"wer ist oakenscowl","oakenscowl lore","welche art von kreatur ist oakenscowl"}},{q="Warum muss Oakenscowl vernichtet werden?",a="Oakenscowl leidet unter einem riesengroßen Tumor, der seinen Verstand verdreht und ihn gewalttätig aggressiv gemacht hat. Seine Anwesenheit in der Höhle am Al'Amethsee verbreitet die seltsame Fäulnis aktiv auf benachbarte Holzlinge und Tiere.",al={"warum oakenscowl töten","ist oakenscowl feindselig"}},{q="Wo lebt Oakenscowl?",a="Oakenscowl lebt tief in einer Höhle am südlichen Ufer des Al'Amethsees im südlichen Teldrassil.",al={"standort von oakenscowl","wo ist die höhle von oakenscowl"}},{q="Wer ist Denalan und warum untersucht er den Tumor?",a="Denalan ist ein Kräuterkundiger und Naturforscher, der am östlichen Ufer des Al'Amethsees lebt. Er studiert die Flora und Fauna des Weltenbaums und versucht, die seltsame Fäulnis zu verstehen und zu heilen, die die lokale Holzlingspopulation befällt.",al={"wer gibt die quest für oakenscowl","denalan oakenscowl"}},{q="Was verursachte den Tumor bei Oakenscowl?",a="Der Tumor ist ein Symptom für eine tiefer liegende, heimtückische Krankheit, die durch den Boden und die Wurzeln von Teldrassil kriecht und Naturgeister von innen heraus verdirbt.",al={"warum haben holzlinge tumors","quelle der verderbnis"}},{q="Ist Oakenscowl nicht mehr zu retten?",a="Wenn Abenteurer ihm begegnen, ist das Leiden bereits zu weit fortgeschritten. Der Tumor hat das Geschöpf vollständig deformiert, sodass Denalan keine andere Wahl bleibt, als um einen barmherzigen Tod zu bitten.",al={"kann oakenscowl geheilt werden","oakenscowl heilen"}}},fx={a853a20e={q="Wofür benötigt Denalan den Riesengroßer Tumor?",a="Denalan benötigt den Riesengroßer Tumor, um das unnatürliche Leiden zu untersuchen, das Teldrassils Holzschinder vergiftet. Als Naturforscher, der am Al'Amethsee lebt, hat er beobachtet, wie die Kreaturen dem Wahnsinn und der Verderbnis anheimfielen. Da Oakenscowl das größte Geschwür trug, das er je gesehen hat, bietet die Untersuchung eines solch extremen Exemplars Denalan die beste Chance, die Krankheit zu verstehen, die die lokale Tierwelt in Aufruhr versetzt.",al={"warum riesengroßer tumor","zweck des riesengroßen tumors","nutzung riesengroßer tumor"}},["47d0c5c8"]={q="Warum benötigt Denalan Eure Hilfe gegen Oakenscowl?",a="Denalan ist ein isolierter Forscher und Kräuterkundiger, kein Krieger, der fähig ist, einen massiven, korrumpierten Holzschinder in seiner Höhle zu bekämpfen. Er gab zu, dass er es nicht einmal wagte, sich dem Biest zu nähern, als er das südliche Ufer erkundete. Da Ihr Eure Fähigkeiten bereits beim Sammeln von moosigen Tumoren und bei der Unterstützung seiner Arbeit unter Beweis gestellt habt, vertraut er Euch die Beseitigung der Bedrohung an, die sein Zuhause am See gefährdet.",al={"warum ich denalan","warum einen abenteurer schicken oakenscowl","warum kann denalan oakenscowl nicht bekämpfen"}}},fp="10,235,17.379.0,21.354.0,19.184.0,33.228.0,29.113.0,48.228.0,36.144.0,28.179.0"}
P.entries["quest:25"] = {n="Und dann langsam abkühlen lassen",s="Stillstand am Steinkrallenpfad ist ein Auftrag der Horde, der von Mastok Wutfauch am Splitterholzposten vergeben wird, um den lebenswichtigen Übergang in das Steinkrallengebirge zu sichern. Beschmutzte Wasserelementare im Mystralsee haben die Nachschubtransporte zum Erliegen gebracht, was die Horde dazu veranlasst, die feindseligen Geister auszudünnen und einen elfischen Pavillon auszukundschaften, der die nahegelegenen Bewegungen der Allianz überblickt.",h="Stillstand am Steinkrallenpfad ist ein Auftrag der Horde, der von Mastok Wutfauch am Splitterholzposten...",kw={"beschmutzter wasserelementar","pavillon","mastok wutfauch","mystralsee","splintertreeposten","und dann langsam abkühlen lassen","der steinkrallenpfad","tideress"},ang={["class:Shaman"]="Der verzerrte Zustand der Wasserelementare des Mystralsees offenbart eine tiefe elementare Disharmonie, die in den uralten Wäldern von Eschental Wurzeln schlägt.",["faction:Horde"]="Der Splitterholzposten kann ohne offene Versorgungskorridore nicht überleben; die Sicherung des Steinkrallenpfads ist unerlässlich, um Kommunikation und Handel mit dem Steinkrallengebirge aufrechtzuerhalten.",["race:Orc"]="Krieger der Horde sind auf das Holz und die Pfade von Eschental angewiesen, um ihre Siedlungen zu versorgen, weshalb eine Unterbrechung der Gebirgsnachschublinien unannehmbar ist."},sec={{t="Eine blockierte Nachschubroute",b="Um die Stellung der Horde in Eschental zu behaupten, bedarf es eines stetigen Flusses an Holz, Vorräten und Boten zwischen dem Wald und den Gipfeln des Steinkrallengebirges. Der Steinkrallenpfad dient als diese entscheidende Lebensader, die am westlichen Ufer des Mystralsees vorbeiführt. Als die Gewässer durch feindselige Elementare heftig aufgewühlt wurden, kam der Reiseverkehr völlig zum Erliegen. Transportkarawanen sahen sich Angriffen wütender Wassergeister ausgesetzt, was Mastok Wutfauch dazu veranlasste, schnelles Handeln zu fordern, bevor die Versorgungslinien vollständig zusammenbrechen."},{t="Die verdorbenen Gewässer",b="Der Mystralsee ist kein friedlicher Waldzufluchtsort mehr. Die Elementare, die durch seine Tiefen treiben, sind beschmutzt, aggressiv und unberechenbar geworden und greifen wahllos jeden an, der die umliegenden Pfade betritt. Das Ausdünnen dieser wässrigen Unholde – und das Brechen der Herrschaft des größeren Geistes Tideress – ist unerlässlich, um wieder ein Mindestmaß an Sicherheit herzustellen. Doch der Ursprung ihres Verderbens bleibt inmitten der allgemeinen Unruhen, die die heiligen Haine von Eschental ergreifen, ein unheilvolles Rätsel."},{t="Blicke über das Wasser",b="Neben der Bezwingung der zornigen Geister des Sees erkennt die Horde eine strategische Gelegenheit auf der zentralen Insel des Mystralsees. Ein uralter Pavillon der Nachtelfen steht auf dem Eiland und bietet ein klares Sichtfeld über das Wasser auf die nahegelegene Nachtelfensiedlung Silberwindzuflucht. Indem sie das Bauwerk auskundschaften, prüfen Späher der Horde, ob die Ruinen als vorgeschobener Beobachtungsposten dienen können, damit die Befehlshaber von Splintertree ihre Rivalen auf Kalimdor unentdeckt im Auge behalten können."}},faq={{q="Was verursacht den Stillstand nahe dem Steinkrallengebirge?",a="Beschmutzte Wasserelementare, die den Mystralsee bewohnen, sind gewalttätig geworden und greifen Reisende entlang des angrenzenden Steinkrallenpfads an. Diese Aggression hat die Nachschubtransporte zwischen Eschental und dem Steinkrallengebirge zum Erliegen gebracht.",al={"warum transporte gestoppt","steinkrallenpfad blockiert","was stoppte nachschubroute"}},{q="Wer befiehlt die Beseitigung der Elementare?",a="Mastok Wutfauch, ein Orc, der am Splitterholzposten im östlichen Eschental stationiert ist, befiehlt die Mission, um die Handelsrouten der Horde wiederherzustellen und die Stellungen der Allianz zu erkunden.",al={"wer vergibt stillstand am steinkrallenpfad","mastok wutfauch quest","wer ist mastok"}},{q="Warum soll der Pavillon mitten im Mystralsee ausgekundschaftet werden?",a="Der Pavillon bietet eine erhöhte Aussicht über den See und liegt direkt gegenüber dem nahegelegenen Lager der Allianz. Mastok hofft, ihn als verdeckten Beobachtungsposten nutzen zu können, um feindliche Bewegungen zu überwachen.",al={"warum pavillon auskundschaften","mystralsee pavillon zweck","pavillon beobachtungsposten"}},{q="Was ist der Steinkrallenpfad?",a="Der Steinkrallenpfad ist der wichtigste Gebirgspfad, der die südwestlichen Gefilde von Eschental mit dem Steinkrallengebirge verbindet und direkt am westlichen Ufer des Mystralsees entlangführt.",al={"steinkrallenpfad standort","pfad nach steinkrallen","steinkrallenstraße"}},{q="Warum sind die Wasserelementare im Mystralsee beschmutzt?",a="Dunkle Energien und weitreichende Unruhen in Eschental haben das natürliche Gleichgewicht gestört, die Geister des Mystralsees in den Wahnsinn getrieben und ihre gewöhnlich ruhigen Gewässer feindselig gegenüber Außenstehenden gemacht.",al={"warum elementare verderbt","mystralsee wasser verdorben","beschmutzte elementare ursprung"}},{q="Welcher Außenposten der Allianz wird vom Pavillon aus beobachtet?",a="Der Pavillon überblickt die Silberwindzuflucht, eine Nachtelfensiedlung knapp nördlich des Sees, die von Schildwachen bewacht wird, die Eschental gegen die Holzfälleraktivitäten der Horde verteidigen.",al={"welche allianzbasis nahe mystralsee","allianz außenposten eschental"}}},fx={["46f9d708"]={q="Was bekämpft Ihr am Mystralsee?",a="Ihr werdet ausgesandt, um die befleckten Wasserelementare zu vernichten, die den Mystralsee bewohnen, sowie Tideress. Die Wasser des Sees sind zum Leben erwacht und greifen jeden aggressiv an, der auf der nahegelegenen Straße reist.",al={"mystralsee ziel","gegen wen werdet ihr ausgesandt","was tötet ihr stonetalon standstill"}}},fp="21,348,21.541.0,20.486.0,21.491.0,47.227.0,34.165.0,51.195.0,27.184.0,54.190.0,56.177.0"}
P.entries["quest:250"] = {n="Eine dunkle Bedrohung",s="Chefingenieur Hinderweir VII. befürchtet, dass der Steinwerkdamm nach den Angriffen im Sumpfland das nächste Ziel der Aggressionen der Dunkeleisenzwerge ist. Da der Großteil der Verteidigungsgarnison des Damms anderweitig eingesetzt wird, werden Abenteurer entsandt, um Dunkeleisenpioniere zu untersuchen, die an der östlichen Rampe lauern.",h="Chefingenieur Hinderweir VII.",kw={"dunkeleisenzwerge","dun modr","hinderweir","loch modan","pioniere","der steinwerkdamm","verdaechtiges fass","thandol-übergang"},ang={["faction:Alliance"]="Da die Frontarmeen über den gesamten Kontinent hinweg ausgedünnt sind, müssen Rekruten der Allianz in die Bresche springen, um wichtige Nachschubknotenpunkte und die regionale Infrastruktur in der Etappe zu schützen.",["profession:Engineering"]="Ingenieure wissen sowohl das atemberaubende Ausmaß des Damms als auch die heimtückische Gefahr zu schätzen, die von Pionieren ausgeht, die flüchtige chemische Sprengstoffe gegen tragende Fundamente einsetzen.",["race:Dwarf"]="Der Steinwerkdamm ist ein Meisterwerk zwergischer Handwerkskunst und des Stolzes; ihn durch tückische Dunkeleisen-Verwandte bedroht zu sehen, macht die Untersuchung zu einer Angelegenheit der nationalen Verteidigung."},sec={{t="Ein verwundbares Wunder",b="Der Steinwerkdamm ist eine der glanzvollsten Ingenieursleistungen von Eisenschmiede und staut die gewaltigen Wassermassen von Loch Modan zurück. Aufgrund der anhaltenden Konflikte in ganz Khaz Modan und darüber hinaus wurde jedoch ein Großteil der Wachmannschaft des Damms an die Front der Allianz abkommandiert. Dieser Truppenmangel lässt Chefingenieur Hinderweir VII. und seine Rumpfbesatzung weitgehend schutzlos gegen koordinierte Angriffe zurück – genau zu dem Zeitpunkt, als feindliche Aktivitäten der kolossalen Struktur immer näher rücken."},{t="Echos aus dem Norden",b="Hinderweirs Sorgen rühren von den jüngsten Verwüstungen an der Nordgrenze her. Dunkeleisenzwerge schlugen im Sumpfland mit tödlicher Koordination zu, sabotierten den strategischen Thandol-Übergang und plünderten die Festungsstadt Dun Modr. Als Hinderweir bekannte Dunkeleisenpioniere bemerkt, die in der Nähe der östlichen Rampe des Damms herumschleichen, erkennt er das Muster: Der abtrünnige Clan hat nun die Zerstörung der Lebensader des Lochs ins Visier genommen."},{t="Das verdächtige Fass",b="Die Erkundung der unteren Festungswälle bestätigt die schlimmsten Befürchtungen des Ingenieurs. Versteckt zwischen den Felsen, wo sich die Pioniere versammelt hatten, liegt ein unbeaufsichtigtes, verdächtiges Fass voller flüchtigem, seltsam riechendem Pulver. Es dient als eindeutiger Beweis dafür, dass die Dunkeleisenzwerge aktiv Sprengungen vorbereiten, um das Fundament des Steinwerkdamms zu sprengen."}},faq={{q="Warum macht sich Chefingenieur Hinderweir Sorgen um den Damm?",a="Dunkeleisentruppen verwüsteten kürzlich nördliche Garnisonen, indem sie den Thandol-Übergang beschädigten und Dun Modr plünderten. Als Hinderweir Dunkeleisenpioniere an der östlichen Rampe des Steinwerkdamms herumschleichen sah, war er überzeugt, dass der Damm ihr nächstes Ziel ist.",al={"warum hinderweir besorgt","bedrohung stonewroughtdamm","warum angriff auf damm"}},{q="Wohin ist die Garnison des Damms verschwunden?",a="Die meisten der am Steinwerkdamm stationierten Sicherheitskräfte, darunter Hinderweirs oberster Inspektor, wurden zur Unterstützung der weitläufigen Front der Allianz abkommandiert, wodurch die wichtige Anlage nur noch spärlich verteidigt wird.",al={"warum keine wachen am damm","damm sicherheitswache","wo sind die soldaten"}},{q="Was findet man an der östlichen Rampe?",a="In der Nähe der östlichen Rampe, wo die Dunkeleisenpioniere gesichtet wurden, entdecken Ermittler ein verdächtiges Fass, das mit einem seltsam riechenden Pulver gefüllt ist – was bestätigt, dass die Dunkeleisenzwerge Sprengstoff platzieren, um das Bauwerk zu sabotieren.",al={"was ist der hinweis","hinweis verdaechtiges fass","was machen die pioniere"}},{q="Welche strategische Bedeutung hat der Steinwerkdamm?",a="Der Steinwerkdamm kontrolliert das Wasserreservoir von Loch Modan. Sollte er brechen, würde die Flut flussabwärts im Sumpfland verheerende Zerstörungen anrichten und gleichzeitig das Kernland des Zwergenterrains trockenlegen.",al={"warum damm zerstoeren","was passiert wenn damm bricht","damm lore"}},{q="Was war der von Hinderweir erwähnte Angriff auf Dun Modr?",a="Dun Modr war ein befestigter Zwergenaßenposten im nördlichen Sumpfland nahe dem Thandol-Übergang. Dunkeleisen-Infiltratoren überwältigten die Stadt und schlugen am nahegelegenen Thandol-Übergang zu, wodurch wichtige Überland-Versorgungsrouten unterbrochen wurden.",al={"angriff auf dun modr","was geschah in dun modr","zerstoerung thandol-uebergang"}},{q="Wer sind die Dunkeleisenzwerge, die es auf Loch Modan abgesehen haben?",a="Der Dunkeleisenclan ist seit dem Krieg der drei Hämmer ein erbitterter Rivale der Bronzebartzwerge. Von dem Schwarzfels und der Sengenden Schlucht aus sabotieren sie regelmäßig die Infrastruktur und die Grenzverteidigung von Bronzebeard.",al={"wer sind die dunkeleisenzwerge","motiv dunkeleisenpioniere","warum hassen dunkeleisenzwerge eisenschmiede"}}},fx={f99be494={q="Warum sind Dunkeleisensappere am Der Steinwerkdamm?",a="Nach ihren Angriffen auf The Thandol Span und die Stadt Dun Modr im Norden sind Dunkeleisenzwerge nach Süden in Loch Modan eingedrungen. Chefingenieur Hinderweir hat ihre Sappere dabei beobachtet, wie sie sich um die östliche Rampe des Der Steinwerkdamm schlichen, und vermutet, dass sie als Nächstes die massive Struktur sabotieren wollen.",al={"dunkeleisensappere damm","warum sind dunkeleisen am damm","dunkeleisensappere loch modan"}}},fp="19,296,19.451.0,21.422.0,19.330.1,55.245.0,32.204.0,37.226.1,59.198.0,56.211.0,51.241.0"}
P.entries["quest:251"] = {n="Übersetzung von Calvinius' Notiz",s="Translate Abercrombie's Note ist eine Allianz-Quest in Dunkelhain, die einen Abenteurer damit beauftragt, einen unleserlichen Brief an den Gelehrten der Stadt zu überbringen. Lord Ello Schwarzhaupt kann sich keinen Reim auf das Schreiben des Einsiedlers machen und ist daher auf das Wissen von Sirra Von'Indi über obskure Schriften angewiesen. Es markiert den Moment, in dem die Führung von Dunkelhain beginnt, sich den seltsamen Brief des Einsiedlers genauer anzusehen.",h="Translate Abercrombie's Note ist eine Allianz-Quest in Dunkelhain, die einen Abenteurer damit beauftragt...",kw={"calvinius","chiffre","dunkelhain","dämmerwald","ello schwarzhaupt","einsiedler","sirra von'indi","übersetzung"},ang={["class:Mage"]="Magier, die mit obskuren Dialekten und arkanen Transkriptionen vertraut sind, werden Sirra Von'Indis Rolle als lokaler Experte von Dunkelhain für esoterische Schriften zu schätzen wissen.",["faction:Alliance"]="Für Allianz-Champions, die dem Dämmerwald helfen, verdeutlicht diese Besorgung, wie verwundbar und isoliert sich die zivile Führung von Dunkelhain inmitten der umliegenden Dunkelheit fühlt."},sec={{t="Eine unleserliche Nachricht",b="Als Calvinius einen versiegelten Brief an Bürgermeister Ello Schwarzhaupt schickt, erwartet das Stadtoberhaupt eine exzentrische Bitte oder bitteres Geplapper des Einsiedlers vom Friedhof. Stattdessen ist das Pergament in seltsamer, kryptischer Schrift verfasst, die sich der üblichen allgemeinen Schriftsprache entzieht. Da ihm die wissenschaftliche Ausbildung fehlt, um alte oder esoterische Sprachen zu entschlüsseln, weigert sich Bürgermeister Schwarzhaupt, den Brief einfach abzutun, da er weiß, dass selbst verrückte Einsiedler im Dämmerwald eine Gefahr darstellen können."},{t="Der Gelehrte von Dunkelhain",b="Um die Chiffre zu knacken, weist Schwarzhaupt Reisende auf der anderen Seite des Platzes an Sirra Von'Indi. Sirra ist Dunkelhains Gelehrter für esoterisches Wissen, der mit alten Künsten und vergessenen Sprachen bestens vertraut ist. Obwohl Sirra über den Geisteszustand von Calvinius spottet – und bemerkt, dass jeder, der neben einem verfluchten Friedhof wohnt, ein verrottetes Gehirn haben muss –, nimmt er das Pergament ernst genug, um mit dem mühsamen Prozess der Transkription zu beginnen."},{t="Ein Einblick in den Geist des Einsiedlers",b="Die Übergabe des Briefes setzt eine düstere Enthüllung für die Stadt in Gang. Während Calvinius zuvor als gebrechlicher, zurückgezogener alter Mann erschien, der um Vorräte und Schutz vor Ghulen bettelte, signalisiert sein verschlüsselter Brief an den Bürgermeister eine weitaus dunklere Intelligenz und eine bevorstehende Abrechnung, der Dunkelhain nur schlecht gewachsen ist."}},faq={{q="Warum kann Bürgermeister Schwarzhaupt den Brief nicht selbst lesen?",a="Der von Calvinius überbrachte Brief ist in einer ungewöhnlichen Schrift oder einer alten Chiffre verfasst. Bürgermeister Ello Schwarzhaupt ist eher ein Verwalter und Adliger als ein Linguist, daher schickt er ihn an Sirra Von'Indi, den Experten für alte Künste und arkane Sprachen in Dunkelhain.",al={"warum kann ello die notiz nicht lesen","schwarzhaupt brief übersetzen","warum wird ein übersetzer benötigt"}},{q="Wer ist Sirra Von'Indi?",a="Sirra Von'Indi ist ein gelehrter Bewohner von Dunkelhain. Bekannt für seine Expertise in obskuren Sprachen, Geschichte und alten Künsten, dient er als Ansprechpartner der Stadt, wann immer mysteriöse Texte oder Relikte aus den dunklen Wäldern auftauchen.",al={"wer ist sirra von indi","wer ist der übersetzer","gelehrter von dunkelhain"}},{q="Wo wohnt Calvinius?",a="Calvinius lebt in einer baufälligen Hütte nordöstlich vom Friedhof von Rabenflucht im westlichen Dämmerwald, umgeben von ruhelosen Untoten und räuberischen Bestien.",al={"wo ist calvinius","standort des einsiedlers","calvinius dämmerwald"}},{q="Was ist Sirras Reaktion auf die Notiz von Calvinius?",a="Sirra zweifelt offen am Verstand von Calvinius und bemerkt, dass jeder, der bereit ist, neben einem Friedhof zu leben, ein verrottetes Gehirn haben müsse. Dennoch erklärt er sich bereit, den Brief zu prüfen und beginnt, dessen esoterische Schrift zu übersetzen.",al={"was denkt sirra über calvinius","sirra von indi dialog"}},{q="Was passiert nach der Übergabe der Notiz an Sirra?",a="Sirra Von'Indi bittet den Abenteurer zu warten, während er an der Transkription arbeitet. Sobald diese fertig ist, muss der übersetzte Brief zurück zu Lord Ello Schwarzhaupt gebracht werden.",al={"nächste quest nach notiz übersetzen","was kommt nach notiz von calvinius übersetzen"}},{q="Warum hat Calvinius an Bürgermeister Schwarzhaupt geschrieben?",a="Die Notiz von Calvinius an den Bürgermeister ist in einer Schrift verfasst, die Ello nicht lesen kann. Was der Einsiedler tatsächlich geschrieben hat, kommt erst ans Licht, nachdem Sirra Von'Indi sie übersetzt hat.",al={"warum hat calvinius einen brief geschickt","zweck der notiz des einsiedlers"}}},fp="28,385,25.450.0,24.403.0,32.329.1,48.261.0,22.238.0,28.158.0,47.214.0,44.166.1,45.158.1"}
P.entries["quest:2518"] = {n="Tränen des Mondes",s="Tränen des Mondes ist eine feierliche Aufgabe, die von Priesterin A'moora im Tempel des Mondes vergeben wird. Einst von der Göttin Elune geschätzt, ist die große Spinne Lady Sathrah dem Wahnsinn verfallen, was die Schwesternschaft von Elune dazu zwingt, ihr ein gnädiges Ende zu bereiten und ihre heiligen Spinndüsen zu bergen.",h="Tränen des Mondes ist eine feierliche Aufgabe, die von Priesterin A'moora im Tempel des Mondes vergeben wird.",kw={"darnassus","elune","lady sathrah","priesterin a'moora","silbrige spinndüsen","tränen des mondes","teldrassil","tempel des mondes","wellspringsee"},ang={["class:Druid"]="Druiden betrachten Sathrahs plötzliche Wildheit und Qual als ein weiteres beunruhigendes Symptom des Ungleichgewichts von Teldrassil, was die Wiederherstellung ihres Geistes zu einer ökologischen Notwendigkeit macht.",["class:Priest"]="Priester, die der Schwesternschaft von Elune dienen, verstehen, dass Gnade manchmal einen schmerzvollen Schlag erfordert, der in einer rituellen Opfergabe gipfelt, um eine verdorbene Seele in die Umarmung der Göttin zurückzubringen.",["race:NightElf"]="Für die Kaldorei ist das Erlösen von Sathrah eine schmerzhafte Mahnung daran, dass die Verderbnis, die Teldrassils Wildnis heimsucht, weder die einfachen Bestien noch die heiligen Gefährten Elunes verschont."},sec={{t="Der Fall einer geliebten Kreatur",b="In den friedvollen Hallen von Darnassus' Tempel des Mondes beklagt Priesterin A'moora das tragische Schicksal von Lady Sathrah. In früheren Tagen wurde Sathrah als gesegnete Kreatur Elunes verehrt. Unter dem Nachthimmel webte sie zarte silberne Netze, die den Abendnebel einfingen, der sich auf den Ästen von Teldrassil sammelte. Der schimmernde Tau, den ihre Netze auffingen, besaß wundersame Heilkräfte und wurde von der Schwesternschaft von Elune sorgsam für ihre heiligen Dienste gesammelt und bewahrt."},{t="Gnade für Sathrah",b="Wie ein Großteil der Tierwelt auf dem jungen Weltenbaum ist auch Lady Sathrah vor Kurzem einem überwältigenden Wahnsinn anheimgefallen. Ihre Verderbnis bedroht nicht nur Reisende, sondern auch ihre eigene ungeschlüpfte Brut in den nördlichen Gefilden nahe dem Quellsee. Da es unmöglich war, sie zu läutern, während sie gewalttätig und rasend umherstreift, beschloss die Schwesternschaft, dass die Beendigung ihres Leidens der einzig verbliebene barmherzige Weg war. Indem sie ihre silbrigen Spinndüsen bergen, beabsichtigen die Priesterinnen, ihre Überreste auf Elunes Altar darzubringen, und beten darum, dass die Mondgöttin ihr Frieden und eine reine Wiedergeburt gewähren möge."}},faq={{q="Wer ist Lady Sathrah?",a="Lady Sathrah ist eine majestätische, uralte Spinne, die auf Teldrassil heimisch ist. Traditionell als Geliebte Elunes verehrt, war sie dafür bekannt, silbrige Netze zu weben, die den an natürlichen Heilkräften reichen Nachtnebel einfingen.",al={"lady sathrah lore","wer ist lady sathrah","sathrah hintergrundgeschichte","sathrah spinne"}},{q="Warum muss Lady Sathrah getötet werden?",a="Sie erlag einem schleichenden Wahnsinn, der die Tierwelt von Teldrassil befallen hat. Da sie gewalttätig den Verstand verlor und zu einer Gefahr für ihren eigenen Nachwuchs wie auch für andere wurde, entschieden die Priesterinnen, dass ihre Tötung ein Akt der Gnade war.",al={"warum sathrah töten","kann sathrah gerettet werden","warum ist sathrah aggressiv"}},{q="Wo ist Lady Sathrah zu finden?",a="Lady Sathrah hat ihren Bau in der nördlichen Wildnis von Teldrassil, nahe den Ufern des Quellsees.",al={"lady sathrah aufenthaltsort","wo ist sathrah","sathrah finden"}},{q="Wofür wurden Lady Sathrahs Netze verwendet?",a="Ihre Netze fingen den Abendnebel ein und bildeten einen wirkmächtigen silbrigen Tau, der für seine tiefgreifenden Heilkräfte bekannt war und von der Schwesternschaft von Elune im Tempel des Mondes aufbewahrt wurde.",al={"bedeutung von tränen des mondes","verwendung von sathrahs netzen","silbriger tau lore"}},{q="Wer vergibt die Quest Tränen des Mondes?",a="Priesterin A'moora, eine Dienerin im Tempel des Mondes in Darnassus, vergibt die Quest an vertrauenswürdige Abenteurer der Allianz.",al={"wer vergibt tränen des mondes","tränen des mondes questgeber","priesterin a'moora"}},{q="Was tun die Priesterinnen mit Sathrahs Spinndüsen?",a="Sie werden Elune am Tempelaltar als Weihegabe dargebracht, um die Göttin darum zu bitten, Sathrahs Geist aufzunehmen, sie zu segnen und ihr eine Wiedergeburt in friedvoller Ruhe zu gewähren.",al={"was geschieht mit den spinndüsen","zweck der spinndüsen","opfergabe an elune"}}},fp="17,276,25.482.0,17.570.1,20.203.0,40.218.0,28.105.0,39.159.0,38.132.0,55.174.0"}
P.entries["quest:2519"] = {n="Der Tempel des Mondes",s="The Temple of the Moon ist eine Einführungsquest in Darnassus, bei der Schwester Aquinne Abenteurer anweist, Priesterin A'moora aufzusuchen. Die Schwesternschaft der Elune benötigt Hilfe für eine leidende uralte Kreatur, die in den Zweigen von Teldrassil lebt. Sie dient als Auftakt zu einem feierlichen Ritual der Gnade.",h="The Temple of the Moon ist eine Einführungsquest in Darnassus, bei der Schwester Aquinne Abenteurer anweist...",kw={"darnassus","elune","priesterin a'moora","sathrah","schwester aquinne","schwesternschaft der elune","die tempelgärten","tempel des mondes"},ang={["class:Druid"]="Druiden sind zutiefst besorgt um jede große Kreatur der Wildnis in Not, was den Ruf aus der Die Tempelgärten zu einer dringenden Angelegenheit des natürlichen Gleichgewichts macht.",["class:Priest"]="Priester, die durch Darnassus wandeln, fühlen sich von Natur aus zur Arbeit der Schwesternschaft hingezogen und unterstützen ihre Mitdiener des Göttlichen bei Riten der Heilung und Gnade.",["race:NightElf"]="Für Nachtelfen ist es eine Erweiterung ihrer Pflicht, das heilige Ökosystem von Teldrassil zu schützen und die Führung der Priesterschaft der Elune aufrechtzuerhalten, wenn sie auf Schwester Aquinne antworten."},sec={{t="Ein Flehen in den Gärten",b="Während sie zwischen den Gewässern und schattigen Hainen der Die Tempelgärten umherwandeln, treffen Reisende auf Schwester Aquinne, eine ergebene Dienerin der Elune. Da sie fähige Hände spürt, wendet sie sich im Namen ihres Ordens an sie. Eine ehrwürdige Waldkreatur leidet und die Schwestern können sich nicht allein um die Angelegenheit kümmern."},{t="In den Tempel des Mondes",b="Schwester Aquinne weist Kandidaten auf den großen Tempel des Mondes gleich im Südosten hin. Dort koordiniert Priesterin A'moora die Rituale und praktischen Pflichten, die erforderlich sind, um sich um die gepeinigte Tierwelt von Teldrassil zu kümmern, und bereitet mitfühlende Verbündete auf eine traurige Aufgabe der Gnade vor."}},faq={{q="Wer beginnt die Quest The Temple of the Moon?",a="Schwester Aquinne beginnt die Quest. Sie steht draußen im Distrikt der Die Tempelgärten in Darnassus.",al={"questgeber the temple of the moon","wo erhalte ich die quest the temple of the moon","wer gibt die quest the temple of the moon"}},{q="Wo befindet sich Priesterin A'moora?",a="Priesterin A'moora befindet sich im Inneren des großen Tempels des Mondes, der sich südöstlich der Die Tempelgärten in Darnassus befindet.",al={"wo ist priesterin a'moora","a'moora finden","standort priesterin a'moora"}},{q="Welche Kreatur benötigt Hilfe?",a="Bei der Kreatur handelt es sich um Sathrah, eine verehrte Spinne von Teldrassil, deren Notlage zu einem Ritual der Gnade führt, das von der Priesterschaft beaufsichtigt wird.",al={"welche kreatur braucht hilfe","wer ist die waldkreatur","worum geht es in dieser questreihe"}},{q="Ist diese Quest erforderlich, um die Kette fortzusetzen?",a="Nein. The Temple of the Moon dient als optionale Breadcrumb-Quest. Ihr könnt direkt mit Priesterin A'moora im Tempel sprechen, um die Ritualaufgaben zu übernehmen, ohne vorher Schwester Aquinne aufzusuchen.",al={"ist the temple of the moon erforderlich","kann ich the temple of the moon überspringen","the temple of the moon breadcrumb"}},{q="Welche Quest folgt auf diese?",a="Priesterin A'moora bietet die Quest Tears of the Moon an und weist Euch an, das Leiden von Lady Sathrah zu beenden und ihre Silbrige Spinndrüsen zurückzubringen.",al={"nächste quest nach the temple of the moon","the temple of the moon folgequest","was kommt als nächstes"}},{q="Warum bittet die Schwesternschaft der Elune Außenseiter um Hilfe?",a="Die Verderbnis, die in der Flora und Fauna von Teldrassil verweilt, überlastet die Schwesternschaft und zwingt die Priesterinnen dazu, kompetente Reisende zu rekrutieren, die die Natur und die Göttin respektieren.",al={"warum werden außenseiter gebeten","warum braucht die priesterschaft hilfe","schwester aquinne motiv"}}},fx={e3d31678={q="Warum schickt Schwester Aquinne Euch zu Priesterin A'moora?",a="Schwester Aquinne erkennt, dass eine ehrwürdige Kreatur der Wälder von Teldrassil leidet und dringend Hilfe benötigt, aber die Angelegenheit erfordert die direkte Anleitung der Priesterschaft. Da sie weiß, dass eine heikle, schwierige Aufgabe bevorsteht, weist sie fähige Reisende an Priesterin A'moora im Tempel des Mondes hin, damit diese ordnungsgemäße Anweisungen erhalten, wie sie eingreifen können.",al={"warum will schwester aquinne das","tempel des mondes warum entsendung","zweck schwester aquinne"}}},fp="22,303,21.286.0,20.283.0,44.114.0,35.125.0,37.137.0,46.199.0,34.138.0,57.181.0"}
P.entries["quest:252"] = {n="Übersetzung für Ello",s="Translation to Ello ist eine entscheidende Quest in der Handlungsreihe um Calvinius im Dämmerwald. Nachdem der Abenteurer Sirra Von'Indi gebeten hat, die kryptischen Aufzeichnungen des Eremiten zu entziffern, wird er damit beauftragt, das übersetzte Pergament direkt an Lord Ello Schwarzhaupt in Dunkelhain zu überbringen.",h="Translation to Ello ist eine entscheidende Quest in der Handlungsreihe um Calvinius im Dämmerwald.",kw={"calvinius","dunkelhain","ello schwarzhaupt","raven hill","sirra von'indi","translation to ello"},ang={["faction:Alliance"]="Für Champions der Allianz ist dieser Moment eine schmerzhafte Lektion über die Tücke des Dämmerwalds: Falsches Vertrauen in den Wäldern kann eine ganze Siedlung unschuldiger Bürger gefährden."},sec={{t="Eine verspätete Erkenntnis",b="Tagelang ließ der betagte Eremit Calvinius Reisende Besorgungen im gesamten Dämmerwald erledigen, unter dem Vorwand, er müsse sein gebrechliches Überleben sichern. Er bat um Faden, konservierte Reagenzien und persönliche Gegenstände. Erst als Sirra Von'Indi endlich sein privates Pergament entziffert, kommt die Wahrheit ans Licht: Der freundliche alte Mann ist ein geistesgestörter Einbalsamierer, und die gesammelten Komponenten dienten dazu, eine furchterregende Waffe der Rache zu konstruieren, die direkt auf Dunkelhain gerichtet ist."},{t="Der Weg nach Dunkelhain",b="Als er Lord Ello Schwarzhaupt den übersetzten Brief überreicht, weicht jede Farbe aus dem Gesicht des Bürgermeisters. Welche edlen Motive das Handeln eines Abenteurers auch geleitet haben mögen, die Lieferung jener letzten Vorräte ermöglichte es Calvinius, seine monströse Schöpfung, Kleiner, fertigzustellen. Die Übergabe des Briefes führt dazu, dass der Koloss direkt ostwärts entlang der Straße vom Friedhof von Rabenflucht marschiert und jede Patrouille der Nachtwache niedermetzelt, die sich ihm in den Weg stellt."}},faq={{q="Was steht im übersetzten Brief?",a="Sirra fürchtet, dass Calvinius etwas Unaussprechliches getan hat. Der übersetzte Brief muss dringend zu Lord Ello Schwarzhaupt gebracht werden, damit dieser die Gefahr für Dunkelhain einschätzen kann.",al={"was steht im brief","text des briefes von calvinius","was wurde übersetzt"}},{q="Wer ist Sirra Von'Indi?",a="Sirra Von'Indi ist ein Gelehrter, der in Dunkelhain lebt. Seine sprachliche und analytische Expertise ermöglicht es ihm, die kryptischen Notizen und Briefe zu entziffern, die Calvinius hinterlassen hat, wenn andere seine Schrift nicht lesen können.",al={"wer ist sirra","sirra von indi hintergrund"}},{q="Warum gibt Lord Ello dem Spieler die Schuld?",a="Lord Ellos Reaktion wird deutlich, sobald er den übersetzten Brief liest. Die Untersuchung verlangt von Euch, ihm die Warnung so schnell wie möglich zu überbringen.",al={"warum ist ello wütend","habe ich kleiner verursacht","ello reaktion"}},{q="Was passiert unmittelbar nach Abschluss dieser Quest?",a="Überbringt den übersetzten Brief an Lord Ello Schwarzhaupt in Dunkelhain. Seine Antwort und die Gefahr, vor der er warnt, werden enthüllt, sobald er ihn liest.",al={"was löst kleiner aus","erscheint kleiner","kleiner ereignis"}},{q="Wohin geht Kleiner danach?",a="Kleiner wird mit der Straße zwischen dem Friedhof von Rabenflucht und Dunkelhain in Verbindung gebracht. Seine Rolle in Calvinius' Komplott wird durch die Untersuchung aufgedeckt.",al={"kleiner weg","wohin marschiert kleiner"}},{q="Welche Quest folgt als Nächstes?",a="Nach der Übergabe des Briefes schickt Lord Ello Abenteurer weiter in die Quest 'Die Braut des Einbalsamierers'.",al={"nächste quest","nach translation to ello"}}},fx={["203575b3"]={q="Warum möchte Sirra Von'Indi, dass der Brief an Ello überbracht wird?",a="Nachdem Sirra den Brief entziffert hatte, wurde ihm klar, dass Calvinius etwas Unaussprechliches begangen und ein monströses Verderben entfesselt hat, das bereits auf Dunkelhain zusteuert. Er schickt Euch, um Lord Ello Schwarzhaupt sofort zu warnen, damit die Stadtführung sich auf die bevorstehende Katastrophe vorbereiten kann, bevor sie ihre Tore erreicht.",al={"warum brief an ello schicken","sirra von indi motiv","warum übersetzte notiz überbringen"}},["4e225af8"]={q="Warum schickt Sirra Euch, um Lord Ello zu warnen, anstatt selbst zu gehen?",a="Ihr wart die Person, die ursprünglich von Lord Ello damit beauftragt wurde, Calvinius' verdächtige Schriften zu entziffern, und Ihr habt den seltsamen Brief überhaupt erst zu Sirra gebracht. Da eine monströse Bedrohung bereits unterwegs ist und jede Sekunde zählt, ist es der schnellste Weg, die Warnung in die Hände des Bürgermeisters zu bekommen, wenn er den fähigen Abenteurer schickt, der direkt vor ihm steht.",al={"warum ich translation to ello","warum geht sirra nicht zu ello","warum spieler zu ello schicken"}}},fp="19,263,21.435.1,21.418.1,41.169.2,22.206.0,36.145.2,53.137.2,34.149.2,22.110.1"}
P.entries["quest:2520"] = {n="Sathrahs Opferung",s="Sathrahs Opferung ist der Abschluss eines feierlichen Rituals, das im Tempel des Mondes in Darnassus vollzogen wird. Betraut mit den Überresten von Lady Sathrah, opfern die Spieler die Spinndrüsen der gefallenen Kreatur den heiligen Wassern Elunes, um ihre Seele von der Verderbnis zu reinigen und ihren Geist zur Ruhe zu betten.",h="Sathrahs Opferung ist der Abschluss eines feierlichen Rituals, das im Tempel des Mondes in Darnassus...",kw={"a'moora","darnassus","elune","brunnen","lady sathrah","reinigung","sathrah","spinndrüsen","teldrassil","tempel des mondes"},ang={["class:Druid"]="Druiden, die den Teldrassil plagenden Siechtum betrauern, schöpfen Trost aus dem Wissen, dass gefallene Bestien durch Läuterung in den natürlichen Kreislauf zurückgeführt werden können.",["class:Priest"]="Priester, die durch den Tempel des Mondes wandeln, erleben aus erster Hand, wie Elunes heiliges Licht und ihre heiligen Wasser Geister heilen können, die von Wahnsinn und Verderbnis zerrissen wurden.",["race:NightElf"]="Für Nachtelfen spiegelt dieser Ritus ihre feierliche Pflicht gegenüber der Flora und Fauna von Kalimdor wider: Selbst wenn Geschöpfe erlegt werden müssen, werden ihre Geister durch Elunes Anmut geehrt und gereinigt."},sec={{t="Eine Reinigung in heiligen Wassern",b="Nach der tragischen Tötung von Lady Sathrah überträgt Priesterin A'moora den Initianden eine letzte spirituelle Pflicht. Die große Spinne war dem dunklen Wahnsinn anheimgefallen, der sich über Teldrassil ausbreitete, und der ihr einst friedliches Wesen in blinde Aggression verwandelte. Anstatt ihren Tod als bloße Ausrottung zu betrachten, strebt die Priesterschaft der Elune danach, ihre gefallene Essenz zu erlösen. Indem man ihre silbrigen Spinndrüsen in den zentralen Brunnen des Tempels des Mondes legt, waschen die geweihten Wasser die befleckende Verderbnis fort und schenken ihr Erlösung."},{t="Die Erneuerung von Sathrah",b="Die Darbringung des Opfers an Elune bringt augenblickliche spirituelle Verbundenheit mit sich. Sobald die Spinndrüsen das mondbeschienene Becken berühren, erhebt sich die ätherische Gestalt von Lady Sathrah aus den Tiefen – friedlich und gereinigt von dem Leiden, das sie in den Wahnsinn getrieben hatte. Die Schwesternschaft von Elune betrachtet dieses Ritual als notwendige Erlösung; obwohl der Verlust der großen Kreatur zutiefst betrauert wird, lehrt der Glaube der Nachtelfen, dass sie durch diese heilige Läuterung eines Tages mit einem unbefleckten Geist wiedergeboren werden kann."}},faq={{q="Wer war Lady Sathrah?",a="Lady Sathrah war eine große Spinne, die Teldrassil bewohnte und der schleichenden Verderbnis erlag, welche die Tierwelt des Weltenbaums heimsuchte. Vom Verderben in den Wahnsinn getrieben, musste sie getötet werden, damit ihre sterblichen Überreste geheiligt werden konnten.",al={"lady sathrah","wer ist sathrah","was ist sathrah"}},{q="Wo wird das Opfer dargebracht?",a="Das Opfer wird im heiligen Brunnen dargebracht, der sich in der Mitte des Tempels des Mondes befindet, dem zentralen Heiligtum der Schwesternschaft von Elune in Darnassus.",al={"wo opfer darbringen","brunnen standort","tempelbrunnen"}},{q="Was geschieht, wenn man die Spinndrüsen in den Brunnen legt?",a="Sobald die silbrigen Spinndrüsen in das gesegnete Wasser gelegt werden, manifestiert sich der gereinigte Geist von Sathrah kurz im Becken und wandelt frei und friedvoll als Zeichen dafür, dass Elune das Opfer angenommen hat.",al={"was passiert am brunnen","geist von sathrah brunnen"}},{q="Warum musste Lady Sathrah sterben?",a="Die Verderbnis, die ihren Verstand vergiftete, war zu tief verwurzelt, als dass sie zu Lebzeiten hätte geheilt werden können. Priesterin A'moora und die Schwesternschaft glaubten, dass die einzige Rettung für ihre Seele darin bestand, ihr Leiden zu beenden und ihre Überreste in Elunes heiligen Wassern zu reinigen.",al={"warum sathrah toeten","konnte sathrah gerettet werden","sathrah wahnsinn"}},{q="Wer vergibt die Quest Sathrahs Opferung?",a="Die Quest wird von Priesterin A'moora vergeben und abgeschlossen, die ihren Dienst im Tempel des Mondes in Darnassus versieht und die zentrale Kammer überblickt.",al={"questgeber","wo abgeben","a'moora standort"}},{q="Welcher Glaube liegt diesem Ritual der Nachtelfen zugrunde?",a="Die Nachtelfen glauben, dass Seelen, die von der Mondmutter gereinigt wurden, mit geläutertem und erneuertem Geist in die natürliche Welt wiedergeboren werden können, frei vom anhaltenden Makel der Verderbnis.",al={"nachtelf reinkarnation","elune reinigung","wiedergeburt lore"}}},fx={f4be164d={q="Warum möchte Priesterin A'moora, dass dies getan wird?",a="Priesterin A'moora versucht, Lady Sathrah friedlich zur Ruhe zu betten und die Verderbnis zu tilgen, die die einst edle Kreatur quälte. Indem Sathrahs Spinndrüsen in die heiligen Wasser des Tempel des Mondes gelegt werden, kann Elune's Grace den verbliebenen Makel reinigen, der die große Spinne in den Wahnsinn trieb, was es ihrem Geist ermöglicht, erlöst und schließlich erneuert wiedergeboren zu werden.",al={"amoora motiv","warum das opfer darbringen","warum will amoora sathrah opfer"}}},fp="19,288,28.530.0,22.470.1,21.213.0,31.158.0,59.182.1,33.217.0,40.144.0,54.185.0"}
P.entries["quest:253"] = {n="Braut des Einbalsamierers",s="„Bride of the Embalmer“ ist eine gefährliche Aufgabe, die von Lord Ello Schwarzhaupt in Dunkelhain vergeben wird. Nachdem die Stadtführung die verstörende Wahrheit hinter dem legendären Einbalsamierer zusammengetragen hat, schickt sie Euch auf die heimgesuchten Friedhöfe des Dämmerwalds, um die Ruhestätte seiner wiedererweckten Frau zu finden. Indem Ihr das lebendige Herz des Alchemisten aus Elizas verfluchten Überresten reißt, zielt Ihr darauf ab, ihn seiner unheiligen Macht zu berauben.",h="„Bride of the Embalmer“ ist eine gefährliche Aufgabe, die von Lord Ello Schwarzhaupt in Dunkelhain vergeben...",kw={"alchemist","bride of the embalmer","dunkelhain","dämmerwald","eliza","ello schwarzhaupt","das herz des einbalsamierers","grab","der einbalsamierer"},ang={["class:Paladin"]="Paladine betrachten Elizas unheilige Reanimation als einen Frevel am Licht und an den Gesetzen der Natur und läutern den fleischfressenden Schrecken mit Freuden, wodurch sie die blasphemische Lebensader des Nekromanten durchtrennen.",["class:Priest"]="Priester erkennen die Tragödie hinter einem trauernden Witwer, der den dunklen Künsten verfallen ist, wissen jedoch, dass Elizas fleischhungriger Hohn auf das Leben mit heiliger Endgültigkeit zur Ruhe gebettet werden muss.",["faction:Alliance"]="Da The Night Watch im Kampf gegen die wilden Schrecken des Dämmerwalds überfordert ist, muss ein Champion der Allianz eingreifen, um Dunkelhain vor diesem uralten, schleichenden Wahnsinn zu verteidigen."},sec={{t="Eine zum Leben erwachte Gutenachtgeschichte",b="Jahrelang erzählten Eltern im Dämmerwald ihren verängstigten Kindern die Geschichte des Einbalsamierers. Der Sage nach war er einst ein gütiger Alchemist, dessen Verstand nach dem tragischen Ableben seiner geliebten Frau Eliza zerbrach. Verzweifelt darauf bedacht, der Sterblichkeit ein Schnippchen zu schlagen, wandte er sich üblen Zaubereien zu und brachte das ultimative Opfer: Er schnitt sein eigenes schlagendes Herz heraus und setzte es in die Brust seiner Frau ein. Lord Ello Schwarzhaupt tat dies lange Zeit als bloße Dorffolklore ab, doch jüngste Enthüllungen haben bewiesen, dass der Einbalsamierer unter ihnen weilt und sein finsteres Werk unter der Friedhofserde schwelt."},{t="Die wiedererweckte Braut",b="Das Ritual hatte zwar Erfolg dabei, Eliza wieder zum Leben zu erwecken, doch dunkle Nekromantie fordert stets einen grausamen Tribut. Durch den gestohlenen Funken des Lebens wiederbelebt, verwandelte sich Eliza in eine unersättliche Abscheulichkeit, die mit einem unstillbaren Hunger nach lebendem Menschenfleisch verflucht war. Entsetzt und unwillig, seine Schöpfung zu vernichten, war der Einbalsamierer gezwungen, seine Braut in einem einsamen Grab zu verbergen, wo er sie im Geheimen aufsuchte, während er weitere Gräueltaten plante. Um den Nekromanten zu entwaffnen, weist Lord Schwarzhaupt mutige Seelen an, Eliza zu exhumieren, den nach Fleisch gierenden Schrecken niederzustrecken und das noch pulsierende Organ zurückzufordern, das seine dunkle Kunst aufrechterhält."},{t="Dunkelhains Ägide",b="Wenn Ihr das schlagende Herz aus Elizas verfallender Brust reißt und es nach Dunkelhain zurückbringt, atmet Lord Schwarzhaupt erleichtert auf. Weit davon entfernt, es einfach zu zerstören, beabsichtigt der Bürgermeister der Stadt, das finstere Handwerk des Alchemisten gegen ihn selbst zu wenden. Er glaubt, dass die im Herzen verweilende unheimliche Magie als schützender Talisman und Ägide über Dunkelhain dienen wird, um die belagerte Stadt vor jeglichem Zorn zu bewahren, den der geschwächte Einbalsamierer aus Rache noch heraufbeschwören könnte."}},faq={{q="Wer ist der Einbalsamierer?",a="Der Einbalsamierer war ursprünglich ein Alchemist im Dämmerwald, der den Verstand verlor, nachdem seine Frau Eliza gestorben war. Er wandte sich nekromantischen Künsten zu, schnitt sein eigenes lebendiges Herz heraus und setzte es in Elizas Leichnam ein, um sie wiederzuerwecken, wodurch er sich selbst in ein schwer fassbares Ungeheuer verwandelte.",al={"überlieferung des einbalsamierers","wer ist der einbalsamierer","hintergrundgeschichte des einbalsamierers"}},{q="Warum wurde Eliza begraben, wenn sie wieder zum Leben erweckt wurde?",a="Obwohl der Alchemist Eliza mithilfe seines eigenen Herzens erfolgreich wiederbelebt hatte, verfluchte die dunkle Magie sie mit einem unstillbaren Hunger nach lebendem Menschenfleisch. Da er sie weder sicher in der Gesellschaft halten noch ihren wilden Appetit stillen konnte, war er gezwungen, sie auf einem Friedhof begraben zu halten.",al={"warum eliza begraben liegt","elizas grab","warum eliza im grab halten"}},{q="Warum will Lord Schwarzhaupt das Herz des Einbalsamierers?",a="Der Geschichte nach, die Ello erzählt, ist das Herz die Quelle der Macht des Einbalsamierers. Er bittet Euch, es aus Elizas Grab zu bergen, solange es noch schlägt, in dem Glauben, dass dies jene Macht brechen wird.",al={"warum das herz holen","zweck des herzens des einbalsamierers"}},{q="Wo beginnt diese Questreihe?",a="Die Quest folgt direkt auf „Translation to Ello“, worin alte Briefe und Nachforschungen an Lord Ello Schwarzhaupt überbracht werden, die beweisen, dass der Einbalsamierer aus den örtlichen Ammenmärchen eine aktive und gefährliche Wirklichkeit ist.",al={"questvoraussetzung","wie man bride of the embalmer erhält","vorquest für den einbalsamierer"}},{q="Besiegt das Bergen des Herzens den Einbalsamierer dauerhaft?",a="Ello glaubt, dass das Bergen des Herzens die Macht des Einbalsamierers brechen wird. Das Ergebnis der Mission offenbart sich, wenn Ihr nach Dunkelhain zurückkehrt.",al={"ist der einbalsamierer tot","tötet dies den einbalsamierer"}},{q="Wer vergibt diese Quest?",a="Lord Ello Schwarzhaupt, der Bürgermeister und Anführer von Dunkelhain, vergibt die Quest aus dem Rathaus von Dunkelhain, nachdem er die schauderhafte Wahrheit hinter der Folklore der Stadt erfahren hat.",al={"questgeber","wer startet bride of the embalmer"}}},fx={a9aedc81={q="Warum möchte Lord Ello Schwarzhaupt, dass Elizas Grab gestört wird?",a="Lord Ello Schwarzhaupt will die Macht des Einbalsamierers brechen, bevor der wahnsinnige Alchemist Dunkelhain ins Verderben stürzt. Der Einbalsamierer goss seine eigene dunkle Magie und sein Herz in die Wiederbelebung seiner verstorbenen Frau Eliza. Indem er das Herz zurückgewinnt, während es noch schlägt, beabsichtigt Schwarzhaupt, die übernatürliche Stärke des Monsters zu schwächen und seine verbleibende Schutzmagie in einen Schutzschild für die Stadt zu verwandeln.",al={"warum will ello das erledigt haben","ebonlocke motiv bride of the embalmer","warum elizas grab finden"}},b836fb1b={q="Was ist Eliza und warum ist sie in Raven Hill begraben?",a="Eliza ist die wiederbelebte Bride of the Embalmer, die in einem vernachlässigten Grab auf dem Friedhof von Raven Hill ruht. Getrieben vom Wahnsinn vor Trauer legte ihr Ehemann sein eigenes Herz in ihre Leiche, um sie wiederzuerwecken. Das Ritual war erfolgreich, aber es verfluchte sie mit einem unersättlichen Hunger nach lebendem menschlichen Fleisch, was ihn zwang, sie begraben zu halten, bis er einen Weg finden konnte, sie zu erhalten.",al={"wer ist eliza","bride of the embalmer ziel","warum ist eliza begraben"}}},fp="21,386,26.579.0,21.604.1,17.464.2,20.253.0,53.261.0,50.191.0,34.210.0,58.140.1,21.162.0"}
P.entries["quest:254"] = {n="Graben in der Erde",s="Graben in der Erde markiert den düsteren Höhepunkt der Jagd nach dem verschwundenen Herzen des Einbalsamierers im Dämmerwald. Tief in der unersättlichen Stille des Friedhofs von Rabenflucht verbirgt ein aufgeworfener Erdhügel einen vergrabenen Schrecken, der sich weigert, tot zu bleiben.",h="Graben in der Erde markiert den düsteren Höhepunkt der Jagd nach dem verschwundenen Herzen des...",kw={"calvinius","braut des einbalsamierers","sarg","graben in der erde","dämmerwald","eliza","elizas graberde","das herz des einbalsamierers","friedhof von rabenflucht"},ang={["class:Paladin"]="Das Stören frischer Gräber widerspricht jedem Bestattungsritus des Heiligen Lichts, doch das Befreien und Vernichten des unnatürlichen Unholds im Inneren ist ein notwendiger Akt der Läuterung.",["class:Priest"]="Die Geräusche scharrender Klauen und mahlender Zähne unter geweihter Erde sind ein Frevel an der friedvollen Ruhe, die das Licht den Verstorbenen des Dämmerwalds versprochen hat.",["faction:Alliance"]="Die Nachtwache kämpft unentwegt gegen den Schrecken an, der aus Rabenflucht quillt; die vom Einbalsamierer verborgenen Schrecken auszumerzen, ist für die Sicherheit von Dunkelhain unerlässlich."},sec={{t="Ein geschändetes Grab",b="Inmitten der unzähligen verwitterten Grabsteine auf dem Friedhof von Rabenflucht liegt ein Fleck frisch umgegrabener, lockerer Erde, markiert mit dem Namen Eliza. Während viele Gräber im Dämmerwald von Aasfressern oder wilden Ghulen geschändet wurden, geschah dies hier mit wohlüberlegter Absicht. Gräbt man durch die oberste Erdschicht, kommt das splitternde Holz eines vergrabenen Sarges zum Vorschein – er verschließt, was auch immer der Einbalsamierer vor dem Licht des Tages verbergen wollte."},{t="Das Scharren im Inneren",b="Unter dem gesplitterten Holz liegt keine ruhende Leiche. Presst man die Hand gegen den Deckel, sind hektische Vibrationen zu spüren – das verzweifelte Scharren langer, bekrallter Finger und das hohle Klappern verfaulter Kiefer. Calvinius' morbides Experiment, Eliza, regt sich ungestüm in ihrem Kiefernholzsarg, während das fehlende Herz des Einbalsamierers in ihrer Brust schlägt und sie darauf lauert, dass unvorsichtige Hände das Grab aufbrechen."}},faq={{q="Was ist in Elizas Grab vergraben?",a="Unter der Erde liegt ein Sarg begraben, der Eliza birgt – eine untote Monstrosität, die vom Einbalsamierer erschaffen wurde. Sie wurde unter der Erde versiegelt, mit dem eigenen Herzen des Einbalsamierers in ihrer Brust.",al={"was ist im grab","wer ist eliza","inhalt von elizas grab"}},{q="Wo befindet sich dieses Grab?",a="Elizas Grab befindet sich auf dem Friedhof von Rabenflucht im westlichen Dämmerwald, inmitten des Meeres aus heimgesuchten Krypten und umherstreifenden Untoten.",al={"wo liegt elizas grab","elizas grab ort","standort der graberde"}},{q="Warum müsst Ihr den Sarg ausgraben?",a="Ihr müsst das Grab aufgraben, um Eliza entgegenzutreten und das Herz des Einbalsamierers zu bergen, womit die Nachforschungen rund um die finsteren Machenschaften des Einbalsamierers abgeschlossen werden.",al={"warum das grab ausheben","zweck des grabens","warum den sarg öffnen"}},{q="Was geschieht, wenn der Sarg geöffnet wird?",a="Wird der Sarg geöffnet, befreit dies Eliza aus ihrem seichten Gefängnis und zwingt Euch dazu, den um sich schlagenden, unersättlichen Ghul zu vernichten, um das in ihrem Inneren verborgene Herz an Euch zu bringen.",al={"was passiert als nächstes","sarg geöffnet","elizas sarg öffnen"}},{q="Wer hat Eliza dort vergraben?",a="Der Einbalsamierer hat sie dort abgelegt und seine grausige Schöpfung zusammen mit seinem wertvollen Herzen auf den weitläufigen Gräberfeldern von Rabenflucht verborgen.",al={"wer begrub eliza","wer hat sie vergraben"}},{q="Ist Eliza ein gewöhnlicher Ghul?",a="Eliza ist die verstorbene Ehefrau des Einbalsamierers, die durch seine dunkle Magie und mit seinem eigenen Herzen in ihrer Brust wiederbelebt wurde; sie ist weitaus zäher und zielgerichteter als die geistlosen Ghule, die über die Straßen des Dämmerwalds streifen.",al={"was für ein monster ist eliza","ist eliza ein ghul"}}},fp="24,239,17.422.0,21.384.1,32.188.1,28.122.0,39.157.1,39.161.1,28.141.1,27.186.1"}
P.entries["quest:2541"] = {n="Der schlafende Druide",s="Tief im Grabhügel von Ban'ethil befindet sich der schlafende Nachtelf Oben Zornklaue in einer fatalen magischen Zwangslage. Feindselige Schamanen der Gnarlpinefurbolgs haben seinen träumenden Geist von seinem physischen Körper getrennt und üble Verzauberungen genutzt, um sein Fleisch zu einem rasenden Wächter zu animieren.",h="Tief im Grabhügel von Ban'ethil befindet sich der schlafende Nachtelf Oben Zornklaue in einer fatalen...",kw={"grabhügel von ban'ethil","grabhügel","smaragdgrüner traum","gnarlpine","oben zornklaue","voodooglücksbringer des schamanen","teldrassil","der schlafende druide"},ang={["class:Druid"]="Für Druiden ist Obens Situation ein wahr gewordener Albtraum: Die Übernahme des eigenen Körpers während der Zwiesprache im Smaragdgrünen Traum verletzt die Grundfesten des druidischen Schlummers.",["race:NightElf"]="Die Schändung des Grabhügels von Ban'ethil zeigt, wie tief die Gnarlpinefurbolgs von ihrer uralten Verbundenheit mit den Kaldorei abgefallen sind."},sec={{t="Ein gestörter Schlummer",b="Nachtelfendruiden betreten Grabhügel in ganz Kalimdor, um in jahrhundertelangem Schlummer mit der Natur zu kommunizieren, und wandeln im Smaragdgrünen Traum, während ihre sterblichen Hüllen sicher in Steinnischen ruhen. Die Verderbnis, die Teldrassil heimsucht, hat den einheimischen Gnarlpinestamm der Furbolgs jedoch zu Taten verzweifelter Grausamkeit getrieben. Im Grabhügel von Ban'ethil entdeckten Gnarlpineschamanen einen Weg, die geheiligte Ruhe von Oben Zornklaue zu stören und seinen lebenden Geist von seiner schlafenden Hülle loszureißen."},{t="Voodoo und Verderbnis",b="Anstatt Oben zu töten, nutzten die Gnarlpineschamanen einen finsteren Talisman – einen Voodooglücksbringer des Schamanen –, um seine leere Hülle gewaltsam zu animieren. Hilflos im Smaragdgrünen Traum gefangen, kann Obens verdrängter Geist nur zusehen, wie seine physische Gestalt durch die Gänge streift und blindlings jeden angreift, der den Höhlenbau betritt. Um die Verzauberung zu brechen und einen Weg zur Wiederherstellung seines Körpers zu finden, beauftragt seine ätherische Projektion Abenteurer damit, einen der Gnarlpine-Glücksbringer zur Untersuchung zu beschaffen."}},faq={{q="Wer ist Oben Zornklaue?",a="Oben Zornklaue ist ein Nachtelfendruide, der sich im Grabhügel von Ban'ethil in einen heiligen Schlummer begab, um mit dem Smaragdgrünen Traum zu kommunizieren. Feindselige Gnarlpinefurbolgs brachten seine physische Hülle in ihre Gewalt und vertrieben seinen Geist.",al={"oben zornklaue","wer ist der schlafende druide","schlafender nachtelf im grabhügel"}},{q="Warum greift Obens Körper andere an?",a="Gnarlpineschamanen vollzogen ein Ritual, das Obens Bewusstsein von seinem Fleisch trennte. Sie belebten seine leere, physische Gestalt mit dunkler Magie, damit sie als aggressiver Wächter die Tiefen des Grabhügels bewacht.",al={"warum ist oben feindselig","warum greift oben an","oben zornklaue körper greift an"}},{q="Was ist der Voodooglücksbringer des Schamanen?",a="Es ist ein verzauberter Fokus, den die Gnarlpineschamanen im Grabhügel von Ban'ethil bei sich tragen. Sie nutzen seine dunkle Macht, um die Geister schlafender Druiden aus ihren Körpern zu reißen und deren physische Hüllen zu animieren.",al={"schamanenglücksbringer","voodooglücksbringer teldrassil","was ist voodooglücksbringer des schamanen"}},{q="Wo befindet sich Obens wahrer Geist während der Quest?",a="Obens Bewusstsein ist darin gefangen, durch den Smaragdgrünen Traum zu wandern, unfähig, in seine sterbliche Hülle zurückzukehren. Er kann mit der wachen Welt nur als schimmernder Geist nahe seiner Ruhestätte kommunizieren.",al={"wo ist oben","oben geist aufenthaltsort","smaragdgrüner traum oben"}},{q="Warum sind die Furbolgs im Grabhügel von Ban'ethil feindselig?",a="Der Gnarlpinestamm ist dem wachsenden Makel und Wahnsinn erlegen, der die Tierwelt und die Wälder von Teldrassil verdirbt, was die Furbolgs dazu brachte, sich gegen ihre einstigen Verbündeten, die Nachtelfen, zu wenden und heilige druidische Stätten zu schänden.",al={"warum sind gnarlpine verrückt","furbolg verderbnis teldrassil","warum sind furbolgs aggressiv"}},{q="Kann Obens Körper gerettet werden, ohne ihn zu töten?",a="Die Untersuchung des Voodooglücksbringers des Schamanen ist Obens erste Hoffnung, das Ritual zu brechen. Indem er die üblen Verzauberungen studiert, die sein Fleisch binden, hofft er, die Magie zu verstehen und einen Weg zur Lösung der Krise zu finden.",al={"oben zornklaue retten","kann oben gerettet werden","oben heilen"}}},fx={["08a1a718"]={q="Warum möchte Oben Zornklaue das Amulett?",a="Gnarlpine-Furbolgschamanen haben es geschafft, Oben Zornklaues Geist von seiner schlafenden physischen Form zu trennen. Sein umherwandernder Körper wurde durch ihre dunkle Magie animiert, um jeden gewaltsam anzugreifen, der den Grabhügel von Ban'ethil betritt, während sein wahres Bewusstsein im Der Smaragdgrüne Traum gefangen bleibt. Oben möchte ein Amulett, damit er dessen üble Verzauberung untersuchen und nach einem Weg suchen kann, die Kontrolle der Furbolgs über seinen Körper zu brechen.",al={"oben zornklaue motiv","warum will oben das amulett","warum oben zornklaue helfen"}},["21a70b6c"]={q="Warum sind die Gnarlpine-Schamanen im Grabhügel von Ban'ethil?",a="Der Gnarlpine-Stamm hat den heiligen Grabhügel von Ban'ethil überrannt und die Verwundbarkeit schlafender Nachtelfdruiden ausgenutzt. Ihre Schamanen haben begonnen, abscheuliche Rituale durchzuführen, um die Geister der Druiden von ihrem Fleisch zu trennen, und die Kontrolle über die physischen Körper übernommen, um sie als gewaltsame Wächter zur Bewachung ihres neu besetzten unterirdischen Reiches einzusetzen.",al={"warum gnarlpine schamanen hier","gnarlpine im grabhügel","wer sind gnarlpine schamanen"}},["2131a103"]={q="Warum benötigt Oben Euch, um das Amulett zu bergen?",a="Oben ist völlig unfähig, selbst zu handeln. Sein Geist ist von der wachen Welt abgeschnitten und im Der Smaragdgrüne Traum gefangen, während sein physischer Körper eine animierte Marionette ist, die von den Gnarlpine-Schamanen kontrolliert wird. Ohne physische Form oder Handlungsfähigkeit ist er vollständig auf einen externen Abenteurer angewiesen, der sich den Furbolgs stellt und das Amulett zu seinem Geist bringt.",al={"warum braucht oben mich","warum kann oben das amulett nicht selbst holen","warum ich oben quest"}}},fp="18,273,19.481.0,21.466.1,21.217.0,36.213.0,32.199.0,45.188.0,53.210.0,44.202.0"}
P.entries["quest:255"] = {n="Söldner",s="Söldner ist ein Kopfgeldauftrag, der von Magistrat Bluntnose in Thelsamar ausgestellt wurde, um die vordringenden Oger der Mo'grosh im nordöstlichen Loch Modan auszudünnen. Da militärische Verstärkungen aus Eisenschmiede in monatelanger bürokratischer Verzögerung feststecken, ist der Magistrat gezwungen, durchreisende Abenteurer anzuheuern, um die verwundbaren Siedlungen, Ausgrabungsstätten des Tals und den lebenswichtigen Steinwerkdamm zu schützen.",h="Söldner ist ein Kopfgeldauftrag, der von Magistrat Bluntnose in Thelsamar ausgestellt wurde, um die...",kw={"loch modan","magistrat bluntnose","söldner","mo'grosh","oger","der steinwerkdamm","thelsamar"},ang={["faction:Alliance"]="Loch Modan bildet einen entscheidenden Korridor zwischen Khaz Modan und den nördlichen Königreichen; ließe man es durch Oger-Überfälle im Chaos versinken, würde dies die Versorgungslinien der Allianz in den Östlichen Königreichen bedrohen.",["race:Dwarf"]="Zu sehen, wie das Kronjuwel zwergischer Ingenieurskunst – der Steinwerkdamm – aufgrund der Bürokratie von Eisenschmiede unbewacht bleibt, macht Bluntnoses Ruf zu den Waffen zu einer persönlichen Angelegenheit für jeden Gebirgsjäger oder Reisenden aus der Hauptstadt."},sec={{t="Eisenschmiedes mahlende Mühlen",b="Thelsamar bekommt die Härte der zwergischen Bürokratie zu spüren. Es dauerte zwei volle Monate, bis Eisenschmiede überhaupt versprach, eine Handvoll Soldaten zur Verstärkung der örtlichen Verteidigung von Loch Modan zu entsenden, und es werden weitere zwei Monate vergehen, bis diese Truppen eintreffen sollen. Da die Stadtwachen an ihren Grenzen sind, kann es sich Magistrat Bluntnose nicht leisten, vier Monate zu warten, während sich feindliche Streitkräfte direkt jenseits der Grenzen des Tals sammeln."},{t="Die Bedrohung in den Hügeln",b="Die Oger der Mo'grosh haben ein Lager in den Hügeln nordöstlich des Lochs befestigt. Ihre wachsende Präsenz gefährdet nicht nur die Stadt Thelsamar, sondern auch die Ironband Excavation Site und den Steinwerkdamm selbst. Sollte der Damm angegriffen oder beschädigt werden, wäre die Verwüstung flussabwärts katastrophal. Da es an offiziellen Gebirgsjäger-Abteilungen fehlt, wandte sich Bluntnose an freischaffende Söldner, um die Reihen der Oger zu lichten und dem Tal Zeit gegen Oger und Troggs zu verschaffen."}},faq={{q="Warum heuert Magistrat Bluntnose Söldner an, anstatt Wachen einzusetzen?",a="Eisenschmiede hat quälend langsam auf Loch Modans Hilferufe reagiert. Es dauerte zwei Monate, bis der Senat die Entsendung von auch nur einer Handvoll Soldaten genehmigte, und weitere zwei Monate, bis sie tatsächlich eintreffen. Angesichts unmittelbarer Bedrohungen für Thelsamar, den Damm und lokale Ausgrabungsstätten bleibt Bluntnose keine andere Wahl, als unabhängige Abenteurer zu bezahlen.",al={"warum söldner anheuern","thelsamar wachen","eisenschmiede hilfe"}},{q="Wo befinden sich die Oger der Mo'grosh?",a="Die Oger der Mo'grosh bewohnen die Festung Mo'grosh, die in den zerklüfteten Klippen und Hügeln nordöstlich des großen Sees von Loch Modan liegt.",al={"oger aufenthaltsort","wo sind mo'grosh","mo'grosh lager"}},{q="Warum gilt der Steinwerkdamm als gefährdet?",a="Der Steinwerkdamm reguliert den gesamten See und ist ein architektonisches Juwel der Zwerge. Da eine militärische Verteidigung praktisch nicht existiert und die Oger der Mo'grosh in der Nähe ein Lager aufgeschlagen haben, befürchtet Bluntnose, dass ein organisierter Überfall das gewaltige Bauwerk beschädigen oder sabotieren und katastrophale Überschwemmungen auslösen könnte.",al={"warum damm beschützen","oger und der damm"}},{q="Welchen anderen Bedrohungen sieht sich Thelsamar neben den Ogern gegenüber?",a="Troggs sind rund um den Loch aus unterirdischen Ruinen und Ausgrabungen hervorgebrochen. Bluntnose hält sie für eine gewaltige Bedrohung, doch die rohe Kraft der nahe gelegenen Ogerfestung zwingt ihn dazu, Kämpfer anzuheuern, um die Mo'grosh zurückzudrängen, damit sich die örtliche Wache auf die Trogg-Einfälle konzentrieren kann.",al={"weitere bedrohungen loch modan","trogg bedrohung"}}},fx={bfea2c9c={q="Warum will Magistrat Bluntnose, dass die Mo'grosh-Oger getötet werden?",a="Magistrat Bluntnose fürchtet um das Überleben von Thelsamar und der umliegenden Region. Die Mo'grosh-Oger haben ein starkes Lager nordöstlich des Sees errichtet, wodurch die Stadt, die örtliche Ausgrabungsstätte und der Steinwerkdamm anfällig für katastrophale Angriffe sind, während die Eisenschmiede die Entsendung von Verteidigungstruppen hinauszögert. Indem er die Oger zurückdrängt, hofft er, eine unmittelbare Bedrohung zu beseitigen und lokale Ressourcen frei zu machen, um mit den grassierenden Trogg-Invasionen fertig zu werden.",al={"motiv von magistrat bluntnose","warum mogrosh oger töten","bluntnose warum mercenaries"}},["5f9f9ec0"]={q="Wer sind die Mo'grosh-Oger, die Loch Modan bedrohen?",a="Die Mo'grosh sind ein brutaler Ogerclan, der in das nordöstliche Loch Modan eingedrungen ist und die rauen Hügel jenseits des Sees beansprucht. Ihre Vollstrecker und Bruten entfalten ihre gewaltige körperliche Stärke direkt neben verwundbarem Zwergenterritorium. Ihre wachsende Präsenz stellt eine unmittelbare physische Bedrohung für Reisende, den Steinwerkdamm und nahegelegene Zwergensiedlungen dar, wobei sie die überdehnten Verteidigungslinien der Region ausnutzen.",al={"wer sind die mogrosh","mogrosh oger loch modan","was sind die mogrosh oger"}}},fp="11,378,23.393.0,23.479.0,71.338.0,37.129.0,49.303.0,59.285.0"}
P.entries["quest:256"] = {n="GESUCHT: Chok'sul",s="Ein in Thelsamar von Magistrat Bluntnose ausgehängtes Kopfgeld fordert den Tod von Chok'sul, einem Oger-Kriegsherrn, der den Nordosten von Loch Modan bedroht. Da man annimmt, dass er die Angriffe auf die örtlichen Siedlungen und die entscheidende Infrastruktur koordiniert, winkt für das Beschaffen seines Kopfes eine stattliche Belohnung durch die Führung der Stadt.",h="Ein in Thelsamar von Magistrat Bluntnose ausgehängtes Kopfgeld fordert den Tod von Chok'sul, einem...",kw={"bluntnose","kopfgeld","chok'sul","choksul","loch modan","oger","der steinwerkdamm","thelsamar"},ang={["faction:Alliance"]="Loch Modan dient als primärer Landwirtschafts- und Versorgungskorridor nach Dun Morogh, weshalb Stabilität rund um Thelsamar für die militärischen Bemühungen der Allianz unerlässlich ist.",["profession:Engineering"]="Der Steinwerkdamm ist eine der größten bautechnischen Leistungen, die jemals von Zwergen errichtet wurden; zuzulassen, dass rohe Oger ihn beschädigen, ist für jeden ehrenwerten Handwerker undenkbar.",["race:Dwarf"]="Die Verteidigung des Steinwerkdamms und der umliegenden archäologischen Ausgrabungen berührt direkt den Stolz der Zwerge, ihr Erbe und die Sicherheit der Hoheitsgebiete von Eisenschmiede."},sec={{t="Eine Bedrohung für den Loch",b="Während Troggs und wilde Tiere unentwegt die Grenzen von Loch Modan auf die Probe stellen, stellt die Ankunft organisierter Oger eine Eskalation dar, die die einheimischen Zwergengebirgsjäger nicht ignorieren können. Diese Grobiane haben sich in Lagern in den zerklüfteten nordöstlichen Weiten des Tals niedergelassen und begnügen sich nicht mehr mit bloßer Plünderung. Den Berichten örtlicher Späher und der Stadtbehörden zufolge sind ihre Überfälle gezielt, hartnäckig und gefährlich."},{t="Der Preis auf Chok'suls Kopf",b="Magistrat Bluntnose aus Thelsamar hat Chok'sul als den Drahtzieher ausgemacht, der die Gewalt gegen die Stadt, die nahegelegene Zwergengrabungsstätte und den Steinwerkdamm selbst koordiniert. Aus Furcht vor verheerenden Schäden an der geschätzten Ingenieursleistung des Tals und am Leben der Zivilisten setzte der Magistrat ein Kopfgeld auf den Ogerhäuptling aus: tot durch jedes erforderliche Mittel, mit seinem abgetrennten Kopf als Beweis."}},faq={{q="Wer hat das Kopfgeld auf Chok'sul ausgesetzt?",a="Magistrat Bluntnose, der oberste Stadtbeamte von Thelsamar, erließ den Befehl im Namen der Stadt offiziell, um die Region vor organisierten Überfällen zu schützen.",al={"wer will choksuls tod","wer hat kopfgeld auf choksul ausgesetzt","thelsamar steckbrief"}},{q="Warum gilt Chok'sul als Ziel mit solch hoher Priorität?",a="Chok'sul gilt als der Koordinator, der die Ogerangriffe gegen Thelsamar, die archäologischen Ausgrabungen von Eisenschmiede und den Steinwerkdamm leitet – Ziele, die sowohl Zwergenleben als auch entscheidende Infrastruktur des Königreichs darstellen.",al={"warum choksul toeten","was hat choksul getan","choksul bedrohung"}},{q="Wo ist Chok'sul zu finden?",a="Er befindet sich im Ogerlager inmitten der zerklüfteten Hügel im nordöstlichen Winkel von Loch Modan.",al={"choksul aufenthaltsort","wo ist choksul","ogerlager loch modan"}},{q="Welchen Beweis verlangt Magistrat Bluntnose?",a="Ihr müsst Chok'suls abgetrennten Kopf direkt zu Magistrat Bluntnose in Thelsamar bringen, um das Kopfgeld und die Dankbarkeit von Eisenschmiede einzufordern.",al={"choksuls kopf","kopfgeld beweis","choksul abgeben"}},{q="Warum sollten Oger den Steinwerkdamm angreifen?",a="Der Steinwerkdamm staut den gewaltigen See von Loch Modan auf und ist ein Meisterwerk der Zwergenbaukunst. Seine Sabotage würde das Sumpfland überfluten und die zwergischen Nachschublinien verwüsten, was ihn zu einem erstklassigen taktischen Ziel für feindliche Truppen macht.",al={"warum den damm angreifen","stonewroughtdamm wird angegriffen"}},{q="Arbeiten noch andere Oger mit Chok'sul zusammen?",a="Ja, Chok'sul befehligt ein Ogerlager in den nordöstlichen Hügeln des Lochs und leitet deren Überfälle in den umliegenden Gebieten.",al={"choksul clan","loch modan oger","choksul anhaenger"}}},fx={["761222eb"]={q="Wer ist Chok'sul?",a="Chok'sul ist ein Ogerbrut, der das Kommando über das Ogerlager im nordöstlichen Loch Modan übernommen hat. Man hält ihn für den gerissenen Koordinator hinter den koordinierten Überfällen auf Thelsamar, den Steinwerkdamm und die örtliche Ausgrabungsstätte der Zwerge; er stellt die größte organisierte Bedrohung für die Sicherheit des Tals dar.",al={"wer ist choksul","ziel choksul","über choksul"}}},fp="16,301,20.404.0,28.402.0,34.154.0,55.232.0,28.110.0,45.134.0,44.240.0,44.154.0"}
P.entries["quest:2561"] = {n="Druide der Klaue",s="Tief in den Grabhügeln von Teldrassil bittet die spektrale Gestalt von Oben Zornklaue um eine tragische Erlösung. Verderbte Furbolgs haben seine physische Hülle mit einer dunklen Verzauberung belegt, was Euch dazu zwingt, seine seelenlose Hülle zu zerstören und das Band zu trennen, damit sein Geist in den Smaragdgrünen Traum zurückkehren kann.",h="Tief in den Grabhügeln von Teldrassil bittet die spektrale Gestalt von Oben Zornklaue um eine tragische...",kw={"ban'ethil","druide der klaue","smaragdgrüner traum","gnarlpine","oben zornklaue","teldrassil","der schlafende druide","voodooglücksbringer"},ang={["class:Druid"]="Einen schlummernden Druiden der Klaue von verderbten Furbolgs geschändet zu sehen, ist eine erschütternde Mahnung an die Gefahren, den eigenen physischen Körper unbeaufsichtigt zu lassen, während man mit dem Smaragdgrünen Traum Zwiesprache hält.",["race:NightElf"]="Teldrassil war als Zuflucht für die Nachtelfen gedacht, doch die rasche Verderbnis einheimischer Furbolgs wie der Gnarlpine stellt selbst in ihren heiligen Grabhügeln eine unmittelbare Bedrohung dar."},sec={{t="Ein getrennter Geist",b="Während er in den Grabhügeln unter Teldrassil ruhte, erlitt Oben Zornklaue ein schreckliches Schicksal. Die verderbten Furbolgs der Gnarlpine belegten seinen schlummernden Körper mit einer finsteren Voodooverzauberung und trennten seinen Geist von seinem sterblichen Fleisch. Im Smaragdgrünen Traum gefangen, verweilt Obens Geist ganz in der Nähe, unfähig zu ruhen oder seinen eigenen Körper wieder in Besitz zu nehmen."},{t="Gnade für das Fleisch",b="Die Untersuchung des Voodooglücksbringers der Gnarlpine enthüllte die finstere Wahrheit: Obens physische Hülle steht gänzlich unter der Herrschaft der Furbolgs. Um die Verzauberung zu brechen, muss ein Abenteurer die nahe Kammer betreten, die geistlose, feindselige Hülle von Oben Zornklaue niederstrecken und den Glücksbringer der Furbolgs über seinen sterblichen Überresten einsetzen, um die Magie, die seine Seele bindet, endgültig zu zerschlagen."}},faq={{q="Warum muss ich Oben Zornklaue töten?",a="Die Furbolgs der Gnarlpine belegten Oben im Schlaf mit einer mächtigen Voodooverzauberung und machten seinen physischen Körper zu einer seelenlosen Marionette. Da sein Fleisch gänzlich unter ihrer Knechtschaft steht, ist die Zerstörung der physischen Hülle der einzige Weg, die Verzauberung zu brechen und seinen verweilenden Geist zu befreien.",al={"warum oben töten","schlafenden druiden töten","oben zornklaue körper"}},{q="Wozu dient der Voodooglücksbringer?",a="Der Glücksbringer birgt den Schlüssel zu der Verzauberung, die Oben kontrolliert. Sobald Ihr seinen verderbten, seelenlosen Körper erschlagt, löst die Aktivierung des Glücksbringers über seinen gefallenen Überresten die dunkle Magie auf, die seinen Geist gefangen hält.",al={"voodooglücksbringer nutzung","voodooglücksbringer anwenden","gnarlpine glücksbringer oben"}},{q="Wohin geht Oben nach dieser Quest?",a="Sobald sein physischer Körper erschlagen und die Verzauberung gebrochen ist, wird der Geist von Oben Zornklaue aus der sterblichen Welt erlöst. Er kann endlich in den Smaragdgrünen Traum reisen, um in Frieden zu ruhen.",al={"oben schicksal","was geschieht mit oben zornklaue","überlebt oben"}},{q="Warum nutzen die Gnarlpine Voodoomagie?",a="Die Furbolgs der Gnarlpine sind tief in Verderbnis und Wahnsinn verfallen und haben sich von ihrer uralten Harmonie abgewandt, um sich finsterer Zauberei und roher dunkler Magie hinzugeben und die Kreaturen sowie schlafenden Druiden um sie herum zu unterjochen.",al={"furbolg voodoo","gnarlpine voodoomagie","warum haben furbolgs glücksbringer"}},{q="Wer war Oben Zornklaue?",a="Oben war ein Nachtelf und Druide der Klaue, der sich in den Grabhügeln von Teldrassil in einen heiligen Schlummer begab, um mit dem Smaragdgrünen Traum zu kommunizieren, bevor die Furbolgs der Gnarlpine seine Ruhe störten und seine sterbliche Hülle versklavten.",al={"wer ist oben","oben lore","oben zornklaue hintergrund"}},{q="Spricht Obens Geist noch mit mir, während sein Körper lebt?",a="Ja. Die dunkle Verzauberung trennte Obens Seele von seinem Fleisch. Sein Geist manifestierte sich als Gespenst nahe dem Kammereingang, völlig unfähig, die verzauberte, leere Hülle im Inneren zu kontrollieren oder wieder in sie einzukehren.",al={"oben geist und körper","zwei obens","warum ist oben an zwei orten"}}},fx={bff893ba={q="Wer ist das Ziel, gegen das ich im Grabhügel von Ban'ethil ausgesandt werde?",a="Ihr werdet ausgesandt, um den seelenlosen physischen Körper von Oben Zornklaue selbst zu vernichten. Während sein Geist außerhalb verweilt, ist seine schlafende sterbliche Hülle in den Bann eines mächtigen Zaubers der Gnarlpine-Furbolgs innerhalb des Grabhügels von Ban'ethil gefallen. Ohne seine Seele handelt die Hülle nun unter ihrer korrupten Herrschaft.",al={"wen töte ich","ziel oben","körperloser oben"}},["6e4ee394"]={q="Warum braucht Oben Zornklaue mich, anstatt dies selbst zu tun?",a="Oben ist derzeit ein ätherischer Geist, vollständig von seiner sterblichen Form getrennt. Als Erscheinung außerhalb der Grabkammer gefangen, fehlt ihm die physische Substanz, um sich seiner verzauberten Hülle entgegenzustellen oder den Voodooglücksbringer zu führen, der benötigt wird, um die Magie zu brechen. Tief im Inneren des Grabhügels, weit außerhalb der Reichweite der Nachtelfen-Wächterinnen, seid Ihr der Einzige, der eingreifen kann.",al={"warum braucht oben mich","warum kann oben seinen körper nicht töten","warum ich oben zornklaue"}}},fp="17,284,16.324.0,19.345.1,36.287.0,34.201.0,36.194.1,41.219.0,22.210.0,61.197.0"}
P.entries["quest:257"] = {n="Das Prahlen eines Jägers",s="A Hunter's Boast ist eine zeitlich begrenzte Jagdherausforderung, die von Daryl der Jüngling in der Weitschreiter-Lodge in Loch Modan ausgegeben wird. Begierig darauf, mit seiner vermeintlichen Meisterschaft anzugeben, fordert der arrogante junge Mensch Abenteurer dazu heraus, sechs Berggeier aufzuspüren und zu erlegen, bevor sein fünfzehnminütiges Zeitlimit abläuft.",h="A Hunter's Boast ist eine zeitlich begrenzte Jagdherausforderung, die von Daryl der Jüngling in der...",kw={"a hunter's boast","daryl der kühne","daryl der jüngling","die weitschreiter-lodge","jagdherausforderung","loch modan","berggeier","zeitlich begrenzte quest"},ang={["class:Hunter"]="Für Schützen und Fährtenleser ist Daryls Wettbewerb eine amüsante Gelegenheit, einen prahlenden Neuling auf seinem eigenen Terrain auszustechen und einen zuverlässigen Bogen oder ein Gewehr zu ergattern.",["faction:Alliance"]="Die Weitschreiter-Lodge dient als wichtiger Außenposten der Allianz entlang der südöstlichen Straßen von Loch Modan und bietet Schutz sowie einen Stützpunkt für Jagden durch die rauen Täler.",["race:Dwarf"]="Zwerge, die an die erfahrenen Jäger der Lodge gewöhnt sind, werden die Großtuerei dieses menschlichen Jünglings als leere Prahlerei erkennen, die man am besten mit ruhiger Kompetenz beantwortet."},sec={{t="Die Arroganz eines jungen Schützen",b="Die Weitschreiter-Lodge dient als Treffpunkt für einige der besten Fährtenleser und Schützen von Khaz Modan, doch nicht jeder unter ihrem Dach besitzt die Bescheidenheit eines Veteranen. Daryl der Jüngling – der sich selbst für 'Daryl den Kühnen' hält – tut umherziehende Abenteurer schnell ab. Davon überzeugt, dass grünschnäbelige Außenseiter seiner eigenen Jagdkunst nicht das Wasser reichen können, legt er eine großmäulige Wette ab: Erlegt ein halbes Dutzend örtlicher Berggeier innerhalb einer Viertelstunde oder gebt Euch geschlagen."},{t="Ausdünnung der Aasfresser",b="Berggeier kreisen über den Felsen und Hängen von Loch Modan, wo sie nach Abfällen suchen und kleinere Wildtiere erbeuten. Obwohl sie in Gruppen gefährlich sind, dienen sie primär als grundlegender Test für die Geschwindigkeit, Geduld und Zielgenauigkeit eines Jägers. Diejenigen, die die geforderte Beute innerhalb des strikten Zeitlimits erlegen, dämpfen Daryls übersteigerten Stolz schnell, zwingen ihn, widerwillig eine seiner Fernkampfwaffen herauszurücken, und bereiten den Boden für weitere Jagdherausforderungen."}},faq={{q="Wo findet diese Jagdherausforderung statt?",a="Die Quest beginnt in der Weitschreiter-Lodge, die in der südöstlichen Wildnis von Loch Modan liegt. Die Berggeier, die Ihr jagen müsst, durchstreifen die nahegelegenen Felsen und offenen Grate im gesamten Gebiet.",al={"ort der quest","wo ist daryl","wo sind die geier"}},{q="Wer ist Daryl der Jüngling?",a="Daryl der Jüngling ist ein ehrgeiziger, großmäuliger junger Mensch, der sich in der Weitschreiter-Lodge aufhält. Er nennt sich selbst 'Daryl der Kühne' und hat Freude daran, Reisende zu zeitlich begrenzten Jagdprüfungen herauszufordern, um seine eigene vermeintliche Überlegenheit unter Beweis zu stellen.",al={"wer ist daryl","daryl der kühne hintergrund","daryl weitschreiter-lodge"}},{q="Warum gibt es ein Zeitlimit für die Jagd?",a="Die fünfzehnminütige Begrenzung ist Teil von Daryls Wette. Er glaubt, dass das Erlegen wilder Geier unter Zeitdruck eine Leistung ist, die weit über das Können eines gewöhnlichen Abenteurers hinausgeht.",al={"warum 15 minuten","zeitlimit der quest","zeitprüfung"}},{q="Was passiert, nachdem man Daryls Herausforderung bestanden hat?",a="Obwohl er schockiert über Euren Erfolg ist, weigert sich Daryl, eine echte Niederlage zuzugeben. Er löst seine Wette ein, indem er eine Waffe anbietet, und bietet dann sofort eine weitere Jagdaufgabe an – A Hunter's Challenge –, bei der es um größeres Wild geht.",al={"was kommt als nächstes","folge von a hunter's boast","jäger-questreihe"}},{q="Warum werden speziell Berggeier gejagt?",a="Schwärme von Berggeiern nisten an den felsigen Hängen von Loch Modan. Sie dienen als agiles, fliegendes Ziel, das ideal ist, um zu testen, ob ein Bogenschütze oder ein Schütze über echte Disziplin im Feld verfügt.",al={"warum geier","zweck der geierjagd","geier in loch modan"}},{q="Ist diese Quest mit den restlichen Aufgaben der Weitschreiter-Lodge verknüpft?",a="Ja. Daryls Prüfungen führen direkt in eine breitere Sequenz von Jagden für die Lodge, die schließlich in der Verfolgung von 'Ol' Sooty' gipfeln – dem Bären, der Daryl vernarbt hat –, was Teil von Vyrin Swiftwinds Plan ist, es dem großmäuligen Jüngling heimzuzahlen.",al={"verbindung zu vyrin","geschichte der lodge","handlungsstrang der weitschreiter"}}},fx={["4c8cb4f1"]={q="Warum fordert Euch Daryl der Jüngling heraus, Geier zu jagen?",a="Daryl hält große Stücke auf seine eigenen Fähigkeiten und will angeben. Er nennt sich selbst 'Daryl der Kühne', blickt auf Reisende herab, die durch die Weitschreiter-Lodge ziehen, und erwartet, dass Ihr scheitert. Er setzt seine eigene Jagdwaffe auf eine knappe fünfzehnminütige Wette, nur um zu beweisen, dass ein Außenstehender seiner Meisterschaft nicht das Wasser reichen kann.",al={"warum will daryl das erledigt haben","motiv daryl","warum herausforderung daryl"}},["3b45bb0a"]={q="Warum jagt Daryl die Geier nicht selbst?",a="Daryl bittet nicht um Unterstützung und versucht auch nicht, die Geier zur Sicherheit zu dezimieren; er bietet eine prahlerische Sportwette an. Er hält die Aufgabe für unter seiner Würde und geht davon aus, dass ein unerprobter Abenteurer nicht sechs Vögel innerhalb von fünfzehn Minuten erlegen kann, was es ihm erlaubt zu prahlen, wenn Ihr zwangsläufig scheitert.",al={"warum ich daryl","warum jagt daryl keine geier","warum fragt daryl mich"}}},fp="16,272,28.463.0,23.445.0,45.183.0,27.214.0,38.168.0,45.202.1,40.182.0,62.222.1"}
P.entries["quest:258"] = {n="Die Herausforderung eines Jägers",s="Die Herausforderung eines Jägers ist eine zeitlich begrenzte Jagdprüfung, die von dem dreisten Menschen Daryl der Jüngling in der Weitschreiter-Lodge im südöstlichen Loch Modan ausgegeben wird. Verärgert über seine eigene Unfähigkeit, Euren vorherigen Erfolg herabzuwürdigen, wettet Daryl sein letztes Hemd, dass Ihr nicht innerhalb von zwölf Minuten fünf uralte Gebirgseber aufspüren und erlegen könnt. Die Aufgabe stellt die Schnelligkeit eines Abenteurers gegen das zerklüftete Terrain und die gefährliche Tierwelt des Hochlands auf die Probe.",h="Die Herausforderung eines Jägers ist eine zeitlich begrenzte Jagdprüfung, die von dem dreisten Menschen Daryl...",kw={"eber","coldridge","daryl","uralter gebirgseber","die weitschreiter-lodge","jagd","loch modan","jüngling"},ang={["class:Hunter"]="Für Fährtenleser bietet das Aufspüren von fünf uralten Gebirgsebern im Hochlanddickicht innerhalb eines strengen Zeitfensters eine klassische Prüfung im Beutemanagement und schnellen Erlegen.",["faction:Alliance"]="Die Weitschreiter-Lodge dient den Waldläufern der Allianz als unverzichtbarer Stützpunkt, um die Ostgrenze von Loch Modan vor wilden Bestien und Gefahren des Hochlands zu schützen.",["race:Dwarf"]="Jeder Zwerg, der seine Anfänge im Coldridgetal erlebte, wird Daryls Vergleich sofort wiedererkennen, auch wenn seine herablassende Art schwerer zu ertragen ist."},sec={{t="Die Prahlerei eines Jünglings",b="Daryl der Jüngling weilt unter den erfahrenen Jägern der Weitschreiter-Lodge, doch besitzt er nichts von ihrer ruhigen Geduld. Stattdessen kompensiert Daryl seine mangelnde Lebenserfahrung mit Großmäuligkeit und übertriebenen Jagdgeschichten, darunter ausschweifendes Seemannsgarn darüber, wie er sich seine „berühmte“ Narbe zugezogen hat. Nicht gewillt, das Können anderer anzuerkennen, verhunzt er fortwährend die Namen seiner Mitjäger und denkt sich strenge Prüfungen aus, die Neulinge demütigen und sein eigenes aufgeblasenes Ansehen unter den Bewohnern der Lodge wiederherstellen sollen."},{t="Die Hochlandjagd",b="Anders als die einfacheren Eber im Coldridgetal, wo angehende Zwergenspäher ihr Handwerk erlernen, sind die uralten Gebirgseber, die durch die Felsen und Hänge von Loch Modan streifen, massiv, dickhäutig und bei Provokation gefährlich. Daryl lässt Jägern gerade einmal zwölf Minuten Zeit, um fünf solcher Bestien aufzuspüren, zur Strecke zu bringen und ihren Tod zu bestätigen. Schließt man die Jagd schnell genug ab, zwingt dies den großmäuligen Burschen zu einem peinlichen Rückzug, bei dem er vorgibt, nichts von der maßlosen Wette zu wissen, die er so leichtfertig eingegangen ist."}},faq={{q="Wer ist Daryl der Jüngling?",a="Daryl ist ein junger, prahlerischer menschlicher Jäger, der in der Weitschreiter-Lodge im südöstlichen Loch Modan lebt. Verzweifelt darum bemüht, genauso furchteinflößend zu wirken wie die älteren Veteranen um ihn herum, prahlt er unablässig mit seinem eigenen Können, erfindet hochtrabende Geschichten und fordert vorbeikommende Abenteurer zu schwierigen Jagdprüfungen heraus.",al={"wer ist daryl","daryl der jüngling geschichte","weitschreiter lodge daryl"}},{q="Wo sind die uralten Gebirgseber zu finden?",a="Uralte Gebirgseber streifen durch die Ausläufer, Wiesen und Bergrücken rund um die Weitschreiter-Lodge sowie die südlichen und östlichen Weiten von Loch Modan. Man findet sie beim Grasen im gesamten hügeligen Hochland zwischen der Lodge und dem zentralen See.",al={"uralter gebirgseber fundort","wo man eber findet","eber jagdgebiet"}},{q="Warum ist diese Jagd zeitlich begrenzt?",a="Daryl begrenzt die Jagd auf zwölf Minuten, weil er fest mit Eurem Scheitern rechnet. Durch das enge Zeitlimit hofft er, Euch bloßzustellen und zu beweisen, dass Eure früheren Jagderfolge nichts weiter als Anfängerglück waren.",al={"warum zwölf minuten","warum zeitbegrenzt","jäger herausforderung timer"}},{q="Welche Wette ging Daryl ein?",a="Während er die Prüfung erklärte, verkündete Daryl vollmundig, er würde Euch sein letztes Hemd geben, falls es Euch gelänge, die fünf uralten Gebirgseber rechtzeitig zu erlegen. Nach Eurer triumphalen Rückkehr tut er natürlich rasch so, als könne er sich an keinerlei derartige Wette erinnern.",al={"daryls wette","sein letztes hemd","was hat daryl gewettet"}},{q="Wie ist der Vergleich zu den Ebern aus dem Coldridgetal?",a="Daryl weist ausdrücklich darauf hin, dass diese uralten Gebirgseber weitaus zäher und aggressiver sind als die kleinen, zahmen Eber, die Zwergenneulinge im Coldridgetal jagen. Die ausgewachsenen Eber von Loch Modan verfügen über dickere Felle und gefährliche Hauer, die am Granit des Hochlands gewetzt wurden.",al={"coldridge eber gegen gebirgseber","coldridge vergleich"}},{q="Wohin führt diese Jagdreihe als Nächstes?",a="Sobald Ihr Daryls Prahlerei durch den Abschluss seiner Herausforderung zum Schweigen gebracht habt, wendet sich die Aufmerksamkeit in der Lodge ernsteren Angelegenheiten zu, was in der Quest Vyrins Rache zu einer Konfrontation mit dem gefährlichen alten Bären Rußbart führt.",al={"welche quest kommt danach","nach die herausforderung eines jägers","jagd questreihe"}}},fx={["4ae04a68"]={q="Was sind die Älteren Gebirgseber?",a="Ältere Gebirgseber sind kampferprobte, zähe Bestien, die in den Felsen und Hügeln um Loch Modan heimisch sind. Im Gegensatz zu den kleineren Ebern, die an Orten wie dem Coldridgetal umherstreifen, sind diese Kreaturen weitaus widerstandsfähiger und gefährlicher, wenn man sie in die Enge treibt. Daryl wählt sie gezielt aus, um Eure Spür- und Kampffertigkeiten bis an ihre Grenzen zu testen, in der Erwartung, dass Ihr unter dem knappen Zeitlimit scheitert.",al={"ältere gebirgseber loch modan","warum ältere eber","wer sind die eber"}},["33153764"]={q="Warum schickt Daryl Euch auf diese Jagd, anstatt selbst zu jagen?",a="Daryl der Jüngling zieht es vor, in der Weitschreiter-Lodge Hof zu halten und großspurige Geschichten darüber zu erzählen, wie er zu seiner berühmten Narbe kam, anstatt durch die Wildnis zu stapfen. Überzeugt von seinem eigenen überlegenen Können, stellt er diese eskalierenden Prüfungen nur auf, um Euch zu demütigen und sein selbst ernanntes Ansehen unter den Jägern zu wahren.",al={"warum jagt daryl nicht","warum braucht daryl mich"}}},fp="20,428,15.498.0,17.493.0,27.290.0,43.243.0,23.224.0,24.262.0,48.260.0,40.220.1"}
P.entries["quest:26"] = {n="Eine wertvolle Lektion",s="Eine wertvolle Lektion ist ein Übergangsritus für junge Taurendruiden, die bereit sind, die Beherrschung des Wassers zu erlangen. Auf den Höhen von Donnerfels von Turak Runentotem vergeben, weist die Quest Schüler an, nach Nachthafen in Mondlichtung zu reisen, um ihre Prüfungen unter der Anleitung des Zirkels des Cenarius zu beginnen.",h="Eine wertvolle Lektion ist ein Übergangsritus für junge Taurendruiden, die bereit sind, die Beherrschung des...",kw={"wassergestalt","zirkel des cenarius","dendrite sternenschauer","die anhöhe der ältesten","eine wertvolle lektion","mondlichtung","nachthafen","donnerfels","turak runentotem"},ang={["class:Druid"]="Dieser Ritus markiert den Übergang vom irdischen Überleben zur wahren elementaren Vielseitigkeit und öffnet den Pfad zur Meisterschaft über das Atmen und Bewegen unter Wasser.",["faction:Horde"]="Obwohl sie der Horde die Treue halten, müssen Taurendruiden die heilige Neutralität von Mondlichtung achten und Seite an Seite mit Nachtelfen unter dem gemeinsamen Blätterdach von Cenarius wandeln.",["race:Tauren"]="Die Quest verkörpert das starke Band zwischen den Taurendruiden von Donnerfels und der weiteren Bruderschaft des Cenarius mit Sitz in Mondlichtung."},sec={{t="Meisterschaft der Tiefen",b="Nachdem sie durch den Bären die rohe physische Macht erlangt haben, wendet sich das Studium eines Druiden der Anpassungsfähigkeit zu. Die Wasserwege von Azeroth stellen landgebundene Reisende vor gefährliche Tücken und verlangen nach einem Aspekt, der für kalte Tiefen und erdrückende Strömungen geschaffen ist. Turak Runentotem beobachtet seine Schüler aufmerksam und wählt nur jene aus, die ihre Hingabe an die Natur bewiesen haben, ehe er sie nach Norden schickt, um die Wassergestalt zu erlernen."},{t="Der Weg nach Nachthafen",b="Da der aquatische Gestaltwandel tiefe spirituelle Einsicht erfordert, müssen Initianden Führung jenseits der Klippen von Mulgore suchen. Turak heißt seine Schüler nach Mondlichtung reisen, der heiligen Zuflucht am Fuße des Hyjal. Dort, im friedlichen Zufluchtsort Nachthafen, heißen uralte Nachtelfen-Mentoren des Zirkels des Cenarius ihre Tauren-Brüder und -Schwestern willkommen und überwinden Fraktionszwistigkeiten, um die gemeinsamen Lehren von Cenarius zu bewahren."},{t="Die beiden Prüfungen",b="Das Erreichen von Dendrite Sternenschauer in Nachthafen markiert erst den Anfang. Der Nachtelfen-Älteste mahnt, dass die Meisterschaft über das Wasser nicht einfach geschenkt werden kann – man muss sie sich durch Prüfungen verdienen. Er warnt die Anwärter vor zwei zermürbenden Tests, die sie erwarten: einer, der Ausdauer und Fassung bei der Arbeit unter wässrigem Druck fordert, und ein weiterer, der ein tiefes spirituelles Verständnis des aquatischen Aspekts selbst verlangt."}},faq={{q="Wer vergibt die Quest Eine wertvolle Lektion?",a="Die Quest wird von Turak Runentotem vergeben, dem Druidenlehrer, der auf der Anhöhe der Ältesten in Donnerfels weilt. Sobald ein Initiand genügend Erfahrung gesammelt hat, schickt er ihn aus, um sich fortgeschrittenem Unterricht zu widmen.",al={"wer startet eine wertvolle lektion","wo bekomme ich eine wertvolle lektion","turak runentotem quest"}},{q="Wohin muss ich gehen, um diese Quest abzuschließen?",a="Ihr müsst in das Dorf Nachthafen reisen, das in den heiligen Wäldern von Mondlichtung eingebettet liegt, und mit Dendrite Sternenschauer vom Zirkel des Cenarius sprechen.",al={"wo gebe ich eine wertvolle lektion ab","dendrite sternenschauer standort","wo ist nachthafen"}},{q="Zu welcher Fähigkeit führt diese Questreihe?",a="Diese Quest ist der erste Schritt in der Questreihe, die Druiden mit der Wassergestalt belohnt, was schnelles Schwimmen unter Wasser sowie unbegrenztes Atmen unter der Oberfläche gewährt.",al={"welche gestalt gibt das","wassergestalt quest","warum diese quest machen"}},{q="Warum begeben sich Taurendruiden für ihre Ausbildung zu einem Nachtelfen?",a="Der Zirkel des Cenarius fungiert als neutrale Bruderschaft, die Cenarius und der Bewahrung der Natur geweiht ist. In Mondlichtung werden die politischen Spannungen zwischen Horde und Allianz beiseitegelegt, damit Nachtelfen und Tauren die heiligen Künste gemeinsam erlernen können.",al={"warum mondlichtung","warum dendrite sternenschauer","zirkel des cenarius tauren"}},{q="Von welchen Prüfungen spricht Dendrite Sternenschauer?",a="Dendrite erklärt, dass Ihr Euch zwei besonderen Herausforderungen stellen müsst: einer, die Eure körperliche Fassung bei der Arbeit unter Druck im Wasser auf die Probe stellt, und einer weiteren, die Eure spirituelle Entschlossenheit fordert, um den Aspekt selbst zu begreifen.",al={"was sind die zwei prüfungen","dendrite prüfungen","aquatische prüfungen"}},{q="Wie gelangt ein Druide zu diesem Zeitpunkt nach Mondlichtung?",a="Druiden besitzen ein angeborenes spirituelles Band, das ihnen den Zauber Teleportieren: Mondlichtung verleiht, mit dem sie von überall in Azeroth direkt in das friedvolle Dorf Nachthafen wechseln können.",al={"wie man nach mondlichtung kommt","teleport nach mondlichtung","nach nachthafen gelangen"}}},fx={b1c6f6a1={q="Warum schickt mich Turak Runetotem in die Mondlichtung?",a="Turak Runetotem hat Euer Wachstum als Beschützer der Natur beobachtet und glaubt, dass Ihr bereit seid, auf Eurem druidischen Pfad voranzuschreiten. Er schickt Euch in die Mondlichtung, damit Ihr mit dem Zirkel des Cenarius in Verbindung treten und den von Cenarius gewährten Tieraspekt erlernen könnt, der die Meisterschaft über das Wasser gebietet.",al={"warum schickt mich turak","motiv turak runetotem","warum eine lektion lernen"}},["055244fc"]={q="Warum muss ich dieses Training selbst absolvieren?",a="Gestaltwandel ist kein Mantel, der verliehen oder von jemand anderem getragen werden kann. Jeder Druide muss seinen eigenen Geist und seine physische Ausdauer direkt vor dem Zirkel des Cenarius unter Beweis stellen, um sich auf den Segen von Cenarius einzustimmen und den Wasseraspekt zu verdienen.",al={"warum muss ich die prüfungen ablegen","warum schickt ihr mich in die mondlichtung","warum ich eine lektion lernen"}}},fp="17,281,21.406.0,22.424.0,15.395.0,38.190.0,39.150.0,43.182.0,52.251.0,45.220.0,47.177.0"}
P.entries["quest:262"] = {n="Die Schattengestalt",s="Heimgesucht vom Massaker an seiner Familie beauftragt Euch der Einsiedler Sven Yorgen damit, die Identität eines mysteriösen Fremden aufzudecken, der in jener verhängnisvollen Nacht in der Nähe seines Hofes lauernd gesehen wurde. Nur mit einem rätselhaften Buch bewaffnet, das aus den Ruinen geborgen wurde, müsst Ihr die Bewohner von Dunkelhain befragen, um den Spuren des Fremden zu folgen.",h="Heimgesucht vom Massaker an seiner Familie beauftragt Euch der Einsiedler Sven Yorgen damit, die Identität...",kw={"buch","dunkelhain","dämmerwald","madame eva","schattengestalt","sven yorgen","svens lager"},ang={["class:Priest"]="Die Untersuchung von Madame Evas Wahrsagung verdeutlicht den schmalen Grat zwischen spirituellem Hellsehen, Schattenmagie und ungesehenen psychischen Eindrücken, die an alltäglichen Gegenständen haften.",["faction:Alliance"]="Dunkelhains Mangel an Unterstützung durch Sturmwind zwingt seine traumatisierten Grenzgänger und örtlichen Seher dazu, sich vollkommen auf umherziehende Champions der Allianz zu verlassen, um tödliche Gräueltaten im Dämmerwald zu untersuchen."},sec={{t="Echos eines Gemetzels",b="Sven Yorgen lebt versteckt in den trostlosen Hügeln des Dämmerwalds, gebrochen durch das schreckliche Abschlachten seiner Familie und Arbeiter. Obwohl er die Schuld ursprünglich den geheimnisvollen schwarzen Reitern gab, die die Wälder terrorisieren, quält seine Erinnerung ein weiteres Detail: eine ruhige, schattenhafte Gestalt, die in der Nacht des Massakers in der Nähe lauerte. Verzweifelt auf der Suche nach Antworten vertraut Sven Euch den einzigen physischen Hinweis an, der aus den Trümmern geborgen wurde – ein seltsames Buch, das auf dem verwüsteten Hof zurückgelassen wurde."},{t="Wahrsagung in der Stadt",b="Ohne direkte Spuren, denen man in der gefährlichen Wildnis folgen könnte, weist der Pfad zurück nach Osten in Richtung Dunkelhain. Sven hofft, dass jemand unter den abergläubischen Einheimischen den merkwürdigen Band wiedererkennen könnte. Dunkelhain birgt seinen Teil an Kuriositäten und Medien, allen voran Madame Eva, deren okkulte Sinne und Weissagungen es ihr ermöglichen, über das gewöhnliche, weltliche Sehen hinauszublicken und die spirituellen Eindrücke zu deuten, die an geheimnisvollen Relikten haften."},{t="Fremde Fäden",b="Madame Eva das Buch zu präsentieren, offenbart schwache, aber unverkennbare psychische Eindrücke. Während Svens eigenes brennendes Verlangen nach Rache die Seiten erst kürzlich gezeichnet hat, gehört die darunterliegende Aura jemand völlig anderem. Eva erkennt, dass der ursprüngliche Besitzer keineswegs ein Bewohner von Dunkelhain oder dem Dämmerwald war, was bestätigt, dass ein Fremder den Hof betrat, bevor das Blutvergießen begann."}},faq={{q="Wer ist Sven Yorgen?",a="Sven Yorgen ist ein am Boden zerstörter Bauer, der in die westlichen Hügel des Dämmerwalds ins Exil getrieben wurde. Nachdem dunkle Reiter sein Gehöft angriffen und seine gesamte Familie abschlachteten, floh er in die Wildnis – zerfressen von Trauer, Furcht und einem verzweifelten Verlangen nach Rache an den Verantwortlichen.",al={"wer ist sven","sven hintergrundgeschichte","sven yorgen"}},{q="Was ist das Buch, das auf Svens Hof gefunden wurde?",a="Das Buch ist ein physisches Artefakt, das aus dem Schmutz und den Trümmern von Svens zerstörtem Gehöft geborgen wurde. Es gehörte einem schwer fassbaren Beobachter, der während des Angriffs auf seine Familie lauernd in den Schatten gesehen wurde.",al={"welches buch ist das","buch von svens hof","geheimnisvolles buch"}},{q="Warum bringt man das Buch zu Madame Eva?",a="Madame Eva ist Dunkelhains ansässige Seherin und Wahrsagerin. Gewöhnliche Stadtbewohner können einem unbeschrifteten Band nicht viel entnehmen, doch Eva nutzt ihre hellseherischen Kräfte, um verbleibende psychische Eindrücke zu lesen, die von demjenigen hinterlassen wurden, der den Gegenstand zuvor besaß oder trug.",al={"warum madame eva","wer liest das buch","dunkelhain mystiker"}},{q="Was erfährt Madame Eva aus dem Buch?",a="Madame Eva spürt den mächtigen emotionalen Abdruck der Rache, der von Svens jüngster Handhabung hinterlassen wurde. Darunter entdeckt sie jedoch schwache Spuren, die darauf hindeuten, dass der ursprüngliche Besitzer ein Außenstehender war, der nicht aus Dunkelhain stammte.",al={"was sagt eva","identität des buchbesitzers","wahrsagung ergebnis"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Die Erkenntnis, dass der Besitzer ein Fremder war, veranlasst Madame Eva dazu, Euch auf die Suche durch andere Aufzeichnungen und örtliche Stätten in Dunkelhain zu schicken – nach jedem, der sich an einen unbekannten Reisenden erinnern könnte, auf den die Beschreibung der Gestalt passt.",al={"wie geht es weiter","folgequest nach dem buch","wer ist die schattengestalt"}}},fx={d371091b={q="Warum will Sven Yorgen, dass dies erledigt wird?",a="Sven ist von Trauer und einem verzweifelten Bedürfnis nach Antworten verzehrt. In der Nacht, als seine Familie auf seinem Hof abgeschlachtet wurde, sah er eine geheimnisvolle Gestalt im Schatten lauern. Er glaubt, dass die Identität dieses Schleichers zu entdecken seine einzige Chance ist, die Wahrheit hinter dem Massaker zu erfahren und Gerechtigkeit zu sehen.",al={"warum will sven, dass die schattenhafte gestalt gefunden wird","motiv sven yorgen","warum besitzer des buches finden"}},["35559963"]={q="Warum bittet Sven Yorgen Euch und nicht die The Night Watch?",a="Sven ist ein isolierter, traumatisierter Einsiedler, der sich in der Wildnis von Dämmerwald versteckt, weit weg von Dunkelhain. Ihr habt Eure Findigkeit bereits bewiesen, indem Ihr das zerstörte Tagebuch auf seinem verwüsteten Gehöft entdeckt habt, was ihn davon überzeugt hat, dass Ihr den nötigen Schneid und die nötige Gerissenheit besitzt, um das Geheimnis zu lüften, wenn es sonst niemand tut.",al={"warum fragt sven nicht die the night watch","warum braucht sven meine hilfe","warum ich sven yorgen"}}},fp="18,315,21.485.0,26.421.0,15.376.1,19.278.0,38.201.0,32.250.0,41.221.1,40.222.1"}
P.entries["quest:263"] = {n="Verteidigung der Länder des Königs",s="Diese Mission steht für den eskalierenden Kampf, den die Gebirgsjäger von Eisenschmiede gegen die Troggplage im südlichen Loch Modan führen. Vom südlichen Wachturm aus schickt Gebirgsjäger Wallbang kampferprobte Rekruten in das Splittersteintal, um gefährliche Troggschamanen und an vorderster Front kämpfende Knochenknacker auszudünnen. Der Abschluss dieser Prüfung sichert Euch Wallbangs volles Vertrauen und gewährt Euch eine Audienz beim kommandierenden Captain der Garnison.",h="Diese Mission steht für den eskalierenden Kampf, den die Gebirgsjäger von Eisenschmiede gegen die Troggplage...",kw={"knochenknacker","eisenschmiede","loch modan","magni","gebirgsjäger","schamane","splitterstein","trogg","wallbang"},ang={["class:Shaman"]="Sich den primitiven Zauberwirkern der Splitterstein-Troggs zu stellen, bietet einen ungeschliffenen, wilden Einblick in eine Erdmagie, die von wilden Instinkten verzerrt wurde.",["faction:Alliance"]="Die Unterstützung des südlichen Wachturms sichert lebenswichtige Handels- und Reiserouten, die Dun Morogh mit den östlichen Feuchtgebieten und dem Königreich Sturmwind verbinden.",["race:Dwarf"]="Wallbangs Ruf zu folgen, ist für jeden Zwerg eine Frage der Heimatverteidigung: Ihr tretet ein, um die Gehöfte von Loch Modan zu schützen, während die stehenden Heere Eures Volkes in die Ferne abberufen sind."},sec={{t="Eine dünne zwergische Verteidigungslinie",b="Die Verteidigung von Loch Modan stößt an ihre Grenzen. Da die regulären zwergischen Reserven an ferne Fronten in ganz Azeroth beordert wurden, sind lokale Vorposten wie der südliche Wachturm unterbesetzt. Gebirgsjäger Wallbang und seine wenigen Kameraden sehen sich unerbittlichem Druck durch den Splittersteinclan ausgesetzt, weshalb sie stark auf durchreisende Allianzvölker angewiesen sind, um den südlichen Pass zu halten."},{t="Gegen die Vorhut der Splittersteine",b="Statt nur vereinzelte Späher abzufangen, zielt dieser Feldzug tiefer in die Hierarchie der Splittersteine. Die Knochenknacker der Troggs verleihen dem Clan rohe Muskelkraft, während ihre primitiven Schamanen Erdmagie wirken, um ihre Sippe aufzuwiegeln. Die Ausschaltung von zwanzig dieser vorrangigen Ziele bremst ihre Vorstöße in das Tiefland und dient unmittelbar König Magni Bronzebarts Verteidigung des Reiches."}},faq={{q="Wer ist Gebirgsjäger Wallbang?",a="Gebirgsjäger Wallbang ist ein Zwerg aus Eisenschmiede, der am südlichen Wachturm in Loch Modan stationiert ist. Seine Aufgabe besteht darin, die über die Berge schwappenden Aktivitäten der Troggs zu überwachen und Milizeinsätze zu koordinieren, um die südliche Hauptstraße zu sichern.",al={"wallbang","wer ist wallbang","gebirgsjäger wallbang hintergrund"}},{q="Warum bitten die Gebirgsjäger Reisende um Hilfe?",a="Die militärischen Reserven von Eisenschmiede wurden an kriegswichtigere Fronten im gesamten Königreich und darüber hinaus abgezogen. Diese Verlegung führt dazu, dass Grenzausposten wie die südlichen Wachtürme von Loch Modan gegen lokale Bedrohungen kritisch unterbesetzt sind.",al={"warum zwerge hilfe brauchen","wo sind die wachen von eisenschmiede","warum keine reserven"}},{q="Wo befinden sich diese Troggs?",a="Sie sammeln sich vor allem im Splittersteintal, das in den schroffen Hügeln südwestlich vom Loch liegt. Kleinere Gruppen dieser Schamanen und Knochenknacker suchen auch die nördlichen Inseln draußen auf dem See heim.",al={"wo sind splitterstein-troggs","splittersteinschamanen aufenthaltsort","wo ist das splittersteintal"}},{q="Was macht den Splittersteinclan zu einer Bedrohung?",a="Troggs vermehren sich rasch und überrennen besiedeltes Gebiet durch schiere unterirdische Schwärme. Der Splittersteinclan setzt durch seine Schamanen rohe Elementarmagie ein und verlässt sich auf wilde Knochenknacker, die zwergische Späher zerfleischen, was nahegelegene Siedlungen und Handelswege gefährdet.",al={"warum sind troggs gefährlich","bedrohung durch die splittersteine"}},{q="Was tut Gebirgsjäger Wallbang nach dieser Aufgabe?",a="Zufrieden darüber, dass Ihr Euch als Kämpfer im Dienste von König Magni bewiesen habt, weist Wallbang Euch an, Euch bei Hauptmann Rugelfuß für strategischere Befehle zur Verteidigung von Loch Modan zu melden.",al={"wie geht es nach wallbang weiter","wer ist der captain"}},{q="Wer herrscht während dieser Krise über Eisenschmiede?",a="König Magni Bronzebart regiert das zwergische Königreich von der Großen Schmiede in Eisenschmiede aus. Jede Anstrengung zum Schutz von Loch Modan wird in seinem Namen und zur Verteidigung seiner Hoheitsgebiete unternommen.",al={"wer ist der zwergenkönig","könig von eisenschmiede"}}},fx={["20cd043f"]={q="Warum will Gebirgsjäger Wallbang, dass diese Troggs getötet werden?",a="Das Trogg-Problem in ganz Loch Modan verschlimmert sich weiter und bedroht die Sicherheit des Hoheitsgebiets der Eisenschmiede. Da die Reserven der Gebirgsjäger an weit entfernte Fronten abgezogen wurden, sitzen Wallbang und seine Kameraden am südlichen Wachturm ohne Verstärkung fest. Er muss die Trogg-Reihen ausdünnen, um das Tal zu schützen und die Stellung im Namen des Königs zu halten.",al={"warum steinbeißer troggs töten","motiv wallbang","warum will wallbang troggs tot sehen"}},c0ccff20={q="Wer sind die Steinbeißer-Schamanen und Knochenbrecher?",a="Sie sind die spezialisierten Vorhut des Steinbeißer-Troggclans, die in Loch Modan eindringen. Die Knochenbrecher dienen als brutale, schwer zuschlagende Vollstrecker des Clans, während ihre Schamanen rohe, urtümliche Magie kanalisieren. Gemeinsam bilden sie die Kernstärke, die die Troggs aus den Tiefen und in die Zwergenlande treibt.",al={"steinbeißer schamane","steinbeißer knochenbrecher","wer sind die trogg ziele"}}},fp="30,419,19.376.0,36.389.0,28.237.0,51.240.0,31.205.0,43.280.0,50.173.0,39.188.0"}
P.entries["quest:264"] = {n="Bis dass der Tod uns scheidet",s="Bis dass der Tod uns scheidet ist eine bittere, persönliche Quest, die zum Grabmal im Silberwald führt. Clarice Foster, eine Verlassene, die in den Teichen der Visionen unter Donnerfels weilt, schickt Abenteurer aus, um ihren Erinnerungsanhänger auf das Grab ihres verstorbenen Mannes Yuriv zu werfen. Die Aufgabe offenbart die schmerzhaften menschlichen Brüche, die durch Fanatismus und Krieg entstanden, als die Seuche Lordaeron heimsuchte.",h="Bis dass der Tod uns scheidet ist eine bittere, persönliche Quest, die zum Grabmal im Silberwald führt.",kw={"clarice foster","kreuzzug","verlassene","anhänger","das grabmal","silberwald","grabstätte","yuriv"},ang={["class:Priest"]="Die Quest zeichnet ein düsteres Bild des Glaubens und unterstreicht, wie Hingabe an das Licht Familien entzweien und bei den Zurückgebliebenen dauerhafte Bitterkeit säen kann.",["faction:Horde"]="Clarice beizustehen gewährt den Champions der Horde einen Einblick in die persönlichen Tragödien und die anhaltende Bosheit, die die Verlassenen im Silberwald zusammenschweißen.",["race:Undead"]="Für die Verlassenen verkörpert Clarice' Schicksal die Scheinheiligkeit der Lebenden: Heilige Krieger überließen ihre Familien im heiligen Eifer dem Verderben und ließen ihre verwandelten Hinterbliebenen die Bürde der Erinnerung tragen."},sec={{t="Ein bitteres Andenken",b="Clarice Foster hegt keinerlei Zuneigung für die Erinnerungen an ihre sterbliche Ehe. Während Lordaeron zerbrach, verließ ihr Ehemann Yuriv sie und die gemeinsamen Kinder, um in einen Kreuzzug gegen die aufkeimende Bedrohung der Untoten zu ziehen, wobei er erklärte, dass der Dienst am Heiligen Licht an erster Stelle stehe. Letztlich rettete seine Hingabe weder seine Familie noch ihn selbst. Nun als Untote auferstanden, während Yuriv unter einem geschändeten Stein verwest, möchte Clarice lediglich die letzte greifbare Erinnerung an seine gebrochenen Versprechen abwerfen."},{t="Das vernachlässigte Grab",b="Yurivs Grabstätte ruht auf dem Friedhof, der das Grabmal umgibt, gezeichnet von Schrunden, übersät mit Müll und von Unkraut überwuchert. Das Ablegen von Clarice' Anhänger auf dem gemeißelten Relief seiner Hände bringt keine erhabene Magie oder spirituellen Frieden, sondern lediglich das Erblassen des Edelsteins und einen kalten, stummen Windstoß über den Gräbern. Es dient als finsteres Zeugnis für den fortwährenden Groll des gefallenen Volkes von Lordaeron."}},faq={{q="Wer war Yuriv?",a="Yuriv war der sterbliche Ehemann von Clarice Foster. Zu Lebzeiten ließ er sie und ihre Kinder zurück, um im Namen des Heiligen Lichts gegen die Geißel zu kämpfen, und stellte seinen Kreuzzug über seine Familie.",al={"wer ist yuriv","yuriv geschichte","clarice ehemann"}},{q="Warum hasst Clarice ihren verstorbenen Ehemann so sehr?",a="Clarice verbrachte Nacht für Nacht damit, auf Yuriv zu warten, während er seine religiösen Pflichten an erste Stelle setzte. Am Ende konnte sein Kreuzzug sie nicht beschützen; er starb in einem vernachlässigten Grab, während sie dazu verdammt war, als genau das untote Monster aufzuerstehen, das er bekämpfte.",al={"warum ist clarice wütend","clarice foster hintergrundgeschichte"}},{q="Was geschieht, wenn man den Anhänger zurückbringt?",a="Wird der Anhänger auf die steinernen Hände von Yurivs gemeißeltem Relief gelegt, verblasst der Edelstein des Schmuckstücks merklich. Eine steife, kühle Brise fegt über das Grabmal und hinterlässt die geschändete Grabstätte in kalter, stiller Verlassenheit.",al={"anhänger auf grab","ende von bis dass der tod uns scheidet"}},{q="Wo befindet sich Yurivs Grab?",a="Yurivs Grabstein befindet sich auf dem Friedhofsgelände des Grabmals, der Bastion der Verlassenen im nördlichen Silberwald.",al={"wo ist yurivs grab","yuriv grab ort"}},{q="Warum ist Yurivs Grab so beschädigt?",a="Das Grab wurde zerschrammt, mit Müll übersät und von Unkraut überwuchert. Die Verlassenen, die im Grabmal leben, empfinden weder Mitgefühl noch Ehrfurcht für einen Kreuzfahrer, der im Kampf gegen ihre Art starb.",al={"warum ist das grab geschändet","grabmal beschädigt"}},{q="Haben Clarice' Kinder überlebt?",a="Clarice erwähnt, dass Yuriv neben ihr auch die gemeinsamen Kinder im Stich gelassen hat, deren endgültiges Schicksal jedoch unerwähnt bleibt. Angesichts der völligen Verwüstung von Lordaeron ist es wahrscheinlich, dass sie ein tragisches Ende fanden.",al={"was geschah mit den kindern","clarice kinder"}}},fp="22,379,17.477.0,19.397.0,14.194.0,47.254.0,41.200.1,30.127.0,32.187.0,31.186.0"}
P.entries["quest:265"] = {n="Die Schattensuche geht weiter",s="Nach Madame Evas Weissagung führt diese Untersuchung von ihrem Salon zu Amtmann Daltry in Dunkelhain. Sie konzentriert sich darauf, den Ursprung des Tagebuchs zurückzuverfolgen, das aus den Ruinen von Sven Yorgens geplündertem Gehöft geborgen wurde.",h="Nach Madame Evas Weissagung führt diese Untersuchung von ihrem Salon zu Amtmann Daltry in Dunkelhain.",kw={"buch","amtmann daltry","dunkelhain","dämmerwald","tagebuch","madame eva","schattenhafte gestalt","sven yorgen"},ang={["class:Rogue"]="Ein nervöses Ziel anhand von Kaufaufzeichnungen und Eindrücken von Händlern durch die Stadt zu verfolgen, ist klassisches investigatives Handwerk.",["faction:Alliance"]="Aufzudecken, wer die Nekromanten im Dämmerwald versorgte und unterstützte, ist unerlässlich, um Dunkelhain zu schützen und den abgeschlachteten Grenzsiedlern Gerechtigkeit widerfahren zu lassen."},sec={{t="The Binding zurückverfolgen",b="Nach der Untersuchung des verbrannten Tagebuchs, das aus der Tragödie auf Svens Hof geborgen worden war, erkannte Madame Eva, dass der Verfasser zwar ein Außenstehender war, der physische Band selbst jedoch aus Dunkelhain stammte. Amtmann Daltry verkauft häufig unbeschriebene Geschäftsbücher und Folianten an reisende Gelehrte, Zauberwirker und Schriftführer. Indem sie der Spur des örtlichen Handels folgen, suchen die Ermittler nach handfesten schriftlichen Hinweisen, um einen ansonsten schwer fassbaren und unheimlichen Eindringling zu identifizieren, der in den düsteren Hainen von Dämmerwald lauert."},{t="Ein nervöser Käufer",b="Bei der Inspektion des Folianten erinnert sich Amtmann Daltry trotz der Fülle an Aufzeichnungen, die das Rathaus von Dunkelhain durchlaufen, genau an das Geschäft. Etwa einen Monat zuvor kaufte ein nervöser, verstohlener Reisender das unbeschriebene Buch, ohne jemals einen Namen zu nennen. Das zittrige Auftreten des Kunden und seine ständigen Blicke über die Schulter hinterließen einen bleibenden Eindruck beim Amtmann und bestätigten, dass The Shadowy Figure, die Sven erblickt hatte, sich offen unter den Bürgern von Dunkelhain bewegt hatte."}},faq={{q="Woher stammte das geheimnisvolle Buch?",a="Madame Eva sagt, der Autor sei ein Fremder in Dunkelhain, doch das Buch sei in der Stadt gekauft worden. Amtmann Daltry verkauft unbeschriebene Bücher und erinnert sich womöglich an dessen Käufer.",al={"herkunft des buches","wer das buch verkaufte","buchquelle"}},{q="Warum schickt Madame Eva Euch zu Amtmann Daltry?",a="Madame Eva erkennt anhand des Einbands und der Materialien des Buches, dass es vor Ort in der Stadt erworben wurde. Amtmann Daltry kümmert sich um den Verkauf unbeschriebener Geschäftsbücher und Tagebücher an Einheimische und reisende Gelehrte.",al={"warum daltry","verbindung eva daltry","wer das buch herstellte"}},{q="Woran erinnert sich Amtmann Daltry hinsichtlich des Käufers?",a="Daltry erinnert sich an die Personen, die in den vergangenen Monaten Bücher von ihm gekauft haben. Die Vorlage des Bandes ermöglicht es ihm nachzuforschen, wer ihn erworben hat.",al={"wer das buch kaufte","beschreibung des käufers","erscheinung der schattenhaften gestalt"}},{q="Wie hängt dies mit Svens Hof zusammen?",a="Das Buch wurde aus Sven Yorgens zerstörtem Hof im südlichen Dämmerwald geborgen, zurückgelassen während des mörderischen Überfalls, der seine Familie und seine Arbeiter auslöschte.",al={"sven-verbindung","warum wir suchen","sven yorgen"}},{q="Wohin führt die Untersuchung als Nächstes?",a="Da der nervöse Fremde einige Zeit in der Stadt verbrachte, wird die Suche in Dunkelhains Taverne, dem Scarlet Raven Inn, fortgesetzt, um zu sehen, ob jemand beobachtet hat, wo er abstieg oder mit wem er sprach.",al={"wie geht es weiter","nach daltry","nächster hinweis"}},{q="Schwebt Amtmann Daltry in Gefahr?",a="Daltry hilft dabei, einen Käufer aus seinen gewöhnlichen Buchverkäufen zu identifizieren. Dieser Austausch liefert keinerlei Anzeichen dafür, dass er persönlich bedroht ist.",al={"amtmann daltry gefahr","daltry in sicherheit"}}},fx={["10e51621"]={q="Warum hilft Madame Eva bei der Suche?",a="Madame Eva dient als Seherin und Beraterin von Dunkelhain und hält Wache über die schattenhaften Omen, die den Dämmerwald plagen. Als Ihr ihr das verkohlte Tagebuch von Svens zerstörtem Hof brachtet, erkannte sie dessen bösartige Herkunft und die Gefahr, die über der Region schwebt. Während ihre Wahrsagerei enthüllte, dass die schattenhafte Gestalt, die es schrieb, ein Fremder für die Stadt war, schlussfolgerte sie, dass das physische Buch selbst vor Ort gekauft wurde. Sie leitet Euch an, die Stadtbewohner zu befragen, damit sie dabei helfen kann, eine Bedrohung auszurotten, die den gesamten Dämmerwald gefährdet.",al={"warum hilft madame eva","motiv madame eva","warum kümmert sich madame eva um das buch"}}},fp="28,217,19.483.0,15.449.1,40.149.0,45.199.0,48.132.0,37.154.0,39.178.1,26.132.0"}
P.entries["quest:266"] = {n="Nachforschungen im Gasthaus",s="Nachforschungen im Gasthaus ist eine Allianz-Quest in Dunkelhain, die die Ermittlungen um den mysteriösen Fremden fortsetzt, der mit Sven Yorgens zerstörtem Hof in Verbindung steht. Auf Geheiß von Amtmann Daltry bringen Abenteurer ein geborgenes Tagebuch in die Scarlet Raven Tavern, um Schankwart Smitts darüber zu befragen, wer dort abgestiegen ist.",h="Nachforschungen im Gasthaus ist eine Allianz-Quest in Dunkelhain, die die Ermittlungen um den mysteriösen...",kw={"amtmann daltry","dunkelhain","dämmerwald","nachforschungen im gasthaus","rabenflucht","scarlet raven","schattengestalt","sven yorgen","schankwart smitts"},ang={["class:Rogue"]="Einen paranoiden Flüchtling von Tavernen-Gerüchten bis hin zu trostlosen Ruinen zu verfolgen, entspricht voll und ganz dem ermittlerischen Handwerk eines Agenten.",["faction:Alliance"]="Die Untersuchung von Bedrohungen in Dunkelhain trägt zum Schutz einer der verwundbarsten und isoliertesten Grenzsiedlungen der Allianz in den südlichen Östlichen Königreichen bei."},sec={{t="Eine Spur in der Scarlet Raven",b="Nachdem Amtmann Daltry das zerfledderte Buch von Sven Yorgens Hof untersucht hat, merkt er an, dass jeder Fremde, der Dunkelhain besucht, mit ziemlicher Sicherheit in der örtlichen Taverne eingekehrt wäre. Das Gasthaus Scarlet Raven auf der anderen Seite der Stadt ist Dunkelhains einziger Versammlungsort und Herberge, was es zum naheliegendsten Ort macht, um durchreisende Besucher aufzuspüren."},{t="Der paranoide Gast",b="Legt man Schankwart Smitts das Buch vor, bestätigt sich Daltrys Ahnung. Smitts erkennt den Band sofort wieder und erinnert sich an einen Gast, der mehrere Tage lang ein Zimmer nahm und seine Abende damit verbrachte, wie besessen an der Bar zu kritzeln. Dem Wirt zufolge floh der Gast voller Panik aus Dunkelhain, überzeugt davon, unerbittlich von einem unsichtbaren Verfolger gejagt zu werden. Sein Weg führte nach Westen die düstere Straße hinab in Richtung Rabenflucht."}},faq={{q="Wer schickt Euch zum Gasthaus?",a="Amtmann Daltry, der Schriftführer der Stadt im Rathaus von Dunkelhain, gibt das Tagebuch zurück und schlägt vor, im örtlichen Gasthaus nachzufragen, ob jemand dessen Besitzer wiedererkennt.",al={"wer gibt diese quest","questgeber","wo beginnt nachforschungen im gasthaus"}},{q="Was für ein Buch tragt Ihr bei Euch?",a="Es ist das abgenutzte Tagebuch, das von Sven Yorgens zerstörtem Gehöft im südlichen Dämmerwald geborgen wurde und von dem man annimmt, dass es der Schattengestalt gehört, die in der Gegend herumschleichen gesehen wurde.",al={"was ist das buch","buch von svens bauernhof","tagebuch"}},{q="Wer leitet das Gasthaus Scarlet Raven?",a="Schankwart Smitts betreibt die Scarlet Raven Tavern, schenkt Getränke aus und vermietet Zimmer an all jene Reisenden, die es noch wagen, sich in den Dämmerwald vorzuwagen.",al={"wer ist der schankwart","gastwirt dunkelhain","wer ist smitts"}},{q="Was enthüllt Schankwart Smitts über den Gast?",a="Smitts erinnert sich daran, dass der Besitzer des Tagebuchs einige Tage lang ein Zimmer mietete und seine Nächte mit Trinken und Schreiben verbrachte. Der Reisende floh daraufhin panisch nach Westen und murmelte etwas davon, von etwas Schrecklichem gejagt zu werden.",al={"was hat smitts gesagt","was geschah mit der schattengestalt","was weiß der gastwirt"}},{q="Wohin floh die Schattengestalt?",a="Er hastete auf der Suche nach einem Versteck aus Dunkelhain nach Westen, was Suchende zur verlassenen Siedlung und den weitläufigen Friedhofsgründen von Rabenflucht führt.",al={"wohin ging er","wo ist die schattengestalt","wohin als nächstes"}},{q="Welche Quest folgt auf Nachforschungen im Gasthaus?",a="Schankwart Smitts weist Euch an, der Spur des Fremden in der Quest 'Die Schattengestalt finden' nach Westen zu folgen.",al={"nächste quest","was kommt nach nachforschungen im gasthaus","folgequest"}}},fx={a709c87f={q="Warum will Amtmann Daltry, dass Ihr Euch im Gasthaus erkundigt?",a="Amtmann Daltry führt die Stadtakten von Dunkelhain, aber seine Register können keine mysteriösen Wanderer erklären, die durch die Schatten schlüpfen. Da er weiß, dass Ihr die schwer fassbare Gestalt verfolgt, die mit den düsteren Ereignissen auf Svens Hof in Verbindung steht, weist er Euch auf das Gasthaus zum Roten Raben hin. In einer vorsichtigen Stadt wie Dunkelhain wäre jeder Fremde, der auf einen Drink oder ein Bett blieb, dem Gastwirt aufgefallen.",al={"warum schickt euch daltry zum gasthaus","motiv daltry gasthaus","warum im gasthaus zum roten raben fragen"}}},fp="18,299,27.363.0,18.419.1,25.172.0,34.162.0,31.143.0,51.205.0,34.157.0,38.112.0"}
P.entries["quest:267"] = {n="Die Bedrohung durch die Troggs",s="Die Bedrohung durch die Troggs ist eine Quest der Allianz, die von Hauptmann Rugelfuß am Südtor von Loch Modan vergeben wird. Da die örtliche Eisenschmiede-Reserve abberufen wurde, um Schlachtfronten der Allianz zu unterstützen, sind die verbliebenen Verteidiger gegen die feindseligen Troggstämme in den Hügeln stark überdehnt. Abenteurer werden damit beauftragt, die Troggs auszudünnen und mit ihren Steinzähnen zurückzukehren, um den Druck auf den Gebirgspass zu lindern.",h="Die Bedrohung durch die Troggs ist eine Quest der Allianz, die von Hauptmann Rugelfuß am Südtor von Loch...",kw={"hauptmann rugelfuß","eisenschmiede-reserve","khaz modan","loch modan","magni bronzebart","südtor","trogg","troggsteinzahn"},ang={["faction:Alliance"]="Die Quest verdeutlicht, wie Verpflichtungen der Allianz in fernen Ländern lokalen Garnisonen wie jener in Loch Modan ihre Verteidigungsreserven entzogen haben.",["race:Dwarf"]="Für Zwerge ist das Dezimieren der Troggs nahe dem Südtor eine direkte Pflicht gegenüber Khaz Modan und bringt ihnen das Lob von König Magni Bronzebart höchstpersönlich ein."},sec={{t="Eine entblößte Grenze",b="Die Verteidigungslinie, die den südlichen Zugang nach Loch Modan bewacht, befindet sich in einem prekären Zustand. Die regulären Zwergengebirgsjäger und Regimenter der Eisenschmiede-Reserve wurden entsandt, um weiter entfernte Kriegsfronten der Allianz zu verstärken, wodurch Hauptmann Rugelfuß und eine Notbesatzung am südlichen Wachturm zurückblieben. Gebunden an strenge Befehle, das Tor nicht aufzugeben, kann Rugelfuss keine aktive Offensive ins Hochland starten, wodurch nahegelegene Siedler und Reisende anfällig für Hinterhalte bleiben."},{t="Den Vormarsch eindämmen",b="Die Troggs, die in den umliegenden Felsen hausen, stellen eine wachsende Gefahr für Khaz Modan dar. Sich selbst überlassen, wächst ihre Zahl rasch an und droht, die Zwergenaußenposten zu überrennen. Um Zeit zu gewinnen und die Bedrohung einzudämmen, bittet Rugelfuss umherziehende Abenteurer, die Troggs direkt in ihren Bauten am Hang anzugreifen und abgetrennte Steinzähne als physischen Beweis der Tat vorzulegen."}},faq={{q="Wer ist Hauptmann Rugelfuß?",a="Hauptmann Rugelfuß ist ein Offizier des Zwergenmilitärs, der am Wachturm des Südtors in Loch Modan stationiert ist. Er hat die Aufgabe, den Pass gegen Eindringlinge zu sichern, während er mit einem gravierenden Mangel an Garnisonstruppen zu kämpfen hat.",al={"hauptmann rugelfuß","wer vergibt die bedrohung durch die troggs","rugelfuss"}},{q="Warum ist das Südtor unterbesetzt?",a="Die Eisenschmiede-Reserve wurde mobilisiert und abkommandiert, um an den größeren Frontlinien der Allianz in der Ferne zu kämpfen. Nur ein kleines Regiment verbleibt am Tor, gebunden an seinen Verteidigungsposten und unfähig, Vergeltungsschläge durchzuführen.",al={"warum gibt es keine wachen","eisenschmiede-reserve abwesend","wo sind die zwergensoldaten"}},{q="Was sind Troggsteinzähne?",a="Troggs besitzen von Natur aus versteinerte, steinartige Zähne, die ihr unterirdisches, irdenes Erbe widerspiegeln. Hauptmann Rugelfuß verlangt sie als unmissverständlichen physischen Beweis dafür, dass Troggs getötet wurden.",al={"troggsteinzahn","steinzähne","warum troggzähne"}},{q="Wo halten sich die Troggs auf?",a="Die Troggs bewohnen die felsigen Hügel, Schluchten und Ausgrabungsstätten entlang der Straße nahe dem Südtor in Loch Modan.",al={"wo man troggs findet","trogg-standorte loch modan","wo sind troggs für diese quest"}},{q="Warum sind die Troggs derzeit eine so große Bedrohung?",a="Troggs vermehren sich rasch, agieren mit gewaltsamer territorialer Aggression und überrennen bewohnte Gebiete, wann immer militärische Garnisonen abgezogen werden. Ohne aktive Dezimierung drohen sie, die Pässe abzuschnüren, die Loch Modan mit den Nachbargebieten verbinden.",al={"warum sind troggs gefährlich","troggproblem","was wollen troggs"}},{q="Inwiefern hilft das Abschließen dieser Quest König Magni Bronzebart?",a="König Magni Bronzebart trägt die Verantwortung für die Sicherheit von ganz Khaz Modan. Indem Abenteurer die Troggpopulation dezimieren, während die Armeen von Eisenschmiede in der Ferne kämpfen, schützen sie die internen Versorgungslinien und verwundbaren Grenzsiedlungen des Reichs.",al={"verbindung zu magni bronzebart","kümmert magni das","warum eisenschmiede helfen"}}},fx={["5b5ee45d"]={q="Warum will Hauptmann Rugelfuß, dass dies erledigt wird?",a="Da die Reserve der Eisenschmiede an die Front der Allianz verlegt wurde, fehlt es Hauptmann Rugelfuß an Arbeitskräften, um die Region zu sichern. Sein Regiment ist damit beschäftigt, den südlichen Wachturm gegen eine potenzielle Invasion zu halten. Wenn die Troggs, die sich in den nahegelegenen Hügeln sammeln, unbeaufsichtigt bleiben, könnten sie den Außenposten leicht überwältigen und Loch Modan überrennen.",al={"motiv rugelfuss","warum troggs bekämpfen","zweck hauptmann rugelfuss"}},ba878bae={q="Warum befallen die Troggs die Hügel in der Nähe des Südtores?",a="Die Troggs sind in den Zwergenländern aufgetaucht und dringen aggressiv in Siedlungen und auf Reisewege ein. Da sie die umliegenden Felsen als reif für eine Invasion empfinden, streifen sie auf den Bergrücken in der Nähe des Südtores umher und warten darauf, die verwundbaren Verteidigungsanlagen anzugreifen, die durch den anhaltenden Truppenmangel geschwächt sind.",al={"wer sind die troggs","trogg ziele","warum sind troggs hier"}}},fp="16,396,19.487.0,17.370.0,25.221.0,38.228.0,27.201.0,29.137.0,43.244.0,58.247.0"}
P.entries["quest:268"] = {n="Rückkehr zu Sven",s="Diese Quest markiert den Moment, in dem Sven Yorgen endlich die Wahrheit hinter dem brutalen Massaker an seiner Familie auf Yorgens Bauernhof erfährt. Nachdem Ihr den flüchtigen Bibbers aufgespürt habt, kehrt Ihr mit Bibbers' vollendetes Tagebuch zu Svens isoliertem Lager am Rande von Westfall zurück. Das Tagebuch verspricht Antworten auf die Fragen, die Sven seit dem Angriff gequält haben.",h="Diese Quest markiert den Moment, in dem Sven Yorgen endlich die Wahrheit hinter dem brutalen Massaker an...",kw={"dunkle reiter","dämmerwald","das verlassene gut","jitters","bibbers' vollendetes tagebuch","morbent teufel","sven yorgen","yorgens bauernhof"},ang={["class:Paladin"]="Sven dabei zu helfen, die Kräfte hinter dem Mord an seiner Familie aufzudecken, dient der heiligen Pflicht, die Unschuldigen zu schützen und Gerechtigkeit zu suchen.",["faction:Alliance"]="Der tragische Untergang von Yorgens Bauernhof ist eine deutliche Erinnerung an das völlige Versagen von Sturmwind, die Grenzsiedlungen des Dämmerwalds vor den eindringenden Schatten zu schützen."},sec={{t="Das Geständnis eines Feiglings",b="Als der Yorgen Farmstead angegriffen wurde, floh Bibbers vor Schrecken in die Wälder und ließ inmitten des Gemetzels nur ein unvollständiges Tagebuch zurück. Vor Svens Zorn erzitternd und von dem gezeichnet, was er gesehen hatte, versteckte sich Bibbers tief im Dämmerwald. Als er gestellt wird, händigt er bereitwillig sein vollendetes Tagebuch aus, in der verzweifelten Hoffnung, dass das Liefern der vollständigen Geschichte des Angriffs ihn davor bewahrt, dem rachsüchtigen Farmer persönlich gegenüberzutreten."},{t="Die Enthüllung der Dunklen Reiter",b="Das Lesen von Bibbers' fertigem Bericht fügt für Sven endlich die schrecklichen Puzzleteile zusammen. Das Gemetzel auf seiner Farm war kein zufälliger Ansturm von Untoten oder ein Angriff wilder Bestien; es wurde von den rätselhaften Dunklen Reitern verübt, die auf der Suche nach einem Artefakt waren. Darüber hinaus erinnert sich Sven, diese gleichen vermummten Gestalten bei einem geheimen Treffen mit dem Nekromanten Morbent Teufel in der Nähe vom verlassenen Gut gesehen zu haben. Bibbers' Tagebuch verwandelt Svens blinden Kummer in eine gezielte Jagd nach Vergeltung gegen den dunklen Magier."}},faq={{q="Warum hat Bibbers solche Angst vor Sven Yorgen?",a="Bibbers floh von Svens Farm und fürchtet sich davor, dem Zorn des trauernden Farmers gegenüberzutreten. Er bittet Euch, sein Tagebuch zu überbringen, damit Sven seinen Bericht lesen kann.",al={"warum hat jitters angst","jitters hat angst vor sven","was hat jitters getan"}},{q="Was steht in Bibbers' vollendetes Tagebuch?",a="Es ist Bibbers' vollständiger Bericht über die Ereignisse auf Svens Farm. Sven muss ihn lesen, um zu verstehen, was mit seiner Familie passiert ist.",al={"was steht in dem tagebuch","jitters vollendetes tagebuch hintergrund"}},{q="Wer sind die von Sven erwähnten Dunklen Reiter?",a="Die Dunklen Reiter sind mysteriöse, in Umhänge gehüllte Gestalten, die den Dämmerwald durchstreifen. Rücksichtslos und tödlich, drangen sie in den Wald ein und suchten unerbittlich nach mächtigen magischen Relikten, wobei sie überall dort, wo sie auftauchten, Tod und Verderben hinterließen.",al={"wer sind die dunklen reiter","reiter im dämmerwald","schwarze reiter"}},{q="Wie hängt Morbent Teufel mit dem Angriff auf Svens Farm zusammen?",a="Morbent Teufel ist ein mächtiger Nekromant im westlichen Dämmerwald. Seine Verbindung zu dem Angriff wird durch Svens Ermittlungen und Bibbers' Tagebuch aufgedeckt.",al={"morbent teufel verbindung","warum morbent teufel","wer ist morbent teufel"}},{q="Wo ist Sven Yorgen zu finden?",a="Sven hat seinen zerstörten Bauernhof verlassen und lebt nun in einem kleinen, angespannten Lager, das in den nordwestlichen Hügeln des Dämmerwaldes liegt, nahe dem Grenzübergang nach Westfall.",al={"wo ist sven","sven yorgen standort","svens lager"}},{q="Was passiert, nachdem man Sven das Tagebuch gegeben hat?",a="Sven liest Bibbers' vollendeten Bericht und bittet Euch, Eure Kampffähigkeiten in der nächsten Aufgabe, Bewährungsprobe, unter Beweis zu stellen.",al={"nächste quest nach rückkehr zu sven","sven questreihe weiter"}}},fx={ba46c9da={q="Warum muss Jitters Euch das Tagebuch überbringen lassen, anstatt es selbst zu bringen?",a="Jitters ist völlig von Angst verzehrt. Er versteckte sich unbemerkt in Svens Scheune, während Svens Familie abgeschlachtet wurde, und floh dann, wobei er sein halbfertiges Tagebuch zurückließ. Anstatt zu riskieren, Svens Zorn persönlich gegenüberzutreten, überreicht er Euch bereitwillig sein vervollständigtes Tagebuch, um die Wahrheit über das, was tatsächlich geschehen ist, zu übermitteln.",al={"warum schickt mich jitters","warum kann jitters nicht mit sven sprechen","warum jitters tagebuch abliefern"}}},fp="14,359,21.425.0,25.487.1,43.136.0,38.122.1,42.213.0,58.151.1,31.175.0,43.119.1"}
P.entries["quest:269"] = {n="Auf der Suche nach Weisheit",s="Seeking Wisdom ist eine Allianz-Botengänge, bei der Ihr Bibbers' vollendetes Tagebuch aus den umkämpften Lagern des Dämmerwalds in die Sicherheit von Sturmwind bringt. Sven Yorgen schickt Abenteurer zu Bischof Heller in die Kathedrale des Lichts, in der Hoffnung, dass heiliger Rat offenbart, wie der beschützte Nekromant Morbent Fel vernichtet werden kann.",h="Seeking Wisdom ist eine Allianz-Botengänge, bei der Ihr Bibbers' vollendetes Tagebuch aus den umkämpften...",kw={"bischof heller","kathedrale des lichts","dunkelhain","dämmerwald","bibbers","morbent fel","seeking wisdom","sturmwind","sven yorgen"},ang={["class:Paladin"]="Das Überbringen von Bitten um heiliges Eingreifen aus den verlassenen Grenzlanden in das Herz der Kathedrale des Lichts stellt direkt die Pflicht der Silbernen Hand auf die Probe, die Vergessenen zu schützen und Nekromantie auszurotten.",["class:Priest"]="Bischof Heller bietet klerikale Führung darüber an, wie dunkle Schutzzauber Seele und Körper korrumpieren, und zeigt, dass Schattenzauberei nicht einfach mit der Klinge bekämpft werden kann, sondern mit fokussierter Heiligung.",["faction:Alliance"]="Die Reise unterstreicht den bitteren politischen Graben zwischen den bewachten Marmorhallen von Sturmwind und den verlassenen Städten des Dämmerwalds, die keinerlei Unterstützung durch Garnisonen erhalten."},sec={{t="Ein Flehen aus den Schatten",b="Der Dämmerwald leidet unter andauernden Flüchen, gefräßigen Untoten und der wachsenden Gleichgültigkeit des königlichen Hofes von Sturmwind. Sven Yorgen, ein gebrochener Überlebender, der nahe der Grenzen kampiert, weiß, dass gewöhnliche Stärke die dunklen Schutzzauber des Nekromanten Morbent Fel nicht durchdringen kann. Bewaffnet mit dem zusammengestellten Tagebuch des Vagabunden Bibbers drängt Sven reisende Helden dazu, bei der Kirche statt beim König vorstellig zu werden, und schickt sie den Weg nach Norden zur Kathedrale des Lichts."},{t="Rat in der Kathedrale",b="In den prachtvollen Hallen der Kathedrale von Sturmwind vertritt Bischof Heller eine der wenigen Autoritäten, die noch bereit sind, sich den Hilferufen aus dem Dämmerwald anzuhören. Nachdem er Bibbers' erschütternden Bericht gelesen hat, bestätigt der Bischof die schreckliche Macht von Morbent Fel. Der Nekromant schützt sich mit abscheulicher Zauberei, die herkömmliche Schläge abwehrt, was bedeutet, dass ungezielter Mut allein nur zum Schlachten führen wird. Um das Ungeheuer zu bezwingen, muss ein verzaubertes heiliges Instrument geborgen werden."}},faq={{q="Warum schickt Sven Euch zu Bischof Heller statt zu König Anduin?",a="Der Adel und die Armee von Sturmwind haben Dunkelhain und die umliegenden Lande weitgehend aufgegeben, damit sie inmitten der politischen Lähmung allein zurechtkommen. Sven weiß, dass offizielle Kanäle keine Soldaten hervorbringen werden, aber er vertraut Bischof Heller als einem mitfühlenden, gelehrten Mann des Heiligen Lichts, der sich auf finstere Magie versteht.",al={"warum farthing","warum nicht sturmwind adel","sturmwind ignoriert dämmerwald"}},{q="Was ist Bibbers' Tagebuch und warum benötigt der Bischof es?",a="Bibbers zeichnete die Ereignisse auf, die zum Angriff auf Svens Bauernhof führten. Sven schickt den vollständigen Bericht an Bischof Heller, damit der Bischof den Abenteurer beraten kann, der sich darauf vorbereitet, Morbent Fel gegenüberzutreten.",al={"was ist bibbers tagebuch","warum bibbers tagebuch","bibbers vollendetes tagebuch"}},{q="Wer ist Morbent Fel?",a="Morbent Fel ist ein mächtiger Nekromant, der am Das verlassene Gut im Dämmerwald gesehen wurde. Er befehligt Horden von skelettierten Dienern und schützt seine physische Gestalt mit mächtigen Schutzzaubern, was ihn gegen normale Waffen immun macht.",al={"wer ist morbent fel","morbent fel lore"}},{q="Wo befindet sich Bischof Heller?",a="Bischof Heller residiert in der Kathedrale des Lichts, der großen Kathedrale der Menschen, die den Kathedralenplatz innerhalb von Sturmwind dominiert.",al={"wo ist farthing","farthing standort","bischof farthing karte"}},{q="Was passiert, nachdem Bischof Heller das Tagebuch gelesen hat?",a="Bischof Heller erklärt, dass Morbent Fel durch konventionelle Angriffe nicht verletzt werden kann. Er weist Abenteurer darauf hin, ein geheiligtes Relikt zu entdecken, das fähig ist, die magischen Schutzzauber des Nekromanten zu bannen, was zur Suche nach The Doomed Fleet führt.",al={"was kommt nach seeking wisdom","seeking wisdom folgequest","nach seeking wisdom"}},{q="Wo hält sich Sven Yorgen im Dämmerwald auf?",a="Sven Yorgen findet Zuflucht in einem kleinen Lager im nordwestlichen Dämmerwald, versteckt nahe der Flussgrenze südlich des Waldes von Elwynn und westlich des verwunschenen Friedhofs von Rabenflucht.",al={"wo ist sven","sven yorgen standort","sven's camp"}}},fx={["12ed4f38"]={q="Warum muss Sven Yorgen Euch bitten, das Tagebuch auszuliefern?",a="Sven hält allein im Dämmerwald die Stellung, verzehrt von Rache und Trauer, während er in einem Lager voller Schrecken ums Überleben kämpft. Sturmwind hat Dunkelhain und die umliegenden Lande ihrem Schicksal überlassen und schickt keine königlichen Wachen, um ihm beizustehen. Sven kann den Dämmerwald nicht unbewacht lassen und besitzt auch nicht die Mittel, um Morbent Fels dunkle Zauberei allein zu brechen. Da Ihr Euch gegen die örtlichen Bedrohungen bewährt habt, seid Ihr seine einzige verlässliche Hoffnung, die Wahrheit über Bibbers zu jemandem zu bringen, der die Weisheit und die heilige Macht besitzt, zu helfen.",al={"warum ich sven","warum spieler zu bischof farthing schicken","warum geht sven nicht nach sturmwind"}}},fp="14,313,23.454.0,24.452.1,65.301.0,57.189.0,19.232.0,33.144.0,53.243.1,40.159.0"}
P.entries["quest:27"] = {n="Eine wertvolle Lektion",s="„Eine wertvolle Lektion“ ist ein früher Initiationsritus für Druiden der Allianz, die in Darnassus ausgebildet werden. Die Quest wird von Mathrengyl Bärenfährte angeboten und weist Novizen an, in die heilige Zuflucht Mondlichtung zu reisen, um damit zu beginnen, ihren aquatischen Aspekt zu meistern.",h="„Eine wertvolle Lektion“ ist ein früher Initiationsritus für Druiden der Allianz, die in Darnassus...",kw={"eine wertvolle lektion","wassergestalt","darnassus","dendrite sternenschauer","druidenquest","mathrengyl bärenfährte","mondlichtung","nachthafen"},ang={["class:Druid"]="Diese Quest markiert einen wichtigen Meilenstein in der Ausbildung eines Druiden und ebnet den Weg zur Zwiesprache mit den Gaben von Cenarius unter den Wellen.",["race:NightElf"]="Für die Kaldorei von Darnassus ist das Befolgen des Rufs des Zirkels des Cenarius nach Mondlichtung eine ehrwürdige Tradition, die sie mit ihren uralten Lehrern verbindet."},sec={{t="Der Ruf der Wildnis",b="Mathrengyl Bärenfährte wacht über junge Nachtelfendruiden, die ihr Handwerk im Geäst von Darnassus ausüben. Sobald ein Novize eine unerschütterliche Verbindung zur Natur und den Willen beweist, größere Verantwortung zu übernehmen, fordert Mathrengyl ihn auf, sich auf seine nächste große Disziplin vorzubereiten: die Beherrschung der Gewässer. Die von Cenarius verliehenen Gaben verlangen strenge Konzentration, und die Fähigkeit, Tiefen ohne zu ertrinken zu durchqueren, erfordert die direkte Zwiesprache mit den Ältesten des Zirkels des Cenarius."},{t="Reise nach Nachthafen",b="Um fortzufahren, muss der Novize Darnassus verlassen und nach Mondlichtung reisen, der uralten Zuflucht am Fuße des Hyjal. In der friedlichen Siedlung Nachthafen wartet Dendrite Sternenschauer. Als erfahrener Mentor des Zirkels prüft Starblaze, ob junge Gestaltwandler bereit sind, sich den Prüfungen zur Freischaltung der Wassergestalt zu stellen, und warnt sie davor, dass die Beherrschung des Wassers sowohl körperliche Ausdauer als auch geistige Entschlossenheit erfordert."}},faq={{q="Wer schickt mich auf diese Quest?",a="Mathrengyl Bärenfährte, der Druidenlehrer in der Enklave des Cenarius in Darnassus, vergibt diese Quest, sobald Ihr in Euren frühen druidischen Künsten weit genug vorangeschritten seid.",al={"questgeber","wer vergibt eine wertvolle lektion","wer startet das"}},{q="Was ist der Zweck dieser Quest?",a="Sie dient als Auftakt für Druiden, die ihre Wassergestalt erlangen wollen. Sie ruft den Novizen nach Mondlichtung, um dort Unterweisung und Prüfungen vom Ältesten Dendrite Sternenschauer zu erhalten.",al={"warum diese quest annehmen","einführung wassergestalt","was erhalte ich"}},{q="Wo befindet sich Dendrite Sternenschauer?",a="Dendrite Sternenschauer weilt im Dorf Nachthafen, gelegen an den nördlichen Ufern des Elune'ara Sees in Mondlichtung.",al={"standort von dendrite","wo ist dendrite sternenschauer","dendrite finden"}},{q="Wie erreichen Druiden Mondlichtung für diese Quest?",a="Druiden besitzen eine spirituelle Einstimmung, die es ihnen ermöglicht, sich mithilfe ihrer Fähigkeit Teleportieren: Mondlichtung direkt in den heiligen Hain von Mondlichtung zu teleportieren, wodurch herkömmliche Überlandrouten umgangen werden.",al={"wie man nach mondlichtung gelangt","weg nach nachthafen"}},{q="Was geschieht nach dem Gespräch mit Dendrite Sternenschauer?",a="Sobald Eure Audienz bei Dendrite Sternenschauer beendet ist, beauftragt er Euch umgehend mit der Prüfung des Sees, um Eure Ausdauer und Klarheit unter Wasser auf die Probe zu stellen.",al={"folgequest","wie geht es weiter","nach eine wertvolle lektion"}}},fx={["67389e7a"]={q="Warum schickt Mathrengyl Bärenfährte Euch zur Mondlichtung?",a="Mathrengyl Bärenfährte hat Euer Wachstum beobachtet und glaubt, dass Ihr bereit seid, Eure Verbindung zur Wildnis zu vertiefen. Die Tieraspekte, die Cenarius verliehen hat, erfordern eine gründlichere Unterweisung, als die normale Ausbildung bietet. Um die Geheimnisse der Meisterschaft über das Wasser zu erlernen, weist er Euch an Dendrite Sternenschauer und den Zirkel des Cenarius im Nachthafen, wo alte druidische Prüfungen überwacht werden.",al={"warum schickt mathrengyl euch","mathrengyl bärenfährte motiv","warum zur mondlichtung"}}},fp="17,229,20.481.0,21.444.0,27.169.0,34.178.0,36.122.0,45.189.0,48.160.0"}
P.entries["quest:270"] = {n="Die Verlorene Flotte",s="Die verlorene Flotte ist eine Reise gen Norden, zu der Bischof Heller in Sturmwinds Kathedrale des Lichts aufruft. Auf der Suche nach einem Weg, den mächtigen Nekromanten Morbent Teufel zu bezwingen, werden Helden quer durch Khaz Modan zu den gesunkenen Wracks vor der Küste des Sumpflands geschickt.",h="Die verlorene Flotte ist eine Reise gen Norden, zu der Bischof Heller in Sturmwinds Kathedrale des Lichts...",kw={"bischof heller","die verlorene flotte","glorin stahlbraue","kul tiras","lichtgeschmiedetes eisen","der hafen von menethil","morbent teufel","die dritte flotte","sumpfland"},ang={["class:Paladin"]="Die Suche nach heiligem Metall, um einen unheiligen Nekromanten zu zerschmettern, veranschaulicht die Berufung der Paladine, die Finsternis mit vom Licht geweihten Waffen zu läutern.",["class:Priest"]="Unter der Führung von Bischof Heller zu handeln, verbindet Priester direkt mit dem uralten Wissen der Kirche über gesegnete Relikte und geweihte Erze.",["faction:Alliance"]="Diese Quest verdeutlicht die logistische Reichweite der Allianz, indem sie die isolierten Menschendörfer des Südens mit Zwergenhäfen und alten Seewegen verbindet.",["profession:Blacksmithing"]="Schmiede werden die seltene Überlieferung um das Lichtgeschmiedete Eisen schätzen – ein vom Glauben erfülltes Metall, dessen Formung meisterhafte Handwerkskunst verlangt."},sec={{t="Eine Waffe der heiligen Wahrheit",b="Herkömmlicher Stahl hat sich gegen die dunklen Schutzschilde als wirkungslos erwiesen, die Morbent Teufel an seinem Rückzugsort auf dem verlassenen Gut abschirmen. Um solche nekromantischen Barrieren zu durchdringen, weist Bischof Heller Abenteurer an, eine an das Heilige Licht gebundene Waffe zu schmieden. Der Schlüsselbestandteil ist Lichtgeschmiedetes Eisen, ein seltenes und geweihtes Metall, dessen Hiebe heilige Wahrheit in sich tragen und magische Schutzwälle durchschneiden, an denen gewöhnliche Klingen abprallen."},{t="Das Wrack der Dritten Flotte",b="Leider gibt es im belagerten Dämmerwald keine Vorräte an Lichtgeschmiedetem Eisen. Heller erinnert sich, dass vor Jahren die Dritte Flotte des Inselreichs Kul Tiras an den tückischen Küsten des Sumpflands nördlich von Eisenschmiede verunglückte. An Bord einer dieser gesunkenen Galeonen befand sich eine Ladung des kostbaren Erzes. Abenteurer müssen den ganzen Weg bis zum Hafen von Menethil reisen, um Glorin Stahlbraue zu Rate zu ziehen, einen Zwergenkontakt, der die Sümpfe und ihre Schiffswracks am besten kennt."}},faq={{q="Warum muss ich den ganzen Weg ins Sumpfland reisen?",a="Morbent Teufels dunkle Verzauberungen schützen ihn vor gewöhnlichen Angriffen. Bischof Heller weiß, dass nur eine aus heiligem Lichtgeschmiedetem Eisen gefertigte Waffe diese Schutzzauber beseitigen kann, und die einzig bekannte Ladung liegt unter den Wracks der Dritten Flotte von Kul Tiras vor dem Hafen von Menethil.",al={"warum ins sumpfland","warum hafen von menethil","sumpfland reise"}},{q="Wer ist Morbent Teufel?",a="Morbent Teufel ist ein finsterer Nekromant, der auf dem verlassenen Gut im Dämmerwald haust. Seine Zauberei hat einen Großteil des Untotenaufstands angefacht, der die Region heimsucht, weshalb sein Untergang für das Überleben von Dunkelhain unerlässlich ist.",al={"morbent teufel identität","wer ist der nekromant","dämmerwald nekromant"}},{q="Wer ist Glorin Stahlbraue?",a="Glorin Stahlbraue ist ein Zwerg, der im Hafen von Menethil im Sumpfland stationiert ist. Er dient der Kirche des Heiligen Lichts als Verbündeter und besitzt tiefe Kenntnisse über die Küste, Schiffswracks und Bergungsarbeiten im Marschland.",al={"wer ist steelbrow","steelbrow rolle"}},{q="Was ist Lichtgeschmiedetes Eisen?",a="Lichtgeschmiedetes Eisen ist ein besonders geweihtes Metall, das von der Priesterschaft hoch geschätzt wird. Daraus geschmiedete Waffen schlagen mit heiliger Macht zu und vermögen dunkle Schilde sowie nekromantische Flüche zu bannen oder zu durchdringen, denen gewöhnliches Eisen nicht beikommen kann.",al={"was bewirkt lichtgeschmiedetes eisen","lichtgeschmiedetes metall","gesegnetes eisen"}},{q="Was geschah mit der Dritten Flotte von Kul Tiras?",a="Vor Jahren erlitt die Dritte Flotte von Kul Tiras an der zerklüfteten, sumpfigen Küste des Sumpflands Schiffbruch und sank. Ihre Rümpfe liegen noch immer vor der Küste unter Wasser, bergen verlorene Fracht und werden von ertrunkenen Seeleuten und Wasserraubtieren bewacht.",al={"schicksal der dritten flotte","kul tiras schiffe sumpfland","wie schiffe sanken"}},{q="Beinhaltet diese Quest sofort Kämpfe?",a="Dieser Abschnitt ist eine reine Botenquest. Er erfordert eine lange Reise aus dem Dämmerwald durch das Königreich Sturmwind und Khaz Modan hinab zum Hafen von Menethil, um Kontakt mit Glorin Stahlbraue aufzunehmen.",al={"gibt es kampf","nur reisequest"}}},fx={ade8f412={q="Warum schickt Bischof Heller Euch auf diese Quest?",a="Bischof Heller weiß, dass der Nekromant Morbent Fel eine tödliche Bedrohung für den Dämmerwald darstellt und nicht mit gewöhnlichen Mitteln besiegt werden kann. Um eine solch dunkle Macht zu besiegen, benötigt Ihr eine Waffe, die mit heiliger Macht gesegnet ist und aus heiligem Lightforge Iron geschmiedet wurde. Da dieses Eisen mit der Third Fleet von Kul Tiras im Meer verloren ging, schickt Heller Euch nach Norden zum Hafen von Menethil, um seinen zwergischen Mitarbeiter Glorin Stahlbraue zu konsultieren, in der Hoffnung, das versunkene Metall zu bergen.",al={"warum will bischof farthing lightforge iron","farthing motiv doomed fleet","warum die doomed fleet finden"}},a631378f={q="Warum können Bischof Heller oder The Night Watch nicht selbst mit Morbent Fel fertig werden?",a="The Night Watch ist gefährlich dünn besetzt und hat schon alle Hände voll zu tun, die Grenzen des Dämmerwalds vor dem Ansturm gedankenloser Untoter, Worgen und Spinnen zu schützen. Bischof Heller muss seinen Pflichten in der Kathedrale des Lichts in Sturmwind nachkommen, und weder er noch die örtliche Miliz können die Zeit oder das Personal für einen langen Marsch über den Kontinent bis in das Sumpfland entbehren. Als unabhängiger Reisender habt Ihr die Freiheit und die Entschlossenheit, nach dem verlorenen Eisen zu suchen und dem Nekromanten direkt entgegenzutreten.",al={"warum mich zur doomed fleet schicken","warum geht the night watch nicht","warum braucht bischof farthing mich"}}},fp="16,255,22.422.0,28.467.0,52.275.0,19.205.0,24.222.0,24.215.0,46.226.0,48.207.0"}
P.entries["quest:273"] = {n="Nachschub für die Ausgrabungsstätte",s="Resupplying the Excavation ist eine Quest der Allianz in Loch Modan, bei der Abenteurer einer Pulverlieferung nachjagen, die für Eisenbands Ausgrabungsstätte bestimmt ist. Ausgesandt von Jern Hornhelm, um das Gespann einzuholen, folgt der Reisende ihrer Route am Ufer des Lochs entlang.",h="Resupplying the Excavation ist eine Quest der Allianz in Loch Modan, bei der Abenteurer einer Pulverlieferung...",kw={"sprengpulver","huldar","eisenband","jern hornhelm","loch modan","miran","resupplying the excavation","saean","thelsamar"},ang={["profession:Mining"]="Flüchtiges Sprengpulver über unwegsames Gelände zu transportieren, ist auch ohne Verrat gefährlich genug, was diese Lieferung für die Ausgräber unten im Süden unverzichtbar macht.",["race:Dwarf"]="Für Zwerge der Bronzebärte hilft der Schutz der Sprengpulverlieferung dabei, Eisenbands Arbeit trotz der Gefahren auf den Straßen von Loch Modan versorgt zu halten."},sec={{t="Eine schwere Fracht entlang des Ufers",b="Eisenbands Ausgrabungsstätte im südlichen Loch Modan benötigt einen stetigen Nachschub an Sprengpulver, um uralte Titanenartefakte freizulegen, die tief in den Bergen vergraben liegen. Nachdem Sprengpulver nach Thelsamar geliefert worden war, organisierte der örtliche Quartiermeister Jern Hornhelm drei Zwerge – Huldar, Miran und Saean –, um die flüchtigen Fässer auf der Straße am Seeufer nach Süden zu transportieren. Belastet durch die schwere Fracht kam die Nachschubgruppe nur langsam voran, was Reisenden in Thelsamar die Gelegenheit gab, sie einzuholen und unterwegs Unterstützung zu leisten."},{t="Verrat in den Schatten",b="Als der Lastenkarren auf der südlichen Straße eingeholt wird, offenbart sich Chaos statt einer routinemäßigen Lieferung. Die Lieferung geriet in einen Hinterhalt von Dunkeleisenzwergen, die aktiv versuchen, die archäologischen Bemühungen der Expedition der Bronzebärte zu sabotieren. Schlimmer noch als der Überfall selbst brachte der Angriff bitteren Verrat ans Licht: Saean, ein Arbeiter, dem vertraut wurde und der fast ein Jahr lang an der Seite von Huldar gearbeitet hatte, erwies sich als Sympathisant der Dunkeleisenzwerge, der bei der Organisation des Hinterhalts half."}},faq={{q="Wer startet die Quest Resupplying the Excavation?",a="Jern Hornhelm bietet die Quest in Thelsamar an, nachdem Ihr ihm das Sprengpulver gebracht habt. Er bittet Euch, der Straße nach Süden am Loch entlang zu folgen, um die Nachschubgruppe einzuholen.",al={"wer vergibt resupplying the excavation","queststart resupplying the excavation","wo startet resupplying the excavation"}},{q="Wo sind Huldar und der Wagen zu finden?",a="Huldar und der Wagen befinden sich südlich von Thelsamar entlang der Straße, die sich an die westliche und südliche Biegung des Lochs schmiegt und in Richtung Eisenbands Ausgrabungsstätte führt.",al={"huldar finden","huldar aufenthaltsort","wo ist der wagen loch modan"}},{q="Warum wird Sprengpulver zu Eisenband geschickt?",a="Ausgrabungsleiter Eisenband und sein Team legen uralte irdene Ruinen und Relikte an der südlichen Ausgrabungsstätte frei. Sprengpulver wird benötigt, um schweren Stein aufzubrechen und durch unterirdische Schichten zu sprengen.",al={"warum eisenband pulver braucht","eisenband sprengpulver","warum sprengpulver zur ausgrabungsstätte"}},{q="Wer überfiel Huldars Wagen?",a="Jern erwartet, dass sich die Nachschubgruppe auf der normalen Straße südlich von Thelsamar am Loch entlang befindet. Was mit dem Wagen geschehen ist, erfahrt Ihr, wenn Ihr Huldar erreicht.",al={"wer hat den wagen angegriffen","wagenhinterhalt loch modan","wer hat huldar angegriffen"}},{q="Welche Rolle spielte Saean bei dem Angriff?",a="Saean reist mit Huldar und Miran, um die schweren Sprengpulverfässer zu transportieren. Seine Rolle bei den Ereignissen auf der Straße wird offenbart, wenn Ihr die Gruppe einholt.",al={"wer ist saean","saean verrat","was hat saean getan"}},{q="Welche Quest folgt nach dem Auffinden von Huldar?",a="Ein Gespräch mit Huldar schließt diesen Teil der Reise ab. Sein Bericht über die Lieferung liefert die nächste Spur.",al={"folgequest nach resupplying the excavation","quest nach huldar"}}},fx={["72005fbc"]={q="Warum schickt Jern Hornhelm Euch hinter Huldar her?",a="Jern Hornhelm erkennt, dass Ihr kurz nach dem Aufbruch von Huldar und seiner Mannschaft mit dem schweren Wagen in Richtung Ironband's Excavation eingetroffen seid, um Sprengpulver abzuliefern. Da der Wagen schwer mit Fässern beladen ist, weiß Jern, dass sie nur langsam auf der südlichen Straße entlang des Lochs vorankommen werden. Er schickt Euch voraus, damit Ihr sie einholen und bei der lebenswichtigen Lieferung behilflich sein könnt.",al={"jern hornhelm motiv","warum huldar einholen","warum schickt jern euch"}}},fp="26,264,29.503.0,24.444.1,48.166.0,40.167.0,42.201.0,28.159.1,39.159.1,43.107.1"}
P.entries["quest:274"] = {n="Eine dunkle Bedrohung",s="Nach der Entdeckung von verdächtigem Pulver am Der Steinwerkdamm identifiziert Ashlan Schmunzelstein in Dun Modr die Substanz als instabiles Seaforyum. Da das Pulver bei Kontakt mit Wasser katastrophale Zerstörungen anrichten kann, stellt es eine unmittelbare Gefahr für die Region und das nahegelegene Zwergenreich dar. Schmunzelstein braut eine Entschärfungspaste zusammen und sendet eine Nachricht an Chefingenieur Hinderweir VII., um die Katastrophe abzuwenden.",h="Nach der Entdeckung von verdächtigem Pulver am Der Steinwerkdamm identifiziert Ashlan Schmunzelstein in Dun...",kw={"ashlan schmunzelstein","sprengpulver","chefingenieur hinderweir vii.","eine dunkle bedrohung","entschärfungspaste","eisenschmiede","seaforyum","sumpfland"},ang={["faction:Alliance"]="Verteidiger der Allianz müssen schnell handeln, um Chefingenieur Hinderweir VII. zu unterstützen und das Tiefland zu sichern, bevor feindliche Saboteure die strategische Infrastruktur zerstören.",["profession:Engineering"]="Ingenieure werden Seaforyum als eine äußerst wirkungsvolle flüchtige Verbindung erkennen, die eine vorsichtige Handhabung und präzise chemische Gegenmaßnahmen erfordert, um massive Schockwellen zu vermeiden.",["race:Dwarf"]="Für die Zwerge von Khaz Modan ist der Gedanke an explosive Saboteure, die flüchtiges Seaforyum nahe dem Tor zu Dun Morogh und Eisenschmiede einsetzen, eine existenzielle Bedrohung."},sec={{t="Eine flüchtige Entdeckung",b="Bei der Untersuchung der Proben, die vom Der Steinwerkdamm gebracht wurden, erkennt Ashlan Schmunzelstein sofort die verräterischen Silberkristalle und den unverwechselbaren Geruch von Seaforyum. Während es unter trockenen Bedingungen träge ist, reagiert Seaforyum heftig auf Feuchtigkeit – eine erschreckende Realität für einen Damm, der die Wasser des Loch Modan zurückhält. Ashlan warnt, dass eine unkontrollierte Explosion einer solchen Verbindung Eisenschmiede aus dem Berg sprengen könnte."},{t="Ein Wettlauf gegen die Zeit",b="Um den flüchtigen Sprengstoff zu neutralisieren, stellt Schmunzelstein eine spezielle Entschärfungspaste her. Die Neutralisierung der Reaktion erfordert eine spezifische chemische Mischung: die Paste kombiniert mit Lauerergift, zermahlenem Kristall der Mo'grosh und der Krokiliskenträne. Die Zeit drängt und Chefingenieur Hinderweir VII. muss sofort gewarnt werden, bevor Feuchtigkeit die Katastrophe auslöst."}},faq={{q="Welche Art von Sprengstoff wurde im Sumpfland gefunden?",a="Ashlan Schmunzelstein identifiziert die geheimnisvolle Substanz als Seaforyum-Pulver, das durch markante Silberkristalle und einen stechenden chemischen Geruch gekennzeichnet ist.",al={"welches pulver ist das","was ist das pulver","seaforyum-pulver"}},{q="Warum ist Seaforyum hier so gefährlich?",a="Seaforyum ist relativ harmlos, solange es trocken gelagert wird, löst aber bei Kontakt mit Wasser eine katastrophale Explosion aus – was den Der Steinwerkdamm, der die Wasser des Loch Modan zurückhält, zu einem außerordentlich gefährlichen Ort dafür macht.",al={"warum ist seaforyum gefährlich","was bringt seaforyum zur explosion"}},{q="Wer ist Ashlan Schmunzelstein?",a="Ashlan Schmunzelstein ist ein zwergischer Spezialist der Allianz, der im Sumpfland lebt und über das technische und chemische Fachwissen verfügt, um mysteriöse Pulver zu analysieren und Neutralisatoren herzustellen.",al={"wer ist ashlan","identität von ashlan schmunzelstein"}},{q="Wer ist Chefingenieur Hinderweir VII.?",a="Chefingenieur Hinderweir VII. beaufsichtigt technische und sicherheitsrelevante Angelegenheiten in der Region und operiert vom Der Steinwerkdamm in Loch Modan aus, um die zwergische Infrastruktur zu warten und zu schützen.",al={"wer ist hinderweir","chefingenieur hinderweir"}},{q="Wie kann das Seaforyum neutralisiert werden?",a="Die Entschärfung der chemischen Reaktion erfordert die Kombination von Ashlans Entschärfungspaste mit drei seltenen lokalen Zutaten: Lauerergift, einem zermahlenen Kristall der Mo'grosh und einer Krokiliskenträne.",al={"wie entschärft man seaforyum","rezept zur seaforyum-entschärfung","rezept für entschärfungspaste"}},{q="Was ist die Gefahr für Eisenschmiede?",a="Ashlan warnt, dass eine unkontrollierte Detonation des Sprengstoffs in den umliegenden Gebirgssystemen zu verheerenden seismischen Schäden führen könnte, die in der Lage sind, Eisenschmiede direkt aus dem Berg zu sprengen.",al={"ist eisenschmiede in gefahr","wie wird eisenschmiede bedroht"}}},fx={["7e9e3f07"]={q="Warum will Ashlan Schmunzelstein, dass dies erledigt wird?",a="Ashlan erkannte, dass es sich bei der mysteriösen Substanz nicht um gewöhnliches Sprengpulver, sondern um instabiles Seaforyum handelt. Sobald Seaforyum mit Wasser in Berührung kommt, könnte seine Explosionskraft ganze Berge zum Einsturz bringen. Ashlan muss Chefingenieur Hinderweir VII. unverzüglich warnen, damit die zwergischen Ingenieure eine neutralisierende Lösung vorbereiten können, bevor die instabile Verbindung detoniert.",al={"warum schickt ashlan euch","ashlan motiv","warum hinderweir warnen"}}},fp="19,418,20.406.0,16.364.1,49.136.0,35.224.0,25.193.0,37.188.0,37.175.0,32.193.0"}
P.entries["quest:2745"] = {n="Eindringen ins Schloss",s="Käsemeister und Informationshändler Elling Trias schickt Euch zum königlichen Sitz in Burg Sturmwind. Euer Ziel ist es, Euch mit seinem Mitstreiter Tyrion zu treffen, der den korrupten Adligen Lord Gregor Lescovar seit Wochen aus den Gärten der Burg beobachtet.",h="Käsemeister und Informationshändler Elling Trias schickt Euch zum königlichen Sitz in Burg Sturmwind.",kw={"käseladen","defias","elling trias","infiltrating the castle","lescovar","burg sturmwind","tyrion"},ang={["class:Rogue"]="Die Infiltration des Sitzes des Adels der Menschen zur Unterstützung zweier erfahrener Agenten des Untergrunds verdeutlicht das unauffällige, tödliche Handwerk, das nötig ist, um Sturmwind vor Schatten am eigenen Hof zu schützen.",["faction:Alliance"]="Da König Varian verschollen ist, kann sich das Königreich keinen Verrat in seiner höchsten gesetzgebenden Kammer leisten; die Verschwörer in der Burg auszumerzen, ist von entscheidender Bedeutung, um das Reich stabil zu halten.",["race:Gnome"]="Dass Tyrion eine so intensive, langfristige verdeckte Überwachungsoperation in Burg Sturmwind durchführt, beweist, dass der Einfallsreichtum der Gnome weit über Mechanik hinaus bis in die riskante Spionage reicht."},sec={{t="Eine Angelegenheit außerhalb des Gesetzes",b="Als Ihr Eure Erkenntnisse zu Elling Trias in seinen Käseladen im Handelsdistrikt bringt, begreift er rasch den Ernst der Defias-Bedrohung, die sich tief in der Führung des Königreichs eingenistet hat. Auf legalem Weg wird es nicht gelingen, jemanden zu entlarven oder zu bestrafen, der so tief verwurzelt und geschützt ist wie Lord Gregor Lescovar. Trias schlägt einen gefährlichen Ausweg vor: die Vollstreckung außergerichtlicher Gerechtigkeit direkt innerhalb der Mauern von Burg Sturmwind, um die Verschwörung endgültig zu zerschlagen."},{t="Augen im Gebüsch",b="Trias arbeitet in den hohen Hallen nicht allein. Seit Wochen überwacht ein Agent namens Tyrion – ein geschickter, in der Tarnung geübter Gnom – die Innenhöfe und gepflegten königlichen Gärten der Burg. Tyrion hat Lescovars Schritte beobachtet und festgehalten, wer seine Gemächer betritt und wann der Verräter sich mit seinen heimlichen Defias-Kontakten berät. Tyrion zu erreichen, ohne das Misstrauen der königlichen Wache zu wecken, ist das entscheidende nächste Glied in der Kette."},{t="Verrat am Hofe",b="Dass ein hoher Adliger wie Lescovar direkt mit Defias-Attentätern wie Marzon the Silent Blade unter einer Decke steckt, unterstreicht, wie verfault Sturmwinds politischer Kern in der Abwesenheit von König Varian Wrynn geworden ist. Während Adlige am Hofe die Geschehnisse von innen manipulieren und Gesetzlose von Westfall und dem Rotkammgebirge aus gegen die Grenzen drängen, ist der Schlag gegen Lescovar der Versuch, ein schwelendes Geschwür herauszuschneiden, bevor das Königreich vollends zerbricht."}},faq={{q="Warum möchte Elling Trias diese Angelegenheit außerhalb des Gesetzes regeln?",a="Lord Lescovar verfügt im Haus der Adligen über immensen Einfluss und großen Wohlstand. Gewöhnliche juristische Anschuldigungen gegen einen hochrangigen Lord ohne unumstößliche, politisch verheerende Beweise vorzubringen, würde sehr wahrscheinlich dazu führen, dass die Beweise unterschlagen und die Informanten hingerichtet werden. Trias erkennt, dass ein direktes, heimliches Vorgehen der einzige verlässliche Weg ist, um die Bedrohung auszuschalten.",al={"warum außerhalb des gesetzes","trias illegale gerechtigkeit","warum selbstjustiz"}},{q="Wo versteckt sich Tyrion?",a="Tyrion hält sich in den königlichen Gärten von Burg Sturmwind versteckt, gleich links neben dem Innenhof, nachdem man durch die Haupttore gegangen ist. Er lauert in den Büschen, um Lord Lescovars Quartiere zu beobachten, ohne die Wachen zu alarmieren.",al={"wo ist tyrion","tyrion finden","tyrion aufenthaltsort"}},{q="Wer ist Tyrion?",a="Tyrion ist ein verdeckter Ermittler und ein vertrauter Partner von Elling Trias. Er hat mehrere Wochen damit verbracht, Burg Sturmwind auszuspähen, um Lord Gregor Lescovar zu überwachen und dessen heimliche Defias-Verbindungen aufzudecken.",al={"wer ist tyrion","tyrion gnom","trias freund"}},{q="Wer ist Lord Lescovar?",a="Lord Gregor Lescovar ist ein einflussreicher Adliger aus Sturmwind, der insgeheim mit die Bruderschaft der Defias zusammenarbeitet und als deren hochrangiger Informant fungiert, um das Königreich aus dem Inneren seines königlichen Hofes heraus zu sabotieren.",al={"lord lescovar","wer ist lescovar","lescovar defias"}},{q="Wer ist Marzon?",a="Marzon, bekannt als the Silent Blade, ist ein Elite-Attentäter der Defias, der direkt mit Lord Lescovar in Verbindung steht, um Angriffe und Morde im Namen der Bruderschaft zu koordinieren.",al={"marzon","marzon the silent blade","silent blade"}},{q="Warum sorgt sich Tyrion um seinen Ruf?",a="Abgesehen davon, dass seine Tarnung bei der verdeckten Überwachung auffliegen könnte, beklagt sich Tyrion sarkastisch darüber, wie verdächtig und unziemlich es wirkt, wenn schwer bewaffnete Abenteurer direkt unter den Augen der Burgwachen neben ihm im königlichen Gebüsch herumlungern.",al={"tyrion versteckt büsche","ruf in den büschen"}}},fx={ae2213ef={q="Hinter wem seid Ihr in Burg Sturmwind her?",a="Elling Trias schickt Euch, um Euch um Lord Gregor Lescovar und seinen Komplizen Marzon zu kümmern. Lescovar ist ein Adliger, der direkt in der Burg Sturmwind agiert und wegen Hochverrats verdächtigt wird, während Marzon die gefährlichen Verschwörer außerhalb der Burgmauern vertritt. Trias und sein Kontakt Tyrion wollen beide Männer ausschalten, bevor ihre Umtriebe das Reich bedrohen können.",al={"wen zielen wir ab","wer ist das ziel bei infiltrating the castle","wer sind lescovar und marzon"}},["7d59c2b3"]={q="Warum schickt Elling Trias Euch, anstatt die Stadtwache von Sturmwind zu benutzen?",a="Lord Lescovar ist ein hochrangiger Adliger in der Burg Sturmwind, was eine offizielle Anschuldigung ohne unbestreitbare Beweise politisch unmöglich macht. Die Stadtwache untersteht dem Hof, wo der Adel das Sagen hat, und die Einschaltung offizieller Kanäle würde Lescovar wahrscheinlich warnen oder die Angelegenheit im bürokratischen Dschungel begraben. Trias verlässt sich auf einen unabhängigen Abenteurer, der sich einschleichen, sich mit Tyrion treffen und entschlossen Gerechtigkeit üben kann, ohne die Verschwörer zu warnen.",al={"warum mich schicken","warum nicht die wachen informieren","warum nicht sturmwindwachen"}}},fp="23,270,24.446.0,21.424.0,20.452.1,56.365.0,23.224.0,14.203.0,21.197.0,14.173.1,43.257.0"}
P.entries["quest:2746"] = {n="Nicht unwichtige Gegenstände",s="Um seinen mechanischen Spion in Burg Sturmwind einzuschleusen und Lord Lescovar zu belauschen, verlangt der verdeckte Ermittler Tyrion nach einer sehr spezifischen Auswahl an Verkleidungsmaterialien. Ihr müsst feine Seide und knackige Äpfel von der Obstplantage beschaffen, um eine bizarre Tarnidentität zusammenzustellen, die unbemerkt an den königlichen Wachen vorbeikommt.",h="Um seinen mechanischen Spion in Burg Sturmwind einzuschleusen und Lord Lescovar zu belauschen, verlangt der...",kw={"clara","elling trias","eindringen ins schloss","lord lescovar","seidenstoff","spybot","burg sturmwind","the attack","tyrion"},ang={["class:Rogue"]="Die Zusammenarbeit mit Agenten wie Tyrion und Elling Trias verdeutlicht die unkonventionellen Überwachungsmethoden des SI:7 und zeigt, wie die Inlandsaufklärung direkt vor den Augen der Adligen operiert.",["faction:Alliance"]="Der Schutz des jungen Königs Anduin und von Hochlord Bolvar Fordragon erfordert es, korrupte Aristokraten auszumerzen, die mitten in Burg Sturmwind mit Gesetzlosen paktieren.",["profession:Tailoring"]="Tyrions improvisierter Plan erfordert echten Seidenstoff und erinnert Schneider daran, dass feine Textilien für verdeckte Intrigen ebenso unverzichtbar sind wie für festliche Gewänder."},sec={{t="Ein knapper Zeitplan",b="Eine Nachricht des Käsehändlers Elling Trias hat die Operationen gegen Lord Gregor Lescovar beschleunigt. In dem Verdacht, dass die Machenschaften des Adligen innerhalb von Burg Sturmwind eine unmittelbare Gefahr für das Reich darstellen, bestand Trias darauf, den Zeitplan vorzuziehen. In den Gärten von Burg Sturmwind versteckt willigt Tyrion ein, den Einsatz voranzutreiben, beharrt jedoch darauf, dass das Beschaffen der richtigen Infiltrationsausrüstung sorgfältige Vorbereitung erfordert."},{t="Die Kunst der Verkleidung",b="Tyrions Plan stützt sich auf ein unkonventionelles Hilfsmittel: Spybot, eine kleine mechanische Vorrichtung, die an den wachsamen Schlosswachen vorbeischlüpfen soll, um Lescovar im Inneren der Feste zu erreichen. Anstatt sich auf bloße Heimlichkeit zu verlassen, konstruiert Tyrion eine bizarre weibliche Verkleidung, um jeden Verdacht abzuwenden. Um dieses Täuschungsmanöver zu vollenden, schickt er Agenten zu Claras Obstplantage direkt vor den Stadtmauern, um Äpfel von passender Größe zu besorgen, während er Ballen aus Seidenstoff verlangt, um die Gewänder der Puppe zu schneidern."},{t="Verrat aufdecken",b="Tyrion offenbart, dass seine anfängliche Überwachung von Lord Lescovar gar nicht mit der Bruderschaft der Defias zusammenhing, sondern vielmehr mit verdächtigen Hinweisen, die den Adligen mit dem Schattenhammerkult in Verbindung brachten. Die Entdeckung, dass Lescovar aktiv mit Verschwörern der Defias kollaboriert, macht seine weitere Anwesenheit am königlichen Hof untragbar und verwandelt eine routinemäßige Überwachungsmission in einen hochriskanten Zugriff im Herzen des Königreichs."}},faq={{q="Warum braucht Tyrion Äpfel und Seidenstoff?",a="Tyrion fertigt eine eigenartige weibliche Verkleidung für seinen mechanischen Späher Spybot an, damit dieser unbemerkt an den königlichen Wachen in Burg Sturmwind vorbeischlüpfen kann. Die Seide wird zu behelfsmäßigen Gewändern geschneidert, während die Äpfel von Claras Hof für die nötigen Formen sorgen, um die Illusion zu vollenden.",al={"warum äpfel","wofür sind die äpfel","tyrion verkleidungsmaterialien","spybot verkleidung"}},{q="Für wen arbeitet Tyrion?",a="Tyrion arbeitet in Abstimmung mit Elling Trias, dem Käsehändler aus der Altstadt, der sein eigenes Netzwerk von Freunden in Sturmwind unterhält; Trias räumt ein, dass die Operation Mathias Shaw und dem SI:7 nur indirekt einen Gefallen tut.",al={"an wen berichtet tyrion","tyrion loyalität","elling trias tyrion"}},{q="Wo finde ich Claras Äpfel?",a="Claras Hof liegt direkt vor den Toren von Sturmwind im nördlichen Wald von Elwynn. Frische Äpfel können direkt auf ihrer bescheidenen Obstplantage gesammelt werden.",al={"clara hof standort","wo sind claras äpfel","frische äpfel sturmwind"}},{q="Wessen verdächtigte Tyrion Lord Lescovar ursprünglich?",a="Tyrion und Trias verfolgten anfangs Spuren, die darauf hindeuteten, dass Lord Lescovar Verbindungen zum finsteren Schattenhammerkult unterhielt. Die Aufdeckung seiner Zusammenarbeit mit der Bruderschaft der Defias bewies jedoch, dass sein Verrat weitaus tiefer reichte und eine unmittelbare Bedrohung für die Krone darstellte.",al={"lescovar schattenhammer","warum lescovar untersucht wurde","tyrion lescovar vergangenheit"}},{q="Was ist der nächste Schritt nach der Übergabe dieser Gegenstände?",a="Sobald Spybot vollständig ausgerüstet und in die Feste geschickt wurde, werdet Ihr in der Folgemission „Der Angriff!“ damit beauftragt, die Verschwörer direkt zu stellen und auszuschalten.",al={"was passiert als nächstes","nach nicht unwichtige gegenstände","folgequest nach nicht unwichtige gegenstände"}},{q="Warum wird ein mechanischer Spybot verwendet, anstatt sich persönlich einzuschleichen?",a="Burg Sturmwind wird streng von königlichen Wachen bewacht, die jeden mustern, der den Thronsaal und die privaten Innenhöfe betritt. Als Priesterin verkleidet kann Spybot an den Wachen vorbeigehen und Lescovar direkt ansprechen, um ihn in den Garten zu locken, damit er dort Marzon trifft – an einen Ort, an den kein bekannter Agent unbemerkt herankommen könnte.",al={"warum spybot nutzen","warum nicht selbst hineinschleichen","burg sturmwind sicherheit"}}},fx={["7ec9a91a"]={q="Warum will Tyrion Lord Lescovar zu Fall bringen?",a="Tyrion und sein Mitarbeiter Elling Trias verfolgen Lord Lescovar seit Wochen, da der Verdacht auf subversive Verbindungen besteht. Während sie ursprünglich mögliche Verbindungen zum Kultisten des Schattenhammers untersuchten, macht die Entdeckung, dass Lescovar aktiv mit The Defias Brotherhood konspiriert, ihn zu einer unmittelbaren und ernsten Gefahr für Sturmwind. Tyrion beabsichtigt, ihn zu entlarven und zu neutralisieren, bevor sein Verrat die Stadt zerreißen kann.",al={"warum lescovar stoppen","tyrion motiv","warum lescovar untersuchen"}},["73f45f0b"]={q="Warum braucht Tyrion die Hilfe eines Außenstehenden anstelle der Stadtwachen?",a="Lord Lescovar ist ein Adliger innerhalb der Burg Sturmwind, was eine offene Anschuldigung oder einen direkten Eingriff der Wache ohne unbestreitbare Beweise unmöglich macht. Die Behörden von Sturmwind sind nicht in der Lage, aufgrund von Vermutungen gegen einen hochrangigen Adligen vorzugehen. Tyrion operiert im Schatten im Auftrag von Meister Trias und benötigt einen unabhängigen Agenten, der bereit ist, geheime Vorräte zu sammeln und schließlich die gefährliche, verdeckte Konfrontation persönlich zu führen.",al={"warum nicht stadtwachen","warum braucht tyrion mich","warum auf abenteurer verlassen"}}},fp="25,301,21.425.0,23.479.0,18.415.1,43.293.0,26.209.0,31.150.0,58.253.1,51.173.1,62.299.0"}
P.entries["quest:275"] = {n="Schwärendes Land",s="Schwärendes Land ist eine Quest der Allianz, die von Rethiel dem Sumpfhüter entlang der östlichen Bergrücken des Sumpflands angeboten wird. Da er spürt, wie eine unnatürliche Krankheit den Sumpf aufwühlt, beauftragt der einsame Sumpfbestienhüter Reisende damit, die erkrankten Fen Creeper zu dezimieren, die die Wasserläufe durchstreifen. Diese schlurfenden Pflanzengreuel zur Ruhe zu betten ist Rethiels Versuch, das steigende Fieber des Sumpfes zu brechen.",h="Schwärendes Land ist eine Quest der Allianz, die von Rethiel dem Sumpfhüter entlang der östlichen Bergrücken...",kw={"schwärendes land","fen creeper","der sumpfhüter","die marschen","rethiel","moore im sumpfland","sumpfland"},ang={["class:Druid"]="Rethiels Mission spiegelt direkt die druidische Pflicht wider, die natürliche Welt zu heilen, indem aufgewühlte elementare Plagen beseitigt werden, damit die Erde wieder ins Gleichgewicht finden kann.",["class:Shaman"]="Die Fen Creeper stellen verzerrte Manifestationen von Erde und Wasser dar, was ihre Vernichtung zu einem Akt der Besänftigung disharmonischer Elementargeister macht.",["race:NightElf"]="Das Auffinden eines einsamen Sumpfbestienhüters, der in den Östlichen Königreichen mit Sturmwind verbündet ist, zeigt, dass selbst die Geister des Landes Hilfe suchen, um verwundeten Boden zu heilen."},sec={{t="Schwelende Marschen",b="Von seinem Hain inmitten der Marschen aus wacht Rethiel der Sumpfhüter über die feuchte Weite des Sumpflands. Die Marschen waren noch nie sanftmütig, doch kürzlich hat begonnen, sich eine unnatürliche Krankheit durch den Morast auszubreiten. Rethiel nimmt dieses Leiden als ein wachsendes Fieber in der Erde selbst wahr, das die wilde Natur dazu bringt, sich zu geistlosen, schlurfenden Monströsitäten zu verzerren."},{t="Die Reinigung des Moores",b="Das Hauptsymptom dieser Fäulnis ist das Aufkommen von Fen Creepern – verfallenden elementaren Massen aus Sumpfvegetation, die entlang der Wasserwege schlurfen. Rethiel beschreibt sie als krankhafte Blasen, die auf der Oberfläche des Landes anschwellen. Da ihre gequälte Existenz nur Unruhe im Moor verbreitet, beauftragt der Sumpfhüter vorbeiziehende Verbündete damit, sie zu vernichten, damit ihre verflochtenen Überreste harmlos zurück in den Schlamm sinken können."}},faq={{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel der Sumpfhüter ist eine Sumpfbestie, die im Greenwarden's Grove im östlichen Sumpfland residiert. Er widmet sich der Pflege des natürlichen Gleichgewichts der Marschen und versucht, die Leiden des Landes zu lindern und verderbte elementare Wucherungen einzudämmen.",al={"wer ist rethiel","rethiel der sumpfhüter lore","wer gibt schwärendes land"}},{q="Was sind Fen Creeper?",a="Fen Creeper sind feindselige Pflanzen- und Sumpfelementare, die die Wasserläufe des Sumpflands durchstreifen. Sie erscheinen als gewaltige, schlurfende Massen aus belebten Ranken, Schlamm und verfallender Sumpfflora.",al={"fen creeper","was ist ein fen creeper","creeper sumpfland"}},{q="Warum möchte Rethiel, dass die Fen Creeper vernichtet werden?",a="Rethiel sieht die Fen Creeper als fieberhafte, krankhafte Ausprägungen der wachsenden Fäulnis des Sumpfes an. Er glaubt, dass ihre Vernichtung es ihrer Gestalt erlaubt, sich aufzulösen und wieder in der Erde zur Ruhe zu kommen, was das aufgewühlte Land beruhigt.",al={"warum fen creeper töten","warum schwärendes land"}},{q="Was verursacht das Schwären im Sumpfland?",a="Rethiel gibt zu, dass er nicht genau weiß, was das Schwären im Sumpfland verursacht. Er spürt schlicht die weinende Not des Landes und behandelt die Symptome, indem er unruhige Elemente besänftigt, wo immer sie aufbranden.",al={"warum ist das sumpfland erkrankt","ursache der krankheit im sumpfland"}},{q="Wo sind Fen Creeper im Sumpfland zu finden?",a="Fen Creeper streifen entlang der feuchten Wasserläufe, schlammigen Ufer und zentralen Flussarme umher, die das Sumpfland durchziehen, insbesondere in der Nähe der tieferen Moore westlich von Greenwarden's Grove.",al={"orte fen creeper","wo fen creeper finden"}},{q="Steht diese Quest mit anderen Aufgaben für Rethiel in Verbindung?",a="Ja. Schwärendes Land knüpft an Rethiels Sorgen bezüglich der Mosshide-Gnolle an, die in Feuer-Tabu die Bäume des Sumpflands verbrennen, und dient als Teil seiner fortwährenden Bemühungen, das Gleichgewicht des Sumpfes zu schützen.",al={"sumpfhüter questreihe","rethiel quests"}}},fp="20,377,19.363.0,17.427.0,31.249.0,22.183.0,49.222.0,42.213.0,45.172.0,51.201.0"}
P.entries["quest:2751"] = {n="Barbarische Waffenschmiedekunst",s="Barbarische Waffenschmiedekunst ist die einleitende Prüfung von Orokk Omosh, einem alternden Schmied in Orgrimmar, der verzweifelt versucht, das Vermächtnis seiner Ahnen zu bewahren. Da er keine Erben hat, verlangt Orokk von einem aufstrebenden Schmied, grundlegende Meisterschaft über Bronze und elementare Handwerkskunst zu beweisen, bevor er die Geheimnisse seines Handwerks offenbart.",h="Barbarische Waffenschmiedekunst ist die einleitende Prüfung von Orokk Omosh, einem alternden Schmied in...",kw={"barbarische waffenschmiedekunst","schmiedekunst","bronze","vermächtnis","omosh","orgrimmar","orokk omosh"},ang={["faction:Horde"]="Das Vermächtnis der Omosh spiegelt das kriegerische Ethos der Horde wider: Metallarbeiten sind dazu bestimmt, im Kampf erprobt und mit dem Blut von Feinden getränkt zu werden.",["profession:Blacksmithing"]="Für Schmiede der Horde stellt diese Aufgabe einen wichtigen Meilenstein beim Übergang von elementaren Bronze- und Kupferarbeiten zu fortgeschritteneren Rüstungstraditionen dar."},sec={{t="Das Ende der Omosh-Blutlinie",b="Orokk Omosh steht an den Ambossen von Orgrimmar und trägt eine schwere Bürde. Seit zwanzig Generationen hat seine Familie an der Esse gearbeitet und zahllose Tonnen Erz zu verheerenden Waffen und robuster Rüstung für die Horde geformt. Tragischerweise betrachtet Orokk sich selbst als das persönliche Versagen seiner Blutlinie, da er kinderlos ist und keine Nachkommen zeugen kann. Angesichts des endgültigen Aussterbens des Omosh-Handwerks hat er beschlossen, den Stolz auf seine Abstammung beiseitezulegen und nach einem Lehrling zu suchen, der fähig ist, die Waffenschmiedetraditionen seiner Familie fortzuführen."},{t="Eine Prüfung aus Metall und Zahn",b="Orokk weigert sich, seine Geheimnisse an einen Dilettanten weiterzugeben. Um ihre grundlegende Kompetenz am Amboss zu beweisen, verlangt er zwei gemusterte Bronzearmschienen, zwei Bronzegroßschwerter und ein Paar scharfe Bestienklauen. Für Orokk ist wahre Schmiedekunst kein Handwerk für müßigen Luxus; ihre höchste Ehre besteht darin, Rüstung und Stahl im Blut von Feinden gebadet zu sehen. Die Erfüllung seiner Forderungen überzeugt den alten Schmied davon, dass das Erbe seiner Linie im Geiste fortbestehen könnte, und öffnet das Tor zu fortgeschritteneren Metallverarbeitungstechniken."}},faq={{q="Wer ist Orokk Omosh?",a="Orokk Omosh ist ein Meisterschmied, der in Orgrimmar lebt. Er repräsentiert die zwanzigste Schmiedegeneration der Omosh-Linie, doch da es ihm an Verwandten oder Erben fehlt, ist er entschlossen, einen Außenstehenden auszubilden, anstatt die Berufsgeheimnisse seines Clans verloren gehen zu lassen.",al={"orokk omosh","wer ist orokk","omosh schmied"}},{q="Warum muss Orokk jemand anderen unterrichten?",a="Orokk kann keine Nachkommen zeugen und hat keine überlebenden Verwandten, die seine Werkstatt erben könnten. Ohne einen Lehrling, an den er seine Baupläne und Techniken weitergeben kann, würden zwanzig Generationen mühsam erworbenen Schmiedewissens mit ihm sterben.",al={"warum lehrling","orokk erbe","warum omosh vermächtnis stirbt"}},{q="Welche Gegenstände sind erforderlich, um Orokk Kompetenz zu beweisen?",a="Orokk verlangt zwei gemusterte Bronzearmschienen, zwei geschmiedete Bronzegroßschwerter und zwei scharfe Klauen von wilden Raubtieren.",al={"was brauche ich für barbarische waffenschmiedekunst","gegenstände für barbarische waffenschmiedekunst","barbarische waffenschmiedekunst abgabe"}},{q="Was folgt nach dem Abschluss von Barbarische Waffenschmiedekunst?",a="Zufrieden mit Eurer grundlegenden Meisterschaft über Bronze setzt Orokk Eure Ausbildung mit 'On Iron Pauldrons' fort und schreitet zum Schmieden von schwererem Eisen sowie komplexer Plattenrüstung voran.",al={"folgequest","questreihe nach barbarische waffenschmiedekunst","was folgt"}}},fx={["2a7cea14"]={q="Warum benötigt Orokk die Musterverzierten Bronzearmschienen, die Bronzegroßschwerter und die Scharfen Klauen?",a="Orokk Omosh sucht einen würdigen Lehrling, der das heilige Schmiede-Erbe seiner Familie fortführen kann. Anstatt die Waffen in Dienst zu stellen, verlangt er die Musterverzierten Bronzearmschienen, Bronzegroßschwerter und Scharfen Klauen als Geschicklichkeitstest. Ihm diese fein gearbeiteten Bronzeartikel zusammen mit rohen Bestientrophäen zu bringen, beweist, dass Ihr über die Disziplin, das technische Können und die raue Stärke verfügt, die erforderlich sind, um die geheimen Rezepte des Clans Omosh zu erlernen.",al={"wofür sind die gegenstände","warum musterverzierte bronzearmschienen","warum bronzegroßschwerter scharfe klauen"}}},fp="20,304,25.511.0,25.482.0,19.248.0,42.214.0,53.130.0,49.178.0"}
P.entries["quest:2753"] = {n="In den Boden getrampelt",s="In den Boden getrampelt ist eine fortgeschrittene Schmiedeprüfung, die von Orokk Omosh im Tal der Ehre in Orgrimmar vergeben wird. Durch das Schmieden einer Reihe von Rüstungsteilen aus grünem Eisen beweisen Schmiede ihre Ausdauer und meistern das Handwerk schwerer Eisenstiefel. Der Abschluss der Aufgabe bringt die geheimen Techniken ein, die in der Blutlinie der Omosh weitergegeben werden.",h="In den Boden getrampelt ist eine fortgeschrittene Schmiedeprüfung, die von Orokk Omosh im Tal der Ehre in...",kw={"rüstungsschmiedekunst","schmiedekunst","gorokk","grünes eisen","orgrimmar","orokk omosh","in den boden getrampelt","tal der ehre"},ang={["faction:Horde"]="Orokks Lektionen liefern widerstandsfähige Eisenrüstungsbaupläne, die auf die an den Kriegsfronten der Horde bevorzugte, brutale Kampfdoktrin zugeschnitten sind.",["profession:Blacksmithing"]="Diese Quest stellt einen wichtigen Meilenstein für angehende Rüstungsschmiede der Horde dar und erfordert umfangreiches Eisenschmelzen sowie die Vorbereitung grüner Farbe, um exklusive Stiefelbaupläne freizuschalten."},sec={{t="Die Prüfungen der Omosh",b="Orokk Omosh bildet Rüstungsschmiede in Orgrimmar mit unerbittlichen, körperlichen Anforderungen aus. Für Orokk ist Metallbearbeitung nicht bloß das Erhitzen von Erz und das Hämmern von Formen; es ist ein Ausdauertest, der seinen angestammten Clan ehren soll. In den Boden getrampelt stellt die dritte Prüfung in seiner rigorosen Aufgabenkette dar und verlangt die wiederholte Herstellung gehärteter grüner Eisenrüstungen, um Muskeln und Disziplin des Handwerkers zu stählen."},{t="Das Erbe von Häuptling Gorokk",b="Schmiede, die die verlangten Rüstungsteile aus grünem Eisen abliefern, ernten seltenes Lob von dem schroffen Rüstungsschmied. Orokk vergleicht einen Handwerker, der diese zermürbende Arbeitslast übersteht, mit seinem Großvater, Häuptling Gorokk der Omosh. Im Austausch für die geschmiedete Rüstung vermittelt Orokk den überlieferten Bauplan für robuste Eisenstiefel – Schuhwerk, das dafür sorgen soll, dass die Krieger der Horde ihre Feinde unter ihren Fersen zermalmen."}},faq={{q="Wer bietet die Quest In den Boden getrampelt an?",a="Die Quest wird von Orokk Omosh vergeben, einem Orc-Rüstungsschmied im Tal der Ehre in Orgrimmar.",al={"questgeber","wer vergibt in den boden getrampelt","orokk omosh standort"}},{q="Was verlangt Orokk Omosh für diese Prüfung?",a="Orokk verlangt vier Green Iron Helms, vier Grüne Eisenarmschienen und zwei Grüne Eisengamaschen, um die Meisterschaft des Schmieds über die Handwerkskunst des grünen Eisens zu beweisen.",al={"in den boden getrampelt abgabe","welche gegenstände benötigt","benötigte materialien"}},{q="Welche Lore steckt hinter der Omosh-Ausbildungsreihe?",a="Orokk Omosh prüft junge Schmiede durch zermürbende körperliche Arbeit, um das kriegerische Erbe seiner Vorfahren aufrechtzuerhalten. Er glaubt, dass harte Rüstungsschmiedekunst die nötige Stärke verleiht, um Ausrüstung zu schaffen, die brutaler Kriegsführung standhält.",al={"warum lässt orokk rüstung schmieden","omosh clan lore"}},{q="Wer ist Häuptling Gorokk der Omosh?",a="Häuptling Gorokk der Omosh ist der Großvater von Orokk Omosh. Orokk schätzt das kriegerische Können seines Großvaters sehr und vergleicht jeden Schmied, der seine schweren Eisenarbeitsprüfungen besteht, mit dem legendären Häuptling.",al={"häuptling gorokk","orokk großvater"}},{q="Welche Quest geht In den Boden getrampelt voraus?",a="In den Boden getrampelt folgt direkt auf die Quest On Iron Pauldrons und setzt Orokks mehrteilige Reihe von Rüstungsschmiede-Herausforderungen fort.",al={"vorherige quest","vorherige quest in der reihe"}},{q="Was ist die nächste Quest nach dem Abschluss von In den Boden getrampelt?",a="Nach Abschluss dieser Aufgabe bietet Orokk Omosh Horns of Frenzy an, die nächste seiner zwei verbleibenden Lektionen, bevor die Reihe mit Freude der Omoshs endet.",al={"nächste quest","was kommt nach in den boden getrampelt"}}},fx={["454b7030"]={q="Warum will Orokk Omosh diese grünen Eisenteile geschmiedet haben?",a="Orokk Omosh bildet Euch in den brutalen Schmiedetraditionen seiner Blutlinie aus. Er glaubt, dass wahre Krieger und Schmiede qualvolle Arbeit ertragen müssen, um Ausrüstung zu schmieden, die den Namen Omosh verdient. Indem er Euch mehrere Helme, Armschienen und Gamaschen aus schwerem grünem Eisen hämmern lässt, testet er sowohl Eure körperliche Ausdauer als auch Euer Handwerk und bereitet Euch darauf vor, das Wissen über das Schmieden kampferprobter Stiefel freizuschalten.",al={"orokk omosh motiv","warum grünes eisen schmieden","warum will orokk das"}},["9ced7653"]={q="Wofür ist der Grüne Eisenhelm?",a="Die Grüne Eisengamaschen dienen als ein Teil von Orokks zermürbendem Test für Handwerkskunst und Ausdauer. Von Eurer eigenen Hand geschmolzen und gehämmert, beweisen sie dem Schmied, dass Ihr die präzise Metallurgie und die rohe körperliche Ausdauer besitzt, die erforderlich sind, um schwere Schutzausrüstung für die Omosh-Tradition herzustellen.",al={"grüner eisenhelm zweck","warum grüner eisenhelm","nutzen von grünem eisenhelm"}},ae72eea8={q="Wofür sind die Grünen Eisenarmschienen?",a="Diese Armschienen beweisen Eure Fähigkeit, unter der strengen Anleitung von Orokk Omosh stabilen und zuverlässigen Gliedmaßenschutz zu schmieden. Die Abgabe von vier ordnungsgemäß gefertigten Paaren beweist, dass Eure Schmiedekünste zuverlässig Krieger für die bevorstehenden wilden Schlachten ausrüsten können.",al={"grüne eisenarmschienen zweck","warum grüne eisenarmschienen","nutzen von grünen eisenarmschienen"}},["9872ef5a"]={q="Wofür sind die Grünen Eisengamaschen?",a="Die Gamaschen erfordern große Mengen an bearbeitetem Eisen und diszipliniertes Schmiedehandwerk. Die Bereitstellung von zwei gut gefertigten Paaren beweist Orokk, dass Ihr es wert seid, die Geheimnisse der Herstellung mächtiger gepanzerter Stiefel zu erben und in die Fußstapfen seines Vorfahren Chef Gorokk zu treten.",al={"grüne eisengamaschen zweck","warum grüne eisengamaschen","nutzen von grünen eisengamaschen"}},f314d286={q="Warum braucht Orokk Omosh Euch, anstatt das Schmieden selbst zu erledigen?",a="Orokk sucht keine Lieferung von Rüstung für sich selbst; er testet und unterweist Euch. Als Ausbilder der alten Techniken seines Clans verlangt er, dass Eure eigenen Muskeln über dem Amboss schmerzen, um Eure Hingabe zu beweisen, bevor er die Entwürfe der Omosh teilt.",al={"warum ich orokk","warum braucht orokk mich","warum nicht selbst schmieden"}}},fp="19,326,19.394.0,22.381.0,41.101.0,45.150.0,49.229.0,29.204.0,40.131.0,60.143.0"}
P.entries["quest:2755"] = {n="Freude der Omoshs",s="Freude der Omoshs ist ein herzerwärmender Abschlussmoment zwischen dem Schmied Orokk Omosh und einem Abenteurer, der ihm in Orgrimmar geholfen hat. Zu Tränen gerührt beteuert der erfahrene Schmied, dass ihm bloß Ruß ins Auge geraten sei, bevor er eine geschätzte Familientradition vorführt. Indem er den energiegeladenen Omosh-Freudentanz vollführt, gibt er ein ungewöhnliches Stück Familienerbe weiter.",h="Freude der Omoshs ist ein herzerwärmender Abschlussmoment zwischen dem Schmied Orokk Omosh und einem...",kw={"schmied","freudentanz","freude der omoshs","orgrimmar","orokk omosh","russ im auge","tal der ehre"},ang={["faction:Horde"]="Das Tal der Ehre ist ein Zentrum kriegerischen Stolzes, was Orokks tränenreiche Freude und seinen temperamentvollen Tanz zu einem liebenswerten Anblick inmitten des klirrenden Stahls von Orgrimmar macht.",["profession:Blacksmithing"]="Für Schmiede, die an die raue, stoische Hitze der Esse gewöhnt sind, bietet Orokks gefühlvoller Familientanz einen ungewöhnlich humorvollen und feinfühligen Einblick in das Privatleben eines gestandenen Handwerkers."},sec={{t="Eine rußbefleckte Träne",b="Orokk Omosh ist ein stämmiger Schmied, der nahe der sengenden Hitze der Schmiede in Orgrimmar arbeitet und eher für wuchtige Schläge auf den Amboss als für emotionale Ausbrüche bekannt ist. Doch nachdem er große Hilfe von einem Abenteurer erhalten hat, ist selbst dieser raue Handwerker überwältigt. Er beharrt stur darauf, dass ihm nur ein verirrter Rußpartikel ins Auge gelangt sei, anstatt zuzugeben, offen zu weinen."},{t="Die Tradition der Omoshs",b="Anstatt stiller Wege zu gehen, besteht Orokk darauf, ein letztes Geheimnis der Omosh-Blutlinie zu teilen, bevor er glücklich sterben kann. Unverzüglich beginnt er mit dem schwungvollen und kräftezehrenden Omosh-Freudentanz und demonstriert die lebhafte Tradition für seinen Schützling, bevor er ihm beibringt, mit eiserner Faust zuzuschlagen."}},faq={{q="Wer ist Orokk Omosh?",a="Orokk Omosh ist ein Orc-Schmied im Tal der Ehre in Orgrimmar. Er ist ungemein stolz auf das Handwerk und die Herkunft seiner Familie und verbindet schmiedetechnisches Können mit lebhaften persönlichen Traditionen.",al={"wer ist orokk","orokk omosh hintergrundgeschichte","orokk schmied"}},{q="Warum weint Orokk?",a="Orokk beteuert, dass er nicht weint und dass es lediglich Schmiederuß in seinem Auge ist. In Wahrheit ist er zutiefst gerührt und ergriffen von der Hilfe des Abenteurers, da er jemanden gefunden hat, der es wert ist, die Traditionen seiner Familie mit ihm zu teilen.",al={"warum weint orokk","ist orokk traurig","russ im auge"}},{q="Was ist der Omosh-Freudentanz?",a="Der Freudentanz ist eine schwungvolle körperliche Darbietung, die in der Omosh-Familienlinie weitergegeben wird. Ihn auszuführen ist äußerst anstrengend für Orokk, der diesen festlichen Tanz schon sehr lange nicht mehr geübt hat.",al={"omosh tanz","freudentanz","was ist der tanz"}},{q="Wo findet diese Quest statt?",a="Die Quest findet in Orgrimmar statt, genauer gesagt an der Schmiede im Tal der Ehre, wo Orokk Omosh sein Metall bearbeitet.",al={"quest ort","wo ist freude der omoshs","orgrimmar schmiede"}},{q="Was bringt Orokk Euch bei?",a="Neben der Vorführung des energiegeladenen Omosh-Freudentanzes verspricht Orokk, das Wissen um die Faust aus Eisen weiterzugeben, was das Band zwischen Schmied und Abenteurer festigt.",al={"omosh belohnung","was lerne ich","faust aus eisen"}},{q="Können Allianz-Spieler an dieser Quest teilnehmen?",a="Nein. Orokk Omosh ist mit der Horde verbündet und lebt innerhalb der befestigten Mauern von Orgrimmar, wodurch diese Interaktion exklusiv für Abenteurer der Horde ist.",al={"allianz freude der omoshs","nur fuer horde"}}},fx={["371650ab"]={q="Warum will Orokk Omosh Euch den Tanz der Freude lehren?",a="Orokk ist überwältigt von Dankbarkeit für Eure Hilfe und möchte die letzte, streng gehütete Tradition seiner Blutlinie weitergeben. Indem er Euch den Omosh-Tanz der Freude lehrt, fühlt er, dass sein Vermächtnis geehrt wird und dass er endlich als glücklicher Orc sterben kann.",al={"warum tanz lehren","orokk omosh motiv","warum will orokk das"}}},fp="13,351,19.368.0,19.304.0,19.194.0,20.228.0,31.197.0,33.137.0,26.164.0,47.149.0"}
P.entries["quest:276"] = {n="Stapfende Pfoten",s="Stapfende Pfoten ist eine Allianz-Aufgabe, die von Rethiel dem Sumpfhüter bei Greenwarden's Grove im Sumpfland vergeben wird. Beunruhigt über die sprunghaft anwachsende Population der Mosshide-Gnolle nahe dem Gate of Algaz beauftragt der Sumpfbestien-Beschützer Abenteurer damit, deren Reihen zu lichten, bevor ihre Feuer und stapfenden Pfoten das Moor zugrunde richten.",h="Stapfende Pfoten ist eine Allianz-Aufgabe, die von Rethiel dem Sumpfhüter bei Greenwarden's Grove im...",kw={"algaz","gnolle","der sumpfhüter","mischlinge","mosshide","rethiel","stapfende pfoten","sumpfland"},ang={["class:Druid"]="Rethiels Mission spiegelt direkt den cenarischen Auftrag wider, das ökologische Gleichgewicht aufrechtzuerhalten und unnatürliche Populationsspitzen einzudämmen, damit das Moor nicht kollabiert.",["race:Dwarf"]="Da sich die Gnolle unmittelbar vor dem Gate of Algaz sammeln, schützt ihre Dezimierung nicht nur das Moor, sondern sichert auch die lebenswichtige Straße, die Eisenschmiede mit dem Hafen von Menethil verbindet.",["race:NightElf"]="Nachtelfen teilen uralte Bande mit den wilden Geistern der Natur, was Rethiels Flehen um die Heilung des Moors zu einer vertrauten und ehrenvollen Pflicht macht."},sec={{t="Eine wachsende Moorbedrohung",b="Viele Jahre lang bewohnten die Mosshide-Gnolle das Sumpfland, ohne dessen natürliche Ordnung vollends zu zerstören. In letzter Zeit jedoch ist ihre Rudelstärke nach Süden in Richtung des Passes von Dun Algaz explosionsartig gewachsen. Ihre schweren Stiefel und Pfotenabdrücke zertrampeln seltene Moorflora, und ihre grobe Abholzung rodet lebenswichtige Haine, um die Flammen ihrer Lagerfeuer zu nähren. Sich selbst überlassen drohen die anwachsenden Rudel die empfindliche Ökologie des Sumpfes zu schädigen."},{t="Das Urteil des Sumpfhüters",b="Rethiel der Sumpfhüter wacht über das Moor mit einem Blick für das Gleichgewicht statt für die Zivilisation. Für den Sumpfhüter liegt das Problem nicht darin, dass Gnolle existieren, sondern dass ihre überbordende Population das übersteigt, was das Sumpfland ertragen kann. Indem sie Mosshide-Gnolle und -Mischlinge wieder auf ein erträgliches Maß zurückdrängen, tragen Abenteurer zum Erhalt des Sumpflands bei und verdienen sich die zögerliche Anerkennung eines uralten Hüters der Wildnis."}},faq={{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel ist eine Sumpfbestie, die im Sumpfland entlang der Straße zwischen den Grenzen von Eisenschmiede und Arathi haust. Sie widmet sich dem Erhalt des Moors, überwacht die Gesundheit des Landes und beauftragt Reisende damit, zerstörerische Populationen im Zaum zu halten.",al={"rethiel lore","wer vergibt stapfende pfoten","der sumpfhüter sumpfland"}},{q="Warum sind die Mosshide-Gnolle jetzt ein Problem?",a="Während das Mosshide-Rudel einst mit dem Moor koexistierte, ohne langfristigen Schaden anzurichten, hat ihr jüngster Populationsboom zu massiver Abholzung für Feuerholz und weitverbreitetem Niedertrampeln der empfindlichen Moorflora geführt.",al={"warum gnolle töten sumpfland","mosshide-gnoll bedrohung"}},{q="Wo richten die Gnolle diesen Schaden an?",a="Die Mosshide-Gnolle und -Mischlinge rotten sich in großer Zahl im Süden des Sumpflands zusammen, insbesondere nahe dem Zwergenpass von Dun Algaz.",al={"wo sind mosshide-gnolle","stapfende pfoten ort"}},{q="Was folgt nach dem Ausdünnen der Gnolle?",a="Sobald die Rudel gelichtet sind, geht Rethiel der Ursache für ihre ungewöhnliche Aktivität und ihren Brennstoffverbrauch genauer auf den Grund und schickt Abenteurer auf die Folgequest 'Fire Taboo'.",al={"nächste quest nach stapfende pfoten","stapfende pfoten folgequest"}},{q="Warum erwähnt Rethiel, dass ihr Glaube auf die Probe gestellt wurde?",a="Rethiel erklärt Euch, dass ihr Glaube an Euer Volk in der Vergangenheit auf eine harte Probe gestellt wurde, und blickt mit Argwohn auf Sterbliche und deren rasche Ausbreitung. Wenn Ihr ihr helft, das wilde Moor zu schützen, beweist das, dass sterbliche Abenteurer als Bewahrer der Natur statt als Ausbeuter handeln können.",al={"rethiel dialog","glaube in der vergangenheit geprüft"}}},fx={["24db34f0"]={q="Wer sind die Mosshide-Gnolle, auf deren Jagd Ihr geschickt werdet?",a="Die Mosshide sind ein Gnollclan, der im Sumpfland beheimatet ist. Obwohl sie hier seit Generationen friedlich im Einklang mit der Natur lebten, entblößt ihre wachsende Population nun das Marschland. Ihre schweren Pfoten zertrampeln die empfindliche Flora der Moore, während ihre Äxte übermäßig viel Holz für Kochstellen und Lagerfeuer fällen, wodurch das lokale Ökosystem völlig aus dem Gleichgewicht gerät.",al={"mosshide gnolle","wer sind mosshide","mosshide-bastarde"}}},fp="13,305,21.407.0,26.403.0,31.235.0,42.207.0,41.145.0,36.169.1,49.255.0"}
P.entries["quest:277"] = {n="Feuer-Tabu",s="Fire Taboo ist eine Aufgabe, die von Rethiel dem Sumpfhüter entlang der sumpfigen Straßen des Sumpflands vergeben wird. Gequält von den Leiden des örtlichen Waldes sendet die Sumpfbestie Reisende aus, um den Mosshide-Gnollen die kunstlosen Feuersteine zu entreißen, mit denen sie lebendiges Holz entzünden und verbrennen. Indem er den Gnollen das Feuer vorenthält, hofft Rethiel, die uralten Äste des Moores vor dem Verzehrtwerden zu bewahren.",h="Fire Taboo ist eine Aufgabe, die von Rethiel dem Sumpfhüter entlang der sumpfigen Straßen des Sumpflands...",kw={"kunstloser feuerstein","fire taboo","gnolle","sumpfhüter","lebendiges holz","mosshide","rethiel","sumpfland"},ang={["class:Druid"]="Als Wächter der Wildnis teilen Druiden Rethiels ehrfürchtige Bindung zu den Bäumen und verstehen den unnatürlichen Schmerz von lebendigem Holz, das den Feuergruben der Gnolle ausgesetzt ist.",["faction:Alliance"]="Die Mosshide-Gnolle bedrohen Reisende, die das Sumpfland durchqueren; den örtlichen Geistern beizustehen hilft, die Handelswege zu sichern, die Dun Morogh und Arathi verbinden.",["race:NightElf"]="Nachtelfen erkennen in Rethiel möglicherweise einen Mitbeschützer lebendiger Bäume, eine Sumpfbestie, die das Leiden des Sumpflands spürt."},sec={{t="Der Schmerz eines Sumpfhüters",b="Rethiel der Sumpfhüter wacht über die Wildnis des Sumpflands und pflegt eine tiefe spirituelle Verbundenheit mit den Bäumen des Moores. Während der natürliche Kreislauf aus Fäulnis und Erneuerung in einen Sumpf gehört, schneidet die vorsätzliche Zerstörung des Holzes tief in Rethiels Geist. Für einen lebendigen Geist des Moores ist das Hören des Ächzens lebendiger Äste, die gefällt und in Herdfeuer geworfen werden, eine Qual, die Rethiel nicht länger im Stillen ertragen kann."},{t="Das Auslöschen der Mosshides",b="Das Rudel der Mosshide verwüstet das Sumpfland für Wärme und Territorium, wobei es grüne Bäume fällt, statt herabgefallenes Totholz zu sammeln. Um ihre Ausbreitung ohne einen langwierigen Abnutzungskrieg einzudämmen, nimmt Rethiel das Schlüsselwerkzeug ihrer Zerstörung ins Visier: die kunstlosen Feuersteine, die von den stärkeren Gnollen verwendet werden. Indem er dem Rudel die Werkzeuge zum Feuermachen entreißt, macht Rethiel sie unfähig, das gefällte Holz zu verbrennen. Rethiel zerschmettert jeden gesammelten Stein persönlich und wirft den Staub ins Meer, um sicherzustellen, dass diese Funken den Wald nie wieder entzünden."}},faq={{q="Wer ist Rethiel der Sumpfhüter?",a="Rethiel der Sumpfhüter ist eine Sumpfbestie, die im Sumpfland weilt. Tief mit der Lebenskraft der örtlichen Bäume und Pflanzenwelt verbunden, trachtet Rethiel danach, den verwundeten Sumpf vor den Übergriffen der Mosshide-Gnolle zu schützen.",al={"wer ist rethiel","rethiel der sumpfhüter lore","wer vergibt fire taboo"}},{q="Warum will Rethiel kunstlose Feuersteine, anstatt die Gnollanführer zu töten?",a="Rethiel betrachtet das Verbrennen lebendigen Holzes als unverzeihlichen Frevel. Durch das Beschlagnahmen der Feuersteine hindert Rethiel die Gnolle direkt daran, Feuer zu entfachen, um die Bäume des Sumpflands zu verzehren, was ihre Lager schwächt und die Zerstörung lebendigen Holzes beendet.",al={"warum feuersteine","warum feuersteine nehmen","zweck kunstloser feuerstein"}},{q="Was geschieht mit den Feuersteinen, sobald sie abgegeben wurden?",a="Rethiel schlägt die kunstlosen Feuersteine in Stücke und wirft die Überreste ins Meer, damit sie nie wieder geschlagen werden können, um einen Funken gegen lebendiges Holz zu erzeugen.",al={"was macht er mit den feuersteinen","feuersteinzerstörung"}},{q="Welche Gnolle tragen die Feuersteine bei sich?",a="Die stärkeren Mitglieder des Mosshide-Rudels tragen kunstlose Feuersteine bei sich. Den kleineren Mosshide-Gnollen und den schwächeren Mongrels vertraut man keine Werkzeuge zum Feuermachen an, und sie tragen keine bei sich.",al={"wer lässt feuersteine fallen","welche gnolle haben kunstlosen feuerstein"}},{q="Warum fällen die Mosshides Bäume?",a="Die Mosshide-Gnolle fällen lebendige Bäume, um ihre Lagerfeuer zu speisen und sich im feuchten Sumpf zu wärmen, statt sich auf trockenes, herabgefallenes Holz zu verlassen.",al={"warum gnolle bäume fällen","holzfällen der mosshide"}},{q="Was folgt nach dem Sammeln der Feuersteine?",a="Nachdem Ihr den Gnollen das Feuer vorenthalten habt, schickt Euch Rethiel in der Folgequest Blisters on The Land aus, um eine weitere Plage anzugehen, die die Sümpfe heimsucht.",al={"welche quest folgt auf fire taboo","nächste quest nach feuersteinen"}}},fx={e3ab03fe={q="Warum will Rethiel der Sumpfhüter, dass dies erledigt wird?",a="Als Beschützer, der mit dem Land und der Natur verbunden ist, spürt Rethiel das Leiden des Sumpflands auf schmerzhafte Weise. Die Mosshide-Gnolle fällen lebende Bäume und verbrennen sie, um sich zu wärmen, was der Wildnis Qualen zufügt. Indem er den Gnollen ihre Feuersteine wegnimmt, hofft Rethiel, die Zerstörung des Waldes zu stoppen und sicherzustellen, dass die Gnolle kein lebendes Holz mehr verbrennen können.",al={"rethiel motiv","warum feuersteine nehmen","warum hasst rethiel feuer"}},["4d5af4db"]={q="Wofür ist der Kunstlose Feuerstein?",a="Die Mosshide-Gnolle tragen kunstlose Feuersteine als primitive Werkzeuge bei sich, um Funken zu schlagen und Feuer zu entzünden. Ohne sie können sie das lebende Holz, das sie im gesamten Sumpfland fällen, nicht verbrennen. Rethiel verlangt, dass Ihr diese Feuersteine sammelt, damit er sie zertrümmern und die Überreste ins Meer werfen kann, was ihnen die Fähigkeit nimmt, Feuer zu entzünden.",al={"nutzen kunstloser feuerstein","was sind kunstlose feuersteine","warum haben gnolle feuerstein"}},["25034295"]={q="Wer sind die Mosshides, gegen die Ihr ausgesandt werdet?",a="Ihr werdet gegen die Mosshidegnolle ausgesandt, ein bösartiger Clan von Hyänenmenschen, die das Sumpfland befallen haben. Sie haben sich im gesamten Sumpf ausgebreitet, Lager errichtet und fällen aggressiv uralte Bäume, um Feuer zu machen und Territorium zu beanspruchen, was dem natürlichen Gleichgewicht, das Rethiel beschützt, Ruin und Elend bringt.",al={"mosshides sumpfland","wer sind die gnolle","mosshide-gnolle"}}},fp="10,366,23.431.0,27.526.0,31.217.0,72.247.0,51.154.0,30.175.0,41.147.0,43.152.1"}
P.entries["quest:278"] = {n="Eine dunkle Bedrohung",s="Diese Quest ist ein entscheidender Schritt bei der Verteidigung des Steinwerkdamms gegen eine mutmaßliche Verschwörung der Dark Iron. Chefingenieur Hinderweir VII. beauftragt Abenteurer damit, seltene chemische und organische Reagenzien aus ganz Loch Modan zu beschaffen, um ein Entschärfungsgemisch herzustellen. Ohne diese Komponenten werden die Verteidiger nicht in der Lage sein, den unter dem gewaltigen Mauerwerk platzierten Sprengstoff zu neutralisieren.",h="Diese Quest ist ein entscheidender Schritt bei der Verteidigung des Steinwerkdamms gegen eine mutmaßliche...",kw={"krokilisktraene","dark iron","hinderweir","loch modan","lauerergift","mo'grosh-kristall","der steinwerkdamm"},ang={["faction:Alliance"]="Sollte es misslingen, die Bedrohung für den Damm zu neutralisieren, hätte dies eine Katastrophe zur Folge und würde entscheidende Überland-Versorgungswege trennen, die Eisenschmiede mit den nördlichen Königreichen verbinden.",["profession:Engineering"]="Ingenieure können Hinderweirs Erfindungsgeist bei der Formulierung eines chemischen Gegenmittels schätzen, das in der Lage ist, instabile Sprengladungen direkt vor Ort zu stabilisieren.",["race:Dwarf"]="Für die Zwerge von Khaz Modan ist die Verhinderung der Sabotage durch die Dark Iron am Steinwerkdamm eine entscheidende Pflicht zum Schutz ihrer angestammten Ländereien und architektonischen Meisterleistungen."},sec={{t="Ein explosives Rezept",b="Um den unbeständigen Sprengstoffmischungen der Saboteure der Dark Iron entgegenzuwirken, setzt Chefingenieur Hinderweir VII. auf einen ungewöhnlichen chemischen Neutralisator. Statt einfachem Wasser oder dämpfendem Sand erfordert die Neutralisierung des Schwarzpulvers der Dark Iron ein wirksames Gemisch aus dem Gift einheimischer Forest Lurker, einer Träne der im Loch lebenden Krokilisken und einem Mo'grosh-Kristall. Jede Komponente steuert einzigartige reaktive Eigenschaften bei, die nötig sind, um die Sprengladungen der Zwerge vollkommen unschädlich zu machen."},{t="Gefährliche Beschaffung",b="Die Beschaffung dieser Zutaten führt Abenteurer in die lebensfeindlichsten Winkel von Loch Modan. Während die Lauererspinnen und Lochkrokilisken gewöhnliche Gefahren der Natur darstellen, erfordert die Beschaffung eines Mo'grosh-Kristalls das Vordringen in die Festung der Oger in den nordöstlichen Hügeln. Die Mo'grosh-Oger bewachen diese seltenen, abgebauten Mineralformationen eifersüchtig, sodass jeder, der den Damm beschützen will, sich seinen Weg durch die Lager der Rohlinge bahnen muss, um sich eine Probe zu sichern."}},faq={{q="Warum benötigt Ingenieur Hinderweir diese speziellen Reagenzien?",a="Chefingenieur Hinderweir VII. stellt eine spezielle neutralisierende Verbindung her, um Sprengstoffe der Dark Iron zu entschärfen. Das ätzende Lauerergift, Krokiliskenabsonderungen und die in Mo'grosh-Kristallen vorkommenden magischen Mineralien liefern genau die chemischen Reaktionen, die erforderlich sind, um die hochentwickelten Sprengladungen der Saboteure unschädlich zu machen.",al={"warum spinnengift","warum krokilisktraene","entschaerfungsgemisch reagenzien"}},{q="Woher stammen die Mo'grosh-Kristalle?",a="Die Kristalle werden von den Mo'grosh-Ogern abgebaut und gehortet, die die nordöstlichen Hügel von Loch Modan bewohnen. Da sie von den Ogern als seltene und wertvolle Kostbarkeit angesehen werden, erfordert die Beschaffung eines solchen Kristalls das Vordringen in ihr schwer verteidigtes Gebiet.",al={"wo sind kristalle","fundort mogrosh kristall","wer hat den kristall"}},{q="Was ist die dunkle Bedrohung, die Loch Modan heimsucht?",a="Die Bedrohung geht von Infiltratoren der Dark Iron-Zwerge aus, die versuchen, den Steinwerkdamm zu zerstören. Die Sprengung dieses monumentalen Meisterwerks der Ingenieurskunst würde das darunterliegende Sumpfland überfluten, Versorgungswege der Allianz abschneiden und die Region verheeren.",al={"welche dunkle bedrohung","wer greift den damm an","eine dunkle bedrohung geschichte"}},{q="Wer ist Chefingenieur Hinderweir VII.?",a="Er ist der leitende Zwergeningenieur, der für die Überwachung der Abläufe und die Unversehrtheit des Steinwerkdamms zuständig ist. Er koordiniert sowohl die bauliche Instandhaltung als auch die örtliche Verteidigung gegen Sabotage.",al={"wer ist hinderweir","chefingenieur hinderweir"}},{q="Wo sind die einheimischen Kreaturen zu finden?",a="Forest Lurker-Spinnen streifen durch die bewaldete Wildnis rund um das Tal, während Krokilisken im und an den Ufern des Lochs selbst leben.",al={"wo sind lauerer","fundort krokilisken","wo spinnen finden"}},{q="Warum beschaffen die Wachen von Eisenschmiede diese Gegenstände nicht selbst?",a="Die Gebirgsjäger und örtlichen Wachen sind mit der Verteidigung von Ortschaften wie Thelsamar und dem Ausspähen von Spähern der Dark Iron voll ausgelastet. Spezielle Beschaffungsaufgaben und Vorstöße in Ogergebiet werden routinemäßig an fähige reisende Abenteurer übertragen.",al={"warum hinderweir helfen","wo sind wachen von eisenschmiede"}}},fx={["0370975a"]={q="Warum möchte Chefingenieur Hinderweir VII., dass diese Gegenstände gesammelt werden?",a="Chefingenieur Hinderweir VII. fürchtet einen unmittelbar bevorstehenden Angriff der Dunkeleisenzwerge auf den Steinwerkdamm. Um jeglichen Sprengungsversuchen entgegenzuwirken, benötigt er Euch, um flüchtige und spezialisierte Reagenzien zu sammeln – Lauerergift, eine Krokiliskenträne und einen seltenen Kristall der Mo'grosh –, damit er eine Neutralisierungsmischung brauen kann, um die Sprengstoffe des Feindes zu entschärfen, bevor das Loch Modan verwüstet wird.",al={"warum will hinderweir das erledigt haben","warum reagenzien sammeln hinderweir","hinderweir motiv dunkle bedrohung"}}},fp="19,371,17.497.0,18.434.0,58.296.0,37.248.0,44.225.0,37.186.0,44.140.0,61.241.0"}
P.entries["quest:280"] = {n="Eine dunkle Bedrohung",s="Eine verzweifelte Notfallmission von Chefingenieur Hinderweir VII., um die Zerstörung des Steinwerkdamms zu verhindern. Saboteure der Dunkeleisenzwerge haben tief unter der Wasserlinie eine explosive Ladung Seaforium platziert und drohen damit, eines der größten ingenieurstechnischen Wunder des Zwergenreichs zu zertrümmern.",h="Eine verzweifelte Notfallmission von Chefingenieur Hinderweir VII., um die Zerstörung des Steinwerkdamms zu...",kw={"damm","dunkeleisen","entschärfen","sprengstoff","hinderweir","aufständische","fass","seaforium","stonewrought"},ang={["faction:Alliance"]="Die Zerstörung des Steinwerkdamms würde lebenswichtige Transportwege verwüsten, die Khaz Modan mit den nördlichen Gebieten der Allianz verbinden.",["profession:Engineering"]="Die direkte Arbeit mit Seaforium und spezialisierten Chemikalien zur Entschärfung unterstreicht die extremen, folgenreichen Anwendungen der Sprengstoff- und Gegenmittelchemie.",["race:Dwarf"]="Der Steinwerkdamm ist ein beständiges Denkmal zwergischer Baukunst und ihres Stolzes; ihn vor dem Verrat der Dunkeleisenzwerge zu schützen, ist für jeden Sohn und jede Tochter von Eisenschmiede von größter Bedeutung.",["race:Gnome"]="Gnomische Geister wissen sowohl die ausgeklügelte Chemie hinter Hinderweirs Neutralisator als auch die schreckliche Verwüstung zu schätzen, die ein Seaforium-Bruch der Zwergenarchitektur zufügen würde."},sec={{t="Sabotage unter der Oberfläche",b="Chefingenieur Hinderweir VII. entdeckte Dunkeleisenaufständische, die mit einem gewaltigen Fass explosivem Seaforium auf das Fundament des Steinwerkdamms zuschwammen. Da keine Gebirgsjäger in der Nähe waren, um einzugreifen, befestigten die Infiltratoren die Waffe direkt am Unterwasserfundament des Damms. Ein Bruch würde das gesamte Wasservolumen des Lochs in das darunterliegende Tiefland entfesseln, was verheerende Überschwemmungen zur Folge hätte und den Handel sowie die Reisewege der Zwerge in der gesamten Region lahmlegen würde."},{t="Ein flüchtiges Neutralisierungsmittel",b="Nachdem Hinderweir rasch reaktive Zutaten zu einer Entschärfungsmixtur zusammengeführt hat, schickt er einen mutigen Taucher direkt zu der untergetauchten Bombe. Um das Seaforium zu neutralisieren, muss das versenkte Fass aufgeschraubt und die chemische Lösung direkt in das Sprengpulver eingerührt werden. Die Mischung stoppt den Countdown mit einem leisen Zischen unter Wasser und stabilisiert die Ladung, bevor die Explosion das Mauerwerk zerreißen kann."}},faq={{q="Was ist das Ziel dieser Quest?",a="Ihr müsst unter die Wasseroberfläche von Loch Modan zum Fundament des Steinwerkdamms tauchen, das platzierte Fass mit Seaforium ausfindig machen und Chefingenieur Hinderweirs Entschärfungsmixtur einrühren, um die Explosion zu neutralisieren.",al={"questziel","was mache ich hier","eine dunkle bedrohung 6 ziel"}},{q="Wer hat das Sprengstofffass platziert?",a="Dunkeleisenaufständische infiltrierten früher am Tag die Gewässer von Loch Modan und nutzten die Abwesenheit einheimischer Gebirgsjäger aus, um eine Seaforium-Ladung direkt an der Unterwasserseite des Damms anzubringen.",al={"wer hat die bombe platziert","wer hat seaforium gelegt","eine dunkle bedrohung schuldige"}},{q="Was passiert, wenn der Damm zerstört wird?",a="Der Steinwerkdamm staut den riesigen See von Loch Modan auf. Würde der Damm zerstört werden, würden Millionen Gallonen Wasser in das Sumpfland und die umliegenden Täler strömen und Straßen, Siedlungen und Menschenleben fortreißen.",al={"warum damm retten","was passiert wenn die bombe detoniert","damm explosion folgen"}},{q="Wer hat die Entschärfungsmixtur zusammengebraut?",a="Chefingenieur Hinderweir VII. stellte den chemischen Neutralisator mithilfe gesammelter Reagenzien her und schuf so eine Mixtur, die in der Lage ist, die Seaforium-Ladung zu neutralisieren, ohne eine versehentliche Detonation auszulösen.",al={"wer hat die mixtur gebraut","hinderweir rolle","wer hat die chemikalie gemacht"}},{q="Wo befindet sich das Sprengstofffass?",a="Das Fass ruht unter Wasser am tief gelegenen Unterwasserfundament des Steinwerkdamms auf der südlichen, dem See zugewandten Seite.",al={"wo ist die bombe","fass fundort","pulverfass unter wasser"}},{q="Welche Art von Sprengstoff wurde verwendet?",a="Die Saboteure der Dunkeleisenzwerge verwendeten Seaforium, eine mächtige und flüchtige Sprengstoffmischung, die in ein versiegeltes, wasserdichtes Fass gefüllt war.",al={"woraus besteht die bombe","bombentyp","welcher sprengstoff"}}},fx={["8859d649"]={q="Warum möchte Chefingenieur Hinderweir VII., dass dies erledigt wird?",a="Als Chefingenieur, der den Steinwerkdamm beaufsichtigt, übernimmt Hinderweir die persönliche Verantwortung für dessen strukturelle Integrität. Dunkeleisenaufständische haben direkt am Fundament einen starken Seaforyumsprengstoff platziert. Sollte der Damm brechen, würde die katastrophale Flut aus dem Loch die Täler darunter überfluten und eines der größten architektonischen Wunder der Zwerge zerstören.",al={"warum kümmert sich hinderweir","hinderweir motivation","warum die explosion stoppen"}},["34eba16d"]={q="Warum braucht Chefingenieur Hinderweir VII. Euch anstelle der Gebirgsschützen?",a="Als sich die Dunkeleisensaboteure näherten, waren keine Gebirgsschützen in der Nähe, um sie abzufangen, und die Zeit drängt verzweifelt. Die Ladung könnte jeden Moment detonieren und Hinderweir musste zurückbleiben, um dringend die Entschärfungsmixtur aus den Rohkomponenten zu brauen. Ihr seid die einzige fähige Hand vor Ort, die unter Wasser tauchen und den Sprengstoff sofort neutralisieren kann.",al={"warum können die wachen das nicht tun","warum ich hinderweir","wo sind die gebirgsschützen"}}},fp="19,296,28.448.0,22.400.1,31.209.0,30.208.0,37.212.0,36.197.0,35.120.0,32.125.0"}
P.entries["quest:282"] = {n="Senirs Beobachtungen",s="Nachdem er wichtige Informationen über die lokalen Bedrohungen im Coldridgetal gesammelt hat, vertraut Grelin Weißbart Euch an, seine Erkenntnisse zu seinem Bruder Senir Weißbart nach Kharanos zu bringen. Um das geschützte Tal zu verlassen, müsst Ihr jedoch einen Tunnel passieren, der kürzlich von feindseligen Troggs überrannt wurde und von Gebirgsjäger Thalos bewacht wird.",h="Nachdem er wichtige Informationen über die lokalen Bedrohungen im Coldridgetal gesammelt hat, vertraut Grelin...",kw={"ambossar","das coldridgetal","grelin weißbart","grelins bericht","kharanos","gebirgsjäger thalos","senir weißbart","troggs","tunnel"},ang={["faction:Alliance"]="Die Aufrechterhaltung eines sicheren Durchgangs zwischen den Tälern der Zwerge ist entscheidend für die Verteidigung von Eisenschmiede und die Sicherheit der Kuriere der Allianz.",["race:Dwarf"]="Für Zwergengebirgsjäger und Rekruten markiert das Durchqueren des östlichen Tunnels Euren ersten offiziellen Einsatz jenseits der Übungsplätze im Coldridgetal.",["race:Gnome"]="Als gnomische Flüchtlinge, die unter den Bronzebärten leben, bietet diese Depesche einen Weg aus der anfänglichen Zuflucht hinaus zu den größeren Problemen, die Dun Morogh heimsuchen."},sec={{t="Ein Bote für die Whitebeards",b="Grelin Weißbart hat erhebliche Mühe darauf verwendet, die Trollaktivitäten rund um das Coldridgetal zu dokumentieren. Als sein Tagebuch gestohlen und anschließend wiederbeschafft wurde, wurde klar, dass die gesammelten Informationen viel zu wichtig waren, um sie einem unerfahrenen Lehrling anzuvertrauen. Um Zwischenstationen zu umgehen, wählt Grelin einen erfahrenen Abenteurer, der seinen Bericht direkt zu seinem Bruder Senir Weißbart bringt, welcher außerhalb des Tals in Kharanos Operationen leitet."},{t="Der versperrte Pass nach Kharanos",b="Das Coldridgetal zu verlassen, ist kein einfacher Marsch mehr auf der Hauptstraße. Der östliche Tunnel, der das Tal mit der weiteren schneebedeckten Hochebene von Dun Morogh verbindet, wurde von grabenden Troggs gewaltsam überrannt. Um zu verhindern, dass unbedarfte Zivilisten in eine Todesfalle tappen, hat die Wache von Eisenschmiede Gebirgsjäger Thalos direkt vor dem Durchgang postiert. Nur Reisenden mit dringenden, offiziellen Angelegenheiten wird gestattet, den Wachposten zu passieren und den unterirdischen Spießrutenlauf zu wagen."}},faq={{q="An wen schickt Grelin diesen Bericht?",a="Der Bericht ist an Senir Weißbart gerichtet, Grelins Bruder, der jenseits der Berge in Kharanos stationiert ist und regionale Angelegenheiten beurteilt.",al={"wer erhält bericht","senir weißbart","empfänger des berichts"}},{q="Warum kann Grelins Lehrling den Bericht nicht überbringen?",a="Grelin hatte ursprünglich vor, seinen Lehrling zu schicken, doch nach den jüngsten Problemen mit Frostmähnentrollen, die sein Tagebuch gestohlen hatten, hielt er die Informationen für zu wichtig, um sie in unerfahrenen Händen zu lassen.",al={"warum nicht lehrling","grelin lehrling"}},{q="Warum wird der Tunnel aus dem Coldridgetal bewacht?",a="Der Tunnel, der das Coldridgetal mit dem Rest von Dun Morogh verbindet, wurde vollständig von Troggs überrannt. Gebirgsjäger Thalos ist am Eingang stationiert, um Zivilisten zu schützen, bis der Weg geräumt werden kann.",al={"warum thalos wache hält","tunnel blockiert","warum ist tunnel geschlossen"}},{q="Wo befindet sich Gebirgsjäger Thalos?",a="Thalos ist östlich von Ambossar stationiert und hält direkt am Eingang des Tunnels Wache, der aus dem Coldridgetal hinaus in Richtung Kharanos führt.",al={"thalos standort","wo ist thalos","gebirgsjäger thalos finden"}},{q="Was ermöglicht es Euch, den von Troggs heimgesuchten Tunnel zu durchqueren?",a="Gebirgsjäger Thalos lässt gewöhnliche Reisende nicht in den Tunnel, doch das Mitführen einer dringenden Depesche von Grelin Weißbart beweist, dass Euer Anliegen wichtig genug ist, um die Reise zu riskieren.",al={"tunnel durchqueren","tunnelerlaubnis"}},{q="Was passiert nach dem Gespräch mit Gebirgsjäger Thalos?",a="Thalos warnt Euch und gibt Anweisungen für das Durchqueren der gefährlichen unterirdischen Route, bevor er Euch die Erlaubnis erteilt, weiter nach Osten in Richtung Kharanos zu ziehen.",al={"nächster schritt","was nach thalos"}}},fx={ba85e128={q="Warum möchte Grelin Weißbart, dass dieser Bericht überbracht wird?",a="Grelin Weißbart hat die wachsende Aktivität und die Bedrohungen der Frostmähnentrolle im Das Coldridgetal dokumentiert. Sein Bruder, Senir Weißbart, ist in Kharanos stationiert und sammelt Informationen über umfassendere Probleme in ganz Dun Morogh. Diesen Bericht sicher zu Senir zu bringen, ist entscheidend für die Koordination der Verteidigung der Region, besonders jetzt, da die Frostmähnen näher an die zwergischen Siedlungen heranrücken.",al={"warum grelin bericht senden","grelin weißbart motiv","warum senirs beobachtungen abliefern"}}},fp="20,320,29.471.0,28.475.0,37.141.0,49.197.0,50.201.0,36.142.0,58.184.0,52.143.0"}
P.entries["quest:283"] = {n="Eine dunkle Bedrohung",s="Eine dunkle Bedrohung ist eine dringende Mission, um Loch Modan vor dem Unheil zu bewahren. Abenteurer der Allianz werden damit beauftragt, eine neutralisierende Chemikalie gegen eine platzierte Sprengladung einzusetzen, bevor dem Steinwerkdamm katastrophaler Schaden zugefügt werden kann.",h="Eine dunkle Bedrohung ist eine dringende Mission, um Loch Modan vor dem Unheil zu bewahren.",kw={"dunkeleisenzwerge","entschärfungsmixtur","sprengladung","hinderweir","loch modan","sabotage","der steinwerkdamm"},ang={["faction:Alliance"]="Das Verhindern des Dammbruchs sichert wichtige Landkorridore zwischen Eisenschmiede und den nördlichen Ländern von Arathi und Lordaeron.",["profession:Engineering"]="Die Neutralisierung eines instabilen Sprengsatzes direkt im Inneren eines kolossalen Bauprojekts verdeutlicht die entscheidende Bedeutung von Gegenmaßnahmen und Sprengstofflehre.",["race:Dwarf"]="Der Steinwerkdamm ist eine meisterhafte Errungenschaft zwergischer Steinmetzkunst; sein Schutz bewahrt den Stolz und die Sicherheit Eisenschmiedes vor der Bosheit der Dunkeleisenzwerge."},sec={{t="Abgewendete Katastrophe",b="Der gewaltige Steinwerkdamm hält die riesigen Wassermassen des Lochs zurück und ragt über das Tiefland des Sumpflands hinweg. Als es Saboteuren der Dunkeleisenzwerge gelang, eine Sprengladung im Inneren des Bauwerks zu platzieren, drohte dem gesamten Tal der Untergang. Das Auftragen der Entschärfungsmixtur lässt das explosive Fass harmlos verpuffen und bannt die unmittelbare Gefahr für die zwergische Ingenieurskunst und zahllose Leben flussabwärts."},{t="Hinderweirs Erleichterung",b="Die Rückkehr zu Chefingenieur Hinderweir VII. bringt den Aufsehern Eisenschmiedes vor Ort enorme Erleichterung. Hinderweir preist das Eingreifen als großen Sieg für das Königreich Eisenschmiede und die Allianz an. Dennoch dient die Infiltration durch die Dunkeleisenzwerge so tief in Khaz Modan als düstere Mahnung daran, dass ihre verbitterten Vettern unerbittlich danach streben, die Errungenschaften Eisenschmiedes zu vernichten."}},faq={{q="Was war das Ziel dieser Questreihe?",a="Die Questreihe dreht sich um das Aufdecken und Vereiteln eines Sabotageplans der Dunkeleisenzwerge, die Sprengstoff zünden wollten, um den Steinwerkdamm zu zerstören.",al={"eine dunkle bedrohung zusammenfassung","stonewroughtdamm questziel","warum bombe entschärfen"}},{q="Wer hat die Sprengladung platziert?",a="Saboteure der Dunkeleisenzwerge platzierten das Sprengfass im Steinwerkdamm, um das gewaltige Bauwerk zu zerstören.",al={"wer hat die bombe platziert","wer griff den damm an","dunkeleisenzwerge damm"}},{q="Wer ist Chefingenieur Hinderweir VII.?",a="Chefingenieur Hinderweir VII. ist der zwergische Aufseher, der für die Instandhaltung, den Betrieb und die Verteidigung des Steinwerkdamms in Loch Modan verantwortlich ist.",al={"wer ist hinderweir","hinderweir lore","ingenieur am damm"}},{q="Was wäre geschehen, wenn der Damm gebrochen wäre?",a="Wäre der Steinwerkdamm gebrochen, hätte sich das gewaltige Reservoir von Loch Modan mit verheerender Wucht entleert, das Sumpfland flussabwärts überflutet und Straßen, Siedlungen sowie wichtige Transitrouten weggespült.",al={"was wenn damm zerstört","folgen eines dammbruchs","damm explosion"}},{q="Wie wurde der Sprengstoff entschärft?",a="Eine eigens hergestellte Entschärfungsmixtur wurde über die Sprengladung gegossen, wodurch das Pulverfass sicher zischte und erlosch, bevor es detonieren konnte.",al={"wie wurde bombe gestoppt","entschärfungsmixtur","wie ladung entschärfen"}},{q="Ist der Steinwerkdamm nun sicher?",a="Obwohl die unmittelbare Detonation verhindert und der Damm gerettet wurde, merkt Hinderweir an, dass die Verteidigung vorerst nur vorübergehend gesichert ist, da Agenten der Dunkeleisenzwerge die Region weiterhin bedrohen.",al={"ist der damm sicher","sind die dunkeleisenzwerge weg","damm für immer sicher"}}},fp="19,248,19.394.0,19.408.1,38.146.0,33.129.0,37.148.0,42.193.0,31.147.1,33.183.1"}
P.entries["quest:287"] = {n="Höhle der Frostmähnen",s="Höhle der Frostmähnen ist eine Aufklärungsmission der Allianz, die von Senir Weißbart in Kharanos vergeben wird. Nachdem er die feindseligen Frostmanetrolle zu ihrer schwer bewachten Höhlenfestung nahe dem Eiswellensee zurückverfolgt hat, rekrutiert Senir abenteuerlustige Späher, um ins Innere vorzudringen, ihre Kopfjäger zu eliminieren und wichtige Informationen für seine Aufklärungsberichte zu liefern.",h="Höhle der Frostmähnen ist eine Aufklärungsmission der Allianz, die von Senir Weißbart in Kharanos vergeben...",kw={"brewnall","dun morogh","frostmaneheadhunter","höhle der frostmähnen","eistrolle","iceflowsee","kharanos","senir weißbart","die berichte"},ang={["faction:Alliance"]="Die Sicherung von Dun Morogh stellt sicher, dass die Gebirgsstraßen, die Eisenschmiede mit den Nachbarkönigreichen verbinden, frei von Hinterhalten feindseliger Stämme bleiben.",["race:Dwarf"]="Die Frostmanetrolle fechten die Vorherrschaft von Eisenschmiede in den schneebedeckten Gipfeln von Dun Morogh an; das Auskundschaften ihrer zentralen Höhlenfestung ist für die Verteidigung des Reiches von entscheidender Bedeutung.",["race:Gnome"]="Da sich nach dem Fall von Gnomeregan Gnom in ganz Dun Morogh und Kharanos niedergelassen haben, sichert die Eindämmung der Frostmanetroll-Offensive die verwundbaren Versorgungskorridore der Flüchtlinge."},sec={{t="Ein Späher im Verzug",b="Der in Kharanos stationierte Gebirgsjäger und Späher Senir Weißbart hatte die Aufgabe, die vorrückende Bedrohung durch die Frostmanetrolle in ganz Dun Morogh zu überwachen. Obwohl es ihm gelang, die aggressiven Stämme zu ihrer primären Höhlenbehausung südwestlich von Bräuhall zurückzuverfolgen, ließ ihn die schiere Menge an bewaffneten Trollen zögern. Da er sich scheute, die Höhle allein zu betreten, und mit seinen offiziellen Berichten stark in Verzug geriet, heuert Senir vorbeikommende Abenteurer an, um sich an seiner statt in die eisigen Tiefen zu wagen."},{t="Das Eindringen in die Höhle",b="Die Festung liegt in die westlichen Gipfel über dem Eiswellensee geschlagen – ein eisiges Bollwerk voller feindseliger Eistrolle. Um Senirs Mission zu erfüllen, müssen sich die Späher tief durch die unterirdischen Tunnel kämpfen, die wilden Frostmaneheadhunter auf den Felsvorsprüngen dezimieren und den Aufbau des Inneren kartieren. Das Überleben dieses Vorstoßes liefert die entscheidenden Erkenntnisse, die Senir benötigt, um seine Berichte für die militärischen Befehlshaber von Eisenschmiede fertigzustellen."}},faq={{q="Wo befindet sich die Höhle der Frostmähnen?",a="Die Höhle der Frostmähnen ist eine Höhle südwestlich von Bräuhall ganz im Westen von Dun Morogh. Folgt von Kharanos aus der Straße nach Norden zur Brücke, folgt dem zugefrorenen Fluss nach Westen am Eiswellensee vorbei nach Bräuhall und haltet Euch nach Südwesten hinauf in die Berge.",al={"höhle der frostmane finden","wo ist die höhle","höhle der frostmane standort"}},{q="Wer ist Senir Weißbart?",a="Senir Weißbart ist ein Zwergenspäher, der vor der Brauerei Donnerbräu in Kharanos stationiert ist. Er verfolgt lokale Bedrohungen in ganz Dun Morogh und verfasst strategische Aufklärungsberichte über die aggressiven Frostmanetrolle.",al={"senir weißbart","wer gibt die quest","questgeber kharanos"}},{q="Warum hat Senir die Höhle nicht selbst erkundet?",a="Senir spähte den Eingang aus und fand heraus, wo sich der Stamm sammelte, stellte jedoch fest, dass die Höhle von so vielen bewaffneten Trollen wimmelte, dass er Angst hatte, sie allein zu betreten. Besorgt um seine Sicherheit und unter Zeitdruck bei seinen Aufklärungsfristen überträgt er die gefährliche Erkundung fähigen Abenteurern.",al={"warum hat senir angst","warum ging senir nicht"}},{q="Wer sind die Frostmanetrolle?",a="Die Frostmane sind ein einheimischer Stamm von Eistrollen, der in den verschneiten Klüften von Dun Morogh beheimatet ist. Als erbitterte Feinde der Zwerge und Gnom von Eisenschmiede überfallen sie aus versteckten Lagern in der gesamten Region regelmäßig Handelswege, Lager und Siedlungen.",al={"frostmane","trolle dun morogh","dun morogh trolle"}},{q="Was geschieht nach Abschluss der Aufklärung der Höhle?",a="Sobald Ihr mit Neuigkeiten über den Aufbau der Höhle und den Verlusten unter ihren Kopfjägern zurückkehrt, stellt Senir seinen Bericht fertig und bittet Euch sogleich, die dringenden Dokumente zu Senirs Vorgesetzten in Dun Morogh zu bringen.",al={"folgequest","was nach höhle der frostmane","die berichte quest"}},{q="Wie tief müsst Ihr in die Höhle hineingehen?",a="Ihr müsst weit über den Eingangsbereich hinaus in die inneren Kammern vordringen, bis die Struktur der Höhle ausgekundschaftet ist und fünf Frostmaneheadhunter getötet wurden, was bestätigt, dass die Tiefen der Höhle gründlich erkundet worden sind.",al={"höhle der frostmane vollständig erkunden","höhlenerkundung trigger"}}},fx={["889a57f0"]={q="Warum möchte Senir Weißbart, dass die Höhle der Frostmähnen erkundet wird?",a="Senir Weißbart ist ein Agent, der an Geheimdienstberichten über die zunehmenden Bedrohungen in Dun Morogh arbeitet. Er ist bei seinen Späherpflichten in Verzug geraten und benötigt Informationen aus erster Hand über das Lager der Frostmähnentrolle, um seine Bewertung für das Kommando in Eisenschmiede abzuschließen, bevor seine Vorgesetzten davon Notiz nehmen.",al={"warum will senir das erledigt haben","senir weißbart motiv","warum höhle der frostmähnen erkunden"}},["860fac70"]={q="Warum werdet Ihr gegen die Frostmähnen-Kopfjäger ausgesandt?",a="Die Frostmähnen-Kopfjäger bilden die militante Verteidigung der Höhle der Frostmähnen, den tiefen Höhlen südwestlich von Bräuhall, wo sich die vertriebenen Trolle massiv versammelt haben. Sie zu töten, dezimiert ihre Patrouillen und ebnet den Weg, um die Tiefen der Höhle angemessen auszukundschaften.",al={"wer sind frostmähnen-kopfjäger","warum kopfjäger töten","frostmähnen-kopfjäger zweck"}}},fp="14,325,23.484.0,20.448.0,32.264.0,24.222.0,42.295.0,29.249.0,52.210.1,41.215.0"}
P.entries["quest:288"] = {n="Die Dritte Flotte",s="Vor der Tiefenwassertaverne im Hafen von Menethil ertränkt Erster Maat Fitzsimmons seine Erinnerungen in Zwergenmet. Er ist der einzige Überlebende von Kul Tiras' Dritter Flotte, einer stolzen Seestreitmacht, die während des Zweiten Krieges vor der Küste des Sumpflands von ork-versklavten roten Drachen eingeäschert wurde.",h="Vor der Tiefenwassertaverne im Hafen von Menethil ertränkt Erster Maat Fitzsimmons seine Erinnerungen in...",kw={"tiefenwassertaverne","die verlorene flotte","dragonmaw","fitzsimmons","kul tiras","der hafen von menethil","rote drachen","dritte flotte","wave mistress","sumpfland"},ang={["faction:Alliance"]="Fitzsimmons' Bericht über den Untergang der Wave Mistress erinnert die Verteidiger der Allianz an die bleibenden Narben, die die Drachenreiter der Horde in ganz Khaz Modan hinterlassen haben.",["race:Dwarf"]="Grim Batol warf einen Schatten über ganz Khaz Modan, und die in seinen Tiefen gezüchteten Drachen richteten verheerende Schäden unter den Zwergenländern und ihren menschlichen Verbündeten an.",["race:Human"]="Die Zerstörung der Dritten Flotte ist eine bittere Erinnerung an die katastrophalen Seeschlachten, die Kul Tiras und die Allianz gegen die Dragonmaw ausfochten."},sec={{t="Die Trauer eines Seemanns",b="Erster Maat Fitzsimmons verbringt seine Tage zusammengesunken vor der Tiefenwassertaverne im Hafen von Menethil, wo er einen endlosen Kater und Erinnerungen pflegt, die er nicht loswird. Einst Offizier an Bord der Wave Mistress – einem Linienschiff unter dem maritimen Banner von Kul Tiras – tauscht er nun seine düsteren Erinnerungen gegen Krüge voller Zwergenmet. Jeder, der bereit ist, ihm noch einen Drink zu spendieren, erhält den Augenzeugenbericht einer der verheerendsten Seeschlachten des Zweiten Krieges."},{t="Feuer über den Wellen",b="Während des Zweiten Krieges segelte die Dritte Flotte an den Küsten von Khaz Modan entlang, als das Unheil aus den Himmeln herabstürzte. Der Clan der Dragonmaw, der den roten Drachenschwarm bei Grim Batol unterjocht hatte, entfesselte Drachenfeuer auf die ahnungslosen Kriegsschiffe. Fitzsimmons erinnert sich an hilflose Holzrümpfe, die unter gewaltigen Feuersäulen brannten und ganze Besatzungen in die Tiefe rissen. Fitzsimmons allein überlebte und wurde an Land gespült; seine gefallenen Brüder ließ er im wässrigen Grab zurück, das heute als die Verlorene Flotte bekannt ist."}},faq={{q="Wer ist Erster Maat Fitzsimmons?",a="Er ist ein alter Seemann, der sein Trauma vor der Tiefenwassertaverne im Hafen von Menethil ertränkt. Als ehemaliger Erster Maat des Kriegsschiffs Wave Mistress aus Kul Tiras ist er der einzige bekannte Überlebende der Vernichtung der Dritten Flotte.",al={"fitzsimmons","wer ist der betrunkene seemann","fitzsimmons taverne"}},{q="Was geschah mit der Dritten Flotte?",a="Die Dritte Flotte von Kul Tiras geriet während des Zweiten Krieges vor der Küste des Sumpflands in einen Hinterhalt und wurde eingeäschert. Drachenreitende Orks des Clans der Dragonmaw ließen Feuer von oben regnen und schickten die Schiffe und Seeleute der Flotte auf den Meeresgrund.",al={"schicksal dritte flotte","wie sank die flotte","kul tiras schiffe gesunken"}},{q="Warum griffen Drachen menschliche Schiffe an?",a="Während des Zweiten Krieges versklavte der Clan der Dragonmaw den roten Drachen Alexstrasza mithilfe der Dämonenseele im nahen Grim Batol. Durch dunkle Zauberei gebunden, wurden die roten Drachen gezwungen, der Horde als monströse Reittiere und Belagerungswaffen zu dienen.",al={"dragonmaw drachen","rote drachen sumpfland","warum orks auf drachen"}},{q="Wo sanken die Schiffe tatsächlich?",a="Die verkohlten Wracks liegen vor der Westküste des Sumpflands, nördlich vom Hafen von Menethil, unter Wasser – ein tragisches Gebiet, das heute als die Verlorene Flotte in Erinnerung geblieben ist.",al={"wo ist die verlorene flotte","schiffswrack ort sumpfland","wrack der dritten flotte"}},{q="Welches Getränk möchte Fitzsimmons?",a="Er braucht einen Krug Zwergenmet, um seine Zunge zu lockern und seinen rasenden Kater zu lindern; dieser kann direkt beim Wirt in der Tiefenwassertaverne gekauft werden.",al={"fitzsimmons met","was will fitzsimmons","krug met"}},{q="Welcher Nation diente die Dritte Flotte?",a="Die Flotte gehörte zu Kul Tiras, dem maritimen Inselkönigreich, dessen gewaltige Marine während des Zweiten Krieges das Rückgrat der Seestreitkräfte der Allianz bildete.",al={"ist die dritte flotte sturmwind","kul tiras flotte","wer besaß die wave mistress"}}},fx={["03818f34"]={q="Warum möchte Erster Maat Fitzsimmons etwas zu trinken?",a="Fitzsimmons ist der einzige Überlebende eines schrecklichen Massakers, verfolgt von der Erinnerung an das Verbrennen seiner Flotte und leidet unter einem heftigen Kater. Sein Kopf hämmert so stark, dass er es nicht ertragen kann, ohne einen starken Drink, um den Schmerz zu dämpfen und seine Zunge zu lockern, von der Tragödie von The Third Fleet zu berichten. Ein Krug Met ist alles, was ihn zum Reden bringen wird.",al={"fitzsimmons motiv","warum will fitzsimmons met","warum fitzsimmons helfen"}},["53fbd504"]={q="Warum braucht Fitzsimmons Euch, um den Met zu holen?",a="Fitzsimmons ist ein gebrochener, mittelloser Überlebender, der vor der Taverne in Selbstmitleid und Qualen schwelgt. Geplagt von einem pochenden Kater und da er wahrscheinlich seinen letzten Kupfer ausgegeben hat, hat er weder die Mittel noch die Kraft, selbst zur Bar zu gehen, weshalb er vorbeiziehende Abenteurer um Wohltätigkeit anbetteln muss.",al={"warum kann fitzsimmons sein getränk nicht selbst kaufen","warum nach met fragen","fitzsimmons warum ich"}}},fp="15,281,16.454.0,19.494.0,30.221.0,33.230.0,39.231.0,34.150.0,33.169.0,38.159.0"}
P.entries["quest:289"] = {n="Die verfluchte Crew",s="Erster Maat Fitzsimmons, der einzige lebende Überlebende der Dritten Flotte von Kul Tiras, bittet um Gnade für seine verlorenen Brüder. Gefangen durch ein dunkles Relikt, das an Bord ihrer gesunkenen Schiffe vor der Küste des Sumpflands verborgen liegt, durchstreifen die ertrunkenen Matrosen und Seesoldaten die Wracks als rastlose Untote.",h="Erster Maat Fitzsimmons, der einzige lebende Überlebende der Dritten Flotte von Kul Tiras, bittet um Gnade...",kw={"die verfluchte crew","verfluchter marinier","verfluchter matrose","fitzsimmons","kul tiras","menethil","snellig","schnupftabakdose","die dritte flotte","sumpfland"},ang={["class:Paladin"]="Die Matrosen der Dritten Flotte waren unschuldige Männer, gefangen von einem unheiligen Relikt; sie zur Ruhe zu betten, reinigt unheilige Entweihung und bringt Licht in dunkle Gewässer.",["faction:Alliance"]="Kul Tiras hat der Großen Allianz seit langem die besten Seeleute gestellt; ihre gequälten Geister zur Ruhe zu bringen, ist eine ernste Ehrenpflicht für jeden Abenteurer der Allianz.",["race:Human"]="Menschliche Reisende spüren das Gewicht der Brüderlichkeit mit diesen gefallenen Seeleuten und erkennen die gemeinsamen Seefahrtstraditionen des Königreichs Kul Tiras an."},sec={{t="Eine rastlose Flotte",b="Als die Dritte Flotte von Kul Tiras an den schroffen Ufern nördlich vom Hafen von Menethil strandete, endete ihre Tragödie nicht unter den Wellen. Während Erster Maat Fitzsimmons lebend an Land gespült werden konnte, ereilte seine Mannschaftskameraden ein Schicksal, das weit schlimmer als der Tod war. Ein geheimnisvoller und schrecklicher Schatz, der tief in einem der Rümpfe verborgen lag, entfesselte eine unheimliche Zauberei über die sterbenden Seeleute, band ihre Seelen an das von der See zerschlagene Holz und verwehrte ihnen die Ruhe des Grabes."},{t="Gnade durch die Klinge",b="Fitzsimmons, der in den Tavernen des Hafens von Menethil verweilt, wird weiterhin von den nächtlichen Stöhnen und Schreien seiner einstigen Schiffskameraden heimgesucht. Im Glauben, dass das Niederstrecken ihrer belebten Leichen ihnen Erlösung bringen wird, schickt er Abenteurer in die verrottenden, ertrunkenen Kolosse, um die verfluchten Matrosen, die erfahrenen Seesoldaten und seinen früheren Gefährten, Ersten Maat Snellig, niederzustrecken und Snelligs persönliche Schnupftabakdose als düsteren Beweis dafür zu bergen, dass sein Freund endlich zur Ruhe gebettet wurde."}},faq={{q="Wer war Erster Maat Snellig?",a="Erster Maat Snellig diente an Bord der unglückseligen Dritten Flotte von Kul Tiras an der Seite von Erstem Maat Fitzsimmons. Nachdem die Flotte vor der Nordküste des Sumpflands Schiffbruch erlitten hatte, ertrank Snellig mit dem Rest der Besatzung, nur um durch das bösartige Relikt, das an Bord der Schiffe verstaut war, wiederauferweckt zu werden. Er spukt nun als untoter Schrecken im überfluteten Frachtraum eines der Wracks herum.",al={"snellig","erster maat snellig","wer ist snellig"}},{q="Warum sind die Matrosen und Seesoldaten verflucht?",a="Laut Fitzsimmons trug eines der Schiffe der Flotte einen verborgenen, unheilvollen Schatz mit sich. Als die Schiffe an der Küste strandeten, banden die dunklen Energien dieses Artefakts die Geister der ertrunkenen Mannschaft an ihre verrottenden Rümpfe, hinderten ihre Seelen am Weiterziehen und zwangen sie in untote Qualen.",al={"warum sind sie untot","fluch der dritten flotte","ursache verfluchte matrosen"}},{q="Wo befinden sich die gesunkenen Schiffe?",a="Die zerstörten Kolosse der Dritten Flotte liegen vor der Küste im nördlichen Sumpfland, nördlich vom Hafen von Menethil, unter Wasser. Die verfluchte Mannschaft durchstreift sowohl die überfluteten Decks als auch das umliegende Wasser, während Snellig selbst im geborstenen Rumpf des südlichen Schiffes lauert.",al={"wo sind die schiffe","wrack-fundort","wo ist snellig"}},{q="Warum will Fitzsimmons Snelligs Schnupftabakdose?",a="Die Schnupftabakdose war zu Lebzeiten ein persönliches Erinnerungsstück von Erstem Maat Snellig. Sie zu Fitzsimmons zurückzubringen, dient als greifbarer Beweis dafür, dass seinem verfluchten Kameraden endlich die Erlösung aus seinem verrottenden Gefängnis unter den Wellen zuteilwurde.",al={"snelligs schnupftabakdose","schnupftabakdose","warum schnupftabakdose"}},{q="Wer ist Erster Maat Fitzsimmons?",a="Fitzsimmons ist ein Seemann aus Kul Tiras und der einzige bekannte lebende Überlebende der Dritten Flotte. Gezeichnet von Kummer und Schuldgefühlen verweilt er im Hafen von Menethil, heimgesucht von Albträumen seiner ertrunkenen Brüder, und sucht verzweifelt nach Reisenden, die bereit sind, deren Leiden ein Ende zu setzen.",al={"fitzsimmons","erster maat fitzsimmons"}},{q="Bricht das Töten der Besatzung den Fluch wirklich?",a="Das Niederstrecken der Matrosen und Seesoldaten gewährt ihren rastlosen Geistern vorübergehende Ruhe, bricht den Zauber jedoch nicht gänzlich. Der Ursprung des Fluches bleibt an das geheimnisvolle Relikt gebunden, das immer noch an Bord der Wracks verborgen liegt.",al={"ist der fluch gebrochen","beendet das den fluch"}}},fx={["8e82e35b"]={q="Warum möchte Erster Maat Fitzsimmons, dass die The Cursed Crew getötet wird?",a="Fitzsimmons ist davon verfolgt, der einzige lebende Überlebende von The Third Fleet zu sein. Im Schlaf wird er von den todgeweihten Stöhnen seiner ertrunkenen Kameraden gequält, deren Seelen durch einen dunklen Schatz an die verrottenden Rümpfe gebunden bleiben. Er hofft, dass das Zur-Ruhe-Bringen ihrer wandelnden Leichen ihre Schreie verstummen lässt und der schreckliche Fluch, der auf ihnen lastet, gebrochen wird.",al={"warum die crew töten","fitzsimmons motiv","warum will fitzsimmons das"}},["7d36941a"]={q="Warum braucht Fitzsimmons Euch, anstatt selbst zu gehen?",a="Fitzsimmons ist ein alter, gebrochener Seemann, der vom Trauma des Überlebens des Schiffbruchs gezeichnet ist, der seine gesamte Flotte forderte. Er ertränkt seine Sorgen in der Taverne und hat weder die Kraft noch das Herz, sich selbst den wiederbelebten Leichen seiner früheren Kameraden zu stellen, und verlässt sich stattdessen auf fähige Abenteurer, um sich zu den Wracks zu begeben.",al={"warum braucht mich fitzsimmons","warum kann fitzsimmons nicht gehen","warum nicht die wachen von menethil"}}},fp="15,279,16.458.0,18.456.1,27.357.0,39.307.0,35.267.0,45.234.0,30.256.0,47.232.1"}
P.entries["quest:290"] = {n="Brechen des Fluchs",s="Erster Maat Fitzsimmons glaubt, dass der ruhelose Fluch, der seine gefallenen Kameraden bindet, von einem dunklen Artefakt stammt, das an Bord ihres Wracks, der Intrepid, verwahrt wurde. Um seine Brüder zu befreien, muss ein Abenteurer dem Geist von Kapitän Halyndor gegenübertreten, sich den Schlüssel zur Schatulle holen und das Relikt aus dem versunkenen Rumpf bergen.",h="Erster Maat Fitzsimmons glaubt, dass der ruhelose Fluch, der seine gefallenen Kameraden bindet, von einem...",kw={"kapitän halyndor","fitzsimmons","glorin stahlbraue","intrepid","brechen des fluchs","der hafen von menethil","schatulle","dritte flotte","sumpfland"},ang={["class:Priest"]="Das Entwirren spiritueller Leiden und das Reinigen verderbter Relikte erfordert spirituelle Autorität, weshalb Fitzsimmons die finale Reinigung des Schatulleninhalts der Priesterschaft anvertraut.",["faction:Alliance"]="Die Matrosen der Dritten Flotte dienten der Allianz im Leben, und ihre gepeinigten Seelen zur Ruhe zu betten, ist eine Pflicht der Ehre für Champions der Allianz, die durch den Hafen von Menethil reisen."},sec={{t="Die Bürde eines Kapitäns",b="Erster Maat Fitzsimmons überlebte das tragische Schicksal der Dritten Flotte, doch die Erinnerung an seine Kameraden verfolgt ihn in seinen wachen Stunden wie in seinen Träumen. Er bleibt überzeugt, dass der untote Zustand, der seine Schiffsgefährten ergriffen hat, mit einem mysteriösen, bösartigen Gegenstand verbunden ist, der in der Schatulle seines alten Schiffes, der Intrepid, eingeschlossen ist. Über das Wrack wacht der spektrale Überrest von Kapitän Halyndor, der selbst im Tod verbissen den Schlüssel zu den tiefsten Geheimnissen des Schiffes bewacht."},{t="Die Tiefen aufschließen",b="Vor der nebelverhangenen Küste des nördlichen Sumpflandes liegen die zerbrochenen Rümpfe der Dritten Flotte. Im gefluteten Rumpf der Intrepid ruht die verschlossene Schatulle des Schiffes, die das Relikt enthält, das den Kern des Leids der Mannschaft bildet. Um es zurückzugewinnen, muss man Halyndors gepeinigten Geist an Deck besiegen, den verrosteten Schlüssel sichern und dem gefluteten Inneren trotzen, um das dunkle Artefakt zu bergen, damit es von heiligen Händen gereinigt werden kann."}},faq={{q="Welches Schiff durchsucht Ihr während dieser Quest?",a="Ihr durchsucht die Intrepid, das versunkene Schiff der Dritten Flotte, das vor der nordwestlichen Küste des Sumpflandes ruht.",al={"welches schiff","intrepid schiffswrack","wo ist die schatulle"}},{q="Wer ist Kapitän Halyndor?",a="Kapitän Halyndor war der kommandierende Offizier der Intrepid. Im Tod spukt sein ruheloser Geist an Deck des zerstörten Schiffes und klammert sich hartnäckig an den Schlüssel zur Schatulle seines Schiffes.",al={"wer ist halyndor","kapitän halyndor hintergrund"}},{q="Warum will Erster Maat Fitzsimmons, dass die Schatulle geöffnet wird?",a="Fitzsimmons glaubt, dass ein verfluchter Gegenstand in der Schatulle dafür verantwortlich ist, die Geister seiner mitsegelnden Gefährten in Qualen zu halten, und das Öffnen ist der einzige Weg, das Artefakt zur Reinigung zu bergen.",al={"fitzsimmons ziel","warum schatulle öffnen","zweck der quest"}},{q="Wo befindet sich die Schatulle der Intrepid?",a="Die Schatulle liegt unter Wasser im unteren Rumpf der Intrepid und ist durch einen Riss in der Seite des Wracks unter den Wellen zugänglich.",al={"fundort der schatulle","wo ist die truhe","wie findet man die schatulle"}},{q="Wer kann den verfluchten Gegenstand reinigen, sobald er geborgen wurde?",a="Fitzsimmons weist Abenteurer an, den geborgenen Gegenstand zu dem zwergischen Priester Glorin Stahlbraue im Hafen von Menethil zu bringen, um dessen üble Verderbtheit reinigen zu lassen.",al={"wer reinigt das relikt","wer ist glorin stahlbraue","wohin mit dem verfluchten gegenstand"}},{q="Was verursachte den Schiffbruch?",a="Während des Zweiten Krieges wurde die Dritte Flotte von roten Drachen angegriffen, die von Orks kontrolliert wurden, und ihre Schiffe wurden verbrannt und vor der Küste des Sumpflandes versenkt; der verfluchte Schatz an Bord hindert die ertrunkenen Mannschaften nun daran, ihre Ruhe zu finden.",al={"wie sank die dritte flotte","ursache für das wrack der dritten flotte"}}},fx={["336b08f7"]={q="Wofür ist der Geldkassettenschlüssel der INTREPID?",a="Der Schlüssel gehörte Kapitän Halyndor und wird benötigt, um die Geldkassette der INTREPID im Wrack aufzuschließen. Darin befindet sich der verfluchte Gegenstand, der für die Verderbnis der Seeleute von The Third Fleet verantwortlich ist, und der geborgen werden muss, bevor er jemals gereinigt werden kann.",al={"geldkassettenschlüssel der intrepid","was öffnet der schlüssel","warum brauche ich den schlüssel"}},["1f8e42a3"]={q="Warum schickt Euch Erster Maat Fitzsimmons, anstatt selbst zu gehen?",a="Fitzsimmons ist tief traumatisiert und wird von Träumen seiner toten Crew und seines früheren Kommandanten heimgesucht. Von Schuldgefühlen und Angst erfüllt, kann er sich dem todgeweihten Wrack der INTREPID oder dem rachsüchtigen Geist von Kapitän Halyndor nicht selbst stellen.",al={"warum ich fitzsimmons","warum kann fitzsimmons das nicht tun","warum fitzsimmons euch braucht"}}},fp="17,312,18.449.0,20.413.1,46.118.0,24.184.0,58.212.0,42.146.0,55.151.0,45.210.0"}
P.entries["quest:2904"] = {n="Eine schöne Bescherung",s="Tief in den verstrahlten Ruinen von Gnomeregan liegt ein verletzter Goblin namens Kernobee zerschlagen unter Troggs, nachdem er von Dunkeleisenzwergen überfallen worden war. Seine Rettung bringt beunruhigende Informationen über die Verstrickung der Dunkeleisenzwerge in unterirdische Bohrmaschinerie ans Licht, die den ganzen Weg nach Beutebucht überbracht werden müssen.",h="Tief in den verstrahlten Ruinen von Gnomeregan liegt ein verletzter Goblin namens Kernobee zerschlagen unter...",kw={"beutebucht","clockwerk run","dunkeleisenzwerge","gnomeregan","kernobee","scooty","riesenbohranlage","tüftelwick","troggs"},ang={["faction:Alliance"]="Die Aufdeckung der dunklen Machenschaften der Dunkeleisenzwerge innerhalb der Grenzen von Dun Morogh bestätigt, dass Imperator Thaurissans Agenten die Wiederaufbaubemühungen der Allianz in Gnomeregan aktiv sabotieren.",["profession:Engineering"]="Die Entdeckung, dass Maschinisten der Dunkeleisenzwerge eine gewaltige Riesenbohranlage bauen, bereitet jedem Ingenieur, der fortschrittliche unterirdische Technologie im Auge behält, unmittelbare Sorge.",["race:Gnome"]="Einen gefangenen Bruder aus den kontaminierten Tiefen von Gnomeregan zu retten, ist eine Ehrenpflicht, besonders gegen die geballte Bosheit von Dunkeleisen-Infiltratoren und wilden Troggs."},sec={{t="Ein übel zugerichteter Überlebender",b="Beim Erkunden der gefährlichen inneren Kammern von Gnomeregan entdecken Abenteurer den gestrandeten Kernobee im Schlafsaalbereich. Der übel zugerichtete und benommene Goblin überlebte die Gefangennahme durch Dunkeleisenzwerge, die ihn zurückließen, um unter den wilden Troggs umzukommen. Ein freundliches Gesicht zu erblicken, ist seine einzige Chance, den Marsch zurück durch die kontaminierten Korridore zu überleben."},{t="Unterirdische Ränke",b="Kernobee besitzt entscheidende Informationen über finstere Mächte, die unter Dun Morogh am Werk sind. Er enthüllt, dass der Dunkeleisenklan tatkräftig am Bau einer gewaltigen Riesenbohranlage beteiligt ist. Während Kernobee über das Meer nach Ratschet flieht, um den Goblin-Ingenieur Tüftelwick vor dieser heraufziehenden Bedrohung zu warnen, schickt er seinen Retter nach Süden nach Beutebucht, um dem Goblin-Ingenieur Scooty Bericht zu erstatten."}},faq={{q="Wer ist Kernobee?",a="Kernobee ist ein Goblin, der sich tief in die Ruinen von Gnomeregan vorwagte. Er geriet in einen Hinterhalt, wurde von Dunkeleisenzwergen beinahe zu Tode geprügelt und den Troggs überlassen, bevor er gerettet werden konnte.",al={"kernobee","wer ist kernobee"}},{q="Wohin muss Kernobee eskortiert werden?",a="Kernobee muss sicher durch die feindseligen Hallen zurück zur Sicherheit des Ausgangs am Clockwerk Run und den oberen Eingangskorridoren der gefallenen Stadt geleitet werden.",al={"wohin kernobee bringen","eskortierziel","ausgang clockwerk run"}},{q="Warum waren die Dunkeleisenzwerge verwickelt?",a="Die Dunkeleisenzwerge haben im Untergrund Ränke geschmiedet und bei der Konstruktion und dem Bau einer gewaltigen Riesenbohranlage geholfen. Kernobee entdeckte diesen Plan, bevor die Zwerge ihn überfielen.",al={"warum dunkeleisenzwerge","riesenbohranlage der dunkeleisenzwerge","dunkeleisenzwerge in gnomeregan"}},{q="Wohin geht Kernobee nach seiner Flucht?",a="Nachdem er Sicherheit erreicht hat, begibt sich Kernobee über das Meer nach Ratschet im Brachland, um den Tüftler Tüftelwick vor der Verstrickung der Dunkeleisenzwerge in die unterirdische Bohranlage zu warnen.",al={"wohin ging kernobee","kernobee ratschet","tüftelwick warnung"}},{q="Warum müsst Ihr Scooty in Beutebucht Bericht erstatten?",a="Scooty ist ein in Beutebucht stationierter Goblin-Ingenieur, der mit Tüftelwick zusammenarbeitet und Operationen koordiniert, die hochentwickelte unterirdische Ausrüstung und Transpondernetzwerke betreffen.",al={"warum scooty","beutebucht abgabe","scooty verbindung"}},{q="Welcher Zusammenhang besteht zu Meckatorkes Erzfeind Thermaplugg?",a="Scooty erkennt die anhaltende Bedrohung, die von Meckatorkes Erzfeind Thermaplugg im Inneren von Gnomeregan ausgeht. Kernobee zu helfen verschafft Abenteurern Unterstützung und Vorräte, die zurückkehren wollen, um sich dem verräterischen Meckatorke zu stellen.",al={"thermaplugg verbindung","thermaplugg bekämpfen"}}},fx={["73352f2e"]={q="Warum muss Kernobee herauseskortiert werden?",a="Kernobee wurde von Dunkeleisenzwergen in einen Hinterhalt gelockt, fast zu Tode geprügelt und in einem Wohnbereich zurückgelassen, der von feindseligen Troggs überrannt wurde. Verletzt und tief in den zerstörten Hallen von Gnomeregan gefangen, kann er die Reise zum Ausgang nicht allein überleben. Entscheidend ist auch, dass er dringende Geheimdienstinformationen bei sich trägt: Er entdeckte, dass der Dunkeleisenzlan direkt an der Konstruktion einer riesigen Bohranlage beteiligt ist. Mit dem Leben davonzukommen ist seine einzige Chance, nach Ratschet zu reisen und seinen Partner Tinkerwiz zu warnen, bevor diese Maschinerie weiteres Unheil anrichtet.",al={"warum kernobee helfen","kernobee motiv","warum braucht kernobee hilfe"}},["9976ada5"]={q="Warum kann Kernobee Gnomeregan nicht alleine entkommen?",a="Kernobee ist kaum bei Bewusstsein, als Ihr ihn findet, nachdem er von seinen Dunkeleisenentführern schwer misshandelt wurde, bevor sie ihn in eine Grube voller Troggs warfen. Prellungen, unbewaffnet und bis aufs Äußerste geschwächt, hat er keine Hoffnung, sich an den verstrahlten Mutanten, den Konstrukten der Schurken und den wilden Troggs vorbeizukämpfen, die Clockwerk Run patrouillieren, ohne einen fähigen Abenteurer, der ihn beschützt.",al={"warum braucht kernobee euch","warum kann kernobee nicht kämpfen","warum ich kernobee"}}},fp="11,308,19.359.0,20.385.1,16.180.0,32.155.0,40.186.0,38.175.1,43.178.0,46.204.0"}
P.entries["quest:291"] = {n="Die Berichte",s="Bringt den Bericht von Senir Weißbart über die Frostmanetrolle von Kharanos zu Senator Barin Redstone in Eisenschmiede. Senir warnt, dass der Senator griesgrämig ist, und bittet Euch, nicht zu erwähnen, wer bei der Informationsbeschaffung geholfen hat.",h="Bringt den Bericht von Senir Weißbart über die Frostmanetrolle von Kharanos zu Senator Barin Redstone in...",kw={"barin redstone","zwergensenat","frostmane","high seat","eisenschmiede","kharanos","magni bronzebart","senir weißbart","die berichte"},ang={["faction:Alliance"]="Die Übergabe dient als frühe Einführung in den städtischen Aufbau von Eisenschmiede und die politische Bürokratie, die die Innenpolitik der Allianz innerhalb von Dun Morogh prägt.",["race:Dwarf"]="Für Zwerge bietet der Gang in den High Seat, um die Depesche zu überbringen, einen Einblick aus erster Hand in das empfindliche Gleichgewicht zwischen der Krone von König Magni und der parlamentarischen Macht des Zwergensenats."},sec={{t="Eine Depesche in die Hauptstadt",b="Nach einer gewagten Aufklärungsmission tief in der Höhle der Frostmähnen verfasst Senir Weißbart einen dringenden Bericht, der die wachsende Trollbedrohung für Dun Morogh detailliert beschreibt. Der Bergsteiger, der in Kharanos stationiert ist, benötigt einen Boten, um diese nachrichtendienstlichen Erkenntnisse direkt an Senator Barin Redstone in Eisenschmiede zu übermitteln. In dem Bestreben, seinen eigenen Ruf in den Augen der Regierung zu wahren, rät Whitebeard seinem Läufer fröhlich, nicht zu erwähnen, wer tatsächlich die gefährliche Arbeit in den verschneiten Felsen geleistet hat."},{t="Reibereien im High Seat",b="Als das Dokument Senator Redstone am königlichen Hof übergeben wird, löst es sofort Empörung aus. Anstatt Dankbarkeit für die Informationen über feindliche Trollbewegungen zu zeigen, sträubt sich der griesgrämige Senator dagegen, dass die persönliche Autorität von König Magni Bronzebart angeführt wurde, um Whitebeards Operationen zu sanktionieren. Die Übergabe offenbart einen anhaltenden Machtkampf innerhalb der Regierungshallen von Eisenschmiede und unterstreicht, wie sehr der Senat exekutive Dekrete und nicht genehmigte Feldeinsätze, die im Namen des Königs durchgeführt werden, ablehnt."}},faq={{q="Wer ist Senir Weißbart?",a="Senir Weißbart ist ein zwergischer Bergsteiger, der in der Nähe von Kharanos in Dun Morogh stationiert ist. Er beaufsichtigt die Spähtrupps und die militärische Aufklärung gegen die Frostmanetrollstämme, die in zwergische Siedlungen eindringen.",al={"senir weißbart","wer gibt die berichte","whitebeard kharanos"}},{q="Wer ist Senator Barin Redstone?",a="Barin Redstone ist ein griesgrämiger, aristokratischer Zwergensenator, der sich im Thronsaal von Eisenschmiede in der Nähe von König Magni Bronzebart aufhält. Er ist ein erbitterter Verteidiger der legislativen Autorität und lässt sich leicht von gewöhnlichen Bittstellern verärgern.",al={"barin redstone","wer ist der senator","redstone eisenschmiede"}},{q="Warum ist Senator Redstone wütend über den Bericht?",a="Senir warnt, dass Redstone ein griesgrämiges Wesen hat. Die Reaktion des Senators auf den Bericht wird deutlich, wenn Ihr ihn überbringt.",al={"warum ist redstone wütend","warum schreit der senator","senat gegen magni"}},{q="Warum bittet Senir Weißbart darum, Eure Hilfe geheim zu halten?",a="Whitebeard möchte, dass seine Vorgesetzten in Eisenschmiede glauben, er habe die mühsame Feldaufklärung persönlich geleitet und abgeschlossen, um seinen Status zu festigen, anstatt zuzugeben, dass ein umherziehender Abenteurer die Mission durchgeführt hat.",al={"warum nimmt senir das lob für sich in anspruch","whitebeard hat sich mit fremden federn geschmückt","senirs geheimnis"}},{q="Wo wird der Bericht abgegeben?",a="Der Bericht wird Senator Barin Redstone im High Seat von Eisenschmiede übergeben, der großen Kammer, in der König Magni Bronzebart Hof hält.",al={"wo gibt man die berichte ab","standort barin redstone","abgabe die berichte"}},{q="Was verrät diese Quest über die Politik von Eisenschmiede?",a="Die Übergabe stellt den Senat von Eisenschmiede und die Beamten vor, die Berichte von der Grenze entgegennehmen. Redstones Reaktion bietet einen genaueren Einblick in seine Politik.",al={"eisenschmiede regierung hintergrundgeschichte","zwergensenat hintergrundgeschichte","magni gegen senat"}}},fx={bde96c47={q="Warum braucht Senir Weißbart Euch, um den Bericht abzuliefern, anstatt es selbst zu tun?",a="Senir Weißbart bleibt in Dun Morogh stationiert, um die Feldoperationen gegen lokale Bedrohungen wie die Frostmähnentrolle zu beaufsichtigen. Noch wichtiger ist, dass er möchte, dass der Senat und seine Vorgesetzten glauben, er arbeite unermüdlich an der Front, wobei er Kurieraufgaben und die unangenehme Aufgabe, einem mürrischen Senator gegenüberzutreten, einem entbehrlichen Reisenden überlässt.",al={"warum mich mit bericht senden","warum liefert senir den bericht nicht ab","warum ich berichte"}}},fp="11,209,25.484.0,25.493.1,24.200.0,30.215.0,47.121.1,55.213.0,30.144.0,53.151.1"}
P.entries["quest:292"] = {n="Das Auge von Paleth",s="In dieser Quest birgt ein Abenteurer einen geschwärzten, pulsierenden Edelstein namens Verfluchtes Auge von Paleth aus dem überfluteten Wrack der Intrepid. Auf Geheiß des von Geistern heimgesuchten Seemanns Fitzsimmons geborgen, muss das bösartige Artefakt in den Hafen von Menethil gebracht werden, damit der Zwergenpriester Glorin Stahlbraue ergründen kann, wie sich dessen Verderbnis reinigen lässt.",h="In dieser Quest birgt ein Abenteurer einen geschwärzten, pulsierenden Edelstein namens Verfluchtes Auge von...",kw={"verfluchtes auge von paleth","auge von paleth","fitzsimmons","glorin stahlbraue","intrepid","der hafen von menethil","die dritte flotte","sumpfland"},ang={["class:Priest"]="Die Auseinandersetzung mit der Entweihung eines heiligen Artefakts wie dem Auge von Paleth verleiht dieser Untersuchung unmittelbare Relevanz für Priester des Heiligen Lichts.",["faction:Alliance"]="Die Dritte Flotte war eine Expedition der Allianz, deren Zerstörung den Hafen von Menethil verwundbar zurückließ; die Bergung ihrer Überreste hilft dabei, den Verlust der gefallenen Kameraden aufzuarbeiten.",["race:Dwarf"]="Die Entdeckung verlorener Artefakte vor den Küsten von Khaz Modan knüpft an das Bestreben der Zwerge an, verborgene Relikte wiederzuerlangen – unterstützt von Geistlichen aus Eisenschmiede wie Glorin Stahlbraue."},sec={{t="Ein verdorbenes Relikt",b="Unter den tückischen Gewässern der Baradinbucht, geborgen in der verschlossenen Kassette des gesunkenen Schiffs Intrepid, liegt kein gewöhnlicher Schatz. Die Truhe birgt eine geschwärzte Kugel, die von einem beunruhigenden Glanz pulsiert: ein Auge von Paleth. Statt heiligem Licht zu strahlen, wurde dieser besondere Stein zu einem Werkzeug des Leids verzerrt, eng verbunden mit den ruhelosen Geistern und dem Verderben, das die Seeleute der Dritten Flotte ereilte."},{t="Suche nach der Priesterschaft",b="In dem Wissen, dass solch dunkle Magie gewöhnliches Bergungsgut übersteigt, wird das Artefakt direkt an Land in den Hafen von Menethil gebracht. Dort untersucht Glorin Stahlbraue, ein Zwergenpriester des Heiligen Lichts, die Anomalie. Obwohl er erstaunt ist, dass sich ein derart heiliges Relikt jemals im Besitz der Dritten Flotte befand, erkennt Glorin sofort dessen unnatürliche Verderbnis und bereitet die Rituale vor, die nötig sind, um den dunklen Einfluss zu bannen."}},faq={{q="Was ist das Auge von Paleth?",a="Das Auge von Paleth ist ein uralter und mächtiger heiliger Edelstein. Normalerweise mit heiligen Energien erfüllt, befand sich dieses besondere Exemplar an Bord der Intrepid, einem gesunkenen Schiff der Dritten Flotte, und wurde verdreht und verflucht, sodass es nun dunkle Magie ausstrahlt.",al={"auge von paleth lore","was ist paleth","verfluchtes auge von paleth"}},{q="Wo wurde das Auge geborgen?",a="Es wird aus einer verschlossenen Kassette an Bord des überfluteten Wracks der Intrepid geborgen, das unweit der nebelverhangenen Küste des Sumpflands liegt.",al={"wo finde ich das auge","auge von paleth fundort","kassette der intrepid"}},{q="Warum interessiert sich Glorin Stahlbraue für das Artefakt?",a="Glorin Stahlbraue ist ein im Hafen von Menethil stationierter Zwergenpriester. Als Diener des Heiligen Lichts verfügt er über das heilige Wissen, das nötig ist, um uralte Relikte zu erkennen und die Rituale einzuleiten, die finstere Flüche brechen.",al={"wer ist glorin stahlbraue","warum steelbrow"}},{q="Woher weiß Fitzsimmons von dem Auge?",a="Fitzsimmons ist ein Überlebender der Dritten Flotte, der noch immer von der Tragödie heimgesucht wird. Traumatisiert suchte er Zuflucht in der Taverne von Menethil und wusste von dem finsteren Relikt, das in den Trümmern verborgen lag und seine gefallenen Schiffskameraden peinigte.",al={"fitzsimmons verbindung","warum schickte mich fitzsimmons"}},{q="Warum ist das Auge verflucht?",a="Während die genaue Verderbnis mit dem übernatürlichen Untergang und den ruhelosen Untoten zusammenhängt, die die Schiffswracks der Dritten Flotte heimsuchen, absorbierte das Artefakt während oder nach der Katastrophe, die die Flotte auf den Meeresgrund riss, finstere Energien.",al={"warum ist es verflucht","ursprung des fluchs des auges"}},{q="Was geschieht, nachdem man Glorin das Auge übergeben hat?",a="Glorin untersucht den verfluchten Edelstein und stellt fest, dass er nicht in seinem verdorbenen Zustand verbleiben darf; er weist den Abenteurer an, das Relikt von seinem unheilvollen Einfluss zu reinigen.",al={"folgequest","was tun mit dem auge"}}},fp="17,334,16.425.0,22.405.1,26.228.0,28.139.0,50.232.0,40.218.0,22.241.0,44.166.1"}
P.entries["quest:2922"] = {n="Rettet Techbots Hirn!",s="Tinkmaster Overspark beauftragt Abenteurer der Allianz damit, den Techbots Speicherkern aus den verstrahlten Ruinen von Gnomeregan zu bergen. Der einst so hilfreiche mechanische Assistent erlitt beim Fall der Stadt eine schwere Gehirnpolarisierung, die ihn durchdrehen ließ. Overspark hofft, dass die Bergung seines Kerns es ihm ermöglicht, den Schaden rückgängig zu machen und seine geliebte Schöpfung wiederherzustellen.",h="Tinkmaster Overspark beauftragt Abenteurer der Allianz damit, den Techbots Speicherkern aus den verstrahlten...",kw={"gnomeregan","speicherkern","negatronisch","overspark","positronisch","techbot","tüftlerstadt"},ang={["faction:Alliance"]="Die Bergung wertvoller verlorener Technologie aus dem verseuchten Perimeter von Gnomeregan ist entscheidend für die Unterstützung der gnomischen Flüchtlinge, die in Eisenschmiede Schutz suchen.",["profession:Engineering"]="Der Übergang von Techbots Prozessor von positronisch zu negatronisch ist eine warnende Geschichte für Tüftler, die mit hochkomplexen mathematischen Berechnungsmatrizen arbeiten.",["race:Gnome"]="Für gnomische Ingenieure repräsentiert Techbot den tragischen Kollateralschaden durch den Verlust ihrer Heimatstadt, was beweist, dass selbst ihre besten intellektuellen Errungenschaften durch die Katastrophe verzerrt werden können."},sec={{t="Ein verdrehter Verstand",b="Vor der Katastrophe, die Gnomeregan forderte, diente Techbot als ein Wunderwerk gnomischer Ingenieurskunst. Der von Tinkmaster Overspark entwickelte Automat unterstützte Forscher mit zahllosen integrierten Gerätschaften und einem enzyklopädischen Wissensspeicher. Doch das Chaos der Trogg-Invasion und das Entweichen giftiger Strahlung verschonten die Maschine nicht. Ein umherirrender elektrischer Schlag erschütterte Techbots empfindliche interne Architektur und polarisierte sein positronisches Gehirn vollständig in einen instabilen negatronischen Zustand."},{t="Bergungsoperation",b="Eingesperrt in den verseuchten Hallen von Gnomeregan wandert Techbot nun in einem manischen Wahn umher und greift jeden in Sichtweite an. Trotz der gewaltsamen Fehlfunktion weigert sich Overspark, seinen geschätzten Assistenten als Schrott abzuschreiben. Er rekrutiert fähige Agenten, um den Amok laufenden Automaten aufzuspüren, seinen Speicherkern aus dem Metallgehäuse zu extrahieren und ihn sicher nach Eisenschmiede zu bringen, damit der Tinkmaster die Polarisierung rückgängig machen und Techbots Verstand reparieren kann."}},faq={{q="Wer ist Techbot?",a="Techbot ist ein mechanischer Assistent, der von Tinkmaster Overspark erfunden wurde. Vor dem Fall von Gnomeregan unterstützte er den Tinkmaster und seine Mitarbeiter mit seiner riesigen Datenbank an Wissen und eingebauten Gerätschaften.",al={"was ist techbot","techbot hintergrundgeschichte","overspark techbot"}},{q="Warum ist Techbot feindselig geworden?",a="Während des Falls von Gnomeregan erschütterte ein umherirrender elektrischer Funke Techbots positronisches Gehirn. Der Schock kehrte seine neuronale Ausrichtung in einen negatronischen Zustand um und verwandelte seine hilfreiche Persönlichkeit in eine rasende Wut.",al={"warum ist techbot verrückt","was ist mit techbot passiert","techbot polarisierung"}},{q="Wo kann man Techbot finden?",a="Techbot wandert durch die äußeren Korridore und Bereitstellungshallen von Gnomeregan, knapp hinter den Außenlinien, an denen die verbannten Gnome und die Expeditionsstreitkräfte der Zwerge operieren.",al={"wo ist techbot","techbot standort","techbot finden"}},{q="Wer vergibt diese Quest?",a="Tinkmaster Overspark bietet die Quest in der Tüftlerstadt in Eisenschmiede an, wo er im Auftrag von Hochtüftler Gelbin Mekkadrill die Bergungs- und Forschungsarbeiten beaufsichtigt.",al={"wer startet rettet techbots gehirn","overspark standort"}},{q="Kann Techbot wirklich repariert werden?",a="Tinkmaster Overspark glaubt, dass die Bergung von Techbots Speicherkern es ihm ermöglichen wird, die genaue Ursache der negatronischen Polarisierung zu diagnostizieren und den Automaten wieder funktionsfähig zu machen.",al={"ist techbot repariert","kann man techbot reparieren","überlebt techbot"}},{q="Was passiert nach der Rückgabe des Speicherkerns?",a="Nach Erhalt des Kerns macht sich Overspark sofort an die Arbeit, die invertierten Schaltkreise zu demontieren und neu zu konfigurieren, obwohl es sich als Herausforderung erweist, die richtigen Werkzeuge in seiner vollgestopften Werkstatt zu finden.",al={"techbot quest abschluss","techbot kern abgeben"}}},fx={e9c625cc={q="Warum möchte Tinkmaster Overspark, dass Techbots Gehirn gerettet wird?",a="Techbot ist Tinkmaster Oversparks wertvollste Schöpfung, die ihm und seinen Mit-Erfindern einst mit einem riesigen Archiv an Wissen und praktischen Gizmos diente. Als Gnomeregan fiel, polarisierte ein irrender elektrischer Schlag das positronische Gehirn des Automaten in einen negatronischen Zustand, was ihn in den Wahnsinn trieb. Overspark weigert sich, seine Schöpfung aufzugeben und hofft, dass das Studium des Kerns es ihm ermöglichen wird, den Schaden rückgängig zu machen und seinen Assistenten wiederherzustellen.",al={"overspark motiv","warum techbot retten","warum will overspark techbot"}},["6f8a4042"]={q="Wofür ist Techbots Speicherkern?",a="Der Speicherkern beherbergt Techbots digitalisierten Geist und sein angesammeltes Wissen. Da sich das positronische Gehirn des Automaten während des Falls von Gnomeregan umkehrte, ist das Extrahieren dieser Komponente der einzige Weg, die Polaritätsverschiebung zu untersuchen und zu versuchen, den mechanischen Assistenten umzuprogrammieren oder wieder aufzubauen.",al={"techbots speicherkern","wofür ist der speicherkern"}}},fp="21,359,15.501.0,17.438.0,15.206.0,31.212.0,27.166.0,21.164.0,30.180.0,45.210.1"}
P.entries["quest:2923"] = {n="Tüftlermeister Oberfunks",s="Dieser Auftrag leitet Abenteurer der Allianz in Sturmwind nach Tüftlerstadt in Eisenschmiede, wo Tüftlermeister Overspark eine tragische Fehlfunktion betrauert. Bruder Sarno berichtet, dass Oversparks mechanische Schöpfung, Techbot, inmitten der verstrahlten Ruinen von Gnomeregan durchgedreht ist. Den Tüftlermeister zu erreichen, ist der erste Schritt, um den Speicherkern des abtrünnigen Konstrukts zu bergen.",h="Dieser Auftrag leitet Abenteurer der Allianz in Sturmwind nach Tüftlerstadt in Eisenschmiede, wo...",kw={"gnomeregan","eisenschmiede","overspark","sarno","techbot","tüftlerstadt","tüftlermeister"},ang={["faction:Alliance"]="Die Unterstützung der vertriebenen gnomischen Flüchtlinge in Tüftlerstadt stärkt die lebenswichtigen Verbindungen zwischen Sturmwind und den Königreichen der Zwerge und Gnome.",["profession:Engineering"]="Oversparks Schöpfungen repräsentieren den neuesten Stand der gnomischen Genialität, was jede Gelegenheit, seine abtrünnigen Konstrukte zu untersuchen, zu einem lehrreichen Unterfangen macht.",["race:Gnome"]="Jede geborgene Schöpfung und jeder wiederhergestellte Speicherkern repräsentiert ein Stück Eurer gefallenen Heimat, das bewahrt wurde, bevor Strahlung und Troggs sie vollständig zerstörten."},sec={{t="Ein Flehen aus der Kathedrale",b="Bruder Sarno, der sich in Sturmwind um Reisende kümmert, berichtet von einem unglücklichen Dilemma, das sich unter den gnomischen Flüchtlingen anbahnt. Tüftlermeister Overspark – einer der brillanten Köpfe hinter den Wundern von Gnomeregan – ist verzweifelt über die Korruption von Techbot, einem einst hilfreichen mechanischen Diener, der den Tüftlern treu gedient hatte, bevor die Stadt in Trümmer fiel."},{t="Nach Tüftlerstadt",b="Die Quest schickt hilfreiche Seelen mit der Tiefenbahn hinauf in Eisenschmiedes geschäftiges Viertel Tüftlerstadt. Dort sucht Overspark verzweifelt nach Abenteurern, die mutig genug sind, in die verstrahlten Hallen von Gnomeregan zurückzukehren, um die Überreste von Techbots Fähigkeiten zu retten, bevor das Konstrukt irreparablen Schaden anrichtet."}},faq={{q="Wer ist Tüftlermeister Overspark?",a="Tüftlermeister Overspark ist ein Gnom-Ingenieur und der Ausbilder für Ingenieurskunst der Gnome. Derzeit ist er in Tüftlerstadt in Eisenschmiede stationiert und arbeitet unermüdlich daran, Rückeroberungsbemühungen zu koordinieren und verirrte gnomische Technologie aus ihrer zerstörten Hauptstadt zu retten.",al={"overspark","wer ist overspark","tüftlermeister overspark"}},{q="Wer beginnt diese Quest?",a="Bruder Sarno, ein menschlicher Kleriker in Sturmwind, gibt Abenteurern diese Quest, um sie zu den Gnomen zu führen, die in Eisenschmiede Hilfe benötigen.",al={"questgeber","wo erhält man die quest von tüftlermeister overspark"}},{q="Was ist Techbot?",a="Techbot ist eine mechanische Schöpfung, die von Tüftlermeister Overspark entworfen wurde. Ursprünglich ein hilfreiches und freundliches Werkzeug für gnomische Ingenieure, entwickelte es nach dem katastrophalen Fall von Gnomeregan eine Fehlfunktion und drehte in der verstrahlten Stadt durch.",al={"techbot","was ist mit techbot passiert"}},{q="Wo findet man Tüftlermeister Overspark?",a="Overspark befindet sich in Tüftlerstadt, dem Gnomviertel im östlichen Bezirk von Eisenschmiede, umgeben von anderen Flüchtlings-Tüftlern und experimentellen Maschinen.",al={"standort von overspark","wo ist overspark"}},{q="Was passiert, nachdem man mit Overspark gesprochen hat?",a="Sobald man sich bei Overspark meldet, bietet er die Quest 'Rettet Techbots Gehirn!' an und bittet Euch, nach Gnomeregan zu reisen, um Techbot zu deaktivieren und seinen Speicherkern zu bergen, damit er wiederhergestellt werden kann.",al={"nächste quest","rettet techbots gehirn"}},{q="Warum interessiert sich die Allianz für die kaputte Maschine eines Erfinders?",a="Neben dem Mitgefühl für die verbannten Gnome stellen umherstreifende abtrünnige Automaten in Gnomeregan eine unmittelbare Bedrohung für alle Expeditionen dar, die versuchen, die unterirdische Hauptstadt zurückzuerobern oder die Grenzen von Dun Morogh zu schützen.",al={"warum ist techbot wichtig","bedeutung von techbot"}}},fx={["9c70ad2e"]={q="Warum schickt Euch Bruder Sarno zu Tinkmaster Overspark?",a="Bruder Sarno erinnert sich an Techbot als einen hilfreichen, sanften Automaten, der den Gnomen treu diente, bevor Gnomeregan in Chaos versank. Dass Overspark über die Fehlfunktion seiner Schöpfung verstört ist, beunruhigt den heiligen Mann. In der Hoffnung, dass die Maschine noch gerettet werden kann, anstatt verrotten oder zerstört zu werden, leitet Sarno mitfühlende Abenteurer zur Tüftlerstadt weiter, damit der verzweifelte Tinkmaster die Hilfe bekommt, die er dringend benötigt.",al={"warum kümmert sich bruder sarno","bruder sarno motiv","warum zu overspark senden"}}},fp="20,370,25.357.0,14.316.0,28.246.0,22.144.0,16.228.0,40.166.0,41.185.0,63.209.0"}
P.entries["quest:2924"] = {n="Grundlegende Artifixe",s="Grundlegende Artifixe ist eine Quest der Allianz, die von Klockmort Spannsplint in Tüftlerstadt in Eisenschmiede angeboten wird. Abenteurer werden damit beauftragt, in die Tiefen der verstrahlten Ruinen von Gnomeregan vorzudringen, um entscheidende universelle Komponenten zu bergen, die während der verzweifelten Evakuierung der Gnome zurückgelassen wurden.",h="Grundlegende Artifixe ist eine Quest der Allianz, die von Klockmort Spannsplint in Tüftlerstadt in...",kw={"artifix-extrapolator","grundlegende artifixe","gnomeregan","gnomeningenieurskunst","eisenschmiede","klockmort spannsplint","tüftlerstadt"},ang={["faction:Alliance"]="Den verbannten Gnomen bei der Rückholung ihrer verlorenen Technologie zu helfen, stärkt das technologische Rückgrat der Allianz mit Sitz in Eisenschmiede.",["profession:Engineering"]="Jeder Ingenieur versteht die Pein, wenn eine einzige universelle Komponente fehlt; die Bergung dieser Geräte unterstreicht die schiere Raffinesse der Handwerkskunst Gnomeregans vor dem Fall.",["race:Gnome"]="Die Beschaffung dieser Bauteile ist eine Frage des Nationalstolzes und der technologischen Kontinuität, die dafür sorgt, dass das Exil in Eisenschmiede den Erfindergeist der Gnome nicht erstickt."},sec={{t="Beim Exodus vergessen",b="Als die Trogg-Invasion Gnomeregan überrannte und giftige Strahlung die Korridore flutete, konnten die fliehenden Gnome nur das mitnehmen, was unmittelbar zur Hand war. Zu den zahllosen zurückgelassenen Wundern gehörten Vorräte an grundlegenden Artifixen – spezialisierte, nahezu universelle mechanische Bauteile, die von Tüftlern und Handwerkern hoch geschätzt werden. Meistertüftler Klockmort Spannsplint, der nun von Tüftlerstadt in Eisenschmiede aus arbeitet, sieht seine bahnbrechenden neuen Experimente ohne sie zum Stillstand verurteilt."},{t="Durchstöbern der Extrapolatoren",b="Diese lebenswichtigen Vorrichtungen befinden sich in schweren, dampfbetriebenen Lagereinheiten, den sogenannten Artifix-Extrapolatoren, tief in der gefallenen Stadt. Um sie zu bergen, muss man verstrahlten Hallen trotzen, in denen mutierte Lepragnome, fehlfunktionierende Verteidigungsautomaten und wilde Troggs lauern. Die Bergung eines Vorrats von zwölf Komponenten ermöglicht es Klockmort, seine wichtige Arbeit wiederaufzunehmen und die gnomische Innovation trotz ihres Exils voranzutreiben."}},faq={{q="Was ist ein grundlegendes Artifix?",a="Ein grundlegendes Artifix ist eine nahezu universelle mechanische Komponente, die von gnomischen Ingenieuren entwickelt wurde. Von Tüftlern und Schmieden hochgeschätzt, dient es als entscheidender Baustein für komplizierte Apparaturen und fortschrittliche experimentelle Maschinen.",al={"was sind grundlegende artifixe","grundlegendes artifix","was ist das"}},{q="Wer vergibt die Quest Grundlegende Artifixe?",a="Die Quest wird von Klockmort Spannsplint vergeben, einem gnomischen Ingenieur in Tüftlerstadt in Eisenschmiede.",al={"questgeber","wer startet dies","wo bekomme ich grundlegende artifixe"}},{q="Wo findet man die grundlegenden Artifixe in Gnomeregan?",a="Sie lagern tief im Inneren von Gnomeregan in Behältern namens Artifix-Extrapolatoren, die wie hohe, dampfbetriebene Schränke aussehen und in den unteren Hallen verteilt sind.",al={"wo sind sie","extrapolator standort","wie man artifixe findet"}},{q="Warum wurden sie in Gnomeregan zurückgelassen?",a="Während der plötzlichen Trogg-Invasion und der darauffolgenden radioaktiven Katastrophe flohen die Gnome in heller Panik aus ihrer Hauptstadt. Im Chaos der Evakuierung wurden die Vorräte dieser unverzichtbaren Komponenten in den unteren Werkstätten zurückgelassen.",al={"warum zurückgelassen","warum sind sie in gnomeregan","geschichte der artifixe"}},{q="Wofür braucht Klockmort sie?",a="Klockmort Spannsplint benötigt einen beträchtlichen Vorrat dieser Universalkomponenten, um eine Reihe neuer, komplexer Experimente durchzuführen, die er in seiner Werkstatt in Eisenschmiede vorbereitet.",al={"warum will klockmort sie","klockmorts plan"}},{q="Ist Klockmorts Grundlagen vor dieser Quest erforderlich?",a="Obwohl die Kurierquest 'Klockmorts Grundlagen' Euch mit Klockmort bekanntmacht und Euch zu seiner Werkstatt führt, ist sie keine zwingende Voraussetzung für die Annahme von Grundlegende Artifixe.",al={"voraussetzung","vorquest","klockmorts grundlagen erforderlich"}}},fx={["41f0ee2b"]={q="Warum braucht Klockmort externe Abenteurer, um Gnomeregan zu betreten?",a="Gnomeregan ist keine funktionierende Stadt mehr – es ist ein tödliches, verstrahltes Kriegsgebiet, das von Troggs und wahnsinnigen Lepragnomen überrannt wird. Gnomische Tüftler wie Klockmort Spannerspan sind Forscher, keine Frontsoldaten, und die überlebenden Gnome in der Tüftlerstadt sind Flüchtlinge, die von der Gastfreundschaft der Zwerge leben, anstatt eine Invasionsarmee zu sein. Das Vorstoßen in die tiefsten, gefährlichsten Sektoren der zerstörten Stadt erfordert erfahrene Abenteurer, die in der Lage sind, sich durch Wellen feindseliger Mutanten zu kämpfen, um die Lagercontainer zu erreichen.",al={"warum mich senden","warum abenteurer","warum kann klockmort sie nicht holen"}}},fp="21,289,23.464.0,25.423.0,32.236.0,42.104.0,56.182.0,40.234.0,34.187.0,60.187.0"}
P.entries["quest:2925"] = {n="Klockmorts Grundlagen",s="Klockmorts Grundlagen ist eine Vorladung, die eine dringende Nachricht des Nachtelfen Mathiel an seinen Gnomenfreund Klockmort Spannsplint überbringt. Da Mathiel seine Pflichten nicht vernachlässigen kann, um nach Dun Morogh zu reisen, bittet er vorbeikommende Reisende der Allianz darum, Klockmorts Hilferuf in Eisenschmiede zu beantworten. Der Aufruf schickt Abenteurer nach Tinkertown, um sich auf ein gefährliches Unterfangen in den verstrahlten Hallen von Gnomeregan vorzubereiten.",h="Klockmorts Grundlagen ist eine Vorladung, die eine dringende Nachricht des Nachtelfen Mathiel an seinen...",kw={"grundlegende artifixe","gnomeregan","eisenschmiede","klockmort spannsplint","klockmorts grundlagen","lepragnome","mathiel","tinkertown"},ang={["faction:Alliance"]="Diese Quest schlägt eine Brücke über die weiten Gebiete des Allianzterritoriums und verbindet die Länder der Nachtelfen mit den zwergischen Berghallen von Eisenschmiede zur gemeinsamen Verteidigung.",["race:Gnome"]="Für Gnome hilft jeder Botengang, der Abenteurer nach Tinkertown lenkt, bei dem verzweifelten, anhaltenden Kampf um die Rückeroberung ihrer verlorenen Heimat Gnomeregan."},sec={{t="Ein Ruf über Kontinente hinweg",b="Nachrichten reisen selbst in unruhigen Zeiten weit. Als Klockmort Spannsplint mutige Verbündete für eine Mission in Gnomeregan brauchte, wandte er sich über das Meer hinweg an seinen Nachtelfenbekannten Mathiel. Mathiel, der an seinen eigenen Posten gebunden ist, kann die Reise in das Bergkönigreich nicht selbst antreten, weigert sich jedoch, die Bitte seines Freundes unbeantwortet zu lassen. Stattdessen bittet er fähige Allianzabenteurer, die ihn auf der Terrasse der Krieger in Darnassus aufsuchen, den weiten Weg nach Dun Morogh an seiner statt auf sich zu nehmen."},{t="Der Weg nach Tinkertown",b="Klockmort Spannsplint operiert von Tinkertown aus, dem geschäftigen Flüchtlingsviertel von Eisenschmiede, in dem sich vertriebene Gnome seit dem katastrophalen Fall ihrer unterirdischen Stadt versammelt haben. Inmitten des Surrens von Zahnrädern und Dampfwolken schmiedet Klockmort Pläne, um lebenswichtige Maschinen zu bergen, die in den verseuchten Korridoren von Gnomeregan zurückgelassen wurden. Mathiels Vermittlung führt Abenteurer direkt zu Klockmorts Werkstatt und spannt sie für seine Rückeroberungsbemühungen ein."}},faq={{q="Wer vergibt die Quest Klockmorts Grundlagen?",a="Die Quest wird von Mathiel angeboten, einem Nachtelfen, der Nachricht von seinem Gnomenfreund Klockmort Spannsplint erhalten hat. Mathiel kann nicht selbst nach Eisenschmiede reisen und bittet daher vertrauenswürdige Abenteurer der Allianz, an seiner statt zu gehen.",al={"questgeber","wer startet klockmorts grundlagen","mathiel quest"}},{q="Wo finde ich Klockmort Spannsplint?",a="Klockmort Spannsplint hält sich in Tinkertown auf, dem Gnomenviertel von Eisenschmiede. Er befindet sich inmitten der Werkstätten und Flüchtlingsapparaturen, die von den aus ihrer verlorenen Heimat vertriebenen Gnomen errichtet wurden.",al={"wo ist klockmort","klockmort aufenthaltsort","klockmort spannsplint eisenschmiede"}},{q="Warum braucht Klockmort Hilfe in Gnomeregan?",a="Gnomeregan wurde überrannt und durch giftigen radioaktiven Niederschlag verstrahlt, sodass es nun von Troggs, wahnsinnigen Lepragnomen und durchgedrehten Automaten wimmelt. Klockmort benötigt unerschrockene Abenteurer, die den Gefahren trotzen und essenzielle mechanische Bauteile aus den Ruinen bergen.",al={"was will klockmort","warum gnomeregan mission","klockmort absicht"}},{q="Ist diese Quest erforderlich, um Gnomeregan zu betreten?",a="Nein, diese Quest ist eine optionale Brotkrumenquest, die Euch von Mathiel direkt zu Klockmort Spannsplint führt. Ihr könnt Klockmort in Eisenschmiede auch ohne Mathiels Vorstellung ansprechen und seine Dungeon-Aufträge direkt annehmen.",al={"ist diese quest pflicht","voraussetzung für gnomeregan","kann man klockmorts grundlagen überspringen"}},{q="Welche Quest folgt auf Klockmorts Grundlagen?",a="Das Gespräch mit Klockmort Spannsplint schließt diesen Botengang ab und führt direkt zur Quest Grundlegende Artifixe, die Abenteurer tief in den Dungeon von Gnomeregan schickt.",al={"nächste quest","folgequest","folgequest grundlegende artifixe"}},{q="Warum ist Mathiel daran interessiert, einem Gnomen in Eisenschmiede zu helfen?",a="Mathiel und Klockmort sind seit langem persönlich befreundet. Auch wenn Mathiel weit entfernt stationiert ist und seinen derzeitigen Posten nicht verlassen kann, treibt ihn die Sorge um seinen Freund dazu, jemanden zu finden, der vertrauenswürdig genug ist, um ihm beizustehen.",al={"mathiel verbindung","warum kümmert sich mathiel","mathiel und klockmort"}}},fx={b4ad922f={q="Warum bittet Euch Mathiel darum, zu gehen, anstatt selbst zu reisen?",a="Mathiel ist durch seine Pflicht an seinen Posten in Darnassus gebunden und kann nicht über das Meer nach Dun Morogh reisen. Obwohl es ihm das Herz bricht, seinem Freund Klockmort nicht direkt helfen zu können, muss er sich auf einen fähigen Abenteurer verlassen, der in Richtung Eisenschmiede reist, um den Ruf stattdessen zu beantworten.",al={"warum kann mathiel nicht","warum mathiel sendet mich","warum hilft mathiel nicht klockmort"}}},fp="22,394,24.488.0,22.460.0,43.215.0,38.184.0,43.262.0,43.221.0,42.180.0,58.217.0"}
P.entries["quest:2926"] = {n="Gnogaine",s="Gnogaine ist eine Quest der Allianz, die von Ozzie Wechselvolt in Kharanos angeboten wird. In einem exzentrischen Versuch, ein Heilmittel für die Lepragestrickten Gnome zu synthetisieren – oder vielleicht ein außerordentlich starkes Getränk zusammenzubrauen –, beauftragt Ozzie Abenteurer damit, sich nach Gnomeregan zu wagen, um radioaktiven Niederschlag von leuchtenden Troggs zu sammeln.",h="Gnogaine ist eine Quest der Allianz, die von Ozzie Wechselvolt in Kharanos angeboten wird.",kw={"gnoarn","gnogaine","gnomeregan","grünes leuchten","verstrahlter trogg","kharanos","lepragestrickter gnom","ozzie wechselvolt","phiole","strahlung"},ang={["faction:Alliance"]="Die aus Gnomeregan quellende Kontamination bedroht Dun Morogh als Ganzes, wodurch jeder Versuch, den Niederschlag zu verstehen oder zu neutralisieren, von entscheidender Bedeutung für die regionale Sicherheit ist.",["profession:Engineering"]="Der Umgang mit unverarbeitetem radioaktivem Ausfluss mithilfe abgeschirmter Bleiphiolen zeigt typische, hochriskante Gnomen-Feldforschung in Aktion.",["race:Gnome"]="Für die verbannten Gnome macht die Verzweiflung, irgendein Gegenmittel für ihre verstrahlten Brüder zu finden, selbst Ozzies grenzwertig verrückte Experimente einen Versuch wert."},sec={{t="Ein Heilmittel oder ein Cocktail",b="Seit dem Fall von Gnomeregan haben sich Flüchtlinge wie Gnoarn vollkommen darauf fixiert, die eindringenden Troggs zu vernichten und das radioaktive Leiden umzukehren, das ihre Brüder mutieren ließ. Im Gegensatz dazu verfolgen Ozzie Wechselvolt und sein Partner Razzle Flinkspross aus ihrer Werkstatt in Kharanos einen etwas weniger orthodoxen Ansatz. Während er vorgibt, nach einem Heilmittel für die Lepragestrickten Gnome zu suchen, gibt Ozzie offen zu, dass ihre experimentelle Rezeptur genauso gut als Rezept für bemerkenswert starken Rum enden könnte."},{t="Das grüne Leuchten ernten",b="Um ihr Gebräu zu verfeinern, benötigen die Erfinder rohe giftige Rückstände direkt aus dem Epizentrum der Katastrophe. Ozzie rüstet die Abenteurer mit einer bleiernen Sammelphiole aus und schickt sie zu den aufgebrochenen Tunneln von Gnomeregan. Dort leuchten umherstreifende verstrahlte Invasoren und Plünderer – Troggs, die von ausgetretenen Abfällen durchtränkt sind – mit jener kränklichen grünen Energie, die zum Füllen der Phiole benötigt wird."},{t="Haare und große Hoffnungen",b="Sobald eine volle Phiole mit grünem Leuchten gesichert ist, verliert Ozzie keine Zeit, einen Live-Test vorzubereiten. Neben der Hoffnung, einem gefangenen Lepragestrickten Gnom Verstand und Gesundheit zurückzugeben, hegt der Tüftler persönliche Bestrebungen für das Gebräu: Er glaubt, dass die Niederschlagsmischung auf wundersame Weise auch seine Kahlköpfigkeit heilen könnte."}},faq={{q="Wer bietet die Quest Gnogaine an?",a="Die Quest wird von Ozzie Wechselvolt vergeben, einem Gnomen-Tüftler, der in Kharanos in Dun Morogh stationiert ist.",al={"wer gibt gnogaine","gnogaine questgeber","ozzie wechselvolt quest"}},{q="Was muss ich für diese Quest sammeln?",a="Ihr müsst eine Leere bleierne Sammelphiole auf leuchtenden, verstrahlten Troggs einsetzen – genauer gesagt auf Verstrahlten Invasoren oder Verstrahlten Plünderern –, die in den Außenkorridoren nach Gnomeregan zu finden sind, bis die Phiole mit radioaktivem Niederschlag gefüllt ist.",al={"gnogaine ziel","was sammle ich gnogaine","volle bleierne sammelphiole"}},{q="Wo finde ich die verstrahlten Troggs?",a="Sie befinden sich in den äußeren Eingangshöhlen und gewundenen Hallen, die zum Instanzportal von Gnomeregan führen, sodass Ihr die Aufgabe abschließen könnt, ohne den Dungeon selbst betreten zu müssen.",al={"wo sind verstrahlte troggs","gnogaine trogg aufenthaltsort","verstrahlter invasor aufenthaltsort"}},{q="Muss ich 'Der Tag danach' abschließen, bevor ich diese Quest annehmen kann?",a="Nein. Obwohl 'Der Tag danach' erzählerisch mit der Situation in Kharanos verknüpft ist und darauf zuführt, bietet Ozzie 'Gnogaine' unabhängig davon an.",al={"ist der tag danach erforderlich","gnogaine voraussetzung"}},{q="Was versucht Ozzie mit dem radioaktiven Niederschlag zu erreichen?",a="Ozzie behauptet, er und Razzle würden versuchen, ein Heilmittel für Lepragestrickte Gnome herzustellen, räumt jedoch ein, dass das Gebräu auch einfach nur hochprozentiger Rum werden könnte. Zudem hofft er insgeheim, dass die Mixtur seinen Haarwuchs wiederherstellt.",al={"warum will ozzie strahlung","wofür ist gnogaine"}},{q="Welche Quest folgt auf Gnogaine?",a="Die Abgabe der vollen Phiole führt direkt zu 'Die einzige Heilung ist noch mehr grünes Leuchten', wofür Ihr tiefer in Gnomeregan selbst vordringen müsst.",al={"gnogaine folgequest","was kommt nach gnogaine"}}},fx={["28ada800"]={q="Wofür ist die Volle bleierne Sammelphiole?",a="Die Phiole ist mit Blei abgeschirmt, um den gefährlichen, leuchtenden radioaktiven Niederschlag, der von Troggs aus der Umgebung von Gnomeregan extrahiert wurde, sicher zu lagern und zu transportieren. Ozzie Wechselvolt und Razzle Flinkspross benötigen diese konzentrierte radioaktive Materie als lebenswichtige Zutat für ihre experimentelle Mixtur, von der sie hoffen, dass sie entweder ihren befallenen, gefangenen Lepragnom heilt, einen außergewöhnlich starken Rum braut oder vielleicht Ozzies Haarwuchs wieder anregt.",al={"nutzung der vollen bleiernen sammelphiole","warum bleierne phiole","zweck der bleiernen sammelphiole"}},dfd2dab8={q="Was sind die verstrahlten Troggs in Gnomeregan?",a="Die Troggs brachen ursprünglich tief unter Gnomeregan hervor und überrannten das technische Wunderwerk einer Stadt. In einem verzweifelten Versuch, die Invasion auszurotten, fluteten Hochtüftler Mekkatorque und seine Berater die unteren Korridore mit giftiger Strahlung. Anstatt auszusterben, überlebten viele Troggs und mutierten zu bösartigen, verstrahlten Invasoren und Plünderern, die nun vor einem kränklichen grünen, radioaktiven Leuchten strotzen.",al={"verstrahlte invasoren","verstrahlte plünderer","warum sind troggs verstrahlt"}}},fp="8,302,20.494.0,19.382.0,19.285.1,30.97.0,41.242.0,39.193.0,63.137.0,64.212.0,28.135.0"}
P.entries["quest:2927"] = {n="Der Tag danach",s="Der Tag danach ist eine Allianz-Quest, die eine Brücke zwischen den Überlebenden in Eisenschmiede und den Forschern schlägt, die in Dun Morogh stationiert sind. Gnoarn, der um den katastrophalen Strahlungsaustritt trauert, der ihn sein legendäres Haar und seine Heimat kostete, schickt Abenteurer aus, um Ozzie Wechselvolt in Kharanos bei seiner Suche nach einer Lösung zu unterstützen.",h="Der Tag danach ist eine Allianz-Quest, die eine Brücke zwischen den Überlebenden in Eisenschmiede und den...",kw={"gnoarn","gnomefro","gnomeregan","kharanos","ozzie wechselvolt","strahlungsaustritt","der tag danach","troggs"},ang={["faction:Alliance"]="Helden der Allianz unterstützen die gnomischen Denker in Dun Morogh dabei, die bizarre biochemische Katastrophe einzudämmen, die das Bergkönigreich bedroht.",["profession:Engineering"]="Ozzie Wechselvolts Bemühungen unterstreichen den Ansatz von Versuch und Irrtum, den gnomische Tüftler verfolgen, wenn sie mit außer Kontrolle geratenen Technokatastrophen konfrontiert werden.",["race:Gnome"]="Für Gnome fängt Gnoarns eigentümliche Klage die Mischung aus tiefer Tragödie, exzentrischem Stolz und bitterer Rache ein, die jeder aus seiner wundersamen Hauptstadt verbannte Flüchtling empfindet."},sec={{t="Ein tragischer Verlust",b="Der Untergang von Gnomeregan forderte von jedem Überlebenden einen tiefgreifenden persönlichen Tribut, und Gnoarn ist da keine Ausnahme. Als Flüchtling in Tüftlerstadt in Eisenschmiede trauert Gnoarn nicht nur um das mechanische Wunderland, das ihm von eindringenden Troggs gestohlen wurde, sondern auch um seinen geschätzten Gnomefro – eine glorreiche Mähne, die in dem Augenblick verloren ging, als ihn eine Welle giftigen Fallouts traf. Angetrieben von anhaltender Wut auf die Troggs und der verzweifelten Hoffnung, die Stadt zurückzuerobern, leitet er mitfühlende Reisende an Kollegen weiter, die vielleicht noch über das wissenschaftliche Können verfügen, um das zu retten, was noch übrig ist."},{t="Der Weg nach Kharanos",b="Anstatt in Verzweiflung zu versinken, weist Gnoarn Helden der Allianz den Weg nach Kharanos, wo findige Köpfe begonnen haben, sich dem Fallout zu widmen. Allen voran Ozzie Wechselvolt, der gemeinsam mit seinem Partner Razzle Flinkspross arbeitet. Ozzie erinnert sich noch lebhaft an den schrecklichen Moment der Katastrophe und daran, wie Gnoarns Haar büschelweise ausfiel, während Wahnsinn und Rachedurst die Oberhand gewannen. Nun, in der relativen Sicherheit der verschneiten Stadt, richtet Ozzie sein technisches Genie darauf, die Kontamination zu analysieren, in der Hoffnung, ein Gegenmittel zu finden."}},faq={{q="Wer ist Gnoarn?",a="Gnoarn ist ein Gnom-Flüchtling, der sich in Tüftlerstadt in Eisenschmiede aufhält. Tief verbittert über die Trogg-Invasion und die Katastrophe durch den radioaktiven Austritt in der Stadt, ist er besonders traumatisiert durch den plötzlichen Verlust seines einst so stolzen Gnomefros.",al={"gnoarn","glatzköpfiger gnom","wer gibt der tag danach"}},{q="Warum schickt Gnoarn Euch zu Ozzie Wechselvolt?",a="Gnoarn glaubt, dass es noch Hoffnung gibt, Gnomeregan zu retten. Ozzie Wechselvolt und sein Partner Razzle sind in Kharanos stationiert, wo sie die giftige Strahlung untersuchen, die der Stadt anhaftet, und versuchen, ein Heilmittel zu entwickeln.",al={"warum zu ozzie gehen","ozzie wechselvolt quest","kharanos ingenieur"}},{q="Was ist mit Gnomeregan geschehen, das dies verursacht hat?",a="Während einer massiven unterirdischen Invasion barbarischer Troggs wurde der Großtüftler Gelbin Mekkadrill dazu überredet, radioaktive giftige Abfälle in die unteren Hallen zu leiten, um sie auszurotten. Das Manöver scheiterte tragisch, mutierte oder tötete zahllose Gnome und machte die Technostadt unbewohnbar, ohne die Troggs vollständig auszulöschen.",al={"was ist mit gnomeregan passiert","warum ist gnomeregan verstrahlt","trogg invasion"}},{q="Wohin führt diese Questreihe, nachdem man Ozzie erreicht hat?",a="Wenn Ihr Euch bei Ozzie meldet, wird die Quest 'Gnogaine' freigeschaltet, bei der Ozzie Euch bittet, radioaktiven Fallout direkt von den verstrahlten Troggs außerhalb von Gnomeregan zu sammeln, um experimentelle Neutralisierungsmischungen zu testen.",al={"der tag danach folgequest","was kommt nach der tag danach","nächste quest"}}},fx={b3abdd6a={q="Warum möchte Gnoarn, dass dies getan wird?",a="Gnoarn wird von persönlicher Wut und hartnäckiger Hoffnung angetrieben. Der radioaktive Niederschlag, der Gnomeregan ruinierte, raubte ihm auch seinen ganzen Stolz und seine Freude: das einzige Gnomfro in ganz Azeroth. Verbittert über seine Glatze und brennend vor Rache gegen die einfallenden Troggs, weigert er sich, seine Heimat aufzugeben. Er glaubt, dass es noch eine Chance gibt, das Desaster rückgängig zu machen und die Stadt zurückzuerobern, wenn er fähige Abenteurer zu Ozzie Wechselvolt schickt.",al={"gnoarns motiv","warum gnoarn helfen","warum kümmert sich gnoarn"}}},fp="13,305,13.521.0,20.545.0,14.221.0,45.229.0,42.313.0,54.198.0"}
P.entries["quest:2928"] = {n="Gyrobohrmatische Exkavation",s="Tief im Zwergendistrikt von Sturmwind bereitet Shoni die Schtille eine Flotte gewaltiger Tunnelbohrmaschinen für den Transit nach Dun Morogh vor. Da ein Mangel an mechanischen Teilen sie aufhält, schickt sie Abenteurer in die verstrahlten Ruinen von Gnomeregan, um intakte Zahnräder und Eingeweide aus abtrünnigen Automaten zu bergen.",h="Tief im Zwergendistrikt von Sturmwind bereitet Shoni die Schtille eine Flotte gewaltiger Tunnelbohrmaschinen...",kw={"dun morogh","der zwergendistrikt","gyrobohrmatische exkavation","gnomeregan","gnomeningenieurskunst","gyrobohrmatisch","robo-mechanical guts","shoni die schtille"},ang={["faction:Alliance"]="Die Unterstützung gnomischer Ausgrabungslogistik von Sturmwind aus stärkt die Bande zwischen den menschlichen Gastgebern und den vertriebenen Überlebenden, die um die Rückeroberung ihres Erbes kämpfen.",["profession:Engineering"]="Das Ausschlachten hochpräziser Uhrwerk-Eingeweide gefallener Diener aus Gnomeregan bietet eine praktische Lektion in fortschrittlicher gnomischer Konstruktion und der Reparatur von Schwermaschinen.",["race:Gnome"]="Jede geborgene Komponente bringt Shonis unterirdische Flotte der Einsatzfähigkeit näher und hält den Traum von Rückeroberung und industrieller Erholung aus dem Inneren von Sturmwind heraus am Leben."},sec={{t="Eine Flotte in Not an Eingeweiden",b="Im Zwergendistrikt von Sturmwind arbeiten gnomische Ingenieure unermüdlich daran, ihr vertriebenes Volk zu unterstützen. Unter ihnen ist Shoni die Schtille, die ein ehrgeiziges unterirdisches Vorhaben beaufsichtigt: eine für Dun Morogh bestimmte Flotte der gyrobohrmatischen Exkavation. Das Projekt steht vor einem kritischen Engpass, da ihr die notwendigen Komponenten fehlen, um die gewaltigen Bohrgeräte einsatzbereit zu machen."},{t="Bergung in der gefallenen Stadt",b="Anstatt neue Teile von Grund auf neu zu schmieden, wendet sich Shoni direkt der Quelle gnomischer Spitzentechnologie zu: der verlorenen Stadt Gnomeregan. In den Ruinen und den umliegenden Tunneln wimmelt es von fehlerhaften Verteidigungsbots, mechanischen Wachen und unkontrolliert umherstreifenden Uhrwerk-Arbeitern. Abenteurer werden ausgesandt, um diese abtrünnigen Maschinen zu zerlegen und zwei Dutzend Bündel Robo-Mechanical Guts zurück in menschliche Länder zu schaffen."},{t="Ein monumentales Unterfangen",b="Das Zurückbringen von zwei Dutzend mechanischen Eingeweiden liefert genug Schrott, um genau eine Maschine der Exkavation zusammenzuflicken. Da noch fast vierhundert Maschinen in ihrer Flotte verbleiben, bleibt Shonis Traum von einem unterirdischen Massentransport ein monumentales, quälend langsames Unterfangen. Dennoch stellt jede funktionierende Maschine einen kleinen Schritt dar, um den in der Katastrophe von Gnomeregan verlorenen Boden zurückzugewinnen."}},faq={{q="Was ist eine gyrobohrmatische Exkavation?",a="Es handelt sich um schwere gnomische Tunnelbohrgeräte oder Maulwurfmaschinen, die für unterirdische Ausgrabungen und Transporte entwickelt wurden. Shoni die Schtille versucht, eine ganze Flotte davon zusammenzustellen, um Personen oder Vorräte nach Dun Morogh zu befördern.",al={"gyrobohrmatische exkavation","was ist gyrobohrmatische exkavation","gnomenbohrer"}},{q="Wer ist Shoni die Schtille?",a="Shoni ist eine gnomische Ingenieurin, die im Zwergendistrikt von Sturmwind stationiert ist. Trotz ihres Beinamens ist sie eine resolute und fordernde Aufseherin, die fest entschlossen ist, Hunderte mechanischer Gräber zu reparieren.",al={"shoni die schtille","shoni","wer ist shoni"}},{q="Warum braucht Shoni gezielt Teile aus Gnomeregan?",a="Gnomeregan wird von Hunderten durchgedrehter Automaten, Uhrwerk-Dienern und Verteidigungsmechs überrannt. Da die regulären Fertigungslieferketten mit dem Fall der Stadt abrissen, stellen diese abtrünnigen Bots die ergiebigste verfügbare Quelle für kompatible gnomische Ersatzteile dar.",al={"warum gnomeregan-teile","warum robotereingeweide","gnomeregan beute"}},{q="Wo findet man die Robo-Mechanical Guts?",a="Die verwertbaren Eingeweide können von den mechanischen Wächtern, Uhrwerkkonstrukten und anderen Feinden erbeutet werden, die durch die Gänge von Gnomeregan wandern, sowohl innerhalb der zerstörten Anlage als auch entlang der oberen Tunnelzugänge.",al={"robo-mechanical guts","wo gibt es eingeweide","mechanische eingeweide gnomeregan"}},{q="Wird Shonis Flotte fertig, wenn eine Maschine repariert ist?",a="Nein. Zwei Dutzend mechanische Eingeweide reichen nur aus, um einen einzigen Bohrer zu reparieren. Nach deren Abgabe bemerkt Shoni, dass sie immer noch 398 Maschinen der Exkavation vor sich hat.",al={"wie viele maschinen der exkavation","shonis flottengröße","wie viele bohrer"}},{q="Warum wird eine Ausgrabungsflotte für Dun Morogh vorbereitet?",a="Dun Morogh ist die angestammte Heimat der Gnome und der Ort ihrer gefallenen Hauptstadt. Die Vorbereitung schwerer Tunnelbohrgeräte bietet eine Möglichkeit zu graben, Trümmer zu beseitigen und Operationen in den schneebedeckten Bergen zu unterstützen.",al={"flotte nach dun morogh","warum dun morogh","zweck der gräber"}}},fx={b2dc5b24={q="Wofür werden die Robo-Mechanical Guts verwendet?",a="Shoni die Schtille benötigt sie als geborgene interne Komponenten, um ihre Flotte von Gyrodrillmatic Excavationators zu reparieren. Die komplexe Mechanik dieser unterirdischen Tunnelbohrfahrzeuge erfordert Präzisionszahnräder, Verkabelung und Aktuatoren, die in Sturmwind nur schwer von Grund auf neu geschmiedet werden können. Indem sie die funktionierenden Innereien aus den autonomen Uhrwerkmaschinen entfernt, die in Gnomeregan umherstreifen, kann sie die wichtigen Ersatzteile bergen, die benötigt werden, um ihre stillgelegten Bohranlagen wieder in Betrieb zu nehmen.",al={"wofür sind robo-mechanical guts","nutzung von robo-mechanical guts","shonis nutzung von guts"}},["1cb24930"]={q="Wogegen kämpft Ihr in Gnomeregan für Shoni?",a="Ihr werdet ausgesandt, um die abtrünnigen Bots und Mechs zu demontieren, die durch die verstrahlten Hallen und Außenbezirke von Gnomeregan wandern. Als die unterirdische Hauptstadt der Gnome der Trogg-Invasion und dem radioaktiven Niederschlag zum Opfer fiel, funktionierten zahllose automatisierte Verteidigungssysteme und Versorgungsapparaturen nicht mehr und wurden gegenüber Außenstehenden feindselig. Shoni sieht in diesen verlassenen, umherstreifenden Automaten nicht nur Gefahren, sondern ein offenes Feld an Schrott, das nur darauf wartet, geplündert zu werden.",al={"gegen wen kämpfe ich für shoni","gnomeregan ziele guts","welche maschinen haben guts"}},["33a01105"]={q="Warum muss Shoni, dass Ihr die Teile sammelt, anstatt selbst zu gehen?",a="Shoni ist eine Ingenieurin, die im Der Zwergendistrikt von Sturmwind stationiert ist und damit beschäftigt ist, Maschinen zu warten und die Montage einer riesigen Ausgrabungsflotte zu beaufsichtigen. Tief in eine verstrahlte, von Troggs verseuchte Ruine vorzudringen, die von tödlichen Uhrwerk-Wächtern überrannt wurde, erfordert einen bewaffneten Abenteurer, der bereit ist, sich durch gefährliche Korridore zu kämpfen. Sie bleibt zurück, um die Bergung zu inspizieren und die Anlagen zu reparieren, sobald Komponenten eintreffen.",al={"warum schickt sie mich für guts","warum geht shoni nicht selbst","warum ich shoni quest"}}},fp="30,316,23.370.0,26.395.0,24.379.0,40.216.0,25.189.0,55.262.0,41.218.0,45.156.0,57.211.0"}
P.entries["quest:293"] = {n="Die Reinigung des Auges",s="Die Reinigung des Auges ist eine Allianz-Quest, die Abenteurer aus dem trüben Sumpfland nach Süden in die Menschenhauptstadt Sturmwind schickt. Nach der Bergung des verfluchten Hellsehersteins, bekannt als das Auge von Paleth, müssen Reisende die Hilfe von Erzbischof Benedictus suchen, um seinen anhaftenden Makel zu tilgen.",h="Die Reinigung des Auges ist eine Allianz-Quest, die Abenteurer aus dem trüben Sumpfland nach Süden in die...",kw={"erzbischof benedictus","kathedrale des lichts","die reinigung des auges","verfluchtes auge von paleth","auge von paleth","glorin stahlbraue","sturmwind","sumpfland"},ang={["class:Paladin"]="Paladine betrachten die Rückholung heiliger Relikte aus finsteren Sümpfen als feierliche Pflicht und sehen die Verderbnis des Auges als Frevel an, der in den geheiligten Hallen von Sturmwind gereinigt werden muss.",["class:Priest"]="Für Priester des Heiligen Lichts zeigt der Umgang mit dem Verfluchten Auge von Paleth die tragische Formbarkeit heiligen Handwerks, wenn es der Verzweiflung ausgesetzt ist, und unterstreicht die Bedeutung von Erzbischof Benedictus' läuterndem Eingreifen.",["faction:Alliance"]="Die Quest hebt die Zusammenarbeit zwischen den Zwergenaußenposten im Sumpfland und der geistlichen Führung von Sturmwind hervor und verbindet die Königreiche durch gemeinsamen Glauben."},sec={{t="Ein verdorbenes Relikt",b="Das aus den Marschen geborgene Auge von Paleth erstrahlt nicht in heiliger Klarheit. Stattdessen ist es von einem beunruhigenden Schatten durchdrungen und trägt die verbliebene Trauer und das Trauma der furchtbaren Tragödie in sich, die sich dort ereignete, wo es verloren ging. Der Zwerg Glorin Stahlbraue erkennt die Macht der Kugel, räumt jedoch ein, dass ihm das göttliche Handwerk fehlt, um eine solch schwere Heimsuchung aufzuheben."},{t="Reise zur Kathedrale",b="Da die Augen von Paleth ursprünglich von menschlichen Priestern des Heiligen Lichts gefertigt wurden, besitzt nur ihr oberster Orden das Wissen, um die Schändung rückgängig zu machen. Glorin weist Abenteurer an, in das Königreich Sturmwind zu reisen und die verdunkelte Kugel Erzbischof Benedictus zu überreichen, dem Anführer der Kirche des Heiligen Lichts. Benedictus erkennt die immense Gefahr eines ungeläuterten Relikts und nimmt es auf sich, dessen heiligen Glanz wiederherzustellen."}},faq={{q="Was ist das Auge von Paleth?",a="Die Augen von Paleth sind heilige Kugeln, die von menschlichen Priestern gefertigt wurden, um in heiligem Glanz zu strahlen und als Seh- oder Hellseherfokusse zu dienen. Wenn sie unbefleckt sind, ist ihre Macht auf das Heilige Licht ausgerichtet; werden sie jedoch korrumpiert, werden ihre umgebenden Energien unbeständig und gefährlich.",al={"auge von paleth lore","was ist diese kugel","was ist das auge von paleth"}},{q="Warum kann Glorin Stahlbraue das Auge nicht selbst reinigen?",a="Glorin Stahlbraue ist ein im Sumpfland stationierter Zwerg, dem das spezialisierte liturgische Handwerk fehlt, das nötig ist, um ein solch finsteres Leiden zu bannen. Da das Relikt von menschlichen Priestern des Heiligen Lichts geschaffen wurde, erfordert das Aufheben seiner Verderbnis eine Autorität genau dieser Tradition.",al={"warum nach sturmwind geschickt","glorin reinigung","warum benedictus"}},{q="Wer ist Erzbischof Benedictus?",a="Erzbischof Benedictus ist der ehrwürdige Anführer der Kirche des Heiligen Lichts, der in der großen Kathedrale des Lichts in Sturmwind residiert. Er folgte auf Erzbischof Alonsus Faol und dient der Allianz als Säule geistlicher Führung.",al={"wer ist benedictus","erzbischof benedictus","sturmwind erzbischof"}},{q="Warum wird das Auge als beschmutzt oder traurigkeitserfüllt beschrieben?",a="Laut Erzbischof Benedictus war die Kugel Zeuge eines immensen, tragischen Ereignisses im Sumpfland und sog diesen Schmerz über die Zeit hinweg in sich auf. Diese anhaltende Trauer verwandelte sich in einen verderbenden Fluch, der die innewohnende Macht des Relikts verzerrte.",al={"warum ist es verflucht","auge von paleth tragödie","verfluchtes auge von paleth"}},{q="Was geschieht, sobald Benedictus die Kugel erhält?",a="Benedictus willigt ein, ein Ritual der Läuterung durchzuführen. Er warnt davor, dass die Augen von Paleth hell erstrahlen sollen und dass ein solches Artefakt in verdorbenem Zustand eine ernste geistige wie körperliche Gefahr für alle in der Nähe darstellt.",al={"reinigt benedictus es","auge von paleth ausgang"}},{q="Wo befindet sich die Kathedrale des Lichts?",a="Die Kathedrale des Lichts beherrscht den Kathedralenplatz im nördlichen Viertel von Sturmwind. Erzbischof Benedictus steht am Hauptaltar im Herzen des Heiligtums.",al={"wo ist kathedrale des lichts","kathedrale des lichts standort","benedictus finden"}}},fx={["6f168d84"]={q="Warum möchte Glorin Stahlbraue das Auge von Paleth gereinigt haben?",a="Glorin erkennt, dass das verfluchte Auge von Paleth ein äußerst gefährliches heiliges Relikt ist. Von menschlichen Priestern des das Heilige Licht geschaffen, um hell zu leuchten, wird seine Magie gefährlich und verdirbt, wenn sie durch Tragödien und dunkle Macht befleckt wird. Da Zwergenhandwerk und seine eigenen Fähigkeiten ein solches spirituelles Leiden nicht aufheben können, besteht er darauf, dass es nach Sturmwind gebracht wird, bevor seine Verderbnis Euch oder dem umliegenden Land weiteren Schaden zufügt.",al={"warum auge von paleth reinigen","glorin stahlbraues motiv","warum auge nach sturmwind senden"}}},fp="17,279,15.355.0,24.445.0,26.254.0,51.271.0,29.237.0,48.232.0,46.214.0,40.171.0"}
P.entries["quest:2930"] = {n="Datenrettung",s="Als die Gnome ihre verstrahlte Hauptstadt evakuierten, blieben gewaltige Archive mit unverzichtbarem technischem Wissen und Aufzeichnungen zurück. Mechanikermeister Castpipe in Eisenschmiede rekrutiert wagemutige Einsatzkräfte, um Gnomeregan zu infiltrieren und eine hochsichere Prismalochkarte zu bergen. Kuriere müssen sich durch verschiedene Stufen computerisierter Sicherheitsfreigaben navigieren und tief in der zerstörten Stadt schrittweise befestigte Terminals stanzen.",h="Als die Gnome ihre verstrahlte Hauptstadt evakuierten, blieben gewaltige Archive mit unverzichtbarem...",kw={"castpipe","datenrettung","engineering labs","gnomeregan","matrix-lochograph","prismalochkarte","lochkarte","tüftlerstadt","train depot"},ang={["faction:Alliance"]="Die Unterstützung von Castpipes Bergungsbemühungen hilft der vertriebenen Gnom-Regierung in Eisenschmiede und stärkt die Einigkeit sowie die technologischen Fähigkeiten innerhalb der Großen Allianz.",["profession:Engineering"]="Das Matrix-Lochographen-Netzwerk repräsentiert automatisierte Datenspeicherung in Reinform und demonstriert die komplexen algorithmischen Freigabemechanismen, die vom Tinkers' Court erdacht wurden.",["race:Gnome"]="Das Bergen von Daten aus Gnomeregan bedeutet die Rückgewinnung gestohlenen Erbes. Jede gerettete Lochkarte stellt sicher, dass der Erfindungsreichtum Eurer gefallenen Stadt bewahrt bleibt, anstatt an Troggs und Strahlung verloren zu gehen."},sec={{t="Verlorene Archive des Untergrunds",b="Der plötzliche Fall von Gnomeregan an Troggs und tödliche Strahlung zwang die gnomische Bevölkerung dazu, Jahrhunderte fortschrittlicher Forschung, Baupläne und städtischer Protokolle aufzugeben. In den technologischen Korridoren verstreut stehen Matrix-Lochograph-Terminals – automatisierte Datenknotenpunkte, die Sicherheitsfreigaben und Datenspeicherung regulieren. Für Anführer im Exil wie Mechanikermeister Castpipe ist die Bergung dieser lochcodierten Archive aus den ruinierten Tiefen eine der obersten Prioritäten der Flüchtlingsgemeinschaft in Tüftlerstadt."},{t="Eine Hierarchie von Perforationen",b="Das gnomische Datenprotokoll verlangt eine rigorose Freigabe, bevor Zugriff auf die zentralen Großrechner gewährt wird. Die Bedienung des Systems erfordert das Starten mit einer einfachen Weißen Lochkarte, die in den Trümmern außerhalb der inneren Tore gefunden wird. Das Einsetzen in einen Matrix-Lochographen 3005-A im Train Depot erzeugt eine gelbe Karte, die anschließend zum 3005-B-Terminal im Dormitory für eine blaue Aufwertung gebracht werden muss, über das Modell 3005-C zu einer Roten Lochkarte verbessert und schließlich in die Engineering Labs hinabgeführt wird, um die begehrte Prismalochkarte zu codieren."},{t="Gnomische Heiterkeit in Binärcode",b="Während Castpipe die Mission als Angelegenheit dringender städtischer Notwendigkeit behandelt, enthalten die eigentlichen Lochkarten binäre Datenströme, die die exzentrische, respektlose Denkweise der Rechengilden von Gnomeregan offenbaren. Inmitten echter technischer Daten übersetzen sich die Lochmuster in humorvolle Sprüche, absurde Beschwerden über den Arbeitsplatz und derbe Witze über Hochtüftler Gelbin Mekkadrill, der Nachtelfen-Unterwäsche trägt – was beweist, dass gnomische Ingenieure selbst im Herzen hochmoderner Infrastruktur niemals einem Streich widerstehen konnten."}},faq={{q="Was ist die Prismalochkarte?",a="Die Prismalochkarte ist die höchste Sicherheitsdatenkarte, die von den automatisierten Großrechnern Gnomeregans anerkannt wird. Sie entsteht durch die Verarbeitung einer Roten Lochkarte am Terminal des Matrix-Lochographen 3005-D tief in den Engineering Labs.",al={"prismalochkarte","was ist eine lochkarte","gnomeregan lochkarte"}},{q="Wo beginnt die Abfolge der Lochkarten?",a="Die Abfolge beginnt mit einer einfachen Weißen Lochkarte, erbeutet von Troggs und mechanischen Wracks, die sich direkt vor dem Haupteingang der Instanz nahe dem Train Depot herumtreiben.",al={"wo weiße lochkarte finden","lochkarten anfangen","erste lochkarte"}},{q="Wo befinden sich die Matrix-Lochograph-Terminals?",a="Modell 3005-A steht außerhalb der Instanz im Train Depot. Modell 3005-B befindet sich im Dormitory hinter der Clean Zone. Modell 3005-C steht auf den darüber liegenden Laufstegplattformen, während Modell 3005-D auf der unteren Ebene der Engineering Labs platziert ist.",al={"terminal standorte","wo sind lochographen","lochkartenmaschinen"}},{q="Wer ist Mechanikermeister Castpipe?",a="Mechanikermeister Castpipe ist ein erfahrener Gnomen-Ingenieur, der unter den Flüchtlingen in Eisenschmiedes Tüftlerstadt lebt. Verzweifelt darauf bedacht, Gnomeregans geistiges Erbe zu retten, koordiniert er Aufklärungs- und Bergungsmissionen in die gefallene Hauptstadt.",al={"castpipe","wer gibt datenrettung","castpipe lore"}},{q="Welche Daten befinden sich tatsächlich auf den Karten?",a="Aus dem reinen ASCII-Binärcode übersetzt enthalten die Lochkarten eine Mischung aus gnomischen Ingenieursplaudereien, heiteren Witzen über regionale Anführer wie Thrall und Mekkatorque sowie skurrilen Notizen neben den entscheidenden Rechendaten der Stadt.",al={"kartentext","binärcode übersetzung","was bedeutet der binärcode"}},{q="Können Horde-Spieler auf diese Terminals zugreifen?",a="Die Quest selbst wird von Mechanikermeister Castpipe in Eisenschmiede exklusiv der Allianz angeboten, doch mit den physischen Lochograph-Terminals innerhalb des Dungeons kann technisch gesehen jeder interagieren, der die erforderlichen Karten bei sich trägt.",al={"horde datenrettung","horde lochkarten","kann horde terminals nutzen"}}},fx={["0f0753b5"]={q="Warum möchte Mechanikermeister Castpipe, dass die Lochkarte geborgen wird?",a="Als die Gnome Gnomeregan während seines Falls evakuierten, blieben im Chaos Berge von lebenswichtigen betrieblichen und technischen Daten zurück. Mechanikermeister Castpipe betrachtet die Informationen, die in den hochsicheren Matrix-Lochkarten-Terminals gespeichert sind, als entscheidend für das Überleben und die Wiederaufbaubemühungen der Gnome und besteht darauf, dass sie es sich nicht leisten können, sie dauerhaft zu verlieren.",al={"castpipes motiv","warum braucht castpipe lochkarte","warum datenrettung"}}},fp="11,422,32.512.0,27.527.0,24.517.1,33.244.0,45.169.0,51.247.0,32.240.0,35.244.0,41.233.0"}
P.entries["quest:2931"] = {n="Gussmuffs Auftrag",s="Gussmuffs Auftrag ist eine Vorladung der Allianz, die fähige Abenteurer dazu anweist, Mechanikermeister Castpipe in Eisenschmiede aufzusuchen. Castpipe koordiniert gefährliche Bergungsoperationen in die verstrahlten Ruinen von Gnomeregan, um lebenswichtige mechanische und technische Aufzeichnungen zu bergen. Sie dient als offizielle Einweisung, die Söldner zu tiefen Bergungsmissionen im Inneren der gefallenen Stadt leitet.",h="Gussmuffs Auftrag ist eine Vorladung der Allianz, die fähige Abenteurer dazu anweist, Mechanikermeister...",kw={"versammlung","castpipe","datenrettung","gaxim","gnomeregan","eisenschmiede","rustfizzle","tinkertown"},ang={["faction:Alliance"]="Den vertriebenen Gnomenverbündeten bei der Sicherung ihrer verlorenen Archive zu helfen, trägt zur Stabilisierung von Tinkertown bei und stärkt das technologische Ansehen der gesamten Allianz.",["profession:Engineering"]="Die Datenkerne im Inneren von Gnomeregan enthalten rechnerische Wunderwerke und fortschrittliche Baupläne, die nirgendwo sonst auf Azeroth ihresgleichen finden.",["race:Gnome"]="Jede Bergungsoperation bedeutet ein weiteres Fragment Eurer gefallenen Heimat, das vor Verstrahlung und Zerstörung bewahrt wird, was Castpipes Mission zu einer Frage des kulturellen Überlebens macht."},sec={{t="Ein Ruf nach Tinkertown",b="Nach dem tragischen Fall und der anschließenden radioaktiven Quarantäne von Gnomeregan suchten die überlebenden Gnom Zuflucht in Tinkertown in Eisenschmiede. Während ihre großartige Heimat weiterhin von Troggs und verstrahlten Konstrukten überrannt bleibt, sind entscheidende Betriebsaufzeichnungen und mechanische Baupläne tief in den verbliebenen Rechenanlagen der Stadt gefangen. Da Mechanikermeister Castpipe erkannte, dass diese Daten für den Wiederaufbau oder das Verständnis der Geschehnisse von unschätzbarem Wert sein könnten, begann er aktiv unerschrockene Außenstehende anzuwerben, die bereit sind, den giftigen Hallen zu trotzen."},{t="Befürwortung der Versammlung",b="Die Nachricht von Castpipes Vorhaben wird von Persönlichkeiten wie Gaxim Rostknirsch von der Erleuchteten Versammlung der Arkanologie, Alchemie und Ingenieurswissenschaften verbreitet. Obwohl Castpipe selbst kein Mitglied dieser angesehenen akademischen Vereinigung ist, respektieren die anderen Gnom seinen technischen Scharfsinn genug, um die Bemühungen zu unterstützen. Rustfizzles eigene Berechnungen beziffern die Wahrscheinlichkeit, dass Castpipes Mission von echtem strategischen Wert ist, auf ermutigende vierundachtzig Prozent, was Reisende dazu motiviert, sich in Tinkertown für Befehle zu melden."}},faq={{q="Wer ist Mechanikermeister Castpipe?",a="Mechanikermeister Castpipe ist ein angesehener Gnomen-Ingenieur, der in Tinkertown in Eisenschmiede ansässig ist. Er organisiert Bergungsteams und Datenrettungsoperationen, die sich auf die unterirdischen Ruinen von Gnomeregan konzentrieren.",al={"castpipe","wer ist castpipe","mechanikermeister castpipe"}},{q="Warum möchte Castpipe Daten aus Gnomeregan?",a="Als Gnomeregan kontaminiert und evakuiert wurde, blieben riesige Mengen an entscheidendem technischem Wissen, Bauplänen und internen Systemprotokollen im Speicher des Großrechners zurück. Diese Informationen zu bergen, ist für die vertriebenen Gnom, die auf einen Wiederaufbau hoffen, von entscheidender Bedeutung.",al={"gnomeregan daten","warum daten bergen","gnomeregan aufzeichnungen"}},{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein Gnomengelehrter, der der Erleuchteten Versammlung der Arkanologie, Alchemie und Ingenieurswissenschaften angehört. Er fungiert als Fürsprecher und Verbindungsmann, der fähige Abenteurer zu Castpipes Bergungsbemühungen leitet.",al={"gaxim","rustfizzle"}},{q="Wo ist Castpipe zu finden?",a="Mechanikermeister Castpipe befindet sich in Tinkertown, dem von Gnomen besiedelten Viertel im östlichen Teil der Zwergenhauptstadt Eisenschmiede.",al={"castpipe aufenthaltsort","wo ist castpipe"}},{q="Was geschieht nach der Meldung bei Castpipe?",a="Die Meldung bei Mechanikermeister Castpipe führt direkt zu einem Einsatz innerhalb der gefallenen Stadt selbst, bekannt als Datenrettung, bei dem Abenteurer in das kontaminierte Innere von Gnomeregan vordringen müssen, um Computer-Lochkarten und Speichermedien zu bergen.",al={"folgequest","was kommt danach","nach castpipe"}},{q="Was ist die Erleuchtete Versammlung der Arkanologie, Alchemie und Ingenieurswissenschaften?",a="Die Erleuchtete Versammlung der Arkanologie, Alchemie und Ingenieurswissenschaften ist eine angesehene intellektuelle Vereinigung der Gnom, die sich rigorosen wissenschaftlichen, magischen und mechanischen Studien widmet. Ihre Mitglieder, wie beispielsweise Gaxim Rostknirsch, wenden strenge Wahrscheinlichkeitsrechnungen an, um kritische Aufgaben zu bewerten.",al={"die versammlung","erleuchtete versammlung"}}},fx={["0652d792"]={q="Warum schickt Euch Gaxim Rostknirsch zu Mechanikermeister Castpipe?",a="Gaxim Rostknirsch respektiert den Intellekt von Mechanikermeister Castpipe, auch wenn Castpipe keine Mitgliedschaft in der Erleuchteten Versammlung für Arkanologie, Alchemie und Ingenieurwissenschaften besitzt. Nach Gaxims Berechnungen besteht eine Wahrscheinlichkeit von vierundachtzig Prozent, dass die Datenbeschaffungsoperation, die Castpipe in Gnomeregan vorbereitet, für die Gnome von entscheidender Bedeutung ist. Angesichts dieser günstigen Quoten ist Gaxim bestrebt, fähige Abenteurer in Richtung Eisenschmiede zu lenken, um die Rückeroberungsbemühungen zu unterstützen.",al={"warum schickt euch gaxim","gaxim rostknirschs motiv","warum mit castpipe sprechen"}}},fp="15,376,20.534.0,20.486.0,32.199.0,44.253.0,24.227.0,28.144.0,41.239.0,81.277.0"}
P.entries["quest:294"] = {n="Ormers Rache",s="Ormers Rache leitet den Vergeltungsfeldzug von Ormer Eisenzopf ein, einem Forscher, der hoch über Whelgars Ausgrabungsstätte im Sumpfland gestrandet ist. Nachdem das zwergische Grabungsteam uralte fossilierte Knochen freigelegt hatte, lockte es unabsichtlich Rudel ausgehungerter gesprenkelter Raptoren an, die ihre Gefährten abschlachteten und die Überlebenden auf einer felsigen Klippe festsetzten.",h="Ormers Rache leitet den Vergeltungsfeldzug von Ormer Eisenzopf ein, einem Forscher, der hoch über Whelgars...",kw={"gesprenkelter raptor","gesprenkelter kreischer","ormer eisenzopf","ormers rache","ausgrabungsleiter whelgar","sumpfland","whelgars ausgrabungsstätte"},ang={["class:Hunter"]="Die aggressiven gesprenkelten Raptoren, die an den Hängen außerhalb der Stätte umherstreifen, bieten aufmerksamen Jägern die Gelegenheit, das gefährliche reptilische Fährtenleseverhalten im Sumpfterrain zu studieren.",["race:Dwarf"]="Zu sehen, wie zwergische Brüder bei einem archäologischen Unternehmen der Forscherliga getötet wurden, macht das Säubern des raptorenverseuchten Steinbruchs zu einem Akt der Ehre der Ahnen und gerechter Vergeltung."},sec={{t="Ausgegrabener Schrecken",b="Whelgars Ausgrabungsstätte sollte ein Triumph für die Archäologie der Zwerge werden und gewaltige prähistorische Überreste zutage fördern, die unter dem Schlamm des Sumpflands begraben lagen. Doch das Freilegen der kolossalen Knochen erregte die Aufmerksamkeit der einheimischen Raptoren des Moors. Angelockt durch die Ruhestörung überrannten Rudel gesprenkelter Raubtiere die Ausgrabungsstätte, überraschten die Ausgräber und schlugen blutige Schneisen in ihre Reihen."},{t="Ein bitteres Ausharren",b="Nur eine Handvoll Zwerge überlebte das anfängliche Gemetzel. Ormer Eisenzopf, Merrin Felsweber und Ausgrabungsleiter Whelgar gelang es, auf eine Klippe über der Grube zu klettern, doch sie bleiben von aggressiven Rudeln darunter eingekesselt. Getrieben von roher Trauer und kochendem Zorn weigert sich Ormer, sich bloß zu verstecken. Da ihn die Pflicht bindet, den zitternden Ausgrabungsleiter und Merrin zu beschützen, heuert er fähige Reisende an, um die umliegenden gesprenkelten Raptoren und gesprenkelten Kreischer auszudünnen – als ersten Schlag seiner Rache."}},faq={{q="Was geschah mit den Ausgräbern hier?",a="Als die zwergischen Archäologen die riesigen Knochen im Becken freilegten, lockten der Lärm und der Geruch die örtlichen Raptorenrudel aus dem Sumpf an. Die Raubtiere überrannten das Lager, massakrierten den Großteil der Mannschaft und schnitten den drei Überlebenden oben auf der hohen Klippe den Rückweg ab.",al={"warum sind hier raptoren","massaker whelgars ausgrabungsstätte","was tötete die zwerge"}},{q="Wer ist Ormer Eisenzopf?",a="Ormer ist einer der überlebenden zwergischen Ausgräber, die an Whelgars Ausgrabungsstätte festsitzen. Zwar fühlt er sich durch seine Ehre verpflichtet zu bleiben und den erschütterten Ausgrabungsleiter Whelgar sowie Merrin Felsweber zu beschützen, doch sein sehnlichster Wunsch ist blutige Vergeltung an den Raptoren, die seine Kameraden niedergemetzelt haben.",al={"wer ist ormer","ormer eisenzopf hintergrundgeschichte"}},{q="Woher kommen diese Raptoren?",a="Gesprenkelte Raptoren und gesprenkelte Kreischer sind einheimische Raubtiere des Sumpflands, die auf den schlammigen Hängen und im Moor westlich der Klippe der Ausgrabung sowie auf den Pfaden lauern, die hinauf zu den Höhlen der Ausgrabungsstätte führen.",al={"wo sind gesprenkelte raptoren","raptoren standorte sumpfland"}},{q="Warum jagt Ormer die Raptoren nicht selbst?",a="Obwohl Ormer darauf brennt, persönlich Raptorenblut zu vergießen, ist er verpflichtet, den verängstigten Ausgrabungsleiter Whelgar und Merrin Felsweber zu bewachen, damit ihre Zuflucht auf der Klippe nicht überrannt wird.",al={"warum kämpft ormer nicht","warum sitzt ormer fest"}},{q="Endet Ormers Groll mit dem Ausdünnen dieser Raptoren?",a="Nein. Das Niederstrecken der gewöhnlichen gesprenkelten Raptoren und Kreischer ist nur der erste Schritt in Ormers Plan, seine gefallenen Freunde zu rächen; härtere Schläge gegen die Raptorenbrut folgen erst noch.",al={"ist das das ende von ormers rache","wie geht es mit ormer weiter"}},{q="Warum lockte das Freilegen der Knochen die Raptoren an?",a="Die Raptoren des Sumpflands verteidigen ihr Territorium verbissen und gehen aggressiv auf Aasjagd. Das Sprengen und Ausgraben uralter riesiger Überreste störte das natürliche Gleichgewicht des Beckens und trieb neugierige wie hungrige Raubtiere mitten in das Ausgrabungslager.",al={"warum knochen raptoren anlockten","dinosaurierknochen raptoren"}}},fx={["87324e21"]={q="Warum möchte Ormer Eisenzopf, dass die Raptoren getötet werden?",a="Als das Zwergenteam an der Ausgrabungsstätte alte Knochen ausgrub, schwärmten gefräßige Raptoren über das Gelände und schlachteten Ormers Kollegen ab. Ormer, Merrin Felsweber und Ausgrabungsleiter Whelgar überlebten den Ansturm nur knapp und sind weiterhin oben auf den Klippen gefangen. Brennend vor Trauer und Wut möchte Ormer seine gefallenen Brüder rächen und beginnen, die bösartigen Bestien von der Ausgrabung zu vertreiben.",al={"ormer eisenzopfs motiv","warum gefleckte raptoren töten","warum ormer rache"}},["79eca2c5"]={q="Was sind die Gefleckten Raptoren und Kreischer, hinter denen Ihr hergeschickt werdet?",a="Ihr werdet gegen die Gefleckten Raptoren und Gefleckten Kreischer ausgesandt, die direkt westlich der Ausgrabungsklippe umherstreifen. Diese aggressiven Reptilien, die im Sumpfland beheimatet sind, schwärmten über das Gelände, sobald die Ausgräber massive alte Knochen freilegten, massakrierten die Ausgräber und beanspruchten das umliegende Gelände als ihr Futterrevier.",al={"gegen wen kämpft ihr","ziel gefleckte kreischer","gefleckte raptoren sumpfland"}}},fp="15,339,17.382.0,14.475.0,37.255.0,23.280.0,33.216.0,43.186.0,46.188.0,49.240.0"}
P.entries["quest:2945"] = {n="Schmutzverkrusteter Ring",s="Tief in den verstrahlten Ruinen von Gnomeregan können Abenteurer von einem eindringenden Dunkeleisenzwerg ein Schmuckstück erbeuten, das dick mit giftigem Unrat und verhärtetem Morast verkrustet ist. Um seine wahre Identität zu lüften, muss der Funkelmat 5200 benutzt werden, ein industrieller Reinigungsautomat im Schlafsaalsektor. Einmal saubergeschrubbt, offenbart der Ring persönliche Gravuren, die eine Reise einleiten, um das Erbstück zurückzugeben oder umarbeiten zu lassen.",h="Tief in den verstrahlten Ruinen von Gnomeregan können Abenteurer von einem eindringenden Dunkeleisenzwerg ein...",kw={"clean zone","dunkeleisenzwerge","schlafsaal","gnomeregan","schmutzverkrusteter ring","die rückkehr des rings","funkelmat 5200"},ang={["profession:Engineering"]="Der Funkelmat 5200 ist ein klassisches Beispiel für skurrile Gnomen-Ingenieurskunst, die das Schrubben mit industriellen Lösungsmitteln mit einer automatischen Geschenkverpackungsausgabe kombiniert.",["race:Dwarf"]="Das Vorkommen des Rings bei einem eindringenden Dunkeleisenzwerg deutet auf erbeutete Beute hin, die Opfern aus Eisenschmiede oder Gnomen während des Chaos beim Fall von Gnomeregan abgenommen wurde.",["race:Gnome"]="Selbst während des katastrophalen Untergangs ihrer Stadt entwarfen Gnome Sanitätsapparaturen, die gefährliche industrielle Waschzyklen mit einem fröhlichen Glockenschlag und einer Schleife beenden."},sec={{t="Ein Relikt unter dem Morast",b="Gnomeregans Korridore schwimmen in giftigem Schlamm, Öl und radioaktivem Niederschlag, weshalb es nicht überrascht, dass im Kampf verlorene Gegenstände von einer undurchdringlichen Schlammschicht überzogen werden. Getötete Dunkeleisenzwerge, die in die Stadt eindringen, tragen oft stark verschmutzten Tand bei sich, vor allem diesen schmutzverkrusteten Reif. Die Kruste ist viel zu hart für eine herkömmliche Handwäsche und verdeckt völlig, ob das Metall darunter Kupfer, Gold oder Schrott ist."},{t="Der Funkelmat 5200",b="Um den Ring zu reinigen, muss man den Funkelmat 5200 im Schlafsaal der Clean Zone finden. Als gnomenhafte Ingenieurskunst in ihrer herrlichsten Absurdität schluckt die Maschine Münzen, setzt stark verschmutzte Gegenstände einer heftigen inneren Scheuerung aus und spuckt sie frisch poliert und ordentlich mit einer Schleife als Geschenk verpackt wieder aus. Das Entfernen des verstrahlten Morasts offenbart ein eingraviertes Abzeichen, das einem Bürger von Eisenschmiede gehört, und verwandelt ein erbeutetes Schmuckstück in eine Quest zur Rückgabe."}},faq={{q="Wo findet Ihr den Schmutzverkrusteten Ring?",a="Der Schmutzverkrustete Ring wird von den Leichen von Dunkeleisenzwergen erbeutet, auf die Ihr im belagerten Dungeon von Gnomeregan trefft.",al={"ring beute","wo droppt schmutzverkrusteter ring","wer droppt schmutzverkrusteten ring"}},{q="Wie reinigt Ihr den Ring?",a="Bringt den Ring zum Funkelmat 5200, der sich im Schlafsaal der Clean Zone in Gnomeregan befindet. Wenn Ihr den Ring zusammen mit der erforderlichen Münzgebühr einwerft, wird eine intensive automatische Reinigung eingeleitet, die den verhärteten Morast entfernt.",al={"ring reinigen","wie schmutzverkrusteten ring reinigen","wo ring waschen"}},{q="Was passiert, nachdem der Ring gereinigt wurde?",a="Der Funkelmat gibt eine ordentlich verpackte Schachtel aus, die einen wiederhergestellten Ring mit deutlichen persönlichen Gravuren enthält. Dies startet die Quest Die Rückkehr des Rings, die Euch dazu führt, seinen ursprünglichen Besitzer zu finden.",al={"folgequest schmutzverkrusteter ring","was tun mit gereinigtem ring","funkelmat ring ergebnis"}},{q="Können Hordespieler diese Quest abschließen?",a="Ja. Hordeabenteurer können den Funkelmat 5200 benutzen, um den Ring zu reinigen. Die nachfolgenden Schritte in der Reihe weichen jedoch ab und führen Hordespieler letztendlich zu einem Ingenieur in Orgrimmar, anstatt ihn nach Eisenschmiede zurückzubringen.",al={"ist schmutzverkrusteter ring nur allianz","horde schmutzverkrusteter ring","kann horde ring reinigen"}},{q="Warum ist der Ring nach der Reinigung in einer Geschenkbox verpackt?",a="Der Funkelmat 5200 ist mit typisch gnomenhafter Schrulligkeit gebaut. Neben dem kräftigen Abscheuern von Schlamm und Schmutz ist der Apparat darauf programmiert, verarbeitete Gegenstände nach Fertigstellung automatisch einzupacken und mit einer dekorativen Schleife zu versehen.",al={"als geschenk verpackter ring","warum geschenkbox funkelmat"}},{q="Gibt es mehrere Funkelmat-Maschinen?",a="Mehrere Funkelmat-Einheiten säumen die Wand im Schlafsaal der Clean Zone, aber nur eine funktioniert für den Ring richtig: die linke, wenn Ihr die Treppe hinunterkommt, in der Nähe der freundlichen Gnome.",al={"welcher funkelmat","funkelmat 5200 orte"}}},fx={["5abd59ba"]={q="Warum müsst Ihr den Grime-Encrusted Ring reinigen?",a="Wenn Ihr den Ring von dem gefallenen Dunkeleisenzwerg wegnehmt, ist er mit einer dicken, verhärteten Kruste aus radioaktivem Schlamm und Höhlendreck überzogen. Ihr könnt das schwache Schimmern von Edelmetall und einem Edelstein unter dem Schmutz erkennen, aber die verkrusteten Rückstände machen ihn untragbar und unmöglich zu inspizieren. Ihn zu reinigen ist die einzige Möglichkeit, seine wahre Handwerkskunst zu enthüllen und zu sehen, ob er irgendeinen wirklichen Wert oder Zweck hat.",al={"warum ring reinigen","zweck grime-encrusted ring","warum grime-encrusted ring waschen"}},c5a1096d={q="Was ist der Grime-Encrusted Ring?",a="Es scheint ein wertvolles Schmuckstück zu sein, das von einem der einfallenden Dunkeleisenzwerge nach Gnomeregan gebracht wurde. Völlig erstickt in verstrahltem Industrieschmutz sind seine feine Metallarbeit und der eingebettete Stein vollständig verborgen, bis er durch Gnomeregans automatischen Reinigungsapparat, den Sparklematic 5200, geführt wird.",al={"was ist grime-encrusted ring","grime-encrusted ring hintergrund","was für ein ring ist das"}}},fp="20,417,24.429.0,21.453.1,43.130.0,26.223.0,39.192.0,38.221.0,53.235.0,41.186.0"}
P.entries["quest:2947"] = {n="Die Rückkehr des Rings",s="Nachdem ein Abenteurer Schichten unterirdischen Schlamms im automatischen Reinigungsapparat von Gnomeregan weggespült hat, entdeckt er einen makellosen goldenen Ring, der das Siegel von Eisenschmiede und die Initialen „TdK“ trägt. Die Verfolgung dieser Markierungen führt hinauf in die belebten Handwerkergassen der Zwergenhauptstadt, um seinen exzentrischen Schöpfer ausfindig zu machen.",h="Nachdem ein Abenteurer Schichten unterirdischen Schlamms im automatischen Reinigungsapparat von Gnomeregan...",kw={"blitzender goldring","dunkeleisen","siegel von eisenschmiede","mystic ward","sparklematic","talvash del kissel","tdk"},ang={["faction:Alliance"]="Die Entdeckung von Artefakten mit dem Siegel von Eisenschmiede in den Händen von Dunkeleisenspionen unterstreicht die wachsende Bedrohung, die von den Agenten von Imperator Thaurissan für die Bergheimat der Allianz ausgeht.",["race:Gnome"]="Die Bergung verlorener Handwerkskunst aus der gefallenen Stadt bietet einen seltenen Einblick in das friedliche alltägliche Handwerk, dem die Gnome vor Thermapluggs Katastrophe nachgingen."},sec={{t="Ein schlammverkrusteter Schatz",b="Tief in den verstrahlten Ruinen von Gnomeregan surren uralte Maschinen noch immer im Angesicht der Trogg-Invasion. Führt man ein schmutziges, verkrustetes Schmuckstück in den Sparklematic 5200 ein, werden Jahre verstrahlten, giftigen Schmutzes abgetragen und ein polierter Blitzender Goldring enthüllt, der von arkaner Macht vibriert. Entlang der Innenseite ist das unverwechselbare Siegel von Eisenschmiede eingeprägt, zusammen mit drei sauber eingravierten Initialen: „TdK“."},{t="Der Kunsthandwerker des Mystic Ward",b="Diese Initialen gehören niemand Geringerem als Talvash del Kissel, einem exzentrischen Gnomen-Juwelier, der im Mystic Ward von Eisenschmiede arbeitet – oft während er hektisch imaginäre Geldeintreiber abwehrt. Talvash erkennt die Handwerkskunst schnell als einen seiner standardmäßigen Entwürfe aus der Zeit vor dem Fall aus seinem alten Laden in Gnomeregan wieder. Zu erfahren, dass das Schmuckstück in den Fängen von Dunkeleisenspionen gefunden wurde, erschüttert den Handwerker zutiefst und deutet auf finstere Intrigen hin, die sich unter der verlorenen Technologiestadt zusammenbrauen."}},faq={{q="Wer hat den in Gnomeregan gefundenen Ring hergestellt?",a="Die Initialen „TdK“ gehören Talvash del Kissel, einem verschrobenen Gnomen-Juwelier, der derzeit im Mystic Ward von Eisenschmiede lebt. Vor dem Fall von Gnomeregan betrieb Talvash ein Juweliergeschäft in der Stadt und schmiedete mehrere einfache magische Ringe dieses Designs.",al={"wer hat den ring gemacht","ring initialen tdk","wer ist tdk"}},{q="Woher stammte der Ring ursprünglich?",a="Der Ring wurde als schmutzverkrustetes Schmuckstück tief in Gnomeregan entdeckt, getragen von feindlichen Invasoren wie den Dunkeleisenzwergen. Nachdem er durch den automatisierten Sparklematic 5200 geschickt wurde, kamen sein goldener Glanz und die Zeichen seines Schöpfers wieder zum Vorschein.",al={"wo wurde der ring gefunden","woher stammt der ring"}},{q="Warum trugen Dunkeleisenzwerge Talvashs Ring bei sich?",a="Talvash ist sich nicht ganz sicher, merkt aber an, dass der Fund seines alten Handwerks bei Dunkeleisenspionen den Verschwörungen rund um den Untergang von Gnomeregan eine weitere verdächtige Ebene hinzufügt. Wahrscheinlich stammte er aus seiner verlassenen Werkstatt oder wurde von jemandem geplündert, der der Invasion nicht entkommen konnte.",al={"warum haben dunkeleisen ihn","dunkeleisen ring lore"}},{q="Warum glaubt Talvash del Kissel, dass Ihr sein Vermieter seid?",a="Talvash ist notorisch nervös, exzentrisch und mit seiner Miete in Eisenschmiede chronisch im Rückstand. Wann immer sich Fremde seinem Laden forsch nähern, nimmt er an, es handle sich um Gerichtsvollzieher oder Vermieter, die seine überfälligen Schulden eintreiben wollen.",al={"warum ist talvash paranoid","talvash miete"}},{q="Stellt Talvash verfluchten Schmuck her?",a="Talvash beteuert gegenüber allen potenziellen Kunden vehement, dass er keine verfluchten Gegenstände herstellt, obwohl seine nervösen, vorsorglichen Dementis eher mehr Fragen aufwerfen, als sie beantworten.",al={"ist talvash verflucht","verfluchter schmuck eisenschmiede"}},{q="Kann ich den Ring einfach behalten, anstatt ihn zurückzugeben?",a="Obwohl das Schmuckstück für sich genommen magische Eigenschaften besitzt, ermöglicht das Vorzeigen bei seinem Schöpfer Talvash, das Stück zu begutachten und anzubieten, seine Verzauberung durch anschließende Arbeit noch weiter zu verfeinern.",al={"den ring behalten","sollte ich den ring zurückgeben"}}},fx={["8e194cce"]={q="Warum möchte der Sparklematic 5200, dass der Ring zurückgegeben wird?",a="Das will er nicht. Der Sparklematic 5200 ist ein automatisiertes Reinigungsgerät, das entwickelt wurde, um aus den Tiefen von Gnomeregan geborgenen Schrott zu verarbeiten. Er reinigt alles, was Ihr hineinlegt, und spuckt das restaurierte Objekt wieder aus. Sobald die Maschine den polierten Blitzender Goldring ausgibt, ist die Rückgabe ganz Eure Entscheidung, nachdem Ihr das Herstellersiegel und das Siegel von Eisenschmiede im Band entdeckt habt.",al={"warum ring zurückgeben","motiv sparklematic 5200","warum will die maschine den ring zurück"}}},fp="18,314,24.408.0,30.489.1,38.253.0,40.239.0,51.293.0,55.225.0,33.178.0,49.188.0"}
P.entries["quest:2948"] = {n="Gnomenverbesserungen",s="Nachdem ein Abenteurer ihm einen einst von ihm hergestellten Ring bringt, der aus den verstrahlten Tiefen von Gnomeregan geborgen wurde, bietet Talvash del Kissel an, das Stück für jeden Abenteurer aufzuwerten, der bereit ist, die Materialien zu beschaffen. Der Gnomenhandwerker, der in der Zwergenhauptstadt Eisenschmiede vom Pech verfolgt ist, kombiniert Silber, Moosachat und kunstvolle Gitterarbeiten, um ein weitaus besseres Schmuckstück herzustellen.",h="Nachdem ein Abenteurer ihm einen einst von ihm hergestellten Ring bringt, der aus den verstrahlten Tiefen von...",kw={"blitzender goldring","gnomenverbesserungen","gnomeregan","eisenschmiede","moosachat","silberbarren","talvash"},ang={["faction:Alliance"]="Die Aufgabe, die sich zwischen Gnomeregan und Eisenschmiede abspielt, festigt die tiefen Bande zwischen den Helden der Allianz und den vertriebenen Flüchtlingen der gefallenen Gnomenhauptstadt.",["profession:Mining"]="Bergleute liefern die grundlegenden Rohstoffe – verhüttetes Silber und geschliffene Moosachate aus unterirdischen Vorkommen –, die für Talvashs Juwelierarbeiten benötigt werden.",["race:Gnome"]="Diese Quest unterstreicht den Stolz und die Widerstandskraft der Gnomenhandwerker, die sich weigern, minderwertige Arbeit abzuliefern, selbst wenn sie aus ihrer Heimat vertrieben und ihrer Rohstoffe beraubt wurden."},sec={{t="Ein Gnomenhandwerker im Exil",b="Talvash del Kissel ist einer der vielen Gnomenflüchtlinge, die nach dem verheerenden Fall Gnomeregans durch die Trogg-Invasion und die Verstrahlung geflohen sind. Talvash, der im Mystic Ward von Eisenschmiede lebt, ist vom Pech verfolgt, hat keine Vorräte mehr und will unbedingt beweisen, dass seine Talente als Juwelier- und Tüftelmeister trotz seines Exils ungebrochen sind."},{t="Aufwertung des alten Reifs",b="Als ein Abenteurer Talvash einen Ring seines eigenen einfachen Vorkriegsdesigns zeigt, der vom Glitzer-o-Mat 5200 von Schmutz befreit wurde, zeigt sich Talvash dankbar, aber ehrgeizig. Anstatt einen Kunden mit einem seiner Ansicht nach veralteten, einfachen Ringdesign gehen zu lassen, besteht er darauf, ihn zu verbessern. Indem er ein zartes Gitterwerk aus Silber und Moosachat über den Reif legt, erschafft er ein verbessertes Stück, das seine wachsende Meisterschaft in der Metall- und Edelsteinbearbeitung widerspiegelt."}},faq={{q="Wer ist Talvash del Kissel?",a="Talvash del Kissel ist ein geschickter Gnomenhandwerker und Juwelier, der derzeit im Exil in Eisenschmiede lebt. Vor dem Fall betrieb er einen kleinen Juwelierladen in Gnomeregan, und einer der Ringe, die er dort herstellte, kann geborgen und zu ihm in den Mystic Ward gebracht werden.",al={"talvash","talvash del kissel","gnomenjuwelier eisenschmiede"}},{q="Welche Geschichte steckt hinter dem aufgewerteten Ring?",a="Der Basisring ist einer von mehreren einfachen Ringen, die Talvash in seinem alten Laden in Gnomeregan gefertigt hat und die später bei einem Dunkeleisenzwerg in den Ruinen gefunden wurden. Nachdem er von Abenteurern aus der Reinigungsmaschine Glitzer-o-Mat 5200 in der zerstörten Stadt geborgen wurde, bietet Talvash an, das schlichte Band zu modernisieren, zu verschönern und in ein viel feineres Schmuckstück zu verwandeln.",al={"woher stammt der ring","ursprung schmutzverkrusteter ring"}},{q="Warum bittet Talvash den Spieler um die Reagenzien?",a="Wie viele aus Gnomeregan vertriebene Gnomenflüchtlinge hat Talvash finanzielle Probleme und seine Rohstoffvorräte in Eisenschmiede vollständig aufgebraucht. Ihm fehlen das Silber und der Moosachat, die nötig sind, um die filigrane Gitterarbeit ohne einen Förderer selbst durchzuführen.",al={"warum brauche ich silber und moosachat","warum hat talvash keine materialien"}},{q="Wo beginnt diese Questreihe?",a="Die Questreihe beginnt in der Instanz Gnomeregan, indem man einen Schmutzverkrusteten Ring von Gegnern erbeutet, ihn an der Maschine Glitzer-o-Mat 5200 reinigt und dann den eingravierten Initialen „TdK“ zurück zu Talvash in Eisenschmiede folgt.",al={"wie startet man gnomen-verbesserungen","start der ring-questreihe"}},{q="Ist Talvash verbittert über seine Situation in Eisenschmiede?",a="Obwohl er beklagt, in einer ungerechten finanziellen Notlage zu stecken, behält Talvash seinen Lebensmut und seinen professionellen Stolz. Er glaubt fest daran, dass er, sobald er wieder auf den Beinen ist, in ganz Azeroth für die Herstellung der feinsten Schmuckstücke bekannt sein wird.",al={"talvash hintergrundgeschichte","talvash persönlichkeit"}},{q="Hat die Horde Zugang zu dieser Quest?",a="Nein. Während Hordenspieler schmutzverkrustete Gegenstände in Gnomeregan reinigen können, leitet ihre Version der Ringquest sie an einen alternativen Kontakt weiter – Nogg in Orgrimmar statt Talvash in Eisenschmiede.",al={"kann horde gnomen-verbesserungen machen","ringaufwertung horde"}}},fx={["2e3e2066"]={q="Wofür ist der Silberbarren?",a="Talvash braucht das veredelte Metall, um Euren ursprünglichen Ring in ein komplizierteres Schmuckstück umzuformen. Er verwendet den Silberbarren, um direkt auf das Band eine detaillierte Gitterarbeit zu schmieden, die dem einfachen Design weit mehr Eleganz und Haltbarkeit verleiht, als seine frühe Handwerksarbeit besaß.",al={"warum silberbarren","talvash silberbarren","wofür braucht er silber"}},a02fa77a={q="Wofür ist der Moosachat?",a="Der Moosachat dient als dekoratives Herzstück für die Aufwertung des Rings. Indem er den polierten grünen Edelstein in das neu geschmiedete Silbergeflecht einsetzt, beabsichtigt Talvash, Flair hinzuzufügen und seine wahre Expertise als Kunsthandwerker zu präsentieren, wodurch ein rudimentäres Schmuckstück in ein weitaus beeindruckenderes Werk verwandelt wird.",al={"warum moosachat","talvash moosachat","wofür braucht er achat"}}},fp="17,365,26.346.0,22.439.0,26.252.0,51.315.0,56.262.0,34.225.0,51.259.0,41.197.0"}
P.entries["quest:2949"] = {n="Die Rückkehr des Rings",s="Nachdem der Schmutz von Gnomeregan im Funkelmat 5200 weggespült wurde, entdeckt ein Abenteurer einen Ring mit dem Siegel von Orgrimmar und den eingravierten Buchstaben „NOG“. Die Spur des Schmuckstücks zurück zur Hauptstadt der Horde führt direkt zum Gobliningenieur Nogg, der seine ganz eigenen neugierigen Theorien über den Fall der Stadt hegt.",h="Nachdem der Schmutz von Gnomeregan im Funkelmat 5200 weggespült wurde, entdeckt ein Abenteurer einen Ring mit...",kw={"blitzender goldring","dunkeleisenzwerge","gnomeregan","nogg","orgrimmar","die rückkehr des rings","funkelmat 5200","tal der ehre"},ang={["faction:Horde"]="Horde-Ikonografie tief im Inneren der führenden technologischen Hauptstadt der Östlichen Königreiche zu finden, ist ein seltener Anblick, der Horde-Abenteurer direkt von Khaz Modan zurück ins Tal der Ehre führt.",["profession:Engineering"]="Die Gobliningenieure in Orgrimmar messen sich ständig an gnomischen Erfindungen, und Nogg brennt darauf, alles zu zerlegen, was aus dem Herzen ihres gefallenen technologischen Wunders geborgen wurde."},sec={{t="Eine merkwürdige Entdeckung",b="Gnomeregan ist eine Stadt der Allianz tief in Khaz Modan, was den Fund eines Rings mit dem offiziellen Siegel von Orgrimmar völlig unerwartet macht. Sobald er die funkelmatische Reinigungsanlage der Gnome durchlaufen hat, streift das Schmuckstück seine dicke Schicht aus unterirdischem Schlamm ab und offenbart einen Schwall magischer Kraft sowie die teilweise lesbaren Buchstaben „NOG“. Ob er nun in Kalimdor geschmiedet oder auf eine verhängnisvolle Expedition mitgeführt wurde: Das Schmuckstück hat eindeutig Wurzeln in der Hauptstadt der Horde."},{t="Gnomische Rivalitäten und Dunkeleisernes",b="Bringt man den Ring zurück ins Tal der Ehre in Orgrimmar, führt dies direkt zu Nogg, einem Ingenieur, der schnell klarstellt, dass der Ring zwar nicht sein persönliches Schmuckstück ist, dessen Herkunft jedoch faszinierende Fragen aufwirft. Goblins blicken seit Langem auf gnomische Erfinder als exzentrische Rivalen herab. Für Nogg deutet die Tatsache, dass Dunkeleisenzwerge den Ring in Gnomeregan besaßen, darauf hin, dass die Gnome die Golementwürfe der Dunkeleisenzwerge gestohlen und modifiziert haben könnten – woraufhin die Dunkeleisenzwerge auf Vergeltung aus waren; eine Spur, die er für untersuchungswürdig hält."}},faq={{q="Warum trägt ein in Gnomeregan gefundener Ring das Siegel von Orgrimmar?",a="Die genauen Umstände, wie der Ring nach Gnomeregan gelangte, bleiben unbekannt, doch er wurde tief in die Ruinen getragen und von Dunkeleisenzwergen geborgen. Seine Insignien von Orgrimmar verbinden ihn mit den Metallurgen und Handwerkern der Horde, die in Durotar tätig sind.",al={"warum orgrimmar-siegel","horde-ring in gnomeregan","wie kam der ring dorthin"}},{q="Wer ist Nogg?",a="Nogg ist ein Gobliningenieur im Tal der Ehre in Orgrimmar. Er beaufsichtigt Ingenieursbedarf sowie Maschinen, und sein Name passt zu den abgenutzten Buchstaben, die neben dem Siegel von Orgrimmar auf dem gereinigten Ring eingraviert sind.",al={"wer ist nogg","nogg orgrimmar","nog buchstaben ring"}},{q="Was ist der Funkelmat 5200?",a="Der Funkelmat 5200 ist ein automatisiertes industrielles Waschsystem in der Clean Zone von Gnomeregan. Es entfernt dicke Schichten giftigen Schlamms und Verstrahlung von Gegenständen, die aus den zerstörten Korridoren geborgen wurden.",al={"was ist der funkelmat","funkelmat 5200","reinigungsautomat"}},{q="Gehört der Ring Nogg?",a="Nein. Wenn ihm das gereinigte Band vorgelegt wird, begutachtet Nogg es und räumt ein, dass es nicht ihm gehört. Er erkennt jedoch die Handwerkskunst an und nutzt sein ingenieurtechnisches Fachwissen, um es für den Abenteurer weiter zu modifizieren.",al={"ist es noggs ring","hat nogg seinen ring verloren","wem gehört der ring"}},{q="Was glaubt Nogg, was mit Gnomeregan geschehen ist?",a="Nogg vermutet, dass die Gnome fortschrittliche Golem-Baupläne vom Dunkeleisenclan gestohlen haben. Er schlussfolgert, dass die Dunkeleisenzwerge dafür gehörige Vergeltung üben wollten, und hält diese Spur für untersuchungswürdig.",al={"nogg gnomeregan theorie","was geschah mit gnomeregan","warum dunkeleisenzwerge"}},{q="Kann ich den Ring behalten, anstatt ihn zu Nogg zurückzubringen?",a="Ihr habt die Wahl, den Ring sofort anzulegen oder ihn nach Orgrimmar zu bringen. Bringt Ihr ihn jedoch zu Nogg, kann der Gobliningenieur dessen Handwerkskunst begutachten und weitere Verbesserungen anbieten.",al={"blitzender goldring behalten","sollte ich den ring zurückgeben","muss ich ihn nogg geben"}}},fx={["9392e9ce"]={q="Warum möchte der Sparklematic 5200, dass der Ring zurückgegeben wird?",a="Der Sparklematic 5200 hat keinen eigenen Willen oder Motiv – es ist lediglich ein automatischer Reinigungsapparat in Gnomeregan, der dazu gedacht ist, Schmutz von geborgenen Objekten zu schrubben und auszugeben, was auch immer herauskommt. Sobald er Euren Grime-Encrusted Ring reinigt und ihn in einer verpackten Schachtel ausgibt, ist seine Funktion beendet. Die Entscheidung, die im Band eingravierten Initialen aufzuspüren, entspringt rein Eurer eigenen Neugier, nachdem Ihr das Orgrimmar-Siegel und die teilweise geätzten Buchstaben entdeckt habt.",al={"sparklematic motiv","warum ring sparklematic zurückgeben","ziel sparklematic 5200"}}},fp="18,307,19.460.0,37.508.1,63.251.0,12.214.0,30.215.0,23.218.1,44.196.0,52.191.0"}
P.entries["quest:295"] = {n="Ormers Rache",s="Ormers Rache ist eine Allianz-Aufgabe von Ormer Eisenzopf an der zerstörten Ausgrabungsstätte von Whelgar im Sumpfland. Nachdem die ersten Kundschafter-Raptoren dezimiert wurden, verlangt Ormer die Tötung der schwereren gesprenkelten Sensenklauen und Rasiermesser, die seine Expedition aus den Gruben vertrieben haben.",h="Ormers Rache ist eine Allianz-Aufgabe von Ormer Eisenzopf an der zerstörten Ausgrabungsstätte von Whelgar im...",kw={"zwerg","ausgrabung","forscherliga","gesprenkeltes rasiermesser","gesprenkelte sensenklaue","ormer eisenzopf","raptoren","sumpfland","whelgar ausgrabungsstätte"},ang={["class:Hunter"]="Die gesprenkelten Raptoren des Sumpflands sind äußerst revierbezogene Rudeljäger, die in den beengten, schlammigen Gräben eine tödliche Herausforderung beim Aufspüren darstellen.",["faction:Alliance"]="Die Rückeroberung der Ausgrabungsstätte von Whelgar sichert einen gefahrlosen Betrieb entlang der östlichen Straße, die das Sumpfland mit dem Arathihochland verbindet.",["race:Dwarf"]="Ormers Zorn spiegelt den unbändigen Stolz der Forscherliga wider, die sich weigert, die Bemühungen der Zwerge, ihre angestammte Vergangenheit freizulegen, von wilden Bestien dauerhaft aufhalten zu lassen."},sec={{t="Eskalation der Jagd",b="Ormer Eisenzopfs Groll gegen die Raptoren, die auf der Ausgrabungsstätte von Whelgar wüten, ist zutiefst persönlicher Natur. Nachdem Ihr die kleineren Jungtiere ausgedünnt habt, die das obere Lager überrannten, richtet er Eure Klingen gegen die ausgewachsenen Raubtiere, die in der unteren Ausgrabungsstätte umherstreifen. Die gesprenkelten Sensenklauen und Rasiermesser stellen die größte Bedrohung für jede Hoffnung dar, die archäologischen Arbeiten wiederaufzunehmen; sie zerfleischten die Zwergenprospektoren und hinterließen die Gräben übersät mit zerschlagenen Kisten und verlassenen Spitzhacken."},{t="Blut in den Gräben",b="Die Ausgrabungsgruben haben sich praktisch in einen Nistplatz für Raptoren verwandelt. Während Ormer auf dem Bergrücken über der Ausgrabung brütet, schickt er fähige Abenteurer hinab in den Schlamm, um die ausgewachsenen Bestien direkt anzugreifen. Während Ausgrabungsleiter Whelgar und seine Mannschaft hoffen, uralte Relikte zu bergen, ist Ormer völlig von Rachegedanken zerfressen und verlangt eine beachtliche Anzahl toter Sensenklauen und Rasiermesser, bevor er überhaupt daran denkt, sich dem größten Schrecken der Stätte zu stellen."}},faq={{q="Warum ist Ormer so wütend auf diese Raptoren?",a="Die gesprenkelten Raptoren überrannten die Ausgrabungsstätte von Whelgar in Scharen, vertrieben das Zwergenteam und töteten jeden, der nicht rechtzeitig entkommen konnte. Ormer Eisenzopf blieb vertrieben und verbittert zurück, und er weigert sich, den Bestien die Herrschaft über die Ausgrabung zu überlassen, ohne dass sie teuer mit Blut dafür bezahlen.",al={"warum ormer wütend","ormer rache grund","warum raptoren sumpfland töten"}},{q="Wo sind die gesprenkelten Sensenklauen und Rasiermesser zu finden?",a="Beide Raptorenarten streifen durch die unteren Ausgrabungsgräben und die umliegenden Erdwälle der Ausgrabungsstätte von Whelgar, die östlich vom Hafen von Menethil und südwestlich von Dun Modr im Sumpfland liegt.",al={"gesprenkelte sensenklauen standort","gesprenkelte rasiermesser standort","wo raptoren für ormer finden"}},{q="Wer ist Ormer Eisenzopf?",a="Ormer Eisenzopf ist ein zwergisches Mitglied der Forscherliga, das an der Ausgrabungsstätte von Whelgar stationiert ist. Nach der verheerenden Überrennung der Ausgrabung hat er es sich zur persönlichen Aufgabe gemacht, das Raptorenrudel auszurotten, das ihre Arbeit heimsucht.",al={"wer ist ormer","ormer eisenzopf geschichte"}},{q="Was geschieht nach dem Ausdünnen dieser Raptoren?",a="Sobald Ihr die Sensenklauen und Rasiermesser dezimiert habt, richtet Ormer seinen Blick auf Sarltooth, den großen Raptor, den er für den Anführer des örtlichen Rudels hält, und beauftragt Euch, der Hauptursache der Raptorenplage ein Ende zu setzen.",al={"was folgt nach ormers rache","ormers rache fortsetzung","folgequest nach sensenklauen"}},{q="Steht diese Quest mit anderen Aufgaben an der Ausgrabungsstätte in Verbindung?",a="Ja. Während Abenteurer für Ormer die Raptoren in der gesamten unteren Ausgrabungsstätte jagen, helfen sie Ausgrabungsleiter Whelgar und seinem Team häufig bei 'Enthüllung der Vergangenheit', indem sie zersplitterte irdene Artefakte sammeln, die in denselben Gräben verstreut liegen.",al={"whelgar ausgrabung quests","verbindung enthüllung der vergangenheit"}},{q="Warum haben die Zwerge hier überhaupt gegraben?",a="Die Forscherliga von Eisenschmiede errichtete die Ausgrabungsstätte von Whelgar, um nach Titanenrelikten zu suchen und die uralte Geschichte des Zwergenvolks aufzudecken, doch ihre Arbeiten wurden gestoppt, als aggressive Wildtiere die Grabung überrannten.",al={"warum ausgrabung sumpfland","whelgar ausgrabung zweck"}}},fx={["2ccf3294"]={q="Was sind Gefleckte Sensenklauen und Gefleckte Reißmäuler?",a="Diese bösartigen Raptorarten durchstreifen die unteren Ebenen der Whelgar-Ausgrabungsstätte. Bekannt für ihre Blutgier und messerscharfen Krallen, überrannten sie die Zwergenausgräber und vertrieben sie aus ihren Arbeitsgruben. Ormer weist Euch nun an, ihre tödlichsten Varietäten zu jagen, um ihre Vorherrschaft über die Ruinen zu brechen.",al={"was sind sensenklauen und reißmäuler","gefleckte sensenklauen","gefleckte reißmäuler","sumpfland raptoren"}},f1520877={q="Warum benötigt Ormer, dass Ihr die Raptoren jagt, anstatt sich selbst darum zu kümmern?",a="Ormer und die überlebenden Ausgrabungsleiter wurden auf den Grat oberhalb der Ausgrabungsstätte vertrieben. Da ihr Ausgrabungsteam verstreut oder getötet wurde, fehlt ihnen das Personal, um allein einen aggressiven Gegenangriff zu starten, und sie benötigen fähige Abenteurer, die bereit sind, in ihrem Namen tief in die verseuchten Gruben hinabzusteigen.",al={"warum braucht ormer hilfe","warum tötet ormer raptoren nicht","warum ich ormer"}}},fp="15,272,19.491.0,21.441.0,39.292.0,54.186.0,23.238.0,41.213.1,62.242.0,53.232.0"}
P.entries["quest:2950"] = {n="Noggs Ringerneuerung",s="Noggs Ringerneuerung schließt die Untersuchung eines schmutzverkrusteten Schmuckstücks ab, das aus den Ruinen von Gnomeregan nach Orgrimmar gebracht wurde. Im Tausch gegen seltene Materialien und wertvolle Informationen über die Aktivitäten der Dunkeleisenzwerge veredelt der Gobliningenieur Nogg das geborgene Schmuckstück, voller Eifer beweisen zu wollen, dass Goblin-Handwerkskunst gnomischen Konstruktionen überlegen ist.",h="Noggs Ringerneuerung schließt die Untersuchung eines schmutzverkrusteten Schmuckstücks ab, das aus den Ruinen...",kw={"blitzender goldring","dunkeleisen","gnomeregan","goblin-ingenieurskunst","moosachat","nogg","orgrimmar","silberbarren"},ang={["faction:Horde"]="Die Bergung von Technologie aus allianznahen Hallen wie Gnomeregan und deren Übergabe an Orgrimmars Tüftler verschafft der Horde entscheidende Einblicke in die Fähigkeiten des Feindes.",["profession:Engineering"]="Die Quest veranschaulicht die ständige ideologische Rivalität zwischen Goblin-Einfallsreichtum und Gnomenspielereien und unterstreicht den Goblin-Ansatz, bestehende Technologie für maximale Leistung aggressiv zu modifizieren.",["profession:Mining"]="Die Veredelung des geborgenen Rings erfordert wertvolle Bodenschätze – einen raffinierten Silberbarren und einen Moosachat –, was die Dienste geschickter Bergleute und Edelsteinschleifer verlangt."},sec={{t="Goblin-Überlegenheit",b="Als ein Abenteurer einen gereinigten Goldring aus den Tiefen von Gnomeregan zu Noggs Werkstatt im Tal der Ehre zurückbringt, übernimmt der natürliche Stolz des Ingenieurs die Oberhand. Nogg tut die ursprüngliche Handwerkskunst als bescheidenes Werk eines Gnoms ab und bietet ein Geschäft an. Für Rohmaterialien und eine bescheidene Gebühr verspricht er, das Schmuckstück der Allianz zu verbessern, indem er ein kunstvolles Gitter aus Silber und Moosachat anfertigt, das die durch den Reif fließende Magie verstärken soll."},{t="Eine Zwergen-Verbindung",b="Noggs plötzliche Bereitschaft, den Ring zu verbessern, rührt nicht allein von kommerziellem Interesse her. Die Berichte über Dunkeleisenzwerge, die in der belagerten Gnomstadt lauern, wecken seine scharfe Aufmerksamkeit. Für Nogg erklärt die Anwesenheit der Zwerge, warum Goblins plötzliche Ausbrüche mechanischer Raffinesse verzeichnen konnten – etwas, das Goblins als ihre ganz eigene Domäne betrachten. Das Zusammentragen dieser Informationen bringt dem Abenteurer ein aufgewertetes Schmuckstück und Noggs widerwilligen Respekt ein."}},faq={{q="Wer ist Nogg?",a="Nogg ist ein prominenter Gobliningenieur, der im Tal der Ehre in Orgrimmar tätig ist. Er arbeitet eng mit anderen Tüftlern in der Drag und dem Tal der Ehre zusammen und befasst sich häufig mit merkwürdigen mechanischen Artefakten und Bauplänen, die von gefährlichen Expeditionen geborgen wurden.",al={"wer ist nogg","nogg orgrimmar","nogg nsc"}},{q="Welche Materialien werden benötigt, um den Ring umzuschmieden?",a="Nogg benötigt den originalen Blitzenden Goldring, einen Silberbarren, einen Moosachat und dreißig Silbermünzen, um seine Arbeit und die Werkstattkosten zu bezahlen.",al={"ring materialien","nogg materialien","was braucht nogg"}},{q="Warum interessiert sich Nogg für Gnomeregan?",a="Gnomeregan besitzt einen immensen technologischen Wert. Goblins stehen in technischen Bereichen in scharfer Konkurrenz zu Gnomen, und Nogg ist besonders fasziniert von Gerüchten, dass Dunkeleisenzwerge an den technologischen Anomalien in der gefallenen Technostadt beteiligt waren.",al={"warum interessiert nogg gnomeregan","gnomeregan goblin interesse"}},{q="Was genau macht Nogg mit dem Ring?",a="Nogg konstruiert ein Gitter aus Silber und Moosachat direkt um den goldenen Reif. Dieses feine Gerüst kanalisiert und stabilisiert die schlummernden Verzauberungen im Inneren des Schmuckstücks, was zu einem stärkeren, wirkungsvolleren Gegenstand führt als der ursprüngliche gnomische Entwurf.",al={"ring aufwertung lore","was ändert sich am ring"}},{q="Wo beginnt diese Questreihe?",a="Die Questreihe beginnt tief im Inneren von Gnomeregan, wenn ein Abenteurer einen Schmutzverkrusteten Ring von einem der Dunkeleisenzwerge erbeutet und ihn mithilfe der Funkel-o-Mat 5200-Maschine säubert.",al={"reihenstart","nogg quest starten","ring questreihe start"}},{q="Warum schöpft Nogg Verdacht gegen die Dunkeleisenzwerge?",a="Gobliningenieure blicken mit tiefem Misstrauen auf gnomische Innovationen. Für Nogg muss jeder plötzliche Funke radikaler mechanischer Erkenntnis bei Gnomen von externen Einmischern beeinflusst oder bereitgestellt worden sein – namentlich dem ränkescheidenden Dunkeleisen-Klan.",al={"warum dunkeleisen","dunkeleisenzwerge verbindung"}}},fx={e11b7fb8={q="Warum will Nogg den Ring umschmieden?",a="Nogg beansprucht den Ring nicht für sich, ist Euch aber aufrichtig dankbar für die Informationen, die Ihr bezüglich der Dunkeleisenzwerge in Gnomeregan zurückgebracht habt. Als Gobliningenieur kann er es sich zudem nicht verkneifen, sein überlegenes Handwerk zur Schau zu stellen: Er möchte unbedingt beweisen, dass er die plumpe Arbeit der Gnomtüftler übertreffen kann, indem er ihr Design mit einem weitaus mächtigeren magischen Gitter verbessert.",al={"warum bietet nogg an, den ring umzuschmieden","warum ring umschmieden","noggs motiv ring umschmieden"}},["63dec8fa"]={q="Wofür wird der Silberbarren in 'Nogg's Ring Redo' verwendet?",a="Nogg verwendet den Silberbarren, um ein verfeinertes strukturelles Gitter um den Ring zu schmieden. Dieses filigrane Metallgerüst dient als physische Hülle, die benötigt wird, um zusätzliche magische Verzauberungen zu binden, ohne den bestehenden Kern des Rings zu stören.",al={"wofür ist der silberbarren","silberbarren nogg","warum silberbarren ring umschmieden"}},c138af81={q="Wofür wird der Moosachat in 'Nogg's Ring Redo' verwendet?",a="Der Moosachat wird in das neue Silbergeflecht eingearbeitet, das Nogg für Euren Ring erschafft. Seine inhärenten mineralischen Eigenschaften helfen dabei, die latente magische Energie, die in dem Stück enthalten ist, zu kanalisieren und zu verstärken, wodurch aus einem einfachen Gnomenschmuckstück ein weitaus mächtigeres Artefakt wird.",al={"wofür ist der moosachat","moosachat nogg","warum moosachat ring umschmieden"}}},fp="16,322,18.448.0,15.467.1,12.264.0,46.147.0,37.245.0,39.253.0,34.182.0,40.227.0"}
P.entries["quest:2951"] = {n="Der Funkelmat 5200!",s="Tief in den Ruinen von Gnomeregan ist der Sparklematic 5200 ein automatisches Reinigungsgerät, das inmitten des Chaos weiterhin funktioniert. Indem sie ihm ein in den unterirdischen Hallen geborgenes Schmutzverkrustetes Objekt zusammen mit einer geringen Münzgebühr zuführen, können Abenteurer geborgene Schmuckstücke, Edelsteine und Schrott in makellosen Zustand zurückversetzen. Er steht als lebendiges Zeugnis für den unerschütterlichen Erfindungsgeist und die Exzentrizität der gnomischen Ingenieurskunst.",h="Tief in den Ruinen von Gnomeregan ist der Sparklematic 5200 ein automatisches Reinigungsgerät, das inmitten...",kw={"reiniger","gnom","gnomeregan","schmutzverkrustet","maschine","bergungsgut","sparklematic","sparklematic 5200","trogg"},ang={["faction:Alliance"]="Für Bergungsteams der Allianz, die den Hallen von Gnomeregan trotzen, bietet die Maschine eine unmittelbare Möglichkeit, gefundene Relikte zu reinigen, bevor sie nach Eisenschmiede zurückgebracht werden.",["profession:Engineering"]="Ingenieure können den robusten Motor und die Sortierarchitektur schätzen, die erforderlich sind, um unbekannte Trümmerteile zu reinigen und zu verarbeiten, ohne zu blockieren oder zu explodieren.",["race:Gnome"]="Die Maschine spiegelt die klassische Unverwüstlichkeit der Gnome wider: Selbst während einer katastrophalen Evakuierung der Heimat gehen Handel und funkelnde Sauberkeit ohne Unterbrechung weiter."},sec={{t="Ein Leuchtfeuer im Schmutz",b="Inmitten des radioaktiven Niederschlags und der Trogg-Invasion, die Gnomeregan heimsuchen, hält eine Gruppe überlebender Gnome einen gesicherten Bereich nahe einer außergewöhnlichen Erfindung aufrecht: dem Sparklematic 5200. Konstruiert, um den hartnäckigen unterirdischen Schmutz von geborgenen Wertsachen abzuwaschen, verspricht diese robuste Vorrichtung, den Glanz zurückzubringen. Selbst während unterirdische Monstrositäten gegen die Schotten hämmern, steht die Maschine für den kommerziellen Betrieb bereit."},{t="Fieberhafter Betrieb",b="Der Reinigungsmechanismus ist alles andere als sanft. Sobald ein Abenteurer ein schmutzverkrustetes Relikt zusammen mit drei Silbermünzen einwirft, gerät der Sparklematic in einen heftigen, wirbelnden Rausch. Der gesamte eiserne Apparat stöhnt, vibriert und schwankt von Seite zu Seite, während er giftigen Schlamm, verstrahltes Fett und Gesteinsstaub abträgt. Augenblicke später spuckt er aus, was auch immer unter dem Dreck begraben war – von wertvollen Mineralien bis hin zu mechanischen Bauteilen."}},faq={{q="Was ist der Sparklematic 5200?",a="Der Sparklematic 5200 ist eine automatische gnomische Reinigungsapparatur, die im sicheren Bereich von Gnomeregan aufgestellt ist. Er ist dafür konstruiert, hartnäckiges radioaktives Fett, Schlamm und Dreck von verkrusteten Gegenständen zu entfernen, die in der gefallenen Stadt geborgen wurden.",al={"was macht sparklematic 5200","sparklematic maschine","reinigungsmaschine gnomeregan"}},{q="Was benötigt die Maschine, um zu funktionieren?",a="Der Betrieb des Sparklematic erfordert ein Schmutzverkrustetes Objekt, das bei den Monstern und Trümmern von Gnomeregan gefunden wird, sowie eine Bearbeitungsgebühr von drei Silbermünzen, die direkt in den Münzschlitz der Maschine eingeworfen wird.",al={"sparklematic benutzen","sparklematic kosten","was in sparklematic einwerfen"}},{q="Warum steht mitten in einem Kriegsgebiet eine funktionierende Maschine?",a="Die Zivilisation der Gnome wurde um automatisierte häusliche und industrielle Annehmlichkeiten herum aufgebaut. Als die Trogg-Invasion und giftige Dämpfe die Stadt verwüsteten, zogen sich überlebende Gnome in befestigte Werkstätten zurück, in denen Maschinen wie der Sparklematic intakt und mit Energie versorgt blieben.",al={"warum steht sparklematic hier","wer hat sparklematic gebaut"}},{q="Was kommt nach der Reinigung eines schmutzverkrusteten Gegenstands heraus?",a="Die Maschine gibt Euren geborgenen Gegenstand vollständig von Schmutz befreit zurück und enthüllt nützliche Handwerkswaren, Handwerkssteine, Edelsteine oder Ingenieursersatzteile, die unter dem Dreck begraben lagen.",al={"belohnung sparklematic","sparklematic beute","schmutzverkrustetes objekt belohnungen"}},{q="Kann ich den Sparklematic 5200 mehr als einmal verwenden?",a="Ja. Nach den anfänglichen Vorführungen kann die Vorrichtung im Rahmen fortlaufender Reinigungsaufgaben wiederholt genutzt werden, solange Ihr zusätzliche Schmutzverkrustete Objekte und Silbermünzen bereitstellt.",al={"sparklematic wiederholbar","mehrere schmutzige gegenstände reinigen","mehr sparklematic"}},{q="Warum rüttelt die Maschine während der Reinigung so heftig?",a="Der verkrustete Schmutz in Gnomeregan ist dicht, giftig und ausgehärtet. Die Maschine setzt auf Hochgeschwindigkeits-Vibrationen und interne Schrubber, um den Schmutz abzutragen, wodurch das gesamte Gehäuse während des Betriebs schwankt und ächzt.",al={"sparklematic wackelt","ist sparklematic kaputt"}}},fx={["3b5f4e4c"]={q="Warum führt der Sparklematic 5200 dies aus?",a="Der Sparklematic 5200 ist kein empfindungsfähiges Wesen, sondern ein automatisiertes Gnomengerät, das für einen einzigen kommerziellen Zweck gebaut wurde: das Reinigen von schmutzigen, verkrusteten Wertgegenständen für zahlende Kunden. Wie auf seiner Messingplakette beworben, ist er darauf ausgelegt, ruinierte, schlammbedeckte Relikte, die aus den verseuchten Hallen von Gnomeregan geborgen wurden, für drei Silbermünzen zu reinigen. Er verfolgt keine persönlichen Ziele, abgesehen davon, seine Programmierung zu erfüllen, wann immer er mit dem richtigen Brennstoff und Münzen gefüttert wird.",al={"warum will sparklematic gegenstände","sparklematic 5200 zweck","warum sparklematic füttern"}},["757f94ef"]={q="Wozu dient das Schmutzverkrustetes Objekt?",a="Ein Schmutzverkrustetes Objekt ist ein nicht identifizierbares Stück geborgener Gnomentechnologie, Mineralerz oder persönlicher Schmuck, das mit dem giftigen Schlamm und der Strahlung, die Gnomeregan überfluten, bedeckt ist. In seinem verschmutzten Zustand ist der Gegenstand völlig nutzlos und seine wahre Natur bleibt verborgen. Wenn Ihr es in den Sparklematic 5200 gebt, schrubbt er den radioaktiven Schlamm und die ätzenden Ablagerungen ab und enthüllt, welche wertvolle Ausrüstung, Edelsteine oder Metallschrott darunter liegen.",al={"was ist schmutzverkrustetes objekt","schmutzverkrustetes objekt zweck","warum schmutzverkrustetes objekt behalten"}}},fp="22,425,21.442.0,18.441.0,30.242.0,41.210.0,64.263.0,53.184.0,47.184.0,56.226.0"}
P.entries["quest:2952"] = {n="Der Funkelmat 5200!",s="Tief in den verstrahlten Hallen von Gnomeregan steht der Sparklematic 5200, eine automatische Reinigungsvorrichtung, die dazu dient, giftigen Schmutz von geborgenem Treibgut zu schrubben. Die Bedienung der Maschine entfernt dicken Dreck von verschmutzten Gegenständen und verpackt alles, was geborgen werden kann, in einer dekorativen Geschenkbox.",h="Tief in den verstrahlten Hallen von Gnomeregan steht der Sparklematic 5200, eine automatische...",kw={"reinigung","vorrichtung","dekontamination","gnomeregan","schmutz","maschine","sparklematic"},ang={["profession:Engineering"]="Die Untersuchung des Sparklematic bietet einen Einblick in die automatische Partikelreinigung und schnelle Verpackungsmechanismen, die dafür konstruiert wurden, starker Umgebungsstrahlung standzuhalten.",["race:Gnome"]="Der Sparklematic ist eine deutliche Erinnerung an die Heimat vor dem Fall: Selbst eine industrielle Schrubbeinheit musste fröhlich bimmeln und das fertige Produkt wie ein Geburtstagsgeschenk verpackt ausliefern."},sec={{t="Automatische Reinigung",b="Gnomische Ingenieurskunst schätzt Effizienz und Verspieltheit oft gleichermaßen. Der Sparklematic 5200 wurde gebaut, um giftigen und kontaminierten Müll zu verarbeiten, indem er Dreck und ätzende Rückstände durch automatische Zyklen abwäscht. Sobald die Vorrichtung beladen und bezahlt ist, rattert sie durch ihre Reinigungsroutine, ehe sie ein fröhliches Klingeln von sich gibt und alles, was übrig bleibt, ordentlich in ein mit einer Schleife versehenes Geschenk verpackt."},{t="Schätze im Schlamm",b="Seit dem Fall von Gnomeregan an die Troggs und der darauf folgenden Strahlenkatastrophe wurden unzählige persönliche Gegenstände und technischer Schrott in industriellem Morast begraben. Abenteurer, die Schmutzverkrustete Objekte in die Maschine werfen, können verlorene Edelsteine, Roherze und lang verschollene Wertsachen bergen, die verschlungen wurden, als die Stadt entlüftet wurde."}},faq={{q="Was bewirkt der Sparklematic 5200?",a="Der Sparklematic 5200 ist eine automatische Reinigungsmaschine in Gnomeregan. Wird er mit einem Schmutzverkrusteten Objekt und einer Münzgebühr gefüttert, entfernt er Schlamm, Dreck und radioaktiven Schmodder und gibt den gereinigten Inhalt in einer kleinen Geschenkbox verpackt zurück.",al={"was ist sparklematic 5200","wie sparklematic funktioniert","sparklematic funktion"}},{q="Wo befindet sich der Sparklematic 5200?",a="Die Maschine befindet sich in den inneren Korridoren der gefallenen Stadt Gnomeregan, nahe der Clean Zone, wo einst Überlebende und automatische Dekontaminationssysteme im Einsatz waren.",al={"sparklematic standort","wo ist die reinigungsmaschine","sparklematic finden"}},{q="Warum verpackt die Maschine Gegenstände mit einer Schleife?",a="Sie wurde mit typisch gnomischer Verspieltheit programmiert. Selbst nachdem gefährlicher Niederschlag und giftiger Dreck von einem Gegenstand geschrubbt wurden, gestalteten ihre Schöpfer den Abschlusszyklus so, dass das restaurierte Objekt in ein hübsches, sauber verschnürtes Geschenk verpackt wird.",al={"warum geschenkbox","sparklematic verpacktes geschenk","mit schleife verpackt"}},{q="Können Abenteurer der Horde den Sparklematic 5200 nutzen?",a="Ja. Der Sparklematic 5200 ist ein vollautomatischer Apparat, dem Fraktionszugehörigkeiten gleichgültig sind. Solange ein Besucher Münzen und verschmutzte Gegenstände einwirft, führt die Maschine ihren Zyklus aus.",al={"horde sparklematic","kann horde schmutz reinigen","ist sparklematic neutral"}},{q="Kann ich den Sparklematic mehrmals benutzen?",a="Ja. Nach der ersten Nutzung schaltet die Maschine eine wiederholbare Aufgabe frei, die es jedem, der im gesamten Dungeon Schmutzverkrustete Objekte findet, erlaubt, diese immer wieder zu verarbeiten.",al={"ist sparklematic wiederholbar","funkelmatastisch","schmutzverkrustete objekte farmen"}},{q="Was passiert nach dieser Quest?",a="Der Abschluss dieser ersten Reinigung führt direkt zum wiederholbaren Reinigungszyklus Funkelmatastisch, der es Euch ermöglicht, alle weiteren Schmutzverkrusteten Funde zu reinigen, die Ihr bei Euch tragt.",al={"folgequest nach sparklematic","was folgt auf sparklematic 5200"}}},fx={["1a7da75f"]={q="Warum benötigt der Sparklematic 5200 Schmutzverkrustete Objekte?",a="Der Sparklematic 5200 besitzt keine persönlichen Ambitionen – er ist ein automatisiertes Wunderwerk gnomischer Ingenieurskunst, das darauf ausgelegt ist, geborgene Waren zu reinigen und wiederherzustellen. Vor dem Fall von Gnomeregan erbaut, besteht seine programmierte Funktion darin, dicke Schichten radioaktiven Schlamms und Trümmer abzuwaschen und alles, was übrig bleibt, in einem ordentlichen, verpackten Päckchen für seinen Benutzer bereitzustellen.",al={"warum will der sparklematic dies","sparklematic 5200 zweck","warum schmutzverkrustete objekte reinigen"}}},fp="22,285,19.384.0,22.341.0,35.246.0,39.175.0,41.225.0,48.184.0,42.179.0,30.186.0"}
P.entries["quest:2953"] = {n="Funkelmatastisch",s="Tief in den verstrahlten Ruinen von Gnomeregan steht der Sparklematic 5200, ein automatisierter Reinigungsapparat, der bei der Evakuierung der Stadt zurückgelassen wurde. Gegen eine geringe Gebühr von Silber schrubbt diese Maschine mit Nachdruck verwertbare Kuriositäten aus dem Schlamm und radioaktiven Schlick, der die gefallene Hauptstadt bedeckt.",h="Tief in den verstrahlten Ruinen von Gnomeregan steht der Sparklematic 5200, ein automatisierter...",kw={"automatisierung","reinigungsmaschine","reinigung","gnomeregan","schmutzverkrustet","sparklematic"},ang={["profession:Engineering"]="Die Bedienung des Geräts bietet Ingenieuren einen direkten Einblick in robuste gnomische Lösungsmittelzyklen und münzaktivierte Automatisierung.",["race:Gnome"]="Der Sparklematic ist ein Zeugnis gnomischer mechanischer Ausdauer, das zuverlässig inmitten der giftigen Ruinen Eurer Heimat funktioniert."},sec={{t="Automatisierte Wiederherstellung",b="Der Sparklematic 5200 repräsentiert die ausgeklügelte automatisierte Infrastruktur, die die Gnome vor der Trogg-Invasion und dem darauffolgenden radioaktiven Niederschlag in ganz Gnomeregan installiert hatten. Selbst als giftiger Abfall und feindselige Automaten die Korridore füllten, führt dieses Gerät immer noch seine genaue Programmierung aus, sobald es mit drei Silbermünzen und einem schmutzverkrusteten Artefakt versorgt wird."},{t="Wunder aus dem Schlamm",b="Wenn er aktiviert wird, ruckelt der Sparklematic wild, während er das eingelegte Relikt in potenten gnomischen Reinigungslösungsmitteln tränkt und schrubbt. Sobald der Zyklus mit einem fröhlichen Klingeln endet, gibt er eine ordentlich verpackte Schachtel aus, die alles enthält, was unter dem korrosiven Trogg-Schleim und dem giftigen Unrat bewahrt wurde."}},faq={{q="Was ist der Sparklematic 5200?",a="Der Sparklematic 5200 ist ein automatisiertes gnomisches Reinigungsgerät, das sich innerhalb von Gnomeregan befindet. Er entfernt ätzenden Schlamm, Schmutz und radioaktive Überreste von geborgenen Objekten und stellt sie als identifizierbares Bergungsgut wieder her.",al={"sparklematic 5200","was macht die maschine","gnomeregan reiniger"}},{q="Warum verlangt die Maschine Münzen?",a="Der Sparklematic benötigt drei Silbermünzen, um einen Reinigungszyklus zu starten. Der genaue Grund für diese Gebühr wird nicht erklärt.",al={"warum silber bezahlen","sparklematic kosten"}},{q="Welche Arten von Objekten können hineingelegt werden?",a="Die Maschine reinigt speziell schmutzverkrustete Objekte, Relikte, die von gefallenen Troggs, korrumpierten Wachen und verstrahlten Schrecken, die durch die Tunnel von Gnomeregan wandern, geborgen wurden.",al={"schmutzverkrustetes objekt","welche gegenstände kann ich reinigen"}},{q="Ist der Sparklematic sicher vor Strahlung?",a="Während die äußeren Tunnel in radioaktivem Abfall versinken, bleibt der Sparklematic 5200 funktionsfähig und setzt spezielle gnomische Reinigungsmittel ein, um gefährliche äußere Rückstände von eingehenden Objekten zu schrubben.",al={"sparklematic verstrahlt","sparklematic kontamination"}},{q="Können beide Fraktionen den Sparklematic 5200 nutzen?",a="Ja. Der Sparklematic 5200 ist eine vollständig mechanische, automatisierte Installation, die neutral arbeitet und Zahlungen sowie schmutzverkrustete Gegenstände unabhängig von der Zugehörigkeit des Besuchers akzeptiert.",al={"horde sparklematic","wer kann ihn benutzen"}},{q="Wer hat den Sparklematic entwickelt?",a="Der Schöpfer wird nicht genannt. Der Sparklematic ist eine gnomische Reinigungsmaschine, die innerhalb von Gnomeregan immer noch funktioniert.",al={"sparklematic schöpfer","wer hat den sparklematic gebaut"}}},fx={["9d072b2b"]={q="Warum muss der Sparklematic 5200 betrieben werden?",a="Der Sparklematic 5200 ist ein automatisiertes Gnomengerät, das für einen einzigen Zweck entwickelt wurde: das Abschrubben von schwerem, unterirdischem Schlamm und industriellen Ablagerungen von kontaminierter Ausrüstung. Als Maschine hegt er keine großen Ambitionen oder versteckten Absichten; er wartet einfach auf die angemessene Gebühr und Schmutzverkrustete Objekte, um seine Reinigungszyklen zu aktivieren und restaurierte Waren auszugeben.",al={"warum sparklematic betreiben","sparklematic motiv","warum sparklematic 5200 benutzen"}}},fp="24,297,21.356.0,21.304.0,30.213.0,34.121.0,40.173.0,40.206.0,44.186.0,30.108.0"}
P.entries["quest:296"] = {n="Ormers Rache",s="Ormers Rache ist der Höhepunkt von Ormer Eisenzopfs Feldzug, um die an der Whelgar Excavation Site abgeschlachteten Zwergenausgräber zu rächen. Überzeugt davon, dass eine listige Bestie namens Sarltooth den wilden Raptorenangriff anführte, schickt Ormer einen Abenteurer los, um den Rudelführer zu töten und dessen Klaue als Beweis einzufordern.",h="Ormers Rache ist der Höhepunkt von Ormer Eisenzopfs Feldzug, um die an der Whelgar Excavation Site...",kw={"explorer's league","ormer eisenzopf","raptoren","sarltooth","klaue","sumpfland","whelgar excavation site"},ang={["class:Hunter"]="Sarltooth verkörpert eines der Spitzenraubtiere des Sumpflands und erfordert geschickte Fährtenleserkunst, um den Felsgrat zu erklimmen und den Rudelführer zur Strecke zu bringen.",["faction:Alliance"]="Die Sicherung von Zwergenexpeditionen in den Marschen stellt sicher, dass die Stützpunkte der Allianz zwischen Eisenschmiede und den nördlichen Ländern intakt bleiben.",["race:Dwarf"]="Für Zwerge ist die Rache für das hingemetzelte Team der Explorer's League an der Whelgar Excavation Site eine Frage der Ehre gegenüber König Magnis gefallenen Untertanen."},sec={{t="Ein Schlag gegen den Rudelführer",b="Nach dem Massaker an den Ausgräbern der Explorer's League an der Whelgar Excavation Site beobachtete Ormer Eisenzopf von seinem Felsgrat aus das Gewimmel der Raptoren und erspähte eine Bestie, die den Rest überragte. Dieser besonders große und bösartige Raptor, bekannt als Sarltooth, hockte über den Ausgrabungsstätten und lenkte oder führte das Rudel an, das die Zwerge vertrieb. Für Ormer war die Bestie nicht bloß ein wildes Tier, sondern der Anstifter eines Angriffs auf Untertanen von König Magni Bronzebart."},{t="Gerechtigkeit im Sumpfland",b="Ormer fordert die Todesstrafe für das Massaker und weist Abenteurer an, die hoch gelegenen Pfade der Ausgrabungswände zu erklimmen und Sarltooth ein Ende zu setzen. Durch das Bergen einer der gewaltigen Klauen der Bestie werden die gefallenen Arbeiter gerächt, was eine unmissverständliche Botschaft durch die Marschen sendet, dass Angriffe auf Zwergenexpeditionen nicht unbeantwortet bleiben."}},faq={{q="Wer ist Sarltooth?",a="Sarltooth ist ein großer, bedrohlicher Raptor, der das Rudel anführt, welches die Whelgar Excavation Site im Sumpfland besetzt hält. Ormer Eisenzopf glaubt, dass er den Angriff leitete, dem die Zwergenausgräber zum Opfer fielen.",al={"was ist sarltooth","wer ist der raptorboss","sarltooth lore"}},{q="Wo befindet sich Sarltooth?",a="Sarltooth streift entlang eines erhöhten Pfades umher, der an der westlichen Wand in der nordwestlichen Ecke der Whelgar Excavation Site emporführt.",al={"sarltooth finden","wo spawnt sarltooth","sarltooth weg"}},{q="Warum will Ormer Sarltooth tot sehen, anstatt ihn nur zu vertreiben?",a="Ormer betrachtet den Raptorenangriff als ein direktes Verbrechen an den Untertanen von König Magni. Da unschuldige Zwergenarbeiter bei ihrer Arbeit ihr Leben verloren, glaubt Ormer, dass nur der Tod das Andenken der Gefallenen sühnen kann.",al={"ormers rache grund","warum sarltooth toeten"}},{q="Welchen Beweis verlangt Ormer?",a="Ormer verlangt eine von Sarltooths Klauen, um sicherzustellen, dass das gewaltige Raubtier wahrhaftig erlegt wurde.",al={"sarltooth beweis","sarltooth klaue"}},{q="Wer waren die Opfer an der Ausgrabungsstätte?",a="Zwergische Archäologen und Arbeiter, die von der Explorer's League entsandt wurden, um Titanenartefakte auszugraben, wurden überrumpelt und niedergemetzelt, als Raptorenrudel die Ausgrabung überrannten.",al={"wer starb bei whelgar","opfer der ausgrabungsstaette"}},{q="Sichert der Tod von Sarltooth die Ausgrabungsstätte?",a="Obwohl die Tötung von Sarltooth die tödlichste Bedrohung des Rudels beseitigt und Vergeltung für die Gefallenen bringt, wimmelt es in den Gräben immer noch von Raptoren, sodass die Stätte gefährlich und weitgehend verlassen bleibt.",al={"ist whelgar jetzt sicher","hat ormer gewonnen"}}},fp="15,307,27.456.0,23.340.0,17.196.0,27.123.0,68.210.0,30.97.0,44.165.0,50.187.0"}
P.entries["quest:2962"] = {n="Das einzige Heilmittel ist mehr grünes Leuchten",s="Nach früheren unschlüssigen Tests an Troggs an der Oberfläche beauftragt Ozzie Wechselvolt Abenteurer damit, reinen, hochwirksamen radioaktiven Niederschlag direkt aus dem Inneren von Gnomeregan zu beschaffen. Sein letztendliches Ziel ist es, die giftige Strahlung zu verstehen, die sein Volk verwüstet hat, und ein Heilmittel für die betroffenen Lepragrome zusammenzubrauen.",h="Nach früheren unschlüssigen Tests an Troggs an der Oberfläche beauftragt Ozzie Wechselvolt Abenteurer damit...",kw={"gnogaine","gnomeregan","hall of gears","kharanos","lepragnom","ozzie wechselvolt","strahlung","radioaktiver niederschlag"},ang={["faction:Alliance"]="Um Dun Morogh zu stabilisieren und Gnomeregan zurückzuerobern, muss man die tödlichen Gefahren verstehen, die noch immer vor der Haustür von Eisenschmiede lauern.",["profession:Engineering"]="Die flüchtige Natur der Strahlungseindämmung erfordert eine robuste Bleiabschirmung und präzise Instrumente, was die verheerenden Folgen veranschaulicht, wenn die Ingenieurskunst versagt.",["race:Gnome"]="Jeder Gnom trägt die Trauer über seine verlorene Heimat in sich. Ozzie dabei zu helfen, zu testen, ob die schreckliche Mutation rückgängig gemacht werden kann, trifft den Kern ihrer Hoffnung, ihre gefallenen Artgenossen zu erlösen."},sec={{t="Eine reine Probe",b="Ozzie Wechselvolts vorläufige Versuche außerhalb der Stadt waren ein Fehlschlag. Die verstrahlten Troggs, die Dun Morogh durchstreifen, trugen unzureichende und unreine Rückstände in sich, was sein Labor in Kharanos mit mehr Fragen als Antworten zurückließ. Um ein echtes Heilmittel für Lepragrome zu entwickeln, kommt Togglevolt zu dem Schluss, dass die wissenschaftliche Integrität eine frische, konzentrierte Probe direkt aus den Tiefen des giftigen Bauchs der Stadt verlangt."},{t="Direkt von der Quelle",b="Niederschlag von ausreichender Wirksamkeit zu beschaffen bedeutet, sich in Gnomeregan selbst hineinzuwagen. In den unteren Tiefen rund um die Hall of Gears und die Clean Zone wimmelt es von verstrahlten Schrecken, Lauern und Schleimen, die durch das verhängnisvolle Ablassen von radioaktivem Müll entstanden sind. Diesen instabilen Schleim in eine schwere Bleiphiole zu extrahieren, ist gefährliche Arbeit: Der Niederschlag zerfällt rasch, was die Eindämmung extrem unbeständig und zeitkritisch macht."}},faq={{q="Warum benötigt Ozzie radioaktiven Niederschlag?",a="Ozzie Wechselvolt versucht, ein Heilmittel für die Lepragrome herzustellen, deren Verstand und Körper durch den Niederschlag ruiniert wurden, der beim Fall von Gnomeregan freigesetzt wurde. Er glaubt, dass das Verständnis des unverdünnten Giftes der erste Schritt dazu ist, seine schrecklichen Auswirkungen umzukehren.",al={"ozzie wechselvolt heilmittel","warum grünes leuchten holen","heilmittel für lepragnome"}},{q="Wo findet der Spieler den Niederschlag?",a="Der Niederschlag muss von lebenden verstrahlten Schrecken, Lauern und Schleimen in den Tiefen von Gnomeregan gesammelt werden, insbesondere in den unteren Ebenen rund um die Hall of Gears und hinter der Clean Zone.",al={"wo gibt es hochwirksamen radioaktiven niederschlag","gnomeregan niederschlag fundort"}},{q="Warum wurden die Proben der Oberflächentroggs abgelehnt?",a="Die Troggs, die außerhalb von Gnomeregan umherwanderten, trugen nicht genug konzentrierte Kontamination in sich. Ihre Proben waren zu schwach und unrein, um als verlässliches Forschungsmaterial für Ozzies Heilmittelexperimente zu dienen.",al={"warum keine troggs","was war falsch an gnogaine"}},{q="Warum unterliegt der Niederschlag einem Zeitlimit?",a="Der Niederschlag ist hochgradig instabil und aktiv. Selbst im Inneren einer bleiernen Sammelphiole baut sich die flüchtige Strahlung rasch ab, was Forscher dazu zwingt, sie in das Labor in Kharanos zurückzubringen, bevor sie ihre Wirksamkeit verliert.",al={"warum verfällt niederschlag","niederschlag dauer"}},{q="Wer sind die Lepragrome, denen Ozzie zu helfen hofft?",a="Lepragrome sind ehemalige Bürger von Gnomeregan, die im Inneren gefangen waren, als die Strahlungsventile geöffnet wurden, um die Troggs zu bekämpfen. Anstatt zu sterben, mutierten sie zu kranken, wahnsinnigen Überlebenden, die ihren einstigen Artgenossen feindlich gesinnt sind.",al={"lepragnome lore","was sind lepragnome"}},{q="Wer vergibt diese Aufgabe?",a="Die Quest wird von Ozzie Wechselvolt vergeben, einem Gnomforscher, der in Kharanos in Dun Morogh stationiert ist und sich der Behebung der Folgen von Gnomeregans Katastrophe widmet.",al={"wer gibt die quest","ozzie wechselvolt aufenthaltsort"}}},fx={a4e93100={q="Wofür wird die Hochwirksame radioaktive Ablagerung verwendet?",a="Ozzie Wechselvolt benötigt die konzentrierte Ablagerung, um die intensive Strahlung zu untersuchen, die Gnomeregan verschlang. Sein ultimatives Ziel ist es, ein Heilmittel für die Lepragnome zu finden, seine verwandten Brüder, deren Geist und Körper durch die Katastrophe verzerrt wurden. Da frühere Oberflächenproben von umherwandernden Troggs sich als zu schwach und kontaminiert erwiesen, um verwertbare wissenschaftliche Ergebnisse zu liefern, benötigt er wirksame, unverdünnte Strahlung direkt von den Kreaturen im Inneren der zerstörten Stadt.",al={"wofür ist radioaktive ablagerung","nutzen hochwirksame ablagerung","zweck ablagerung ozzie"}},["089f8395"]={q="Welche Kreaturen jagt Ihr im Inneren von Gnomeregan?",a="Ihr werdet ausgesandt, um Proben von den verstrahlten Schlämmen, Lurkern und Schrecken zu sammeln, die in Gnomeregan vor sich hin faulen. Diese elenden Schlicke und mutierten Wesen bildeten sich direkt infolge des toxischen Ausstoßes, der während des Falls der Stadt freigesetzt wurde, und absorbierten massive Konzentrationen an rohem radioaktivem Abfall. Da sie die Ablagerungen in ihrem reinsten, aktivsten Zustand verkörpern, liefert das Extrahieren von Rückständen direkt aus ihnen die unverdünnte Wirksamkeit, die Ozzie für seine Forschung benötigt.",al={"was sind verstrahlte schlämme","wen töte ich für ablagerungen","gnomeregan ablagerung kreaturen"}}},fp="32,311,13.392.0,21.398.0,40.263.0,39.202.0,44.196.0,35.217.0,45.219.0,22.174.0"}
P.entries["quest:298"] = {n="Bericht über den Fortschritt der Ausgrabungen",s="Bericht über den Fortschritt der Ausgrabungen ist ein Botengang der Allianz von den Ausgrabungsstätten in Loch Modan zurück in die Stadt. Ausgrabungsleiter Eisenband beauftragt einen Abenteurer damit, seine neuesten Ausgrabungsberichte und eine Erneuerung seiner Sprengstoffbestellungen zu Jern Hornhelm in Thelsamar zu bringen.",h="Bericht über den Fortschritt der Ausgrabungen ist ein Botengang der Allianz von den Ausgrabungsstätten in...",kw={"sprengpulver","bericht über den fortschritt der ausgrabungen","explorers' league","jern hornhelm","loch modan","ausgrabungsleiter eisenband","thelsamar","trogg"},ang={["faction:Alliance"]="Das Offenhalten der Nachschublinien zwischen Thelsamar und abgelegenen Außenposten sichert die Vormachtstellung der Allianz in den Bergen von Loch Modan.",["profession:Mining"]="Bergleute verstehen nur zu gut die Notwendigkeit von zuverlässigem Sprengpulver, wenn es darum geht, dichtes Grundgestein zu brechen und Tunnel in uralte Schichten zu treiben.",["race:Dwarf"]="Für zwergische Abenteurer bedeutet die Unterstützung von Ironband, die unverzichtbaren historischen Bestrebungen der Explorers' League aufrechtzuerhalten und Artverwandte vor den Überfällen gefräßiger Troggs zu schützen."},sec={{t="Eine Depesche nach Thelsamar",b="Die archäologischen Bemühungen von Ausgrabungsleiter Eisenband in Loch Modan erfordern ständige logistische Unterstützung aus den nahe gelegenen Siedlungen. Die Freilegung uralter Titanenrelikte ist anstrengende Arbeit, die Spitzhacken, Arbeitskräfte und reichliche Mengen an Sprengpulver erfordert, um hartnäckiges Grundgestein zu durchbrechen. Ironband verlässt sich auf Läufer, die seine regelmäßigen Lageberichte und Materialbestellungen an Jern Hornhelm übermitteln, den örtlichen Ansprechpartner der Expedition in Thelsamar."},{t="Vermisste Munition",b="Nach Erhalt von Ironbands Depesche erfährt Hornhelm, dass die Ausgrabungsstätte schweren Angriffen durch aggressive Troggs ausgesetzt ist. Obwohl Hornhelm zustimmt, dass die Bereitstellung von Pulver zum Zerschlagen von Stein oder zum Sprengen von Troggs eine lohnende Aufgabe ist, weckt Ironbands erneute Nachbestellung sofortige Besorgnis. Hornhelm hatte bereits Wochen zuvor eine beträchtliche Lieferung Sprengpulver losgeschickt, was ihn rätseln lässt, welches Schicksal die vermisste Munition auf den schroffen Bergpfaden ereilte."}},faq={{q="Wer übergibt Euch diesen Bericht?",a="Ausgrabungsleiter Eisenband übergibt Euch den Bericht bei Ironbands Ausgrabungsstätte, die in den südöstlichen Hügeln von Loch Modan liegt. Er beaufsichtigt die dort stattfindenden archäologischen Ausgrabungen.",al={"questgeber","wer startet bericht über den fortschritt der ausgrabungen","ironband standort"}},{q="Wer ist Jern Hornhelm?",a="Jern Hornhelm ist ein zwergischer Ansprechpartner der Explorers' League, der in Thelsamar stationiert ist. Er koordiniert die lokale Logistik und den Nachschub für archäologische Expeditionen in ganz Loch Modan.",al={"wo ist jern hornhelm","wer ist der empfänger","thelsamar ansprechpartner"}},{q="Warum benötigt Ausgrabungsleiter Eisenband mehr Sprengpulver?",a="Ironband benötigt vordergründig Sprengpulver, um massives Gestein für seine Ausgrabung freizulegen. Die Ausgrabungsstätte wird jedoch von feindseligen Troggs belagert, wodurch Sprengstoffe für die Verteidigung ebenso entscheidend sind.",al={"warum sprengpulver","wofür will ironband pulver"}},{q="Was geschah mit der vorherigen Pulverlieferung?",a="Jern Hornhelm schickte vor Wochen eine Lieferung Sprengpulver ab, die nie an der Ausgrabung ankam. Ihr mysteriöses Verschwinden deutet auf Probleme entlang der Versorgungsrouten hin, die Thelsamar mit den abgelegenen Stätten verbinden.",al={"wohin ist das pulver verschwunden","vermisstes sprengpulver"}},{q="Was folgt nach der Übergabe des Fortschrittsberichts?",a="Nachdem Hornhelm Ironbands missliche Lage und das ungelöste Problem des vermissten Pulvers geprüft hat, weist er Euch an, Vorgesetzten in Eisenschmiede über den Status der Expedition Bericht zu erstatten.",al={"folgequest","was kommt danach","meldung in eisenschmiede"}},{q="Warum greifen Troggs die Ausgrabungsstätte an?",a="Zwergische Ausgrabungen legen häufig unterirdische Kammern frei und stören die Höhlen der Troggs. Die Kreaturen betrachten die Bergleute als Eindringlinge in ihr Territorium und stürzen sich gewaltsam auf jeden, der in die Erde gräbt.",al={"trogg angriffsgrund","warum troggs ironband hassen"}}},fx={["0b7d15ff"]={q="Warum benötigt Ausgrabungsleiter Eisenband Euch, um den Bericht zu überbringen?",a="Ausgrabungsleiter Eisenband und seine Grabungshelfer sind an der Ausgrabungsstätte durch unerbittliche Angriffe der Troggs festgesetzt. Da seine Crew vollauf damit beschäftigt ist, ihre archäologische Arbeit zu verteidigen und ums Überleben zu kämpfen, kann Eisenband niemanden entbehren, um den weiten Weg zurück nach Thelsamar zurückzulegen. Ein außenstehender Reisender wie Ihr bietet einen schnellen, zuverlässigen Boten, um seine Worte durch die gefährliche Wildnis zu tragen.",al={"warum schickt er mich","warum geht er nicht selbst","warum bericht überbringen"}}},fp="26,257,23.440.0,17.437.1,29.181.0,21.188.0,51.179.0,49.205.0,50.177.0,45.192.0"}
P.entries["quest:2985"] = {n="Ruf des Wassers",s="Call of Water markiert den Beginn der Zwiesprache eines Schamanen mit dem fließenden Element der Heilung und Anpassungsfähigkeit. Nachdem ein Initiat seine Meisterschaft über Erde und Feuer bereits unter Beweis gestellt hat, wird er von Searn Feuerwächter in Orgrimmar angewiesen, die Einsiedlerin Islen Wasserdeuter an der Ostküste des Brachlands aufzusuchen.",h="Call of Water markiert den Beginn der Zwiesprache eines Schamanen mit dem fließenden Element der Heilung und...",kw={"call of water","islen wasserdeuter","orgrimmar","ratschet","searn feuerwächter","schamane","der südstrom","brachland","wassertotem"},ang={["class:Shaman"]="Dieser Ruf markiert den entscheidenden Übergang vom zerstörerischen Feuer und der standhaften Erde hin zu den wiederherstellenden Kräften des Wassers und schaltet das spirituelle Leitmedium frei, das zum Wirken von Heiltotems erforderlich ist.",["faction:Horde"]="Schamanen der Horde in ganz Kalimdor – ob Orc, Troll oder Tauren – werden zu Islen Wasserdeuter an die Küste des Brachlands geschickt, um ihre wässrige Zwiesprache aufzunehmen."},sec={{t="Ein Wandel in den Elementen",b="Die Ausbildung eines Schamanen verlangt nach Gleichgewicht. Nachdem sie die unerschütterliche Widerstandskraft der Erde erlernt und die wilde Wildheit des Feuers ertragen haben, werden Initiaten zur fließenden, anpassungsfähigen Natur des Wassers gerufen. In Orgrimmar beurteilt der Trollschamane Searn Feuerwächter das spirituelle Wachstum seiner Schüler. Wenn ein Initiat seine Beherrschung der Flamme bewiesen hat, ohne von ihr verzehrt zu werden, erkennt Searn, dass sein Geist gestählt genug ist, um die Lehren des Wassers zu suchen."},{t="Die Einsiedlerin der Händlerküste",b="Um die Geheimnisse der Wassergeister zu erlernen, muss der Schamane entlang Des Südstroms nach Süden in das Brachland reisen und weiter nach Osten zur Küste vordringen, kurz hinter dem geschäftigen Goblinhafen Ratschet. Dort, am Meeresufer nahe dem Kadaver eines riesigen Hais, verweilt Islen Wasserdeuter. Anders als die zurückgezogenen Lehrer im Tal der Geister lebt Islen dort, wo die Salzwogen unerbittlich auf das Land treffen, und dient der Horde als wichtigste Führerin für die Zwiesprache mit dem Wasser."}},faq={{q="Wer vergibt diese Quest?",a="Searn Feuerwächter, ein Schamanenlehrer der Trolle, der in Grommash Hold in Orgrimmar weilt, vergibt diese Aufgabe, sobald Ihr Eure Beherrschung über Feuer und Erde bewiesen habt.",al={"questgeber","wer startet call of water","searn feuerwächter"}},{q="Wo kann ich Islen Wasserdeuter finden?",a="Islen Wasserdeuter lebt an der Ostküste des Brachlands, südlich von Ratschet. Folgt Dem Südstrom südwärts aus Durotar hinaus, haltet Euch hinter Ratschet auf das Ufer zu und sucht nach ihrem Lager, das durch einen großen gestrandeten Hai markiert ist.",al={"wo ist islen","standort von islen","wie man islen wasserdeuter findet"}},{q="Warum muss ein Schamane die Elemente in einer bestimmten Reihenfolge erlernen?",a="Die schamanische Tradition erfordert es von einem Initiaten, schrittweise ein spirituelles Gleichgewicht aufzubauen. Durch die Erde geerdet und durch das Feuer gestählt, wird die Seele beständig genug, um der fließenden, wandelbaren Reinheit des Wassers zu widerstehen, ohne fortgespült zu werden.",al={"elementreihenfolge","warum wasser nach feuer","schamanenfortschritt"}},{q="Ist diese Quest für andere Klassen verfügbar?",a="Nein. Die Quests von Call of Water sind ausschließlich Schamanen vorbehalten, die danach streben, die Gunst der Wassergeister zu erlangen und ihr Wassertotem zu manifestieren.",al={"können nicht-schamanen dies tun","ist call of water nur für schamanen"}},{q="Nach welchem Orientierungspunkt sollte ich suchen, wenn ich nach Islen suche?",a="Searn rät Reisenden, entlang der Küste südlich von Ratschet nach einem gewaltigen gestrandeten Hai Ausschau zu halten. Islen hat ihre Behausung direkt daneben errichtet.",al={"hai wahrzeichen","wie man islens lager entdeckt","islens küste"}},{q="Was geschieht nach dem Erreichen von Islen Wasserdeuter?",a="Das Gespräch mit Islen leitet die wahren Prüfungen des Wassers ein und verlangt vom Schamanen, durch Kalimdor und Lordaeron zu reisen, um reine Wassertropfen zu sammeln und Geister zu konfrontieren, bevor er das Totem erlangt.",al={"nächster schritt","was tut islen","nach call of water"}}},fx={["67ae3245"]={q="Warum schickt Searn Feuerwächter Euch zu Islen Wasserdeuter?",a="Searn Feuerwächter erkennt Eure Meisterschaft über die Flamme und sieht, dass Eure spirituelle Reise als Schamane weitergehen muss. Er kann Euch die Wege des Wassers nicht selbst lehren – das Meistern dieses fließenden, reinen Elements erfordert die Anleitung von Islen Wasserdeuter, einer hingebungsvollen Ältesten, die an der Küste des Brachlands lebt. Searn schickt Euch weiter, damit Ihr mit dem Wasser kommunizieren und Eure Bindung zu den Elementen erweitern könnt.",al={"warum will searn dies erledigt haben","searn feuerwächter motiv","warum zu islen schicken"}}},fp="13,300,23.453.0,33.465.0,21.151.0,33.224.0,57.226.0,41.132.0,57.142.0,44.189.1"}
P.entries["quest:299"] = {n="Enthüllung der Vergangenheit",s="Ausgrabungsleiter Whelgar beauftragt Abenteurer damit, sich in die überrannte Whelgars Ausgrabungsstätte im Sumpfland zu wagen, um vier fehlende Teile einer uralten Tafel namens Goazstein zu bergen, damit ihre geheimnisvollen Inschriften übersetzt werden können.",h="Ausgrabungsleiter Whelgar beauftragt Abenteurer damit, sich in die überrannte Whelgars Ausgrabungsstätte im...",kw={"ados","goazstein","golm","modr","neru","ausgrabungsleiter whelgar","titanen","enthüllung der vergangenheit","sumpfland","whelgars ausgrabungsstätte"},ang={["faction:Alliance"]="Die Unterstützung der Ausgrabungen der Liga im gesamten Sumpfland stärkt die Präsenz der Allianz und sichert wertvolles Wissen, bevor es in wilde oder feindliche Hände fällt.",["race:Dwarf"]="Die Forscherliga betrachtet jedes geborgene Relikt als entscheidend für die Ergründung der zwergischen Ursprünge, und die Titaneninschriften auf dem Goazstein knüpfen direkt an dieses uralte Erbe an."},sec={{t="Der zerbrochene Stein",b="Bevor Raptoren die Ausgrabungsstätte im Sumpfland überrannten, legte Ausgrabungsleiter Whelgar ein bedeutendes Relikt frei: den Goazstein. Erste Versuche, seine uralte Schrift zu entziffern, brachten bruchstückhafte Hinweise auf einen „göttlichen Plan“ und eine „dem Untergang geweihte Prophezeiung“ hervor. Unglücklicherweise brachen entscheidende Abschnitte an vier verschiedenen Stellen ab, wodurch wichtige Passagen im fossilienübersäten Erdreich verstreut wurden."},{t="Mutprobe an der Ausgrabungsstätte",b="Um den Stein wieder zusammenzusetzen, muss das von Raptoren wimmelnde Ausgrabungsgelände nach den vier fehlenden Fragmenten durchkämmt werden: Ados, Modr, Golm und Neru. Sie liegen in lockerem Erdreich und unter halb freigelegten Relikten vergraben, die von aggressiven Razormaws und Scytheclaws bewacht werden, sodass das Finden jedes Teils den Kampf gegen die Spitzenprädatoren des Marschlandes erfordert."},{t="Gekettet unter dem Land",b="Wieder vereint offenbart der Goazstein die feine und rätselhafte Sprache der Titanen. Bei der Übersetzung der neu zusammengesetzten Glyphen stößt Whelgar auf eine schauerliche Inschrift: „Alte Götter... Gekettet unter dem Land.“ Weit mehr als eine bloße historische Kuriosität deutet die Tafel auf titanische Kämpfe aus der Frühzeit der Welt und auf finstere Übel hin, die unter der Kruste von Azeroth begraben liegen."}},faq={{q="Was ist der Goazstein?",a="Der Goazstein ist ein uraltes Titanenrelikt, das von Ausgrabungsleiter Whelgar in der Ausgrabungsstätte im Sumpfland entdeckt wurde. Er enthält kryptische Inschriften über die kosmische Geschichte, einen göttlichen Plan und uralte Wesenheiten, die tief unter der Erde gebunden sind.",al={"goazstein lore","was ist die goaz-tafel","tafelfragmente sumpfland"}},{q="Wer vergibt die Quest Enthüllung der Vergangenheit?",a="Ausgrabungsleiter Whelgar bietet die Quest von seinem Aussichtspunkt über Whelgars Ausgrabungsstätte in den südlichen Hügeln des Sumpflands an, nachdem er von wilden Raptoren von seiner Grabung vertrieben wurde.",al={"wer startet enthüllung der vergangenheit","wo gibt es enthüllung der vergangenheit"}},{q="Welche Fragmente werden benötigt, um die Tafel zu vervollständigen?",a="Ihr benötigt vier bestimmte Steinfragmente: Ados, Modr, Golm und Neru. Sie sind in lockeren Erdhaufen und uralten Urnen auf dem von Raptoren heimgesuchten Steinbruchboden verstreut.",al={"welche fragmente","tafelbruchstücke namen","ados modr golm neru"}},{q="Warum kann Ausgrabungsleiter Whelgar die Fragmente nicht selbst bergen?",a="Whelgar ist ein betagter Zwergengelehrter. Als bösartige Raptoren plötzlich den Steinbruch stürmten und überrannten, war er zum Rückzug gezwungen und besitzt nicht die körperliche Kraft, um sich allein durch die Rudel zu kämpfen.",al={"warum holt whelgar die steine nicht","warum bittet whelgar euch"}},{q="Was enthüllen die übersetzten Titanenglyphen?",a="Sobald die vier fehlenden Teile eingesetzt sind, entziffert Whelgar die Titanenschrift und liest die Worte: „Alte Götter... Gekettet unter dem Land.“ Dies deutet auf die uralten kosmischen Wesenheiten hin, die während der Erschaffung Azeroths weggesperrt wurden.",al={"was steht auf dem goazstein","titanen übersetzung sumpfland","alte götter gekettet unter dem land"}},{q="Hängt diese Quest mit anderen nahegelegenen Expeditionen zusammen?",a="Ja. Sie ergänzt direkt Ormer Eisenzopfs Questreihe Ormers Rache, die Abenteurer damit beauftragt, die Raptorenpopulation im selben Steinbruch auszudünnen.",al={"quests nahe ausgrabungsstätte","ormer eisenzopf verbindung","ormers rache verknüpfung"}}},fx={["2fe7ef8c"]={q="Warum möchte Ausgrabungsleiter Whelgar, dass die Tafelfragmente geborgen werden?",a="Ausgrabungsleiter Whelgar entdeckte ein massives Relikt, bekannt als Goazstein, kurz bevor Raptoren die Ausgrabungsstätte überrannten. Die übersetzten Teile seiner Titanenschrift sprechen düster von einem 'göttlichen Plan' und einer 'verhängnisvollen Prophezeiung', doch die Inschrift bricht abrupt in vier fehlenden Abschnitten ab. In der Befürchtung, dass die Zeit knapp wird, ist Whelgar verzweifelt darauf bedacht, die gesamte Tafel wieder zusammenzusetzen, damit er den Rest der Nachricht entziffern und die Geheimnisse aufdecken kann, die unter der Ausgrabung begraben liegen.",al={"whelgar motiv","warum fragmente finden","warum braucht whelgar fragmente"}},f38df7d0={q="Was sind die Ados-, Modr-, Golm- und Neru-Fragmente?",a="Die Ados-, Modr-, Golm- und Neru-Fragmente sind die vier fehlenden Stücke, die vom Goazstein abgebrochen sind. Jedes Fragment enthält einen Abschnitt alter Titanenschrift, der benötigt wird, um die Inschrift zu vervollständigen. Sobald sie wieder in den Hauptstein eingepasst sind, ermöglichen sie es Ausgrabungsleiter Whelgar, den Text fertig zu übersetzen und offenbaren bedrohliche Passagen über uralte Wesen, die unter der Erde angekettet sind.",al={"was sind die fragmente","ados modr golm neru","bedeutung tafelfragmente"}}},fp="19,236,16.363.0,20.321.0,24.360.1,23.226.1,40.190.0,49.173.0,59.192.0,43.229.1,54.165.0"}
P.entries["quest:2996"] = {n="Die Suche nach Strahad",s="Die Suche nach Strahad ist ein wesentlicher Übergangsritus für Hexenmeister der Horde, die ihren grundlegenden Beschwörungskünsten entwachsen sind. Nach Anweisung von Gan'rul Blutauge in den schattigen Spalten von Orgrimmar müssen die Praktizierenden nach Süden nach Ratschet reisen, um unter einem abtrünnigen menschlichen Beschwörer zu lernen.",h="Die Suche nach Strahad ist ein wesentlicher Übergangsritus für Hexenmeister der Horde, die ihren...",kw={"brachland","die kluft der schatten","teufelsjaeger quest","gan'rul blutauge","ratschet","die suche nach strahad","strahad farsan","foliant der kabale"},ang={["class:Warlock"]="Diese Quest markiert Euren Übergang zur Beherrschung dämonischer Wesenheiten mittleren Ranges und stellt Eure Bereitschaft auf die Probe, den magiefressenden Teufelsjäger zu unterwerfen.",["faction:Horde"]="Die Bereitschaft der Meister der Horde, Lehrlinge zu einem einsamen Menschen zu schicken, zeigt, wie unabhängig Hexenzirkel von der formellen Diplomatie des Kriegshäuptlings agieren."},sec={{t="Das Verlassen der Schatten von Orgrimmar",b="In den dunklen Felsspalten der Kluft der Schatten leitet der orkische Hexenmeisterlehrer Gan'rul Blutauge junge Praktizierende in der tückischen Kunst an, den Nether zu befehligen. Schließlich erreicht ein Hexenmeisterlehrling eine Schwelle, an der die Stammesunterweisung nicht mehr ausreicht. Gan'rul erkennt an, dass unbeständigere Entitäten eine spezialisierte Ausbildung erfordern, und schickt seine Schüler vor die Tore der Stadt zu einer Gestalt, die eine tiefere Beherrschung der dunklen Arkana besitzt."},{t="Ein unkonventionelles Bündnis",b="Der von Gan'rul auserwählte Lehrmeister ist Strahad Farsan, ein menschlicher Zauberer, der in einem abgelegenen Turm mit Blick auf den Goblinhafen Ratschet haust. Trotz des anhaltenden Hasses zwischen der Horde und der Menschheit existieren Hexenmeister in einer Sphäre jenseits herkömmlicher Fraktionstreue. Macht, Disziplin und rituelles Wissen stehen über der Abstammung, und Strahad schert sich weit mehr um den inneren Hass und die Eignung eines Lehrlings zur Unterwerfung als um dessen Hautfarbe."}},faq={{q="Warum schickt mich ein Orc-Hexenmeister zu einem Menschen?",a="Hexenmeister teilen eine pragmatische Philosophie, die dunkles Wissen über völkische Loyalitäten stellt. Gan'rul Blutauge erkennt an, dass Strahad Farsan über seltene und eindrucksvolle Fachkenntnisse in fortgeschrittener Dämonologie verfügt. Beim Streben nach gefährlichen Beschwörungen wiegt das Können eines Lehrmeisters weit schwerer als Fraktionsgrenzen.",al={"warum von mensch lernen","strahad menschlicher hexenmeister","warum strahad"}},{q="Wo finde ich Strahad Farsan?",a="Strahad Farsan verweilt auf den hohen Klippen direkt über dem Goblinhafen Ratschet im Brachland und steht vor seinem persönlichen Turm über den belebten Docks.",al={"strahad aufenthaltsort","wo ist strahad","strahad turm ratschet"}},{q="Welche Macht lehrt Strahad?",a="Strahad leitet Hexenmeister durch die komplexen Rituale an, die erforderlich sind, um einen Teufelsjäger zu binden – einen unersättlichen, magiefressenden Dämon des Wirbelnden Nethers. Seine Lektionen tauchen tief in okkulte Schriften ein, bevor Eure Fähigkeit auf die Probe gestellt wird, die Bestie zu versklaven.",al={"was schaltet strahad frei","was bekommt man von strahad","die suche nach strahad belohnung"}},{q="Wer ist Gan'rul Blutauge?",a="Gan'rul Blutauge ist ein bedeutender Lehrmeister der Orc-Hexenmeister in der Kluft der Schatten unter Orgrimmar. Er bildet aufstrebende Hexenmeister der Horde in den Grundlagen der Teufelsmagie und der Beschwörung niederer Diener aus.",al={"wer ist ganrul","ganrul bloodeye","orgrimmar hexenmeisterlehrer"}},{q="Gibt es einen anderen Weg, diese Quest zu beginnen?",a="Ja. Hexenmeister der Verlassenen erhalten eine parallele Vorladung aus dem Magieviertel in Unterstadt, die sie zu genau demselben menschlichen Lehrmeister oberhalb von Ratschet führt.",al={"die suche nach strahad unterstadt","verlassene die suche nach strahad","unterstadt version"}},{q="Stellt Ratschet eine Gefahr für Hexenmeister der Horde dar?",a="Ratschet wird vom Steamwheedle-Kartell betrieben und dient als streng neutraler Hafen. Solange Ihr den Frieden wahrt und keine Mitreisenden innerhalb der Stadtgrenzen angreift, lassen Euch die Schläger der Goblins in Ruhe.",al={"ist ratschet sicher","ratschet wachen feindlich","neutraler hafen"}}},fx={d843591e={q="Warum schickt Gan'rul Blutauge Euch zu Strahad?",a="Gan'rul Blutauge erkennt, dass Eure dunklen Talente seinem eigenen Unterricht in Orgrimmar entwachsen sind. Um auf dem Pfad der Dämonologie weiter voranzuschreiten und mächtigere Beschwörungen zu meistern, benötigt Ihr esoterisches Wissen, das nur Strahad Farsan besitzt. Gan'rul legt rassistische Vorurteile beiseite, um sicherzustellen, dass Eure Meisterschaft vertieft wird.",al={"warum zu strahad schicken","gan'rul blutauge motiv","warum strahad aufsuchen"}}},fp="15,266,32.451.0,22.438.0,44.292.0,32.170.0,30.232.1,24.200.0,41.155.0,47.211.0"}
P.entries["quest:2997"] = {n="Foliant der Offenbarung",s="Der Foliant der Offenbarung ist eine einführende Vorladung, die junge Zwergenpaladine von ihren Feldeinsätzen in Dun Morogh in die Bergstadt Eisenschmiede ruft. Entsandt von Azar Hammerkraft, wird der Initiant angewiesen, bei Tiza Kriegshammer hoch in der Hall of Mysteries Rat zu suchen. Es markiert den formellen Beginn der tiefergehenden Prüfungen eines Paladins im Dienste des Heiligen Lichts.",h="Der Foliant der Offenbarung ist eine einführende Vorladung, die junge Zwergenpaladine von ihren Feldeinsätzen...",kw={"azar hammerkraft","dun morogh","hall of mysteries","heiliges licht","eisenschmiede","mystic ward","paladin","erlösung","tiza kriegshammer","foliant der offenbarung"},ang={["class:Paladin"]="Dieser Übergangsritus schlägt eine Brücke zwischen dem praktischen Militärdienst im Schnee und der tiefen spirituellen Disziplin, die von heiligen Kriegern erwartet wird.",["faction:Alliance"]="Die gemeinsame Verehrung des Lichts verbindet die zwergischen Verteidiger von Khaz Modan mit ihren menschlichen Verbündeten in Lordaeron und Sturmwind.",["race:Dwarf"]="Zwergenpaladine verbinden die unerschütterliche Ausdauer ihres Volkes mit den Lehren des Heiligen Lichts, mit dem Sanktum der Hall of Mysteries in Eisenschmiede als Mittelpunkt."},sec={{t="Ein Ruf zum High Seat",b="Während zwergische Initianten ihre Ausbildung mit dem Schutz der schneebedeckten Dörfer und Straßen von Dun Morogh beginnen, macht kriegerisches Können allein noch keinen Paladin aus. Azar Hammerkraft erkennt, wann ein Verteidiger für eine tiefere spirituelle Unterweisung bereit ist. Anstatt die gewöhnlichen Kampfübungen fortzusetzen, schickt er vielversprechende Anwärter in das Herz von Eisenschmiede, um ihre wahre Initiation unter den verehrten heiligen Ältesten der Stadt zu beginnen."},{t="Die Hall of Mysteries",b="Die Vorladung leitet den Initianten in den Mystic Ward, hinauf in die ruhigen Kammern der Hall of Mysteries. Dort, umgeben von heiligen Relikten und feierlichem Studium, steht Tiza Kriegshammer. Als eine der angesehensten Zwergenstreiterinnen des Lichts prüft sie eintreffende Paladine auf ihre Bereitschaft, Selbstaufopferung, Barmherzigkeit und die schweren moralischen Pflichten ihrer heiligen Berufung anzunehmen."}},faq={{q="Was ist der Zweck dieser Quest?",a="Sie dient als einleitende Vorladung, die einen Zwergenpaladin von den abgelegenen Übungsplätzen in Dun Morogh zu Tiza Kriegshammer in Eisenschmiede führt und die Prüfungen einleitet, die erforderlich sind, um das Heilige Licht zu verstehen und die Kraft der Wiederbelebung zu erlangen.",al={"warum brauche ich diese quest","wozu dient foliant der offenbarung","zweck von foliant der offenbarung"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer ist eine erfahrene Zwergenpaladinin und angesehene Mentorin, die im oberen Stockwerk der Hall of Mysteries in Eisenschmiede weilt. Sie beaufsichtigt die spirituelle Unterweisung junger Paladine und leitet sie durch die heiligen Prüfungen des Folianten der Offenbarung.",al={"wer ist tiza","tiza kriegshammer lore","wer ist battleforge"}},{q="Wo befindet sich die Hall of Mysteries?",a="Die Hall of Mysteries befindet sich im Mystic Ward im westlichen Eisenschmiede. Sie ist das spirituelle und arkane Zentrum der Zwergenhauptstadt und beherbergt Priester, Paladine sowie Magier.",al={"wo ist die hall of mysteries","hall of mysteries finden","hall of mysteries eisenschmiede"}},{q="Wer schickt den Paladin auf diesen Botengang?",a="Azar Hammerkraft, ein Paladinlehrer in Dun Morogh, schickt vielversprechende Initianten nach Eisenschmiede, sobald sie ihre kriegerische Hingabe bei der Verteidigung der örtlichen Zwergensiedlungen unter Beweis gestellt haben.",al={"wer startet foliant der offenbarung","questgeber foliant der offenbarung","azar hammerkraft"}},{q="Warum müssen Zwergenpaladine in Eisenschmiede lernen?",a="Feldlehrer wie Azar unterrichten grundlegende Kampfkünste, doch die formellen Lehren, heiligen Schriften und Ältesten des Heiligen Lichts weilen in der Hall of Mysteries. Fortgeschrittene Riten und spirituelle Doktrinen müssen direkt bei ranghohen Mentoren wie Tiza Kriegshammer erlernt werden.",al={"warum nach eisenschmiede","warum training in eisenschmiede"}},{q="Was folgt nach dem Gespräch mit Tiza Kriegshammer?",a="Das Gespräch mit Tiza leitet die wahren Zwergenprüfungen des Folianten der Offenbarung ein und fordert den Paladin heraus, Hingabe, Mitgefühl und Opferbereitschaft im Dienst des Lichts zu beweisen.",al={"was kommt als nächstes","folgequest nach foliant der offenbarung","was gibt mir tiza"}}},fx={d775d5e6={q="Warum möchte Azar Hammerkraft, dass Ihr Eisenschmiede besucht?",a="Azar Hammerkraft erkennt, dass Eure Zeit als Lehrling, der Dun Morogh unterstützt, sich dem Ende zuneigt. Um wahrhaftig als Champion des Heiligen Lichts zu dienen, benötigt Ihr tiefergehenden Unterricht in seinen Mysterien, Prinzipien und Verpflichtungen. Er schickt Euch nach Eisenschmiede, weil Tiza Kriegshammer damit betraut ist, vielversprechende junge Paladine zu prüfen und zu ihrer wahren Berufung zu führen.",al={"warum schickt azar","azar hammerkraft motiv","warum tiza kriegshammer aufsuchen"}},a7a63213={q="Warum schickt Azar Hammerkraft Euch persönlich?",a="Diese Reise ist kein Botengang, den ein Stadtwache oder ein etablierter Veteran für Euch erledigen könnte. Sie markiert Eure persönliche Entwicklung als Paladin. Azar schickt Euch zu Tiza Kriegshammer, weil Ihr allein dem Ruf des Lichts folgen, Eure Hingabe an seine Tugenden beweisen und die Bürden akzeptieren müsst, die von einem heiligen Krieger erwartet werden.",al={"warum schickt er mich","warum azar schickt","warum paladin"}}},fp="16,368,23.420.0,21.381.0,34.239.0,24.243.0,39.178.0,37.197.0,45.263.0,50.174.0"}
P.entries["quest:2998"] = {n="Foliant der Offenbarung",s="Foliant der Offenbarung stellt eine entscheidende Vorladung für angehende menschliche Paladine im Dienste der Allianz dar. Von örtlichen Mentoren wie Bruder Wilhelm in Goldhain entsandt, reisen die Initianden zur Kathedrale des Lichts in Sturmwind, um Duthorian Rall zu treffen. Diesem Ruf zu folgen, leitet die heilige Prüfung ein, die erforderlich ist, um die heilige Gabe der Wiederbelebung zu meistern.",h="Foliant der Offenbarung stellt eine entscheidende Vorladung für angehende menschliche Paladine im Dienste der...",kw={"bruder wilhelm","kathedrale des lichts","duthorian rall","goldhain","paladin","erlösung","sturmwind","foliant der offenbarung"},ang={["class:Paladin"]="Diese Quest stellt einen Übergangsritus für menschliche Paladine dar und markiert den Moment, in dem Eure Mentoren Eure Taten formell anerkennen und Euch vor die Hohen Kommandanten der Silbernen Hand senden.",["faction:Alliance"]="Die Rekrutierung und Prüfung heiliger Krieger in Sturmwind stellt sicher, dass die Allianz in unruhigen Zeiten stets über hingebungsvolle Heiler und Kämpfer an vorderster Front verfügt.",["race:Human"]="Die Reise aus dem ländlichen Wald von Elwynn in die grandiose Kathedrale des Lichts verankert menschliche Verteidiger in den tiefsten spirituellen und kriegerischen Institutionen des Königreichs."},sec={{t="Eine Vorladung in die Hauptstadt",b="Novizen unter den Paladinen, die ihre Reise durch den Wald von Elwynn beginnen, verbringen ihre ersten Tage damit, den Einheimischen zu helfen und ihr Kampfgeschick an Wölfen, Defias-Banditen und Kobolden zu erproben. Sobald ein Initiand sowohl kriegerische Disziplin als auch Hingabe an das Heilige Licht bewiesen hat, überbringen Mentoren wie Bruder Wilhelm eine persönliche Vorladung. Einflussreiche Paladinführer werden auf vielversprechende Schüler aufmerksam und weisen sie an, die örtlichen Kapellenausläufer hinter sich zu lassen und sich direkt im spirituellen Herzen des Königreichs zu melden."},{t="Die Kathedrale des Lichts",b="Am Kathedralenplatz in Sturmwind dient die Kathedrale des Lichts als erhabenstes Heiligtum für die Priesterschaft des Königreichs und die Ritter der Silbernen Hand. Hier verweilt Duthorian Rall und wacht über die Entwicklung jener, die dem Orden die Treue geschworen haben. Unter den hoch aufragenden Gewölbedecken tritt der Initiand vor hochrangige Paladine, um die formellen Prüfungen des Folianten der Offenbarung zu empfangen – Herausforderungen, die darauf ausgelegt sind, unerschütterliches Mitgefühl, Seelenstärke und aufopferungsvolle Pflichterfüllung auf die Probe zu stellen."}},faq={{q="Wer schickt mich für diese Quest nach Sturmwind?",a="Bruder Wilhelm, der Paladinlehrer nahe dem Gasthaus \"Zur Höhle des Löwen\" in Goldhain, bietet diese Vorladung an, sobald Ihr im Feld ausreichendes Potenzial und Stärke bewiesen habt.",al={"questgeber","wer gibt quest","bruder wilhelm"}},{q="Wo kann ich Duthorian Rall finden?",a="Duthorian Rall befindet sich im Inneren der Kathedrale des Lichts, gelegen am Kathedralenplatz im Nordwesten von Sturmwind. Er verbringt die meiste Zeit damit, Paladine in den großen Hallen der Kathedrale auszubilden.",al={"duthorian rall aufenthaltsort","wo ist duthorian rall","paladinlehrer standort"}},{q="Warum ist diese Vorladung für Paladine so wichtig?",a="Das Melden bei Duthorian Rall markiert den Übergang von einfacher Kampfausbildung zu tiefer heiliger Einkehr. Es leitet die Prüfungen des Folianten der Offenbarung ein, die letztlich die heilige Macht verleihen, gefallene Verbündete durch das Licht vom Tode zurückzurufen.",al={"warum diese quest machen","bedeutung der quest","paladinprüfung"}},{q="Erhalten nicht-menschliche Paladine genau diese Quest?",a="Diese spezielle Version der Vorladung stammt aus dem Wald von Elwynn von Bruder Wilhelm und ist für menschliche Paladine bestimmt. Paladine der Zwerge erhalten in Dun Morogh von ihren eigenen Ausbildern einen gleichwertigen Ruf, Eisenschmiede aufzusuchen.",al={"zwergenpaladin","können zwerge das machen","ist diese quest nur für menschen"}},{q="Was geschieht, nachdem man sich bei Duthorian Rall gemeldet hat?",a="Nachdem Ihr Duthorian Rall begrüßt habt, heißt er Euch in Sturmwind willkommen und stellt Euch umgehend die Prüfungen des Folianten der Offenbarung, um Euer Mitgefühl und Eure Hingabe an den Schutz der Schwachen auf die Probe zu stellen.",al={"folgequest","was passiert als nächstes","foliant der offenbarung nächster schritt"}},{q="Wer ist Duthorian Rall?",a="Duthorian Rall ist einer der einflussreichsten Paladine im Königreich Sturmwind und den Rittern der Silbernen Hand, verantwortlich für die Ausbildung neuer Generationen heiliger Krieger in der Hauptstadt.",al={"wer ist duthorian","duthorian rall hintergrund"}}},fx={["69ec335a"]={q="Warum schickt Bruder Wilhelm Euch zu Duthorian Rall?",a="Bruder Wilhelm hegt großen Respekt für Duthorian Rall, einen der einflussreichsten Paladine des Ordens. Nachdem er gehört hat, wie Duthorian voller Anerkennung von Eurem Dienst sprach und erwähnte, dass Ihr bereit seid, auf die Probe gestellt zu werden, möchte Wilhelm einfach sicherstellen, dass Ihr die Gelegenheit ergreift. Vielversprechende Novizen zu fortgeschrittener Unterweisung zu führen, ist seine Pflicht und sein Stolz als Mentor in Goldhain.",al={"warum schickt wilhelm","bruder wilhelm motiv","warum mit duthorian rall sprechen"}}},fp="16,320,24.502.0,22.485.0,41.172.0,32.199.0,46.247.0,47.225.0,47.185.0,22.199.0"}
P.entries["quest:2999"] = {n="Foliant der Offenbarung",s="Foliant der Offenbarung ist eine Übergangsritus-Quest, die jungen Zwergenpaladinen angeboten wird, die in Dun Morogh dienen. Geleitet von Brandur Eisenhammer, dem Paladinlehrer in Eisenschmiedes Hall of Mysteries, wird ein Initiant nach oben geschickt, um mit der angesehenen Paladinlehrerin Tiza Kriegshammer zu sprechen. Sie markiert den Übergang von der grundlegenden militärischen Ausbildung zu den tieferen spirituellen Pflichten und heiligen Gelübden des Heiligen Lichts.",h="Foliant der Offenbarung ist eine Übergangsritus-Quest, die jungen Zwergenpaladinen angeboten wird, die in Dun...",kw={"brandur eisenhammer","hall of mystics","eisenschmiede","paladin","erlösung","tiza kriegshammer","foliant der offenbarung"},ang={["class:Paladin"]="Diese Quest markiert den Moment, in dem ein Initiant von einfachen militärischen Übungen zu den tiefgründigen spirituellen Bürden des Heiligen Lichts übergeht, und bereitet die Prüfungen vor, um die Kraft der Erlösung zu erlangen.",["race:Dwarf"]="Zwergenpaladine verbinden die Hingabe an das Heilige Licht mit Khaz Modans tiefen Traditionen von Pflicht und Brüderlichkeit und folgen dem Ruf in den Berghallen von Eisenschmiede."},sec={{t="Der Ruf zum High Seat",b="Während angehende Paladine ihre ersten Tage damit verbringen, Ambossar und Kharanos vor Troggs und Frosttrollen zu verteidigen, verlangen ihre Pflichten schließlich nach tieferer Hingabe. Brandur Eisenhammer, der erkennt, dass ein Initiant seine kriegerische Disziplin bewiesen hat, rät ihm, eine Pause von seiner Arbeit in den verschneiten Pässen einzulegen und oben in seiner eigenen Hall of Mysteries in Eisenschmiede Führung zu suchen. Dort wachen ranghöhere Paladine über die spirituelle Reifung des Ordens."},{t="Führung durch Tiza Kriegshammer",b="Tiza Kriegshammer gilt als eine der am meisten verehrten Paladinen unter den Zwergen von Eisenschmiede. Es ist ihre Verantwortung, Initianten über die wahren Bürden des Lichts zu unterrichten, indem sie über einfaches Schwertspiel und Hammerschwünge hinausgeht, um Mitgefühl, Gerechtigkeit und Selbstaufopferung zu lehren. Sie aufzusuchen leitet das formelle Studium des Folianten der Offenbarung ein – ein heiliger Prozess, der darauf abzielt, einem Paladin die Fähigkeit zu verleihen, die Gefallenen wiederzubeleben."}},faq={{q="Was ist der Zweck dieser Quest?",a="Diese Quest führt junge Zwergenpaladine von ihrem Lehrer Brandur Eisenhammer zur ranghöheren Paladin Tiza Kriegshammer in Eisenschmiede. Sie dient als einleitender Schritt für die Prüfungen, die erforderlich sind, um den Folianten der Offenbarung zu studieren und die Kraft der spirituellen Wiederbelebung zu erlangen.",al={"was bewirkt diese quest","foliant der offenbarung start","warum diese quest machen"}},{q="Wer ist Brandur Eisenhammer?",a="Brandur Eisenhammer ist ein Zwergenpaladinlehrer, der in der Hall of Mysteries im Mystic Ward von Eisenschmiede stationiert ist. Er wacht dort über junge Paladine und schickt vielversprechende Initianten nach oben zu Tiza Kriegshammer, sobald sie für größere heilige Verantwortungen bereit sind.",al={"wer gibt diese quest","brandurs rolle","brandur eisenhammer lore"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer ist eine angesehene Paladinveteranin, die sich im oberen Stockwerk der Hall of Mysteries in Eisenschmiede aufhält. Sie unterweist jüngere Paladine darin, was das Heilige Licht über das kriegerische Können hinaus wahrhaft von ihnen verlangt.",al={"wo ist tiza","tiza kriegshammer rolle","wer ist tiza"}},{q="Wohin führt diese Quest als Nächstes?",a="Das Gespräch mit Tiza Kriegshammer leitet die spezifischen Prüfungen des Folianten der Offenbarung ein. Diese Aufgaben stellen die Hingabe, Barmherzigkeit und Bereitschaft eines Paladins auf die Probe, im Dienste des Lichts Leben zu schützen und wiederherzustellen.",al={"folgequest","was kommt danach","foliant der offenbarung questreihe"}},{q="Warum müssen Zwergenpaladine den Folianten der Offenbarung aufsuchen?",a="Um das Wunder zu wirken, einen gefallenen Verbündeten ins Leben zurückzuholen, muss ein Paladin wahre Selbstlosigkeit und spirituelle Pflicht verstehen. Der Foliant der Offenbarung leitet Initianten durch formelle Lektionen und Glaubensprüfungen, die notwendig sind, um solch mächtige heilige Macht zu kanalisieren.",al={"warum foliant der offenbarung","paladin wiederbelebung quest lore","erlösung zwerg"}},{q="Erhalten Menschen die gleiche Unterweisung in Eisenschmiede?",a="Menschliche Paladine treten eine parallele Reise in der Kathedrale des Lichts in Sturmwind anstatt in Eisenschmiede an. Diese spezifische Aufforderung von Brandur Eisenhammer an Tiza Kriegshammer ist auf Zwerge zugeschnitten, die in Eisenschmiede ausgebildet werden.",al={"können menschen das machen","ist das nur für zwerge","mensch foliant der offenbarung"}}},fx={["1a85ab42"]={q="Warum schickt Brandur Eisenhammer Euch zu Tiza Kriegshammer?",a="Brandur Eisenhammer erkennt, dass Eure Ausbildungszeit in Dun Morogh Euch auf tiefergehende Verantwortungen innerhalb des Ordens vorbereitet hat. Anstatt Euch an lokale Probleme zu binden, möchte er, dass Ihr in Eurer Berufung voranschreitet. Tiza Kriegshammer wird unter zwergischen Paladinen als eine Mentorin verehrt, die jüngere Novizen anleitet, wenn sie bereit sind zu lernen, was das Heilige Licht wirklich von ihnen verlangt.",al={"warum schickt brandur","brandur eisenhammer motiv","warum mit tiza kriegshammer sprechen"}},["264c72ef"]={q="Warum müsst Ihr selbst mit Tiza sprechen, anstatt dass Brandur das erledigt?",a="Der Pfad eines Paladins ist zutiefst persönlich und kann nicht durch Stellvertreter beschritten werden. Brandur Eisenhammer kann Euer frühes kämpferisches Training leiten, aber spirituelle Weiterentwicklung erfordert, dass Ihr Euch persönlich vor Euren Ältesten präsentiert. Tiza Kriegshammer muss Eure Hingabe und Entschlossenheit aus erster Hand beurteilen, bevor sie Euch heilige Lehren wie die 'The Tome of Divinity' anvertrauen kann.",al={"warum tome of divinity","warum muss ich zu tiza","warum geht brandur nicht selbst"}}},fp="16,397,25.447.0,30.413.0,34.260.0,26.258.0,24.201.0,32.200.0,56.245.0,53.222.0"}
P.entries["quest:3000"] = {n="Foliant der Offenbarung",s="Dieser Auftrag weist zwergische Paladine, die in der Fremde umherziehen, an, nach Eisenschmiede heimzukehren, um ihrer heiligen Berufung weiter nachzugehen. Angeboten von Lord Grayson Schattenbruch in Sturmwind, führt er angehende Champions zu Tiza Kriegshammer, einer der angesehensten Ausbilderinnen in der Hall of Mysteries. Die Heimkehr markiert den Beginn ihrer offiziellen Prüfungen mit dem Folianten der Offenbarung.",h="Dieser Auftrag weist zwergische Paladine, die in der Fremde umherziehen, an, nach Eisenschmiede heimzukehren...",kw={"zwergenpaladin","hall of mysteries","eisenschmiede","lord grayson schattenbruch","mystic ward","erloesung","tiza kriegshammer","foliant der offenbarung"},ang={["class:Paladin"]="Dies markiert einen bedeutenden Übergangsritus für zwergische Paladine, der sie auf den Pfad führt, den Folianten der Offenbarung zu studieren und die Gabe der Wiederbelebung zu meistern.",["faction:Alliance"]="Die gemeinsame Ausbildung und der gegenseitige Respekt zwischen den Paladinen von Sturmwind und den Mentoren von Eisenschmiede unterstreichen das enge spirituelle Bündnis zwischen Zwergen und Menschen.",["race:Dwarf"]="Diese Quest schlägt eine Brücke zwischen Euren Abenteuern in den Ländern der Menschen und Eurer Pflicht gegenüber Khaz Modan, indem sie Euch an Euren angestammten Sitz in Eisenschmiede zurückruft, um unter Euren eigenen Ältesten zu trainieren."},sec={{t="Ein Ruf nach Hause",b="Obwohl zwergische Paladine dem Königreich Sturmwind häufig beistehen und die menschlichen Gebiete bereisen, bleiben ihre spirituellen und kriegerischen Wurzeln in Khaz Modan verankert. Sobald Lord Grayson Schattenbruch erkennt, dass die Ausbildung eines Zwergs im Felde weit genug fortgeschritten ist, rät er ihm, in das Herz von Eisenschmiede zurückzukehren. Dort wacht ihr eigenes Volk über die tiefgründigen spirituellen Verpflichtungen, die von einem vollwertigen Ritter der Silbernen Hand erwartet werden."},{t="Die Hall of Mysteries",b="Nach der Rückkehr in die Gebirgshauptstadt wird der Paladin in den Mystic Ward geschickt. Tief im Inneren der Hall of Mysteries, auf deren oberer Ebene, verweilt Tiza Kriegshammer. Sie dient der jüngeren Generation zwergischer Paladine als verehrte Mentorin und bereitet sie darauf vor, die Bürde des Heiligen Lichts durch die im Folianten der Offenbarung festgehaltenen heiligen Prüfungen auf sich zu nehmen."}},faq={{q="Warum schickt mich Lord Grayson Schattenbruch nach Eisenschmiede zurück?",a="Lord Grayson erkennt an, dass Ihr Euren Mut im Felde bewiesen habt, junge zwergische Paladine die tieferen Grundsätze und Prüfungen des Heiligen Lichts jedoch direkt von ihrem eigenen Volk unter der Anleitung von Tiza Kriegshammer erlernen sollen.",al={"warum nach eisenschmiede","warum grayson wegschickt","warum tiza besuchen"}},{q="Wer ist Tiza Kriegshammer?",a="Tiza Kriegshammer ist eine der angesehensten zwergischen Paladinen von Eisenschmiede. Oben in der Hall of Mysteries stationiert, betreut sie heranwachsende Paladine und leitet die Prüfungen, die ihre Hingabe an das Licht auf die Probe stellen.",al={"tiza kriegshammer","wer ist tiza","paladinlehrerin tiza"}},{q="Wo kann ich Tiza Kriegshammer finden?",a="Sie befindet sich in der Hall of Mysteries, die im Mystic Ward von Eisenschmiede liegt. Begebt Euch innerhalb des Heiligtums nach oben, um sie zu finden.",al={"wo ist tiza","tiza kriegshammer standort","wie man tiza findet"}},{q="Was ist der Foliant der Offenbarung?",a="Der Foliant der Offenbarung umfasst die heiligen Lehren und anspruchsvollen Prüfungen, denen sich Paladine unterziehen müssen, um das Heilige Licht zu meistern – insbesondere die Macht der Wiederbelebung und die selbstlose Hingabe an gefallene Verbündete.",al={"bedeutung foliant der offenbarung","was ist der foliant","paladinbuch"}},{q="Können menschliche Paladine diese Version der Quest annehmen?",a="Nein. Dieser spezielle Ruf weist ausdrücklich zwergische Paladine an, zu den Ausbildern ihrer Heimat zurückzukehren, während menschliche Paladine ihre Prüfungen direkt unter Lord Grayson Schattenbruch und Duthorian Rall in Sturmwind absolvieren.",al={"koennen menschen das machen","ist diese quest nur fuer zwerge"}},{q="Was geschieht, nachdem man sich bei Tiza Kriegshammer gemeldet hat?",a="Sobald Ihr Euch bei Tiza vorstellt, konfrontiert sie Euch mit Euren formellen Zwergenprüfungen aus dem Folianten der Offenbarung und stellt Eure Bereitschaft auf die Probe, die erlösende Macht des Lichts zu führen.",al={"wie geht es weiter","naechste quest nach foliant der offenbarung","nach dem gespraech mit tiza"}}},fx={c5356bb5={q="Warum wählt Lord Grayson Schattenbruch mich dafür aus?",a="Lord Grayson erkennt Euer wachsendes Potenzial als Paladin, respektiert aber die ausgeprägten Traditionen Eures Volkes. Anstatt Euch vollständig innerhalb der Kathedrale des Lichts in Sturmwind zu unterrichten, weiß er, dass junge zwergische Paladine in den Lehren ihrer eigenen Ältesten verwurzelt sein müssen. Er schickt Euch nach Hause, weil es Zeit für Euren nächsten heiligen Ritus ist, und Tiza Kriegshammer ist die verehrte Mentorin, die Zwerge durch diesen spirituellen Meilenstein führt.",al={"warum tome of divinity","warum schickt grayson","warum zwerg paladin"}}},fp="16,370,14.432.0,21.365.0,62.228.0,24.213.0,34.136.0,29.198.0,48.226.0,49.177.0"}
P.entries["quest:3001"] = {n="Die Suche nach Strahad",s="Die Suche nach Strahad ist ein Unterfangen, das Hexenmeistern der Horde von Carendin Halgar in Unterstadt anvertraut wird. Halgar schickt seinen Schüler über das große Meer in die staubigen Hügel oberhalb von Ratschet, wo ein menschlicher Zauberer die Schlüssel zu tieferen, gefährlicheren Beschwörungen hütet. Es markiert den Übergang vom grundlegenden Schattenhandwerk zur anspruchsvollen Kunst, einen Teufelsjäger zu beschwören.",h="Die Suche nach Strahad ist ein Unterfangen, das Hexenmeistern der Horde von Carendin Halgar in Unterstadt...",kw={"brachland","carendin halgar","teufelsjäger","ratschet","die suche nach strahad","strahad farsan","foliant der kabale","unterstadt","hexenmeister"},ang={["class:Warlock"]="Diese Quest ist ein entscheidender Übergangsritus um Euren dreißigsten Zirkel der Macht, der über das Binden niederer Wichtel und Leerwandler hinaus zur Beherrschung des räuberischen Teufelsjägers führt.",["faction:Horde"]="Verlassene und orkische Anhänger müssen ihre gewohnte Feindseligkeit gegenüber Menschen herunterschlucken und den weiten Weg ins neutrale Ratschet auf sich nehmen, um von einem lebenden Zauberer zu lernen.",["race:Undead"]="Carendin Halgar entsendet Jünger der Verlassenen persönlich aus Unterstadt, was beweist, dass selbst die Getreuen von Sylvanas lebende Meister nutzen, um ihr Arsenal zu erweitern."},sec={{t="Ein Meister jenseits des Meeres",b="Carendin Halgar, der Hexenmeisterlehrer der Verlassenen, der die dunklen Künste im Magieviertel von Unterstadt überwacht, erkennt, wenn ein Initiant der grundlegenden Ausbildung entwachsen ist. Anstatt seine Schüler innerhalb der Grenzen der Ruinen von Lordaeron zu halten, befiehlt er ihnen, Strahad Farsan aufzusuchen. Halgar warnt davor, dass Strahad zwar ein lebender Mensch, aber keineswegs schwach ist und nicht als Feind behandelt werden darf. Für Hexenmeister steht das Streben nach dämonischer Meisterschaft regelmäßig über den Grenzen von Volk und Fraktion."},{t="Der Rundblick bei Ratschet",b="Strahad operiert in relativer Neutralität hoch oben auf den Klippen mit Blick auf den Goblinhafen Ratschet im Brachland. Von seinem Posten nahe dem steinernen Wachturm blickt er mit leichter Verachtung auf das geschäftige Treiben der Seeleute, Söldner und Händler herab und spottet über deren glückselige Unwissenheit bezüglich des Wirbelnden Nethers. Strahad stört sich nicht an dem Misstrauen oder dem schwelenden Hass in den Augen der Anhänger der Horde, die vor ihm treten; stattdessen betrachtet er diese rohe Bosheit als wirksamen Treibstoff, der zu dunkler Autorität geformt werden kann."}},faq={{q="Warum schickt mich ein Hexenmeister aus Unterstadt zu einem Menschen?",a="Hexenmeister legen die Kluft zwischen den Fraktionen häufig beiseite, wenn sie seltenem und mächtigem dunklem Wissen nachjagen. Carendin Halgar erkennt an, dass Strahad Farsan über spezialisierte Meisterschaft bei größeren Dämonenbeschwörungen verfügt, die Halgar nicht bieten kann. Beim Streben nach dämonischer Macht zählt Wissen weit mehr als die Abstammung des Lehrmeisters.",al={"warum menschlicher lehrer","warum zu mensch geschickt","carendin schickt zu strahad"}},{q="Wo genau befindet sich Strahad Farsan?",a="Strahad Farsan hält sich im Brachland auf, hoch oben auf den Klippen direkt über dem Goblinhafen Ratschet. Er steht nahe dem Steinturm mit Blick auf die Bucht und die geschäftigen Hafenbecken darunter.",al={"strahad aufenthaltsort","wo ist strahad","wie man strahad findet"}},{q="Welche Art von Macht lehrt Strahad?",a="Strahad führt erfahrene Hexenmeister durch die komplexen Rituale, die erforderlich sind, um größere Dämonen aus dem Wirbelnden Nether zu binden, was direkt zu den gefährlichen Prüfungen führt, die für das Beschwören und Beherrschen eines Teufelsjägers notwendig sind.",al={"was strahad lehrt","wozu diese quest dient","teufelsjäger quest"}},{q="Ist Strahad mit der Allianz verbündet?",a="Obwohl er ein Mensch ist, agiert Strahad vom neutralen Goblingebiet in Ratschet aus und bleibt unabhängig von der Großen Allianz. Er ist ein freischaffender Praktizierender, der ungehindert mit Hexenmeistern von Horde und Allianz verhandelt, die fähig sind, seine Unterweisung zu überleben.",al={"gehört strahad zur allianz","strahad fraktion","ist strahad friedlich"}},{q="Was geschieht nach dem Eintreffen bei Strahad?",a="Nach Eurer Ankunft prüft Strahad Eure Entschlossenheit und beauftragt Euch damit, die verstreuten Fragmente und Bestandteile für den Foliant der Kabale zu beschaffen. Damit schickt er Euch auf eine weitreichende Quest, um das Ritual zur Beschwörung eines Teufelsjägers freizuschalten.",al={"was nach strahad kommt","foliant der kabale","nächste quest"}},{q="Warum begrüßt Strahad den Hass in seinen Schülern?",a="Dämonische Magie nährt sich von intensiven Emotionen, Dominanz und Willenskraft. Strahad betrachtet Hass als eine fokussierte, wirkungsvolle Disziplin, die kanalisiert werden kann, um chaotische Wesen des Nethers zu unterwerfen, die sonst einen undisziplinierten Beschwörer verschlingen würden.",al={"warum mag strahad hass","hass in euren augen"}}},fx={c0e56201={q="Warum schickt Euch Carendin, anstatt selbst zu gehen?",a="Carendin Halgar dient als Hexenmeister-Ausbilder in der Unterstadt und unterweist Novizen, soweit es seine Lehren erlauben. Ihr seid über die grundlegenden Künste hinausgewachsen, die er Anfängern vermittelt, und habt bewiesen, dass Ihr bereit für größere Beschwörungen seid. Dies ist keine diplomatische Mission, sondern eine Prüfung für Euer eigenes Vorankommen. Er schickt Euch los, um Strahad Farsan zu suchen, da Eure eigene Meisterschaft der dunklen Künste getestet und erweitert werden muss.",al={"warum soll ich strahad suchen","warum geht carendin nicht selbst","warum braucht carendin mich"}}},fp="15,355,23.489.0,23.504.0,50.323.0,40.199.0,38.209.0,36.252.0,36.217.0,48.235.0"}
P.entries["quest:301"] = {n="Meldung in Eisenschmiede",s="Dieser Botengang schickt einen Abenteurer von Thelsamar in Loch Modan mit entscheidenden Neuigkeiten von Eisenbands Ausgrabungsstätte ins Herz von Eisenschmiede. Die Übergabe von Bericht über den Fortschritt der Ausgrabungen an Ausgrabungsleiter Sturmlanze in der Versammlung der Forscher löst eine Untersuchung über verschwundenes Sprengpulver und ins Stocken geratene Ausgrabungen in den Ausläufern aus.",h="Dieser Botengang schickt einen Abenteurer von Thelsamar in Loch Modan mit entscheidenden Neuigkeiten von...",kw={"sprengpulver","forscherliga","eisenbands truppenlager","jern hornhelm","loch modan","ausgrabungsleiter sturmlanze","meldung in eisenschmiede","thelsamar"},ang={["faction:Alliance"]="Diese Aufgabe veranschaulicht die logistische Reichweite der Allianz, die entlegene Forschungslager in den Bergtälern mit der militärischen und wissenschaftlichen Führung in Eisenschmiede verbindet.",["race:Dwarf"]="Für Zwerge ist die Navigation durch die Bürokratie der Forscherliga und der Umgang mit dem legendären Temperament des Stormpike-Clans ein vertrauter Übergangsritus in den Hallen ihrer Hauptstadt."},sec={{t="Ein Kurier für die Liga",b="Archäologische Expeditionen in ganz Khaz Modan sind stark auf Finanzierung, Vorräte und Aufsicht durch die Forscherliga angewiesen. Als Ausgrabungsleiter Eisenbands Ausgrabungsstätte im südlichen Loch Modan der Sprengstoff ausgeht, können seine Aufseher nicht einfach vor Ort Nachschub anfordern. Jern Hornhelm im Gasthof von Thelsamar betraut einen Abenteurer damit, Ironbands schriftlichen Bericht über die Bergpässe direkt zu Ausgrabungsleiter Sturmlanze im Hauptquartier der Liga zu bringen."},{t="Das Temperament der Stormpikes",b="Ausgrabungsleiter Sturmlanze verkörpert die kompromisslose, feurige Entschlossenheit, die für seinen Clan typisch ist. Stationiert in der großen Bibliothek und Hall of Explorers in Eisenschmiede, erwartet er rasche, greifbare Ergebnisse von den Ausgrabungen der Liga. Nach Erhalt der Nachricht ist Stormpike empört darüber, dass Ironband eine Wochen zuvor entsandte, gewaltige Ladung Sprengpulver mit keinem Wort erwähnt, was offenbart, dass die Nachschublinien in Loch Modan gefährlich zusammengebrochen sind."}},faq={{q="Warum muss dieser Bericht den ganzen Weg nach Eisenschmiede gebracht werden?",a="Die Forscherliga regelt die Verteilung wertvoller Ressourcen wie Sprengpulver streng. Ausgrabungen im Feld können gefährliche Explosivstoffe nicht ohne formelle Genehmigung der leitenden Ausgrabungsleiter im Hauptquartier in der Hall of Explorers anfordern.",al={"warum nach eisenschmiede","warum bericht zu stormpike bringen","eisenschmiede meldung grund"}},{q="Wer ist Ausgrabungsleiter Sturmlanze?",a="Er ist ein hochrangiger Funktionär der Forscherliga mit Sitz in Eisenschmiede. Als Mitglied des stolzen Stormpike-Clans ist er berüchtigt für sein hitziges Gemüt und seine Ungeduld bei ins Stocken geratenen Ausgrabungen und fehlenden Beständen.",al={"wer ist stormpike","ausgrabungsleiter stormpike geschichte"}},{q="Wo ist Ironbands ursprüngliches Sprengpulver geblieben?",a="Eine Ladung Sprengpulver war bereits Wochen zuvor entsandt worden, doch Ironband erwähnt mit keinem Wort, sie je erhalten zu haben. Dies weckt sofortige Befürchtungen, dass Troggs oder Banditen den Transportkarren auf den Straßen von Loch Modan überfallen haben könnten.",al={"was geschah mit dem sprengpulver","fehlendes sprengpulver","wo ist das pulver"}},{q="Wo findet man Ausgrabungsleiter Sturmlanze in Eisenschmiede?",a="Ausgrabungsleiter Sturmlanze befindet sich in der Versammlung der Forscher, auch bekannt als Bibliothek oder Hall of Explorers, gelegen im nordöstlichen Flügel von Eisenschmiede.",al={"stormpike aufenthaltsort","wo ist stormpike","versammlung der forscher standort"}},{q="Wer übergibt Euch den Bericht in Thelsamar?",a="Jern Hornhelm, der sich im Gasthof Zum Starkbier-Lager in Thelsamar aufhält, fungiert als Verbindungsmann, der Berichte und Mitteilungen zwischen Ironbands abgelegenem Lager und der Stadtführung koordiniert.",al={"wer startet meldung in eisenschmiede","jern hornhelm rolle"}},{q="Was geschieht, nachdem Stormpike den Bericht gelesen hat?",a="Wütend über die unauffindbare Munition und den stockenden Fortschritt befiehlt Stormpike dem Spieler, eine neue Ladung Sprengpulver zu organisieren und diese direkt zu Ausgrabungsleiter Eisenband zurückzubringen.",al={"was kommt danach","folgequest nach meldung in eisenschmiede"}}},fx={["601d3943"]={q="Warum möchte Jern Hornhelm, dass dieser Bericht nach Eisenschmiede geschickt wird?",a="Die Ausgrabung von Ausgrabungsleiter Eisenband im Loch Modan ist zum Stillstand gekommen, da der Mannschaft das Sprengpulver ausgegangen ist. Jern Hornhelm kann in eigener Vollmacht keine weiteren Vorräte anfordern; er benötigt die formelle Genehmigung der Forscherliga aus Eisenschmiede. Die Zustellung des Fortschrittsberichts an Ausgrabungsleiter Sturmlanze ist der einzige verwaltungstechnische Weg, um eine neue Ladung Pulver zu sichern und die Grabungen fortzusetzen.",al={"warum den bericht senden","jern hornhelm motiv","warum will jern sprengpulver"}},["499fe615"]={q="Warum schickt Euch Jern Hornhelm, anstatt selbst zu gehen?",a="Jern Hornhelm hat alle Hände voll damit zu tun, die Logistik in Thelsamar zu verwalten und die örtlichen Ausgrabungsarbeiten zu unterstützen. Zudem ist Ausgrabungsleiter Sturmlanze dafür bekannt, ein kurzes, feuriges Temperament zu haben, wenn es um Verzögerungen und Rückschläge geht. Wenn er einen entbehrlichen Kurier losschickt, der dem Zorn von Sturmlanze trotzt, erspart sich Jern den direkten Zorn seiner Vorgesetzten und kann sich weiterhin auf die lokalen Abläufe konzentrieren.",al={"warum schickt er mich","warum geht er nicht selbst","warum braucht hornhelm mich"}}},fp="19,331,24.453.0,20.452.1,57.245.0,28.214.0,45.220.0,52.159.0,38.182.0,46.183.1"}
P.entries["quest:302"] = {n="Pulver für Eisenband",s="Pulver für Eisenband ist eine Lieferungsquest der Allianz, die das Hauptquartier der Explorer's League in Eisenschmiede mit Loch Modan verbindet. Nachdem sie die offizielle Genehmigung von Ausgrabungsleiter Sturmlanze erhalten haben, werden Abenteurer nach Thelsamar geschickt, um eine entscheidende Lieferung von Sprengpulver für Eisenbands Ausgrabungsstätte zu überwachen.",h="Pulver für Eisenband ist eine Lieferungsquest der Allianz, die das Hauptquartier der Explorer's League in...",kw={"explorers league","huldar","eisenschmiede","jern hornhelm","loch modan","pulver für eisenband","ausgrabungsleiter sturmlanze","thelsamar"},ang={["faction:Alliance"]="Die Sicherheit der Verkehrsstraßen in Loch Modan aufrechtzuerhalten, ist für den Zusammenhalt der Allianz zwischen Eisenschmiede und den östlichen Grenzgebieten von entscheidender Bedeutung.",["profession:Mining"]="Sprengpulver ist ein wesentliches Werkzeug des Zwergenhandwerks, das gleichermaßen von Bergleuten und Ausgräbern genutzt wird, um das tiefste Grundgestein aufzubrechen.",["race:Dwarf"]="Für Zwerge ist die Beschaffung von Ausgrabungspulver nicht bloß logistische Unterstützung; sie dient dem heiligen Bestreben, die mysteriösen Ursprünge ihres Volkes aufzudecken."},sec={{t="Bürokratie und Sprengpulver",b="Archäologische Ausgrabungen in den Bergen von Khaz Modan erfordern schwere Munition. Als der Expedition von Ausgrabungsleiter Eisenband im südlichen Loch Modan die Sprengmittel ausgingen, wurde die Führung der Liga in Eisenschmiede benachrichtigt. Ausgrabungsleiter Sturmlanze genehmigte die Anforderung rasch und wies den Boten an, sich mit Jern Hornhelm in Thelsamar abzustimmen, dem primären logistischen Knotenpunkt des Tals."},{t="Eine verpasste Abreise",b="Da frühere Nachschubkonvois durch den Loch verschwunden waren oder von einheimischen Troggs überfallen wurden, befahl Stormpike dem Kurier ausdrücklich, den Pulverkarren persönlich zu sichern. Doch Bürokratie und Reisezeit arbeiten gegen die Liga. Bis ein Bote im Gasthof Zum Starkbier-Lager in Thelsamar eintrifft, hat Jern Hornhelm den Karren bereits unter der Bewachung von Huldar und zwei Zwergenträgern losgeschickt, sodass der Bote die Straße hinabeilen muss, um sie einzuholen."}},faq={{q="Warum wird Sprengpulver zu Ironband geschickt?",a="Ausgrabungsleiter Eisenband leitet eine wichtige archäologische Ausgrabung der Zwerge im südlichen Loch Modan. Das Freilegen von Titanenartefakten und uralten Steinrelikten erfordert das Aufsprengen von dichtem Gestein, und sein Team hat seine Vorräte inmitten zunehmender Angriffe der Troggs aufgebraucht.",al={"warum pulver gebraucht wird","ironband sprengpulver","wofür ist pulver"}},{q="Wer ist Ausgrabungsleiter Sturmlanze?",a="Ausgrabungsleiter Sturmlanze ist ein leitender Offizier der Zwergen-Explorer's League, der in der Hall of Explorers in Eisenschmiede stationiert ist. Er prüft Anforderungen aus dem Feld, genehmigt wichtige Ausrüstung und leitet die Logistik für bedeutende Ausgrabungsstätten in ganz Khaz Modan.",al={"stormpike rolle","wer vergibt quest"}},{q="Wer ist Jern Hornhelm?",a="Jern Hornhelm ist ein Logistikkoordinator und Verbündeter der Gebirgsjäger, der in Thelsamar in Loch Modan stationiert ist. Er bereitet Nachschub vor und organisiert Transportteams, die in die gefährlicheren Grenzgebiete des Tals aufbrechen.",al={"jern hornhelm aufenthaltsort","wo ist jern hornhelm"}},{q="Warum wurde für diese Lieferung eine persönliche Eskorte angefordert?",a="Frühere Lieferungen an die Ausgrabungsstätte haben ihr Ziel nicht erreicht. Da Loch Modan von Troggs heimgesucht wird, die aus den Hügeln und Ausgrabungsstätten strömen, sind die Versorgungswege entlang der Hauptstraße zunehmend gefährlich geworden.",al={"warum pulver eskortieren","troggangriffe auf wagen"}},{q="Was geschieht, wenn Ihr in Thelsamar ankommt?",a="Jern Hornhelm hat den Wagen bereits mit Huldar und den Trägern Miran und Saean losgeschickt. Ihr seid gezwungen, der südlichen Straße zu folgen, um sie einzuholen, bevor Unheil geschieht.",al={"wagen verpasst","wo ist die lieferung"}},{q="Wie fügt sich diese Quest in die Handlung der Explorer's League ein?",a="Sie dient als Verbindungskurier, der die ursprüngliche Anfrage von der Ausgrabungsstätte über die zentralen Behörden in Eisenschmiede und zurück ins Feld über Thelsamar transportiert, um die fortlaufenden Ausgrabungen der Expedition abzusichern.",al={"ironband questreihe","ausgrabung questreihe"}}},fx={["8773e6dd"]={q="Warum schickt Ausgrabungsleiter Sturmlanze einen Abenteurer und keine offiziellen Wachen?",a="Ausgrabungsleiter Sturmlanze arbeitet von der Hall of Explorers in Eisenschmiede aus und konzentriert sich eher auf verwaltungstechnische Angelegenheiten und das Einholen von Genehmigungen, anstatt Truppen ins Feld zu schicken. Da frühere Lieferungen von Sprengpulver auf den Straßen von Loch Modan bereits Gefahren zum Opfer gefallen sind, vertraut er auf einen fähigen Reisenden, der ohnehin in diese Gegend unterwegs ist, um persönlich sicherzustellen, dass Jern Hornhelms Versorgungskonvoi den Ausgrabungsort sicher erreicht.",al={"warum schickt er mich","warum keine wachen zu eisenband","warum ein abenteurer"}}},fp="18,298,31.403.0,18.467.1,46.241.0,28.241.0,21.210.0,52.221.0,42.185.1,61.215.0"}
P.entries["quest:303"] = {n="Der Dunkeleisenkrieg",s="Am nördlichen Rand des Sumpflands bereitet Motley Garmason eine verzweifelte Verteidigung vor, um Dun Modr vom Dunkeleisenclan zurückzuerobern. Nachdem feindliche Saboteure den Thandol-Übergang zertrümmert und die Stadt eingenommen haben, halten die Bergsteiger der Eisenschmiede eine fragile Linie, während sie auf Verstärkungen warten, die möglicherweise niemals eintreffen werden.",h="Am nördlichen Rand des Sumpflands bereitet Motley Garmason eine verzweifelte Verteidigung vor, um Dun Modr...",kw={"bronzebart","dunkeleisenzwerge","sprengmeister","dun modr","eisenschmiede","motley garmason","saboteure","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Die Zerstörung des Thandol-Übergangs und der Fall von Dun Modr unterbrechen den Überlandzugang zwischen den nördlichen Verbündeten Sturmwinds und den südlichen Königreichen.",["profession:Engineering"]="Die Präzision, mit der die Saboteure des Dunkeleisenclans spezielle Sprengstoffe einsetzten, um uraltes Zwergenmauerwerk zu zertrümmern, zeugt von einer erschreckenden Meisterschaft in der strukturellen Sprengtechnik.",["race:Dwarf"]="Für die Bronzebartzwerge ist der Verlust von Dun Modr eine bittere Demütigung und eine direkte Bedrohung für die Souveränität von Khaz Modan, die Rache an ihren uralten Feinden fordert."},sec={{t="Eine Front am Nordtor",b="Dun Modr war einst die stolze Bastion der Eisenschmiede, die das südliche Ende des Thandol-Übergangs bewachte, der kolossalen Brücke, die Khaz Modan mit Lordaeron verbindet. Als Saboteure und Sprengmeister des Dunkeleisenclans den Torbogen der Brücke sprengten, unterbrachen sie den Transit der Allianz und überwältigten die Festung im Handumdrehen. Motley Garmason und eine Handvoll überlebender Verteidiger konnten sich gerade weit genug zurückziehen, um ein Beobachtungslager zu errichten, doch ohne sofortige Gegenangriffe droht das gesamte nördliche Tor unter die dauerhafte Herrschaft der Dunkeleisenzwerge zu fallen."},{t="Zeit für die Reserven gewinnen",b="Da Zwergenregimenter auf entfernten Schlachtfeldern der Allianz eingesetzt sind, ist Motleys kleine Einheit weitgehend auf sich allein gestellt. Seine Kundschafter versuchen, die Eisenschmiede um Hilfe zu rufen, doch die Kommunikation ist unterbrochen und von den versprochenen Reserven fehlt jede Spur. In dem Versuch, Zeit zu gewinnen und die feindlichen Verschanzungen zu stören, befiehlt Motley chirurgische Schläge direkt in die Ruinen von Dun Modr, um die Reihen der Ingenieure, Tunnelgräber und Frontsoldaten des Dunkeleisenclans zu dezimieren, bevor sie weiter nach Süden in das Sumpfland vorstoßen können."}},faq={{q="Wer ist Motley Garmason?",a="Motley Garmason ist ein Offizier der Bergsteiger der Eisenschmiede, der die Überreste der Garnison von Dun Modr befehligt. Er ist direkt außerhalb der besetzten Stadt stationiert und koordiniert Kundschaftereinsätze und Guerillaschläge gegen die besetzenden Truppen des Dunkeleisenclans.",al={"motley garmason","wer ist motley","kommandant von dun modr"}},{q="Warum ist Dun Modr so wichtig für die Eisenschmiede?",a="Dun Modr bewacht das südliche Ende des Thandol-Übergangs. Als einzige Überlandstraße, die Khaz Modan mit dem Arathihochland und dem nördlichen Lordaeron verbindet, kontrolliert derjenige, der Dun Modr beherrscht, effektiv den gesamten Reise- und Versorgungsverkehr zwischen diesen Regionen.",al={"warum ist dun modr wichtig","bedeutung von dun modr","hintergrund von dun modr"}},{q="Warum kämpfen Dunkeleisenzwerge im Sumpfland?",a="Der Dunkeleisenclan versucht schon lange, seine Bronzebart-Vettern zu untergraben und die Allianz zu schwächen. Durch die Invasion des Sumpflands und die Zerstörung des Thandol-Übergangs schneiden sie die Versorgungswege der Eisenschmiede in den Norden ab und eröffnen eine feindliche zweite Front hinter den Grenzen der Allianz.",al={"warum sind die dunkeleisenzwerge hier","dunkeleisenzwerge im sumpfland","grund für den krieg der dunkeleisenzwerge"}},{q="Was ist mit dem Thandol-Übergang geschehen?",a="Tunnelgräber und Sprengmeister des Dunkeleisenclans platzierten konzentrierte Sprengladungen in den Grundpfeilern des Thandol-Übergangs und beschädigten die Brücke schwer, um Verstärkungen der Eisenschmiede aus Lordaeron abzuschneiden, bevor sie Dun Modr überrannten.",al={"thandol-übergang zerstört","wer hat die brücke gesprengt","explosion am thandol-übergang"}},{q="Wo sind die Reserveeinheiten der Eisenschmiede?",a="Das Militär der Eisenschmiede ist durch zahlreiche Feldzüge im Ausland und die Heimatverteidigung stark beansprucht. Garmasons Kundschafter Roggo hatte Mühe, zuverlässigen Kontakt zum Oberkommando herzustellen, was den Außenposten Dun Modr dazu zwingt, die Stellung mit allen verfügbaren Verbündeten vor Ort zu halten.",al={"reserven der eisenschmiede","wo sind die verstärkungen","roggo reserven"}},{q="Was passiert, nachdem die Dunkeleisenzwerge in Dun Modr zurückgedrängt wurden?",a="Das Ausschalten der Fußsoldaten und Pioniere verschafft entscheidende Zeit, doch Roggos Informationen enthüllen, dass Kam Tiefenzorn, der in der Stormwind Stockade gefangen gehalten wird, den Angriff auf den Thandol-Übergang mitgeplant hat, und Motley bittet Euch, ihm den Kopf von Tiefenzorn zu bringen.",al={"nächste quest nach dem krieg der dunkeleisenzwerge","quest the fury runs deep","was folgt auf den krieg der dunkeleisenzwerge"}}},fx={["07a4003e"]={q="Warum möchte Motley Garmason, dass dies erledigt wird?",a="Motley ist verzweifelt bemüht, Dun Modr zurückzuerobern und den Vormarsch der Dunkeleisenzwerge ins Sumpfland zu stoppen, bevor das Gebiet von Eisenschmiede vollständig in Gefahr gerät. Die Dunkeleisenzwerge haben bereits The Thandol Span gesprengt und die Stadt überrannt, wodurch lebenswichtige Verbindungen in den Norden gekappt wurden. Motley hofft, durch unmittelbaren offensiven Druck auf deren Linien die Front lange genug halten zu können, bis Verstärkung aus Eisenschmiede eintrifft, um sie endgültig zurückzuschlagen.",al={"motley garmason motiv","warum die dunkeleisenzwerge bekämpfen","warum dun modr säubern"}},b2f42bee={q="Warum benötigt Motley Garmason Eure Hilfe anstatt der eigenen Truppen?",a="Das stehende Heer von Eisenschmiede ist bis an die Belastungsgrenze beansprucht, da es weit weg von der Heimat in fremden Ländern im Namen der Allianz kämpft. Nachdem The Thandol Span und Dun Modr gefallen waren, blieb er nur mit einer Handvoll Verteidiger zurück und verfügt über keine frischen Soldaten. Seine Späher schaffen es nicht, Reserven zu mobilisieren, weshalb ihm keine andere Wahl bleibt, als sich auf fähige Reisende wie Euch zu verlassen, um den Kampf zu führen.",al={"warum braucht motley mich","warum kämpfen die wachen nicht","wo sind die truppen von eisenschmiede"}}},fp="17,310,28.523.0,28.515.0,23.229.0,42.247.0,51.264.0,34.223.0,39.269.0,59.235.1"}
P.entries["quest:304"] = {n="Eine grausige Aufgabe",s="Nach dem verheerenden Angriff der Dunkeleisenzwerge auf Dun Modr und den Thandol-Übergang sinnt Langzopf der Grimmige auf Rache für gefallene Verwandte und verlorene Soldaten. Er beauftragt tapfere Reisende damit, den schwer fassbaren Dunkeleisenhexenmeister Balgaras the Foul aufzuspüren und zu töten sowie dessen Ohr als Beweis für die Tat mitzubringen.",h="Nach dem verheerenden Angriff der Dunkeleisenzwerge auf Dun Modr und den Thandol-Übergang sinnt Langzopf der...",kw={"eine grausige aufgabe","balgaras the foul","dunkeleisenzwerge","dun modr","langzopf der grimmige","roggo","thandol-übergang","sumpfland"},ang={["class:Warlock"]="Balgaras the Foul nutzt unheilvolle Teufelsmagie, um das Massaker an den Verteidigern von Dun Modr zu koordinieren, was die gefährlichen Absichten verdeutlicht, für die die Dunkeleisenzwerge ihr Handwerk einsetzen.",["faction:Alliance"]="Der Thandol-Übergang ist der wichtigste Landweg, der Khaz Modan mit Lordaeron verbindet, weshalb die Beseitigung der Dunkeleisensaboteure eine entscheidende strategische Priorität für die gesamte Allianz darstellt.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede sind der Verrat und die Gewalt des Dunkeleisenclans in Dun Modr ein persönlicher Affront und eine frische Wunde im langen Bürgerkrieg zwischen den Clans."},sec={{t="Die Ruinen von Dun Modr",b="In den nördlichen Weiten des Sumpflands kam es zu heftigen Kämpfen zwischen den Gebirgsjägern von Eisenschmiede und Infiltratoren des Dunkeleisenclans. Während der Belagerung wurde die Stadt Dun Modr überrannt und die westliche Brücke des Thandol-Übergangs zerstört. Langzopf der Grimmige verlor bei dem Überfall nicht nur viele loyale Soldaten, sondern auch seinen eigenen Bruder, was ihn dazu bewegte, es dem Feind mit gleicher Münze heimzuzahlen."},{t="Ein feiger Kommandant",b="Die Aufklärung durch Späher wie Roggo ergab, dass das Dunkeleisenkontingent, welches Dun Modr besetzt hält, von einem Hexenmeister namens Balgaras the Foul befehligt wird. Anstatt sich seinen Feinden von Angesicht zu Angesicht zu stellen, versteckt sich Balgaras feige, während er seinen Soldaten befiehlt, seine finsteren Pläne in die Tat umzusetzen. Longbraid hofft, dass das Ausschalten von Balgaras das Rückgrat der Dunkeleisenstreitmacht brechen wird, sodass die Überlebenden von Eisenschmiede den lebenswichtigen Übergang nach Norden sichern können."}},faq={{q="Wer ist Balgaras the Foul?",a="Balgaras the Foul ist ein Dunkeleisenhexenmeister, der die Streitkräfte befehligt, die Dun Modr im nördlichen Sumpfland besetzt halten. Von Langzopf dem Grimmigen als Feigling beschrieben, meidet er den direkten Kampf und schickt stattdessen Scharen von Dunkeleisentruppen aus, um die Region zu halten.",al={"balgaras","wer ist balgaras","dunkeleisen anführer dun modr"}},{q="Wer ist Langzopf der Grimmige?",a="Langzopf der Grimmige ist ein Zwergenkommandant, der vor den Ruinen von Dun Modr lagert. Er verlor seinen Bruder und viele Soldaten, als die Streitkräfte der Dunkeleisenzwerge die Siedlung einnahmen und den westlichen Übergang des Thandol-Übergangs zerstörten.",al={"longbraid","langzopf der grimmige","questgeber dun modr"}},{q="Warum will Longbraid Balgaras' Ohr?",a="Da Balgaras ein schwer fassbares Ziel ist, das sich oft vor einer offenen Schlacht versteckt, verlangt Longbraid einen physischen Beweis für den Tod des Hexenmeisters, um sicherzugehen, dass die Bedrohung wahrhaftig beseitigt wurde.",al={"warum ohr","ohr von balgaras"}},{q="Was geschah mit dem Thandol-Übergang?",a="Die westliche Brücke des Thandol-Übergangs wurde von den Dunkeleisenzwergen während ihrer überraschenden Offensive auf Dun Modr zerstört, wodurch eine essenzielle Straße zwischen dem Sumpfland und dem Arathihochland abgeschnitten wurde.",al={"thandol-übergang brücke zerstört","warum ist der thandol-übergang zerstört"}},{q="Wo versteckt sich Balgaras?",a="Balgaras lauert in den eingenommenen Befestigungen und Ruinen rund um Dun Modr und versteckt sich hinter seinen Soldaten, anstatt sich in die offenen Marschen hinauszuwagen.",al={"wo ist balgaras","balgaras finden"}},{q="Was geschieht, nachdem Balgaras getötet wurde?",a="Sobald Balgaras tot ist, wird es nach Longbraids Ansicht viel einfacher sein, die verbleibenden, desorganisierten Dunkeleisentruppen beiseitezufegen, bevor ein anderer Kommandant eintreffen kann, um sie zu verstärken.",al={"nach eine grausige aufgabe","wie geht es weiter in dun modr"}}},fx={["7a4e9943"]={q="Warum möchte Langzopf der Grimmige, dass Balgaras getötet wird?",a="Langzopf verlor während der Schlacht um Dun Modr viele Soldaten, darunter seinen eigenen Bruder, der ums Leben kam, als die Dunkeleisenzwerge die westliche Brücke von The Thandol Span zerstörten. Balgaras befehligt die feindlichen Dunkeleisentruppen im Sumpfland und dirigiert die Angriffe, während er sich sicher hinter seinen Schergen versteckt. Durch die Hinrichtung des Hexenmeisters sucht Langzopf Vergeltung für seine gefallenen Verwandten und Soldaten und hofft, die Befehlsstruktur der Dunkeleisenbande zu brechen und den Überlebenden Seelenfrieden zu verschaffen.",al={"warum balgaras töten","langzopf motiv","warum will langzopf das erledigt haben"}}},fp="11,288,21.409.0,20.441.0,25.240.0,26.217.0,39.180.0,34.200.0,25.155.0,37.171.0"}
P.entries["quest:305"] = {n="Auf der Suche nach dem Ausgrabungstrupp",s="Auf der Suche nach dem Ausgrabungstrupp beginnt bei Tarrel Felsweber im Sumpfland, der über das plötzliche Schweigen seiner Frau Merrin bestürzt ist. Sie wurde der angesehenen Whelgar Excavation Site im Osten zugeteilt und hat zwei Wochen lang keine ihrer regelmäßigen Briefe geschickt, was die Furcht schürt, dass der Expedition ein Unglück widerfahren ist. Reisende werden beauftragt, in den Sumpf aufzubrechen, die Ausgrabungsstätte ausfindig zu machen und ihre Sicherheit festzustellen.",h="Auf der Suche nach dem Ausgrabungstrupp beginnt bei Tarrel Felsweber im Sumpfland, der über das plötzliche...",kw={"forscherliga","auf der suche nach dem ausgrabungstrupp","langzopf","merrin felsweber","tarrel felsweber","sumpfland","whelgar ausgrabung"},ang={["faction:Alliance"]="Die Aufrechterhaltung zwergischer Stützpunkte und Forschungsexpeditionen in den Marschen ist von entscheidender Bedeutung, um das Sumpfland gegen vordringende Gefahren der Wildnis zu sichern.",["race:Dwarf"]="Die Forscherliga ist sehr stolz darauf, uralte Geschichte ans Licht zu bringen, was die Notsituation von Artgenossen an der Whelgar Excavation zu einer dringenden Angelegenheit für jeden reisenden Zwerg macht."},sec={{t="Die Furcht eines Ehemanns",b="Während er in den feuchten Weiten des Sumpflands stationiert war, erwartete Tarrel Felsweber regelmäßige Post von seiner Frau Merrin. Von der als Whelgar Excavation Site bekannten Zwergenausgrabung aus hatte Merrin wöchentliche Berichte über ihre Arbeit geschickt. Als zwei ganze Wochen ohne ein einziges Wort vergingen, war Tarrel überzeugt, dass das Lager von einer Katastrophe heimgesucht worden war. Da die offiziellen zwergischen Autoritäten überlastet sind, verlässt er sich auf vorbeikommende Kundschafter, die den Gefahren der Sümpfe trotzen, um zu sehen, ob die Ausgräber noch am Leben sind."},{t="Die Whelgar-Ausgrabung",b="Die Whelgar Excavation Site stellt das typische Unterfangen der Zwerge dar, uralte Titanenrelikte und die Geschichte der titanengeschmiedeten Schöpfungen aus dem Morast des Sumpflands zu bergen. Das Ausgraben prähistorischer Schichten in ungezähmtem Gebiet setzt die Trupps jedoch häufig wilden Tieren und feindseligen unterirdischen Bedrohungen aus. Um die Stätte zu erreichen, muss man nach Osten in ein Gebiet reisen, das weit von der relativen Sicherheit der Hauptstraßen entfernt liegt und in dem das Unheil, das die Briefe der Ausgräber unterbrochen hat, noch immer lauert."}},faq={{q="Wer ist Tarrel Felsweber?",a="Tarrel Felsweber ist ein besorgter Zwerg, der im Sumpfland stationiert ist. Von Angst erfüllt über das abrupte Ausbleiben der Briefe seiner Frau Merrin, die an der östlichen Ausgrabungsstätte arbeitet, hält er vorbeikommende Abenteurer für offizielle Kundschafter, die geschickt wurden, um das Schweigen des Lagers zu untersuchen.",al={"tarrel felsweber","questgeber","wer gibt auf der suche nach dem ausgrabungstrupp"}},{q="Wer ist Merrin Felsweber?",a="Merrin Felsweber ist eine Zwergenarchäologin, die beim Ausgrabungstrupp von Whelgar östlich vom Hafen von Menethil im Sumpfland arbeitet. Sie schrieb ihrem Mann regelmäßig, bis eine unerwartete Wendung der Ereignisse ihre Verbindung abrupt abbrach.",al={"merrin felsweber","tarrel frau","wer ist merrin"}},{q="Wo liegt die Whelgar Excavation Site?",a="Die Whelgar Excavation Site liegt östlich vom Hafen von Menethil und südwestlich von Dun Modr im Sumpfland, eingebettet in die felsigen Hänge weit abseits der Hauptstraße.",al={"standort ausgrabungsstätte","wo findet man merrin","wo ist whelgar excavation"}},{q="Warum hat Merrin aufgehört, Briefe zu schreiben?",a="Das plötzliche Schweigen der Ausgrabungsstätte rührt von einer aufkommenden Bedrohung an der Ausgrabung her, die die Zwergenforscher von den normalen Kurierwegen und dem alltäglichen Lagerleben abgeschnitten hat.",al={"warum keine briefe mehr","was geschah mit dem ausgrabungstrupp","warum keine post"}},{q="Wer ist der von Tarrel erwähnte „Langzopf“?",a="Langzopf ist eine zwergische Autoritätsperson, die versprochen hatte, Kundschafter zur Whelgar Excavation Site zu entsenden, sollten die Kommunikationswege abreißen. Dies veranlasst Tarrel zu der Annahme, dass jeder fähige Abenteurer, der eintrifft, um zu helfen, auf Langzopfs Befehl geschickt wurde.",al={"wer ist langzopf","langzopf kundschafter"}},{q="Kann man sich der Ausgrabungsstätte gefahrlos nähern?",a="Nein. Die Stätte liegt in der gefährlichen Wildnis des Sumpflands, und was auch immer die wöchentlichen Depeschen des Trupps unterbrochen hat, stellt eine aktive Bedrohung für jeden dar, der die Ausgrabung erreicht.",al={"ist die ausgrabung sicher","whelgar gefährlich"}}},fx={d2e8931d={q="Warum benötigt Tarrel Felsweber einen Abenteurer, um das Ausgrabungsteam zu finden?",a="Tarrel ist im Hafen von Menethil voller Sorge, aber er ist kein bewaffneter Forscher oder Soldat, der allein durch das gefährliche Marschland reisen könnte. Örtliche Offizielle wie Langzopf versprachen, einen erfahrenen Späher zu entsenden, um die Stille vom Ausgrabungsort zu untersuchen. Als Ihr ankommt, betrachtet Tarrel Euch als die fähige Hilfe, die ihm versprochen wurde, um der Wildnis zu trotzen und nach seiner Frau zu sehen.",al={"warum schickt er mich","warum keine wachen","warum kann tarrel nicht gehen"}}},fp="32,409,17.523.0,15.470.0,25.266.0,25.231.0,37.153.0,36.176.0,43.236.0,40.174.0"}
P.entries["quest:306"] = {n="Auf der Suche nach dem Ausgrabungstrupp",s="Dieser Auftrag überbringt die Nachricht von einem verheerenden Dinosaurierangriff bei Whelgars Ausgrabungsstätte zurück in den Hafen von Menethil. Merrin Felsweber verfasst einen eilig geschriebenen Brief, um ihren besorgten Ehemann Tarrel zu beruhigen, während sie schildert, wie die Expedition überrannt wurde.",h="Dieser Auftrag überbringt die Nachricht von einem verheerenden Dinosaurierangriff bei Whelgars...",kw={"ausgrabung","hafen von menethil","merrin felsweber","gescheckte raptoren","ormer","tarrel felsweber","sumpfland","whelgar"},ang={["faction:Alliance"]="Die Versorgungswege und Grenzlandprojekte im Sumpfland bleiben extrem anfällig für wilde Bestien und erfordern ständige Wachsamkeit von Reisenden der Allianz.",["race:Dwarf"]="Die Katastrophe bei der Ausgrabung trifft die archäologischen Ambitionen der Zwerge empfindlich und verdeutlicht die Gefahren, denen die Forscher von König Magni fernab der Sicherheit von Eisenschmiede ausgesetzt sind."},sec={{t="Eine Nachricht aus den Ruinen",b="Nachdem die Überreste des Grabungsteams ausfindig gemacht wurden, die sich nahe dem Bergrücken über der Ausgrabungsstätte kauern, liefert Merrin Felsweber einen eiligen Bericht. Das Freilegen seltener Artefakte neben gewaltigen prähistorischen Fossilien erwies sich als fatal, als Rudel einheimischer gescheckter Raptoren über die Ausgräber herfielen. Die plötzliche Wildheit kostete die meisten Arbeiter das Leben und schnitt die Überlebenden von der Zivilisation ab."},{t="Eine bittere Erleichterung",b="Die Rückkehr in den Hafen von Menethil bringt Tarrel Felsweber düsteren Trost. Zu wissen, dass seine Frau und mindestens zwei Gefährten dank des Mutes eines Verteidigers namens Ormer überlebt haben, beruhigt sein Gemüt, auch wenn das Abschlachten so vieler Kollegen schwer auf dem Pioniergeist der Stadt lastet."}},faq={{q="Was ist mit dem Grabungsteam im Sumpfland geschehen?",a="Beim Freilegen seltener Artefakte und gewaltiger uralter Knochen wurde die Zwergenexpedition überrascht und von territorialen gescheckten Raptoren überrannt. Die meisten Ausgräber wurden getötet, sodass nur eine Handvoll Überlebender auf den Klippen oberhalb der Grabungsstätte gefangen blieb.",al={"was geschah mit der ausgrabungsstätte","katastrophe ausgrabung sumpfland","warum scheiterte die ausgrabung"}},{q="Wer hat Merrin Felsweber gerettet?",a="Merrin verdankt ihre Rettung einem tapferen Verteidiger namens Ormer, der die Raptoren abwehrte und sie sowie den Prospektor in relative Sicherheit auf den Bergrücken geleitete, als der untere Bereich überrannt wurde.",al={"wer rettete merrin","ormer rockweaver","wer ist ormer"}},{q="Wer ist Tarrel Felsweber?",a="Tarrel Felsweber ist Merrins Ehemann, der im Hafen von Menethil stationiert ist. Beunruhigt über das Ausbleiben von Nachrichten von der Ausgrabungsstätte suchte er nach Reisenden, um ihren Verbleib zu untersuchen.",al={"wer ist tarrel","aufenthaltsort tarrel felsweber"}},{q="Wo befindet sich die Ausgrabungsstätte?",a="Die Ausgrabungsstätte liegt im Landesinneren im südlichen Bereich des Sumpflands, östlich des Hafens von Menethil nahe dem Fuß der Bergkämme von Eisenschmiede.",al={"wo ist die ausgrabung","ort whelgars ausgrabungsstätte"}},{q="Wonach hat die Expedition gegraben?",a="Unter der Leitung von Zwergenprospektoren grub das Team nach seltenen unterirdischen Artefakten und großen prähistorischen Fossilien, die in den Sümpfen begraben lagen.",al={"wonach wurde gegraben","artefakte der ausgrabung"}},{q="Gibt es neben Merrin noch weitere Überlebende?",a="Ja, Merrin erwähnt, dass Ormer und der leitende Prospektor den Raptoren zusammen mit ihr entkommen konnten, womit die Zahl der bekannten Überlebenden bei drei liegt.",al={"wer hat noch überlebt","überlebende der ausgrabung"}}},fx={["2f0bde8f"]={q="Warum möchte Merrin Felsweber, dass Ihr ihren Brief überbringt?",a="Merrin möchte ihren Ehemann Tarrel beruhigen, dass sie den brutalen Angriff auf den Ausgrabungsort überlebt hat. Die Raptoren haben ihr Lager überrannt und viele der Archäologen getötet, wodurch Merrin, Ausgrabungsleiter Whelgar und Ormer in einem provisorischen Unterschlupf gefangen sind. Da sie selbst nicht durch die Bestien durchbrechen können, vertraut sie Euch ihren Brief an, damit Tarrel erfährt, dass sie am Leben sind, und das schreckliche Schicksal der Expedition versteht.",al={"warum merrins brief überbringen","merrin felsweber motiv","warum die notiz an tarrel liefern"}},f4e86a28={q="Warum kann Merrin Felsweber die Notiz nicht selbst überbringen?",a="Merrin und ihre Mitüberlebenden sind abgeschnitten und werden von aggressiven gesprenkelten Raptoren bedrängt. Wenn sie ihren Unterschlupf verlassen würden, wären sie den wilden Bestien ausgesetzt, die bereits den Rest des Ausgrabungsteams zerfleischt haben. Als ein körperlich fähiger Reisender, der in der Lage ist, sich durch die Sümpfe und Raptorrudel zu schlagen, könnt Ihr die Nachricht sicher zurück zum Hafen von Menethil tragen, wenn sie es nicht können.",al={"warum braucht merrin mich","warum kann merrin nicht vom ausgrabungsort weg","warum braucht merrin hilfe"}}},fp="32,245,24.370.0,15.277.0,53.256.0,28.174.0,25.183.0,30.142.0,36.148.0,40.145.0"}
P.entries["quest:3065"] = {n="Einfache Schrifttafel",s="Einfache Schrifttafel ist ein einleitender Übergangsritus für angehende Krieger, die das Tal der Prüfungen betreten. Nachdem Ihr Euren Mut gegen einheimische Bestien unter Beweis gestellt habt, wird sie Euch überreicht und weist Euch den Weg zu Frang, dem hiesigen Veteranen, dessen Aufgabe es ist, rohe Muskelkraft zu kriegerischer Disziplin zu formen.",h="Einfache Schrifttafel ist ein einleitender Übergangsritus für angehende Krieger, die das Tal der Prüfungen...",kw={"durotar","frang","gornek","einfache schrifttafel","der höhlenbau","das tal der prüfungen","krieger"},ang={["class:Warrior"]="Diese Aufforderung markiert Euren allerersten Schritt auf dem Pfad des Kriegers in Durotar und führt Euch direkt zu Frang, um grundlegende Haltungen und Schläge zu erlernen.",["faction:Horde"]="Die Horde verlässt sich auf einen steten Strom gestählter Frontkämpfer, um Durotars gefährdete Grenzen gegen Zentauren, Borstennacken und menschliche Eindringlinge zu sichern.",["race:Troll"]="Dunkelspeere, die im Tal trainieren, mögen Frangs schroffe Bemerkungen über ihre Vorliebe für Speere statt orcischer Äxte zu hören bekommen, auch wenn er alles respektiert, was tötet."},sec={{t="Ein Ruf zu den Waffen",b="Nachdem Ihr bewiesen habt, dass Ihr Euch gegen die gescheckten Eber des Tals behaupten könnt, überreicht Gornek Euch ein Pergament, das eigens für Euch bestimmt ist. In der rauen Umgebung von Durotar lässt die Horde ihre Kämpfer nicht lange ohne Führung. Die Schrifttafel dient als Aufforderung, Frang aufzusuchen, den Kriegerlehrer, der vor dem Höhlenbau stationiert ist."},{t="Im Schatten des Höhlenbaus",b="Frang sucht Schutz im Schatten direkt vor dem Höhlenbau und beobachtet, wie die Rekruten aus dem roten Buschland eintreffen. Er mustert die Neulinge mit erfahrenem Blick und ist bereit, ihnen die Grundlagen zu vermitteln – sei es das Schwingen einer schweren Axt oder das Führen eines Speers –, um sicherzustellen, dass jeder neue Soldat die verwundbaren Siedlungen der jungen Horde verteidigen kann."}},faq={{q="Was ist die Einfache Schrifttafel?",a="Es ist eine einleitende Anweisung, die jungen Kriegern im Tal der Prüfungen überreicht wird. Gornek gibt sie weiter, um kriegerische Rekruten zu Frang zu leiten, dem ansässigen Kriegerlehrer.",al={"einfache schrifttafel","was ist diese schrifttafel","kriegernotiz"}},{q="Wer schickt die Schrifttafel?",a="Die Nachricht stammt von Frang, dem erfahrenen Kriegerlehrer, der sich vor dem Höhlenbau aufhält und nach aufstrebenden Kämpfern Ausschau hält.",al={"wer schrieb die schrifttafel","wer schickte einfache schrifttafel"}},{q="Wo kann ich Frang finden?",a="Frang ist vor dem Höhlenbau im Tal der Prüfungen postiert, wo er unter den Felsvorsprüngen Schutz vor der Wüstensonne sucht.",al={"frang standort","wo ist frang","kriegerlehrer finden"}},{q="Warum erwähnt Frang Speere und Äxte?",a="Frang bemerkt die unterschiedlichen Kampfstile unter den Rekruten der Horde. Während Orcs schwere Hackmesser wie große Äxte bevorzugen, greifen Trolle und andere Kämpfer oft zu Speeren und leichteren Stangenwaffen – beides erweist sich im Kampf als nützlich.",al={"frang speer zitat","warum speere"}},{q="Erhalten andere Klassen diese Quest?",a="Nein. Die Einfache Schrifttafel wird ausschließlich Kriegern überreicht. Andere Klassen erhalten ihr eigenes Pergament, eine Rune oder eine Schriftrolle, die sie zu ihren jeweiligen Mentoren führt.",al={"ist einfache schrifttafel nur fuer krieger","klassenquests im tal der pruefungen"}},{q="Welchem Zweck dient der Höhlenbau?",a="Der Höhlenbau ist ein geschützter Höhlenkomplex im Tal der Prüfungen, in dem sich Lehrer, Vorräte und rastende Rekruten fernab der sengenden Hitze und umherstreifenden Bestien sammeln.",al={"was ist der hoehlenbau","der hoehlenbau durotar"}}},fp="13,277,17.338.0,26.318.0,26.170.0,21.131.0,23.121.0,39.213.0,32.159.0,31.164.0"}
P.entries["quest:307"] = {n="Schmutzige Pfoten",s="Schmutzige Pfoten ist eine Aufgabe von Gebirgsjäger Sturmlanze, um wertvolle Ausrüstung aus der verseuchten Silberbachmine zu bergen. Obwohl sie an Erz erschöpft war, wurde die Mine von der Miners' League als Depot umfunktioniert, bevor eindringende Kobolde die Tunnel überrannten. Die zwergischen Autoritäten wollen ihre robusten Werkzeuge zurückholen, bevor die Gebirgsjäger eine zerstörerische Säuberung des Ortes einleiten.",h="Schmutzige Pfoten ist eine Aufgabe von Gebirgsjäger Sturmlanze, um wertvolle Ausrüstung aus der verseuchten...",kw={"schmutzige pfoten","kobold","loch modan","bergbauausruestung","miners' league","gebirgsjäger sturmlanze","silberbachmine","thelsamar"},ang={["faction:Alliance"]="Da die zwergischen Verteidigungskräfte in ganz Khaz Modan dünn gesät sind, stellt die Räumung von Nachschubdepots sicher, dass die lebenswichtige Infrastruktur für die Allianz offen bleibt.",["profession:Mining"]="Bergleute wissen den Wert erstklassiger zwergischer Ausrüstung und die Tragödie zu schätzen, wenn funktionstüchtige Werkzeuge in den Pfoten von Höhlenungeziefer verrotten.",["race:Dwarf"]="Für Zwerge ist es eine Beleidigung, mitansehen zu müssen, wie primitive Kobolde die Handwerkskunst der Miners' League entweihen – ein Affront, der nach rascher Rückforderung und scharfem Stahl verlangt."},sec={{t="Ein erschöpftes Depot",b="Die Silberbachmine, eingebettet in die Hügel des nördlichen Loch Modan östlich von Station Algaz, brachte vor langer Zeit ihre letzten Silberadern hervor. Anstatt den unterirdischen Komplex aufzugeben, funktionierte die zwergische Miners' League die trockenen Schächte zu einem sicheren Lagerdepot für überschüssige Ausgrabungsausrüstung, Spitzhacken und Bereitstellungsmaterialien um. Robuste unterirdische Tunnel bieten in Khaz Modan natürliche Lagerstätten, vorausgesetzt, sie bleiben bemannt und gegen die Wildnis abgeriegelt."},{t="Pfoten im Depot",b="Die Wachsamkeit der Zwerge in ganz Loch Modan hat nachgelassen, und Kobolde nutzten die Gelegenheit, um in die Schächte einzudringen. Angelockt von den dunklen Tunneln und den glänzenden Eisenwerkzeugen, die zurückgelassen wurden, beanspruchten die Plagegeister den Ort schnell als Bau für sich. Gebirgsjäger Sturmlanze brennt darauf, ein Kontingent von Kriegern in die Stollen zu führen, um sie auszulöschen, doch schwere Stiefel und weite Hiebe würden die Kisten zertrümmern. Ein Abenteurer muss sich hineinschleichen oder hineinkämpfen, um die Vorräte der Liga zu bergen, bevor der Großangriff beginnt."}},faq={{q="Warum wurde Ausrüstung in der Mine zurückgelassen, wenn sie bereits erschöpft war?",a="Die Miners' League wandelte die Silberbachmine in ein zentrales Lagerdepot um, nachdem das Erz versiegt war. Unterirdische Zwergentunnel bieten solide, trockene Unterkünfte, um sperrige Werkzeuge und Vorräte zu lagern, bis sie an anderer Stelle gebraucht werden.",al={"warum ist ausrüstung in der silberbachmine","warum werkzeuge in mine","miners league depot"}},{q="Warum säubert Gebirgsjäger Sturmlanze die Mine nicht selbst?",a="Stormpike hat den Befehl zu warten. Zudem möchte die Miners' League, dass ihre Ausrüstung zuvor herausgeholt wird; Krieger der Wache, die in die engen, dunklen Schächte stürmen, würden die empfindlichen, in Kisten verpackten Werkzeuge in der Hitze des Gefechts wahrscheinlich zertrümmern.",al={"warum geht stormpike nicht","warum warten gebirgsjaeger","stormpike quest grund"}},{q="Wo befindet sich die Silberbachmine?",a="Die Mine befindet sich im nördlichen Loch Modan, östlich von Station Algaz und südwestlich des Steinwerkdamms.",al={"silberbachmine standort","wo ist silberbachmine","wo schmutzige pfoten stattfindet"}},{q="Was macht zwergische Werkzeuge für Kobolde so interessant?",a="Kobolde sind manische unterirdische Aasfresser und Sammler. Sie begehren Metallspitzhacken, Schaufeln, Kerzen und fertige Eisenwaren, die ihnen ihr ständiges Graben erleichtern, was ein Lager voller zwergischer Werkzeuge zu einer unwiderstehlichen Beute macht.",al={"warum wollen kobolde ausruestung","kobolde werkzeugdiebstahl","kobolde silberbachmine"}},{q="Ist es gefährlich, die Silberbachmine allein zu erkunden?",a="Die engen Gänge der Mine und die dichten Ansammlungen von Kobolden machen sie gefährlich. Gebirgsjäger Sturmlanze warnt ausdrücklich davor, dass einsame Abenteurer Gefährten mitbringen sollten.",al={"ist schmutzige pfoten schwer","silberbachmine schwierigkeit","kann ich schmutzige pfoten solo machen"}},{q="Wem gehören die in der Mine gelagerten Vorräte?",a="Die Vorräte gehören der Miners' League von Eisenschmiede, der Handelsgilde, die für den Steinbruchbau, den Bergbau und die Verwaltung unterirdischer Ressourcen im gesamten Zwergenreich zuständig ist.",al={"wem gehoert die ausruestung","miners league kisten","wer leitet die miners league"}}},fx={c638d192={q="Warum möchte Gebirgsjäger Sturmlanze, dass die Minenarbeiterausstattung geborgen wird?",a="Die Bergarbeiterliga baute die erschöpfte Silberbachmine in ein Lagerhaus um, aber Kobolde haben die Tunnel befallen und die Ausrüstung beschlagnahmt. Während die Gebirgsjäger planen, das Ungeziefer bald zu vertreiben, besteht die Liga darauf, dass ihre wertvollen Werkzeuge zuerst geborgen werden. Sturmlanze schickt Euch vor der militärischen Säuberung hinein, damit die groben Zwergenkrieger beim anstehenden Angriff nicht die empfindliche Ausrüstung zertrümmern.",al={"warum will sturmlanze die ausrüstung","sturmlanze filthy paws motiv","warum minenarbeiterausstattung bergen"}},e40e35ce={q="Wofür wird die Minenarbeiterausstattung verwendet?",a="Die Ausrüstung besteht aus hochwertigen zwergischen Werkzeugen und Vorräten, die der Bergarbeiterliga gehören. Nachdem die Silberbachmine kein Erz mehr förderte, nutzte die Liga ihre Kammern als sicheres Depot, um Arbeitsausrüstung zu lagern. Die Liga muss diese wertvollen Gerätschaften intakt zurückerhalten, bevor der Kampf sie ruiniert.",al={"was ist minenarbeiterausstattung","zweck der minenarbeiterausstattung","wozu die zwergischen werkzeuge"}},["31be8455"]={q="Wer hat die Silberbachmine übernommen?",a="Ein Rudel Kobolde hat die alten Minentunnel überrannt. Von Natur aus von unterirdischen Behausungen und glänzendem Metall angezogen, zogen diese Plagegeister in die erschöpften Schächte und begannen, die gelagerte Ausrüstung zu durchsuchen und zwergische Werkzeuge mit ihren Pfoten zu beschmutzen.",al={"wer ist in der silberbachmine","filthy paws feinde","wer hat die mine übernommen"}}},fp="11,367,16.453.0,17.509.0,56.227.0,57.229.0,40.104.0,50.217.0,53.179.0,41.167.0"}
P.entries["quest:308"] = {n="Jarvens Ablenkung",s="Unten im Keller der Brauerei Donnerbräu findet sich die Wache Jarven Donnerbräu von Fässern umgeben, die er nicht anrühren darf. Voller Verlangen nach einem Schluck der Familienkunst bittet er einen vorbeikommenden Abenteurer um einen Krug Donnerbier, um seine Sinne im Dienst zu schärfen.",h="Unten im Keller der Brauerei Donnerbräu findet sich die Wache Jarven Donnerbräu von Fässern umgeben, die er...",kw={"keller","brauerei","jarvens ablenkung","dun morogh","jarven donnerbräu","kharanos","donnerbier"},ang={["class:Rogue"]="Einen Wachposten mit starkem Alkohol abzulenken, ist ein uralter Trick des Gewerbes – selbst wenn Jarven freudig selbst um die Ablenkung bittet.",["race:Dwarf"]="Jeder Zwerg versteht die Qual, Wache neben Fässern legendären Biers zu halten, ohne sich auch nur einen einzigen Schluck gönnen zu dürfen."},sec={{t="Eine durstige Wache im Dienst",b="Jarven Donnerbräu hat die Aufgabe, die tiefen Vorratslager der Brauerei Donnerbräu in Kharanos zu bewachen. Obwohl er vom feinsten Starkbier in Dun Morogh umgeben ist, steht er unter dem strengen Befehl der Familie, sich während der Wache nicht an den Beständen zu bedienen. Die Versuchung erweist sich als zu groß und veranlasst ihn, vorbeireisende Wanderer darum zu bitten, ihm ein Glas des kräftigen Donnerbiers von den Zapfhähnen oben zu holen."},{t="Ein zweifelhafter Schärfer",b="Jarven beharrt darauf, dass ein guter Schluck seine Sinne nur schärfen und seine Wachsamkeit stärken wird. Ob es klug ist, einer diensthabenden Wache nachzugeben, bleibt eine offene Frage, doch unter den wettergegerbten Zwergen von Dun Morogh wird kaum jemand einem Donnerbräu verübeln, das weltberühmte Gebräu seiner eigenen Sippe kosten zu wollen."}},faq={{q="Wer ist Jarven Donnerbräu?",a="Jarven ist ein Mitglied der angesehenen Familie Donnerbräu und unten im Keller der Brauerei Donnerbräu in Kharanos stationiert, um über die gelagerten Fässer zu wachen.",al={"wer ist jarven","jarven lore","wache im keller"}},{q="Warum braucht Jarven jemanden, der ihm Bier bringt?",a="Jarven steht unter dem strengen Befehl seiner Familie, während seiner Wache nicht aus den Kellerbeständen zu trinken. Um die Regeln zu umgehen, ohne die versiegelten Fässer aufzubrechen, bittet er einen Außenstehenden, ihm einen frischen Krug von oben zu bringen.",al={"warum darf jarven nicht trinken","jarven bier quest","warum alkohol besorgen"}},{q="Wo ist Donnerbier zu finden?",a="Donnerbier wird direkt oben in der Hauptschankstube der Brauerei Donnerbräu in Kharanos ausgeschenkt und vom Gastwirt sowie von Barkeepern verkauft.",al={"donnerbier bekommen","wo gibt es donnerbier","donnerbier kaufen"}},{q="Wo befindet sich die Brauerei Donnerbräu?",a="Die Brauerei dient als das belebte zentrale Gasthaus von Kharanos, eingebettet im verschneiten Herzen von Dun Morogh, gleich unterhalb des Berges von Eisenschmiede.",al={"brauerei kharanos","keller brauerei donnerbräu","wo ist jarven"}},{q="Warum ist Donnerbräu-Bier so berühmt?",a="Gebraut vom Clan der Donnerbräu, sind ihre Starkbiere und Ales in ganz Khaz Modan und darüber hinaus für ihre außergewöhnliche Wucht, ihren Geschmack und ihren zwergischen Biss legendär.",al={"donnerbräu ruf","was ist donnerbier"}},{q="Sorgt es für Ärger, wenn man Jarven betrunken macht?",a="Jarven behauptet, das Bier schärfe seine Sinne, anstatt sie zu trüben, auch wenn es seine Aufmerksamkeit gewiss von jedem ablenkt, der im unteren Vorratslager herumstöbert.",al={"jarven betrunken folgen","was passiert nach jarvens ablenkung"}}},fx={a200e5d8={q="Warum möchte Jarven Donnerbräu ein Fass Donnerbier?",a="Jarven ist damit beauftragt, die Keller zu bewachen, die von Fässern mit zwergischem Spirituosen umgeben sind, aber strenge Befehle untersagen es ihm, die Bestände in seiner Obhut anzurühren. Da er sich nach einem Drink sehnt, um seinen Verstand zu schärfen und die lange Wache zu überstehen, braucht er jemanden Diskreten, der ihm ein wenig von Thunderbrews feinstem Gebräu zusteckt, damit er nachgeben kann, ohne offen gegen die Disziplin zu verstoßen.",al={"warum will jarven bier","jarven motiv","warum trinkt jarven"}},["8c39bfa0"]={q="Wofür wird das Donnerbier verwendet?",a="Das Fass mit Donnerbier dient als starke persönliche Erfrischung, um den Durst von Jarven Donnerbräu zu stillen. Während er tief in den Kellern der Brennerei Wache schiebt, verlässt er sich darauf, dass Ihr es von den Zapfhähnen oben holt, damit er trinken kann, ohne seinen Posten aufzugeben oder die gelagerten Vorräte zu manipulieren.",al={"wofür ist das donnerbier","verwendung donnerbier","warum donnerbier besorgen"}}},fp="18,257,23.385.0,19.276.0,26.163.0,46.215.0,27.133.0,44.142.0,33.151.0,44.149.0"}
P.entries["quest:3082"] = {n="Geätzte Schrifttafel",s="Geätzte Schrifttafel ist eine einführende Jägerquest, die im Tal der Prüfungen vergeben wird, nachdem die ersten Prüfungen abgeschlossen wurden. Sie weist angehende Trolljäger an, sich bei der Jägerausbilderin Jen'shan zu melden, um ihre formale Ausbildung in der Wildnis zu beginnen.",h="Geätzte Schrifttafel ist eine einführende Jägerquest, die im Tal der Prüfungen vergeben wird, nachdem die...",kw={"dunkelspeer","durotar","geätzte schrifttafel","gornek","jäger","jen'shan","das tal der prüfungen"},ang={["class:Hunter"]="Diese Quest markiert Euren offiziellen Eintritt in die Reihen der Jäger der Horde und festigt Eure Bindung zur Wildnis und Eurer örtlichen Ausbilderin.",["faction:Horde"]="Der Austausch zwischen Jen'shan und jungen Rekruten zeigt, wie die Horde die ausgeprägten kulturellen Stärken von Orcs und Trolls vereint, um ihr gemeinsames Überleben zu sichern.",["race:Orc"]="Für junge Orcs bedeutet der Erhalt der Tafel, dass sie verfeinertes Anschleichen und Fährtenlesen in der Wildnis von ihren Dunkelspeer-Verbündeten erlernen, was ihre traditionelle Kriegerstärke ergänzt.",["race:Troll"]="Jen'shan ist stolz darauf, wie das Jagdwissen der Dunkelspeer dazu beigetragen hat, die Horde auf Kalimdor zu festigen, was die lebenswichtige Rolle unterstreicht, die die Traditionen der Trolls für das Überleben ihrer Verbündeten spielen."},sec={{t="Ein Ruf zur Jagd",b="Nachdem sie ihr frühes Können gegen die örtlichen Eber im Höhlenbau unter Beweis gestellt haben, werden angehende Jäger von Gornek mit einer eingravierten Nachricht abgefangen. Die Steintafel trägt das Zeichen von Jen'shan, einer erfahrenen Trolljägerin, die in der Nähe stationiert ist. Gornek überreicht sie als Zeichen dafür, dass der junge Jäger genug Schneid bewiesen hat, um die Aufmerksamkeit erfahrener Überlebenskünstler auf sich zu ziehen, was den Übergang von grundlegendem, rohem Überlebenskampf hin zur disziplinierten Ausbildung in der Wildnis markiert."},{t="Das Teilen des Überlebenswissens",b="Wenn Ihr Euch bei Jen'shan meldet, spricht die Trollausbilderin über die tiefe Geschichte zwischen Orcs und Trolls innerhalb der Horde. Während die Orcs für ihre Traditionen als Krieger und Schamanen bekannt waren, brachten die Dunkelspeertrolle altes Wissen über das Anschleichen, Fährtenlesen und Überleben mit, das den Orcs half, das Leben auf Azeroth zu meistern. Jen'shan sieht die Ausbildung neuer Jäger als einen fortwährenden Austausch von Überlebenswissen an, der die verbündeten Völker durch gemeinsamen Respekt vor der Jagd enger miteinander verbindet."}},faq={{q="Wer schickt die Geätzte Schrifttafel?",a="Die Jägerausbilderin Jen'shan schickt den beschrifteten Stein, der direkt von Gornek überbracht wird, sobald Ihr Euch im Tal der Prüfungen bewährt habt.",al={"wer schrieb geätzte schrifttafel","absender der schrifttafel","wer gab mir diese schrifttafel"}},{q="Wo ist Jen'shan zu finden?",a="Jen'shan befindet sich im nördlichen Bereich des Tals der Prüfungen in Durotar, positioniert bei den anderen Klassenausbildern in der Nähe vom Höhlenbau.",al={"standort von jen'shan","wo ist jenshan","jenshan finden"}},{q="Warum unterrichten Trollausbilder hier Orc-Jäger?",a="Jen'shan sagt, dass sich die Horde an die Trolls wandte, um Jagdwissen zu erlangen, während sie auf Azeroth ums Überleben kämpfte. Die Orcs kannten bereits die Wege der Krieger und Schamanen, und beide Völker tauschen weiterhin ihre Fähigkeiten aus.",al={"warum troll-jägerausbilderin","troll unterrichtet orc","dunkelspeer jäger"}},{q="Was passiert nach dem Abgeben dieser Tafel?",a="Jen'shan akzeptiert Euch als ihre Schülerin oder ihren Schüler und bietet an, Euch in den grundlegenden Techniken, Schüssen und Überlebenspraktiken zu unterweisen, die von Jägern der Horde erwartet werden, während Ihr Erfahrung sammelt.",al={"was kommt nach der schrifttafel","hintergrundwissen belohnung geätzte schrifttafel","folgequest für jenshan"}},{q="Welche Voraussetzung muss erfüllt sein, bevor man diese Tafel erhält?",a="Ihr müsst zuerst die erste Aufgabe Scharfe Zähne für Gornek abschließen, indem Ihr gefleckte Eber erlegt, um Eure grundlegende Ausdauer zu beweisen.",al={"voraussetzung für schrifttafel","wie schalte ich geätzte schrifttafel frei","voraussetzungen für geätzte schrifttafel"}},{q="Kann jede Klasse diese Quest abschließen?",a="Nein, diese Quest ist speziell für angehende Jäger, die ihre Reise im Tal der Prüfungen beginnen. Andere Klassen erhalten ihre eigenen, spezifischen Ausbildungsrufe von Gornek.",al={"wer kann geätzte schrifttafel erhalten","klassenanforderung für geätzte schrifttafel","ist das nur für jäger"}}},fp="13,237,21.438.0,23.469.0,28.147.0,28.135.0,45.195.0,42.172.0,62.121.0,34.168.0"}
P.entries["quest:3083"] = {n="Verschlüsselte Schrifttafel",s="Die Verschlüsselte Schrifttafel ist eine Vorladung, die Gornek an angehende Schurken überbringt, die im Tal der Prüfungen trainieren. Die in Geheimschrift verfasste Botschaft weist unerfahrene Beutelschneider an, sich zu Rwag zu begeben, dem verdeckten Agenten im Höhlenbau, der die Ausbildung der Schurken und die Verbindungen zur Shattered-Hand überwacht.",h="Die Verschlüsselte Schrifttafel ist eine Vorladung, die Gornek an angehende Schurken überbringt, die im Tal...",kw={"durotar","verschlüsselte schrifttafel","gornek","schurkenlehrer","rwag","shattered-hand","der höhlenbau","das tal der prüfungen"},ang={["class:Rogue"]="Diese Schrifttafel markiert Eure offizielle Einführung in die verdeckten Operationen von Durotar, bringt Euch in direkten Kontakt mit Eurem ersten Mentor Rwag und führt Euch an den feinen Einfluss der Shattered-Hand heran.",["race:Orc"]="Während die traditionelle Kultur der Orcs den offenen Kampf auf dem Schlachtfeld ehrt, spielen Orc-Schurken unter der modernen Horde eine unverzichtbare Rolle als Späher und Infiltratoren.",["race:Troll"]="Schurken der Dunkelspeere verbinden die Instinkte des Dschungelspurenlesens mit der von den Mentoren im Höhlenbau gelehrten Klingenkunst und sichern sich so ihren unauffälligen Nutzen unter ihren orcischen Verbündeten."},sec={{t="Eine verschlüsselte Vorladung",b="Sobald ein Initiant seinen Mut gegen die einheimische Tierwelt bewiesen hat, überreicht Gornek eine speziell für ihn zugestellte Verschlüsselte Schrifttafel. Statt in Klartext ist die Botschaft in Geheimschrift verfasst – eine Prüfung und Vorsichtsmaßnahme, die jenen angemessen ist, die sich den Künsten der Heimlichtuerei, des Giftes und der Täuschung widmen. Sie lädt den Rekruten ein, in den Höhlenbau hinabzusteigen, um Rwag zu treffen, den Ausbilder, der Schurken, Diebe und Beutelschneider für die Horde formt."},{t="Der Schatten der Hand",b="Nach dem Entziffern der Anweisungen und dem Betreten des Höhlenbaus treffen Initianten auf Rwag, einen Agenten, der mit der Shattered-Hand verbündet ist. Obwohl er neu rekrutierten Schurken versichert, dass die Gilde nicht jeden ihrer Atemzüge bestimmen wird, warnt er, dass die Hand ihn zur Rechenschaft ziehen wird, sollte ein Lehrling versagen. In einer jungen Nation, die von Feinden umgeben ist, verlässt sich die Horde stark auf lautlose Späher und flinke Beutelschneider, um Informationen zu sammeln und Bedrohungen aus den Schatten heraus zu beseitigen."}},faq={{q="Was ist der Zweck der Verschlüsselten Schrifttafel?",a="Sie dient als einleitende Vorladung für angehende Schurken im Tal der Prüfungen und weist sie an, ihren Klassenlehrer Rwag im Höhlenbau aufzusuchen.",al={"was macht die schrifttafel","zweck der verschluesselten schrifttafel","warum verschluesselte schrifttafel"}},{q="Wer überbringt dem Spieler die Schrifttafel?",a="Gornek, der Aufseher der Prüfungen im Tal, überreicht Euch die Schrifttafel, sobald Ihr Eure erste Kampfprüfung durch das Töten von Fleckschweinen abgeschlossen habt.",al={"wer gibt die verschluesselte schrifttafel","schrifttafel questgeber","gornek schrifttafel"}},{q="Wo ist Rwag zu finden?",a="Rwag befindet sich tief im Höhlenbau, dem dunklen Höhlenkomplex an den nördlichen Klippen des Tals der Prüfungen.",al={"rwag aufenthaltsort","wo ist rwag","rwag finden"}},{q="Was ist 'die Hand', die Rwag erwähnt?",a="Rwag bezieht sich auf die Shattered-Hand, das verdeckte Netzwerk und die Gilde aus Meuchelmördern, Spionen und Schurken im Dienste der Horde von Kriegshäuptling Thrall.",al={"was ist die hand","shattered-hand rwag","wer ist die hand"}},{q="Warum ist die Schrifttafel in einer Geheimschrift verfasst?",a="Die Verschlüsselung stellt sicher, dass heikle Schurkenangelegenheiten und die Identitäten ihrer Kontaktmänner vor neugierigen Blicken verborgen bleiben, und prüft zugleich die Fähigkeit des Initianten, mit diskreten Botschaften umzugehen.",al={"warum verschluesselt","warum geheimschrift","schurken schrifttafel code"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Die Verschlüsselte Schrifttafel ist ausschließlich für Schurken der Trolle reserviert, die ihre Reise im Tal der Prüfungen beginnen.",al={"ist verschluesselte schrifttafel nur fuer schurken","koennen krieger die verschluesselte schrifttafel annehmen","schrifttafel klassenbeschraenkung"}}},fp="16,270,15.438.0,22.457.0,44.149.0,38.142.0,24.122.0,37.134.0,49.177.0,35.115.0"}
P.entries["quest:3084"] = {n="Mit Runen beschriftete Schrifttafel",s="Die Mit Runen beschriftete Schrifttafel ist ein Vorladungsschreiben, das angehenden Schamanen überreicht wird, die im Tal der Prüfungen trainieren. Es wurde von Shikrik verfasst und lädt vielversprechende Initianden dazu ein, ihre formelle Ausbildung in der Zwiesprache mit den Geistern und der Beherrschung der Elementarkräfte von Erde, Feuer, Wasser und Luft zu beginnen.",h="Die Mit Runen beschriftete Schrifttafel ist ein Vorladungsschreiben, das angehenden Schamanen überreicht...",kw={"durotar","elemente","gornek","schamane","shikrik","schrifttafel","thrall","das tal der prüfungen"},ang={["class:Shaman"]="Diese Schrifttafel markiert Eure offizielle Aufnahme auf den Pfad der Schamanen und trägt Euch auf, das Gleichgewicht der Elementarkräfte zu wahren und als Leuchtfeuer der Führung durch die Ahnen zu dienen.",["faction:Horde"]="Der Schamanismus ist das moralische und spirituelle Rückgrat der neuen Horde und dient als Kompass für Ehre und Gleichgewicht im rauen Grenzland.",["race:Orc"]="Die Schrifttafel spiegelt die moderne Rückkehr der Orcs zum Schamanismus der Ahnen wider, die von Thrall vorangetrieben wurde, und lässt das finstere Hexenmeister-Erbe der dämonischen Vergangenheit hinter sich.",["race:Troll"]="Dunkelspeere, die den Schamanismus praktizieren, finden mit Orc-Mentoren wie Shikrik eine gemeinsame Basis, indem sie ihre Zwiesprache mit den Ahnen mit den geteilten Elementartraditionen der Horde verbinden."},sec={{t="Ein Ruf an die Geister",b="Nachdem sie ihre anfängliche Disziplin auf den staubigen Übungsplätzen des Tals der Prüfungen unter Beweis gestellt haben, erhalten angehende Schamanen von Gornek eine behauene Steintafel. Die darauf befindlichen Runen dienen als Einladung von Shikrik, der örtlichen Schamanenlehrerin, und signalisieren, dass der Initiand bereit ist, über den einfachen körperlichen Kampf hinauszublicken und auf die tieferen Strömungen der natürlichen Welt zu achten."},{t="Geistige Führung in der neuen Horde",b="Der Schamanismus nimmt in der wiedererstarkten Horde einen heiligen Platz ein. Wie Shikrik lehrt, schöpfen Schamanen ihre Macht aus den vier Elementarkräften und ihre Stärke aus den Geistern der Ahnen. Dem Vorbild von Kriegshäuptling Thrall nacheifernd, wird von Schamanen erwartet, dass sie ihren Gemeinschaften als spirituelle Führer und Bollwerke der Weisheit dienen und den Siedlungen Schutz bieten, die in ganz Durotar Fuß fassen."}},faq={{q="Was ist die Mit Runen beschriftete Schrifttafel?",a="Es handelt sich um eine beschriftete Steintafel, die Schamanenneulingen im Tal der Prüfungen von Gornek überreicht wird. Sie enthält eine Vorladung der Schamanenlehrerin Shikrik, die den jungen Abenteurer dazu auffordert, seine Ausbildung in den spirituellen und elementaren Künsten offiziell zu beginnen.",al={"mit runen beschriftete schrifttafel","schrifttafel gegenstand","schamanen schrifttafel"}},{q="Wer ist Shikrik?",a="Shikrik ist die Schamanenlehrerin, die nahe dem Eingang des Höhlenbaus im Tal der Prüfungen stationiert ist. Sie leitet neue Schamanen der Orcs und Trolle dabei an, die Elemente zu meistern und ihre Pflicht als geistige Anführer innerhalb der Horde zu verstehen.",al={"shikrik","wer ist shikrik","schamanenlehrerin tal der prüfungen"}},{q="Warum beruft sich Shikrik auf Thrall, wenn sie zu neuen Schamanen spricht?",a="Kriegshäuptling Thrall führte die Wiederbelebung des Schamanismus der Ahnen nach der dämonischen Verderbnis der Alten Horde an. Shikrik verweist auf Thrall als das vollkommene Beispiel für die Pflicht eines Schamanen: das Gleichgewicht der Elemente zu wahren und zugleich sein Volk zu leiten und zu beschützen.",al={"warum thrall","shikrik erwähnt thrall"}},{q="Wo befindet sich Shikrik?",a="Shikrik steht direkt vor dem Eingang zum Höhlenbau auf der östlichen Seite des Tals der Prüfungen, bereit, Schamanenneulingen ihre ersten Techniken beizubringen.",al={"wo ist shikrik","shikrik finden"}},{q="Wer händigt die Schrifttafel aus?",a="Gornek, der die ersten Prüfungen der Neuankömmlinge im Tal der Prüfungen beaufsichtigt, übergibt die Schrifttafel, sobald ein Initiand seinen grundlegenden Mut bewiesen hat.",al={"wer gibt die schrifttafel","gornek schrifttafel"}},{q="Welche grundlegende Philosophie lehrt Shikrik?",a="Shikrik betont, dass die reine Macht eines Schamanen aus Feuer, Erde, Wasser und Luft geschöpft wird, während seine Ausdauer und Entschlossenheit den Geistern der Ahnen entspringen. Von Schamanen wird erwartet, dass sie jenen Siedlungen oder Kriegstrupps, denen sie sich anschließen, Weisheit und Schutz bieten.",al={"shikrik philosophie","schamanenlehren"}}},fp="21,286,21.360.0,37.362.0,34.234.0,15.221.0,60.244.0,25.150.0,25.154.0,40.242.0"}
P.entries["quest:3085"] = {n="Geheiligte Schrifttafel",s="Eine einfache Vorladung, die angehenden Priestern im Tal der Prüfungen nach ihrer ersten Kraftprobe überreicht wird. Die beschriftete Tafel weist junge Spiritualisten an Ken'jai, den ansässigen Troll-Priesterlehrer, der sie in die tiefere Zwiesprache mit den Geistern einführt.",h="Eine einfache Vorladung, die angehenden Priestern im Tal der Prüfungen nach ihrer ersten Kraftprobe...",kw={"dunkelspeer","durotar","gornek","geheiligte schrifttafel","ken'jai","priester","geister","der höhlenbau","das tal der prüfungen"},ang={["class:Priest"]="Diese Quest markiert den Übergang von profanen Prüfungen im Tal zur formellen spirituellen Unterweisung unter Ken'jai vor dem Höhlenbau.",["faction:Horde"]="Während die Horde Durotar besiedelt, stellen mystische Praktizierende sicher, dass spirituelle Riten und der Wille der Geister für das Wachstum der neuen Nation von zentraler Bedeutung bleiben.",["race:Troll"]="Die Schrifttafel betont die spirituellen Traditionen der Dunkelspeere und wendet sich den Geistern der Ahnen und den Loa zu, anstatt den dogmatischen Philosophien fremder Priesterschaften zu folgen."},sec={{t="Eine Nachricht von Ken'jai",b="Nachdem sie unter Gorneks Aufsicht ihren Mut gegen die hiesigen Eber bewiesen haben, erhalten junge Priester, die im Tal der Prüfungen trainieren, einen beschrifteten Stein, der als Geheiligte Schrifttafel bekannt ist. Die von Gornek überbrachte Botschaft trägt das Zeichen von Ken'jai, einem Mystiker der Dunkelspeere vor dem Höhlenbau, der über Neuankömmlinge wacht, die zum Pfad des Glaubens und der spirituellen Magie berufen sind."},{t="Zwiesprache mit den Geistern",b="Im Gegensatz zum Heiligen Licht, das von ihren menschlichen oder zwergischen Gegenstücken jenseits des Meeres praktiziert wird, steht das Priestertum unter den Dunkelspeeren der Horde im Zeichen der Zwiesprache mit den Geistern und Loa. Ken'jai heißt angehende Akolythen in Durotar willkommen, indem er sie daran erinnert, dass ihre Macht aus spiritueller Disziplin entspringt, und verspricht, sie erst dann in höheren Riten zu unterweisen, wenn ihr spirituelles Band gereift ist."}},faq={{q="Was ist die Geheiligte Schrifttafel?",a="Es ist eine beschriftete Nachricht, die vom Troll-Priesterlehrer Ken'jai an junge Priester gesendet wird, die im Tal der Prüfungen trainieren. Gornek behält sie ein, bis der Initiant seine grundlegenden Fähigkeiten im Tal unter Beweis stellt.",al={"was ist geheiligte schrifttafel","gegenstand geheiligte schrifttafel","schrifttafel lore"}},{q="Wer ist Ken'jai?",a="Ken'jai ist ein Priesterlehrer der Dunkelspeere, der vor dem Höhlenbau im Tal der Prüfungen stationiert ist. Er unterweist junge Initianten in der Zwiesprache mit den Geistern und leitet sie an, während sie lernen, sowohl heilende als auch schattenhafte spirituelle Künste zu wirken.",al={"kenjai","wer ist kenjai","ken'jai lehrer"}},{q="Warum beginnt ein Priester damit, gescheckte Eber zu bekämpfen?",a="Jeder Initiant im Tal der Prüfungen muss unabhängig von seiner Berufung grundlegende Selbstständigkeit und körperliche Überlebensfähigkeiten beweisen, bevor spezialisierte Ausbilder Zeit in sein Training investieren.",al={"warum eber toeten","verbindung cutting teeth"}},{q="Wie unterscheidet sich Ken'jais Priestertum vom Heiligen Licht?",a="Priester der Dunkelspeere rufen die Geister und die Loa an, anstatt zum Heiligen Licht der Kirchen der Menschen und Zwerge zu beten. Ken'jai legt Wert darauf, die Gunst dieser unsichtbaren Wesenheiten und die Harmonie mit ihnen zu wahren.",al={"trollpriester lore","horde priester","geister vs licht"}},{q="Wo ist der Höhlenbau?",a="Der Höhlenbau ist eine ausgehöhlte Höhlensiedlung im Tal der Prüfungen im südlichen Durotar, die als Knotenpunkt für Lehrer und Prüfungsmeister dient, welche die neuen Rekruten der Horde beaufsichtigen.",al={"der hoehlenbau durotar","wo ist der hoehlenbau","kenjai standort"}},{q="Können Orcs durch diese Quest Priester werden?",a="Nein. Im Tal der Prüfungen besitzen nur die Dunkelspeere die spirituellen Traditionen, die erforderlich sind, um unter Ken'jai als Priester ausgebildet zu werden. Die orcische Kultur stützt sich stattdessen auf Schamanismus und Hexenmeistermagie.",al={"orcpriester","koennen orcs priester sein","orc geheiligte schrifttafel"}}},fp="15,268,22.369.0,26.376.0,28.205.0,15.231.0,51.194.0,57.198.0,17.169.0,43.190.0"}
P.entries["quest:3086"] = {n="Glyphenschrifttafel",s="Glyphenschrifttafel ist eine einführende Klassenquest im Tal der Prüfungen, die sich an angehende Magier der Horde richtet. Sie wird nach dem Beweis der eigenen Stärke von Gornek übergeben und schickt junge Zauberwirker zu Mai'ah, einer Troll-Magierlehrerin, die vor dem Höhlenbau stationiert ist.",h="Glyphenschrifttafel ist eine einführende Klassenquest im Tal der Prüfungen, die sich an angehende Magier der...",kw={"arkan","durotar","glyphenschrifttafel","gornek","magier","mai'ah","der höhlenbau","das tal der prüfungen"},ang={["class:Mage"]="Diese Quest markiert Eure formelle Aufnahme in die Reihen der Hordenmagier, stellt Euch der Lehrerin des Tals vor und betont die disziplinierte Geisteshaltung, die zur Kontrolle roher Magie erforderlich ist.",["race:Orc"]="Orc-Magier existieren in der traditionellen Kultur der Orcs nicht, was dieses Training zu einer Gelegenheit für andere Völker der Horde wie die Dunkelspeer macht, ihr Handwerk auf den Übungsplätzen von Durotar zu verfeinern.",["race:Troll"]="Für Dunkelspeer, die den arkanen Pfad einschlagen, spiegelt die Unterweisung durch Mai'ah die wachsende Anpassung des Stammes an formalisiertes Zauberwirken neben ihren traditionellen spirituellen Riten wider."},sec={{t="Eine Botschaft in beschriftetem Stein",b="Nachdem sie ihren grundlegenden Mut gegen die einheimische Tierwelt im Tal der Prüfungen unter Beweis gestellt haben, erhalten angehende Magier eine von Gornek überreichte beschriftete Tafel. Die Botschaft stammt von Mai'ah, der ortsansässigen Magierlehrerin des Tals, die den Novizen auffordert, sie am Eingang zum Höhlenbau aufzusuchen, sobald sie bereit sind, ihr formelles Arkanstudium aufzunehmen."},{t="Die Gefahren des Unsichtbaren",b="Bei der Begrüßung verschwendet Mai'ah wenig Zeit mit Formalitäten und kommt direkt auf die ernüchternde Realität arkaner Macht zu sprechen. Zwar räumt sie ein, dass Magier weltbewegendes Potenzial besitzen, warnt jedoch davor, dass ihre größte Bedrohung weder rivalisierende Krieger noch feindliche Völker sind, sondern die unsichtbare, verderbliche Verlockung der Magie selbst. Sie mahnt zu Demut und Geduld und warnt davor, dass ungezügelte Zauberei einen Anwender leicht dazu verleitet, die eigene Beherrschung zu überschätzen."}},faq={{q="Wer übergibt dem Spieler die Glyphenschrifttafel?",a="Gornek, der anfängliche Questgeber des Tals, übergibt Euch die Tafel, sobald Ihr Eure vorläufige Aufgabe abgeschlossen habt, im Tal der Prüfungen gescheckte Eber zu beseitigen.",al={"wer vergibt glyphen-schrifttafel","woher bekomme ich glyphen-schrifttafel","glyphen-schrifttafel startquest"}},{q="Wer ist Mai'ah?",a="Mai'ah ist eine Magierlehrerin der Dunkelspeer, die direkt vor dem Eingang zum Höhlenbau im Tal der Prüfungen stationiert ist. Sie unterweist angehende Hordenmagier in ersten Zaubern und spricht eindringliche Warnungen vor den Gefahren arkaner Verderbnis aus.",al={"wer ist maiah","mai'ah lore","troll magierlehrer"}},{q="Wo befindet sich Mai'ah?",a="Mai'ah steht direkt vor dem Eingang zum Höhlenbau, rechts von der Tunnelmündung, im nördlichen Abschnitt des Tals der Prüfungen.",al={"wo ist maiah","mai'ah aufenthaltsort","maiah finden"}},{q="Welche Warnung spricht Mai'ah bezüglich der Magie aus?",a="Mai'ah warnt davor, dass Magie einen inhärenten verderblichen Einfluss besitzt, der sich nicht leicht aufhalten lässt. Sie betont, dass Magier eher die unsichtbaren Versuchungen und Machtillusionen des Arkane fürchten sollten als physische Feinde wie Orcs, Elfen oder Zwerge.",al={"mai'ah warnung","lore der magie-verderbnis","was sagt mai'ah"}},{q="Erhalten andere Klassen die Glyphenschrifttafel?",a="Nein. Die Glyphenschrifttafel ist ausschließlich für Novizen der Magier bestimmt. Andere Klassen erhalten eigene einführende Vorladungen – wie Runen, Schriftrollen oder Siegel –, die auf ihre jeweiligen Lehrer zugeschnitten sind.",al={"können andere klassen glyphen-schrifttafel erhalten","ist glyphen-schrifttafel nur für magier"}},{q="Welche Voraussetzung muss erfüllt sein, um diese Tafel zu erhalten?",a="Ihr müsst zuerst die Anfangsquest 'Erste Schritte' für Gornek abschließen, indem Ihr gescheckte Eber in den roten Lehmniederungen des Tals der Prüfungen erlegt.",al={"glyphen-schrifttafel voraussetzungen","vorbedingung für glyphen-schrifttafel"}}},fp="14,242,28.358.0,25.438.0,46.162.0,14.230.0,24.134.0,42.256.0,44.192.0,53.144.0"}
P.entries["quest:3087"] = {n="Geätztes Pergament",s="Geätztes Pergament ist eine Einführungsquest, die junge Jäger der Orcs im Tal der Prüfungen zu ihrer lokalen Klassenlehrerin Jen'shan führt. Nachdem ein Novize seine erste Bewährungsprobe bestanden hat, wird ihm die Notiz von Gornek überreicht und öffnet die Tür zu einer spezialisierten Wildnisausbildung und Überlebensfähigkeiten in Durotar.",h="Geätztes Pergament ist eine Einführungsquest, die junge Jäger der Orcs im Tal der Prüfungen zu ihrer lokalen...",kw={"dunkelspeere","durotar","geätztes pergament","gornek","jägerlehrer","jen'shan","das tal der prüfungen"},ang={["class:Hunter"]="Diese Notiz stellt Eure erste formelle Anerkennung als Jäger der Horde dar und weist Euch an Jen'shan, um Euer Zielen zu verfeinern und die Wildnis zu verstehen.",["faction:Horde"]="Jäger kundschaften die Grenzen aus und versorgen die Lager mit Nahrung; Novizen früh an ihr Handwerk heranzuführen, stellt sicher, dass die aufkeimende Nation von Durotar versorgt und bewacht bleibt.",["race:Orc"]="Jäger der Orcs verlassen sich auf Mentoren wie Jen'shan, um die traditionellen Jagdmethoden der Clans an die kargen Klippen und tödlichen Bestien von Durotar anzupassen.",["race:Troll"]="Für Rekruten der Dunkelspeere hält das Lernen unter Jen'shan die uralten Traditionen des Dschungelspurenlesens am Leben, die von den Echoinseln mitgebracht wurden."},sec={{t="Ein Ruf aus der Wildnis",b="Nachdem sie ihren grundlegenden Mut gegen die ansässigen Borsteneber unter Beweis gestellt haben, erhalten angehende Jäger im Tal der Prüfungen ein geätztes Pergament, das von Gornek übergeben wird. Das Schreiben stammt von Jen'shan, einer geschickten Jägerin der Dunkelspeere, die die Neuankömmlinge vom Rande des Lagers aus beobachtet. Die Notiz dient als offizielle Einladung zum Beginn der formellen Ausbildung und bestätigt, dass der Novize die nötigen Instinkte besitzt, um die ungezähmten Bestien und die raue Landschaft von Durotar zu meistern."},{t="Der Weg der Jäger",b="Sich bei Jen'shan zu melden, markiert den Übergang vom gewöhnlichen Rekruten zum entschlossenen Pirscher. Jen'shan nimmt Neulingen die Vorstellung, das Jägerhandwerk sei einfacher als die arkanen Künste oder der uralte Schamanismus. Durotars Raubtiere zu meistern, Fernkampfwaffen zu pflegen und in einem unbarmherzigen Land zu überleben, erfordert unerbittliche Disziplin. Sie weist ihre Lehrlinge an, den anderen Bewohnern des Tals zu helfen, um ihre Fähigkeiten auf die Probe zu stellen, bevor sie für fortgeschrittenere Überlebenstechniken zu ihr zurückkehren."}},faq={{q="Was ist das Geätzte Pergament?",a="Es ist eine schriftliche Vorladung, die von Gornek im Auftrag der Jägerlehrerin Jen'shan überbracht wird. Sie fordert vielversprechende Rekruten dazu auf, sich für spezialisierten Kampf- und Wildnisunterricht im Tal der Prüfungen bei ihr zu melden.",al={"was ist dieses pergament","geätztes pergament notiz","jäger pergament"}},{q="Wer überbringt dem Spieler diese Vorladung?",a="Gornek übergibt das Pergament, nachdem Ihr Eure anfängliche Prüfung bestanden habt, bei der Ihr Borsteneber im Tal der Prüfungen erlegen musstet.",al={"wer gibt geätztes pergament","woher bekomme ich die quest"}},{q="Wer ist Jen'shan?",a="Jen'shan ist eine Trolljägerin der Dunkelspeere, die im Tal der Prüfungen stationiert ist. Sie beurteilt neue Jäger der Orcs und Trolle und bringt ihnen die grundlegenden Fähigkeiten des Fernkampfs, des Aufspürens und der Tierkunde bei.",al={"jen'shan geschichte","wer ist jen'shan"}},{q="Warum vergleicht Jen'shan Jäger mit Magiern und Schamanen?",a="Jen'shan warnt davor, dass viele die Jagd im Vergleich zum Umgang mit Geistern der Ahnen oder arkaner Magie für einen einfachen Pfad halten. Sie betont, dass das Meistern tödlicher Treffsicherheit und wilder Bestien gleichermaßen Hingabe und Gefahren mit sich bringt.",al={"warum jäger nicht einfach","bedeutung von jen'shans dialog"}},{q="Was geschieht, nachdem man sich bei Jen'shan gemeldet hat?",a="Jen'shan führt Euch in fortgeschrittene Jägertechniken ein und weist Euch an, den anderen Bewohnern des Tals der Prüfungen beizustehen, um Eure neu erworbenen Fertigkeiten beim praktischen Überleben zu verfeinern.",al={"wie geht es nach geätztes pergament weiter","jägerquest fortsetzung"}},{q="Wer kann diese Quest erhalten?",a="Diese Quest wird ausschließlich neu erstellten Orcjägern angeboten, die im Tal der Prüfungen ausgebildet werden.",al={"wer erhält geätztes pergament","ist das nur für jäger"}}},fp="16,283,23.472.0,16.490.0,29.206.0,40.119.0,16.195.0,55.216.0,41.182.0,27.96.0"}
P.entries["quest:3088"] = {n="Verschlüsseltes Pergament",s="Das Verschlüsselte Pergament ist eine Vorladung für angehende Orcschurken, die ihr grundlegendes Überlebenstalent im Tal der Prüfungen unter Beweis gestellt haben. In Geheimschrift verfasst, weist es vielversprechende Rekruten in die schattigen Tiefen des Höhlenbaus, um Rwag zu treffen, einen Agenten im Dienste der Shattered-Hand.",h="Das Verschlüsselte Pergament ist eine Vorladung für angehende Orcschurken, die ihr grundlegendes...",kw={"durotar","verschlüsseltes pergament","gornek","orcschurke","rwag","shattered-hand","der höhlenbau","das tal der prüfungen"},ang={["class:Rogue"]="Dieses Pergament markiert Eure formelle Aufnahme in den verdeckten Apparat der Horde und führt Euch zu Rwag sowie Eurer frühesten beruflichen Ausbildung.",["faction:Horde"]="Selbst ein ehrenhafter Kriegshäuptling wie Thrall erkennt die Notwendigkeit von Spionen und Kundschaftern, um die jungen Lande von Durotar vor verborgenen Bedrohungen zu schützen.",["race:Orc"]="Anders als typische Orckrieger, die nach offener, blutdürstiger Glorie streben, bringen Orcschurken überlieferte Disziplin mit der stillen Schläue in Einklang, die von der Shattered-Hand verlangt wird."},sec={{t="Eine verschlüsselte Vorladung",b="Nachdem sie ihren Mut gegen die einheimische Tierwelt bewiesen haben, erhalten angehende Orcs ein verschlüsseltes Pergament, das von Gornek überbracht wird. Während andere Ausbilder auf der Lichtung offen Schüler anwerben, bevorzugt der Schurkenlehrer Rwag die diskrete Sicherheit von Geheimschrift und Stein. Das Pergament führt den Initianden am sonnenbeschienenen Lager vorbei und tief in die Höhle, die als der Höhlenbau bekannt ist."},{t="Augen in den Schatten",b="Nachdem der Novize die Botschaft entziffert und sich hineingewagt hat, entdeckt er Rwag, der im Fels lauert. Misstrauisch gegenüber den Hexenmeistern, die noch tiefer in der Höhle hausen, verliert Rwag keine Zeit, seine wahre Loyalität zu erklären: Er beobachtet Rekruten im Auftrag der Shattered-Hand. Während die orcische Gesellschaft offenen Ruhm und Ehre auf dem Schlachtfeld verherrlicht, fungiert die Shattered-Hand als das lautlose Netzwerk der Horde aus Spionen, Halsabschneidern und Informationsbeschaffern."}},faq={{q="Wer schickt das Verschlüsselte Pergament?",a="Das Pergament wurde von Rwag verfasst, dem Schurkenlehrer im Tal der Prüfungen. Er lässt Gornek die verschlüsselte Nachricht an vielversprechende junge Orcs überbringen, sobald diese ihre ersten Prüfungen abgeschlossen haben.",al={"wer schrieb das pergament","wer gab mir das verschlüsselte pergament","wer schickte notiz"}},{q="Was ist der Zweck dieser Quest?",a="Sie dient als einführende Klassenquest für Orcschurken und lehrt sie, Rwag im Höhlenbau zu finden, damit sie ihre formelle Ausbildung in Täuschung, Schlossknacken und kriegerischer List beginnen können.",al={"warum brauche ich verschlüsseltes pergament","was bringt diese quest"}},{q="Wo befindet sich Rwag?",a="Rwag versteckt sich im Höhlenbau, der dunklen Höhle auf der Nordseite des Tals der Prüfungen. Er lauert in den Schatten nahe dem Eingang und hält misstrauisch Abstand zu den Hexenmeistern weiter drinnen.",al={"wo ist rwag","rwag finden","rwag aufenthaltsort"}},{q="Warum ist das Pergament verschlüsselt?",a="Schurken verlassen sich auf Geheimhaltung und Diskretion. Die Verwendung einer Geheimschrift stellt sicher, dass umherstreifende Grobiane oder neugierige Außenstehende die Vorladung nicht lesen können, während gleichzeitig die Fähigkeit des Initianden geprüft wird, verdeckte Nachrichten zu entschlüsseln.",al={"warum geheimschrift","warum ist notiz verschlüsselt"}},{q="Wer ist die Shattered-Hand?",a="Ursprünglich ein berüchtigter Orc-Clan, der für Selbstverstümmelung bekannt war, hat sich die Shattered-Hand innerhalb von Thralls Horde zu einer Organisation von Spähern, Attentätern und verdeckten Agenten entwickelt, die aus den Schatten heraus operieren, um die Interessen der Horde zu schützen.",al={"shattered-hand horde","was ist shattered-hand"}},{q="Warum misstraut Rwag Nartok?",a="Nartok ist ein Hexenmeisterlehrer tiefer im Höhlenbau. Schurken agieren heimlich, doch selbst Rwag findet es zutiefst beunruhigend, dass finstere Zauberwirker in den hintersten Winkeln der Höhle offen Teufelsrituale durchführen.",al={"rwag nartok","warum hasst rwag hexenmeister"}}},fp="19,293,15.355.0,19.441.0,34.182.0,34.192.0,22.198.0,31.214.0,27.225.0,30.209.0"}
P.entries["quest:3089"] = {n="Mit Runen beschriftetes Pergament",s="Mit Runen beschriftetes Pergament ist ein Schreiben, das angehenden Schamanen der Horde zu Beginn ihrer Reise im Tal der Prüfungen überreicht wird. Das von der Ausbilderin Shikrik verfasste Pergament ruft vielversprechende Initianden dazu auf, ihre formelle Ausbildung im Einklang mit den Geistern und Elementen zu beginnen.",h="Mit Runen beschriftetes Pergament ist ein Schreiben, das angehenden Schamanen der Horde zu Beginn ihrer Reise...",kw={"ahnen","durotar","elemente","gornek","mit runen beschriftetes pergament","schamane","shikrik","das tal der prüfungen"},ang={["class:Shaman"]="Dieses Pergament stellt Euren ersten Schritt auf der spirituellen Reise dar und besiegelt Euren heiligen Bund mit den Geistern und den ungezähmten Elementen von Durotar.",["race:Orc"]="Für Orcs ehrt die Rückkehr zum Schamanismus die uralten Traditionen Draenors, die während der dämonischen Verderbnis der Alten Horde beinahe ausgelöscht wurden.",["race:Troll"]="Dunkelspeer, die diesem Ruf folgen, verweben ihre angeborene spirituelle Zwiesprache und Ahnenverehrung mit den gemeinsamen schamanistischen Traditionen der neuen Horde."},sec={{t="Ein Ruf der Geister",b="Nachdem sie ihre grundlegenden Überlebensfähigkeiten gegen die örtliche Tierwelt unter Beweis gestellt haben, erhalten neue Orcschamanen von Gornek, dem Aufseher des Tals der Prüfungen, ein mit Runen beschriftetes Pergament. Das Pergament trägt mystische Schriftzeichen von Shikrik, der im Tal ansässigen Schamanenausbilderin, und bittet den neu eingetroffenen Initianden um eine Audienz."},{t="Der Pfad des Schamanen",b="Sich bei Shikrik zu melden, markiert den formellen Beginn der heiligen Pflicht eines Schamanen gegenüber der Horde. Shikrik erinnert den jungen Initianden daran, dass seine Berufung nicht rein kriegerischer Natur ist; sie sind auserwählt, als Sprachrohr der Ahnengeister zu dienen und den Zorn der Elemente zu führen. Durch Shikrik lernen neue Schamanen, spirituelle Energien zu bündeln, Wunden zu heilen und die Naturkräfte Kalimdors herbeizurufen."}},faq={{q="Was ist das mit Runen beschriftete Pergament?",a="Es ist eine schriftliche Vorladung von Gornek im Tal der Prüfungen an neue Schamanen, die sie auffordert, ihre Ausbilderin Shikrik für die formelle Ausbildung in den Elementen aufzusuchen.",al={"was ist diese quest","pergamentquest","schamanen startnotiz"}},{q="Wer verschickt das Pergament?",a="Die Nachricht wurde von Shikrik verfasst, der Schamanenausbilderin, die nahe den Höhlen im Tal der Prüfungen stationiert ist und auf jene wartet, die dazu auserkoren sind, ihr Volk spirituell zu leiten.",al={"wer schrieb das pergament","shikrik notiz","wer ist shikrik"}},{q="Wohin bringt man das Pergament?",a="Ihr bringt es nach einem kurzen Fußweg innerhalb des Tals der Prüfungen dorthin, wo Shikrik unter den roten Klippen bereitsteht, um Schamanen der Orcs und Trolle auszubilden.",al={"wohin gehen","wo ist shikrik","abgabeort"}},{q="Warum wurde mein Charakter dafür ausgewählt?",a="Laut Shikrik sind jene, die sich zum schamanistischen Pfad berufen fühlen, dazu auserwählt, als Sprachrohr der Ahnen zu dienen und direkt mit den Elementarkräften der Welt zu sprechen.",al={"warum schamane","warum auserwählt","schamanenberufung hintergrund"}},{q="Was geschieht nach dem Vorzeigen des Pergaments?",a="Shikrik nimmt Euch als Schülerin oder Schüler an und führt Euch in den Pfad der Elementarmagie, die Zwiesprache mit den Ahnen und die Grundlagen von Heilung und Kampf ein.",al={"nächster schritt","was macht shikrik","nach dem pergament"}},{q="Kann jede Klasse diese Quest abschließen?",a="Nein. Das Mit Runen beschriftete Pergament richtet sich eigens an angehende Schamanen. Andere Klassen erhalten jeweils ihre eigenen Vorladungen zu ihren entsprechenden Ausbildern.",al={"nur für schamanen","wer bekommt dieses pergament","pergament für krieger"}}},fp="24,270,26.317.0,22.385.0,37.168.0,24.165.0,30.142.0,42.161.0,44.145.0,34.159.0"}
P.entries["quest:309"] = {n="Beschützen der Fracht",s="Beschützen der Fracht ist eine Begleitquest im südlichen Loch Modan, bei der Abenteurer den Kurier Miran auf seinem Weg zu Ironbands Ausgrabungsstätte beschützen. Miran transportiert eine Kiste mit hochexplosivem Sprengpulver, das von Ausgrabungsleiter Eisenband dringend benötigt wird. Die Reise offenbart anhaltende Subversion durch Dunkeleisenzwerge, die das Hinterland der Zwerge bedroht.",h="Beschützen der Fracht ist eine Begleitquest im südlichen Loch Modan, bei der Abenteurer den Kurier Miran auf...",kw={"sprengpulver","hinterhalt der dunkeleisenzwerge","eisenbands ausgrabungsstätte","eskorte loch modan","miran","ausgrabungsleiter eisenband"},ang={["faction:Alliance"]="Die Allianz verlässt sich auf eine funktionierende Logistik in Loch Modan; Kuriere vor unterirdischen Angreifern zu schützen, bewahrt die Verbindung zwischen Eisenschmiede und den östlichen Grenzlanden.",["profession:Mining"]="Bergleute verstehen nur allzu gut den Wert – und die Flüchtigkeit – von Sprengpulver, wenn es darum geht, Khaz Modans widerspenstiges Grundgestein zu durchdringen.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede ist die Verteidigung von Ironbands Nachschub eine direkte Verteidigung ihres Erbes, die uralte Entdeckungen vor der Sabotage ihrer verbitterten Dunkeleisen-Verwandten schützt."},sec={{t="Ein Pulvertransport in Gefahr",b="Ausgrabungsleiter Eisenbands archäologische Ausgrabung in den Hügeln des südlichen Loch Modan benötigt einen stetigen Nachschub an Sprengpulver, um sich durch widerspenstigen Fels zu sprengen. Als die Nachschublinien zusammenbrechen und Kurierwagen bedroht werden, strandet der Kurier Miran mit einer schweren Ladung Pulver auf der Straße. Miran sicher über die unwegsamen Pfade zur Ausgrabungsstätte zu geleiten, stellt sicher, dass Ironbands Arbeit nicht völlig zum Erliegen kommt."},{t="Sympathisanten der Dunkeleisenzwerge",b="Die Straße zur Ausgrabungsstätte wird nicht nur von wilden Tieren heimgesucht; Infiltratoren der Dunkeleisenzwerge lauern aktiv darauf, die explosive Fracht abzufangen. Ihr dreister Hinterhalt nahe der Stätte offenbart Ironband eine finstere Wahrheit: Streitkräfte der Dunkeleisenzwerge beschaffen sich illegale Materialien und säen aktiv Zwietracht im Herzen von Loch Modan. Auch wenn die Lieferung den Fortgang der Grabung sichert, weckt sie Beunruhigung darüber, wie tief feindliche Sabotage bereits in das Territorium der Allianz reicht."}},faq={{q="Wer ist Miran?",a="Miran ist ein Kurier der Allianz, der damit beauftragt ist, lebenswichtigen Nachschub – insbesondere Sprengpulver – über die gefährlichen Nebenstraßen von Loch Modan zu Eisenbands Ausgrabungsstätte zu transportieren.",al={"wer ist miran","miran loch modan","kurier miran"}},{q="Warum benötigt Ausgrabungsleiter Eisenband das Pulver?",a="Ausgrabungsleiter Eisenband leitet eine bedeutende archäologische Ausgrabung im südlichen Loch Modan. Sein Team ist auf schweres Sprengpulver angewiesen, um Felsen zu sprengen, uralte Titanenartefakte freizulegen und ihre Grabungsarbeiten aufrechtzuerhalten.",al={"warum ironband pulver braucht","verwendungszweck pulver","ironband sprengpulver"}},{q="Wer greift während der Eskorte an?",a="Saboteure der Dunkeleisenzwerge überfallen den Kurier kurz vor der Ausgrabungsstätte, um den Sprengstoff an sich zu reißen und die Unternehmungen von Eisenschmiede in der Region zu durchkreuzen.",al={"wer greift miran an","angreifer des hinterhalts","begleitquest angreifer"}},{q="Wohin führt die Eskorte?",a="Die Eskorte beginnt entlang der südlichen Straße von Loch Modan und endet an Eisenbands Ausgrabungsstätte, die in den Hügeln südöstlich des Sees liegt.",al={"ziel der eskorte","wohin geht miran","wo ist ironband"}},{q="Warum befinden sich Dunkeleisenzwerge in Loch Modan?",a="Der Dunkeleisenclan unterhält geheime Enklaven und Spione in ganz Khaz Modan. Sie überfallen aktiv Nachschublinien, sabotieren Ausgrabungen der Forscherliga und versuchen, Eisenschmiedes Verteidigungslinie zu destabilisieren.",al={"dunkeleisenzwerge loch modan","warum dunkeleisenzwerge hier","präsenz der dunkeleisenzwerge"}},{q="Was geschieht, nachdem die Fracht eingetroffen ist?",a="Ausgrabungsleiter Eisenband nimmt das Pulver erleichtert entgegen und dankt dem Licht dafür, dass der Nachschub trotz der beunruhigenden Erkenntnis angekommen ist, dass Sympathisanten der Dunkeleisenzwerge in der Nähe operieren.",al={"questfortsetzung","was nach beschützen der fracht","folgequest"}}},fx={a48eefd2={q="Warum möchte Miran, dass dies erledigt wird?",a="Miran ist damit beauftragt, lebenswichtiges Sprengpulver durch feindliches Gebiet zum Ausgrabungsort von Ausgrabungsleiter Eisenband zu transportieren. Die Lieferung ist schwer und die Straße ist tückisch, was durch die lauernde Gefahr von Hinterhalten der Dunkeleisenzwerge noch schlimmer wird. Er kann nicht gleichzeitig die instabile Fracht tragen und sich auf dem gefährlichen Weg verteidigen.",al={"miran motiv","warum miran eskortieren","warum pulver liefern"}},bdc08a2b={q="Warum benötigt Miran Eure Hilfe anstatt der örtlichen Wachen?",a="Die Gebirgsjäger von Loch Modan sind bis zum Äußersten beansprucht, da sie Trogg-Einfälle abwehren und wichtige Siedlungen in der gesamten Region sichern müssen. Da keine offiziellen Patrouillen zur Verfügung stehen, um einen Versorgungstransport zu schützen, ist Miran auf fähige Abenteurer wie Euch angewiesen, um die in den Hügeln lauernden Dunkeleisenzwerge abzuwehren.",al={"warum ich miran","warum braucht miran hilfe","warum keine gebirgsjäger miran"}}},fp="23,331,21.413.0,22.441.1,13.173.0,45.215.0,30.160.0,27.144.0,33.200.0,40.180.0"}
P.entries["quest:3092"] = {n="Geätzte Notiz",s="Die Geätzte Notiz ist eine formelle Vorladung an vielversprechende junge Taurenjäger in Camp Narache. Im Auftrag des Lehrers Lanka Weitschuss überbracht, ruft die Nachricht den Neuling dazu auf, die praktischen und spirituellen Künste der Wildnis zu meistern.",h="Die Geätzte Notiz ist eine formelle Vorladung an vielversprechende junge Taurenjäger in Camp Narache.",kw={"camp narache","geätzte notiz","lanka weitschuss","mulgore","die hochwolkenebene","taurenjäger"},ang={["class:Hunter"]="Diese Vorladung markiert Eure offizielle Aufnahme in die Tradition der Jäger und bereitet Euch darauf vor, Treffsicherheit, das Überleben in der Wildnis und die Gefährtenschaft mit Tieren zu meistern.",["race:Tauren"]="Für die Shu'halo ist die Jagd eine heilige Pflicht, die die Erdenmutter durch den Respekt vor den Bestien ehrt, welche den Stamm in den Ebenen von Mulgore ernähren."},sec={{t="Ein Ruf zur Jagd",b="Während ihrer Ausbildung auf den Klippen der Hochwolkenebene erhalten junge Tauren, die Begabung im Treffsicherheit und Fährtenlesen zeigen, eine geätzte Botschaft. Durch Grull Falkenwind überreicht, verkündet die Notiz, dass Lanka Weitschuss auf die Abstammung und die rohe Begabung des Jünglings aufmerksam geworden ist, und fordert ihn auf, seine Ausbildung unter seinem wachsamen Auge offiziell zu beginnen."},{t="Tradition der Ebenen",b="Für die Shu'halo ist ein Jäger weit mehr als ein einfacher Kundschafter oder Krieger. Jäger ernähren die Stämme durch ihre Beute, beschützen nomadische Lager und leben im engen Einklang mit den Bestien von Kalimdor. Indem er den Neuling zur Ausbildung ruft, legt Lanka den Grundstein für den Umgang mit Waffen, das Verständnis für die Kreaturen von Mulgore und schließlich für die uralte Kunst des Zähmens wilder Gefährten."}},faq={{q="Was ist der Zweck der Geätzten Notiz?",a="Die Geätzte Notiz dient als formelle Einführung, die einen angehenden Taurenjäger mit Lanka Weitschuss zusammenbringt, dem in Camp Narache stationierten Klassenlehrer.",al={"was bewirkt geätzte notiz","zweck geätzte notiz","warum habe ich geätzte notiz erhalten"}},{q="Wer überbringt die Notiz?",a="Grull Falkenwind übergibt die Notiz und erklärt, dass ein Bote des Jägerlehrers den jungen Jäger kurz zuvor gesucht habe.",al={"wer gibt geätzte notiz","questgeber geätzte notiz","rohaku notiz"}},{q="Wo befindet sich Lanka Weitschuss?",a="Lanka Weitschuss hält sich in Camp Narache auf der Hochwolkenebene auf und steht nahe den Jägerübungsplätzen bereit, um neue Rekruten auszubilden.",al={"wo ist lanka weitschuss","lanka weitschuss finden","standort lanka"}},{q="Warum werden Jäger bei den Tauren so verehrt?",a="Jäger spielen eine entscheidende Rolle in der Taurengesellschaft, indem sie Nahrung beschaffen, die ungezähmte Wildnis deuten und die Harmonie mit den Geistern der Ebenen bewahren.",al={"tauren jäger lore","warum taurenjäger wichtig sind"}},{q="Welche Fertigkeiten vermittelt diese Ausbildung?",a="Lanka bereitet den Neuling auf grundlegende Jagdtechniken vor, darunter den Einsatz von Fernkampfwaffen, das Verständnis wilder Bestien und schließlich die Rituale, die zum Zähmen tierischer Begleiter erforderlich sind.",al={"was lanka lehrt","jäger grundlagen tauren"}},{q="Was ist der nächste Schritt nach dem Lesen der Notiz?",a="Das Melden bei Lanka Weitschuss schließt die Vorladung ab und macht ihn zu Eurem Ausbilder, der Euch lehrt, Eure Flinte abzufeuern, einen Begleiter zu zähmen und vieles mehr, während Ihr heranwachst.",al={"nächste quest nach geätzter notiz","folgequest geätzte notiz"}}},fx={["69749d8d"]={q="Warum gibt Euch Grull Falkenwind die Geätzte Notiz?",a="Grull Falkenwind gibt lediglich eine Nachricht im Auftrag eines Boten weiter, der durch Camp Narache geschickt wurde. Lanka Weitschuss, die Ausbilderin für Jäger im Lager, schickte den Boten speziell aus, um Euch zu suchen, da Ihr nun erwachsen werdet. Grull stellt einfach sicher, dass die Vorladung Eure Hände ohne Verzögerung erreicht, damit Ihr die ordnungsgemäße Ausbildung unter Eurem Volk beginnen könnt.",al={"warum gibt rohaku eine notiz","rohaku steinhuf motiv","warum gab mir rohaku das"}}},fp="11,247,21.346.0,23.398.0,39.152.0,22.132.0,31.134.0,44.152.0,41.189.0,45.148.0"}
P.entries["quest:3094"] = {n="Tiefgrüne Notiz",s="Die Tiefgrüne Notiz ist eine formelle Vorladung, die vielversprechenden jungen Tauren auf der Hochwolkenebene überbracht wird. Die von Grull Falkenwind anvertraute Botschaft fordert angehende Beschützer der Wildnis auf, den Druidenlehrer Gart Nebelläufer in Camp Narache aufzusuchen.",h="Die Tiefgrüne Notiz ist eine formelle Vorladung, die vielversprechenden jungen Tauren auf der Hochwolkenebene...",kw={"camp narache","druide","erdenmutter","gart nebelläufer","grull falkenwind","mulgore","die hochwolkenebene","tiefgrüne notiz"},ang={["class:Druid"]="Diese Vorladung markiert die früheste Einführung eines Druiden in das Kanalisieren der wilden Energien und unruhigen Geister von Azeroth.",["faction:Horde"]="Taurendruiden bilden die wichtigste Brücke zwischen der modernen Horde und den Naturgeheimnissen von Kalimdor und verleihen der rohen kriegerischen Stärke der Fraktion ein spirituelles Gleichgewicht.",["race:Tauren"]="Für die Tauren ist das Druidentum nicht bloß eine Schule der Magie, sondern ein heiliger Bund, der aus ihrer mythischen Hingabe an die Erdenmutter erwachsen ist."},sec={{t="Ein Ruf auf den Pfad",b="Junge Tauren, die auf der Hochwolkenebene beginnen, ihre Verantwortung zu tragen, werden schnell aufgrund ihrer natürlichen Gaben ausgewählt. Grull Falkenwind übergibt dieses Schreiben im Namen eines von Gart Nebelläufer entsandten Boten. Die Notiz dient als Einladung in die uralte Gemeinschaft des Druidentums der Tauren und ruft den Novizen von einfachen Dorfaufgaben fort, um auf das flüsternde Gleichgewicht der Ebenen zu lauschen."},{t="Stimmen der Erdenmutter",b="Sobald der angehende Druide dem Ruf folgt, warnt ihn Gart Nebelläufer davor, dass die Ahnen- und Naturgeister überall in Mulgore unruhig geworden sind. Taurendruiden haben die Aufgabe, als lebende Avatare der Natur zu wirken und im Einklang mit dem Willen der Erdenmutter zu bleiben, ungeachtet entfernter Rivalitäten. Obwohl auch Nachtelfen die druidischen Künste praktizieren, mahnt Gart, dass deren Stolz sie für die tief verwurzelte Verbindung der Tauren mit dem Reich der Natur blind macht."}},faq={{q="Was ist die Tiefgrüne Notiz?",a="Sie ist eine einleitende Aufforderung, die jungen Taurendruiden in Camp Narache übergeben wird. Sie weist den Träger an, den örtlichen Lehrer, Gart Nebelläufer, aufzusuchen, um mit der strukturierten Ausbildung in den druidischen Künsten zu beginnen.",al={"tiefgrüne notiz","druidenbrief","mulgore druidenquest notiz"}},{q="Wer übergibt dem Spieler die Notiz?",a="Grull Falkenwind überreicht dem jungen Druiden die Notiz und erwähnt, dass kürzlich ein von Gart Nebelläufer entsandter Bote nach ihm gesucht hat.",al={"wer gibt tiefgrüne notiz","tiefgrüne notiz queststart"}},{q="Wo ist Gart Nebelläufer zu finden?",a="Gart Nebelläufer hält sich in Camp Narache auf, wo er im Schutz der natürlichen Klippen des Lagers die Ausbildung der Tauren-Novizendruiden leitet.",al={"gart nebelläufer aufenthaltsort","wo ist gart"}},{q="Warum warnt Gart Nebelläufer vor den Nachtelfen?",a="Obwohl beide Völker die Natur verehren und das Druidentum im Zirkel des Cenarius ausüben, stellt Gart fest, dass die Arroganz der Nachtelfen oft ihren Blick auf andere Kulturen trübt. Er ermutigt seinen Schüler, solche Haltungen zu ignorieren und sich einzig auf die Weisheit der Erdenmutter zu konzentrieren.",al={"druiden der tauren und nachtelfen","nachtelfenstolz druide"}},{q="Warum sind die Geister in Mulgore unruhig?",a="Gart Nebelläufer spürt Unruhen, welche die Ahnen- und Naturgeister in den Ebenen von Mulgore aufwühlen – ein frühes Zeichen dafür, dass das Gleichgewicht der Wildnis zur lebenslangen Aufgabe des neuen Druiden wird.",al={"mulgore geister unruhig","warum sind naturgeister zornig"}},{q="Welche Fähigkeit lehrt Gart nach Abschluss dieser Quest als Nächstes?",a="Nachdem sich der Novize bei Gart Nebelläufer gemeldet hat, wird dieser zu seinem Ausbilder und verspricht, ihn mit wachsender Weisheit in den Gaben der Erdenmutter zu unterweisen.",al={"was kommt nach tiefgrüne notiz","druidenquest folgequest"}}},fx={["92e5d696"]={q="Warum gibt Euch Grull Falkenwind die Tiefgrüne Notiz?",a="Ein Bote hat speziell nach Euch gesucht im Auftrag von Gart Nebelläufer, dem Druiden-Ausbilder des Lagers. Grull Falkenwind leitet nur die dringende Nachricht weiter, damit Ihr nicht zögert, Eure formelle spirituelle Ausbildung unter Garts Führung zu beginnen.",al={"warum gibt rohaku eine notiz","rohaku steinhuf motiv","warum will rohaku das erledigt haben"}}},fp="12,237,21.383.0,25.433.0,25.201.0,36.134.0,35.150.0,54.278.0,40.202.0,62.137.0"}
P.entries["quest:3096"] = {n="Verschlüsselte Rolle",s="Die Verschlüsselte Rolle ist eine diskrete Vorladung für frisch erwachte Schurken der Verlassenen in Todesend. Weitergereicht von Schattenpriester Sarvis, leitet die Chiffre den Rekruten zu David Trias, einem Schurken-Mentor, der im Stillen im örtlichen Gasthaus agiert.",h="Die Verschlüsselte Rolle ist eine diskrete Vorladung für frisch erwachte Schurken der Verlassenen in Todesend.",kw={"david trias","todesend","verschlüsselte rolle","verlassene schurke","schattenpriester sarvis","shadowstalkers","tirisfal"},ang={["class:Rogue"]="Dieses Schreiben markiert Eure formelle Einführung in das geheime Netzwerk der Verlassenen und schlägt die Brücke zwischen einer frisch auferstandenen Leiche und einem angehenden Geheimagenten.",["race:Undead"]="Während die neugeformten Verlassenen Tirisfal gegen die Geißel und verbliebene Lebende sichern, sind Späher und verdeckte Ermittler überlebenswichtig für die Strategie der Dunklen Fürstin."},sec={{t="Eine leise Vorladung",b="Während neu erweckte Verlassene auf dem Friedhof gegen geistlose Zombies kämpfen, beobachtet die Führung der Siedlung diejenigen mit besonderen Neigungen zu Heimlichkeit und Täuschung. Schattenpriester Sarvis übergibt dieses versiegelte Pergament an vielversprechende Späher, sobald ihre anfängliche Einsatzbereitschaft bewiesen ist. Versehen mit dem diskreten Siegel von David Trias, dient es als frühe Einführung in das Schattennetzwerk, das unterhalb der Hierarchie der Verlassenen operiert."},{t="Augen in den Schatten",b="David Trias beobachtet die Kreuzung und das Gasthaus von Todesend und hält Ausschau nach Anwärtern für künftige verdeckte Operationen. Anstatt gewöhnliche Diebe oder leichtsinnige Beutelschneider zu suchen, benötigen die Verlassenen disziplinierte Geheimagenten, um dem jungen Königreich zu dienen. Trias deutet an, dass fähige Schurken letztendlich die Aufmerksamkeit der Shadowstalkers erregen könnten – eines eingeschworenen Kaders innerhalb der Verlassenen, der Scharfsinn, Präzision und absolute Loyalität gegenüber der Dunklen Fürstin schätzt."}},faq={{q="Was ist der Zweck der Verschlüsselten Rolle?",a="Die Schriftrolle ist eine private Einladung für frisch erwachte Schurken der Verlassenen. Schattenpriester Sarvis übergibt sie Euch, sobald Ihr Eure Fähigkeiten bewiesen habt, und weist Euch an, Euch für eine spezialisierte Ausbildung bei David Trias zu melden.",al={"was ist verschlüsselte rolle","was bewirkt die rolle","warum verschlüsselte rolle"}},{q="Wer ist David Trias?",a="David Trias ist der Schurkenlehrer im Gasthaus von Todesend. Er beurteilt neue Rekruten und sucht nach potenziellen Agenten für größere Geheimdienstoperationen der Verlassenen.",al={"david trias","wer ist trias","schurkenlehrer todesend"}},{q="Wer sind die von Trias erwähnten Shadowstalkers?",a="Die Shadowstalkers sind eine Organisation von Schleichagenten und Attentätern der Verlassenen. Trias warnt neue Schurken, dass die Shadowstalkers nur talentierte, disziplinierte Agenten anwerben und keine ungeschickten Taschendiebe.",al={"wer sind die shadowstalkers","shadowstalkers verlassene","shadowstalkers"}},{q="Warum ist die Nachricht verschlüsselt?",a="Schurken der Verlassenen schätzen Geheimhaltung und operative Sicherheit. Die Anweisung von Anwärtern über verschlüsselte Depeschen stellt sicher, dass heikle Mitteilungen in einer verwundbaren Siedlung wie Todesend vor unvorsichtigen Blicken geschützt bleiben.",al={"warum verschlüsselt","warum chiffriert"}},{q="Wo findet man Schattenpriester Sarvis?",a="Schattenpriester Sarvis beaufsichtigt die Erstaufnahme neuer Verlassener im zentralen Krypta- und Kapellenkomplex von Todesend in Tirisfal.",al={"wo ist sarvis","sarvis aufenthaltsort","schattenpriester sarvis finden"}},{q="Wo befindet sich David Trias?",a="David Trias steht im beschädigten Gasthausgebäude gleich den Weg hinab von der zentralen Kapelle in Todesend.",al={"wo ist trias","david trias standort","todesend lehrer gasthaus"}}},fp="16,243,15.433.0,19.443.0,44.200.0,19.169.0,46.205.0,29.217.0,39.142.0,29.108.0"}
P.entries["quest:3097"] = {n="Geheiligte Rolle",s="Die Geheiligte Rolle ist eine einführende Vorladung für frisch erwachte Priester der Verlassenen in Todesend. Ausgehändigt von Schattenpriester Sarvis ruft das Schreiben den Neuling zu Dunklem Kleriker Duesten in die zerstörte Dorfkapelle, um zu lernen, wie die Untoten nach dem Tod ihren Glauben einsetzen.",h="Die Geheiligte Rolle ist eine einführende Vorladung für frisch erwachte Priester der Verlassenen in Todesend.",kw={"dunkler kleriker duesten","todesend","priester der verlassenen","geheiligte rolle","priesterquest","schattenpriester sarvis","tirisfal"},ang={["class:Priest"]="Diese Quest markiert Eure philosophische Taufe in die Priesterschaft der Verlassenen, bei der traditionelle fromme Ergebenheit abgelegt wird, um Selbstständigkeit, Leid und Schattenmagie anzunehmen.",["race:Undead"]="Die Rolle veranschaulicht das Weltbild der Verlassenen: Von ihren alten menschlichen Glaubensformen abgeschnitten, überleben sie allein durch eisernen Willen und gegenseitige Notwendigkeit."},sec={{t="Eine Vorladung in Todesend",b="Wenn frisch erwachte Untote aus den Gräbern von Todesend wanken, sind ihre Geister oft noch von den Traumata der Seuche, des Todes und der plötzlichen Befreiung aus dem Griff des Lichkönigs benommen. Für jene, die zu Lebzeiten fromme Anhänger des Heiligen Lichts waren, sitzt die Verwirrung besonders tief. Während junge Untote die geistlose Geißel bekämpfen, die den Rand der Siedlung heimsucht, fängt Schattenpriester Sarvis eintreffende Botschaften ab. Versehen mit dem Siegel von Dunklem Kleriker Duesten fordert die geheiligte Rolle neuerweckte Priester auf, ihr Umherirren zu beenden und sich in der entweihten Stadtkapelle zu melden."},{t="Ein neu definierter Glaube",b="Bei Abgabe der Rolle begegnet ein Novize der harten Theologie der Priesterschaft der Verlassenen. Dunkler Kleriker Duesten nimmt kein Blatt vor den Mund: Das Heilige Licht hat sie im Tod verlassen, Geister der Ahnen sind hohle Märchen und Dämonen anderer Ebenen interessieren sich nicht für ihre Not. Stattdessen lehrt der Klerus der Verlassenen, dass schiere Willenskraft und radikale Selbstständigkeit die einzig wahren Quellen der Erlösung sind. Unter Duestens Anleitung lernen frisch erweckte Anwender, sowohl göttliche Disziplin als auch Schatten zu kanalisieren – eine Macht, die sie nicht aus Ergebenheit gegenüber fernen Göttern führen, sondern aus dem unbedingten Willen zu ihrem eigenen Überleben."}},faq={{q="Was ist die Geheiligte Rolle?",a="Es ist ein versiegeltes Dokument, das Schattenpriester Sarvis neuerweckten Priestern der Verlassenen in Todesend überreicht. Es weist sie an, Dunklen Kleriker Duesten in der Stadtkapelle aufzusuchen, um ihre formelle Priesterausbildung zu beginnen.",al={"geheiligte rolle","rollen-gegenstand","priesterrolle"}},{q="Wer schickt dem Spieler die Rolle?",a="Die Rolle trägt das persönliche Siegel von Dunklem Kleriker Duesten, dem örtlichen Priesterausbilder der Verlassenen in Todesends Kapelle, wird Euch jedoch von Schattenpriester Sarvis überreicht.",al={"wer hat die rolle geschickt","duestens rolle","sarvis brief"}},{q="Können die Verlassenen noch das Heilige Licht wirken?",a="Dunkler Kleriker Duesten erklärt neuen Priestern, dass das Heilige Licht sie nichts mehr angeht. Wie er darlegt, weicht die traditionelle Verehrung des Lichts dem Glauben an sich selbst und der Meisterschaft über den Schatten.",al={"untote nutzen licht","verlassene heiliges licht","können untote licht wirken"}},{q="Wo befindet sich Dunkler Kleriker Duesten?",a="Er befindet sich in der Kirchenruine im Zentrum von Todesend im westlichen Tirisfal und steht dort bei anderen Ausbildern der Verlassenen.",al={"duesten finden","duestens standort","wo ist kleriker duesten"}},{q="Warum wischt Duesten Ahnen und Dämonen beiseite?",a="Duesten will den neuerweckten Untoten jegliche Illusionen nehmen. Die Kultur der Verlassenen lehnt äußere göttliche Erlöser, Hilfe von Ahnen und Dämonenpakte ab und predigt stattdessen, dass ihr Überleben einzig und allein von ihrer eigenen kollektiven Willenskraft abhängt.",al={"duestens rede","märchen","der nether will euch nicht"}},{q="Was geschieht nach dem Lesen der Rolle?",a="Ihr lest das Pergament und stellt Euch Dunklem Kleriker Duesten in der Kapelle von Todesend vor, wodurch Ihr Eure ersten Priesterfähigkeiten freischaltet und ihn zu Eurem Ausbilder im Startgebiet macht.",al={"ziel der geheiligten rolle","rolle abgeben"}}},fp="15,277,23.577.0,15.584.0,28.210.0,35.179.0,40.201.0,37.133.0,46.244.0,38.197.0"}
P.entries["quest:3098"] = {n="Glyphenrolle",s="Die Glyphenrolle ist eine offizielle Vorladung, die frisch erweckten Magiern der Verlassenen in Todesend überbracht wird. Versehen mit dem Siegel der Magierlehrerin Isabella weist das Pergament vielversprechende Ausüber der Arkanmagie an, sie in der entweihten Dorfkirche aufzusuchen, um ihre unberechenbaren Kräfte zu verfeinern.",h="Die Glyphenrolle ist eine offizielle Vorladung, die frisch erweckten Magiern der Verlassenen in Todesend...",kw={"arkan","todesend","verlassener magier","glyphenrolle","isabella","magierlehrer","tirisfal"},ang={["class:Mage"]="Diese Schriftrolle markiert Eure offizielle Aufnahme in die Reihen der Magier der Verlassenen und knüpft Euer magisches Handwerk direkt an das Überleben und den Wiederaufstieg Eures neu befreiten Volkes.",["race:Undead"]="Magier der Verlassenen gebrauchen das Arkan für finstere Absichten und begreifen Magie nicht als akademisches Geplänkel Dalarans, sondern als unverzichtbare Waffe zur Rückeroberung ihrer geraubten Heimat."},sec={{t="Ein Ruf zur Arkanmagie",b="Wenn ein frisch erweckter Verlassener beim Ausdünnen der geistlosen Geißel rund um Todesend eine Begabung für Arkanmagie offenbart, erregt er rasch die Aufmerksamkeit seiner Ältesten. Die persönlich überbrachte Glyphenrolle ist mit dem arkanspezifischen Siegel von Isabella, der örtlichen Magierausbilderin, versehen. Sie fordert den neu erwachten Zauberkundigen auf, sich an ihrem Posten in der Kirchenruine zu melden, da man erkannt hat, dass eine unregulierte magische Begabung für die Verlassenen eine ebenso große Gefahr darstellt wie für ihre Feinde."},{t="Magie im Untod wirken",b="In der zerstörten Kapelle von Todesend belehrt Isabella Neulinge darüber, dass der Tod sie keineswegs von den Gefahren des Arkans befreit hat. Zwar hat die Sterblichkeit ihnen die physischen Schwächen genommen, doch der unbeständige Reiz und das verderbende Wesen der Magie bestehen unvermindert fort. Für die Verlassenen ist das Streben nach arkaner Vorherrschaft kein bloßes intellektuelles Unterfangen, sondern ein Werkzeug des Überlebens und der Rache – ein Mittel, um ihr Schicksal zurückzugewinnen und jeden zu vernichten, der ihre fragile Rückeroberung von Lordaeron bedroht."}},faq={{q="Was ist die Glyphenrolle?",a="Die Glyphenrolle ist ein Lehrschreiben, das das persönliche Siegel von Isabella trägt, der Magierlehrerin der Verlassenen in Todesend. Sie weist neu erwachte Magier an, sich in der Kirchenruine einzufinden, um ihr Studium des Arkans voranzutreiben.",al={"glyphen-rolle quest","was ist diese schriftrolle","todesend schriftrolle"}},{q="Wer schickt Euch die Glyphenrolle?",a="Die Schriftrolle wird von Isabella entsandt, der ansässigen Magierlehrerin in Todesend, und Euch überbracht, nachdem Ihr Euren Nutzen im Kampf gegen die nahe geistlose Geißel unter Beweis gestellt habt.",al={"wer sandte die schriftrolle","wer schrieb glyphen-rolle","absender von glyphen-rolle"}},{q="Wo befindet sich Isabella?",a="Isabella hält sich in der zerstörten Dorfkirche im Zentrum von Todesend auf, zusammen mit anderen Klassenlehrern, die frisch auferstandenen Verlassenen Führung bieten.",al={"wo ist isabella","isabella finden","todesend magierlehrer standort"}},{q="Warum warnt Isabella Euch vor magischem Verderben?",a="Isabella mahnt, dass das unberechenbare Wesen der arkanen Macht unverändert bleibt, auch wenn die Verlassenen untot sind. Magie birgt noch immer die ständige Gefahr von Verderbnis und Sucht und verlangt Disziplin und Willen, um sie zu beherrschen, ohne von ihr verzehrt zu werden.",al={"magieverderbnis untote","arkane verderbnis lore","warum ist magie gefährlich für untote"}},{q="Warum ist Arkanmagie für die Verlassenen in Todesend wichtig?",a="Magier der Verlassenen betrachten arkane Macht als unverzichtbares Werkzeug, um Lordaeron zurückzuerobern und ihre Eigenständigkeit gegenüber der geistlosen Geißel, feindseligen lebenden Sterblichen und dem Scharlachroten Kreuzzug zu sichern.",al={"warum nutzen verlassene magie","untote magier lore"}},{q="Kann jede Klasse der Verlassenen diese Schriftrolle erhalten?",a="Nein. Die Glyphenrolle wird ausschließlich Magiern der Verlassenen als einleitende Vorladung zu ihrer primären Klassenlehrerin in Todesend überreicht.",al={"ist glyphen-rolle nur für magier","können hexenmeister glyphen-rolle erhalten","wer erhält glyphen-rolle"}}},fp="14,286,23.482.0,25.502.0,27.226.0,36.169.0,26.165.0,52.239.0,60.174.0,43.134.0"}
P.entries["quest:31"] = {n="Wassergestalt",s="Diese Quest markiert den letzten Schritt auf der Reise eines jungen Horde-Druiden zur Beherrschung der Gewässer. Nachdem er sich in Mondlichtung als würdig erwiesen und sich auf den Seelöwenaspekt eingestimmt hat, kehrt der Druide in seine Heimat nach Donnerfels zurück, um die formelle Anerkennung zu erhalten und seine Wassergestalt zu meistern.",h="Diese Quest markiert den letzten Schritt auf der Reise eines jungen Horde-Druiden zur Beherrschung der...",kw={"wassergestalt","dendrite sternenschauer","druide","mondlichtung","anhänger des seelöwen","seelöwe","donnerfels","turak runentotem"},ang={["class:Druid"]="Das Erlangen Eurer Wassergestalt schlägt eine Brücke zwischen Land und Meer, sodass Ihr Gewässer mühelos durchqueren und Räubern in der Tiefe entkommen könnt.",["faction:Horde"]="Tauren-Druiden stellen das spirituelle Bindeglied der Horde zum Zirkel des Cenarius dar und wandeln zwischen uralten neutralen Zufluchtsorten und ihren eigenen Stammeshauptstädten.",["race:Tauren"]="Turak Runentotem erinnert Euch daran, dass das Meistern der Meeresbestien Eure Ahnen ehrt und das heilige Wiederaufleben der druidischen Pfade bei den Tauren festigt."},sec={{t="Rückkehr des Seelöwen",b="Nachdem er den Prüfungen in der heiligen Zuflucht von Mondlichtung getrotzt hat, wird ein aufstrebender Tauren-Druide von Dendrite Sternenschauer zurück nach Mulgore gewiesen. Ausgestattet mit dem Anhänger des Seelöwen trägt der Initiand den physischen Beweis seines Gleichgewichts und seiner Hingabe über die Gewässer von Kalimdor hinweg. Er dient als greifbarer Beleg dafür, dass die uralten Traditionen respektiert wurden, die für die Annahme eines aquatischen Aspekts erforderlich sind."},{t="Einklang mit den Wassern",b="Nachdem der Reisende die Höhen von Donnerfels erklommen hat, überreicht er den Anhänger seinem Mentor Turak Runentotem. Erfreut darüber, dass der Initiand seine Ahnen und das natürliche Gleichgewicht ehrt, vermittelt Turak das Geheimnis der Wassergestalt. Mit dieser Lehre erlangt der Druide die angeborene Fähigkeit, unter die Oberfläche von Flüssen und Meeren zu gleiten, frei zu atmen und sich wie ein Meeresgeschöpf durch die Tiefen zu bewegen."}},faq={{q="Was ist der Zweck dieser Quest?",a="Diese Quest schließt den Übergangsritus für junge Horde-Druiden ab und erlaubt es ihnen, ihren hart verdienten Anhänger des Seelöwen in Donnerfels abzugeben, um schließlich ihre gestaltwandelnde Wassergestalt freizuschalten.",al={"warum diese quest machen","wassergestalt zweck","was bewirkt diese quest"}},{q="Zu wem bringe ich den Anhänger des Seelöwen?",a="Ihr müsst den Anhänger zu Turak Runentotem bringen, dem Druidenlehrer auf den oberen Anhöhen von Donnerfels in Mulgore.",al={"wer gibt dies ab","wo wassergestalt abgeben","turak runentotem standort"}},{q="Wer schickt Euch zurück nach Donnerfels?",a="Dendrite Sternenschauer, ein Nachtelfen-Hüter der Druiden im neutralen Zufluchtsort Mondlichtung, schickt Euch zurück, sobald Eure aquatischen Prüfungen abgeschlossen sind.",al={"wer gibt wassergestalt quest","dendrite sternenschauer quest"}},{q="Können Nicht-Druiden diese Quest abschließen?",a="Nein. Diese Questreihe ist im Rahmen ihres spirituellen und magischen Fortschritts zur Freischaltung von Tiergestalten streng auf Druiden beschränkt.",al={"nur für druiden","können andere klassen wassergestalt machen"}},{q="Warum hilft ein Nachtelf in Mondlichtung einem Horde-Druiden?",a="Mondlichtung ist ein neutraler Zufluchtsort unter der Aufsicht des Zirkels des Cenarius. Bei der Unterweisung in den uralten Künsten des cenarischen Pfades leiten Nachtelfen-Mentoren Tauren-Druiden ohne politische Feindseligkeit an und konzentrieren sich ausschließlich darauf, das Gleichgewicht der Natur zu wahren.",al={"warum hilft dendrite der horde","mondlichtung horde allianz","neutralität der druiden"}},{q="Welche Fähigkeit wird durch das Abschließen dieser Quest gewährt?",a="Nachdem Ihr die Quest bei Turak Runentotem abgegeben habt, wird Euch die Wassergestalt beigebracht, die im verwandelten Zustand ein erhöhtes Schwimmtempo und Unterwasseratmung gewährt.",al={"welche gestalt erhalte ich","wassergestalt zauber","wassergestalt"}}},fx={["269933c9"]={q="Warum schickt Euch Dendrite Sternenschauer zurück nach Donnerfels?",a="Dendrite Sternenschauer beaufsichtigt Eure Prüfungen in der Mondlichtung im Auftrag vom Zirkel des Cenarius, aber die Mondlichtung ist ein Heiligtum der Lehre und nicht Euer persönliches Zuhause. Nachdem er Eure Ausdauer und Ehrerbietung gegenüber dem Wasser getestet hat, ist Dendrites Pflicht erfüllt. Er schickt Euch zurück zu Eurem örtlichen Ausbilder, Turak Runetotem auf der Anhöhe der Ältesten in Donnerfels, um den Beweis Eurer Riten vorzulegen und den endgültigen Segen zu empfangen, der Euch die Aquatic Form gewährt.",al={"warum zu turak schicken","dendrite sternenschauer motiv","warum zurück nach donnerfels"}}},fp="12,268,22.381.0,25.390.0,34.200.0,46.120.0,36.147.0,35.127.0,53.231.0,46.153.0"}
P.entries["quest:310"] = {n="Bittere Rivalen",s="Bitter Rivals ist eine frühe Quest der Allianz in Dun Morogh, die aus der erbitterten Konkurrenz zwischen zwei stolzen zwergischen Braufamilien hervorgeht. Marleth Gerstenbräu schickt einen Abenteurer los, um die Brauerei Donnerbräu in Kharanos zu infiltrieren und den Vorrat der Konkurrenz zu manipulieren.",h="Bitter Rivals ist eine frühe Quest der Allianz in Dun Morogh, die aus der erbitterten Konkurrenz zwischen...",kw={"gerstenbräu-brüher","bitter rivals","dun morogh","kharanos","marleth gerstenbräu","donnerbier","brauerei donnerbräu"},ang={["class:Rogue"]="Das Infiltrieren eines bewachten Kellers, das Ablenken der Wache und der heimliche Austausch von Schmuggelware ist für jeden Schurken vertraute Arbeit, auch wenn der Gewinn Bier statt Gold ist.",["faction:Alliance"]="Kharanos ist für Allianz-Reisende das kulturelle und logistische Zentrum von Dun Morogh, wodurch Streitigkeiten in der örtlichen Taverne eine häufige Abwechslung für vorbeiziehende Rekruten sind.",["race:Dwarf"]="Für Zwerge ist das Brauen ein ernstes Geschäft, das beim Ansehen mit der Schmiedekunst konkurriert. Sich in einen Kellerstreit um konkurrierende Biere einzumischen, passt perfekt in die verschneiten Lande von Dun Morogh."},sec={{t="Ein Vorgeschmack auf den Wettbewerb",b="Wenige Dinge in Khaz Modan wecken so schnell Leidenschaften wie ein Glas Bier. Die Gerstenbräus stehen schon lange im Schatten der berühmten Brauerei Donnerbräu in Kharanos. Obwohl Marleth Gerstenbräu zähneknirschend zugibt, dass das Handwerk der Donnerbräus respektabel ist, kann sie den Gedanken nicht ertragen, dass es der einzige bekannte Jahrgang in Dun Morogh sein soll. Um den lokalen Gaumen wachzurütteln, entwickelt sie einen Plan, ein Fass Donnerbier gegen ihre eigene feurige Kreation, den Gerstenbräu-Brüher, auszutauschen."},{t="List im Keller",b="Um den Plan auszuführen, muss man sich direkt unter der Nase der Gäste von Kharanos hindurchschleichen. Unter der Küche der Brauerei befindet sich das Kellerlager, in dem die Fässer zur Reifung darauf warten, angezapft zu werden. Da die Donnerbräus einen Wächter bei ihrem wertvollsten Vorrat postiert haben, muss ein Möchtegern-Saboteur einen Weg finden, den Wachmann wegzulocken, bevor er heimlich die Fässer austauscht."}},faq={{q="Wer vergibt die Quest Bitter Rivals?",a="Marleth Gerstenbräu vergibt die Quest. Sie ist entschlossen zu beweisen, dass das Handwerk ihrer Familie mit den berühmten Getränken, die in der Brauerei Donnerbräu ausgeschenkt werden, konkurrieren kann.",al={"wer startet bitter rivals","marleth questgeber"}},{q="Wo befindet sich der Keller der Brauerei Donnerbräu?",a="Der Keller befindet sich unter der Brauerei Donnerbräu in der Stadt Kharanos. Die Treppe, die nach unten führt, ist hinter einem Tisch in der Küche versteckt.",al={"wo ist der donnerbräu keller","wie kommt man in den keller der brauerei"}},{q="Was ist der Gerstenbräu-Brüher?",a="Der Gerstenbräu-Brüher ist Marleths starkes Hausbier. Sie glaubt, dass die Gäste in Kharanos, wenn sie es unter dem Deckmantel von Donnerbier probieren, endlich ihre Überlegenheit beim Brauen erkennen werden.",al={"gerstenbräu-brüher","welches bier soll ich austauschen"}},{q="Wie umgeht man die Wache, die die Fässer bewacht?",a="Die Wache der Donnerbräus, die unten im Keller postiert ist, gibt Hinweise darauf, was seine Aufmerksamkeit ablenken könnte, und gibt Euch genau genug Zeit, die Fässer auszutauschen, während er abgelenkt ist.",al={"kellerwache ablenkung","unbewachtes donnerbier-fass","fass bewachen"}},{q="Warum streiten sich die Gerstenbräus und die Donnerbräus?",a="Es ist eine Frage des professionellen zwergischen Stolzes. Die Donnerbräus beherrschen die lokale Tavernenszene in Kharanos, und die Gerstenbräus wollen beweisen, dass ihre eigenen Rezepte genauso gut, wenn nicht sogar besser sind.",al={"brauereistreit","warum hassen die gerstenbräus die donnerbräus"}},{q="Welche Quest folgt auf Bitter Rivals?",a="Sobald das Fass mit dem Gerstenbräu-Brüher an seinem Platz steht, führt die Quest direkt zu Return to Marleth, um Euren Erfolg zu melden.",al={"nächste quest nach bitter rivals","was kommt nach bitter rivals"}}},fx={["6a423fcc"]={q="Warum will Marleth Gerstenbräu die Bierfässer austauschen?",a="Marleth Gerstenbräu steckt in einem erbitterten, langjährigen Wettbewerb mit dem Thunderbrew-Clan darüber, wer das beste Bier in ganz Dun Morogh braut. Obwohl sie widerwillig zugibt, dass die Thunderbrews ein ordentliches Getränk herstellen, kann sie ihr Prahlen nicht ausstehen und will beweisen, dass ihr eigener Gerstenbräu-Aufwiegler überlegen ist. Indem sie ihr Fass in den Keller der Brauerei Donnerbräu schmuggelt, hofft sie, dass deren treue Kunden es trinken, merken, wie gut es ist, und die Thunderbrews damit ein wenig herabstufen.",al={"warum fässer tauschen","marleths motiv","warum das bier austauschen"}},c3ae0653={q="Warum braucht Marleth Gerstenbräu Euch anstatt es selbst zu tun?",a="Marleth ist in Kharanos viel zu bekannt, als dass sie unbemerkt in den Keller ihres Rivalen spazieren könnte. Die Brauerei Donnerbräu überwacht ihren Keller genau und jedes Erscheinen eines bekannten Mitglieds der Familie Gerstenbräu würde sofort Alarm schlagen. Als unbekannter Reisender könnt Ihr in die Brauerei schlüpfen, einen Weg am Kellerwächter vorbei finden und die Fässer austauschen, ohne den ganzen Plan sofort auffliegen zu lassen.",al={"warum kann marleth es nicht selbst tun","warum ich bitter rivals","warum einen außenstehenden anheuern"}}},fp="13,260,22.466.0,17.369.0,34.154.0,40.144.0,27.195.0,49.179.0,49.197.0,33.120.0"}
P.entries["quest:3103"] = {n="Geheiligter Brief",s="Der Geheiligte Brief ist eine formelle Vorladung, die vielversprechenden jungen Priestern von Marschall McBride im Namen der ansässigen Ausbilderin der Abtei von Nordhain, Priesterin Anetta, überreicht wird. Er markiert den Beginn der offiziellen Unterweisung eines angehenden Priesters in den Lehren des Heiligen Lichts inmitten einer unruhigen und verwundbaren Welt.",h="Der Geheiligte Brief ist eine formelle Vorladung, die vielversprechenden jungen Priestern von Marschall...",kw={"elwynn","geheiligter brief","heiliges licht","marschall mcbride","abtei von nordhain","priester","priesterin anetta"},ang={["class:Priest"]="Diese Quest markiert Eure offizielle Aufnahme als Schüler des Heiligen Lichts unter Priesterin Anetta und stellt Eure göttliche Magie als entscheidende Pflicht dar, eine zerrüttete Welt zu heilen.",["race:Human"]="Die Abtei von Nordhain ist seit langem eine Zuflucht des Glaubens und der Genesung für das Königreich Sturmwind und führt ihre Traditionen trotz der heranrückenden Unruhen rund um Elwynn fort."},sec={{t="Ein Ruf zum Priesteramt",b="Nachdem sie ihren Mut gegen das Ungeziefer bewiesen haben, das in die Weinberge von Nordhain eindringt, erhalten novizische Priester ein Schreiben, das das heilige Siegel von Priesterin Anetta trägt. Der durch Marschall McBride überbrachte Brief dient als Einladung, das ernsthafte Studium des Heiligen Lichts in den stillen Hallen der Abtei aufzunehmen."},{t="Eine Welt in Not",b="Wird ihr der Brief überreicht, schärft Priesterin Anetta ihrem neuen Schüler den düsteren Zustand des Reiches ein. Fortwährende Bedrohungen durch die Brennende Legion werfen lange Schatten über Azeroth, während die Kontinente mit frischen Wunden und Unruhen ringen. In ihren Augen ist die Ergreifung des Priesteramts nicht bloß eine akademische Hingabe, sondern eine dringende moralische Verantwortung, einer leidenden Welt Heilung und Trost zu spenden."}},faq={{q="Was ist der Geheiligte Brief?",a="Es ist ein versiegelter Brief mit dem Wappen von Priesterin Anetta, der neu eingetroffenen menschlichen Priestern von Marschall McBride im Nordhaintal übergeben wird. Er weist den Novizen an, seine Ausbildung in der Abtei von Nordhain offiziell aufzunehmen.",al={"geheiligter brief","priester intro quest nordhain","anetta brief"}},{q="Wer verschickt den Geheiligten Brief?",a="Priesterin Anetta, die in der Abtei von Nordhain stationierte Priesterlehrerin, verfasst und versiegelt das Schreiben und bittet Marschall McBride, es zu übergeben, sobald der Initiand von der Auskundschaftung der Koboldplage zurückkehrt.",al={"wer schrieb geheiligter brief","wer sandte den brief"}},{q="Warum ruft Priesterin Anetta neue Priester zu sich?",a="Anetta erkennt die Berufung des Novizen zum Heiligen Licht und möchte dessen Ausbildung leiten. Angesichts von Gefahren wie den in der Welt verbliebenen Überresten der Brennenden Legion betont sie, dass disziplinierte Heiler und Führer dringend benötigt werden.",al={"warum will anetta mich","zweck des briefes"}},{q="Wo ist Priesterin Anetta zu finden?",a="Sie hält sich in der Haupthalle der Abtei von Nordhain auf, bereit, menschliche Priester auszubilden, während sie ihre ersten Gebete und Rituale meistern.",al={"wo ist anetta","priesterin anetta aufenthaltsort"}},{q="Was geschieht, nachdem der Brief Priesterin Anetta vorgelegt wurde?",a="Nachdem sie den Brief gelesen und die Begrüßung empfangen hat, nimmt Anetta den Spieler als ihren Schüler auf, vermittelt grundlegende Weisheiten und lädt ihn ein, für weiteres Training zurückzukehren, während er an Erfahrung gewinnt.",al={"folgequest nach geheiligter brief","was folgt auf geheiligter brief"}},{q="Warum wird die Brennende Legion in Nordhain erwähnt?",a="Obwohl der Dritte Krieg endete, suchen dämonische Überreste der Legion Azeroth noch immer heim. Priesterin Anetta erwähnt diese weltweite Bedrohung, um die größeren Gefahren zu unterstreichen, die jeden Abenteurer erwarten, der das Tal verlässt.",al={"brennende legion nordhain","warum spricht anetta über dämonen"}}},fp="15,292,22.311.0,15.409.0,28.217.0,30.202.0,45.233.0,36.130.0,61.180.0,50.205.0"}
P.entries["quest:3104"] = {n="Glyphenbrief",s="Der Glyphenbrief ist eine formelle Vorladung, die angehenden menschlichen Magiern im Nordhaintal von Marschall McBride überreicht wird. Unter dem arkane Siegel von Khelden Bremen verfasst, ruft das Schreiben vielversprechende Zauberwirker in die Abtei von Nordhain, um ihre offizielle Unterweisung in den arkanen Künsten zu beginnen.",h="Der Glyphenbrief ist eine formelle Vorladung, die angehenden menschlichen Magiern im Nordhaintal von...",kw={"arkan","wald von elwynn","glyphenbrief","khelden bremen","magier","marschall mcbride","abtei von nordhain"},ang={["class:Mage"]="Diese Quest markiert Euren offiziellen Übergang von einem rohen, ungeschliffenen Talent zu einem anerkannten Lehrling der arkanen Künste von Sturmwind unter Khelden Bremen.",["race:Human"]="Nordhains menschliche Magier treten das Erbe der ersten menschlichen Arkanisten von Dalaran und den Kirin Tor an und tragen die arkane Macht in das Königreich Sturmwind."},sec={{t="Eine Vorladung zur Arkanmagie",b="Sobald ein aufstrebender Lehrling seine Fähigkeiten unter Beweis stellt, indem er Marschall McBride gegen das örtliche Ungeziefer beisteht, überreicht der Garnisonskommandant ihm eine mit arkanen Runen versehene Botschaft. Der Brief stammt direkt von Khelden Bremen, dem ansässigen Magierlehrer von Nordhain, der die an der Abtei eintreffenden Rekruten auf Anzeichen magischer Disziplin und Begabung hin mustert."},{t="Das Gewicht der Zauberkunst",b="Die Abtei von Nordhain diente historisch stets als Zuflucht für das Heilige Licht, doch die anhaltenden Gefahren für Sturmwind verlangen nach Vertretern jeder Disziplin. Wer dem Brief folgt, gelangt nach oben zu Khelden Bremen. Statt leichtfertigen Lobes erteilt der Lehrer eine ernste Warnung: Die Beherrschung arkaner Macht erfordert das Überwinden natürlicher Grenzen, was bei gewöhnlichen Leuten sowohl tiefen Respekt als auch tief sitzende Furcht hervorruft."}},faq={{q="Wer überbringt den Glyphenbrief?",a="Marschall McBride überreicht den Brief neu eingetroffenen Magiern vor der Abtei von Nordhain, sobald sie geholfen haben, das nahegelegene Kobold-Ungeziefer zu beseitigen.",al={"wer vergibt glyphen-brief","glyphen-brief questgeber"}},{q="Wer hat den Glyphenbrief verfasst?",a="Der Brief wurde von Khelden Bremen verfasst und versiegelt, dem ansässigen Magierlehrer in den oberen Gemächern der Abtei von Nordhain.",al={"autor von glyphen-brief","wer schickte glyphen-brief"}},{q="Wo finde ich Khelden Bremen?",a="Betretet die Abtei von Nordhain hinter Marschall McBride, nehmt den linken Korridor, geht die Treppe hinauf und seht in den hinteren Gemächern nach, wo Khelden darauf wartet, zu unterrichten.",al={"khelden bremen standort","wo ist khelden"}},{q="Warum befindet sich der Magierlehrer in einer Abtei?",a="Obwohl die Abtei von Nordhain im Grunde eine heilige Zuflucht ist, nutzt Sturmwind das Tal als anfängliches Ausbildungslager für Verteidiger aller Disziplinen und stationiert arkane Lehrer an der Seite von Klerikern und Marschällen.",al={"warum magier in abtei von nordhain","magierlehrer in heiliger abtei"}},{q="Was geschieht nach Abgabe des Briefes?",a="Khelden Bremen nimmt Euch als seinen Schüler an, begrüßt Eure Entschlossenheit, die Arkanmagie trotz ihrer Gefahren zu nutzen, und bietet direkten Zugang zur grundlegenden Zauberausbildung.",al={"was folgt auf glyphen-brief","nächste quest nach glyphen-brief"}},{q="Warum warnt Khelden davor, dass Magier gefürchtet werden?",a="Arkane Magie ist eine unbeständige, die Realität beugende Kraft. Khelden erinnert Lehrlinge daran, dass das Streben nach höchstem Wissen bedeutet, Grenzen zu überschreiten, was normale Menschen zutiefst verunsichert.",al={"warum werden magier gefürchtet","khelden bremen dialog"}}},fp="14,275,23.348.0,22.425.0,32.137.0,29.135.0,31.157.0,44.207.0,41.155.0,48.178.0"}
P.entries["quest:3105"] = {n="Besudelter Brief",s="Der Besudelte Brief ist eine diskrete Vorladung, die an unerfahrene menschliche Hexenmeister übergeben wird, die im Nordhaintal ausgebildet werden. Das Schreiben wurde Marschall McBride von der verschwiegenen Ausbilderin Drusilla La Salle anvertraut und ruft die Initianden abseits der neugierigen Blicke der Wachen der Abtei herbei, um ihre formelle Unterweisung in den Teufelskünsten zu beginnen.",h="Der Besudelte Brief ist eine diskrete Vorladung, die an unerfahrene menschliche Hexenmeister übergeben wird...",kw={"verderbnis","drusilla la salle","wald von elwynn","marschall mcbride","abtei von nordhain","besudelter brief","wirbelnder nether","hexenmeister"},ang={["class:Warlock"]="Diese Quest stellt die formelle Rekrutierung menschlicher Hexenmeister in Nordhain dar und begründet das heikle Gleichgewicht zwischen dem Verstecken vor verurteilenden Wachen und dem Meistern gefährlicher Nethermagie.",["race:Human"]="Die Kultur der Menschen verehrt überwiegend das Heilige Licht und die disziplinierte Arkanmagie der Kirin Tor, was menschliche Hexenmeister dazu zwingt, ihre Beschwörungen an den stillen Rändern von Siedlungen wie Nordhain zu praktizieren."},sec={{t="Eine diskrete Vorladung",b="Während Priester und Paladine offen in den geweihten Hallen der Abtei von Nordhain studieren, müssen Praktizierende dunklerer Magie vorsichtig vorgehen. Nachdem sie ihre Fähigkeiten gegen die örtliche Koboldbedrohung unter Beweis gestellt haben, erhalten angehende Hexenmeister einen von Marschall McBride überbrachten Brief. Das Schreiben trägt das Siegel von Drusilla La Salle und weist den jungen Zauberwirker an, sich direkt bei ihrem abgelegenen Posten außerhalb der Hauptmauern der Abtei zu melden, bevor er irgendwelchen anderen Pflichten nachgeht."},{t="Versuchung und Ehrgeiz",b="Die Begegnung mit Drusilla offenbart die prekäre Natur des Pfades eines Hexenmeisters unter den wachsamen Augen der Wachen von Sturmwind, die sie als 'armselige Gewöhnliche' abtut. Drusilla spricht gegenüber Eurem Schüler eine unverblümte Warnung aus: Macht aus dem Wirbelnden Nether zu schöpfen und mit Dämonen zu verkehren birgt eine allgegenwärtige Gefahr der Verderbnis. Obwohl sie zu Geduld, Umsicht und unerschütterlicher Selbstbeherrschung rät, um nicht den dunklen Energien anheimzufallen, die sie manipulieren, macht sie deutlich, dass solche Vorsicht niemals den brennenden Ehrgeiz ersticken sollte."}},faq={{q="Wer schickt den Besudelten Brief?",a="Der Brief wurde von Drusilla La Salle verfasst und versiegelt, der örtlichen Hexenmeisterausbilderin, die sich direkt außerhalb der Abtei von Nordhain aufhält. Sie bittet Marschall McBride, ihn Euch zu übergeben, sobald Ihr von der Säuberung der nahegelegenen Koboldlager zurückkehrt.",al={"wer schrieb besudelter brief","verfasser besudelter brief","wer gibt den besudelten brief"}},{q="Warum überbringt Marschall McBride einen Hexenmeisterbrief?",a="Marschall McBride fungiert im Tal lediglich als Bote, der Nachrichten an vielversprechende Rekruten weiterleitet. Obwohl er weiß, dass der Brief Drusillas Siegel trägt, und darauf beharrt, dass er Vorrang hat, gilt sein Hauptaugenmerk der Verteidigung und Verwaltung von Nordhain und nicht der Überwachung der spezifischen magischen Praktiken seiner Verteidiger.",al={"warum hat mcbride ihn","weiß mcbride was der brief ist","mcbride hexenmeisterbrief"}},{q="Wo kann ich Drusilla La Salle finden?",a="Drusilla La Salle steht vor dem Haupteingang der Abtei von Nordhain, nahe den Außenmauern und Zelten abseits der Kleriker im Inneren.",al={"drusilla aufenthaltsort","wo ist drusilla la salle","drusilla finden"}},{q="Warum werden Hexenmeister in der Abtei von Nordhain geduldet?",a="Hexenmeister stehen auf dem Gebiet der Allianz unter schwerem Verdacht und halten sich im Hintergrund. In Nordhain verlegt Drusilla ihre Ausbildung außerhalb des eigentlichen Heiligtums und hält sich im Freien auf, wo sie Rekruten unterrichten kann, während sie eine direkte Konfrontation mit den Klerikern und Paladinen des Heiligen Ordens von Nordhain vermeidet.",al={"hexenmeister in nordhain","ist teufelsmagie legal in nordhain","warum hexenmeister erlauben"}},{q="Welche Lehre erteilt Drusilla nach Erhalt des Briefes?",a="Drusilla warnt davor, dass das Schöpfen aus dem Wirbelnden Nether jedem Praktizierenden Verderbnis bringt, dem es an Disziplin mangelt. Sie rät zu strikter Selbstbeherrschung und Umsicht und betont gleichzeitig, dass die Furcht vor Verderbnis niemals den persönlichen Ehrgeiz eines Hexenmeisters zunichtemachen sollte.",al={"drusillas rat","was sagt drusilla","lektion aus besudeltem brief"}},{q="Was folgt nach der Übergabe des Besudelten Briefes?",a="Das Gespräch mit Drusilla schließt die Vorladung ab und macht sie zu Eurer Ausbilderin; sie lädt Euch ein, zurückzukehren, wenn Ihr mächtiger werdet, um mehr über die Wege des Hexenmeisters zu lernen.",al={"folgequest nach besudeltem brief","besudelter brief folge"}}},fp="14,304,18.465.0,23.538.0,29.223.0,50.315.0,35.143.0,45.296.0,58.248.0,47.161.0"}
P.entries["quest:3106"] = {n="Einfache Rune",s="Einfache Rune ist eine Einführungsaufgabe für angehende Zwergenkrieger im Coldridgetal. Sie wird von Sten Starkarm im Namen des Kriegerlehrers Thran Khorman überreicht und schickt neue Rekruten nach Ambossar hinein, um ihre Kampfausbildung zu beginnen.",h="Einfache Rune ist eine Einführungsaufgabe für angehende Zwergenkrieger im Coldridgetal.",kw={"ambossar","das coldridgetal","dun morogh","eisenschmiede","einfache rune","sten starkarm","thran khorman","troggs","krieger"},ang={["class:Warrior"]="Diese Rune markiert den formellen Eintritt eines Kriegers in die kämpferische Disziplin und leitet neue Klingen und Streitkolben direkt zu Thran Khorman in Ambossar.",["faction:Alliance"]="Das Coldridgetal dient als anfängliches Trainingsgelände für die Gebirgstruppen, die die südlichen Zugänge der Allianz nach Khaz Modan verteidigen.",["race:Dwarf"]="Thran Khorman erfüllt es mit großem Stolz, zwergischen Rekruten das Kämpfen mit traditioneller Härte beizubringen, was ihre Kultur in einer sich rasant wandelnden Welt in Stahl und Eisen verankert.",["race:Gnome"]="Nachdem sie Gnomeregan an Troggs und Strahlung verloren haben, müssen gnomische Kämpfer, die im Coldridgetal beginnen, an der Seite zwergischer Ausbilder den Kampf an vorderster Front erlernen, um das Exil zu überstehen."},sec={{t="Ein Ruf an den Amboss",b="Während junge Rekruten Schädlinge beseitigen und im Coldridgetal ihren Mut beweisen, halten erfahrene Späher ein wachsames Auge auf vielversprechende Kämpfer gerichtet. Sten Starkarm überreicht eine beschriftete Schiefertafel – eine einfache Rune –, die ihm von Thran Khorman übergeben wurde. Dieser Ruf beordert künftige Kämpfer von den verschneiten Pfaden des Tals in die warme Schmiedehalle von Ambossar, um sich feierlich dem Handwerk des Kriegers zu verschreiben."},{t="Ein verändertes Dun Morogh",b="Sich bei Thran zu melden bietet einen unmittelbaren Einblick in die harten Realitäten, denen das moderne Dun Morogh gegenübersteht. Der erfahrene Ausbilder spricht offen über den Wandel des Königreichs: vertriebene Gnome, die Zuflucht suchen, nachdem katastrophale Explosionen Gnomeregan zerstört haben, Zwergenbrüder, die fremde arkane Künste ausüben oder die menschliche Hingabe an das Heilige Licht übernehmen, und eine allgegenwärtige Bedrohung durch unterirdische Troggs, die an den Berggrenzen kratzen. In Thrans Augen bleibt solide militärische Disziplin das Fundament, das nötig ist, um dem Ganzen standzuhalten."}},faq={{q="Was ist die Einfache Rune?",a="Die Einfache Rune ist eine kleine, beschriftete Schiefertafel, die von Sten Starkarm im Namen von Thran Khorman überreicht wird. Sie dient als offizielle Einladung und Anweisung für neue Krieger, sich drinnen zur professionellen Ausbildung einzufinden.",al={"einfache rune gegenstand","was bewirkt die rune","einfache rune lore"}},{q="Wer ist Thran Khorman?",a="Thran Khorman ist der ansässige Kriegerlehrer in Ambossar im Coldridgetal. Er unterweist angehende Zwergen- und Gnomenkrieger in den Grundlagen des Nahkampfs, in Disziplin und in zwergischer Zähigkeit.",al={"wer ist thran","thran khorman lore","kriegerlehrer coldridgetal"}},{q="Warum leben Gnome in Dun Morogh und Eisenschmiede?",a="Die Gnome wurden vor Kurzem aus ihrem unterirdischen technologischen Wunderwerk Gnomeregan vertrieben, nachdem sie in einem verzweifelten Versuch, eine unterirdische Trogg-Invasion abzuwehren, katastrophale Strahlungssprengsätze gezündet hatten. Die Überlebenden flohen den Berghang hinauf, um bei ihren Zwergenverbündeten in Eisenschmiede Zuflucht zu suchen.",al={"warum sind gnom hier","gnom in eisenschmiede","gnomeregan flüchtlinge"}},{q="Warum erwähnt Thran Troggs?",a="Troggs sind primitive, bösartige Kreaturen, die vor Kurzem in die Höhlen an der Oberfläche im Coldridgetal und in Dun Morogh eingedrungen sind, nachdem sie tief unter der Erde aufgeschreckt wurden. Sie stellen eine unmittelbare Gefahr für die örtlichen Siedlungen und Handelswege dar und erfordern bewaffnete Wachsamkeit von den Verteidigern in Ambossar.",al={"trogg-bedrohung","warum gibt es troggs","coldridge-troggs"}},{q="Was meint Thran damit, dass Zwerge das Heilige Licht anbeten?",a="Traditionell an uralte Bergbräuche und die Ehrung der Titanen gebunden, haben Zwerge durch Jahrhunderte enger kultureller Bündnisse mit menschlichen Königreichen wie Lordaeron und Sturmwind zunehmend die Philosophie des Heiligen Lichts angenommen und bilden eigene Paladine und Priester aus.",al={"zwerge und das heilige licht","zwergenpaladine lore","zwergenpriester"}},{q="Wohin bringe ich die Einfache Rune?",a="Die Rune wird direkt zu Thran Khorman gebracht, der auf dem Übungsplatz in der großen Bunkerhalle von Ambossar steht, gleich den Pfad hinauf im Coldridgetal.",al={"einfache rune abgeben","wo ist thran khorman","thran finden"}}},fp="11,242,22.389.0,21.522.0,24.215.0,21.231.0,50.294.0,30.278.0,62.277.0,32.159.0"}
P.entries["quest:3107"] = {n="Geweihte Rune",s="Die Geweihte Rune ist eine einleitende Vorladung, die an angehende Zwergenpaladine im Coldridgetal überbracht wird. Sie wird von Sten Starkarm im Namen von Bromos Grummler überreicht und markiert die formelle Aufnahme eines Initianden in die Ritter der Silbernen Hand.",h="Die Geweihte Rune ist eine einleitende Vorladung, die an angehende Zwergenpaladine im Coldridgetal überbracht...",kw={"ambossar","bromos grummler","das coldridgetal","geweihte rune","das heilige licht","paladinlehrer","die silberne hand","sten starkarm"},ang={["class:Paladin"]="Diese Rune markiert Euren ersten formellen Schritt in die Ritter der Silbernen Hand und begründet Eure Pflicht, das Licht zur Verteidigung von Eisenschmiede zu lenken.",["race:Dwarf"]="Zwergenpaladine verbinden traditionelle zwergische Standhaftigkeit mit von Menschen gelehrter Theologie und verleihen den Lehren des Heiligen Lichts unerschütterliche Entschlossenheit."},sec={{t="Eine Vorladung nach Ambossar",b="Während unerfahrene Abenteurer Troggs und Wölfe rund um das Coldridgetal beseitigen, behalten die örtlichen Anführer diejenigen genau im Auge, die eine Gabe für göttliches kriegerisches Können an den Tag legen. Sten Starkarm überbringt diese beschriftete Rune jungen Paladinen und weist sie an, Bromos Grummler in der Wärme von Ambossar aufzusuchen. Sie dient sowohl als Einladung als auch als offizielle Mitteilung, dass rohes Potenzial nun durch Disziplin gehärtet werden muss."},{t="Zwerge und das Heilige Licht",b="Obwohl die Ritter der Silbernen Hand ihren Ursprung unter den Menschen von Lordaeron hatten, nahmen die Zwerge von Eisenschmiede die Philosophie des Heiligen Lichts mit unerschütterlicher Hingabe an. Bromos Grummler heißt die Initianden in der Bruderschaft willkommen und erinnert sie daran, dass Zwergenpaladine nun die feierliche Pflicht teilen, Azeroth zu beschützen. Gegründet auf Aufopferung, Tradition und kriegerischer Tugend verlangt der Orden von den Rekruten, Hammer und Glauben zu gleichen Teilen zu ergreifen."}},faq={{q="Was ist die Geweihte Rune?",a="Es ist ein beschriftetes Zeichen, das angehenden Zwergenpaladinen im Coldridgetal überbracht wird und sie anweist, sich bei Bromos Grummler in Ambossar für ihre formelle Ausbildung zu melden.",al={"geweihte rune gegenstand","was macht die rune","paladinrune coldridge"}},{q="Wer ist Bromos Grummler?",a="Bromos Grummler ist der in Ambossar stationierte örtliche Paladinlehrer. Er unterweist neue zwergische Mitglieder der Ritter der Silbernen Hand und bereitet sie auf die Gefahren vor, die Dun Morogh bedrohen.",al={"wer ist bromos","paladinlehrer ambossar","bromos grummler lore"}},{q="Warum sind Zwerge Teil der Ritter der Silbernen Hand?",a="Während des Zweiten Krieges und in dessen Nachwirkungen brachten menschliche Priester und Paladine den Zwergen von Eisenschmiede die Lehren des Heiligen Lichts näher. Die Zwerge schätzen die kriegerische Disziplin des Ordens und seine Bereitschaft zutiefst, Opfer für die Verteidigung von Azeroth zu bringen.",al={"zwergenpaladin lore","warum haben zwerge paladine","silberne hand zwerge"}},{q="Wer gibt Euch die Geweihte Rune?",a="Sten Starkarm übergibt Euch die Rune vor Ambossar, nachdem Ihr ihm bei lokalen Aufgaben geholfen habt, und bemerkt, dass Bromos Grummler um deren Zustellung gebeten hat.",al={"woher bekommt man die rune","wer übergibt die rune"}},{q="Wo befindet sich Bromos Grummler?",a="Bromos Grummler befindet sich in der großen Halle von Ambossar im Coldridgetal, wo er neben anderen Klassenlehrern steht.",al={"bromos standort","wo ist bromos","bromos grummler finden"}},{q="Was geschieht, nachdem man Bromos die Rune vorgelegt hat?",a="Bromos bestätigt Eure Aufnahme in die Silberne Hand und bietet Eure erste formelle Kampf- und Heiligenausbildung an, bevor er Euch wieder hinaus nach Dun Morogh schickt.",al={"was kommt danach","nach geweihter rune"}}},fp="16,245,21.418.0,26.433.0,29.165.0,23.194.0,55.247.0,35.150.0,33.123.0,49.155.0"}
P.entries["quest:3108"] = {n="Geätzte Rune",s="Die Geätzte Rune ist eine schriftliche Aufforderung, die an unerfahrene Zwergenjäger überreicht wird, welche der Wache im Coldridgetal helfen. Überbracht von Sten Starkarm, weist der beschriftete Stein angehende Fährtenleser an, Thorgas Grimson in Ambossar aufzusuchen, um ihre Ausbildung im Kampf und in der Wildnis offiziell zu beginnen.",h="Die Geätzte Rune ist eine schriftliche Aufforderung, die an unerfahrene Zwergenjäger überreicht wird, welche...",kw={"ambossar","das coldridgetal","dun morogh","zwerg","geätzte rune","jäger","sten starkarm","thorgas grimson"},ang={["class:Hunter"]="Diese Rune leitet Eure Reise als Jäger in Dun Morogh ein und stellt Euch Thorgas Grimson sowie die grundlegenden zwergischen Traditionen des Spurenlesens, der Waffenpflege und des Wildnisüberlebens vor.",["race:Dwarf"]="Das Meißeln von Botschaften in massiven Stein spiegelt die tief verwurzelte Ehrfurcht der Zwerge vor dauerhaftem Handwerk wider – selbst bei alltäglichen Vorladungen und Befehlen im Feld."},sec={{t="Eine Aufforderung in Stein",b="Während sie Sten Starkarm dabei helfen, nahe Bedrohungen rund um das Coldridgetal zu bewältigen, erhalten vielversprechende Zwergenjäger eine beschriftete Steintafel, die als Geätzte Rune bekannt ist. Anstatt mündliche Befehle oder einfaches Pergament zu nutzen, bevorzugen Zwergenmentoren gemeißelte Runen, um formelle Botschaften zu übermitteln. Die Rune weist den Empfänger an, seine ersten Erfolge Revue passieren zu lassen und sich im Inneren von Ambossar einzufinden, um tiefer in die Kunst der Jagd eingeweiht zu werden."},{t="Traditionen des Jägers von Dun Morogh",b="Die Vorlage der Rune bei Thorgas Grimson markiert den Eintritt eines Jägers in die formelle Disziplin. Thorgas betont, dass das Überleben und Bergsteigen in Khaz Modan tiefen Respekt vor der rauen Natur erfordern: Spuren im eisigen Schneetreiben lesen, Waffen und Munition instand halten und die wilden Tiere der schroffen Hänge verstehen. Der behauene Stein dient dem Jäger als erster Schritt von einem einsamen Wanderer mit einer Waffe hin zu einem Lehrling der erfahrenen Pfadfinder von Ambossar."}},faq={{q="Was ist die Geätzte Rune?",a="Es ist eine beschriftete Steintafel, die unerfahrenen Jägern im Coldridgetal übergeben wird und als schriftliche Einladung dient, die offizielle Ausbildung bei Thorgas Grimson in Ambossar zu beginnen.",al={"was ist geätzte rune","geätzte rune gegenstand","bedeutung rune"}},{q="Wer sendet die Geätzte Rune?",a="Der Jägerlehrer Thorgas Grimson sendet sie, doch sie wird Euch persönlich vom Gebirgsjäger Sten Starkarm überreicht, sobald Ihr Euer grundlegendes Können außerhalb von Ambossar unter Beweis gestellt habt.",al={"wer gab mir geätzte rune","absender geätzte rune"}},{q="Wohin bringe ich die Geätzte Rune?",a="Ihr bringt sie zu Thorgas Grimson, der in der großen Halle von Ambossar im Coldridgetal zu finden ist.",al={"wo muss ich hin","bei wem abgeben","thorgas aufenthaltsort"}},{q="Warum benutzen Zwerge Runen anstelle von Briefen?",a="Die Kultur der Zwerge misst Steinmetzkunst, Tradition und beständigem Handwerk einen hohen Wert bei. Das Einmeißeln von Botschaften und heiligen Anweisungen auf Steinrunen stellt sicher, dass sie den schneidenden Winden und rauen Elementen von Dun Morogh weitaus besser trotzen als zerbrechliches Pergament.",al={"warum geätzte rune","zwergenrunen lore"}},{q="Was passiert nach der Abgabe der Rune bei Thorgas Grimson?",a="Thorgas heißt Euch in den Reihen der Zwergenfährtenleser willkommen und erklärt die Grundpfeiler des Überlebens in den gefrorenen Klippen, die Pflege Eurer Ausrüstung und den Respekt vor den Bestien der Wildnis, bevor er Euch in einfachen Jägertechniken unterweist.",al={"was lehrt thorgas","geätzte rune abgeben"}},{q="Kann jede Klasse die Geätzte Rune erhalten?",a="Nein. Die Geätzte Rune wird eigens Zwergenjägern übergeben, die ihre Reise im Coldridgetal beginnen. Andere Klassen erhalten jeweils eigene Rekrutierungszeichen, die sie zu ihren entsprechenden Mentoren in Ambossar führen.",al={"ist geätzte rune nur für jäger","können krieger geätzte rune bekommen"}}},fp="11,289,18.443.0,35.466.0,24.175.0,26.172.0,32.104.0,44.243.0,58.235.0,38.218.0"}
P.entries["quest:3109"] = {n="Verschlüsselte Rune",s="Die Verschlüsselte Rune ist ein codiertes Schreiben, das angehenden Schurken überbracht wird, die ihre ersten Schritte im Coldridgetal wagen. Die von Sten Starkarm weitergegebene, gravierte Botschaft weist vielversprechende Schatten nach Ambossar, um sich beim Schurkenlehrer Solm Hargrin zu melden.",h="Die Verschlüsselte Rune ist ein codiertes Schreiben, das angehenden Schurken überbracht wird, die ihre ersten...",kw={"ambossar","das coldridgetal","dun morogh","verschlüsselte rune","gnomeregan","schurkenlehrer","solm hargrin","sten starkarm"},ang={["class:Rogue"]="Diese Rune markiert Euren ersten formellen Kontakt mit dem Schurkennetzwerk in Dun Morogh und führt Euch zu Solm Hargrin, um mit dem Verfeinern Eurer Heimlichkeit, Kampftricks und Eures Überlebenshandwerks zu beginnen.",["race:Dwarf"]="Solm heißt zwergische Gefährten des Eisenschmiede-Klans in den Schatten willkommen und bemerkt, dass es nichts Besseres als eine kalte Klinge und die Dunkelheit gibt, um einen Agenten in Dun Morogh am Leben zu halten.",["race:Gnome"]="Solm ermahnt seine Schüler, den Gnomen Kameradschaft zu erweisen, die nach dem tragischen Verlust ihrer Heimat in Gnomeregan im Coldridgetal Zuflucht suchen."},sec={{t="Eine codierte Botschaft",b="Während sie Sten Starkarm in den verschneiten Pässen des Coldridgetals beistehen, erhalten scharfsinnige Schurken einen merkwürdigen gravierten Stein. Sten gibt zu, dass ihm das Stück zugesteckt wurde, damit er es überreicht, und vermutet, dass es direkt von Solm Hargrin stammt. Anstatt quer über den Hof nach potenziellen Spähern und Schurken zu rufen, nutzt Solm eine verschlüsselte Rune, um die Diskretion eines Neulings zu prüfen und ihn ins Innere zu rufen."},{t="Unter den Dachsparren von Ambossar",b="Im Inneren von Ambossar heißt Solm Hargrin neu eingetroffene Agenten im Handwerk willkommen. Er bietet an, die Manöver, Schläge und subtilen Künste zu lehren, die einen Agenten am Leben halten und seine Taschen mit Münzen füllen. Neben dem Schärfen ihrer Dolche erinnert Solm zwergische Schurken daran, auf ihre vertriebenen gnomischen Verbündeten zu achten, die sich noch immer von dem katastrophalen Fall von Gnomeregan erholen."}},faq={{q="Wer schickt die Verschlüsselte Rune?",a="Die Rune stammt von Solm Hargrin, dem Schurkenlehrer, der in der großen Halle von Ambossar stationiert ist. Er lässt sie durch Sten Starkarm diskret an vielversprechende Rekruten draußen im Schnee weitergeben.",al={"wer schrieb die rune","verschlüsselte rune absender","wer gab sten die rune"}},{q="Wo finde ich Solm Hargrin?",a="Solm Hargrin befindet sich in der Haupthalle von Ambossar, der steinernen Bastion im Zentrum des Coldridgetals in Dun Morogh.",al={"wo ist solm","solm hargrin aufenthaltsort","solm finden"}},{q="Was ist der Zweck dieser Rune?",a="Sie dient als einleitende Vorladung für angehende Schurken und spornt sie dazu an, die Botschaft zu entschlüsseln, sich bei ihrem Klassenlehrer zu melden und mit dem Erlernen fortgeschrittener Kampftechniken und Überlebensmanöver zu beginnen.",al={"was bewirkt die rune","zweck der verschlüsselten rune","warum verschlüsselte rune"}},{q="Warum erwähnt Solm die Gnome?",a="Da Gnomeregan vor Kurzem einer Katastrophe zum Opfer gefallen ist, teilen sich gnomische Flüchtlinge das Coldridgetal und Ambossar mit den Zwergen. Solm erinnert seine Schüler daran, dass die Gnome eine schwere Zeit hinter sich haben und Unterstützung brauchen, um sich in ihrem vorübergehenden Zuhause einzuleben.",al={"warum gnomen helfen","solm gnomeregan kommentar"}},{q="Wer gibt dem Spieler die Rune?",a="Sten Starkarm übergibt den Stein an Schurken-Abenteurer im Coldridgetal, nachdem sie ihm zuvor bei den lokalen Aufgaben im Tal unter die Arme gegriffen haben.",al={"wer startet verschlüsselte rune","questgeber verschlüsselte rune"}},{q="Können andere Klassen diese Rune erhalten?",a="Nein. Die Verschlüsselte Rune ist ausschließlich für Schurken-Novizen gedacht, die ihre Reise im Coldridgetal beginnen.",al={"ist diese quest nur für schurken","können krieger die verschlüsselte rune erhalten"}}},fp="14,248,17.392.0,24.381.0,29.185.0,29.124.0,33.196.0,33.232.0,33.146.0,36.106.0"}
P.entries["quest:311"] = {n="Rückkehr zu Marleth",s="Return to Marleth markiert den schelmischen Abschluss einer hitzigen Braufehde in Dun Morogh. Nachdem ein Abenteurer den Keller von Kharanos infiltriert und ein Fass von Marleths feurigem 'Scalder' untergeschoben hat, kehrt er mit einem preisgekrönten Fass mit Donnerbier nach Bräuhall zurück – als unbestreitbarer Beweis.",h="Return to Marleth markiert den schelmischen Abschluss einer hitzigen Braufehde in Dun Morogh.",kw={"bräuhall","dun morogh","kharanos","marleth gerstenbräu","scalder","donnerbier","thunderbrew"},ang={["class:Rogue"]="Das Eindringen in einen bewachten Keller, um dort illegale Fässer auszutauschen, bietet einen amüsanten Test für Heimlichkeit und Fingerfertigkeit in den verschneiten Hügeln.",["race:Dwarf"]="Die Zwergenkultur betrachtet das Brauen als Kunstform und Ehrenwettstreit, was die kleinliche Kellerspionage zu einer Angelegenheit von großem lokalen Stolz macht."},sec={{t="Die Beute der Sabotage",b="Zwergische Rivalitäten werden selten mit Diplomatie beigelegt, wenn es um Bier geht. Marleth Gerstenbräu aus Bräuhall hegt einen erbitterten, wettbewerbsorientierten Groll gegen die Destillateure von Kharanos, den Schöpfern des berühmten Donnerbiers. Nachdem ihr starker 'Scalder' unbemerkt in den Keller von Thunderbrew geschmuggelt wurde, verlangt Marleth einen Beweis für die Heldentat. Ein echtes Fass mit Donnerbier direkt unter deren Nasen zu entwenden, dient sowohl als Trophäe als auch als Druckmittel."},{t="Ein bitteres Gebräu beigelegt",b="Das schwere Fass zurück über die schneebedeckten Bergrücken nach Bräuhall zu schleppen, vollendet den Streich. Marleth ist begeistert, den Erfolg des Plans zu sehen, und schwelgt voller Freude darin, die Wachen und Kellermeister von Kharanos überlistet zu haben. Obwohl der Vorfall oberflächlich betrachtet harmlos ist, unterstreicht er den leidenschaftlichen, kompromisslosen Stolz, den verschiedene Zwergenfamilien in ganz Dun Morogh in ihre eigenen Rezepturen stecken."}},faq={{q="Was ist das Ziel dieser Quest?",a="Ihr müsst das gestohlene Fass mit Donnerbier zu Marleth Gerstenbräu nach Bräuhall zurückbringen, um zu beweisen, dass Ihr erfolgreich ihren Scalder im Keller von Kharanos platziert habt.",al={"was muss ich tun","ziel von return to marleth","fass abgeben"}},{q="Wer ist Marleth Gerstenbräu?",a="Marleth ist eine zwergische Brauerin, die in Bräuhall lebt. Sie ist sehr stolz auf die stämmigen Rezepte ihrer Familie und pflegt eine kleinliche Rivalität mit den Thunderbrew-Destillateuren in Kharanos.",al={"wer ist marleth","marleth hintergrundgeschichte","gerstenbräu"}},{q="Woher stammt das Fass?",a="Das Fass wird direkt aus dem Kellerlager der Brauerei Donnerbräu in Kharanos geholt, nachdem Marleths Scalder in deren Vorräte geschmuggelt wurde.",al={"woher kam das fass","kharanos keller","fundort donnerbier"}},{q="Wo liegt Bräuhall?",a="Bräuhall liegt an den gefrorenen Ufern des Eiswellensees im westlichen Dun Morogh, nordwestlich von Kharanos.",al={"standort bräuhall","wo ist bräuhall","wie finde ich marleth"}},{q="Warum hat Marleth eine Fehde mit Kharanos?",a="Zwergenbraumeister sind leidenschaftliche Konkurrenten, wenn es um ihre Rezepte geht. Marleth wollte beweisen, dass ihre eigene Mischung, der Scalder, das berühmte Donnerbier, das von den Thunderbrews hergestellt wird, übertreffen oder demütigen kann.",al={"warum rivalen","marleth gegen thunderbrew","braufehde"}},{q="Was macht Marleth mit dem Fass?",a="Das Fass dient hauptsächlich als Beweis dafür, dass der Tausch direkt unter den Nasen der Wachen von Kharanos vollzogen wurde, obwohl Marleth zweifellos erfreut ist, den Vorrat ihrer Rivalen zu behalten.",al={"warum donnerbier stehlen","was passiert mit dem bier"}}},fp="17,278,22.453.0,21.378.0,34.166.0,26.182.0,33.153.0,26.110.0,36.198.0,37.174.0"}
P.entries["quest:3110"] = {n="Geheiligte Rune",s="Geheiligte Rune ist eine Einführungsquest für angehende Zwergenpriester im Coldridgetal. Sten Starkarm übergibt eine beschriftete Rune von Priesterlehrer Branstock Khalder, die den Neuling nach Ambossar ruft, um seine Verbindung mit dem Heiligen Licht zu vertiefen.",h="Geheiligte Rune ist eine Einführungsquest für angehende Zwergenpriester im Coldridgetal.",kw={"ambossar","branstock khalder","das coldridgetal","dun morogh","zwergpriester","geheiligte rune","sten starkarm"},ang={["class:Priest"]="Dieses Pergament markiert Eure offizielle Anerkennung als Diener des Heiligen Lichts in Dun Morogh und weist Euch für Eure allererste Zauberkunst zu Branstock Khalder.",["race:Dwarf"]="Zwergenpriester verbinden tiefe Hingabe an das Licht mit typischer Gebirgszähe und erweisen sich als unverzichtbar, um das Coldridgetal gegen eindringende Troggs zu halten."},sec={{t="Die Berufung zum Tuch",b="Während er Sten Starkarm dabei hilft, die unmittelbaren Bedrohungen vor Ambossar zu beseitigen, erregt ein frisch eingetroffener Priester die Aufmerksamkeit des geistlichen Führers der Siedlung. Branstock Khalder vertraut Sten eine geheiligte Rune an, die mit Gebeten und Anweisungen versehen ist und den jungen Abenteurer dazu anleitet, die wehrhaften Hallen von Ambossar zu betreten, um seine heiligen Studien offiziell zu beginnen."},{t="Verteidiger von Coldridge",b="Obwohl die Kultur der Zwerge oft kriegerische Tapferkeit und schwere Rüstung betont, bleibt das Heilige Licht ein Eckpfeiler der Gesellschaft von Eisenschmiede. Im Coldridgetal spielen heilige Zauberwirker neben Kriegern und Jägern eine lebenswichtige Rolle beim Schutz der Enklave vor aggressiven Trogg-Übergriffen und gefährlicher Tierwelt, die durch die Schneewehen schleicht."}},faq={{q="Was ist die Geheiligte Rune?",a="Es handelt sich um eine beschriftete klerikale Rune, die von Sten Starkarm im Namen von Branstock Khalder überreicht wird. Das Lesen dient als Einführung in grundlegende Gebete und ermutigt junge Priester, eine formelle Ausbildung aufzusuchen.",al={"was ist die geheiligte rune","zweck der rune"}},{q="Wer ist Branstock Khalder?",a="Branstock Khalder ist der Zwergen-Priesterlehrer, der in Ambossar stationiert ist. Bekannt für seinen trockenen Humor und seinen unerschütterlichen Glauben, betreut er angehende Akolythen und lehrt sie grundlegende Heiligtumszauber, um die Verteidigung des Coldridgetals zu unterstützen.",al={"branstock","priesterlehrer coldridgetal"}},{q="Wo finde ich Branstock Khalder?",a="Er befindet sich in der steinernen Haupthalle von Ambossar, gelegen auf der zentralen Lichtung des Coldridgetals in Dun Morogh.",al={"standort von branstock","wo ist branstock"}},{q="Warum brauchen Zwerge Priester im Coldridgetal?",a="Troggs haben Teile des Tals überrannt, und die örtlichen Wachen verlassen sich auf die heilenden Kräfte und das heilige Züchtigen der Lichtwirker, um ihre Linien zu halten und die Verwundeten zu heilen.",al={"warum zwergenpriester","priester in ambossar"}},{q="Kann jede Klasse diese Quest annehmen?",a="Nein. Die Geheiligte Rune wird ausschließlich jungen Zwergenpriestern übergeben, die ihre Reise im Coldridgetal beginnen.",al={"wer bekommt die geheiligte rune","ist diese quest nur für priester"}},{q="Wer überbringt dem Spieler die Rune?",a="Sten Starkarm, ein Gebirgsjäger von Ambossar, der die Prüfungen direkt vor der Hütte überwacht, händigt die Rune aus, nachdem Ihr ihm bei der ersten Verteidigung des Tals geholfen habt.",al={"wer startet geheiligte rune","rolle von sten starkarm"}}},fp="13,258,22.364.0,22.331.0,26.202.0,25.229.0,34.123.0,48.168.0,30.116.0,36.148.0"}
P.entries["quest:3112"] = {n="Einfaches Memorandum",s="Das Einfache Memorandum ist ein Schreiben, das angehenden Gnomkriegern zu Beginn ihrer Reise im Coldridgetal überreicht wird. Es wird von Sten Starkarm draußen weitergegeben und weist die frisch ausgebildeten Kämpfer nach Ambossar, um Thran Khorman aufzusuchen, der versprochen hat, sie auf die Rückeroberung von Gnomeregan vorzubereiten.",h="Das Einfache Memorandum ist ein Schreiben, das angehenden Gnomkriegern zu Beginn ihrer Reise im Coldridgetal...",kw={"ambossar","das coldridgetal","dun morogh","gnomeregan","einfaches memorandum","sten starkarm","thran khorman","kriegerausbilder"},ang={["class:Warrior"]="Dieses Schreiben leitet die Kampfausbildung eines Gnomkriegers offiziell ein und begründet ein Band mit den erfahrenen Waffenmeistern von Eisenschmiede.",["race:Dwarf"]="Zwergische Lehrmeister wie Thran Khorman betrachten die Not der Gnome als gleichbedeutend mit ihren eigenen uralten Fehden und beweisen tiefe Solidarität mit ihren vertriebenen Verbündeten.",["race:Gnome"]="Das Memorandum unterstreicht das Exil der Gnome aus Gnomeregan und ihre stille Entschlossenheit, Soldaten auszubilden, die fähig sind, ihre verstrahlte Stadt zurückzugewinnen."},sec={{t="Eine Vorladung nach Ambossar",b="Während ein junger Gnomkrieger für den Gebirgsjäger Sten Starkarm die Troggs und Eber beseitigt, die das Coldridgetal heimsuchen, erhält er eine kurze Nachricht, die dem Zwerg zugesteckt wurde. Da der erfahrene Ausbilder Thran Khorman das Potenzial in dem geflüchteten Rekruten erkennt, nutzt er das Memorandum, um den Neuling in Ambossars zentrale Halle zu rufen und mit der eigentlichen militärischen Ausbildung zu beginnen."},{t="Ein Versprechen der Solidarität",b="Auch wenn zwergische Ausbilder Gnomkrieger gelegentlich wegen ihrer geringen Körpergröße necken mögen, nimmt Thran Khorman ihren Kampf sehr ernst. Er fühlt mit dem Verlust von Gnomeregan und vergleicht die Notlage der Gnome damit, wie es Zwergen ergehen würde, falls Eisenschmiede an die Dunkeleisenzwerge fiele. Um sein Wort zu halten, gelobt er, die verbannten Kämpfer in der Kriegskunst zu unterweisen, bis sie bereit sind, ihre Heimat zurückzuerobern."}},faq={{q="Was ist das Einfache Memorandum?",a="Es ist eine einleitende Notiz, die neuen Gnomkriegern von Sten Starkarm im Coldridgetal überreicht wird. Der Brief weist den Krieger an, Thran Khorman aufzusuchen, den Kriegerausbilder in der großen Halle von Ambossar.",al={"einfaches memorandum","was ist diese notiz","memorandum quest"}},{q="Wer sendet das Memorandum?",a="Es stammt von Thran Khorman, dem ansässigen zwergischen Kriegerausbilder, der in Ambossar stationiert ist. Er lässt es von Sten Starkarm an vielversprechende Kämpfer weitergeben, die den Gebirgsjägern zur Hand gehen.",al={"wer schrieb das memorandum","wer schickte das einfache memorandum"}},{q="Warum bildet Thran Khorman Gnomkrieger aus?",a="Thran gab sein Wort, den verbannten Gnomen beizustehen. Er respektiert ihre Entschlossenheit und fühlt tiefen Schmerz über ihre Tragödie, indem er den Fall von Gnomeregan damit vergleicht, wie es wäre, wenn Eisenschmiede vom Dunkeleisen-Clan erobert worden wäre.",al={"warum thran gnom trainiert","gnomkrieger geschichte"}},{q="Wo finde ich Thran Khorman?",a="Thran Khorman steht in der Haupthalle von Ambossar, der zentralen Siedlung im Coldridgetal in Dun Morogh.",al={"wo ist thran khorman","thran khorman aufenthaltsort"}},{q="Wer ist Sten Starkarm?",a="Sten Starkarm ist ein zwergischer Gebirgsjäger, der direkt vor Ambossar im Coldridgetal stationiert ist und die örtliche Verteidigung gegen aggressive Eber und eindringende Troggs koordiniert.",al={"sten starkarm","wer ist sten"}},{q="Warum beginnen Gnome im Coldridgetal?",a="Nach dem tragischen Fall und der Verstrahlung von Gnomeregan flohen die überlebenden Gnome als Flüchtlinge in das Zwergenterrain. Ambossar und Eisenschmiede öffneten ihre Tore, um ihnen Zuflucht zu gewähren, während sie ihre Streitkräfte neu aufbauen.",al={"warum gnome hier sind","gnom im coldridgetal"}}},fp="17,274,21.363.0,22.406.0,30.211.0,25.181.0,44.231.0,30.124.0,21.166.0,44.208.0"}
P.entries["quest:3113"] = {n="Verschlüsseltes Memorandum",s="Das Verschlüsselte Memorandum ist eine einführende Vorladung, die sich an angehende gnomische Schurken richtet, die im Coldridgetal eintreffen. Die getarnte Notiz wird über Sten Starkarm weitergegeben und weist neue Agenten diskret an, Solm Hargrin in Ambossar aufzusuchen.",h="Das Verschlüsselte Memorandum ist eine einführende Vorladung, die sich an angehende gnomische Schurken...",kw={"ambossar","das coldridgetal","dun morogh","verschlüsseltes memorandum","gnomeregan","schurkenlehrer","solm hargrin","sten starkarm"},ang={["class:Rogue"]="Diese Aufgabe dient als erster Appell für gnomische Schurken und führt sie an Solm Hargrin sowie die Philosophie des gegenseitigen Schutzes heran, die erforderlich ist, um ihr verdecktes Handwerk in den Ländern der Zwerge auszuüben.",["race:Dwarf"]="Zwergische Bergsteiger wie Sten Starkarm erleichtern diese Kommunikation und zeigen die praktische Zusammenarbeit zwischen Eisenschmiede und den vertriebenen Gnomen im Coldridgetal.",["race:Gnome"]="Das Memorandum beleuchtet die Not der Gnom-Flüchtlinge nach der Katastrophe in Gnomeregan und zeigt, wie Überlebende zusammenhalten, während sie als Gäste unter den Zwergen leben."},sec={{t="Eine diskrete Einführung",b="Während neu eingetroffene Gnome den Bergsteigern im Coldridgetal bei lokalen Bedrohungen durch Troggs helfen, überreicht Sten Starkarm ein gefaltetes Stück Pergament, das ihm im Vertrauen zugesteckt wurde. Die Notiz, die oberflächlich wie ein offizielles Memorandum wirkt, ist eine Einladung, Solm Hargrin zu treffen, den ansässigen Schurkenlehrer, der in Ambossar stationiert ist."},{t="Gemeinsame Entbehrungen im Schnee",b="Die Nachricht spiegelt die schwierige Realität wider, mit der die Gnome nach dem plötzlichen Fall von Gnomeregan konfrontiert sind. Vertriebene Überlebende der Gnome müssen sich in Dun Morogh auf engem Raum mit ihren zwergischen Gastgebern arrangieren. Solm Hargrin weiß, dass Schurken Argwohn erregen, wenn Gegenstände verschwinden, und er setzt sich für eine unausgesprochene Solidarität unter den Ausübenden dieses Handwerks ein, um ihr gegenseitiges Überleben zu sichern."}},faq={{q="Wer schrieb das Verschlüsselte Memorandum?",a="Solm Hargrin, der Schurkenlehrer in Ambossar, verfasste die Notiz. Er tarnte sie als offizielle Anweisung von Vorgesetzten, damit Sten Starkarm sie ohne Argwohn weitergeben würde.",al={"wer schickte das memorandum","wer schrieb die notiz","solm notiz"}},{q="Warum ist das Memorandum getarnt?",a="Schurken bevorzugen Diskretion, besonders in einer belebten Zwergenfestung wie Ambossar. Solm Hargrin hält sich bedeckt, um Gerüchte oder Anschuldigungen zu vermeiden, wenn Ausrüstung verschwindet, und nutzt verschlüsselte Grüße, um gezielt andere Gauner zu erreichen.",al={"warum getarnt","warum verschlüsselt"}},{q="Was verrät diese Notiz über die Situation in Dun Morogh?",a="Der Dialog beleuchtet die Spannungen und die Solidarität zwischen Gnomen und Zwergen nach dem Verlust von Gnomeregan. Obwohl die Unterbringung beider Bevölkerungsgruppen in Eisenschmiede und Dun Morogh die Ressourcen belastet, betont Solm, dass diejenigen, die im Schatten ihr Handwerk ausüben, aufeinander achtgeben müssen.",al={"gnomisch-zwergische beziehungen","gnomeregan flüchtlinge dun morogh"}},{q="Wer überreicht dem Spieler das Memorandum?",a="Sten Starkarm händigt das Dokument aus, nachdem Ihr ihm im Coldridgetal geholfen habt, in der Annahme, es stamme von Solm Hargrin für Eure Ausbildung.",al={"sten starkarm übergabe","wer händigt die notiz aus"}},{q="Welche Rolle nimmt Solm Hargrin ein?",a="Solm Hargrin ist der Schurkenlehrer in der Berghalle von Ambossar, der für die Ausbildung neuer Schurken in Kampftechniken und schattenhaften Talenten verantwortlich ist.",al={"solm hargrin rolle","was macht solm"}},{q="Bezieht sich diese Aufgabe auf den Fall von Gnomeregan?",a="Ja. Solm bezieht sich direkt darauf, dass Gnomeregan überrannt wurde, und betont, dass sich vertriebene gnomische Schurken trotz des Verlusts ihrer mechanischen Heimat auf ihre gemeinsame Bruderschaft verlassen können, um zu bestehen.",al={"gnomeregan fall lore","gnom flüchtlingsstatus"}}},fp="20,238,23.321.0,28.393.0,35.194.0,32.242.0,61.274.0,42.133.0,34.160.0,44.188.0"}
P.entries["quest:3114"] = {n="Glyphenmemorandum",s="Das Glyphenmemorandum ist eine Einführungsaufgabe, die angehende Magier im Coldridgetal zu ihrem Klassenlehrer in Ambossar leitet. Das Schreiben wurde dem Gebirgsjäger Sten Starkarm anvertraut und fordert aufstrebende Arkananwender auf, den exzentrischen Gnomen Marryk Nurribit aufzusuchen, um ihre formelle Ausbildung im Zauberwirken zu beginnen.",h="Das Glyphenmemorandum ist eine Einführungsaufgabe, die angehende Magier im Coldridgetal zu ihrem...",kw={"ambossar","das coldridgetal","dun morogh","glyphenmemorandum","magierlehrer","marryk nurribit","sten starkarm"},ang={["class:Mage"]="Dieses Schreiben markiert Eure offizielle Einführung in die arkane Unterweisung in Dun Morogh und bringt Euch direkt mit Eurem Startlehrer in Kontakt.",["faction:Alliance"]="Die reibungslose Zusammenarbeit zwischen Sten Starkarm und Marryk Nurribit verdeutlicht die enge Partnerschaft zwischen Zwergen und Gnomen, die sich das Coldridgetal teilen.",["race:Gnome"]="Marryk Nurribit ist einer von mehreren Gnomen-Spezialisten, die nach dem Fall von Gnomeregan in den Zwergenlanden Zuflucht suchten, um ihr traditionelles Handwerk zu lehren."},sec={{t="Ein Schreiben für angehende Magier",b="Während sie dem Gebirgsjäger Sten Starkarm bei seinen ersten Pflichten im Coldridgetal helfen, werden neu eingetroffene Magier von einer örtlichen Arkanautorität vorgeladen. Sten erhält ein schriftliches Memorandum, das an den unerfahrenen Zauberwirker adressiert ist, und leitet es weiter, verbunden mit dem Rat, sich einen Moment Zeit zum Lesen zu nehmen und in das warme Innere von Ambossar zu gehen, um dessen Verfasser zu treffen."},{t="Ausbildung bei Marryk Nurribit",b="Der Verfasser des Memorandums ist Marryk Nurribit, ein in Ambossar stationierter Magierlehrer der Gnom. Statt seinen Schüler mit trockenen theoretischen Vorträgen zu überfordern, erteilt Marryk geradlinige, bodenständige Ratschläge: keinen ernsten Ärger machen, Münzen für die Ausbildung und Wirtshausgetränke sparen und die radioaktive Katastrophe des gefallenen Gnomeregan strikt meiden. Nachdem die grundlegenden Erwartungen geklärt sind, steht Marryk bereit, Neulinge in den arkanen Künsten zu unterweisen."}},faq={{q="Wer überbringt dieses Memorandum?",a="Sten Starkarm, ein im Coldridgetal stationierter Gebirgsjäger der Allianz, überreicht Euch das Memorandum, nachdem Ihr ihm bei seinen ersten Aufgaben geholfen habt.",al={"wer vergibt glyphen-memorandum","sten starkarm quest"}},{q="Wer ist Marryk Nurribit?",a="Marryk Nurribit ist ein Magierlehrer der Gnom, der sich in Ambossar im Coldridgetal aufhält. Er unterweist angehende Magier in ersten Zaubern und allgemeinen arkanen Sicherheitsmaßnahmen.",al={"wer ist marryk","ambossar magierlehrer"}},{q="Wo finde ich Marryk Nurribit?",a="Marryk befindet sich in der Haupthalle von Ambossar, dem zentralen Außenposten der Zwerge im oberen Bereich des Coldridgetals in Dun Morogh.",al={"marryk nurribit aufenthaltsort","wo ist der magierlehrer im coldridgetal"}},{q="Warum warnt Marryk vor einem Besuch in Gnomeregan?",a="Gnomeregan wurde vor Kurzem von Troggs überrannt und durch eine verheerende Freisetzung von radioaktivem Gas verseucht, was es für jeden unerfahrenen Abenteurer in Dun Morogh lebensgefährlich macht.",al={"marryk gnomeregan warnung","warum gnomeregan meiden"}},{q="Welche Klassen erhalten diese Aufgabe?",a="Diese Quest wird ausschließlich angehenden Magiern angeboten, die ihre Reise im Coldridgetal beginnen, um sie mit ihrem Klassenlehrer bekannt zu machen.",al={"wer bekommt glyphen-memorandum","ist diese quest nur für magier"}},{q="Was erwartet Marryk von seinen Schülern?",a="Marryk hält seine Anforderungen schlicht: Er mahnt seine Schüler, keinen Ärger zu machen, genug Silber zu sparen, um für ihre Zauber zu bezahlen und ihm ein Bier auszugeben, und sich von Gnomeregan fernzuhalten.",al={"marryk erwartungen","was verlangt der lehrer"}}},fp="18,304,26.362.0,29.436.0,29.139.0,23.157.0,33.134.0,49.171.0,31.138.0,42.176.0"}
P.entries["quest:3115"] = {n="Besudeltes Memorandum",s="Besudeltes Memorandum ist eine Einführungsquest für angehende Gnomhexenmeister, die ihre ersten Schritte im Coldridgetal wagen. Leise überbracht durch Sten Starkarm ruft das Schreiben den Neophyten in die Schatten von Ambossar, um Alamar Grimm zu treffen, der Selbstständigkeit durch dunkle Macht predigt, anstatt auf ihre zwergischen Gastgeber zu vertrauen.",h="Besudeltes Memorandum ist eine Einführungsquest für angehende Gnomhexenmeister, die ihre ersten Schritte im...",kw={"alamar grimm","ambossar","das coldridgetal","dun morogh","gnom hexenmeister","gnomeregan exil","sten starkarm","besudeltes memorandum"},ang={["class:Warlock"]="Dieses Schreiben markiert Euren formellen Eintritt in das Handwerk der Hexenmeister und stellt dämonische Pakte nicht als Wahnsinn dar, sondern als aus dem Überleben geborenen Pragmatismus.",["race:Dwarf"]="Zwergische Gastgeber dulden diese finsteren Ausübenden unter ihrem Dach mit offenkundigem Abscheu und scharfsinniger Wachsamkeit.",["race:Gnome"]="Das Memorandum spiegelt den tief sitzenden Groll wider, den einige verbannte Gnome über ihren Status als Vertriebene und ihre Abhängigkeit von Eisenschmiede empfinden."},sec={{t="Eine diskrete Aufforderung",b="Selbst im eisigen Außenposten des Coldridgetals begegnet man der Ausübung der dunklen Künste mit tiefem Misstrauen. Während sie Sten Starkarm im Kampf gegen lokale Bedrohungen helfen, wird jungen Gnomhexenmeistern eine Notiz zugesteckt. Sten überbringt sie nur widerwillig und bringt den brüchigen Waffenstillstand zur Sprache, der Hexenmeister in den Gebieten der Allianz duldet: „Passt auf Euch auf... Euresgleichen genießt hier nicht gerade das größte Vertrauen.“"},{t="Gnomische Bitterkeit im Exil",b="Als er der Nachricht folgt, trifft der Hexenmeister auf Alamar Grimm, der in den Hallen von Ambossar lauert. Grimm nimmt bezüglich der Notlage der Gnome kein Blatt vor den Mund. In seinen Augen haben gewöhnliche Tüftelei und gewöhnliche Magie Gnomeregan vollkommen im Stich gelassen, ihr Volk an den Rand der Auslöschung getrieben und sie als Flüchtlinge zweiter Klasse zurückgelassen, die vom Wohlwollen der Zwerge abhängig sind. Anstatt zum Heiligen Licht zu beten oder Vertrauen in zwergische Politik zu setzen, drängt Grimm seinen Schüler dazu, Unholde zu beschwören und zu meistern, die bedingungslosen Gehorsam bieten."}},faq={{q="Was ist das Besudelte Memorandum?",a="Es ist eine schriftliche Nachricht, die frischgebackenen Gnomhexenmeistern von Sten Starkarm im Coldridgetal überreicht wird. Sie weist sie an, Alamar Grimm aufzusuchen, den örtlichen Hexenmeisterlehrer in Ambossar.",al={"besudeltes memorandum","hexenmeisternotiz dun morogh","was ist das memorandum"}},{q="Warum wird Hexenmeistern im Coldridgetal misstraut?",a="Zwerge und ihre Verbündeten der Allianz schätzen traditionelle Tugenden wie kriegerische Ehre und das Heilige Licht sehr und betrachten Dämonologie und Schattenmagie von Natur aus als verderbt und gefährlich. Gnomhexenmeister stehen unter einem Schleier tiefen gesellschaftlichen Misstrauens.",al={"warum mögen zwerge keine hexenmeister","hexenmeistervorurteile ambossar"}},{q="Wer ist Alamar Grimm?",a="Alamar Grimm ist ein Gnomhexenmeisterlehrer, der in Ambossar residiert. Verbittert über den Fall von Gnomeregan und die Demütigung, auf zwergische Wohltätigkeit angewiesen zu sein, unterweist er junge Gnome in der Bindung dämonischer Diener, um ihre eigene Macht zu sichern.",al={"alamar grimm lore","wer ist alamar"}},{q="Warum kritisiert Grimm normale Magie und Technologie?",a="Grimm glaubt, dass konventionelle Ingenieurskunst und akzeptierte Magieschulen die Gnome während der Katastrophe von Gnomeregan im Stich gelassen haben, wodurch sie von zwergischen Gönnern abhängig wurden, die Verbindungen zu Menschen über die Rückeroberung der Gnomheimat stellen.",al={"grimms sicht auf gnomeregan","warum dunkle magie statt ingenieurskunst"}},{q="Können Zwerghexenmeister diese Quest erhalten?",a="Nein. In Dun Morogh können nur Gnome den Pfad des Hexenmeisters beschreiten, weshalb diese Aufforderung ausschließlich neu eingetroffenen Gnomen vorbehalten ist.",al={"zwerg hexenmeister besudeltes memorandum","können zwerge hexenmeister sein"}},{q="Wo findet diese Quest statt?",a="Die Quest beginnt bei Sten Starkarm im Coldridgetal und endet in Ambossar, der zentralen Feste mit Blick auf das Tal im südwestlichen Dun Morogh.",al={"wo ist alamar grimm","besudeltes memorandum abgabe"}}},fp="18,326,18.373.0,27.513.0,31.174.0,48.248.0,20.232.0,53.235.0,38.131.0,33.156.0"}
P.entries["quest:3116"] = {n="Einfaches Siegelzeichen",s="Das Einfache Siegelzeichen ist eine einführende Aufforderung an angehende Krieger der Nachtelfen im Laubschattental. Überbracht von Konservator Ilthalaine im Namen der Ausbilderin Alyissia, markiert es formell den Übergang des Rekruten zur Kampfausbildung, um das noch junge Geäst von Teldrassil zu beschützen.",h="Das Einfache Siegelzeichen ist eine einführende Aufforderung an angehende Krieger der Nachtelfen im...",kw={"aldrassil","alyissia","feralas","ilthalaine","laubschattental","einfaches siegelzeichen","teldrassil","krieger"},ang={["class:Warrior"]="Diese Quest markiert Euren offiziellen Beginn als Krieger der Kaldorei und führt Euch an Alyissia als Eure erste Lehrmeisterin der Waffen heran.",["faction:Alliance"]="Alyissias Rat spiegelt die frühen Bemühungen der Nachtelfen wider, andere Völker der Allianz trotz jahrhundertelanger Isolation auf ihren Ästen willkommen zu heißen.",["race:NightElf"]="Das Siegelzeichen verdeutlicht die raschen Veränderungen um die Kaldorei – von der Pflanzung Teldrassils bis hin zur Öffnung ihrer abgeschiedenen Heimat für fremde Verbündete."},sec={{t="Ein Ruf zu den Waffen im Laubschattental",b="Nachdem sie ihre grundlegenden Überlebensfähigkeiten gegen die unruhige Tierwelt des Laubschattentals unter Beweis gestellt haben, erhalten junge Krieger der Nachtelfen ein beschriftetes Siegelzeichen, das ihnen von Konservator Ilthalaine überreicht wird. Das Zeichen ist eine formelle Bitte von Alyissia, der örtlichen Kriegerausbilderin bei Aldrassil, die den Neuling auffordert, vorzutreten und seine kriegerische Kraft der Verteidigung seines Volkes zu widmen."},{t="Eine turbulente neue Ära",b="Meldet man sich bei Alyissia, stellt sie das Training des Kriegers vor den Hintergrund rascher und beunruhigender Veränderungen. In nur wenigen kurzen Jahren haben die Nachtelfen den Weltenbaum Teldrassil emporwachsen lassen, das Ausbreiten eines heimtückischen Verderbens unter den Waldtieren nah und fern miterlebt und den Kontakt zu uralten Ahngebieten wie Feralas wiederhergestellt, die einst als verloren galten. Angesichts dieser Gefahren werden fähige Verteidiger dringend benötigt."},{t="Öffnung des Geästs",b="Über die kriegerische Disziplin hinaus bereitet Alyissia junge Kaldorei auf die Welt außerhalb ihrer geschützten Lichtung vor. Sie rät den Rekruten, Vorurteile gegenüber Außenstehenden anderer Völker abzulegen, die auf Teldrassil eintreffen. Zwar mahnt sie zur Vorsicht, da nicht jeder Reisende aus reiner Selbstlosigkeit handle, betont jedoch, dass Verbündete für die Verteidigung der Kaldorei unerlässlich sind, und fordert ihre Schüler auf, ihnen ein angemessenes Maß an Vertrauen entgegenzubringen, wenn sie ihre Rolle als Beschützer übernehmen."}},faq={{q="Was ist das Einfache Siegelzeichen?",a="Es ist ein beschriftetes Zeichen von Alyissia, der Kriegerausbilderin im Laubschattental, das Kriegerneulingen der Nachtelfen überbracht wird, um sie zur formellen Kampfausbildung zu rufen.",al={"einfaches siegelzeichen gegenstand","was ist dieses siegelzeichen","siegelzeichen des kriegers"}},{q="Wer schickt Euch zu Alyissia?",a="Konservator Ilthalaine überreicht das Siegelzeichen und schickt Euch zu Alyissia, nachdem Ihr Eure ersten Aufgaben zur Wahrung des Gleichgewichts im Laubschattental abgeschlossen habt.",al={"wer gibt das einfache siegelzeichen","questgeber einfaches siegelzeichen"}},{q="Wo ist Alyissia zu finden?",a="Alyissia befindet sich in der sicheren Zuflucht des Laubschattentals nahe dem gewaltigen Stamm von Aldrassil, wo sie angehende Krieger der Nachtelfen ausbildet.",al={"alyissia aufenthaltsort","wo ist alyissia","kriegerausbilder laubschattental"}},{q="Warum werden laut Alyissia gerade jetzt Krieger gebraucht?",a="Die letzten Jahre brachten einschneidende Herausforderungen: die Erschaffung von Teldrassil, ein um sich greifendes Verderben unter den einheimischen Wildtieren und die Wiederentdeckung längst verlorener Länder wie Feralas. Geübte Kämpfer werden gebraucht, um die Kaldorei vor diesen herannahenden Bedrohungen zu schützen.",al={"warum nachtelfen krieger brauchen","laubschattental krieger lore"}},{q="Was sagt Alyissia über andere Völker, die Teldrassil besuchen?",a="Sie mahnt davor, Vorurteile zu hegen, und erklärt, dass Fremde anderer Völker bald die Äste von Teldrassil betreten werden. Obwohl sie einräumt, dass nicht alle Ankömmlinge rein uneigennützig sind, rät sie dazu, ihnen ein gewisses Vertrauen entgegenzubringen, damit sie bei der Verteidigung des Baumes helfen können.",al={"alyissia über andere völker","nachtelfen und außenstehende","allianz in teldrassil"}},{q="Welche Bedeutung hat die Erwähnung von Feralas?",a="Feralas steht für uralte Gebiete der Nachtelfen, die nach der Großen Zerschlagung lange Zeit abgeschnitten oder für verloren gehalten wurden. Seine Wiederentdeckung verdeutlicht, wie rasch die Kaldorei nach Jahrtausenden der Isolation wieder Verbindung mit der weiten Welt aufnehmen.",al={"warum feralas erwähnen","verbindung zu feralas"}}},fp="12,280,28.370.0,20.422.0,18.430.0,25.162.0,31.146.0,28.145.0,52.261.0,61.259.0,47.233.0"}
P.entries["quest:3117"] = {n="Geätztes Siegelzeichen",s="Das Geätzte Siegelzeichen ist eine schriftliche Vorladung, die jungen Nachtelfenjägern in Laubschattental durch Konservator Ilthalaine überbracht wird. Sie ruft sie hinauf in die gewaltigen Äste von Aldrassil, um ihre Ausbilderin Ayanna Immerlauf zu treffen und offiziell ihren Pfad der Schießkunst und Tierkunde zu beginnen.",h="Das Geätzte Siegelzeichen ist eine schriftliche Vorladung, die jungen Nachtelfenjägern in Laubschattental...",kw={"aldrassil","ayanna immerlauf","geätztes siegelzeichen","jäger","ilthalaine","laubschattental","teldrassil"},ang={["class:Hunter"]="Diese Quest markiert Eure offizielle Einführung in die Jägerlehre auf Teldrassil und öffnet die Tür zum Erlernen von Bogenkunst, Fährtenlesen und Tierbeherrschung.",["race:NightElf"]="Für die Kaldorei ist die Jagd eine heilige Disziplin, die eng mit natürlicher Harmonie und der Ehrfurcht vor Elune verbunden ist, anstatt bloßer Sport zu sein."},sec={{t="Eine Vorladung in die Äste",b="Nachdem sie ihre frühe Wachsamkeit bei der Verteidigung von Laubschattental bewiesen haben, wird jungen Kaldoreijägern von Konservator Ilthalaine ein beschriftetes Zeichen überreicht. Ursprünglich von einem Boten der Jägermentorin Ayanna Immerlauf überbracht, weist das geätzte Siegelzeichen den Neuling an, hoch in die oberen Bereiche von Aldrassil zu klettern, wo die Ausbilder über das Blätterdach wachen."},{t="Der Pfad des Jägers",b="Das Treffen mit Ayanna markiert den formellen Beginn der Ausbildung eines Jägers auf Teldrassil. Sie unterweist Neulinge in den doppelten Künsten der Treffsicherheit und dem Verständnis für die wilden Kreaturen Kalimdors. Ayanna betont, dass ein wahrer Jäger seine tierischen Gefährten mit Respekt behandeln und in einer Welt voller unsichtbarer Gefahren stets achtsam und demütig bleiben muss."}},faq={{q="Was ist das Geätzte Siegelzeichen?",a="Es ist eine beschriftete Nachricht der Jägerausbilderin Ayanna Immerlauf, um vielversprechende Nachtelfenneulinge zu ihrem Posten auf Aldrassil zu leiten.",al={"geätztes siegelzeichen","was ist dieses siegelzeichen","siegelzeichen gegenstand"}},{q="Wo befindet sich Ayanna Immerlauf?",a="Sie ist auf den oberen Terrassen von Aldrassil zu finden, der gewaltigen Weltenbaumhöhle im Zentrum von Laubschattental.",al={"wo ist ayanna","ayanna immerlauf finden","ayanna immerlauf aufenthaltsort"}},{q="Wer übergibt das Geätzte Siegelzeichen?",a="Konservator Ilthalaine händigt es Nachtelfenjägern aus, sobald sie beginnen, sich durch die Verteidigung des örtlichen Waldes zu beweisen.",al={"wer gibt die quest","questgeber","woher bekomme ich geätztes siegelzeichen"}},{q="Was lehrt Ayanna Immerlauf?",a="Sie unterrichtet Jäger in den Traditionen der Treffsicherheit, dem Umgang mit Tieren und dem Überleben in der Wildnis, während sie sie davor warnt, die Gefahren in der Ferne jemals zu unterschätzen.",al={"jägerausbildung","was lehrt ayanna","warum mit ayanna sprechen"}},{q="Warum mahnt Ayanna Jäger zur Vorsicht im Umgang mit ihren Begleitern?",a="Sie erinnert ihre Schüler daran, dass die Wildnis weitaus größere Gefahren birgt, als Neulingsjägern bewusst ist, was bedeutet, dass ein Jäger seine Tiergefährten respektieren muss, anstatt leichtfertig mit ihren Fähigkeiten umzugehen.",al={"tiergefahr","warum tiere respektieren","begleitervorsicht"}},{q="Ist diese Quest für andere Klassen verfügbar?",a="Nein, das Geätzte Siegelzeichen ist eine spezifische einleitende Klassenvorladung, die ausschließlich für Nachtelfenjäger gedacht ist.",al={"können druiden das tun","nur für jäger","andere klassen"}}},fp="12,266,23.350.0,22.334.0,25.137.0,35.109.0,31.120.0,34.157.0,49.207.0,41.102.0"}
P.entries["quest:3118"] = {n="Verschlüsseltes Siegelzeichen",s="Das Verschlüsselte Siegelzeichen ist eine einleitende Vorladung für angehende Nachtelfenschurken, die in Laubschattental eintreffen. Es wird von Konservator Ilthalaine im Namen von Frahun Schattenflüsterer überbracht und weist verdeckte Agenten an, ihre Ausbildung zu beginnen und auf den fragilen Frieden zu achten, der Kalimdor bedroht.",h="Das Verschlüsselte Siegelzeichen ist eine einleitende Vorladung für angehende Nachtelfenschurken, die in...",kw={"aldrassil","konservator ilthalaine","verschlüsseltes siegelzeichen","frahun schattenflüsterer","schurkenlehrer","laubschattental","teldrassil"},ang={["class:Rogue"]="Diese Aufgabe markiert Euren Eintritt in das Netzwerk der Kaldorei aus Spähern, Meuchelmördern und Kundschaftern, die damit beauftragt sind, Teldrassil vor ungesehenen Widersachern zu schützen.",["faction:Alliance"]="Die Ausbilder von Laubschattental erinnern Rekruten daran, dass fraktionsübergreifende Verträge fragil sind und dass Aufklärungsarbeit von entscheidender Bedeutung ist, um Übergriffe der Horde zu verhindern.",["race:NightElf"]="Selbst im abgelegenen Zufluchtsort Aldrassil halten die Kaldorei ein wachsames Auge auf Kalimdors veränderliche Grenzen, um ihre frisch gepflanzten Äste zu verteidigen."},sec={{t="Eine Botschaft in den Schatten",b="Während jüngere Nachtelfen unter Konservator Ilthalaine das Gleichgewicht der Natur studieren, erhalten jene, die zu Heimlichkeit und Täuschung neigen, eine stillere Vorladung. Das Verschlüsselte Siegelzeichen wird durch einen Boten von Frahun Schattenflüsterer überbracht, dem Schurkenausbilder von Laubschattental. Versehen mit Chiffren, die einzig für Eingeweihte des Handwerks bestimmt sind, weist es den Träger an, seinen Inhalt zu entschlüsseln und Frahun nahe den Wurzeln von Aldrassil aufzusuchen, um formell mit der Ausbildung zu beginnen."},{t="Den Horizont im Blick",b="Frahuns Botschaft ist mehr als eine einfache Verabredung zum Training; sie dient als ernüchternde Warnung vor den geopolitischen Realitäten Kalimdors. Nach dem Ende des Dritten Krieges bleibt der Frieden zwischen der Allianz und der aufstrebenden Horde hauchdünn. In Laubschattental werden schurkische Späher und Informanten dazu angehalten, schon früh Augen und Ohren offen zu halten, um potenzielle Bedrohungen und verdeckte Provokationen zu überwachen, die jenseits der Grenzen erneut einen Krieg entfachen könnten."}},faq={{q="Was ist das Verschlüsselte Siegelzeichen?",a="Es ist ein kodiertes Zeichen, das der Schurkenausbilder Frahun Schattenflüsterer an neue Schurken in Laubschattental sendet und sie anweist, sich für ihre formelle Ausbildung unter Aldrassil bei ihm zu melden.",al={"was ist dieses siegelzeichen","verschlüsselte siegelzeichen quest","siegelzeichen gegenstand"}},{q="Wer übergibt das Siegelzeichen an junge Nachtelfen?",a="Konservator Ilthalaine überbringt das Siegelzeichen in Frahuns Namen, sobald ein Eingeweihter grundlegende Kompetenz im Umgang mit der einheimischen Tierwelt um die Äste von Laubschattental bewiesen hat.",al={"wer gibt die quest","questgeber","konservator ilthalaine"}},{q="Wo ist Frahun Schattenflüsterer zu finden?",a="Frahun Schattenflüsterer ist im Schutz des Großen Baumes Aldrassil in Laubschattental stationiert, bereit, neu eingetroffene Nachtelfenschurken auszubilden.",al={"wo ist frahun","frahun schattenflüsterer finden","frahun standort"}},{q="Warum werden im friedlichen Teldrassil Schurken benötigt?",a="Wie Frahun anmerkt, ist der vorherrschende Waffenstillstand mit externen Fraktionen brüchig. Heimliche Späher und Kundschafter sind unerlässlich, um Heimlichtuereien aufzudecken, insbesondere im Hinblick auf Bewegungen der Horde und interne Bedrohungen für die Äste.",al={"warum brauchen nachtelfen schurken","schurken in laubschattental","zweck von schurken"}},{q="Was geschieht, nachdem man Frahun das Siegelzeichen vorgelegt hat?",a="Frahun nimmt die Chiffre entgegen, erkennt Eure Bereitschaft an und lädt Euch ein, zurückzukehren, sobald Ihr Erfahrung sammelt, damit er Euch Kampftechniken, den Umgang mit Waffen und die Künste der Heimlichkeit lehren kann.",al={"was kommt danach","nach verschlüsseltes siegelzeichen","siegelzeichen belohnung geschichte"}},{q="Bedroht die Horde Laubschattental aktiv und direkt?",a="Obwohl das abgelegene Blätterdach von Teldrassil vor offenen Angriffen der Horde weitgehend abgeschirmt ist, halten Gerüchte über Agenten der Horde, die überall auf Kalimdor Misstrauen säen, die Wachtposten und Agenten der Kaldorei in höchster Alarmbereitschaft.",al={"ist die horde in teldrassil","horde bedrohung laubschattental","horde säht misstrauen"}}},fp="15,280,24.439.0,20.437.0,28.164.0,41.169.0,39.144.0,45.228.0,50.181.0,53.192.0"}
P.entries["quest:3119"] = {n="Geheiligtes Siegelzeichen",s="Das Geheiligte Siegelzeichen ist eine einführende Vorladung, die jungen Nachtelfenpriestern zu Beginn ihrer Ausbildung im Laubschattental überbracht wird. Konservator Ilthalaine übermittelt die Nachricht der Priesterlehrerin Shanda und weist unerfahrene Novizen an, in Aldrassil Führung zu suchen, während sie lernen, Elunes Anmut zu wirken.",h="Das Geheiligte Siegelzeichen ist eine einführende Vorladung, die jungen Nachtelfenpriestern zu Beginn ihrer...",kw={"aldrassil","konservator ilthalaine","elune","geheiligtes siegelzeichen","priester","laubschattental","shanda","teldrassil"},ang={["class:Priest"]="Dieser Übergangsritus verbindet einen novizischen Kaldorei-Priester mit Shanda und leitet seine formelle Ausbildung im Licht und in der Weisheit von Elune ein.",["faction:Alliance"]="Shandas Bemerkungen verdeutlichen, wie neu geschlossene Bündnisse mit der Allianz unbekannte Völker und Reisende direkt auf die Äste von Teldrassil führen.",["race:NightElf"]="Die Priesterschaft ist von zentraler Bedeutung für die Kultur der Kaldorei und wird von uralten Traditionen der Mondverehrung geleitet, die ihr Volk seit Jahrtausenden führen."},sec={{t="Ein Ruf zum Dienst",b="Priester nehmen in der Kultur der Nachtelfen einen heiligen Platz als Mägde und Diener der Mondgöttin Elune ein. Wenn ein junger Kaldorei im Laubschattental eine Affinität zum göttlichen Licht und zur Hingabe zeigt, vertraut Konservator Ilthalaine ihm ein geheiligtes Siegelzeichen an. Überbracht durch einen Boten der Priesterlehrerin Shanda, dient dieses Zeichen als formelle Einladung, sich am Baum Aldrassil einzufinden, um die engagierte spirituelle Unterweisung zu beginnen."},{t="Eine Welt im Wandel",b="Beim Treffen mit Shanda erfährt der junge Akolyt, dass die geschützte Zuflucht von Teldrassil ungewöhnliche Umwälzungen erlebt. Shanda bemerkt, dass sich in den Ästen des Weltenbaums Reisende tummeln, darunter Mitglieder der weiteren Allianz, denen gestattet wurde, sich mit den Kaldorei zu treffen. Obwohl die weite Welt ruft, rät Shanda den Novizen, sich zunächst den Problemen zu widmen, die Laubschattental unmittelbar bevorstehen, bevor sie sich in die größeren Konflikte jenseits seiner Grenzen wagen."}},faq={{q="Was ist das Geheiligte Siegelzeichen?",a="Es ist ein beschriftetes Zeichen, das von der Priesterlehrerin Shanda per Bote an Konservator Ilthalaine geschickt wurde, um einen Priesternovizen zur Unterweisung in Aldrassil herbeizurufen.",al={"geheiligtes siegelzeichen gegenstand","was ist dieses siegelzeichen","siegelzeichen von shanda"}},{q="Wer ist Shanda?",a="Shanda ist die Priesterlehrerin, die bei Aldrassil im Laubschattental stationiert ist. Sie leitet angehende Nachtelfenpriester in den grundlegenden Riten, Disziplinen und Gebeten der Schwesternschaft von Elune an.",al={"priesterlehrer aldrassil","wer ist shanda"}},{q="Wo befindet sich Shanda?",a="Shanda weilt im hohlen Stamm von Aldrassil, dem gewaltigen zentralen Baum im Herzen des Laubschattentals auf Teldrassil.",al={"shanda finden","wo geheiligtes siegelzeichen abgeben","shanda aufenthaltsort"}},{q="Warum besuchen Mitglieder der Allianz Teldrassil?",a="Die Nachtelfen haben nach dem Dritten Krieg Bande mit der Allianz geschmiedet. Fremde Völker treffen nun allmählich auf den Ästen von Teldrassil ein, um sich mit den Kaldorei abzustimmen und zu beraten, während sich beide Seiten auf die bevorstehenden Herausforderungen Azeroths vorbereiten.",al={"allianz in teldrassil","warum fremde auf weltenbaum"}},{q="Was sollte ein Priester nach Abschluss dieser Aufgabe tun?",a="Shanda rät den Priestern, den örtlichen Verteidigern und Wächtern im gesamten Laubschattental beizustehen und zu ihr zurückzukehren, wann immer sie neue Gebete und Techniken erlernen müssen.",al={"was nach siegelzeichen","nach geheiligtem siegelzeichen"}},{q="Warum vergibt Ilthalaine diese Quest?",a="Konservator Ilthalaine überwacht die allerersten Prüfungen der Novizen im Laubschattental. Als ein Bote von Shanda mit dem Siegelzeichen eintraf, behielt Ilthalaine es ein, bis sich der angehende Priester als fähig erwies, die nächsten Schritte zu unternehmen.",al={"konservator ilthalaine priester","warum mit ilthalaine sprechen"}}},fp="14,305,20.428.0,16.449.0,27.161.0,14.184.0,24.118.0,45.236.0,51.159.0,36.218.0"}
P.entries["quest:312"] = {n="Tundra MacGranns gestohlene Vorräte",s="Tundra MacGrann, ein verletzter Zwergenjäger, der in den kalten Felswänden von Dun Morogh lebt, hat seine Wintervorräte an eine berüchtigte örtliche Bestie verloren. Ein riesiger Yeti, bekannt als Old Icebeard, schleppte MacGranns thoriumverstärkte Fleischkiste in seine Höhle. Da der Jäger mit einem lahmen Bein der Bestie nicht davonlaufen kann, ist er auf vorbeikommende Abenteurer angewiesen, die hineinschlüpfen und seinen Proviant zurückholen.",h="Tundra MacGrann, ein verletzter Zwergenjäger, der in den kalten Felswänden von Dun Morogh lebt, hat seine...",kw={"trockenfleisch","dun morogh","fleischkiste","old icebeard","gestohlenes lager","thorium","tundra macgrann","yeti"},ang={["class:Hunter"]="Andere Fährtenleser werden MacGranns Missgeschick nachempfinden können, dass monatelanges sorgfältiges Ausweiden und Haltbarmachen von Wild von einer opportunistischen Bestie zunichtegemacht wurde, während er Hirsche aufspürte.",["class:Rogue"]="MacGrann sucht gezielt nach heimlichen Reisenden, was diesen Diebstahl zu einem Paradeauftrag für Kundschafter macht, die sich hinter Old Icebeards Rücken hineinschleichen können, ohne jemals eine Klinge zu ziehen.",["race:Dwarf"]="Jeder Zwerg in Dun Morogh kennt die unbarmherzige Härte eines Bergwinters; ohne haltbares Fleisch oder Unterschlupf kann selbst ein abgehärteter Bergsteiger der Kälte nicht standhalten."},sec={{t="Wintervorräte und gestohlene Kisten",b="Das Überleben in den harten Wintern von Dun Morogh erfordert Vorbereitung, insbesondere für Bergsteiger, die außerhalb der Wärme von Kharanos und Eisenschmiede leben. Tundra MacGrann hatte sorgfältig Trockenfleisch für einen ganzen Monat eingesalzen, um die Schneestürme der kommenden kalten Jahreszeit zu überstehen. Als Vorsichtsmaßnahme gegen hungrige wilde Bären verschloss er seine Rationen in einer verstärkten Fleischkiste aus Thorium. Leider bedachte er nicht die schiere rohe Kraft der Bergyetis, die die gesamte Truhe wegtrugen, anstatt zu versuchen, sie an Ort und Stelle zu öffnen."},{t="Old Icebeards Höhle",b="Der Übeltäter hinter dem Diebstahl ist Old Icebeard, ein gefürchteter und bösartiger Yeti, der in den zerklüfteten Hügeln lauert. Während MacGrann auf der Jagd nach Hirschen war, schnappte sich Icebeard die Kiste und schleppte sie in seine Berghöhle zurück. Obwohl MacGrann zuversichtlich bleibt, dass selbst ein Yeti massives Thoriumblech nicht zerschmettern kann, macht sein eigenes verletztes Bein eine Bergungsmission zu einem Selbstmordkommando. Jede tapfere Seele, die sich in die Höhle wagt, muss entweder direkt gegen die Bestie antreten oder ihr Eindringen sorgfältig planen, während das Ungeheuer draußen durch die Schneewehen streift."}},faq={{q="Wer ist Tundra MacGrann?",a="Tundra MacGrann ist ein zwergischer Fallensteller und Jäger, der in den schneebedeckten Weiten von Dun Morogh lebt. Wegen eines verletzten Beins ist er auf seine angelegten Vorräte angewiesen, um die harten Winterbedingungen zu überstehen.",al={"tundra macgrann","macgrann","wer ist macgrann"}},{q="Wer hat MacGranns Fleischkiste gestohlen?",a="Ein bedrohlicher örtlicher Yeti namens Old Icebeard stahl die Kiste, während MacGrann auf der Jagd nach Hirschen war, und schleppte die schwere Thoriumtruhe in sein Bergversteck.",al={"wer hat das lager gestohlen","wer hat das fleisch genommen","dieb des gestohlenen lagers"}},{q="Warum kann MacGrann sein Fleisch nicht selbst zurückholen?",a="MacGrann leidet an einem verletzten Bein, das seine Beweglichkeit stark einschränkt. Er weiß, dass er sich nicht schnell oder leise genug bewegen kann, um Old Icebeards Höhle zu betreten und wieder zu verlassen, ohne erwischt und zerfleischt zu werden.",al={"warum macgrann es nicht holen kann","macgranns bein","lahmes bein"}},{q="Hat der Yeti das Essen gefressen?",a="Nein. Das Trockenfleisch war in einer robusten Kiste aus massivem Thorium eingeschlossen. Obwohl es dem Yeti gelang, den schweren Behälter wegzutragen, ist er nicht in der Lage, das Metall zu durchbrechen.",al={"ist das essen gefressen","kann icebeard die kiste oeffnen"}},{q="Muss man gegen Old Icebeard kämpfen, um die Fleischkiste zu bekommen?",a="Nein, Ihr müsst nicht zwingend gegen ihn kämpfen. Old Icebeard wandert regelmäßig außerhalb seines Unterschlupfs umher, was flinken Abenteurern die Gelegenheit bietet, sich unbemerkt in die Höhle zu schleichen und die Kiste zu plündern.",al={"an icebeard vorbeischleichen","muss icebeard getoetet werden"}},{q="Wo befindet sich das gestohlene Versteck?",a="Die gestohlene Fleischkiste liegt tief im Inneren von Old Icebeards Berghöhle, die sich in den Hügeln nahe MacGranns Lager in Dun Morogh befindet.",al={"wo ist die hoehle","icebeard hoehle standort"}}},fx={ceb049bb={q="Warum muss Tundra MacGrann seinen Fleischschrank zurückerhalten?",a="MacGrann hat lange Tage damit verbracht, einen ganzen Monat an Rationen zu jagen und einzupökeln, um die harte kalte Jahreszeit in Dun Morogh zu überleben. Ohne dieses konservierte Fleisch droht ihm in seinem abgelegenen Lager in den Bergen der Hungertod, sobald die Winterstürme aufziehen, da sein verletztes Bein ihn daran hindert, genug Wild zu jagen, um seine Wintervorräte rechtzeitig aufzustocken.",al={"warum tundra macgrann helfen","macgranns motiv","warum den fleischschrank bergen"}},["9ce729b1"]={q="Was ist MacGranns Trockenfleisch?",a="Es ist ein umfangreicher Vorrat an gepökeltem Wildbret und Fleisch, den Tundra MacGrann speziell dafür konserviert hat, den Winter in den Bergen zu überdauern. Er hat das Fleisch in einem verstärkten Thoriumschrank eingeschlossen, damit aasfressende Bären es nicht wittern können, was sich glücklicherweise als robust genug erwies, um auch den Alten Eisbart davon abzuhalten, sich darüber herzumachen.",al={"macgranns trockenfleisch","was ist macgranns trockenfleisch","inhalt macgranns fleischschrank"}}},fp="30,373,32.541.0,18.519.0,23.186.0,33.155.0,46.194.0,26.184.0,57.189.0,34.127.0"}
P.entries["quest:3120"] = {n="Tiefgrünes Siegelzeichen",s="Das Tiefgrüne Siegelzeichen ist eine schriftliche Vorladung, die neu erwachten Nachtelfendruiden in Laubschattental überreicht wird. Konservator Ilthalaine gibt es weiter, um angehende Gestaltwandler zu Mardant Starkeiche im Geäst von Aldrassil zu leiten. Es markiert den formellen Beginn der Unterweisung eines Druiden in den Mysterien der Natur und des Smaragdgrünen Traums.",h="Das Tiefgrüne Siegelzeichen ist eine schriftliche Vorladung, die neu erwachten Nachtelfendruiden in...",kw={"aldrassil","druidenlehrer","smaragdgrüner traum","ilthalaine","mardant starkeiche","laubschattental","tiefgrünes siegelzeichen"},ang={["class:Druid"]="Diese Quest stellt Eure offizielle Initiation in die Lehren des Zirkels des Cenarius unter Mardant Starkeiche dar und bringt Euch auf den langen Pfad zum Verständnis des Smaragdgrünen Traums.",["race:NightElf"]="Der Druidismus ist tief in der Kultur der Nachtelfen verwoben; die Vorlage dieses Siegelzeichens bei Aldrassil markiert den ersten Schritt eines Initianden in eine uralte Tradition."},sec={{t="Ein Ruf ins Geäst",b="Sobald ein junger Nachtelf Talent darin zeigt, das lokale Gleichgewicht von Laubschattental zu bewahren, ist eine formelle Einführung in seinen Orden erforderlich. Konservator Ilthalaine erhält das Tiefgrüne Siegelzeichen über einen Boten und vertraut es dem Initianden an. Das kleine Zeichen bedeutet, dass der Zirkel in Aldrassil aufmerksam geworden ist und den jungen Druiden einlädt, seine Ausbildung offiziell aufzunehmen."},{t="Zwiesprache und der Traum",b="Nachdem das Siegelzeichen Mardant Starkeiche in Aldrassil vorgelegt wurde, wird der Initiand in der Gemeinschaft willkommen geheißen. Während tiefer gehende Zwiesprache mit dem Smaragdgrünen Traum und das Meistern von Tiergestalten noch in der Zukunft liegen, nimmt Mardant die Rolle des ersten Führers ein, der ihm beibringt, wie man die Naturgeister deutet und ungezähmte Waldkräfte kanalisiert."}},faq={{q="Was ist das Tiefgrüne Siegelzeichen?",a="Es ist eine beschriftete Vorladung, die im Namen von Mardant Starkeiche über Konservator Ilthalaine überbracht wird und einen Novizendruiden dazu aufruft, seine formelle Ausbildung im Inneren von Aldrassil zu beginnen.",al={"tiefgrünes siegelzeichen gegenstand","was ist dieses siegelzeichen","druidensiegelzeichen"}},{q="Wohin bringe ich das Tiefgrüne Siegelzeichen?",a="Bringt es zu Mardant Starkeiche, dem Druidenlehrer im Inneren des großen Hügelbaums Aldrassil im Herzen von Laubschattental.",al={"wo ist mardant","tiefgrünes siegelzeichen abgeben","wohin gehen"}},{q="Warum erwähnt Mardant den Smaragdgrünen Traum?",a="Druiden schöpfen einen Großteil ihrer Macht und Weisheit durch lange Schlaftrancen aus dem Smaragdgrünen Traum. Auch wenn ein Novize noch nicht bereit ist, frei im Traum zu wandeln, führt Mardant ihn als das grundlegende Mysterium ein, das er letztlich studieren wird.",al={"warum smaragdgrüner traum","mardant traum dialog","druidentrance"}},{q="Wer schickt das Siegelzeichen zu Ilthalaine?",a="Ein von Mardant Starkeiche entsandter Bote überbrachte das Siegelzeichen an Konservator Ilthalaine, damit es direkt in die Hände eines vielversprechenden jungen Druiden gelegt werden konnte.",al={"wer schickte das siegelzeichen","siegelzeichen bote"}},{q="Was geschieht nach dem Vorzeigen des Siegelzeichens?",a="Mardant Starkeiche wird Euer Hauptmentor in Laubschattental, wodurch Ihr Eure ersten Druidenzauber und magischen Techniken erlernen könnt, während Eure Macht wächst.",al={"was lerne ich als nächstes","nach dem tiefgrünen siegelzeichen"}},{q="Können Nicht-Druiden diese Quest erhalten?",a="Nein. Das Tiefgrüne Siegelzeichen ist ausschließlich für Nachtelfendruiden bestimmt, die ihre Reise in Laubschattental beginnen. Andere Klassen erhalten jeweils eigene Vorladungen zu ihren entsprechenden Ausbildern.",al={"nur für druiden","wer erhält tiefgrünes siegelzeichen"}}},fp="13,326,20.364.0,23.330.0,26.170.0,34.128.0,43.235.0,34.157.0,40.156.0,34.178.0"}
P.entries["quest:313"] = {n="Zum Zusehen verdammt",s="Pilot Steinsegel aus Kharanos sucht nach jemandem mit echtem Zwergenmut, um seine geliebte Belagerungsmaschine, den Trollpflüger, aufzumöbeln. Um den Schneid eines angehenden Abenteurers auf die Probe zu stellen, schickt er ihn nach Westen in die gefährliche Höhle namens Der altgediente Bau, um wilde Wendigos wegen ihrer dicken Pelze zu jagen.",h="Pilot Steinsegel aus Kharanos sucht nach jemandem mit echtem Zwergenmut, um seine geliebte...",kw={"dun morogh","der altgediente bau","kharanos","pilot steinsegel","trollpflüger","wendigo","wendigomähne"},ang={["profession:Engineering"]="Jeder, der die Kunst der zwergischen Belagerungsfahrzeuge zu schätzen weiß, weiß auch, dass die Instandhaltung schwerer Maschinen bei Minusgraden kreative Lösungen für die Wärme im Cockpit erfordert.",["race:Dwarf"]="Für junge Bergsteiger und Abenteurer aus Eisenschmiede ist der Kampf gegen die Wendigos aus dem altgedienten Bau eine wesentliche örtliche Reifeprüfung.",["race:Gnome"]="Seite an Seite mit den Zwergen rund um Kharanos zu leben bedeutet, mit anzupacken, um die schwer gepanzerten Maschinen von Eisenschmiede auszurüsten."},sec={{t="Ein Test des Zwergenmuts",b="Die Bedienung eines gewaltigen zwergischen Belagerungspanzers erfordert Nerven aus Eisen und die Konstitution, zähneklappernde Maschinerie in eisiger Bergluft zu beherrschen. Pilot Steinsegel, stationiert in Stahlrosts Depot nahe Kharanos, behauptet, beides im Überfluss zu besitzen. Anstatt einfach Arbeit oder Respekt leichtfertig zu vergeben, fordert er Neulinge heraus zu beweisen, dass sie denselben standhaften Charakter besitzen, indem sie in die gefrorenen Hügel ziehen, um sich den einheimischen Bestien zu stellen."},{t="Häusliche Gemütlichkeit im Trollpflüger",b="Stonegears Belagerungsmaschine trägt den stolzen und unmissverständlichen Namen Trollpflüger, doch ihre enge, eisenbeschlagene Kabine ist im bitteren Klima von Dun Morogh grausam kalt. Stonegear verfällt auf eine praktische, wenn auch wilde Lösung: Wendigopelz. Das Erbeuten dicker Mähnen von den wilden Wendigos, die den altgedienten Bau durchstreifen, liefert die benötigten Materialien, um einen strapazierfähigen, warmen Vorleger für das Deck des Trollpflügers anzufertigen, während gleichzeitig der Bestand der örtlichen Bestien eingedämmt wird."}},faq={{q="Wer ist Pilot Steinsegel?",a="Pilot Steinsegel ist ein zwergischer Belagerungsmaschinenfahrer, der außerhalb von Kharanos in Dun Morogh stationiert ist. Er steuert eine gepanzerte Kriegsmaschine, die liebevoll auf den Namen Trollpflüger getauft wurde, und ist ungemein stolz auf seine eisernen Nerven und sein mechanisches Handwerk.",al={"pilot steinsegel","wer vergibt quest","wer ist stonegear"}},{q="Wo befindet sich der altgediente Bau?",a="Der altgediente Bau ist ein schneebedecktes Höhlensystem, das in den Bergen direkt westlich von Kharanos liegt. Er dient als berüchtigter Unterschlupf für die bösartigen Wendigos von Dun Morogh.",al={"der altgediente bau standort","wo ist wendigohöhle","den altgedienten bau finden"}},{q="Warum möchte Stonegear Wendigomähnen?",a="Stonegear möchte das dichte, wärmende Fell der Wendigos, um einen behaglichen Teppich für das Innendeck seiner Belagerungsmaschine, den Trollpflüger, anzufertigen und gleichzeitig den Mut eines Abenteurers auf die Probe zu stellen.",al={"warum wendigomähnen","zweck der mähnen","wofür mähnen"}},{q="Was ist der Trollpflüger?",a="Der Trollpflüger ist Pilot Steinsegels persönliche zwergische Belagerungsmaschine. Sein aggressiver Name spiegelt den anhaltenden Konflikt zwischen den Zwergen von Eisenschmiede und den feindseligen Trollen der Frostmähnen wider, die die umliegenden Felsen bewohnen.",al={"trollpflüger","stonegear panzer","was ist trollpflüger"}},{q="Welche Kreaturen bewohnen den altgedienten Bau?",a="Die Höhle wird von wilden Wendigos bewohnt – ungezähmten, affenähnlichen Bestien, die in den verschneiten Höhen von Dun Morogh heimisch sind und ihr Territorium aggressiv gegen jeden Eindringling verteidigen.",al={"monster im altgedienten bau","was lebt im altgedienten bau"}},{q="Stellen die Wendigos eine Gefahr für Kharanos dar?",a="Obwohl Wendigos selten koordinierte Angriffe wie die Frostmähnentrolle starten, machen ihre unberechenbare Wildheit und die Nähe zu den Hauptstraßen sie zu einer ständigen Gefahr für Reisende und örtliche Handwerker gleichermaßen.",al={"sind wendigos eine bedrohung","wendigo gefahr"}}},fx={["9edb896b"]={q="Wofür werden die Wendigomähnen verwendet?",a="Pilot Steinsegel will die dicken, zotteligen Mähnen der Wendigos aus The Grizzled Den für einen sehr praktischen Luxus für Zwerge: die Inneneinrichtung. Eine massive Belagerungsmaschine wie den Trollpflug bei der beißenden Kälte von Dun Morogh zu bedienen, lässt den Metalldeckboden unter den Füßen gefrieren. Steinsegel plant, die geernteten Mähnen zu einem warmen, schweren Teppich zusammenzunähen, um die Kabine des Trollpflugs während langer Patrouillen gemütlicher zu machen.",al={"nutzen wendigomähne","wofür ist wendigomähne","warum wendigomähnen"}},["72b90979"]={q="Warum schickt Pilot Steinsegel Euch anstatt die Mähnen selbst zu holen?",a="Steinsegel ist Pilot einer Belagerungsmaschine, und die Instandhaltung einer Eisenmaschine wie des Trollpflugs sowie deren Verteidigungsbereitschaft in Kharanos erfordern seine volle Aufmerksamkeit. Die Jagd auf wendige, wilde Wendigos in engen, zugefrorenen Höhlengängen ist keine Arbeit, die für eine massive Kriegsmaschine geeignet ist. Steinsegel betrachtet die Aufgabe auch als eine offene Herausforderung, um zu sehen, ob Ihr den Mut, das Rückgrat und die Nerven besitzt, die man von den Verteidigern von Dun Morogh verlangt.",al={"warum ich steinsegel","warum braucht steinsegel hilfe","warum mähnen nicht selbst holen"}}},fp="16,281,14.425.0,30.426.0,23.224.0,34.163.0,38.185.0,18.206.0,48.167.0,39.204.0"}
P.entries["quest:314"] = {n="Die Herde beschützen",s="Die Herde beschützen ist eine Aufgabe, die von Rudra Amberstill auf dem Gehöft Bernruh in Dun Morogh vergeben wird. Eine wilde, raubtierhafte Bestie namens Vagash hat nachts die geschätzten Bergwidder der Ranch angegriffen, und da die Militärgarnison von Eisenschmiede über das gesamte Reich verstreut ist, müssen sich die einheimischen Züchter zur Verteidigung auf vorbeiziehende Abenteurer verlassen.",h="Die Herde beschützen ist eine Aufgabe, die von Rudra Amberstill auf dem Gehöft Bernruh in Dun Morogh vergeben...",kw={"gehöft bernruh","dun morogh","eisenschmiede","bergwidder","die herde beschützen","rudra amberstill","vagash","veron bernruh"},ang={["class:Hunter"]="Das Aufspüren eines berüchtigten Spitzenprädators wie Vagash in seinem Mountain Den ist eine klassische Bewährungsprobe für jeden Fährtenleser, der seine Fertigkeiten in den Schneeverwehungen von Dun Morogh verfeinert.",["faction:Alliance"]="Da die Regimenter des High Seat abgezogen wurden, um die Verpflichtungen der Allianz in den Östlichen Königreichen zu stärken, trägt die Hilfe für bedrängte ländliche Gehöfte zur Stabilisierung der Heimatfront bei.",["race:Dwarf"]="Für Zwergenwanderer schützt die Verteidigung von Gehöft Bernruh genau die Bergwidder, die Euer Volk in ganz Khaz Modan in die Schlacht tragen."},sec={{t="Eine Bedrohung für die Ranch",b="Das Gehöft Bernruh liefert die Bergwidder, die den Bronzebeardzwergen als ikonische Reittiere und Arbeitstiere dienen. Der Erhalt dieser Herden ist lebenswichtig für die ländliche Wirtschaft von Dun Morogh. Als die Nacht hereinbrach und panische Schreie über die Koppeln hallten, bemerkte die Familie Amberstill, dass zwei ihrer geschätzten Widder fehlten. Der Übeltäter ist Vagash, eine berüchtigte und wilde Bestie, die in den nahen Felsen oberhalb der Ranch lauert und dafür bekannt ist, das einheimische Vieh gewaltsam zu reißen."},{t="Überstrapazierte Verteidigung",b="Normalerweise würden lokale Bedrohungen dieses Ausmaßes von den Zwergengebirgsjägern oder den königlichen Streitkräften von König Magni Bronzebart bekämpft. Die stehende Armee von Eisenschmiede ist jedoch derzeit an fernen Fronten gebunden, um die Allianz im weiteren Sinne zu unterstützen. Ohne eine offizielle Militärabteilung zur Bewachung der Bergkämme ist Rudra Amberstill gezwungen, unabhängige Kämpfer darum zu bitten, Vagash zur Strecke zu bringen und einen der tödlichen Reißzähne der Bestie als Beweis zurückzubringen."}},faq={{q="Wer ist Vagash?",a="Vagash ist ein gefährliches, raubtierhaftes Monster, das die verschneiten Kämme direkt über dem Gehöft Bernruh durchstreift. Gefürchtet wegen seiner schieren Kraft und seines unersättlichen Appetits, stellt er eine tödliche Bedrohung sowohl für zahme Widderherden als auch für unvorsichtige Reisende im östlichen Dun Morogh dar.",al={"was ist vagash","vagash monster","vagash hintergrund"}},{q="Wo ist Vagash zu finden?",a="Vagash haust in einer schneebedeckten Höhle hoch oben in den Felsen mit Blick auf das Gehöft Bernruh. Steigt man den schneebedeckten Hügel gleich hinter den Kiefern hinter dem Gehöft hinauf, gelangt man direkt zum Eingang seines Baus.",al={"vagash aufenthaltsort","wo ist vagash","vagash finden"}},{q="Warum kümmern sich die Wachen von Eisenschmiede nicht darum?",a="Die Truppen von König Magni Bronzebart sind derzeit weit verstreut, um strategische Garnisonen zu verteidigen und ferne Feldzüge der Allianz zu unterstützen. Infolgedessen müssen ländliche Gehöfte wie das Gehöft Bernruh für sich selbst sorgen oder fähige Abenteurer anheuern.",al={"warum keine wachen","wo ist armee von eisenschmiede","warum amberstill helfen"}},{q="Wer ist der von Rudra erwähnte Veron?",a="Veron Bernruh ist ein Meisterwidderzüchter auf der Ranch, der die gefeierten Reitwidder der Bronzebeards ausbildet und pflegt. Rudra erwähnt, dass Veron ungemein erleichtert sein wird, sobald die raubtierhafte Bedrohung, die ihren geschätzten Tieren nachstellt, beseitigt ist.",al={"wer ist veron","veron bernruh","veron"}},{q="Warum ist ein Beweis für den Abschuss erforderlich?",a="Rudra verlangt den Reißzahn von Vagash, um absolut sicherzugehen, dass das echte Monster, das ihre Herden terrorisiert, zur Strecke gebracht wurde und nicht nur ein gewöhnlicher Streuner von den Berghängen.",al={"warum zahn von vagash","zahn von vagash","was ist der beweis"}},{q="Welche Bedeutung haben die Widder für Dun Morogh?",a="Bergwidder sind zähe, trittsichere Kreaturen, die bestens dafür geeignet sind, sich im eisigen, felsigen Gelände von Khaz Modan zu bewegen. Sie dienen dem Zwergenkönigreich als unverzichtbare Zugtiere, Wolllieferanten und Kavalleriereittiere.",al={"warum widder wichtig sind","amberstill widder nutzen","zwergenwidder hintergrund"}}},fx={["81b569d0"]={q="Warum will Rudra Amberstill, dass dies erledigt wird?",a="Rudra Amberstill verteidigt die Lebensgrundlage ihrer Familie. Das Gehöft Bernruh züchtet und pflegt die robusten Bergwidder, die in ganz Dun Morogh und Eisenschmiede geschätzt werden. Vagash hat begonnen, in der Nähe des Gehöfts herumzustreunen und schleicht sich im Schutz der Dunkelheit heran, um das Vieh zu töten. Da bereits zwei preisgekrönte Widder in einer einzigen Nacht verschleppt wurden, kann das Gehöft keine fortwährenden Überfälle eines solch bösartigen Raubtiers überstehen.",al={"warum will rudra vagash tot","rudra amberstills motiv","warum vagash töten"}},["34abe682"]={q="Wozu dient der Fangzahn von Vagash?",a="Der Fangzahn dient als unbestreitbarer physischer Beweis dafür, dass die gefürchtete Bestie tatsächlich erlegt wurde. Vagash ist auf dem Gehöft für seine Größe und Wildheit berüchtigt, und Rudra Amberstill braucht absolute Gewissheit, dass das Raubtier, das auf den Felsen über ihnen lauert, tot ist, bevor sie und ihre Familie sich wegen ihrer überlebenden Herde beruhigen können.",al={"warum fangzahn von vagash nötig","zweck fangzahn von vagash","vagash zahn"}}},fp="19,335,21.456.0,17.452.0,14.250.0,26.210.0,47.246.0,32.240.0,34.185.0,47.216.0"}
P.entries["quest:315"] = {n="Das perfekte Starkbier",s="Rejold Gerstenbräu aus Bräuhall ist entschlossen, das ultimative Zwergenstarkbier zu brauen, indem er familiäre Brautradition mit exotischen einheimischen Zutaten verbindet. Um sein experimentelles Rezept zu perfektionieren, sucht er nach Schimmerkraut, einer beißenden Pflanze, die ausschließlich von den feindseligen Frostmähnentrollen auf dem Schimmergrat angebaut wird. Wagemutige Reisende werden in das Lager der Trolle geschickt, um das Kraut direkt aus den Stammeskörben zu entwenden.",h="Rejold Gerstenbräu aus Bräuhall ist entschlossen, das ultimative Zwergenstarkbier zu brauen, indem er...",kw={"brewnall","dun morogh","zwergenbier","frostmähnen","das perfekte starkbier","rejold gerstenbräu","schimmergrat","schimmerkraut"},ang={["profession:Herbalism"]="Obwohl es kein gewöhnliches Handwerkskraut ist, machen die einzigartigen botanischen Eigenschaften des frostbeständigen Schimmerkrauts es zu einer faszinierenden Besonderheit in den eisigen Felsen von Dun Morogh.",["race:Dwarf"]="Das Brauen ist für den Bronzebart-Clan praktisch heilig, und das Finden eines exotischen Wildkrauts, um konkurrierende Tavernen zu übertrumpfen, gilt als edles Bestreben."},sec={{t="Der Ehrgeiz eines Brauers",b="In Bräuhall ist das Brauen mehr als nur ein Handwerk – es ist eine Lebensart, besonders für die Familie Gerstenbräu. Rejold Gerstenbräu glaubt daran, dass ihm die Braukunst im Blut liegt, doch das legendäre 'perfekte Starkbier' zu erschaffen, verlangt nach unkonventionellen Innovationen. Anstatt sich allein auf standardmäßigen Hopfen, Malz und Gebirgsquellwasser zu verlassen, blickt Rejold auf die ungezähmte Flora von Dun Morogh, um seinem Bier eine unverwechselbare Note zu verleihen."},{t="Das Trollkraut vom Schimmergrat",b="Die geheime Zutat, nach der Rejold begehrt, ist Schimmerkraut, eine kälteresistente Pflanze, die von den Frostmähnentrollen oben auf dem Schimmergrat im Nordwesten kultiviert wird. Während die Frostmähnen sie für ihre eigenen rituellen und mystischen Bräuche ernten, hatten Zwerge abseits ihres scharfen, ausgeprägten Geschmacks bisher wenig praktische Verwendung dafür. Direkt aus den Vorratskörben im Trolldorf entwendet, dient das Kraut als Herzstück für Rejolds neuestes und kühnstes Gärexperiment."}},faq={{q="Was ist Schimmerkraut?",a="Schimmerkraut ist eine markante Pflanze, die von den Frostmähnentrollen auf dem Schimmergrat angebaut und geerntet wird. Während die Trolle sie hauptsächlich in ihren Stammeszeremonien und Ritualen verwenden, möchte Rejold Gerstenbräu ihren scharfen, einzigartigen Geschmack als unkonventionelles Aroma in der Zwergenbraukunst erproben.",al={"schimmerkraut lore","was bewirkt schimmerkraut","frostmähnen pflanze"}},{q="Wo befindet sich der Schimmergrat?",a="Der Schimmergrat liegt in den verschneiten Höhen nordwestlich von Bräuhall in Dun Morogh. Er dient den einheimischen Frostmähnentrollen als befestigtes Lager, was jeden Ausflug zum Kräutersammeln dorthin zu einem gefährlichen Vorstoß in feindliches Gebiet macht.",al={"schimmergrat standort","wo liegt der schimmergrat","schimmergrat finden"}},{q="Warum will Rejold von den Frostmähnentrollen stehlen?",a="Die Frostmähnentrolle besitzen das Monopol auf den Anbau von Schimmerkraut in Dun Morogh, und die Spannungen zwischen Zwergen und Trollen machen friedlichen Handel unmöglich. Da die Pflanzen in ihrem Lager bereits geerntet und in Stammeskörben gebündelt sind, ist das Hineinschleichen oder Durchkämpfen Rejolds einzige Möglichkeit, an sie heranzukommen.",al={"warum trolle bestehlen","warum trollkörbe","rejold troll plan"}},{q="Wer ist Rejold Gerstenbräu?",a="Rejold Gerstenbräu ist ein ehrgeiziger Zwergenbrauer, der in Bräuhall lebt. Seinem Familiennamen treu geblieben, hat er sein Handwerk der Entdeckung des Rezepts für das perfekte Starkbier gewidmet und experimentiert ständig mit neuen Geschmäckern und wirkungsvollen wilden Zutaten.",al={"wer ist rejold","rejold gerstenbräu","familie gerstenbräu"}},{q="Gilt Schimmerkraut als Alchemiekraut?",a="Nein. Schimmerkraut ist kein alchemistisches Reagenz, das von wilden Vorkommen gesammelt wird. Es ist ein Questgegenstand, der in Weidenkörben und Vorratslagern in den Siedlungen der Frostmähnen oben auf dem Schimmergrat aufbewahrt wird.",al={"können kräuterkundige schimmerkraut pflücken","ist schimmerkraut kräuterkunde","schimmerkraut sammeln"}},{q="Was geschieht mit dem Schimmerkraut, sobald es abgegeben wurde?",a="Rejold wirft das frisch gesammelte Schimmerkraut direkt in einen aktiven Gärbottich in Bräuhall, in der Hoffnung, dass sein einzigartiges Profil endlich das makellose Rezept hervorbringt, nach dem er gesucht hat.",al={"funktioniert das starkbier","rejold brauergebnis","schimmerkraut bier"}}},fx={["3780a202"]={q="Wer sind die Frostmähnentrolle?",a="Die Frostmähne sind ein einheimischer Stamm von Eistrollen, die auf den verschneiten Felsen von Dun Morogh heimisch sind. Von den expandierenden Zwergen aus Eisenschmiede aus ihren historischen Jagdgründen vertrieben, hegen sie eine tiefe Feindseligkeit gegenüber ihren zwergischen Nachbarn. Von Siedlungen wie der auf dem Schimmergrat aus kultivieren sie Schimmerkraut für ihre Stammesrituale und verteidigen ihre Lager erbittert gegen jeden Eindringling.",al={"frostmähnentrolle","wer sind die trolle auf dem schimmergrat","frostmähnentamm"}}},fp="17,402,19.424.0,31.459.0,20.281.0,31.242.0,56.313.0,25.248.0,42.182.0,47.191.0"}
P.entries["quest:317"] = {n="Vorräte für Dampfstrahl",s="Vorräte für Dampfstrahl ist eine Allianz-Quest, die von Pilot Bellfiz bei Stahlrosts Depot in Dun Morogh angeboten wird. Während er seine Belagerungsmaschine für einen längeren Einsatz mit der Belagerungsbrigade von Eisenschmiede vorbereitet, heuert der Pilot einheimische Jäger an, um Eberfleisch und Bärenpelze zur Verpflegung seiner Mannschaft zu sammeln.",h="Vorräte für Dampfstrahl ist eine Allianz-Quest, die von Pilot Bellfiz bei Stahlrosts Depot in Dun Morogh...",kw={"bärenpelze","eberfleisch","dun morogh","der altgediente bau","jetsteam","pilot bellfiz","belagerungsbrigade","stahlrosts depot"},ang={["faction:Alliance"]="Die Zusammenarbeit zwischen zwergischen Reparaturwerkstätten und den gepanzerten Besatzungen der Belagerungsbrigade hält die Belagerungstechnologie der Allianz an vorderster Front einsatzbereit.",["profession:Cooking"]="Das Beschaffen von dicken Stücken Eberfleisch in den Schneeverwehungen von Dun Morogh veranschaulicht das Hauptwild, das die örtlichen Gebirgsgarnisonen ernährt.",["race:Dwarf"]="Die Bereitstellung von Wild aus den schroffen Höhen von Dun Morogh hält die zwergischen Besatzungen der Belagerungsbrigade während ihrer Arbeit in den Maschinenwerkstätten von Khaz Modan satt und ausgeruht.",["race:Gnome"]="Bellowfiz beizustehen sorgt dafür, dass die zwergische Belagerungsbrigade – Eisenschmiedes mechanisierter Verbündeter der verbannten Gnome – für die bevorstehenden langen Feldzüge voll versorgt bleibt."},sec={{t="Verproviantierung der Maschine",b="Direkt vor Kharanos bei Stahlrosts Depot stationiert, überwacht Pilot Bellfiz die Vorbereitungen für eine bevorstehende Fernoperation im Auftrag der Belagerungsbrigade. Sein Belagerungspanzer namens Jetsteam benötigt sowohl eine mechanische Feinabstimmung durch Meisteringenieur Beldin Stahlrost als auch Feldproviant für einen Monat, um die Einsatzfähigkeit seiner Besatzung bei den rauen Minusgraden von Dun Morogh zu gewährleisten."},{t="Jagd in den Schneefeldern",b="Da Beldin Stahlrost unter der Haube von Jetsteam beschäftigt ist, kann Bellowfiz sein Fahrzeug nicht verlassen, um Rationen und Isolationsmaterial zu besorgen. Er weist Reisende an, in den verschneiten Ebenen südlich des altgedienten Baus zu jagen, wo einheimische Eber nahrhaftes Fleisch als Nahrung und Bären dicke Pelze liefern, die sich als warme Schlafunterlagen für den Panzer eignen."}},faq={{q="Was ist Jetsteam?",a="Jetsteam ist der Belagerungspanzer, der vom Zwerg Pilot Bellfiz gesteuert wird. Stationiert bei Stahlrosts Depot, wird er für einen längeren Militäreinsatz im Auftrag der Belagerungsbrigade von Eisenschmiede gewartet und mit Vorräten bestückt.",al={"jetsteam","wer ist jetsteam","was ist jetstream","bellowfiz panzer"}},{q="Wer ist Pilot Bellfiz?",a="Pilot Bellfiz, genannt Fizzer, ist ein zwergischer Belagerungsmaschinenpilot der Belagerungsbrigade von Eisenschmiede. Während sein Gefährt bei Stahlrosts Depot mechanischen Anpassungen unterzogen wird, koordiniert er die Feldvorräte für seinen bevorstehenden Einsatz.",al={"pilot bellfiz","bellowfiz","wer ist pilot bellfiz"}},{q="Wo können die benötigten Vorräte gesammelt werden?",a="Pilot Bellfiz verweist Jäger auf die verschneiten Ebenen südlich des altgedienten Baus – ein Gebiet, das von einheimischen Ebern und Bären bewohnt wird, deren Fleisch und Pelze angemessenen Proviant und Schlafunterlagen bieten.",al={"wo sind die eber","wo sind bären","jagdort","eberfleisch dun morogh"}},{q="Was ist die Belagerungsbrigade?",a="Die Belagerungsbrigade ist Eisenschmiedes Korps aus Belagerungsmaschinenpiloten, die schwer gepanzerte Kriegsmaschinen wie Jetsteam und Trollplow zur Unterstützung der zwergischen Verteidigung und von Allianz-Feldzügen bedienen.",al={"belagerungsbrigade"}},{q="Wohin führt dieser Einsatz als Nächstes?",a="Nachdem Jetsteam mit Fleisch und Pelzen aufgestockt wurde, schickt Pilot Bellfiz Reisende in der Quest Immerschimmer nach Westen nach Bräuhall, um nach einem wirksamen Gebräu zu suchen, das er sowohl zum Wärmen als auch als Notfallbrennstoff für den Ofen des Panzers nutzt.",al={"folgequest","was kommt nach vorräte für jetsteam","vorräte für jetsteam folgequest"}},{q="Warum benötigt eine Belagerungsmaschine Tierpelze?",a="Das Innere eines zwergischen oder gnomischen Dampfpanzers ist bei langen Einsätzen im Gebirgsschnee eiskalt und zugig. Dicke Bärenpelze bieten lebenswichtige Wärme und Isolierung für die Schlafstätten der Besatzung bei längeren Aufenthalten fernab des Lagers.",al={"warum pelz","nutzen von dickem bärenfell","bettzeug"}}},fx={bd6a237a={q="Warum will Pilot Bellfiz, dass dies erledigt wird?",a="Pilot Bellfiz rüstet sich für einen längeren Einsatz mit der Belagerungsbrigade. Die bevorstehende Mission wird ihn mindestens einen Monat lang im Feld halten, und der Betrieb tief in der eisigen Wildnis von Dun Morogh erfordert eine sorgfältige Vorbereitung. Er benötigt reichlich Vorräte, die an Bord von Jetsteam verstaut werden müssen, bevor er in den aktiven Dienst geht.",al={"pilot bellfiz motiv","warum jetsteam bestücken","warum braucht bellfiz vorräte"}},f0e85f28={q="Wozu dient das Stück Eberfleisch?",a="Das Eberfleisch dient als lebenswichtige Ration für Pilot Bellfiz’ bevorstehenden einmonatigen Einsatz. Der Betrieb einer schweren Belagerungsmaschine in der eisigen Kälte verbrennt viel Energie, und haltbares Fleisch, das von den örtlichen Felsebern gesammelt wird, liefert die Nahrung, die er benötigt, während er weit entfernt von freundlichen Außenposten stationiert ist.",al={"nutzen stück eberfleisch","warum eberfleisch","eberfleisch jetsteam"}},["779906a6"]={q="Warum braucht Pilot Bellfiz Euch für die Jagd?",a="Bellfiz kann die Zeit nicht für die Jagd aufbringen, da er die Wartung von Jetsteam beaufsichtigt. Der Mechanikermeister Beldin Stahlrost stimmt den Panzer in Stahlrosts Depot aktiv ab und repariert ihn, was erfordert, dass der Pilot in der Nähe bleibt und sicherstellt, dass die Maschine ordnungsgemäß für die Abreise vorbereitet ist.",al={"warum kann bellfiz nicht jagen","warum ich bellfiz","warum muss ich für bellfiz jagen"}}},fp="17,280,23.382.0,23.325.0,17.210.0,23.228.0,44.185.0,26.183.0,34.220.1,44.223.0"}
P.entries["quest:318"] = {n="Immerschimmer",s="Immerschimmer ist eine Lieferquest der Allianz, die bei Pilot Bellfiz nahe Kharanos beginnt. Der zwergische Belagerungsmaschinenpilot schickt Reisende gen Westen nach Bräuhall, um ein potentes Zwergengebräu zu holen, das von Rejold Gerstenbräu hergestellt wird. Der Schnaps dient gleichermaßen als wärmendes Getränk wie auch als hochoktaniger Notfalltreibstoff für Bellowfiz' Belagerungsmaschine.",h="Immerschimmer ist eine Lieferquest der Allianz, die bei Pilot Bellfiz nahe Kharanos beginnt.",kw={"brewnall","dun morogh","immerschimmer","dampfstrahl","kharanos","pilot bellfiz","rejold gerstenbräu"},ang={["profession:Engineering"]="Die Nutzung hochprozentiger Spirituosen als zusätzlicher Treibstoffbeschleuniger zeigt, wie Piloten wie Bellowfiz ihre Belagerungsmaschinen in rauen Umgebungen am Laufen halten.",["race:Dwarf"]="Rejold Gerstenbräus potente Spirituose repräsentiert die feurigen Extreme zwergischer Brautradition in den kalten Gipfeln von Dun Morogh.",["race:Gnome"]="Pilot Bellfiz' Gewohnheit, alltägliche Gegenstände – selbst Zwergenschnaps – zu improvisiertem Treibstoff umzufunktionieren, würde jeden Gnomen-Tüftler beeindrucken."},sec={{t="Ein potentes Gebräu",b="Die Braukunst der Zwerge ist in ganz Khaz Modan berühmt, doch die Rezepte von Rejold Gerstenbräu in Bräuhall sprengen die Grenzen herkömmlicher Gärung. Sein experimentelles Getränk, Immerschimmer, ist berüchtigt dafür, selbst die stämmigsten Zwerge von den Beinen zu hauen. Trotz seiner ungestümen Stärke wird es in der bitteren Kälte von Dun Morogh wegen seiner schieren Wärmekraft geschätzt."},{t="Treibstoff für Pilot Bellfiz",b="Belagerungspiloten finden oft unorthodoxe Verwendungsmöglichkeiten für alltägliche Dinge, und Pilot Bellfiz bildet da keine Ausnahme. Bellowfiz operiert von Stahlrosts Depot außerhalb von Kharanos aus und verlässt sich auf Immerschimmer nicht bloß als Schluck gegen die eisigen Winde, sondern auch als Zusatztreibstoff. Schüttet er den flüchtigen Alkohol direkt in die Brennkammer seiner Belagerungsmaschine Dampfstrahl, sorgt dies für einen explosiven Notfallschub, der ihn schon aus so manch brenzliger Lage befreit hat."}},faq={{q="Was ist Immerschimmer?",a="Immerschimmer ist ein außergewöhnlich starkes, experimentelles alkoholisches Gebräu, das vom zwergischen Braumeister Rejold Gerstenbräu in Bräuhall gebraut wird. Es ist berühmt für seinen feurigen Schlag und seine Fähigkeit, selbst die trinkfestesten Zwerge niederzustrecken.",al={"was ist immerschimmer","immerschimmer gebräu","welche art getränk ist immerschimmer"}},{q="Warum verlangt Pilot Bellfiz nach Immerschimmer?",a="Pilot Bellfiz nutzt Immerschimmer sowohl zum Aufwärmen gegen die Kälte von Dun Morogh als auch als leicht brennbaren Notfalltreibstoff. Wird die flüchtige Spirituose in die Brennkammer seiner Belagerungsmaschine Dampfstrahl gegossen, erzeugt sie sofortigen Schub.",al={"warum bellowfiz gebräu will","pilot bellfiz immerschimmer","warum bellowfiz es braucht"}},{q="Wo liegt Bräuhall?",a="Bräuhall liegt im Westen von Dun Morogh, direkt an der Straße westlich von Kharanos. Es schmiegt sich an die verschneiten Hügel und beherbergt einheimische Brauer wie Rejold Gerstenbräu.",al={"wo liegt brewnall","brewnall lage","brewnall finden"}},{q="Wer ist Rejold Gerstenbräu?",a="Rejold Gerstenbräu ist ein experimentierfreudiger Zwergenbrauer, der in Bräuhall ansässig ist. Er stellt die verschiedensten Getränke her – von bekömmlichen Bieren bis hin zu feurigen Gebräuen, die stark genug sind, um die Brennkammern von Maschinen anzufeuern.",al={"wer ist rejold","rejold gerstenbräu infos","brauer gerstenbräu"}},{q="Wie geht es weiter, nachdem man Rejold Gerstenbräu erreicht hat?",a="Rejold trennt sich nicht ohne Gegenleistung von seinem geschätzten Schnaps. Die Ankunft in Bräuhall führt zur Quest 'Ein Gefallen für Immerschimmer', bei der Spieler dem Brauer helfen müssen, bevor er ein Fass für Pilot Bellfiz herausrückt.",al={"folgequest nach immerschimmer","was folgt nach immerschimmer","rejold folgequest"}},{q="Kann man Immerschimmer wirklich gefahrlos trinken?",a="Laut Pilot Bellfiz streckt Immerschimmer fast jeden Zwerg nieder, der ihn probiert. Während er für Bergbewohner mit eisernem Magen technisch genießbar ist, eignet er sich durch seine extreme Entflammbarkeit ebenso gut als Treibstoff für eine Maschinenbrennkammer.",al={"kann man immerschimmer trinken","ist immerschimmer giftig","immerschimmer gefährlich"}}},fp="9,327,19.362.0,24.448.0,18.221.0,40.231.0,26.182.0,25.209.0,49.222.1,33.236.0"}
P.entries["quest:319"] = {n="Ein Gefallen für etwas Immerschimmer",s="Um sich für Pilot Bellfiz bei Stahlrosts Depot ein Fass Immerschimmer zu sichern, muss ein Abenteurer zunächst Bräuhall unter die Arme greifen. Brauer Rejold Gerstenbräu weigert sich, seinen Schnaps herauszugeben, ehe die gefährlichen Raubtiere in den nahen Schneewehen ausgedünnt wurden.",h="Um sich für Pilot Bellfiz bei Stahlrosts Depot ein Fass Immerschimmer zu sichern, muss ein Abenteurer...",kw={"bellowfiz","brewnall","dun morogh","uralter felseber","immerschimmer","eisklauenbär","rejold gerstenbräu","schneeleopard"},ang={["class:Hunter"]="Das Ausdünnen der aggressiven Raubtiere im westlichen Dun Morogh stellt die Treffsicherheit gegen die widerstandsfähigsten Winterbestien der Felsen auf die Probe.",["race:Dwarf"]="Jeder Zwerg versteht, wie wichtig es ist, wilde Bestien von einer ehrlichen Destille fernzuhalten, damit die legendären Fässer von Brewnall unberührt bleiben.",["race:Gnome"]="Die Belagerungspiloten und Tüftler bei Stahlrosts Depot warten dringend auf dieses Fass und verlassen sich auf Abenteurer, die den sturen Brauer besänftigen, damit die Vorbereitungen für Jetsteam weitergehen können."},sec={{t="Der Handel eines Brauers",b="Rejold Gerstenbräu besitzt das Fass Immerschimmer, das Pilot Bellfiz benötigt, doch er hat es keineswegs eilig, sein geschätztes Gebräu umsonst herzugeben. Statt Münzen verlangt Rejold Schutz. Die wilden Bestien des westlichen Dun Morogh – ausgehungerte Eisklauenbären, dickhäutige uralte Felseber und herumstreifende Schneeleoparden – wandern unangenehm nah an Bräuhall heran und stellen eine ständige Ablenkung sowie Gefahr für die Einheimischen dar."},{t="Ruhe für die Handwerker",b="Auch wenn Rejold schnell betont, dass kein Zwerg mit Selbstachtung vor wilden Tieren kuscht, kostet der ständige Umgang mit Raubtieren wertvolle Stunden. Das Ausdünnen der einheimischen Tierwelt verschafft den Dorfbewohnern die nötige Ruhe, um sich auf das Destillieren und Schmieden zu konzentrieren, ohne ständig ein Auge auf den Waldrand richten zu müssen."}},faq={{q="Warum möchte Rejold, dass diese Tiere getötet werden?",a="Umherstreifende Bären, Eber und Schneeleoparden kommen Bräuhall gefährlich nah. Zwar fürchten sich die Zwerge nicht vor ihnen, doch das Vertreiben vergeudet wertvolle Arbeitszeit, die man für das Brauen und Handwerk nutzen könnte.",al={"warum bären töten","warum tiere ausdünnen brewnall","rejolds aufgabe grund"}},{q="Was ist Immerschimmer?",a="Immerschimmer ist ein wirkungsstarker, hochgelobter Schnaps, der exklusiv in Bräuhall von Rejold Gerstenbräu gebraut wird. Belagerungsmaschinen-Piloten wie Pilot Bellfiz finden ihn äußerst nützlich, sowohl als Getränk als auch als flüchtiger Treibstoffzusatz.",al={"was ist immerschimmer","immerschimmer gebräu","rejold schnaps"}},{q="Wer bat ursprünglich um den Immerschimmer?",a="Pilot Bellfiz drüben bei Stahlrosts Depot hat Euch geschickt, um ihn zu besorgen, damit er sich unterwegs warm halten und den Kessel seiner eigenen Belagerungsmaschine, Jetsteam, für einen Kraftschub anheizen kann.",al={"wer schickte mich für immerschimmer","wer will immerschimmer","questreihe start"}},{q="Wo sind die Tiere zu finden?",a="Sie streifen durch die gefrorenen Felder und Felsen direkt um Bräuhall und den Eiswellensee im westlichen Dun Morogh.",al={"wo sind eisklauenbären","schneeleopard aufenthaltsort","uralter felseber aufenthaltsort"}},{q="Was geschieht nach Erledigung des Gefallens?",a="Sobald die Bestien erlegt sind, übergibt Rejold das Fass Immerschimmer, sodass Ihr es direkt zu Pilot Bellfiz bei Stahlrosts Depot zurückbringen könnt.",al={"nächste quest","nach gefallen für immerschimmer"}},{q="Sind die Dorfbewohner tatsächlich in Gefahr durch die Raubtiere?",a="Rejold beteuert zwar, dass kein Zwerg mit Selbstachtung eine Bestie im Schnee fürchtet, doch knurrende Raubtiere vor der Haustür sind eine dauerhafte Störung und Gefahr für das tägliche Schaffen.",al={"ist brewnall in gefahr","haben zwerge angst"}}},fx={["02738ac5"]={q="Welche Tiere schickt Euch Rejold Gerstenbräu jagen?",a="Rejold schickt Euch, um die wilden Raubtiere und Bestien zu dezimieren, die in den Schneewehen um Bräuhall herumstreifen: Eiskrallenbären, Ältere Felseber und Schneeleoparden. Diese einheimischen Bestien wandern gefährlich nah an die Siedlungsgrenze, knurren und schnauben draußen, während die Dorfbewohner versuchen, sich um ihre Bottiche und Werkstätten zu kümmern.",al={"rejolds ziele","welche bestien","tiere töten für evershine","welche tiere bräuhall"}},fe0fe64f={q="Warum bittet Rejold Euch, anstatt die Dorfbewohner von Bräuhall die Bestien erledigen zu lassen?",a="Die Zwerge von Bräuhall haben kaum Angst vor der örtlichen Tierwelt – kein Zwerg mit Selbstachtung würde vor einem Eber oder Schneeleoparden zurückweichen. Doch die Jagd auf umherstreifende Raubtierrudel nimmt wertvolle Zeit von ihren wahren Leidenschaften in Anspruch: Bier brauen, Handwerk und die Pflege ihrer Bottiche. Da Ihr ein rüstiger Reisender seid, der ohnehin nach einem Fass von Evershine sucht, schließt Rejold einen Handel ab, damit sein Volk in Frieden weiterarbeiten kann.",al={"warum können dorfbewohner sie nicht töten","warum ich rejold","warum braucht rejold hilfe","jäger von bräuhall"}}},fp="21,264,18.420.0,23.313.0,42.205.0,18.221.0,39.181.0,31.120.0,40.145.0,54.184.0"}
P.entries["quest:321"] = {n="Lichtgeschmiedetes Eisen",s="Lichtgeschmiedetes Eisen ist ein Bergungsauftrag der Allianz, der von Glorin Stahlbraue im Hafen von Menethil vergeben wird. Abenteurer werden ausgesandt, um das Wrack der Flying Osprey zu durchsuchen – eines elfischen Zerstörers, der seltenes heiliges Metall transportierte und während des Zweiten Krieges an der Seite der Dritten Flotte von Kul Tiras verloren ging.",h="Lichtgeschmiedetes Eisen ist ein Bergungsauftrag der Allianz, der von Glorin Stahlbraue im Hafen von Menethil...",kw={"flying osprey","glorin stahlbraue","barren","kul tiras","lichtgeschmiedetes eisen","der hafen von menethil","murloc","dritte flotte","durchnässte kiste","sumpfland"},ang={["class:Paladin"]="Aus Lichtgeschmiedetem Eisen geschmiedete Waffen sind tief auf das Heilige Licht eingestimmt, was die Bergung selbst eines einzigen verlorenen Barrens von spiritueller Bedeutung macht.",["faction:Alliance"]="Die versunkenen Schiffe vor dem Hafen von Menethil sind düstere Mahnmale des Zweiten Krieges, an dem tapfere Seeleute aus Kul Tiras und Lordaeron dem Drachenfeuer zum Opfer fielen.",["profession:Blacksmithing"]="Schmiede aller Disziplinen verehren Lichtgeschmiedetes Eisen als heiligen Gral unter den Materialien, bekannt dafür, mächtige Segnungen aufzunehmen und eine unübertroffene strukturelle Stabilität zu bewahren."},sec={{t="Eine heilige Fracht",b="Während die meisten der versunkenen Rümpfe, die die Küste des Sumpflands säumen, zur berühmten Dritten Flotte von Kul Tiras gehörten, stach ein Schiff hervor: ein elfischer Zerstörer namens Flying Osprey. Von Lordaeron kommend, suchte das Schiff Schutz in der Überzahl an der Seite der Kriegsflotte und führte eine wertvolle Fracht an Lichtgeschmiedetem Eisen mit sich. Unglücklicherweise half das Geleit von Kriegsgaleeren wenig, als die vom Drachenmalklan versklavten roten Drachen vom Himmel herabstießen, die Flotte in Brand steckten und sowohl Soldaten als auch das geweihte Metall in den Fluten versenkten."},{t="Von den Gezeiten geplündert",b="Erreicht man die zerschmetterten Überreste der Flying Osprey südlich des Hafens von Menethil, zeigt sich, dass Zeit und Meer nicht die einzigen Kräfte am Werk waren. Die durchnässte Kiste, die die Ladung barg, wurde aufgebrochen und von Klauen durchwühlt. Küstenmurlocs, stets eifrige Plünderer von Wracks, haben den Frachtraum durchkämmt und die Barren verstreut, sodass kaum eine Spur des kostbaren Erzes zurückblieb, das Glorin Stahlbraue sucht."}},faq={{q="Was ist die Flying Osprey?",a="Die Flying Osprey war ein elfischer Zerstörer, der während des Zweiten Krieges von Lordaeron aus in See stach. Sie transportierte eine Ladung seltenen Lichtgeschmiedeten Eisens und reiste zum Schutz an der Seite der Dritten Flotte von Kul Tiras, nur um zusammen mit dem Rest der Flotte von durch Orcs versklavten roten Drachen verbrannt und versenkt zu werden.",al={"flying osprey geschichte","elfischer zerstörer sumpfland","welches schiff hatte das eisen"}},{q="Wer ist Glorin Stahlbraue?",a="Glorin Stahlbraue ist ein Zwerg, der im Hafen von Menethil im Sumpfland stationiert ist. Er interessiert sich für die Bergung historischer Frachten und wertvoller Materialien aus den versunkenen Schiffen entlang der Küste, insbesondere für legendäre Metalle wie Lichtgeschmiedetes Eisen.",al={"glorin stahlbraue","zwerg in menethil","wer vergibt lichtgeschmiedetes eisen"}},{q="Was ist Lichtgeschmiedetes Eisen?",a="Lichtgeschmiedetes Eisen ist ein außergewöhnlich seltenes, geweihtes Metall, das zum Schmieden geweihter Waffen und Rüstungen verwendet wird. Es wird von Schmieden und Champions des Heiligen Lichts wegen seiner Reinheit und widerstandsfähigen spirituellen Eigenschaften geschätzt.",al={"lichtgeschmiedetes metall","was ist lichtgeschmiedetes eisen","lichtgeschmiedete barren"}},{q="Warum wurden die Schiffe im Sumpfland versenkt?",a="Während des Zweiten Krieges nutzte der Drachenmalklan der Horde die Dämonenseele, um den roten Drachenschwarm zu versklaven. Drachenreiter griffen die Dritte Flotte von Kul Tiras vor der Küste des Sumpflands an, setzten die Schiffe in Brand und schickten sie auf den Meeresgrund.",al={"wer versenkte die dritte flotte","warum schiffswracks im sumpfland","rote drachen sumpfland flotte"}},{q="Warum ist die Kiste fast leer?",a="Die durchnässte Kiste an Bord der Flying Osprey weist frische Klauenspuren von Küstenmurlocs auf. Die Kreaturen brachen sie auf, plünderten die Fracht, entkamen mit den meisten Barren und verstreuten sie entlang des sumpfigen Ufers.",al={"wo sind die barren","warum klauenspuren an der kiste","wer stahl das lichtgeschmiedete eisen"}},{q="Wo befindet sich das Wrack der Flying Osprey?",a="Das Wrack liegt in den Untiefen an der Küste direkt südlich des Hafens von Menethil am westlichen Ufer des Sumpflands, verteilt über das seichte Wasser nahe den örtlichen Murlocsiedlungen.",al={"flying osprey standort","wo ist die kiste","sumpfland schiffswrack standort"}}},fx={["915ea990"]={q="Warum will Glorin Stahlbraue Lightforge Iron?",a="Glorin Stahlbraue ist ein Priester, der versucht, das seltene Metall zu bergen, um eine Waffe gegen Morbent Fel vorzubereiten. Die versunkene Ladung der Flying Osprey bietet eine seltene Gelegenheit, Lightforge Iron zu bergen, ein kostbares elfisches Handelsgut, das seit dem Zweiten Krieg verloren ist. Indem er Euch schickt, es zu bergen, hofft er, genug verarbeitbares Metall zu sammeln, um Waffen zu schmieden, die seiner dauerhaften Legende würdig sind.",al={"warum will glorin eisen","glorin stahlbraues lightforge iron motiv","warum lightforge iron finden"}}},fp="15,276,14.542.0,22.407.1,26.291.0,24.241.0,24.206.0,40.234.0,30.223.0,51.170.0"}
P.entries["quest:322"] = {n="Gesegnete Waffe",s="Nachdem ein Abenteurer Lichtschmiedeblöcke aus dem Wrack der Flying Osprey im Sumpfland geborgen hat, wird er angewiesen, das kostbare Metall nach Sturmwind zu bringen. Dort erwartet ihn der meisterhafte Zwergenschmied Grimand Elmore, um das Rohmetall zu einem Werkzeug zu verarbeiten, das ausreicht, um dem Nekromanten Morbent Teufel entgegenzutreten.",h="Nachdem ein Abenteurer Lichtschmiedeblöcke aus dem Wrack der Flying Osprey im Sumpfland geborgen hat, wird er...",kw={"gesegnete waffe","der zwergendistrikt","glorin stahlbraue","grimand elmore","lichtgeschmiedetes eisen","loch modan","morbent teufel","sturmwind"},ang={["class:Paladin"]="Das Tragen von geweihtem Eisen, um eine Waffe gegen einen Nekromanten im Dämmerwald zu schmieden, spiegelt die Kernaufgabe der Silbernen Hand wider: dunkle Zauberei mit heiliger Wachsamkeit zu reinigen.",["faction:Alliance"]="Die Lieferung zeigt die enge Zusammenarbeit zwischen den Königreichen, indem sie eine Brücke zwischen einem Zwergenpriester im Hafen von Menethil und den Schmieden des Zwergendistrikts von Sturmwind schlägt, um den geplagten Menschen im Dämmerwald zu helfen.",["profession:Blacksmithing"]="Lichtgeschmiedetes Eisen ist ein seltenes und empfindliches Metall; einem erfahrenen Zwergenschmied wie Grimand Elmore bei der Arbeit zuzusehen, unterstreicht das außergewöhnliche Können, das erforderlich ist, um heilige Waffen zu schmieden."},sec={{t="Ein seltenes Metall kehrt zurück",b="Lichtgeschmiedetes Eisen ist kein handelsübliches Metall, das man an gewöhnlichen Marktständen findet. Es ist bekannt für seine Resonanz gegenüber abscheulichen und unheiligen Entitäten und erfordert einen Schmied, der seine Härte und Eigenheiten versteht. Nachdem die Fracht aus dem Wrack der Flying Osprey vor der Küste des Sumpflands geborgen wurde, packte Glorin Stahlbraue die wiedergewonnenen Blöcke in eine stabile Kiste, da er nur einen Handwerker in den südlichen Königreichen kannte, der für die Verarbeitung eines so außergewöhnlichen Materials geeignet war: den Waffenmeister Grimand Elmore."},{t="Die Schmiede im Zwergendistrikt",b="Inmitten des Rußes und Klapperns des Zwergendistrikts in Sturmwind unterhält Grimand Elmore einen der besten Ambosse der Stadt. Als ihm die geborgene Fracht präsentiert wird, bemerkt Elmore, dass Jahre vergangen sind, seit er das letzte Mal Lichtgeschmiedetes Eisen gehämmert hat. Fasziniert von dem heldenhaften Auftrag und begierig darauf, einen Schlag gegen den Nekromanten Morbent Teufel zu führen, erklärt sich der erfahrene Handwerker bereit, seinen Hammer für diese Sache einzusetzen."}},faq={{q="Was ist der Zweck dieser Lieferung?",a="Die Kiste enthält geborgenes Lichtgeschmiedetes Eisen aus dem Wrack der Flying Osprey im Sumpfland. Glorin Stahlbraue sendet es an Grimand Elmore, damit der geschickte Schmied das geweihte Metall zu einer Waffe formen kann, die den Nekromanten Morbent Teufel bekämpfen kann.",al={"warum blöcke nach stormwind bringen","zweck der gesegneten waffe","wofür ist die kiste mit lichtschmiedeblöcken"}},{q="Wer ist Grimand Elmore?",a="Grimand Elmore ist ein angesehener Zwergen-Waffenschmied, der im Zwergendistrikt von Sturmwind arbeitet. Er gehört zu den wenigen Handwerkern mit der Ausbildung und dem Können, die notwendig sind, um spezialisierte Metalle wie Lichtgeschmiedetes Eisen zu schmieden.",al={"hintergrund zu grimand elmore","wer ist der schmied im zwergendistrikt"}},{q="Warum ist Lichtgeschmiedetes Eisen so wichtig gegen Morbent Teufel?",a="Morbent Teufel ist ein schwer fassbarer und mächtiger Nekromant, der durch dunkle Magie geschützt wird. Gewöhnliche Waffen haben Schwierigkeiten, seine unheiligen Abwehrkräfte zu durchdringen, weshalb Waffen aus geheiligtem Lichtgeschmiedeten Eisen notwendig sind, um seinen Schutz zu durchbrechen und ihn verwundbar zu machen.",al={"warum lichtgeschmiedetes eisen","wie schadet lichtgeschmiedetes eisen morbent teufel"}},{q="Wohin schickt Euch Glorin Stahlbraue?",a="Glorin Stahlbraue schickt Euch vom Hafen von Menethil im Sumpfland zum Zwergendistrikt von Sturmwind, wo Grimand Elmore seine Schmiede hat.",al={"wohin muss ich für die gesegnete waffe","wo befindet sich grimand elmore"}},{q="Hat Grimand Elmore schon früher mit Lichtgeschmiedetem Eisen gearbeitet?",a="Ja. Bei der Untersuchung des Metalls bemerkt Grimand, dass es Jahre her ist, seit er das letzte Mal mit Lichtgeschmiedetem Eisen gearbeitet hat, und er begrüßt die Gelegenheit, sein Handwerk wieder an einem so geschichtsträchtigen Material auszuüben.",al={"hat grimand schon einmal lichtgeschmiedetes eisen geschmiedet","schmiede-erfahrung von elmore"}},{q="Was muss geschehen, bevor die Waffe fertiggestellt werden kann?",a="Grimand erklärt sich bereit, das geborgene Lichtgeschmiedete Eisen zu Morbents Bann zu schmieden. Sobald er fertig ist, muss die Waffe zu Sven Yorgen im Dämmerwald gebracht werden.",al={"was kommt nach der gesegneten waffe","wird die waffe sofort geschmiedet"}}},fx={affa6c43={q="Warum will Glorin Stahlbraue, dass diese Lieferung erfolgt?",a="Glorin weiß, dass gewöhnlicher Stahl die dunklen Schutzmechanismen, die Morbent Fel im Dämmerwald bewachen, nicht durchbrechen kann. Nachdem er das Lightforge Iron geborgen hat, das Ihr vom Wrack der Flying Osprey im Sumpfland gesichert habt, erkennt er Euren Feldzug gegen den Nekromanten an und weist Euch an einen geschickten Schmied, der eine Waffe schmieden kann, die wahrhaftig in der Lage ist, dem Zauberer der Geißel zu schaden.",al={"glorin stahlbraues motiv","warum hilft glorin","warum barren an grimand senden"}}},fp="11,302,20.489.0,28.410.0,37.257.0,22.219.0,56.244.0,37.144.0,54.194.0,51.149.0"}
P.entries["quest:3221"] = {n="Sprecht mit Renferrel",s="Sprecht mit Renferrel ist eine kurze Besorgung innerhalb des Grabmals im Silberwald. Hochexekutor Hadrec schickt Euch zurück zum örtlichen Forscher der Königlichen Apothekervereinigung, um Erkenntnisse über verdorbene Wolfsherzen zu besprechen.",h="Sprecht mit Renferrel ist eine kurze Besorgung innerhalb des Grabmals im Silberwald.",kw={"hadrec","renferrel","königliche apothekervereinigung","das grabmal","silberwald","wolfsherzen"},ang={["faction:Horde"]="Während die Horde Stützpunkte in ganz Lordaeron errichtet, ist das Verständnis der die örtlichen Bestien befallenden Verderbnis unerlässlich, um die Wildnis zu sichern.",["race:Undead"]="Die Königliche Apothekervereinigung arbeitet eng mit dem militärischen Kommando im Grabmal zusammen und stellt sicher, dass jede biologische Anomalie im Silberwald erforscht wird, um den Zielen der Dunklen Fürstin zu dienen."},sec={{t="Vorladung durch die Vereinigung",b="Nachdem Ihr den Todespirschern im gesamten Silberwald beigestanden habt, überbringt Hochexekutor Hadrec eine dringende Nachricht von Apotheker Renferrel. Renferrel hat Zeit damit verbracht, die von der einheimischen Tierwelt gesammelten verfärbten Wolfsherzen zu analysieren, und verlangt unverzüglich Eure Anwesenheit."},{t="Alchemistische Kuriositäten",b="Apotheker Renferrel dient der Königlichen Apothekervereinigung von seinem Labor in der Krypta des Grabmals aus. Seine fortlaufende Arbeit untersucht, wie dunkle Magie und Seuchen die Bestien des Silberwalds verändern, und schlägt eine Brücke zwischen militärischer Aufklärung an vorderster Front und chemischer Forschung."}},faq={{q="Wo befindet sich Apotheker Renferrel?",a="Apotheker Renferrel befindet sich in der Krypta des Grabmals im zentralen Silberwald, wo er nahe seiner Alchemieausrüstung nur wenige Schritte von Hochexekutor Hadrec entfernt steht.",al={"renferrel aufenthaltsort","wo ist renferrel","renferrel finden"}},{q="Warum möchte Apotheker Renferrel mit mir sprechen?",a="Renferrel hat verfärbte Wolfsherzen analysiert, die von einheimischen Wölfen des Silberwalds gesammelt wurden, und Auffälligkeiten in ihrer Verderbnis entdeckt, die weitere Nachforschungen und eine Mitteilung an Unterstadt erfordern.",al={"warum will renferrel mich sprechen","renferrel wolfsherzen"}},{q="Wer schickt Euch zu Renferrel?",a="Hochexekutor Hadrec, der militärische Befehlshaber der Verlassenen im Grabmal, überbringt Euch Renferrels Vorladung, sobald Ihr von Eurer Unterstützung für seine Todespirscher Bericht erstattet.",al={"wer gibt sprecht mit renferrel","questgeber"}},{q="Was folgt auf dieses Gespräch?",a="Das Gespräch mit Renferrel führt direkt zu Aufgaben, die dazu beitragen, die regionale alchemistische Forschung des Grabmals mit hochrangigen Persönlichkeiten wie Apothekerin Zinge in Unterstadt zu verknüpfen.",al={"folgequest nach sprecht mit renferrel","renferrel folgeaufgabe"}}},fx={["1f8d2902"]={q="Warum schickt Euch Hochexekutor Hadrec zu Renferrel?",a="Hochexekutor Hadrec übermittelt lediglich eine formelle Vorladung im Namen der Königlichen Apothekervereinigung. Während Ihr an der Front im Silberwald für The Deathstalkers Aufklärung betrieben habt, bat Apotheker Renferrel um Eure Rückkehr, um die Wolfsherzen zu besprechen, die Ihr zuvor für seine alchemistischen Forschungen gesammelt habt. Hadrec stellt sicher, dass wichtige Geschäfte zwischen dem Militärposten und der Vereinigung reibungslos weiterlaufen.",al={"hadrecs motiv","warum will hadrec, dass ich mit renferrel spreche","warum mich zu apotheker renferrel schicken"}}},fp="20,221,24.273.0,22.261.0,38.169.0,52.211.0,27.159.0,31.172.0"}
P.entries["quest:323"] = {n="Bewährungsprobe",s="Bewährungsprobe ist ein entscheidender Schritt in Sven Yorgens Rachefeldzug im westlichen Dämmerwald. Bevor der trauernde Einsiedler einem Abenteurer gestattet, dem Nekromanten Morbent Teufel direkt gegenüberzutreten, verlangt er den Beweis, dass dieser die untoten Legionen bezwingen kann, die den Friedhof von Rabenflucht heimsuchen.",h="Bewährungsprobe ist ein entscheidender Schritt in Sven Yorgens Rachefeldzug im westlichen Dämmerwald.",kw={"dark riders","dämmerwald","das verlassene gut","morbent teufel","bewährungsprobe","friedhof von rabenflucht","skeletal healer","skeletal raider","skeletal warder","sven yorgen"},ang={["class:Paladin"]="Den Friedhof von Rabenflucht von Morbent Teufels rastlosen Toten zu säubern, ist ein heiliges Werk, das die ungehörten Schreie der Verstorbenen des Dämmerwalds mit der Gerechtigkeit des Lichts beantwortet.",["class:Priest"]="Die Entweihung der Grüfte von Rabenflucht durch finstere Rituale verlangt nach einer spirituellen Reinigung, um den Wächtern und Heilern ein Ende zu setzen, die Leben und Tod verhöhnen.",["faction:Alliance"]="Der westliche Dämmerwald ist ohne regelmäßige Patrouillen aus Sturmwind der Gesetzlosigkeit anheimgefallen, sodass verzweifelte Grenzer wie Sven vollkommen auf reisende Recken angewiesen sind, um die untote Geißel zurückzuschlagen."},sec={{t="Die Prüfung eines verbitterten Einsiedlers",b="Sven Yorgen verbirgt sich in einem abgelegenen Lager nördlich der heulenden Wälder, verzehrt von Trauer und Zorn über die Ermordung seiner Familie. Er hat herausgefunden, dass die schattenhaften Dark Riders, die sein Gehöft dem Erdboden gleichgemacht haben, mit einem finsteren Nekromanten namens Morbent Teufel verbündet waren. Obwohl Sven nach Vergeltung dürstet, ist er nicht leichtsinnig genug, einen unerprobten Rekruten geradewegs in Fels Fänge zu schicken. Er verlangt den Beweis purer Kampfkunst gegen die skelettierten Streitkräfte, die den Friedhof von Rabenflucht besetzt halten."},{t="Die Grüfte von Rabenflucht",b="Um Sven zufriedenzustellen, müssen Abenteurer tief in die Nekropole von Rabenflucht südlich vom verlassenen Gut vordringen. Das Mausoleum und die umliegenden Ländereien wimmeln von rastlosen Leichen, die durch Fels üble Magie gebunden sind: Schwertschwingende Skeletal Raiders patrouillieren zwischen den Grabsteinen, während Skeletal Warders und Healers die finstereren Kammern unter der Erde bewachen. Diese Vorhut zu beseitigen, ist eine blutige Plackerei – besonders da Schrecken wie das rachsüchtige Phantom Mor'Ladim die Pfade des Friedhofs durchstreifen."},{t="Der Weg zum Nekromanten",b="Das Überleben in den knochenübersäten Katakomben überzeugt Sven davon, dass sein Verbündeter mehr als nur leeren Mut besitzt. Fels niedere Diener zu besiegen, ist jedoch nur das Vorspiel. Morbent Teufel verfügt über dunkle Schutzzauber, die ihn für gewöhnliche Waffen nahezu unantastbar machen, was Sven dazu zwingt, nach größerer Weisheit und uralten Relikten zu suchen, bevor die letzte Konfrontation beginnen kann."}},faq={{q="Warum lässt Sven mich gegen Skelette kämpfen, bevor ich Morbent Teufel entgegentrete?",a="Sven weiß, dass Morbent Teufel ein tödlicher Nekromant ist, der mit den mysteriösen Dark Riders im Bunde steht. Er weigert sich, einen Verbündeten in den sinnlosen Tod zu schicken, solange dieser nicht die Ausdauer und das taktische Geschick bewiesen hat, die nötig sind, um eine ganze Vorhut untoter Diener niederzustrecken.",al={"warum bewährungsprobe","warum sven skelette töten lässt","sven prüfung"}},{q="Wo sind die Skeletal Warders und Healers zu finden?",a="Während Skeletal Raiders das offene Friedhofsgelände südlich vom verlassenen Gut durchstreifen, halten sich Skeletal Healers und Warders vor allem im Inneren und in unmittelbarer Nähe des großen Mausoleums und der Grufttunnel westlich des Friedhofszentrums auf.",al={"wo sind warder","wo sind skeletal healer","skeletal warder finden"}},{q="Wer ist Mor'Ladim und warum sollte man sich hier vor ihm in Acht nehmen?",a="Mor'Ladim ist ein mächtiger, tragischer untoter Ritter, der die Wege auf dem Friedhof von Rabenflucht durchstreift. Er ist weitaus stärker als die gewöhnlichen Skelette rund um die Grüfte und wird unvorsichtige Abenteurer rasch niederstrecken.",al={"morladim gefahr","wer ist mor'ladim","wandernder elite rabenflucht"}},{q="Wie ist Morbent Teufel mit den Dark Riders verbunden?",a="Sven fand heraus, dass Morbent Teufel mit den verhüllten Dark Riders verbündet war, die seine Frau und seine Kinder abschlachteten. Während die Reiter wieder in den Schatten verschwanden, verweilt Fel weiterhin im Dämmerwald und setzt seine finstere Nekromantie fort.",al={"verbindung morbent teufel dark riders","warum dark riders und fel","mörder von svens familie"}},{q="Was geschieht nach dem Abschluss dieser Quest?",a="Sobald Ihr Euer kriegerisches Können unter Beweis gestellt habt, erkennt Sven Eure Stärke an, erklärt jedoch, dass Morbent Teufel nicht allein durch rohe Gewalt getötet werden kann. Er weist Euch an, den Rat von Bischof Heller in Sturmwinds Kathedrale des Lichts einzuholen, um einen Weg zu finden, dem Nekromanten seinen unheiligen Schutz zu entreißen.",al={"folgequest nach bewährungsprobe","was tun nach den skeletten"}},{q="Wo befindet sich Sven Yorgens Lager?",a="Sven unterhält ein verstecktes Lager in den Hügeln am äußersten Nordwestrand des Dämmerwalds, sicher verborgen nördlich von Rabenflucht und westlich der Straße, die nach Westfall führt.",al={"wo ist sven","svens lager standort"}}},fx={["865aa68b"]={q="Wer sind die skelettierten Diener auf Raven Hill?",a="Die skelettierten Plünderer, Heiler und Wächter, die den Friedhof von Rabenflucht heimsuchen, sind die wiederbelebten Toten, die der Nekromant Morbent Fel erweckt hat. Aus den geschändeten Gräbern im Dämmerwald stammend, bilden diese ruhelosen Toten nun ein unheiliges Bollwerk, das die Friedhofskrypten bewacht und den dunklen Willen ihres Meisters ausführt.",al={"skelettierte plünderer raven hill","wer sind die skelette raven hill","morbent fels diener"}},fbdf818d={q="Warum braucht Sven Yorgen Euch, um gegen Morbent Fels Diener zu kämpfen?",a="Sven Yorgen ist ein isolierter Einsiedler, der allein in der verwunschenen Wildnis des Dämmerwalds überlebt. Von Trauer zerrissen und angetrieben vom Hass auf die Dunklen Reiter, die seine Familie abgeschlachtet haben, fehlen ihm die Kraft und die Ressourcen, um Morbent Fels untote Armee allein anzugreifen. Er wendet sich an fähige Abenteurer, die bereit sind, den Friedhof von Rabenflucht zu trotzen, um seine Rache zu üben.",al={"warum braucht sven hilfe","warum kämpft sven nicht","warum mich fragen sven"}}},fp="18,282,22.482.0,21.463.0,27.362.1,64.250.0,49.239.0,57.200.0,48.220.0,41.288.1,36.171.0"}
P.entries["quest:324"] = {n="Die verlorenen Blöcke",s="Die verlorenen Blöcke ist eine Allianz-Aufgabe im Sumpfland, um geweihtes Metall aus einem Schiffswrack zu bergen. Nachdem Reisende nur einen einzigen Barren in einer versunkenen Kiste gefunden haben, müssen sie die einheimischen Murlocs der Bluegill jagen, die die restliche Ladung geplündert haben.",h="Die verlorenen Blöcke ist eine Allianz-Aufgabe im Sumpfland, um geweihtes Metall aus einem Schiffswrack zu...",kw={"bluegill","flying osprey","glorin stahlbraue","barren","lichtgeschmiedetes eisen","murloc","durchnässte kiste","sumpfland"},ang={["class:Paladin"]="Die Rückforderung von lichtgeschmiedetem Eisen von primitiven Murlocs stellt sicher, dass heilige Materialien erhalten bleiben, um geweihte Waffen zu fertigen, die würdig sind, für das Licht zu streiten.",["profession:Blacksmithing"]="Jeder Metallarbeiter kennt die Tragödie, wenn erstklassiges Material wie lichtgeschmiedetes Eisen als Kuriosität in einem Murlocnest an der Küste endet, anstatt auf einem Amboss.",["race:Dwarf"]="Verlorenes meisterhaftes Erz zu bergen und es in die Hände eines Zwergenpriesters wie Glorin Stahlbraue zu legen, ehrt die lange Tradition zwergischer Handwerkskunst und Rückeroberer."},sec={{t="Ein geplündertes Schiffswrack",b="Vor den nebligen Küsten des Sumpflands liegt das zerschellte Wrack der Flying Osprey. Ausgesandt, um wertvolles lichtgeschmiedetes Eisen für den Zwergenpriester Glorin Stahlbraue zu beschaffen, stellten Suchende fest, dass die vollgesogene Kiste im Frachtraum fast leer war. Die unersättlichen einheimischen Murlocs der Bluegill hatten das restliche Schiff bereits geplündert und die glänzenden Blöcke an sich genommen."},{t="Die Rückholung des heiligen Metalls",b="Lichtgeschmiedetes Eisen ist kein gewöhnliches Erz; es ist ein seltenes, besonderes Metall, das auf heiliges Schmiedehandwerk abgestimmt ist. Es in Lagern der Murlocs verrotten zu lassen, ist für einen Zwerg des Lichts undenkbar. Indem sie die Bluegillräuber jagen, die das seichte Wasser nahe dem zerborstenen Rumpf belagern, entreißen Abenteurer ihnen die verstreuten Barren, damit Glorin Stahlbraue das Eisen zu einer Waffe schmieden lassen kann."}},faq={{q="Welches Schiff transportierte das lichtgeschmiedete Eisen?",a="Die Fracht traf an Bord der Flying Osprey ein, einem unglückseligen Schiff, das vor der Küste des Sumpflands sein Ende fand. Seine zerbrochenen Balken liegen nun teilweise im seichten Wasser versunken.",al={"welches schiff","flying osprey","schiffswrack name"}},{q="Warum befanden sich die Blöcke nicht in der Kiste?",a="Nur ein einziger Barren verblieb verschlossen in der durchnässten Kiste. Die Murlocs der Bluegill an der Küste waren bereits in das versunkene Wrack eingedrungen und hatten den Rest der Fracht geplündert, um sie unter ihren Küstenräubern zu verteilen.",al={"wo sind die barren","warum haben murlocs eisen","kiste leer"}},{q="Wer ist Glorin Stahlbraue?",a="Glorin Stahlbraue ist ein Zwergenpriester der Kirche des Heiligen Lichts, der in der Tiefenwassertaverne im Hafen von Menethil anzutreffen ist. Als Kollege von Bischof Heller sucht er nach lichtgeschmiedetem Eisen, damit eine Waffe gegen den Nekromanten Morbent Teufel geschmiedet werden kann.",al={"glorin","wer ist glorin stahlbraue","questgeber"}},{q="Was ist das Besondere an lichtgeschmiedetem Eisen?",a="Lichtgeschmiedetes Eisen ist ein seltenes, geweihtes Metall, das für heilige Verzauberungen und Schmiedearbeiten außergewöhnlich empfänglich ist. Es wird von Kunsthandwerkern geschätzt, die auf das Heilige Licht ausgerichtete Rüstungen und Waffen herstellen.",al={"lore lichtgeschmiedetes eisen","was ist lichtgeschmiedetes eisen","warum ist das eisen wichtig"}},{q="Welche Murlocs haben das Eisen entwendet?",a="Der Stamm der Bluegill, insbesondere die Murlocräuber, die in den Untiefen und an den Stränden rund um das Wrack der Flying Osprey lauern, brachten die fehlenden Barren in ihren Besitz.",al={"wer stahl die barren","welcher stamm","bluegillräuber"}},{q="Wie geht es nach der Rückgabe der Blöcke weiter?",a="Sobald Glorin Stahlbraue alle Barren erhalten hat, packt er das geweihte Metall in eine Kiste und schickt Euch zum Waffenschmied Grimand Elmore in Sturmwind, um es schmieden zu lassen, was in Gesegnete Waffe fortgeführt wird.",al={"nächste quest","was tut glorin","quest gesegnete waffe"}}},fp="15,236,21.371.0,27.370.0,38.180.0,37.216.0,24.239.0,38.170.0,28.154.0,43.204.1"}
P.entries["quest:325"] = {n="Bewaffnet und bereit",s="Armed and Ready markiert den Höhepunkt des Schmiedens einer Waffe, die speziell dafür geschaffen wurde, die unheiligen Schutzzauber des Nekromanten Morbent Fel zu brechen. Nachdem Grimand Elmores Handwerkskunst und ein heiliger Segen erlangt wurden, trägt The Adventurer Morbents Bann über den Fluss zurück zum rachsüchtigen Sven Yorgen im Dämmerwald.",h="Armed and Ready markiert den Höhepunkt des Schmiedens einer Waffe, die speziell dafür geschaffen wurde, die...",kw={"armed and ready","dämmerwald","grimand elmore","morbent fel","morbents bann","raven hill","sturmwind","sven yorgen"},ang={["class:Paladin"]="Die Kombination aus feinem Zwergenstahl und heiliger Weihe spiegelt die Tradition der Paladine wider, kriegerische Waffen mit göttlichem Licht zu erfüllen, um die Schutzbannungen der Untoten zu zerschmettern.",["faction:Alliance"]="Die Abstimmung zwischen Handwerkern in Sturmwind und Überlebenden an vorderster Front im Dämmerwald verdeutlicht, wie die Allianz auf das Fachwissen ihrer Hauptstadt zurückgreifen muss, um um sich greifende Plagen zu läutern.",["profession:Blacksmithing"]="Grimand Elmores Handwerkskunst zeigt, wie meisterhafte Schmiedekunst mit göttlichen Riten verbunden werden kann, um spezialisierte Bannwaffen gegen übernatürliche Bedrohungen zu fertigen."},sec={{t="Eine Waffe geschmiedet",b="Morbent Fels Griff nach dem Friedhof von Raven Hill schien unzerbrechlich. Konventioneller Stahl zersplitterte oder prallte harmlos an den finsteren Schutzbannungen ab, die den Nekromanten umhüllten. Um eine solch abscheuliche Magie zu überwinden, bedurfte es eines spezialisierten Artefakts: Morbents Bann. Nachdem das Metall von Grimand Elmore im Zwergendistrikt von Sturmwind geformt und mit heiliger Macht gebührend geweiht wurde, ist das schutzbrechende Relikt nun endlich vollendet und bereit, Fels Verbindung zum Unleben zu trennen."},{t="Rückkehr zu The Hermit",b="Morbents Bann zurück in den Dämmerwald zu tragen, schenkt Sven Yorgen Hoffnung, der mitansehen musste, wie seine Familie und sein Hof der vordringenden Dunkelheit zum Opfer fielen. In seinem einsamen Lager nahe der Westgrenze des Waldes stationiert, erkennt Sven sofort das Feuer in den Augen des Reisenden und die göttliche Handwerkskunst der Waffe. Da das schutzbrechende Relikt überbracht ist, ist der Boden für einen direkten Schlag gegen den Herrn von Raven Hill bereitet."}},faq={{q="Was ist Morbents Bann?",a="Morbents Bann ist eine speziell geschmiedete und geweihte Waffe, die geschaffen wurde, um die unüberwindlichen magischen Schutzbannungen zu durchdringen, die den Nekromanten Morbent Fel in Raven Hill umgeben.",al={"morbents bann","was ist die waffe","morbents bann schwert"}},{q="Wer stellte die Waffe her?",a="Grimand Elmore, ein erfahrener Schmied, der im Zwergendistrikt von Sturmwind ansässig ist, fertigte das schutzbrechende Relikt, bevor es einen heiligen Segen erhielt.",al={"wer stellte morbents bann her","rolle von grimand elmore"}},{q="Wo liefere ich Morbents Bann ab?",a="Ihr müsst die Waffe zu Sven Yorgen bringen, der sich in einem Lager im westlichen Dämmerwald unweit der Grenze zu Westfall verbirgt.",al={"wo ist sven","sven yorgen aufenthaltsort","abgabeort"}},{q="Warum kann Sven Yorgen Morbent Fel nicht selbst bekämpfen?",a="Sven Yorgen wurde aus seiner Heimat vertrieben und verlor seine Familie sowie seine Gefährten an die finsteren Mächte, die den Wald heimsuchen. Isoliert und gejagt verlässt er sich auf fähige Champions der Allianz, um die Gefallenen zu rächen.",al={"warum kaempft sven nicht","hintergrundgeschichte von sven yorgen"}},{q="Was geschieht nach dem Abschluss von Armed and Ready?",a="Nachdem Sven Yorgen die gesegnete Waffe erhalten hat, beauftragt er Euch damit, direkt zum Friedhof von Rabenflucht aufzubrechen, um Euch Morbent Fel zu stellen und ihn niederzustrecken.",al={"was kommt als naechstes","folgequest nach armed and ready"}},{q="Welches ist der schnellste Weg zurück zu Sven's Camp?",a="Von Späherkuppe in Westfall aus nach Osten über den Fluss zu reisen, bietet oft einen weitaus kürzeren und sichereren Weg zu Sven's Camp, als westwärts durch die Schrecken von Dunkelhain zu ziehen.",al={"schnellster weg zu sven","wie man schnell zu sven gelangt"}}},fx={["4a0f4d98"]={q="Warum will Grimand Elmore, dass Morbents Bann an Sven geliefert wird?",a="Grimand Elmore ist ein Meisterschmied aus Sturmwind, der die Aufgabe übernommen hat, eine Waffe zu schmieden, die dunkle Magie durchdringen kann. Nachdem er Morbents Bann fertiggestellt hat, schickt er Euch eifrig zurück in den Dämmerwald, damit die Waffe ihrem beabsichtigten Zweck zugeführt werden kann. Er wünscht Euch den Sieg gegen den Nekromanten und freut sich darauf, Eure Geschichte vom Triumph zu hören.",al={"grimand elmores motiv","warum hilft grimand","warum sven grimand helfen"}},["2182c2f5"]={q="Warum benötigt Grimand Elmore Euch, um die Waffe zu überbringen, anstatt sie selbst auszuliefern?",a="Grimand ist ein Schmied, der im Der Zwergendistrikt in Sturmwind arbeitet, kein umherziehender Abenteurer oder Kurier. Ihr habt ihm die Materialien und die düsteren Neuigkeiten aus dem Dämmerwald gebracht, und da Ihr die Person seid, die sich gemeinsam mit Sven Yorgen dem Unhold stellen wird, ist es an Euch, die geweihte Waffe zurück zum Schlachtfeld zu bringen.",al={"warum ich armed and ready","warum geht grimand nicht in den dämmerwald","warum spieler zu sven schicken"}}},fp="15,305,15.453.0,20.429.1,23.163.0,23.160.0,34.134.0,48.201.0,46.146.1,47.182.0"}
P.entries["quest:3261"] = {n="Jorn Himmelsdeuter",s="Jorn Himmelsdeuter ist eine Reisequest der Horde, die erfahrene Jäger vom Wegekreuz aus nach Süden durch das Brachland nach Camp Taurajo führt. Nachdem sie für Sergra Dunkeldorn ihr Fährtenlesegeschick an den einheimischen Raptoren bewiesen haben, werden die Jäger entsandt, um unter der Leitung des erfahrenen Tauren-Fährtenlesers Jorn Himmelsdeuter tiefere geistige und körperliche Führung zu suchen.",h="Jorn Himmelsdeuter ist eine Reisequest der Horde, die erfahrene Jäger vom Wegekreuz aus nach Süden durch das...",kw={"camp taurajo","der weg des jägers","jorn himmelsdeuter","sensenklauen","sergra dunkeldorn","brachland","das wegekreuz"},ang={["class:Hunter"]="Diese Quest macht Euch direkt mit Jorn Himmelsdeuter bekannt, der Eure Fähigkeit auf die Probe stellt, die legendären Spitzenprädatoren der zentralen und südlichen Ebenen zu überlisten und zu bezwingen.",["faction:Horde"]="Als Verbindung zwischen dem Wegekreuz und Camp Taurajo führt dieser Übergang die Streitkräfte der Horde tiefer in das umkämpfte südliche Gebiet des Brachlands.",["race:Tauren"]="Für Tauren, die nach Süden in Richtung Camp Taurajo zurückkehren, verbindet diese Reise die Jagdkunst der Stämme wieder mit der spirituellen Wacht über die Wildnis des Brachlands."},sec={{t="Übergabe des Mantels",b="Nach der Jagd auf die gerissenen Sonnenschuppen- und Sensenklauenraptoren, die die nördliche Savanne durchstreifen, verdient sich ein Abenteurer den Respekt von Sergra Dunkeldorn im Wegekreuz. Wohl wissend, dass rohes kriegerisches Können letztlich mit einem tieferen Verständnis für die großen Bestien des Landes einhergehen muss, erklärt Sergra ihre Unterweisung für beendet und schickt den Jäger nach Süden."},{t="Der Weg nach Taurajo",b="Folgt man der langen Goldstraße nach Süden, führt der Weg durch zunehmend zerklüftete Ebenen in Richtung Camp Taurajo, einer wichtigen Taurensiedlung nahe der südlichen Wildnis. Dort wartet Jorn Himmelsdeuter, ein erfahrener alter Fährtenleser, der bereit ist, Jäger darin zu unterweisen, wie man schwer fassbare, legendäre Beute im Brachland aufspürt."}},faq={{q="Wer schickt mich zu Jorn Himmelsdeuter?",a="Sergra Dunkeldorn, die im Wegekreuz stationierte Raptorjägerin, schickt Euch zu ihm, nachdem Ihr Euer Fährtenlese- und Jagdgeschick an den einheimischen Sensenklauen bewiesen habt.",al={"wer gibt jorn himmelsdeuter","wer startet jorn himmelsdeuter","sergra dunkeldorn quest"}},{q="Wo befindet sich Jorn Himmelsdeuter?",a="Jorn Himmelsdeuter ist in Camp Taurajo anzutreffen, das weit im Süden an der Hauptstraße liegt, die durch das Brachland verläuft.",al={"wo ist jorn himmelsdeuter","jorn himmelsdeuter standort","jorn himmelsdeuter finden"}},{q="Was passiert, nachdem man Jorn Himmelsdeuter erreicht hat?",a="Sobald Ihr Euch bei ihm meldet, heißt Jorn Euch willkommen, den Weg des Jägers zu beschreiten, und weist Euch an, schwer fassbare Bestien im Südlichen Brachland aufzuspüren und zu jagen, beginnend mit dem legendären Raptor Ishamuhale.",al={"was lehrt jorn","jorn himmelsdeuter folgequest","nächste quest nach jorn himmelsdeuter"}},{q="Muss ich die Jägerklasse spielen, um diese Quest zu machen?",a="Nein. Obwohl sich die Geschichte darum dreht, die Bräuche eines Fährtenlesers der Ebenen zu erlernen und den Weg des Jägers zu beschreiten, kann jeder Horde-Abenteurer, der Sergra Dunkeldorns Raptor-Aufgaben abschließt, sie annehmen.",al={"nur für jäger","klassenanforderung jorn himmelsdeuter"}},{q="Warum unterrichtet Sergra einen nicht mehr selbst?",a="Sergra Dunkeldorn konzentriert ihre Arbeit auf die nördlichen Raptornester nahe dem Wegekreuz. Sobald ein Abenteurer diese Jagden meistert, verweist sie ihn nach Süden an Jorn Himmelsdeuter, der tiefere Expeditionen zum südlichen Wild leitet.",al={"warum schickt sergra einen weg","sergras unterweisung beendet"}},{q="Was ist Camp Taurajo?",a="Camp Taurajo ist ein Taurenlager im Südlichen Brachland. Es dient als Jagdposten, Handelsknotenpunkt und kulturelle Raststätte für Reisende, die zwischen den nördlichen Ebenen und Mulgore oder Tausend Nadeln unterwegs sind.",al={"über camp taurajo","was ist taurajo"}}},fp="12,319,18.340.0,19.288.0,29.162.0,30.116.0,41.201.0,48.193.0,42.218.0,21.212.0"}
P.entries["quest:3281"] = {n="Gestohlenes Silber",s="Gestohlenes Silber ist ein Horde-Auftrag von Gazrog im Wegekreuz, um ein von Raptoren stibitztes Versteck mit Soldmünzen wiederzubeschaffen. Gerüchten über deren verblüffende Schläue folgend, spüren Reisende das verschwundene Geld tief in den Raptorgründen südlich von Ratschet auf. Die Bergung der Schatulle stellt sicher, dass die Garnison im Wegekreuz ihren Sold tatsächlich erhält.",h="Gestohlenes Silber ist ein Horde-Auftrag von Gazrog im Wegekreuz, um ein von Raptoren stibitztes Versteck mit...",kw={"brachland","das wegekreuz","gazrog","sold","raptorgründe","raptorendiebe","ratschet","gestohlenes silber"},ang={["class:Hunter"]="Das Verhalten der Raptoren im Brachland widerspricht typischen Bestienmustern; sie zeigen ein komplexes soziales Nistverhalten und eine ungewöhnliche Vorliebe für künstliche, glänzende Fracht.",["faction:Horde"]="Das Wegekreuz ist das logistische Rückgrat Kalimdors für die Horde; seine Wachen bezahlt und versorgt zu halten, ist unerlässlich, um die Kontrolle über das Grenzland zu wahren."},sec={{t="Ein bestialischer Raubzug",b="Das Wegekreuz dient als zentraler Knotenpunkt des Brachlands und verbindet Orgrimmar, Mulgore und Ratschet. Die Ordnung in dieser weiten Savanne aufrechtzuerhalten, erfordert aufmerksame Wachen – und Wachen verlangen regelmäßigen Sold. Als Raptoren die Soldlieferung überfielen, sann Gazrog zunächst auf Rache an den Bestien. Doch das Töten des Rudels gleicht die Hauptbücher der Siedlung nicht aus, was die Horde dazu zwingt zu untersuchen, wie und warum einfache Tiere schwere Kisten voller Münzen wegschleppten."},{t="Die Raptorgründe",b="Späher machten ein dichtes Nest von Raptoren ausfindig, eingebettet zwischen zwei zerklüfteten Gipfeln südlich von Ratschet und nordwestlich der Feste Northwatch. Die Kreaturen hatten die intakte Schatulle direkt in ihr Nistgebiet gezerrt und verteidigten sie an der Seite ihrer Eier und frischer Beute. Gazrog muss zähneknirschend einräumen, dass Geschichten über die Intelligenz und das Hortungsverhalten von Raptoren überraschend zutreffend sind, da gewöhnliche Bestien metallische Wertsachen wohl kaum beiseiteschaffen würden."}},faq={{q="Warum haben Raptoren überhaupt Silber gestohlen?",a="Die Raptoren des Brachlands sind für ihre verblüffende Schläue und eigenartige Aasfressergewohnheiten bekannt. Ob sie nun vom glänzenden Metall, dem Geruch von bearbeitetem Leder an der Kiste oder schlicht von aggressiven Hortungsinstinkten angezogen wurden – sie schleppten die unversehrte Geldkassette zurück zu ihren Gemeinschaftsnestern in den Raptorgründen.",al={"warum wollen raptoren silber","warum silber raptoren","raptoren münzen motiv"}},{q="Wer ist Gazrog?",a="Gazrog ist ein Orksoldat, der im Hauptbunker des Wegekreuzes stationiert ist. Er leitet die Sicherheit und Logistik des Außenpostens und befasst sich mit Bedrohungen durch die heimische Tierwelt, Übergriffen der Zentauren und Unterbrechungen der Soldauszahlungen.",al={"gazrog","wer gibt gestohlenes silber","das wegekreuz questgeber gazrog"}},{q="Wo befinden sich die Raptorgründe?",a="Die Raptorgründe liegen im östlichen Brachland, südlich des Goblin-Hafens Ratschet und nordwestlich der Festung der Allianz in der Feste Northwatch. Die Nester füllen eine zerklüftete Passage, die zwischen zwei Bergen eingeklemmt ist.",al={"raptorgründe standort","wo gestohlenes silber finden","gestohlenes silber kiste ort"}},{q="Was geschieht, wenn das Silber nicht wiederbeschafft wird?",a="Das gestohlene Silber enthält den Monatssold für die Wachen des Wegekreuzes. Ohne dieses Geld droht den Verteidigern des Außenpostens, unbezahlt ihren Dienst tun zu müssen, was die Moral in einer Festung gefährdet, die ständig von Borstennacken, Zentauren und Plünderern der Allianz bedrängt wird.",al={"warum ist gestohlenes silber wichtig","das wegekreuz wachen sold"}},{q="Ist dies Teil einer längeren Questreihe?",a="Ja. Vor der Suche nach dem Versteck müssen Abenteurer zunächst Raptorendiebe für Gazrog abschließen und die Raptoren des Brachlands dezimieren, die den ursprünglichen Transport überfallen hatten, bevor sie den genauen Ort der Beute aufspüren.",al={"gestohlenes silber voraussetzungen","raptorendiebe folgequest"}},{q="Ist die Allianz in den Diebstahl verwickelt?",a="Nein. Obwohl die Feste Northwatch südöstlich der Raptorgründe liegt, wurde der Diebstahl vollständig von einheimischen Raptoren begangen, was selbst erfahrene Hordenkommandanten mit ihren diebischen Trieben und ihrem Hortungsverhalten überraschte.",al={"hat northwatch silber gestohlen","allianz raptoren brachland"}}},fx={f31163b7={q="Warum möchte Gazrog, dass das Gestohlenes Silber zurückgeholt wird?",a="Das Gestohlenes Silber macht den Lohn für den kommenden Monat für die Wachen in Das Wegekreuz aus. Als ein lebenswichtiger Außenposten der Horde, der Bedrohungen durch Zentauren, Stacheleber und die nahegelegene Allianz ausgesetzt ist, hängt Das Wegekreuz stark von diesen Wachen ab. Ohne ihren Sold könnten die Moral und die Verteidigung der Siedlung zusammenbrechen, weshalb Gazrog entschlossen ist, jede Münze zurückzuholen.",al={"gazrog motiv gestohlenes silber","warum braucht gazrog das silber","warum gestohlenes silber zurückholen"}},b903b9d8={q="Was ist das Gestohlenes Silber?",a="Das Silber ist der Sold, der für die Wachen in Das Wegekreuz bestimmt war, und der in einer verschlossenen Truhe aufbewahrt wurde, bis schlaue Raptoren ihn entwendeten. Tief in den Raptorgründe südlich von Ratschet versteckt, repräsentiert diese Kiste voller Münzen den Lebensunterhalt der Beschützer des Außenpostens und die Sicherheit der wichtigsten Kreuzung im Brachland.",al={"was ist gestohlenes silber","gestohlenes silber questgegenstand","wem gehört das silber"}},["03250c10"]={q="Gegen wen werdet Ihr in den Raptorgründe ausgesandt?",a="Ihr werdet in die Raptorgründe entsandt, einen rauen Nistplatz südlich von Ratschet und nordwestlich von Die Feste Northwatch. Das Gebiet wimmelt von wilden Sonnenfeuerraptoren, überraschend schlauen Bestien, die dafür bekannt sind, glänzende Wertsachen in ihren Nestern zu horten und die gestohlene Truhe aggressiv gegen jeden Eindringling zu verteidigen.",al={"wer bewacht das gestohlene silber","raptorgründe feinde","was lebt in den raptorgründe"}}},fp="13,323,15.453.0,18.433.0,48.282.0,14.210.0,37.199.0,44.228.0,37.214.0,38.202.0"}
P.entries["quest:33"] = {n="Wölfe an der Grenze",s="Wölfe an der Grenze ist eine frühe Aufgabe, die von Eagan Pelzschneider direkt vor der Abtei von Nordhain vergeben wird. Er rekrutiert neue Abenteurer, um umherstreifende Wölfe im Tal zu jagen und ihr Fleisch für seine persönliche Küche zu sammeln.",h="Wölfe an der Grenze ist eine frühe Aufgabe, die von Eagan Pelzschneider direkt vor der Abtei von Nordhain...",kw={"abtei","eagan","elwynn","fleisch","nordhain","pelzschneider","holzfällerwolf","wölfe"},ang={["profession:Cooking"]="Eagans Verlangen nach Wolfssteak führt neue Abenteurer an die Realität der Grenze von Azeroth heran: Was auch immer Ihr jagt, kann oft gekocht und gegessen werden.",["race:Human"]="Menschliche Rekruten, die ihre Reise in Nordhain beginnen, finden dies als eine ihrer ersten praktischen Aufgaben bei der Sicherung der unmittelbaren Grenzen von Sturmwind."},sec={{t="Eine pragmatische Bitte",b="Während sich Marschall McBride und die Wachen von Sturmwind darauf konzentrieren, ihre begrenzten Kräfte für die Verteidigung der Abtei von Nordhain gegen Defias-Banditen einzusetzen, haben die einfachen Handwerker immer noch tägliche Bedürfnisse. Eagan Pelzschneider steht an den Mauern der Abtei und hegt einen tiefen Groll gegen die örtlichen Holzfällerwölfe. Anstatt sich nur über die Bestien zu beschweren, die durch die Grenzgebiete streifen, rekrutiert er vorbeikommende Abenteurer, um deren Anzahl zu verringern und zähes Wolfsfleisch für seine Pfanne zu beschaffen."},{t="Wildnis von Nordhain",b="Das Nordhaintal war einst ein friedliches Refugium, geschützt von sanften Hügeln und dichten Wäldern. Da das Königreich Sturmwind durch fehlende Führung und Truppenknappheit belastet ist, sind wilde Raubtiere wie junge Wölfe und Holzfällerwölfe mutiger geworden und streifen nun näher an den Pfaden und Obstgärten der Abtei entlang. Sie zu beseitigen füllt nicht nur Eagans Vorratskammer, sondern macht die direkten Wege auch sicherer für Novizen, Arbeiter und neu eingetroffene Verteidiger."}},faq={{q="Wer ist Eagan Pelzschneider?",a="Eagan Pelzschneider ist ein örtlicher Jäger und Händler in der Nähe des Eingangs zur Abtei von Nordhain. Er hegt eine Abneigung gegen die wilden Holzfällerwölfe der Region, aber er freut sich sehr darauf, ihr Fleisch zu kochen und zu essen.",al={"wer ist eagan","pelzschneider","eagan pelzschneider"}},{q="Warum möchte Eagan Wolfsfleisch?",a="Eagan genießt es wirklich, Wolfssteaks zu essen. Er tauscht nützliche Startausrüstung und Münzen gegen die Hilfe von Rekruten, die bereit sind, rauszugehen und frisches Fleisch für ihn zu erlegen.",al={"warum wolfsfleisch","eagan hungrig","was macht eagan mit dem fleisch"}},{q="Wo befinden sich die Wölfe?",a="Holzfällerwölfe und junge Wölfe durchstreifen die Felder, Hügel und Flussufer im gesamten Nordhaintal, insbesondere im Süden und Osten der Abtei.",al={"wo sind die wölfe","wolfsstandorte","wölfe finden"}},{q="Warum sind Wölfe in Nordhain ein Problem?",a="Aufgrund reduzierter Patrouillen und Bedrohungen wie Defias-Banditen, die das Tal unter Druck setzen, sind wilde Tiere auf die Straßen und Farmen vorgedrungen, was das Reisen ohne Begleitung für Kleriker und Arbeiter gefährlich macht.",al={"warum greifen wölfe an","wolfsproblem in nordhain"}},{q="Muss ich mit jemandem sprechen, bevor ich diese Quest annehme?",a="Nein. Während Deputy Willem Neulinge über einen einleitenden Auftrag zu Eagan Pelzschneider schicken mag, bietet Eagan diese Jagdaufgabe jedem direkt an, der ihn außerhalb der Abtei anspricht.",al={"questvoraussetzungen","voraussetzungen","wer gibt diese quest"}},{q="Wird zähes Wolfsfleisch für Kochrezepte verwendet?",a="Eagan beabsichtigt, das Fleisch selbst zu kochen, aber angehende Köche lernen oft, dass Wolfsfleisch, das im Wald von Elwynn gesammelt wurde, als grundlegendes Grundnahrungsmittel beim Kochen im Freien dient.",al={"kochen von zähem wolfsfleisch","können spieler wolfsfleisch kochen"}}},fx={["12d6ae41"]={q="Wofür ist das Zähes Wolfsfleisch gedacht?",a="Eagan Peltskinner beabsichtigt, daraus Wolfssteaks für sich selbst zu kochen. Obwohl er die Bestien, die das Tal durchstreifen, verabscheut, hat er einen herzhaften Appetit auf ihr Fleisch entwickelt und tauscht gerne nützliche Ausrüstung gegen alles, was seinen Tisch deckt.",al={"wofür ist das zähes wolfsfleisch","warum zähes wolfsfleisch","verwendung von zähem wolfsfleisch"}},acd05579={q="Warum durchstreifen Wölfe das Nordhain?",a="Junge Wölfe und Holzfällerwölfe durchstreifen auf natürliche Weise die bewaldeten Ränder und offenen Wiesen im Nordhaintal. Da die örtlichen Wachen von Sturmwind jedoch mit der wachsenden Bedrohung durch The Defias Brotherhood beschäftigt sind, streifen die Raubtiere ungehindert näher an das Gelände der Abtei heran.",al={"warum sind hier wölfe","holzfällerwölfe im nordhain","wölfe im nordhain"}}},fp="24,218,19.440.0,19.442.0,25.206.0,30.143.0,29.152.0,39.185.0,53.185.0,44.157.0"}
P.entries["quest:3301"] = {n="Mura Runentotem",s="Diese Quest betraut einen Reisenden mit einer Probe eines veränderten Schnappkieferpanzers aus dem Brachland, die zu Mura Runentotem im Silberwald gebracht werden soll. Sie schlägt eine Brücke zwischen den Heilungsbemühungen der Tauren über Kontinente hinweg und verbindet die seltsame Lebenskraft der Ebenen Kalimdors mit den verheerten Ländern der Verlassenen.",h="Diese Quest betraut einen Reisenden mit einer Probe eines veränderten Schnappkieferpanzers aus dem Brachland...",kw={"brachland","mura runentotem","oasen","das grabmal","silberwald","schnappkieferpanzer","tonga runentotem"},ang={["class:Druid"]="Die Erforschung ungewöhnlichen Wiederauflebens der Natur – selbst jener Ausprägungen, die aus seltsamen Mutationen hervorgehen – ist ein zentraler Bestandteil der druidischen Bemühungen, versehrten Ländern ihr Gleichgewicht zurückzugeben.",["faction:Horde"]="Diese Aufgabe spiegelt das wachsende Band der Zusammenarbeit innerhalb der jungen Horde wider und verbindet die Verteidiger Kalimdors direkt mit den Kämpfen der Verlassenen in Lordaeron.",["race:Tauren"]="Diese Mission verdeutlicht die tiefe Hingabe, die der Clan der Runentotems für den Schutz und Erhalt der Natur empfindet, indem er seine heilende Hand sogar über das Meer bis in die düsteren, verdorrten Haine des Silberwalds ausstreckt.",["race:Undead"]="Während viele die Ländereien der Verlassenen als an Fäulnis und Pest verloren ansehen, versuchen Taurendruiden wie Mura Runentotem aufrichtig, den Wald rund um das Grabmal zu revitalisieren."},sec={{t="Eine Brücke über die Meere",b="Bei der Untersuchung der bizarren, magisch mutierten Tierwelt rund um die üppigen Oasen im Brachland bemerkt Tonga Runentotem etwas Ungewöhnliches an den veränderten Schnappkiefern. Trotz ihrer Verderbnis pulsieren ihre Panzer vor lebendiger, widerstandsfähiger Energie. In dem Glauben, diese seltsame Vitalität könnte einem höheren Zweck dienen, bittet Tonga einen Abenteurer, einen Panzer über das große Meer zu seiner Clangefährtin Mura Runentotem zu bringen, die in den Östlichen Königreichen stationiert ist."},{t="Den Verlassenen beistehen",b="Mura Runentotem weilt im Grabmal, einem Außenposten der Verlassenen in den unheimlichen, verfallenden Wäldern des Silberwalds. Da sie erkannte, dass der Silberwald ein kranker, von der Fäulnis heimgesuchter Wald ist, unternahm Mura die beschwerliche Reise, um den neuesten Verbündeten der Horde bei der Reinigung und Verjüngung ihrer Heimat zu helfen. Sie hofft, dass das innere Leuchten des Panzers und sein hartnäckiger, beständiger Lebensfunke Geheimnisse lüften, um die Vitalität des nördlichen Kontinents wiederherzustellen."}},faq={{q="Wer ist Mura Runentotem?",a="Mura Runentotem ist eine Taurendruidin und Clangefährtin von Tonga Runentotem. Sie reiste über das Meer in den Silberwald und ließ sich im Grabmal nieder, um den Verlassenen zu helfen, indem sie Wege erforscht, ihren sterbenden Wald zu heilen.",al={"mura","wer ist mura","runetotem silberwald"}},{q="Wo befindet sich Mura Runentotem?",a="Mura Runentotem ist im Grabmal stationiert, einer Stadt der Verlassenen an der Straße im Herzen des Silberwalds auf dem Kontinent der Östlichen Königreiche.",al={"mura standort","wo ist mura","mura runentotem finden"}},{q="Warum möchte Tonga einen Schnappkieferpanzer in den Silberwald schicken?",a="Die in der Nähe der Oasen des Brachlands gesammelten Schnappkieferpanzer weisen eine unnatürliche Lebenskraft und ein inneres Glühen auf. Tonga glaubt, dass die Erforschung dieser widerstandsfähigen Lebenskraft Mura Einblicke gewähren könnte, wie sich die verheerte, sterbende Ökologie des Silberwalds heilen lässt.",al={"warum panzer schicken","zweck schnappkieferpanzer","warum mura panzer braucht"}},{q="Warum versuchen die Tauren, das Land der Verlassenen zu heilen?",a="Die Tauren betrachten es als heilige Pflicht, die natürliche Welt zu hegen und zu pflegen. Da sie den Verfall und die Verheerung des Silberwalds erkannte, hofft Mura, die Heilungstraditionen der Erde einzusetzen, um ihren neuen Verbündeten in der Horde beizustehen und dem Boden sein Gleichgewicht zurückzugeben.",al={"tauren helfen untoten","warum silberwald heilen","druiden im silberwald"}},{q="Wie verbindet diese Quest das Brachland mit dem Silberwald?",a="Sie dient als thematisches und geografisches Band zwischen den frühen Territorien der Horde und schickt Abenteurer von den sonnendurchfluteten Ebenen Kalimdors in die finsteren Wälder der Östlichen Königreiche, um Forschungsmaterial zu überbringen.",al={"brachland zu silberwald quest","kontinentuebergreifende quest"}},{q="Was geschieht, nachdem man Mura den Panzer übergeben hat?",a="Mura ist von dem anhaltenden inneren Leuchten des Panzers fasziniert und beschließt, ihn eingehend zu studieren, um ihr langfristiges Ziel fortzusetzen: ein Heilmittel für die verheerten Wälder des Silberwalds zu finden.",al={"mura folgequest","was kommt danach"}}},fx={["10ada1ab"]={q="Warum bittet Tonga Runentotem Euch, den Panzer auszuliefern?",a="Tonga Runentotem ist in Das Wegekreuz stationiert und damit beschäftigt, die bizarren Mutationen zu untersuchen, die die Oasen im Brachland befallen. Eine Reise über das Meer zum fernen Kontinent Lordaeron würde ihn von seinen dringenden Pflichten in Kalimdor abhalten, was einen abenteuerlustigen Boten zur idealen Wahl macht, um seine Probe zu Mura zu bringen.",al={"warum mich schicken","warum kann tonga es nicht ausliefern","warum ich mura runetotem"}}},fp="14,293,20.444.0,19.410.0,22.218.0,32.155.0,55.236.0,49.249.0,54.211.0,41.180.0"}
P.entries["quest:332"] = {n="Weinladen-Werbung",s="\"Weinladen-Werbung\" ist ein kurzer Werbeauftrag, der von Renato Gallina im Handelsdistrikt von Sturmwind vergeben wird. Er lockt Passanten mit einem Gutschein für eine kostenlose Flasche Jahrgangswein aus dem Laden seiner Familie an den Kanälen. Er dient als alltäglicher Einblick in den lokalen Handel und die kleinen Unternehmen, die in der wiederaufgebauten Hauptstadt florieren.",h="\"Weinladen-Werbung\" ist ein kurzer Werbeauftrag, der von Renato Gallina im Handelsdistrikt von Sturmwind...",kw={"kanäle","gallina winery","pinot noir","renato gallina","suzetta gallina","der handelsdistrikt","weinladen-werbung","weingutschein"},ang={["faction:Alliance"]="Selbst in turbulenten Zeiten von Krieg und vermissten Königen unterhält der geschäftige Handelsdistrikt von Sturmwind einen aktiven Markt für heimische Luxusgüter und importierte Geschmacksrichtungen.",["profession:Cooking"]="Feine Weine wie der Pinot Noir, der von den Gallinas vertrieben wird, sind geschätzte Begleiter zu herzhaften Mahlzeiten, die in den Tavernen der Östlichen Königreiche zubereitet werden.",["race:Human"]="Für Menschen, die ihr Leben in Sturmwind wiederaufbauen, ist das Vorhandensein von familiengeführten Weingütern entlang der Kanalufer ein tröstliches Zeichen des städtischen Wiederaufbaus."},sec={{t="Ein Geschmack der Kanäle",b="Während Abenteurer sich oft mit kriegerischen Bedrohungen und politischen Intrigen beschäftigen, dreht sich das tägliche Leben in Sturmwind um regen Handel. Renato Gallina geht die gepflasterten Wege des Handelsdistrikts entlang und bewirbt die Gallina Winery, das kleine Geschäft, das er zusammen mit seiner Schwester Suzetta betreibt. Um durstige Reisende und Einheimische gleichermaßen anzulocken, verteilt er Werbeflyer, die den Inhaber zu einer kostenlosen Verkostung berechtigen."},{t="Der Pinot Noir-Jahrgang",b="Der von der Familie Gallina angebotene Preis ist eine Flasche ihres berühmten Pinot Noir. Wenn Kunden dem Ticket zum Eingang der Weinkellerei nahe der Kanäle folgen, finden sie Suzetta Gallina, die bereit ist, die Flasche zu überreichen, im Vertrauen darauf, dass ein Schluck ihres Vorzeigeweins jeden Neuling in einen treuen Stammkunden verwandelt."}},faq={{q="Wo befindet sich die Gallina Winery?",a="Die Gallina Winery liegt im Handelsdistrikt von Sturmwind, direkt am Rand der malerischen Kanäle, nicht weit von Renato Gallinas Werberoute entfernt.",al={"wo ist die gallina winery","standort suzetta gallina","wo gibt man weinladen-werbung ab"}},{q="Wer sind Renato und Suzetta Gallina?",a="Renato und Suzetta Gallina sind Geschwister, die ein unabhängiges Weingeschäft in Sturmwind betreiben. Renato wandert durch die Straßen und wirbt mit Flyern für ihr Geschäft, während Suzetta hinter dem Ladentresen steht und den Wein einschenkt.",al={"wer sind die gallinas","renato gallina","suzetta gallina hintergrundgeschichte"}},{q="Welchen Wein erhält man mit dem Ticket?",a="Eine Flasche des berühmten Pinot Noir der Gallinas, der Vorzeigerotwein des Ladens, von dem Renato hofft, dass er Neulinge in treue Stammkunden verwandelt.",al={"pinot noir wein","welchen wein bekommt man","pinot noir sturmwind"}},{q="Warum verteilt Renato kostenlose Weintickets?",a="Das ist klassisches Marketing auf der Straße. Renato nutzt kostenlose Kostproben ihres geschätzten Bestands, um Kunden in ihren Laden am Kanal zu locken und einen Stammkundenstamm unter den Bürgern von Sturmwind aufzubauen.",al={"warum kostenloser wein","zweck des weinladen-tickets"}},{q="Beinhaltet dieser Auftrag irgendeine Gefahr oder einen Kampf?",a="Nein. Der Auftrag besteht lediglich darin, ein Werbeticket von Renato anzunehmen und einen kurzen Weg durch die sicheren Straßen des Handelsdistrikts zu Suzetta am Ladeneingang zu spazieren.",al={"ist weinladen-werbung gefährlich","kämpfe wein-quest"}},{q="Verkauft die Gallina Winery auch andere Waren?",a="Suzetta führt eine Auswahl an Standardweinen und alkoholischen Getränken für durstige Reisende, Wachen in der Pause und örtliche Tavernenlieferanten, die Nachschub benötigen.",al={"was verkauft suzetta noch","getränke gallina winery"}}},fp="16,361,21.410.0,22.302.0,36.157.0,35.208.0,31.128.0,43.196.0,46.178.0,41.156.0"}
P.entries["quest:333"] = {n="Harlan braucht Nachschub",s="Harlan Bagley, ein Händler in Sturmwind, findet seine Regale durch einen beispiellosen Nachfrageschub nach robuster Kleidung und Rüstung geleert vor. Da er von den sich anbahnenden Konflikten jenseits der Stadtmauern nichts ahnt, schickt er einen Kurier mit einer dringenden Stoffbestellung zu Rema Schneider in den Canal Tailor and Fit Shop.",h="Harlan Bagley, ein Händler in Sturmwind, findet seine Regale durch einen beispiellosen Nachfrageschub nach...",kw={"bagley","kanal","stoff","harlan","rema","nachschub","schneider","sturmwind","schneiderin"},ang={["faction:Alliance"]="Die stille Panik unter Sturmwinds Einkäufern deutet auf die wachsende Unruhe hin, die das Kernland der Allianz in Abwesenheit von König Varian Wrynn erfasst.",["profession:Tailoring"]="Die Besorgung bietet einen Einblick in die alltägliche Logistik von Sturmwinds Textilindustrie, in der kleine Kanalwerkstätten größere Handelsgeschäfte beliefern.",["race:Human"]="Sturmwinds Handwerker der Arbeiterschicht begegnen ihren Herrschern weiterhin mit Misstrauen und vermuten, dass der Adel die einfachen Bürger über drohende Gefahren im Dunkeln lässt."},sec={{t="Ein Ansturm auf robuste Kleidung",b="In den belebten Handelsvierteln von Sturmwind mussten Ladenbesitzer wie Harlan Bagley mitansehen, wie ihre Bestände in alarmierendem Tempo schwanden. Gewöhnliche Bürger und umherziehende Abenteurer gleichermaßen haben verstärkte Tuniken, Reisekleidung und kampfbereite Rüstung aufgekauft. Für Harlan fühlt es sich an, als wappne sich die Bevölkerung des Königreichs für eine harte Jahreszeit oder einen bevorstehenden Winter, doch das schiere Verkaufsvolumen lässt seinen Laden leergefegt und händeringend nach fertigem Stoff suchen."},{t="Fragen an den Kanälen",b="Um seine Regale wieder aufzufüllen, schickt Bagley einen Boten über die Wasserwege der Stadt zu Rema Schneider, der Schneiderin im Canal Tailor and Fit Shop. Rema ist zwar dankbar für die anhaltende Kundschaft, doch der plötzliche Ansturm auf Schutzkleidung kommt ihr beunruhigend vor. Gerüchte über Spannungen liegen im gesamten Königreich in der Luft, und die Schneiderin kann sich des Gedankens nicht erwehren, dass das regierende House of Nobles von Sturmwind Gerüchte über einen offenen Krieg vor dem einfachen Volk verheimlicht."}},faq={{q="Wer ist Harlan Bagley?",a="Harlan Bagley ist ein Tuchhändler und Ladenbesitzer in Sturmwind. Sein Geschäft ist auf örtliche Schneider angewiesen, um seinen Bestand an Strickwaren und reisefertiger Kleidung aufzufüllen.",al={"harlan bagley","wer ist harlan","bagley sturmwind"}},{q="Wer ist Rema Schneider?",a="Rema Schneider ist eine professionelle Schneiderin, die im Canal Tailor and Fit Shop in Sturmwind arbeitet. Zusammen mit ihrem Ehemann Corbett beliefert sie Händler in der ganzen Stadt mit frisch genähten Stoffen und Kleidungsstücken.",al={"rema schneider","schneiderin rema","canal schneider"}},{q="Warum geht Harlan die Kleidung aus?",a="Bürger und Reisende haben Rüstungen und robuste Kleidungsstücke in ungewöhnlich großer Zahl aufgekauft. Harlan scherzt, die Leute würden sich verhalten, als stünde ein bitterer Winter bevor, obwohl der wahre Grund die wachsende Unruhe und Gefahr an den Grenzen des Königreichs ist.",al={"warum kein stoff mehr","warum rüstung kaufen","harlans geschäft boomt"}},{q="Warum hegt Rema Schneider Verdacht gegen den Adel?",a="Rema findet es unnatürlich, dass das einfache Volk sich plötzlich ohne jede offizielle Kriegserklärung für den Kampf rüstet. Da das House of Nobles die königlichen Angelegenheiten lenkt, während König Varian Wrynn abwesend bleibt, fürchtet sie, dass die Aristokratie einen bevorstehenden Krieg vor der Öffentlichkeit verheimlicht.",al={"rema adlige","sturmwind adlige verheimlichen krieg","warum adel verdächtig"}},{q="Wo befindet sich der Canal Tailor and Fit Shop?",a="Der Canal Tailor and Fit Shop liegt an den Wasserstraßen, die sich durch Sturmwind ziehen, günstig gelegen zwischen den großen Stadtbezirken für einfache Händlerlieferungen.",al={"canal tailor standort","wo ist rema schneider","wo ist canal tailor"}},{q="Was geschieht, nachdem die Stoffanforderung überbracht wurde?",a="Nach Erhalt der Bestellung bereitet Rema die Nachschublieferung vor, was ihren Ehemann Corbett Schneider dazu veranlasst, sich durch die Straßen der Stadt aufzumachen – vorbei an lokalen Geschäften wie der Lionheart Armory und Trias' Cheese –, um Handelsbesorgungen zu erledigen.",al={"corbett schneider spaziergang","was macht corbett","remas ehemann"}}},fp="23,289,23.469.0,23.448.0,21.184.0,22.221.0,38.241.0,43.291.0,47.170.0,50.234.0"}
P.entries["quest:334"] = {n="Eine Lieferung für Thurman",s="Package for Thurman ist eine kurze Besorgung durch die Straßen von Sturmwind. Eine besorgte Mutter, Rema Schneider, bittet vorbeikommende Reisende, ihrem faulenzenden Lehrlingssohn bei Larson Clothiers im Magierviertel vergessenen Schneiderbedarf zu bringen.",h="Package for Thurman ist eine kurze Besorgung durch die Straßen von Sturmwind.",kw={"lehrling","tuchhändler","larson","das magierviertel","rema","schneider","nähset","sturmwind","thurman"},ang={["faction:Alliance"]="Unterhalb der hohen Politik von Burg Sturmwind halten einfache Bürger und Handwerker die Hauptstadt bekleidet, ernährt und am Laufen – eine Besorgung nach der anderen.",["profession:Tailoring"]="Jeder große Schneider fing ganz unten an: Säume nähen, Nadeln halten und versuchen, sich vor den Lehrlingspflichten bei Larson Clothiers zu drücken."},sec={{t="Die Besorgung einer Mutter",b="Im alltäglichen Trubel von Sturmwind beinhaltet nicht jede Aufgabe den Kampf gegen Gnolle oder das Aufdecken von Defias-Verschwörungen. Rema Schneider, die um den Lebensunterhalt ihres Sohnes Thurman besorgt ist, bemerkt, dass er das Haus in Eile ohne seine Schere und Nadeln verlassen hat. Aus Furcht, er könnte bei seinen beruflichen Pflichten in Rückstand geraten, bittet sie einen Abenteurer, das Set über die Canals zu seiner Werkstatt zu bringen."},{t="Ein widerwilliger Lehrling",b="Larson Clothiers liegt tief im Magierviertel eingebettet, nicht weit von den aufragenden Spitzen des Mage Tower entfernt. Nach Erhalt seiner Werkzeuge enthüllt Thurman, dass das Zurücklassen seiner Schere reine Absicht war – ein Plan, um seinen täglichen Pflichten zu entkommen und den Tag mit Vergnügen zu verbringen. Durch das Eingreifen seiner Mutter löst sich sein freier Nachmittag jedoch in Luft auf und er wird zurück an seine Näharbeit gezwungen."}},faq={{q="Wer startet die Quest Package for Thurman?",a="Rema Schneider startet die Quest. Sie sucht nach jemandem, der ihrem Sohn, der am anderen Ende der Stadt im Magierviertel arbeitet, ein Nähset bringt.",al={"wer vergibt die quest","rema schneider quest","questgeber"}},{q="Wo ist Thurman Schneider zu finden?",a="Thurman Schneider befindet sich in Larson Clothiers im Magierviertel von Sturmwind. Der Laden liegt tiefer im Viertel, nahe dem Weg, der zum Mage Tower hinaufführt.",al={"thurman standort","wo ist thurman","thurman finden"}},{q="Hat Thurman seine Werkzeuge wirklich versehentlich vergessen?",a="Rema glaubt, dass Thurman ohne sein Set davongeeilt ist, und bittet Euch, es ihm zu bringen.",al={"hat thurman vergessen","warum hat thurman werkzeug zurückgelassen","thurman faulenzt"}},{q="In welchem Geschäft lernt Thurman?",a="Thurman arbeitet als Schneiderlehrling für Larson Clothiers, ein Bekleidungsgeschäft im Magierviertel von Sturmwind, das von der Familie Larson geführt wird.",al={"wo arbeitet thurman","larson clothiers","für wen arbeitet thurman"}},{q="Warum bittet Rema Schneider einen Abenteurer um Hilfe?",a="Rema glaubt, dass die Ausbildung ihres Sohnes ohne sein Set in Gefahr ist. Da sie ihren eigenen Pflichten nachgehen muss, wendet sie sich an vorbeikommende Abenteurer, die möglicherweise auf dem Weg zum Magierviertel sind.",al={"warum den spieler fragen","rema hilfe"}},{q="Was geschieht, nachdem Ihr das Nähset abgeliefert habt?",a="Bringt das Nähset zu Thurman bei Larson Clothiers in Sturmwind.",al={"questbelohnung","nach package for thurman","thurmans reaktion"}}},fx={["3c7bea70"]={q="Warum möchte Rema Schneider, dass dies erledigt wird?",a="Rema sorgt sich um die Zukunft ihres Sohnes Thurman. Er hat einen Platz als Lehrling bei Larson Clothiers im Magierviertel bekommen, eilte jedoch los, ohne seine Scheren und Nadeln mitzunehmen. Ohne sein Werkzeug kann Thurman seine Aufgaben nicht erfüllen oder sein Handwerk erlernen, was seinen Stand bei seinen Arbeitgebern gefährdet. Da sie glaubt, es sei ein bloßes Versehen gewesen, möchte sie, dass sein Set sofort geliefert wird, damit seine Ausbildung nicht gefährdet wird.",al={"warum muss das nähzeug an rema geliefert werden","beweggründe rema schneider","warum thurman das werkzeug bringen"}}},fp="19,243,17.361.0,22.393.1,41.138.0,37.182.0,50.82.1,38.128.0,51.187.0,46.65.1"}
P.entries["quest:335"] = {n="Ein nobles Bräu",s="Tief in den schattenhaften Winkeln des Gasthauses Zum Geschlachteten Lamm in Sturmwind schmiedet Zardeth der Schwarzen Klaue Ränke gegen den Adel der Stadt. Ein neugieriger Peer, Lord Wishock, droht die Hexenmeister-Enklave unter der Taverne aufzudecken, was eine heimliche Beschaffung seltener und mächtiger Reagenzien erfordert, um die Bedrohung zu neutralisieren.",h="Tief in den schattenhaften Winkeln des Gasthauses Zum Geschlachteten Lamm in Sturmwind schmiedet Zardeth der...",kw={"dunkelhain","house of nobles","bisamwurzel","slaughtered lamb","der steinwerkdamm","tilloa","wishock","zardeth"},ang={["class:Warlock"]="Die Krypten unter dem Gasthaus Zum Geschlachteten Lamm sind Euer sicherer Zufluchtsort in Sturmwind. Zardeth beizustehen schützt Eure Brüder und Schwestern der dunklen Künste vor den neugierigen Blicken des rechtschaffenen Adels des Königreichs.",["faction:Alliance"]="Während König Varian Wrynn weiterhin verschollen bleibt, sind die politischen Manöver im House of Nobles auf einem Höchststand, was interne Skandale für die Stabilität der Stadt besonders gefährlich macht.",["profession:Herbalism"]="Die Tilloaträne und die Bisamwurzel stellen eine seltene und spezialisierte Flora dar, die nur in Regionen gedeiht, die von finsterer Geschichte oder tosenden Schauern reinsten Wassers geprägt sind."},sec={{t="Bedrohung durch den Adel",b="Unter den Straßen des Magierviertels genießt der Hexenmeisterzirkel, der aus dem Gasthaus Zum Geschlachteten Lamm heraus operiert, eine prekäre Geheimhaltung. Diese Heimlichkeit wird durch Lord Wishock gefährdet, ein Mitglied des House of Nobles, der Wind von der dunklen Magie bekommen hat, die unter der Stadt schwelt. Wishock hat begonnen, bei seinen Standesgenossen für eine umfassende Untersuchung zu werben, was die Stadtwache und königliche Aufmerksamkeit auf den Zirkel lenken würde."},{t="Ein Gebräu in den Schatten",b="Anstatt eine offene Konfrontation mit der herrschenden Klasse von Sturmwind zu riskieren, ersinnt Zardeth der Schwarzen Klaue ein diskretes Mittel, um sicherzustellen, dass Lord Wishock dauerhaft beschäftigt bleibt. Die Zubereitung erfordert obskure botanische Zutaten aus fernen Ecken der Östlichen Königreiche: eine blasse Blüte namens Tilloaträne aus dem Dämmerwald und eine unter Wasser wachsende Bisamwurzel, die unter dem Steinwerkdamm gepflückt werden muss."}},faq={{q="Wer ist Lord Wishock?",a="Lord Wishock ist ein Adliger im House of Nobles von Sturmwind. Nachdem er Hinweise auf Aktivitäten von Hexenmeistern unter dem Magierviertel entdeckt hatte, begann er, den Rat zu einer formellen Untersuchung zu drängen.",al={"wishock","lord wishock","wer ist wishock"}},{q="Wer ist Zardeth der Schwarzen Klaue?",a="Zardeth ist ein erfahrener Hexenmeister, der aus den Krypten unter der Taverne Zum Geschlachteten Lamm in Sturmwind heraus agiert. Er arbeitet daran, die Hexenmeister-Kabale der Stadt davor zu bewahren, von den Behörden entdeckt und ausgelöscht zu werden.",al={"zardeth","zardeth black claw","wer ist zardeth"}},{q="Woher stammt die Tilloaträne?",a="Die Tilloaträne ist eine zarte weiße Blume, die im überwucherten Garden of Stalvan am Rande von Dunkelhain im Dämmerwald wächst.",al={"fundort tilloaträne","tilloaträne","wo ist tilloaträne"}},{q="Wo findet man die Bisamwurzel?",a="Die Bisamwurzel wächst nur in den Feuchtgebieten am Fuße der gewaltigen Wasserfälle, die unter dem Steinwerkdamm im Sumpfland herabstürzen.",al={"fundort bisamwurzel","bisamwurzel","wo gibt es bisamwurzel"}},{q="Warum weiß die Regierung von Sturmwind nicht längst von den Hexenmeistern?",a="Teufelsmagie ist innerhalb der Allianz streng verboten und verpönt. Die Hexenmeister unter dem Gasthaus Zum Geschlachteten Lamm müssen ihr Handwerk vollkommen im Verborgenen ausüben, um einer Einkerkerung oder Hinrichtung durch die Paladine und Stadtwachen zu entgehen.",al={"sturmwind hexenmeister geheimnis","warum hexenmeister verstecken","sind hexenmeister illegal"}},{q="Was beabsichtigt Zardeth mit diesen Reagenzien zu brauen?",a="Zardeth behauptet, das Gebräu werde Lord Wishock 'beschäftigen', sodass die Untersuchung ins Stocken gerät. Was genau er für den Adligen vorgesehen hat, wird erst klar, wenn das Gebräu fertig ist.",al={"was ist das gebräu","zweck adelsgebräu","warum gebräu brauen"}}},fx={e620a973={q="Warum möchte Zardeth der Schwarzen Klaue, dass dies erledigt wird?",a="Lord Wishock entdeckte den geheimen Hexenmeister-Zirkel, der unter The Slaughtered Lamb im Mage Quarter von Sturmwind operiert. Da Wishock das Haus der Adligen aktiv dazu aufruft, eine formelle Untersuchung ihrer Präsenz einzuleiten, benötigt Zardeth ein Gebräu, um den sich einmischenden Adligen abzulenken, bevor die städtischen Behörden gegen ihre dunklen Praktiken vorgehen.",al={"warum zardeth helfen","zardeth motiv","warum will zardeth a noble brew"}},["9e466bd7"]={q="Wofür ist die Tilloaträne?",a="Die Tilloaträne ist eine zarte weiße Blume, die aus dem Garten von Stalvan in der Nähe von Dunkelhain geerntet wird. Zardeth benötigt sie als Hauptreagenz für das Brauen einer speziellen Mischung, die dazu bestimmt ist, Lord Wishocks politischen Kreuzzug gegen den Zirkel zu neutralisieren.",al={"was bewirkt tilloaträne","zweck der tilloaträne","warum tilloaträne benötigt"}},["84ab02b5"]={q="Wofür ist die Bisamwurzel?",a="Die Bisamwurzel wächst am nebelverhangenen Fuß der Wasserfälle unterhalb vom Der Steinwerkdamm im Sumpfland. Zardeth verwendet ihre wirkungsvollen Eigenschaften zusammen mit der Tilloaträne, um ein Gebräu herzustellen, das stark genug ist, um Lord Wishock abzulenken.",al={"was bewirkt bisamwurzel","zweck der bisamwurzel","warum bisamwurzel benötigt"}},["256dc9f2"]={q="Warum benötigt Zardeth einen Abenteurer, anstatt die Zutaten selbst zu beschaffen?",a="Zardeth und seine Hexenmeister-Gefährten müssen unter The Slaughtered Lamb verborgen bleiben. Das Verlassen ihres Zufluchtsortes riskiert, die sofortige Aufmerksamkeit der Stadtwache und des Hauses der Adligen auf sich zu ziehen, insbesondere während Lord Wishock aktiv eine Untersuchung fordert.",al={"warum ich a noble brew","warum braucht zardeth mich","warum kann zardeth die reagenzien nicht besorgen"}}},fp="12,312,24.402.0,27.413.1,20.201.0,33.196.0,40.137.0,33.142.0,67.219.0,53.177.1"}
P.entries["quest:336"] = {n="Ein nobles Bräu",s="Ein nobles Bräu ist der Höhepunkt eines verdeckten Plans, der aus dem zwielichtigen Keller unter Zum Geschlachteten Lamm in Sturmwind orchestriert wurde. Auf Geheiß von Zardeth der Schwarzen Klaue liefert ein ahnungsloser oder gleichgültiger Kurier einen wirkungsvollen Trunk namens Schwarzklauenbier an Lord Baurles K. Wischock innerhalb von Burg Sturmwind.",h="Ein nobles Bräu ist der Höhepunkt eines verdeckten Plans, der aus dem zwielichtigen Keller unter Zum...",kw={"baurles wishock","schwarzklauenbier","halle der bittsteller","nobles bräu","slaughtered lamb","burg sturmwind","zardeth"},sec={{t="Ein nobler Heuchler",b="Lord Baurles K. Wischock ist ein Adliger, der regelmäßig die Halle der Bittsteller in Burg Sturmwind besucht und dort von Selbstwichtigkeit und der Zukunft des Königreichs predigt. Doch unter seinem aristokratischen Gehabe verbirgt sich ein offenes Geheimnis, das den Stammgästen von Zum Geschlachteten Lamm bekannt ist: Nachts besucht Wishock die oberen Räume der Taverne, trinkt exzessiv und lässt enorme Rechnungen auflaufen, die er niemals begleicht. Noch schlimmer in den Augen des Etablissements ist, dass er seine Tage damit verbringt, die Schließung der Taverne zu fordern."},{t="Ein tödlicher Toast",b="Zardeth der Schwarzen Klaue, ein Hexenmeister, der in den dunklen Winkeln unter der Taverne lauert, beschließt, Wishocks Schulden auf endgültige Weise zu begleichen. Er braut ein spezialisiertes Gebräu – Schwarzklauenbier – und verspricht, dass es „ordentlich reinhaut“. Als ihm der schäumende Humpen in der Halle der Bittsteller präsentiert wird, hält der hochnäsige Adlige den Kurier für einen einfachen Diener, wirft eine Kupfermünze als Abfertigung und trinkt gierig, nur um kurz darauf mitten in den Hallen der Festung tot zusammenzubrechen."}},faq={{q="Wer ist Zardeth der Schwarzen Klaue?",a="Zardeth der Schwarzen Klaue ist ein Hexenmeister, der mit der schattenhaften Kabale verbunden ist, die in den versteckten Katakomben unter Zum Geschlachteten Lamm im Magierviertel von Sturmwind operiert. Er führt gefährliche und geheime Operationen fernab der Augen der Stadtwache durch.",al={"wer ist zardeth","zardeth der schwarzen klaue","wer gibt die quest"}},{q="Warum nimmt Zardeth Lord Wishock ins Visier?",a="Wishock ist ein betrunkener Heuchler, der seine Nächte damit verbringt, in den oberen Stockwerken von Zum Geschlachteten Lamm zu zechen, ohne seine Rechnungen zu bezahlen, während er seine Tage in der Halle der Bittsteller damit verbringt, von den Behörden die Schließung der Taverne zu verlangen.",al={"warum wishock töten","wishocks motivation","warum vergiftet"}},{q="Wo findet Ihr Lord Wishock?",a="Lord Baurles K. Wischock lungert in der Halle der Bittsteller herum, einem Vorraum innerhalb von Burg Sturmwind, in dem sich Adlige und Bürger versammeln, um bei der Regentschaft des Reiches Lobbyarbeit zu leisten.",al={"fundort lord wishock","wo ist wishock","wishock in der halle der bittsteller"}},{q="Wie erhält Lord Wishock das Gebräu?",a="Wishock hält den Kurier für einen Diener, nimmt das Starkbier als erfrischendes Getränk entgegen und fertigt ihn mit einer einzigen Kupfermünze ab.",al={"stirbt wishock","wishocks tod","wirkung des starkbiers"}},{q="Erregt die Lieferung des Starkbiers die Aufmerksamkeit der Wachen?",a="Die Lieferung wird wie die eines gewöhnlichen Dieners behandelt, der ein Getränk bringt, und der Kurier kann seinen Botengang fortsetzen, ohne eine Konfrontation mit den Wachen zu riskieren.",al={"greifen wachen an","bin ich in stormwind gesucht","folgen der vergiftung"}},{q="Welche Quest folgt auf diese Lieferung?",a="Der Botengang setzt sich mit „Ihr habt uns gute Dienste erwiesen“ fort, womit Ihr zu Zardeth unter Zum Geschlachteten Lamm zurückkehrt.",al={"was passiert als nächstes","nach ein nobles bräu","nächste quest"}}},fx={["06c31ab1"]={q="Wer ist Lord Wischock und warum ist er ein Ziel?",a="Lord Baurles K. Wischock ist ein wichtigtuerischer Adliger aus Sturmwind, der sich in der Halle der Bittsteller aufhält, um ein Anliegen beim königlichen Hof vorzubringen. Obwohl er sich selbst für unverzichtbar für die Zukunft des Königreichs hält, besucht er häufig die unterirdische Taverne The Slaughtered Lamb, wo er riesige Trinkgelage auf Kosten des Hauses veranstaltet, für die er sich weigert zu bezahlen, während er gleichzeitig aktiv eine Kampagne zur Schließung des Lokals führt. Zardeth hat es auf ihn abgesehen, um seinen Einmischungen ein Ende zu setzen und seine unbezahlten Schulden zu begleichen.",al={"wer ist lord wischock","warum wischock töten","wer ist wischock","lord wischock"}},c4eeba5d={q="Warum muss ich das Starkbier für Zardeth ausliefern, anstatt dass er es selbst tut?",a="Zardeth und seine Hexenmeisterkollegen operieren heimlich aus den Krypten unter dem The Slaughtered Lamb im Herzen von Sturmwind. Persönlich vor den Adligen und der Stadtwache in der Burg Sturmwind zu erscheinen, würde sofortige Aufmerksamkeit erregen und zur Verhaftung führen, besonders da Lord Wischock Zardeths Lokal bereits kennt. Indem er einen unauffälligen Abenteurer schickt, sieht die Lieferung wie die eines gewöhnlichen Dieners aus, der Erfrischungen bringt, was Zardeths Plan vor Blicken verborgen hält.",al={"warum braucht zardeth mich","warum das bier ausliefern","warum kann zardeth es ihm nicht selbst geben"}}},fp="12,320,17.484.0,14.482.1,33.238.0,37.231.1,28.159.0,39.130.1,56.147.1,33.103.1"}
P.entries["quest:3361"] = {n="Dilemma eines Flüchtlings",s="Nach dem verheerenden Fall von Gnomeregan an die Troggs und die Strahlung sind vertriebene Gnom in die verschneite Wildnis von Dun Morogh geflohen. Außerhalb von Ambossar verlor ein Ingenieur namens Felix Windenbolz während der panischen Evakuierung seine lebenswichtigen Besitztümer und Werkzeuge an plündernde Frostmanetrolle.",h="Nach dem verheerenden Fall von Gnomeregan an die Troggs und die Strahlung sind vertriebene Gnom in die...",kw={"ambossar","eimer voller bolzen","coldridge","felix windenbolz","frostmane","gnomeregan","strahlung"},ang={["profession:Engineering"]="Kein Handwerker mit Selbstachtung kann tatenlos zusehen, wie Plünderer mit Präzisionsbolzen, Messschiebern und Werkzeugkästen davonkommen, deren Zusammenstellung ein ganzes Leben gekostet hat.",["race:Dwarf"]="Die Coldridgeberge bieten Eurem Volk seit Jahrhunderten Schutz; den Gnomenflüchtlingen zu helfen, in Ambossar Fuß zu fassen, ehrt das uralte Bündnis zwischen Eisenschmiede und Gnomeregan.",["race:Gnome"]="Diese Quest fasst die bittere Tragödie zusammen, vor der Euer Volk steht: Nachdem Ihr Eure wundersame Heimat an Gift und Verrat verloren habt, müssen alltägliche Tüftler nun Fremde anflehen, primitiven Trollen einfache Werkzeuge abzujagen."},sec={{t="Die Flucht aus Gnomeregan",b="Als unterirdische Troggs die hochtechnisierte Stadt Gnomeregan überrannten, genehmigten Hochtüftler Gelbin Mekkadrill und seine Berater in einem verzweifelten Versuch, die Invasoren auszulöschen, die Freisetzung von radioaktivem Gas. Das Wagnis schlug katastrophal fehl, tötete Tausende Unschuldige, mutierte Überlebende zu geistlosen Lepragnomen und zwang die verbleibende Bevölkerung zu einem hektischen Exodus quer durch Dun Morogh."},{t="Plünderer im Schnee",b="Fliehende Ingenieure und Tüftler nahmen alle geschätzten Werkzeuge und Baupläne mit, die sie retten konnten. Allerdings werden die eisigen Gebirgspässe zwischen Gnomeregan und dem Coldridgetal von einheimischen Frostmanetrollen durchstreift. Als Felix Windenbolz zur Zuflucht von Ambossar eilte, rissen Frostmaneräuber seinen Werkzeugkasten, seine Schatulle und seinen Eimer voller Bolzen an sich und schleppten sie in ihre Lager südwestlich der Stadt."}},faq={{q="Wer ist Felix Windenbolz?",a="Felix Windenbolz ist ein Gnomen-Ingenieur, der der radioaktiven Zerstörung von Gnomeregan nur knapp entkam. Da ihm das kriegerische Geschick fehlt, um die Gefahren von Dun Morogh abzuwehren, sucht er in der Nähe von Ambossar Zuflucht, während er versucht, seine gestohlene Ausrüstung wiederzubeschaffen.",al={"felix windenbolz","wer ist felix","felix ambossar"}},{q="Warum ist Gnomeregan verstrahlt?",a="Während einer unerwarteten Trogg-Invasion setzten die Gnomenbehörden unbeständiges radioaktives Gas frei, um die Monster zu vernichten. Stattdessen kontaminierte das Gas die Belüftungssysteme der Stadt, tötete oder mutierte die meisten Bewohner und machte die Hauptstadt unbewohnbar.",al={"was geschah mit gnomeregan","gnomeregan strahlung","fall von gnomeregan"}},{q="Wer hat Felix' Besitztümer gestohlen?",a="Frostmanetrolle nahmen seine Kiste, seine Schatulle und seinen Eimer voller Bolzen an sich. Diese einheimischen Trolle lauern Reisenden auf den Bergpfaden von Dun Morogh auf und schaffen gestohlenen Schrott sowie Ausrüstung in ihre primitiven Lager südwestlich von Ambossar.",al={"wer hat die bolzen gestohlen","wer hat felix' sachen","frostmanetrolle"}},{q="Wo suchten die vertriebenen Gnome Zuflucht?",a="Viele Gnome flohen durch Dun Morogh in das Zwergenkönigreich Eisenschmiede, während andere in kleineren Siedlungen wie Ambossar und Kharanos in ganz Dun Morogh vorübergehend Schutz suchten.",al={"wo leben gnome","gnomenflüchtlinge","gnomensiedlung"}},{q="Warum ist ein Eimer voller Bolzen so wichtig?",a="Für einen verbannten Gnomentüftler stellen Werkzeuge, Spezialschauben und maschinell gefertigte Bolzen den gesamten Lebensunterhalt dar. Ohne geeignete Ausrüstung haben Ingenieure auf der Flucht keine Möglichkeit, ihr Handwerk auszuüben, Verteidigungsanlagen zu bauen oder ihr Leben im Exil neu aufzubauen.",al={"warum bolzen","felix eimer voller bolzen"}},{q="Welche Bedrohung stellen die Frostmanetrolle für das Coldridgetal dar?",a="Der Stamm der Frostmane bewohnt seit langem die rauen Gipfel von Dun Morogh. Mit den jüngsten Trogg-Ausbrüchen und dem Chaos der Evakuierung von Gnomeregan sind die Trolle dreister geworden, überfallen Versorgungslinien und lauern Reisenden auf.",al={"trolle in dun morogh","frostmane bedrohung","frostmane lager"}}},fx={["0b2d3aab"]={q="Warum möchte Felix Windenbolz seine Habseligkeiten zurück?",a="Nachdem er vor der Strahlenvergiftung aus Gnomeregan floh und kaum die Kleidung am Leib hatte, verlor Felix die letzten Überreste seines Lebensunterhalts und Handwerks. Ohne seine persönliche Truhe, seinen Kasten und seine Werkzeuge sitzt er völlig mittellos in Ambossar fest und hat keine Möglichkeit, sein Leben neu aufzubauen oder als Flüchtling seinem Handwerk nachzugehen.",al={"felix motiv","warum braucht felix das","felix windenbolz habseligkeiten"}},["48f90e68"]={q="Warum kann Felix seine Habseligkeiten nicht selbst zurückholen?",a="Felix ist ein gewöhnlicher Tüftler und vertriebener Flüchtling, kein Abenteurer oder Soldat. Verängstigt von der feindseligen Wildnis und den Frostmähnentrollen, die seine Ausrüstung verschleppt haben, nicht gewachsen, kann er es nicht riskieren, sich allein in ihre Lager zu wagen.",al={"warum holt felix seine sachen nicht selbst","warum braucht felix mich","felix warum ich"}},["6a13a14f"]={q="Was befindet sich in Felix' Kasten und Felix' Truhe?",a="Felix' Truhe und Kasten enthalten die persönlichen Habseligkeiten und Spezialwerkzeuge, die er bei der Flucht vor der Katastrophe in Gnomeregan einpacken konnte. Für einen vertriebenen Handwerker weit weg von zu Hause enthalten diese Behälter alles, was für einen Neuanfang erforderlich ist.",al={"felix' kasten","felix' truhe","was ist in felix' truhe"}}},fp="20,283,26.396.0,22.399.0,25.243.0,29.266.0,29.221.0,43.182.0,42.237.0,61.221.0"}
P.entries["quest:3364"] = {n="Lieferung des kochend heißen Morgengebräus",s="„Lieferung des kochend heißen Morgengebräus“ ist eine eilige Besorgung durch das Coldridgetal, um ein frisches heißes Getränk abzuliefern, bevor es im Bergfrost abkühlt. Nori Stolzmut vertraut die Lieferung einem Abenteurer an, um sicherzustellen, dass Durnan Pelznaht sein Morgengebräu kochend heiß erhält.",h="„Lieferung des kochend heißen Morgengebräus“ ist eine eilige Besorgung durch das Coldridgetal, um ein...",kw={"ambossar","das coldridgetal","dun morogh","durnan pelznaht","morgengebräu","nori stolzmut"},ang={["profession:Cooking"]="Getränke bei der richtigen Temperatur zu servieren, ist ein Zeichen wahrer kulinarischer Ehrerbietung – besonders unter den unerbittlichen Minusgraden von Dun Morogh.",["race:Dwarf"]="Jeder Zwerg versteht die Tragödie kalten Gebräus in eisiger Bergluft, was diesen Spurt quer durch das Tal zu einer reinen Prinzipsache macht."},sec={{t="Ein Wettlauf gegen den Frost",b="Die beißende Kälte von Dun Morogh hat schon so manche heiße Mahlzeit ruiniert, und Morgengebräu bildet da keine Ausnahme. Nachdem er eine Lieferung an Grelin Weißbart abgeschlossen hat, bemerkt Nori Stolzmut, dass ihm die Zeit fehlt, um einen weiteren frischen Becher nach Ambossar zu bringen, bevor er zu einem ungenießbaren Matsch gefriert. Anstatt seinen Kunden zu enttäuschen, spannt er jeden schnellen Reisenden ein, der bereit ist, dem Schnee zu trotzen."},{t="Der Preis eines warmen Bechers",b="Durnan Pelznaht, der in der Wärme von Ambossars Berghalle stationiert ist, gilt bei seinen Erfrischungen als wählerisch. Kaltes Morgengebräu kommt einfach nicht infrage. Das dampfende Getränk unversehrt abzuliefern, verschafft einem müden Zwerg eine wohlverdiente Pause von seinen Pflichten – auch wenn Nori dennoch erwartet, dass sein Lieblingsbecher in einem Stück zurückgebracht wird."}},faq={{q="Wer ist Durnan Pelznaht?",a="Durnan Pelznaht ist ein Zwerg, der in der unterirdischen Halle von Ambossar im Coldridgetal lebt. Er verlässt sich für sein heißes Morgengebräu auf lokale Lieferungen von Nori Stolzmut.",al={"durnan pelznaht","wer ist durnan","furcutter"}},{q="Warum muss die Lieferung so schnell erfolgen?",a="Das eisige alpine Wetter des Coldridgetals sorgt dafür, dass heiße Getränke rasch abkühlen. Durnan hat ausdrücklich kochend heißes Morgengebräu bestellt, und kaltes Bier oder kalter Tee gilt nach Zwergenmaßstäben als verdorben.",al={"warum mit zeitlimit","morgengebräu zeitlimit","warum beeilen"}},{q="Wer ist Nori Stolzmut?",a="Nori Stolzmut ist ein Zwerg, der auf den verschneiten Pfaden des Coldridgetals stationiert ist. Er kümmert sich um Lieferungen zwischen den örtlichen Lagern und bringt unter anderem Getränke zu Grelin Weißbart und zu den Arbeitern in Ambossar.",al={"nori stolzmut","nori","wer ist nori"}},{q="Was ist Morgengebräu?",a="Morgengebräu ist ein warmes, belebendes zwergisches Gebräu für den Morgen, das entwickelt wurde, um die frostige Kälte der Gipfel von Dun Morogh zu vertreiben und abgehärtete Bergarbeiter zu stärken.",al={"was ist morgengebräu","morgengebräu hintergrund"}},{q="Wo befindet sich Ambossar?",a="Ambossar liegt direkt nordöstlich von Noris Posten und ist in den Bergfels des Coldridgetals gehauen, um junge Gebirgsjäger und Handwerker vor den Schneestürmen zu schützen.",al={"wo ist ambossar","standort ambossar","ambossar finden"}},{q="Möchte Nori den Becher zurückhaben?",a="Ja. Sobald Durnan sein heißes Gebräu ausgetrunken hat, gibt er das leere Gefäß zurück, damit es wieder zu Nori ins Coldridgetal gebracht werden kann.",al={"becher zurückbringen","den becher zurückbringen","noris becher"}}},fx={["77d8ea01"]={q="Warum möchte Nori Stolzmut, dass das Morgenbräu ausgeliefert wird?",a="Nori sollte frisches, kochend heißes Morgenbräu an Durnan Pelznaht ausliefern, aber eine frühere Lieferung an Grelin Weißbart hielt ihn auf. Durnan erwartet sein Gebräu speziell kochend heiß, nicht lauwarm oder kalt, daher bemüht sich Nori, das Getränk nach Ambossar zu bringen, bevor es vollständig abkühlt.",al={"warum morgenbräu ausliefern","nori motiv","warum muss das von nori ausgeliefert werden"}},["4fdc3467"]={q="Warum bittet Nori Euch, es auszuliefern, anstatt es selbst zu bringen?",a="Nori ist bereits in Verzug geraten, nachdem er angehalten hatte, um Grelin Weißbart zu bedienen. Da er weiß, dass das Gebräu nur für wenige kurze Minuten kochend heiß bleibt, erkennt er, dass er den Bergpfad aus eigener Kraft nicht schnell genug hinaufsprinten kann. Als er Euch sah, verließ er sich auf Eure frischen Beine, um nach Ambossar zu eilen, bevor das Getränk kalt wird.",al={"warum braucht nori mich","warum kann nori es nicht ausliefern","warum ich nori lieferung"}}},fp="26,254,24.351.0,23.318.0,24.171.0,41.190.0,23.202.0,17.156.0,26.169.0,28.133.0"}
P.entries["quest:3365"] = {n="Den Becher zurückbringen",s="Nachdem ein kochend heißer Schluck Mornbrew durch die Schneewehen von Dun Morogh geliefert wurde, bleibt noch eine letzte Besorgung: den leeren Humpen zurückzubringen. Durnan Pelznaht schickt den Boten zurück durch das Coldridgetal, um Nori Stolzmuts geschätzten Becher zurückzubringen. Es ist eine einfache Höflichkeit, die der Brauverkäufer jedoch zutiefst zu schätzen weiß.",h="Nachdem ein kochend heißer Schluck Mornbrew durch die Schneewehen von Dun Morogh geliefert wurde, bleibt noch...",kw={"den becher zurückbringen","dun morogh","durnan pelznaht","kharanos","mornbrew","nori stolzmut","humpen"},ang={["profession:Cooking"]="Jeder ordentliche Koch oder Brauer weiß, dass guter Service erst endet, wenn das Geschirr vollzählig in die Küche zurückgebracht wurde.",["race:Dwarf"]="Jeder Zwerg weiß, dass das Behalten des Humpens eines Wirts der schnellste Weg zu einer Schlägerei ist; Noris Becher zurückzubringen, gehört zum zwergischen Grundanstand."},sec={{t="Eine Frage der Tavernen-Etikette",b="In der schneidenden Kälte von Dun Morogh kochend heißen Mornbrew auszuschenken, ist ein heikles Geschäft. Sobald Durnan Pelznaht seine Knochen mit dem brühend heißen Gebräu gewärmt hat, kann der leere Humpen nicht einfach in den Schnee geworfen werden. Zwergische Gastfreundschaft beruht auf gegenseitigem Respekt, und gutes Geschirr verschwinden zu lassen, ist ein sicherer Weg, bei zukünftigen Runden leer auszugehen."},{t="Becher wachsen nicht auf Bäumen",b="Die Rückkehr in das Coldridgetal schließt den Lieferauftrag für Nori Stolzmut ab. Wie Nori vergessliche Kuriere gerne erinnert, wächst robustes Trinkgeschirr keineswegs auf Bäumen – schon gar nicht in den eisigen Klüften der Zwergenheimat. Das unversehrte Zurückbringen des leeren Gefäßes festigt den Ruf eines Abenteurers als verlässliche Hilfe in der hiesigen Gemeinschaft."}},faq={{q="Wer startet diese Besorgung?",a="Durnan Pelznaht gibt Euch diese Aufgabe unmittelbar, nachdem Ihr ihm das frisch gebraute Mornbrew draußen in Dun Morogh überbracht habt.",al={"questgeber","wer vergibt den becher zurückbringen","durnan pelznaht quest"}},{q="Wem bringe ich den Becher zurück?",a="Ihr bringt den leeren Becher zu Nori Stolzmut zurück, der durch das Coldridgetal in Dun Morogh wandert und sein Mornbrew verkauft.",al={"wohin mit dem becher","wer bekommt den becher","nori aufenthaltsort"}},{q="Gibt es ein Zeitlimit, um den Becher zurückzubringen?",a="Nein. Während die anfängliche Lieferung des brühend heißen Mornbrew ein striktes Zeitlimit hatte, damit das Getränk kochend heiß blieb, könnt Ihr den leeren Becher in Eurem eigenen Tempo zurückbringen.",al={"hat diese quest ein zeitlimit","becher timer","muss man sich beeilen"}},{q="Warum liegt Nori so viel an einem leeren Becher?",a="Hochwertige Becher und Humpen sind wertvolles Barzubehör in Dun Morogh. Wie Nori betont, wachsen Becher nicht auf Bäumen, und Tavernen können es sich nicht leisten, ihr Trinkgeschirr an jeden vorbeikommenden Kurier zu verlieren.",al={"warum will nori den becher zurück","bedeutung des bechers"}},{q="Welche Quest führt direkt zu dieser?",a="Diese Besorgung ist die direkte Fortsetzung von 'Scalding Mornbrew Delivery' und beginnt in dem Moment, in dem Durnan das Getränk trinkt, das Ihr ihm gebracht habt.",al={"vorherige quest","was kommt vor den becher zurückbringen"}},{q="Wo ist Durnan Pelznaht zu finden?",a="Durnan Pelznaht ist ein Händler für Rüstung aus Tuch und aus Leder und hält sich in Ambossar auf, der in den Berg gehauenen Siedlung im Coldridgetal.",al={"durnan aufenthaltsort","wo ist durnan"}}},fx={aa771bb6={q="Warum möchte Durnan Pelznaht, dass dies erledigt wird?",a="Durnan Pelznaht hat gerade das kochend heiße Morgenbräu genossen, das von Nori im Das Coldridgetal geliefert wurde, um die Kälte zu vertreiben. Den leeren Krug zurückzugeben, ist einfache Höflichkeit gegenüber Nori Stolzmut, der seine Glaswaren zurückerwartet, anstatt Kuriere sie verstreut im eisigen Schnee von Dun Morogh liegen zu lassen.",al={"warum krug zurückgeben","durnan krug zurückgeben","warum den krug zurückschicken"}}},fp="18,313,28.361.0,24.354.0,23.120.0,27.109.0,40.158.0,46.176.0,40.133.0,36.135.0"}
P.entries["quest:3369"] = {n="Alptraum",s="Alptraum ist eine Quest der Horde, die einen Abenteurer damit beauftragt, ein beunruhigendes Relikt, den Alptraumsplitter, zu Erzdruide Hamuul Runentotem auf der Anhöhe der Ältesten in Donnerfels zu bringen. Ursprünglich als leuchtendes Fragment aus den Höhlen des Wehklagens geborgen, offenbart der Splitter eine zutiefst beunruhigende Verderbnis, die in den Smaragdgrünen Traum sickert.",h="Alptraum ist eine Quest der Horde, die einen Abenteurer damit beauftragt, ein beunruhigendes Relikt, den...",kw={"die anhöhe der ältesten","smaragdgrüner traum","falla weisenwind","leuchtender splitter","hamuul runentotem","alptraum","alptraumsplitter","donnerfels","die höhlen des wehklagens"},ang={["class:Druid"]="Für Druiden ist der Splitter ein zutiefst alarmierender Beweis dafür, dass die unberührte Unversehrtheit des Smaragdgrünen Traums gefährdet ist, was das Geflüster über die im Zirkel des Cenarius um sich greifende Verderbnis bestätigt.",["faction:Horde"]="Die Abgabe des Splitters sichert das spirituelle Wohl des zentralen Kalimdor und beweist, dass die Horde eine entscheidende Rolle bei der Eindämmung der pilzartigen und traumgeborenen Verderbnis spielt, die aus dem Brachland quillt.",["race:Tauren"]="Die Rückkehr zu Erzdruide Hamuul Runentotem unterstreicht die wachsende Bedeutung der Taurendruiden innerhalb des Zirkels des Cenarius, während sie sich an der Seite ihrer nachtelfischen Lehrer uralten kosmologischen Bedrohungen stellen."},sec={{t="Eine beunruhigende Entdeckung",b="Nachdem Falla Weisenwind den seltsamen Kristall aus den Tiefen der Höhlen des Wehklagens untersucht hat, erkennt sie, dass er aus der reinen Essenz des Smaragdgrünen Traums besteht. Doch die Vision in seinem Inneren ist finster und chaotisch und trägt nicht das Zeichen friedlichen Schlummers, sondern das eines wachen Alptraums. Da sie davor zurückschreckt, offen über solch alarmierende Omen zu sprechen, vertraut sie Euch den Splitter an, mit der Anweisung, Donnerfels' verehrtesten Ältestendruiden aufzusuchen: Erzdruide Hamuul Runentotem."},{t="Ein Geheimnis im Traum",b="Als ihm der Alptraumsplitter auf der Anhöhe der Ältesten überreicht wird, gerät Hamuul Runetotems gewohnte Gelassenheit beim Blick in sein Inneres ins Wanken. Konfrontiert mit handfesten Beweisen dafür, dass der Smaragdgrüne Traum in einen Alptraum zerfällt, wählt der Erzdruide seine Worte mit Bedacht. Er rät nachdrücklich zur Diskretion, warnt davor, dass diese heiklen Angelegenheiten das Verständnis gewöhnlicher Reisender weit übersteigen, und beschließt im Stillen, dem unsichtbaren Leiden nachzugehen, welches das Reich des Schlummers bedroht."}},faq={{q="Was ist der Alptraumsplitter?",a="Der Alptraumsplitter ist die gereinigte Form des leuchtenden Splitters, der von den mutierten Bestien in den Höhlen des Wehklagens erbeutet wurde. Obwohl er aus der reinen spirituellen Essenz des Smaragdgrünen Traums geschmiedet wurde, birgt er eine üble, verdrehte Vision, die darauf hinweist, dass im Traum etwas schrecklich schiefgelaufen ist.",al={"was ist der alptraumsplitter","leuchtender splitter alptraum","was hat falla gefunden"}},{q="Wer ist Falla Weisenwind?",a="Falla Weisenwind ist eine kundige Taurendruidin, die sich am Berghang mit Blick auf die Höhlen des Wehklagens im Brachland aufhält. Sie erforscht die anomalen Phänomene, die aus den verderbten Oasenhöhlen dringen, und schickt Kuriere der Horde zu Hamuul Runentotem, wenn gefährliche Relikte entdeckt werden.",al={"falla weisenwind","wer gab mir diese quest","questgeber"}},{q="Wo finde ich Erzdruide Hamuul Runentotem?",a="Erzdruide Hamuul Runentotem verweilt auf der Anhöhe der Ältesten, einer der erhabenen Mesas von Donnerfels. Man findet ihn inmitten des druidischen Zirkels an der Seite seiner Mitstreiter aus dem Zirkel des Cenarius.",al={"wo ist hamuul","hamuul runentotem aufenthaltsort","anhöhe der ältesten hamuul"}},{q="Warum möchte Hamuul den Splitter geheim halten?",a="Der Smaragdgrüne Traum ist die heilige Zuflucht der Natur und der schlummernden Druiden. Handfeste Beweise dafür, dass er zu einem Alptraum verzerrt wird, könnten im Zirkel des Cenarius weitreichende Panik auslösen und die zerbrechlichen Bemühungen um die spirituelle Wiederherstellung Kalimdors untergraben, weshalb Hamuul zu Stillschweigen mahnt.",al={"warum geheim halten","hamuul geheimnis","warum versteckt hamuul den splitter"}},{q="Gibt es eine Allianz-Version dieser Quest?",a="Ja. Während Streiter der Horde den Alptraumsplitter zu Erzdruide Hamuul Runentotem in Donnerfels bringen, werden Allianz-Spieler, welche Die Höhlen des Wehklagens untersuchen, angewiesen, ihren Splitter über das Meer nach Darnassus zu bringen und ihn dem Druiden Mathrengyl Bärenfährte vom Zirkel des Cenarius vorzulegen.",al={"allianz version","alptraum allianz","kann die allianz das machen"}},{q="Welcher Zusammenhang besteht zu den Höhlen des Wehklagens?",a="Der Splitter stammt aus den Höhlen des Wehklagens, wo der Druide Naralex in eine tiefe Trance fiel, um unterirdische Quellen in das Brachland zu leiten. Statt das Land zu heilen, verwandelte sich Naralex' Schlummer in einen wachen Alptraum, der die Fauna der Höhle mutieren ließ und in Kristallsplitter wie diesen überging.",al={"höhlen des wehklagens verbindung","naralex verbindung","wie hängt dies mit naralex zusammen"}}},fx={d74ecb00={q="Warum möchte Falla Weisenwind, dass der Alptraumsplitter an Hamuul Runetotem ausgeliefert wird?",a="Als Falla Weisenwind den Splitter untersucht, erkennt sie ihn als reine Essenz des Der Smaragdgrüne Traum, jedoch befleckt von Visionen eines wachen Alptraums. Beunruhigt von dem, was sie sieht, erkennt sie, dass die Entdeckung viel zu gefährlich und bedeutsam ist, als dass sie allein damit umgehen könnte. Sie weigert sich, weiter darüber zu sprechen und besteht darauf, dass Ihr ihn sofort zum Erzdruide Hamuul Runetotem nach Donnerfels bringt, da sie nur einem der ranghöchsten und weisesten Druiden des Zirkel des Cenarius zutraut, ein solch schlimmes Omen zu verstehen und zu bewältigen.",al={"warum splitter an hamuul schicken","warum möchte falla das erledigt haben","falla weisenwind motiv"}}},fp="13,325,22.482.0,21.463.1,28.285.0,22.283.0,45.197.0,48.296.0,47.288.0,44.297.0"}
P.entries["quest:337"] = {n="Ein altes Geschichtsbuch",s="Dieser mitgenommene Wälzer, der aus dem verheerten Boden und den monströsen Höhlen des Dämmerwalds geborgen wurde, trägt den offiziellen Stempel der Royal Library von Sturmwind. Unter dem Titel 'Die Geschichte von Sturmwind' verschwand er noch vor dem Wiederaufbau des Königreichs nach dem Ersten Krieg. Seine Rückgabe bringt Chefbibliothekar Milton Garbenbund eine verlorene Chronik zurück und leitet das Bestreben ein, die Geschichte der südlichen Menschen zu bewahren.",h="Dieser mitgenommene Wälzer, der aus dem verheerten Boden und den monströsen Höhlen des Dämmerwalds geborgen...",kw={"ein altes geschichtsbuch","dämmerwald","milton garbenbund","wissen bewahren","süderstade","burg sturmwind","bibliothek von sturmwind","the history of stormwind"},ang={["class:Mage"]="Gelehrte des Arkanen wissen, dass alte Bibliotheken Wissen bergen, das dem Verfall und der Vernachlässigung preisgegeben ist, wenn es in der Wildnis zurückbleibt.",["faction:Alliance"]="Die Bergung von Vorkriegstexten stellt Fragmente von Sturmwinds verlorenem Erbe wieder her, die die Verwüstung des Ersten Krieges überstanden haben.",["race:Human"]="Für die Menschen des Südens ist die Rückholung schriftlicher Aufzeichnungen aus der Wildnis ein entscheidender Schritt beim Wiederaufbau der durch die Alte Horde zerstörten Kultur."},sec={{t="Ein Relikt des Ersten Krieges",b="Dieser schlammverkrustete Band, der inmitten der feindseligen Untoten und brutalen Oger des Dämmerwalds entdeckt wurde, ist ein seltenes überlebendes Artefakt aus der Zeit vor Sturmwinds Zerstörung. Mit dem offiziellen Bibliothekssiegel des Königreichs auf der ersten Seite versehen, wurde er vor Jahrzehnten ausgeliehen – noch bevor die Horde die Hauptstadt dem Erdboden gleichmachte – und galt im Zuge des Falls des Südens als für immer verloren."},{t="Vergessene Annalen wiederherstellen",b="Wird das Buch zu Milton Garbenbund in die Royal Library von Burg Sturmwind zurückgebracht, erkennt er darin einen unschätzbaren Schatz, der für das Archiv seltener Bücher bestimmt ist. Jahrelange Witterung in der heimgesuchten Wildnis hat seinen Seiten schwer zugesetzt, und der Fund spornt Sheaf dazu an, weiteres verlorenes Wissen wiederzuerlangen, wobei sein Blick nach Norden nach Süderstade wandert, der Stadt, die dem zerstörten Königreich Alterac und seinen verlassenen Bibliotheken am nächsten liegt."}},faq={{q="Wo wird dieses Buch gefunden?",a="Das Buch wird von verschiedenen feindseligen Kreaturen im Dämmerwald erbeutet, am häufigsten von den Untoten, die die Friedhöfe und Felder heimsuchen, oder den Ogern, die die südlichen Hügel besetzen.",al={"wo man das alte geschichtsbuch findet","fundort des buches","geschichtsbuch dämmerwald"}},{q="Zu wem bringe ich das Buch?",a="Ihr bringt den Band zu Milton Garbenbund zurück, dem Chefbibliothekar in der Royal Library innerhalb von Burg Sturmwind.",al={"abgabeort","wo gebe ich das ab","milton garbenbund aufenthaltsort"}},{q="Warum ist das Buch in so schlechtem Zustand?",a="Das Buch wurde vor dem Ersten Krieg und der Plünderung von Sturmwind ausgeliehen. Es überdauerte Jahrzehnte in der Wildnis des Dämmerwalds, gezeichnet von Schmutz, Fäulnis und den Händen umherstreifender Plünderer und Monster.",al={"warum ist es schlammig","warum beschädigt"}},{q="Führt die Rückgabe dieses Buches zu weiteren Aufgaben?",a="Ja. Milton Garbenbund wird Euch nach Norden nach Süderstade im Vorgebirge des Hügellands schicken, um mit Loremaster Dibbs zu sprechen, der Euch zu Büchern leiten kann, die noch immer in den Ruinen von Alterac liegen.",al={"wie geht es weiter","folgequest","buch-questreihe"}},{q="Warum bedeutet Milton Garbenbund ausgerechnet dieser Band so viel?",a="Da das ursprüngliche Königreich während des Ersten Krieges dem Erdboden gleichgemacht wurde, überstanden nur wenige originale historische Aufzeichnungen den Brand der Stadt. Die Bergung echter Vorkriegstexte hilft Gelehrten dabei, die Vergangenheit des Königreichs zu rekonstruieren.",al={"warum ist das buch wichtig","bedeutung von the history of stormwind"}},{q="Können Horde-Spieler diese Quest abschließen?",a="Nein. Das Buch gehört der Royal Library von Sturmwind und kann nur bei Bibliothekaren der Allianz in Burg Sturmwind abgegeben werden.",al={"horde-version","ist das nur für die allianz"}}},fp="19,380,24.358.0,26.404.0,25.166.0,27.110.0,39.201.0,45.175.0,60.208.0,38.126.0"}
P.entries["quest:3370"] = {n="Alptraum",s="Nach der Entdeckung eines seltsamen leuchtenden Splitters erkennt Falla Weisenwind, dass das Artefakt die reine Essenz des Smaragdgrünen Traums enthält, die jedoch von dunklen Visionen verdorben wurde. Sie schickt einen Abenteurer nach Darnassus, um das beunruhigende Relikt direkt den älteren Druiden des Zirkels des Cenarius zu überbringen.",h="Nach der Entdeckung eines seltsamen leuchtenden Splitters erkennt Falla Weisenwind, dass das Artefakt die...",kw={"zirkel des cenarius","die enklave des cenarius","darnassus","smaragdgrüner traum","falla weisenwind","leuchtender splitter","alptraum","mathrengyl bärenfährte","alptraumsplitter"},ang={["class:Druid"]="Für Druiden offenbart diese Quest, dass der heilige Smaragdgrüne Traum nicht der unberührte Zufluchtsort ist, mit dem sie zu kommunizieren gelehrt wurden, was auf eine tiefgreifende innere Gefahr hindeutet.",["faction:Alliance"]="Allianz-Abenteurer, die dieses Relikt in das Herz von Darnassus tragen, gewähren der Führung der Nachtelfen einen frühen Einblick in die Verderbnis, die sich unter der Oberfläche der Welt ausbreitet.",["race:NightElf"]="Nachtelfen verehren das schlummernde Reich, in dem Malfurion Sturmgrimm weilt; einen wachen Alptraum in dessen Essenz zu entdecken, trifft den Kern ihres spirituellen Erbes."},sec={{t="Eine beunruhigende Enthüllung",b="Der leuchtende Splitter, der aus den Tiefen der Höhlen des Wehklagens geborgen wurde, erweist sich als weitaus gefährlicher als ein einfacher Kristall. Bei seiner Untersuchung identifiziert Falla Weisenwind ihn als eine Verkörperung der reinsten Essenz des Smaragdgrünen Traums. Doch statt die saftig grüne Vollkommenheit des urzeitlichen Bauplans von Azeroth widerzuspiegeln, windet sich der Stein vor verstörenden, furchterregenden Visionen. Erschüttert von dem, was sie sieht, weigert sich Falla, selbst tiefer nachzuforschen, und besteht darauf, dass der Splitter sicher zur Führungsriege des Zirkels des Cenarius gebracht werden muss."},{t="Geflüster in der Enklave des Cenarius",b="In Darnassus wird das Relikt Mathrengyl Bärenfährte vorgelegt, einem erfahrenen Druiden in der Enklave des Cenarius. Zunächst mit ruhiger Neugier empfangen, ist Mathrengyl sichtlich beunruhigt, sobald er in das Innere des Splitters blickt. Als er erkennt, dass das Verderben, welches das Brachland heimsucht, direkt mit Störungen tief im Smaragdgrünen Traum selbst zusammenhängt, bringt er jede weitere Diskussion rasch zum Schweigen. Der ältere Druide warnt davor, dass derart schreckliche Anomalien nichts für gewöhnliche Ohren sind, und nimmt den Alptraumsplitter still in seine Obhut, um den vordringenden Schatten zu untersuchen."}},faq={{q="Was ist der Alptraumsplitter?",a="Der Alptraumsplitter ist ein kristallisiertes Stück der Essenz des Smaragdgrünen Traums, das ursprünglich als mysteriöser Leuchtender Splitter geborgen wurde. Anstatt natürlicher Harmonie strahlt er finstere Visionen und verderbliche Macht aus, was offenbart, dass eine unheilvolle Präsenz begonnen hat, in den Traum einzudringen.",al={"was ist der alptraumsplitter","leuchtender splitter lore","smaragdgrüner traum splitter"}},{q="Wer ist Falla Weisenwind?",a="Falla Weisenwind ist eine Tauren-Druidin der Naturkunde, die seltsame Relikte untersucht, die in der Wildnis gefunden werden. Als sie den wahren, schrecklichen Ursprung des leuchtenden Splitters erkennt, verweist sie Reisende an höhere druidische Autoritäten in Darnassus.",al={"falla weisenwind","wer ist falla"}},{q="Wer ist Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte ist ein älterer Druidenausbilder des Zirkels des Cenarius, der in der Enklave des Cenarius in Darnassus stationiert ist. Er fungiert als erfahrener Mentor und untersucht schwerwiegende spirituelle Bedrohungen, die die Natur und den Smaragdgrünen Traum betreffen.",al={"mathrengyl bärenfährte","bearwalker darnassus","wer ist mathrengyl"}},{q="Warum ist Mathrengyl bezüglich des Splitters so verschwiegen?",a="Der Smaragdgrüne Traum wird als das unberührte, unantastbare Reich der Natur verehrt, das vom Grünen Drachenschwarm und den schlafenden Druiden behütet wird. Beweise dafür, dass dieses Reich unter alptraumhafter Verderbnis leidet, stellen eine tiefgreifende spirituelle Krise dar, die der Zirkel des Cenarius nur ungern an die Öffentlichkeit dringen lässt.",al={"warum geheim","was verbirgt mathrengyl","warum schweigt mathrengyl"}},{q="Wo beginnt diese Questreihe?",a="Die Geschichte beginnt mit 'Der leuchtende Splitter', einem Gegenstand, den man von Mutanus dem Verschlinger am Ende der Höhlen des Wehklagens erbeutet. Dieser Splitter wird Gelehrten überbracht, die seine unheilvollen Ursprünge schließlich nach Darnassus oder Donnerfels zurückverfolgen.",al={"alptraum voraussetzungen","wo begann das","wie startet alptraum"}},{q="Haben Horde-Spieler eine entsprechende Quest?",a="Ja. Während Allianz-Helden Mathrengyl Bärenfährte in Darnassus Bericht erstatten, überbringen Horde-Streiter ihre Funde Hamuul Runentotem auf der Anhöhe der Ältesten in Donnerfels und erfahren dieselben beunruhigenden Neuigkeiten über den Smaragdgrünen Traum.",al={"horde version","gibt es eine horde-version von alptraum","alptraum horde"}}},fx={da5fa45e={q="Warum möchte Falla Weisenwind, dass der Alptraumsplitter ausgeliefert wird?",a="Falla Weisenwind erkannte, dass der Splitter die Essenz des Der Smaragdgrüne Traum enthält, aber die Vision, die sie darin erhaschte, war tief in einen Alptraum verdreht. Alarmiert von dem, was sie sah, und im Wissen, dass eine solch bedrohliche Verderbnis weit über ihr Verständnis hinausgeht, besteht sie darauf, dass er umgehend von einem weisen Druiden des Zirkel des Cenarius in Darnassus untersucht wird.",al={"warum den splitter nach darnassus schicken","warum möchte falla das erledigt haben","falla weisenwind motiv"}}},fp="13,294,22.507.0,32.552.1,28.278.1,22.231.0,29.234.0,47.298.1,34.237.0,42.229.0"}
P.entries["quest:3376"] = {n="Tötet Spitzhauer!",s="Break Sharptusk! ist ein entscheidendes Initiationsritual, das von Kriegerheldin Windfeather auf Die Hochwolkenebene ausgegeben wird. Um die Heimat der Tauren gegen fortwährende Überfälle zu sichern, werden junge Champions in den Osten in die Dornrankenklamm entsandt, um Häuptling Sharptusk Thornmantle zu erschlagen. Die Beseitigung des Häuptlings der Borstennacken ist ein schwerer Schlag gegen die Stachelquillensippe, die in Mulgore eindringt.",h="Break Sharptusk!",kw={"dornrankenklamm","borstennacken","mulgore","narache","stachelquillensippe","die hochwolkenebene","sharptusk","thornmantle","windfeather"},ang={["class:Hunter"]="Für Jäger ist diese Quest die ultimative frühe Prüfung: das Aufspüren einer Beute, die über eigene List, Waffen und die Absicht verfügt, Euch im Gegenzug zu jagen.",["faction:Horde"]="Durch die Hinrichtung von Häuptling Sharptusk demonstrieren Verbündete der Horde ihr Engagement für die Stabilisierung von Mulgore und die Sicherung friedlicher Ländereien für ihre neuen Taurenbrüder.",["race:Tauren"]="Sharptusk Thornmantle zu erschlagen ist eine der letzten Prüfungen, die ein junger Taure absolviert, bevor er Camp Narache verlässt, und beweist, dass er die Entschlossenheit besitzt, die Stämme gegen feindselige Nachbarn zu verteidigen."},sec={{t="Ein in Blut gewonnenes Zuhause",b="Die grasbewachsenen Höhen der Die Hochwolkenebene dienten lange Zeit als friedlicher Zufluchtsort, an dem junge Tauren die Traditionen der Jagd und die Einstimmung auf die Erdenmutter erlernen. Doch dieser Friede ist ständig bedroht. Im Osten liegt die Dornrankenklamm, eine von Dornen überwucherte Schlucht, die vom feindseligen Stamm der Borstennacken-Stachelquillensippe beansprucht wird. Die Stachelquillensippe betrachtet die Tauren als Eindringlinge, die heiligen Boden stehlen, und führt unerbittliche Scharmützel gegen die Stämme, die versuchen, ein stabiles Leben in Mulgore aufzubauen."},{t="Die Bedrohung durch Thornmantle",b="Die anhaltenden Angriffe auf die Ebene sind kein zielloser Wahnsinn; sie werden unter der brutalen Führung von Häuptling Sharptusk Thornmantle koordiniert. Sharptusk residiert in einem befestigten provisorischen Dorf tief in der Schlucht und lenkt seine Krieger und Geomanten gegen die Shu'halo. Da Kriegerheldin Windfeather erkennt, dass die Borstennacken ihre Überfälle niemals einstellen werden, solange ihr Häuptling noch atmet, befiehlt sie einem aufstrebenden Helden, in die Schlucht einzudringen, Thornmantle zu erschlagen und als Beweis mit seinem abgetrennten Kopf zurückzukehren."},{t="Die Lektionen der Jagd",b="Für junge Tauren und ihre Verbündeten ist die Jagd auf Sharptusk mehr als eine einfache Hinrichtung – es ist eine Einführung in die harten Realitäten des Überlebens. Wie Kriegerheldin Windfeather lehrt, lehrt die Jagd auf Bestien Geduld, doch die Jagd auf einen Feind, der schlau genug ist, selbst zu jagen, stellt Mut, Wachsamkeit und kriegerische Disziplin auf die Probe. Sharptusk zur Strecke zu bringen, verschafft den gefallenen Verwandten Gerechtigkeit und markiert die Bereitschaft des Jägers, sich hinaus in die weiten Ebenen von Mulgore zu wagen."}},faq={{q="Wer ist Häuptling Sharptusk Thornmantle?",a="Häuptling Sharptusk Thornmantle ist der rücksichtslose Anführer der Borstennacken-Stachelquillensippe, die die Dornrankenklamm bewohnt. Unter seinem Kommando inszeniert der Stamm kontinuierlich Überfälle und Scharmützel gegen die Taurensiedlung auf Die Hochwolkenebene.",al={"wer ist sharptusk","sharptusk thornmantle hintergrundgeschichte","wer ist der stachelquillenhäuptling"}},{q="Wo kann man Häuptling Sharptusk Thornmantle finden?",a="Sharptusk residiert tief in der Dornrankenklamm, die am östlichen Rand der Die Hochwolkenebene liegt. Er überwacht seinen Stamm von ihrem provisorischen Dorf aus, das in die dornenbedeckte Schlucht eingebettet ist.",al={"wo ist sharptusk","sharptusk fundort","wie findet man sharptusk"}},{q="Wer vergibt die Quest Break Sharptusk!?",a="Die Quest wird von Kriegerheldin Windfeather angeboten, einer erfahrenen Taurenkriegerin, die Camp Narache auf Die Hochwolkenebene bewacht. Sie beauftragt vielversprechende Neulinge damit, ihren Mut zu beweisen, indem sie die Bedrohung durch die Borstennacken beseitigen.",al={"questgeber break sharptusk","wer startet break sharptusk","fundort kriegerheldin windfeather"}},{q="Warum hassen die Borstennacken-Stachelquillensippe die Tauren?",a="Stachelquillensippen glauben, dass alles Land, das mit Blutstein und heiligen Dornenranken geschmückt ist, ihnen durch das göttliche Recht ihres Halbgott-Schöpfers Agamaggan gehört. Sie betrachten die Tauren, die Siedlungen in Mulgore gründen, als eindringende Übeltäter auf ihren angestammten Jagdgründen.",al={"warum greifen stachelquillensippen an","konflikt zwischen tauren und stachelquillensippen","warum sind stachelquillensippen feindselig"}},{q="Welchen Beweis verlangt Kriegerheldin Windfeather?",a="Kriegerheldin Windfeather verlangt den abgetrennten Kopf von Häuptling Sharptusk Thornmantle. Den Kopf zu bringen beweist zweifelsfrei, dass der Anführer gefallen ist, und dient als strenge Warnung an alle verbliebenen Borstennacken.",al={"was muss man windfeather bringen","sharptusk beweis","questziel sharptusk"}},{q="Welche kulturelle Bedeutung hat diese Jagd für junge Tauren?",a="In der Kultur der Tauren kommt wahre Reife durch das Verständnis des Gleichgewichts zwischen Jäger und Gejagtem. Windfeather betont, dass das Aufspüren eines denkenden, gerissenen Gegners wie Sharptusk junge Krieger die Schwere des tödlichen Kampfes und die Verantwortung für die Verteidigung des Stammes lehrt.",al={"warum sharptusk töten hintergrund","initiation der tauren sharptusk","bedeutung der jagd"}}},fx={d0ec7fec={q="Warum möchte Kriegerheldin Windfeather, dass Häuptling Sharptusk getötet wird?",a="Die Borstennackenstacheleber führen einen unerbittlichen Feldzug gegen die Tauren der Die Hochwolkenebene und bedrohen die Sicherheit ihres neu erbauten Zuhauses. Häuptling Sharptusk Dornmantel leitet diese Überfälle aus der nahegelegenen Dornrankenklamm. Kriegerheldin Windfeather versucht, einen entscheidenden Schlag gegen ihre Führung zu führen, um das Blutvergießen zu stoppen und jedem, der die Anwesenheit der Tauren auf der Ebene in Frage stellen würde, eine feste Warnung zu übermitteln.",al={"windfeather motiv","warum sharptusk töten","warum sharptusk brechen"}},["8bbc47fc"]={q="Warum beauftragt Euch Kriegerheldin Windfeather, anstatt sich selbst um Sharptusk zu kümmern?",a="Andere erfahrene Verteidiger haben bereits versucht, den Stacheleberhäuptling zu vertreiben, sind aber gescheitert, während die verbleibenden Krieger zurückbleiben müssen, um Camp Narache zu bewachen und die Jungen vor umherstreifenden Bedrohungen zu schützen. Da sie von Eurem wachsenden Potenzial als aufstrebender Jäger gehört hat, sieht Windfeather in Euch ein ungetestetes, aber beeindruckendes Talent, das in der Lage ist, einen gerissenen Gegner zu besiegen und die wahre Bedeutung der Jagd zu lernen.",al={"warum werde ich geschickt","warum nicht die krieger","warum nicht kriegerheldin windfeather"}}},fp="16,345,19.488.0,25.507.0,23.453.0,35.229.0,47.190.0,37.205.0,48.259.0,41.200.0,64.277.0"}
P.entries["quest:343"] = {n="Reden über Kraft",s="„Reden über Kraft“ ist ein Botengang der Allianz in Sturmwind, der von Bruder Kristoff auf dem Kathedralenplatz begonnen wird. Zur Vorbereitung einer Predigt mit dem Titel „Seelenstärke“ heuert Kristoff einen Abenteurer an, um die Royal Library in Burg Sturmwind aufzusuchen und Chefbibliothekar Milton Garbenbund nach einem bestimmten technischen Text zu fragen.",h="„Reden über Kraft“ ist ein Botengang der Allianz in Sturmwind, der von Bruder Kristoff auf dem...",kw={"bruder kristoff","kathedrale des lichts","metallurgie","milton garbenbund","royal library","reden über kraft","burg sturmwind","die belastungen des eisens"},ang={["class:Priest"]="Bruder Kristoffs Predigt greift Themen spiritueller Seelenstärke auf und bietet Einblick darin, wie Sturmwinds Klerus Predigten gestaltet, indem er alltägliche Handwerkslehren mit der Hingabe an das Licht verknüpft.",["faction:Alliance"]="Der Botengang verbindet die Priesterschaft des Kathedralenplatzes direkt mit der Royal Library in Burg Sturmwind und zeigt die bürgerliche und wissenschaftliche Infrastruktur der Hauptstadt.",["profession:Blacksmithing"]="Die Predigt stützt sich auf „Die Belastungen des Eisens“ und spiegelt wider, wie selbst gelehrte Theologen auf die harten Realitäten der Schmiede zurückgreifen, um Ausdauer unter Druck zu erklären."},sec={{t="Eine Metapher in Metall",b="Bruder Kristoff, einer der in Sturmwinds Kathedrale des Lichts stationierten Priester, möchte eine Predigt über die Seelenstärke halten. Anstatt sich ausschließlich auf klerikale Schriften zu stützen, greift Kristoff auf das Handwerk der Metallbearbeitung zurück, um die Abhärtung und Widerstandskraft des Glaubens zu veranschaulichen. Konkret benötigt er eine Abhandlung namens „Die Belastungen des Eisens“, um daraus während seiner Ansprache zu zitieren, in der Hoffnung, dass ihre Lehren über das Aushalten von Druck bei seiner Gemeinde Anklang finden."},{t="Die königlichen Bestände",b="Burg Sturmwind beherbergt die Royal Library, das zentrale Archiv für Wissen, Geschichte und bürgerliche Abhandlungen des Königreichs Sturmwind. Da die Sammlung unzählige Regale und Jahrhunderte an Werken umfasst, schickt Kristoff Boten zu Milton Garbenbund, dem Chefbibliothekar. Sheaf ist stolz darauf, das Archiv auswendig zu kennen, was ihn zum einzig praktikablen Führer macht, um obskure Handwerksmanuskripte in den weitläufigen Gewölben der Feste aufzuspüren."}},faq={{q="Wer ist Bruder Kristoff?",a="Bruder Kristoff ist ein Priester im Dienst der Kirche des Heiligen Lichts auf dem Kathedralenplatz in Sturmwind. Er bittet häufig Besucher um Hilfe bei der Beschaffung von Materialien und Referenzen für seine Lehren und Predigten.",al={"kristoff","wer vergibt reden über kraft","bruder kristoff"}},{q="Welches Buch sucht Bruder Kristoff?",a="Er sucht nach einem technischen Text mit dem Titel „Die Belastungen des Eisens“, einem Lehrwerk über Metallurgie, das er als Metapher für spirituelle Ausdauer zitieren möchte.",al={"welches buch","die belastungen des eisens","kristoff buch"}},{q="Wer ist Milton Garbenbund?",a="Milton Garbenbund ist der Chefbibliothekar der Royal Library in Burg Sturmwind. Er beaufsichtigt die riesige Sammlung des Reiches an Büchern, Schriftrollen und städtischen Aufzeichnungen und kennt die Bestände in- und auswendig.",al={"milton garbenbund","bibliothekar sturmwind","chefbibliothekar"}},{q="Wo befindet sich die Royal Library?",a="Die Royal Library liegt im nordöstlichen Flügel von Burg Sturmwind und ist direkt über die Haupthalle des königlichen Palastes zugänglich.",al={"bibliothek standort sturmwind","wo ist royal library","burg sturmwind bibliothek"}},{q="Warum braucht ein Priester ein Buch über Metallurgie?",a="Bruder Kristoff verfasst eine Predigt mit dem Titel „Seelenstärke“. Er beabsichtigt, die physischen Belastungen, denen Eisen beim Schmieden ausgesetzt ist, als Allegorie dafür zu nutzen, wie der menschliche Geist unter Prüfungen gestärkt wird.",al={"warum metallurgie","warum eisenbuch","seelenstärke predigt"}},{q="Hat Milton Garbenbund das Buch sofort griffbereit?",a="Milton Garbenbund bestätigt, dass die Bibliothek Werke über Metallurgie beherbergt, muss jedoch den genauen Titel prüfen und die Suche koordinieren, sobald er angesprochen wird, was den Prozess zum Auffinden von Kristoffs Text in Gang setzt.",al={"hat sheaf das buch","abgabe reden über kraft"}}},fp="21,314,19.460.0,16.440.0,24.215.0,42.166.0,20.196.0,35.133.0,41.212.0,49.195.0"}
P.entries["quest:344"] = {n="Bruder Paxton",s="Bruder Paxton ist ein Botengang, der Abenteurer aus Sturmwinds königlichen Archiven zur Abtei von Nordhain führt. Bibliothekar Milton Garbenbund schickt Suchende dorthin, um eine geliehene zwergische Bergbauabhandlung aufzuspüren, die nie den Weg zurück in die Regale der Stadt fand.",h="Bruder Paxton ist ein Botengang, der Abenteurer aus Sturmwinds königlichen Archiven zur Abtei von Nordhain...",kw={"bruder paxton","margulf blaggon","milton garbenbund","abtei von nordhain","bibliothek von sturmwind","die belastbarkeit des eisens","abschrift"},ang={["class:Priest"]="Ein Besuch bei Bruder Paxton gewährt einen Einblick in die wissenschaftlichen Pflichten der Nordhain-Kleriker, die Folianten mühsam von Hand abschreiben, um Wissen für den Orden zu bewahren.",["faction:Alliance"]="Diese Aufgabe verdeutlicht den kulturellen Austausch zwischen Sturmwind und Eisenschmiede, da menschliche Bibliotheken grundlegende Zwergentexte aktiv bewahren und studieren.",["profession:Mining"]="Das Objekt Eurer Suche, Margulf Blaggons „Die Belastbarkeit des Eisens“, verkörpert jahrzehntelanges, hart erarbeitetes Zwergenwissen über den Bergbau, das direkt den Bergen von Khaz Modan abgerungen wurde.",["race:Dwarf"]="Der gesuchte Foliant ist zwergisches Handwerk in seiner reinsten Form, verfasst vom Bergarbeiter Margulf Blaggon und hoch genug geschätzt, dass Sturmwinds Schreiber nach Abschriften verlangen."},sec={{t="Ein geliehener Band",b="Wenn Gelehrte in Sturmwind nach seltenem Fachwissen suchen, stellt Oberbibliothekar Milton Garbenbund oft fest, dass seine Sammlung verstreut ist. Eine bemerkenswerte Abhandlung über metallurgische Verfahren, „Die Belastbarkeit des Eisens“ vom zwergischen Prospektor Margulf Blaggon, fehlt in den Regalen der Hauptstadt. Anstatt in der Hauptstadt verlegt worden zu sein, wurde sie vor Monaten an die Kleriker der Abtei von Nordhain zur Abschrift verliehen."},{t="Nordhains Schreiber",b="Die Aufgabe, Literatur abzuschreiben und zu bewahren, fällt Bruder Paxton zu, dem Hüter der Bibliothek der Abtei. Obwohl der Heilige Orden der Kleriker von Nordhain Wissen hoch schätzt, ist das manuelle Abschreiben langwieriger Fachmanuskripte mühsam und langsam. Auf frischer Tat mit dem überfälligen Folianten ertappt, gibt Paxton zu, Blaggons Werk noch nicht fertig vervielfältigt zu haben, was die Rückholung des Originalmanuskripts verzögert."}},faq={{q="Warum schickt Euch Milton Garbenbund zur Abtei von Nordhain?",a="Milton Garbenbund hat das Bibliotheksexemplar von „Die Belastbarkeit des Eisens“ vor Monaten an Bruder Paxton verliehen, damit die Abtei ihr eigenes Duplikat anfertigen konnte. Da Paxton weder Nachricht gab noch das Manuskript zurückbrachte, schickt Sheaf Euch los, um nach Paxtons Fortschritt zu sehen.",al={"warum bruder paxton","wo ist das buch","milton garbenbund botengang"}},{q="Wer ist Bruder Paxton?",a="Bruder Paxton ist ein Kleriker und der Hüter der Bibliothek in der Abtei von Nordhain. Er verbringt seine Tage damit, wertvolle Bücher zu katalogisieren und manuell abzuschreiben, um die lokale Sammlung der Abtei aufzubauen.",al={"wer ist paxton","bruder paxton geschichte","paxton nordhain"}},{q="Was ist „Die Belastbarkeit des Eisens“?",a="Es ist ein angesehenes Fachhandbuch, das vor Jahrzehnten vom zwergischen Bergarbeiter Margulf Blaggon verfasst wurde und seine Erkenntnisse über den Erzabbau sowie metallurgische Belastungen tief in den Bergen von Khaz Modan beschreibt.",al={"was ist die belastbarkeit des eisens","die belastbarkeit des eisens buch","margulf blaggon buch"}},{q="Warum hat Paxton das Buch noch nicht zurückgegeben?",a="Bruder Paxton schreibt das Manuskript noch immer von Hand für die Regale seiner eigenen Bibliothek ab. Da das händische Abschreiben eines umfangreichen Fachwerks beträchtliche Zeit und Materialien erfordert, zögert er, sich vor der Fertigstellung vom Original zu trennen.",al={"warum überfällig","warum braucht paxton so lange","paxton verzögerung"}},{q="Wo ist Bruder Paxton zu finden?",a="Bruder Paxton hält sich in der Abtei von Nordhain auf, dem Sitz des Heiligen Ordens der Kleriker von Nordhain, der im Nordhaintal im nördlichen Wald von Elwynn liegt.",al={"paxton standort","wo ist bruder paxton"}},{q="Was passiert, nachdem Ihr Bruder Paxton zur Rede gestellt habt?",a="Paxton gibt zu, das Buch zu besitzen, und erklärt, dass er die Abschrift nicht ohne neue Schreibmaterialien fertigstellen kann, woraufhin er Euch losschickt, um Tinten-Zutaten zu beschaffen.",al={"folgequest nach paxton","was braucht paxton"}}},fx={["4a96b020"]={q="Warum benötigt Milton Garbenbund einen Abenteurer, um Brother Paxton zu finden?",a="Milton Garbenbund ist der oberste Bibliothekar von Sturmwind und dazu verpflichtet, die Royal Library in Burg Sturmwind zu beaufsichtigen. Er kann seinen Posten nicht einfach verlassen, um wegen eines längst überfälligen Buches ins Nordhaintal zu gehen. Als Ihr ankommt und nach 'The Stresses of Iron' fragt, bietet Ihr ihm einen praktischen Boten, der ohnehin unterwegs ist und bereit ist, Brother Paxton aufzuspüren.",al={"warum ich brother paxton","warum braucht mich milton garbenbund","warum kann milton das buch nicht selbst holen"}}},fp="14,254,17.422.0,19.406.0,51.228.0,22.188.0,31.198.0,40.233.0,34.156.0,47.167.1"}
P.entries["quest:345"] = {n="Tinten-Zutaten",s="Tinten-Zutaten ist ein Botengang der Allianz im Auftrag von Bruder Paxton, einem klösterlichen Schreiber in der Abtei von Nordhain. Da er einen speziellen mineralischen Bestandteil benötigt, um seine schnelltrocknende Tinte herzustellen, schickt Paxton einen Abenteurer nach Osten in die umkämpfte Ortschaft Seenhain, um sich Rethbanerz von Großknecht Oslow zu beschaffen.",h="Tinten-Zutaten ist ein Botengang der Allianz im Auftrag von Bruder Paxton, einem klösterlichen Schreiber in...",kw={"bruder paxton","großknecht oslow","tinten-zutaten","seenhain","abtei von nordhain","rotkammgebirge","rethbanerz","the stresses of iron"},ang={["class:Priest"]="Bruder Paxtons Questreihe gehört zu den frühen Prüfungen rund um die Tugenden der Seelenstärke und leitet Akolythen des Heiligen Lichts an, die Gelehrtenarbeit der Geistlichen zu unterstützen.",["faction:Alliance"]="Die Reise verdeutlicht den scharfen Kontrast zwischen der friedvollen Abgeschiedenheit der Abtei von Nordhain und der gewaltsamen Grenzlandkrise, die Seenhain erfasst hat.",["profession:Mining"]="Die Quest rückt das Rethbaneisenerz in den Mittelpunkt, ein örtlich begrenztes Mineralvorkommen hoch in den schroffen Felsen des Rotkammgebirges."},sec={{t="Die Rezeptur eines Schreibers",b="Bruder Paxton ist ungemein stolz auf sein literarisches Handwerk und weigert sich, für wichtige Abschriften wie The Stresses of Iron auf gewöhnliche Tinten zurückzugreifen. Stattdessen braut er eine eigene Rezeptur zusammen, die für ihre Wischfestigkeit und ihre kurze Trocknungszeit geschätzt wird. Der größte Makel der Mixtur liegt darin, dass sie selbst im Gefäß eintrocknet, wenn man sie zu lange stehen lässt. Um seine Vorräte wieder aufzufüllen, benötigt er rohes Rethbaneisenerz – ein markantes Mineral, das in den felsigen Weiten des Rotkammgebirges abgebaut wird."},{t="Eine belagerte Stadt",b="Wenn Reisende mit Paxtons bescheidenem Gesuch in Seenhain eintreffen, finden sie die Siedlung in einem Zustand vor, der wenig Raum für die Bitten eines fernen Mönchs lässt. Großknecht Oslow beaufsichtigt die überlasteten Arbeiter des Ortes, die vollauf damit beschäftigt sind, Barrikaden zu verstärken, zerstörte Bauten wiederaufzubauen und sich gegen die anhaltenden Überfälle der Blackrockorcs zu wappnen. Oslow hat weder die Leute noch die Geduld, Erz für Sturmwinds Schreiber abzubauen, sodass Außenstehende sich auf eigene Faust in die gefährlichen Rethbanhöhlen wagen müssen."}},faq={{q="Warum benötigt Bruder Paxton Eisenerz für Tinte?",a="Bruder Paxton verwendet eine eigene Rezeptur, die dauerhafte, wischfeste Schriftzüge hervorbringen soll, welche nahezu augenblicklich trocknen. Gemahlenes Rethbaneisenerz liefert das entscheidende mineralische Pigment und die bindenden Eigenschaften, die für seine besondere Tinte unverzichtbar sind.",al={"warum eisen fuer tinte","paxton erz tinte","bruder paxton tintenrezept"}},{q="Wer ist Großknecht Oslow?",a="Großknecht Oslow ist der oberste Vorarbeiter, der für die städtischen Bauarbeiten und Ausbesserungen in Seenhain zuständig ist. Da der Ort unter ständigem Druck durch Blackrockorcs steht, leitet er die Befestigungs- und Wiederaufbaumaßnahmen entlang des Sees.",al={"großknecht oslow","oslow seenhain","wer ist oslow"}},{q="Wohin schickt Euch Bruder Paxton?",a="Paxton schickt Euch vom Wald von Elwynn nach Osten nach Seenhain, der zentralen Siedlung des Rotkammgebirges, um Großknecht Oslow aufzusuchen.",al={"tinten-zutaten zielort","wo ist oslow","wohin fuer tinten-zutaten"}},{q="Warum gibt Euch Großknecht Oslow das Erz nicht einfach?",a="Seenhain sieht sich unerbittlichen Angriffen von Orcs des Blackrockclans ausgesetzt. Oslows Arbeiter sind vollkommen damit ausgelastet, beschädigte Gebäude zu reparieren und die Verteidigungslinien des Ortes zu verstärken, weshalb keine Arbeitskräfte für Botengänge zum Erzabbau entbehrt werden können.",al={"warum kein erz","oslow verweigert erz","warum oslow wuetend"}},{q="Welches Buch versucht Bruder Paxton zu kopieren?",a="Er befindet sich mitten in der Abschrift eines Bandes mit dem Titel The Stresses of Iron – eine Arbeit, die zum Erliegen kam, als seine vorherige Ladung schnelltrocknender Tinte in ihrem Behälter aushärtete.",al={"paxton buch","was kopiert paxton","the stresses of iron"}},{q="Was geschieht nach dem Gespräch mit Großknecht Oslow?",a="Oslow erklärt Euch, dass Ihr Euch das Rethbaneisenerz selbst in den gefährlichen Rethbanhöhlen nördlich des Immerruhsees beschaffen müsst, wenn Ihr es haben wollt.",al={"naechste quest nach tinten-zutaten","wie weiter nach oslow","folgequest tinten-zutaten"}}},fx={["3b01bf84"]={q="Warum möchte Brother Paxton, dass Ihr Rethban Ore holt?",a="Brother Paxton widmet sich dem Kopieren der wissenschaftlichen Abhandlung The Stresses of Iron für die Bibliothek der Abtei von Nordhain. Er besteht darauf, seine eigene Spezialtinte zu brauen, für die pulverisiertes Rethban Ore benötigt wird, um sicherzustellen, dass sie schnell trocknet und nicht verschmiert. Leider ist seine vorherige Charge vollständig eingetrocknet, bevor er mit der Transkription fertig war, wodurch sein wissenschaftliches Projekt ins Stocken geraten ist, bis frische Mineralien eintreffen.",al={"warum braucht brother paxton erz","beweggrund von brother paxton","warum tintenvorräte"}},c7dba9bc={q="Warum schickt Euch Brother Paxton, anstatt das Erz selbst zu besorgen?",a="Brother Paxton ist ein hingebungsvoller Kopist, der an seine Pflichten innerhalb der klösterlichen Mauern der Abtei von Nordhain gebunden ist. Eine Reise bis nach Seenhain im Rotkammgebirge geht weit über seinen friedlichen klösterlichen Alltag hinaus, zumal die Reisewege immer gefährlicher werden. Als fähiger Abenteurer, der ohnehin durch das Reich reist, könnt Ihr seine übliche Kontaktperson leicht benachrichtigen.",al={"warum kann paxton das erz nicht selbst holen","warum einen abenteurer schicken","warum ich tintenvorräte"}}},fp="12,295,18.462.0,18.481.0,46.240.0,21.219.0,35.131.0,46.215.0,47.171.0,47.147.0"}
P.entries["quest:346"] = {n="Rückkehr zu Kristoff",s="Rückkehr zu Kristoff schließt Bruder Kristoffs Suche nach dem schwer auffindbaren Wälzer, The Stresses of Iron, ab. Nach einer Reise durch das Rotkammgebirge, um Erz für Spezialtinte zu beschaffen, und dem Warten auf die Schreiber von Nordhain bringt der Abenteurer den geliehenen Band schließlich zurück zur Kathedrale des Lichts in Sturmwind.",h="Rückkehr zu Kristoff schließt Bruder Kristoffs Suche nach dem schwer auffindbaren Wälzer, The Stresses of...",kw={"bruder kristoff","bruder paxton","kathedralenplatz","milton garbenbund","abtei von nordhain","rückkehr zu kristoff","sturmwind","the stresses of iron"},ang={["class:Priest"]="Ein einfacher Botengang für die Geistlichen veranschaulicht, wie die Kirche des Heiligen Lichts bedeutende wissenschaftliche Werke im gesamten Königreich pflegt, bewahrt und verteilt.",["faction:Alliance"]="Selbst scheinbar belanglose akademische Austausche hängen von sicheren Straßen zwischen Burg Sturmwind, Nordhain und dem umkämpften Rotkammgebirge ab."},sec={{t="Eine lang verzögerte Rückkehr",b="Bruder Kristoff, der auf dem Kathedralenplatz von Sturmwind stationiert ist, benötigte Zugang zu einem metallurgischen Fachband namens The Stresses of Iron. Die Beschaffung des Werkes schickte Kuriere durch die Länder der Menschen, was zunächst in die Royal Library in Burg Sturmwind und dann tief in die Abtei von Nordhain führte. In der Abtei war Bruder Paxton emsig damit beschäftigt, den Text von Hand zu kopieren, verzögert durch einen Mangel an Rethbanerz, das für die Herstellung von Schreibertinte benötigt wurde. Nachdem das Erz beschafft und die Abschrift fertiggestellt ist, händigt Paxton schließlich den Originalband für die Rückkehr in die Stadt aus."},{t="Die Arbeit der Schreiber",b="In einem Königreich, das ständig von äußeren Bedrohungen bedrängt wird, bleibt die stille Arbeit der Kopisten von Nordhain unerlässlich, um das bürgerliche und geistige Wissen zu bewahren. Bruder Paxtons Bitte, sich bei Bibliothekar Milton Garbenbund zu entschuldigen, verdeutlicht, wie knapp die Ressourcen der Abtei geworden sind. Wertvolle Bücher müssen unter Verwendung mineralreicher Tinten akribisch Strich für Strich vervielfältigt werden, bevor sie wieder in die Obhut von Sturmwind übergeben werden können, was eine einfache Buchanfrage in eine mühsame logistische Botenfahrt verwandelt."}},faq={{q="Worum geht es in dem Buch The Stresses of Iron?",a="The Stresses of Iron ist eine Abhandlung über Metallurgie und Metallverarbeitung. Bruder Kristoff ersuchte darum, um es auf dem Kathedralenplatz zu studieren, während die Schreiber in der Abtei von Nordhain eine exakte Abschrift benötigten, um das Wissen zu bewahren.",al={"was ist stresses of iron","stresses of iron buch","welches buch sucht kristoff"}},{q="Warum befand sich das Buch in der Abtei von Nordhain?",a="Die Royal Library lieh das Buch an Bruder Paxton aus, damit dieser eine illustrierte Abschrift für das Archiv der Abtei von Nordhain anfertigen konnte. Schreiber dort bewahren wichtige Texte von Hand auf, doch Paxtons Fortschritt geriet ins Stocken, als ihm das Rethbanerz für Spezialtinte ausging.",al={"warum behielt paxton das buch","warum war es in nordhain"}},{q="Wer ist Bruder Kristoff?",a="Bruder Kristoff ist ein Mitglied des Klerus des Heiligen Lichts, der auf dem Kathedralenplatz vor der Kathedrale des Lichts in Sturmwind stationiert ist. Er bat um das Buch und spendet aus Dankbarkeit spirituellen Segen.",al={"wer ist kristoff","kristoff sturmwind"}},{q="Wer ist Milton?",a="Milton Garbenbund ist der leitende Bibliothekar, der in der Royal Library in Burg Sturmwind verweilt. Er gestattete ursprünglich die Ausleihe von The Stresses of Iron und wurde angesichts der langen Verzögerung bei der Rückgabe ungeduldig.",al={"wer ist bibliothekar milton","milton garbenbund"}},{q="Wo beginnt diese Questreihe?",a="Die Reihe beginnt auf dem Kathedralenplatz von Sturmwind bei Bruder Kristoff mit der Quest Reden über Kraft, die zu Bibliothekar Milton Garbenbund, danach zur Abtei von Nordhain und ins Rotkammgebirge führt, bevor sie wieder bei Kristoff abschließt.",al={"start reden über kraft","start der questreihe"}},{q="Gibt es für diese Quest Folgequests?",a="Rückkehr zu Kristoff markiert das Ende der Questreihe um Reden über Kraft. Sobald Ihr The Stresses of Iron abliefert, spricht Bruder Kristoff seinen Dank und einen Segen des Lichts aus, womit die Angelegenheit beigelegt ist.",al={"was folgt auf rückkehr zu kristoff","gibt es eine folgequest"}}},fx={["46830297"]={q="Warum möchte Brother Paxton, dass das Buch an Bruder Kristoff zurückgegeben wird?",a="Brother Paxton hat The Stresses of Iron nur ausgeliehen, um seinen Inhalt in der Abtei von Nordhain kopieren zu können. Jetzt, da seine Transkription abgeschlossen ist, hat er keinen Anspruch mehr auf den seltenen Band und schuldet seine sichere Rückgabe an die Kathedrale des Lichts in Sturmwind, in der Hoffnung, etwaige Probleme, die durch seine lange Verzögerung entstanden sind, wiedergutzumachen.",al={"warum stresses of iron zurückgeben","beweggrund von brother paxton","warum buch an kristoff zurückschicken"}}},fp="18,293,21.544.0,20.471.0,44.216.0,37.254.0,24.202.0,14.192.0,34.234.0,36.197.0"}
P.entries["quest:347"] = {n="Rethbanerz",s="Großknecht Oslow schickt Abenteurer in die Rethbanhöhlen des Rotkammgebirges, um ein eigentümliches dunkles Mineral zu beschaffen. Obwohl es zu weich ist, um verlässliche Rüstungen oder Waffen daraus zu schmieden, macht seine einzigartige Pigmentierung es für die Schriftgelehrten der Abtei von Nordhain zur Herstellung spezieller Tinte unentbehrlich.",h="Großknecht Oslow schickt Abenteurer in die Rethbanhöhlen des Rotkammgebirges, um ein eigentümliches dunkles...",kw={"bart rethban","bruder paxton","großknecht oslow","abtei von nordhain","rotkammschinder","rethbanhöhlen","rethbanerz","the stresses of iron"},ang={["faction:Alliance"]="Der Auftrag verdeutlicht, wie überdehnt die Nachschublinien des Königreichs Sturmwind sind, wenn Klosterschreiber auf reisende Abenteurer angewiesen sind, um grundlegenden Schreibbedarf aus Kriegsgebieten zu beschaffen.",["profession:Mining"]="Bergleute können Rethbanerz mit einer Spitzhacke direkt aus den Adern der Höhle abbauen, ohne rohe Brocken von Gnollschindern erbeuten zu müssen.",["race:Human"]="Die Bewahrung historischer Manuskripte in der Abtei von Nordhain ist eine heilige Pflicht für Sturmwinds Gelehrte, die sich dafür einsetzen, das während des Ersten und Zweiten Krieges verlorene Wissen wiederherzustellen."},sec={{t="Ein merkwürdiges Mineral",b="Rethbanerz ist nach seinem Entdecker, Bart Rethban, benannt. Im Gegensatz zu gewöhnlichem Eisen oder Kupfer besitzt dieses Erz am Amboss eines Rüstungsschmieds kaum einen Wert – wird es eingeschmolzen, fehlt dem entstandenen Metall die Zugfestigkeit, die für robuste Waffen oder Plattenrüstungen erforderlich ist. Sein wahrer Wert liegt in seiner rohen, dunklen, matten Färbung, die von Mönchen und Schriftgelehrten als Pigmentbasis für ergiebige Manuskriptfarben geschätzt wird."},{t="Umkämpfte Höhlen",b="Die primären Vorkommen des Minerals liegen in den Rethbanhöhlen, eingebettet in den nördlichen Bergen des Rotkammgebirges. Zum Unglück für die Steinmetze von Seenhain haben die örtlichen Bergleute die Höhle aufgegeben. Eine grimmige Schar von Rotkammgnollen hat die Stollen an sich gerissen und lässt Gnollschinder das Gestein abbauen, um die Adern für ihre eigenen primitiven Zwecke zu nutzen."},{t="Bewahrung des geschriebenen Wortes",b="Bruder Paxton, ein Mönch innerhalb der ruhigen Mauern der Abtei von Nordhain, ist auf dieses Pigment angewiesen, um historische Texte zu vervielfältigen. Sein derzeitiges Vorhaben – eine handschriftliche Kopie der Abhandlung „The Stresses of Iron“ – kam ohne den passenden Farbstoff zu einem abrupten Stillstand, weshalb Boten und Abenteurer tief in gnollverseuchtes Gebiet geschickt werden, um das Rohgestein zu sichern."}},faq={{q="Wofür wird Rethbanerz verwendet?",a="Obwohl es nach dem Einschmelzen zu schwach ist, um dauerhafte Waffen oder Rüstungen daraus zu schmieden, eignet sich seine dunkle, matte Farbe hervorragend als Basispigment für Tinten und Farben. Schriftgelehrte wie Bruder Paxton in der Abtei von Nordhain sind darauf angewiesen, um historische Manuskripte zu kolorieren und abzuschreiben.",al={"warum braucht man rethbanerz","verwendungszweck rethbanerz","wofür ist rethbanerz"}},{q="Wer war Bart Rethban?",a="Bart Rethban war der Forscher und Schürfer, der die dunklen Erzadern in den nördlichen Bergen des Rotkammgebirges ursprünglich entdeckte und sowohl dem Mineral als auch den Rethbanhöhlen ihren Namen gab.",al={"wer entdeckte rethbanerz","bart rethban geschichte"}},{q="Warum hat Seenhain das Erz in letzter Zeit nicht abgebaut?",a="Großknecht Oslow und die Arbeiter der Stadt sind vollkommen mit der Verteidigung von Seenhain gegen die Überfälle der Schwarzfelsorcs beschäftigt. Erschwerend kommt hinzu, dass Rotkammgnolle in die Rethbanhöhlen eingedrungen sind und die zivilen Bergleute vertrieben haben.",al={"warum baut oslow es nicht ab","warum sind die minen verlassen"}},{q="Welches Buch schreibt Bruder Paxton ab?",a="Bruder Paxton fertigt eifrig die Kopie eines Informationswerks mit dem Titel „The Stresses of Iron“ an. Er benötigt den dunklen Farbstoff aus dem Rethbanerz, um die Abschrift des Textes für die Bibliothek der Abtei fertigzustellen.",al={"welches buch schreibt paxton","paxton manuskript"}},{q="Warum wollen die Gnolle das Erz?",a="Die Rotkammgnolle haben ihre Schinder in den gesamten Höhlen graben lassen. Obwohl Gnolle selten umfangreiche schriftliche Aufzeichnungen führen, begehren sie Metallvorkommen für primitive Werkzeuge, zum Handeln oder schlicht zur Befestigung ihrer Gebirgsbaue gegen Eindringlinge.",al={"warum schürfen gnolle","gnollschinder rethban"}},{q="Wohin führt diese Questreihe als Nächstes?",a="Sobald Bruder Paxton das Erz erhält und die Vorbereitung seiner Tinten abgeschlossen hat, schickt er Euch nach Sturmwind zurück, um Kristoff von Eurem Erfolg zu berichten, was den Auftrag für Nordhains Schriftgelehrte abschließt.",al={"welche quest folgt auf rethbanerz","rückkehr zu kristoff danach"}}},fx={["86e7e5db"]={q="Warum möchte Großknecht Oslow, dass dies erledigt wird?",a="Großknecht Oslow sucht das Erz nicht für sich selbst oder die Baumeister von Seenhain. Brother Paxton aus der Abtei von Nordhain hat Euch zu Oslow geschickt, um Rethban Ore für Tinte zum Buchbinden zu beschaffen. Oslow kommt der Bitte lediglich nach, indem er Euch zur Quelle schickt, da die Vorräte der Stadt leer sind und seine Arbeiter nicht die Zeit erübrigen können, es selbst zu graben.",al={"beweggrund von großknecht oslow","warum braucht oslow erz","warum hilft oslow paxton"}},fa5d21e9={q="Wer besetzt die Rethbanhöhlen?",a="Die Gnolle des Rotkammgebirges haben die Rethbanhöhlen nördlich von Seenhain überrannt. Anstatt die Höhlen leer stehen zu lassen, haben Gnollplünderer begonnen, die dunklen Erzadern für ihre eigenen Zwecke auszugraben und dabei alle einheimischen Bergleute, die sich zu nähern versuchen, gewaltsam vertrieben.",al={"feinde in den rethbanhöhlen","wer ist in den rethbanhöhlen","gnolle im rotkammgebirge höhlen"}}},fp="11,270,17.371.0,17.358.0,19.362.0,29.256.0,21.188.0,44.217.0,36.197.0,27.246.0,38.186.1"}
P.entries["quest:35"] = {n="Weitere Sorgen",s="Weitere Sorgen ist eine Kurierquest der Allianz, die von Marschall Dughan in Goldhain ausgegeben wird, um Gerüchte über eine amphibische Bedrohung zu untersuchen. Der Marshal schickt Euch nach Osten durch den Wald von Elwynn, um Wache Thomas am Flussübergang zu befragen. Dies verlagert Eure Aufmerksamkeit von den zentralen Garnisonsaufgaben auf die sich verschlechternde Sicherheitskrise entlang der östlichen Grenze.",h="Weitere Sorgen ist eine Kurierquest der Allianz, die von Marschall Dughan in Goldhain ausgegeben wird, um...",kw={"östliche brücke","wald von elwynn","weitere sorgen","goldhain","wache thomas","marschall dughan","murloc"},ang={["faction:Alliance"]="Die Quest unterstreicht die wachsenden operativen Risse im Königreich Sturmwind und zeigt, wie dünn die menschlichen Verteidigungslinien selbst nur einen kurzen Fußmarsch von der Hauptstadt entfernt sind.",["race:Human"]="Für die Menschen von Elwynn bedroht die Ausbreitung aggressiver Murlocs die Bauernhöfe der Kornkammer und die Handelsadern, die Goldhain mit Seenhain verbinden."},sec={{t="Ein Auge auf den östlichen Übergang",b="Während der zentrale Wald von Elwynn unter dem Gewicht von Banditen und Ungeziefer leidet, machen beunruhigende Gerüchte über Wasserwesen, die an den Flussufern entlangkriechen, die Runde. Marschall Dughan, der die Garnison in Goldhain befehligt, weigert sich, die Panik einfach abzutun. Statt Wachen von der Stadt abzuziehen, schickt er Reisende nach Osten, um Wache Thomas zu befragen, den Posten, der an der Brücke steht, welche den östlichen Fluss in Richtung Rotkammgebirge überspannt."},{t="Eine ausgedünnte Grenze",b="Wache Thomas hält den Brückenaußenposten seit über einer Woche und ist Zeuge dessen geworden, was die Führung von Goldhain nur vermuten konnte. Halbintelligente, feindselige Murlocs haben Lager entlang der Wasserwege im östlichen Elwynn errichtet. Da Sturmwinds Armee abwesend ist und die örtlichen Garnisonen damit beschäftigt sind, Stadtmauern und Versorgungswege zu schützen, sind ländliche Brückenköpfe wie der Posten von Thomas gegen diese schleichende Gefahr kritisch isoliert."}},faq={{q="Warum schickt mich Marschall Dughan zu Wache Thomas?",a="Marschall Dughan erhielt Berichte und Gerüchte über Murlocs, die in die östlichen Wasserwege eindringen. Da Wache Thomas seit einer Woche an der Brücke im östlichen Elwynn stationiert ist, verlässt sich Dughan auf ihn, um zu bestätigen, ob die Bedrohung echt ist.",al={"warum wache thomas","dughans absicht","mit thomas sprechen"}},{q="Wo ist Wache Thomas stationiert?",a="Wache Thomas ist an der hölzernen Brücke stationiert, die den Fluss im äußersten Osten des Waldes von Elwynn überspannt, und bewacht die Straße, die zum Rotkammgebirge führt.",al={"standort wache thomas","wo ist thomas","wache an der östlichen brücke"}},{q="Welche Bedrohung bestätigt Wache Thomas?",a="Wache Thomas bestätigt, dass feindselige, halbintelligente Murlocs sich tatsächlich an den Bächen und Wasserwegen des östlichen Elwynn niedergelassen haben und eine unmittelbare Gefahr für Reisende und nahegelegene Bauernhöfe darstellen.",al={"murlocbedrohung","was hat thomas herausgefunden","bedrohung am östlichen fluss"}},{q="Wie erreicht man Wache Thomas?",a="Folgt der Straße von Goldhain aus nach Osten durch den Wald von Elwynn bis zur Brücke über den östlichen Fluss, wo Wache Thomas Wache hält.",al={"schnellreise zu thomas","reiten zu dughan","pferd zur brücke"}},{q="Warum schickt Sturmwind keine Armee, um das östliche Elwynn zu unterstützen?",a="Sturmwinds stehende militärische Kräfte sind stark eingeschränkt, da König Varian Wrynn vermisst wird und Ressourcen von der Landschaft abgezogen wurden. Außenposten wie der von Wache Thomas müssen sich weitgehend auf vorbeiziehende Abenteurer verlassen.",al={"wo sind die wachen von stormwind","warum ist elwynn unverteidigt","militärische hilfe aus stormwind"}},{q="Was passiert, nachdem man Wache Thomas Bericht erstattet hat?",a="Sobald Wache Thomas die Präsenz der Murlocs bestätigt, bittet er Euch, bei der Untersuchung des Schicksals anderer Wachen zu helfen, die am Flussufer patrouillierten und nicht zurückgekehrt sind.",al={"nächste quest nach weitere sorgen","folgeschritte bei thomas","quest vermisste wachen"}}},fx={["01d891f6"]={q="Warum schickt Marschall Dughan einen Abenteurer anstelle seiner eigenen Wachen?",a="Marschall Dughan ist überlastet, während er Goldhain gegen Defias-Banditen und Gnolle sichert. Da Sturmwind zusätzliche Truppen und Ressourcen verweigert, kann die örtliche Garnison keine Soldaten für routinemäßige Botengänge oder weit entfernte Erkundungen entbehren. Weil Ihr ihm die erste Warnung überbracht und Sorge um die Sicherheit von Elwynn gezeigt habt, vertraut er Euch damit, nach Osten zu reisen, um mit Wache Thomas an der östlichen Brücke Rücksprache zu halten.",al={"warum werde ich geschickt","warum keine wachen einsetzen","warum braucht mich dughan"}}},fp="16,348,28.437.0,25.425.0,48.234.0,32.152.0,38.193.0,30.126.0,58.226.0,45.167.0"}
P.entries["quest:350"] = {n="Auf einen alten Freund verlassen",s="Meister Mathias Shaw weist einen Ermittler an, einen unkonventionellen Kontakt im Handelsdistrikt von Sturmwind aufzusuchen. Da korrupte Adlige mächtige Verräter vor der normalen Justiz schützen, greift der Spymaster widerwillig auf das Geheimdienstnetzwerk des besten Käsehändlers der Stadt zurück.",h="Meister Mathias Shaw weist einen Ermittler an, einen unkonventionellen Kontakt im Handelsdistrikt von...",kw={"defias","elling trias","lescovar","marzon","mathias shaw","sturmwind","der handelsdistrikt","trias cheese"},ang={["class:Rogue"]="Die stille Rivalität zwischen Mathias Shaw und Elling Trias verdeutlicht die zerrissene Natur der verdeckten Operationen in Sturmwind, wo Informanten auf Straßenebene oft über besseren Einfluss verfügen als die offizielle Geheimdienstabteilung der Krone.",["faction:Alliance"]="Diese Aufgabe zeigt, wie die Korruption des Hauses der Adligen die interne Sicherheit von Sturmwind lähmt, während König Varian Wrynn weiterhin vermisst wird."},sec={{t="Über dem Gesetz",b="Nach der Entdeckung, dass Lord Gregor Lescovar und der Assassine Marzon the Silent Blade direkte Verbindungen zur Bruderschaft der Defias unterhalten, steht Meister Mathias Shaw vor einer Sackgasse bei seinen Ermittlungen. Da Edwin van Cleef in den Todesminen tot ist und Bazil Thredd im Verlies ausgeschaltet wurde, gibt es keine lebenden Anführer der Banditen mehr, die aussagen könnten. Zudem ist Lord Gregor Lescovar aufgrund seines aristokratischen Status und seiner weitreichenden politischen Verbindungen praktisch vor der regulären Justiz der Königlichen Garde und den formellen Haftbefehlen des SI:7 sicher."},{t="Das Ohr des Käsehändlers",b="Um die Verteidigung eines Adligen aus Sturmwind zu durchbrechen, verweist Shaw seinen Agenten an Elling Trias, den Besitzer von Trias' Cheese im Handelsdistrikt. Obwohl er nach außen hin nur ein temperamentvoller Händler ist, der in der ganzen Stadt für seine importierten Käsesorten bekannt ist, unterhält Trias ein unabhängiges Netzwerk aus Augen und Ohren, das dem SI:7 in nichts nachsteht. Shaw verabscheut es, seinen ehemaligen Kollegen um Hilfe zu bitten, doch die Entlarvung des Verrats in der Burg Sturmwind erfordert Methoden jenseits der offiziellen königlichen Kanäle."}},faq={{q="Warum schickt Mathias Shaw Euch zu einem Käsehändler?",a="Elling Trias ist weit mehr als ein einfacher Käsehändler. Während er Trias' Cheese nahe des Eingangs zum Handelsdistrikt betreibt, unterhält er ein unabhängiges, weitreichendes geheimes Informationsnetzwerk. Shaw verabscheut es, ihn um Unterstützung zu bitten, doch der SI:7 benötigt unkonventionelle Mittel, um gegen einen Adligen vorzugehen, der sich außerhalb der Reichweite der normalen Strafverfolgungsbehörden befindet.",al={"warum elling trias","warum mit trias sprechen","warum käseladen"}},{q="Warum kann Mathias Shaw Lord Gregor Lescovar nicht einfach verhaften?",a="Lord Gregor Lescovar ist ein hochrangiger Adliger aus Sturmwind mit tiefen Verbindungen innerhalb des Hauses der Adligen. Shaw fehlen die nötigen Zeugenaussagen, um die Beweise rechtlich gegen einen Aristokraten durchzusetzen.",al={"warum lescovar nicht verhaften","warum kann shaw lescovar nicht verhaften","warum ist lescovar unantastbar"}},{q="Wer ist Marzon the Silent Blade?",a="Marzon the Silent Blade ist ein tödlicher Agent, der eng mit der Verschwörung der Defias zusammenarbeitet und geheime Kommunikationen mit Lord Gregor Lescovar am Hofe von Sturmwind unterhält.",al={"wer ist marzon","rolle von marzon the silent blade"}},{q="Warum erwähnt Trias Deathwing, wenn Ihr mit ihm sprecht?",a="Als er von der Verschwörung rund um die Bruderschaft der Defias erfährt, reagiert Trias mit beißendem Sarkasmus und spottet, dass Ihr ihm als Nächstes wahrscheinlich erzählen werdet, dass der lange verschollene Aspekt des Schwarzen Drachen Deathwing noch am Leben ist und das Königreich angreift.",al={"warum erwähnt trias deathwing","trias deathwing satz","greift deathwing stormwind an"}},{q="Was passiert nach dem Treffen mit Elling Trias?",a="Nachdem er sich den vollständigen Bericht über die Verschwörung angehört hat, beginnt Trias damit, eine leise Infiltration der Burg Sturmwind zu planen, um Lord Gregor Lescovar in die Enge zu treiben, ohne den restlichen Adelshof zu alarmieren.",al={"nächste quest nach trias","wohin nach auf einen alten freund verlassen"}},{q="Wo befindet sich Elling Trias?",a="Elling Trias ist in seinem Laden, Trias' Cheese, zu finden, der sich im Handelsdistrikt von Sturmwind befindet, direkt an der Hauptstraße, die von den Stadttoren herführt.",al={"standort von trias","wo ist trias cheese"}}},fx={["9cbff8f4"]={q="Warum schickt Mathias Shaw Euch, anstatt dies über das SI:7 zu regeln?",a="Lord Gregor Lescovar ist ein mächtiger, gut vernetzter Adliger, was ihn effektiv über das konventionelle Gesetz von Sturmwind stellt. Shaw fehlen die Zeugenaussagen, die nötig wären, um den Fall gegen ihn offiziell vor Gericht zu beweisen. Ein offizielles Vorgehen des SI:7 oder der Stadtwache würde ohne eiserne Beweise politisches Entsetzen beim Adel auslösen. Ihr hingegen operiert inoffiziell als unabhängiger Agent, was es Shaw ermöglicht, unkonventionelle, diskrete Wege zu verfolgen, ohne vorzeitige Aufmerksamkeit von Lescovars Verbündeten im Haus der Adligen auf sich zu ziehen.",al={"warum werde ich geschickt","warum nicht das si:7","warum braucht mich shaw"}}},fp="21,288,13.491.1,22.450.1,52.343.0,51.185.0,31.171.0,55.235.0,45.185.1,30.148.0"}
P.entries["quest:3513"] = {n="Die runenverzierte Rolle",s="Die runenverzierte Rolle ist ein merkwürdiges, mit einem silbrigen Band verschnürtes Dokument, das in der Wildnis von Kalimdor gefunden wurde. Seine formelle Erscheinung deutet auf militärische oder administrative Korrespondenz hin, die von den Nachtelfen jenseits der Grenze stammt. Ihr Fund führt Späher der Horde direkt zum Mor'shan-Schutzwall, um die Wachen vor Aktivitäten im Norden zu warnen.",h="Die runenverzierte Rolle ist ein merkwürdiges, mit einem silbrigen Band verschnürtes Dokument, das in der...",kw={"eschental","hordengrenze","kadrak","der mor'shan-schutzwall","nachtelfenrolle","runenverzierte rolle","brachland"},ang={["faction:Horde"]="Jede abgefangene Information der Allianz schützt die Holzfällertrupps und Grenzposten, die das Tor nach Eschental verteidigen.",["race:Orc"]="Die Ausbreitung des Kriegshymnenklans nach Eschental hängt maßgeblich von der Grenzverteidigung am Mor'shan-Schutzwall ab, was Botschaften der Nachtelfen zu unverzichtbaren Nachrichten macht."},sec={{t="Ein silbriges Band",b="Fest verschnürt mit einem kunstvollen silbrigen Band sticht die Schriftrolle sofort aus dem derben Leder und Pergament hervor, das im Brachland üblich ist. Ihre feine Handwerkskunst und Schrift weisen auf die Nachtelfen hin, die unter den dichten Baumkronen von Eschental direkt im Norden hausen. In einem Gebiet, das an jedem Grat und jedem Weg umkämpft ist, besitzt eine abgefangene Botschaft für die Frontlinien der Horde höchsten strategischen Wert."},{t="Wachsamer Blick auf die Nordgrenze",b="Statt die Schriftrolle quer durch die Steppen zum Kriegshäuptling nach Orgrimmar zu schicken, erkennt jeder Abenteurer mit Gespür für das Schlachtfeld die Dringlichkeit der örtlichen Befehlshaber. Am Mor'shan-Schutzwall, genau dort postiert, wo die rote Erde des Brachlands den üppigen Wäldern von Eschental weicht, wacht der Orc-Krieger Kadrak über Grenzüberschreitungen. Die Übergabe dieser Rolle versorgt den Außenposten am Schutzwall mit entscheidenden Erkenntnissen über die Truppenbewegungen der Nachtelfen."}},faq={{q="Was ist die runenverzierte Rolle?",a="Es handelt sich um ein offizielles, fein gearbeitetes Dokument, das mit einem silbrigen Band verschnürt ist, was auf nachtelfischen Ursprung hinweist. Es enthält Informationen über deren Bewegungen oder Pläne entlang der Grenze zum Brachland.",al={"was ist diese rolle","runenverzierte rolle lore","rolle mit silbernem band"}},{q="Wohin sollte ich die Rolle bringen?",a="Die Schriftrolle muss zum nördlichen Grenzwachturm am Mor'shan-Schutzwall gebracht werden, wo Kadrak die Aktivitäten zwischen dem Brachland und Eschental überwacht.",al={"wohin mit der runenverzierten rolle","rolle abgeben","wer will die rolle"}},{q="Wer ist Kadrak?",a="Kadrak ist ein Späher und Wächter der Horde, der auf einem der Verteidigungstürme am Mor'shan-Schutzwall stationiert ist und Bedrohungen an der Grenze im Auge behält, die aus Eschental herabdrängen.",al={"kadrak","orc auf dem turm"}},{q="Warum sollten die Nachtelfen eine Schriftrolle im Brachland verlieren?",a="Schildwachen und Späher der Nachtelfen patrouillieren regelmäßig an den Grenzen und Rändern von Eschental und stoßen bisweilen nach Süden vor, um die Verteidigung der Horde zu prüfen oder Nachschublinien in Richtung Norden zu überfallen.",al={"warum liegt die rolle hier","nachtelfen im brachland"}},{q="Was geschieht, nachdem man Kadrak die Rolle übergeben hat?",a="Nachdem Kadrak die Rolle geprüft hat, identifiziert er die Dryade Rynthariel, Schlüsselmeisterin des Krallenbaus, als deren Verfasserin und schickt Euch zum Steinkrallengipfel, um sie zu töten und eine Fahne der Horde im Bau zu hissen.",al={"quest hordenpräsenz","wie geht es weiter"}},{q="Warum ist die Rolle für die Horde von Bedeutung?",a="Wegen der Holzfällungen und der Grenzen schwelen die Spannungen zwischen der Horde und den Nachtelfen unentwegt. Jede abgefangene Nachricht bietet eine frühzeitige Warnung vor Hinterhalten der Allianz am Mor'shan-Schutzwall.",al={"bedeutung der runenverzierten rolle","interesse der horde an der rolle"}}},fp="16,330,16.421.0,27.453.0,25.194.0,31.152.0,14.170.0,55.178.0,47.189.0,40.201.0"}
P.entries["quest:3514"] = {n="Hordenpräsenz",s="Hordenpräsenz ist ein militärischer Vorstoß, der vom Orc Kadrak an der Grenze zwischen dem Brachland und Eschental in Auftrag gegeben wird. Veranlasst durch ein abgefangenes Schreiben entsendet die Horde einen Champion hoch hinauf auf den Steinkrallengipfel, um die Dryade Rynthariel zu eliminieren und ein Banner der Horde direkt im Krallenbau zu platzieren.",h="Hordenpräsenz ist ein militärischer Vorstoß, der vom Orc Kadrak an der Grenze zwischen dem Brachland und...",kw={"brachland","dryade","hordenpräsenz","kadrak","kadraks flagge","rynthariel","der steinkrallengipfel","der krallenbau","die runenverzierte rolle"},ang={["class:Druid"]="Für Hordedruiden verdeutlicht der Marsch auf den Steinkrallengipfel, um eine dryadische Tochter des Cenarius niederzustrecken, die bitteren politischen Spannungen zwischen Fraktionstreue und heiligen Banden der Natur.",["faction:Horde"]="Die Sicherung der Nordgrenzen des Brachlands ist unerlässlich, um die Kontrolle über die zentralen Ebenen von Kalimdor zu wahren und neue Siedlungen vor Vorstößen der Nachtelfen zu schützen.",["race:Orc"]="Orcs betrachten Kadraks entschlossene Offensive als die einzig angemessene Antwort auf territoriale Grenzüberschreitungen – Stärke zu demonstrieren, statt der Allianz Handlungsspielraum zu gewähren."},sec={{t="Eine abgefangene Botschaft",b="Kadrak bewacht die nördliche Grenze des Brachlands und hält wachsam Ausschau nach Übergriffen der Allianz und der Nachtelfen. Als ein Bote niedergestreckt wird, der eine runenverzierte Rolle bei sich trägt, entschlüsselt Kadrak die Botschaft und führt ihren Ursprung auf Rynthariel die Schlüsselmeisterin zurück, eine einflussreiche Dryade, die auf dem Steinkrallengipfel stationiert ist. Anstatt nur die Gebirgspässe zu verteidigen, wählt Kadrak eine aggressive Reaktion, um künftige Späher davon abzuhalten, Hordengebiet auszukundschaften."},{t="Trotz im Bau",b="Die Mission führt Hordekrieger tief in den Krallenbau, eine höhlenartige Bastion hoch über dem Steinkrallengipfel. Rynthariel zu töten versetzt der Koordination der örtlichen Nachtelfen einen direkten Schlag, doch dieser Akt wird noch dadurch unterstrichen, dass Kadraks Hordenbanner direkt in der Höhle aufgestellt wird. Indem die Horde ihre rote Standarte im Herzen des Dryadenterritoriums wehen lässt, will sie ein klares Signal senden, dass Übergriffe auf das Brachland mit entschlossener Gewalt beantwortet werden."}},faq={{q="Wer ist Kadrak und warum ordnet er diesen Schlag an?",a="Kadrak ist ein Orckrieger, der am nördlichen Grenzposten zwischen dem Brachland und Eschental stationiert ist. Verantwortlich für die Sicherung der Hordeländereien gegen fremde Übergriffe, ordnet er einen präventiven Vergeltungsschlag an, als er entdeckt, dass Allianzboten die nahegelegenen Pässe durchqueren.",al={"kadrak","wer ist kadrak","kadrak zweck"}},{q="Wer ist Rynthariel die Schlüsselmeisterin?",a="Rynthariel ist eine Dryadenanführerin, die im Krallenbau auf dem Steinkrallengipfel weilt. Sie verfasste die runenverzierte Rolle, die der abgefangene Bote bei sich trug, und koordinierte die Bewegungen von Allianz und Schildwachen über die Gebirgskorridore hinweg.",al={"rynthariel","rynthariel die schlüsselmeisterin","krallenbau boss"}},{q="Wo befindet sich der Krallenbau?",a="Der Krallenbau ist ein unterirdischer Höhlenkomplex an den Westhängen des Steinkrallengipfels, hoch oben im Steinkrallengebirge gelegen.",al={"krallenbau standort","wo ist der krallenbau","rynthariel standort"}},{q="Was ist der Zweck des Aufstellens von Kadraks Flagge?",a="Das Aufstellen der Flagge dient als psychologische Warnung. Kadrak möchte, dass die Nachtelfen und die Allianz das rote Hordenbanner über ihrer gefallenen Anführerin sehen, damit sie zögern, bevor sie weitere Späher durch das Brachland schicken.",al={"warum die flagge aufstellen","kadraks flagge","zweck der hordenflagge"}},{q="Wie ist diese Quest mit 'Die runenverzierte Rolle' verknüpft?",a="Hordenpräsenz ist die direkte Fortsetzung von 'Die runenverzierte Rolle'. Die Mission wird erst freigeschaltet, nachdem ein Spieler das abgefangene Pergament bei einem Allianzboten entdeckt und es zur Übersetzung zu Kadrak bringt.",al={"verbindung runenverzierte rolle","vorherige quest","hordenpräsenz voraussetzung"}},{q="Warum ist die Horde über Allianzböten im Brachland besorgt?",a="Das Brachland ist das lebenswichtige Herzland, das Orgrimmar, Donnerfels und die umliegenden Siedlungen miteinander verbindet. Lässt man Allianzboten und nachtelfische Verbündete ungehindert durch die Gebirgspässe ziehen, bedroht dies die Nachschublinien und die Grenzsicherheit der Horde.",al={"allianz im brachland","warum gegen dryaden kämpfen","brachland bedrohung"}}},fp="14,289,21.458.0,19.453.0,48.272.0,32.218.0,31.138.0,46.235.0,50.212.0,65.240.0"}
P.entries["quest:3519"] = {n="Ein Freund in der Not",s="Ein Freund in der Not ist ein dringender Hilferuf von Iverron, einem jungen Nachtelfen, der im Laubschattental an giftigen Spinnenbissen leidet. Niedergestreckt von der tödlichen Bestie Githyiss the Vile, schickt Iverron Reisende los, um Dirania Silberschein zu finden, bevor das Gift ihn dahinrafft.",h="Ein Freund in der Not ist ein dringender Hilferuf von Iverron, einem jungen Nachtelfen, der im...",kw={"aldrassil","dirania silberschein","githyiss","iverron","gift","laubschattental","spinne","teldrassil"},ang={["class:Druid"]="Druiden lernen früh, dass das Ungleichgewicht in der heimischen Tierwelt die Unvorsichtigen niederstrecken kann, was die dringende Notwendigkeit unterstreicht, die Gifte der Natur zu verstehen und ihnen entgegenzuwirken.",["race:NightElf"]="Für junge Kaldorei, die ihre Ausbildung unter Aldrassil beginnen, ist Iverrons missliche Lage eine deutliche Mahnung, dass selbst die geschützten Zweige des Laubschattentals nicht länger frei von Verderbnis und tödlicher Gefahr sind."},sec={{t="Ein leichtsinniges Unterfangen",b="Das weite Blätterdach des Laubschattentals bietet allerlei Wildtieren Schutz, doch die nahegelegenen, von Netzen überzogenen Höhlungen bergen weitaus finsterere Gefahren. Alle bisherigen Warnungen ignorierend, wagte sich Iverron zu nah an die örtlichen Webwood-Höhlen heran und traf auf Githyiss the Vile – eine bösartige Spinne, deren Gift den jungen Elfen rasch überwältigte. Geplagt von Schwindel und schwindenden Kräften ist er völlig unfähig, sich aus eigener Kraft in Sicherheit zu bringen."},{t="Ein Ruf nach Aldrassil",b="Verzweifelt um sein Überleben kämpfend, weist Iverron jeden Vorbeikommenden an, rasch zum zentralen Baum von Aldrassil zurückzueilen und Dirania Silberschein zu verständigen. Dirania, die es gewohnt ist, auf ihn Acht zu geben und mit den Gefahren des Tals vertraut ist, stellt seine einzige Hoffnung dar, rechtzeitig ein lebensrettendes Gegengift zuzubereiten, ehe das Gift tödlich wirkt."}},faq={{q="Wer ist Iverron?",a="Iverron ist ein junger Nachtelf, der im Laubschattental auf Teldrassil lebt. Trotz der Warnungen seiner Gefährten begibt er sich immer wieder an gefährliche Orte, was letztlich zu seiner beinahe tödlichen Begegnung mit Githyiss the Vile führt.",al={"iverron lore","wer ist der vergiftete elf","wer gibt ein freund in not"}},{q="Was hat Iverron angegriffen?",a="Er wurde von Githyiss the Vile gebissen, einer berüchtigten, hochgiftigen Spinne, die in der Spinnenhöhle im Laubschattental lauert.",al={"was hat iverron gebissen","wer ist githyiss","welche spinne hat ihn vergiftet"}},{q="Wer ist Dirania Silberschein?",a="Dirania Silberschein ist eine Nachtelfe, die bei Aldrassil im Laubschattental lebt. Sie ist eine enge Freundin und Beschützerin von Iverron und weiß, wie giftige Verletzungen zu behandeln sind.",al={"dirania rolle","mit wem sprechen für iverron"}},{q="Wo findet diese Quest statt?",a="Die Quest findet vollständig im Laubschattental statt, dem geschützten Starttal der Nachtelfen hoch oben in der Krone von Teldrassil.",al={"wo ist ein freund in not","iverron standort"}},{q="Was geschieht, nachdem Dirania von Iverrons Zustand berichtet wurde?",a="Dirania macht sich unverzüglich an die Zubereitung eines Heilmittels und schickt Abenteurer durch den Hain, um die seltenen Reagenzien zu beschaffen, die für das Gegengift benötigt werden, bevor Iverron dem Gift erliegt.",al={"wie geht es weiter nach ein freund in not","wird iverron gerettet"}},{q="Warum gibt es im Laubschattental tödliche Spinnen?",a="Obwohl das Laubschattental als sichere Zuflucht für junge Nachtelfen gilt, hat die sich über Teldrassil ausbreitende Verderbnis wilde Bestien und Ungeziefer wie die Webwood-Spinnen in ungewöhnlich aggressive, giftige Raubtiere verwandelt.",al={"warum gibt es spinnen im laubschattental","spinnen verderbnis teldrassil"}}},fx={c3a2deab={q="Warum möchte Iverron, dass dies erledigt wird?",a="Iverron wurde von der giftigen Webwoodspinne Githyiss die Niederträchtige gebissen, während er eine nahe gelegene Höhle erkundete. Das tödliche Gift breitet sich schnell in seinen Adern aus und macht ihn schwach, schwindelig und lässt ihn um sein Leben fürchten. Da er weiß, dass er das Leiden nicht alleine heilen kann, benötigt er dringend das Eingreifen von Dirania Silberschein, bevor das Gift ihn vollständig überwältigt.",al={"warum braucht iverron hilfe","beweggrund von iverron","was ist mit iverron passiert"}},b12cb73c={q="Warum benötigt Iverron Euch, anstatt selbst Hilfe zu suchen?",a="Das Gift von Githyiss die Niederträchtige hat Iverron schwer getroffen, was ihn völlig desorientiert und kaum in der Lage sein lässt, zu stehen. Allein in der Wildnis gestrandet, kann er den Rückweg nach Aldrassil nicht antreten, ohne zusammenzubrechen. Ihr seid der einzige fähige Reisende, der ihn rechtzeitig gefunden hat, um zurückzueilen und Diranias Hilfe zu rufen.",al={"warum kann iverron nicht selbst gehen","warum ich a friend in need","warum holt iverron keine wachen"}}},fp="16,264,18.394.0,19.311.0,15.216.0,22.130.0,27.166.0,33.137.0,60.187.1,47.217.0"}
P.entries["quest:3521"] = {n="Iverrons Gegengift",s="Iverrons Gegengift ist eine dringliche Aufgabe im Laubschattental, um einen vergifteten Späher der Nachtelfen zu retten. Durch das Sammeln von wilden Pilzen, Lilien und Spinnen-Ichor helfen Abenteurer Dirania Silberschein dabei, ein Heilmittel zu brauen, bevor das Gift vollständig seine Wirkung entfaltet.",h="Iverrons Gegengift ist eine dringliche Aufgabe im Laubschattental, um einen vergifteten Späher der Nachtelfen...",kw={"aldrassil","gegengift","dirania silberschein","hyazinthenpilz","iverron","mondblütenlilie","laubschattental","schattenweberhöhle","waldwebersekret"},ang={["class:Druid"]="Das Brauen von Heilmitteln aus der einheimischen Flora und das Neutralisieren natürlicher Gifte spiegelt das grundlegende Gleichgewicht wider, das Druiden in der Wildnis zu bewahren suchen.",["profession:Herbalism"]="Das Sammeln von Mondblütenlilien und Hyazinthenpilzen zeigt, welch wirksame medizinische Eigenschaften wilde Pflanzen von Teldrassil besitzen, wenn sie mit Bedacht verwendet werden.",["race:NightElf"]="Sich um gefallene Brüder und Schwestern zu kümmern, ist eine heilige Pflicht in Laubschattental, wo jeder Verteidiger gebraucht wird, um den frisch sprießenden Weltenbaum zu schützen."},sec={{t="Ein Wettlauf gegen das Gift",b="Beim Auskundschaften des Geästs von Laubschattental fiel der junge Iverron den giftigen Fängen der einheimischen Webwood-Spinnen zum Opfer. Zusammengebrochen und im Sterben liegend, hängt sein Überleben gänzlich vom heilkundlichen Wissen von Dirania Silberschein bei Aldrassil ab. Da die Kräfte des Jünglings rasch schwinden, muss sie schnell ein spezielles Gebräu herstellen, um das aggressive Gift in seinem Blut zu neutralisieren."},{t="Reagenzien von Laubschattental",b="Diranias Rezept stützt sich auf die heilsame Flora von Teldrassil, abgestimmt auf das Gift selbst. Hyazinthenpilze, die von den diebischen Grell im Süden begehrt werden, bilden eine erdige Basis, während zarte Mondblütenlilien aus ruhigen Waldtümpeln reinigende Eigenschaften verleihen. Um den Trank zu vollenden, muss eine Probe Webwood-Ichor direkt von den Spinnen entnommen werden, die nahe der Schattenweberhöhle lauern, um das Heilmittel genau auf ihr spezifisches Gift abzustimmen."}},faq={{q="Wer ist Iverron?",a="Iverron ist ein junger Nachtelf in Laubschattental, der sich zu nah an die feindseligen Webwood-Spinnen heranwagte und von ihrem tödlichen Gift niedergestreckt wurde.",al={"iverron","wer ist iverron","wer vergiftet"}},{q="Wer vergibt die Quest Iverrons Gegengift?",a="Dirania Silberschein, eine Dienerin vor den mächtigen Ästen von Aldrassil in Laubschattental, vergibt die Quest und braut das Heilmittel.",al={"questgeber","dirania","dirania silberschein"}},{q="Warum benötigt das Gegengift Spinnen-Ichor?",a="In der traditionellen Kräuterkunde hilft das Beifügen eines Bestandteils der körpereigenen Flüssigkeiten oder des Giftes der Kreatur, den spezifischen Toxinen entgegenzuwirken, die dem Opfer zu schaffen machen.",al={"warum spinnenichor","waldwebersekret nutzen","spinnengift heilmittel"}},{q="Wo findet man Hyazinthenpilze?",a="Hyazinthenpilze wachsen am Fuße großer Bäume in ganz Laubschattental und können auch den Fängen der Grell entrissen werden, die sie im Süden horten.",al={"wo gibt es hyazinthenpilze","hyazinthenpilz fundort"}},{q="Wo wachsen Mondblütenlilien?",a="Mondblütenlilien blühen an den Ufern der ruhigen Süßwassertümpel, die im Nordwesten von Aldrassil verborgen liegen.",al={"mondblütenlilie fundort","wo sind lilien"}},{q="Wo befinden sich die Webwood-Spinnen?",a="Webwood-Spinnen hausen in den nördlichen Wäldern von Laubschattental, vor allem rund um den finsteren Eingang der Schattenweberhöhle.",al={"webwood spinnen fundort","spinnen fundort laubschattental"}}},fx={["77bb41e6"]={q="Warum möchte Dirania Silberschein, dass dies erledigt wird?",a="Dirania weiß, wie man ein Heilmittel braut, das das tödliche Gift, das durch Iverrons Körper fließt, neutralisieren kann. Ohne schnelles Eingreifen wird sich sein Zustand verschlechtern, und sie verlässt sich auf Eure Geschwindigkeit, um die notwendigen Waldzutaten zu sammeln, bevor es zu spät ist, ihn zu retten.",al={"beweggrund von dirania silberschein","warum iverron helfen","warum das gegenmittel herstellen"}},d7eaa833={q="Wofür wird der Hyazinthpilz verwendet?",a="Hyazinthpilze sind einheimische Pilze, die unter den großen Ästen von Laubschattental wachsen. Dirania verwendet sie als primäre pflanzliche Komponente, um das Gegenmittel zu brauen, das die härteren Gifte ausgleicht und das Toxin neutralisiert, das in Iverrons Körper eingedrungen ist.",al={"zweck des hyazinthpilzes","warum hyazinthpilz","wissen zum hyazinthpilz"}},ece05283={q="Wofür wird die Mondblütenlilie verwendet?",a="Mondblütenlilien sind zarte Wasserblüten, die an den ruhigen Waldteichen von Laubschattental gedeihen. Dirania mischt sie in ihr Heilmittel, um ihre beruhigenden natürlichen Eigenschaften zu nutzen und dem bösartigen Spinnengift entgegenzuwirken.",al={"zweck der mondblütenlilie","warum mondblütenlilie","wissen zur mondblütenlilie"}}},fp="18,226,20.372.0,22.448.0,15.139.0,39.140.0,40.160.0,35.151.0,31.121.0,38.116.0"}
P.entries["quest:3522"] = {n="Iverrons Gegengift",s="Diese Aufgabe verlangt von einem Abenteurer einen Wettlauf gegen die Zeit, um einer vergifteten Nachtelfenspäherin frisch gebraute Medizin zu überbringen. Gestrandet vor einer von Spinnen heimgesuchten Höhle in Laubschattental ist Iverron völlig auf Dirania Silberscheins Kräutergebräu angewiesen, bevor die wirksame Mischung ihre Wirkung verliert.",h="Diese Aufgabe verlangt von einem Abenteurer einen Wettlauf gegen die Zeit, um einer vergifteten...",kw={"gegengift","dirania silberschein","iverron","laubschattental","teldrassil","gift","webwood spinne"},ang={["profession:Herbalism"]="Die flüchtige Beschaffenheit des Tranks verdeutlicht die Schwierigkeiten bei der Arbeit mit roher Waldflora, deren botanische Zubereitungen ohne angemessene Konservierung nahezu sofort ihre lebenswichtigen Eigenschaften einbüßen.",["race:NightElf"]="Für junge Nachtelfen, die in Laubschattental ausgebildet werden, dient die Rettung Iverrons als ernüchternde Mahnung an die wachsende Verderbnis und Aggression, die sich unter den einheimischen Tieren von Teldrassil regt."},sec={{t="Ein Wettlauf gegen die Zeit",b="Dirania Silberschein stellt das heilende Gebräu aus frisch geernteten Giftsäcken, Lilienwurzeln und Hyazinthenpilzen her, doch seine instabile alchemistische Natur birgt eine ernste Gefahr. Die Medizin behält ihre Wirksamkeit nach der Destillation lediglich fünf Minuten lang. Jeder, der die Phiole bei sich trägt, muss ohne Zögern von der Lichtung direkt zu den nördlichen Anhöhen sprinten."},{t="Ein Hang zu Schwierigkeiten",b="Iverron ist den Webwood-Spinnen zum Opfer gefallen, die rund um die Grabhügel und Höhlen von Laubschattental lauern. Nach eigenem Bekunden besitzt er das unglückliche Talent, ständig in Gefahr zu geraten, und verlässt sich häufig auf Diranias heilkundliches Wissen, um sich aus brenzligen Lagen befreien zu lassen. Selbst nach dem Trinken des Gegengifts bleibt seine Genesung heikel, sodass er sich vor den feindseligen Spinnentieren fürchtet, die noch immer seinen Heimweg versperren."}},faq={{q="Warum gibt es ein Zeitlimit für die Lieferung des Gegengifts?",a="Das von Dirania Silberschein gemischte Gegengift basiert auf unverarbeiteten Naturzutaten und frischem Gift. Seine aktiven Heileigenschaften verfallen nach der Zubereitung rapide, wodurch es völlig nutzlos wird, wenn es nicht innerhalb von fünf Minuten nach Verlassen ihrer Obhut eingenommen wird.",al={"warum fünf minuten","gegengift timer","zeitquest"}},{q="Wo befindet sich Iverron?",a="Iverron lehnt erschöpft an den Felsen vor der nördlichen Höhle in Laubschattental, nördlich des Hauptwegs durch den Hain.",al={"wo ist iverron","iverron aufenthaltsort","iverron finden"}},{q="Wie wurde Iverron vergiftet?",a="Er wurde von den giftigen Webwood-Spinnen angegriffen, die am nördlichen Rand von Laubschattental hausen – einer aggressiven Brut, die sich um die Wurzeln und Höhlen von Teldrassil herum ausgebreitet hat.",al={"wer hat iverron vergiftet","warum ist iverron krank","iverron gift"}},{q="Was geschieht, nachdem Iverron das Gegengift getrunken hat?",a="Obwohl das Gift neutralisiert ist, bleibt Iverron zu schwach und geschwächt, um gefahrlos allein zu reisen, weshalb er um Hilfe bittet, die nahegelegenen Webwood-Spinnen zu beseitigen, die seinen Rückweg in Sicherheit blockieren.",al={"wie geht es weiter mit iverron","nach iverrons gegengift","iverron folgequest"}},{q="In welcher Beziehung stehen Dirania und Iverron zueinander?",a="Dirania Silberschein ist eine fähige Kräuterkundige und Heilerin in Laubschattental, die Iverron regelmäßig aus seinen Missgeschicken rettet. Iverron räumt offen ein, dass es ihm im Blut liegt, in Schwierigkeiten zu geraten, und dass Dirania ihn ständig heraushauen muss.",al={"dirania und iverron","wer ist dirania für iverron","sind sie befreundet"}},{q="Was passiert, wenn das Gegengift abläuft, bevor es ihn erreicht?",a="Sollte das flüchtige Gebräu vor der Übergabe verderben, kann die Aufgabe nicht abgeschlossen werden. Ihr müsst zu Dirania Silberschein in Laubschattental zurückkehren, um eine neue Dosis zu erhalten und den Lauf erneut zu wagen.",al={"gegengift abgelaufen","zeit abgelaufen","gegengift verloren"}}},fx={b60b9a13={q="Warum möchte Dirania Silberschein, dass Ihr das Gegenmittel überbringt?",a="Iverron ist in der Wildnis von Laubschattental einem tödlichen Spinnengift zum Opfer gefallen und wird ohne sofortiges Eingreifen sterben. Dirania Silberschein hat das Heilmittel bereits vorbereitet, aber die Mischung ist instabil und wird schnell verderben, wenn sie nicht unverzüglich verabreicht wird. Sie sorgt sich um Iverron und hilft ihm routinemäßig aus Schwierigkeiten, was Eure schnelle Lieferung zu einer Frage von Leben und Tod macht.",al={"beweggrund von dirania silberschein","warum iverron helfen","warum will dirania, dass dies erledigt wird"}}},fp="18,291,24.353.0,18.413.0,53.242.0,25.128.0,25.178.0,47.205.1,46.248.0,57.174.0"}
